import { describe, it, expect } from "vitest";
import { WORKSPACES, workspaceLabel, effectiveWorkspace, type Workspace } from "@/app/registry";

describe("screen registry (#nav-pass)", () => {
  it("gives every screen a non-empty label, a unique key, and an icon", () => {
    const keys = WORKSPACES.map((s) => s.key);
    expect(new Set(keys).size).toBe(keys.length);                  // no duplicate keys
    expect(WORKSPACES.every((s) => s.label.trim().length > 0)).toBe(true);
    expect(WORKSPACES.every((s) => !!s.Icon)).toBe(true);            // a real lucide component
  });

  it("covers exactly the Workspace union — a new screen can't ship unlabeled", () => {
    // This literal must enumerate every Workspace key (a missing/extra one is a compile error),
    // and WORKSPACES must match it at runtime — so the rail nav + titlebar always have a name.
    const all: Record<Workspace, true> = {
      console: true, glance: true, logs: true, settings: true,
      // The five GRAPHS (`five-graphs-become-rail-workspaces`).
      components: true, teams: true, algorithms: true, data: true, sounds: true,
      // The two utilities that own a rail destination: what we have LEARNED
      // (`a-memory-workspace-shows-what-we-know`) and the credential store's window
      // (`a-credentials-workspace-shows-the-state-of-every-credential`).
      memory: true, credentials: true,
    };
    expect(new Set(WORKSPACES.map((s) => s.key))).toEqual(new Set(Object.keys(all)));
  });

  it("workspaceLabel returns the canonical name, falling back to the raw key when unknown", () => {
    expect(workspaceLabel("console")).toBe("Console");
    expect(workspaceLabel("logs")).toBe("Logs");              // the Security/Agents screen became Logs
    expect(workspaceLabel("nonexistent" as Workspace)).toBe("nonexistent");
  });

  it("labels and orders Memory as a utility, sitting between the graphs and Credentials", () => {
    // Memory is ABOUT the graphs — most of its edges point at a graph record — so it reads next to
    // them. It is still not one of them: the graphs are what the app is made of, and a lesson is
    // not a pillar. Asserted by POSITION rather than by index, so adding a graph does not fail it.
    expect(workspaceLabel("memory")).toBe("Memory");
    const keys = WORKSPACES.map((s) => s.key);
    expect(keys.indexOf("memory")).toBeGreaterThan(keys.indexOf("sounds"));
    expect(keys.indexOf("memory")).toBeLessThan(keys.indexOf("credentials"));
  });

  it("labels and orders Credentials as a utility, not as a sixth graph", () => {
    // It is a rail destination, but NOT part of the graph group — putting it inside would break the
    // contiguity asserted below, and would say in the chrome that a credential is one of the app's
    // pillars rather than a utility you visit when something is wrong.
    expect(workspaceLabel("credentials")).toBe("Credentials");
    const keys = WORKSPACES.map((s) => s.key);
    expect(keys.indexOf("credentials")).toBeGreaterThan(keys.indexOf("memory"));
    expect(keys.indexOf("credentials")).toBeLessThan(keys.indexOf("logs"));
  });

  it("labels the five graphs by the names the rail and crumb show", () => {
    // `components` is the case worth pinning: the Planner TAB id was "designs" (the internal feature
    // name) while its LABEL was "Components" (#2818). The Workspace takes the label, so the key and
    // the old tab id deliberately differ — and `migrateGraphPage` maps designs → components because
    // of exactly this.
    expect(workspaceLabel("components")).toBe("Components");
    expect(workspaceLabel("teams")).toBe("Teams");
    expect(workspaceLabel("algorithms")).toBe("Algorithms");
    expect(workspaceLabel("data")).toBe("Data");
    expect(workspaceLabel("sounds")).toBe("Sounds");
  });

  it("keeps the five graphs together in rail order", () => {
    // Product-defined grouping: the graphs sit between the workflow destinations and the utilities.
    // Asserted as CONTIGUITY rather than exact indices so reordering within the group, or adding a
    // workflow screen above it, does not spuriously fail.
    const keys = WORKSPACES.map((s) => s.key);
    const graphs: Workspace[] = ["components", "teams", "algorithms", "data", "sounds"];
    const idx = graphs.map((k) => keys.indexOf(k));
    expect(idx.every((i) => i >= 0)).toBe(true);
    expect(Math.max(...idx) - Math.min(...idx)).toBe(idx.length - 1);
  });
});

describe("effectiveWorkspace — identity now that Console is a permanent workspace", () => {
  it("passes every workspace through unchanged (the #2372/#3575 opt-in redirect is gone)", () => {
    for (const raw of WORKSPACES.map((s) => s.key)) {
      expect(effectiveWorkspace(raw)).toBe(raw);
    }
  });
});

implementations.code:
// Canonical Workspace registry — the SINGLE source of truth for each top-level Workspace's key,
// display name, and rail icon (a Workspace = a rail destination; see docs/frontend-structure.md).
// The left-nav rail AND the titlebar position crumb both read from here, so a Workspace is named in
// exactly ONE place and the two can never drift: add a Workspace here and it's labeled everywhere
// (rail tooltip + the "you are here" titlebar). Previously the rail's NAV array and App's titlebar
// switch each hardcoded the names independently. (#nav-pass; Screen → Workspace rename #1879)

import {
  TerminalSquare, ScrollText, Settings, Network,
  Component, Users, Binary, Database, AudioLines, KeyRound, Brain,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

/** Every top-level Workspace key (a rail destination). The store's `activeWorkspace` is one of these. */
// "design" (Design Studio) and "algorithms" (the knowledge graph) were removed as rail Workspaces —
// each is a single page, now a Planner tab (projectsPageMode "designs" / "algorithms"). A persisted
// `activeWorkspace: "design" | "algorithms"` is migrated to projects + the matching page mode.
// "skills" went the same way (skills-move-to-teams-and-pair-with-personas): a skill is injectable
// agent CONTEXT, so it lives on the TEAMS page beside the personas that carry it, and a persisted
// `activeWorkspace: "skills"` migrates to projects + the "teams" page mode.

// "security" became "logs" (the-logs-workspace-scaffold-and-activity): three of its four tabs were

// deleted and the survivor — Activity, an audit FEED — is history, so it opens the unified Logs

// screen instead of holding a workspace of its own. A persisted `activeWorkspace: "security"`

// migrates to "logs"; so does the older "agents", which used to redirect to "security".

// "automation" is gone too (hooks-and-schedules-belong-to-the-persona): its CONFIG -- hooks and

// schedules -- is carried by the persona that runs it and read on the Teams page, and its

// HISTORY is the Logs -> Automations tab. A persisted `activeWorkspace: "automation"` migrates

// to Teams, which is where the thing it used to edit now lives.
// "projects" (the Planner) is gone (delete-the-planner-ui-keep-the-planner): its screen was the
// pitch-to-plan CONVERSATION, and planning is the director's job now — the architect runs discovery
// with the user, then creates a director that completes the plan and designs its team. The planner's
// FUNCTIONS are untouched: 142 React-free modules, `src-tauri/src/planner`, the fleet, and plan.db all
// remain, driven through `bsc plan` / `bsc publish` / `bsc fleet start`. A persisted
// `activeWorkspace: "projects"` migrates to GLANCE, which is where projects are seen.
// "github" is gone (delete-the-github-screen-keep-the-integration): the SCREEN was 22 records of
// repo/PR/insight charts over an API the app no longer needs a browser for. The INTEGRATION stays —
// `src-tauri/src/github` still runs publish and readiness, and Settings → GitHub is still where an
// account is connected. A persisted `activeWorkspace: "github"` migrates to Settings → GitHub, which
// is where GitHub still exists in the app.
// "mcp" is gone too (mcp-moves-to-teams): an MCP server is injectable agent CAPABILITY, the same
// class of thing as a skill, so it is READ on the Teams page beside the agents that get it rather
// than owning a rail destination. A persisted `activeWorkspace: "mcp"` migrates to the Teams page.
export type Workspace =
  | "console" | "glance" | "logs" | "settings"
  // The five GRAPHS (`five-graphs-become-rail-workspaces`). Each was a Planner tab; each is now its
  // own rail destination, because the graphs ARE the app. This REVERSES the collapses recorded above
  // — `design` and `algorithms` came back out, and `teams`/`sounds`/`data` came with them — so the
  // redirects in `store/retiredWorkspaces.ts` had to be REVERSED, not extended: every one of them
  // pointed at a Planner page that no longer exists.
  | "components" | "teams" | "algorithms" | "data" | "sounds"
  // The CREDENTIAL store (`a-credentials-workspace-shows-the-state-of-every-credential`). NOT a
  // graph — a utility, so it sits with Logs and Settings rather than inside the graph group. It is
  // a rail destination because a credential that has quietly expired is invisible everywhere else:
  // the OS keychain has no listing, so before this screen the only way to discover a broken pairing
  // was an agent's call failing mid-task.
  | "credentials"
  // SESSION MEMORY (`a-memory-workspace-shows-what-we-know`). Also a utility rather than a sixth
  // graph, and for a sharper reason than Credentials: the other graphs describe what the app IS
  // MADE OF and are AUTHORING surfaces, while memory is what we have LEARNED ABOUT it. Putting it
  // in the graph group would claim in the chrome that a lesson is a pillar of the product.
  | "memory";

export interface WorkspaceMeta {
  key: Workspace;
  /** The page's display name — the rail tooltip AND the titlebar position crumb. */
  label: string;
  Icon: LucideIcon;
}

/** Rail order is product-defined (#872) and locked by rail.test.tsx; the titlebar reads the
 *  same labels. Adding a screen is one entry here. */
export const WORKSPACES: WorkspaceMeta[] = [
  { key: "console",    label: "Console",     Icon: TerminalSquare },
  { key: "glance",     label: "Glance",      Icon: Network },
  // The five GRAPHS, kept together and in this order deliberately: Components and Algorithms lead
  // because they are the two whose technology axis is real in the data today; the three whose axis
  // is newer follow. They sit between the workflow destinations above and the utilities below.
  { key: "components", label: "Components",  Icon: Component },
  { key: "teams",      label: "Teams",       Icon: Users },
  { key: "algorithms", label: "Algorithms",  Icon: Binary },
  { key: "data",       label: "Data",        Icon: Database },
  { key: "sounds",     label: "Sounds",      Icon: AudioLines },
  // Utilities. Memory leads them, immediately after the graphs it is mostly ABOUT — most of its
  // edges point at a graph record, so the two are read together. Credentials follows: it is the one
  // that can be WRONG, and a destination you only visit when something is broken has to be easy to
  // find.
  { key: "memory",     label: "Memory",      Icon: Brain },
  { key: "credentials", label: "Credentials", Icon: KeyRound },
  { key: "logs",       label: "Logs",        Icon: ScrollText },
  { key: "settings",   label: "Settings",    Icon: Settings },
];

const BY_KEY = Object.fromEntries(WORKSPACES.map((s) => [s.key, s])) as Record<Workspace, WorkspaceMeta>;

/** The canonical display name for a Workspace — the rail tooltip and the titlebar position crumb.
 *  Falls back to the raw key for an unknown Workspace so an unmapped page is still visibly labeled
 *  (never blank). */
export function workspaceLabel(key: Workspace): string {
  return BY_KEY[key]?.label ?? key;
}

/** The Workspace to actually render for a raw store `activeWorkspace`. Identity now that Console is a
 *  permanent rail workspace (the `showConsolePage` opt-in, #2372, is gone) — kept as the single
 *  indirection the App shell and `useHotkeys` share so any future workspace redirect has one home. */
export function effectiveWorkspace(raw: Workspace): Workspace {
  return raw;
}

// App-state gist transport (#2272) — publish/load a "demoable" app-state snapshot as a typed gist,
// reusing the SAME extension-manifest envelope + gist transport blueprints already use. The `kind`
// discriminator (`app-state`) is what lets the app tell an app-state gist from a blueprint gist.
//
// Split into pure envelope helpers (unit-testable) + the Tauri-backed load/save transport.

import {
  wrapExtension, validateManifest, type ExtensionManifest,
} from "@/features/planner/lib/gist/manifest";
import { installFromGist, publishGist } from "@/features/planner/lib/gist/gist";
import { pickDemoable, snapshotAppState, type AppStateSnapshot } from "@/store/appState";
import { useAppStore } from "@/store";

/** The manifest kind an app-state snapshot ships as (#2272). */
export const APP_STATE_KIND = "app-state" as const;
/** Stable manifest id for an app-state snapshot (there is one logical app-state per gist). */
const APP_STATE_ID = "app-state";

/** Wrap a snapshot in the typed extension envelope for publishing. */
export function appStateToManifest(
  snapshot: AppStateSnapshot, name = "Demo app-state", version = "1.0.0",
): ExtensionManifest<AppStateSnapshot> {
  return wrapExtension(APP_STATE_KIND, APP_STATE_ID, name, version, snapshot);
}

/** Reconstruct a sanitized snapshot from a validated manifest, or an error if it's not an app-state.
 *  The payload is run through {@link pickDemoable} so an untrusted gist can never set a non-demoable
 *  (secret / machine) key. */
export function appStateFromManifest(
  m: ExtensionManifest,
): { ok: true; name: string; snapshot: AppStateSnapshot } | { ok: false; error: string } {
  if (m.kind !== APP_STATE_KIND) return { ok: false, error: `expected an app-state, got '${m.kind}'` };
  return { ok: true, name: m.name, snapshot: pickDemoable(m.payload) };
}

/**
 * Load an app-state gist by URL/id and overlay it as the demo (backing up the current state so it's
 * clearable). Reading a public gist needs no auth; `token` only raises the rate limit / reads a
 * secret gist.
 */
export async function loadDemoFromGist(
  url: string, token = "",
): Promise<{ ok: true; name: string } | { ok: false; error: string }> {
  const res = await installFromGist(url, token);
  if (!res.ok) return res;
  const parsed = appStateFromManifest(res.manifest);
  if (!parsed.ok) return parsed;
  useAppStore.getState().loadDemoState(parsed.snapshot);
  return { ok: true, name: parsed.name };
}

/**
 * Snapshot the CURRENT app-state (allowlist-filtered — never secrets) and publish it as a gist.
 * Needs a token with the `gist` scope. `public` makes it a shareable public gist (the shape a curated
 * demo wants); the default is a secret gist.
 */
export async function saveDemoToGist(
  token: string, name = "Demo app-state", opts: { public?: boolean } = {},
): Promise<{ ok: true; url: string } | { ok: false; error: string }> {
  try {
    const snapshot = snapshotAppState(useAppStore.getState());
    const res = await publishGist(token, appStateToManifest(snapshot, name), { public: opts.public });
    return { ok: true, url: res.htmlUrl };
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

// Re-export for tests / callers that want the raw validator on an already-fetched manifest.
export { validateManifest };

