// The composed AppStore interface (#1634). It `extends` the per-feature slice interfaces
// (Skills/Mcp/Automations/Github/Tunnel — owned by their features) AND the per-domain core-state
// interfaces split out of the former monolith. Composition model is unchanged: every field still
// lives on AppStore; it is just sourced from focused per-domain modules.
//
// Where the rest lives:
//  - GitHub connection state    → GithubSlice    (@/features/github/store)
//  - Mobile tunnel state        → TunnelSlice    (@/features/tunnel/store)
//  - Automations CRUD           → AutomationsSlice (@/features/automations/store)
//  - MCP servers + hooks        → McpSlice       (@/features/mcp/store)
//  - Skills library/groups      → SkillsSlice    (@/features/skills/store)
import type { McpSlice } from "@/features/mcp/store";
import type { PersonasSlice } from "@/features/personas/store";
import type { OrgSlice } from "@/features/teams/store";
import type { NetworksSlice } from "@/features/networks";
import type { ComponentsSlice } from "@/features/designs/store";
import type { AlgorithmsSlice } from "@/features/algorithms/store";
import type { StudiosSlice } from "@/features/studio-sessions/store";
import type { SkillsSlice } from "@/features/skills/store";
import type { AutomationsSlice } from "@/features/automations/store";
import type { GithubSlice } from "@/features/github/store";
import type { TunnelSlice } from "@/features/tunnel/store";
import type { ConsoleState } from "@/store/types/console";
import type { ShellState } from "@/store/types/shell";
import type { LlmState } from "@/store/types/llm";
import type { ProjectsState } from "@/store/types/projects";
import type { PlanState } from "@/store/types/plan";
import type { SessionState } from "@/store/types/session";

export interface AppStore
  extends SkillsSlice,
    PersonasSlice,
    OrgSlice,
    NetworksSlice,
    ComponentsSlice,
    AlgorithmsSlice,
    StudiosSlice,
    McpSlice,
    AutomationsSlice,
    GithubSlice,
    TunnelSlice,
    ConsoleState,
    ShellState,
    LlmState,
    ProjectsState,
    PlanState,
    SessionState {}

// Appearance prefs that drive the design-token CSS variables at runtime (#486).
//
// The accent is a single hue threaded through two tokens — `--accent` (the bright
// interactive color) and `--accent-dim` (its muted partner) — which the rest of
// the palette derives from via color-mix. Offering a fixed set of hue presets (vs.
// a freeform picker) keeps the two tokens in lockstep at the lightness/chroma the
// design was tuned for, so every accent stays legible.
//
// Pure (no DOM access) so the mapping is unit-testable; the App applies the result
// to document.documentElement.

export interface AccentPreset {
  /** Stable id persisted in the store. */
  id: string;
  /** Label shown in the Appearance picker. */
  label: string;
  /** oklch hue angle for this accent. */
  hue: number;
}

/** The accent palette. `amber` (hue 70) is the historical default in tokens.css. */
export const ACCENT_PRESETS: AccentPreset[] = [
  { id: "amber",  label: "Amber",  hue: 70  },
  { id: "blue",   label: "Blue",   hue: 230 },
  { id: "green",  label: "Green",  hue: 145 },
  { id: "cyan",   label: "Cyan",   hue: 195 },
  { id: "purple", label: "Purple", hue: 300 },
  { id: "red",    label: "Red",    hue: 25  },
];

export const DEFAULT_ACCENT = "amber";

/** The two `--accent*` token values for an accent id. Lightness/chroma match the
 *  tokens.css defaults so only the hue changes; an unknown id falls back to the
 *  default so a corrupt persisted value can't blank the accent. */
export function accentVars(id: string): { accent: string; accentDim: string } {
  const p = ACCENT_PRESETS.find((x) => x.id === id)
    ?? ACCENT_PRESETS.find((x) => x.id === DEFAULT_ACCENT)!;
  return {
    accent: `oklch(0.80 0.14 ${p.hue})`,
    accentDim: `oklch(0.55 0.10 ${p.hue})`,
  };
}

tests.src:
import { describe, it, expect } from "vitest";
import { ACCENT_PRESETS, DEFAULT_ACCENT, accentVars } from "@/features/settings/lib/appearance";

describe("accentVars", () => {
  it("maps a known accent id to a matching --accent / --accent-dim oklch pair", () => {
    const blue = ACCENT_PRESETS.find((p) => p.id === "blue")!;
    expect(accentVars("blue")).toEqual({
      accent: `oklch(0.80 0.14 ${blue.hue})`,
      accentDim: `oklch(0.55 0.10 ${blue.hue})`,
    });
  });

  it("falls back to the default accent for an unknown id", () => {
    expect(accentVars("does-not-exist")).toEqual(accentVars(DEFAULT_ACCENT));
  });

  it("every preset yields both token values", () => {
    for (const p of ACCENT_PRESETS) {
      const v = accentVars(p.id);
      expect(v.accent).toContain(String(p.hue));
      expect(v.accentDim).toContain(String(p.hue));
    }
  });
});

