// The automations feature's graph-platform surface (#3642, epic #3604) — the modules a graph-loaded
// Automations page imports but does NOT redraw: the cross-feature `HooksView` + hook-telemetry helpers
// (from the mcp barrel), and the feature's own pure scheduler/cron/format logic. Registered HERE, inside
// the feature, because the shell must not reach a feature's internals (#1545) and eager-importing them
// from `app/` would de-lazy the feature at boot. The automations host calls this synchronously before the
// graph page loads, so the modules are present when the compiled page's `require()` runs. Mirrors
// `registerFleetPlatform` (features/planner/fleet/graphPlatform.ts).
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Mcp from "@/features/mcp"; // HooksView + parseHookLog/aggregateHookTelemetry (the Hooks + Hook-Analytics tabs)
import * as Scheduler from "@/features/automations/lib/scheduler";
import * as Cron from "@/features/automations/lib/cron";
import * as Format from "@/features/automations/format";
import * as GraphPlatform from "@/features/automations/graphPlatform";

/** Register the automations page's injected graph-platform modules by the specifiers it imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerAutomationsPlatform(): void {
  registerAppModule("@/features/mcp", Mcp);
  registerAppModule("@/features/automations/lib/scheduler", Scheduler);
  registerAppModule("@/features/automations/lib/cron", Cron);
  registerAppModule("@/features/automations/format", Format);
  registerAppModule("@/features/automations/graphPlatform", GraphPlatform);
}

// The automations feature's PUBLIC API — re-exports only, plus the stylesheet the page needs.
//
// The Automations screen itself (#142) is the `automationspage` RECORD, mounted by
// AutomationsGraphHost — which is what `lazyWorkspaces` resolves the `AutomationsWorkspace` symbol
// to, in both App.tsx and DetachedWindow. The copy that used to live in this file was a dead
// duplicate: nothing imported it.
//
// Note for anyone pruning `@/features/mcp`: that record's Hooks tab imports the REAL `HooksView`
// from the mcp barrel and resolves it through the graph platform, so the export is load-bearing at
// runtime even though no FILE imports it any more. A file-import search will call it dead. It isn't.

// Re-exported feature surface — this index is the automations feature's public API barrel (#1309).
export { AutomationsGraphHost } from "@/features/automations/AutomationsGraphHost"; // the graph-hosted workspace (#3642)
export { AutomationsStatus } from "@/features/automations/AutomationsStatus";
export { useScheduler } from "@/features/automations/useScheduler";

// #1545: public API for cross-feature consumers (tunnel).
export { type Automation, type AutomationWhen } from "@/features/automations/lib/scheduler";
export { isValidCron } from "@/features/automations/lib/cron";
export { dispatchSchedule } from "@/features/automations/lib/dispatch";

// Automations feature store slice (#1309) — schedules, commands, and cron automations. Extracted
// from the former grab-bag `automations` slice (which kept LLM config / active-project state, now
// in store/slices/core.ts). Composed into the app store by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { type Automation, type AutomationRun, appendRun, computeNextRun } from "@/features/automations/lib/scheduler";
import type { Schedule, Command } from "@/shared/data/mock";

export interface AutomationsSlice {
  schedules: Schedule[];
  addSchedule: () => void;
  updateSchedule: (id: string, patch: Partial<Schedule>) => void;
  removeSchedule: (id: string) => void;
  commands: Command[];
  addCommand: () => void;
  updateCommand: (id: string, patch: Partial<Command>) => void;
  removeCommand: (id: string) => void;
  automations: Automation[];
  addAutomation: (input: Omit<Automation, "id" | "lastRunAt" | "nextRunAt" | "runs">) => string;
  updateAutomation: (id: string, patch: Partial<Automation>) => void;
  removeAutomation: (id: string) => void;
  setAutomationArmed: (id: string, armed: boolean) => void;
  recordAutomationRun: (id: string, run: AutomationRun) => void;
}

export const createAutomationsSlice: StateCreator<AppStore, [], [], AutomationsSlice> = (set) => ({
  schedules: [],
  addSchedule: () =>
    set((s) => {
      const id = `S-${String(s.schedules.length + 1).padStart(2, "0")}`;
      const newSched: Schedule = {
        id, name: "New schedule", on: false,
        when: "every day · 02:00", target: "",
        action: "command", detail: "",
        lastRun: "—", nextRun: "—",
      };
      return { schedules: [...s.schedules, newSched] };
    }),
  updateSchedule: (id, patch) =>
    set((s) => ({ schedules: s.schedules.map((sc) => (sc.id === id ? { ...sc, ...patch } : sc)) })),
  removeSchedule: (id) =>
    set((s) => ({ schedules: s.schedules.filter((sc) => sc.id !== id) })),

  commands: [],
  addCommand: () =>
    set((s) => {
      const id = `cmd_${Math.random().toString(36).slice(2, 8)}`;
      const newCmd: Command = { id, name: "New command", cmd: "", used: 0, tags: [] };
      return { commands: [...s.commands, newCmd] };
    }),
  updateCommand: (id, patch) =>
    set((s) => ({ commands: s.commands.map((c) => (c.id === id ? { ...c, ...patch } : c)) })),
  removeCommand: (id) =>
    set((s) => ({ commands: s.commands.filter((c) => c.id !== id) })),

  automations: [],
  addAutomation: (input) => {
    // Mint the id outside `set` so the action can return it — callers select the new row via useDraft
    // instead of the fragile "find the last item" lookup the screens used to do.
    const id = `auto_${Math.random().toString(36).slice(2, 8)}`;
    set((s) => {
      const nextRunAt = input.armed ? computeNextRun(input.when, Date.now()) : null;
      const a: Automation = { ...input, id, lastRunAt: null, nextRunAt, runs: [] };
      return { automations: [...s.automations, a] };
    });
    return id;
  },
  updateAutomation: (id, patch) =>
    set((s) => ({
      automations: s.automations.map((a) => {
        if (a.id !== id) return a;
        const next = { ...a, ...patch };
        // Editing the trigger or arming re-derives the next fire time.
        if ("when" in patch || "armed" in patch) {
          next.nextRunAt = next.armed ? computeNextRun(next.when, Date.now()) : null;
        }
        return next;
      }),
    })),
  removeAutomation: (id) =>
    set((s) => ({ automations: s.automations.filter((a) => a.id !== id) })),
  setAutomationArmed: (id, armed) =>
    set((s) => ({
      automations: s.automations.map((a) =>
        a.id === id
          ? { ...a, armed, nextRunAt: armed ? computeNextRun(a.when, Date.now()) : null }
          : a),
    })),
  recordAutomationRun: (id, run) =>
    set((s) => ({
      automations: s.automations.map((a) =>
        a.id === id
          ? { ...a, runs: appendRun(a.runs, run), lastRunAt: run.at, nextRunAt: computeNextRun(a.when, run.at) }
          : a),
    })),
});

// The app's NOTICE registry (#54) — the one list the banner stack and `bsc navigate dismiss` share.
//
// Every banner in `AppBanners.tsx` hides itself through its own local `useState`, which is fine for a
// human with a mouse and unreachable for a session driving the app from a shell. A designer session hit
// this with two notices it could see in a capture and had no way to clear.
//
// The ids live HERE rather than as strings at each dismiss site so the CLI cannot drift from the UI: a
// banner renamed without updating this list fails the registry test, instead of silently becoming
// un-dismissable the next time someone reaches for it.

/** A notice the app can show, and whether clearing it would decide something on the user's behalf. */
export interface NoticeDef {
  id: string;
  /** What it tells the user — the `bsc navigate dismiss --list` line. */
  label: string;
  /**
   * Does this notice ask a QUESTION whose answer is lost if it is hidden?
   *
   * `session-recovery` asks "3 sessions found on disk that aren't open — restore or discard?". Hiding it
   * does not answer it; it removes the only place the answer could be given, and those sessions stay
   * unrestored with nothing on screen to say so. So a decision-bearing notice is never cleared by a
   * blanket dismiss and is REFUSED by name — choosing for the user is worse than leaving the banner up,
   * which is the whole reason this flag exists rather than a plain id list.
   */
  decision?: true;
}

/** Every dismissable notice, in the order `AppBanners` stacks them. */
export const NOTICES: readonly NoticeDef[] = [
  { id: "kit-changes", label: "a packaged kit changed since you last synced" },
  { id: "seed-drift", label: "rendered modules do not match their source file" },
  { id: "crash-recovery", label: "the app did not shut down cleanly" },
  { id: "interrupted-loop", label: "a designer loop was interrupted mid-run" },
  { id: "session-recovery", label: "sessions found on disk that aren't open — restore or discard?", decision: true },
  { id: "quarantine", label: "a worker was quarantined" },
  { id: "sandbox-setup", label: "the WSL sandbox is not provisioned" },
  { id: "project-complete", label: "a project finished its build" },
  { id: "path-expose", label: "`bsc` is not on your PATH" },
];

const BY_ID = new Map(NOTICES.map((n) => [n.id, n]));

/** Is `id` a notice this app knows how to show? */
export function isNotice(id: string): boolean {
  return BY_ID.has(id);
}

/** The notices a blanket `dismiss all` clears — everything that does not ask a question. */
export function blanketDismissable(): string[] {
  return NOTICES.filter((n) => !n.decision).map((n) => n.id);
}

/** Why `id` cannot be dismissed, or `null` when it can. Pure, so both the bridge and its tests use it. */
export function refuseDismissal(id: string): string | null {
  const n = BY_ID.get(id);
  if (!n) return `unknown notice '${id}' — one of: ${NOTICES.map((x) => x.id).join(", ")}`;
  if (n.decision) {
    return `'${id}' asks a question ("${n.label}") — dismissing it would not answer it, it would remove ` +
      `the only place the answer can be given. Act on it in the app instead.`;
  }
  return null;
}

