use std::collections::{HashMap, HashSet, VecDeque};

/// Breadth-first traversal order from `start` over an adjacency map.
pub fn bfs(adj: &HashMap<&str, Vec<&str>>, start: &str) -> Vec<String> {
    let mut order = Vec::new();
    let mut seen = HashSet::from([start]);
    let mut queue = VecDeque::from([start]);
    while let Some(node) = queue.pop_front() {
        order.push(node.to_string());
        for &next in adj.get(node).into_iter().flatten() {
            if seen.insert(next) {
                queue.push_back(next);
            }
        }
    }
    order
}

/// Binary search a sorted slice; `Some(index)` on a hit, else `None`.
pub fn binary_search<T: Ord>(xs: &[T], target: &T) -> Option<usize> {
    let (mut lo, mut hi) = (0, xs.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match xs[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

// The verb→state binding convention (#3176, epic #3171) — the ONE way every per-structure renderer
// stamps a frame's ops/marks onto an element, so a state-triggered kit animation (#3058) fires the same
// way across all of them. PURE + React-free (returns plain `data-*` attribute objects a renderer spreads
// onto its JSX elements).
//
//   trace verb  →  element `data-op` / `data-mark` state  →  state-triggered kit animation (#3058)
//
// The renderer never writes animation CSS: it only stamps the state. The kit owns the keyframes/timing
// and binds them to `[data-op="swap"]` / `[data-mark="sorted"]` (designed in the Designer). Change the
// `swap` animation once → every sort visualization updates. See docs/algorithm-visualization.md.
//
// The convention: at most ONE op targets a given element per frame (the animation is the transient VERB),
// while a `mark` / `marks` entry is a DURABLE state (a cell reaching `sorted`, a node `visited`). This
// module gives renderers three shared readers so index-, id-, and mark-addressed states stamp identically.

/** The `data-*` state a renderer stamps on an element — a transient op verb and/or a durable mark.
 *  Spread directly onto a JSX element: `<Cell {...opStateAttrs(frame.ops, i)} />`. */
export interface OpStateAttrs {
  /** The transient verb the element is participating in this frame (`swap`/`compare`/`visit`/…). */
  "data-op"?: string;
  /** The durable state the element has reached (`sorted`/`pivot`/`visited`/`current`/…). */
  "data-mark"?: string;
  /** The durable ROLE the algorithm assigned the element (`start`/`goal`) — a SECOND, independent axis
   *  (#3378). An element carries at most one `data-mark` AND at most one `data-role`, so a start node can
   *  render as both the origin and visited. */
  "data-role"?: string;
}

/** A NUMERIC-index-addressed op — the shape `opStateAttrs` reads from array / linked-list / stack ops.
 *  `at` is a single index or the `[a, b]` pair a compare/swap spans; `as` carries a `mark` op's state.
 *  Position-less ops (stack `push`/`pop`) carry no `at` and are the renderer's own concern. */
export interface IndexedOp {
  op: string;
  at?: number | [number, number];
  as?: string;
}

/** An ID-addressed op — the shape `nodeOpStateAttrs` reads from graph / tree ops. A node op names its
 *  `node`; an edge op its `edge` `[from, to]`; a path its `nodes`; a compare/swap its `at` id pair. */
export interface NodeOp {
  op: string;
  node?: string;
  nodes?: string[];
  edge?: [string, string];
  at?: [string, string];
}

function targetsIndex(at: IndexedOp["at"], index: number): boolean {
  if (at === undefined) return false;
  return typeof at === "number" ? at === index : at[0] === index || at[1] === index;
}

/**
 * The `data-op` / `data-mark` for the element at numeric position `index` (array / linked-list / stack).
 * An op that targets `index` stamps `data-op` = its verb; a `mark` op stamps `data-mark` = its `as`
 * state instead. Ops without an `at` (stack push/pop) are ignored here. At most one op should target an
 * element per frame (convention); if several do, the last wins. Pure.
 */
export function opStateAttrs(ops: readonly IndexedOp[] | undefined, index: number): OpStateAttrs {
  const attrs: OpStateAttrs = {};
  for (const o of ops ?? []) {
    if (!targetsIndex(o.at, index)) continue;
    if (o.op === "mark" && o.as) attrs["data-mark"] = o.as;
    else attrs["data-op"] = o.op;
  }
  return attrs;
}

/**
 * The `data-op` for the node with id `id` (graph / tree) — set when any op names that id via `node`,
 * `nodes`, `edge`, or `at`. Durable node states come from the frame's `marks` record via
 * {@link markStateAttrs}; this covers the transient VERB. Ops that address no id (a tree `rotate`, which
 * names a `pivot`) are left to the renderer. Last matching op wins. Pure.
 */
export function nodeOpStateAttrs(ops: readonly NodeOp[] | undefined, id: string): OpStateAttrs {
  const attrs: OpStateAttrs = {};
  for (const o of ops ?? []) {
    const hit = o.node === id || !!o.nodes?.includes(id) || !!o.edge?.includes(id) || !!o.at?.includes(id);
    if (hit) attrs["data-op"] = o.op;
  }
  return attrs;
}

/**
 * The `data-mark` for a keyed element from a frame's durable `marks` record (graph node search state,
 * tree node state, …). Empty when the key has no mark. Pure.
 */
export function markStateAttrs(marks: Record<string, string> | undefined, key: string): OpStateAttrs {
  const mark = marks?.[key];
  return mark ? { "data-mark": mark } : {};
}

/**
 * The `data-role` for a keyed element from a frame's durable `roles` record (a graph node's `start`/`goal`
 * anchor, #3378). Empty when the key has no role. The independent twin of {@link markStateAttrs}: roles and
 * marks are different facts, so both may be stamped on the same element and neither overwrites the other.
 * Pure.
 */
export function roleStateAttrs(roles: Record<string, string> | undefined, key: string): OpStateAttrs {
  const role = roles?.[key];
  return role ? { "data-role": role } : {};
}

/** A 2-D-addressed op — the shape `cellOpStateAttrs` reads from matrix ops (#3221). A cell op names its
 *  `at` `[row, col]`; a `region` op names its `rows`/`cols` inclusive ranges (with an optional `as` label). */
export interface CellOp {
  op: string;
  at?: [number, number];
  rows?: [number, number];
  cols?: [number, number];
  as?: string;
}

/**
 * The `data-op` / `data-mark` for the cell at (`row`, `col`) in a matrix. A `read`/`write` op that targets
 * the cell stamps `data-op` = its verb; a `region` op covering the cell stamps `data-mark` = its `as` label
 * (or `data-op` = "region" when unlabelled). Last matching op wins. Pure — the 2-D twin of {@link
 * opStateAttrs}.
 */
export function cellOpStateAttrs(ops: readonly CellOp[] | undefined, row: number, col: number): OpStateAttrs {
  const attrs: OpStateAttrs = {};
  for (const o of ops ?? []) {
    if (o.at && o.at[0] === row && o.at[1] === col) {
      attrs["data-op"] = o.op;
    } else if (
      o.rows &&
      o.cols &&
      row >= o.rows[0] &&
      row <= o.rows[1] &&
      col >= o.cols[0] &&
      col <= o.cols[1]
    ) {
      if (o.as) attrs["data-mark"] = o.as;
      else attrs["data-op"] = "region";
    }
  }
  return attrs;
}

// Blueprints-page registry layer (#609) — the editor's palette metadata. The per-stage
// metadata (icon + hue + title + blurb) is single-sourced from the stage's own JSON in
// the prompts data layer (#1603): real stages carry `icon`/`hue` on their SECTION_DEF, and
// the discovery dimensions that double as palette kinds carry them on `discovery.json`'s
// `dimensions`. STAGE_KINDS is DERIVED from those here — no hand-maintained duplicate. Pure;
// the editor reads this for glyphs/hues/blurbs/dispositions; the runtime (#584 gateRule/
// stageStatus) is unchanged.

import { STAGE_DEFS } from "@/features/planner/stages/blueprints";

// ── hue helpers (oklch accents; share L/C, vary hue) ──────────────────────────
export const hue = (h: number): string => `oklch(0.74 0.11 ${h})`;
export const tint = (h: number, a: number): string => `oklch(0.74 0.11 ${h} / ${a})`;

// ── stage kinds: the palette of stages a blueprint can contain ────────────────
// `glyph` is the Material/Lucide icon name (for the editor `<Ic>`); `h` is the accent hue.
interface StageKindMeta { title: string; glyph: string; h: number; blurb: string }

/** Built at load from the stage JSON data layer: every real stage (a SECTION_DEF with an
 *  `icon`/`hue`) + every discovery dimension that doubles as a palette kind (an enriched
 *  `discovery.json` dimension). A stage's title/blurb come from its `name`/`blurb`, so the
 *  palette stays consistent with the stage bar (#1603 reconciled the former divergences). */
function buildStageKinds(): Record<string, StageKindMeta> {
  const out: Record<string, StageKindMeta> = {};
  for (const [key, def] of Object.entries(STAGE_DEFS)) {
    if (def.icon && typeof def.hue === "number") {
      out[key] = { title: def.name, glyph: def.icon, h: def.hue, blurb: def.blurb };
    }
  }
  for (const dim of STAGE_DEFS.discovery?.dimensions ?? []) {
    if (dim.icon && typeof dim.hue === "number") {
      out[dim.key] = { title: dim.title, glyph: dim.icon, h: dim.hue, blurb: dim.blurb ?? "" };
    }
  }
  return out;
}

export const STAGE_KINDS: Record<string, StageKindMeta> = buildStageKinds();

export function stageKind(key: string): StageKindMeta {
  return STAGE_KINDS[key] ?? { title: key, glyph: "category", h: 250, blurb: "" };
}

/** The kinds offered in the editor's "add stage" palette — a CURATED subset of {@link STAGE_KINDS},
 *  NOT every entry. The map also carries icon/metadata for stages that arrive via blueprints or
 *  STAGE_DEFS but aren't hand-addable (the data-platform pipeline stages and the lifecycle stages
 *  seeded by their category's built-in), so an imported blueprint resolves a real icon for every
 *  stage without those flooding the palette. */
export const STAGE_KIND_KEYS = [
  "discovery", "deployment", "users", "ui", "stack", "architecture", "schema", "api",
  "streams", "automations", "skills", "security",
  "observability", "infra", "cicd", "docs",
];

// ── output dispositions: what happens to a stage's artifact ───────────────────
interface DispositionMeta { title: string; glyph: string; h: number; desc: string }

export const DISPOSITIONS: Record<string, DispositionMeta> = {
  "plan-file":  { title: "Plan file",       glyph: "description", h: 70,  desc: "Written to the plan directory." },
  issues:       { title: "GitHub issues",   glyph: "task_alt",    h: 230, desc: "Published as tracked issues." },
  milestones:   { title: "Milestones",      glyph: "flag",        h: 295, desc: "Synced to repo milestones." },
  "skill-index":{ title: "Skill index",     glyph: "extension",   h: 70,  desc: "Upserted into Skills library." },
  knowledge:    { title: "Knowledge store", glyph: "psychology",  h: 195, desc: "Injected into agent prompts." },
  scratch:      { title: "Scratch",         glyph: "edit_note",   h: 250, desc: "Working note — not published." },
};
export const DISPOSITION_KEYS = Object.keys(DISPOSITIONS);

/** Default disposition for a stage kind. */
export function defaultDisposition(key: string): string {
  if (key === "streams") return "issues";
  if (key === "skills") return "skill-index";
  if (key === "discovery") return "knowledge";
  return "plan-file";
}

// ── import source (#923) ──
// The import screen pulls real blueprint gists from a source GitHub account; the mock community
// catalog (+ its preview/fork flow) was removed. Configurable sources land later (#598). For now
// the default source is the maintainer's account.
export const DEFAULT_GIST_SOURCE = "kevinthelago";

/** Whether an imported blueprint is OUT OF DATE with its upstream gist (#955): the gist's current
 *  `updated_at` is strictly newer than the one recorded locally at import/sync. Both are GitHub
 *  `updated_at` timestamps. Unknown on either side ⇒ can't tell ⇒ not stale (treat as current).
 *  Drives whether the import page renders an "Update" button instead of "✓ Imported". */
export function gistUpdateAvailable(currentUpdatedAt?: string, importedUpdatedAt?: string): boolean {
  if (!currentUpdatedAt || !importedUpdatedAt) return false;
  const cur = new Date(currentUpdatedAt).getTime();
  const imp = new Date(importedUpdatedAt).getTime();
  return isFinite(cur) && isFinite(imp) && cur > imp;
}

