import { describe, it, expect } from "vitest";
import { buildSkillLibrary } from "@/features/planner/blueprints/blueprintSkills";
import { addSkill, removeSkill, mkStageSection } from "@/features/planner/blueprints/blueprintEdit";
import type { SkillDef } from "@/features/skills/lib/skills";
import type { BlueprintStage } from "@/features/planner/stages/blueprints";

const skillDef = (id: string, name: string): SkillDef => ({
  id, name, kind: "procedure", source: "local", desc: `${name} desc`, prompt: "", tools: [], profiles: [],
  projects: [], enabled: true, pinned: false, invocations: 0, success: 0, avgTokensK: 0, lastUsed: "", trend: [],
} as unknown as SkillDef);

describe("blueprintSkills library (#636)", () => {
  const lib = buildSkillLibrary([skillDef("s1", "API design"), skillDef("s2", "House style")]);

  it("lists skills as pickable items", () => {
    expect(lib).toEqual([
      { id: "s1", name: "API design", kind: "skill", desc: "API design desc" },
      { id: "s2", name: "House style", kind: "skill", desc: "House style desc" },
    ]);
  });
});

describe("blueprintEdit skill helpers (#636)", () => {
  const base = (): BlueprintStage[] => [mkStageSection("api")];
  it("addSkill attaches (no dupes); removeSkill detaches", () => {
    let s = base();
    s = addSkill(s, s[0].uid, "s1");
    s = addSkill(s, s[0].uid, "s1"); // dupe ignored
    expect(s[0].skills).toEqual(["s1"]);
    s = addSkill(s, s[0].uid, "k1");
    expect(s[0].skills).toEqual(["s1", "k1"]);
    s = removeSkill(s, s[0].uid, "s1");
    expect(s[0].skills).toEqual(["k1"]);
  });
});

implementations.code:
// Pure blueprint/stage HELPERS (#513/#514, split out #2148): the functions over blueprint +
// section data — the authoring-lifecycle checks, search filtering, section/dep/lock resolution,
// the built-in refresh/merge, the blueprint-driven stage status + progress engine, and the
// template-change detection. Pure (no React/Tauri). Types live in blueprintTypes.ts; the packaged
// data + library assembly in blueprintBuiltins.ts.

import { PLAN_STAGES, type StageConfig, type StageId } from "@/features/planner/stages/planStages";
import { evalGate, gateApplies, type PlanSignals } from "@/features/planner/stages/stageGate";
import type {
  Blueprint, BlueprintStage, SectionStatus,
  StageRenderStatus, IncompleteStage, SectionDef, ModelCapabilityTier, StageSeed,
} from "@/features/planner/stages/blueprintTypes";
import { uid, makeBlueprints, dedupeSections } from "@/features/planner/stages/blueprintBuiltins";

// ── Dynamic-blueprint resolution (#1854 Phase a) ──────────────────────────────

/** Resolve the prompt to use for a stage, adapting to the driving model's capability tier (#1854
 *  Phase a). When a `tier` is given and the stage declares a {@link SectionDef.promptVariants}
 *  override for exactly that tier, that variant wins; otherwise the stage's base `prompt` is used —
 *  so a stage with no variants (or no tier) behaves exactly as today (the base prompt). The lookup is
 *  DIRECT (no cross-tier cascade): an absent variant falls straight back to the base `prompt`, which
 *  is already the open-ended frontier prompt. Returns "" for a missing section. */
export function resolveStagePrompt(
  section: Pick<SectionDef, "prompt" | "promptVariants"> | undefined,
  tier?: ModelCapabilityTier,
): string {
  if (!section) return "";
  const variant = tier ? section.promptVariants?.[tier] : undefined;
  return variant?.trim() ? variant : section.prompt;
}

/** The archetype seed content for a stage, or undefined when the stage carries none (#1854 Phase a).
 *  A convenience accessor so callers don't reach into `section.seed` (and so an empty/whitespace
 *  `content` is treated as absent). */
export function stageSeed(section: Pick<SectionDef, "seed"> | undefined): StageSeed | undefined {
  const seed = section?.seed;
  return seed?.content?.trim() ? seed : undefined;
}

/** Filter blueprints by a free-text query over name/desc/tags. Pure; drives the Library's search.
 *  The lifecycle-category facet went away with #3785 — a blueprint is a goal/domain route now, and
 *  lifecycle is discovered per PROJECT (`ClassifyConfig.lifecycle`), not declared per blueprint. */
export function filterBlueprints(blueprints: Blueprint[], opts: { query?: string }): Blueprint[] {
  const q = (opts.query ?? "").trim().toLowerCase();
  if (!q) return blueprints;
  return blueprints.filter((b) =>
    `${b.name} ${b.desc} ${(b.tags ?? []).join(" ")}`.toLowerCase().includes(q));
}

export const DEFAULT_BLUEPRINT_ID = "default";

/** Seed blueprints — the starter library, depicting every section/pipeline state. */
/**
 * Replace persisted built-in blueprints with their current code definitions (by id) and
 * append any new built-ins, leaving user-created / forked / imported blueprints untouched.
 * Built-ins are code-owned templates, but `blueprints` is persisted — this lets improvements
 * (the optional UI stage, enabled repos, updated prompts, …) reach an already-seeded store
 * instead of being pinned to the version a user first ran (#677).
 */
export function refreshBuiltIns(persisted: Blueprint[]): Blueprint[] {
  const fresh = makeBlueprints();
  const byId = new Map(fresh.map((b) => [b.id, b]));
  // Drop persisted built-ins that no longer exist in code (removed templates), refresh the rest by
  // id, and leave user-created / forked / imported blueprints untouched (#923 cleanup).
  const merged = persisted
    .filter((b) => b.origin !== "built-in" || byId.has(b.id))
    // Built-ins are replaced by their fresh code def; everything else is a persisted
    // user/forked/imported blueprint — dedup its section keys defensively.
    .map((b) => (b.origin === "built-in" && byId.has(b.id) ? byId.get(b.id)! : { ...b, sections: dedupeSections(b.sections) }));
  for (const b of fresh) if (!merged.some((x) => x.id === b.id)) merged.push(b);
  return merged;
}

/**
 * Dependency / lock resolution. A section is LOCKED when it's enabled but a
 * dependency is off or itself locked. A dep this blueprint omits is treated as met.
 */
export function computeStatus(sections: BlueprintStage[]): Record<string, SectionStatus> {
  const byKey: Record<string, BlueprintStage> = Object.fromEntries(sections.map((s) => [s.key, s]));
  const memo: Record<string, boolean> = {};
  function satisfied(key: string, stack: Set<string>): boolean {
    if (key in memo) return memo[key];
    const s = byKey[key];
    if (!s) return true;
    if (!s.enabled) return (memo[key] = false);
    if (stack.has(key)) return true; // cycle guard
    stack.add(key);
    const ok = (s.deps || []).every((d) => satisfied(d, stack));
    stack.delete(key);
    return (memo[key] = ok);
  }
  const out: Record<string, SectionStatus> = {};
  for (const s of sections) {
    const present = (s.deps || []).filter((d) => byKey[d]);
    const unmet = present.filter((d) => !byKey[d].enabled || !satisfied(d, new Set()));
    out[s.key] = { locked: s.enabled && unmet.length > 0, unmet, satisfied: satisfied(s.key, new Set()) };
  }
  return out;
}

/** Move `fromUid` before/after `toUid` in a uid-keyed list (drag-reorder). */
export function reorder<T extends { uid: string }>(arr: T[], fromUid: string, toUid: string, before: boolean): T[] {
  const a = [...arr];
  const fi = a.findIndex((x) => x.uid === fromUid);
  if (fi < 0) return arr;
  const [item] = a.splice(fi, 1);
  let ti = a.findIndex((x) => x.uid === toUid);
  if (ti < 0) { a.push(item); return a; }
  if (!before) ti += 1;
  a.splice(ti, 0, item);
  return a;
}

/** Deep-copy sections with fresh uids (for duplicate). */
export function cloneStages(sections: BlueprintStage[]): BlueprintStage[] {
  return sections.map((s) => ({ ...s, uid: uid("sec") }));
}

/**
 * Derive the per-project StageConfig (enabled + order over the registry's known
 * StageIds) that the planning N-bar reads, from a blueprint's sections. Custom and
 * non-registry sections (e.g. testing) are omitted — they configure planning but
 * don't have a registry gate yet.
 */
/**
 * What to record when a project's planning opens (#647). A brand-new project (no stage
 * config) seeds from + records the active blueprint. An existing project with NO recorded
 * blueprint (planned before blueprint tracking) backfills to the default — so selecting a
 * different blueprint still triggers the reset prompt instead of silently doing nothing.
 * Otherwise the project already knows its blueprint, so nothing changes here.
 */
export function resolveProjectSeed(
  hasConfig: boolean, recordedBlueprintId: string | undefined, activeBlueprintId: string,
): { seedConfig: boolean; setBlueprintId?: string } {
  if (!hasConfig) return { seedConfig: true, setBlueprintId: activeBlueprintId };
  if (!recordedBlueprintId) return { seedConfig: false, setBlueprintId: DEFAULT_BLUEPRINT_ID };
  return { seedConfig: false };
}

export function blueprintToStageConfig(bp: Blueprint): StageConfig {
  const known = new Set<string>(PLAN_STAGES.map((s) => s.id));
  const enabled = Object.fromEntries(PLAN_STAGES.map((s) => [s.id, false])) as Record<StageId, boolean>;
  const order: StageId[] = [];
  for (const s of bp.sections) {
    if (!known.has(s.key)) continue;
    const id = s.key as StageId;
    enabled[id] = s.enabled;
    order.push(id);
  }
  return { enabled, order };
}

// ── Blueprint-driven status (#…) ──────────────────────────────────────────────
// These evaluate a blueprint's sections DIRECTLY against the published signal bag —
// no PLAN_STAGES enum, no per-stage hardcoding. Each section carries its own
// declarative gate (`gateRule`), applicability (`appliesWhen`), and `deps`, so a
// built-in section and a cloud-distributed one are evaluated by the exact same code.
// The progress bar, readiness check, current-section, and the "what's incomplete"
// feedback all read from here.

/** The signal that marks an informational (gateless) section confirmed/complete (#664). */
export const confirmedSignal = (key: string) => `confirmed:${key}`;

/** The signal that marks an OPTIONAL section the user deliberately SKIPPED (#921). A skipped
 *  section counts as resolved — the flow advances past it and it never blocks completion — but
 *  it renders distinctly ("skipped", not "complete"). */
export const skippedSignal = (key: string) => `skipped:${key}`;

/** Whether a section is done/resolved. A user-SKIPPED section (#921) is resolved regardless of
 *  its gate. Otherwise: a section WITH a declarative gate uses {@link evalGate}; a gateless
 *  ("informational") section is done only when confirmed (a `confirmed:<key>` signal), so a
 *  fresh/cleared plan shows it as in-progress rather than ✓ (#664). */
export function stageDone(section: BlueprintStage, signals: PlanSignals): { done: boolean; fraction: number } {
  if (signals[skippedSignal(section.key)] === true) return { done: true, fraction: 1 };
  if (section.gateRule) return evalGate(section.gateRule, signals);
  const ok = signals[confirmedSignal(section.key)] === true;
  return { done: ok, fraction: ok ? 1 : 0 };
}

/** Whether a section was resolved by a deliberate user SKIP (vs genuinely completed) — drives the
 *  distinct "skipped" rendering. (#921) */
export function stageSkipped(section: BlueprintStage, signals: PlanSignals): boolean {
  return signals[skippedSignal(section.key)] === true;
}

/** A dependency is satisfied when the blueprint omits it, it's disabled, it's N/A, or
 *  its own gate is complete. Mirrors the registry's dep rule, but over blueprint data. */
function depSatisfied(depKey: string, byKey: Record<string, BlueprintStage>, signals: PlanSignals): boolean {
  const dep = byKey[depKey];
  if (!dep) return true;        // this blueprint doesn't include the dep
  if (!dep.enabled) return true;
  if (dep.optional) return true;        // optional deps never block dependents (#676)
  if (!gateApplies(dep.appliesWhen, signals)) return true;
  return stageDone(dep, signals).done;
}

/**
 * Resolve a section's render status + bar fill from blueprint data alone: its
 * applicability rule, its declarative gate, and its (included, enabled) dependencies.
 */
export function stageStatus(
  section: BlueprintStage,
  sections: BlueprintStage[],
  signals: PlanSignals,
): { status: StageRenderStatus; fraction: number } {
  // An optional section is always shown (it bypasses appliesWhen) — it's just never
  // required; non-optional sections still go N/A when their applicability rule fails (#676).
  if (!section.optional && !gateApplies(section.appliesWhen, signals)) return { status: "na", fraction: 0 };
  const g = stageDone(section, signals);
  if (g.done) return { status: "complete", fraction: 1 };
  const byKey: Record<string, BlueprintStage> = Object.fromEntries(sections.map((s) => [s.key, s]));
  const locked = (section.deps || []).some((d) => !depSatisfied(d, byKey, signals));
  return { status: locked ? "locked" : "in-progress", fraction: g.fraction };
}

/** The enabled sections of a blueprint, in their declared order. */
export function enabledStages(sections: BlueprintStage[]): BlueprintStage[] {
  return sections.filter((s) => s.enabled);
}

/** Whether every enabled, applicable section is resolved — the triage readiness gate. An OPTIONAL
 *  section must be DECIDED (completed or user-skipped) just like a required one; a user-skip marks
 *  it done (#921). This is what lets the user, not the app, decide whether to skip an optional
 *  stage — the plan isn't "complete" until each enabled optional stage has been addressed. */
export function planStagesComplete(sections: BlueprintStage[], signals: PlanSignals): boolean {
  return enabledStages(sections).every((s) => {
    const { status } = stageStatus(s, sections, signals);
    return status === "complete" || status === "na";
  });
}

/**
 * The current ("reached") section: the first enabled + applicable section that is
 * in progress. When all are complete it falls back to the last enabled + applicable
 * one. Drives which pipelines' second screens render.
 */
export function currentStage(sections: BlueprintStage[], signals: PlanSignals): BlueprintStage | undefined {
  // The flow STOPS on an optional stage too, so the USER decides whether to do or skip it (#921) —
  // a skipped optional section is `stageDone` ⇒ not "in-progress", so the frontier advances past
  // it. Optional sections bypass `appliesWhen` (always shown), matching `stageStatus`.
  const applicable = enabledStages(sections).filter((s) => s.optional || gateApplies(s.appliesWhen, signals));
  const active = applicable.find((s) => stageStatus(s, sections, signals).status === "in-progress");
  return active ?? applicable[applicable.length - 1];
}

/**
 * Every enabled section that is not yet complete, in section order, each tagged with
 * its status and the section's own gate description as the reason. Fully blueprint-
 * driven — including unknown / cloud-distributed sections — so adding or reordering a
 * section flows through here with nothing hardcoded per stage. Powers the feedback
 * shown when the user clicks a locked Triage button.
 */
export function incompleteStages(sections: BlueprintStage[], signals: PlanSignals): IncompleteStage[] {
  const out: IncompleteStage[] = [];
  for (const s of enabledStages(sections)) {
    const { status } = stageStatus(s, sections, signals);
    if (status === "complete" || status === "na") continue;
    out.push({ key: s.key, name: s.name, reason: s.gate, status });
  }
  return out;
}

// ── Blueprint/template-change detection (#827/#1296) ──────────────────────────
// The context signature (planner/workspace.rs `context_signature`) is `v{TEMPLATE_VERSION}|
// repos|kb|stages`. Its FIRST `|`-delimited field is the blueprint/planner-template version;
// the rest is per-project SETUP (linked repos, KB blocks, enabled stages). A genuine
// "the blueprint has changed" event — the only thing that should auto-open the destructive
// BlueprintUpdateModal — is a change to that version field. Mere setup tweaks (link a repo,
// toggle a KB block, enable/disable a stage) change the later fields and drive only the quiet
// "context updated · refresh" badge, NOT the modal (#1296).

/** The blueprint/planner-template version component of a context signature (everything before
 *  the first `|`), or "" when the signature is empty/absent. */
export function signatureTemplateVersion(sig: string | null | undefined): string {
  if (!sig) return "";
  const bar = sig.indexOf("|");
  return bar === -1 ? sig : sig.slice(0, bar);
}

/** True only when two non-empty signatures carry DIFFERENT template-version prefixes — i.e. the
 *  blueprint/planner template was genuinely updated, not just the linked repos / KB / stages. */
export function blueprintTemplateChanged(currentSig: string | null | undefined, baselineSig: string | null | undefined): boolean {
  const cur = signatureTemplateVersion(currentSig);
  const base = signatureTemplateVersion(baselineSig);
  return !!cur && !!base && cur !== base;
}

/**
 * Whether the destructive "this project's blueprint has changed" modal should AUTO-open (#1296).
 * Gated on a true template-version mismatch (`blueprintTemplateChanged`) — never on benign setup
 * tweaks — plus an existing plan to protect, and the once-per-open `alreadyShown` guard.
 */
export function shouldAutoOpenBlueprintModal(args: {
  currentSig: string | null | undefined;
  baselineSig: string | null | undefined;
  hasExistingPlan: boolean;
  alreadyShown: boolean;
}): boolean {
  return blueprintTemplateChanged(args.currentSig, args.baselineSig)
    && args.hasExistingPlan
    && !args.alreadyShown;
}

// Blueprint model TYPES (#513/#514, split out #2148): the pure type surface behind the
// Blueprints page — the substeps, the section/stage defs, the Blueprint shape, and the
// status result types. No runtime data or logic; the built-in library lives in
// blueprintBuiltins.ts and the pure helpers in blueprintStages.ts (both re-exported by
// the ./blueprints barrel).

import { type ClassificationSignals } from "@/features/planner/stages/classification";
import { type StageGate, type Requirement } from "@/features/planner/stages/stageGate";
import { type AgentFlow } from "@/features/planner/fleet/agentFlow";
// Type-only cross-feature import (allowed by the #1545 boundary): the blueprint team (#2450)
// reuses the org feature's graph shape rather than redeclaring it.
import type { Position, Relationship } from "@/features/teams";

// ── Substeps ─────────────────────────────────────────────────────────────────
// A discrete step WITHIN a stage. The conductor injects ONE substep's prompt at a time and
// advances when its artifact is written + confirmed — incremental, instead of front-loading
// the whole stage's instructions. A `loop` substep repeats once per dynamic item discovered
// during the stage (the feature workshop), so the conductor drives "one feature at a time".
export type SubStepLoop = "features" | "repos" | "topics";
export interface SubStep {
  /** Canonical key / artifact stem (e.g. "goal" → goal.md). For a loop, the loop's id. */
  key: string;
  label: string;
  /** Injected into the session when this substep becomes active. Plan-only — never describes
   *  publishing (the user owns that). */
  prompt: string;
  /** Human "done when…"; absent ⇒ informational (no gate of its own). */
  gate?: string;
  /** Repeat once per dynamic item (a feature, a repo). Absent ⇒ a single static substep. */
  loop?: SubStepLoop;
}

// ── Dynamic-blueprint additions (#1854 Phase a) ──────────────────────────────
// The first slice of the dynamic-blueprints epic: a stage can adapt its prompt to the DRIVING
// MODEL and can carry ARCHETYPE SEED CONTENT. Both are optional and additive — a stage without
// them behaves exactly as before (its single `prompt`, no seed).

/** A model CAPABILITY tier — the axis model-variant prompts key on (#1854 Phase a). Deliberately
 *  keyed by *capability*, not by a vendor model id, because blueprints are WAN-distributable and
 *  must not couple to a specific model/provider (they run on any {@link LlmProvider} via the
 *  bsc-agent "run on any model" track, #1078):
 *   - `frontier` — top frontier models (Claude Opus/Sonnet, GPT-4-class). The default open-ended
 *     prompt (the base `prompt`) is already written for this tier, so an explicit variant is only
 *     needed to override it.
 *   - `standard` — mid-capability hosted models (Haiku-class, smaller hosted models).
 *   - `local`    — weak local models. The headline payoff: a tight, schema-shaped, more-explicit
 *     directive prompt that lets a weak model plan reliably.
 *  A tier with no variant defined falls back to the base `prompt` (see {@link resolveStagePrompt}). */
export type ModelCapabilityTier = "frontier" | "standard" | "local";

/** Archetype seed content for a stage (#1854 Phase a) — starter content the stage can offer when it
 *  opens (e.g. a "twitter clone" archetype → a starter feature set for the Features stage). Additive:
 *  a stage with no `seed` behaves as today. Seeds; the planner + user still shape the final artifact. */
export interface StageSeed {
  /** The archetype this seed represents (a descriptive slug, e.g. "twitter-clone"). */
  archetype?: string;
  /** The starter content, as markdown — offered as an injectable option when the stage is active. */
  content: string;
}

// ── Sections (the canonical planning stages) ─────────────────────────────────

/** One discovery-checklist dimension. The editor-presentation fields (`icon`/`hue`/`blurb`)
 *  are present only for the dimensions that double as add-stage palette kinds (#1603); plain
 *  checklist dimensions carry just `key` + `title`. */
export interface DimensionMeta {
  key: string;
  title: string;
  /** Material/Lucide icon name (the editor `<Ic>` glyph). */
  icon?: string;
  /** Accent hue (oklch) for the palette card. */
  hue?: number;
  blurb?: string;
}

export interface SectionDef {
  name: string;
  /** Unicode symbol rendered as text in the focused-pane stepper (`focusedPlan.ts`). */
  glyph: string;
  /** Material/Lucide icon name for the editor/bar `<Ic>` component (#1603 — the editor
   *  presentation metadata, single-sourced here from the stage's own JSON). */
  icon: string;
  /** Accent hue (oklch) for the stage's editor/palette card (#1603). */
  hue: number;
  /** Human-readable gate description, shown in the editor and the readiness feedback. */
  gate: string;
  deps: string[];
  blurb: string;
  prompt: string;
  /** Model-variant prompts (#1854 Phase a) — per {@link ModelCapabilityTier} overrides of `prompt`,
   *  so a stage adapts its instructions to the DRIVING model (a tight, schema-shaped prompt for a
   *  weak `local` model alongside the open-ended default). Absent tier ⇒ the base `prompt` is used
   *  (resolved via {@link resolveStagePrompt}); the whole field absent ⇒ today's single-prompt
   *  behavior. Reference-by-tier; unknown tiers are simply ignored. */
  promptVariants?: Partial<Record<ModelCapabilityTier, string>>;
  /** Archetype seed content (#1854 Phase a) — starter content this stage offers when active (e.g. a
   *  starter feature set for a known archetype). Absent ⇒ no seed (today's behavior). */
  seed?: StageSeed;
  /** UI stage only (#604): the self-contained instruction the file-intake "Route" action injects
   *  into the planner to read the staged design files and route each to the right repo. Carried as
   *  stage DATA (like `prompt`) so it isn't hardcoded in the frontend. Absent ⇒ no route prompt. */
  routePrompt?: string;
  /** Declarative completion gate (#…) — the DATA that decides this section's
   *  done-ness. Carried on every section instance so a section is fully serializable
   *  and distributable; the app evaluates it via {@link evalGate}. Absent ⇒ the
   *  section is informational (vacuously complete). */
  gateRule?: StageGate;
  /** Optional applicability rule (e.g. UI only when the project needs a UI). Absent ⇒
   *  the section always applies. */
  appliesWhen?: Requirement;
  /** Declarative "skippable RIGHT NOW" rule (#2854) — the same {@link Requirement} shape as
   *  {@link appliesWhen}/gateRule, evaluated against the live signal bag, that makes a section's
   *  Skip control appear. It expresses the "empty ⇒ skippable, populated ⇒ required" pattern
   *  WITHOUT the stage disappearing (unlike `appliesWhen`, which drops it entirely): e.g. Features
   *  carries `{ signal: "featuresDefined", target: 0, op: "==" }`, so an empty Features stage is
   *  skippable but one with content is required. Absent ⇒ not skippable on its own (only an
   *  {@link optional} section or gate-override offers Skip). Drives `Stage.skippable`. */
  skipWhen?: Requirement;
  /** An OPTIONAL section is shown but never required: it doesn't block plan completion or
   *  downstream dependents, and it's off the critical path (currentStage skips it) — the
   *  user can fill it or skip it (#676). Equivalent to an always-passing {@link skipWhen}. */
  optional?: boolean;
  /** Context stage only (#1019): the baseline REQUIRED topics this section seeds into the project's
   *  dynamic context manifest (plan.db) when first adopted. The planner then adjusts the set with
   *  `bsc-plan context require/unrequire`. Absent ⇒ the universal {@link DISCOVERY_BASELINE}. */
  requires?: string[];
  /** Discovery stage only (#1603): the checklist dimensions, carried as data so the editor's
   *  add-stage palette + the dimension vocabulary (`KNOWN_DIMENSIONS`) single-source from here. */
  dimensions?: DimensionMeta[];
  /** Output disposition (#609) — what happens to this stage's artifact (a key into
   *  DISPOSITIONS: plan-file / issues / milestones / skill-index / knowledge / scratch).
   *  Editor metadata; the runtime doesn't read it. Absent ⇒ defaultDisposition(key). */
  output?: string;
  /** Attached skills/knowledge (#636) — library item ids (KB blocks or Skills) injected
   *  into the agent's context for this stage. Resolved at planning + fleet launch
   *  (slice b). Reference-by-id; unresolved ids surface a warning. */
  skills?: string[];
  /** Attached MCP servers (#897) — server NAMES (the portable ref, matching the catalog +
   *  `<mcp_assign>`), scoped to the project at launch so the planner/fleet can call them.
   *  Kept SEPARATE from `skills`: MCP servers are tools (research/analysis/grading), skills are
   *  knowledge. Reference-by-name; an unresolved name surfaces a warning in the editor. */
  mcp?: string[];
  /** Ordered substeps the conductor injects one at a time (#…). Absent ⇒ the stage is driven
   *  by a single prompt (its `prompt`). Pipeline `triggerTarget`s reference these by `key`. */
  substeps?: SubStep[];
  /** The planner-facing directive prose (#1462) — the single source of truth, shared byte-for-byte
   *  with the Rust `stage_directive`, read from this stage's `prompts/stages/<id>.json`. Only the
   *  duplicated stages carry one; stages without it use the generic Rust fallback. */
  directive?: string;
  /** Reserved (populated by #1395) — the classification signals that gate this stage's applicability,
   *  and its ordering tier. Typed now so #1395 fills them without re-churning files; unset today. */
  signals?: ClassificationSignals;
  phase?: "discover" | "decide" | "generate";
}

export interface BlueprintStage extends SectionDef {
  uid: string;
  key: string;
  enabled: boolean;
  expanded: boolean;
}

/** Where a blueprint came from (#609) — drives the card's origin tag. */
export type BlueprintOrigin = "built-in" | "local" | "forked" | "imported";

/** Whether a blueprint starts from a pitch (create) or runs against existing repos
 *  (operate) — selects the planner intro at launch. */
export type BlueprintMode = "create" | "operate";

/** Gist link state for a blueprint (#609) — the publish/sync state-machine. Slice 5
 *  populates this; the Library card reads it for the sync badge. Absent ⇒ local-only. */
export interface BlueprintGist {
  state: "local" | "dirty" | "synced" | "forked";
  /** Whether an upstream update is available (forked blueprints). */
  behind?: boolean;
  rev?: string;
  author?: string;
  id?: string;
  url?: string;
  public?: boolean;
  /** The upstream gist's `updated_at` recorded at import/sync. Compared against the gist's CURRENT
   *  `updated_at` on the import-from-gist page to detect an available update (#955). */
  updatedAt?: string;
}

/** Fleet POLICY a blueprint declares (#1854 Phase b) — the default per-stream {@link AgentProfile}
 *  and {@link AgentFlow} the planner instantiates when it generates this project type's fleet. A
 *  COMPOSED typed sub-model (epic discipline #1: not N flat top-level fields), carrying only the
 *  *recipe/policy* — the DEFAULTS — while the concrete per-stream config stays planner-GENERATED
 *  per-project (discipline #2: static template vs generation policy). Resolution precedence is
 *  stream-declared → this policy → the hard launch-time default (see `resolveStreamProfile` /
 *  `resolveStreamFlow` in `../fleet/fleetPolicy`). Both fields optional ⇒ when unset, today's
 *  launch-time defaults apply, byte-for-byte.
 *
 *  Trust boundary (discipline #3): a blueprint only *seeds* the launch default here — the role
 *  gate (#219) still caps the session. The request-vs-cap permission POSTURE is Phase (c), out of
 *  scope for this sub-model. */
export interface FleetPolicy {
  /** Default {@link AgentProfile} id for a WORKER stream that doesn't pin its own `profile` (#289).
   *  A reference-by-id; an unknown id just falls through to the role default at launch. Applies to
   *  worker streams only — never the director, which keeps its role's read-only review profile. */
  profile?: string;
  /** Default {@link AgentFlow} (autonomy + push + trigger + gate) for a stream that doesn't declare
   *  its own `flow` (#297). Absent ⇒ the launch path applies {@link DEFAULT_FLOW}. */
  flow?: AgentFlow;
}

/** The TEAM a blueprint carries (#2450) — an embedded org configuration: positions (personas
 *  referenced by id — personas stay a global library) wired by relationships, with the canvas
 *  layout coords on each position. The same graph shape the `bsc org` store holds, MINUS the
 *  library identity fields (`id`/`name`/`blurb`/`builtin`) — the blueprint itself is the identity.
 *
 *  FORK-ON-ATTACH: authoring starts by DEEP-COPYING a library org (or blank) into
 *  `blueprint.team` (see `forkTeamFromOrg`); the `bsc org` store remains the archetype library.
 *  Editing a blueprint's team never mutates the library org and vice versa — reproducibility of
 *  the blueprint artifact wins. Persisted inside the blueprint's JSON (the `bsc blueprint` store
 *  is verbatim JSON), so export/import carries it automatically. Optional — a blueprint without
 *  `team` behaves exactly as before; plan-time consumption (seeding fleet streams from the team)
 *  is a deliberate follow-up, not this field's contract. */
export interface BlueprintTeam {
  positions: Position[];
  relationships: Relationship[];
}

/** The UI KIT a blueprint pins (#2465) — a LOCKFILE entry, deliberately the opposite of `team`:
 *  the kit is REFERENCED, never embedded, because kits are immutable versioned artifacts shared
 *  across blueprints (one copy in the global store, `~/.base-studio-code/kits/<id>/<version>/`,
 *  no matter how many blueprints pin it). Exact pins only — no version ranges (reproducibility).
 *
 *  `hash` is the sha256 (lowercase hex) of the kit artifact's bytes, verified BEFORE a fetched
 *  kit is accepted into the store (resolve flow, `uiKitPin.ts`); `source` is the typed-gist URL
 *  to fetch from when `id@version` isn't in the local store yet. A new blueprint default-pins the
 *  packaged `bsc/react-ui` kit ({@link Blueprint.uiKit} set in `addBlueprint`); a blueprint
 *  without a pin behaves exactly as before. */
export interface BlueprintUiKit {
  /** Publisher-scoped kit id (e.g. `"bsc/react-ui"`). */
  id: string;
  /** Exact semver of the pinned artifact (immutable once published). */
  version: string;
  /** sha256 (lowercase hex) of the artifact bytes. */
  hash: string;
  /** Typed-gist URL to fetch from when the id@version is missing locally. */
  source?: string;
  /** The kit THEME paired with the pin (#2489) — a `bsc ui theme` id. Absent ⇒ `"default"`. An ID,
   *  never the vars: the theme resolves through `bsc ui theme get` at EMISSION time
   *  (`bsc ui emit-css --theme <id>` → the generated app's tokens.css + theme.css), so
   *  designer-authored themes apply the moment they exist. This is the blueprint-level default;
   *  the planned application's actual pair is recorded per project in plan.db (`bsc plan ui`). */
  themeId?: string;
}

/** The SOUND KIT a blueprint pins (#3372, epic #3071 phase 4) — the sounds twin of
 *  {@link BlueprintUiKit}, deliberately the SAME lockfile discipline: the kit is REFERENCED, never
 *  embedded, against the global versioned sound-kit release store
 *  (`~/.base-studio-code/sound-kits/<id>/<version>/`, the Rust `bsc sound release` CLI, #3371).
 *  Exact pins only — no ranges (reproducibility). A new blueprint default-pins the packaged
 *  `bsc/signal` kit ({@link Blueprint.soundKit} set in `addBlueprint`), which resolves against the
 *  store's embedded fallback and so needs no fetch.
 *
 *  NO `themeId` twin: a theme restyles a component kit's tokens, and a sound kit has no token
 *  contract to restyle — its cues ARE the palette. Adding a dead field "for symmetry" would invent
 *  a knob nothing reads. */
export interface BlueprintSoundKit {
  /** Publisher-scoped kit id (e.g. `"bsc/signal"`). */
  id: string;
  /** Exact semver of the pinned artifact (immutable once published). */
  version: string;
  /** sha256 (lowercase hex) of the artifact bytes — the canonical SoundKit object, NOT a wrapper. */
  hash: string;
  /** Typed-gist URL to fetch from when the id@version is missing locally. */
  source?: string;
}

/** A blueprint's DESIGN contribution (#2646, epic #2606) — the categorical dimensions it introduces
 *  that need design-token backing (a `simulation` node-kind, say), plus an optional theme by reference.
 *  Downloading a blueprint RECONCILES this against the local design contract: categories the contract
 *  doesn't define are surfaced (a dedicated confirm-list, 5b) and filled by the generator (#2636), so a
 *  shared blueprint brings its look with NO holes. Deliberately the opposite of embedding: categories
 *  are KEYS (the generator derives on-brand colours), `theme` is a `bsc ui theme` id (never the vars). */
export interface BlueprintDesign {
  /** Categorical keys the blueprint introduces — reconciled against the contract's graph-category group;
   *  any the contract doesn't define is a gap the generator fills (5b). */
  categories?: string[];
  /** Optional theme by reference — a `bsc ui theme` id (mirrors the uiKit pin's `themeId`; absent ⇒ default). */
  theme?: string;
}

export interface Blueprint {
  id: string;
  name: string;
  desc: string;
  sections: BlueprintStage[];
  /** The curated FEATURE LIST this blueprint seeds (#3785) — the raw `features` section content
   *  (`features.md`) captured when a completed project is promoted (`generateBlueprint`). A blueprint
   *  is a goal/domain planning ROUTE (its `sections`/stages) PLUS the features that route builds
   *  (this). Absent ⇒ no seeded features (the blueprint is a bare route); applying one with features
   *  seeds them into the new project's Features stage. */
  features?: string;
  /** Display + provenance metadata (#609). All optional — the Library derives sensible
   *  fallbacks (icon from the name, hue from the id, origin "local", local-only gist). */
  icon?: string;
  /** Accent hue (oklch) for the card/editor icon. */
  h?: number;
  origin?: BlueprintOrigin;
  tags?: string[];
  gist?: BlueprintGist;
  /** How many projects this blueprint has seeded. */
  uses?: number;
  updatedAt?: string;
  /** Blueprint-wide attached skills/knowledge (#636) — applied across every stage,
   *  in addition to each section's own `skills`. Library item ids. */
  skills?: string[];
  /** Blueprint-wide attached MCP servers (#897) — applied across every stage, in addition to
   *  each section's own `mcp`. Server NAMES (the portable ref). */
  mcp?: string[];
  /** The component KIT (#2277) an app seeded from this blueprint is built on — a `bsc ui` kit id
   *  (e.g. `"react-ui"`). Recording it makes every project seeded here a CONSUMER of that kit, so a kit
   *  change fans out to it (the `kit_usage` consumer index self-fills at planning). Absent ⇒ the blueprint
   *  isn't tied to a shared kit (an authoring blueprint, or one that operates on a repo's own UI). */
  kit?: string;
  /** Fleet policy (#1854 Phase b) — the DEFAULT per-stream profile + flow the planner instantiates
   *  when it generates this project type's fleet. A composed sub-model; see {@link FleetPolicy}.
   *  Absent ⇒ today's launch-time defaults apply (byte-identical). */
  fleetPolicy?: FleetPolicy;
  /** The blueprint's own TEAM (#2450) — an embedded org configuration forked from the org library
   *  (or authored blank). A composed sub-model; see {@link BlueprintTeam}. Absent ⇒ no team
   *  authored (today's behavior, byte-identical everywhere). */
  team?: BlueprintTeam;
  /** The UI kit this blueprint pins (#2465) — a lockfile entry referencing an immutable
   *  `id@version` artifact in the global kit store; see {@link BlueprintUiKit}. Absent ⇒ no pin
   *  (existing blueprints are unaffected); a NEW blueprint default-pins the packaged kit. */
  uiKit?: BlueprintUiKit;
  /** The SOUND kit this blueprint pins (#3372) — the same lockfile entry one pillar over, against
   *  the versioned sound-kit release store; see {@link BlueprintSoundKit}. Absent ⇒ no pin
   *  (existing blueprints are unaffected); a NEW blueprint default-pins the packaged `bsc/signal`. */
  soundKit?: BlueprintSoundKit;
  /** The blueprint's DESIGN contribution (#2646) — the categorical keys it introduces + an optional
   *  theme ref; reconciled against the local design contract on download. Absent ⇒ nothing to reconcile
   *  (existing blueprints unaffected). See {@link BlueprintDesign}. */
  design?: BlueprintDesign;
  /** Create (from a pitch) vs operate (against existing repos). Absent ⇒ create. */
  mode?: BlueprintMode;
  /** Catalog metadata: a one-line catalog pitch, the audience it serves, and the share visibility
   *  (used by the gist share/import flow). `tags` doubles as the "best for" catalog tags. */
  pitch?: string;
  audience?: string;
  visibility?: "local" | "private-gist" | "catalog";
}

/** The JSON shape of a built-in blueprint definition (stages/blueprints/*.json): blueprint
 *  metadata + an ordered list of section KEYS (chaining to stages/sections/*.json). The keys
 *  resolve to full section instances via mkStage at load — no blueprint data lives in TS. */
export interface BlueprintDef extends Omit<Blueprint, "sections"> {
  /** Display order within the built-in library. */
  order?: number;
  /** Ordered section refs: a key into STAGE_DEFS + an optional per-blueprint `optional` flag. */
  sections: { key: string; optional?: boolean }[];
}

export interface SectionStatus { locked: boolean; unmet: string[]; satisfied: boolean }

/** Render status of a blueprint section. `na` = not applicable to this project. */
export type StageRenderStatus = "locked" | "in-progress" | "complete" | "na";

/** A blueprint section that isn't satisfied yet — what the user still has to finish. */
export interface IncompleteStage {
  key: string;
  /** The section's display name, straight from the blueprint. */
  name: string;
  /** The section's own gate description (`gate`) — the human "what's left". */
  reason: string;
  /** Locked behind an unfinished dependency vs. simply in progress. */
  status: "locked" | "in-progress";
}

// Blueprints (#513/#514): the model behind the Blueprints page. A blueprint is an
// ordered list of planning SECTIONS (stages) that seeds every new project. Each
// section owns its prompt module (the instructions Claude receives for that stage)
// and its PIPELINES — pluggable actions that run on the stage's output. Pure (no
// React/Tauri) so it's unit-testable and the store can seed from it directly.
//
// Mirrors design/base-studio-code-projects/Blueprints.html.
//
// Decomposed (#2148) into three colocated modules, re-exported here so this remains the
// single public entry point (every importer keeps `@/features/planner/stages/blueprints`):
//   • blueprintTypes.ts    — the pure type surface (SectionDef / Blueprint / status types).
//   • blueprintBuiltins.ts — the packaged stage defs + built-in library assembly (STAGE_DEFS,
//                            mkStage, makeBlueprints, CATEGORY_META, …).
//   • blueprintStages.ts   — the pure helpers (auth-lifecycle, filtering, the blueprint-driven
//                            stage status/progress engine, template-change detection).

export * from "@/features/planner/stages/blueprintTypes";
export * from "@/features/planner/stages/blueprintBuiltins";
export * from "@/features/planner/stages/blueprintStages";

tests.src:
import { describe, it, expect } from "vitest";
import {
  makeBlueprints, mkStage, computeStatus, reorder, cloneStages, blueprintToStageConfig,
  stageStatus, incompleteStages, planStagesComplete, currentStage, confirmedSignal, skippedSignal,
  stageDone,
  signatureTemplateVersion, blueprintTemplateChanged, shouldAutoOpenBlueprintModal,
  dedupeSections, resolveStagePrompt, stageSeed,
  STAGE_DEFS, type BlueprintStage, type Blueprint, type SectionDef,
} from "@/features/planner/stages/blueprints";
import { SKILLS } from "@/shared/data/skills";
import { PLAN_STAGES, buildPlanStageState } from "@/features/planner/stages/planStages";
import { planStateToSignals } from "@/features/planner/stages/planStageDerive";
import { evalGate } from "@/features/planner/stages/stageGate";

const sig = (over: Parameters<typeof buildPlanStageState>[0] = {}) =>
  planStateToSignals(buildPlanStageState(over));
const setEnabled = (secs: BlueprintStage[], key: string, enabled: boolean): BlueprintStage[] =>
  secs.map((s) => (s.key === key ? { ...s, enabled } : s));

describe("greenfield blueprints declare their consumer kit (#2810)", () => {
  const bps = makeBlueprints();

  it("CREATE built-ins auto-record kit=react-ui so the kit_usage edge fills at bind (#3785)", () => {
    // …every create-from-a-pitch blueprint actually SHIPS an app UI. Keyed off `mode` since #3785
    // removed the lifecycle `category` this used to read.
    const create = bps.filter((b) => b.mode !== "operate");
    expect(create.length).toBeGreaterThan(0);
    expect(create.every((b) => b.kit === "react-ui")).toBe(true);
  });

  it("an OPERATE-on-existing-repos built-in isn't auto-tied to a shared kit", () => {
    const other = bps.find((b) => b.mode === "operate");
    if (other) expect(other.kit).toBeUndefined();
  });
});

describe("blueprints — seed library", () => {
  it("seeds the starter blueprints with a 'default'", () => {
    const bps = makeBlueprints();
    expect(bps.find((b) => b.id === "default")).toBeTruthy();
    // #3785 made `default` the greenfield superset; #3783 adds the five domain greenfields
    // (crm/erp/helpdesk/hr/project-management) that walk that same route.
    expect(bps.length).toBe(6);
    for (const id of ["crm", "erp", "helpdesk", "hr", "project-management"]) {
      expect(bps.find((b) => b.id === id), `built-in blueprint '${id}' present`).toBeTruthy();
    }
  });

  it("each section carries a prompt module and a gate from its def", () => {
    const ctx = makeBlueprints()[0].sections.find((s) => s.key === "discovery")!;
    expect(ctx.prompt.length).toBeGreaterThan(20);
    expect(ctx.gate).toBe(STAGE_DEFS.discovery.gate);
  });

  it("orders Features before UI in every UI-bearing blueprint (#825)", () => {
    for (const bp of makeBlueprints()) {
      const keys = bp.sections.map((s) => s.key);
      const ui = keys.indexOf("ui");
      if (ui < 0) continue; // headless blueprints have no UI stage
      const features = keys.indexOf("features");
      expect(features, `${bp.id}: features must precede ui`).toBeGreaterThanOrEqual(0);
      expect(features).toBeLessThan(ui);
    }
    // and the UI stage declares the features dependency that enforces it
    expect(STAGE_DEFS.ui.deps).toContain("features");
  });

  it("the Skills stage is SKIPPABLE — an opt-in stage must never trap the plan (#3905)", () => {
    // Skills sits behind the `needsSkills` opt-in AND self-enables whenever the project resolves
    // any skill (`needsSkills: !!classifyCfg?.needsSkills || projectSkillCount > 0`). Without
    // `optional` it offered no Skip, and its gate signal `skillsAck` was hardcoded false — so once
    // the stage appeared the plan could never complete and TRIAGE became unreachable.
    expect(STAGE_DEFS.skills.optional, "skills must declare optional so the footer offers Skip").toBe(true);
    // …and the flag survives the section build (`mkStage` inherits `optional ?? def.optional`).
    expect(mkStage("skills").optional).toBe(true);
    // The gate still MEANS something: it requires `skillsAck`, which is satisfied by having skills,
    // not by a stub. (A `needsSkills` project with zero skills assigned still blocks.)
    expect(STAGE_DEFS.skills.gateRule?.require?.[0]?.signal).toBe("skillsAck");
  });

  it("the ui stage teaches the data-shape layout picker (#2475, moved from test_ui #4249)", () => {
    // #4249: `test_ui` sat in NO blueprint while owning half the pipeline, so the kit query moved to
    // `ui` — where the screens are actually specced and the designer is actually commissioned.
    const def = STAGE_DEFS.ui;
    expect(def).toBeTruthy();
    // The seed teaches the flow: derive the data's shape, then query the kit's ideals via the two
    // read verbs — and treat an uncovered shape as a gap, never a forced fit.
    for (const text of [def.prompt ?? "", def.directive ?? ""]) {
      expect(text).toContain("bsc ui shapes");
      expect(text).toContain("bsc ui list --shape");
    }
    // The whole seven-shape vocabulary is named for the planner to derive against (#2475/#3517).
    for (const shape of ["list", "linked-list", "tree", "graph", "table", "key-value", "series"]) {
      expect(def.prompt ?? "", `prompt names the ${shape} shape`).toContain(shape);
    }
  });

  it("the layout stages close the schema → shape → component loop (#2478)", () => {
    // #2475 gave the planner "which component renders shape X" (`bsc ui shapes`). #2478 supplies the
    // OTHER half — "what shape IS this entity's data" — inferred from the canonical Data Model by
    // `bsc data shapes` (crates/data `shape.rs`). The stage that picks a layout must teach it, or the
    // session is back to judging the taxonomy by hand. ONE stage since #4249 — `test_ui` carried a
    // second copy of the whole loop while belonging to no blueprint.
    for (const key of ["ui"]) {
      const def = STAGE_DEFS[key];
      expect(def, `${key} stage def exists`).toBeTruthy();
      for (const text of [def.prompt ?? "", def.directive ?? ""]) {
        expect(text, `${key} teaches the schema→shape verb`).toContain("bsc data shapes");
      }
      // The inference returns RANKED candidates with reasons, never one guess — and a tie goes to
      // the user (a lone self-reference is a tree only if an item has ONE parent).
      const both = `${def.prompt ?? ""}\n${def.directive ?? ""}`.toLowerCase();
      expect(both, `${key} says the candidates are ranked`).toContain("rank");
      expect(
        both.includes("ask the user") || both.includes("put the question to the user"),
        `${key} tells the session to ask when the top candidates tie`,
      ).toBe(true);
      // The vocabulary the two CLIs share — pinned so the prose can't teach a rejected token.
      for (const shape of ["list", "linked-list", "tree", "graph", "table", "key-value"]) {
        expect(both, `${key} names the ${shape} shape`).toContain(shape);
      }
    }
  });

  it("the ui stage teaches the theme pairing + the swappable-CSS emission (#2489, moved from test_ui #4249)", () => {
    // This was the sharpest consequence of `test_ui` being orphaned: it owned the ONLY path that
    // records a project's {kit, theme} pair and emits its palette, so no generated project ever got a
    // theme. Pairing is a step inside commissioning a UI, so it lives with the commission.
    const def = STAGE_DEFS.ui;
    // Both faces of the seed teach the whole loop: enumerate themes, choose WITH the user, record
    // the {kit, theme} pair in plan.db, and emit the two-layer palette for the generated app.
    for (const text of [def.prompt ?? "", def.directive ?? ""]) {
      expect(text).toContain("bsc ui theme list");
      expect(text).toContain("bsc plan ui set");
      expect(text).toContain("bsc ui emit-css");
      expect(text).toContain("tokens.css");
      expect(text).toContain("theme.css");
      // Re-theming is the one-file swap — the payoff the stage must state.
      expect(text).toMatch(/swapping (that one file|theme\.css)/);
    }
    // The token contract layer is read-only for the build agents.
    expect(def.prompt).toMatch(/read-only for build agents/);
    expect(def.directive).toMatch(/read-only for workers/);
  });

  it("carries the MCPs stage after Streams in the Default blueprint (#878/#1003/#1914/#3785)", () => {
    expect(STAGE_DEFS.mcps).toBeTruthy();
    // #3785: mcps is now a non-optional section on the unified Default blueprint (hidden-by-default
    // via appliesWhen signals, not the `optional` flag).
    expect(STAGE_DEFS.mcps.optional).not.toBe(true);
    for (const id of ["default"]) {
      const bp = makeBlueprints().find((b) => b.id === id)!;
      const keys = bp.sections.map((s) => s.key);
      expect(keys, `${id} has an mcps stage`).toContain("mcps");
      // #1914: structure+permissions collapsed into the `streams` stage; mcps comes after it.
      expect(keys.indexOf("mcps"), `${id}: mcps after streams`).toBeGreaterThan(keys.indexOf("streams"));
    }
  });

  it("market is a discovery-toggled optional stage — right after Discovery, hidden until needsMarket (#2430/#3806)", () => {
    for (const id of ["default"]) {
      const bp = makeBlueprints().find((b) => b.id === id)!;
      const secs = bp.sections;
      const keys = secs.map((s) => s.key);
      // #3806: the Configure stage folded into Discovery, so market now follows Discovery directly.
      expect(keys.indexOf("market"), `${id}: market right after discovery`).toBe(keys.indexOf("discovery") + 1);
      // No longer the `optional` flag — market is signal-gated like source/mcp/skills/automations:
      // hidden (N/A) by default, shown only once the planner sets needsMarket during Discovery.
      const market = secs.find((s) => s.key === "market")!;
      expect(market.optional).not.toBe(true);
      expect(stageStatus(market, secs, { ...sig(), needsMarket: false }).status).toBe("na");
      expect(stageStatus(market, secs, { ...sig(), needsMarket: true }).status).not.toBe("na");
    }
  });

  it("Default is the superset greenfield route; the domain greenfields walk it (#1003/#1914/#3785/#3783)", () => {
    const bp = (id: string) => makeBlueprints().find((b) => b.id === id)!;
    const keysOf = (id: string) => bp(id).sections.map((s) => s.key);
    // #3785: Default absorbed Complete's stages — it's the greenfield superset. The unified
    // vocabulary (#1914) collapsed repos+deploy → `deployment` and structure+permissions → `streams`.
    expect(keysOf("default")).toEqual(
      ["discovery", "market", "deployment", "source", "features", "ui", "streams", "mcps", "automations", "skills"],
    );
    // The legacy collapsed keys never survive the unified vocabulary.
    for (const k of ["repos", "structure", "permissions"]) {
      expect(keysOf("default"), `default omits ${k}`).not.toContain(k);
    }
    // #3783: the built-ins are Default plus the domain blueprints.
    const builtIns = makeBlueprints().map((b) => b.id);
    expect(builtIns).toEqual(
      expect.arrayContaining(["default", "crm", "erp", "helpdesk", "hr", "project-management"]),
    );
    // Default is still the superset by keys — every domain blueprint's stages are a subset of it.
    const defaultKeys = new Set(keysOf("default"));
    for (const id of ["crm", "erp", "helpdesk", "hr", "project-management"]) {
      expect(keysOf(id).every((k) => defaultKeys.has(k)), `${id} keys ⊆ default`).toBe(true);
    }
  });

  it("classification folded into Discovery — there is no standalone Configure stage (#3806)", () => {
    // #3806: the Configure stage was removed; the planner classifies (uiMode + which optional stages
    // the project needs) as the closing step of Discovery. No blueprint carries a `configure` section,
    // and the registry has no `configure` def.
    expect(STAGE_DEFS.configure).toBeUndefined();
    for (const bp of makeBlueprints()) {
      expect(bp.sections.map((s) => s.key), `${bp.id} has no configure stage`).not.toContain("configure");
    }
  });

});

// #1854 Phase (a): a stage can carry model-variant prompts (adapt the prompt to the driving model's
// capability tier) + archetype seed content. Both are additive — absent ⇒ today's single-prompt,
// no-seed behavior.
describe("dynamic blueprints — model-variant prompts (#1854a)", () => {
  const base: Pick<SectionDef, "prompt" | "promptVariants"> = {
    prompt: "Open-ended: design the feature set with the user.",
    promptVariants: {
      local: "Tight: list EXACTLY 5 features as `- name: one-line` and nothing else.",
    },
  };

  it("returns the base prompt when no tier is given (today's behavior)", () => {
    expect(resolveStagePrompt(base)).toBe(base.prompt);
  });

  it("returns the base prompt for a tier that has no variant (direct fallback, no cascade)", () => {
    // `standard` isn't defined and `frontier`'s prompt IS the base → both fall back to `prompt`.
    expect(resolveStagePrompt(base, "standard")).toBe(base.prompt);
    expect(resolveStagePrompt(base, "frontier")).toBe(base.prompt);
  });

  it("picks the tier's variant when one is defined (the weak-local-model payoff)", () => {
    expect(resolveStagePrompt(base, "local")).toBe(base.promptVariants!.local);
  });

  it("falls back to the base prompt when the variant is empty/whitespace", () => {
    const blankLocal = { prompt: "P", promptVariants: { local: "   " } } as Pick<SectionDef, "prompt" | "promptVariants">;
    expect(resolveStagePrompt(blankLocal, "local")).toBe("P");
  });

  it("a stage with no promptVariants resolves to its base prompt for every tier", () => {
    const plain = { prompt: "just the one prompt" } as Pick<SectionDef, "prompt" | "promptVariants">;
    for (const tier of ["frontier", "standard", "local"] as const) {
      expect(resolveStagePrompt(plain, tier)).toBe("just the one prompt");
    }
  });

  it("returns '' for a missing section", () => {
    expect(resolveStagePrompt(undefined)).toBe("");
    expect(resolveStagePrompt(undefined, "local")).toBe("");
