type ConsoleSlice = Pick<AppStore,
  "activeWorkspace" | "setWorkspace" | "navigate" | "hasHydrated" | "setHasHydrated" | "tabs" | "activeTabIdx" | "paneMenuOpenIdx" | "focusedPaneIdx" | "fullscreenPaneIdx" | "consoleBroadcast" | "setConsoleBroadcast" | "focusQueue" | "focusTarget" | "setFocusTarget" | "enqueueFocus" | "removeFocus" | "clearFocusQueue" | "reconcileFocusQueue" | "advanceFocus" | "terminalFontSize" | "setTerminalFontSize" | "accent" | "setAccent" | "kitTheme" | "setKitTheme" | "soundNotifications" | "setSoundNotifications" | "ttsEnabled" | "setTtsEnabled" | "ttsRate" | "setTtsRate" | "ttsVoice" | "setTtsVoice" | "ttsVerbosity" | "setTtsVerbosity" | "keybindings" | "setKeybinding" | "resetKeybinding" | "resetAllKeybindings" | "paneViews" | "paneNames" | "paneCwds" | "paneWasClaude" | "uncleanShutdown" | "setUncleanShutdown" | "interruptedLoops" | "reapStrandedLoops" | "dismissInterruptedLoops" | "restoreRequested" | "restoreSessionsFromCrash" | "achievements" | "unlockAchievement" | "setPaneWasClaude" | "setPaneCwd" | "paneStatus" | "setPaneStatus" | "quarantinedPanes" | "markQuarantine" | "clearQuarantine" | "acknowledgeQuarantine" | "wardenSince" | "clearProjectQuarantine" | "endedPanes" | "markPaneEnded" | "clearEndedPanes" | "reopenPane" | "panePrProbes" | "setPanePrProbe" | "clearPanePrProbe" | "dormantPanes" | "paneLastActivity" | "idleReaper" | "reapPane" | "resumePane" | "resumePaneSession" | "setIdleReaperConfig" | "recomputeTabState" | "clearTabStatuses" | "paneInitCmds" | "setPaneInitCmd" | "paneStartupPromptDocs" | "paneCheckpointDocs" | "paneStartupPromptText" | "paneContinue" | "disabledPanes" | "setPaneDisabled" | "paneRoles" | "setPaneRole" | "panePersonas" | "setPanePersona" | "agentProfiles" | "setAgentProfiles" | "updateAgentProfile" | "panePermsStale" | "clearPanePermsStale" | "paneRedrawNonce" | "requestPaneRedraw" | "paneProfiles" | "paneRoleGlobs" | "paneRepos" | "paneFlows" | "paneProviders" | "setPaneProvider" | "paneWslDistro" | "paneMaintaining" | "setPaneMain