// Firing one carried schedule (#142, hooks-and-schedules-belong-to-the-persona).
//
// A schedule is carried by a PERSONA and fires into the pane that persona is running in. Every run
// is one line in the `automation` log stream — the only record of it. There is no `runs[]` on a
// record any more and no `nextRunAt` to rewrite, so the history cannot drift from the bookkeeping.
import { log } from "@/shared/lib/core/log";
import { resolvePersonaPane, type CarriedSchedule } from "@/features/automations/lib/scheduler";

export interface DispatchDeps {
  /** Which persona each pane is running — the target lookup. */
  panePersonas: Record<string, string>;
  disabledPanes: Record<string, boolean>;
  /** Write into a pane (e.g. invoke("pty_write", …); a trailing CR is added here). */
  write: (paneId: string, data: string) => Promise<void>;
  /** Append one line to the automation log. */
  recordRun: (pane: string, schedule: string, status: string, note: string) => void;
}

/**
 * Dispatch one carried schedule, recording exactly one run (ok / skipped / fail). Never throws — a
 * write failure is captured as a failed run, because a scheduler that dies on one bad job stops
 * firing every other one.
 */
export async function dispatchSchedule(s: CarriedSchedule, deps: DispatchDeps): Promise<void> {
  const key = `${s.personaId}:${s.name}`;
  const paneId = resolvePersonaPane(s.personaId, deps.panePersonas, deps.disabledPanes);
  if (!paneId) {
    // Not an error: the agent simply is not running. Recorded so a job that never fires is visible
    // as SKIPPED rather than as silence.
    deps.recordRun("", key, "skipped", `no open pane is running ${s.personaId}`);
    return;
  }
  const command = s.command.trim();
  if (!command) {
    deps.recordRun(paneId, key, "fail", "empty command");
    return;
  }
  try {
    await deps.write(paneId, command + "\r");
    deps.recordRun(paneId, key, "ok", `ran in ${paneId}`);
  } catch (e) {
    log.error(`schedule ${key} dispatch failed: ${e}`);
    deps.recordRun(paneId, key, "fail", String(e));
  }
}

