import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { isBenign } from "@/app/safety/fatalOverlay";

type Bridge = { invoke: (cmd: string, args: unknown) => Promise<unknown> };
const g = globalThis as { __TAURI_INTERNALS__?: Bridge };

/** A FRESH copy of the overlay — it latches after the first fatal, so each scenario needs its own. */
async function fresh() {
  vi.resetModules();
  return await import("@/app/safety/fatalOverlay");
}

/** Drive it through a REAL window `error` event — the path a crash actually takes.
 *
 *  Only ever asserted NEGATIVELY (nothing reported), because the listener this module installs at
 *  import cannot be removed: every fresh copy a previous test loaded is still listening, so a positive
 *  count here would be counting instances rather than behaviour. The positive assertions call `show`
 *  on the one instance under test. */
async function fireEvent(message: string) {
  await fresh();
  window.dispatchEvent(new ErrorEvent("error", { message }));
}

// Regression: the crash overlay must NOT fire on benign browser warnings — notably the
// ResizeObserver loop message the planner's resizable split panes emit on resize, which was
// surfacing as a full-screen "Uncaught error" overlay (false crash).
describe("fatalOverlay.isBenign", () => {
  it("ignores the ResizeObserver loop warnings", () => {
    expect(isBenign("ResizeObserver loop completed with undelivered notifications")).toBe(true);
    expect(isBenign("ResizeObserver loop limit exceeded")).toBe(true);
  });

  it("ignores the opaque cross-origin Script error", () => {
    expect(isBenign("Script error.")).toBe(true);
  });

  it("does NOT ignore real errors", () => {
    expect(isBenign("TypeError: Cannot read properties of undefined (reading 'x')")).toBe(false);
    expect(isBenign("")).toBe(false);
  });
});

// The overlay's durable half (the-app-starts-and-never-mounts-and-nothing-says-so).
//
// Everything the overlay knows dies with the window it painted into. Handing it to the backend is what
// turns a boot crash from a `<pre>` nobody can read afterwards into a `launch` fault carrying the real
// error — the alternative being the watchdog's message-less "the UI never mounted".
describe("fatalOverlay: handing the crash to the backend", () => {
  let prev: Bridge | undefined;
  beforeEach(() => {
    prev = g.__TAURI_INTERNALS__;
    document.querySelectorAll("[data-fatal-overlay]").forEach((n) => n.remove());
  });
  afterEach(() => {
    g.__TAURI_INTERNALS__ = prev;
    vi.restoreAllMocks();
  });

  it("reports a real crash through the bridge, with the message first and the stack alongside", async () => {
    const invoke = vi.fn().mockResolvedValue(undefined);
    g.__TAURI_INTERNALS__ = { invoke };
    const { show } = await fresh();
    show("Uncaught error", "TypeError: x is not a function\n  at boot (main.tsx:1:1)");

    expect(invoke).toHaveBeenCalledTimes(1);
    const [cmd, args] = invoke.mock.calls[0] as [string, { message: string; detail: string }];
    expect(cmd).toBe("boot_failed");
    // The title is one line — it becomes a fault title, and a multi-line one would break the TSV that
    // `bsc errors list` prints.
    expect(args.message).not.toContain("\n");
    expect(args.message).toContain("TypeError: x is not a function");
    expect(args.message).toContain("Uncaught error");
    expect(args.detail).toContain("at boot");
    // ...and it still did its own job.
    expect(document.querySelector("[data-fatal-overlay]")).toBeTruthy();
  });

  it("never reports a benign browser warning — a false fault would pin the app node red", async () => {
    const invoke = vi.fn().mockResolvedValue(undefined);
    g.__TAURI_INTERNALS__ = { invoke };
    await fireEvent("ResizeObserver loop completed with undelivered notifications");
    expect(invoke).not.toHaveBeenCalled();
    expect(document.querySelector("[data-fatal-overlay]")).toBeNull();
  });

  it("still paints when there is NO bridge — the case the overlay exists for", async () => {
    // A detached window may have no `__TAURI_INTERNALS__` at all. Reporting is a bonus; rendering the
    // crash is the mechanism, and it must not depend on the bonus succeeding.
    delete g.__TAURI_INTERNALS__;
    const { show } = await fresh();
    expect(() => show("Uncaught error", "TypeError: boom")).not.toThrow();
    expect(document.querySelector("[data-fatal-overlay]")?.textContent).toContain("TypeError: boom");
  });

  it("reports at most ONCE per window — the overlay latches, and so must the fault", async () => {
    const invoke = vi.fn().mockResolvedValue(undefined);
    g.__TAURI_INTERNALS__ = { invoke };
    const { show } = await fresh();
    show("Uncaught error", "TypeError: first");
    show("Uncaught error", "TypeError: second");
    // A crash usually cascades; a fault per cascaded error would bury the one that started it.
    expect(invoke).toHaveBeenCalledTimes(1);
    expect((invoke.mock.calls[0] as [string, { detail: string }])[1].detail).toContain("first");
  });

  it("survives a bridge that rejects — an older backend has no such command", async () => {
    const invoke = vi.fn().mockRejectedValue(new Error("unknown command boot_failed"));
    g.__TAURI_INTERNALS__ = { invoke };
    const { show } = await fresh();
    expect(() => show("Uncaught error", "TypeError: boom")).not.toThrow();
    expect(document.querySelector("[data-fatal-overlay]")).toBeTruthy();
  });
});

// Regression (`the-crash-overlay-blanks-a-running-app`): a rejection AFTER the app has mounted is
// not a boot failure. Observed in the wild as
// `Unhandled promise rejection: @user-script:8:11:75` logged as a "fatal boot error" 22 seconds
// after `render→mounted`/`hydrated→painted`, with the app then launching a full fleet — while the
// overlay covered the working UI and `boot_failed` filed a durable launch fault for a boot that
// had succeeded.
describe("fatalOverlay.handle — mount state decides", () => {
  let invoked: string[];
  beforeEach(() => {
    invoked = [];
    g.__TAURI_INTERNALS__ = { invoke: (cmd: string) => { invoked.push(cmd); return Promise.resolve(); } };
    document.body.innerHTML = "";
  });
  afterEach(() => {
    delete g.__TAURI_INTERNALS__;
    document.body.innerHTML = "";
  });

  /** The case the overlay was written for: nothing rendered, so the overlay IS the only surface. */
  it("before mount, paints the overlay and files the boot fault", async () => {
    document.body.innerHTML = `<div id="root"></div>`; // present but EMPTY — React never rendered
    const m = await fresh();
    m.handle("Uncaught error", "TypeError: boom");
    expect(document.querySelector("[data-fatal-overlay]")).not.toBeNull();
    expect(invoked).toContain("boot_failed");
  });

  /** ...and the case that made this a bug. */
  it("after mount, neither covers the UI nor claims the boot failed", async () => {
    document.body.innerHTML = `<div id="root"><main>the running app</main></div>`;
    const spy = vi.spyOn(console, "error").mockImplementation(() => {});
    const m = await fresh();
    m.handle("Unhandled promise rejection", "@user-script:8:11:75");
    expect(document.querySelector("[data-fatal-overlay]")).toBeNull();
    expect(invoked).not.toContain("boot_failed");
    expect(spy).toHaveBeenCalledWith(expect.stringContaining("@user-script:8:11:75"));
    spy.mockRestore();
  });

  /** Downgraded, never dropped — a post-mount failure still has to leave a trace. */
  it("post-mount is quieter, not silent", async () => {
    document.body.innerHTML = `<div id="root"><main>up</main></div>`;
    const spy = vi.spyOn(console, "error").mockImplementation(() => {});
    const m = await fresh();
    m.handle("Uncaught error", "Importing a module script failed.");
    expect(spy).toHaveBeenCalledWith(expect.stringContaining("post-mount"));
    spy.mockRestore();
  });

  /** A missing root is treated as pre-mount — the louder direction. Guessing "mounted" on a window
   *  with no `#root` would silence the tear-off crash this module exists for. */
  it("no root element at all counts as pre-mount", async () => {
    const m = await fresh();
    m.handle("Uncaught error", "TypeError: boom");
    expect(document.querySelector("[data-fatal-overlay]")).not.toBeNull();
  });

  /** The benign filter still applies first, in both states. */
  it("still ignores benign warnings after mount", async () => {
    document.body.innerHTML = `<div id="root"><main>up</main></div>`;
    const spy = vi.spyOn(console, "error").mockImplementation(() => {});
    const m = await fresh();
    m.handle("Uncaught error", "ResizeObserver loop limit exceeded");
    expect(spy).not.toHaveBeenCalled();
    expect(invoked).not.toContain("boot_failed");
    spy.mockRestore();
  });
});

// Tests for the runtime fault → routed fix decision core (#2265). Covers the three acceptance
// guarantees — the auto-triage GATE, DEDUP per fingerprint, and the RATE-LIMIT / fan-out cap — plus
// the resolve→clear path and severity/threshold filtering.
import { describe, it, expect } from "vitest";
import {
  planFaultDispatch,
  unresolvedCount,
  DEFAULT_FAULT_TRIAGE,
  type FaultLite,
  type FaultTriageConfig,
} from "@/shared/lib/fleet/faultTriage";

const cfg = (over: Partial<FaultTriageConfig> = {}): FaultTriageConfig => ({
  enabled: true,
  ...DEFAULT_FAULT_TRIAGE,
  ...over,
});

const fault = (fp: string, over: Partial<FaultLite> = {}): FaultLite => ({
  fingerprint: fp,
  level: "error",
  title: `fault ${fp}`,
  count: 1,
  ...over,
});

describe("planFaultDispatch — the gate", () => {
  it("dispatches nothing when auto-triage is OFF (surface-only)", () => {
    const faults = [fault("a"), fault("b", { level: "fatal" })];
    const plan = planFaultDispatch(faults, [], cfg({ enabled: false }));
    expect(plan.dispatch).toEqual([]);
    // The ledger is still pruned to open faults, but nothing is routed.
    expect(plan.nextDispatched).toEqual([]);
  });

  it("dispatches when ON", () => {
    const plan = planFaultDispatch([fault("a")], [], cfg());
    expect(plan.dispatch.map((d) => d.fingerprint)).toEqual(["a"]);
    expect(plan.nextDispatched).toEqual(["a"]);
  });
});

describe("planFaultDispatch — dedup by fingerprint", () => {
  it("routes a given fingerprint exactly once across cycles", () => {
    const faults = [fault("a")];
    const first = planFaultDispatch(faults, [], cfg());
    expect(first.dispatch).toHaveLength(1);
    // Second cycle: same open fault, already dispatched → no re-dispatch (idempotent).
    const second = planFaultDispatch(faults, first.nextDispatched, cfg());
    expect(second.dispatch).toEqual([]);
    expect(second.nextDispatched).toEqual(["a"]);
  });

  it("collapses N occurrences of one fault (a higher count) into one dispatch", () => {
    // A fault that fired 500× is still ONE fingerprint → one dispatch, never 500.
    const plan = planFaultDispatch([fault("storm", { count: 500 })], [], cfg());
    expect(plan.dispatch).toHaveLength(1);
    expect(plan.dispatch[0].count).toBe(500);
  });
});

describe("planFaultDispatch — rate-limit / fan-out cap", () => {
  it("never exceeds maxPerCycle in a single tick (a fault storm can't spawn a fleet)", () => {
    const faults = Array.from({ length: 50 }, (_, i) => fault(`f${i}`));
    const plan = planFaultDispatch(faults, [], cfg({ maxPerCycle: 2, maxInFlight: 100 }));
    expect(plan.dispatch).toHaveLength(2);
  });

  it("never exceeds maxInFlight across cycles", () => {
    const faults = Array.from({ length: 50 }, (_, i) => fault(`f${i}`));
    const c = cfg({ maxPerCycle: 2, maxInFlight: 3 });
    // Cycle 1: 2 dispatched (per-cycle cap).
    const c1 = planFaultDispatch(faults, [], c);
    expect(c1.dispatch).toHaveLength(2);
    // Cycle 2: 2 in-flight, cap 3 → only 1 slot left despite the per-cycle cap of 2.
    const c2 = planFaultDispatch(faults, c1.nextDispatched, c);
    expect(c2.dispatch).toHaveLength(1);
    expect(c2.nextDispatched).toHaveLength(3);
    // Cycle 3: at the cap → nothing.
    const c3 = planFaultDispatch(faults, c2.nextDispatched, c);
    expect(c3.dispatch).toEqual([]);
    expect(c3.nextDispatched).toHaveLength(3);
  });

  it("routes the worst faults first when slots are scarce (severity, then volume)", () => {
    const faults = [
      fault("warnish", { level: "warn", count: 99 }),
      fault("small", { level: "error", count: 1 }),
      fault("big", { level: "error", count: 40 }),
      fault("fatal", { level: "fatal", count: 1 }),
    ];
    const plan = planFaultDispatch(faults, [], cfg({ maxPerCycle: 2, minLevel: "warn" }));
    // fatal wins, then the higher-volume error.
    expect(plan.dispatch.map((d) => d.fingerprint)).toEqual(["fatal", "big"]);
  });
});

describe("planFaultDispatch — severity + threshold filters", () => {
  it("skips faults below minLevel", () => {
    const plan = planFaultDispatch([fault("w", { level: "warn" })], [], cfg({ minLevel: "error" }));
    expect(plan.dispatch).toEqual([]);
  });

  it("skips faults below the count threshold", () => {
    const faults = [fault("rare", { count: 1 }), fault("common", { count: 5 })];
    const plan = planFaultDispatch(faults, [], cfg({ threshold: 3 }));
    expect(plan.dispatch.map((d) => d.fingerprint)).toEqual(["common"]);
  });
});

describe("planFaultDispatch — resolve → clear path", () => {
  it("drops a resolved fault from the ledger, freeing its fan-out slot", () => {
    const c = cfg({ maxInFlight: 1, maxPerCycle: 1 });
    // Cycle 1: dispatch "a"; now at the fan-out cap.
    const c1 = planFaultDispatch([fault("a")], [], c);
    expect(c1.dispatch).toHaveLength(1);
    // "b" appears but "a" is still open (in-flight) → capped, no dispatch.
    const c2 = planFaultDispatch([fault("a"), fault("b")], c1.nextDispatched, c);
    expect(c2.dispatch).toEqual([]);
    // "a" is resolved (the fix landed → `bsc errors resolve`), so it drops from the unresolved list.
    // The slot frees and "b" dispatches; "a" is pruned from the ledger.
    const c3 = planFaultDispatch([fault("b")], c2.nextDispatched, c);
    expect(c3.dispatch.map((d) => d.fingerprint)).toEqual(["b"]);
    expect(c3.nextDispatched).toEqual(["b"]);
  });

  it("re-dispatches a fault that recurs after being resolved", () => {
    // Dispatch, resolve (drops from unresolved list), then it recurs (errordb re-opens the fingerprint).
    const c1 = planFaultDispatch([fault("flaky")], [], cfg());
    expect(c1.dispatch).toHaveLength(1);
    // Resolved → not in the unresolved list this cycle → pruned from the ledger.
    const c2 = planFaultDispatch([], c1.nextDispatched, cfg());
    expect(c2.nextDispatched).toEqual([]);
    // Recurrence: the same fingerprint is open again and no longer tracked → re-dispatched.
    const c3 = planFaultDispatch([fault("flaky")], c2.nextDispatched, cfg());
    expect(c3.dispatch.map((d) => d.fingerprint)).toEqual(["flaky"]);
  });

  it("prunes the ledger even when the gate is off", () => {
    // Toggle off but a previously-tracked fault resolved → still pruned, so a later toggle-on is clean.
    const plan = planFaultDispatch([], ["gone"], cfg({ enabled: false }));
    expect(plan.nextDispatched).toEqual([]);
  });
});

describe("unresolvedCount", () => {
  it("counts only unresolved faults", () => {
    expect(unresolvedCount([fault("a"), fault("b", { resolvedAt: 123 }), fault("c")])).toBe(2);
  });

  // The "builds a director prompt" case went with `faultDispatchPrompt`
  // (#coord-prefix-names-the-sender) — nothing injected it. The CLASSIFICATION above still runs and
  // is still tested; only the prose the app used to type at a director is gone.
});

// The fault-triage decision, captured from the LIVE TypeScript so the Rust port can be proved equal.
//
// `fault-triage.ts` turns a project's unresolved runtime faults into a bounded, deduped set of fix
// dispatches. Three guarantees ride on it, each a real failure mode: the GATE (auto-triage off means
// dispatch nothing), DEDUP (never dispatch the same fingerprint twice while it stays open), and the
// RATE-LIMIT (a fault storm must not become a worker storm). The faults live in error.db, which Rust
// owns; only the decision is in the renderer.
//
// Regenerate deliberately:
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/fleet/faultTriage.fixtures.gen.test.ts
//
// A regeneration that changes the file is a CHANGE OF BEHAVIOUR. Read the diff before committing it.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  planFaultDispatch,
  unresolvedCount,
  worstFault,
  DEFAULT_FAULT_TRIAGE,
  type FaultLite,
  type FaultTriageConfig,
} from "@/shared/lib/fleet/faultTriage";

const FIXTURE = join(process.cwd(), "src/shared/lib/fleet/faultTriage.fixtures.json");

const cfg = (o: Partial<FaultTriageConfig> = {}): FaultTriageConfig =>
  ({ enabled: true, ...DEFAULT_FAULT_TRIAGE, ...o });

const f = (
  fingerprint: string,
  level: FaultLite["level"],
  count: number,
  resolvedAt: number | null = null,
): FaultLite => ({ fingerprint, level, title: `${fingerprint} title`, count, resolvedAt });

interface Case { name: string; faults: FaultLite[]; dispatched: string[]; cfg: FaultTriageConfig }

/** Each case names the guarantee or branch it exists to pin. */
const CASES: Case[] = [
  { name: "nothing open", faults: [], dispatched: [], cfg: cfg() },
  {
    name: "GATE off — surface only, dispatch nothing",
    faults: [f("aa", "fatal", 9)], dispatched: [], cfg: cfg({ enabled: false }),
  },
  {
    name: "GATE off still PRUNES a resolved fingerprint",
    faults: [f("aa", "fatal", 9, 1000)], dispatched: ["aa"], cfg: cfg({ enabled: false }),
  },
  {
    name: "DEDUP — an already-dispatched open fault is not dispatched again",
    faults: [f("aa", "error", 3)], dispatched: ["aa"], cfg: cfg(),
  },
  {
    name: "a dispatched fingerprint that RESOLVED is pruned from in-flight",
    faults: [f("aa", "error", 3, 1000), f("bb", "error", 3)], dispatched: ["aa"], cfg: cfg(),
  },
  {
    name: "RATE-LIMIT — maxPerCycle caps one cycle",
    faults: [f("aa", "fatal", 9), f("bb", "fatal", 8), f("cc", "fatal", 7)],
    dispatched: [], cfg: cfg({ maxPerCycle: 2, maxInFlight: 10 }),
  },
  {
    // NOT a rate-limit case, despite where it sits: `zz-gone` names no OPEN fault, so it is pruned
    // from in-flight and the slots it was occupying come back. Named for what it actually pins.
    name: "a dispatched fingerprint that is no longer open is pruned, freeing its slot",
    faults: [f("aa", "fatal", 9), f("bb", "fatal", 8), f("cc", "fatal", 7)],
    dispatched: ["zz-gone"], cfg: cfg({ maxInFlight: 2, maxPerCycle: 5 }),
  },
  {
    // The real one: the in-flight fingerprint IS open, so it holds its slot and only one remains.
    name: "RATE-LIMIT — one genuinely in-flight fault leaves exactly one slot",
    faults: [f("held", "error", 1), f("aa", "fatal", 9), f("bb", "fatal", 8)],
    dispatched: ["held"], cfg: cfg({ maxInFlight: 2, maxPerCycle: 5 }),
  },
  {
    name: "RATE-LIMIT — no slots at all dispatches nothing",
    faults: [f("aa", "fatal", 9), f("in1", "error", 1), f("in2", "error", 1)],
    dispatched: ["in1", "in2"], cfg: cfg({ maxInFlight: 2, maxPerCycle: 5 }),
  },
  {
    name: "minLevel excludes a warn",
    faults: [f("aa", "warn", 99), f("bb", "error", 1)], dispatched: [], cfg: cfg({ minLevel: "error" }),
  },
  {
    name: "threshold excludes a low-count fault",
    faults: [f("aa", "error", 1), f("bb", "error", 5)], dispatched: [], cfg: cfg({ threshold: 3 }),
  },
  {
    name: "ORDER — level outranks count",
    faults: [f("aa", "error", 100), f("bb", "fatal", 1)], dispatched: [], cfg: cfg({ maxPerCycle: 1 }),
  },
  {
    name: "ORDER — equal level falls back to count",
    faults: [f("aa", "error", 2), f("bb", "error", 7)], dispatched: [], cfg: cfg({ maxPerCycle: 1 }),
  },
  {
    name: "ORDER — equal level and count falls back to fingerprint",
    faults: [f("zz", "error", 4), f("aa", "error", 4)], dispatched: [], cfg: cfg({ maxPerCycle: 1 }),
  },
  {
    name: "a resolved fault is never a candidate",
    faults: [f("aa", "fatal", 9, 1234), f("bb", "error", 2)], dispatched: [], cfg: cfg(),
  },
];

function build() {
  return {
    note: "GENERATED from the live TypeScript — see faultTriage.fixtures.gen.test.ts",
    defaults: DEFAULT_FAULT_TRIAGE,
    cases: CASES.map((c) => ({
      ...c,
      plan: planFaultDispatch(c.faults, c.dispatched, c.cfg),
      unresolvedCount: unresolvedCount(c.faults),
      worstFault: worstFault(c.faults),
    })),
  };
}

describe("the fault-triage decision is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const text = JSON.stringify(build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("exercises each guarantee, so a port cannot pass on the easy cases alone", () => {
    const b = build();
    expect(b.cases.some((c) => !c.cfg.enabled && c.plan.dispatch.length === 0)).toBe(true);
    expect(b.cases.some((c) => c.dispatched.length > 0 && c.plan.dispatch.length === 0)).toBe(true);
    expect(b.cases.some((c) => c.faults.length > c.plan.dispatch.length && c.plan.dispatch.length > 0)).toBe(true);
    expect(b.cases.some((c) => c.worstFault !== null)).toBe(true);
  });
});

