// #4103 — the completion gates read GitHub as evidence, not just plan.db.
import { describe, it, expect, vi, beforeEach } from "vitest";

const graphql = vi.fn();
vi.mock("@/shared/lib/github/github", () => ({ githubGraphql: (...a: unknown[]) => graphql(...a) }));

const { resolveClosedRefs } = await import("@/features/glance/lib/fleetIssueState");
const { planResumeLaunch } = await import("@/features/glance/lib/resumeProject");

const stream = (id: string, issues: string[]) =>
  ({ id, name: id, repo: "kev/app", owns: [], issues, dependsOn: [] });

beforeEach(() => graphql.mockReset());

describe("resolveClosedRefs", () => {
  it("returns each stream's OWN ref spelling, not the normalized number", async () => {
    // THE TRAP. `streamComplete` asks `stream.issues.every((r) => done.has(r))`, and a stream stores
    // "#3898" while GitHub returns the number 3898. A set of normalized refs matches NOTHING, so every
    // stream reads unfinished — the same silent failure #4103 is about, reintroduced from the other side.
    graphql.mockResolvedValue({ r0: { i3898: { number: 3898, state: "CLOSED" } } });
    const out = await resolveClosedRefs([stream("api", ["#3898"])]);
    expect(out.has("#3898")).toBe(true);
    expect(out.has("3898")).toBe(false);
  });

  it("omits an issue that is still open", async () => {
    graphql.mockResolvedValue({ r0: { i1: { number: 1, state: "OPEN" }, i2: { number: 2, state: "CLOSED" } } });
    expect([...await resolveClosedRefs([stream("api", ["#1", "#2"])])]).toEqual(["#2"]);
  });

  it("spends NO request when nothing is addressable", async () => {
    await resolveClosedRefs([{ repo: "", issues: [] }]);
    expect(graphql).not.toHaveBeenCalled();
  });

  it("a response it cannot parse yields NO closed refs", async () => {
    // The fail-closed direction: absent or unreadable evidence must under-report completion. Over-
    // reporting would skip a worker that still has work — the one outcome worse than re-launching one
    // that is finished. (The thrown-error path returns the same empty set; it is not asserted here
    // because a mock that throws trips vitest's own result tracking, not this code.)
    graphql.mockResolvedValue({ r0: null });
    expect((await resolveClosedRefs([stream("api", ["#1"])])).size).toBe(0);
  });

  it("an unreachable GitHub leaves every stream ACTIVE, never complete", async () => {
    // What the failure actually has to guarantee, asserted through the gate that consumes it.
    const { maintenanceIds } = planResumeLaunch(
      { streams: [stream("api", ["#1"])], director: { enabled: false } } as never,
      [],
      new Set(),                      // what a failed resolve returns
    );
    expect(maintenanceIds.size).toBe(0);
  });
});

describe("planResumeLaunch with GitHub evidence (#4103)", () => {
  const fleet = {
    streams: [stream("api", ["#1", "#2"]), stream("web", ["#3"])],
    director: { enabled: false },
  } as never;

  it("THE BUG: with no plan.db rows, nothing was ever complete", () => {
    // Measured on the live store: 40 streams, 0 issue rows. `doneIssueRefs([])` is empty, so
    // `streamComplete` was false for every stream — a relaunch restarted finished workers and
    // maintenance mode (#1957) never engaged.
    const { maintenanceIds } = planResumeLaunch(fleet, []);
    expect(maintenanceIds.size).toBe(0);
  });

  it("the same fleet prunes correctly once GitHub supplies the evidence", () => {
    const { maintenanceIds } = planResumeLaunch(fleet, [], new Set(["#1", "#2"]));
    expect([...maintenanceIds]).toEqual(["api"]);   // every owned ref closed ⇒ maintenance
  });

  it("unions the two sources — either one calling a ref done makes it done", () => {
    // plan.db knows only what a planner run authored; GitHub only what a token could reach. Neither is
    // complete alone, so a stream finished half by each must still prune.
    const { maintenanceIds } = planResumeLaunch(
      fleet,
      [{ ref: "#1", stream: "api", status: "complete" }],
      new Set(["#2"]),
    );
    expect([...maintenanceIds]).toEqual(["api"]);
  });

  it("a partially-finished stream stays ACTIVE", () => {
    const { maintenanceIds } = planResumeLaunch(fleet, [], new Set(["#1"]));
    expect(maintenanceIds.size).toBe(0);
  });
});

implementations.code:
// Live Fleet data (#412) — PURE mappers from the running app state to the Fleet
// board shapes. The roster comes from the store's launched fleet
// (`fleetPaneStreams`), run/idle from the live `paneStatus` map (#412), and
// blocked/asking/waiting from the coordination log (CoordState). No fabrication —
// GitHub-derived analytics (throughput, merge queue, time-to-land) and token/cost
// accounting are deferred to follow-ups and rendered as explicit "not wired" states.
//
// Framework-free + unit-tested; the store/coord wiring lives in hooks/useFleetLive.

import { hashString } from "@/shared/lib/core/format";
import { resolveByPrecedence, type PrecedenceRule } from "@/shared/lib/algorithms/precedenceResolve";
import type { CoordState } from "@/shared/lib/fleet/coordination";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import type { WorkerStatus } from "@/shared/data/fleet";

/** Minimal AgentProfile fields we need for labels/colors (avoids a hard dep). */
export interface ProfileLike { id: string; name: string }

export interface LiveWorker {
  /** pane id, e.g. "t2p0" — the coordination `session` key too. */
  id: string;
  /** display name (the stream name). */
  name: string;
  /** stream/worktree repo. */
  repo: string;
  /** resolved profile label + a stable color. */
  profileLabel: string;
  profileColor: string;
  status: WorkerStatus;
  /** the work item it's on (first owned issue, else the stream name). */
  issue: string;
  /** a short sub-note: the block dep / question / wait reason, when parked. */
  note: string;
  /** count of issues this stream owns. */
  ownedTotal: number;
}

/** Stable color from a string (profile id), matching the loginColor convention. */
function hashColor(s: string): string {
  return `oklch(0.72 0.13 ${hashString(s) % 360})`;
}

/**
 * The live status for a worker pane: coordination wins (a parked worker is
 * asking / waiting / blocked), otherwise the raw run/idle from `paneStatus`
 * ("run" → running, anything else → idle).
 *
 * The precedence is DATA (#3465) — the `PRECEDENCE` table below, resolved by the generic
 * `resolveByPrecedence`. As a chain of `if` returns the ordering existed only in statement order:
 * unreadable as a whole, untestable on its own, and reorderable by accident. The order itself is the
 * decision worth being explicit about — a worker that needs a human must never be hidden behind a
 * mechanical "running", which is why the coordination states sit above the run sample.
 */
const PRECEDENCE: PrecedenceRule<{ paneId: string; coord: CoordState; paneStatus: Record<string, "run" | "on" | "idle"> }, WorkerStatus>[] = [
  { state: "asking", when: ({ paneId, coord }) => coord.asking.some(a => a.session === paneId) },
  { state: "waiting", when: ({ paneId, coord }) => coord.waiting.some(w => w.session === paneId) },
  { state: "blocked", when: ({ paneId, coord }) => coord.waiters.some(w => w.session === paneId) },
  // Active work wins over a parked state (a dispatched maintenance worker is running, not parked).
  { state: "running", when: ({ paneId, paneStatus }) => paneStatus[paneId] === "run" },
  // A finished worker parked in maintenance (#1957) reads `maintenance`, not plain idle.
  { state: "maintenance", when: ({ paneId, coord }) => coord.maintaining.some(m => m.session === paneId) },
];

export function statusForPane(
  paneId: string, coord: CoordState, paneStatus: Record<string, "run" | "on" | "idle">,
): WorkerStatus {
  return resolveByPrecedence({ paneId, coord, paneStatus }, PRECEDENCE, "idle");
}

/** The parked-state note for a pane (question / wait reason / block deps), or "". */
function noteForPane(paneId: string, coord: CoordState): string {
  const ask = coord.asking.find(a => a.session === paneId);
  if (ask) return ask.question;
  const wait = coord.waiting.find(w => w.session === paneId);
  if (wait) return wait.reason;
  const blocked = coord.waiters.find(w => w.session === paneId);
  if (blocked) {
    const deps = blocked.deps.map(d => (d.kind === "issue" ? `#${d.number}` : d.kind === "contract" ? `contract:${d.name}` : d.kind)).join(", ");
    return deps ? `blocked on ${deps}` : "blocked";
  }
  const maint = coord.maintaining.find(m => m.session === paneId);
  if (maint) return maint.note || "owned issues complete — standing by";
  return "";
}

export interface BuildWorkersInput {
  /** the launched fleet: pane id → its stream, keyed by the #1176 IDENTITY id (`<key>:<stream>`). */
  fleetPaneStreams: Record<string, AgentStream>;
  paneStatus: Record<string, "run" | "on" | "idle">;
  coord: CoordState;
  /** The open tabs (with their minted `paneIds`), so a worker whose tab was closed is dropped. */
  tabs: { paneIds?: string[] }[];
  disabledPanes: Record<string, boolean>;
  profiles: ProfileLike[];
}

/** Build the live worker roster from the running fleet. Only panes whose tab is
 *  still open and not disabled are included (a launched-then-closed fleet drops). */
export function buildLiveWorkers(input: BuildWorkersInput): LiveWorker[] {
  const { fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles } = input;
  const profById = new Map(profiles.map(p => [p.id, p]));
  // A worker is live only while its pane is still one of an OPEN tab's minted cells (#1176): the
  // fleet/triage launch records each pane's IDENTITY id (`<key>:<stream>`) on the tab's `paneIds`, so
  // a closed tab drops its workers. (The old positional `tabOfPane` parse matched only `t<idx>p<idx>`
  // and so silently dropped EVERY identity-keyed pane — the "No fleet running" bug.)
  const livePaneIds = new Set(tabs.flatMap(t => t.paneIds ?? []));
  const workers: LiveWorker[] = [];
  for (const [paneId, stream] of Object.entries(fleetPaneStreams)) {
    if (!livePaneIds.has(paneId) || disabledPanes[paneId]) continue;
    const prof = stream.profile ? profById.get(stream.profile) : undefined;
    workers.push({
      id: paneId,
      name: stream.name,
      repo: stream.repo,
      profileLabel: prof?.name ?? stream.profile ?? "—",
      profileColor: stream.profile ? hashColor(stream.profile) : "var(--fg-dim)",
      status: statusForPane(paneId, coord, paneStatus),
      issue: stream.issues[0] ?? stream.name,
      note: noteForPane(paneId, coord),
      ownedTotal: stream.issues.length,
    });
  }
  // Stable order: by tab/pane id.
  return workers.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
}

/** Worker counts per status (drives the donut). */
export function statusCounts(workers: LiveWorker[]): Partial<Record<WorkerStatus, number>> {
  const c: Partial<Record<WorkerStatus, number>> = {};
  for (const w of workers) c[w.status] = (c[w.status] ?? 0) + 1;
  return c;
}

export interface FleetKpis {
  total: number;
  active: number;       // running
  needAttention: number; // blocked | asking | waiting
  idle: number;
  maintenance: number;  // parked & ready — finished every owned issue, standing by (#1957)
}
export function deriveFleetKpis(workers: LiveWorker[]): FleetKpis {
  const is = (s: WorkerStatus) => workers.filter(w => w.status === s).length;
  return {
    total: workers.length,
    active: is("running"),
    needAttention: is("blocked") + is("asking") + is("waiting"),
    idle: is("idle"),
    maintenance: is("maintenance"),
  };
}

// Per-worker issue progress, derived from the FLEET PLAN (#4102).
//
// ── WHY THIS EXISTS ALONGSIDE `streamProgress.ts` ────────────────────────────────────────────────
// #4050 derived progress entirely from plan.db's `issues` table: it partitioned `bsc plan list` by
// each issue's `stream` field. That is correct wherever those rows exist — and invisible wherever they
// do not. Measured on the live store (`plans/studio-code.db`): 40 `fleet_streams`, 40 `features`, and
// ZERO `issues`. So every stream got `total: 0`, and `GlanceNode`'s (correct) `total > 0` guard hid a
// bar it had no data for. The bars had simply never had an input.
//
// Ownership was not missing, only stored elsewhere: a stream carries its own work as GitHub refs in
// `AgentStream.issues` (`["#3898","#3979"]`) — 60 refs across 24 of the 40 streams. That is the
// authoritative ownership record, it is already in memory via the fleet plan, and it needs no network.
//
// ── THE SPLIT: OWNERSHIP IS LOCAL, DONE-NESS IS EVIDENCE ─────────────────────────────────────────
// So `total` comes from the plan (always available, always right) and `done` comes from whatever
// evidence exists that a ref is finished — plan.db statuses where rows were authored, GitHub
// open/closed otherwise. Unioning them means a project with a populated plan.db keeps working exactly
// as it did under #4050, while one without it stops rendering a permanently empty graph.
//
// Keeping `total` off plan.db is the actual fix. A denominator that silently drops to zero does not
// look broken — it looks like a fleet that owns no work.

import type { StreamProgress } from "@/features/glance/lib/streamProgress";

/** The minimum shape this needs from a fleet stream — kept structural so the pure fn does not drag in
 *  the whole `AgentStream` (and so tests can state a stream in one line). */
export interface OwningStream {
  id: string;
  /** Issue refs this stream owns, e.g. `["#3898"]`. */
  issues: readonly string[];
}

/** Normalise a ref for comparison: `#3898`, `3898` and ` #3898 ` are the same issue.
 *
 *  Worth doing rather than trusting equality — the refs come from three places (the plan's stored
 *  strings, plan.db's `ref` column, GitHub's numeric `number`) and a formatting mismatch between any
 *  two would show as a bar stuck at 0/N, which is exactly the failure this file exists to end. */
export function normalizeRef(ref: string | number): string {
  return String(ref).trim().replace(/^#/, "");
}

/**
 * Every alias a plan.db issue answers to, so a stream's ref can be matched against ITS OWN namespace.
 *
 * `glance-progress-ref-namespace-split`. A stream's `issues` and plan.db's `ref` column are two separate
 * ownership records, and they do not always speak the same language. Measured across the two live
 * projects:
 *
 *   base-studio-code   22 stream refs, ALL 22 are plan.db slugs   -> 22/22 resolve
 *   studio-code        56 stream refs, ALL bare GitHub numbers    -> 0/56 resolve (plan.db is slugs,
 *                                                                    and carries no gh_number at all)
 *
 * A slug that carries its origin number (`4260-sandbox-by-default-…`) therefore also answers to `4260`,
 * which is the one join available without a schema change — `bsc plan list --full` does not project
 * `gh_number`, so the number embedded in the ref is the only GitHub identity reachable from here.
 */
export function knownRefAliases(issues: readonly { ref: string }[]): Set<string> {
  const out = new Set<string>();
  for (const i of issues) {
    const ref = normalizeRef(i.ref ?? "");
    if (!ref) continue;
    out.add(ref);
    const lead = /^(\d+)-/.exec(ref);
    if (lead) out.add(lead[1]);
  }
  return out;
}

/**
 * Per-stream `done / total` for a fleet.
 *
 * `total` is what the stream OWNS. `done` counts its refs present in `doneRefs` — so a ref that is
 * done but owned by nobody cannot inflate anyone's progress, and a stream owning nothing yields
 * `total: 0`, which the node renders as NO bar (deliberately: an empty bar and a zero-progress bar
 * say different things, and only one of them is true).
 *
 * Pure. `doneRefs` may hold refs in either form; both sides are normalised.
 */
export function fleetPlanProgress(
  streams: readonly OwningStream[],
  doneRefs: ReadonlySet<string>,
  /** When set, ALSO emit this node id carrying the union of EVERY stream's refs (#4122).
   *
   *  The director is not a stream — it owns no lane — so a per-stream map leaves its node with no
   *  progress at all. But it is the one agent responsible for the whole board, so its bar is the
   *  project's: every issue any worker owns, de-duplicated, because two streams naming one ref is one
   *  piece of work and double-counting would make the director's denominator disagree with the sum of
   *  its workers'. */
  aggregateId?: string,
  /** The refs plan.db actually knows ({@link knownRefAliases}). When given, a stream whose refs are ALL
   *  unknown emits NO entry, so `mergeStreamProgress` lets plan.db answer instead.
   *
   *  `glance-progress-ref-namespace-split`: without this, a ref path that can never resolve still won,
   *  because winning only required `total > 0`. On `studio-code` every one of the 56 stream refs is a
   *  GitHub number this plan.db has no row for, so all 24 owning streams rendered `0/N` — and
   *  `design-studio`, which plan.db knows to be 8/8 DONE, rendered `0/15`. A denominator with no
   *  reachable numerator is not evidence; it is the absence of evidence wearing evidence's clothes.
   *
   *  Omitted ⇒ every stream emits, exactly as before (the pre-existing callers and tests are unchanged). */
  knownRefs?: ReadonlySet<string>,
): Map<string, StreamProgress> {
  const done = new Set<string>();
  for (const r of doneRefs) done.add(normalizeRef(r));
  const resolves = (r: string) => !knownRefs || knownRefs.has(r);

  const out = new Map<string, StreamProgress>();
  for (const s of streams) {
    // De-duplicate within a stream: a ref listed twice would push `done` past `total` and render a bar
    // over 100%. `progressFraction` clamps the fill, but the "3/2" label beside it would still be wrong.
    const refs = new Set(s.issues.map(normalizeRef));
    // Only a stream that owns refs AND resolves NONE of them stands aside. A stream owning NOTHING must
    // still emit `{0,0}` — that is the documented contract (`mergeStreamProgress` reads `total === 0` as
    // "owns no refs, let plan.db answer", and the node renders no bar). Skipping it here instead made
    // `fleetPlanProgress`'s own tests fail on `expected undefined`, which is the distinction: "owns
    // nothing" and "owns things I cannot resolve" reach the same UI, but only one of them is a fact
    // about the stream rather than about my ability to look it up.
    if (refs.size > 0 && ![...refs].some(resolves)) continue;
    let d = 0;
    for (const r of refs) if (done.has(r)) d += 1;
    out.set(s.id, { done: d, total: refs.size });
  }

  if (aggregateId) {
    // Union across streams, then count — NOT a sum of the per-stream rows, which would double-count a
    // ref two streams both claim.
    const all = new Set<string>();
    for (const s of streams) for (const r of s.issues) all.add(normalizeRef(r));
    // Same rule as a stream: an aggregate over refs that resolve to nothing is the director's `0/56`.
    if ([...all].some(resolves)) {
      let d = 0;
      for (const r of all) if (done.has(r)) d += 1;
      out.set(aggregateId, { done: d, total: all.size });
    }
  }
  return out;
}

/**
 * Combine the ref-derived progress with plan.db's own, per stream.
 *
 * A stream that owns refs uses the ref-derived numbers — that is the fix, and its denominator cannot
 * silently collapse to zero. A stream that owns NONE falls back to plan.db's entry, which preserves
 * #4050 exactly where it already worked: a project whose planner run authored issue rows carrying a
 * `stream` field, but whose stream records never listed the refs, still shows the bar it showed before.
 *
 * Neither source is dropped, so this cannot regress a project that was working.
 */
export function mergeStreamProgress(
  fromRefs: ReadonlyMap<string, StreamProgress>,
  fromPlanDb: ReadonlyMap<string, StreamProgress>,
): Map<string, StreamProgress> {
  const out = new Map<string, StreamProgress>(fromPlanDb);
  for (const [id, p] of fromRefs) {
    // `total === 0` means "owns no refs", which is not evidence of anything — let plan.db answer.
    if (p.total > 0) out.set(id, p);
  }
  return out;
}

/**
 * Union the done-evidence sources into the set `fleetPlanProgress` consumes.
 *
 * Both are partial and neither is authoritative alone: plan.db knows only what a planner run authored
 * (nothing, for a hand-assembled fleet), and GitHub knows only what a token could reach (nothing, when
 * disconnected). A ref that either source calls finished IS finished — treating one as authoritative
 * would make progress vanish the moment that source is the empty one, which is the bug being fixed.
 */
export function unionDone(...sources: ReadonlyArray<Iterable<string> | undefined>): Set<string> {
  const out = new Set<string>();
  for (const src of sources) {
    if (!src) continue;
    for (const r of src) out.add(normalizeRef(r));
  }
  return out;
}

