import { describe, it, expect } from "vitest";
import {
  enqueue, removeFromQueue, nextInCycle, reconcileQueue,
  shouldFocus, FOCUS_TARGETS, DEFAULT_FOCUS_TARGET, focusTargetLabel,
  AUTO_FOCUS_MODES, DEFAULT_AUTO_FOCUS_MODE, autoFocusModeLabel,
  type QueuedPane,
} from "@/app/console/lib/focusQueue";

const p = (tab: number, pane: number): QueuedPane => ({ tab, pane });

describe("enqueue", () => {
  it("appends a new pane in FIFO order", () => {
    expect(enqueue([p(0, 1), p(0, 2)], p(0, 3))).toEqual([p(0, 1), p(0, 2), p(0, 3)]);
  });

  it("de-duplicates an already-queued pane (same reference)", () => {
    const q = [p(0, 1), p(0, 2)];
    expect(enqueue(q, p(0, 2))).toBe(q);
  });

  it("treats the same pane index on different tabs as distinct", () => {
    expect(enqueue([p(0, 2)], p(1, 2))).toEqual([p(0, 2), p(1, 2)]);
  });

  it("ignores negative pane indices", () => {
    const q = [p(0, 1)];
    expect(enqueue(q, p(0, -1))).toBe(q);
  });
});

describe("removeFromQueue", () => {
  it("removes a queued pane", () => {
    expect(removeFromQueue([p(0, 1), p(0, 2), p(0, 3)], p(0, 2))).toEqual([p(0, 1), p(0, 3)]);
  });

  it("is a no-op (same reference) for an absent pane", () => {
    const q = [p(0, 1), p(0, 2)];
    expect(removeFromQueue(q, p(0, 9))).toBe(q);
    expect(removeFromQueue(q, p(1, 1))).toBe(q); // same index, different tab
  });
});

describe("nextInCycle", () => {
  it("moves to the next waiting pane after the current one", () => {
    expect(nextInCycle([p(0, 5), p(0, 6), p(0, 7)], p(0, 5))).toEqual(p(0, 6));
  });

  it("wraps around to the front", () => {
    expect(nextInCycle([p(0, 5), p(0, 6), p(0, 7)], p(0, 7))).toEqual(p(0, 5));
  });

  it("returns a waiting pane on another tab", () => {
    expect(nextInCycle([p(0, 5), p(1, 2)], p(0, 5))).toEqual(p(1, 2));
  });

  it("starts at the front when the current pane isn't queued", () => {
    expect(nextInCycle([p(0, 5), p(0, 6), p(0, 7)], p(0, 9))).toEqual(p(0, 5));
  });

  it("returns null when the only queued pane is the current one", () => {
    expect(nextInCycle([p(0, 5)], p(0, 5))).toBeNull();
  });

  it("returns null for an empty queue", () => {
    expect(nextInCycle([], p(0, 3))).toBeNull();
  });
});

describe("reconcileQueue", () => {
  // After #187 every tab is mounted, so the caller can pass live waiting sets
  // for ALL tabs in one go. Callers from #77 wire this up so background-tab
  // panes get pruned the same way active-tab panes do.
  const w = (entries: Record<number, number[]>): Map<number, Set<number>> =>
    new Map(Object.entries(entries).map(([t, panes]) => [Number(t), new Set(panes)]));

  it("drops a tab's panes that are no longer waiting", () => {
    expect(reconcileQueue([p(0, 1), p(0, 2), p(0, 3)], w({ 0: [1, 3] })))
      .toEqual([p(0, 1), p(0, 3)]);
  });

  it("prunes across multiple tabs in one sweep", () => {
    // p(0,3) no longer idle on tab 0; p(1,5) no longer idle on tab 1 — both go.
    const q = [p(0, 1), p(1, 5), p(0, 3), p(1, 2)];
    expect(reconcileQueue(q, w({ 0: [1], 1: [2] }))).toEqual([p(0, 1), p(1, 2)]);
  });

  it("returns the same reference when nothing is pruned", () => {
    const q = [p(0, 1), p(0, 2)];
    expect(reconcileQueue(q, w({ 0: [1, 2] }))).toBe(q);
  });

  it("empties when nothing on a single-tab queue is waiting", () => {
    expect(reconcileQueue([p(0, 1), p(0, 2)], w({ 0: [] }))).toEqual([]);
  });

  it("leaves tabs absent from the map alone (no live data → no assumption)", () => {
    // Tab 1 not in the map → its entries survive even if the caller has no
    // status info for them. Defensive against transient empty-state moments.
    const q = [p(0, 1), p(1, 2)];
    expect(reconcileQueue(q, w({ 0: [1] }))).toEqual([p(0, 1), p(1, 2)]);
  });
});

describe("shouldFocus (role-aware focus targeting #392)", () => {
  it("default target is director", () => {
    expect(DEFAULT_FOCUS_TARGET).toBe("director");
  });

  it("a plain console (no role) always queues except under 'none'", () => {
    for (const t of FOCUS_TARGETS) {
      expect(shouldFocus(undefined, t)).toBe(t !== "none");
      expect(shouldFocus("", t)).toBe(t !== "none");
    }
  });

  it("'none' queues nothing — not even the director or a console", () => {
    expect(shouldFocus("director", "none")).toBe(false);
    expect(shouldFocus("worker", "none")).toBe(false);
    expect(shouldFocus(undefined, "none")).toBe(false);
  });

  it("'director' queues only director panes (workers run dark)", () => {
    expect(shouldFocus("director", "director")).toBe(true);
    expect(shouldFocus("worker", "director")).toBe(false);
    expect(shouldFocus("triage", "director")).toBe(false);
  });

  it("'workers' queues only worker panes", () => {
    expect(shouldFocus("worker", "workers")).toBe(true);
    expect(shouldFocus("director", "workers")).toBe(false);
  });

  it("'fleet' queues both director and worker panes", () => {
    expect(shouldFocus("director", "fleet")).toBe(true);
    expect(shouldFocus("worker", "fleet")).toBe(true);
    expect(shouldFocus("reviewer", "fleet")).toBe(false);
  });

  it("'everything' queues every role", () => {
    for (const r of ["director", "worker", "triage", "reviewer", "tester"]) {
      expect(shouldFocus(r, "everything")).toBe(true);
    }
  });

  it("exposes labelled presets in display order", () => {
    expect(FOCUS_TARGETS).toEqual(["director", "workers", "fleet", "everything", "none"]);
    expect(focusTargetLabel("fleet")).toBe("Director + workers");
  });
});

describe("ConsoleAutoFocusMode (#434)", () => {
  it("default mode is cycle-on-reply", () => {
    expect(DEFAULT_AUTO_FOCUS_MODE).toBe("cycle-on-reply");
  });

  it("exposes both modes in display order", () => {
    expect(AUTO_FOCUS_MODES).toEqual(["cycle-on-reply", "off"]);
  });

  it("has human labels for every mode", () => {
    expect(autoFocusModeLabel("cycle-on-reply")).toBe("Cycle on reply");
    expect(autoFocusModeLabel("off")).toBe("Off (manual)");
  });
});

implementations.code:
// Focused planner pane (#652) — the pure model behind the one-stage-at-a-time right
// pane. It wraps the EXISTING blueprint/signal/gate logic (stageStatus / currentStage
// / evalGate) into a navigable "stage" view: which stages are visible, each one's status
// (complete / active / locked / upcoming), the gate pill, and the advance-bar action.
// Pure + serializable so it's fully unit-testable; no React/Tauri.

import {
  enabledStages, currentStage, stageStatus, stageSkipped,
  type BlueprintStage,
} from "@/features/planner/stages/blueprints";
import { evalGate, evalRequirement, gateReasons, type PlanSignals } from "@/features/planner/stages/stageGate";
import type { StagePrompt } from "@/features/planner/session/plannerConductor";

// "complete" = done IN sequence (at/behind the current position); "ahead" = done OUT of
// sequence (gate met past the current position — "banked"); "skipped" = an OPTIONAL section
// the USER deliberately skipped (#921 — the flow now STOPS on every optional stage; the only way
// past one without completing it is a user skip). The rail renders each distinctly so a future
// stage finishing early / a deliberately skipped stage don't read as in-order progress or as a
// not-yet-reached stage (#668).
export type StageStatus = "complete" | "ahead" | "active" | "skipped" | "locked" | "upcoming";

export interface Stage {
  key: string;
  name: string;
  glyph: string;
  blurb: string;
  /** The section's human gate description. */
  gate: string;
  index: number;
  total: number;
  status: StageStatus;
  /** Gate fill 0..1 for the in-progress fraction. */
  fraction: number;
  /** An optional stage — shown but never required (#676). */
  optional?: boolean;
  /** Whether the stage is SKIPPABLE right now (#2854): intrinsically `optional`, OR its declarative
   *  `skipWhen` rule passes against the live signals (e.g. an empty Features stage). Drives whether
   *  the footer renders a Skip control at all — a required stage (no rule) shows none, not a disabled
   *  ghost. Absent ⇒ not skippable. */
  skippable?: boolean;
  /** The Repos stage folds Deploy in as a "ship" substep (#1383) — drives the combined body. */
  ship?: boolean;
  /** The Structure stage folds Permissions in as a "fleet" substep → the "Streams" stage — drives
   *  the combined body (graph + coordination + permissions). */
  fleet?: boolean;
  /** The still-unmet gate requirements (label + progress detail) — drives the "why is this
   *  blocked" feedback on the gate pill (#805). Empty once the gate passes. */
  unmet?: { label: string; detail?: string }[];
}

/**
 * The visible stage list: enabled, non-N/A sections in declared order, each tagged with
 * its status — complete (gate passed), active (the current reached stage), locked (a
 * dependency is unmet), or upcoming (reachable but not yet current).
 */
export function stagesFrom(sections: BlueprintStage[], signals: PlanSignals): Stage[] {
  const current = currentStage(sections, signals);
  const visible = enabledStages(sections)
    .map((s) => ({ s, st: stageStatus(s, sections, signals) }))
    .filter(({ st }) => st.status !== "na");
  // The current position among visible stages; everything complete PAST it is "ahead".
  const activeIdx = current ? visible.findIndex(({ s }) => s.key === current.key) : visible.length;
  return visible.map(({ s, st }, i) => {
    let status: StageStatus;
    // A deliberately user-skipped optional stage reads as "skipped", not "complete" — even though
    // it counts as resolved for the frontier/gate (`stageDone`). Check this first (#921).
    if (stageSkipped(s, signals)) status = "skipped";
    else if (st.status === "complete") status = i > activeIdx ? "ahead" : "complete";
    else if (st.status === "locked") status = "locked";
    else status = current && s.key === current.key ? "active" : "upcoming";
    const unmet = gateReasons(s.gateRule, signals)
      .filter((r) => !r.pass)
      .map(({ label, detail }) => ({ label, detail }));
    // Skippable RIGHT NOW (#2854): intrinsically optional, or the declarative `skipWhen` rule passes
    // against the live signals (e.g. featuresDefined == 0). Drives whether the footer offers Skip.
    const skippable = s.optional === true || (s.skipWhen ? evalRequirement(s.skipWhen, signals).pass : false);
    return {
      key: s.key, name: s.name, glyph: s.glyph, blurb: s.blurb, gate: s.gate,
      index: i, total: visible.length, status, fraction: st.fraction, optional: s.optional, skippable, unmet,
      // #1383: the Repos stage folds Deploy in as a "ship" substep when a blueprint opts in — the
      // combined body renders the deploy block only then.
      ship: s.substeps?.some((ss) => ss.key === "ship"),
      fleet: s.substeps?.some((ss) => ss.key === "fleet"),
    };
  });
}

/**
 * The blueprint section for a stage, resolved BY KEY (#815). `stages` is a FILTERED subset of the
 * raw section list (disabled / not-applicable sections like `ui` are dropped by {@link stagesFrom}),
 * so indexing the raw sections with a stage index lands on the wrong section once any earlier one is
 * dropped. The conductor uses this to inject the *active stage's* prompt, not a neighbor's.
 */
export function sectionForStage<T extends { key: string }>(
  sections: T[], stage: { key: string } | undefined,
): T | undefined {
  return stage ? sections.find((s) => s.key === stage.key) : undefined;
}

export type ConnectorKind = "solid" | "partial" | "dashed" | "dim";

/** The rail connector AFTER node `i` (#668): solid traces the walked in-sequence path,
 *  partial leaves the current node, dashed reaches a banked-ahead node, dim otherwise. */
export function connectorKind(stages: Stage[], i: number): ConnectorKind {
  const role = stages[i]?.status;
  const next = stages[i + 1]?.status;
  // A banked-ahead node (done out of sequence) is reached by a dashed connector.
  if (role === "ahead" || next === "ahead") return "dashed";
  // The walked path is green UP TO the current node: every connector positioned BEFORE the
  // active node is solid — including the one leaving a skipped/optional section — so the
  // green leads INTO the current node, never out of it. Beyond the current node: dim (#668).
  const activeIdx = stages.findIndex((p) => p.status === "active");
  const frontier = activeIdx >= 0 ? activeIdx : stages.length;
  return i < frontier ? "solid" : "dim";
}

/** Index of the active stage (else the last) — what the selection auto-follows. */
export function activeIndex(stages: Stage[]): number {
  const a = stages.findIndex((p) => p.status === "active");
  return a >= 0 ? a : Math.max(0, stages.length - 1);
}

/** Clamp an index into [0, count-1] (0 when empty) — guards against a shrunk stage list
 *  after a blueprint switch / clear. */
export function clampIndex(i: number, count: number): number {
  if (count <= 0) return 0;
  return Math.min(Math.max(0, i), count - 1);
}

export type GatePill = "pass" | "wait";

/** Gate pill for a stage, from the declarative gate (#897 Phase 4c removed the legacy
 *  pipeline gate): "pass" once the stage's gateRule is satisfied, else "wait". */
export function gatePill(stage: Stage): GatePill {
  return stage.status === "complete" || stage.status === "ahead" ? "pass" : "wait";
}

/** Whether a stage has any GUIDANCE to reveal (#3257) — the gate's unmet requirements (while it's
 *  blocking) and/or a suggested next-step prompt. Drives whether the gate pill acts as a disclosure
 *  TOGGLE for the guidance card: with nothing to reveal the pill stays a plain status chip. */
export function hasStageGuidance(stage: Stage, pill: GatePill, prompt?: StagePrompt, onInject?: (text: string) => void): boolean {
  const showReqs = pill !== "pass" && (stage.unmet ?? []).length > 0;
  const showPrompt = !!prompt && !!onInject;
  return showReqs || showPrompt;
}

export type FooterKind = "back-to-current" | "jump-to-current" | "approve-continue" | "route-design" | "publish" | "awaiting";

export interface FooterAction {
  kind: FooterKind;
  enabled: boolean;
  /** Whether this action KIND supports a Skip control — set by {@link footerAction} on the active-stage
   *  advance actions (approve-continue / route-design), never on navigation/publish. A marker only:
   *  {@link resolveFooter} decides whether Skip actually RENDERS (`skipEnabled`) from the live signals. */
  canSkip?: boolean;
  /** Whether the Skip control RENDERS as an actionable button (#2854): true only when the stage is
   *  skippable now (its `skipWhen` rule passes / it's intrinsically optional) OR the user enabled
   *  "allow gate override" (#1285). A required stage like Discovery shows NO Skip — not a disabled
   *  ghost (the #2533 always-visible-Skip behavior regressed into a greyed button beside "gate
   *  blocking…"). The footer renders Skip iff this is set. */
  skipEnabled?: boolean;
}

/**
 * The advance-bar's primary action, by where the selection sits relative to the active
 * stage. Browsing a future (locked) stage → back to current; a past stage → jump to
 * current; on the active stage → approve & continue, or publish when the plan is complete.
 *
 * `userGated` (#funnel-ui-into-stores) is what turns this bar from a CONTROL into a PROGRESS
 * readout. Under the three-tier funnel the director advances the Features and Plan gates itself when
 * the requirement's authority covers them (#funnel-unattended-director), so an "approve & continue"
 * button there would offer the user a decision that is no longer theirs to make — and worse, one that
 * has often already been made. Those stages report `awaiting` instead: the funnel is running, watch it.
 *
 * A stage that keeps a REAL user gate passes `userGated: true` and is unchanged. The transformation
 * queue is the standing example, and the reason is worth carrying: it reverse-scopes a RUNNING app
 * rather than shaping one being created.
 *
 * `canSkip` marks the active-stage advance actions (approve-continue, route-design) as skip-ELIGIBLE
 * — a marker, not a render decision. Whether Skip actually appears is decided later by
 * {@link resolveFooter} (`skipEnabled`) from the live signals: skippable stage or gate-override on.
 * Navigation, publish and `awaiting` are never skip-eligible.
 */
export function footerAction(
  selectedIdx: number, activeIdx: number, planComplete: boolean, currentGateReady: boolean,
  routeDesign = false, userGated = true,
): FooterAction {
  if (selectedIdx > activeIdx) return { kind: "back-to-current", enabled: true };
  if (selectedIdx < activeIdx) return { kind: "jump-to-current", enabled: true };
  if (planComplete) return { kind: "publish", enabled: true };
  // #2121: the active UI stage whose design is missing or stale → the primary action ROUTES the
  // design (sync the skeleton + mark it current) instead of advancing. It's skip-eligible too —
  // routing and skipping are both valid choices — but resolveFooter still gates the actual Skip.
  if (routeDesign) return { kind: "route-design", enabled: true, canSkip: true };
  // Not user-gated ⇒ the director advances this stage under authority. Report, do not offer.
  // Deliberately NOT skip-eligible: skipping is a user decision about a gate the user no longer holds.
  if (!userGated) return { kind: "awaiting", enabled: false };
  return { kind: "approve-continue", enabled: currentGateReady, canSkip: true };
}

/**
 * Stage ids that keep a REAL user gate under the funnel (#funnel-ui-into-stores). Everything else
 * advances under the requirement's authority clauses, so its advance bar reports rather than offers.
 *
 * An ALLOW-list, not a deny-list, and that direction is the point: a stage added later is
 * authority-governed by default and has to argue its way onto this list, rather than silently keeping
 * a human gate nobody revisited.
 */
export const USER_GATED_STAGES: readonly string[] = ["transformations"];

/** Whether `stageId` keeps a user gate — see {@link USER_GATED_STAGES}. */
export function isUserGated(stageId: string | undefined): boolean {
  return !!stageId && USER_GATED_STAGES.includes(stageId);
}

/**
 * Resolve the final advance-bar action from the raw {@link footerAction}. Two independent axes:
 *
 * PRIMARY — a blocking "approve & continue" (gate not ready) lights up when `pendingCount > 0`:
 * there are drafted-but-unconfirmed sections and clicking confirms them (the one-click approval).
 * Otherwise the primary stays disabled ("gate blocking…").
 *
 * SKIP (#2854) — the Skip control RENDERS (`skipEnabled`) only when the KIND is skip-eligible
 * (`canSkip`) AND the active stage is skippable now (its `skipWhen` rule passes / it's intrinsically
 * optional) OR the user enabled gate override (#1285). A required stage (Discovery) shows NO Skip —
 * not a disabled ghost. When Skip renders it is always actionable, so there is no disabled state.
 *
 * Pure + unit-tested.
 */
export function resolveFooter(
  raw: FooterAction, pendingCount: number, allowOverride: boolean, skippable: boolean,
): FooterAction {
  // Skip renders only when its KIND is eligible AND the stage is skippable now (or override is on).
  const withSkip = raw.canSkip ? { ...raw, skipEnabled: skippable || allowOverride } : raw;
  // One-click confirm lights the blocking primary; nothing else force-enables it now.
  if (withSkip.kind !== "approve-continue" || withSkip.enabled) return withSkip;
  if (pendingCount > 0) return { ...withSkip, enabled: true };
  return withSkip;
}

/** Whether the active stage's gate is satisfied — enables "approve & continue". */
export function currentGateReady(sections: BlueprintStage[], signals: PlanSignals): boolean {
  const cur = currentStage(sections, signals);
  return !!cur && evalGate(cur.gateRule, signals).done;
}

/**
 * Whether the auto-complete-gates effect should confirm the active stage's pending sections (#1068):
 * the global flag is on, the planning autopilot is NOT driving (it owns confirmation then), and the
 * active stage actually has sections awaiting confirmation. The same "approve & continue" action the
 * user would click, minus the click — so it advances exactly the gates the manual path would.
 */
export function shouldAutoCompleteGate(autoOn: boolean, autopilotActive: boolean, pending: string[]): boolean {
  return autoOn && !autopilotActive && pending.length > 0;
}

