import { describe, it, expect } from "vitest";
import { timeAgo, timeAgoShort, timeAgoMs, loginColor, hueFor, truncate, slugify, fmtClock, dayKey } from "@/shared/lib/core/format";

describe("timeAgo", () => {
  const at = (msAgo: number) => new Date(Date.now() - msAgo).toISOString();

  it("renders seconds / minutes / hours / days / months", () => {
    expect(timeAgo(at(5_000))).toMatch(/^\d+s ago$/);
    expect(timeAgo(at(3 * 60_000))).toBe("3m ago");
    expect(timeAgo(at(2 * 3_600_000))).toBe("2h ago");
    expect(timeAgo(at(4 * 86_400_000))).toBe("4d ago");
    expect(timeAgo(at(60 * 86_400_000))).toBe("2mo ago");
  });

  it("guards empty, non-finite, and future timestamps to \"\"", () => {
    expect(timeAgo("")).toBe("");
    expect(timeAgo("not-a-date")).toBe("");
    expect(timeAgo(at(-10_000))).toBe(""); // future
  });
});

describe("timeAgoShort", () => {
  const at = (msAgo: number) => new Date(Date.now() - msAgo).toISOString();
  it("drops the trailing \" ago\"", () => {
    expect(timeAgoShort(at(5_000))).toMatch(/^\d+s$/);
    expect(timeAgoShort(at(2 * 3_600_000))).toBe("2h");
    expect(timeAgoShort(at(60 * 86_400_000))).toBe("2mo");
    expect(timeAgoShort("")).toBe("");
  });
});

describe("timeAgoMs", () => {
  it("renders from epoch millis and dashes a non-positive input", () => {
    expect(timeAgoMs(Date.now() - 2 * 3_600_000)).toBe("2h ago");
    expect(timeAgoMs(0)).toBe("—");
  });
});

describe("hueFor", () => {
  it("is deterministic and in [0, 360)", () => {
    expect(hueFor("alpha")).toBe(hueFor("alpha"));
    const h = hueFor("some-gist-id");
    expect(h).toBeGreaterThanOrEqual(0);
    expect(h).toBeLessThan(360);
  });
  it("differs across distinct strings", () => {
    expect(hueFor("alice")).not.toBe(hueFor("bob"));
  });
});

describe("loginColor", () => {
  it("is deterministic for a login and an in-range oklch hue", () => {
    const a = loginColor("octocat");
    expect(a).toBe(loginColor("octocat"));      // stable
    const hue = Number(a.match(/oklch\(0\.68 0\.12 (\d+)\)/)![1]);
    expect(hue).toBeGreaterThanOrEqual(0);
    expect(hue).toBeLessThan(360);
  });

  it("differs across distinct logins (no trivial collision)", () => {
    expect(loginColor("alice")).not.toBe(loginColor("bob"));
  });
});

// ── #2421 consolidated helpers — each test pins the edge behavior of the former copies ─────────

describe("truncate", () => {
  it("returns the string unchanged at or under max", () => {
    expect(truncate("hello", 5)).toBe("hello");
    expect(truncate("hi", 600)).toBe("hi");
    expect(truncate("", 10)).toBe("");
  });

  it("hard-cap shape (keep = max): the issue-body previews (600/800)", () => {
    const body = "x".repeat(601);
    expect(truncate(body, 600)).toBe("x".repeat(600) + "…");
    // Exactly max → untouched (the former `slice(0,600) + (len>600 ? "…" : "")` also kept it whole).
    expect(truncate("x".repeat(600), 600)).toBe("x".repeat(600));
  });

  it("display-budget shape (keep < max): the label sites (64/61, 32/30, 20/18)", () => {
    const s65 = "a".repeat(65);
    expect(truncate(s65, 64, 61)).toBe("a".repeat(61) + "…"); // lessonTitle
    // In the (max, max-2] band the string passes through whole — longer than the truncated form,
    // exactly like the former `len > 64 ? slice(0,61)+… : s` copies.
    expect(truncate("a".repeat(64), 64, 61)).toBe("a".repeat(64));
    expect(truncate("b".repeat(33), 32, 30)).toBe("b".repeat(30) + "…"); // prettyGist
    expect(truncate("feature/very-long-name", 20, 18)).toBe("feature/very-long-".slice(0, 18) + "…"); // BranchGraph lane
  });
});

describe("slugify", () => {
  it("lowercases, collapses non-alphanumeric runs to '-', and strips edge dashes", () => {
    expect(slugify("Invite Teammates")).toBe("invite-teammates");
    expect(slugify("  Salesforce (prod) → v2!  ")).toBe("salesforce-prod-v2");
    expect(slugify("--already--sluggy--")).toBe("already-sluggy");
  });

  it("returns '' when nothing survives (callers apply their own fallback)", () => {
    expect(slugify("")).toBe("");
    expect(slugify("→ ★ !!!")).toBe("");
    expect(slugify("→ ★ !!!", 40) || "source").toBe("source"); // the FocusedSourceBody shape
  });

  it("caps at max AFTER edge-stripping (matching the former featureList/source copies)", () => {
    expect(slugify("a".repeat(80), 60)).toBe("a".repeat(60));
    // A cut on a word boundary can leave a trailing dash — the former copies did too.
    expect(slugify("ab cd", 3)).toBe("ab-");
  });

  it("supports the DesignsWorkbench first-two-words derivation", () => {
    expect(slugify("A Sleek Primary Button!").split("-").filter(Boolean).slice(0, 2).join("-")).toBe("a-sleek");
  });
});

describe("fmtClock", () => {
  it("renders HH:MM, padded (the automations shape)", () => {
    expect(fmtClock(new Date(2026, 0, 1, 2, 0).getTime())).toBe("02:00");
    expect(fmtClock(new Date(2026, 5, 15, 23, 59).getTime())).toBe("23:59");
  });
  it("renders an em dash for null", () => {
    expect(fmtClock(null)).toBe("—");
  });
  it("renders HH:MM:SS with { seconds: true } (the MCP Analytics shape)", () => {
    expect(fmtClock(new Date(2026, 0, 1, 2, 0, 7).getTime(), { seconds: true })).toBe("02:00:07");
  });
});

describe("dayKey", () => {
  it("renders the LOCAL zero-padded YYYY-MM-DD (the telemetry daily-bucket key)", () => {
    expect(dayKey(new Date(2026, 0, 5).getTime())).toBe("2026-01-05");
    expect(dayKey(new Date(2026, 10, 30, 23, 59, 59).getTime())).toBe("2026-11-30");
  });
  it("buckets two timestamps on the same local day identically", () => {
    expect(dayKey(new Date(2026, 3, 2, 0, 0, 1).getTime())).toBe(dayKey(new Date(2026, 3, 2, 23, 30).getTime()));
  });
});

implementations.code:
// Filesystem confinement (#158) — the file-tool axis of per-session repo isolation.
//
// A session for repo A shouldn't read/write files in sibling repos. The `bsc-confine`
// PreToolUse hook (gated panes) blocks Claude's file tools (Read/Edit/Write/MultiEdit/
// NotebookEdit) when their target path escapes the session's repo root. This module is
// the pure decision the hook mirrors in shell — so the rule is unit-tested even though
// the runtime check runs in bash.
//
// Deliberately conservative + string-based (no realpath, portable across OSes): any
// `..` segment is rejected, and an absolute path must sit under the repo root. It only
// covers the AI's file tools — true Bash-command confinement needs OS-level sandboxing.

function normalize(p: string): string {
  return p.replace(/\\/g, "/");
}

/** Absolute paths: POSIX (`/…`), home (`~…`), Windows drive (`C:…`), or UNC (`\\…`). */
function isAbsolute(p: string): boolean {
  return /^(\/|~|[A-Za-z]:)/.test(p) || p.startsWith("\\\\");
}

/** True if any path segment is a `..` (an upward traversal). */
function hasParentSegment(p: string): boolean {
  return normalize(p).split("/").some((seg) => seg === "..");
}

function underRoot(root: string, target: string): boolean {
  const r = normalize(root).replace(/\/+$/, "");
  const t = normalize(target);
  return t === r || t.startsWith(r + "/");
}

/**
 * Whether a file-tool target stays within `repoRoot`:
 * - empty path → confined (not a path op);
 * - any `..` segment → NOT confined (rejected conservatively, even within-repo);
 * - absolute path → confined only if it sits under `repoRoot`;
 * - plain relative path → confined (resolved against the repo-root cwd).
 */
export function isPathConfined(repoRoot: string, target: string): boolean {
  if (!target) return true;
  if (hasParentSegment(target)) return false;
  if (isAbsolute(target)) return underRoot(repoRoot, target);
  return true;
}

/**
 * Whether a **read** may reach `target` even though it sits OUTSIDE the repo root: it is an absolute
 * path under one of the session's declared read-only HARVEST roots (#3509 / #3530).
 *
 * #3509 widened what `bsc ui harvest` / `bsc graph harvest` may SCAN via `$BSC_HARVEST_ROOTS`, but the
 * session's Read tool is gated by the separate `bsc-confine` hook, which knew nothing of those roots — so
 * the designer could harvest components from the app repo yet not Read the sibling files they import
 * (the utility/hook/type modules harvest doesn't surface). This closes that: a Read of a harvest root is
 * allowed. It is deliberately **read-only** — only the caller's `Read` tool composes this; Write/Edit stay
 * confined — so a harvest root grants no write anywhere, matching the #3509 contract.
 *
 * Same conservatism as {@link isPathConfined}: a `..` segment is rejected, and only ABSOLUTE paths are
 * considered (a plain relative path resolves against the repo-root cwd, so it is in-repo by construction
 * and can only escape via `..`, which is already blocked). Empty roots contribute nothing.
 */
export function isUnderHarvestRoot(harvestRoots: readonly string[], target: string): boolean {
  if (!target || hasParentSegment(target) || !isAbsolute(target)) return false;
  return harvestRoots.some((r) => r && underRoot(r, target));
}

/**
 * Whether `target` is the session's OWN `.claude/` config (the hook list + permissions) — which the
 * file tools must never touch, even though it sits INSIDE the repo root (so {@link isPathConfined}
 * passes it). The `bsc-confine` hook blocks it too (#1916 config self-protection): an agent must not
 * be able to edit `settings.json` to remove the confinement hooks once a session runs under
 * `bypassPermissions`, where the `permissions.deny` rule that used to guard it is ignored. Only the
 * repo-root `.claude` is protected (a nested `src/.claude` is not the session config).
 */
export function isConfigProtected(repoRoot: string, target: string): boolean {
  if (!target) return false;
  const r = normalize(repoRoot).replace(/\/+$/, "");
  const t = normalize(target).replace(/\/+$/, "");
  const rel = (t === r ? "" : t.startsWith(r + "/") ? t.slice(r.length + 1) : t).replace(/^\.\//, "");
  return rel === ".claude" || rel.startsWith(".claude/");
}

