// Persisted GitHub board state (#2446, epic #2444) — the pure model behind the last-known-projects
// cache. A successful `PROJECTS_QUERY` fetch is boiled down to one MINIMAL record per board
// (identity + lifecycle + progress counts + repos — enough for the Projects column, the Glance
// nodes, and the progress meters offline) and stored as `{ records, fetchedAt }`:
//   - in the zustand store (persisted; the fast-paint CACHE — golden rule: cache, not source of truth),
//   - mirrored into the bsc-project store (`~/.base-studio-code/github-state.json`, via
//     `bsc project github-state set`) so the durable copy is `bsc`-reachable (golden rule #2).
//
// Precedence at the consumers (useGlanceProjects + ProjectsList): live fetch > persisted records >
// local-inventory-only (#2445). The persisted fallback is always FILTERED to projects that still
// exist locally ({@link filterRecordsToLocal}) — a record whose hub was deleted must not resurrect
// the project; only the LIVE fetch can vouch for a GitHub-only board.
//
// Board/Issues/Insights detail (fieldValues, labels, comments) deliberately stays refetch-on-view —
// only this entry-point set persists.

import { projectSlug, sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

/** One `projectsV2` item as the wire carries it (structural twin of publishedModel's GhProjectItem). */
interface GhItemShape { content: { __typename?: string; state?: string } | null }

/**
 * The `projectsV2` node shape this module reads/synthesizes — a structural twin of the planner's
 * `GhProject` (publishedModel.ts), declared here so `shared/` stays feature-agnostic. Anything
 * matching this shape (including `GhProject` itself) interoperates both ways.
 */
export interface GhProjectShape {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  items: { totalCount: number; nodes: GhItemShape[] };
  repositories: { nodes: Array<{ nameWithOwner: string }> };
}

/** The minimal per-board record that persists (#2446) — identity + lifecycle + progress + repos. */
export interface MinimalGhProject {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  /** True item count (the fetched item page is capped at 100; this is the headline number). */
  itemsTotalCount: number;
  /** Open issues/PRs among the fetched items (mirrors publishedModel's `projectProgress`). */
  openCount: number;
  /** Closed/merged issues/PRs among the fetched items. */
  closedCount: number;
  /** `nameWithOwner` per linked repository. */
  repos: string[];
}

/** The persisted state: the last successful fetch's records + when it landed (epoch ms). */
export interface GithubState {
  records: MinimalGhProject[];
  fetchedAt: number;
}

/**
 * Boil a fetched `projectsV2` set down to the minimal persisted records. Open/closed counts derive
 * from the fetched item states exactly like `projectProgress` (MERGED counts as closed; a draft
 * item — `content: null` — counts as neither).
 */
export function toMinimalGhProjects(projects: GhProjectShape[]): MinimalGhProject[] {
  return projects.map((p) => {
    let openCount = 0, closedCount = 0;
    for (const n of p.items?.nodes ?? []) {
      const s = n.content?.state;
      if (s === "OPEN") openCount++;
      else if (s === "CLOSED" || s === "MERGED") closedCount++;
    }
    return {
      id: p.id, number: p.number, title: p.title, shortDescription: p.shortDescription,
      url: p.url, closed: p.closed, updatedAt: p.updatedAt,
      itemsTotalCount: p.items?.totalCount ?? 0, openCount, closedCount,
      repos: (p.repositories?.nodes ?? []).map((r) => r.nameWithOwner),
    };
  });
}

/**
 * Expand a persisted record back into the `GhProject` shape the existing published rendering
 * consumes, synthesizing `openCount`/`closedCount` item stubs so `projectProgress` computes the
 * exact same open count + closed fraction the record was derived from. This is what lets the stale
 * overlay reuse the live `ProjectRow`/merge paths untouched.
 */
export function minimalToGhProject(r: MinimalGhProject): GhProjectShape {
  const nodes: GhItemShape[] = [
    ...Array.from({ length: r.openCount }, () => ({ content: { state: "OPEN" } })),
    ...Array.from({ length: r.closedCount }, () => ({ content: { state: "CLOSED" } })),
  ];
  return {
    id: r.id, number: r.number, title: r.title, shortDescription: r.shortDescription,
    url: r.url, closed: r.closed, updatedAt: r.updatedAt,
    items: { totalCount: r.itemsTotalCount, nodes },
    repositories: { nodes: r.repos.map((nameWithOwner) => ({ nameWithOwner })) },
  };
}

/**
 * Keep only the records that still correspond to a LOCAL project — the don't-resurrect rule (#2446).
 * Matching mirrors the #2445 overlay (`buildLocalPublished` / the `mark_published` reconcile): a
 * record covers a local entry when the entry's key equals the record's name-derived
 * `projectSlug(title)` (today's keys) or the legacy `sanitizeProjectKey(title)` (grandfathered
 * title-keyed hubs), or when the titles match case-insensitively.
 *
 * @param records the persisted records (the last-known board state).
 * @param locals  the projects that exist locally — on-disk hubs and/or store drafts (`key` + `title`).
 */
export function filterRecordsToLocal(
  records: MinimalGhProject[],
  locals: Array<{ key: string; title: string }>,
): MinimalGhProject[] {
  if (records.length === 0 || locals.length === 0) return [];
  const keys = new Set(locals.map((l) => l.key));
  const titles = new Set(locals.map((l) => l.title.toLowerCase()));
  return records.filter((r) =>
    keys.has(projectSlug(r.title)) || keys.has(sanitizeProjectKey(r.title)) || titles.has(r.title.toLowerCase()),
  );
}

// GitHub feature store slice (#1309) — connection state, token (+ repo-scoped tokens), user, repos,
// active repo, and the page mode. Extracted from the former grab-bag `github` slice (whose residual
// — app-chrome + tunnel state — is now store/slices/shell.ts). Composed by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore, GithubUser, GithubRepo } from "@/store/types";
import { leanRepos } from "@/store/types/github";
import type { GithubState, MinimalGhProject } from "@/shared/lib/github/githubState";
import { pushGithubState } from "@/shared/lib/github/githubStateBridge";

export interface GithubSlice {
  githubConnected: boolean;
  githubToken: string;
  // The last-known GitHub board state (#2446): the minimal per-project records from the most recent
  // successful projects fetch + when it landed. Persisted (the fast-paint cache — survives restart
  // and renders as a stale-marked overlay while logged out / pre-refresh) and mirrored into the
  // bsc-project store so the durable copy is `bsc`-reachable. `null` until a fetch ever lands.
  // Deliberately NOT cleared by disconnectGithub — surviving the logged-out state is its point.
  githubState: GithubState | null;
  /** Overwrite the records wholesale (a fresh fetch), stamping `fetchedAt` and mirroring to bsc. */
  setGithubState: (records: MinimalGhProject[]) => void;
  // Repo-scoped GitHub credentials (#158): per-`owner/name` fine-grained token; persisted, never
  // logged. A request targeting that repo uses it instead of the global PAT.
  repoGithubTokens: Record<string, string>;
  setRepoGithubToken: (repo: string, token: string | null) => void;
  githubUser: GithubUser | null;
  githubRepos: GithubRepo[];
  activeRepoName: string;
  githubPageMode: "summary" | "projects" | "repos";
  setGithubPageMode: (v: "summary" | "projects" | "repos") => void;
  setGithubToken: (token: string) => void;
  setGithubUser: (user: GithubUser | null) => void;
  setGithubRepos: (repos: GithubRepo[]) => void;
  setActiveRepo: (name: string) => void;
  setGithubConnected: (connected: boolean) => void;
  disconnectGithub: () => void;
  markGithubTokenInvalid: () => void;
}

export const createGithubSlice: StateCreator<AppStore, [], [], GithubSlice> = (set) => ({
  githubConnected: false,
  githubToken: "",
  githubState: null,
  setGithubState: (records) => {
    const next: GithubState = { records, fetchedAt: Date.now() };
    set({ githubState: next });
    void pushGithubState(next); // mirror the durable copy into the bsc-project store (#2446)
  },
  repoGithubTokens: {},
  setRepoGithubToken: (repo, token) =>
    set((s) => {
      const next = { ...s.repoGithubTokens };
      if (token && token.trim()) next[repo] = token.trim();
      else delete next[repo];
      return { repoGithubTokens: next };
    }),
  githubUser: null,
  githubRepos: [],
  activeRepoName: "",
  githubPageMode: "summary",
  setGithubPageMode: (v) => set({ githubPageMode: v }),
  setGithubToken: (token) => set({ githubToken: token }),
  setGithubUser: (user) => set({ githubUser: user }),
  // Project to the DECLARED fields on the way in (#githubrepos-projected…). GitHub's response
  // carries 82; `GithubRepo` names 8; the annotation strips nothing at runtime, so without this
  // the store held ~6 KB per repo of which 61% was `*_url` templates nothing reads — 493.8 KB at
  // 84 repos, 86% of the persisted state, re-stringified on EVERY store set() by `persist`.
  // Done HERE rather than at the call site so no future caller can reintroduce it.
  setGithubRepos: (repos) => set({ githubRepos: leanRepos(repos as unknown as Record<string, unknown>[]) }),
  setActiveRepo: (name) => set({ activeRepoName: name }),
  setGithubConnected: (connected) => set({ githubConnected: connected }),
  disconnectGithub: () => set({
    githubConnected: false,
    githubToken: "",
    repoGithubTokens: {},
    githubUser: null,
    githubRepos: [],
    activeRepoName: "",
  }),
  // A request returned 401 (token expired/revoked) — flip to disconnected so the UI prompts a
  // reconnect instead of 401-looping; cached user/repos stay for context until reconnect.
  markGithubTokenInvalid: () => set((s) => (s.githubConnected ? { githubConnected: false } : {})),
});

// Shared GitHub data shapes (#1492, #1528) — reused across features (mcp, skills, planner,
// github). Genuinely-shared shapes live here; truly view-specific supersets (the full
// projectsV2 node in ProjectsList) stay with their feature.

/** A minimal GitHub Project reference (subset of the GraphQL `projectsV2` node). */
export interface GhProjectRef {
  id: string;
  number: number;
  title: string;
}

/** A GitHub REST milestone (the superset the Roadmap Gantt needs; ProjectsSummary reads a subset). */
export interface GhMilestone {
  number: number;
  title: string;
  description: string | null;
  state: "open" | "closed";
  due_on: string | null;
  created_at: string;
  open_issues: number;
  closed_issues: number;
  creator: { login: string } | null;
}

/** A GitHub REST issue row (the `issues` endpoint also returns PRs — rows with `pull_request`
 *  set are PRs and must be excluded from "issues"). Union of the fields the fleet + portfolio
 *  views read. */
export interface GhIssueItem {
  number: number;
  title: string;
  state: string;
  created_at: string;
  closed_at: string | null;
  pull_request?: unknown;
}

/** A GitHub Events API event — the shape the user/repo activity feeds consume. */
export interface GHEvent {
  id: string;
  type: string;
  actor: { login: string };
  repo: { name: string };
  payload: unknown;
  created_at: string;
}

/** A GitHub issue/PR label — `name` + a 6-hex `color` (no leading `#`). */
export interface GhLabel {
  name: string;
  color: string;
}

import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { resolveGithubToken } from "@/shared/lib/github/repoCredentials";

/**
 * Default in-memory freshness window. Within this many seconds of the last fetch,
 * a revisit is served straight from the backend cache with **no network call** —
 * so navigating between screens doesn't refetch GitHub every time. After the
 * window the next call revalidates cheaply (ETag → 304). `force` (manual refresh)
 * always bypasses it; pass `maxAgeSecs: 0` to always revalidate-on-view.
 */
export const DEFAULT_MAX_AGE_SECS = 300;

export interface GithubRequestOpts {
  /** Serve the cached body without any network call when it's younger than this
   *  (seconds). Defaults to {@link DEFAULT_MAX_AGE_SECS}; pass 0 to always revalidate. */
  maxAgeSecs?: number;
  /** Bypass the cache + ETag and force a fresh fetch (manual refresh). */
  force?: boolean;
}

/** A `github_request` failure that is a 401 — the stored token is expired/revoked. */
export function isGithubAuthError(e: unknown): boolean {
  const s = String(e);
  return s.includes("401") || s.includes("Bad credentials");
}

/**
 * Match the backend's typed rate-limit error (#2448): `github rate-limited until <epoch secs>` —
 * raised when GitHub's quota is exhausted (403/429 + `X-RateLimit-Remaining: 0` / `Retry-After`)
 * and while the backend's in-memory gate short-circuits further requests.
 *
 * @returns the reset time in epoch **milliseconds**, or null for any other failure.
 */
export function rateLimitedUntil(e: unknown): number | null {
  const m = /github rate-limited until (\d+)/.exec(String(e));
  return m ? Number(m[1]) * 1000 : null;
}

/** The quiet inline wording for a rate-limited query (#2448), or null for any other error —
 *  callers render this as a dim note instead of the red error banner. */
export function rateLimitNote(e: unknown): string | null {
  const until = rateLimitedUntil(e);
  if (until === null) return null;
  const at = new Date(until).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  return `GitHub rate limit reached — showing cached data; retrying after ${at}.`;
}

/**
 * Call the GitHub REST API through the ETag-validated backend cache (`github_request`).
 *
 * - Pulls the token from the store, so callers just pass a path.
 * - Passes `maxAgeSecs`/`force` through to the cache: within `maxAgeSecs` the cached
 *   body is served with no network call; `force` bypasses the cache for a manual refresh.
 *   Otherwise the backend revalidates cheaply with `If-None-Match` (304 → cached).
 * - On a 401 (expired/revoked PAT) it flips the app to disconnected via
 *   {@link markGithubTokenInvalid} so the UI prompts a reconnect instead of
 *   silently 401-looping, then rethrows.
 */
export async function githubRequest<T>(path: string, opts: GithubRequestOpts = {}): Promise<T> {
  // Repo-scoped credentials (#158): a request targeting a repo with an assigned
  // fine-grained token uses it instead of the global PAT (so a session can't reach
  // other repos via the proxy); everything else uses the global token.
  const s = useAppStore.getState();
  const token = resolveGithubToken(path, s.repoGithubTokens, s.githubToken);
  try {
    return await invoke<T>("github_request", {
      token,
      path,
      maxAgeSecs: opts.maxAgeSecs ?? DEFAULT_MAX_AGE_SECS,
      force: opts.force,
    });
  } catch (e) {
    if (isGithubAuthError(e)) useAppStore.getState().markGithubTokenInvalid();
    throw e;
  }
}

/**
 * Call the GitHub GraphQL API through the backend cache (`github_graphql`).
 * GraphQL has no ETag, so the cache is purely time-windowed: within `maxAgeSecs`
 * (default {@link DEFAULT_MAX_AGE_SECS}) the cached result is served with no
 * network call; otherwise it re-POSTs. `force` bypasses. 401 → disconnect, as with
 * {@link githubRequest}.
 */
export async function githubGraphql<T>(
  query: string,
  variables: Record<string, unknown> | null,
  opts: GithubRequestOpts = {},
): Promise<T> {
  const token = useAppStore.getState().githubToken;
  try {
    return await invoke<T>("github_graphql", {
      token,
      query,
      variables,
      maxAgeSecs: opts.maxAgeSecs ?? DEFAULT_MAX_AGE_SECS,
      force: opts.force,
    });
  } catch (e) {
    if (isGithubAuthError(e)) useAppStore.getState().markGithubTokenInvalid();
    throw e;
  }
}

/** Drop the backend's cached GitHub responses (call on connect / disconnect / re-auth). */
export function clearGithubCache(): Promise<void> {
  return invoke("github_cache_clear");
}

