import { describe, it, expect } from "vitest";
import { SAMPLE_GRAPH, buildGlanceData } from "@/features/glance/lib/glanceData";
import { kitNodeId, usesKitEdgeId, libraryNodeId, requiresEdgeId, mcpNodeId, usesMcpEdgeId, serviceNodeId, usesServiceEdgeId } from "@/features/glance/lib/glanceGraph";
import type { ProjectLink } from "@/features/glance/lib/projectLinks";
// Cross-feature via the barrel (#1309): the REAL kit→library roll-up + the component record it reads.
import { resolveKitLibraryRefs, type ComponentRecord } from "@/features/designs";

// Guard for the externalized sample network (@data/glance/sample-graph.json, #2419).
describe("SAMPLE_GRAPH (loaded from @data/glance/sample-graph.json)", () => {
  it("is the 14-node / 20-edge Northwind spine, flagged sample", () => {
    expect(SAMPLE_GRAPH.sample).toBe(true);
    expect(SAMPLE_GRAPH.rawNodes).toHaveLength(14);
    expect(SAMPLE_GRAPH.rawEdges).toHaveLength(20);
  });

  it("is referentially intact — every edge endpoint is a node, every node id unique", () => {
    const ids = new Set(SAMPLE_GRAPH.rawNodes.map((n) => n.id));
    expect(ids.size).toBe(SAMPLE_GRAPH.rawNodes.length);
    for (const e of SAMPLE_GRAPH.rawEdges) {
      expect(ids.has(e.from)).toBe(true);
      expect(ids.has(e.to)).toBe(true);
    }
  });

  it("carries only valid role / health / activity / edge-kind tokens (#2541)", () => {
    const roles = ["infra", "service", "data", "client"];
    const healths = ["idle", "healthy", "warning", "error"];
    const activities = ["idle", "planning", "building", "waiting", "review", "live"];
    const kinds = ["api", "data", "events"];
    for (const n of SAMPLE_GRAPH.rawNodes) {
      expect(roles).toContain(n.role);
      expect(healths).toContain(n.health);
      expect(activities).toContain(n.activity);
    }
    for (const e of SAMPLE_GRAPH.rawEdges) expect(kinds).toContain(e.kind);
  });

  it("keeps the spec's reporting⇄analytics dependency cycle (the coordination-hazard example)", () => {
    const has = (from: string, to: string) => SAMPLE_GRAPH.rawEdges.some((e) => e.from === from && e.to === to);
    expect(has("reporting", "analytics")).toBe(true);
    expect(has("analytics", "reporting")).toBe(true);
  });
});

describe("buildGlanceData", () => {
  it("zero projects yields an EMPTY real graph — never the sample (#2272)", () => {
    const g = buildGlanceData([]);
    expect(g.sample).toBe(false);
    expect(g.rawNodes).toHaveLength(0);
    expect(g.rawEdges).toHaveLength(0);
  });

  it("builds a deterministic node — the same project id always yields the same node (#2583/#4052)", () => {
    // The lifecycle CATEGORY that used to be carried here is gone (#4052); what mattered about that
    // test — no hash-per-id tier, so a node never changes shape between renders — is asserted directly.
    const g = buildGlanceData([{ id: "p", name: "P" }]);
    expect(g.rawNodes[0]).toEqual(buildGlanceData([{ id: "p", name: "P" }]).rawNodes[0]);
    expect(g.rawNodes[0]).not.toHaveProperty("category");
  });

  it("carries a project's APP-TYPE onto the node — the contract endpoint-type discriminator (#3786/#3802)", () => {
    const g = buildGlanceData([{ id: "p", name: "P", appType: "api" }]);
    expect(g.rawNodes[0].appType).toBe("api");
    // absent appType ⇒ the node is byte-identical to before (toEqual ignores the undefined key)
    expect(buildGlanceData([{ id: "q", name: "Q" }]).rawNodes[0].appType).toBeUndefined();
  });
});

describe("buildGlanceData — UI-kit nodes (#2571)", () => {
  const projects = [{ id: "app-a", name: "App A" }, { id: "app-b", name: "App B" }];
  const kits = [{ id: "react-ui", name: "React UI" }];

  it("adds ONE kit node per distinct kit in use + one kit→project edge per consumer", () => {
    const g = buildGlanceData(projects, [], [
      { projectKey: "app-a", kitId: "react-ui" },
      { projectKey: "app-b", kitId: "react-ui" },
    ], kits);
    const kitNode = g.rawNodes.find((n) => n.kind === "kit");
    expect(kitNode).toMatchObject({ id: kitNodeId("react-ui"), kind: "kit", slug: "React UI", health: "off", activity: "idle" });
    // exactly one kit node (two consumers of the SAME kit ⇒ one node)
    expect(g.rawNodes.filter((n) => n.kind === "kit")).toHaveLength(1);
    // one edge per consumer, project→kit, kind "uses-kit"
    const kitEdges = g.rawEdges.filter((e) => e.kind === "uses-kit");
    expect(kitEdges).toEqual([
      { id: usesKitEdgeId("app-a", "react-ui"), from: "app-a", to: kitNodeId("react-ui"), kind: "uses-kit" },
      { id: usesKitEdgeId("app-b", "react-ui"), from: "app-b", to: kitNodeId("react-ui"), kind: "uses-kit" },
    ]);
  });

  it("leaves the PROJECT nodes untouched — no `kind`, same shape as without kit usage", () => {
    const withKits = buildGlanceData(projects, [], [{ projectKey: "app-a", kitId: "react-ui" }], kits);
    const without = buildGlanceData(projects);
    const projA = withKits.rawNodes.find((n) => n.id === "app-a");
    expect(projA?.kind).toBeUndefined();
    expect(projA).toEqual(without.rawNodes.find((n) => n.id === "app-a"));
  });

  it("emits NO kit node for a kit whose only consumer isn't a project in this graph (stale usage)", () => {
    const g = buildGlanceData(projects, [], [{ projectKey: "ghost", kitId: "react-ui" }], kits);
    expect(g.rawNodes.some((n) => n.kind === "kit")).toBe(false);
    expect(g.rawEdges.some((e) => e.kind === "uses-kit")).toBe(false);
  });

  it("dedupes a duplicate (projectKey, kitId) into a single edge", () => {
    const g = buildGlanceData(projects, [], [
      { projectKey: "app-a", kitId: "react-ui" },
      { projectKey: "app-a", kitId: "react-ui" },
    ], kits);
    expect(g.rawEdges.filter((e) => e.kind === "uses-kit")).toHaveLength(1);
  });

  it("falls back to the kit ID when the kit library has no matching name", () => {
    const g = buildGlanceData(projects, [], [{ projectKey: "app-a", kitId: "mystery-kit" }], []);
    expect(g.rawNodes.find((n) => n.kind === "kit")?.slug).toBe("mystery-kit");
  });

  it("adds nothing when there is no kit usage (identical to before #2571)", () => {
    const g = buildGlanceData(projects, [], [], kits);
    expect(g.rawNodes.some((n) => n.kind === "kit")).toBe(false);
    expect(g.rawEdges).toEqual([]);
  });
});

// The REAL cross-graph data path (#3133) — not synthetic band input: a genuine ComponentRecord whose source
// imports `@bsc/algorithms/fibonacci` is resolved by the designs feature's roll-up against the PACKAGED
// algorithm seed, then joined against kit usage here. This is the wiring #3133 exists to add; #3119 only
// ever exercised hand-written `requires` fixtures.
describe("buildGlanceData — cross-graph `requires` from REAL library refs (#3133)", () => {
  const projects = [{ id: "route-planner", name: "Route Planner" }, { id: "app-b", name: "App B" }];
  const kits = [{ id: "react-ui", name: "React UI" }];
  const comp = (id: string, source: string, kitId = "react-ui"): ComponentRecord => ({
    id, name: id, kitId, role: "composite", version: "1", used: 1, tags: [], variants: ["default"],
    composes: [], props: [], whenUse: [], whenNot: [], src: "", srcText: "", source,
  });
  const FIB_SRC = 'import { fibonacci } from "@bsc/algorithms/fibonacci";\nexport const C = () => fibonacci(10);';
  const FIB_NODE = libraryNodeId("algo", "fibonacci.ts");

  it("draws a project→algorithm `requires` edge for a kit the project consumes", () => {
    const refs = resolveKitLibraryRefs([comp("FibCard", FIB_SRC)]);
    const g = buildGlanceData(projects, [], [{ projectKey: "route-planner", kitId: "react-ui" }], kits, refs);

    const lib = g.rawNodes.filter((n) => n.kind === "library");
    expect(lib).toEqual([
      { id: FIB_NODE, slug: "fibonacci", kind: "library", library: "algo", role: "infra", health: "off", activity: "idle" },
    ]);
    expect(g.rawEdges.filter((e) => e.kind === "requires")).toEqual([
      { id: requiresEdgeId("route-planner", FIB_NODE), from: "route-planner", to: FIB_NODE, kind: "requires" },
    ]);
    // the kit dimension is untouched — the project still consumes its kit
    expect(g.rawEdges.filter((e) => e.kind === "uses-kit")).toHaveLength(1);
  });

  it("fans one shared library node out to EVERY project consuming the kit", () => {
    const refs = resolveKitLibraryRefs([comp("FibCard", FIB_SRC)]);
    const g = buildGlanceData(projects, [], [
      { projectKey: "route-planner", kitId: "react-ui" },
      { projectKey: "app-b", kitId: "react-ui" },
    ], kits, refs);
    expect(g.rawNodes.filter((n) => n.kind === "library")).toHaveLength(1); // ONE band node, shared
    expect(g.rawEdges.filter((e) => e.kind === "requires").map((e) => e.from)).toEqual(["route-planner", "app-b"]);
  });

  it("carries an ALGORITHM and a SOUND as separately-tagged band nodes", () => {
    const refs = resolveKitLibraryRefs([
      comp("Mixed", 'import { fibonacci } from "@bsc/algorithms/fibonacci";\nimport { play } from "@bsc/sounds/click";\nexport const M = () => fibonacci(play());'),
    ]);
    const g = buildGlanceData(projects, [], [{ projectKey: "route-planner", kitId: "react-ui" }], kits, refs);
    expect(g.rawNodes.filter((n) => n.kind === "library").map((n) => n.library)).toEqual(["algo", "sound"]);
    expect(g.rawEdges.filter((e) => e.kind === "requires")).toHaveLength(2);
  });

  it("dedupes to ONE edge when a project consumes two kits requiring the same node", () => {
    const refs = resolveKitLibraryRefs([comp("A", FIB_SRC), comp("B", FIB_SRC, "other-kit")]);
    expect(refs).toHaveLength(2); // one ref per kit
    const g = buildGlanceData(projects, [], [
      { projectKey: "route-planner", kitId: "react-ui" },
      { projectKey: "route-planner", kitId: "other-kit" },
    ], [...kits, { id: "other-kit", name: "Other" }], refs);
    expect(g.rawNodes.filter((n) => n.kind === "library")).toHaveLength(1);
    expect(g.rawEdges.filter((e) => e.kind === "requires")).toHaveLength(1);
  });

  it("emits NOTHING for a library ref whose kit no project consumes (no dangling band node)", () => {
    const refs = resolveKitLibraryRefs([comp("FibCard", FIB_SRC)]);
    const g = buildGlanceData(projects, [], [], kits, refs);                                  // no usage at all
    expect(g.rawNodes.some((n) => n.kind === "library")).toBe(false);
    const stale = buildGlanceData(projects, [], [{ projectKey: "ghost", kitId: "react-ui" }], kits, refs);
    expect(stale.rawNodes.some((n) => n.kind === "library")).toBe(false); // consumer isn't in this graph
  });

  it("is byte-identical to the pre-#3133 graph when no component imports a library (no regression)", () => {
    const refs = resolveKitLibraryRefs([comp("Plain", "export const C = () => null;")]);
    expect(refs).toEqual([]);
    const usage = [{ projectKey: "route-planner", kitId: "react-ui" }];
    expect(buildGlanceData(projects, [], usage, kits, refs)).toEqual(buildGlanceData(projects, [], usage, kits));
  });
});

// The external MCP-CONTRACT dimension (#3786, Phase 1 inter-app contracts) — mirrors the kit loop: a
// SCOPED server (its `projects` names ≥1 project in the graph) becomes one contract node edged from each
// consumer; a GLOBAL server (`projects: []`, every session gets it) is skipped.
describe("buildGlanceData — MCP contract nodes (#3786)", () => {
  const projects = [{ id: "app-a", name: "App A" }, { id: "app-b", name: "App B" }];
  const server = (over: Partial<{ id: string; name: string; projects: string[]; transport: "stdio" | "http" }> = {}) =>
    ({ id: "postgres", name: "Postgres", projects: ["app-a"], transport: "stdio" as const, ...over });

  it("adds ONE mcp node per scoped server + one project→mcp `uses-mcp` edge per consumer", () => {
    const g = buildGlanceData(projects, [], [], [], [], [server({ projects: ["app-a", "app-b"] })]);
    const mcp = g.rawNodes.find((n) => n.kind === "mcp");
    expect(mcp).toMatchObject({ id: mcpNodeId("postgres"), kind: "mcp", slug: "Postgres", role: "infra", health: "off", activity: "idle" });
    expect(g.rawNodes.filter((n) => n.kind === "mcp")).toHaveLength(1); // two consumers of the SAME server ⇒ one node
    expect(g.rawEdges.filter((e) => e.kind === "uses-mcp")).toEqual([
      { id: usesMcpEdgeId("app-a", "postgres"), from: "app-a", to: mcpNodeId("postgres"), kind: "uses-mcp" },
      { id: usesMcpEdgeId("app-b", "postgres"), from: "app-b", to: mcpNodeId("postgres"), kind: "uses-mcp" },
    ]);
  });

  it("skips a GLOBAL server (empty `projects`) — a global built-in is not a specific contract", () => {
    const g = buildGlanceData(projects, [], [], [], [], [server({ projects: [] })]);
    expect(g.rawNodes.some((n) => n.kind === "mcp")).toBe(false);
    expect(g.rawEdges.some((e) => e.kind === "uses-mcp")).toBe(false);
  });

  it("emits NO mcp node for a server whose only scoped project isn't in this graph (stale scope)", () => {
    const g = buildGlanceData(projects, [], [], [], [], [server({ projects: ["ghost"] })]);
    expect(g.rawNodes.some((n) => n.kind === "mcp")).toBe(false);
    expect(g.rawEdges.some((e) => e.kind === "uses-mcp")).toBe(false);
  });

  it("derives the mcp node's appType from the transport — http ⇒ api, stdio ⇒ serverless", () => {
    const http = buildGlanceData(projects, [], [], [], [], [server({ id: "sentry", transport: "http" })]);
    expect(http.rawNodes.find((n) => n.kind === "mcp")?.appType).toBe("api");
    const stdio = buildGlanceData(projects, [], [], [], [], [server({ transport: "stdio" })]);
    expect(stdio.rawNodes.find((n) => n.kind === "mcp")?.appType).toBe("serverless");
  });

  it("dedupes a duplicate (projectKey, serverId) into a single edge", () => {
    const g = buildGlanceData(projects, [], [], [], [], [server({ projects: ["app-a", "app-a"] })]);
    expect(g.rawEdges.filter((e) => e.kind === "uses-mcp")).toHaveLength(1);
  });

  it("falls back to the server ID when it has no name", () => {
    const g = buildGlanceData(projects, [], [], [], [], [server({ id: "mystery", name: "", projects: ["app-a"] })]);
    expect(g.rawNodes.find((n) => n.kind === "mcp")?.slug).toBe("mystery");
  });

  it("adds nothing (byte-identical to before #3786) when there are no scoped mcp servers", () => {
    expect(buildGlanceData(projects, [], [], [], [], [])).toEqual(buildGlanceData(projects));
    expect(buildGlanceData(projects, [], [], [], [], [server({ projects: [] })])).toEqual(buildGlanceData(projects));
  });
});

// EXPLICIT, planner-declared inter-app contracts (#3786 Phase 2) — a stored ProjectLink whose `target` is
// a `service` or `mcp` endpoint (not another project) becomes an external band node edged from `from`,
// GENERALIZING the Phase-1 auto-derived mcp scope. Deduped against the auto-mcp nodes by node id.
describe("buildGlanceData — explicit external contracts (#3786 Phase 2)", () => {
  const projects = [{ id: "app-a", name: "App A" }, { id: "app-b", name: "App B" }];

  it("renders a SERVICE-targeted contract as ONE external service node + a uses-service edge", () => {
    const links: ProjectLink[] = [
      { id: "app-a>stripe:api", from: "app-a", to: "stripe", kind: "api",
        target: { type: "service", name: "Stripe", url: "https://api.stripe.com", appType: "api" } },
    ];
    const g = buildGlanceData(projects, links);
    expect(g.rawNodes.find((n) => n.kind === "service")).toMatchObject({
      id: serviceNodeId("stripe"), kind: "service", slug: "Stripe", appType: "api", role: "infra", health: "off", activity: "idle",
    });
    expect(g.rawEdges).toEqual([
      { id: usesServiceEdgeId("app-a", "stripe"), from: "app-a", to: serviceNodeId("stripe"), kind: "uses-service" },
    ]);
    // NOT a project edge (the target isn't a project) — lifted into the band, never the L0 network.
    expect(g.rawEdges.some((e) => e.id === "app-a>stripe:api")).toBe(false);
  });

  it("renders an MCP-targeted contract as ONE external mcp node + a uses-mcp edge, appType from the declaration", () => {
    const links: ProjectLink[] = [
      { id: "app-a>postgres:data", from: "app-a", to: "postgres", kind: "data", target: { type: "mcp", appType: "serverless" } },
    ];
    const g = buildGlanceData(projects, links);
    expect(g.rawNodes.find((n) => n.kind === "mcp")).toMatchObject({ id: mcpNodeId("postgres"), kind: "mcp", slug: "postgres", appType: "serverless" });
    expect(g.rawEdges).toEqual([
      { id: usesMcpEdgeId("app-a", "postgres"), from: "app-a", to: mcpNodeId("postgres"), kind: "uses-mcp" },
    ]);
  });

  it("DEDUPES an explicit mcp contract against a Phase-1 auto-derived mcp node — ONE node, ONE edge", () => {
    // `postgres` is BOTH in the mcp scope (Phase-1 auto) AND declared as an explicit contract from app-a:
    // the same server id ⇒ ONE node (the auto node wins) and the edge id collides ⇒ ONE edge.
    const links: ProjectLink[] = [
      { id: "app-a>postgres:data", from: "app-a", to: "postgres", kind: "data", target: { type: "mcp", appType: "serverless" } },
    ];
    const mcpServers = [{ id: "postgres", name: "Postgres", projects: ["app-a"], transport: "stdio" as const }];
    const g = buildGlanceData(projects, links, [], [], [], mcpServers);
    expect(g.rawNodes.filter((n) => n.kind === "mcp")).toHaveLength(1);
    expect(g.rawNodes.find((n) => n.kind === "mcp")?.slug).toBe("Postgres");  // the auto node (store name) wins
    expect(g.rawEdges.filter((e) => e.kind === "uses-mcp")).toHaveLength(1);
  });

  it("keeps an explicit contract ALONGSIDE a distinct auto-mcp node (no false dedup across kinds)", () => {
    const links: ProjectLink[] = [
      { id: "app-a>stripe:api", from: "app-a", to: "stripe", kind: "api", target: { type: "service", appType: "api" } },
    ];
    const mcpServers = [{ id: "postgres", name: "Postgres", projects: ["app-b"], transport: "http" as const }];
    const g = buildGlanceData(projects, links, [], [], [], mcpServers);
    expect(g.rawNodes.filter((n) => n.kind === "service")).toHaveLength(1);
    expect(g.rawNodes.filter((n) => n.kind === "mcp")).toHaveLength(1);
  });

  it("skips an external contract whose consuming project isn't in this graph (stale from)", () => {
    const links: ProjectLink[] = [
      { id: "ghost>stripe:api", from: "ghost", to: "stripe", kind: "api", target: { type: "service" } },
    ];
    const g = buildGlanceData(projects, links);
    expect(g.rawNodes.some((n) => n.kind === "service")).toBe(false);
    expect(g.rawEdges).toEqual([]);
  });

  it("leaves a legacy project↔project link (no target) as a plain L0 edge — byte-identical", () => {
    const link: ProjectLink = { id: "app-a>app-b:api", from: "app-a", to: "app-b", kind: "api" };
    const g = buildGlanceData(projects, [link]);
    expect(g.rawEdges).toEqual([{ id: "app-a>app-b:api", from: "app-a", to: "app-b", kind: "api" }]);
    expect(g.rawNodes.some((n) => n.kind === "service" || n.kind === "mcp")).toBe(false);
    // an explicit `{ type: "project" }` target draws the SAME plain project edge (no band node)
    const withProjTarget: ProjectLink = { ...link, target: { type: "project" } };
    expect(buildGlanceData(projects, [withProjTarget])).toEqual(g);
  });
});

implementations.code:
// Glance fleet drill (#…) — the L1 graph you get by clicking a project on the L0 project network: that
// project's FLEET as a graph in the same Glance node/edge language (director + workers + a reviewer,
// wired by coordination edges), so the drill reads as one recursive graph zooming in. The topology is a
// deterministic SAMPLE per project until a real per-project fleet-plan feed lands (mirrors glanceData's
// sample project topology) — isolated here so wiring the real fleet later is a drop-in.
import type { GRawNode, GRawEdge, GRole, GEdgeKind, GNodeComm } from "@/features/glance/lib/glanceGraph";
import type { GlanceData } from "@/features/glance/lib/glanceData";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import { archetypeById, positionComms, type Team, type Position, type Relationship, PER_TECH_STUDIO_NODES } from "@/features/teams";
import type { BlueprintTeam } from "@/features/planner/stages/blueprintTypes";

/** Session-role → Glance colour bucket, grouped by agent FUNCTION (#2561): ORCHESTRATE (planner ·
 *  director) = infra, BUILD (worker) = service, VERIFY (reviewer · tester · juror) = data, FLOW (issuer ·
 *  triage · documentor · designer — intake, routing, docs, UI) = client. The bucket drives the colour;
 *  the real session role rides as `roleLabel` + the legend reads the function-group names at L1. */
const ROLE_TO_GROLE: Record<string, GRole> = {
  planner: "infra", director: "infra", debugger: "infra",
  worker: "service",
  reviewer: "data", tester: "data", juror: "data",
  issuer: "client", triage: "client", documentor: "client", designer: "client",
  // The AUTHORING system sessions join `designer` in the FLOW bucket: like it, they produce the material
  // a build runs on (algorithms, teams, sounds, connectors) rather than the build itself. Without these
  // entries `gRole` falls through to "service" and a librarian would draw as a worker.
  librarian: "client", architect: "client", "sound-designer": "client", integrator: "client",
};
const gRole = (role?: string): GRole => (role && ROLE_TO_GROLE[role]) || "service";

/** The planner position's node id — fixed, like `"director"`, so the graph, the role fallback and any
 *  later pane binding all name it the same way. Not a stream id: `AgentStream.id` comes from the plan
 *  and could in principle collide, which `fleetToOrg`'s `rel()` guard (`from === to`) would then hide. */
export const PLANNER_NODE_ID = "planner";

/** The app-owned SYSTEM SESSIONS a project can declare (`FleetPlan.systemSessions`) → the session role
 *  each renders as. The ids match both the fixed singletons in `shared/lib/session/systemSessions` and
 *  the Studio Network team's position ids, so one of these means the same thing everywhere.
 *
 *  Deliberately NOT called "studios": a **Studio** is already the export/import unit for the whole app
 *  library (studio snapshots). Two unrelated concepts sharing one word in one codebase is how a reader
 *  ends up looking at the wrong feature.
 *
 *  An id outside this map is IGNORED rather than rendered: a typo in the plan should cost that one node,
 *  not put a phantom agent on the graph that no session can ever back. */
const SYSTEM_SESSION_ROLES: Record<string, string> = {
  designer: "designer",
  librarian: "librarian",
  architect: "architect",
  "sound-designer": "sound-designer",
  integrator: "integrator",
  // The DEBUGGER is app-owned like the rest, but a project never DECLARES it: the caller injects it
  // into `systemSessions` while a request is open, so the node comes and goes with the queue.
  // Listing it here is what lets `resolveSystemSessions` admit it, and what keeps it out of the
  // `worker` role-colour fallback.
  debugger: "debugger",
};

/**
 * The per-TECHNOLOGY sessions a declared kind expands into (#system-sessions-are-per-technology).
 *
 * A project declares `designer`, but there is no such SESSION — there are `design-studio:designer-react`
 * and `…-react-native`, and the same for each of the librarian's languages. Rendering the bare kind gives
 * a node that cannot open anything, because the pane-id map is keyed per technology. So the kind expands
 * here and every downstream consumer (positions, personaOf, the role fallback) sees only real sessions.
 *
 * THE ROSTER IS THE TEAMS FEATURE'S, not a copy (`the-studio-session-set-is-derived-not-declared`).
 * This module used to declare its own, listing `librarian-python` alongside the other two — a
 * technology with no record anywhere in the repo — so the same wrong node was drawn from two
 * independent lists. Now there is one, and it is pinned to the store the technologies come from by
 * `studioNodeRoster.test.ts`; a technology that gains or loses records moves both graphs at once.
 */
const SYSTEM_SESSION_VARIANTS: Record<string, readonly string[]> = PER_TECH_STUDIO_NODES;

/** A system-session node's DISPLAY label. `designer-react` reads "designer · react"; a kind with no
 *  technologies keeps its own name. The node id stays the machine identity — this is only what shows. */
export function systemSessionLabel(nodeId: string): string {
  for (const [kind, ids] of Object.entries(SYSTEM_SESSION_VARIANTS)) {
    if (ids.includes(nodeId)) return `${kind} · ${nodeId.slice(kind.length + 1)}`;
  }
  return nodeId;
}

/** The KIND behind a per-technology session id, for the role fallback + persona lookup. */
function systemSessionKind(nodeId: string): string {
  for (const [kind, ids] of Object.entries(SYSTEM_SESSION_VARIANTS)) {
    if (ids.includes(nodeId)) return kind;
  }
  return nodeId;
}

/** Every app-owned system session id, in display order. Exported so the L0 graph
 *  (#glance-reads-left-to-right-sessions-to-libraries) draws the SAME set this fleet graph resolves —
 *  one list, so a session added here appears in both places at once rather than in whichever was
 *  remembered. */
export const SYSTEM_SESSION_IDS: readonly string[] = Object.keys(SYSTEM_SESSION_ROLES);

/** The declared system sessions that are real, de-duplicated, in a stable order. */
export function resolveSystemSessions(ids: readonly string[] | undefined): string[] {
  const known = [...new Set(ids ?? [])].filter((s) => s in SYSTEM_SESSION_ROLES);
  return [...new Set(known.flatMap((s) => SYSTEM_SESSION_VARIANTS[s] ?? [s]))];
}

/** The session role for a position whose persona did not resolve. The fixed-id agents are known by
 *  their id — without this a planner falls through to `worker` and renders in the BUILD colour, which
 *  is exactly wrong for an ORCHESTRATE agent (`ROLE_TO_GROLE` already buckets `planner` as infra). */
function fallbackRole(nodeId: string): string {
  if (nodeId === "director" || nodeId === PLANNER_NODE_ID) return nodeId;
  return SYSTEM_SESSION_ROLES[systemSessionKind(nodeId)] ?? "worker";
}

/** Fleet coordination kind → Org relationship ARCHETYPE (#2561, interim map until fleets are authored as
 *  Orgs). The archetype names the relationship (Oversees a review, Stewards a shared resource, Peers on a
 *  handoff) and expands into the communication forms shown in the edge inspector. The director hub is a
 *  `manages` relationship; plain `dependsOn` is a lateral `peers` seam. */
const KIND_TO_ARCHETYPE: Record<string, string> = {
  handoff: "peers", blocking: "peers", sequence: "peers", review: "oversees", notify: "peers", shared: "peers", mutex: "stewards",
};

/** Resolve the persona surfaced on a fleet node (#2561): who is at this terminal. */
function nodePersona(p: Persona | undefined): GRawNode["persona"] {
  return p ? { name: p.name, role: p.role, model: p.model, skills: p.skills ?? [], responsibilities: p.responsibilities ?? [] } : undefined;
}

/**
 * Project a {@link FleetPlan} into a real {@link Org} (#2563) — the "fleet as Org" bridge. Streams (+ an
 * enabled director) become POSITIONS (personas referenced by id); coordination becomes RELATIONSHIPS
 * tagged with their archetype, in ARCHETYPE-NATIVE direction: the director MANAGES each stream, a typed
 * edge maps its kind (producer→consumer), a plain `dependsOn` is a lateral peer seam. Reusing the Org
 * model lets the drill derive each agent's communication surface (`positionComms`) from ONE source of
 * truth — the foundation for later authoring the fleet as an Org. Pure + exported for testing.
 */
/** The streams that are COORDINATORS — a peer of the director rather than one of its reports.
 *
 *  ONE definition, because two placers need it and they must not drift: `fleetToOrg` uses it to decide
 *  the archetypes (which set the COLUMN), and `withStreamRepos` uses it to decide repo banding (which
 *  sets the ROW). A coordinator that was a peer in one and a lane in the other would render as a node
 *  in the coordinator column but inside one repository's band — half cross-repo, half not.
 *
 *  Read from the persona library: a stream whose persona carries the `director` ROLE. Not an id list,
 *  so a second coordinator needs no code change. */
export function coordinatorIds(fleet: FleetPlan, personas: readonly Persona[]): Set<string> {
  const directorRoles = new Set(personas.filter((p) => p.role === "director").map((p) => p.id));
  return new Set(fleet.streams.filter((s) => s.persona && directorRoles.has(s.persona)).map((s) => s.id));
}

export function fleetToOrg(fleet: FleetPlan, team?: BlueprintTeam, personas: readonly Persona[] = []): Team {
  // THE COORDINATOR TIER. A stream whose persona carries the `director` ROLE is a PEER of the director,
  // not one of its reports — `persona-lexicographer` is exactly that, and the roster says so rather than
  // this module hardcoding an id. Read from the persona library, so a second coordinator added there
  // lands in the right column without a code change.
  //
  // Placement follows from the archetypes, as everything here does: a coordinator is SERVED by the
  // system sessions (same as the director, so it shares the director's depth and therefore its column)
  // and is never `manages`-ed by the director (which would push it one layer right).
  const coordinatorSet = coordinatorIds(fleet, personas);
  const isCoordinator = (streamId: string): boolean => coordinatorSet.has(streamId);
  // `planner` is a RESERVED id that no longer renders. Dropping the synthesized node is not enough: a
  // fleet can carry a REAL stream under that id (studio-code's is named "Project planning session"),
  // and removing only the synthetic one would leave the real stream in its place — the same node the
  // maintainer asked to remove, under a different label.
  const positions: Position[] = fleet.streams
    .filter((s) => s.id !== PLANNER_NODE_ID)
    .map((s) => ({ nodeId: s.id, kind: "agent", personaId: s.persona, label: s.name || s.id }));
  if (fleet.director?.enabled) positions.push({ nodeId: "director", kind: "agent", personaId: "director", label: "director" });
  // The PLANNER, always (#glance-planner-node-per-project). Every project has one — the session that
  // produced this plan — and until now it was the one agent absent from the graph of the work it
  // authored. Unconditional, unlike the director: a project can decline a director, but a plan it can
  // drill into necessarily came from a planning session.
  //
  // Guarded against a stream that is itself called `planner`: two positions sharing a nodeId would put
  // two nodes with one id in the graph, and `rel()` de-dupes by id — so the collision would not look
  // like a duplicate, it would look like edges going missing. A real stream keeps the name; we add ours
  // only when nothing already claims it.
  // NO PLANNER POSITION, and none survives from the fleet either (see the filter below). Reverses
  // #glance-planner-node-per-project on the maintainer's call: the planning session authored the plan
  // but is not part of the RUNTIME picture, so the drill starts at the director.
  // The SYSTEM SESSIONS this project DECLARES it uses. Same collision
  // guard as the planner: a stream already owning the id keeps it.
  const systemSessions = resolveSystemSessions(fleet.systemSessions);
  for (const s of systemSessions) {
    if (!positions.some((p) => p.nodeId === s)) {
      positions.push({ nodeId: s, kind: "agent", personaId: systemSessionKind(s), label: systemSessionLabel(s) });
    }
  }
  const posIds = new Set(positions.map((p) => p.nodeId));
  // Authored-team archetype overlay (#2572): a `persona→persona` pair the blueprint team wired with an
  // archetype OVERRIDES the coordination-derived archetype for that pair — so the authored design's
  // semantics drive the drill wherever the team authored them. Empty (no team) ⇒ pure derived, unchanged.
  const authored = teamArchetypeByPersonaPair(team);
  const personaOf = new Map<string, string | undefined>(fleet.streams.map((s) => [s.id, s.persona]));
  personaOf.set("director", "director");
  personaOf.set(PLANNER_NODE_ID, "planner");
  for (const s of resolveSystemSessions(fleet.systemSessions)) personaOf.set(s, s);
  const archOf = (from: string, to: string, derived: string): string => {
    const pf = personaOf.get(from), pt = personaOf.get(to);
    return (pf && pt && authored.get(`${pf}|${pt}`)) || derived;
  };
  const relationships: Relationship[] = [];
  const seen = new Set<string>();
  const rel = (from: string, to: string, archetype: string) => {
    if (from === to || !posIds.has(from) || !posIds.has(to)) return;
    const k = `${from}|${to}`;
    if (seen.has(k)) return;
    seen.add(k);
    relationships.push({ id: `r${relationships.length}`, archetype, from, to });
  };
  // manager → report, for every stream EXCEPT the planner. A fleet may carry a real stream whose id is
  // `planner` (studio-code's "Project planning session" is one), and pairing `director manages planner`
  // with the `planner serves director` edge below makes a MUTUAL PAIR — which `mutualPairs` classifies
  // as a cycle, and cycle edges are handed to `layerDag` as the break set. Both edges then drop out of
  // layering, the planner loses every constraint, and it lands among the workers to the RIGHT of the
  // director — the opposite of the intent, reported in-app as `dependency cycle: director ⇄ Project
  // planning session`.
  //
  // Excluding it is the right semantics regardless of the cycle: the planning session is not a worker in
  // the director's lane. It hands the plan over and briefs it, which is exactly what `serves` says.
  // WHICH COORDINATOR OWNS A STREAM. `stream.coordinator` names one by id; anything that is not a real
  // coordinator (absent, misspelled, or naming a plain stream) resolves to the director, so an
  // unreadable value can never leave a stream with no manager at all.
  //
  // Until this existed EVERY coordinator managed EVERY stream, which is harmless with one and false
  // with two — a surface stream was drawn as a report of the lexicographer AND the director at once.
  const ownerOf = (s: { id: string; coordinator?: string }): string =>
    s.coordinator && coordinatorSet.has(s.coordinator) ? s.coordinator : "director";
  if (fleet.director?.enabled) {
    for (const s of fleet.streams) {
      if (s.id === PLANNER_NODE_ID) continue;
      // A COORDINATOR IS NOT A REPORT. `manages` would layer it one step right of the director; it
      // belongs in the same column, and gets there via the `serves` edges below.
      if (isCoordinator(s.id)) continue;
      // ...and a stream that answers to ANOTHER coordinator is not the director's report either.
      if (ownerOf(s) !== "director") continue;
      rel("director", s.id, archOf("director", s.id, "manages"));
    }
  }
  // planner → director (#glance-planner-node-per-project). `serves`, not `manages`: the planner hands
  // the plan over and briefs it at runtime (`bsc-brief`, #2377) but owns none of the execution — the
  // director does. That makes the authority chain read end to end in one direction: the system sessions serve
  // the planner, the planner serves the director, the director manages the workers.

  // studio → planner, the SAME archetype + direction the Studio Network team already uses. This is what
  // places them: Glance layers by dependency depth, `serves` puts the server at the lower (further-left)
  // layer, so they land left of the planner, which is left of the director, with the workers
  // right of it. The arrangement is a consequence of the archetype, not a layout rule.
  //
  // EVERY COORDINATOR, not only the director. `serves` puts the server at the lower (further-left)
  // layer, so this is what places the system sessions to the LEFT of the whole coordinator column and
  // gives each coordinator the same depth — the arrangement the maintainer asked for, expressed as
  // relationships rather than as coordinates.
  const coordinators = ["director", ...fleet.streams.map((x) => x.id).filter(isCoordinator)];
  for (const s of systemSessions) {
    for (const co of coordinators) rel(s, co, archOf(s, co, "serves"));
  }
  // A COORDINATOR MANAGES THE WORK IT DISTRIBUTES, which is what puts every worker and noun session to
  // the RIGHT of the coordinator column rather than merely right of the director. The lexicographer
  // hands surface work to noun/verb sessions exactly as the director hands feature work to workers;
  // both are `manages`, so both push their reports one layer right and the dependency DAG orders them
  // among themselves from there.
  for (const co of coordinators) {
    if (co === "director") continue;
    for (const s of fleet.streams) {
      if (s.id === PLANNER_NODE_ID || isCoordinator(s.id)) continue;
      // ONLY THE STREAMS THAT NAME IT. A coordinator that owns nothing manages nothing — it still sits
      // in the column via its `serves` edges, which is the honest picture of a coordinator with an
      // empty lane rather than one drawn as managing work it does not own.
      if (ownerOf(s) !== co) continue;
      rel(co, s.id, archOf(co, s.id, "manages"));
    }
  }

  // producer → consumer, and upstream ↔ dependent — both SKIPPING the planner entirely.
  //
  // The planner participates in exactly ONE relationship: `serves director` (above). Every other edge
  // touching it is dropped, because a planning session is not a peer of the build streams it produced.
  //
  // This is load-bearing, not tidiness. A fleet may carry a real `planner` stream WITH `dependsOn` on
  // build streams (studio-code's does). The director manages those streams, so the planner sat BELOW the
  // director via its dependency AND above it via `serves` — closing cycles like
  //   console -> planner -> director -> console
  //   cli-platform -> console -> planner -> director -> cli-platform
  // `mutualPairs` only finds 2-CYCLES, so these never reached `layerDag`'s break set and the relaxation
  // ran away: measured at layer 141 across 46 nodes, spreading the graph over 142 columns, which renders
  // as an EMPTY canvas. (The old `director manages planner` edge had been masking it — that made a
  // 2-cycle, which mutualPairs did catch.)
  const touchesPlanner = (a: string, b: string) => a === PLANNER_NODE_ID || b === PLANNER_NODE_ID;
  for (const e of fleet.edges ?? []) {
    if (touchesPlanner(e.from, e.to)) continue;
    rel(e.from, e.to, archOf(e.from, e.to, KIND_TO_ARCHETYPE[e.kind] ?? "peers"));
  }
  for (const s of fleet.streams) {
    for (const dep of s.dependsOn) {
      if (touchesPlanner(dep, s.id)) continue;
      rel(dep, s.id, archOf(dep, s.id, "peers"));
    }
  }

  // Phase 2 (#2575): ADD the team's authored relationships that have no derived edge, INSTANTIATED onto
  // the streams by persona — a team rel posA→posB becomes every {posA-persona stream} × {posB-persona
  // stream} pair with the team's archetype. `rel` dedups vs the derived edges above (a pair with both
  // keeps its slice-3-overlaid archetype), so this only ADDS authored relationships the coordination
  // didn't wire. Nodes stay the fleet streams (identity + liveness preserved).
  if (team) {
    const streamsByPersona = new Map<string, string[]>();
    for (const s of fleet.streams) if (s.persona) {
      const arr = streamsByPersona.get(s.persona);
      if (arr) arr.push(s.id); else streamsByPersona.set(s.persona, [s.id]);
    }
    const personaOfPos = new Map(team.positions.map((p) => [p.nodeId, p.personaId]));
    for (const tr of team.relationships) {
      const pa = personaOfPos.get(tr.from), pb = personaOfPos.get(tr.to);
      if (!pa || !pb) continue;
      for (const sa of streamsByPersona.get(pa) ?? []) for (const sb of streamsByPersona.get(pb) ?? []) rel(sa, sb, tr.archetype);
    }
  }
  return { id: "fleet", name: "Fleet", positions, relationships };
}

/** A `personaFrom|personaTo → archetype` lookup from a blueprint {@link BlueprintTeam}'s authored
 *  relationships (#2572) — so the fleet projection can override a coordination pair's archetype with the
 *  team's authored one when the two streams' personas match (direction included). Empty for no team. */
function teamArchetypeByPersonaPair(team?: BlueprintTeam): Map<string, string> {
  const m = new Map<string, string>();
  if (!team) return m;
  const personaOf = new Map(team.positions.map((p) => [p.nodeId, p.personaId]));
  for (const r of team.relationships) {
    const pf = personaOf.get(r.from), pt = personaOf.get(r.to);
    if (pf && pt) m.set(`${pf}|${pt}`, r.archetype);
  }
  return m;
}

/** Convert a blueprint {@link BlueprintTeam} into a standalone {@link Org} (#2572) — the team is already
 *  `{positions, relationships}`, so this just stamps the library-identity fields. Exported for phase 2
 *  (rendering the drill from the authored team directly). */
export function teamToOrg(team: BlueprintTeam): Team {
  return { id: "team", name: "Team", positions: team.positions, relationships: team.relationships };
}

/** A minimal persona for a node with no matching persona entry (e.g. the director hub) — so its comms
 *  surface still renders. */
const fallbackPersona = (name: string, role: string): NonNullable<GRawNode["persona"]> => ({ name, role, skills: [], responsibilities: [] });

/** Org relationship archetype → a representative Glance edge `kind` (#2565). For a fleet-drill (L1) edge
 *  the `kind` is largely vestigial — the edge is coloured + labelled by its ARCHETYPE now (#2561), and
 *  `kind` drives only the `hard` flag (unshown at L1); the archetype is the real identity. */
const ARCHETYPE_TO_KIND: Record<string, GEdgeKind> = {
  manages: "api", oversees: "data", consults: "events", peers: "api", serves: "events", stewards: "data",
};

/**
 * Render a Glance fleet graph FROM an {@link Org} (#2565) — the ONE source that drives the drill's nodes,
 * edges, AND comms. Positions → nodes (persona resolved + its communication surface via `positionComms`);
 * relationships → edges. Direction: a Glance edge is "from depends on to" — the INVERSE of an org
 * relationship's archetype-native direction (a report depends on its manager, a consumer on its producer)
 * — so each relationship maps to a Glance edge REVERSED. Pure + exported: the org may be projected from a
 * running fleet (below) or, later, sourced from a blueprint's authored `team`.
 */
export function buildOrgFleetData(org: Team, personas: Persona[]): GlanceData {
  const personaById = new Map(personas.map((p) => [p.id, p]));
  const rawNodes: GRawNode[] = org.positions.map((pos) => {
    const persona = pos.personaId ? personaById.get(pos.personaId) : undefined;
    const role = persona?.role ?? fallbackRole(pos.nodeId);
    const p = nodePersona(persona) ?? fallbackPersona(pos.label ?? persona?.name ?? pos.nodeId, role);
    p.comms = projectComms(org, pos, personas); // who this agent talks to + how (#2563)
    // Rests at idle (#2551) — a planned position isn't "building" until its session is actually live.
    // A `resource` position (a library, not an agent) is marked so the canvas draws it distinctly (#3322)
    // instead of the persona-less "worker" fallback role reading as an agent node.
    return { id: pos.nodeId, slug: pos.label ?? persona?.name ?? pos.nodeId, role: gRole(role), roleLabel: role, health: "off" as const, activity: "idle" as const, persona: p, resource: pos.kind === "resource" || undefined };
  });
  const ids = new Set(rawNodes.map((n) => n.id));
  const rawEdges: GRawEdge[] = [];
  const seen = new Set<string>();
  for (const r of org.relationships) {
    // A CYCLICAL archetype (iterates, #2578) is a deliberate feedback LOOP — emit BOTH directions so the
    // shared graph-core cycle primitive (`mutualPairs`) detects it and renders it as a bowed loop; every
    // other archetype maps to ONE reversed edge (Glance "from depends on to" inverts the org direction).
    const dirs: [string, string][] = archetypeById(r.archetype)?.cyclical
      ? [[r.to, r.from], [r.from, r.to]]
      : [[r.to, r.from]];
    for (const [from, to] of dirs) {
      if (from === to || !ids.has(from) || !ids.has(to)) continue;
      const k = `${from}|${to}`;
      if (seen.has(k)) continue;
      seen.add(k);
      rawEdges.push({ from, to, kind: ARCHETYPE_TO_KIND[r.archetype] ?? "api", archetype: r.archetype });
    }
  }
  return { rawNodes, rawEdges, sample: false };
}

/** Build a project's REAL fleet as a Glance graph — project the {@link FleetPlan} into an Org (#2563) and
 *  render from it (#2565), so the drill's nodes / edges / comms all flow from ONE source (the Org). The
 *  layout is topology-identical to the pre-#2565 inline builder. Returns `sample:false`. */
export function buildRealFleetData(fleet: FleetPlan, personas: Persona[], team?: BlueprintTeam): GlanceData {
  return withStreamRepos(buildOrgFleetData(fleetToOrg(fleet, team, personas), personas), fleet, coordinatorIds(fleet, personas));
}

/**
 * Carry each stream's REPOSITORY onto its node, so the drill can group by it (`bandNodesByRepo`).
 *
 * A SEPARATE PASS rather than a field threaded through the Org, and deliberately: `fleetToOrg` projects
 * the fleet into the SHARED Team model that `bsc teams` also uses, where a position is a persona in a
 * relationship graph and has no repository — adding one there would put a fleet-only concept into a
 * model that has nothing to do with repos. The node id IS the stream id, so the join needs nothing else.
 *
 * A stream with an EMPTY repo is left absent rather than grouped under `""`. `parseFleetFile` keeps such
 * a stream visible with an empty `repo` on purpose (#2611) — a plan that could not resolve one — and an
 * empty-string band would render as a group with no name, which reads as a bug rather than as the
 * missing datum it is. Ungrouped is the honest position, and it is the same place the architect sits.
 *
 * Pure; returns a new graph and mutates nothing.
 */
export function withStreamRepos(data: GlanceData, fleet: FleetPlan, coordinators: ReadonlySet<string> = new Set()): GlanceData {
  const repoOf = new Map<string, string>();
  for (const s of fleet.streams ?? []) {
    // A COORDINATOR IS NEVER IN A REPOSITORY BAND. It spans them by definition — the director already
    // sits ungrouped for exactly this reason, and a lexicographer whose vocabulary crosses both repos is
    // the same kind of node. A stray `repo` on such a stream would drop it into one band while the
    // column said it was a peer of the director, which is the picture contradicting itself.
    if (coordinators.has(s.id)) continue;
    const repo = (s.repo ?? "").trim();
    if (s.id && repo) repoOf.set(s.id, repo);
  }
  if (!repoOf.size) return data;
  return { ...data, rawNodes: data.rawNodes.map((n) => (repoOf.has(n.id) ? { ...n, repo: repoOf.get(n.id) } : n)) };
}

/** The fleet-drill's PREVIEW node id (#2623) — a reserved, non-agent node, so it never collides with a
 *  stream id (stream ids are slugs; this carries the structural `:` + reserved tail, like `:director`). */
export const PREVIEW_NODE_ID = "__preview__";

/**
 * Add the PREVIEW node to a fleet-drill graph when the project is COMPLETE (#2623) — the surface the user
 * clicks to render the finished application in the graph (it morphs open the app preview the way an agent
 * node morphs open its terminal). Not an agent: no persona/edges, marked `preview`, and rendered
 * distinctly by the canvas. Idempotent (never doubles) and a no-op while the project is still building, so
 * the node appears exactly when there's something to preview. Pure.
 */
export function withPreviewNode(data: GlanceData, complete: boolean): GlanceData {
  if (!complete || data.rawNodes.some((n) => n.preview)) return data;
  const preview: GRawNode = {
    id: PREVIEW_NODE_ID, slug: "preview", role: "client", roleLabel: "preview",
    health: "healthy", activity: "live", preview: true,
  };
  return { ...data, rawNodes: [...data.rawNodes, preview] };
}

/** Pare an org {@link positionComms} summary down to the glance node's {@link GNodeComm} shape (labels +
 *  transports only) — keeping the glance model decoupled from the Org form types. */
function projectComms(org: Team, pos: Position, personas: Persona[]): GNodeComm[] {
  return positionComms(org, pos, personas).map((c) => ({
    withName: c.counterpartName,
    archetypeLabel: c.archetypeLabel,
    hue: c.hue,
    sends: c.sends.map((f) => ({ label: f.label, transport: f.transport })),
    receives: c.receives.map((f) => ({ label: f.label, transport: f.transport })),
  }));
}

/**
 * Whether a fleet node has a LIVE terminal to open — the check that decides if clicking it morphs the
 * node into its in-graph terminal (#2534). A node is openable iff its identity pane id
 * (`<project>:<stream>` or `<project>:director`) is a live CELL of a launched fleet tab — the durable,
 * symmetric truth for BOTH workers and the DIRECTOR (#2542). Both are cells in the build tab, so both
 * open. This replaced the earlier per-pane runtime signals (roster / paneStatus / paneClaudeActive),
 * which covered workers but never the director: it isn't a stream (off the roster) and sits at "idle"
 * between prompts, so no transient runtime signal was true at click time. `livePaneIds` is the set of
 * pane ids that are cells of an open tab, minus ended/disabled panes. Pure.
 */
export function nodeHasLiveSession(paneId: string, livePaneIds: ReadonlySet<string>): boolean {
  return livePaneIds.has(paneId);
}

/**
 * Every live session pane that belongs to a project — its director + workers — so the whole fleet can be
 * ended at once (#3052). A fleet pane id is `<projectKey>:<streamId>` (fleetPaneId), so the project's
 * panes are exactly those with the `<projectKey>:` prefix. The trailing `:` makes the match EXACT: a
 * project keyed `cli` never captures `cli-typer`'s panes. Pure; the caller kills each returned pane.
 */
export function livePanesForProject(projectKey: string, livePaneIds: ReadonlySet<string>): string[] {
  if (!projectKey) return [];
  const prefix = `${projectKey}:`;
  return [...livePaneIds].filter((pid) => pid.startsWith(prefix));
}

tests.src:
import { describe, it, expect } from "vitest";
import { buildOrgFleetData, buildRealFleetData, fleetToOrg, teamToOrg, nodeHasLiveSession, livePanesForProject, withPreviewNode, PREVIEW_NODE_ID, PLANNER_NODE_ID, resolveSystemSessions, systemSessionLabel } from "@/features/glance/lib/glanceFleet";
import { buildGraph } from "@/features/glance/lib/glanceGraph";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import type { Team } from "@/features/teams";
import type { BlueprintTeam } from "@/features/planner/stages/blueprintTypes";

describe("buildRealFleetData (glance drill — real fleet)", () => {
  const personas: Persona[] = [
    { id: "p-worker", name: "Backend Engineer", blurb: "", role: "worker", startPrompt: "", skills: ["rust", "api"], model: "claude-sonnet-5", responsibilities: ["owns the API"] },
    { id: "p-reviewer", name: "Reviewer", blurb: "", role: "reviewer", startPrompt: "", skills: [] },
  ];
  const fleet = {
    recommended: 2, reasoning: "",
    streams: [
      { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [], persona: "p-worker" },
      { id: "ui", name: "UI", repo: "r", owns: [], issues: [], dependsOn: ["api"], persona: "p-worker" },
      { id: "qa", name: "QA", repo: "r", owns: [], issues: [], dependsOn: [], persona: "p-reviewer" },
    ],
    director: { enabled: true },
    edges: [{ id: "e1", from: "api", to: "ui", kind: "handoff" as const, hardness: "blocking" as const, via: "direct" as const }],
  } as unknown as FleetPlan;

  it("maps streams→nodes (role via persona), a director hub, and coordination + dependsOn edges", () => {
    const d = buildRealFleetData(fleet, personas);
    expect(d.sample).toBe(false);
    const byId = Object.fromEntries(d.rawNodes.map((n) => [n.id, n]));
    expect(byId.api.role).toBe("service");   // worker → service (colour category)
    expect(byId.api.roleLabel).toBe("worker"); // real role carried for display
    expect(byId.qa.role).toBe("data");       // reviewer → data
    expect(byId.qa.roleLabel).toBe("reviewer");
    expect(byId.director.role).toBe("infra");// director hub added
    expect(byId.director.roleLabel).toBe("director");
    // director hub: each stream is MANAGED by the director (Org archetype #2561)
    expect(d.rawEdges).toContainEqual({ from: "api", to: "director", kind: "api", archetype: "manages" });
    // dependsOn + the handoff both resolve to a single ui→api PEERS edge (deduped)
    expect(d.rawEdges.filter((e) => e.from === "ui" && e.to === "api")).toEqual([{ from: "ui", to: "api", kind: "api", archetype: "peers" }]);
  });

  it("surfaces each stream's persona on its node (#2561): name · model · skills · responsibilities", () => {
    const d = buildRealFleetData(fleet, personas);
    const api = d.rawNodes.find((n) => n.id === "api")!;
    expect(api.persona).toMatchObject({ name: "Backend Engineer", role: "worker", model: "claude-sonnet-5", skills: ["rust", "api"], responsibilities: ["owns the API"] });
    expect(api.persona!.comms!.length).toBeGreaterThan(0); // its communication surface is attached (#2563)
    // a persona with no model/responsibilities resolves to empty arrays, not undefined holes
    const qa = d.rawNodes.find((n) => n.id === "qa")!;
    expect(qa.persona).toMatchObject({ name: "Reviewer", role: "reviewer", skills: [], responsibilities: [] });
  });

  it("tags the coordination edge with its Org archetype (review→oversees, handoff→peers)", () => {
    const withReview = { ...fleet, edges: [{ id: "e2", from: "api", to: "qa", kind: "review", hardness: "blocking", via: "direct" }] } as unknown as FleetPlan;
    const d = buildRealFleetData(withReview, personas);
    // review edge producer(api)→consumer(qa) becomes qa→api, archetype OVERSEES
    expect(d.rawEdges).toContainEqual({ from: "qa", to: "api", kind: "data", archetype: "oversees" });
  });
});

describe("fleetToOrg (#2563 — the fleet-as-Org projection)", () => {
  const fleet = {
    recommended: 2, reasoning: "",
    streams: [
      { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [], persona: "p-worker" },
      { id: "ui", name: "UI", repo: "r", owns: [], issues: [], dependsOn: ["api"], persona: "p-worker" },
    ],
    director: { enabled: true },
    edges: [{ id: "e1", from: "api", to: "ui", kind: "handoff", hardness: "blocking", via: "direct" }],
  } as unknown as FleetPlan;

  it("projects streams (+ director) into positions and coordination into archetype relationships", () => {
    const org = fleetToOrg(fleet);
    expect(org.positions.map((p) => p.nodeId).sort()).toEqual(["api", "director", "ui"]);
    expect(org.positions.find((p) => p.nodeId === "api")).toMatchObject({ kind: "agent", personaId: "p-worker" });
    // the director MANAGES each stream
    expect(org.relationships).toContainEqual(expect.objectContaining({ from: "director", to: "api", archetype: "manages" }));
    expect(org.relationships).toContainEqual(expect.objectContaining({ from: "director", to: "ui", archetype: "manages" }));
    // the handoff + dependsOn between api and ui collapse to ONE peers seam
    expect(org.relationships.filter((r) => r.from === "api" && r.to === "ui")).toEqual([expect.objectContaining({ archetype: "peers" })]);
  });

  it("omits the director position + manages relationships when there is no director", () => {
    const org = fleetToOrg({ ...fleet, director: { enabled: false } });
    expect(org.positions.some((p) => p.nodeId === "director")).toBe(false);
    expect(org.relationships.some((r) => r.archetype === "manages")).toBe(false);
  });

  // ── the planner position ──────────────────────────────────────────────────
  it("has NO planner node — the drill starts at the director", () => {
    // REVERSES #glance-planner-node-per-project on the maintainer's call: the planning session authored
    // the plan but is not part of the RUNTIME picture. Nothing synthesizes it any more.
    const org = fleetToOrg(fleet);
    expect(org.positions.some((p) => p.nodeId === PLANNER_NODE_ID)).toBe(false);
    expect(org.relationships.some((r) => r.from === PLANNER_NODE_ID || r.to === PLANNER_NODE_ID)).toBe(false);
  });

  it("excludes a REAL `planner` stream too, not just the synthesized node", () => {
    // Dropping only the synthetic position would leave studio-code's real stream — named "Project
    // planning session" — sitting in exactly the same place under a different label, which is the node
    // that was asked to go. `planner` is a reserved id that no longer renders, whatever its origin.
    const org = fleetToOrg({
      ...fleet,
      streams: [
        { id: "planner", name: "Project planning session", repo: "r", owns: [], issues: [], dependsOn: [] },
        { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [] },
      ],
    } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === PLANNER_NODE_ID)).toBe(false);
    expect(org.positions.some((p) => p.label === "Project planning session")).toBe(false);
    // every OTHER stream is still managed — the exclusion is scoped to the one id
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "director", to: "api", archetype: "manages" }),
    );
  });

  it("a planner stream's edges vanish with it — the cycle that blanked the graph", () => {
    // Regression, and the reason the exclusion is by ID rather than by "was it synthesized". A real
    // `planner` stream WITH dependsOn sat below the director (director manages console, planner depends
    // on console) and above it (planner serves director), closing
    //   console -> planner -> director -> console
    // `mutualPairs` only finds 2-cycles, so this never reached layerDag's break set: measured at layer
    // 141 across 46 nodes, spreading the graph over 142 columns — an empty canvas. With the planner no
    // longer a position, `rel()` drops these on its posIds guard.
    const org = fleetToOrg({
      ...fleet,
      streams: [
        { id: "planner", name: "Planning", repo: "r", owns: [], issues: [], dependsOn: ["console"] },
        { id: "console", name: "Console", repo: "r", owns: [], issues: [], dependsOn: [] },
      ],
      edges: [{ id: "e9", from: "planner", to: "console", kind: "handoff", hardness: "blocking", via: "direct" }],
    } as unknown as FleetPlan);
    expect(org.relationships.some((r) => r.from === PLANNER_NODE_ID || r.to === PLANNER_NODE_ID)).toBe(false);
    // Everyone else's edges are untouched.
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "director", to: "console", archetype: "manages" }),
    );
  });

  it("keeps a NON-planner dependsOn edge — the skip is scoped, not a blanket drop", () => {
    const org = fleetToOrg({
      ...fleet,
      streams: [
        { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [] },
        { id: "web", name: "Web", repo: "r", owns: [], issues: [], dependsOn: ["api"] },
      ],
      edges: [],
    } as unknown as FleetPlan);
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "api", to: "web", archetype: "peers" }),
    );
  });

  it("admits an injected `debugger` session and wires it to the director like the rest", () => {
    // The debugger is app-owned but NEVER project-declared: while a request is open the caller injects
    // it into `systemSessions`, so the node appears with the queue and leaves with it. `resolveSystemSessions`
    // filters to KNOWN ids, so this only works because `debugger` is in the roles map — before that it
    // was silently dropped, which reads as "the feature does nothing".
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "debugger"] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === "debugger")).toBe(true);
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "debugger", to: "director", archetype: "serves" }),
    );
    // and it is NOT a worker — the role fallback would colour it as one
    expect(buildOrgFleetData(org, []).rawNodes.find((n) => n.id === "debugger")?.roleLabel).toBe("debugger");
  });

  it("drops the debugger again when nothing injects it — the node is not sticky", () => {
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect"] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === "debugger")).toBe(false);
  });

  it("the system sessions SERVE the director", () => {
    // The maintainer's directive: the sessions wire straight to the director, with no planning node
    // between them. `serves` (not `manages`) keeps the authority chain reading one way, and is what
    // layers them LEFT of the director.
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "integrator"] } as unknown as FleetPlan);
    for (const s of ["architect", "integrator"]) {
      expect(org.relationships).toContainEqual(
        expect.objectContaining({ from: s, to: "director", archetype: "serves" }),
      );
    }
    expect(org.relationships.some((r) => r.to === PLANNER_NODE_ID)).toBe(false);
  });

  it("a director-less fleet still renders, with the sessions simply serving nothing", () => {
    // The old code kept a planner node so the graph never "lost the agent that authored the plan".
    // Now there is no such node, so the no-director case must not leave an orphan in its place.
    const org = fleetToOrg({ ...fleet, director: { enabled: false }, systemSessions: ["architect"] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === PLANNER_NODE_ID)).toBe(false);
    expect(org.positions.some((p) => p.nodeId === "architect")).toBe(true);
    expect(org.relationships.some((r) => r.from === "architect")).toBe(false);
  });

  // ── declared system sessions ──────────────────────────────────────────────
  it("renders ONLY the system sessions the project declares, each serving the director", () => {
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "integrator"] } as unknown as FleetPlan);
    expect(org.positions.map((p) => p.nodeId).sort())
      .toEqual(["api", "architect", "director", "integrator", "ui"]);
    for (const s of ["architect", "integrator"]) {
      expect(org.relationships).toContainEqual(
        expect.objectContaining({ from: s, to: "director", archetype: "serves" }),
      );
    }
    // the ones it did NOT declare are absent — a project with no UI kit shows no designer
    expect(org.positions.some((p) => p.nodeId === "sound-designer")).toBe(false);
    expect(org.positions.some((p) => p.nodeId === "designer-react")).toBe(false);
  });

  it("declares none ⇒ renders none", () => {
    const org = fleetToOrg(fleet);
    for (const s of ["designer", "librarian", "architect", "sound-designer", "integrator"]) {
      expect(org.positions.some((p) => p.nodeId === s)).toBe(false);
    }
  });

  it("ignores an unknown system-session id rather than rendering a phantom agent", () => {
    // A typo should cost that one node, not put an agent on the graph no session can ever back.
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "architetc", ""] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === "architetc")).toBe(false);
    expect(org.positions.some((p) => p.nodeId === "architect")).toBe(true);
    // de-duped, and a MULTI-TECH kind expands to its real sessions rather than the bare kind
    expect(resolveSystemSessions(["architect", "architetc", "architect"])).toEqual(["architect"]);
    expect(resolveSystemSessions(["designer"])).toEqual(["designer-react", "designer-react-native"]);
  });

  it("renders each system session in its own role, not as a worker", () => {
    // A per-technology node keeps its KIND's role — `librarian-rust` is a librarian, not a worker.
    const data = buildOrgFleetData(
      fleetToOrg({ ...fleet, systemSessions: ["librarian"] } as unknown as FleetPlan), [],
    );
    expect(data.rawNodes.find((n) => n.id === "librarian-rust")).toMatchObject({ roleLabel: "librarian", role: "client" });
    expect(data.rawNodes.some((n) => n.id === "librarian")).toBe(false); // the bare kind is never a node
  });

  it("expands a declared kind into ONE NODE PER TECHNOLOGY, labelled", () => {
    // A project declares `designer`, but no such SESSION exists — there is design-studio:designer-react
    // and …-react-native. Rendering the bare kind gives a node that can never open anything, because the
    // pane-id map is keyed per technology. Each variant is its own openable node instead.
    const org = fleetToOrg({ ...fleet, systemSessions: ["designer", "librarian"] } as unknown as FleetPlan);
    const ids = org.positions.map((p) => p.nodeId);
    expect(ids).toEqual(expect.arrayContaining([
      "designer-react", "designer-react-native", "librarian-rust", "librarian-typescript",
    ]));
    expect(ids).not.toContain("designer");
    expect(ids).not.toContain("librarian");
    // labelled for a human, while the id stays the machine identity
    expect(org.positions.find((p) => p.nodeId === "designer-react")?.label).toBe("designer · react");
    expect(systemSessionLabel("librarian-typescript")).toBe("librarian · typescript");
    expect(systemSessionLabel("architect")).toBe("architect"); // no technologies ⇒ unchanged
    // every variant serves the director, exactly like a single-session kind
    for (const id of ["designer-react", "librarian-typescript"]) {
      expect(org.relationships).toContainEqual(
        expect.objectContaining({ from: id, to: "director", archetype: "serves" }),
      );
    }
  });

  it("places system sessions LEFT of the director, workers right", () => {
    // The arrangement is a CONSEQUENCE of `serves`, not a layout rule — so assert the layering the real
    // chain produces. Glance inverts org relationships into `from depends on to`, then reverses again
    // for layerDag, so a `serves` edge puts the server at the lower (further-left) layer.
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "integrator"] } as unknown as FleetPlan);
    const glance = buildOrgFleetData(org, []).rawEdges;               // already inverted once
    const rev = glance.map((e, i) => ({ id: `e${i}`, from: e.to, to: e.from })); // glanceGraph's reversal
    const ids = org.positions.map((p) => p.nodeId);
    const layer: Record<string, number> = Object.fromEntries(ids.map((i) => [i, 0]));
    for (let k = 0; k <= ids.length; k++) {
      let changed = false;
      for (const e of rev) {
        if (layer[e.to] < layer[e.from] + 1) { layer[e.to] = layer[e.from] + 1; changed = true; }
      }
      if (!changed) break;
    }
    expect(layer.architect).toBeLessThan(layer.director);
    expect(layer.integrator).toBeLessThan(layer.director);
    expect(layer.director).toBeLessThan(layer.api);
    expect(layer.director).toBeLessThan(layer.ui);
  });

  it("renders orchestrating agents in the ORCHESTRATE bucket, not as workers", () => {
    // Without the role fallback knowing the id, an unmatched persona falls through to `worker` and an
    // orchestrating agent would draw in the BUILD colour. The planner node is gone (it is no longer a
    // position at all), so the surviving orchestrators are the director and the system sessions.
    const data = buildOrgFleetData(fleetToOrg({ ...fleet, systemSessions: ["architect"] } as unknown as FleetPlan), []);
    expect(data.rawNodes.find((n) => n.id === "architect")?.roleLabel).toBe("architect"); // NOT the worker fallback
    // the director keeps its own fallback
    expect(data.rawNodes.find((n) => n.id === "director")).toMatchObject({ role: "infra", roleLabel: "director" });
    // a stream with no persona still falls through to worker
    expect(data.rawNodes.find((n) => n.id === "api")?.roleLabel).toBe("worker");
  });
});

