// ── the COORDINATOR COLUMN (#a-coordinator-is-a-peer-of-the-director) ────────────────────────────────
//
// The arrangement the maintainer asked for — system sessions LEFT, director and lexicographer on ONE
// column, workers and noun sessions RIGHT and in dependency order — asserted as LAYERS, because that is
// what the canvas turns into x-positions. Asserting edges instead would pass while the picture was wrong.
describe("the coordinator column", () => {
  const mk = (id: string, extra: Record<string, unknown> = {}) => ({
    id, name: id, repo: "r/x", dependsOn: [], issues: [], owns: [], commands: [], ...extra,
  });
  const PERSONAS = [
    { id: "persona-lexicographer", name: "Lex", role: "director" },
    { id: "persona-director", name: "Dir", role: "director" },
    { id: "persona-worker", name: "W", role: "worker" },
  ] as never;
  const layersOf = (fleet: unknown) => {
    const data = buildRealFleetData(fleet as never, PERSONAS);
    const g = buildGraph(data.rawNodes, data.rawEdges);
    const at = new Map<string, number>();
    for (const n of g.nodes) at.set(n.id, n.layer);
    return at;
  };

  it("puts the system sessions left, the coordinators together, and the work right", () => {
    const at = layersOf({
      director: { enabled: true },
      systemSessions: ["designer", "librarian", "architect"],
      streams: [
        mk("lexicographer", { persona: "persona-lexicographer" }),
        mk("graph", { persona: "persona-worker" }),
        mk("ui", { persona: "persona-worker", dependsOn: ["graph"] }),
      ],
    });
    const director = at.get("director")!;
    // SAME COLUMN. The lexicographer's persona carries the `director` role, so it is a peer — not a
    // report that would layer one step right.
    expect(at.get("lexicographer"), "lexicographer shares the director's column").toBe(director);
    // LEFT. Every system session serves both coordinators, and `serves` puts the server further left.
    expect(at.get("architect")!, "a system session sits left of the coordinators").toBeLessThan(director);
    // RIGHT, and ordered by dependency among themselves.
    expect(at.get("graph")!, "a worker sits right of the coordinators").toBeGreaterThan(director);
    expect(at.get("ui")!, "and a dependent worker sits right of what it depends on").toBeGreaterThan(at.get("graph")!);
  });

  it("keeps an ordinary worker OUT of the coordinator column", () => {
    // NON-VACUITY, and the thing that makes the first test mean something: the rule must key on the
    // persona's ROLE, not on being a stream. A worker-role stream is managed by the director and lands
    // one layer right of it, exactly as before this change.
    const at = layersOf({
      director: { enabled: true },
      systemSessions: ["architect"],
      streams: [mk("graph", { persona: "persona-worker" })],
    });
    expect(at.get("graph")!).toBeGreaterThan(at.get("director")!);
  });
  it("keeps the two repositories apart, with the coordinators in neither band", () => {
    // studio-code is a TWO-REPO project — its director's own role is "async integrator across two
    // repos" — so the drill must band the work by repository while leaving the cross-repo roles out of
    // both bands. A coordinator carrying a stray `repo` would render as a peer of the director in the
    // column AND inside one repository's band, which is the picture contradicting itself.
    const fleet = {
      director: { enabled: true },
      systemSessions: ["architect"],
      streams: [
        // Deliberately DECLARES a repo: the rule must override it, not depend on the data being right.
        mk("lexicographer", { persona: "persona-lexicographer", repo: "kevinthelago/base-studio-code" }),
        mk("graph", { persona: "persona-worker", repo: "kevinthelago/base-studio-code" }),
        mk("mobile-tunnel", { persona: "persona-worker", repo: "kevinthelago/mobile-studio-code" }),
      ],
    } as never;
    const data = buildRealFleetData(fleet as never, PERSONAS);
    const byId = new Map(data.rawNodes.map((n) => [n.id, n as { repo?: string }]));
    expect(byId.get("graph")?.repo, "a worker keeps its repository").toBe("kevinthelago/base-studio-code");
    expect(byId.get("mobile-tunnel")?.repo, "and the mobile worker keeps its own").toBe("kevinthelago/mobile-studio-code");
    expect(byId.get("lexicographer")?.repo, "a coordinator is ungrouped even when it declares one").toBeUndefined();
    expect(byId.get("director")?.repo, "as the director already is").toBeUndefined();
  });
});

// A project with NO planned fleet drills into an EMPTY graph — never an invented team.
//
// THE BUG: the no-fleet branch fell back to `buildFleetData`, a SAMPLE generator that emitted a
// director, a reviewer, an auditor and 2-4 `worker-N` nodes whose count was a hash of the project id.
// It carried `sample: true`, which earned only a small "sample topology · preview" chip — nowhere near
// enough to stop invented agents reading as this project's real team. The maintainer met it as "team
// nodes that don't or shouldn't exist. it's the director that should choose their team."
//
// The architect's fresh project was guaranteed to land there: `bsc fleet director new` builds its
// FleetPlan as a LAUNCH INPUT and deliberately does not write plan.db, so a just-handed-off project
// has a running director and no stored fleet at all.
//
// THERE IS NO FALLBACK NOW, and the generator is deleted rather than left unreachable. The graph shows
// what exists; until the director designs a team there is nothing to show.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import * as glanceFleet from "@/features/glance/lib/glanceFleet";

const GLANCE: string = JSON.parse(
  readFileSync("src-tauri/data/components/app/features/glance/glancepage.json", "utf8"),
).srcText;

describe("the no-fleet drill invents nothing", () => {
  it("has no sample-fleet generator left to call", () => {
    // Deleted, not merely unreferenced: an unreachable generator is one import away from returning.
    expect("buildFleetData" in glanceFleet).toBe(false);
  });

  it("draws an EMPTY graph rather than substituting a topology", () => {
    // Not even a synthesized director: a node no plan asserts is still a node the user did not put
    // there. `composed` present ⇒ the real builder; absent ⇒ nothing.
    expect(GLANCE).toMatch(/const EMPTY_FLEET_DATA = \{ rawNodes: \[\], rawEdges: \[\], sample: false \}/);
    expect(GLANCE).toMatch(/: EMPTY_FLEET_DATA;/);
  });

  it("keeps the real builder for a project that HAS a fleet", () => {
    // The fix must not cost a planned fleet its graph — that path is untouched.
    expect(GLANCE).toMatch(/buildRealFleetData\(composed, personas, drillTeam\)/);
    expect(typeof glanceFleet.buildRealFleetData).toBe("function");
  });
});

// A fleet-less project draws the director IT ACTUALLY HAS — and nothing it does not.
//
// THREE answers have lived at this branch, and the first two were wrong in opposite directions:
//   v1  `buildFleetData` FABRICATED a reviewer, an auditor and 2-4 hash-counted workers.
//   v2  a substituted director-only plan ASSUMED every project has a director.
//   v3  drawing nothing HID a director that was demonstrably running (pain-point-finder, pid 3082124,
//       LIVE in `bsc fleet directors`, with `(no fleet)` in its plan store).
//
// THE RULE: draw a node when a SESSION EXISTS FOR IT. Never from an assumed plan, never from a
// generated topology. `livePaneIds` is the evidence — tab membership, which GlanceWorkspace documents
// as "a durable, symmetric this-agent-has-a-terminal signal for BOTH workers AND the DIRECTOR", added
// because the director is not a stream and idles between prompts.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { buildRealFleetData } from "@/features/glance/lib/glanceFleet";

const GLANCE: string = JSON.parse(
  readFileSync("src-tauri/data/components/app/features/glance/glancepage.json", "utf8"),
).srcText;

describe("the fleet-less drill", () => {
  it("decides from an existing PANE, not from an assumed plan", () => {
    // The evidence, and it must be the drilled project's own director pane.
    expect(GLANCE).toMatch(/const hasDirectorPane = !!drill && livePaneIds\.has\(fleetPaneId\(drill, "director"\)\)/);
  });

  it("draws the director when its pane exists, and nothing when it does not", () => {
    expect(GLANCE).toMatch(/: hasDirectorPane\s*\n\s*\? buildRealFleetData\(DIRECTOR_ONLY_FLEET, personas, drillTeam\)\s*\n\s*: EMPTY_FLEET_DATA;/);
    expect(GLANCE).toMatch(/const EMPTY_FLEET_DATA = \{ rawNodes: \[\], rawEdges: \[\], sample: false \}/);
  });

  it("re-runs the graph when a director appears or goes, not on every liveness poll", () => {
    // A boolean in the deps, never the whole `livePaneIds` set: the set churns on every poll, and the
    // base graph is deliberately separate from the liveness overlay applied downstream.
    //
    // `surfaceRoster` joined the list and is allowed for the SAME reason, not as an exception: its
    // setter keeps the previous reference when the roster is unchanged, so it cannot churn either.
    // Anything appended here must clear that bar — a value that gets a new reference per poll would
    // rebuild the whole drill graph on a timer.
    // `planFeatures` / `planStreams` joined for the SAME reason `surfaceRoster` did, and had to clear
    // the same bar: both setters keep the PREVIOUS reference when the plan is unchanged (comparing
    // slugs, and stream id + feature), so neither can hand the memo a new array on a timer. A feature
    // roster changes when someone edits the plan, so "no change" is the common case and costs nothing.
    expect(GLANCE).toMatch(/activeDebugRequests, drill, hasDirectorPane, surfaceRoster, planFeatures, planStreams\]\);/);
    // The bar itself, asserted rather than described: each new value's setter must return `prev` on a
    // no-op. A setter that always built a fresh array would satisfy the deps line above and still
    // rebuild the drill every poll — which is the failure this test exists to prevent, not the spelling.
    for (const setter of ["setPlanFeatures", "setPlanStreams"]) {
      const body = GLANCE.slice(GLANCE.indexOf(`${setter}((prev)`));
      expect(body.slice(0, 400), `${setter} must keep the old reference when nothing changed`).toMatch(/\? prev\b/);
    }
    expect(GLANCE).not.toMatch(/activeDebugRequests, drill, livePaneIds\]/);
  });

  it("yields exactly one node — the director — on the real builder", () => {
    // Not a hand-rolled node: `fleetToOrg` already emits precisely this for `director.enabled` with no
    // streams, on the id `fleetPaneId` resolves to `<project>:director`, so it morphs like any other.
    const data = buildRealFleetData(
      { recommended: 0, reasoning: "", streams: [], director: { enabled: true } },
      [],
    );
    expect(data.rawNodes.map((n) => n.id)).toEqual(["director"]);
    expect(data.rawEdges).toEqual([]);
  });

  it("still invents nothing — no sample generator survives", () => {
    expect(GLANCE).not.toMatch(/buildFleetData\(/);
  });
});

