describe("nodeStateWord (#3957)", () => {
  const n = (health: GHealth, activity: GActivity, rollupHealth?: GHealth) =>
    ({ health, activity, rollupHealth: rollupHealth ?? health });

  it("a degraded node reads its HEALTH word, never its reason", () => {
    // The bug: the slot is 108px/nowrap/ellipsis, so a reason didn't overflow — it truncated.
    // "waiting on 2 upstreams to land (domain-model…" rendered as "waiting on 2 upstre…".
    expect(nodeStateWord(n("warning", "building"))).toBe("warning");
    expect(nodeStateWord(n("error", "idle"))).toBe("error");
  });

  it("a healthy node still reads its ACTIVITY word", () => {
    expect(nodeStateWord(n("healthy", "building"))).toBe(ACTIVITY_META.building.label);
    expect(nodeStateWord(n("healthy", "waiting"))).toBe(ACTIVITY_META.waiting.label);
  });

  it("a deactivated node keeps its own word — the DIMMING says it is off (#4034)", () => {
    // #3239 spent the node's one word slot on "off". But a deactivated node is already dimmed in place
    // (`offOpacity`), so the word was redundant — and it cost the more useful fact: a node that was off
    // AND complete read "off" and lost the completion entirely. The dimming carries deactivation now;
    // the word carries what the node IS.
    expect(nodeStateWord(n("healthy", "building", "off"))).toBe(ACTIVITY_META.building.label);
    expect(nodeStateWord(n("healthy", "complete", "off"))).toBe(ACTIVITY_META.complete.label);
    // A node that is off AND genuinely degraded still reports the fault — that outranks activity.
    expect(nodeStateWord(n("error", "idle", "off"))).toBe(HEALTH_META.error.label);
  });

  it("a node degraded only by a DEPENDENCY keeps its own word", () => {
    // `health` is the node's own axis; `rollupHealth` folds in dependencies. A healthy node must not
    // read "warning" because something upstream is degraded — that is what the rollup DOT is for.
    expect(nodeStateWord(n("healthy", "building", "warning"))).toBe(ACTIVITY_META.building.label);
  });

  it("only ever returns a FIXED label — never free text", () => {
    // The real invariant. Not "one word": `ACTIVITY_META` legitimately carries "in review". What must
    // never happen is a `reason` (or any other caller-supplied string) reaching this slot, because the
    // slot truncates at 108px and free text becomes an unreadable fragment.
    const known = new Set([
      ...Object.values(HEALTH_META).map((m) => m.label),
      ...Object.values(ACTIVITY_META).map((m) => m.label),
    ]);
    const healths: GHealth[] = Object.keys(HEALTH_META) as GHealth[];   // #4042: derive, so a new/removed state is covered automatically
    const acts: GActivity[] = Object.keys(ACTIVITY_META) as GActivity[];
    for (const h of healths) for (const a of acts) {
      for (const roll of [undefined, ...healths]) {
        expect(known).toContain(nodeStateWord(n(h, a, roll)));
      }
    }
  });
});

describe("showsBuildingPulse (#4015)", () => {
  const ctx = { fleet: true, isOff: false, isError: false };

  it("pulses a building WORKER and nothing else", () => {
    expect(showsBuildingPulse({ activity: "building" }, ctx)).toBe(true);
    for (const a of ["idle", "planning", "waiting", "review", "live"] as const) {
      expect(showsBuildingPulse({ activity: a }, ctx)).toBe(false);
    }
  });

  it("stops when the worker parks into maintenance", () => {
    // Maintenance resolves to plain `idle` (agentStall), so the pulse stopping falls straight out of
    // the activity — which is why this keys on activity rather than on a separate flag.
    expect(showsBuildingPulse({ activity: "idle" }, ctx)).toBe(false);
  });

  it("NEVER animates an L0 project node, however busy the project is", () => {
    // The reason this is a prop and not `n.category`: an unclassified project has no category either,
    // so inferring would animate exactly the L0 nodes it was meant to exclude.
    expect(showsBuildingPulse({ activity: "building" }, { ...ctx, fleet: false })).toBe(false);
  });

  it("yields to error and stays off a deactivated node", () => {
    expect(showsBuildingPulse({ activity: "building" }, { ...ctx, isError: true })).toBe(false);
    expect(showsBuildingPulse({ activity: "building" }, { ...ctx, isOff: true })).toBe(false);
  });
});

describe("resolveGridAnchor (a vanished anchor must not blank every morph)", () => {
  const present = new Set(["a", "b", "c"]);

  it("keeps the stored anchor while its node is still in the graph", () => {
    expect(resolveGridAnchor("b", ["b", "c"], present)).toBe("b");
  });

  // THE BUG: the anchor is retained after its own morph closes, so the id outlives the node. The old
  // lookup returned null here and the caller dropped EVERY open morph, permanently.
  it("falls back to a surviving placement when the anchor has left the graph", () => {
    expect(resolveGridAnchor("gone", ["gone", "c"], present)).toBe("c");
  });

  it("falls back in PLACEMENT order, so the choice is deterministic across renders", () => {
    expect(resolveGridAnchor("gone", ["b", "c"], present)).toBe("b");
    expect(resolveGridAnchor("gone", ["c", "b"], present)).toBe("c");
  });

  it("handles never having had an anchor — the first open resolves one", () => {
    expect(resolveGridAnchor(null, ["c"], present)).toBe("c");
  });

  it("returns null ONLY when nothing resolves — the honest empty grid", () => {
    expect(resolveGridAnchor("gone", ["also-gone"], present)).toBeNull();
    expect(resolveGridAnchor(null, [], present)).toBeNull();
    expect(resolveGridAnchor("a", [], new Set())).toBeNull();
  });
});

// The INTEGRATION band vocabulary (`an-integration-is-a-glance-node-with-a-real-signal`).
//
// These pin the decisions that were live alternatives, each of which would have been wrong in a way
// nothing else would catch: reusing the `service` kind (already taken by a hand-declared endpoint),
// reusing `library` (a cross-graph algorithm or sound), and keying on a bare slug (`stripe` is a valid
// project key, so the namespace is the only thing keeping them apart).
import { describe, it, expect } from "vitest";
import {
  INTEGRATION_META,
  INTEGRATION_NODE_PREFIX,
  integrationNodeId,
  integrationIdOfNode,
  usesIntegrationEdgeId,
  bandNodeMeta,
  isBandNode,
  isBandEdge,
  EDGE_META,
  MCP_META,
  SERVICE_META,
  SURFACE_META,
  LIBRARY_META,
  type GNodeKind,
} from "@/features/glance/lib/glanceGraph";

describe("the integration band", () => {
  it("is its own kind, not a reuse of service, surface or library", () => {
    const kind: GNodeKind = "integration";
    expect(bandNodeMeta({ kind })).toBe(INTEGRATION_META);
    // `service` is the near-miss and the one that would have been chosen by default: a hand-declared
    // endpoint with a URL. An integration is backed by a probed, tried, registered manifest and can
    // report what it last verified, which a service node structurally cannot carry.
    expect(bandNodeMeta({ kind })).not.toBe(SERVICE_META);
    expect(bandNodeMeta({ kind })).not.toBe(MCP_META);
    expect(bandNodeMeta({ kind })).not.toBe(SURFACE_META);
    expect(bandNodeMeta({ kind })).not.toBe(LIBRARY_META.algo);
  });

  it("renders in the fenced band, and its edge routes there too", () => {
    expect(isBandNode({ kind: "integration" })).toBe(true);
    expect(isBandEdge("uses-integration")).toBe(true);
  });

  it("carries a full presentation row with an accent no neighbouring dimension uses", () => {
    for (const [field, value] of Object.entries(INTEGRATION_META)) {
      expect(typeof value, `${field} must be a string`).toBe("string");
      expect(value.length, `${field} must not be blank`).toBeGreaterThan(0);
    }
    const others = [MCP_META.color, SERVICE_META.color, SURFACE_META.color, ...Object.values(LIBRARY_META).map((m) => m.color)];
    expect(others).not.toContain(INTEGRATION_META.color);
  });

  it("namespaces its node id, because a bare integration slug IS a valid project key", () => {
    expect(integrationNodeId("stripe")).toBe("integration:stripe");
    expect(INTEGRATION_NODE_PREFIX).not.toBe("");
    expect(integrationIdOfNode(integrationNodeId("stripe"))).toBe("stripe");
    // An unprefixed id passes through unchanged rather than being mangled.
    expect(integrationIdOfNode("stripe")).toBe("stripe");
  });

  it("keys its edge on BOTH ends, since one integration is routinely declared by several projects", () => {
    expect(usesIntegrationEdgeId("storefront", "stripe")).not.toBe(usesIntegrationEdgeId("billing", "stripe"));
    expect(usesIntegrationEdgeId("storefront", "stripe")).toBe(usesIntegrationEdgeId("storefront", "stripe"));
  });

  it("has an EDGE_META row, or the edge renders as an unlabelled line", () => {
    // The whole-program check is what caught this being missed for `depends-on`; assert it here so a
    // test sees it too, since only tsc executes that map otherwise.
    expect(EDGE_META["uses-integration"]).toBeDefined();
    expect(EDGE_META["uses-integration"].color).toBe(INTEGRATION_META.color);
    expect(EDGE_META["uses-integration"].label.length).toBeGreaterThan(0);
  });
});

// The COMMAND-SURFACE band vocabulary (`epic-command-surfaces-are-nodes`, slice 1).
//
// One node per CRATE — the 2026-09-01 decision. The node's job is MAINTENANCE, so every workspace
// member gets one and not only the 37 that expose verbs: `bsc-util` exposes none and is the crate
// whose change reaches most of the workspace, which makes it exactly the one that needs an owner.
// "Has verbs" is a facet, not the criterion for existing.
//
// These assertions are about the VOCABULARY, which is what the node builder will be written against.
// Two of them exist because the alternatives were live possibilities and each would have been wrong
// in a way nothing else would catch: reusing the `library` kind (already taken by cross-graph
// algorithm/sound nodes), and keying on a bare crate name (indistinguishable from a project key).
import { describe, it, expect } from "vitest";
import {
  SURFACE_META,
  SURFACE_NODE_PREFIX,
  surfaceNodeId,
  surfaceCrateOfNode,
  bandNodeMeta,
  isBandNode,
  LIBRARY_META,
  MCP_META,
  SERVICE_META,
  type GNodeKind,
} from "@/features/glance/lib/glanceGraph";

describe("the command-surface band", () => {
  it("is its own kind, not a reuse of `library`", () => {
    // `library` already means a cross-graph algorithm or sound node. Reusing it would put crates in
    // the same band as `@bsc/algorithms/fibonacci`, which is a different dimension entirely.
    const kind: GNodeKind = "surface";
    expect(bandNodeMeta({ kind })).toBe(SURFACE_META);
    expect(bandNodeMeta({ kind })).not.toBe(LIBRARY_META.algo);
    expect(bandNodeMeta({ kind })).not.toBe(MCP_META);
    expect(bandNodeMeta({ kind })).not.toBe(SERVICE_META);
  });

  // REVERSED 2026-09-02 by the maintainer: "lets treat these like normal nodes, instead of placing
  // them in a box. they should flow within the graph." Kept as an assertion rather than deleted, so
  // the decision is visible where the old one was — this is the second time this graph has fenced
  // something that belonged with the work (`architect-sits-with-the-projects` was the first).
  //
  // The band is for a shared DEPENDENCY the projects CONSUME. A crate is not consumed by the project;
  // it IS the project, decomposed.
  it("does NOT render in the fenced band — a crate flows with the graph", () => {
    expect(isBandNode({ kind: "surface" })).toBe(false);
  });

  it("carries a full presentation row, so the inspector has nothing to invent", () => {
    for (const [field, value] of Object.entries(SURFACE_META)) {
      expect(typeof value, `${field} must be a string`).toBe("string");
      expect(value.length, `${field} must not be blank`).toBeGreaterThan(0);
    }
    // Its accent must not collide with a neighbouring dimension, or two bands read as one.
    const others = [MCP_META.color, SERVICE_META.color, ...Object.values(LIBRARY_META).map((m) => m.color)];
    expect(others).not.toContain(SURFACE_META.color);
  });

  /** A bare crate name is a valid project key (`[a-z0-9-]`, no colon), so the namespace is load-bearing. */
  it("namespaces its id so a crate can never collide with a project key", () => {
    expect(surfaceNodeId("bsc-util")).toBe("surface:bsc-util");
    expect(surfaceNodeId("bsc-util")).not.toBe("bsc-util");
    expect(surfaceNodeId("studio-code")).toContain(":");
  });

  it("round-trips the crate out of a node id", () => {
    for (const crate of ["bsc-util", "plandb", "base-studio-code", "bsc-data", "bsc-llm"]) {
      expect(surfaceCrateOfNode(surfaceNodeId(crate))).toBe(crate);
    }
    // An id that carries no prefix comes back unchanged rather than being silently truncated.
    expect(surfaceCrateOfNode("bsc-util")).toBe("bsc-util");
    expect(SURFACE_NODE_PREFIX.endsWith(":")).toBe(true);
  });

  /**
   * The key is the cargo PACKAGE name. Three names are in play and only this one is right: the
   * DIRECTORY differs for `crates/data` (bsc-data) and `crates/llm` (bsc-llm), and the LIB TARGET
   * differs again for llm, whose dispatch arm is `llm::cli::run`. Keying on either of the others
   * gets llm wrong and looks right everywhere else.
   */
  it("keys on the package name, which is not always the directory", () => {
    expect(surfaceNodeId("bsc-data")).toBe("surface:bsc-data");
    expect(surfaceNodeId("bsc-llm")).toBe("surface:bsc-llm");
    // The app crate's package is `base-studio-code`, not `src-tauri`.
    expect(surfaceCrateOfNode(surfaceNodeId("base-studio-code"))).toBe("base-studio-code");
  });
});

// EVERY NODE KIND HAS A READING POSITION.
//
// The Glance sidebar groups by type, and the order is a decision — what the project is built ON, then
// what it IS, then who runs it. A kind with no rank would fall to an unspecified position that a
// reader would take for a judgement someone made.
//
// `Record<GNodeKind, number>` already makes an omission a compile error. This adds the two things the
// type cannot say: that the ORDER is the intended one, and that the sort actually applies it.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { NODE_KIND_ORDER, nodeKindRank } from "@/features/glance/lib/glanceGraph";

describe("NODE_KIND_ORDER", () => {
  it("ranks every kind the graph can produce", () => {
    // The union, read off the source rather than restated — a kind added to `GNodeKind` and forgotten
    // here is exactly what this guards, and a hand-copied list would forget it too.
    const seed = JSON.parse(readFileSync("src-tauri/data/knowledge/algorithms.json", "utf8")) as {
      implementations: { id: string; code?: string }[];
    };
    const src = seed.implementations.find((i) => i.id === "glance-graph.ts")?.code ?? "";
    const decl = /export type GNodeKind =([^;]+);/.exec(src);
    expect(decl, "GNodeKind not found — this guard is reading the wrong shape").not.toBeNull();
    const kinds = [...decl![1].matchAll(/"(\w[\w-]*)"/g)].map((m) => m[1]);
    expect(kinds.length).toBeGreaterThan(5);
    for (const k of kinds) {
      expect(NODE_KIND_ORDER[k as keyof typeof NODE_KIND_ORDER], `\`${k}\` has no reading position`).toBeTypeOf("number");
    }
  });

  it("reads dependencies → the program → its decomposition → the actors", () => {
    const r = NODE_KIND_ORDER;
    // A library is consumed and owned elsewhere; an MCP/service/integration is the same kind of thing,
    // so it sits beside one rather than among the project's own parts.
    expect(r.library).toBe(r.kit);
    expect(r.mcp).toBe(r.service);
    expect(r.mcp).toBe(r.integration);
    expect(r.library).toBeLessThan(r.mcp);
    // The program, then how it is decomposed, then who operates it.
    expect(r.mcp).toBeLessThan(r.feature);
    expect(r.feature).toBeLessThan(r.surface);
    expect(r.surface).toBeLessThan(r.session);
    expect(r.session).toBe(r.architect);
  });

  it("sorts a kind-less node LAST, not first", () => {
    // Rank 0 would put an unknown node at the top of the list, which reads as "most fundamental".
    expect(nodeKindRank({})).toBeGreaterThan(NODE_KIND_ORDER.session);
  });

  it("the sidebar actually applies it", () => {
    // A ranking nothing sorts by is a table of numbers. This repo has shipped that exact shape twice
    // (`featureBand` and `featureDrill`, each tested and uncalled), so the call site is asserted.
    const seed = JSON.parse(readFileSync("src-tauri/data/components/app/features/glance/glancepage.json", "utf8")) as
      | { srcText?: string }
      | { srcText?: string }[];
    const rec = Array.isArray(seed) ? seed[0] : seed;
    expect(rec.srcText ?? "").toContain("nodeKindRank(a) - nodeKindRank(b)");
  });
});

