// Node-parting geometry (#2671, supersedes the #2666 d3-force relaxation) — when the terminal morph GROWS
// in the graph (#2534/#2662), the neighbourhood PARTS to make room in four rigid "curtains" (left/right/
// up/down), split by the panel's aspect-scaled diagonals. Each curtain translates as ONE block by the
// clearance its most-penetrating member needs, so:
//   1. every neighbour clears the panel BY CONSTRUCTION — a hard guarantee the old soft, alpha-scaled
//      force could not make (it settled at equilibrium with residual penetration → the visible clipping);
//   2. nodes never clip INTO each other either — a curtain shifts RIGIDLY, so members keep their exact
//      relative spacing (the whole region slides aside, like curtains parting), and orthogonal curtains
//      move away from their shared diagonal.
// Closed-form + deterministic (no simulation, no tuning knobs): the same rect always yields the same
// offsets — no jitter — and it's cheap enough to recompute live during a resize drag. Pure (React/DOM-
// free) so the clearance guarantee + the rigid spacing are unit-tested in isolation. The canvas animates
// each node's offset AND the panel's grow off one matched easing, so the two read as a single motion.
import { NW, NH } from "@/features/glance/lib/glanceGraph";

/** The expanded panel's world box — reported by the morph, consumed by the canvas. */
export interface MorphRect { left: number; top: number; w: number; h: number }

/** Clearance (world px) every neighbour keeps from the expanded terminal panel. */
export const PUSH_MARGIN = 36;

type Dir = "left" | "right" | "up" | "down";

/**
 * Per-node box offset so the graph PARTS to make room for the open panel `rect` — the four-curtain model.
 * Each neighbour is assigned to a curtain by which side of the panel it sits on (the panel's aspect-scaled
 * diagonals decide the dominant axis), then every curtain translates as one rigid block by the largest
 * clearance any of its members needs. Result: the panel is cleared by construction (no node clips into it)
 * and every curtain keeps its internal spacing (no node clips into a neighbour). Returns a
 * `nodeId → {dx,dy}` map of the NON-ZERO shifts only. Pure + deterministic.
 *
 * `rect` is the region to clear. Since #3361 that is the whole OCCUPIED GRID REGION (the bounding box of
 * every open morph's slot), not a single free-floating panel — the four-curtain model is indifferent to
 * how large the region is, so parting around N morphs is the same computation as parting around one.
 *
 * `exclude` are the nodes sitting UNDER the region — the grown nodes themselves — which must not be
 * pushed. Accepts one id or a set (the multi-morph case).
 */
export function partAroundPanel(
  nodes: { id: string; x: number; y: number }[],
  rect: MorphRect,
  exclude?: string | ReadonlySet<string>,
): Map<string, { dx: number; dy: number }> {
  const excluded = typeof exclude === "string" ? new Set([exclude]) : exclude;
  const out = new Map<string, { dx: number; dy: number }>();
  const cx0 = rect.left + rect.w / 2, cy0 = rect.top + rect.h / 2;
  const hx = rect.w / 2, hy = rect.h / 2;
  // The Minkowski-expanded forbidden box for a node CENTRE: the panel grown by the node's half-extent +
  // the margin. A node centre inside this box means its card overlaps the panel (within the margin).
  const fx0 = rect.left - NW / 2 - PUSH_MARGIN, fx1 = rect.left + rect.w + NW / 2 + PUSH_MARGIN;
  const fy0 = rect.top - NH / 2 - PUSH_MARGIN, fy1 = rect.top + rect.h + NH / 2 + PUSH_MARGIN;

  // Pass 1 — assign each node to a curtain and record the max clearance that curtain must provide.
  const need: Record<Dir, number> = { left: 0, right: 0, up: 0, down: 0 };
  const dirOf = new Map<string, Dir>();
  for (const n of nodes) {
    if (excluded?.has(n.id)) continue;
    const cx = n.x + NW / 2, cy = n.y + NH / 2;
    // Wedge by the panel's diagonals, scaled to its aspect: whichever axis the node is more displaced
    // along (relative to the panel's half-size) wins, so the split lines run corner-to-corner.
    const dir: Dir =
      Math.abs(cx - cx0) / hx >= Math.abs(cy - cy0) / hy
        ? (cx < cx0 ? "left" : "right")
        : (cy < cy0 ? "up" : "down");
    dirOf.set(n.id, dir);
    // If this node overlaps the panel, the distance to slide it out of the forbidden box along its
    // curtain's OWN axis (always positive for an overlapper, since its centre is inside the box).
    if (cx > fx0 && cx < fx1 && cy > fy0 && cy < fy1) {
      const exit = dir === "left" ? cx - fx0 : dir === "right" ? fx1 - cx : dir === "up" ? cy - fy0 : fy1 - cy;
      if (exit > need[dir]) need[dir] = exit;
    }
  }

  // Pass 2 — every member of a curtain takes that curtain's block shift (rigid → spacing preserved).
  const vec: Record<Dir, { dx: number; dy: number }> = {
    left: { dx: -need.left, dy: 0 }, right: { dx: need.right, dy: 0 },
    up: { dx: 0, dy: -need.up }, down: { dx: 0, dy: need.down },
  };
  for (const n of nodes) {
    const dir = dirOf.get(n.id);
    if (!dir) continue;
    const v = vec[dir];
    if (v.dx || v.dy) out.set(n.id, v);
  }
  return out;
}

// The glancepage PROJECTION (#the-glance-record-lost-the-architect-and-four-other-fixes).
//
// WHY THIS EXISTS. Glance does not render `GlanceWorkspace.tsx`. `lazyWorkspaces.tsx` aliases the
// workspace to `GlanceGraphHost`, which renders `<GraphComponent id="glancepage" />` (#4185, epic
// #3604) — so the running cockpit is the `glancepage` RECORD, and the `.tsx` is its source of truth
// only if something keeps the two in step. Nothing did. The record was last mirrored by hand in
// bc3f38d1 (2026-08-12) and then drifted for weeks, silently losing the architect drill
// (#architect-node-expands-into-system-sessions), the contract re-read
// (#architect-wires-project-relationships), plan.db outranking the persisted fleet, the progress
// ref-namespace split, and the director progress fallback. Every one of those was live in `src/`
// and dead in the app.
//
// THE RECORD IS A PROJECTION, NOT A COPY, and all three differences below are deliberate — reproduce
// them or the page breaks:
//
//   1. The AS GRAPH SOURCE preamble, which tells a reader of the record where its behaviour comes from.
//   2. First-party RELATIVE specifiers rewritten ABSOLUTE. The runtime loader resolves a record's
//      imports against the app's module registry, not against a directory, so `./lib/glanceData` has
//      no meaning to it. Sibling COMPONENTS resolve differently again — as `@/components/<record-id>`
//      graph records, not as feature paths — which is why they need their own map rather than the
//      same prefix rule.
//   3. `import "@/features/glance/lib/glance.css"` STRIPPED. The loader cannot resolve a CSS side-effect import;
//      `GlanceGraphHost` owns the stylesheet instead (see its header).
//
// Keeping this as a pure function, rather than inline in the generator, is what lets the guard test
// assert the record IS the projection — the check that would have caught the drift.

/** The record's preamble — four lines, verbatim, ahead of the file's own header. */
export const GRAPH_SOURCE_HEADER = [
  "// Glance → the cockpit workspace (#2206), AS GRAPH SOURCE (#4185, epic #3604). Transcribed from the live feature file: the runtime",
  "// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui",
  "// design system + the store via appModules, the glance lib/hook surface via the glance graph-platform,",
  "// and the sibling components as @/components/* graph records). Behaviour runs here.",
];

/** Sibling COMPONENTS resolve as graph records (`@/components/<id>`), not as feature paths. A sibling
 *  added to `GlanceWorkspace.tsx` without an entry here would be rewritten to a feature path that the
 *  loader cannot resolve, so {@link projectGlancePage} throws rather than emitting a broken record. */
export const SIBLING_RECORDS: Record<string, string> = {
  "./GlanceCanvas": "@/components/glance-canvas",
  "./GlanceChatDock": "@/components/glance-chat-dock",
};

/** Relative specifiers that are NOT sibling components resolve as feature paths under the glance slice. */
const FEATURE_PREFIX = "@/features/glance/";

/** The CSS side-effect import the loader cannot resolve — dropped; the host imports it instead. */
const CSS_IMPORT = 'import "@/features/glance/lib/glance.css";';

/**
 * Project `GlanceWorkspace.tsx` source into the `glancepage` record's `srcText`.
 *
 * @param src the file's verbatim contents (LF-normalized by the caller).
 * @returns the record source: preamble + the file with its relative imports resolved and the CSS
 *   side-effect import removed.
 * @throws if a relative specifier points OUT of the glance slice (`../`), which the record has no way
 *   to express — better to fail the generator than to emit a record that compiles to the wrong module.
 */
export function projectGlancePage(src: string): string {
  const out: string[] = [];
  for (const line of src.replace(/\r\n/g, "\n").split("\n")) {
    if (line.trim() === CSS_IMPORT) continue;
    out.push(rewriteSpecifier(line));
  }
  return [...GRAPH_SOURCE_HEADER, ...out].join("\n");
}

/** Rewrite one line's relative import specifier, if it has one. */
function rewriteSpecifier(line: string): string {
  return line.replace(/from "(\.\.?\/[^"]+)"/, (_match, spec: string) => {
    if (SIBLING_RECORDS[spec]) return `from "${SIBLING_RECORDS[spec]}"`;
    if (spec.startsWith("../")) {
      throw new Error(
        `glancepage projection: cannot express the out-of-slice specifier ${spec}. A record resolves ` +
        `against the module registry, so an import that leaves the glance slice needs an explicit ` +
        `@/… path in GlanceWorkspace.tsx, or an entry in SIBLING_RECORDS if it is a graph component.`,
      );
    }
    return `from "${FEATURE_PREFIX}${spec.slice(2)}"`;
  });
}

// glTF / scene renderer (#581 PV-gltf).
//
// Mounts a persistent iframe that runs three.js (loaded from esm.sh via import-map)
// and receives glTF data via postMessage. The iframe stays mounted between updates;
// each render_gltf command replaces the previous model without reloading the runtime.
//
// Payload shape: { url?: string; base64?: string }
//   url    — a URL the iframe can fetch (same-origin or CORS-enabled).
//   base64 — raw glTF JSON or binary GLB, base64-encoded.
//            The iframe constructs a data URI: data:model/gltf+json;base64,<base64>.

import type { PreviewRenderer, RendererHandle } from '@/features/planner/preview/registry';
import type { RenderableChunk, PreviewStatus } from '@/features/planner/preview/types';
import { buildGltfRuntimeHtml } from '@/features/planner/preview/streamingRuntime';

type GltfPayload = { url?: string; base64?: string };

function createGltfRenderer(): PreviewRenderer {
  return {
    kind: ['gltf', 'scene'],

    mount(container: HTMLElement, initial: RenderableChunk): RendererHandle {
      const iframe = document.createElement('iframe');
      iframe.title = 'glTF preview';
      // allow-scripts: run three.js; no host access.
      iframe.setAttribute('sandbox', 'allow-scripts');
      iframe.style.cssText = 'flex:1;width:100%;height:100%;border:none;background:#0d0d0f';
      container.style.cssText = 'display:flex;flex:1;min-height:0';
      container.appendChild(iframe);

      let statusCb: ((s: PreviewStatus) => void) | undefined;
      let runtimeReady = false;
      let pendingChunk: RenderableChunk | null = null;

      // Bootstrap the three.js runtime.
      iframe.srcdoc = buildGltfRuntimeHtml();

      function sendGltf(payload: GltfPayload) {
        iframe.contentWindow?.postMessage(
          { __preview_cmd: 'render_gltf', url: payload.url, base64: payload.base64 },
          '*',
        );
      }

      function onMsg(e: MessageEvent) {
        const d = e.data as { __preview?: string; message?: unknown } | null;
        if (!d || typeof d !== 'object') return;
        if (d.__preview === 'runtime_ready') {
          runtimeReady = true;
          if (pendingChunk) {
            sendGltf(pendingChunk.payload as GltfPayload);
            pendingChunk = null;
          }
        } else if (d.__preview === 'ready') {
          statusCb?.({ status: 'ready' });
        } else if (d.__preview === 'error') {
          statusCb?.({ status: 'error', message: String(d.message ?? '') });
        }
      }
      window.addEventListener('message', onMsg);

      // Apply initial chunk once runtime is ready.
      const initPayload = initial.payload as GltfPayload;
      if (initPayload.url || initPayload.base64) {
        if (runtimeReady) {
          sendGltf(initPayload);
        } else {
          pendingChunk = initial;
        }
      }

      const handle: RendererHandle = {
        update(chunk: RenderableChunk) {
          const p = chunk.payload as GltfPayload;
          if (!runtimeReady) {
            pendingChunk = chunk;
          } else {
            sendGltf(p);
          }
        },
        onStatus(cb) { statusCb = cb; },
        teardown() {
          window.removeEventListener('message', onMsg);
          if (container.contains(iframe)) container.removeChild(iframe);
        },
      };
      return handle;
    },
  };
}

export const gltfRenderer = createGltfRenderer();

