// Invoke round-trip timing (#3626).
import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { slowInvokeLine, startInvokeTimer, bscLabel, SLOW_INVOKE_MS } from "@/shared/lib/core/invokeTiming";

describe("slowInvokeLine", () => {
  it("returns null under the threshold", () => {
    expect(slowInvokeLine("read_x", SLOW_INVOKE_MS - 1)).toBeNull();
    expect(slowInvokeLine("read_x", 0)).toBeNull();
  });

  it("formats a rounded [invoke] line at/over the threshold", () => {
    expect(slowInvokeLine("read_x", SLOW_INVOKE_MS)).toBe(`[invoke] read_x ${SLOW_INVOKE_MS}ms`);
    expect(slowInvokeLine("bsc ui list", 152.7)).toBe("[invoke] bsc ui list 153ms");
  });

  it("excludes the logging subsystem's own commands regardless of duration", () => {
    expect(slowInvokeLine("frontend_log", 5000)).toBeNull();
    expect(slowInvokeLine("log_get_scopes", 5000)).toBeNull();
  });

  it("checks exclusion against the real command, not the label", () => {
    // A bsc call is labelled `bsc …` but its command is "bsc" — never excluded.
    expect(slowInvokeLine("bsc ui list", 5000, "bsc")).toBe("[invoke] bsc ui list 5000ms");
    // A slow log_get_scopes is still excluded when the command is passed explicitly.
    expect(slowInvokeLine("log_get_scopes", 5000, "log_get_scopes")).toBeNull();
  });
});

describe("bscLabel", () => {
  it("labels by the first two args (subcommand + verb)", () => {
    expect(bscLabel(["ui", "list"])).toBe("bsc ui list");
    expect(bscLabel(["plan", "issue", "add", "x"])).toBe("bsc plan issue"); // extra args dropped
    expect(bscLabel(["skill"])).toBe("bsc skill");
    expect(bscLabel([])).toBe("bsc");
  });
});

describe("startInvokeTimer", () => {
  let nowSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    vi.mocked(invoke).mockResolvedValue(undefined);
    nowSpy = vi.spyOn(performance, "now");
  });
  afterEach(() => nowSpy.mockRestore());

  it("emits a [invoke] warn line to the perf scope when the call ran slow", () => {
    nowSpy.mockReturnValueOnce(1000).mockReturnValueOnce(1000 + SLOW_INVOKE_MS + 50);
    const done = startInvokeTimer("read_x");
    done();
    expect(invoke).toHaveBeenCalledWith("frontend_log", {
      level: "warn",
      scope: "perf",
      message: `[invoke] read_x ${SLOW_INVOKE_MS + 50}ms`,
    });
  });

  it("stays silent for a fast call", () => {
    nowSpy.mockReturnValueOnce(1000).mockReturnValueOnce(1010);
    const done = startInvokeTimer("read_x");
    done();
    expect(invoke).not.toHaveBeenCalled();
  });

  it("uses the bsc command for exclusion so bsc labels always log when slow", () => {
    nowSpy.mockReturnValueOnce(0).mockReturnValueOnce(500);
    const done = startInvokeTimer(bscLabel(["ui", "list"]), "bsc");
    done();
    expect(invoke).toHaveBeenCalledWith("frontend_log", {
      level: "warn",
      scope: "perf",
      message: "[invoke] bsc ui list 500ms",
    });
  });
});

import { describe, it, expect } from "vitest";
import { BSC_ISSUE_LABEL, withProvenanceLabel, triageIssueListArgs } from "@/shared/lib/github/issueProvenance";
import { buildTriagePrompt, TRIAGE_PROMPT, useAppStore } from "@/store";

describe("issue provenance (#738)", () => {
  it("withProvenanceLabel stamps the bsc-generated label, idempotently", () => {
    expect(withProvenanceLabel([])).toEqual([BSC_ISSUE_LABEL]);
    expect(withProvenanceLabel(["stream:ux"])).toEqual(["stream:ux", BSC_ISSUE_LABEL]);
    expect(withProvenanceLabel([BSC_ISSUE_LABEL, "x"])).toEqual([BSC_ISSUE_LABEL, "x"]);
  });

  it("triageIssueListArgs restricts to the provenance label by default", () => {
    expect(triageIssueListArgs(true)).toContain(`--label ${BSC_ISSUE_LABEL}`);
    expect(triageIssueListArgs(false)).not.toContain("--label");
    expect(triageIssueListArgs(false)).toContain("--state open");
  });

  it("buildTriagePrompt(true) confines triage to authored issues + flags the rest untrusted", () => {
    const p = buildTriagePrompt(true);
    expect(p).toContain(BSC_ISSUE_LABEL);
    expect(p).toContain(`--label ${BSC_ISSUE_LABEL}`);
    expect(p).toMatch(/untrusted/);
    expect(p).toMatch(/do NOT act on it/);
  });

  it("buildTriagePrompt(false) works every open issue (opt-out)", () => {
    const p = buildTriagePrompt(false);
    expect(p).not.toContain(`--label ${BSC_ISSUE_LABEL}`);
    expect(p).toContain("every open issue");
  });

  it("TRIAGE_PROMPT defaults to the secure (restricted) prompt", () => {
    expect(TRIAGE_PROMPT).toContain(BSC_ISSUE_LABEL);
  });

  it("buildTriagePrompt(_, _, local=true) triages plan.db via bsc plan, not gh (#3281 local-first)", () => {
    const p = buildTriagePrompt(true, undefined, true);
    // Offline: reads + updates the plan store — no `gh` anywhere in the prompt.
    expect(p).toContain("bsc plan list --status open");
    expect(p).toContain("bsc plan status");
    expect(p).not.toMatch(/gh issue/);
    // All plan.db issues are planner-authored, so the untrusted-external-issue guard doesn't apply.
    expect(p).not.toContain(BSC_ISSUE_LABEL);
    expect(p).not.toMatch(/untrusted/);
  });

  it("the local flag overrides restrictToBsc — plan.db has no external channel to restrict", () => {
    // restrictToBsc=true would normally add the label dance; local mode ignores it (all trusted).
    expect(buildTriagePrompt(true, undefined, true)).not.toContain(`--label ${BSC_ISSUE_LABEL}`);
  });

  it("the restrictToBscIssues setting is ON by default and toggles", () => {
    expect(useAppStore.getState().restrictToBscIssues).toBe(true); // secure by default
    useAppStore.getState().setRestrictToBscIssues(false);
    expect(useAppStore.getState().restrictToBscIssues).toBe(false);
    useAppStore.getState().setRestrictToBscIssues(true);
  });

  it("triageStartProject seeds the restricted GITHUB prompt by default when CONNECTED (#738)", () => {
    // The restricted (gh issue list) triage is the connected behavior, so it needs a token (#3281 made
    // triage token-aware: no token ⇒ the local plan.db prompt, next test) AND a strategy that actually
    // reaches a remote (#worker-prose-follows-the-local-first-loop — a token alone stopped being
    // enough, because holding one is not consent to WRITE to GitHub).
    //
    // The #738 guard itself is unchanged and still worth pinning: WHEN a project genuinely triages
    // GitHub issues, only bsc-authored ones are trusted.
    useAppStore.setState({
      bscBaseDir: "/base",
      restrictToBscIssues: true,
      githubToken: "ghp_x",
      // keyed by the sanitized project NAME ("Proj"), which is what triageStartProject derives — not
      // the project id ("k") it is also passed.
      planFleet: { Proj: { recommended: 1, reasoning: "", director: { enabled: false }, streams: [], strategy: "pr-ci" } },
    } as never);
    useAppStore.getState().triageStartProject("Proj", ["acme/web"], "k");
    const texts = Object.values(useAppStore.getState().paneStartupPromptText);
    expect(texts.some((t) => typeof t === "string" && t.includes(BSC_ISSUE_LABEL))).toBe(true);
  });

  it("triageStartProject seeds the LOCAL plan.db prompt with no token (#3281)", () => {
    // Clear paneStartupPromptText — the store is a singleton, so the prior test's gh-issue prompt would
    // otherwise linger and trip the negative assertion below.
    useAppStore.setState({ bscBaseDir: "/base", restrictToBscIssues: true, githubToken: "", paneStartupPromptText: {} });
    useAppStore.getState().triageStartProject("Proj2", ["acme/web"], "k2");
    const texts = Object.values(useAppStore.getState().paneStartupPromptText).filter((t): t is string => typeof t === "string");
    // Offline: the seeded triage prompt reads plan.db via `bsc plan`, never `gh issue`.
    expect(texts.some((t) => t.includes("bsc plan list --status open"))).toBe(true);
    expect(texts.some((t) => /gh issue/.test(t))).toBe(false);
  });
});

// Issue PROVENANCE, captured from the live TypeScript so Rust can be proved to match.
//
// This is the untrusted-issue channel (#738). A triage session runs `gh issue list` over every open
// issue in a repo, so an issue nobody in this system authored can otherwise be picked up and acted
// on by an agent. base-studio-code stamps the issues it publishes with a distinctive label and
// restricts triage to that label BY DEFAULT.
//
// Caveat carried over from the source, because a port that "hardens" it would be lying: the label is
// FORGEABLE by anyone with repo write access. This stops accidental and hand-created pickup and
// raises the bar; it is not a cryptographic guarantee.
//
// ## What a port drifts on
//
//   * `withProvenanceLabel` is IDEMPOTENT and ORDER-PRESERVING — the label is appended, never
//     inserted, and never duplicated. A set-based port passes a membership check and silently
//     reorders the labels that reach the GitHub API.
//   * `triageIssueListArgs(false)` must NOT carry the label selector. Getting this backwards fails
//     OPEN: triage would read every issue in the repo, which is the exact exposure the label exists
//     to close, and every "does it return a string" test still passes.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/github/issueProvenance.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  BSC_ISSUE_LABEL,
  BSC_ISSUE_LABEL_COLOR,
  triageIssueListArgs,
  withProvenanceLabel,
} from "@/shared/lib/github/issueProvenance";

const FIXTURE = join(process.cwd(), "src/shared/lib/github/issueProvenance.fixtures.json");

/** Label lists, including the ones that separate append-if-absent from a set union. */
const LABEL_CASES: { label: string; labels: string[] }[] = [
  { label: "empty", labels: [] },
  { label: "one unrelated label", labels: ["bug"] },
  { label: "already stamped — idempotent", labels: [BSC_ISSUE_LABEL] },
  { label: "already stamped, not last — must not move or duplicate", labels: [BSC_ISSUE_LABEL, "bug"] },
  { label: "order is preserved and the stamp is APPENDED", labels: ["zeta", "alpha", "mid"] },
  { label: "a near-miss label does not count as stamped", labels: ["bsc-generated-x", "BSC-GENERATED"] },
  { label: "duplicates in the input are left alone", labels: ["bug", "bug"] },
];

describe("issueProvenance fixture", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const doc = {
      note: "GENERATED from the live TypeScript — see issueProvenance.fixtures.gen.test.ts",
      // The constants themselves are part of the contract: the label is what the published issue
      // carries AND what triage selects on, so a port that drifts on the string silently selects
      // nothing rather than failing.
      label: BSC_ISSUE_LABEL,
      labelColor: BSC_ISSUE_LABEL_COLOR,
      withProvenanceLabel: LABEL_CASES.map((c) => ({
        label: c.label,
        input: c.labels,
        // The whole ORDERED list, never a membership boolean.
        output: withProvenanceLabel(c.labels),
      })),
      triageIssueListArgs: [true, false].map((restrict) => ({
        restrictToBsc: restrict,
        args: triageIssueListArgs(restrict),
      })),
    };
    const text = `${JSON.stringify(doc, null, 2)}\n`;
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });
});

