import { describe, it, expect, vi, beforeEach } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { createHash, webcrypto } from "node:crypto";
import { kitToManifest, kitFromManifest, kitShareCode, kitFromCode, publishKitToGist, KIT_KIND, type KitPayload } from "@/features/designs/lib/kitGist";
import { validateManifest, type ExtensionManifest } from "@/features/planner/lib/gist/manifest";
import type { ComponentRecord, Kit } from "@/features/designs/lib/model";

// sha256Hex rides WebCrypto; back the jsdom env with Node's webcrypto when absent.
if (!globalThis.crypto?.subtle) vi.stubGlobal("crypto", webcrypto);

const kit: Kit = { id: "my-kit", name: "My Kit", stack: "React", dot: "var(--accent)", builtin: false };
const comps: ComponentRecord[] = [
  {
    id: "btn", name: "Btn", kitId: "my-kit", role: "primitive", version: "1.0.0", used: 3, tags: ["control"],
    variants: ["a"], composes: [], props: [{ name: "x", type: "string", req: true, desc: "d" }],
    whenUse: ["u"], whenNot: ["n"], src: "Btn.tsx", srcText: "code", wraps: "button",
  },
];

describe("component-kit gist envelope (#2305 slice 1c)", () => {
  it("round-trips a kit through the manifest", () => {
    const m = kitToManifest(kit, comps);
    expect(m.kind).toBe(KIT_KIND);
    expect(validateManifest(m).ok).toBe(true);
    const r = kitFromManifest(m);
    expect(r.ok).toBe(true);
    if (!r.ok) return;
    expect(r.kit.id).toBe("my-kit");
    expect(r.components.map((c) => c.name)).toEqual(["Btn"]);
    expect(r.components[0].wraps).toBe("button");
  });

  it("round-trips through a no-account share code", () => {
    const r = kitFromCode(kitShareCode(kit, comps));
    expect(r.ok).toBe(true);
    if (r.ok) expect(r.kit.name).toBe("My Kit");
  });

  it("rejects a non-kit manifest", () => {
    const bp = { manifest: 1, kind: "blueprint", id: "b", name: "B", version: "1", payload: {} } as unknown as ExtensionManifest;
    expect(kitFromManifest(bp).ok).toBe(false);
  });

  it("forces components into the kit id + drops builtin (never trusts the payload)", () => {
    const evil = kitToManifest({ ...kit, id: "react-ui" }, [{ ...comps[0], kitId: "other", builtin: true }]);
    const r = kitFromManifest(evil);
    expect(r.ok).toBe(true);
    if (!r.ok) return;
    expect(r.components[0].kitId).toBe("react-ui");   // forced into the kit
    expect(r.components[0].builtin).toBeUndefined();  // an imported record is never a built-in
  });

  it("rejects a kit with no valid components", () => {
    expect(kitFromCode(kitShareCode(kit, [])).ok).toBe(false);
  });

  it("rides the data-shape axis through a share, filtered to the vocabulary (#2475)", () => {
    const stamped = { ...comps[0], shapes: ["list", "blob"] } as unknown as ComponentRecord;
    const r = kitFromManifest(kitToManifest(kit, [stamped]));
    expect(r.ok).toBe(true);
    if (!r.ok) return;
    // In-vocabulary shapes survive; the off-vocabulary token is dropped, never trusted.
    expect(r.components[0].shapes).toEqual(["list"]);
    // An unstamped component stays unstamped (no fabricated empty array).
    const r2 = kitFromManifest(kitToManifest(kit, comps));
    expect(r2.ok && r2.components[0].shapes).toBeUndefined();
  });

  it("rides the rail-hierarchy axes through a share; a missing axis stays absent (#2487)", () => {
    const r = kitFromManifest(kitToManifest({ ...kit, tech: "react", style: "studio" }, comps));
    expect(r.ok && r.kit.tech).toBe("react");
    expect(r.ok && r.kit.style).toBe("studio");
    // tech normalizes to its lowercase-slug form; declared-but-blank counts as missing.
    const r2 = kitFromManifest(kitToManifest({ ...kit, tech: "React", style: "  " }, comps));
    expect(r2.ok && r2.kit.tech).toBe("react");
    expect(r2.ok && r2.kit.style).toBeUndefined();
    // A kit that never declared the axes imports without them (no fabricated values) — it groups
    // into the rail's "other" bucket instead of crashing.
    const r3 = kitFromManifest(kitToManifest(kit, comps));
    expect(r3.ok && r3.kit.tech).toBeUndefined();
    expect(r3.ok && r3.kit.style).toBeUndefined();
  });
});

describe("publish with a kit-store identity (#2465)", () => {
  beforeEach(() => vi.mocked(invoke).mockClear());

  it("kitToManifest stamps `payload.store` only when given (pre-#2465 envelope stays byte-identical)", () => {
    const plain = kitToManifest(kit, comps);
    expect((plain.payload as KitPayload).store).toBeUndefined();
    expect("store" in (plain.payload as KitPayload)).toBe(false);
    const stamped = kitToManifest(kit, comps, "2.0.0", { id: "me/my-kit", version: "2.0.0" });
    expect((stamped.payload as KitPayload).store).toEqual({ id: "me/my-kit", version: "2.0.0" });
    expect(stamped.version).toBe("2.0.0");
    // The identity survives the payload coercion path untouched (kitFromManifest ignores it).
    expect(kitFromManifest(stamped).ok).toBe(true);
  });

  it("publishKitToGist(publisher) publishes, registers the store entry, and returns the pin", async () => {
    vi.mocked(invoke).mockImplementation(async (cmd) => {
      if (cmd === "gist_create") return { id: "0123456789abcdef", html_url: "https://gist.github.com/me/0123456789abcdef" };
      if (cmd === "bsc") return "{}";
      return null;
    });
    const res = await publishKitToGist("tok", kit, comps, { public: true, publisher: "Me User" });
    expect(res.ok).toBe(true);
    if (!res.ok) return;
    expect(res.warning).toBeUndefined();
    // The pin: slugged publisher-scoped id, the exact published bytes' sha256, the gist URL.
    const expectedText = JSON.stringify(kitToManifest(kit, comps, "1.0.0", { id: "me-user/my-kit", version: "1.0.0" }), null, 2);
    const expectedHash = createHash("sha256").update(expectedText, "utf8").digest("hex");
    expect(res.pin).toEqual({ id: "me-user/my-kit", version: "1.0.0", hash: expectedHash, source: res.url });
    // …and the local store got EXACTLY those bytes, verified by the same hash.
    const add = vi.mocked(invoke).mock.calls.find((c) => c[0] === "bsc")!;
    const { args, stdin } = add[1] as { args: string[]; stdin: string };
    expect(args).toEqual(["ui", "release", "add", "me-user/my-kit", "1.0.0", "--kind", KIT_KIND, "--sha256", expectedHash, "--source", res.url]);
    expect(stdin).toBe(expectedText);
  });

  it("a local-store refusal downgrades to a warning (the gist publish already succeeded)", async () => {
    vi.mocked(invoke).mockImplementation(async (cmd) => {
      if (cmd === "gist_create") return { id: "0123456789abcdef", html_url: "https://gist.github.com/me/0123456789abcdef" };
      if (cmd === "bsc") throw new Error("already exists with different content — published versions are immutable");
      return null;
    });
    const res = await publishKitToGist("tok", kit, comps, { publisher: "me" });
    expect(res.ok).toBe(true);
    if (res.ok) {
      expect(res.pin).toBeTruthy();
      expect(res.warning).toContain("immutable");
    }
  });

  it("without a publisher the legacy shape is preserved (no pin, no store write)", async () => {
    vi.mocked(invoke).mockImplementation(async (cmd) => {
      if (cmd === "gist_create") return { id: "0123456789abcdef", html_url: "https://gist.github.com/me/0123456789abcdef" };
      return null;
    });
    const res = await publishKitToGist("tok", kit, comps);
    expect(res.ok).toBe(true);
    if (res.ok) expect(res.pin).toBeUndefined();
    expect(vi.mocked(invoke).mock.calls.some((c) => c[0] === "bsc")).toBe(false);
  });
});

implementations.code:
// Hierarchical kit navigation (#2487, policy fixed by #2506) — the PURE grouping model behind the
// Design Studio rail. The full hierarchy is technology → visual language → kit → components: `tech`
// (lowercase slug) is the top grouping axis, `style` (the visual language — a STRUCTURALLY different
// component set, i.e. a different kit; the palette/THEME axis restyles one kit via tokens and never
// appears here) is the second. React/Tauri-free so the rail render and the tests share one model.
//
// ALWAYS GROUPED (#2506) — the rail shows technology groups at the top level and style groups within
// each technology, ALWAYS. (#2487 originally auto-flattened a level whose partition was trivial; that
// heuristic is superseded by explicit user direction — the fixed two-level hierarchy is the point, so
// the packaged single-kit library reads React → Studio → components rather than a bare kit list.)
//
// THE SINGLE-KIT STYLE MERGE — a kit is a (tech, style) unit, so the normal case is a style bucket
// holding exactly ONE kit. Then the style header IS the kit: the group node carries `kit`, its
// components list directly under the style header, and no redundant kit row renders. Only when
// several kits share one (tech, style) pair does a kit level nest beneath the style group.
//
// MISSING FIELDS — kits without `tech`/`style` (user-authored, imported, pre-#2487) group into the
// trailing "other" bucket on that axis. Never a crash.
//
// THE `folder` AXIS UNDER A KIT (#3048/#3582) — a kit's components carry a `/`-delimited folder path
// derived from their `src`, so a kit browses like a completed project's folders. Building that tree is
// NOT this module's job any more: since #4128 the nested-folder model is shared with the Algorithms rail
// (`@/shared/lib/core/folderTree`), because two copies of "the same structure" had already drifted apart
// on ungrouped-handling and ordering. `groupComponentsByFolder` is now the components-typed binding of
// that one builder.
import { buildFolderTree, folderItemCount, type FolderNode } from "@/shared/lib/core/folderTree";
import type { Kit, ComponentRecord } from "@/features/designs/lib/model";

export { UNGROUPED_KEY, UNGROUPED_LABEL } from "@/shared/lib/core/folderTree";

/** The bucket kits without a `tech`/`style` value group under (always ordered last). */
export const OTHER_BUCKET = "other";

/** A kit row in the rail tree (only under a style that holds SEVERAL kits — see the module doc). */
export interface KitLeaf {
  kind: "kit";
  kit: Kit;
}

/** A collapsible group header in the rail tree (a tech or visual-language level). */
export interface KitGroup {
  kind: "group";
  level: "tech" | "style";
  /** Stable expand-state key (`tech:react`, `style:react/studio`). */
  key: string;
  label: string;
  /** Kits under this group (transitively). */
  count: number;
  /** Style level only: when the style holds exactly ONE kit, the header IS that kit — components
   *  render directly beneath it and `children` is empty (#2506). */
  kit?: Kit;
  children: KitTreeNode[];
}

export type KitTreeNode = KitGroup | KitLeaf;

const techOf = (k: Kit): string => (k.tech ?? "").trim().toLowerCase() || OTHER_BUCKET;
const styleOf = (k: Kit): string => (k.style ?? "").trim() || OTHER_BUCKET;

/** Bucket items by a key in first-appearance order, the missing-field OTHER bucket forced last.
 *  Generic over kits (the tech/style axes) and components (the #3048 `group` axis). */
function bucket<T>(items: readonly T[], keyOf: (x: T) => string): Map<string, T[]> {
  const m = new Map<string, T[]>();
  for (const x of items) {
    const key = keyOf(x);
    const arr = m.get(key);
    if (arr) arr.push(x);
    else m.set(key, [x]);
  }
  const other = m.get(OTHER_BUCKET);
  if (other && m.size > 1) {
    m.delete(OTHER_BUCKET);
    m.set(OTHER_BUCKET, other);
  }
  return m;
}

/** The style level under one tech group: a style group per bucket; a single-kit style merges the kit
 *  into its header (see the module doc). */
function styleLevel(kits: Kit[], keyPrefix: string): KitTreeNode[] {
  return [...bucket(kits, styleOf)].map(([style, inStyle]) => ({
    kind: "group" as const,
    level: "style" as const,
    key: `style:${keyPrefix}${style}`,
    label: style,
    count: inStyle.length,
    ...(inStyle.length === 1
      ? { kit: inStyle[0], children: [] as KitTreeNode[] }
      : { children: inStyle.map((kit): KitTreeNode => ({ kind: "kit", kit })) }),
  }));
}

/**
 * Group the kit library into the rail tree: tech groups → style groups (→ kit leaves only when a
 * style holds several kits) — ALWAYS grouped, per the module doc (#2506). Kits keep their library
 * order within a bucket; buckets order by first appearance, the "other" bucket last.
 */
export function groupKits(kits: Kit[]): KitTreeNode[] {
  return [...bucket(kits, techOf)].map(([tech, inTech]) => ({
    kind: "group" as const,
    level: "tech" as const,
    key: `tech:${tech}`,
    label: tech,
    count: inTech.length,
    children: styleLevel(inTech, `${tech}/`),
  }));
}

/** One folder of a kit's tree — the shared {@link FolderNode} bound to {@link ComponentRecord}. The
 *  components-side NAME for the shared node (#4128), kept so importers read in kit vocabulary; the
 *  SHAPE is the shared one, which is what makes the two library rails structurally identical. */
export type ComponentFolder = FolderNode<ComponentRecord>;

/** Total components under a folder, transitively (its own + every descendant's) — the header count. */
export const folderComponentCount = folderItemCount<ComponentRecord>;

/**
 * Partition ONE kit's components into a nested FOLDER TREE by their `folder` path (#3048/#3582) — the
 * components-typed binding of the shared {@link buildFolderTree} (#4128).
 *
 * `composes` is unaffected — it resolves across the whole kit, so components in different folders still
 * compose freely; this tree is organizational only.
 *
 * Returns `null` when NO component carries a `folder`, so the rail renders the flat component list
 * exactly as it would without folders (zero regression for folderless kits).
 */
export function groupComponentsByFolder(comps: readonly ComponentRecord[]): ComponentFolder[] | null {
  return buildFolderTree(comps, (c) => c.folder);
}

