// The themeable kit (#1852 Phases 0/1/3) — public barrel. The semantic component tokens live in
// styles/tokens.css; this module is the THEME axis over them: the registry + apply helpers + the
// scoped wrapper. See also `@/shared/ui/spec` (the SPEC axis — the node contract + KitRenderer).

export type { KitTheme } from "@/shared/ui/kit/theme";
export {
  KIT_THEMES, DEFAULT_THEME, KIT_TOKENS, themeById, themeVars, applyThemeToRoot,
  // #2488: the designer-writable theme store's sync hooks — the components slice hydrate pushes the
  // store collection in; every themeById/themeVars/ThemeScope consumer then resolves against it.
  setActiveKitThemes, activeKitThemes, kitTokens,
} from "@/shared/ui/kit/theme";
export { ThemeScope } from "@/shared/ui/kit/ThemeScope";
export type { ThemeScopeProps } from "@/shared/ui/kit/ThemeScope";
// #3711/#3715: the JS projection of the active theme — concrete token VALUES for a component that renders to
// a NON-CSS surface (canvas / WebGL / non-web runtime) and can't see the cascade. `<ThemeProvider>` is the
// JS counterpart to `<ThemeScope>`; `useResolvedTheme()` reads it; `resolveThemeTokens` is the pure resolver.
export { ThemeProvider, useResolvedTheme } from "@/shared/ui/kit/ThemeProvider";
export type { ResolvedTheme } from "@/shared/ui/kit/ThemeProvider";
export { resolveThemeTokens } from "@/shared/ui/kit/resolve";
// #2569: data-defined component variants — compile the designer-authored variant store into a managed
// `<style>` of `.<component>.<variant>` rules (the render path for `bsc ui component … define-variant`).
export type { VariantDef } from "@/shared/ui/kit/variants";
export { compileVariantsCss, applyVariantsToRoot } from "@/shared/ui/kit/variants";
// #2942: data-defined KIT animations — compile a kit's motion library (its `animations`) into a
// managed <style> (keyframes + a reduced-motion-guarded applying rule), re-applied on boot + ui-touch.
export type { KitAnimation, AnimationDef, AnimationTrigger } from "@/shared/ui/kit/animations";
export { compileAnimationsCss, applyAnimationsToRoot, kitAnimations, animClassName } from "@/shared/ui/kit/animations";
// #2650: design-contribution overlay — the compose-don't-mutate application of the tokens a downloaded
// blueprint contributes (reconciled missing categories, generated by #2636), as a managed :root <style>.
export type { DesignContributionOverlay } from "@/shared/ui/kit/contributions";
export {
  compileContributionsCss, applyContributionsToRoot, contributionFromCategories, graphCategoryToken,
} from "@/shared/ui/kit/contributions";
// #2646: the PURE reconcile diff — a downloaded blueprint's design contribution vs the local contract.
// The confirm-list (#2658) generates + registers a contribution for whatever the contract can't cover.
export type { DesignContribution, DesignReconcile } from "@/shared/ui/kit/reconcile";
export { reconcileDesign, KNOWN_GRAPH_CATEGORIES } from "@/shared/ui/kit/reconcile";

// The frontend ↔ kit-usage consumer-index bridge (#2277). Which projects use which kit — the GLOBAL
// edge store the change-propagation fan-out reads, reached (from the UI AND a live session's shell)
// through the SAME `bsc ui usage …` CLI over the generic `bsc` bridge (#2114). Global → every
// call passes `null` as the projectKey. The Zustand `kitUsage` slice is a write-through cache over it.
import { bsc, bscRun } from "@/shared/lib/core/bsc";
import type { KitConsumer } from "@/features/designs/lib/propagation";

/**
 * Load every consumer edge via `bsc ui usage list --json`. Returns `null` when the bridge is
 * unreachable (no Tauri host / an old binary) so the caller keeps its persisted cache rather than
 * blanking it. NOT `bscJson` — its degrade-to-`[]` would clobber the cache on a transient failure.
 */
export async function loadKitUsage(): Promise<KitConsumer[] | null> {
  try {
    const out = await bsc(null, ["ui", "usage", "list", "--json"]);
    const rows = JSON.parse(out.trim() || "[]") as { projectKey?: string; kitId?: string }[];
    return (rows ?? [])
      .filter((u): u is { projectKey: string; kitId: string } => !!u.projectKey && !!u.kitId)
      .map((u) => ({ projectKey: u.projectKey, kitId: u.kitId }));
  } catch {
    return null;
  }
}

/** Write-through an edge add (`bsc ui usage add`). Fire-and-forget; never throws (degrades to
 *  cache-only when the bridge/binary is absent). */
export async function pushKitUsage(projectKey: string, kitId: string): Promise<void> {
  try { await bscRun(null, ["ui", "usage", "add", projectKey, kitId]); } catch { /* bridge absent — cache-only */ }
}

/** Write-through an edge removal (`bsc ui usage remove <id>`). Never throws. */
export async function dropKitUsage(id: string): Promise<void> {
  try { await bscRun(null, ["ui", "usage", "remove", id]); } catch { /* bridge absent — cache-only */ }
}

