// The Algorithms knowledge-graph model (#2761/#2958): the impl-only, primitives-rooted model — seed
// integrity, the per-language kits, the composes graph, and the compose-depth layout. The abstract
// concept ontology (nodes/edges) was removed with #2961 — a node IS its implementation.
import { describe, it, expect } from "vitest";
import {
  KNOWLEDGE, TECHS, implById, usedByImpl, buildKnowledge,
  kitTechs, kitImpls, kitImplsByRole, kitGraph, groupImplsByLanguage, layoutKitGraph,
  matchesImpl, type AlgoImpl, type RawKnowledge,
} from "@/features/algorithms/lib/knowledge";

describe("KNOWLEDGE seed (impl-only, #2958)", () => {
  it("carries the Rust kit — unique ids, known roles, real same-tech composes", () => {
    const impls = KNOWLEDGE.implementations;
    expect(impls.length).toBeGreaterThanOrEqual(16);
    const ids = new Set(impls.map((i) => i.id));
    expect(ids.size).toBe(impls.length); // ids unique
    for (const im of impls) {
      expect(["primitive", "algorithm"]).toContain(im.role);
      expect(TECHS).toContain(im.tech);
      expect(im.name.trim().length).toBeGreaterThan(0);
      // #2972: an algorithm carries real, reusable code; a primitive is a DESCRIPTOR of a language
      // built-in — it names its std `ref` and is NOT re-coded.
      if (im.role === "algorithm") {
        expect((im.code ?? "").trim().length).toBeGreaterThan(0);
      } else {
        expect((im.ref ?? "").trim().length).toBeGreaterThan(0);
        expect(im.code).toBeUndefined();
      }
      for (const c of im.composes) {
        expect(ids.has(c)).toBe(true); // every composes id is a REAL impl
        expect(implById(KNOWLEDGE, c)!.tech).toBe(im.tech); // and of the SAME tech
      }
    }
  });

  it("is primitives-rooted — every kit has a primitive base and algorithms that compose down to it", () => {
    for (const tech of kitTechs(KNOWLEDGE)) {
      const prims = kitImplsByRole(KNOWLEDGE, tech, "primitive");
      const algos = kitImplsByRole(KNOWLEDGE, tech, "algorithm");
      expect(prims.length).toBeGreaterThan(0); // a base exists
      // At least one algorithm composes a primitive (roots in the base).
      expect(algos.some((a) => a.composes.some((c) => prims.some((p) => p.id === c)))).toBe(true);
    }
  });
});

describe("implById / usedByImpl", () => {
  it("implById resolves an id and misses cleanly", () => {
    expect(implById(KNOWLEDGE, "bfs.rs")?.tech).toBe("rust");
    expect(implById(KNOWLEDGE, "nope.rs")).toBeUndefined();
  });

  it("merge-sort.rs composes merge.rs and roots in the Rust primitives", () => {
    const ms = implById(KNOWLEDGE, "merge-sort.rs");
    expect(ms?.composes).toEqual(["merge.rs", "rust.vec", "rust.slice"]);
  });

  it("usedByImpl is the reverse of composes", () => {
    // merge.rs is composed only by merge-sort.rs.
    expect(usedByImpl(KNOWLEDGE, "merge.rs").map((i) => i.id)).toEqual(["merge-sort.rs"]);
    // A top-level algorithm no one composes has no reverse edges.
    expect(usedByImpl(KNOWLEDGE, "merge-sort.rs")).toEqual([]);
    // A language primitive is composed UP by its algorithms.
    expect(usedByImpl(KNOWLEDGE, "rust.iterator").map((i) => i.id)).toContain("quick-sort.rs");
  });
});

describe("language kits (#2863) — a kit is every impl of one tech, grouped by role", () => {
  it("kitTechs lists the seeded languages, TECHS-ordered", () => {
    // Rust-first, plus a minimal TypeScript kit seeded for the #3116 Component→Algorithm example
    // (typescript.number + fibonacci.ts); TECHS order puts typescript first.
    expect(kitTechs(KNOWLEDGE)).toEqual(["typescript", "rust"]);
  });

  it("kitImpls scopes to one language; kitImplsByRole splits primitives (language built-ins) from algorithms", () => {
    const rs = kitImpls(KNOWLEDGE, "rust");
    expect(rs.length).toBeGreaterThan(0);
    expect(rs.every((im) => im.tech === "rust")).toBe(true);
    const prims = kitImplsByRole(KNOWLEDGE, "rust", "primitive");
    const algos = kitImplsByRole(KNOWLEDGE, "rust", "algorithm");
    expect(prims.map((im) => im.id)).toContain("rust.iterator"); // a language primitive
    expect(prims.map((im) => im.id)).toContain("rust.vec"); // a language primitive
    expect(algos.map((im) => im.id)).toContain("merge.rs"); // a user impl
    expect(algos.map((im) => im.id)).toContain("merge-sort.rs"); // an algorithm
    expect(prims.length + algos.length).toBe(rs.length);
  });

  it("groupImplsByLanguage makes one folder per language, primitives before algorithms (the rail tree)", () => {
    const groups = groupImplsByLanguage(KNOWLEDGE);
    expect(groups.map((g) => g.tech)).toEqual(kitTechs(KNOWLEDGE));
    const rs = groups.find((g) => g.tech === "rust")!;
    expect(rs.label).toBe("Rust");
    expect(rs.key).toBe("lang:rust");
    expect(rs.dot).toBe("var(--state-wait)"); // the per-language folder-head color (#2902)
    expect(rs.impls.every((im) => im.tech === "rust")).toBe(true);
    const firstAlgo = rs.impls.findIndex((im) => im.role === "algorithm");
    const lastPrim = rs.impls.map((im) => im.role).lastIndexOf("primitive");
    expect(lastPrim).toBeLessThan(firstAlgo);
    expect(rs.impls.map((im) => im.id)).toContain("rust.iterator"); // a primitive
    expect(rs.impls.map((im) => im.id)).toContain("merge-sort.rs"); // an algorithm
  });

  it("kitGraph builds a kit's own impl graph — nodes are that tech's impls, wired by composes only", () => {
    const kg = kitGraph(KNOWLEDGE, "rust");
    expect(kg.nodes).toEqual(kitImpls(KNOWLEDGE, "rust"));
    expect(kg.nodes.every((n) => n.tech === "rust")).toBe(true);
    // The builds-on edge (merge-sort.rs composes merge.rs)…
    expect(kg.edges).toContainEqual({ from: "merge-sort.rs", to: "merge.rs", rel: "composes" });
    // …and an algorithm rooting in a language primitive (quick-sort.rs composes rust.iterator).
    expect(kg.edges).toContainEqual({ from: "quick-sort.rs", to: "rust.iterator", rel: "composes" });
    // Every edge is a `composes` between in-kit impl ids (the ontology is gone, #2961).
    const ids = new Set(kg.nodes.map((n) => n.id));
    expect(kg.edges.every((e) => e.rel === "composes" && ids.has(e.from) && ids.has(e.to))).toBe(true);
    // The composes edge count equals the sum of in-kit composes references.
    const composeRefs = kg.nodes.reduce((acc, n) => acc + n.composes.filter((c) => ids.has(c)).length, 0);
    expect(kg.edges.length).toBe(composeRefs);
  });

  it("layoutKitGraph bands by origin and keeps depth as the order INSIDE a cluster", () => {
    const kg = kitGraph(KNOWLEDGE, "rust");
    const l = layoutKitGraph(kg);
    expect([...l.pos.keys()].sort()).toEqual(kg.nodes.map((n) => n.id).sort());

    // DEPTH IS NO LONGER THE GLOBAL X AXIS, and that is the change. It was, and it is what produced a
    // 3,308 x 43,114 world on the typescript kit: 538 of 644 nodes share depth 1, so ONE column held 84%
    // of the graph and ran 52 screens down. ORIGIN is the coarse axis now, so `rust.vec` (a language
    // built-in) and `merge.rs` (a reference algorithm) are not comparable by x at all — different bands.
    const bandOf = (id: string) => {
      const p = l.pos.get(id)!;
      return l.clusters.find((c) => p.x >= c.x && p.x < c.x + c.w && p.y >= c.y && p.y < c.y + c.h)!;
    };
    expect(bandOf("rust.vec").origin).toBe("built-ins");
    expect(bandOf("merge.rs").origin).toBe("reference");

    // Depth survives LOCALLY: inside one cluster, base still precedes what builds on it.
    if (bandOf("merge.rs").label === bandOf("merge-sort.rs").label) {
      const a = l.pos.get("merge.rs")!, b = l.pos.get("merge-sort.rs")!;
      expect(a.y < b.y || (a.y === b.y && a.x < b.x)).toBe(true);
    }

    expect(l.world.w).toBeGreaterThan(0);
    expect(l.world.h).toBeGreaterThan(0);
    expect(l.world.h / l.world.w).toBeLessThan(5); // never a runaway column again
  });
});

describe("matchesImpl — the rail's one filter (#4128)", () => {
  const im = (o: Partial<AlgoImpl> & Pick<AlgoImpl, "id" | "tech">): AlgoImpl =>
    ({ role: "algorithm", name: o.id, composes: [], ...o });

  it("matches name, id, FOLDER PATH and tags — so a folder can be narrowed to by typing it", () => {
    // The folder half is the point: the components rail's `matchesQuery` has matched the folder path
    // since #3589, and with the domain dropdown gone (#4128) search is how this rail narrows too.
    const dijkstra = im({ id: "dijkstra.rs", tech: "rust", name: "dijkstra", folder: "graphs/shortest-path", tags: ["greedy"] });
    expect(matchesImpl(dijkstra, "dijk")).toBe(true);       // name
    expect(matchesImpl(dijkstra, ".rs")).toBe(true);         // id
    expect(matchesImpl(dijkstra, "shortest-path")).toBe(true); // folder path
    expect(matchesImpl(dijkstra, "graphs/")).toBe(true);       // a partial path
    expect(matchesImpl(dijkstra, "greedy")).toBe(true);        // tag
    expect(matchesImpl(dijkstra, "quicksort")).toBe(false);
  });

  it("is case-insensitive, and an empty query matches everything", () => {
    const plain = im({ id: "plain.rs", tech: "rust", name: "Plain" });
    expect(matchesImpl(plain, "PLAIN")).toBe(true);
    expect(matchesImpl(plain, "")).toBe(true);
    expect(matchesImpl(plain, "   ")).toBe(true);
  });

  it("never crashes on an impl carrying neither folder nor tags (the seeded classics)", () => {
    const seeded = im({ id: "merge-sort.rs", tech: "rust", name: "merge sort" });
    expect(matchesImpl(seeded, "merge")).toBe(true);
    expect(matchesImpl(seeded, "shared/ui")).toBe(false);
  });
});

describe("the domain facet is no longer an organizer (#4128)", () => {
  it("keeps `domain` on the RECORD — the CLI still writes and filters it — while the rail ignores it", () => {
    // #4128 removed the rail's domain dropdown and with it `domainsOf`/`implsByDomain`/`kitImplsByDomain`,
    // which had no other consumer. The FIELD stays: `bsc graph impl set --domain` / `impl list --domain`
    // still read it, and the harvest still derives one. What is gone is domain as a way the library is
    // presented — the folder tree (a strictly richer derivation of the same `src`) is that.
    const tagged = KNOWLEDGE.implementations.find((i) => i.domain);
    expect(tagged?.domain).toBeTruthy();
  });

  describe("a record missing `composes` must not take the hydrate down", () => {
    // THE OUTAGE THIS EXISTS FOR. `bsc-bluetooth--tests.rs` landed in the writable store with no
    // `composes`. `AlgoImpl` declares the field required, so every consumer reaches for it unguarded —
    // `graphSig` does `.join(",")` — and that threw inside the hydrate poll. `setGraph` never ran and
    // `useKnowledgeGraph` kept the packaged seed, so the page showed 758 records instead of 1,403 and
    // said nothing. A missing optional field may cost one record's edges; it may not cost the hydrate.
    it("defaults it to an empty array so the type's promise holds", () => {
      const g = buildKnowledge({ implementations: [{ id: "a.rs", name: "a" }] } as unknown as RawKnowledge);
      expect(g.implementations[0].composes).toEqual([]);
      // …and the shape every consumer relies on actually works:
      expect(() => g.implementations.map((im) => im.composes.join(","))).not.toThrow();
    });

    it("leaves a real `composes` untouched", () => {
      const g = buildKnowledge({
        implementations: [{ id: "a.rs", name: "a", composes: ["b.rs"] }],
      } as unknown as RawKnowledge);
      expect(g.implementations[0].composes).toEqual(["b.rs"]);
    });

    it("normalises a `composes` that is present but not an array", () => {
      const g = buildKnowledge({
        implementations: [{ id: "a.rs", name: "a", composes: null }],
      } as unknown as RawKnowledge);
      expect(g.implementations[0].composes).toEqual([]);
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  KNOWLEDGE, kitGraph, layoutKitGraph, originOf, clusterOf, NODE_H,
  type AlgoImpl, type KitGraph,
} from "@/features/algorithms/lib/knowledge";

/** A node with just the fields the layout reads. */
const impl = (id: string, over: Partial<AlgoImpl> = {}): AlgoImpl => ({
  id, tech: "typescript", role: "algorithm", name: id, composes: [], ...over,
});
const kit = (nodes: AlgoImpl[]): KitGraph => ({ nodes, edges: [] });

describe("origin banding", () => {
  it("separates crate code from frontend code — the split the crate migration needs", () => {
    expect(originOf(impl("a", { src: "crates/bsc-shot/src/lib.rs" }))).toBe("crates");
    expect(originOf(impl("b", { src: "src-tauri/src/session/launch.rs" }))).toBe("backend");
    expect(originOf(impl("c", { src: "src/features/glance/lib/x.ts" }))).toBe("features");
    expect(originOf(impl("d", { src: "src/shared/lib/core/y.ts" }))).toBe("shared");
    expect(originOf(impl("e", { src: "src/app/console/z.ts" }))).toBe("shell");
    expect(originOf(impl("f", { src: "src/store/slices/s.ts" }))).toBe("store");
  });

  /** The textbook algorithms (a-star.rs, bfs.rs) carry no `src` and are NOT codebase code — they are a
   *  third population that should not mix into either the crates or the frontend. */
  it("keeps reference algorithms and language built-ins out of the codebase bands", () => {
    expect(originOf(impl("a-star.rs", { src: undefined }))).toBe("reference");
    expect(originOf(impl("rust.vec", { role: "primitive" }))).toBe("built-ins");
  });

  it("clusters by the crate, the feature, or the folder — what the rail already navigates by", () => {
    expect(clusterOf(impl("a", { src: "crates/bsc-shot/src/lib.rs" }))).toBe("bsc-shot");
    expect(clusterOf(impl("b", { src: "src/features/planner/lib/x.ts" }))).toBe("planner");
    expect(clusterOf(impl("c", { src: "src/shared/lib/core/y.ts", folder: "shared/lib/core" }))).toBe("shared/lib/core");
    expect(clusterOf(impl("d", {}))).toBe("general");
  });
});

describe("layoutKitGraph", () => {
  /**
   * THE REGRESSION THIS EXISTS FOR. The old layout put a node in the column of its compose depth and
   * stacked with no wrap; 538 of 644 typescript nodes are depth 1, so one column ran 43,114px down —
   * 52 screens of travel to reach a node. Asserted against the REAL packaged graph, because a synthetic
   * fixture cannot reproduce the depth-1 pile-up that caused it.
   */
  it("keeps the real typescript kit to a screen-shaped world, not a 43,000px column", () => {
    const laid = layoutKitGraph(kitGraph(KNOWLEDGE, "typescript"));
    expect(laid.pos.size).toBeGreaterThan(100);
    expect(laid.world.h).toBeLessThan(12_000);
    // Aspect, not just height: wrapping the depths alone was measured at 8,280px WIDE, which is the
    // same problem rotated. Neither side may run away from the other.
    const aspect = laid.world.h / laid.world.w;
    expect(aspect).toBeGreaterThan(0.2);
    expect(aspect).toBeLessThan(5);
  });

  it("gives every node a position, and never two nodes the same one", () => {
    const laid = layoutKitGraph(kitGraph(KNOWLEDGE, "typescript"));
    const seen = new Set([...laid.pos.values()].map((p) => `${p.x},${p.y}`));
    expect(seen.size).toBe(laid.pos.size);
  });

  it("is pure — the same graph lays out identically twice", () => {
    const g = kitGraph(KNOWLEDGE, "typescript");
    const a = layoutKitGraph(g);
    const b = layoutKitGraph(g);
    expect([...b.pos].map(([k, v]) => [k, v.x, v.y])).toEqual([...a.pos].map(([k, v]) => [k, v.x, v.y]));
  });

  it("bands are laid out in ORIGIN_BANDS order, each below the last", () => {
    const laid = layoutKitGraph(kit([
      impl("c1", { src: "crates/bsc-shot/src/lib.rs" }),
      impl("f1", { src: "src/features/glance/a.ts" }),
      impl("r1", {}),
    ]));
    const band = (o: string) => laid.clusters.find((c) => c.origin === o)!;
    expect(band("crates").y).toBeLessThan(band("features").y);
    expect(band("features").y).toBeLessThan(band("reference").y);
  });

  /** Depth is no longer the global axis, but base-to-derived must still read INSIDE a cluster. */
  it("orders a cluster by compose depth, shallowest first", () => {
    const nodes = [
      impl("deep.ts", { src: "src/shared/x/deep.ts", folder: "f", composes: ["mid.ts"] }),
      impl("mid.ts", { src: "src/shared/x/mid.ts", folder: "f", composes: ["base.ts"] }),
      impl("base.ts", { src: "src/shared/x/base.ts", folder: "f" }),
    ];
    const laid = layoutKitGraph(kit(nodes));
    const y = (id: string) => laid.pos.get(id)!.y;
    const x = (id: string) => laid.pos.get(id)!.x;
    // One column at this size, so "earlier" is "higher".
    expect(y("base.ts")).toBeLessThanOrEqual(y("mid.ts"));
    expect(y("mid.ts")).toBeLessThanOrEqual(y("deep.ts"));
    expect(new Set([x("base.ts"), x("mid.ts"), x("deep.ts")]).size).toBe(1);
  });

  it("an empty kit is a degenerate world rather than a crash", () => {
    const laid = layoutKitGraph(kit([]));
    expect(laid.pos.size).toBe(0);
    expect(laid.world.w).toBeGreaterThan(0);
    expect(laid.world.h).toBeGreaterThan(0);
    expect(laid.clusters).toEqual([]);
  });

  it("a single node still gets a real box", () => {
    const laid = layoutKitGraph(kit([impl("only.ts", { src: "src/shared/a/only.ts", folder: "a" })]));
    expect(laid.pos.size).toBe(1);
    expect(laid.world.h).toBeGreaterThan(NODE_H);
    expect(laid.clusters).toHaveLength(1);
    expect(laid.clusters[0].count).toBe(1);
  });
});

// THE TAB IS A LENS, NOT A PARTITION (`the-tab-is-a-lens-not-a-partition`).
//
// Selecting a language tab must change FOCUS — which nodes are laid out — and never which edges exist.
// The distinction is not decorative. Technology is a CURATION scope: `studioScopeDirective` splits the
// librarian per language so each curates its own partition, and that governs who may WRITE a record. It
// says nothing about what may REFERENCE one. The cross-graph URN grammar makes that concrete —
// `@bsc/algorithms/fibonacci` is kit-less, so a React component resolves a TypeScript implementation
// across both pillar AND technology (epic #3114, whose whole purpose was ending exactly that siloing).
//
// WHY THIS IS A GUARD AND NOT A FIX: measured against the seed today there are 578 within-language
// `composes` edges and ZERO that cross a language, so nothing is being dropped right now. `kitGraph`
// filters edges to targets inside the same language (`if (ids.has(c))`), which means the day someone
// adds a cross-language edge it will vanish from the view with no error and no warning — just a link
// that is not drawn. That is the failure this file exists to make loud, and it cannot be caught by
// eye: a missing edge looks exactly like an edge that was never authored.
import { describe, it, expect } from "vitest";
import { KNOWLEDGE, kitTechs, kitGraph, buildKnowledge, type AlgoImpl } from "@/features/algorithms/lib/knowledge";

/** Every `composes` edge in the graph whose target actually resolves, as `from->to`. */
const allResolvableEdges = (g: typeof KNOWLEDGE): Set<string> => {
  const ids = new Set(g.implementations.map((i) => i.id));
  const out = new Set<string>();
  for (const im of g.implementations) {
    for (const c of im.composes) if (ids.has(c)) out.add(`${im.id}->${c}`);
  }
  return out;
};

/** Every edge the UI actually renders, unioned across every tab a user can select. */
const renderedAcrossAllTabs = (g: typeof KNOWLEDGE): Set<string> => {
  const out = new Set<string>();
  for (const tech of kitTechs(g)) {
    for (const e of kitGraph(g, tech).edges) out.add(`${e.from}->${e.to}`);
  }
  return out;
};

describe("the language tab is a lens over the algorithms graph", () => {
  it("renders EVERY edge the store holds across the set of tabs — none is dropped", () => {
    // The property, stated directly: no tab selection may hide an edge from the graph entirely.
    const stored = allResolvableEdges(KNOWLEDGE);
    const rendered = renderedAcrossAllTabs(KNOWLEDGE);
    const missing = [...stored].filter((e) => !rendered.has(e));
    expect(
      missing,
      `${missing.length} edge(s) exist in the store but are drawn under NO tab — ` +
      `kitGraph drops any \`composes\` whose target is in another language. ` +
      `The tab must be a lens, not a partition: ${missing.slice(0, 5).join(", ")}`,
    ).toEqual([]);
    expect(stored.size).toBeGreaterThan(0); // the check is meaningless against an empty graph
  });

  it("FAILS LOUDLY for a graph that does have a cross-language edge — the guard actually guards", () => {
    // Proving the assertion above can fail. Without this, a tautology (an empty `missing` because
    // nothing is ever compared) would read exactly like a passing guard — which is the failure mode
    // this repo keeps getting caught by: a green check that sees less than the reader assumes.
    const im = (o: Partial<AlgoImpl> & Pick<AlgoImpl, "id" | "tech" | "name">): AlgoImpl =>
      ({ role: "algorithm", composes: [], ...o });
    const crossing = buildKnowledge({
      implementations: [
        im({ id: "caller.ts", tech: "typescript", name: "caller", composes: ["helper.rs"] }),
        im({ id: "helper.rs", tech: "rust", name: "helper" }),
      ],
    });
    expect(allResolvableEdges(crossing).has("caller.ts->helper.rs")).toBe(true);
    expect(
      renderedAcrossAllTabs(crossing).has("caller.ts->helper.rs"),
      "kitGraph drops a cross-language edge — this is the case the guard above is watching for",
    ).toBe(false);
  });

  it("gives each tab its own nodes, and every node exactly one tab", () => {
    // The other half of "focus, not partition": focus must be TOTAL and UNAMBIGUOUS. A node reachable
    // from no tab is unreachable in the UI; a node on two tabs is two copies of one record.
    const seen = new Map<string, number>();
    for (const tech of kitTechs(KNOWLEDGE)) {
      for (const n of kitGraph(KNOWLEDGE, tech).nodes) seen.set(n.id, (seen.get(n.id) ?? 0) + 1);
    }
    const unreachable = KNOWLEDGE.implementations.filter((i) => !seen.has(i.id)).map((i) => i.id);
    const duplicated = [...seen].filter(([, n]) => n > 1).map(([id]) => id);
    expect(unreachable, "impls reachable from no tab").toEqual([]);
    expect(duplicated, "impls appearing under more than one tab").toEqual([]);
  });
});

implementations.code:
// The Algorithms knowledge graph — pure model (#2761, epic #2760). React/Tauri-free so the tests, the
// page render, and the harvest lift all share ONE model. PRIMITIVES-ROOTED, impl-is-concept
// (#2958/#2961): each language kit is a graph of its implementations, rooted in that language's
// PRIMITIVES (Vec, Iterator, …) with algorithms composing UP from them. There is NO abstract concept
// layer — a node IS a concrete implementation. Loaded from the packaged seed
// (@data/knowledge/algorithms.json — the SAME source `bsc graph` embeds).
import { buildFolderTree, folderItemCount, type FolderNode } from "@/shared/lib/core/folderTree";
import RAW from "@data/knowledge/algorithms.json";

/** The languages a kit can be in (#2770). */
export type Tech = "typescript" | "rust";

/** The implementation techs, in display order. */
export const TECHS: Tech[] = ["typescript", "rust"];

/** Per-tech display label + file extension (an algorithm impl's id suffix) + rail dot color (a
 *  per-language identifier, the Algorithms analog of a Designs kit's `dot`). */
export const TECH_META: Record<Tech, { label: string; ext: string; dot: string }> = {
  typescript: { label: "TypeScript", ext: "ts", dot: "var(--info)" },
  rust: { label: "Rust", ext: "rs", dot: "var(--state-wait)" },
};

/** What KIND of thing a record is (#2863/#2958): a `primitive` is a LANGUAGE built-in
 *  (`rust.iterator`, `rust.vec`); an `algorithm` composes primitives + simpler algorithms up — the
 *  "base vs growing" distinction the rail groups by; a `test` is a module whose whole purpose is to
 *  check other records (`a-test-only-module-is-not-an-algorithm`).
 *
 *  A record is a `test` when its DECLARATION gates it out of production builds — `#[cfg(test)]` on the
 *  `mod` line — never because of its filename. The Rust mirror of this contract is `ROLES` in
 *  `crates/bsc-graph/src/lib.rs`, and the two must widen together: the store is untyped JSON, so a
 *  union narrower than the store holds is not a compile error here, it is a silent untruth. */
export type ImplRole = "primitive" | "algorithm" | "test";

/**
 * A unit of a language kit (#2863/#2958) — a node in one `tech`. The implementation IS the concept:
 * there is no abstract concept node. `role` splits **primitives** — a language BUILT-IN (`rust.vec`,
 * `rust.iterator`) that is DESCRIBED by its std `ref`, never re-coded (#2972) — from **algorithms**:
 * real reusable `code` that `compose`s OTHER impls of the SAME tech, growing UP from the primitive base
 * (e.g. `merge-sort.rs` composes `merge.rs`, `rust.vec`, `rust.slice`). `id` is `<name>.<ext>` for an
 * algorithm, `<tech>.<name>` for a primitive.
 */
/** The manipulation KINDS an algorithm can carry (#3210, epic #3209) — the "what it does" axis of the
 *  animation (`sort`/`search`/…), paired with the DATA STRUCTURE it operates on to pick the live
 *  visualization. Grows as more example animations land (matrix ops, etc.). */
export const ALGO_KINDS = ["sort", "search", "traversal", "accumulate", "transform"] as const;
export type AlgoKind = (typeof ALGO_KINDS)[number];

export interface AlgoImpl {
  /** sha256 of the record's source, set by `graph_dump`'s index projection — the index carries no
   *  bodies, so this is what tells a consumer the source MOVED. Absent on a record with no source, and
   *  absent from the packaged seed, which carries the bodies themselves. */
  codeHash?: string;
  /** `<name>.<ext>` (algorithm) or `<tech>.<name>` (primitive) — e.g. "merge-sort.rs", "rust.iterator". */
  id: string;
  tech: Tech;
  /** What kind of record this is (#2863) — `primitive` (a language built-in), `algorithm` (composed
   *  production logic), or `test` (a module that checks other records). See {@link ImplRole}. */
  role: ImplRole;
  name: string;
  summary?: string;
  /** OTHER implementation ids of the same tech this builds on — the "builds on" edges, pointing DOWN
   *  to the primitive base. */
  composes: string[];
  /** A primitive's std reference — the language built-in it names (`std::vec::Vec`, `i64`). Primitives
   *  are DESCRIBED, not re-coded (#2972); algorithms leave this unset. */
  ref?: string;
  /** An algorithm's real, reusable implementation in `tech`. Optional for a primitive — a language
   *  built-in is described (`ref` + `summary`), not re-coded (#2972). */
  code?: string;
  /** The `@/…` import specifier this impl SATISFIES, set by a module-granularity harvest
   *  (`bsc graph harvest --module`). Present only on impls that are whole MODULES: a function lifted out
   *  of a file satisfies no import, so the field stays absent there rather than null. It is what
   *  `resolveGraphSource` matches on, and the only thing that lets a component's import reach the
   *  algorithms graph at all — components resolve by specifier, algorithms otherwise compose by id. */
  provides?: string;
  /** PROVENANCE (#4091/#4107) — the scanned-root-relative path of the file this was harvested from.
   *  The Rust mirror is `AlgoImpl.src`. Absent on anything authored before it (every seeded impl). */
  src?: string;
  /** The module's TOP-LEVEL MUTABLE BINDINGS — the state it holds, named. Set by a module-granularity
   *  harvest; absent (never `[]`) on a pure module and on any function-granularity impl, which is a
   *  fragment of a file and so holds none of the file's module state.
   *
   *  This is the property that decides whether vendoring the record is equivalent to importing the
   *  module. `provides` makes the loader hand a graph consumer this source INSTEAD of the bundled
   *  module, so a module holding state gives that consumer a SECOND instance of it — a second queue,
   *  a second cache, a second timer — and the two diverge with nothing on screen to say so. Naming the
   *  bindings is what makes that visible rather than something each reader rediscovers in the source. */
  moduleState?: string[];
  /** The FOLDER (#4107) — the nested, `/`-delimited path this impl organizes under, derived from
   *  {@link src} by the SAME derivation components use (`bsc_util::folder_from_src`). Harvest is 1:1:
   *  the folder mirrors where the code actually lives, so the library reads like the tree it came from.
   *  Absent ⇒ the impl is UNFOLDERED and the rail lists it directly under its language. */
  folder?: string;
  /** Optional DOMAIN facet (#3120) — the lightweight, cross-language collection this impl belongs to
   *  (e.g. "logistics", "graphics"). ADDITIVE + backward-compatible: impls authored before the facet
   *  existed have no `domain` and are simply absent from every domain collection, so nothing breaks. A
   *  domain cross-cuts language, so a domain app can pull its relevant subset of the library — all
   *  `logistics` algorithms, across languages. Curated via `bsc graph impl set --domain <d>`. */
  domain?: string;
  /** Optional free-form tags (#3120) — additive keywords for search / cross-cutting collections. Absent
   *  on existing impls; curated via `bsc graph impl set --tags a,b,c`. */
  tags?: string[];
  /** Optional KIND facet (#3210) — the manipulation this algorithm performs (`sort`/`search`/…), the
   *  "what it does" axis that (with its data structure) selects the live animation. ADDITIVE + backward-
   *  compatible: the CREATOR assigns it (`bsc graph impl set --kind sort`), and a heuristic classifier
   *  fills it for untyped impls; absent on impls authored before the facet, so nothing breaks. */
  kind?: AlgoKind;
  /** Optional VIZ-CODE facet (#3218, epic #3215) — the algorithm's VISUALIZATION as data: a JS
   *  trace-program the executor (#3232) runs to DERIVE the animation from the real algorithm. It is a JS
   *  EXPRESSION evaluating to a self-describing descriptor `{ datatype, input, run }` — `datatype` is
   *  `"array" | "matrix" | "graph"` (picks the renderer + input seam), `input` is the default input, and
   *  `run(structure)` is the algorithm written against the matching Traced<Structure> API. The visualizable
   *  form of an impl whose reference `code` can't run in the browser (e.g. Rust). ADDITIVE; the librarian
   *  authors it (`bsc graph impl set --viz-code`). Absent (or malformed) ⇒ the impl falls back to an in-app
   *  trace-program (the sort family / matrix transforms / graph traversals) or shows no animation. */
  vizCode?: string;
}

/** The knowledge model — the per-language implementation tier (#2958); the abstract concept ontology
 *  (nodes/edges) was removed with #2961 (a node IS its implementation). */
export interface KnowledgeGraph {
  implementations: AlgoImpl[];
}

/** The raw graph document shape — `@data/knowledge/algorithms.json` and `bsc graph dump` (#2853). */
export interface RawKnowledge {
  implementations?: AlgoImpl[];
}

/** Build the model from a raw graph document, defaulting missing implementations to []. Shared by the
 *  packaged seed AND the live hydrate from the writable store (#2856), so both produce the identical
 *  model. Pure.
 *
 *  # It NORMALISES `composes`, and that is not defensive padding
 *
 *  `AlgoImpl` declares `composes: string[]` — required — and the store does not guarantee it. This is
 *  the one boundary where raw JSON becomes the typed model, so it is the only place that promise can be
 *  made true; every consumer downstream is written against the type and reaches for the field without a
 *  guard (`graphSig` does `im.composes.join(",")`, `usedByImpl` does `.includes()`, the inspector does
 *  `.map()`).
 *
 *  ONE record arriving without it took the whole page down. `bsc-bluetooth--tests.rs` landed in the
 *  writable store with no `composes`; `graphSig` threw inside the hydrate poll, `setGraph` never ran,
 *  and `useKnowledgeGraph` silently kept the packaged seed — so the Algorithms graph showed 758 records
 *  instead of 1,403 and 36 crate records instead of 542, with no error anywhere a user could see. A
 *  missing optional field should cost one record's edges, never the entire hydrate. */
export function buildKnowledge(raw: RawKnowledge): KnowledgeGraph {
  return {
    implementations: (raw.implementations ?? []).map((im) =>
      Array.isArray(im?.composes) ? im : { ...im, composes: [] },
    ),
  };
}

/** The packaged seed graph — the fast-first-paint fallback + the ONE source `bsc graph` embeds. The live
 *  Algorithms view hydrates from the writable store (`bsc graph dump`, #2856) over this. */
export const KNOWLEDGE: KnowledgeGraph = buildKnowledge(RAW as unknown as RawKnowledge);

// ── The per-tech implementation tier — pure lookups over `graph.implementations`. ──

/** An implementation by its id (e.g. "merge-sort.rs"), or `undefined`. */
export function implById(graph: KnowledgeGraph, id: string): AlgoImpl | undefined {
  return graph.implementations.find((im) => im.id === id);
}

/** The implementations that `compose` `implId` — the reverse of `composes` ("used by"). */
export function usedByImpl(graph: KnowledgeGraph, implId: string): AlgoImpl[] {
  return graph.implementations.filter((im) => im.composes.includes(implId));
}

// ── Language kits (#2863) — a kit is every implementation of one `tech`; navigation groups a kit by
// `role` (primitives → algorithms) the way the Designs rail groups a kit by component role. ──

/** The techs that carry at least one implementation — the language kits present, in {@link TECHS}
 *  order first, then any others in seed order. */
export function kitTechs(graph: KnowledgeGraph): Tech[] {
  const seen = graph.implementations.map((im) => im.tech);
  const ordered = TECHS.filter((t) => seen.includes(t));
  const extras = seen.filter((t, i) => seen.indexOf(t) === i && !ordered.includes(t));
  return [...ordered, ...extras];
}

/** Every implementation in a language kit (all impls of `tech`), in seed order. */
export function kitImpls(graph: KnowledgeGraph, tech: Tech): AlgoImpl[] {
  return graph.implementations.filter((im) => im.tech === tech);
}

/** A kit's implementations of one `role` (its primitives, or its algorithms). */
export function kitImplsByRole(graph: KnowledgeGraph, tech: Tech, role: ImplRole): AlgoImpl[] {
  return graph.implementations.filter((im) => im.tech === tech && im.role === role);
}

// ── The language-folder rail model (#2899) — mirror the Designs rail (kitGroups.ts): each LANGUAGE is a
// folder (like each technology is a folder in Components), its impls the rows. Pure, so the rail render +
// tests share one model. ──

/** A language folder in the Algorithms rail — a `tech` and its implementations (primitives first). */
export interface AlgoLangGroup {
  tech: Tech;
  label: string;
  /** Stable expand-state key (`lang:<tech>`). */
  key: string;
  /** The folder-head color dot — the per-language identifier (#2902), like a Designs kit's `dot`. */
  dot: string;
  /** The kit's impls, primitives before algorithms, each in seed order. */
  impls: AlgoImpl[];
}

/** Group the implementations into one folder per language (#2899) — the rail tree. Languages in
 *  {@link kitTechs} order; within a folder, primitives lead the algorithms (the "base then grows up"
 *  reading). Pure + deterministic. */
export function groupImplsByLanguage(graph: KnowledgeGraph): AlgoLangGroup[] {
  return kitTechs(graph).map((tech) => ({
    tech,
    label: TECH_META[tech]?.label ?? tech,
    key: `lang:${tech}`,
    dot: TECH_META[tech]?.dot ?? "var(--fg-muted)",
    impls: [...kitImplsByRole(graph, tech, "primitive"), ...kitImplsByRole(graph, tech, "algorithm")],
  }));
}

/** One folder of a language's tree — the shared {@link FolderNode} bound to {@link AlgoImpl}. Since
 *  #4128 this is the SAME node the components rail renders, so the two libraries cannot drift apart on
 *  what a folder is. */
export type AlgoFolderNode = FolderNode<AlgoImpl>;

/** Total impls under a folder, transitively — the folder header's count. */
export const folderImplCount = folderItemCount<AlgoImpl>;

/**
 * Partition a language kit's impls into a nested FOLDER TREE by their {@link AlgoImpl.folder} path
 * (#4107) — the algorithms-typed binding of the shared {@link buildFolderTree} (#4128), the same one
 * `groupComponentsByFolder` binds for components.
 *
 * Impls with no folder land in the trailing "ungrouped" bucket rather than spilling flat beside the
 * tree, which is what the components rail has always done — before #4128 this side spilled them, and a
 * mostly-unfoldered library (the seeded classics carry no `src` to derive a folder from) therefore read
 * as a flat list with a few folders wedged on top.
 *
 * Returns `null` when NO impl carries a folder, so a wholly unfoldered kit renders its flat list
 * exactly as it would without folders at all.
 */
export function folderTree(impls: readonly AlgoImpl[]): AlgoFolderNode[] | null {
  return buildFolderTree(impls, (im) => im.folder);
}

/** Does an impl match a free-text rail query (name / id / folder path / tag, case-insensitive)? Mirrors
 *  the components rail's `matchesQuery` (#3589) — the folder path matches too, so a query like
 *  `viz/examples` filters the rail to a folder. Empty query → all. Pure. */
export function matchesImpl(im: AlgoImpl, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return (
    im.name.toLowerCase().includes(q) ||
    im.id.toLowerCase().includes(q) ||
    (im.folder ?? "").toLowerCase().includes(q) ||
    (im.tags ?? []).some((t) => t.toLowerCase().includes(q))
  );
}

// ── The per-kit graph (#2863/#2958) — the kit's OWN graph: nodes are its implementations (a concept IS
// its implementation), wired by `composes` (builds-on, pointing down to the primitive base). Per-language,
// not deduped: each kit renders only its own impls. This is what a kit's center graph draws. ──

/** A per-kit edge relationship — just `composes` now the abstract ontology is gone (#2961). */
export type KitRel = "composes";

/** Per-kit-rel display label + edge style. Shared by the kit-graph canvas AND the on-graph legend (#2909)
 *  so the key never drifts from the drawn edges. */
export const KIT_REL_META: Record<KitRel, { label: string; dashed?: boolean; doubleEnded?: boolean }> = {
  composes: { label: "composes" },
};

/** The order kit-rel legend rows read in. */
export const KIT_REL_ORDER: KitRel[] = ["composes"];

/** An edge in a kit graph — endpoints are implementation ids. */
export interface KitEdge { from: string; to: string; rel: KitRel }

/** A language kit as its own graph: the kit's impls + the `composes` edges between them. */
export interface KitGraph { nodes: AlgoImpl[]; edges: KitEdge[] }

/**
 * Build a kit's own graph (#2863/#2958) from `graph.implementations`, scoped to `tech`: each impl → the
 * same-tech impls it `composes` (the "grows up from the primitive base" edges). The abstract concept
 * ontology is gone (#2961), so `composes` is the only edge. Pure.
 */
export function kitGraph(graph: KnowledgeGraph, tech: Tech): KitGraph {
  const nodes = kitImpls(graph, tech);
  const ids = new Set(nodes.map((n) => n.id));
  const edges: KitEdge[] = [];
  for (const im of nodes) {
    for (const c of im.composes) if (ids.has(c)) edges.push({ from: im.id, to: c, rel: "composes" });
  }
  return { nodes, edges };
}

// ── Layout — the kit graph columns by compose depth (primitives at the base, algorithms deepening right). ──

/** A node's laid-out position (top-left, world coords). */
export interface NodePos { x: number; y: number }

/** A design-space box — matches the viewport's `GraphBox` so it can drive `contentBounds`. */
export interface Box { x: number; y: number; w: number; h: number }

export interface KnowledgeLayout {
  pos: Map<string, NodePos>;
  world: { w: number; h: number };
  /** The bounding box of the actual nodes — framed by `fit()` so the graph centers on content. */
  bounds: Box;
  /** The laid-out cluster boxes, for the canvas to caption. Present so the grouping is VISIBLE: an
   *  unlabelled pack reads as an arbitrary grid, and the whole point is that the region means
   *  something the rail also names. */
  clusters: ClusterBox[];
}

/** Node box size (world px) — shared by the layout and the canvas card. */
export const NODE_W = 172;
export const NODE_H = 58;
const PAD = 48;
/** Cell pitch INSIDE a cluster. Tight: a cluster's members are adjacent, so no edge gutter is owed. */
const CELL_W = NODE_W + 20;
const CELL_H = NODE_H + 16;
const LABEL_H = 26;
const CLUSTER_GAP = 30;
const BAND_GAP = 56;
/**
 * Width the packer wraps clusters at — the ONE tuning knob. Raising it makes the world wider and
 * shorter. MEASURED over the real store at 3800: 3,894 x 6,146 (1.58:1), against 3,308 x 43,114
 * (13:1) before.
 *
 * Deliberately NOT a viewport measurement. The world must be stable for a given graph; a layout that
 * reflowed on window resize would move every node out from under the reader's cursor.
 */
const BAND_W = 3800;
/** Slightly wide clusters read better than square ones at this cell ratio. */
const CLUSTER_ASPECT = 1.9;

/**
 * The bands, in draw order. A node's ORIGIN — where its code actually lives — is the coarse axis, so
 * crate code and frontend code occupy separate regions instead of interleaving. That separation is what
 * the crate migration needs: `crates/*` records are a different population from `src/*` ones, and the
 * reference algorithms (textbook `a-star.rs`, `bfs.rs`) are a third that belongs in neither.
 */
export const ORIGIN_BANDS = [
  "crates", "backend", "features", "shared", "shell", "store", "reference", "built-ins", "other",
] as const;
export type Origin = (typeof ORIGIN_BANDS)[number];

/** Which band a node belongs to. From `src` (94% populated); `role`/absence covers the rest. */
export function originOf(im: AlgoImpl): Origin {
  if (im.role === "primitive") return "built-ins";
  const s = im.src ?? "";
  if (!s) return "reference";
  if (s.startsWith("crates/")) return "crates";
  if (s.startsWith("src-tauri/")) return "backend";
  if (s.startsWith("src/features/")) return "features";
  if (s.startsWith("src/shared/")) return "shared";
  if (s.startsWith("src/app")) return "shell";
  if (s.startsWith("src/store")) return "store";
  return "other";
}

/**
 * The cluster a node sits in inside its band — the CRATE for crate code, the FEATURE for a feature
 * module, else the folder. Chosen because THE RAIL ALREADY NAVIGATES BY FOLDER, so the canvas and the
 * rail finally describe the same structure rather than being two unrelated views of one graph.
 */
export function clusterOf(im: AlgoImpl): string {
  const s = im.src ?? "";
  if (s.startsWith("crates/")) return s.split("/")[1] || "crates";
  if (s.startsWith("src/features/")) return s.split("/")[2] || "features";
  return im.folder || im.domain || "general";
}

/** Rows/cols for `n` cells, aiming at {@link CLUSTER_ASPECT}. */
function gridFor(n: number): { cols: number; rows: number } {
  const cols = Math.max(1, Math.round(Math.sqrt((n * CLUSTER_ASPECT * CELL_H) / CELL_W)));
  return { cols, rows: Math.ceil(n / cols) };
}

/** Per-impl "compose depth": a primitive is the base (0); an algorithm is 1 + the deepest in-kit impl
 *  it composes (min 1). No longer the global X axis — 84% of a real kit shares depth 1, so as a column
 *  key it sorted nothing. It survives as the ORDER WITHIN a cluster, where base-to-derived still reads.
 *  Cycle-guarded (composes shouldn't cycle, but a bad kit won't hang). */
function composeDepth(kit: KitGraph): Map<string, number> {
  const byId = new Map(kit.nodes.map((n) => [n.id, n]));
  const memo = new Map<string, number>();
  const visiting = new Set<string>();
  const depth = (id: string): number => {
    if (memo.has(id)) return memo.get(id)!;
    const node = byId.get(id);
    if (!node || node.role === "primitive") { memo.set(id, 0); return 0; }
    if (visiting.has(id)) return 1; // cycle guard
    visiting.add(id);
    const composed = node.composes.filter((c) => byId.has(c));
    const d = composed.length ? 1 + Math.max(...composed.map(depth)) : 1;
    visiting.delete(id);
    memo.set(id, d);
    return d;
  };
  for (const n of kit.nodes) depth(n.id);
  return memo;
}

/** A laid-out cluster: its caption, its box, and how many nodes it holds. */
export interface ClusterBox {
  origin: Origin;
  label: string;
  x: number;
  y: number;
  w: number;
  h: number;
  count: number;
}

/**
 * Lay a kit graph out as ORIGIN BANDS of FOLDER CLUSTERS, depth-ordered inside each cluster.
 *
 * It replaced a column-per-`composeDepth` stack with NO row wrap, which put 538 of 644 typescript nodes
 * in one column and produced a 3,308 x 43,114 world — 52 screens of vertical travel to reach a node.
 * Wrapping the depths alone was measured too, and merely traded that for 8,280px of width: depth cannot
 * be the organising axis when 84% of a kit shares one value.
 *
 * Pure + deterministic — positions are keyed by impl id and depend only on `kit`, so the same graph lays
 * out identically every time and the same canvas/viewport draw it.
 */
export function layoutKitGraph(kit: KitGraph): KnowledgeLayout {
  const depths = composeDepth(kit);
  const pos = new Map<string, NodePos>();
  const clusters: ClusterBox[] = [];

  const bands = new Map<Origin, Map<string, AlgoImpl[]>>();
  for (const n of kit.nodes) {
    const o = originOf(n);
    const c = clusterOf(n);
    let byCluster = bands.get(o);
    if (!byCluster) {
      byCluster = new Map();
      bands.set(o, byCluster);
    }
    const list = byCluster.get(c);
    if (list) list.push(n);
    else byCluster.set(c, [n]);
  }

  let y = PAD;
  let worldW = 0;
  for (const origin of ORIGIN_BANDS) {
    const byCluster = bands.get(origin);
    if (!byCluster) continue;
    // Largest first: shelf packing wastes least when the tall blocks are placed early. The name
    // tiebreak keeps two equally sized clusters in a stable order run to run.
    const ordered = [...byCluster.entries()].sort(
      (a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]),
    );

    let x = PAD;
    let shelfH = 0;
    const bandTop = y + LABEL_H;
    let bandBottom = bandTop;
    for (const [label, members] of ordered) {
      const { cols } = gridFor(members.length);
      const rows = Math.ceil(members.length / cols);
      const w = cols * CELL_W;
      const h = rows * CELL_H + LABEL_H;
      if (x > PAD && x + w > BAND_W) {
        y = bandBottom + CLUSTER_GAP;
        x = PAD;
        shelfH = 0;
      }
      const top = Math.max(y, bandTop);
      const sorted = [...members].sort(
        (a, b) => (depths.get(a.id) ?? 0) - (depths.get(b.id) ?? 0) || a.name.localeCompare(b.name),
      );
      sorted.forEach((n, i) => {
        pos.set(n.id, { x: x + (i % cols) * CELL_W, y: top + LABEL_H + Math.floor(i / cols) * CELL_H });
      });
      clusters.push({ origin, label, x, y: top, w, h, count: members.length });
      x += w + CLUSTER_GAP;
      shelfH = Math.max(shelfH, h);
      bandBottom = Math.max(bandBottom, top + shelfH);
      worldW = Math.max(worldW, x);
    }
    y = bandBottom + BAND_GAP;
  }

  const world = { w: worldW + PAD, h: Math.max(y - BAND_GAP, PAD) + PAD };
  const bounds: Box = {
    x: PAD,
    y: PAD,
    w: Math.max(world.w - PAD * 2, 0),
    h: Math.max(world.h - PAD * 2, 0),
  };
  return { pos, world, bounds, clusters };
}

// Role gate (#219) — launch wiring. Renders a role's capability into the concrete permission
// artifacts a session is launched with: the write-tool `permissions.allow`/`deny` rules
// ({@link roleWriteRules}), whole-tool denies ({@link roleDeniedTools}), the command-prefix denies
// merged into the allowlist ({@link roleDeniedCommands}), and the bsc-agent-native permission doc
// ({@link bscAgentPerms}). Pure enforcement core, free of React / xterm / Tauri. Re-exported from
// `sessionRoles.ts`.

import type { AccessTier, RoleCapability } from "@/shared/lib/session/roleModel";
import { capabilitySurfaces, DB_OWNED_PLAN_FILES, DEP_MANIFEST_FILES, hasScopedWriteCarveOut, isRestrictedRole, mayFileToolingRequest, TOOLING_REQUEST_COMMAND } from "@/shared/lib/session/roleModel";

// ── Launch wiring: write-tool permission rules ──────────────────────────────────

/** The file-mutating tools gated by a WHOLE-TOOL deny (bare tool name, no path). Claude Code has no
 *  `MultiEdit` tool (removed) and a bare `Edit` deny does NOT cover `Write`/`NotebookEdit` — they are
 *  separate tools — so all three must be listed to block every file write (#3534). */
const WRITE_TOOLS = ["Edit", "Write", "NotebookEdit"];

/** A PATH-SCOPED file rule uses ONLY `Edit(<glob>)`: Claude Code matches file-permission rules on the
 *  `Edit` tool alone, and that ONE rule covers every file-editing tool (Write/NotebookEdit). Emitting
 *  `Write(<glob>)`/`NotebookEdit(<glob>)`/`MultiEdit(<glob>)` produces rules Claude Code never matches —
 *  a silent no-op for an allow, and (worse) an unenforced deny (#3534). */
export const editPathRule = (glob: string): string => `Edit(${glob})`;

export interface ToolPermissionRules {
  /** Rules to auto-approve (Claude Code `permissions.allow`). */
  allow: string[];
  /** Rules to block (`permissions.deny`; deny wins over allow). */
  deny: string[];
}

/**
 * Declarative `settings.json` permission rules that encode {@link canWritePath} for
 * the file-write tools at session launch — the write-tool counterpart to
 * {@link roleDeniedCommands}.
 *
 * - `code: "none"` (planner/director/triage) — {@link canWritePath} is always false,
 *   so deny every write tool outright (bare tool names = whole-tool deny).
 * - `code: "write"` with a boundary — auto-approve each `writeGlob` as
 *   `Tool(<glob>)` allow rules (exactly the paths {@link canWritePath} accepts).
 *   Writes outside the boundary fall through to Claude Code's default prompt; a
 *   hard outside-boundary *block* is the PreToolUse-hook follow-on.
 * - `code: "write"` with no boundary yet — no rules (writes follow the default),
 *   since the ownership globs aren't assigned to the pane.
 *
 * {@link canWritePath} stays the authoritative runtime predicate; these rules mirror
 * it into the tools at launch.
 */
export function roleWriteRules(cap: RoleCapability): ToolPermissionRules {
  if (cap.code === "none") {
    // Scoped carve-out (#851): a `code: "none"` role WITH explicit writeGlobs (the director's
    // commons) auto-approves the write tools for EXACTLY those globs. Claude Code's precedence is
    // deny > allow, so the whole-tool deny would mask any narrower allow — instead of denying the
    // bare tools we emit only the per-glob allows. Any write OUTSIDE the commons falls through to
    // the default prompt and is hard-blocked by the bsc-scope hook ({@link scopeWriteGlobs}), so
    // the director can write the commons and is denied all other code writes.
    if (hasScopedWriteCarveOut(cap)) {
      return { allow: cap.writeGlobs.map(editPathRule), deny: [] };
    }
    return { allow: [], deny: [...WRITE_TOOLS] };
  }
  const allow = cap.writeGlobs.map(editPathRule);
  // Role-specific deny set, layered over the write-glob allows (deny wins over allow):
  // - director / planner: the DB-owned plan-state artifacts (#1070) — the plan globs would otherwise
  //   auto-approve a stray `deploy.md`/`phases.json`; force them to the `bsc plan` CLI. The DIRECTOR
  //   is listed because it now carries the planning write surface — omitting it would have handed the
  //   merged role file-level write over exactly the plan state plan.db is supposed to own.
  // - worker: the dependency manifests + lockfiles (#1111) — the planner locks deps once and
  //   publish seeds them, so a worker editing its own manifest is the parallel-redefinition that
  //   collides at integration; a new dep routes through the director.
  const denyFiles = cap.role === "planner" || cap.role === "director" ? DB_OWNED_PLAN_FILES
    : cap.role === "worker" ? DEP_MANIFEST_FILES
    : [];
  const deny = denyFiles.map(editPathRule);
  return { allow, deny };
}

/**
 * Whole-tool denies by role BEYOND the write-path tools (#1036) — currently the sub-agent **Task**
 * tool for **workers**. A worker must not spawn its OWN sub-agents: each spawned agent reads as
 * fresh activity that the always-on coordinator keeps trying to relaunch the worker for (a wake
 * request every poll), and it blurs the worker's lane. A worker does its assigned issue directly;
 * spinning up helper sessions is the director's job. Denied by bare tool name — the same whole-tool
 * deny {@link roleWriteRules} uses for Edit/Write — so it's a hard block at launch, no prompt, no
 * delay. Merged into `denyToolRules` at session launch.
 */
export function roleDeniedTools(cap: RoleCapability): string[] {
  const out: string[] = [];
  if (cap.role === "worker") out.push("Task");
  // Network gate (#1107): `net: "none"` denies the web tools outright at launch — the lever that
  // turns OFF the planner's (or any agent's) live injection surface. `read` (the default) leaves
  // them allowed, with results framed as untrusted data.
  if (cap.net === "none") out.push("WebFetch", "WebSearch");
  return out;
}

// ── Launch wiring: command-allowlist denies ────────────────────────────────────

/** git write subcommand prefixes (the backend wraps each as `Bash(<prefix> *)`). */
const GIT_WRITE_DENY = [
  "git push", "git commit", "git merge", "git rebase", "git reset", "git revert",
  "git cherry-pick", "git tag", "git am", "git apply",
];

/** gh write command prefixes + writing `gh api` methods. */
const GH_WRITE_DENY = [
  "gh issue create", "gh issue edit", "gh issue close", "gh issue reopen",
  "gh issue comment", "gh issue delete", "gh issue lock", "gh issue transfer", "gh issue pin",
  "gh pr create", "gh pr merge", "gh pr close", "gh pr edit", "gh pr comment", "gh pr ready", "gh pr review",
  "gh label create", "gh label edit", "gh label delete",
  "gh release create", "gh release edit", "gh release delete",
  "gh repo create", "gh repo edit", "gh repo delete",
  "gh api --method POST", "gh api --method PATCH", "gh api --method PUT", "gh api --method DELETE",
  "gh api -X POST", "gh api -X PATCH", "gh api -X PUT", "gh api -X DELETE",
];

/** `bsc ui` (component/kit store) mutating verb prefixes (#2470) — denied at `ui: "read"` so a
 *  session can READ the kit it implements against but never redefine it. Includes the deprecated
 *  `bsc component` alias's verbs while that alias lives (#2469); deny-wins keeps these solid over
 *  the baseline's broad `bsc` allow. */
const UI_WRITE_DENY = [
  "bsc ui set", "bsc ui remove", "bsc ui kit set", "bsc ui kit remove",
  "bsc component set", "bsc component remove", "bsc component kit set", "bsc component kit remove",
];

/** File-mutating shell commands denied for a WRITE-LESS role (#2932) — the bash counterpart to the
 *  whole-tool Edit/Write deny in {@link roleWriteRules}. A `code: "none"` role with no scoped write
 *  carve-out writes NOTHING: not via the Edit/Write tools (already denied), and not via bash either —
 *  otherwise (as happened) a session bypasses the tool-deny with `tee`/`cp`/`echo > file` and mutates
 *  the repo (e.g. `src-tauri/data/`, triggering a rebuild). Denies the common file writers; shell
 *  redirection (`>`) can't be prefix-denied and is caught by the always-on `bsc-confine` FS hook.
 *  Carve-out roles (documentor/marketer/a commons director) and writers (planner/worker) are EXCLUDED —
 *  they write their scoped globs via the Write tool, not bash. */
const FILE_WRITE_DENY = [
  "tee", "dd", "truncate", "install", "cp", "mv", "ln", "patch", "sponge",
  "sed -i", "sed --in-place", "perl -i",
  "vi", "vim", "nano", "emacs", "ed", "ex",
];

/**
 * Command-prefix denies to apply at session launch for a role, merged into the
 * session's `deniedCommands` (the backend wraps each as `Bash(<prefix> *)`, and a
 * specific deny overrides the broad `git`/`gh` allow). A first-layer gate: blocks the
 * args-bearing mutating commands while leaving reads alone. `none` tiers deny the tool
 * outright.
 *
 * This is the launch-time allowlist layer; complete subcommand-granular enforcement
 * (incl. no-arg variants) is a PreToolUse hook (follow-on), and the authoritative
 * publish gate is `checkCommand` at the executor call site.
 */
/** The persona store's mutating verbs — architect-only (see {@link roleDeniedCommands}). `rename` is
 *  included because a persona's NAME is how every other surface refers to it, so renaming one out from
 *  under a team is a mutation like any other. */
const PERSONA_WRITE_DENY = ["bsc persona set", "bsc persona remove", "bsc persona rename"];

/**
 * Interpreters a RESTRICTED role may not reach for — the "pipe into an interpreter" case its own
 * spec already forbids in prose.
 *
 * The designer's spec says it outright: "You do **not** have `node`, `python`, `jq` ... and reaching
 * for one will be refused — not as a mistake, but by design: your shell surface is an allow-list."
 * That was PROSE ONLY. Nothing denied an interpreter; it simply was not in the allow-list, so it
 * PROMPTED and was approved. A promise the environment does not keep teaches the opposite of what
 * it says, and the session learns the rule does not apply.
 *
 * MEASURED before writing this: one designer session made 555 Bash calls, 37 of them python — every
 * one post-processing `bsc` JSON (selecting a field, counting a length, looping over ids), and the
 * session had run `which python3 node jq` first, so it went looking for a way around.
 *
 * Written as bare PROGRAM NAMES on purpose. `deny_matches` (bsc-util/src/deny.rs) gives a bare name
 * program-TOKEN semantics: it takes the first word of every pipeline segment and recurses into
 * `sh -c`, so `bsc ui get x | python3 -c '…'` is caught. A `Bash(python3 *)` prefix rule would not
 * have been — and the observed misuse was almost entirely piped, which is exactly the shape a
 * workaround takes.
 *
 * RESTRICTED roles only. A worker legitimately builds and tests; a studio whose entire surface is
 * one store CLI has no use for an interpreter that its spec has not already told it to avoid.
 */
const INTERPRETER_DENY = ["python", "python3", "node", "jq", "perl", "ruby"];

export function roleDeniedCommands(cap: RoleCapability, activeSurfaces: readonly string[] = []): string[] {
  const out: string[] = [];
  // The COMMAND-SURFACE complement (`a-persona-declares-its-command-surfaces`). `bsc` sits in the
  // permission model's `mandatory` tier (`data/permissions/base.json`) — always allowed, every role,
  // every posture — so a role that declares no surfaces reaches ALL of them. A role that DOES declare
  // them is held to exactly that set by denying every active catalog surface it did not name.
  //
  // `activeSurfaces` is the ONE catalog (`bsc surface list --json`), passed in rather than restated:
  // `bsc surface help` says outright that the role join belongs at the consumer, and three plan items
  // already exist for hand-kept copies of this set drifting from what really dispatches.
  //
  // FAIL-OPEN ON AN EMPTY CATALOG, deliberately. The catalog is read from a subprocess, so
  // "unavailable" and "no surfaces exist" are indistinguishable here. Complementing against an empty
  // list denies nothing, which is the safe direction: the alternative would brick every session the
  // moment that read failed. A declared list NARROWS an already-granted surface — it is not the grant.
  //
  // The pattern carries a SPACE, which is load-bearing: `deny_matches` (bsc-util/src/deny.rs) keeps
  // substring semantics for anything that is not a bare program name, so `bsc atlas` matches
  // `bsc atlas list …` while a bare `bsc` would deny the entire CLI. Same shape as the
  // TOOLING_REQUEST_COMMAND deny below, which is the precedent this generalizes.
  const declared = capabilitySurfaces(cap);
  if (declared) {
    for (const surface of activeSurfaces) {
      if (!declared.includes(surface)) out.push(`bsc ${surface}`);
    }
  }
  if (cap.git === "none") out.push("git");
  else if (cap.git === "read") out.push(...GIT_WRITE_DENY);
  if (cap.github === "none") out.push("gh");
  else if (cap.github === "read") out.push(...GH_WRITE_DENY);
  // UI store tier (#2470), rendered like git/gh. FAIL-CLOSED on the tier: only an explicit
  // `"write"` skips the mutating-verb denies, so a capability read from a STALE config-dir
  // override that predates the `ui` field (#2325 floor-merge hazard — the merged role OBJECT can
  // lack it) behaves as `"read"`, never as an accidental grant.
  if (cap.ui === "none") out.push("bsc ui", "bsc component");
  else if (cap.ui !== "write") out.push(...UI_WRITE_DENY);
  // `graph: none` denies the SURFACE, so `none` means for the algorithms store exactly what it means
  // for the component store one line up — a tier rather than a synonym for `read`.
  //
  // Only the `none` arm, deliberately. `ui: read` also denies its mutating COMMANDS here, which buys a
  // launch-time prompt; the algorithms store's write gate lives in the `bsc-graph` binary, and that is
  // strictly stronger — `permissions.deny` is ignored under the bypass posture while the CLI refusal
  // is not (`the-algorithms-graph-has-no-write-gate`).
  if (cap.graph === "none") out.push("bsc graph");
  // A write-less role (code:none, no carve-out) writes NOTHING — deny the file-mutating bash commands
  // too, the counterpart to its whole-tool Edit/Write deny (#2932). Shell redirection (`>`) can't be
  // prefix-denied; the always-on `bsc-confine` FS hook is the complete layer.
  //
  // A RESTRICTED role keeps these denies even though it HAS a carve-out (#3373). Its carve-out is a
  // tool-only staging dir: it writes `scratch/**` with the Write tool and applies it with its one store
  // CLI. It has no business running `cp`/`mv`/`tee`/`sed -i` at all — its spec says in as many words
  // not to reach for bash to sidestep the file rules — so the shell mutation set stays denied. Without
  // this clause the carve-out would silently UN-deny them, widening the session well past the staging
  // dir the design intended.
  const carveOutWritesViaShell = hasScopedWriteCarveOut(cap) && !isRestrictedRole(cap.role);
  if (cap.code === "none" && !carveOutWritesViaShell) out.push(...FILE_WRITE_DENY);
  // The global tooling-request queue (#4000). `bsc` sits in the permission model's `mandatory` tier —
  // ALWAYS allowed, every role, every posture — so without this deny any worker could file straight
  // into the queue a full-capability session drains to edit base-studio-code itself. Not granting it
  // is not enough; only a deny keeps it out, because the hook is the sole layer that fires under
  // bypass (where `permissions.deny` is ignored).
  //
  // The pattern carries a SPACE, which matters: `deny_matches` (bsc-util/src/deny.rs) treats a bare
  // program name as a program-TOKEN match, but keeps substring semantics for anything else — so
  // "bsc request" matches `bsc request new …` while a bare "bsc" would have denied the entire CLI.
  if (!mayFileToolingRequest(cap.role)) out.push(TOOLING_REQUEST_COMMAND);
  // Persona WRITES are the architect's (epic `the-persona-is-the-whole-agent`). The architect is the
  // session that configures personas and their capability BEFORE a director is asked to design a team
  // from them, so every other role is denied the three mutating verbs. Reads stay open to everyone —
  // a worker must still be able to see what it is running as.
  //
  // THIS IS A POLICY, NOT A BOUNDARY, and the distinction is worth stating where it is implemented:
  // these patterns carry SPACES, so `deny_matches` (bsc-util/src/deny.rs) applies substring semantics
  // rather than a program-token match — `bsc  persona set` with two spaces walks straight through —
  // and under the bypass posture `permissions.deny` is ignored entirely, leaving only the hook. What
  // actually holds is the store's own narrow-only clamp (crates/bsc-persona/src/floor.rs), which is a
  // property of the WRITE rather than of the caller and therefore cannot be spoofed or evaded. This
  // deny is here to make the workflow explicit and to stop the accidental case, not to cage anything.
  if (cap.role !== "architect") out.push(...PERSONA_WRITE_DENY);
  // ...and make the restricted spec's "you do not have python" true rather than merely stated. See
  // INTERPRETER_DENY: without this the sentence is prose the environment contradicts, and a session
  // that has been approved for python 37 times has learned which one to believe.
  if (isRestrictedRole(cap.role)) out.push(...INTERPRETER_DENY);
  // DEDUPED: the surface complement above can restate a deny a later clause adds for its own reason —
  // `bsc request` is denied both as an undeclared surface and as the tooling queue — and a doubled
  // entry would ride into every `.claude/settings.json` and `$BSC_DENY_BASH` this feeds.
  return [...new Set(out)];
}

/** The permission doc the `bsc-agent` runtime reads from `$BSC_AGENT_PERMS` (#1078 P3) — the
 *  generic role model rendered to bsc-agent's native shape (vs the Claude `.claude/settings.json`
 *  syntax {@link roleWriteRules}/{@link roleDeniedTools} produce). `code: "none"` denies the
 *  write/edit tools outright; `deny_bash` reuses {@link roleDeniedCommands} (substring-matched by
 *  bsc-agent — coarser than Claude's prefix allowlist); `write_globs` scopes a writer to its lane. */
export interface BscAgentPerms {
  deny_tools: string[];
  deny_bash: string[];
  write_globs: string[];
}

/** Render the role capability to bsc-agent's native permission doc. `granted` are the
 *  GitHub-propagation commands the pane's *flow* permits (from {@link flowGrantedPushCommands}):
 *  the flow owns `git push` / `gh pr create`, so they're lifted from the role denies when it
 *  permits pushing/PRing — mirroring the Claude role↔flow reconciliation (#304) so an `auto-pr`
 *  bsc-agent worker (github:read) can open its own PR. Everything else the role denies stays
 *  denied. With no flow grant (the default), behavior is unchanged.
 *
 *  `cap` may be `null` for a role-less (ad-hoc) bsc-agent console — then only `extraDenyBash`
 *  applies. `extraDenyBash` is the user's global command denylist (`store.deniedCommands`), the
 *  parallel to the `...deniedCommands` the Claude path passes to `ensure_session_settings`; bsc-agent
 *  has no `.claude/settings.json`, so they must ride in here to be enforced. The catastrophic
 *  base floor (sudo / `rm -rf /` / force-push) is NOT listed here — it's an always-on floor inside
 *  the bsc-agent runtime ({@link ../../../../crates/bsc-agent BASE_DANGEROUS_BASH}), so it can't be
 *  dropped by an empty perm doc. */
export function bscAgentPerms(
  cap: RoleCapability | null,
  granted: string[] = [],
  extraDenyBash: string[] = [],
  activeSurfaces: readonly string[] = [],
): BscAgentPerms {
  // The scoped carve-out (#851) applies here too: a `code: "none"` director WITH commons writeGlobs
  // keeps its write tools (scoped to the commons) rather than having them denied outright.
  const carveOut = cap ? hasScopedWriteCarveOut(cap) : false;
  // THE SURFACE COMPLEMENT, which this call used to omit
  // (`a-bsc-agent-session-is-denied-less-than-the-same-role-on-claude`). `roleDeniedCommands`'
  // second argument defaults to `[]`, and an empty catalog denies NOTHING extra — so a persona's
  // undeclared `bsc` surfaces stayed reachable here while the same role on Claude had them denied.
  // MEASURED: a designer was denied `bsc plan`, `bsc skill`, `bsc graph` and `bsc org` on Claude and
  // none of them on this harness.
  //
  // Nothing said the omission was deliberate — this doc explained the flow reconciliation and the
  // user denylist and was silent on surfaces, which is what an argument forgotten at one of two call
  // sites looks like. It is also the ONLY route: `bsc-agent` reaches a surface through its `bash`
  // tool and nowhere else (it registers ten tools and none of them runs a `bsc` noun), so `deny_bash`
  // is what gates it.
  const roleDenies = cap ? roleDeniedCommands(cap, activeSurfaces).filter((d) => !granted.includes(d)) : [];
  return {
    deny_tools: cap && cap.code === "none" && !carveOut ? ["write_file", "edit_file"] : [],
    deny_bash: [...new Set([...roleDenies, ...extraDenyBash.map((c) => c.trim()).filter(Boolean)])],
    write_globs: cap && (cap.code === "write" || carveOut) ? cap.writeGlobs : [],
  };
}

/** The per-store access-scope doc rendered into a gated session's `$BSC_SCOPES` env (#2470) — the
 *  runtime, defense-in-depth twin of the launch-time verb denies above. A store CLI reads it via
 *  `bsc_cli_util::scope_allows_write` and refuses its mutating verbs when the store is scoped
 *  read-only. Explicitly NOT a security boundary (a session owns its own env) — it guards accidents
 *  and non-Claude runtimes (`bsc-agent`, raw shells); {@link roleDeniedCommands} is the boundary.
 *  Currently just `ui`; other stores (`plan`, `skill`, `data`, …) adopt incrementally by adding
 *  their tier here. Missing tier ⇒ `"read"` (the same fail-closed floor as the deny rendering). */
export function sessionScopes(cap: RoleCapability): Record<string, AccessTier> {
  // Both stores. The doc carried exactly ONE key until now, which is why the algorithms store was
  // governed by nothing at all: `bsc-graph` held no `require_write_scope` calls, and there was no tier
  // for one to read (`the-algorithms-graph-has-no-write-gate`).
  //
  // `?? "read"` on each for the same reason `roleCapability` defaults them — a capability that predates
  // an axis must reach the session as the reading tier, never as a grant nobody wrote down.
  return { graph: cap.graph ?? "read", ui: cap.ui ?? "read" };
}

// Topological layering (#2214, graph-core epic) — the ONE longest-path layerer the graphs share. A
// dependency/coordination DAG flows across LAYERS: each node lands as deep as its longest incoming
// chain, so a source (no in-edges) sits at layer 0. The caller hands in a cycle-break set (the
// back-edges it already computed via `cycles.ts`, or its 2-cycle mutual pairs) so a loop can't diverge
// the layout. Pure; the callers own the layer→pixel PLACEMENT (Glance's grid, Relationship's swimlanes)
// — this only assigns the layer number.
import type { GraphEdge } from "@/shared/lib/graph/types";

/**
 * Longest-path topological layering. Assigns each node in `nodeIds` an integer layer so that for every
 * kept edge `from→to`, `layer[to] >= layer[from] + 1` — sources sit at layer 0 and each node lands as
 * deep as its longest incoming chain. Edges in `backEdgeIds` (the caller's cycle-break set), self-loops,
 * and edges touching an id outside `nodeIds` are ignored, so a cycle can't diverge the assignment. The
 * result is the DAG's unique longest-path layering, so it's independent of the relaxation order (and
 * identical to a Kahn / memoized-DFS layerer over the same acyclic edge set).
 *
 * Edge direction is "from → deeper": a node points to the nodes that must sit BELOW it. A "depends-on"
 * DAG — where the dependency should sit at a LOWER layer than its dependent — reverses its edges before
 * calling (see Glance's `buildGraph`).
 */
export function layerDag(
  nodeIds: readonly string[],
  edges: readonly GraphEdge[],
  backEdgeIds?: ReadonlySet<string>,
): Record<string, number> {
  const idSet = new Set(nodeIds);
  const kept = edges.filter(
    (e) => e.from !== e.to && idSet.has(e.from) && idSet.has(e.to) && !backEdgeIds?.has(e.id),
  );
  const layer: Record<string, number> = {};
  for (const id of nodeIds) layer[id] = 0;
  // Relax to the fixpoint: the longest path on a DAG spans ≤ nodeIds.length edges, so that many sweeps
  // always converge; the `changed` guard usually breaks far sooner. Same result as Kahn — order-free.
  for (let iter = 0; iter <= nodeIds.length; iter++) {
    let changed = false;
    for (const e of kept) {
      if (layer[e.to] < layer[e.from] + 1) { layer[e.to] = layer[e.from] + 1; changed = true; }
    }
    if (!changed) break;
  }
  return layer;
}

