import { lazy } from "react";
import { Row } from "@/shared/ui/layout/Row";

// Lazy-loaded screens (#perf): only the Console is needed at boot. Each other screen's chunk
// loads on first navigation, keeping the heavy module graph (esp. the planner) off the cold
// startup path — both the dev transform and the production bundle. Shared by the shell's screen
// switcher and the detached-window renderer.
// Settings renders from the HAND-CODED pages. It was migrated to the graph in #3658, rolled back by
// preference in #3758, and the dormant graph path was DELETED in #4183 — a copy nobody renders only
// rots. If Settings returns to the graph, regenerate it from the files of that day.
export const SettingsWorkspace    = lazy(() => import("@/features/settings").then((m) => ({ default: m.SettingsWorkspace })));
// Skills renders FROM THE GRAPH (#3654, epic #3604) — the graph host mounts the authored `skillspage` node;
// the symbol name stays so App.tsx + DetachedWindow (which passes `pageOverride`) need no change.
export const SkillsWorkspace      = lazy(() => import("@/features/skills").then((m) => ({ default: m.SkillsGraphHost })));
// Security renders FROM THE GRAPH (#3646, epic #3604) — the graph host mounts the authored `securitypage`
// node; the symbol name stays so App.tsx + DetachedWindow (which passes `pageOverride`) need no change.
export const LogsWorkspace        = lazy(() => import("@/features/logs").then((m) => ({ default: m.LogsGraphHost })));
// Glance renders FROM THE GRAPH (#4185, epic #3604) — the graph host mounts the authored `glancepage`
// node; the symbol name stays so App.tsx needs no change.
export const GlanceWorkspace      = lazy(() => import("@/features/glance").then((m) => ({ default: m.GlanceGraphHost })));
// THE FIVE GRAPHS (`five-graphs-become-rail-workspaces`) — Components, Teams, Algorithms, Data and
// Sounds are rail Workspaces again. They spent a while folded into the Planner as tabs (#move-to-planner,
// #2785, #2199, #3072); that collapse is reversed, so each is lazy-mounted here like every other screen.
//
// Components and Algorithms are the two heaviest chunks in the app after the planner — the component
// preview/build chain and the knowledge graph respectively — which is exactly why they stay LAZY:
// a rail destination nobody has opened should not be on the cold-start path.
export const ComponentsWorkspace  = lazy(() => import("@/features/designs").then((m) => ({ default: m.DesignsWorkbench })));
export const AlgorithmsWorkspace  = lazy(() => import("@/features/algorithms").then((m) => ({ default: m.AlgorithmsGraphHost })));
export const TeamsWorkspace       = lazy(() => import("@/features/teams").then((m) => ({ default: m.TeamsGraphHost })));
export const DataWorkspace        = lazy(() => import("@/features/data").then((m) => ({ default: m.DataGraphHost })));
export const SoundsWorkspace      = lazy(() => import("@/features/sounds").then((m) => ({ default: m.SoundsGraphHost })));
// The session-memory store's window (`a-memory-workspace-shows-what-we-know`). Lazy for the same
// reason as the two below: it reads `bsc memory` on mount, and a screen nobody has opened should not
// be on the cold-start path.
export const MemoryWorkspace      = lazy(() => import("@/features/memory").then((m) => ({ default: m.MemoryWorkspace })));
// The credential store's window. Lazy like every other non-Console destination: it reads `bsc secret`
// on mount, and a screen nobody has opened should not be on the cold-start path.
export const CredentialsWorkspace = lazy(() => import("@/features/credentials").then((m) => ({ default: m.CredentialsWorkspace })));

/** Lightweight placeholder shown while a lazy screen's chunk loads. */
export function WorkspaceFallback() {
  return (
    <Row className="mono" justify="center" style={{ flex: 1, color: "var(--fg-dim)", fontSize: 12 }}>
      loading…
    </Row>
  );
}

// Self-correction lessons — the frontend side of #1362. A lesson is a mistake an agent caught
// mid-session (captured by the `bsc-learned` helper into the project's plan.db); the user reviews the
// pending queue here and confirms it into a project skill or discards it. These drive the SAME
// `bsc plan lesson …` verbs the planner/agents use, through the generic `bsc` bridge (#2114/#2115) —
// UI↔planner parity over one store surface (they replaced the per-verb `plan_lesson_*` Tauri commands).
//
// Kept Tauri-light + React-free so the mapping helpers are unit-testable; the LessonsTab component
// does the rendering. Mirrors how skillBridge.ts isolates the skilldb bridge.

import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { truncate } from "@/shared/lib/core/format";
import { blankSkill, skillSlug, type SkillDef } from "@/features/skills/lib/skills";

/** A captured lesson candidate — mirrors the Rust `plandb::Lesson` (camelCase). */
export interface Lesson {
  id: string;
  /** What went wrong. */
  mistake: string;
  /** Why it happened (optional). */
  cause: string;
  /** The corrective rule a future agent should follow. */
  rule: string;
  /** Origin tag set by the capture helper (`pane …, repo …`). */
  provenance: string;
  /** `pending` | `confirmed` | `discarded`. */
  status: string;
  /** How many times this same lesson was captured (dedup counter). */
  seen: number;
  createdAt: number;
  updatedAt: number;
}

/** The project's pending lesson candidates (the review queue). Returns [] when the bridge is absent
 *  (no Tauri host / no plan.db) so the UI degrades to an empty queue rather than throwing. */
export async function loadPendingLessons(projectKey: string): Promise<Lesson[]> {
  if (!projectKey) return [];
  // `bsc plan lesson list --status pending` emits the JSON array (the same `Vec<Lesson>` serde shape
  // the old `plan_lesson_list` command returned); bscJson degrades to [] when plan.db doesn't exist yet.
  return bscJson<Lesson[]>(projectKey, ["plan", "lesson", "list", "--status", "pending"], []);
}

/** Mark a candidate confirmed (the user accepted it). The caller also materializes it as a skill. */
export async function confirmLesson(projectKey: string, id: string): Promise<void> {
  await bscRun(projectKey, ["plan", "lesson", "confirm", id]);
}

/** Mark a candidate discarded (kept as a record; its seen count still grows if it recurs). */
export async function discardLesson(projectKey: string, id: string): Promise<void> {
  await bscRun(projectKey, ["plan", "lesson", "discard", id]);
}

/** A confirmed lesson's display title — the corrective rule (the actionable part), else the mistake,
 *  capped so it slugs to a sane skill directory name. */
export function lessonTitle(lesson: Pick<Lesson, "mistake" | "rule">): string {
  const base = (lesson.rule.trim() || lesson.mistake.trim()).replace(/\s+/g, " ");
  return truncate(base, 64, 61);
}

/**
 * Map a confirmed {@link Lesson} to a **project-scoped** {@link SkillDef} (the resolver then attaches
 * it to that project's future sessions). The skill is a `review`-kind corrective check: its body is
 * the transferable mistake → rule, scoped to `projectKey` (the user can later globalize it via the
 * normal skill-scope UI — that's the "promote to global" path, #1338). A stable id derived from the
 * lesson id keeps a re-confirm idempotent. Returns `null` when the lesson has nothing to name.
 */
export function lessonToSkill(lesson: Lesson, projectKey: string): (Omit<SkillDef, "id"> & { id: string }) | null {
  const name = lessonTitle(lesson);
  if (!skillSlug(name)) return null;
  const body = [
    lesson.mistake.trim() && `When: ${lesson.mistake.trim()}`,
    lesson.cause.trim() && `Why: ${lesson.cause.trim()}`,
    lesson.rule.trim() && `Do: ${lesson.rule.trim()}`,
  ].filter(Boolean).join("\n");
  return {
    ...blankSkill(),
    id: `lesson-skill-${lesson.id}`,
    name,
    kind: "review",
    source: "first-party",
    desc: lesson.mistake.trim() || lesson.rule.trim(),
    prompt: body,
    projects: projectKey ? [projectKey] : [],
    enabled: true,
  };
}

