// The algo-graph NodeLookup adapter (#3116) — the map from the algorithms store onto the shared
// cross-graph resolver. Verifies bare-name + exact-id resolution, the miss, and the code/kind carry-through.
import { describe, it, expect } from "vitest";
import { algoNodeLookup } from "@/features/algorithms/lib/crossGraphAdapter";
import { buildKnowledge } from "@/features/algorithms/lib/knowledge";

const graph = buildKnowledge({
  implementations: [
    { id: "fibonacci.ts", tech: "typescript", role: "algorithm", name: "fibonacci", composes: ["typescript.number"], code: "export function fibonacci(){}" },
    { id: "typescript.number", tech: "typescript", role: "primitive", name: "number", composes: [], ref: "number" },
    { id: "fibonacci.rs", tech: "rust", role: "algorithm", name: "fibonacci", composes: [], code: "pub fn fibonacci(){}" },
  ],
});

describe("algoNodeLookup (#3116)", () => {
  const lookup = algoNodeLookup(graph);

  it("resolves a TS algorithm by its BARE name and carries its code + kind", () => {
    const n = lookup("typescript", "fibonacci");
    expect(n).not.toBeNull();
    expect(n!.id).toBe("fibonacci.ts"); // the canonical impl id (so a caller can canonicalize the URN)
    expect(n!.label).toBe("fibonacci");
    expect(n!.kind).toBe("algorithm");
    expect(n!.code).toContain("export function fibonacci");
    expect(n!.graph).toBe("algo");
  });

  it("resolves the SAME impl by its exact id (fibonacci.ts)", () => {
    expect(lookup("typescript", "fibonacci.ts")?.id).toBe("fibonacci.ts");
  });

  it("scopes to the kit (a Rust fibonacci is a different node) and misses cleanly", () => {
    expect(lookup("rust", "fibonacci")?.id).toBe("fibonacci.rs");
    expect(lookup("typescript", "nope")).toBeNull();
    expect(lookup("python", "fibonacci")).toBeNull(); // an unseeded kit
  });

  it("resolves a primitive too — but with no code (a descriptor, not importable)", () => {
    const n = lookup("typescript", "number");
    expect(n?.kind).toBe("primitive");
    expect(n?.code).toBeUndefined();
  });
});

implementations.code:
// Mounted-preview registry (#3437) — which component previews exist RIGHT NOW, so `bsc debug frames`
// can report them.
//
// WHY A REGISTRY AND NOT A QUERY
// `document.querySelectorAll("iframe")` finds the elements but not the two facts that matter when a
// preview misbehaves: was the pan/zoom engine REQUESTED for this frame (the `zoomEngine` prop), and did
// the built srcdoc actually CONTAIN it. Those live in React, are gone by the time the DOM is inspected,
// and their disagreement is exactly the bug class this exists to surface — "the host asked for an engine
// and the builder dropped it" reads identically to "no engine wanted" from the DOM alone.
//
// Deliberately module-level and React-free: the shell's debug channel reads it without a store round-trip
// or a context, and a frame that unmounts removes itself, so the list is never stale.
export interface PreviewFrameEntry {
  /** The previewed component's id. */
  component: string;
  /** The live iframe element — the host side of the sandbox boundary. */
  iframe: HTMLIFrameElement;
  /** Was the pan/zoom engine asked for (the `zoomEngine` prop)? */
  engineRequested: boolean;
  /** Did the built srcdoc actually carry the engine? Diverges from `engineRequested` on a builder bug. */
  engineInSrcdoc: boolean;
}

const FRAMES = new Map<string, PreviewFrameEntry>();

/** Record (or update) one mounted preview. `key` is stable per frame instance, so a rebuild replaces
 *  rather than duplicates its entry. */
export function registerPreviewFrame(key: string, entry: PreviewFrameEntry): void {
  FRAMES.set(key, entry);
}

/** Drop a preview on unmount. Never throws on an unknown key — teardown order is not guaranteed. */
export function unregisterPreviewFrame(key: string): void {
  FRAMES.delete(key);
}

/** Every currently-mounted preview. Entries whose iframe has left the document are filtered out (and
 *  forgotten): a frame torn down without its cleanup running must not be reported as live. */
export function mountedPreviewFrames(): PreviewFrameEntry[] {
  const out: PreviewFrameEntry[] = [];
  for (const [key, entry] of FRAMES) {
    if (entry.iframe.isConnected) out.push(entry);
    else FRAMES.delete(key);
  }
  return out;
}

/** Test seam: forget every registration. */
export function resetPreviewFrames(): void {
  FRAMES.clear();
}

// Barrel for the Skills feature's pure helpers — the SkillDef model, per-session
// resolution, catalog → definition templates, the planner `skills.json` parser,
// and the conversion to the backend payload written into a session's
// `.claude/skills/<slug>/SKILL.md`.
//
// Free of React / Tauri imports so it can be unit-tested and shared between the
// store, the Skills screen, the planner ingestion, and TerminalView. Mirrors
// lib/mcpServers.ts. Decomposed into colocated modules (#2151); this barrel keeps
// the original public API intact so every importer works unchanged.

export { type SkillDef, skillSlug, skillContentKey, blankSkill } from "@/features/skills/lib/skillsModel";
export { skillFromPayload, seedSkills, refreshPackagedSkills } from "@/features/skills/lib/skillsSeed";
export {
  resolveSkills, sessionSkillState, effectiveSessionSkills, applySessionSkillChoice,
  type SessionSkillOverride, type SessionSkillReason, type SessionSkillState,
} from "@/features/skills/lib/skillsSession";
export {
  expandGroups, groupSkillCount, parseSkillGroupsFile, type SkillGroup,
} from "@/features/skills/lib/skillGroups";
export { toSkillCfgs, type SkillCfg } from "@/features/skills/lib/skillsPayload";
export { parseSkillsFile, type PlannerSkill } from "@/features/skills/lib/skillsParser";
export { deriveSkillKpis, type DerivedSkillKpis } from "@/features/skills/lib/skillsKpis";

