// LlmSettingsSlice — the API-tier LLM provider config (#1085): the anthropic/openai/gemini keys,
// the local endpoint, and the provider/model that back llm_complete calls. Split out of the former
// `core` grab-bag (#2715) — these are settings, not project state. Typed Pick<AppStore, …>.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { modelOnProviderSwitch, DEFAULT_ANTHROPIC_MODEL, DEFAULT_LOCAL_BASE_URL } from "@/shared/lib/core/llmConfig";

type LlmSettingsSlice = Pick<AppStore,
  "claudeApiKey" | "setClaudeApiKey" | "llmProvider" | "setLlmProvider" | "llmModel" | "setLlmModel" | "openaiKey" | "setOpenaiKey" | "geminiKey" | "setGeminiKey" | "localBaseUrl" | "setLocalBaseUrl" | "llmNumCtx" | "setLlmNumCtx"
>;

export const createLlmSettingsSlice: StateCreator<AppStore, [], [], LlmSettingsSlice> = (set) => ({
      claudeApiKey: "",
      setClaudeApiKey: (key) => set({ claudeApiKey: key }),

      // API-tier LLM provider config (#1085). claudeApiKey is the anthropic key.
      llmProvider: "anthropic",
      // Switch the model field to the new provider's default when it still holds another provider's
      // default (a hosted `claude-*` model can't run on Ollama, and vice-versa) — a model the user
      // typed is preserved. So picking Ollama lands on `qwen3-coder` instead of a 404 on the Claude id.
      setLlmProvider: (p) => set((s) => ({ llmProvider: p, llmModel: modelOnProviderSwitch(p, s.llmModel) })),
      llmModel: DEFAULT_ANTHROPIC_MODEL,
      setLlmModel: (m) => set({ llmModel: m }),
      openaiKey: "",
      setOpenaiKey: (k) => set({ openaiKey: k }),
      geminiKey: "",
      setGeminiKey: (k) => set({ geminiKey: k }),
      localBaseUrl: DEFAULT_LOCAL_BASE_URL,
      // TRIMMED AT THE SETTING (`a-whitespace-base-url-survives-the-pane-routing-and-cannot-dial`). A
  // whitespace-only endpoint is not an endpoint, and storing one sends the failure far from the field
  // that caused it. Fixing it here means nothing new is stored wrong; the readers still trim because
  // persisted state predates this.
  setLocalBaseUrl: (u) => set({ localBaseUrl: u.trim() }),
      // The per-agent context cap. Defaults to EMPTY rather than to a number, so the runtime's
      // packaged ceiling stays the source of that default: raising it then reaches every install,
      // instead of only the ones that never opened this field. A number here is a real override.
      llmNumCtx: "",
      setLlmNumCtx: (v) => set({ llmNumCtx: v }),
});

// API-tier LLM provider config (#1085) — the keys + provider/model that back llm_complete calls.
// Split from store/types (#1634).
import type { LlmProvider } from "@/shared/lib/core/llmConfig";

/** LLM-provider slice of {@link AppStore}. */
export interface LlmState {
  claudeApiKey: string;
  setClaudeApiKey: (key: string) => void;

  // API-tier LLM provider config (#1085) — powers llm_complete-backed calls (planning
  // autopilot, grader, cleanup verifier). `claudeApiKey` doubles as the anthropic key.
  // Distinct from the per-pane runtime model (defaultModel/paneModels).
  llmProvider: LlmProvider;
  setLlmProvider: (p: LlmProvider) => void;
  llmModel: string;
  setLlmModel: (m: string) => void;
  openaiKey: string;
  setOpenaiKey: (k: string) => void;
  geminiKey: string;
  setGeminiKey: (k: string) => void;
  /** OpenAI-compatible endpoint for the `local` provider (default Ollama). */
  localBaseUrl: string;
  setLocalBaseUrl: (u: string) => void;
  /** The per-agent context cap (`num_ctx`) for a local session, as typed — reaches the runtime as
   *  `$BSC_AGENT_NUM_CTX`. A STRING because the field is a text input and three states must stay
   *  distinguishable: empty = "use the runtime's packaged ceiling", `"0"` = "don't set `num_ctx` at
   *  all", any other number = that ceiling. A `number` cannot hold the first two apart.
   *
   *  Load-bearing, not a preference: a prompt at or over `num_ctx` is not trimmed by Ollama, it is
   *  truncated to HALF the window with the head discarded — and the head is the CLAUDE.md. */
  llmNumCtx: string;
  setLlmNumCtx: (v: string) => void;
}

// Local published inventory (#2445, epic #2444) — the offline entry point for published projects.
//
// Published projects used to exist in the UI only as live `projectsV2` query results: logged out of
// GitHub, `fetchProjects` never runs and `buildDrafts` drops published hubs, so a published project
// appeared in NEITHER Projects column (and a restored fleet ran with no reachable surface). The
// on-disk hubs already carry everything the column needs — the `.published` marker and the `.title`
// display name — so the published column renders from THIS local selection first, and the GitHub
// records OVERLAY it when the query returns: a hub matched by a fetched board drops out of the local
// list (the board's `ProjectRow` — status/progress/url/counts — is the richer rendering of the same
// project).
//
// Matching mirrors the `mark_published` reconcile in ProjectsList (#922/#2409): a board covers a hub
// when the hub's folder key equals the board's name-derived `projectSlug(title)` (today's keys) or
// the legacy `sanitizeProjectKey(title)` (grandfathered title-keyed hubs), or when the titles match
// case-insensitively.

import { projectSlug, sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import type { LocalProjectLite } from "@/features/planner/list/drafts";

/** A published hub rendered from the local inventory — key is the identity (the hub folder key). */
export interface LocalPublishedRow { key: string; title: string; updatedAt: number }

/**
 * Select the local published hubs NOT covered by a fetched GitHub board.
 *
 * @param localProjects on-disk hubs from `list_local_projects` (carry `.published` + `.title`).
 * @param ghProjects    the fetched (visible) GitHub boards — empty while logged out / before the
 *                      query lands, so every published hub renders locally until the overlay arrives.
 * @returns local-only published rows, unsorted (caller sorts).
 */
export function buildLocalPublished(
  localProjects: LocalProjectLite[],
  ghProjects: Array<{ title: string }>,
): LocalPublishedRow[] {
  const safeLocals = Array.isArray(localProjects) ? localProjects : [];
  const ghTitles = new Set(ghProjects.map((p) => p.title.toLowerCase()));
  const ghKeys = new Set(ghProjects.flatMap((p) => [projectSlug(p.title), sanitizeProjectKey(p.title)]));
  return safeLocals
    .filter((lp) => lp?.published && !ghKeys.has(lp.key) && !ghTitles.has(lp.title.toLowerCase()))
    .map((lp) => ({ key: lp.key, title: lp.title, updatedAt: lp.updatedAt }));
}

