// The top-left "you are here" location crumb (#3036) — the sub-page detail appended after the
// Workspace name (from `registry.ts`) in the titlebar (`App.tsx` → `Titlebar`). Pure + unit-tested so
// EVERY navigable page is reflected, not just a few.
//
// Every workspace's active page IS in the store: an uncontrolled `<Screen>` persists it at
// `activePageTab[pageKey]` (`usePageTabs`), the controlled ones use a dedicated field
// (`projectsPageMode` / `githubTab` / `settingsSection`), and the console uses its own tab array.
//
// The page-label maps below MIRROR each feature's TabItem labels (glance `GLANCE_TABS`, skills
// `SKILL_TABS`, automations `defs`, logs `logDefs`, github `GITHUB_TABS`, planner
// `PROJECT_MODES`, settings `SECTIONS`). They live here (not imported) so the shell doesn't reach into
// every feature's internals; an id with no entry Title-Cases gracefully, so a newly-added tab is still
// labeled (never blank), just less pretty than a curated name.

import { workspaceLabel, type Workspace } from "@/app/registry";

/** Title-case a page id as a graceful fallback for an unmapped tab: `hook-analytics` → `Hook Analytics`. */
export function titleCasePageId(id: string): string {
  return id.split(/[-_]/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
}

/** Per-workspace page-id → label for the UNCONTROLLED Screens (active id in `activePageTab[pageKey]`). */
const PAGES: Partial<Record<Workspace, Record<string, string>>> = {
  glance:     { network: "Network", fleet: "Fleet" },
  logs:       { activity: "Activity", waiting: "Waiting", skills: "Skills", sessions: "Sessions", cost: "Cost", automations: "Automations", streams: "Streams" },
  // Memory's pages are the GRAPH plus one per memory kind. Mapped rather than Title-Cased from the id
  // (which is what this did first): the kind ids are singular — `lesson` — while the pages read as
  // plurals, and `note` reads as "Unclassified" because it is the absence of a kind rather than one.
  // The parity is pinned by a test against the feature's own `TAB_LABEL`, so the two cannot drift.
  memory:     { graph: "Graph", lesson: "Lessons", highlight: "Highlights", record: "Records", ambient: "Ambient", note: "Unclassified" },
};
/**
 * A graph WORKSPACE → the `crumbEntity` key the page reports under
 * (`five-graphs-become-rail-workspaces`).
 *
 * Needed because the two vocabularies are NOT the same. Each graph calls `useCrumbEntity` with its
 * historical PAGE id, and one of those differs from the workspace key: the Design Studio reports
 * under `designs` while its Workspace is `components` (the tab id was the feature name, the label was
 * "Components", #2818). Reading `crumbEntity[workspace]` directly would therefore work for four
 * graphs and silently show nothing for the fifth — the kind of near-miss that reads as "the crumb is
 * just like that" rather than as a bug.
 *
 * `data` is absent on purpose: that page reports no entity yet, so there is nothing to key.
 */
const GRAPH_CRUMB_KEY: Partial<Record<Workspace, string>> = {
  components: "designs",
  teams: "teams",
  algorithms: "algorithms",
  sounds: "sounds",
};

/** Settings section (`settingsSection`) → label (mirrors `SECTIONS`). */
const SETTINGS_SECTIONS: Record<string, string> = { general: "General", planner: "Planner", skills: "Skills", automations: "Automations", mcp: "MCP", github: "GitHub", security: "Security" };

/** The `activePageTab` key when it differs from the Workspace key. EMPTY now — automations was
 *  the only one, and that workspace is retired. Kept because the lookup below reads it and a
 *  future workspace may need it again. */
const PAGE_KEY: Partial<Record<Workspace, string>> = {};
/** The default first tab per uncontrolled workspace — so the crumb shows the current page even before
 *  the user has ever selected one (`activePageTab` is empty until the first click). Mirrors each feature's
 *  first `TabItem` id. */
const DEFAULT_PAGE: Partial<Record<Workspace, string>> = {
  glance: "network", logs: "activity", memory: "graph",
};

const label = (map: Record<string, string>, id: string | undefined): string =>
  id ? (map[id] ?? titleCasePageId(id)) : "";

/** The store fields the crumb reads — kept explicit (a subset of `AppStore`) so it's trivially testable. */
export interface CrumbState {
  activeWorkspace: Workspace;
  activePageTab: Record<string, string>;
  /** The navigated ENTITY per graph, keyed by page id (`glance`/`teams`/`designs`/`algorithms`),
   *  reported by each graph via `useCrumbEntity` (#3041). Appended after the page name. */
  crumbEntity: Record<string, string>;
  projectsPageMode: string;
  projectsView: string;
  settingsSection: string;
  /** The active console tab's name (`tabs[activeTabIdx]?.name`). */
  consoleTab?: string;
  focusedAgentName?: string;
}

/**
 * The full "you are here" crumb: the Workspace's canonical name (`registry.ts`) followed by its active
 * PAGE label — and, where meaningful, one more detail (the focused console agent, the planning
 * session). Every workspace's page is reflected. Parts are joined with " — ".
 */
export function locationCrumb(s: CrumbState): string {
  const w = s.activeWorkspace;
  const parts: string[] = [workspaceLabel(w)];
  switch (w) {
    case "console":
      if (s.consoleTab) parts.push(s.consoleTab);
      if (s.focusedAgentName) parts.push(s.focusedAgentName);
      break;
    case "glance":
      parts.push(label(PAGES.glance ?? {}, s.activePageTab.glance ?? DEFAULT_PAGE.glance));
      if (s.crumbEntity.glance) parts.push(s.crumbEntity.glance); // the drilled project
      break;
    case "logs":
      parts.push(label(PAGES[w] ?? {}, s.activePageTab[PAGE_KEY[w] ?? w] ?? DEFAULT_PAGE[w]));
      break;
    case "memory":
      parts.push(label(PAGES[w] ?? {}, s.activePageTab[w] ?? DEFAULT_PAGE[w]));
      break;
    case "settings":
      parts.push(label(SETTINGS_SECTIONS, s.settingsSection));
      break;
    case "components":
    case "teams":
    case "algorithms":
    case "data":
    case "sounds": {
      // The five graphs (`five-graphs-become-rail-workspaces`). The Workspace NAME is already in
      // `parts[0]`; this adds the active TAB and then the navigated entity.
      //
      // The tab is Title-Cased from its id rather than mapped: unlike every other workspace here, these
      // vocabularies are DATA — the languages the knowledge graph holds, the sound kits, the teams — so
      // a curated label map would be a second copy that goes stale the moment the data changes, and a
      // stale map shows the wrong name rather than an ugly one. `titleCasePageId` already exists for
      // exactly this "labelled, never blank" case.
      //
      // Teams' overview tab is skipped: its id is `teams`, so it would render "Teams — Teams".
      const tab = s.activePageTab[w];
      if (tab && !(w === "teams" && tab === "teams")) parts.push(titleCasePageId(tab));
      // The entity — the active kit, team or language the page itself reports. Before the promotion
      // this came through the `projects` case reading `crumbEntity[projectsPageMode]`; that path is
      // dead now, so without this the crumb would quietly stop naming what you are looking at.
      const entity = s.crumbEntity[GRAPH_CRUMB_KEY[w] ?? w];
      if (entity) parts.push(entity);
      break;
    }
  }
  return parts.filter(Boolean).join(" — ");
}

// Text-log retention config (#1060). Split from the former store/types monolith (#1634).
/** Retention for the text log streams (#1060). 0 disables a cap. */
export interface LogConfig {
  /** Trim a text log to its newest N lines on enforcement. 0 = no line cap. */
  maxLines: number;
  /** Trim a text log to its newest bytes if it exceeds this many MB. 0 = no size cap. */
  maxSizeMb: number;
}

export const DEFAULT_LOG_CONFIG: LogConfig = {
  maxLines: 10_000,
  maxSizeMb: 20,
};

// In-process log-stream reads (#3630) — the perf-critical replacement for polling the unified log
// streams through the `bsc` bridge, which SPAWNED a `bsc.exe` subprocess per read (`console::bsc`).
// The always-on fleet/console pumps (`useCoordLog`, `useWorkerAutoEnd`, the pane-activity poll) hit
// these every ~1s; at 5–10 spawns/sec the Tauri invoke backlog grew without bound and the app froze.
// These native commands (`observability::logs::logs_*`) read the SAME files in-process via the `logs`
// crate — a file read, not a process — so the hot polls stop saturating the backend.
//
// Same JSON shape the `bsc logs …` subcommands emitted (the native commands return the same serde
// types), so these are drop-ins for the prior `bscJson(null, ["logs", …])` calls. Low-frequency
// `bsc logs …` reads (cost, analytics one-shots) stay on the `bsc` bridge.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** One pane's latest turn-boundary state — the `logs::PaneActivity` shape (`bsc logs pane-activity`). */
export interface PaneActivityRow {
  pane: string;
  state: string;
  at: number;
}

/**
 * Newest `limit` raw lines of a unified log stream (`coord`/`audit`/`skill`/`hook`/`mcp`/`ui`/…),
 * read in-process. `oldest` keeps chronological (oldest-first) order — pass `true` for the coord/ui
 * logs the replayers walk forward. An unknown/missing stream resolves to `fallback` (default `[]`);
 * pass `null` where a caller must distinguish "read failed → skip this tick" from an empty log.
 */
export function logsTail(stream: string, limit: number, oldest?: boolean): Promise<string[]>;
export function logsTail<F>(stream: string, limit: number, oldest: boolean, fallback: F): Promise<string[] | F>;
export function logsTail(stream: string, limit: number, oldest = false, fallback: unknown = []): Promise<unknown> {
  return safeInvoke("logs_tail", { stream, limit, oldest }, fallback);
}

/** The latest turn-boundary state per pane (`run`/`idle`), newest pane first — `bsc logs pane-activity`.
 *  Generic `T` lets a caller keep its own row type; the wire shape is always `{ pane, state, at }`. */
export function logsPaneActivity<T = PaneActivityRow>(): Promise<T[]> {
  return safeInvoke<T[]>("logs_pane_activity", undefined, []);
}

/** The deduped set of panes that self-reported `done` (#1379), newest first — `bsc logs done-panes`. */
export function logsDonePanes(): Promise<string[]> {
  return safeInvoke<string[]>("logs_done_panes", undefined, []);
}

/** One blocked session — the `logs::WaitingSession` shape (`bsc logs waiting`). */
export interface WaitingRow {
  /** The pane/session that is blocked. */
  pane: string;
  /** `wait` · `ask` · `request` · `permission` — what kind of answer it needs. */
  kind: string;
  /** The question / reason / request text. EMPTY for a permission prompt, which carries none. */
  detail: string;
  /** Epoch-ms of the opening event. */
  at: number;
  /** The request id, for `kind: "request"` — what `bsc plan request resolve` takes. Else empty. */
  id: string;
}

/**
 * Every session blocked on a HUMAN, OLDEST FIRST — `bsc logs waiting` (#4015).
 *
 * Oldest-first is the contract, not a default: this is a QUEUE and the longest-waiting session is
 * the one to clear first. Do not re-sort it newest-first to match the other feeds.
 *
 * Deliberately NOT computed from `coordinationLog.ts`, which reduces the same coord.log in the
 * frontend. `waiting.rs` says the two MUST agree and that the DIRECTOR is what suffers when they
 * do not — its protocol tells it to run `bsc logs waiting` and drive the queue to empty. Rendering
 * the reducer would put a human in front of a different queue than the director works.
 */
export function logsWaiting(): Promise<WaitingRow[]> {
  return safeInvoke<WaitingRow[]>("logs_waiting", undefined, []);
}

/** One session's whole footprint — the `logs::SessionRow` shape (`bsc logs sessions`). */
export interface SessionRollupRow {
  /** The pane/session id. */
  session: string;
  /** Derived from the id: worker · planner · director · session. */
  role: string;
  /** Tool attempts recorded for it (the audit stream). */
  tools: number;
  /** Skill invocations. */
  skills: number;
  /** MCP calls. Legacy column-less lines stay unattributed and count toward NO session. */
  mcp: number;
  /** Coordination events emitted. */
  coord: number;
  /** Cost in USD, from the session transcript.
   *
   *  SNAKE_CASE ON PURPOSE. `SessionRow` has no `serde(rename_all)`, unlike `WaitingSession` right
   *  above it, so this field crosses the wire as `cost_usd` — and the SAME struct is what
   *  `bsc logs sessions --json` prints, so camelCasing the Rust side to make TypeScript prettier
   *  would change a CLI contract. A mismatch here does not throw: the field reads `undefined` and
   *  every row renders $0.00, which looks like a fleet that cost nothing. */
  cost_usd: number;
  /** Latest activity state (`run`/`idle`/`attn`), or EMPTY when the session never reported one. */
  activity: string;
}

/**
 * The per-session rollup across every pane-tagged stream plus cost — `bsc logs sessions` (#1607).
 *
 * The heaviest log read in the app: five streams plus the cost rollup, which re-reads every
 * transcript named in `tokens.log`. Poll it only while something is showing it.
 */
export function logsSessions(): Promise<SessionRollupRow[]> {
  return safeInvoke<SessionRollupRow[]>("logs_sessions", undefined, []);
}

/** One session's token + cost rollup — the `logs::Cost` shape (`bsc logs cost`).
 *
 *  SNAKE_CASE, like `SessionRollupRow` and for the same reason: `Cost` carries no
 *  `serde(rename_all)`, and the same struct is what `bsc logs cost --json` prints. */
export interface CostRow {
  session: string;
  /** The model the transcript reports. `<synthetic>` for a message with no real model. */
  model: string;
  input: number;
  output: number;
  cache_creation: number;
  cache_read: number;
  cost_usd: number;
}

/** The whole fleet's token + cost rollup — `bsc logs cost` (#1607). Re-reads every transcript
 *  named in `tokens.log`, so poll it only while something is showing it. */
export function logsCosts(): Promise<CostRow[]> {
  return safeInvoke<CostRow[]>("logs_costs", undefined, []);
}

/**
 * The canonical stream key for a read alias — mirrors Rust `logs::canonical_stream`. The UI reads a few
 * streams by alias (`audit`→`tool`, `skills`→`skill`); everything else is already canonical. Used to
 * line a read alias up with the backend's `logs://<canonical>` change event (#3638), so a subscriber
 * never misses an emit because it named the stream differently than the watcher did.
 */
export function canonicalStream(alias: string): string {
  switch (alias) {
    case "audit":
    case "tools":
      return "tool";
    case "skills":
      return "skill";
    default:
      return alias;
  }
}

/** The Tauri event the backend log watcher (`observability::log_watch`) emits when `stream` changes —
 *  the event `useLogStream` subscribes to. Accepts a read alias (canonicalized). MUST stay in sync with
 *  the Rust `event_name` (#3638). */
export function logEventName(stream: string): string {
  return `logs://${canonicalStream(stream)}`;
}

