  it("documents the per-worker assignment directive (the stream `mcp` list)", () => {
    const md = buildMcpContext([mk("Research")], catalog);
    expect(md).toContain('"mcp": ["Research"]');
    expect(md).toMatch(/exposed to you \(the planner\)/);
