  it("keeps the well-known entries the planner's <mcp_assign> resolves by name", () => {
    for (const name of ["Compliance", "Research", "Postgres", "Slack", "Sentry", "Linear", "Notion"]) {
      expect(catalogTemplates).toHaveProperty(name);
    }
