import { describe, it, expect } from "vitest";
import {
  gridOrigin, cellRect, cellOffset, anchorCentre, ringCells, unionRects, placeByDirection, releaseCell, occupants, clampCell,
  CELL_W, CELL_H, GRID_GAP, DEFAULT_CELL,
  CELL_MIN_W, CELL_MIN_H, CELL_MAX_W, CELL_MAX_H,
  type MorphPlacement, type GridCell,
} from "@/features/glance/lib/morphGrid";
import { NW, NH } from "@/features/glance/lib/glanceGraph";
import type { MorphRect } from "@/features/glance/lib/glancePush";

const ANCHOR = { x: 100, y: 100 };
/** Do two world boxes overlap at all? The property the whole grid exists to guarantee. */
const overlaps = (a: MorphRect, b: MorphRect) =>
  a.left < b.left + b.w && b.left < a.left + a.w && a.top < b.top + b.h && b.top < a.top + a.h;

/** Place `id` at world offset (dx,dy) from the anchor node — the shape the workspace passes in. */
const place = (ps: MorphPlacement[], id: string, dx: number, dy: number) =>
  placeByDirection(ps, id, { dx, dy });
/** The cell `id` ended up in. */
const cellOf = (ps: MorphPlacement[], id: string): GridCell => {
  const p = ps.find((x) => x.nodeId === id)!;
  return { col: p.col, row: p.row };
};
/** An anchor placement to build on — "root" occupies (0,0). */
const rooted = () => place([], "root", 0, 0);

describe("gridOrigin (#3361 — the first opened node defines the grid)", () => {
  it("centres cell (0,0) on the anchor node — byte-identical to the pre-grid single morph's own box", () => {
    // The morph used to compute `node.x + NW/2 - CARD_W/2`. Opening ONE node must look unchanged.
    expect(gridOrigin(ANCHOR)).toEqual({
      x: ANCHOR.x + NW / 2 - CELL_W / 2,
      y: ANCHOR.y + NH / 2 - CELL_H / 2,
    });
  });

  it("re-centres when the shared cell is resized, so the grid stays anchored on the node", () => {
    expect(gridOrigin(ANCHOR, { w: 400, h: 300 })).toEqual({
      x: ANCHOR.x + NW / 2 - 200,
      y: ANCHOR.y + NH / 2 - 150,
    });
  });
});

describe("cellRect (#3367 — a SIGNED lattice)", () => {
  it("places cell (0,0) at the origin", () => {
    const o = gridOrigin(ANCHOR);
    expect(cellRect(ANCHOR, { col: 0, row: 0 })).toEqual({ left: o.x, top: o.y, w: CELL_W, h: CELL_H });
  });

  it("puts NEGATIVE cells left of / above the anchor — the whole point of #3367", () => {
    const o = gridOrigin(ANCHOR);
    expect(cellRect(ANCHOR, { col: -1, row: 0 }).left).toBe(o.x - (CELL_W + GRID_GAP));
    expect(cellRect(ANCHOR, { col: 0, row: -1 }).top).toBe(o.y - (CELL_H + GRID_GAP));
    expect(cellRect(ANCHOR, { col: 1, row: 0 }).left).toBe(o.x + (CELL_W + GRID_GAP));
    expect(cellRect(ANCHOR, { col: 0, row: 1 }).top).toBe(o.y + (CELL_H + GRID_GAP));
  });

  it("NEVER overlaps any other cell — the guarantee the grid exists to provide", () => {
    const rects = [{ col: 0, row: 0 }, ...ringCells(1), ...ringCells(2)].map((c) => cellRect(ANCHOR, c));
    for (let a = 0; a < rects.length; a++) {
      for (let b = a + 1; b < rects.length; b++) {
        expect(overlaps(rects[a], rects[b])).toBe(false);
      }
    }
  });

  it("still never overlaps at the MAXIMUM cell size", () => {
    const cell = { w: CELL_MAX_W, h: CELL_MAX_H };
    const rects = [{ col: 0, row: 0 }, ...ringCells(1)].map((c) => cellRect(ANCHOR, c, cell));
    for (let a = 0; a < rects.length; a++) {
      for (let b = a + 1; b < rects.length; b++) {
        expect(overlaps(rects[a], rects[b])).toBe(false);
      }
    }
  });

  it("tracks the anchor node — the grid moves with the graph rather than freezing at open time", () => {
    const moved = { x: ANCHOR.x + 500, y: ANCHOR.y - 250 };
    const at = { col: -2, row: 1 };
    expect(cellRect(moved, at).left - cellRect(ANCHOR, at).left).toBe(500);
    expect(cellRect(moved, at).top - cellRect(ANCHOR, at).top).toBe(-250);
  });
});

describe("ringCells (#3367)", () => {
  it("ring 0 is the origin; ring 1 is the eight neighbours; ring r has 8r cells", () => {
    expect(ringCells(0)).toEqual([{ col: 0, row: 0 }]);
    expect(ringCells(1)).toHaveLength(8);
    expect(ringCells(2)).toHaveLength(16);
    expect(ringCells(3)).toHaveLength(24);
  });

  it("every cell in ring r is at Chebyshev distance exactly r", () => {
    for (const c of ringCells(3)) expect(Math.max(Math.abs(c.col), Math.abs(c.row))).toBe(3);
  });
});

// ── #3525: placement is UNIFORMITY-first (a tidy tile block), DIRECTION second (the block leans toward
//    the side its nodes sit). Replaces the direction-first #3367 contract, which left sparse strips. ──
/** The bounding box of a set of cells + how many of its cells are empty. */
const blockShape = (ps: MorphPlacement[]) => {
  const cols = ps.map((p) => p.col), rows = ps.map((p) => p.row);
  const w = Math.max(...cols) - Math.min(...cols) + 1;
  const h = Math.max(...rows) - Math.min(...rows) + 1;
  return { w, h, maxDim: Math.max(w, h), holes: w * h - ps.length };
};
/** The mean cell of the block — used to assert which SIDE of the anchor the block leans to. */
const centroid = (ps: MorphPlacement[]) => ({
  col: ps.reduce((a, p) => a + p.col, 0) / ps.length,
  row: ps.reduce((a, p) => a + p.row, 0) / ps.length,
});

describe("placeByDirection (#3525 — uniformity first, direction second)", () => {
  it("the first opened node anchors the grid at (0,0)", () => {
    expect(rooted()).toEqual([{ nodeId: "root", col: 0, row: 0 }]);
  });

  it("a SECOND node opens adjacent to the anchor on its side — a tight 2×1, never a diagonal", () => {
    // Two nodes: the most uniform block is a 2×1 with no holes; direction picks WHICH side.
    expect(cellOf(place(rooted(), "n", 0, -900), "n")).toEqual({ col: 0, row: -1 });
    expect(cellOf(place(rooted(), "s", 0, 900), "s")).toEqual({ col: 0, row: 1 });
    expect(cellOf(place(rooted(), "e", 900, 0), "e")).toEqual({ col: 1, row: 0 });
    expect(cellOf(place(rooted(), "w", -900, 0), "w")).toEqual({ col: -1, row: 0 });
  });

  it("a DIAGONALLY-placed node still opens to an ADJACENT cell — a 2×1 beats a hole-y 2×2 (#3525)", () => {
    // Under direction-first (#3367) a NE node took the diagonal (1,-1), leaving a 2×2 with two gaps.
    // Uniformity-first prefers a gap-free 2×1: the block is adjacent, and stays on the node's side.
    for (const [dx, dy] of [[700, -700], [-700, -700], [700, 700], [-700, 700]] as const) {
      const ps = place(rooted(), "d", dx, dy);
      expect(blockShape(ps)).toMatchObject({ maxDim: 2, holes: 0 }); // adjacent, no diagonal gap
    }
  });

  it("collapses N opened nodes into a tight SQUARE — 4 → an exact 2×2, 9 → an exact 3×3", () => {
    // The heart of #3525: a filled square with NO holes, not a strip or a scatter.
    let four = rooted();
    for (const [id, dx, dy] of [["e", 900, 0], ["w", -900, 0], ["s", 0, 900]] as const) four = place(four, id, dx, dy);
    expect(blockShape(four)).toEqual({ w: 2, h: 2, maxDim: 2, holes: 0 });

    let nine = rooted();
    const dirs: [string, number, number][] = [
      ["e", 900, 0], ["w", -900, 0], ["n", 0, -900], ["s", 0, 900],
      ["ne", 700, -700], ["nw", -700, -700], ["se", 700, 700], ["sw", -700, 700],
    ];
    for (const [id, dx, dy] of dirs) nine = place(nine, id, dx, dy);
    expect(blockShape(nine)).toEqual({ w: 3, h: 3, maxDim: 3, holes: 0 });
  });

  it("never leaves an interior gap while the block is still growing", () => {
    // 'checks for a pattern before filling its slot': at every step the block is as dense as possible,
    // so holes (if any) are only the unfilled tail of the last row — always fewer than a full side.
    let ps = rooted();
    for (let i = 1; i <= 12; i++) {
      ps = place(ps, `x${i}`, ((i % 3) - 1) * 900, (Math.floor(i / 3) - 2) * 900);
      const { maxDim, holes } = blockShape(ps);
      expect(holes).toBeLessThan(maxDim); // at most a partial last row/col, never an interior void
    }
  });

  it("the block LEANS toward the side its nodes sit on — direction survives as the tiebreak", () => {
    // Individual cells may sit in the anchor's column when that completes the square, but the block's
    // centre of mass is unambiguously on the nodes' side. (Direction-first kept every cell strictly
    // sided; #3525 trades that for a uniform block that still points the right way.)
    let west = rooted();
    for (let i = 0; i < 6; i++) west = place(west, `w${i}`, -900, (i - 3) * 30);
    expect(centroid(west).col).toBeLessThan(0);

    let north = rooted();
    for (let i = 0; i < 6; i++) north = place(north, `n${i}`, (i - 3) * 30, -900);
    expect(centroid(north).row).toBeLessThan(0);
  });

  it("breaks a uniformity tie by direction — two equally-compact cells go to the matching side", () => {
    // After the anchor, a west and an east node are each a valid 2×1; direction sends them opposite ways.
    const w = cellOf(place(rooted(), "w", -900, 0), "w");
    const e = cellOf(place(rooted(), "e", 900, 0), "e");
    expect(w.col).toBeLessThan(0);
    expect(e.col).toBeGreaterThan(0);
  });

  it("never places two morphs in the same cell", () => {
    let ps = rooted();
    const dirs: [string, number, number][] = [
      ["a", -900, 0], ["b", 900, 0], ["c", 0, -900], ["d", 0, 900],
      ["e", -700, -700], ["f", 700, 700], ["g", -700, 700], ["h", 700, -700],
      ["i", -900, -30], ["j", -900, 30],
    ];
    for (const [id, dx, dy] of dirs) ps = place(ps, id, dx, dy);
    const keys = ps.map((p) => `${p.col},${p.row}`);
    expect(new Set(keys).size).toBe(keys.length);
  });

  it("is STABLE — placing another node never moves an existing one", () => {
    let ps = rooted();
    ps = place(ps, "west", -900, 0);
    const before = cellOf(ps, "west");
    ps = place(ps, "east", 900, 0);
    ps = place(ps, "north", 0, -900);
    expect(cellOf(ps, "west")).toEqual(before);
    expect(cellOf(ps, "root")).toEqual({ col: 0, row: 0 });
  });

  it("re-placing an already-placed node is a no-op, not a second cell", () => {
    let ps = place(rooted(), "west", -900, 0);
    ps = place(ps, "west", -900, 0);
    expect(ps.filter((p) => p.nodeId === "west")).toHaveLength(1);
  });

  it("fills a freed CENTRE to keep the block compact (#3525 — uniformity beats keeping (0,0) reserved)", () => {
    // Under direction-first (#3367) the freed anchor cell was left empty so a directional node wouldn't
    // 'steal' it. Uniformity-first fills it: leaving a hole in the middle of the block is exactly the
    // sparseness this change removes. The two morphs end up a gap-free 2×1.
    let ps = rooted();
    ps = place(ps, "west", -900, 0);                     // (-1,0)
    ps = releaseCell(ps, "root");                        // the anchor's own morph closed; (0,0) is free
    ps = place(ps, "east", 900, 0);
    const open = ps.filter((p) => p.nodeId !== "root");
    expect(blockShape(open)).toMatchObject({ maxDim: 2, holes: 0 });
    expect(open.some((p) => p.col === 0 && p.row === 0)).toBe(true); // the gap got filled
  });

  it("but the ANCHOR node itself (zero delta) takes the centre back when it re-opens", () => {
    let ps = rooted();
    ps = place(ps, "west", -900, 0);
    ps = releaseCell(ps, "root");
    ps = place(ps, "root", 0, 0);
    expect(cellOf(ps, "root")).toEqual({ col: 0, row: 0 });
  });

  it("does not mutate its input", () => {
    const ps = rooted();
    place(ps, "west", -900, 0);
    expect(ps).toEqual([{ nodeId: "root", col: 0, row: 0 }]);
  });
});

describe("releaseCell / occupants (#3361)", () => {
  it("drops one placement and leaves the others exactly where they were", () => {
    let ps = rooted();
    ps = place(ps, "west", -900, 0);
    ps = place(ps, "east", 900, 0);
    const westCell = cellOf(ps, "west");
    ps = releaseCell(ps, "east");
    expect(occupants(ps)).toEqual(["root", "west"]);
    expect(cellOf(ps, "west")).toEqual(westCell);        // no reflow — a terminal being read must not jump
  });

  it("releasing an absent node changes nothing, and does not mutate", () => {
    const ps = rooted();
    expect(releaseCell(ps, "zzz")).toEqual(ps);
    expect(ps).toHaveLength(1);
  });

  it("occupants lists the node ids in placement order", () => {
    expect(occupants(place(rooted(), "west", -900, 0))).toEqual(["root", "west"]);
    expect(occupants([])).toEqual([]);
  });
});

describe("unionRects (#3361 — the graph parts around ONE region)", () => {
  it("is null with nothing open, so the neighbours snap back", () => {
    expect(unionRects([])).toBeNull();
  });

  it("returns a single rect unchanged — parting around one morph is unchanged behaviour", () => {
    const r = cellRect(ANCHOR, { col: 0, row: 0 });
    expect(unionRects([r])).toEqual(r);
  });

  it("bounds cells on BOTH sides of the anchor (a negative col extends the region left)", () => {
    const u = unionRects([cellRect(ANCHOR, { col: -1, row: 0 }), cellRect(ANCHOR, { col: 0, row: 0 })])!;
    const o = gridOrigin(ANCHOR);
    expect(u.left).toBe(o.x - (CELL_W + GRID_GAP));
    expect(u.w).toBe(CELL_W * 2 + GRID_GAP);
    expect(u.h).toBe(CELL_H);
  });

  it("spans rows above and below", () => {
    const u = unionRects([cellRect(ANCHOR, { col: 0, row: -1 }), cellRect(ANCHOR, { col: 0, row: 1 })])!;
    expect(u.h).toBe(CELL_H * 3 + GRID_GAP * 2);
  });
});

describe("clampCell (#3361 — a shared cell size, bounded)", () => {
  it("passes a sane size through", () => {
    expect(clampCell(800, 600)).toEqual({ w: 800, h: 600 });
  });

  it("clamps to the resize bounds", () => {
    expect(clampCell(10, 10)).toEqual({ w: CELL_MIN_W, h: CELL_MIN_H });
    expect(clampCell(99999, 99999)).toEqual({ w: CELL_MAX_W, h: CELL_MAX_H });
  });

  it("the default cell is within its own bounds", () => {
    expect(clampCell(DEFAULT_CELL.w, DEFAULT_CELL.h)).toEqual(DEFAULT_CELL);
  });
});

// ── `the-in-graph-terminal-cannot-be-clicked-accurately-under-zoom`: the lattice is now a SCREEN-space
//    lattice hung from one WORLD point, because the card it arranges is a constant screen size. ──
describe("the screen/world split (the-in-graph-terminal-cannot-be-clicked-accurately-under-zoom)", () => {
  /** Every zoom the viewport permits, plus the ends. `useGraphViewport` clamps to [0.28, 2.6], so this is
   *  the whole reachable range rather than a sample that happens to look good. */
  const ZOOMS = [0.28, 0.5, 0.85, 1, 1.5, 2, 2.6];

  it("is UNCHANGED at zoom 1 — the default keeps every pre-fix call site byte-identical", () => {
    // The reason `scale` is a defaulted trailing parameter rather than a required one: 60-odd existing
    // assertions above call these with no zoom and must keep passing verbatim.
    expect(cellRect(ANCHOR, { col: 0, row: 0 }, DEFAULT_CELL, 1)).toEqual(cellRect(ANCHOR, { col: 0, row: 0 }));
    expect(cellRect(ANCHOR, { col: -2, row: 1 }, DEFAULT_CELL, 1)).toEqual(cellRect(ANCHOR, { col: -2, row: 1 }));
    expect(gridOrigin(ANCHOR, DEFAULT_CELL, 1)).toEqual(gridOrigin(ANCHOR));
  });

  it("NEVER overlaps at ANY zoom — the invariant that a screen-constant card would otherwise break", () => {
    // THE REGRESSION. While the cards scaled with the graph, cell size and lattice were both world units
    // and non-overlap was trivial. A screen-constant card covers `cell/scale` WORLD units, so it grows as
    // you zoom out — and against the old world-spaced lattice it would have swallowed its neighbours
    // below zoom 1. Dividing the spacing by the same `scale` is what keeps the gutter positive.
    for (const scale of ZOOMS) {
      const rects = [{ col: 0, row: 0 }, ...ringCells(1), ...ringCells(2)]
        .map((c) => cellRect(ANCHOR, c, DEFAULT_CELL, scale));
      for (let a = 0; a < rects.length; a++) {
        for (let b = a + 1; b < rects.length; b++) {
          expect(overlaps(rects[a], rects[b]), `overlap at zoom ${scale}`).toBe(false);
        }
      }
    }
  });

  it("still never overlaps at the MAXIMUM cell size, across the whole zoom range", () => {
    const cell = { w: CELL_MAX_W, h: CELL_MAX_H };
    for (const scale of ZOOMS) {
      const rects = [{ col: 0, row: 0 }, ...ringCells(1)].map((c) => cellRect(ANCHOR, c, cell, scale));
      for (let a = 0; a < rects.length; a++) {
        for (let b = a + 1; b < rects.length; b++) {
          expect(overlaps(rects[a], rects[b]), `overlap at zoom ${scale}`).toBe(false);
        }
      }
    }
  });

  it("reports a world footprint that GROWS as you zoom out and SHRINKS as you zoom in", () => {
    // This is what the neighbour push reads. A card that keeps one screen size necessarily covers more
    // of the world when the world is drawn smaller — reporting the nominal cell instead is what let a
    // zoomed-out panel cover the nodes it was supposed to part.
    expect(cellRect(ANCHOR, { col: 0, row: 0 }, DEFAULT_CELL, 0.5).w).toBe(CELL_W * 2);
    expect(cellRect(ANCHOR, { col: 0, row: 0 }, DEFAULT_CELL, 2).w).toBe(CELL_W / 2);
    expect(cellRect(ANCHOR, { col: 0, row: 0 }, DEFAULT_CELL, 0.5).h).toBe(CELL_H * 2);
    expect(cellRect(ANCHOR, { col: 0, row: 0 }, DEFAULT_CELL, 2).h).toBe(CELL_H / 2);
  });

  it("stays CENTRED on the anchor node at every zoom — the card never drifts off its own node", () => {
    const c = anchorCentre(ANCHOR);
    for (const scale of ZOOMS) {
      const r = cellRect(ANCHOR, { col: 0, row: 0 }, DEFAULT_CELL, scale);
      expect(r.left + r.w / 2).toBeCloseTo(c.x, 9);
      expect(r.top + r.h / 2).toBeCloseTo(c.y, 9);
    }
  });

  it("anchorCentre and cellOffset carry NO zoom term — the reason placement cannot lag a wheel gesture", () => {
    // `view.scale` reaches React only 120ms after a wheel settles (#4140 drives the transform
    // imperatively). Anything the card's POSITION is derived from must therefore be zoom-free, or it
    // drifts for the whole gesture and snaps at the end. These two are what the morph renders with.
    expect(anchorCentre(ANCHOR)).toEqual({ x: ANCHOR.x + NW / 2, y: ANCHOR.y + NH / 2 });
    expect(cellOffset({ col: 0, row: 0 })).toEqual({ dx: 0, dy: 0 });
    expect(cellOffset({ col: 1, row: -1 })).toEqual({ dx: CELL_W + GRID_GAP, dy: -(CELL_H + GRID_GAP) });
    expect(cellOffset({ col: -2, row: 0 }, { w: 400, h: 300 })).toEqual({ dx: -2 * (400 + GRID_GAP), dy: 0 });
  });

  it("keeps a CONSTANT screen gutter — the world gap is the screen gap over the zoom", () => {
    for (const scale of ZOOMS) {
      const a = cellRect(ANCHOR, { col: 0, row: 0 }, DEFAULT_CELL, scale);
      const b = cellRect(ANCHOR, { col: 1, row: 0 }, DEFAULT_CELL, scale);
      expect((b.left - (a.left + a.w)) * scale).toBeCloseTo(GRID_GAP, 9);
    }
  });
});

import { describe, it, expect } from "vitest";
import { applyNavigate, type NavVocab } from "@/app/navigateBridge";
import type { AppStore } from "@/store/types";
import { WORKSPACES, type Workspace } from "@/app/registry";

// A minimal fake store: only the fields + actions applyNavigate touches. Mutating actions write into
// `s` and `read()` returns it fresh — which is the point. Zustand hands out a NEW object per update, so a
// resolver that reads a captured snapshot would report the pre-navigation view; these tests use a live
// getter so that bug can't hide.
function makeVocab(over: Partial<Record<string, unknown>> = {}): NavVocab & { s: Record<string, unknown> } {
  const s: Record<string, unknown> = {
    activeWorkspace: "console",
    projectsPageMode: "projects",
    // Each tabbed workspace keeps its page here (`navigation-vocabulary-follows-the-new-page-structure`).
    // The ack reads the ACTIVE workspace's page from where that workspace stores it — it used to report
    // `projectsPageMode` for every workspace, which was a confident lie once the graphs left the Planner.
    activePageTab: { glance: "network", logs: "activity", teams: "teams" } as Record<string, string>,
    designsKitId: "",
    designsCompId: null,
    designsPreviewState: "loaded",
    kitTheme: "default",
    kits: [{ id: "react-ui" }, { id: "react-d3" }],
    kitThemes: [{ id: "default" }, { id: "nord" }],
    components: [
      { id: "Heatmap", kitId: "react-d3" },
      { id: "BarChart", kitId: "react-d3" },
      { id: "Card", kitId: "react-ui" },
    ],
    setWorkspace: (v: string) => { s.activeWorkspace = v; },
    setProjectsPageMode: (v: string) => { s.projectsPageMode = v; },
    // The knob every tabbed workspace turns — glance, logs, and the four store-backed graphs.
    setActivePageTab: (k: string, v: string) => {
      s.activePageTab = { ...(s.activePageTab as Record<string, string>), [k]: v };
    },
    setKitTheme: (v: string) => { s.kitTheme = v; },
    setDesignsKit: (v: string) => { s.designsKitId = v; s.designsCompId = null; },
    setDesignsComp: (v: string | null) => { s.designsCompId = v; },
    setDesignsPreviewState: (v: string) => { s.designsPreviewState = v; },
    dismissedNotices: [] as string[],
    dismissNotice: (id: string) => { (s.dismissedNotices as string[]).push(id); },
    ...over,
  };
  return {
    s,
    read: () => s as unknown as AppStore,
    // Kept in step with `WORKSPACES` by the test below, deliberately: this fixture drifting from the
    // registry is how `bsc navigate workspace <id>` could fail live while every test here stayed green.
    workspaces: [
      "console", "glance",
      "components", "teams", "algorithms", "data", "sounds",
      // The utilities, Credentials first
      // (`a-credentials-workspace-shows-the-state-of-every-credential`), and the session-memory
      // store's (`a-memory-workspace-shows-what-we-know`).
      "memory", "credentials", "logs", "settings",
    ],
    // Per-workspace now (`navigation-vocabulary-follows-the-new-page-structure`): a flat list checked
    // every workspace's page against the Planner's, so a real Algorithms language would have been
    // refused for not being a Planner tab. `null` is PERMISSIVE — the graphs whose tabs come from
    // hook-local data (languages present, sound kits) are deliberately not enumerated here.
    pagesFor: (w: Workspace) =>
      w === "teams" ? ["teams", "org-default-fleet"]
      : w === "components" ? ["react", "react-native"]
      : null,
  };
}

// The Design Studio "already showing" store — a component navigate folds to it (#3599).
// The Design Studio is its own WORKSPACE now (`five-graphs-become-rail-workspaces`), so "on the
// Studio" is a workspace, not a Planner page mode.
const onStudio = { activeWorkspace: "components" };

describe("navigateBridge — component (the case #3261 needed a human click for)", () => {
  it("when the Studio is showing, selects the component AND lands its workspace + page (intents, not steps)", () => {
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap" }, v);
    expect(ack.error).toBeUndefined();
    // The caller asked for a component; it should not have to know where the Studio lives.
    expect(ack.workspace).toBe("components");
    expect(ack.kit).toBe("react-d3");
    expect(ack.component).toBe("Heatmap");
  });

  it("#3599: OFF the Studio, sets the focus but does NOT yank the user off their current page", () => {
    const v = makeVocab({ activeWorkspace: "logs" });
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap" }, v);
    expect(ack.error).toBeUndefined();
    // The focus IS set (so the Studio shows it when the user opens it themselves) …
    expect(v.s.designsKitId).toBe("react-d3");
    expect(v.s.designsCompId).toBe("Heatmap");
    // … but the user's current view is UNTOUCHED — no forced navigation.
    expect(v.s.activeWorkspace).toBe("logs");
    expect(v.s.projectsPageMode).toBe("projects");
    expect(ack.workspace).toBe("logs");
    // #4248: the refusal is STATED. Without this the ack reads as an ordinary success reporting the
    // current view, so a caller with nothing to photograph concludes the navigate failed and forces the
    // view with `navigate page designs` — the escalation that IS the yank.
    expect(ack.declined).toContain("view unchanged");
    expect(ack.declined).toContain("Do not force it");
    expect(ack.declined).toContain("#3599"); // names the rule, so the refusal is checkable
  });

  it("#3599: an EXPLICIT workspace/page request still navigates (a deliberate steer, not a background focus)", () => {
    const v = makeVocab({ activeWorkspace: "logs" });
    const ack = applyNavigate({ workspace: "components", kit: "react-d3", component: "Heatmap" }, v);
    expect(ack.workspace).toBe("components");
    expect(ack.component).toBe("Heatmap");
    expect(ack.declined, "an honoured steer declines nothing").toBeUndefined();
  });

  it("reports the view read back AFTER the mutations, not the request it was handed", () => {
    // The stale-snapshot bug: read the store once up front and the ack reports the PRE-mutation value
    // (an empty component), which would send every following capture at the wrong node — confidently.
    const v = makeVocab(onStudio);
    expect(v.s.designsCompId).toBeNull();
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap" }, v);
    expect(ack.component).toBe("Heatmap");
    expect(v.s.designsCompId).toBe("Heatmap");
  });

  it("sets the kit BEFORE the component (setDesignsKit clears the selection)", () => {
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap" }, v);
    // If the order flipped, the kit change would null the component and this would be undefined.
    expect(ack.component).toBe("Heatmap");
    expect(v.s.designsCompId).toBe("Heatmap");
  });

  it("resolves a component against the CURRENT kit when none is named", () => {
    const v = makeVocab({ designsKitId: "react-ui" });
    const ack = applyNavigate({ component: "Card" }, v);
    expect(ack.error).toBeUndefined();
    expect(ack.kit).toBe("react-ui");
    expect(ack.component).toBe("Card");
  });

  it("carries a theme through for a themed capture", () => {
    const v = makeVocab();
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap", theme: "nord" }, v);
    expect(ack.theme).toBe("nord");
    expect(ack.component).toBe("Heatmap");
  });

  it("#3717: drives the preview DATA-STATE so a capture targets a specific render", () => {
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap", state: "loading" }, v);
    expect(ack.error).toBeUndefined();
    expect(ack.state).toBe("loading");
    expect(v.s.designsPreviewState).toBe("loading");
    // The state control and navigate now share ONE store value.
  });

  it("#3717: rejects an unknown state, listing the valid ones (no half-apply)", () => {
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap", state: "spinning" }, v);
    expect(ack.error).toContain("unknown state 'spinning'");
    expect(ack.error).toContain("loading");
    // Validated BEFORE any mutation — the component focus did not move either.
    expect(v.s.designsPreviewState).toBe("loaded");
    expect(v.s.designsCompId).toBeNull();
  });
});

// The ack used to report the store SELECTION it had just written, so a component the preview refused to
// build acked exactly like one that rendered. The pure half decides only WHETHER a mount is owed; the
// adapter observes the frame (see useNavigateBridge.test.tsx).
describe("navigateBridge — the ack owes a mount only when one is actually coming", () => {
  it("marks the component to await when the Studio is the visible page", () => {
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap" }, makeVocab(onStudio));
    expect(ack.awaitMount).toBe("Heatmap");
  });

  it("marks it on an EXPLICIT steer from off-Studio too — the view really does switch", () => {
    const v = makeVocab({ activeWorkspace: "logs" });
    const ack = applyNavigate({ workspace: "components", kit: "react-d3", component: "Heatmap" }, v);
    expect(ack.awaitMount).toBe("Heatmap");
  });

  it("awaits NOTHING on a #3599 decline — no frame will rebuild, so waiting would only burn the budget", () => {
    const v = makeVocab({ activeWorkspace: "logs" });
    const ack = applyNavigate({ kit: "react-d3", component: "Heatmap" }, v);
    expect(ack.declined).toBeDefined();
    expect(ack.awaitMount).toBeUndefined();
  });

  it("awaits nothing for a navigate that names no component", () => {
    expect(applyNavigate({ theme: "nord" }, makeVocab(onStudio)).awaitMount).toBeUndefined();
  });

  it("awaits nothing when the presence gate (#4248) left the view alone", () => {
    const v = makeVocab({ activeWorkspace: "logs" });
    const ack = applyNavigate(
      { workspace: "components", kit: "react-d3", component: "Heatmap" },
      { ...v, humanPresent: () => true },
    );
    expect(ack.declined).toContain("someone is using the app");
    expect(ack.awaitMount).toBeUndefined();
  });
});

describe("navigateBridge — unknown ids are errors, not silent no-ops", () => {
  it("rejects an unknown component and names what the kit does have", () => {
    // Silence here would be the worst outcome: the caller captures the previous view believing it moved.
    const v = makeVocab();
    const ack = applyNavigate({ kit: "react-d3", component: "Nope" }, v);
    expect(ack.error).toContain("unknown component 'Nope'");
    expect(ack.error).toContain("react-d3");
    expect(ack.error).toContain("Heatmap");
  });

  it("marks a component miss RETRYABLE so the adapter re-reads the store once", () => {
    // #navigate-answers-from-a-stale-app-snapshot / request #55: this resolves against the app's HYDRATED
    // copy, which only refreshes while the Design Studio is visible. A component written from a shell
    // while the app shows Console is therefore "unknown" here despite existing in the store. The pure
    // function cannot hydrate — it says the miss is worth a re-read and the adapter does it.
    const v = makeVocab();
    expect(applyNavigate({ kit: "react-d3", component: "Nope" }, v).retryAfterHydrate).toBe(true);
    expect(applyNavigate({ kit: "nope-kit" }, v).retryAfterHydrate).toBe(true);
  });

  it("does NOT mark a miss retryable when re-reading components cannot help", () => {
    // A hydrate refreshes components and kits. Vocabulary that does not come from the store — a bad
    // workspace, page or state — is never fixed by re-reading, so retrying would just cost a store read
    // and report the same error twice.
    const v = makeVocab();
    expect(applyNavigate({ workspace: "nowhere" }, v).retryAfterHydrate).toBeUndefined();
    expect(applyNavigate({ state: "sideways" }, v).retryAfterHydrate).toBeUndefined();
  });

  it("rejects a component in the WRONG kit even though the id exists elsewhere", () => {
    const v = makeVocab();
    const ack = applyNavigate({ kit: "react-ui", component: "Heatmap" }, v);
    expect(ack.error).toContain("unknown component 'Heatmap' in kit 'react-ui'");
  });

  it("tells you to name a kit when there is no current one", () => {
    const v = makeVocab({ designsKitId: "" });
    const ack = applyNavigate({ component: "Heatmap" }, v);
    expect(ack.error).toContain("name a kit");
  });

  it("rejects unknown workspace / page / kit / theme, listing the valid ones", () => {
    const v = makeVocab();
    expect(applyNavigate({ workspace: "nope" }, v).error).toContain("unknown workspace");
    // A page is checked against the TARGET workspace's vocabulary, so the case has to name a workspace
    // that HAS one — `console`, the fixture's default, is permissive on purpose.
    expect(applyNavigate({ workspace: "components", page: "nope" }, v).error).toContain("unknown page");
    // …and a permissive workspace lets an arbitrary page through rather than refusing it.
    expect(applyNavigate({ page: "anything" }, v).error).toBeUndefined();
    expect(applyNavigate({ kit: "nope" }, v).error).toContain("unknown kit");
    expect(applyNavigate({ theme: "nope" }, v).error).toContain("unknown theme");
  });

  it("does NOT half-apply: a request with a bad field changes nothing", () => {
    // A half-applied navigation is worse than a refused one — the caller gets an error AND a view that
    // partially moved, so the next capture is wrong in a way nothing reported.
    const v = makeVocab();
    const ack = applyNavigate({ workspace: "glance", theme: "nord", component: "Nope", kit: "react-d3" }, v);
    expect(ack.error).toBeTruthy();
    expect(v.s.activeWorkspace).toBe("console");
    expect(v.s.kitTheme).toBe("default");
    expect(v.s.designsCompId).toBeNull();
  });
});

// REGRESSION, designer request #104 (and its second filing). `bsc ui get keyboardcard` prints the record
// stored as `settings-keyboardcard`, because `resolve_component_handle` falls back to a unique `name`.
// `bsc navigate component` did not, so the same handle that WORKED one command over produced a five-second
// timeout blaming the window here. The reporter concluded the preview was hanging and went debugging
// KeyboardCard's keyboard listeners; there was nothing there. Then `formlane` (id `teams-form-lane`, name
// `FormLane`) reproduced it, and was filed as possibly-a-slow-compile. Two false reports, one lookup gap.
describe("navigateBridge — a component HANDLE resolves the way `bsc ui get` resolves one (#104)", () => {
  // The real store carries `name`; the fixture above deliberately does not, so these cases add it.
  const named = {
    components: [
      { id: "settings-keyboardcard", name: "KeyboardCard", kitId: "app" },
      { id: "teams-form-lane", name: "FormLane", kitId: "app" },
      { id: "settings-themecard", name: "ThemeCard", kitId: "app" },
      { id: "ui-box", name: "Box", kitId: "other-kit" },
    ],
    designsKitId: "app",
    activeWorkspace: "components",
  };

  it("resolves a unique NAME, case-insensitively — the exact handle from the request", () => {
    const v = makeVocab(named);
    for (const handle of ["keyboardcard", "KeyboardCard", "KEYBOARDCARD", "formlane"]) {
      const ack = applyNavigate({ component: handle }, v);
      expect(ack.error, `'${handle}' must resolve`).toBeUndefined();
    }
    // …and the ack reports the id that ACTUALLY landed, not the handle it was asked with, so the caller
    // learns the real id rather than keeping the one that only half-works.
    expect(applyNavigate({ component: "formlane" }, v).component).toBe("teams-form-lane");
  });

  it("an id still WINS over a name of the same spelling — the store is keyed by id", () => {
    // The same precedence `resolve_component_handle` takes. Resolving to the other record would be a
    // silent switcheroo, and the id is the identity every other verb uses.
    const v = makeVocab({
      ...named,
      components: [
        { id: "themecard", name: "Unrelated", kitId: "app" },
        { id: "settings-themecard", name: "themecard", kitId: "app" },
      ],
    });
    expect(applyNavigate({ component: "themecard" }, v).component).toBe("themecard");
  });

  it("REFUSES an ambiguous name instead of picking one, and names both candidates", () => {
    const v = makeVocab({
      ...named,
      components: [
        { id: "a-card", name: "Card", kitId: "app" },
        { id: "b-card", name: "Card", kitId: "app" },
      ],
    });
    const ack = applyNavigate({ component: "Card" }, v);
    expect(ack.error).toContain("is the NAME of 2 components");
    expect(ack.error).toContain("a-card");
    expect(ack.error).toContain("b-card");
    // NOT retryable: a hydrate cannot make an ambiguous name unique, so spending the adapter's retry
    // budget on it would only delay an error the caller can already act on.
    expect(ack.retryAfterHydrate).toBeUndefined();
  });

  it("a genuine miss NAMES the id and suggests the near one, rather than blaming the window", () => {
    const v = makeVocab(named);
    const ack = applyNavigate({ component: "keybordcard" }, v);
    expect(ack.error).toContain("unknown component 'keybordcard'");
    expect(ack.error).toContain("in kit 'app'");
    // A typo has no substring neighbour, so it falls to the bounded sample — which still names real ids.
    expect(ack.error).toContain("settings-keyboardcard");
    expect(ack.retryAfterHydrate).toBe(true);
  });

  it("suggests the affixed id when the caller used the bare one", () => {
    // The shape every real miss here has had: the store id carries a folder prefix nothing on screen
    // shows. With name resolution these now RESOLVE, so the suggestion is for the ones that don't.
    const v = makeVocab({ ...named, components: [{ id: "settings-keyboardcard", name: "Something", kitId: "app" }] });
    expect(applyNavigate({ component: "keyboardcard" }, v).error).toContain("did you mean: settings-keyboardcard");
  });

  it("points at the OTHER kit when the handle lives there", () => {
    const v = makeVocab(named);
    const ack = applyNavigate({ component: "ui-box" }, v);
    expect(ack.error).toContain("it is in kit 'other-kit'");
    expect(ack.error).toContain("bsc navigate component other-kit ui-box");
  });

  it("does not print the whole kit: a miss names at most 8 ids and says how many it withheld", () => {
    // The app kit carries ~476 components. Printing every id buried the one line that mattered under a
    // wall a terminal reader scrolls past — the message existed but could not be read.
    const many = Array.from({ length: 30 }, (_, i) => ({ id: `c${String(i).padStart(2, "0")}`, name: `C${i}`, kitId: "app" }));
    const v = makeVocab({ ...named, components: many });
    const err = String(applyNavigate({ component: "zzz" }, v).error);
    expect(err.match(/c\d\d/g)).toHaveLength(8);
    expect(err).toContain("+22 more");
    expect(err).toContain("bsc ui list --raw");
  });

  it("still resolves by id when the record carries no name at all (the lite projection)", () => {
    // Phase 1 of `hydrateComponents` paints from a 33 KB projection that carries no `name`. Resolution
    // must not depend on a field that is legitimately absent for the first second of a boot.
    const v = makeVocab({ components: [{ id: "Heatmap", kitId: "react-d3" }], designsKitId: "react-d3" });
    expect(applyNavigate({ component: "Heatmap" }, v).error).toBeUndefined();
  });
});

describe("the vocabulary the bridge is handed", () => {
  // `makeVocab` writes the workspace list by hand, and the REAL bridge builds it from WORKSPACES
  // (useNavigateBridge). Nothing connected the two, so every test here could stay green against a
  // list the app no longer has — and `bsc navigate workspace <id>` is answered by the app, not by
  // this file. That is a live CLI verb failing while its unit tests pass, which is the shape this
  // repo keeps getting caught by. Pin the fixture to the registry instead.
  it("matches the real rail registry, so a renamed Workspace cannot pass here and fail in the app", () => {
    expect(makeVocab().workspaces).toEqual(WORKSPACES.map((w) => w.key));
  });

  it("accepts `logs` — the rail destination the Security workspace became", () => {
    const v = makeVocab();
    const ack = applyNavigate({ workspace: "logs" }, v);
    expect(ack.error).toBeUndefined();
    expect(ack.workspace).toBe("logs");
    // The ack reports LOGS' own page, not the Planner's.
    expect(ack.page).toBe("activity");
    // …and the key it replaced is genuinely gone, not merely aliased.
    expect(applyNavigate({ workspace: "security" }, v).error).toContain("unknown workspace");
  });
});

describe("navigateBridge — the other verbs", () => {
  it("workspace / page / theme each move only their own field", () => {
    const v = makeVocab();
    expect(applyNavigate({ workspace: "glance" }, v).workspace).toBe("glance");
    expect(v.s.designsCompId).toBeNull();
    // Stated on a workspace whose page the ack can actually read back: `console` has no page concept
    // (its tabs are index-switched, not string pages), so a bare page there lands nowhere to report.
    expect(applyNavigate({ workspace: "teams", page: "teams" }, v).page).toBe("teams");
    expect(applyNavigate({ theme: "nord" }, v).theme).toBe("nord");
  });

  /** REGRESSION, request #164. A bare `page` (no `--workspace`) used to commit to `DESIGNS_WORKSPACE`
   *  ("components") no matter which workspace was actually showing — even though the validation two
   *  blocks above already checks the page against the CURRENT workspace's own vocabulary. So
   *  `bsc navigate page org-default-fleet` while on Teams silently moved Components' page instead, and
   *  Teams' own page never changed — with no error reported, exactly as request #164 described. */
  it("#164: a bare `page` (no --workspace) commits to the CURRENTLY ACTIVE workspace, not Designs", () => {
    const v = makeVocab({ activeWorkspace: "teams" });
    (v.s.activePageTab as Record<string, string>).teams = "teams";
    const ack = applyNavigate({ page: "org-default-fleet" }, v);
    expect(v.s.activeWorkspace).toBe("teams"); // no workspace was named, so it does not move either
    expect((v.s.activePageTab as Record<string, string>).teams).toBe("org-default-fleet");
    expect(ack.workspace).toBe("teams");
    expect(ack.page).toBe("org-default-fleet");
  });

  it("an empty request is a READ — it reports the view without changing it", () => {
    const v = makeVocab({ activeWorkspace: "glance", designsKitId: "react-d3", designsCompId: "Heatmap" });
    const ack = applyNavigate({}, v);
    expect(ack).toEqual({
      workspace: "glance",
      page: "network",
      kit: "react-d3",
      component: "Heatmap",
      theme: "default",
      state: "loaded",
    });
    expect(v.s.activeWorkspace).toBe("glance");
  });

  it("selecting a kit alone clears the component (it belongs to one kit)", () => {
    const v = makeVocab({ designsKitId: "react-d3", designsCompId: "Heatmap" });
    const ack = applyNavigate({ kit: "react-ui" }, v);
    expect(ack.kit).toBe("react-ui");
    expect(ack.component).toBeUndefined();
  });
});

describe("the presence gate (#4248)", () => {
  const present = { humanPresent: () => true };
  const away = { humanPresent: () => false };

  /** THE bug. #3599 honoured an explicit `--page` as "a deliberate steer", but the designer's background
   *  loop is made of explicit commands — it fired exactly this every ~7s to route around the component
   *  refusal, pulling the user off Algorithms/Sounds/Teams while they worked. */
  it("refuses a bare `page` steer while a human is using the app", () => {
    // A bare `page` now steers within the ACTIVE workspace, so the case is stated on one that has
    // several pages: Teams, sitting on a team, asked to move to the overview.
    const v = { ...makeVocab({ activeWorkspace: "teams" }), ...present };
    v.s.activePageTab = { teams: "org-default-fleet" };
    const ack = applyNavigate({ page: "teams" }, v);
    expect((v.s.activePageTab as Record<string, string>).teams).toBe("org-default-fleet"); // untouched
    expect(ack.declined).toContain("someone is using the app");
  });

  it("refuses a workspace steer too", () => {
    const v = { ...makeVocab({ activeWorkspace: "console" }), ...present };
    applyNavigate({ workspace: "components", page: "react" }, v);
    expect(v.s.activeWorkspace).toBe("console");
  });

  /** The case the steering exists for (#3260/#3263): nobody is there, so nothing is being taken. */
  it("steers normally when nobody is present", () => {
    const v = { ...makeVocab({ activeWorkspace: "console" }), ...away };
    const ack = applyNavigate({ workspace: "components", page: "react" }, v);
    expect(v.s.activeWorkspace).toBe("components");
    expect(ack.declined).toBeUndefined();
  });

  it("--force is the human-driven escape hatch", () => {
    const v = { ...makeVocab({ activeWorkspace: "console" }), ...present };
    const ack = applyNavigate({ workspace: "components", page: "react", force: true }, v);
    expect(v.s.activeWorkspace).toBe("components");
    expect(ack.declined).toBeUndefined();
  });

  /** Refusing the VIEW must not refuse the WORK: the focus lands so the Studio shows the right component
   *  the moment the user opens it — the same shape #3599 chose. */
  it("still sets the focus it was asked for", () => {
    const v = { ...makeVocab({ activeWorkspace: "logs" }), ...present };
    applyNavigate({ workspace: "components", kit: "react-d3", component: "Heatmap" }, v);
    expect(v.s.designsKitId).toBe("react-d3");
    expect(v.s.designsCompId).toBe("Heatmap");
    expect(v.s.activeWorkspace).toBe("logs");
  });

  /** Omitting the probe must behave exactly as before this landed — an absent signal cannot silently
   *  disable a gate, nor silently enable one. */
  it("defaults to unattended when no probe is supplied", () => {
    const v = makeVocab({ activeWorkspace: "console" });
    applyNavigate({ workspace: "components", page: "react" }, v);
    expect(v.s.activeWorkspace).toBe("components");
  });

  it("a non-steering request is unaffected by presence", () => {
    const v = { ...makeVocab({ activeWorkspace: "console" }), ...present };
    const ack = applyNavigate({ theme: "nord" }, v);
    expect(ack.declined).toBeUndefined();
    expect(v.s.kitTheme).toBe("nord");
  });
});


// #54 — a session driving the app from a shell could SEE a banner in a capture and had no way to clear
// it: every banner hides through its own local React state. `dismiss` is the affordance a human already
// had, reachable from the CLI.
describe("navigateBridge — dismissing an app notice", () => {
  it("clears a named notice and reports what it cleared", () => {
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ dismiss: "seed-drift" }, v);
    expect(ack.error).toBeUndefined();
    expect(ack.dismissed).toEqual(["seed-drift"]);
    expect(v.s.dismissedNotices).toContain("seed-drift");
  });

  it("REFUSES a decision-bearing notice, and mutates nothing", () => {
    // "restore or discard?" — hiding it removes the only place the answer can be given.
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ dismiss: "session-recovery" }, v);
    expect(ack.error).toContain("asks a question");
    expect(v.s.dismissedNotices ?? []).toEqual([]);
  });

  it("`all` sweeps the ordinary notices and leaves the question standing", () => {
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ dismiss: "all" }, v);
    expect(ack.dismissed).toContain("seed-drift");
    expect(ack.dismissed).not.toContain("session-recovery");
  });

  it("refuses an unknown id BEFORE mutating anything, like every other validation", () => {
    // A half-applied navigation that also refused a dismissal would leave the caller guessing which
    // half happened — so this is validated with the rest, ahead of the commit.
    const v = makeVocab(onStudio);
    const ack = applyNavigate({ dismiss: "not-a-banner", theme: "nord" }, v);
    expect(ack.error).toContain("unknown notice");
    expect(v.s.kitTheme, "the theme must NOT have been applied").not.toBe("nord");
  });

  it("reports nothing when no dismissal was asked for", () => {
    expect(applyNavigate({ theme: "nord" }, makeVocab(onStudio)).dismissed).toBeUndefined();
  });
});

