// #3602 — the unified navigate helper. Two layers of coverage:
//  1. `applyNavigation`/`dispatchPage` over a FAKE store — proves each workspace's page/entity routes to
//     the RIGHT setter, and that page+entity are set BEFORE the workspace switch (so the target screen
//     mounts already on the right page, never flashing its last-viewed one).
//  2. The real store `navigate` action — proves the wiring, so a caller genuinely cannot forget the page.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { applyNavigation, dispatchPage } from "@/app/navigate";
import type { AppStore } from "@/store/types";
import { useAppStore } from "@/store";

/** A store stub exposing only the setters navigate touches, each a spy. */
function fakeStore() {
  return {
    setWorkspace: vi.fn(),
    setActivePageTab: vi.fn(),
    setProjectsPageMode: vi.fn(),
    setGithubTab: vi.fn(),
    setSettingsSection: vi.fn(),
    setGlanceDrill: vi.fn(),
  };
}

describe("applyNavigation — per-workspace page dispatch (#3602)", () => {
  it("routes tabbed workspaces (glance/mcp/security) through setActivePageTab keyed by workspace", () => {
    // `skills` was one of these until it moved onto the Teams page and stopped being a Workspace.
    for (const ws of ["glance", "logs"] as const) {
      const s = fakeStore();
      applyNavigation(s as unknown as AppStore, { workspace: ws, page: "x" });
      expect(s.setActivePageTab).toHaveBeenCalledWith(ws, "x");
      expect(s.setWorkspace).toHaveBeenCalledWith(ws);
    }
  });

  it("routes a tabbed graph workspace → setActivePageTab", () => {
    // The Planner had its own page-mode knob and is gone
    // (`delete-the-planner-ui-keep-the-planner`); the graph workspaces keep their tab in
    // `activePageTab`, which is the general form now.
    const s = fakeStore();
    applyNavigation(s as unknown as AppStore, { workspace: "algorithms", page: "rust" });
    expect(s.setActivePageTab).toHaveBeenCalledWith("algorithms", "rust");
  });

  it("routes settings → setSettingsSection", () => {
    // The `github` workspace routed to `setGithubTab` until its screen was removed
    // (`delete-the-github-screen-keep-the-integration`). Settings → GitHub is where the integration
    // lives now, which is also where a persisted `activeWorkspace: "github"` is migrated to.
    const se = fakeStore();
    applyNavigation(se as unknown as AppStore, { workspace: "settings", page: "github" });
    expect(se.setSettingsSection).toHaveBeenCalledWith("github");
  });

  it("console carries no string page: a page-less navigate only switches the workspace", () => {
    const s = fakeStore();
    applyNavigation(s as unknown as AppStore, { workspace: "console" });
    expect(s.setWorkspace).toHaveBeenCalledWith("console");
    expect(s.setActivePageTab).not.toHaveBeenCalled();
    expect(s.setProjectsPageMode).not.toHaveBeenCalled();
  });

  it("dispatchPage is a no-op for a workspace with no page mechanism (console)", () => {
    const s = fakeStore();
    dispatchPage(s as unknown as AppStore, "console", "anything");
    expect(s.setActivePageTab).not.toHaveBeenCalled();
    expect(s.setProjectsPageMode).not.toHaveBeenCalled();
  });

  it("omitting page leaves the page untouched; omitting drill leaves the drill untouched", () => {
    const s = fakeStore();
    applyNavigation(s as unknown as AppStore, { workspace: "glance" });
    expect(s.setActivePageTab).not.toHaveBeenCalled();
    expect(s.setGlanceDrill).not.toHaveBeenCalled();
    expect(s.setWorkspace).toHaveBeenCalledWith("glance");
  });

  it("drill routes to the entity setter — including an explicit null to CLEAR it", () => {
    const set = fakeStore();
    applyNavigation(set as unknown as AppStore, { workspace: "glance", page: "network", drill: "proj-a" });
    // The drill is keyed BY TAB now, and the tab is the one this navigation targets (`page`), not the
    // one being left — `applyNavigation` applies the drill before `dispatchPage`.
    expect(set.setGlanceDrill).toHaveBeenCalledWith("network", "proj-a");

    const clear = fakeStore();
    applyNavigation(clear as unknown as AppStore, { workspace: "glance", drill: null });
    // No `page` on this one, so it falls back to the tab already showing.
    expect(clear.setGlanceDrill).toHaveBeenCalledWith("", null);
  });

  it("sets the entity + page BEFORE switching the workspace (mounts on the right page, no flash)", () => {
    const s = fakeStore();
    applyNavigation(s as unknown as AppStore, { workspace: "glance", page: "network", drill: "proj" });
    const drillOrder = s.setGlanceDrill.mock.invocationCallOrder[0];
    const pageOrder = s.setActivePageTab.mock.invocationCallOrder[0];
    const wsOrder = s.setWorkspace.mock.invocationCallOrder[0];
    expect(drillOrder).toBeLessThan(wsOrder);
    expect(pageOrder).toBeLessThan(wsOrder);
  });
});

describe("store navigate action — the wiring cannot forget the page (#3602)", () => {
  beforeEach(() => {
    useAppStore.setState({
      activeWorkspace: "console",
      glanceDrill: {},
      activePageTab: {},
      projectsPageMode: "projects",
      settingsSection: "appearance",
    });
  });

  it("navigate sets workspace + page + drill atomically", () => {
    useAppStore.getState().navigate({ workspace: "glance", page: "network", drill: "proj-x" });
    const s = useAppStore.getState();
    expect(s.activeWorkspace).toBe("glance");
    expect(s.activePageTab.glance).toBe("network");
    expect(s.glanceDrill.network, "the drill is filed under the tab navigated to").toBe("proj-x");
  });

  it("navigate to settings lands on the named section, not the last-viewed one", () => {
    useAppStore.getState().navigate({ workspace: "settings", page: "github" });
    const s = useAppStore.getState();
    expect(s.activeWorkspace).toBe("settings");
    expect(s.settingsSection).toBe("github");
  });

  it("navigate to a graph page sets its tab", () => {
    useAppStore.getState().navigate({ workspace: "algorithms", page: "rust" });
    const s = useAppStore.getState();
    expect(s.activeWorkspace).toBe("algorithms");
    expect(s.activePageTab.algorithms).toBe("rust");
  });
});

implementations.code:
// navigate (#3602) — ONE place that turns "go here" into the right store mutations, so navigation can
// never forget the page.
//
// WHY THIS EXISTS
// A Workspace switch (`setWorkspace`) and the PAGE within it (which tab/section) are set through
// DIFFERENT mechanisms per workspace — tabbed screens persist an uncontrolled `activePageTab[key]`,
// the rest each own a dedicated field (`projectsPageMode`, `githubTab`, `automationsTab`,
// `settingsSection`). So a caller that just did `setWorkspace("glance")` lands on whatever tab was last
// open, not the one it meant — #3598 was FOUR separate one-off fixes for exactly this (triage-complete
// landing on Glance but not the Network tab / not the project, GitHub-connect banner landing on the
// last settings section, …). `navigate({ workspace, page, drill })` makes "specify the page" STRUCTURAL:
// you name the page in the same call that switches the workspace, and this module knows which knob each
// workspace turns.
import type { AppStore } from "@/store/types";
import type { Workspace } from "@/app/registry";

/** A navigation target: WHERE (workspace) + WHICH page within it + an optional entity to focus.
 *  `workspace` is required — the whole point is that you cannot switch screens without saying which
 *  page, so "land on glance" can never silently mean "…on whatever tab happened to be open". */
export interface NavLoc {
  workspace: Workspace;
  /** The page/tab within the workspace. Omit only for a workspace with no pages (console — its tabs are
   *  index-switched, not a string page) or when the workspace's default page is genuinely what you want. */
  page?: string;
  /** An entity to focus on the landing screen (currently only Glance, which drills into a project). Pass
   *  `null` to clear a drill; omit to leave it untouched. */
  drill?: string | null;
}

/** How each workspace sets its current PAGE — the single source of truth for a workspace's page knob.
 *  Tabbed screens (glance/logs) persist an uncontrolled `activePageTab[key]`; the rest own
 *  a dedicated field. `console` is intentionally absent: its "pages" are indexed tabs switched by
 *  `setActiveTab(idx)`, not a string page — a `navigate` to console carries no `page`. */
const WORKSPACE_PAGE: Partial<Record<Workspace, (s: AppStore, page: string) => void>> = {
  glance: (s, page) => s.setActivePageTab("glance", page),
  logs: (s, page) => s.setActivePageTab("logs", page),
  settings: (s, page) => s.setSettingsSection(page),
  // The five GRAPHS (`navigation-vocabulary-follows-the-new-page-structure`). Four of them keep their
  // active tab in `activePageTab`, so they take the same knob glance and logs do — which is exactly why
  // they were made UNCONTROLLED: a tab held in component state cannot be set from here, so the verb
  // would write the store, the page would ignore it, and the ack would report a page nobody is on.
  teams: (s, page) => s.setActivePageTab("teams", page),
  algorithms: (s, page) => s.setActivePageTab("algorithms", page),
  data: (s, page) => s.setActivePageTab("data", page),
  sounds: (s, page) => s.setActivePageTab("sounds", page),
  // Memory's pages are its horizon facet plus the unlinked queue (`a-memory-workspace-shows-what-we-know`).
  // Registered here so `bsc navigate --workspace memory --page future` reaches a page rather than
  // switching the workspace and landing on whatever was last open.
  memory: (s, page) => s.setActivePageTab("memory", page),
  // COMPONENTS IS THE EXCEPTION, and deliberately so. Its tab is DERIVED from the active kit, because a
  // technology has many kits and a tab cannot say which — the graph, inspector and designer dock are
  // all keyed on a kit. So selecting a technology here means selecting a kit within it, the same thing
  // clicking the tab does. Writing `activePageTab["components"]` would be a silent no-op.
  //
  // The first kit of that technology is the choice, matching the tab's own behaviour; an unknown
  // technology leaves the selection alone rather than clearing it to nothing.
  components: (s, page) => {
    const want = page.trim().toLowerCase();
    const first = s.kits.find((k) => ((k.tech ?? "").trim().toLowerCase() || "other") === want);
    if (first) s.setDesignsKit(first.id);
  },
};

/** How each workspace focuses an ENTITY. Only Glance drills today; the map keeps the door open. */
const WORKSPACE_DRILL: Partial<Record<Workspace, (s: AppStore, id: string | null, tab: string) => void>> = {
  // Onto the TAB THIS NAVIGATION TARGETS (`each-glance-tab-owns-its-own-drill`) — the drill is keyed by
  // tab now, so the caller supplies which one rather than this reading the active one.
  glance: (s, id, tab) => s.setGlanceDrill(tab, id),
};

/** Set the page for `workspace` through its own mechanism. Exported so the `bsc navigate` bridge routes
 *  through the SAME map instead of hard-coding one workspace's setter. A workspace with no page
 *  mechanism (console) is a no-op. */
export function dispatchPage(s: AppStore, workspace: Workspace, page: string): void {
  WORKSPACE_PAGE[workspace]?.(s, page);
}

/**
 * Apply a navigation: focus the entity, set the page, THEN switch the workspace — in that order, so the
 * target screen mounts already showing the right page/entity rather than flashing its last-viewed one.
 * Pure over the store (every mutation is a store setter), so it is unit-testable with a fake store.
 */
export function applyNavigation(s: AppStore, loc: NavLoc): void {
  // The drill lands on the tab this navigation TARGETS — `loc.page` when it names one, else the tab
  // already showing. Reading only the CURRENT tab would file it under the page being left, because the
  // drill is applied before `dispatchPage` (deliberately: everything is set before the workspace
  // switch, so the mount lands on the right page with no flash).
  if (loc.drill !== undefined) {
    WORKSPACE_DRILL[loc.workspace]?.(s, loc.drill, loc.page ?? s.activePageTab?.[loc.workspace] ?? "");
  }
  if (loc.page !== undefined) dispatchPage(s, loc.workspace, loc.page);
  s.setWorkspace(loc.workspace);
}

// Network layout (#2505) — the pure (React-free) model behind NetworkPage. A general directed graph
// rides EXACTLY the shared graph stack the Tree layered variant established (treeLayout.ts, #2476):
// `findBackEdges` (#2217) breaks cycles so layering can't diverge, `layerDag` (#2214) assigns depths,
// `orderLayers` (#2418) runs the shared barycenter sweep (neighbors = every edge endpoint, both
// directions — the Glance discipline), and this module owns only the layer→pixel PLACEMENT
// (centered rows, top-down). Nothing here forks graph logic; it only feeds the shared pieces
// arbitrary node/edge input.
import { findBackEdges } from "@/shared/lib/graph/cycles";
import { layerDag } from "@/shared/lib/graph/layers";
import { orderLayers } from "@/shared/lib/graph/order";
import type { GraphEdge } from "@/shared/lib/graph/types";

/** One network node — the page renders label + optional meta on its card. */
export interface NetworkNodeData {
  id: string;
  label: string;
  /** Optional dimmed mono meta under the label (a kind, a count, a rate). */
  meta?: string;
}

/** One directed edge; `id` is derived (`from->to`) when omitted. */
export interface NetworkEdgeData {
  id?: string;
  from: string;
  to: string;
}

/** Node card box (world coords) — shared with NetworkPage's node + edge rendering. */
export const NET_NODE_W = 156;
export const NET_NODE_H = 46;

export interface NetworkLayoutMetrics {
  nodeW: number;
  nodeH: number;
  /** Horizontal clearance between nodes in a row. */
  hGap: number;
  /** Vertical clearance between layers (the gap the edges cross). */
  vGap: number;
  /** World padding around the whole layout. */
  pad: number;
}

export const DEFAULT_NET_METRICS: NetworkLayoutMetrics = {
  nodeW: NET_NODE_W, nodeH: NET_NODE_H, hGap: 30, vGap: 78, pad: 48,
};

export interface NetworkLayout {
  /** Node id → its card's top-left corner in world coords. */
  pos: Map<string, { x: number; y: number }>;
  /** Every edge (incl. cycle-closing ones — they still DRAW; they just don't layer). */
  edges: GraphEdge[];
  /** World (design-space) size — the GraphCanvas `world` box. */
  world: { w: number; h: number };
  /** Node id → its layer (0 = sources). Exposed for tests + callers. */
  layer: Record<string, number>;
}

/** Normalize the page's edges into the shared GraphEdge shape (derive missing ids). */
export function networkEdges(edges: readonly NetworkEdgeData[]): GraphEdge[] {
  return edges.map((e) => ({ id: e.id ?? `${e.from}->${e.to}`, from: e.from, to: e.to }));
}

/**
 * Top-down network placement: cycle-safe `layerDag` depth → row, shared barycenter ordering within
 * each row (neighbors = both endpoints of every edge), rows centered — the same discipline as
 * `layoutTree`, generalized to any directed graph.
 */
export function layoutNetwork(
  nodes: readonly NetworkNodeData[],
  edgeData: readonly NetworkEdgeData[],
  metrics: NetworkLayoutMetrics = DEFAULT_NET_METRICS,
): NetworkLayout {
  const m = metrics;
  const ids = nodes.map((n) => n.id);
  const edges = networkEdges(edgeData);
  const { backEdgeIds } = findBackEdges(ids, edges);
  const layer = layerDag(ids, edges, backEdgeIds);

  // Barycenter neighbors: every edge endpoint, in both directions (multiplicity counts).
  const neighbors = new Map<string, string[]>(ids.map((id) => [id, []]));
  for (const e of edges) {
    if (e.from === e.to) continue;
    neighbors.get(e.from)?.push(e.to);
    neighbors.get(e.to)?.push(e.from);
  }
  const rows = orderLayers(ids, (id) => layer[id] ?? 0, (id) => neighbors.get(id) ?? []);

  const rowWidth = (n: number) => n * m.nodeW + Math.max(0, n - 1) * m.hGap;
  const maxRow = Math.max(0, ...[...rows.values()].map((r) => r.length));
  const w = Math.max(320, 2 * m.pad + rowWidth(maxRow));

  const pos = new Map<string, { x: number; y: number }>();
  let bottom = m.pad;
  for (const [l, row] of [...rows.entries()].sort(([a], [b]) => a - b)) {
    const y = m.pad + l * (m.nodeH + m.vGap);
    const x0 = (w - rowWidth(row.length)) / 2; // center each row — hubs sit toward the middle
    row.forEach((id, i) => pos.set(id, { x: x0 + i * (m.nodeW + m.hGap), y }));
    bottom = y + m.nodeH;
  }
  const h = Math.max(240, bottom + m.pad);

  return { pos, edges, world: { w, h }, layer };
}

