// networkLayout (#2505) — the pure model behind NetworkPage: the shared graph stack (findBackEdges +
// layerDag + orderLayers) over arbitrary directed input, plus the centered-row placement.
import { describe, it, expect } from "vitest";
import { layoutNetwork, networkEdges, NET_NODE_W, NET_NODE_H, type NetworkNodeData } from "@/shared/ui/pages/networkLayout";

const NODES: NetworkNodeData[] = [
  { id: "api", label: "api" },
  { id: "ui", label: "ui" },
  { id: "db", label: "db" },
  { id: "docs", label: "docs" }, // isolated
];
const EDGES = [
  { from: "api", to: "ui" },
  { from: "db", to: "api" },
];

describe("layoutNetwork — layering rides the shared graph stack", () => {
  it("assigns each node its longest-path layer (from → deeper) and derives missing edge ids", () => {
    const l = layoutNetwork(NODES, EDGES);
    expect(l.layer.db).toBe(0);
    expect(l.layer.api).toBe(1);
    expect(l.layer.ui).toBe(2);
    expect(l.layer.docs).toBe(0); // no in-edges → a source row
    expect(l.edges.map((e) => e.id)).toContain("api->ui");
  });

  it("positions every node and stacks layers top-down with the metric gaps", () => {
    const l = layoutNetwork(NODES, EDGES);
    for (const n of NODES) expect(l.pos.get(n.id), n.id).toBeTruthy();
    expect(l.pos.get("db")!.y).toBeLessThan(l.pos.get("api")!.y);
    expect(l.pos.get("api")!.y).toBeLessThan(l.pos.get("ui")!.y);
    // The world box contains every card.
    for (const { x, y } of l.pos.values()) {
      expect(x).toBeGreaterThanOrEqual(0);
      expect(x + NET_NODE_W).toBeLessThanOrEqual(l.world.w);
      expect(y + NET_NODE_H).toBeLessThanOrEqual(l.world.h);
    }
  });

  it("tolerates cycles: layering breaks the back-edge, drawing keeps every edge", () => {
    const cyc = [...EDGES, { from: "ui", to: "db" }]; // db → api → ui → db
    const l = layoutNetwork(NODES, cyc);
    expect(l.edges).toHaveLength(3);                  // the cycle edge still draws
    // …but does not diverge the layers. The shared findBackEdges DFS visits nodes in NODES order,
    // so it roots at "api" and marks db→api as the back-edge — layering keeps api→ui and ui→db
    // (#2515: the original expectation assumed the ADDED edge broke, which the contract never promised).
    expect(l.layer.api).toBe(0);
    expect(l.layer.ui).toBe(1);
    expect(l.layer.db).toBe(2);
    // The invariant that matters: every kept (non-back) edge still flows strictly downward.
    expect(l.layer.ui).toBeGreaterThan(l.layer.api);
    expect(l.layer.db).toBeGreaterThan(l.layer.ui);
  });

  it("networkEdges keeps explicit ids and derives `from->to` for the rest", () => {
    const edges = networkEdges([{ id: "e1", from: "a", to: "b" }, { from: "b", to: "c" }]);
    expect(edges.map((e) => e.id)).toEqual(["e1", "b->c"]);
  });

  it("handles an empty graph without dividing by zero", () => {
    const l = layoutNetwork([], []);
    expect(l.world.w).toBeGreaterThan(0);
    expect(l.world.h).toBeGreaterThan(0);
    expect(l.pos.size).toBe(0);
  });
});

// Cross-graph node addressing (#3115, epic #3114) — URN grammar + the reserved `@bsc/…` import mapping.
import { describe, it, expect } from "vitest";
import {
  formatNodeUrn,
  parseNodeUrn,
  isNodeUrn,
  isNodeGraph,
  parseLibrarySpec,
  isLibrarySpec,
  urnToImportSpec,
  NODE_GRAPHS,
} from "@/shared/lib/graph/nodeUrn";

describe("formatNodeUrn / parseNodeUrn (#3115)", () => {
  it("round-trips a URN for each graph", () => {
    const cases: [Parameters<typeof formatNodeUrn>[0], string, string][] = [
      ["algo", "typescript", "fibonacci.ts"],
      ["ui", "react-ui", "Sparkline"],
      ["sound", "default", "click"],
    ];
    for (const [graph, kit, id] of cases) {
      const urn = formatNodeUrn(graph, kit, id);
      expect(urn).toBe(`${graph}:${kit}/${id}`);
      expect(parseNodeUrn(urn!)).toEqual({ graph, kit, id });
    }
  });

  // #3514 — `<kit>/<id>` is ambiguous when either half holds a `/`, so the grammar has to pick a side.
  // It picks the KIT: a sound kit is SCOPED (`acme/neon`), which is the exact form #3412 taught
  // blueprints to pin, whereas no id has ever contained a slash. The previous split (on the FIRST `/`)
  // guarded the hypothetical case at the cost of the shipping one — `sound:acme/neon/zap` parsed as kit
  // `acme` + id `neon/zap`, so a pinned sound kit resolved NOTHING, silently.
  it("round-trips a SCOPED kit id — the kit may contain a slash", () => {
    const urn = formatNodeUrn("sound", "acme/neon", "zap");
    expect(urn).toBe("sound:acme/neon/zap");
    expect(parseNodeUrn(urn!)).toEqual({ graph: "sound", kit: "acme/neon", id: "zap" });
  });

  it("splits on the LAST slash — the id is the final segment", () => {
    expect(parseNodeUrn("ui:react-ui/forms/Field")).toEqual({ graph: "ui", kit: "react-ui/forms", id: "Field" });
  });

  it("format rejects an empty component instead of minting a malformed URN", () => {
    expect(formatNodeUrn("algo", "", "x")).toBeNull();
    expect(formatNodeUrn("algo", "typescript", "")).toBeNull();
    // @ts-expect-error unknown graph
    expect(formatNodeUrn("nope", "k", "i")).toBeNull();
  });

  it("parse returns null (never throws) for malformed input", () => {
    for (const bad of ["", "algo", "algo:", "algo:typescript", "algo:/id", "algo:kit/", ":kit/id", "unknown:kit/id", "algo/kit/id"]) {
      expect(parseNodeUrn(bad)).toBeNull();
      expect(isNodeUrn(bad)).toBe(false);
    }
    // non-string input is tolerated
    expect(parseNodeUrn(undefined as unknown as string)).toBeNull();
  });

  it("isNodeGraph guards the graph token", () => {
    for (const g of NODE_GRAPHS) expect(isNodeGraph(g)).toBe(true);
    expect(isNodeGraph("designs")).toBe(false);
  });
});

describe("library import specifiers `@bsc/<segment>/<name>` (#3115)", () => {
  it("parses each graph's segment to its graph + name", () => {
    expect(parseLibrarySpec("@bsc/algorithms/fibonacci")).toEqual({ graph: "algo", name: "fibonacci" });
    expect(parseLibrarySpec("@bsc/sounds/click")).toEqual({ graph: "sound", name: "click" });
    expect(parseLibrarySpec("@bsc/ui/Sparkline")).toEqual({ graph: "ui", name: "Sparkline" });
  });

  it("keeps a name path with a slash", () => {
    expect(parseLibrarySpec("@bsc/ui/forms/Field")).toEqual({ graph: "ui", name: "forms/Field" });
  });

  it("rejects non-library / unknown-segment / nameless specs", () => {
    for (const bad of ["react", "@/features/x", "./sibling", "@bsc", "@bsc/", "@bsc/algorithms", "@bsc/algorithms/", "@bsc/nope/x", "@bscx/algorithms/y"]) {
      expect(parseLibrarySpec(bad)).toBeNull();
    }
    expect(isLibrarySpec("react")).toBe(false);
    expect(isLibrarySpec("@bsc/algorithms/fibonacci")).toBe(true);
  });

  it("urnToImportSpec builds the canonical `@bsc/<segment>/<id>` form", () => {
    expect(urnToImportSpec("algo:typescript/fibonacci.ts")).toBe("@bsc/algorithms/fibonacci.ts");
    expect(urnToImportSpec("sound:default/click")).toBe("@bsc/sounds/click");
    expect(urnToImportSpec("ui:react-ui/Sparkline")).toBe("@bsc/ui/Sparkline");
    expect(urnToImportSpec("garbage")).toBeNull();
  });
});

// The node-URN grammar, captured from the LIVE TypeScript so the Rust port can be proved equal.
//
// The grammar is load-bearing for cross-graph resolution: `@bsc/algorithms/fibonacci` is kit-less, so
// a React component resolves a TypeScript implementation across BOTH pillar and technology. The graph
// STORE is Rust's — `bsc graph impl get`, `bsc ui get` — but the grammar that says what a URN IS lived
// only in the renderer, so the backend could hold every record and still not parse a reference to one.
//
// A grammar is defined as much by what it REFUSES as by what it accepts, so the rejections carry the
// same weight here as the accepts.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/graph/nodeUrn.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  NODE_GRAPHS,
  LIBRARY_ROOT,
  LIBRARY_SEGMENT,
  isNodeGraph,
  formatNodeUrn,
  parseNodeUrn,
  isNodeUrn,
  isLibrarySpec,
  parseLibrarySpec,
  urnToImportSpec,
} from "@/shared/lib/graph/nodeUrn";

const FIXTURE = join(process.cwd(), "src/shared/lib/graph/nodeUrn.fixtures.json");

/** Strings put through every parser. Accepts and rejections, each labelled with what it pins. */
const SUBJECTS: Array<[string, string]> = [
  ["a plain urn", "algo:rust/fibonacci"],
  ["the ui graph", "ui:react/Button"],
  ["the sound graph", "sound:kit/click"],
  ["a kit with a slash — LAST slash splits", "algo:rust/nested/fibonacci"],
  ["a deep kit", "ui:react/a/b/c/Thing"],
  ["unknown graph is refused", "nope:rust/fibonacci"],
  ["empty graph is refused", ":rust/fibonacci"],
  ["no colon is refused", "algo/rust/fibonacci"],
  ["colon at index 0 is refused", ":algo:rust/x"],
  ["no slash is refused", "algo:rustfibonacci"],
  ["slash at index 0 of the rest is refused", "algo:/fibonacci"],
  ["empty id is refused", "algo:rust/"],
  ["empty string is refused", ""],
  ["a bare graph name is refused", "algo"],
  ["a library spec is not a urn", "@bsc/algorithms/fibonacci"],
  ["ui library spec", "@bsc/ui/Button"],
  ["sounds library spec", "@bsc/sounds/click"],
  ["a library spec with a nested name", "@bsc/algorithms/a/b"],
  ["unknown segment is refused", "@bsc/nope/fibonacci"],
  ["library root alone is refused", "@bsc/"],
  ["library root with no name is refused", "@bsc/algorithms/"],
  ["a near-miss root is not a library spec", "@bscx/algorithms/fibonacci"],
  ["an ordinary npm package is not a library spec", "react"],
  ["a scoped npm package is not a library spec", "@scope/pkg"],
];

/** Triples put through the formatter, including the rejected ones. */
const FORMATS: Array<[string, string, string, string]> = [
  ["ordinary", "algo", "rust", "fibonacci"],
  ["ui", "ui", "react", "Button"],
  ["unknown graph is refused", "nope", "rust", "x"],
  ["empty kit is refused", "algo", "", "x"],
  ["empty id is refused", "algo", "rust", ""],
];

function build() {
  return {
    note: "GENERATED from the live TypeScript — see nodeUrn.fixtures.gen.test.ts",
    graphs: NODE_GRAPHS,
    libraryRoot: LIBRARY_ROOT,
    librarySegment: LIBRARY_SEGMENT,
    graphPredicate: ["algo", "ui", "sound", "nope", "", "ALGO"].map((g) => ({
      value: g,
      isNodeGraph: isNodeGraph(g as never),
    })),
    formats: FORMATS.map(([why, graph, kit, id]) => ({
      why, graph, kit, id,
      formatted: formatNodeUrn(graph as never, kit, id),
    })),
    subjects: SUBJECTS.map(([why, s]) => ({
      why,
      subject: s,
      parseNodeUrn: parseNodeUrn(s),
      isNodeUrn: isNodeUrn(s),
      isLibrarySpec: isLibrarySpec(s),
      parseLibrarySpec: parseLibrarySpec(s),
      urnToImportSpec: urnToImportSpec(s),
    })),
  };
}

describe("the node-URN grammar is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const text = JSON.stringify(build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("records as many REJECTIONS as accepts — a grammar is defined by what it refuses", () => {
    const s = build().subjects;
    expect(s.filter((x) => x.parseNodeUrn === null).length).toBeGreaterThanOrEqual(8);
    expect(s.filter((x) => x.parseNodeUrn !== null).length).toBeGreaterThanOrEqual(5);
    expect(s.some((x) => x.parseLibrarySpec !== null)).toBe(true);
  });
});

