import { describe, it, expect } from "vitest";
import { isTurnOpen, isTurnOpenDebounced, ACTIVITY_IDLE_GRACE_MS, paneActivityFor, type PaneActivity, needsAttention } from "@/app/console/lib/paneActivity";

// The status-dot gate (#1184): the silence timer must NOT idle a pane whose turn is still open
// (a UserPromptSubmit with no following Stop). These tests pin the pure decision the poller feeds
// into TerminalView's `armQuietTimer` callback.

describe("isTurnOpen — silence-timer gate", () => {
  it("treats a run state as turn-open (gates the silence timer)", () => {
    // A worker that submitted a prompt and is now working-but-silent (thinking / long tool call /
    // backoff) records `run` — the dot must stay run past QUIET_MS instead of false-idling.
    expect(isTurnOpen({ pane: "p1", state: "run", at: 100 })).toBe(true);
  });

  it("treats an idle state as turn-closed (silence timer stays authoritative)", () => {
    // An authoritative Stop records `idle` — the gate releases, so the pane idles.
    expect(isTurnOpen({ pane: "p1", state: "idle", at: 200 })).toBe(false);
  });

  it("treats no activity as NOT turn-open — no regression for non-bash / never-launched panes", () => {
    // A PowerShell/cmd session or a pane that hasn't taken a turn emits no activity at all; the gate
    // stays false so the silence timer behaves exactly as before.
    expect(isTurnOpen(undefined)).toBe(false);
  });
});

describe("isTurnOpenDebounced — worker flicker debounce", () => {
  const NOW = 100_000;

  it("keeps run open regardless of time", () => {
    expect(isTurnOpenDebounced({ pane: "p1", state: "run", at: 0 }, NOW)).toBe(true);
  });

  it("keeps a freshly-idle turn open within the grace window (no blink)", () => {
    // A worker's blocked Stop just recorded idle; its next prompt is about to reopen run. The dot
    // must NOT blink idle in this gap.
    expect(isTurnOpenDebounced({ pane: "p1", state: "idle", at: NOW - 1000 }, NOW)).toBe(true);
    expect(isTurnOpenDebounced({ pane: "p1", state: "idle", at: NOW - (ACTIVITY_IDLE_GRACE_MS - 1) }, NOW)).toBe(true);
  });

  it("releases the gate once idle is older than the grace (genuinely done)", () => {
    expect(isTurnOpenDebounced({ pane: "p1", state: "idle", at: NOW - ACTIVITY_IDLE_GRACE_MS }, NOW)).toBe(false);
    expect(isTurnOpenDebounced({ pane: "p1", state: "idle", at: NOW - 10_000 }, NOW)).toBe(false);
  });

  it("treats no activity as not open (non-bash fallback unchanged)", () => {
    expect(isTurnOpenDebounced(undefined, NOW)).toBe(false);
  });
});

describe("paneActivityFor — per-pane lookup", () => {
  const rows: PaneActivity[] = [
    { pane: "t0p0", state: "idle", at: 10 },
    { pane: "t0p1", state: "run", at: 20 },
  ];

  it("picks this pane's record out of the flat list", () => {
    expect(paneActivityFor(rows, "t0p1")).toEqual({ pane: "t0p1", state: "run", at: 20 });
    // End-to-end: an open turn for t0p1 gates its timer; a closed turn for t0p0 does not.
    expect(isTurnOpen(paneActivityFor(rows, "t0p1"))).toBe(true);
    expect(isTurnOpen(paneActivityFor(rows, "t0p0"))).toBe(false);
  });

  it("returns undefined for a pane with no activity row (and for an empty/undefined list)", () => {
    expect(paneActivityFor(rows, "t0p9")).toBeUndefined();
    expect(paneActivityFor([], "t0p1")).toBeUndefined();
    expect(paneActivityFor(undefined, "t0p1")).toBeUndefined();
  });
});

describe("needsAttention (#4005)", () => {
  const act = (state: "run" | "idle" | "attn", at = 0) => ({ pane: "p", state, at });

  it("is true only for attn", () => {
    expect(needsAttention(act("attn"))).toBe(true);
    expect(needsAttention(act("run"))).toBe(false);
    expect(needsAttention(act("idle"))).toBe(false);
    expect(needsAttention(undefined)).toBe(false);
  });

  it("does NOT make the turn read as open", () => {
    // An `attn` pane is STOPPED, not working. Treating it as turn-open would hold the status dot at
    // "run" for a session that is doing nothing — the exact wrongful-run the #1184 gate exists to
    // avoid, just from the other direction. This adds a signal; it must not re-gate the old one.
    expect(isTurnOpen(act("attn"))).toBe(false);
    expect(isTurnOpenDebounced(act("attn"), 10_000)).toBe(false);
  });

  it("is cleared by the ordinary turn boundaries", () => {
    // The Notification hook only fires; nothing un-fires it. Clearing is the next UserPromptSubmit
    // (`run`) or Stop (`idle`) superseding the row — without that a pane stays flagged forever after
    // a single permission prompt.
    expect(needsAttention(act("run"))).toBe(false);
    expect(needsAttention(act("idle"))).toBe(false);
  });
});

// The turn-open GATE, captured from the live TypeScript so Rust can be proved to match it.
//
// ## Why a fixture
//
// Rust already RECORDS the turn boundaries — `bsc-activity run` on UserPromptSubmit, `idle` on Stop,
// `attn` when Claude Code is blocked on a person — and `logs::pane_activity` reads them back. What it
// does not do is decide what they MEAN: `logs_pane_activity` ships rows out and the renderer gates the
// status dot on them. `epic-frontend-logic-over-backend-resources-belongs-in-rust` moves that decision
// to the side that owns the events.
//
// ## The two rules a tidier port would get wrong
//
// Both are places where the CODE and its own doc comment differ, so reading either alone is not enough:
//
//   * The debounce says "a freshly-`idle` pane is still treated as open". The code is
//     `now - activity.at < graceMs` under a plain `state !== "run"`, so a fresh **`attn`** is held open
//     too. That is the shipping behaviour and the port reproduces it.
//   * `<` is exclusive: at EXACTLY `graceMs` elapsed the gate has already released. A corpus of
//     realistic ages never lands on the boundary and passes either version.
//
//     UPDATE_FIXTURES=1 npx vitest run .bsc-records/app/console/lib/paneActivity.1.test.ts
//
// A regeneration that changes the file is a CHANGE OF BEHAVIOUR. Read the diff before committing it.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  isTurnOpen,
  needsAttention,
  paneActivityFor,
  isTurnOpenDebounced,
  ACTIVITY_IDLE_GRACE_MS,
  type PaneActivity,
} from "@/app/console/lib/paneActivity";

const FIXTURE = join(process.cwd(), "src/app/console/paneActivity.fixtures.json");

const NOW = 1_760_000_000_000;
const G = ACTIVITY_IDLE_GRACE_MS;

/** One row per (state × age), including the ages a realistic corpus never produces. */
const ROWS: { label: string; activity: PaneActivity | undefined; graceMs?: number }[] = [
  { label: "absent — no activity ever recorded", activity: undefined },
  { label: "run, fresh", activity: { pane: "p", state: "run", at: NOW } },
  // A `run` is open however OLD it is: the gate is about the last event, not its age.
  { label: "run, ancient", activity: { pane: "p", state: "run", at: NOW - 10 * 60 * 1000 } },
  { label: "idle, just now", activity: { pane: "p", state: "idle", at: NOW } },
  { label: "idle, inside the grace", activity: { pane: "p", state: "idle", at: NOW - (G - 1) } },
  // THE BOUNDARY. `<` is exclusive, so exactly the grace has already released the gate.
  { label: "idle, exactly at the grace", activity: { pane: "p", state: "idle", at: NOW - G } },
  { label: "idle, past the grace", activity: { pane: "p", state: "idle", at: NOW - (G + 1) } },
  // THE DOC/CODE DIVERGENCE. The comment says the grace is for a freshly-IDLE pane; the code gates on
  // `state !== "run"`, so a fresh `attn` is held open too.
  { label: "attn, fresh — held open despite the doc saying idle", activity: { pane: "p", state: "attn", at: NOW } },
  { label: "attn, past the grace", activity: { pane: "p", state: "attn", at: NOW - (G + 1) } },
  // A FUTURE timestamp (clock skew, or a row written by another machine): `now - at` is negative, which
  // is less than any positive grace, so the gate is open. Not a case any realistic corpus contains.
  { label: "idle, timestamped in the future", activity: { pane: "p", state: "idle", at: NOW + 5000 } },
  // A ZERO grace is a sentinel, not a small number: it disables the debounce entirely, so even a
  // same-millisecond idle is closed.
  { label: "idle, just now, with a zero grace", activity: { pane: "p", state: "idle", at: NOW }, graceMs: 0 },
  { label: "run, with a zero grace", activity: { pane: "p", state: "run", at: NOW - 999_999 }, graceMs: 0 },
  { label: "idle, with a huge grace", activity: { pane: "p", state: "idle", at: NOW - 60_000 }, graceMs: 120_000 },
];

/** The lookup, which is where a wrong pane id silently becomes "no activity". */
const LOOKUPS: { label: string; rows: PaneActivity[] | undefined; paneId: string }[] = [
  { label: "absent list", rows: undefined, paneId: "p" },
  { label: "empty list", rows: [], paneId: "p" },
  {
    label: "first match wins",
    rows: [
      { pane: "a", state: "idle", at: 1 },
      { pane: "p", state: "run", at: 2 },
      { pane: "p", state: "idle", at: 3 },
    ],
    paneId: "p",
  },
  { label: "no match", rows: [{ pane: "a", state: "run", at: 1 }], paneId: "p" },
  { label: "empty pane id matches an empty pane", rows: [{ pane: "", state: "attn", at: 7 }], paneId: "" },
];

function build() {
  return {
    note: "GENERATED from the live TypeScript — see paneActivity.fixtures.gen.test.ts",
    graceMs: ACTIVITY_IDLE_GRACE_MS,
    now: NOW,
    gates: ROWS.map(({ label, activity, graceMs }) => ({
      label,
      activity: activity ?? null,
      graceMs: graceMs ?? null,
      turnOpen: isTurnOpen(activity),
      needsAttention: needsAttention(activity),
      turnOpenDebounced:
        graceMs === undefined ? isTurnOpenDebounced(activity, NOW) : isTurnOpenDebounced(activity, NOW, graceMs),
    })),
    lookups: LOOKUPS.map(({ label, rows, paneId }) => ({
      label,
      rows: rows ?? null,
      paneId,
      // WHOLE RECORD, not just whether one was found — a lookup that returns the wrong row and one that
      // returns none are different bugs and a boolean cannot tell them apart.
      found: paneActivityFor(rows, paneId) ?? null,
    })),
  };
}

describe("the turn-open gate is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const text = JSON.stringify(build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  /** Every state must appear, or the port can hardcode one and pass. */
  it("exercises all three recorded states", () => {
    const seen = new Set(build().gates.map((g) => g.activity?.state).filter(Boolean));
    expect([...seen].sort()).toEqual(["attn", "idle", "run"]);
  });

  /** THE BOUNDARY CASE, asserted as a pair so `<` cannot become `<=` unnoticed. */
  it("pins the grace boundary as exclusive", () => {
    const g = build().gates;
    expect(g.find((x) => x.label === "idle, inside the grace")?.turnOpenDebounced).toBe(true);
    expect(g.find((x) => x.label === "idle, exactly at the grace")?.turnOpenDebounced).toBe(false);
  });

  /** THE DOC/CODE DIVERGENCE, pinned so a port cannot "fix" it into matching the comment. */
  it("holds a fresh attn open, which the doc comment does not say", () => {
    const g = build().gates;
    const fresh = g.find((x) => x.label.startsWith("attn, fresh"));
    expect(fresh?.turnOpenDebounced).toBe(true);
    expect(fresh?.turnOpen).toBe(false); // …while the UNdebounced gate correctly says the agent is not working
    expect(fresh?.needsAttention).toBe(true);
  });

  /** The three predicates must disagree somewhere, or one of them is redundant in the corpus. */
  it("contains a row where each predicate gives a different answer", () => {
    const g = build().gates;
    expect(g.some((x) => x.turnOpen !== x.turnOpenDebounced)).toBe(true);
    expect(g.some((x) => x.needsAttention && !x.turnOpen)).toBe(true);
  });
});

implementations.code:
// Pane identity (#1176). Pane state, the PTY, and crash recovery must key off a STABLE identity
// id, not the positional `t{tabIdx}p{paneIdx}` — positional keys get reused when a tab is closed
// and a new one lands on the index, so the new pane inherits persisted state (paneWasClaude, cwd,
// restoreRequested) and resumes a previous session.
//
// Identity is minted where a pane is created:
//   - MANUAL console ("+" button): an ephemeral id unique to the tab — `man:<tabId>:p<idx>`. The
//     tab already carries a stable uuid `id`, so a fresh manual tab can never collide into an old
//     one's state, and (because the id isn't a `project:…` identity) it is excluded from recovery.
//   - FLEET / TRIAGE panes: a meaningful id minted by project planning / triage launch
//     (`<projectKey>:<streamId>`, `<projectKey>:director`, `<projectKey>:<repo>:triage`), recorded
//     on the tab's `paneIds[]`. Recovery reconnects only the exact identity it belongs to.
//
// Stage 1 wires the MANUAL path; fleet/triage tabs (those with `kind`) keep the positional id until
// Stage 2 mints their `paneIds`.

export interface PaneIdentityTab {
  id?: string;
  /** Fleet ("build") / "triage" tabs are app-created; absence ⇒ a manually-created console. */
  kind?: "build" | "triage";
  /** Per-cell identity ids minted at fleet/triage launch (Stage 2). */
  paneIds?: string[];
}

/** The legacy positional id — still used for fleet/triage tabs until Stage 2. */
export function positionalPaneId(tabIdx: number, paneIdx: number): string {
  return `t${tabIdx}p${paneIdx}`;
}

/** A manual console pane's ephemeral, per-tab id. */
export function manualPaneId(tabId: string, paneIdx: number): string {
  return `man:${tabId}:p${paneIdx}`;
}

/** Fleet worker / director identity ids. */
export function fleetPaneId(projectKey: string, streamId: string): string {
  return `${projectKey}:${streamId}`;
}
export function directorPaneId(projectKey: string): string {
  return `${projectKey}:director`;
}

/** A per-repo triage pane's identity id. */
export function triagePaneId(projectKey: string, repo: string): string {
  return `${projectKey}:${repo}:triage`;
}

/** Whether an id is a manual console pane — manual panes are never auto-recovered (#1176). */
export function isManualPaneId(id: string): boolean {
  return id.startsWith("man:");
}

/**
 * Will the BACKEND require a `.claude/settings.json` gate for this pane before it will spawn?
 *
 * A byte-for-byte mirror of `must_be_gated` (`src-tauri/src/console/pty/mod.rs`): not a `man:` pane,
 * and a `<a>:<b>` shape with a non-empty first segment and at least one non-empty segment after it.
 *
 * It exists because the two sides disagreed, and the disagreement was a DEADLOCK
 * (`a-directors-pane-can-never-write-the-gate-that-lets-it-launch`). Rust refuses a gated pane whose
 * cwd has no gate file — and the only writer of that file, `ensure_session_settings`, sat behind the
 * frontend's `launchesClaude`, which is false for a RESTORED pane (no initCmd, no resolved startup
 * prompt). So the pane could never write the file that would let it launch, silently: the skip logged
 * nothing. Measured at 30 project hubs with no gate file and 10 directors refused in one app run.
 *
 * The rule is the BACKEND's, so the frontend asks the backend's question rather than its own.
 */
export function paneNeedsGate(id: string): boolean {
  if (isManualPaneId(id)) return false;
  const parts = id.split(":");
  return parts.length >= 2 && parts[0] !== "" && parts.slice(1).some((p) => p !== "");
}

/**
 * Whether an id is the dedicated PLANNER pane — `planning_<key>` (Planning.tsx), the intentional
 * exception to the `<key>:<stream>` identity scheme. A planning session is re-entered via the
 * Projects page, not restored from the crash-recovery banner, so it's excluded from recovery (#1579).
 */
export function isPlanningPaneId(id: string): boolean {
  return id.startsWith("planning_");
}

/**
 * Resolve a pane's identity id from its tab + grid position. A minted `paneIds[idx]` (fleet/triage,
 * Stage 2) wins; otherwise a fleet/triage tab keeps the positional id (Stage 1), a manual tab with a
 * stable `id` gets a `man:` id, and an id-less legacy tab falls back to positional.
 */
export function paneIdFor(tab: PaneIdentityTab | undefined, tabIdx: number, paneIdx: number): string {
  const minted = tab?.paneIds?.[paneIdx];
  if (minted) return minted;
  if (tab?.kind) return positionalPaneId(tabIdx, paneIdx);
  if (tab?.id) return manualPaneId(tab.id, paneIdx);
  return positionalPaneId(tabIdx, paneIdx);
}

/**
 * Whether `paneId` is one of the cells `tab` (at grid index `tabIdx`) owns — the inverse of
 * `paneIdFor`. A minted id matches when it is in the tab's `paneIds[]`; a `man:<tabId>:…` id
 * matches when the tab's stable `id` matches; a legacy positional `t<idx>p…` id matches when
 * the tab index matches. Director / worker / triage identity ids only ever belong via `paneIds`.
 *
 * This is the identity-aware replacement for parsing a positional key out of a pane id: a status
 * rollup or a stale-status clear must work for manual (`man:`) and minted fleet/triage ids too,
 * not just the legacy positional shape (#1176).
 */
export function paneBelongsToTab(paneId: string, tab: PaneIdentityTab, tabIdx: number): boolean {
  if (tab.paneIds?.includes(paneId)) return true;
  const parsed = parsePaneIdentity(paneId);
  if (!parsed) return false;
  if (parsed.kind === "manual") return !!tab.id && parsed.tabId === tab.id;
  if (parsed.kind === "positional") return parsed.tabIdx === tabIdx;
  return false;
}

/**
 * Find the tab that owns `paneId` (and its index), or null. Scans by identity (`paneBelongsToTab`)
 * so a manual (`man:…`) or minted fleet/triage id resolves to its real tab — the positional
 * `parsePaneKey` could only ever resolve legacy `t<idx>p…` ids, which silently dropped the rollup
 * for every identity-keyed pane (#1176).
 */
export function findPaneOwnerTab<T extends PaneIdentityTab>(
  tabs: readonly T[],
  paneId: string,
): { tab: T; tabIdx: number } | null {
  for (let i = 0; i < tabs.length; i++) {
    if (paneBelongsToTab(paneId, tabs[i], i)) return { tab: tabs[i], tabIdx: i };
  }
  return null;
}

// ── Parsing identity ids back into meaning (#1266) ──────────────────────────────
//
// The id grammar is self-describing, so a session can be recovered from its NAME alone —
// the key to scanning durable, store-independent sources (the pty ledger, the worktree tree)
// and rebuilding the session topology when the persisted store has lost it.

/** The shape a pane identity id encodes. `positional` is the legacy `t{idx}p{idx}` form. */
export type PaneIdentityKind = "director" | "worker" | "triage" | "manual" | "positional";

export interface ParsedPaneIdentity {
  kind: PaneIdentityKind;
  /** The id as given. */
  raw: string;
  /** Present for director / worker / triage. */
  projectKey?: string;
  /** Present for a worker — its stream id. */
  streamId?: string;
  /** Present for a triage pane — the repo (`owner/name`). */
  repo?: string;
  /** Present for a manual console — its owning tab's stable id. */
  tabId?: string;
  /** Present for manual / positional — the grid cell index. */
  paneIdx?: number;
  /** Present for positional — the tab index. */
  tabIdx?: number;
}

/**
 * Parse a pane identity id back into its structured meaning — the inverse of the minting
 * helpers above (#1266). The grammar:
 *
 *   man:<tabId>:p<idx>          → manual console (ephemeral; never auto-recovered)
 *   t<idx>p<idx>                → legacy positional id
 *   <projectKey>:<repo>:triage  → per-repo triage pane
 *   <projectKey>:director       → a project's director
 *   <projectKey>:<streamId>     → a fleet worker
 *
 * Project keys are sanitized to `[A-Za-z0-9-]` (no colons), so colons are purely structural
 * separators and repo full names carry `/`, never `:`. Returns `null` for an unrecognized
 * shape. Known ambiguity: a worker whose stream id were literally `director` (or a 2-part
 * `<key>:triage`) would classify as director/worker respectively — real planner stream ids
 * never collide with those reserved tails.
 */
/**
 * The panes a crash-restore would ACTUALLY bring back.
 *
 * `paneWasClaude` is not "was running when we crashed" — it is a PERSISTED, append-only ledger of
 * "claude ran here at some point", set once per pane and never cleared. The crash banner counted its
 * whole length, so the offer grew with every session the app had ever hosted and never shrank.
 *
 * Measured on a real profile: 20 flagged panes, of which only 7 were still cells of a tab. The other
 * 13 had nothing to restore INTO — ten of them `debug-studio:req-<n>` one-shot request sessions that
 * had already resolved and closed. The banner offered "Restore 20"; the action would have scheduled
 * at most 7. The count and the thing it counts were computed in two different places, and only one of
 * them knew the rules.
 *
 * So this is the rules, once, for both. A pane is restorable when:
 *   * it is not a MANUAL scratch shell — those never auto-resume, deliberately;
 *   * a host tab can be resolved for it, by `paneIds` membership or (legacy) a positional id whose
 *     tab index is still in range — otherwise the restore has nowhere to put it;
 *   * it is not DISABLED and not ENDED — a finished worker must not be reopened by a crash restore,
 *     which the action already enforced at fire time while the banner advertised it anyway.
 *
 * Order follows `paneWasClaude`'s own key order, so the caller's stagger is stable across calls.
 */
export function crashRestorablePanes(args: {
  paneWasClaude: Record<string, boolean | undefined>;
  tabs: readonly PaneIdentityTab[];
  disabledPanes?: Record<string, boolean | undefined>;
  endedPanes?: Record<string, unknown>;
}): string[] {
  const { paneWasClaude, tabs, disabledPanes = {}, endedPanes = {} } = args;
  return Object.keys(paneWasClaude).filter((paneId) => {
    if (!paneWasClaude[paneId]) return false;
    if (isManualPaneId(paneId)) return false;
    if (disabledPanes[paneId] || endedPanes[paneId]) return false;
    return crashRestoreTabIdx(paneId, tabs) >= 0;
  });
}

/** The tab index a crash-restore would relaunch `paneId` into, or `-1` when there is none. */
export function crashRestoreTabIdx(paneId: string, tabs: readonly PaneIdentityTab[]): number {
  const byId = tabs.findIndex((t) => t.paneIds?.includes(paneId));
  if (byId >= 0) return byId;
  // A legacy positional id encodes its tab index directly — still valid only while that tab exists.
  const m = /^t(\d+)p\d+$/.exec(paneId);
  if (!m) return -1;
  const idx = Number(m[1]);
  return idx >= 0 && idx < tabs.length ? idx : -1;
}

export function parsePaneIdentity(id: string): ParsedPaneIdentity | null {
  // Manual: man:<tabId>:p<idx>. The tabId may contain hyphens but no colon; the :p<n> tail is fixed.
  const manual = /^man:(.+):p(\d+)$/.exec(id);
  if (manual) {
    return { kind: "manual", raw: id, tabId: manual[1], paneIdx: Number(manual[2]) };
  }
  // Legacy positional: t<idx>p<idx>.
  const positional = /^t(\d+)p(\d+)$/.exec(id);
  if (positional) {
    return { kind: "positional", raw: id, tabIdx: Number(positional[1]), paneIdx: Number(positional[2]) };
  }
  const parts = id.split(":");
  // Triage: <key>:<repo>:triage — a "triage" tail with the repo in between (repo has no colon).
  if (parts.length >= 3 && parts[parts.length - 1] === "triage" && parts[0]) {
    return { kind: "triage", raw: id, projectKey: parts[0], repo: parts.slice(1, -1).join(":") };
  }
  // Director: <key>:director.
  if (parts.length === 2 && parts[1] === "director" && parts[0]) {
    return { kind: "director", raw: id, projectKey: parts[0] };
  }
  // Worker: <key>:<streamId> — both parts non-empty.
  if (parts.length >= 2 && parts[0] && parts.slice(1).join(":")) {
    return { kind: "worker", raw: id, projectKey: parts[0], streamId: parts.slice(1).join(":") };
  }
  return null;
}

/**
 * The identity to provision a per-agent sandbox Linux USER for (#1994), or `null` when this pane must
 * keep the sealed distro's shared default user.
 *
 * Per-agent filesystem isolation: a sandboxed FLEET pane — a `<projectKey>:<streamId>` worker or the
 * `<projectKey>:director`, running INSIDE the sealed WSL2 distro (`distro` set) — runs as its OWN
 * non-root Linux user with a locked-down (`700`) home, so co-located agents can't read or tamper with
 * its files even via raw Bash. Every other pane (manual / triage / planner / positional) and every
 * non-sandboxed pane (no `distro`) keep the distro's shared default user.
 *
 * The DIRECTOR gets its own user too (#4260): the issue's requirement is that worker↔director be
 * isolated by the OS rather than by the `bsc-scope` write hook alone. It costs the director nothing —
 * its cwd is the project hub, which lives in the group-shared base (`SHARED_BASE`) that every agent
 * user reaches, not in any one home.
 *
 * Returns the pane id itself — the agent's STABLE identity (`fleetPaneId` / `directorPaneId`) — so a
 * relaunch re-derives (via the Rust `agent_user_name`) and reuses the SAME Linux user + home. Pure (no
 * invoke) so the "which pane gets a user" decision is unit-testable; the caller provisions it with
 * `ensure_sandbox_user` and threads the returned username to `pty_create`'s `wslUser`.
 */
export function sandboxUserIdentity(paneId: string, distro: string | undefined): string | null {
  if (!distro) return null;
  const kind = parsePaneIdentity(paneId)?.kind;
  return kind === "worker" || kind === "director" ? paneId : null;
}

/**
 * The Rust command + args that resolve a pane's on-disk dir from its identity (#1819 hardening) — for
 * a claude pane whose configured cwd came back EMPTY (the async `bscBaseDir` mirror wasn't loaded when
 * the pane's cwd was set, so `projectRepoCwd`/`projectHubCwd` returned ""). The launch can then recover
 * an authoritative absolute path from the backend instead of running permission-less.
 *
 * `triage` → its repo clone dir (`repo_dir_path`); `director` → the project hub (`project_dir_path`).
 * Returns `null` for an id whose dir can't be derived from the id alone — manual/positional panes, or a
 * `worker` (its cwd is a worktree keyed by the agent id, which `ensure_worktree` already supplies). Pure
 * (no invoke) so it's unit-testable; the caller runs the returned command.
 */
export function paneCwdRecovery(
  paneId: string,
): { cmd: "repo_dir_path" | "project_dir_path"; args: Record<string, string> } | null {
  const id = parsePaneIdentity(paneId);
  if (!id?.projectKey) return null;
  if (id.kind === "triage" && id.repo) {
    return { cmd: "repo_dir_path", args: { projectKey: id.projectKey, repo: id.repo } };
  }
  if (id.kind === "director") {
    return { cmd: "project_dir_path", args: { projectKey: id.projectKey } };
  }
  return null;
}

