// Pure logic for the chained-digit console pane selector (Ctrl+Shift + digits).

/**
 * Commit window after the last digit while Ctrl+Shift is held (ms). The buffer
 * also commits immediately when Ctrl/Shift is released, so single-digit
 * selections feel instant — this timeout only matters if the modifier is held.
 */
export const PANE_SELECT_COMMIT_MS = 800;

/**
 * Resolve a typed digit buffer (accumulated while Ctrl+Shift is held) to a
 * 0-based pane index, or null when it doesn't name a real pane in the grid.
 *
 * Pane numbers are 1-based as typed (1 → first pane), so "13" → index 12. A
 * leading zero is rejected so "0"/"01" never select pane 0, and numbers beyond
 * the active grid are ignored.
 *
 * @param buffer digits typed so far, e.g. "1" or "13".
 * @param paneCount number of panes in the active tab's grid.
 */
export function resolvePaneFromBuffer(buffer: string, paneCount: number): number | null {
  if (!/^\d+$/.test(buffer)) return null;
  if (buffer[0] === "0") return null;       // leading zero → no pane 0
  const idx = parseInt(buffer, 10) - 1;     // 1-based → 0-based
  if (idx < 0 || idx >= paneCount) return null;
  return idx;
}

tests.src:
import { describe, it, expect } from "vitest";
import { resolvePaneFromBuffer, PANE_SELECT_COMMIT_MS } from "@/app/console/lib/paneSelect";

describe("resolvePaneFromBuffer", () => {
  it("maps a single digit to a 0-based index", () => {
    expect(resolvePaneFromBuffer("1", 9)).toBe(0);
    expect(resolvePaneFromBuffer("9", 9)).toBe(8);
  });

  it("maps multi-digit numbers so panes 10+ are reachable", () => {
    expect(resolvePaneFromBuffer("10", 16)).toBe(9);
    expect(resolvePaneFromBuffer("13", 16)).toBe(12);
    expect(resolvePaneFromBuffer("16", 16)).toBe(15);
  });

  it("rejects a leading zero so pane 0 is never selected", () => {
    expect(resolvePaneFromBuffer("0", 16)).toBeNull();
    expect(resolvePaneFromBuffer("01", 16)).toBeNull();
  });

  it("rejects numbers beyond the active grid", () => {
    expect(resolvePaneFromBuffer("17", 16)).toBeNull();
    expect(resolvePaneFromBuffer("99", 16)).toBeNull();
  });

  it("rejects empty or non-numeric buffers", () => {
    expect(resolvePaneFromBuffer("", 16)).toBeNull();
    expect(resolvePaneFromBuffer("1a", 16)).toBeNull();
  });

  it("exposes a positive commit window", () => {
    expect(PANE_SELECT_COMMIT_MS).toBeGreaterThan(0);
  });
});

implementations.code:
// Canonical pane activity status (#435), shared by the console grid, the per-tab
// fleet rollup, and the tunnel's desktop→mobile status mapping. ONE vocabulary so
// the dot in a pane, the dot on a tab, and the phone mirror can never disagree:
//   • "run"  — a session is actively working (its turn is in flight).
//   • "on"   — a session is attached/connected but at rest (at its prompt).
//   • "idle" — no live session in the cell.
//
// The pure helpers here are the single decision surface for how those per-pane
// states roll up to a tab, which panes count, and when a stale status is dropped —
// extracted from the console so the rules are unit-testable in isolation.
//
// Pane ids are the STABLE identity ids minted by `paneIdFor` (#1176) — `man:<tabId>:p<n>` for a
// manual tab, the minted `paneIds[]` for fleet/triage — NOT the legacy positional `t<idx>p<n>`.
// So the rollup/clear here resolve cells through `paneIdFor` / `paneBelongsToTab` rather than
// reconstructing positional keys, which only ever matched the legacy shape.
import { paneIdFor, paneBelongsToTab, type PaneIdentityTab } from "@/app/console/lib/paneIdentity";

export type PaneStatus = "run" | "on" | "idle";

/** A tab as the status helpers need it: its layout (cell count) + identity (to mint pane ids). */
export type StatusTab = PaneIdentityTab & { layout: string; state?: PaneStatus };

/** Legacy positional pane key for a (tab, pane) cell — only valid for positional/legacy tabs. */
export function paneKey(tabIdx: number, paneIdx: number): string {
  return `t${tabIdx}p${paneIdx}`;
}

/** Parse a legacy positional pane id back into its (tab, pane) indices, or null when malformed. */
export function parsePaneKey(pid: string): { tabIdx: number; paneIdx: number } | null {
  const m = /^t(\d+)p(\d+)$/.exec(pid);
  return m ? { tabIdx: Number(m[1]), paneIdx: Number(m[2]) } : null;
}

/** Pane-cell count for a "C×R" layout string; falls back to 1 on a malformed layout. */
export function paneCountForLayout(layout: string): number {
  const [c, r] = layout.split("×").map(Number);
  return (c || 1) * (r || 1);
}

/**
 * Roll a tab's per-pane statuses up to a single tab-level status (#435).
 *
 * Only panes that are IN the current grid AND not disabled contribute — so shrinking
 * the layout drops the trimmed cells, and disabling a busy pane immediately stops it
 * counting as "run". Precedence: any live "run" ⇒ "run"; else any "on" ⇒ "on"; else
 * "idle". A pane that paused mid-turn (one cell idle) never pulls a tab out of "run"
 * while another cell is still working — the rollup is over the whole live set.
 *
 * Always computed from the FULL current set, never mutated incrementally, so a stale
 * "run" left by a closed or remounted pane cannot strand the tab in the running state.
 */
export function aggregateTabState(
  tab: StatusTab,
  tabIdx: number,
  statuses: Readonly<Record<string, PaneStatus>>,
  disabledPanes: Readonly<Record<string, boolean>> = {},
): PaneStatus {
  const count = paneCountForLayout(tab.layout);
  let result: PaneStatus = "idle";
  for (let i = 0; i < count; i++) {
    const pid = paneIdFor(tab, tabIdx, i); // the SAME id the pane's PTY + status are keyed by
    if (disabledPanes[pid]) continue; // disabled cell — no live session
    const s = statuses[pid] ?? "idle";
    if (s === "run") return "run"; // any running pane dominates the tab
    if (s === "on") result = "on";
  }
  return result;
}

/**
 * Drop every per-pane status belonging to `tab` (at grid index `tabIdx`) (#435).
 *
 * Used when a tab's panes remount (a runId bump relaunches the sessions) or the tab
 * closes, so a previous session's "run"/"on" never lingers as a stale activity dot on
 * the fresh panes. Membership is by identity (`paneBelongsToTab`), so a manual or minted
 * fleet/triage pane is cleared too — the old positional parse silently kept them. Returns
 * a new map; the input is not mutated.
 */
export function clearTabStatuses(
  statuses: Readonly<Record<string, PaneStatus>>,
  tab: PaneIdentityTab,
  tabIdx: number,
): Record<string, PaneStatus> {
  const next: Record<string, PaneStatus> = {};
  for (const [pid, s] of Object.entries(statuses)) {
    if (!paneBelongsToTab(pid, tab, tabIdx)) next[pid] = s;
  }
  return next;
}

tests.src:
import { describe, it, expect } from "vitest";
import {
  paneKey,
  parsePaneKey,
  paneCountForLayout,
  aggregateTabState,
  clearTabStatuses,
  type PaneStatus,
  type StatusTab,
} from "@/app/console/lib/paneStatus";

// A legacy/positional tab (no id, no kind) → paneIdFor yields `t{idx}p{n}`.
const ptab = (layout: string): StatusTab => ({ layout });

describe("paneKey / parsePaneKey", () => {
  it("round-trips a (tab, pane) cell", () => {
    expect(paneKey(2, 5)).toBe("t2p5");
    expect(parsePaneKey("t2p5")).toEqual({ tabIdx: 2, paneIdx: 5 });
  });
  it("returns null for a non-pane key", () => {
    expect(parsePaneKey("apply_tag")).toBeNull();
    expect(parsePaneKey("t2")).toBeNull();
  });
});

describe("paneCountForLayout", () => {
  it("multiplies cols × rows", () => {
    expect(paneCountForLayout("2×2")).toBe(4);
    expect(paneCountForLayout("4×4")).toBe(16);
    expect(paneCountForLayout("3×2")).toBe(6);
    expect(paneCountForLayout("1×1")).toBe(1);
  });
  it("falls back to 1 on a malformed layout", () => {
    expect(paneCountForLayout("garbage")).toBe(1);
    expect(paneCountForLayout("")).toBe(1);
  });
});

describe("aggregateTabState (#435 — tab rollup)", () => {
  it("is idle when every pane is idle / missing", () => {
    expect(aggregateTabState(ptab("2×2"), 0, {})).toBe("idle");
    expect(aggregateTabState(ptab("2×2"), 0, { t0p0: "idle", t0p1: "idle" })).toBe("idle");
  });

  it("is run when any in-grid pane is running", () => {
    expect(aggregateTabState(ptab("2×2"), 0, { t0p0: "on", t0p3: "run" })).toBe("run");
  });

  it("is on when at least one pane is attached and none is running", () => {
    expect(aggregateTabState(ptab("2×2"), 0, { t0p0: "idle", t0p1: "on" })).toBe("on");
  });

  it("only counts the SOURCE tab's panes, not other tabs", () => {
    const statuses: Record<string, PaneStatus> = { t0p0: "idle", t1p0: "run" };
    expect(aggregateTabState(ptab("2×2"), 0, statuses)).toBe("idle");
    expect(aggregateTabState(ptab("2×2"), 1, statuses)).toBe("run");
  });

  // layout-change: a pane that fell outside the (now smaller) grid stops contributing.
  it("ignores panes trimmed out by a layout shrink", () => {
    const statuses: Record<string, PaneStatus> = { t0p0: "idle", t0p3: "run" };
    expect(aggregateTabState(ptab("2×2"), 0, statuses)).toBe("run"); // p3 is in a 2×2
    expect(aggregateTabState(ptab("1×1"), 0, statuses)).toBe("idle"); // p3 trimmed out of a 1×1
  });

  // disabled-pane: a disabled cell never counts, even if it carries a stale "run".
  it("excludes disabled panes from the rollup", () => {
    const statuses: Record<string, PaneStatus> = { t0p0: "run", t0p1: "idle" };
    expect(aggregateTabState(ptab("2×2"), 0, statuses)).toBe("run");
    expect(aggregateTabState(ptab("2×2"), 0, statuses, { t0p0: true })).toBe("idle");
  });

  // mid-turn-pause: one pane pausing to idle must not pull the tab out of "run"
  // while another pane is still working.
  it("stays run when one pane pauses but another keeps working", () => {
    expect(aggregateTabState(ptab("2×2"), 0, { t0p0: "run", t0p1: "idle", t0p2: "on" })).toBe("run");
  });

  // #1176 regression: a MANUAL tab's panes are keyed `man:<tabId>:p<n>`, NOT positional —
  // the rollup must read those ids (the bug rolled up nothing → a stuck activity dot).
  it("rolls up a manual tab's `man:` pane ids (not positional)", () => {
    const tab: StatusTab = { id: "tab-A", layout: "2×2" };
    expect(aggregateTabState(tab, 0, { "man:tab-A:p1": "run" })).toBe("run");
    expect(aggregateTabState(tab, 0, { "man:tab-A:p0": "on" })).toBe("on");
    // A stray positional id at this index does NOT count for a manual tab.
    expect(aggregateTabState(tab, 0, { t0p0: "run" })).toBe("idle");
    // Disabled keyed by the manual id excludes the cell.
    expect(aggregateTabState(tab, 0, { "man:tab-A:p0": "run" }, { "man:tab-A:p0": true })).toBe("idle");
  });

  // #1176 regression: fleet/triage tabs carry minted `paneIds[]` (director/worker ids).
  it("rolls up a fleet tab's minted paneIds", () => {
    const tab: StatusTab = { id: "x", kind: "build", layout: "1×2", paneIds: ["proj:director", "proj:auth"] };
    expect(aggregateTabState(tab, 0, { "proj:auth": "run" })).toBe("run");
    expect(aggregateTabState(tab, 0, { "proj:director": "on" })).toBe("on");
  });
});

describe("clearTabStatuses (#435 — stale clear on close/remount)", () => {
  it("drops only the target tab's pane statuses", () => {
    const statuses: Record<string, PaneStatus> = {
      t0p0: "run", t0p1: "on",
      t1p0: "run", t1p1: "idle",
    };
    expect(clearTabStatuses(statuses, ptab("2×2"), 0)).toEqual({ t1p0: "run", t1p1: "idle" });
  });

  it("leaves non-pane keys untouched and does not mutate the input", () => {
    const statuses: Record<string, PaneStatus> = { t0p0: "run", apply_tag: "run" as PaneStatus };
    const out = clearTabStatuses(statuses, ptab("2×2"), 0);
    expect(out).toEqual({ apply_tag: "run" }); // unrecognized key kept; positional t0p* dropped
    expect(statuses).toEqual({ t0p0: "run", apply_tag: "run" }); // unchanged
  });

  // remount: after clearing, the aggregate for that tab is idle until panes re-emit —
  // so a relaunched tab never inherits the prior session's running dot.
  it("makes the cleared tab aggregate to idle", () => {
    const statuses: Record<string, PaneStatus> = { t0p0: "run", t0p1: "run" };
    const cleared = clearTabStatuses(statuses, ptab("2×2"), 0);
    expect(aggregateTabState(ptab("2×2"), 0, cleared)).toBe("idle");
  });

  // #1176 regression: clears a manual tab's `man:` ids (the positional parse kept them,
  // so a relaunched manual tab inherited a stale running dot).
  it("clears a manual tab's `man:` ids and keeps other tabs", () => {
    const statuses: Record<string, PaneStatus> = {
      "man:tab-A:p0": "run", "man:tab-A:p1": "on",
      "man:tab-B:p0": "run",
    };
    expect(clearTabStatuses(statuses, { id: "tab-A" }, 0)).toEqual({ "man:tab-B:p0": "run" });
  });
});

implementations.code:
/**
 * Rolling byte buffer for PTY output that arrives while a TerminalView is
 * hidden (background tab, fullscreen-of-another-pane, view switched off
 * "console"). Drops oldest chunks once over `maxBytes` so a long-streaming
 * background pane can't grow the JS heap without bound — matching what xterm
 * does to its own scrollback for visible terminals.
 *
 * Flushed in one `term.write` call when the pane becomes visible, so background
 * panes pay zero render cost while hidden and the user sees everything still
 * within the cap when they switch back. Part of #52's "make each pane cheaper"
 * direction (the other lever besides WebGL + per-slice selectors).
 */
export class PendingPtyData {
  private chunks: string[] = [];
  private bytes = 0;
  constructor(private readonly maxBytes: number) {}

  /** Append a PTY chunk. Drops oldest chunks first to stay under `maxBytes`. */
  push(s: string): void {
    if (s.length === 0) return;
    this.chunks.push(s);
    this.bytes += s.length;
    // Keep at least one chunk so a single oversized payload survives intact;
    // dropping it would lose data the user might still want to see on flush.
    while (this.bytes > this.maxBytes && this.chunks.length > 1) {
      const dropped = this.chunks.shift()!;
      this.bytes -= dropped.length;
    }
  }

  /** Return everything buffered as one string and clear. Empty string when nothing pending. */
  flush(): string {
    if (this.chunks.length === 0) return "";
    const out = this.chunks.join("");
    this.chunks = [];
    this.bytes = 0;
    return out;
  }

  /** Current byte count. Used by callers that want to skip a no-op flush. */
  size(): number { return this.bytes; }
}

tests.src:
import { describe, it, expect } from "vitest";
import { PendingPtyData } from "@/app/console/lib/pendingPtyData";

/**
 * Pins the contract used by TerminalView's hide-and-buffer path (#52). The
 * helper trades a small JS-heap allocation for skipping xterm.write while a
 * pane is hidden; on flush it must hand back everything still within the cap,
 * in order.
 */
describe("PendingPtyData", () => {
  it("flush returns all pushed chunks concatenated, in order", () => {
    const p = new PendingPtyData(1024);
    p.push("hello ");
    p.push("world");
    expect(p.flush()).toBe("hello world");
  });

  it("flush on empty returns ''", () => {
    expect(new PendingPtyData(1024).flush()).toBe("");
  });

  it("flush clears the buffer and resets size to 0", () => {
    const p = new PendingPtyData(1024);
    p.push("abc");
    expect(p.size()).toBe(3);
    p.flush();
    expect(p.size()).toBe(0);
    expect(p.flush()).toBe("");
  });

  it("size tracks total bytes across pushes", () => {
    const p = new PendingPtyData(1024);
    p.push("ab");      // 2
    p.push("cdef");    // 4 → 6
    p.push("");        // ignored
    expect(p.size()).toBe(6);
  });

  it("drops the oldest chunks first once size exceeds the cap", () => {
    // Cap is small so we can drive the eviction predictably.
    const p = new PendingPtyData(10);
    p.push("AAAA");    // size 4
    p.push("BBBB");    // size 8
    p.push("CCCC");    // size 12 → evict "AAAA" → size 8
    expect(p.size()).toBeLessThanOrEqual(10);
    expect(p.flush()).toBe("BBBBCCCC");
  });

  it("keeps at least one chunk even when it alone exceeds the cap", () => {
    // A single oversized payload (e.g. a giant claude response) should survive
    // intact rather than being dropped — dropping would silently lose data the
    // user might still want to see on flush.
    const p = new PendingPtyData(8);
    p.push("X".repeat(64));
    // Cap exceeded, but the lone chunk stays.
    expect(p.size()).toBe(64);
    expect(p.flush()).toBe("X".repeat(64));
  });

  it("eviction respects insertion order when multiple chunks must go", () => {
    const p = new PendingPtyData(6);
    p.push("AA");      // 2
    p.push("BB");      // 4
    p.push("CC");      // 6
    p.push("DDDD");    // 10 → evict "AA" (8) → evict "BB" (6) — still within cap
    expect(p.flush()).toBe("CCDDDD");
  });
});

// #3610 / #4086 — the persisted snapshot must NOT carry a `bsc`-owned library.
//
// Zustand `persist` re-`JSON.stringify`s the whole partialized snapshot on EVERY store write. #3610
// found `components` (~592 KB) riding along on every unrelated tick and freezing the app; #4086 found
// the same shape in `blueprints` (395 KB), `skills` (71 KB), `personas` (33 KB) and `teams` (6 KB) —
// together 96% of a 519 KB file. Each is REPLACED from its own SQLite store at boot, so the persisted
// copy was a second source that could only drift.
//
// These guard that they stay out, and that genuine UI/settings state stays in.
import { describe, it, expect } from "vitest";
import { persistedState, migrateAutoResumeOff } from "@/store/persist";
import { useAppStore } from "@/store";

describe("persistedState — the persist allowlist (#3610)", () => {
  it("does NOT persist any bsc-owned library (each re-hydrates from its store at boot)", () => {
    const snap = persistedState(useAppStore.getState());
    // Paired with the hydrate that owns each one — a field may only be dropped BECAUSE something
    // else restores it, so the pairing is the actual invariant.
    for (const [field, owner] of [
      ["components", "hydrateComponents"],
      ["blueprints", "store/index.ts blueprint list --full"],
      ["skills", "hydrateSkills"],
      ["skillGroups", "hydrateSkills"],
      ["personas", "hydratePersonas"],
      ["teams", "hydrateOrgs"],
    ]) {
      expect(field in snap, `${field} must stay out of persist — ${owner} restores it`).toBe(false);
    }
  });

  it("a fat bsc-owned library added to the store does NOT grow the persisted snapshot (#4086)", () => {
    // The generalization of the #3610 proof: the heavy libraries no longer ride along on every write.
    const before = JSON.stringify(persistedState(useAppStore.getState())).length;
    const fat = (n: number) => Array.from({ length: n }, (_, i) => ({ id: `x${i}`, body: "y".repeat(4000) }));
    useAppStore.setState({ blueprints: fat(100) as never, skills: fat(30) as never, personas: fat(20) as never });
    expect(JSON.stringify(persistedState(useAppStore.getState())).length).toBe(before);
  });

  it("a full 600 KB component library added to the store does NOT grow the persisted snapshot", () => {
    // The direct proof of the fix, independent of any seed sizes: inject a fully-hydrated library and
    // show the serialized snapshot is byte-for-byte unchanged — i.e. the heavy blob no longer rides
    // along on every write. Before the fix this delta was ~600 KB per write.
    const before = JSON.stringify(persistedState(useAppStore.getState())).length;
    const fatLibrary = Array.from({ length: 154 }, (_, i) => ({ id: `c${i}`, srcText: "x".repeat(4000) }));
    useAppStore.setState({ components: fatLibrary as never });
    const after = JSON.stringify(persistedState(useAppStore.getState())).length;
    expect(after).toBe(before);
    expect("components" in persistedState(useAppStore.getState())).toBe(false);
  });

  it("still persists genuine UI + settings + library state (not an over-broad deletion)", () => {
    const snap = persistedState(useAppStore.getState());
    // A representative field from every domain that MUST survive a restart.
    for (const key of [
      "activeWorkspace", "tabs", "keybindings",           // shell / console UI
      "githubToken", "githubState",                        // github
      "planFleet", "planStages",                           // planner
      "kits", "kitUsage", "kitDispatches",                 // kit state (kept: small caches + durable queue)
    ]) {
      expect(key in snap).toBe(true);
    }
  });

  it("returns a plain projection, not the whole store (no store methods leak in)", () => {
    const snap = persistedState(useAppStore.getState()) as Record<string, unknown>;
    expect(typeof snap.setWorkspace).toBe("undefined");
    expect(typeof snap.navigate).toBe("undefined");
  });
});

// #restart-does-not-resume-sessions — the v1→v2 flip that actually reaches existing installs.
describe("migrateAutoResumeOff (persist v1 → v2)", () => {
  it("turns a persisted `true` OFF on the upgrade — the case every existing install is in", () => {
    // This is the whole point of the migration. `autoResumeClaude` defaulted TRUE, so the persisted
    // snapshot carries an explicit `true` that is rehydrated OVER the new default — moving the default
    // alone would have left every affected install auto-resuming exactly as before.
    expect(migrateAutoResumeOff({ autoResumeClaude: true }, 1).autoResumeClaude).toBe(false);
  });

  it("leaves an already-off install alone", () => {
    expect(migrateAutoResumeOff({ autoResumeClaude: false }, 1).autoResumeClaude).toBe(false);
  });

  it("does NOT re-flip a deliberate re-enable — it is one-time, keyed on the upgrade", () => {
    // The setting survives so it can be switched back on. If this ran on every load, turning it on in
    // Settings would silently revert at the next restart and read as the toggle being broken.
    expect(migrateAutoResumeOff({ autoResumeClaude: true }, 2).autoResumeClaude).toBe(true);
    expect(migrateAutoResumeOff({ autoResumeClaude: true }, 3).autoResumeClaude).toBe(true);
  });

  it("tolerates a snapshot that never had the field", () => {
    expect(migrateAutoResumeOff({}, 1)).toEqual({});
  });
});

// ── the role must be as durable as everything derived from it ────────────────────────────────────
//
// `a-fleet-pane-comes-back-uncaged-after-an-app-restart`. `paneRoles` and `panePersonas` were the
// only pane-identity fields left OUT of the allowlist, while every value derived from the role —
// the profile, the write globs, the flow, the repo, the stream, the cwd — was persisted beside
// them. After a restart `paneRole()` resolved undefined, `sandboxPlanFor` computed backend "none",
// and a fleet pane relaunched on the host with no cage and no role gate. MEASURED: a director came
// back as `claude --model sonnet` with `/proc/<pid>/ns/mnt` equal to the host's.
//
// A studio pane survived the same restart caged, which is what hid this: `paneRole()` falls back to
// `studioRoleForPaneId`, so a studio role is derivable from the pane id. A fleet role is not.

describe("persistedState — a pane's isolation survives a restart", () => {
  it("persists the ROLE, not only the things derived from it", () => {
    const snap = persistedState(useAppStore.getState());
    // The pairing IS the invariant: each derived field is only meaningful alongside the role that
    // produced it, so persisting one without the other is what made the set incoherent.
    for (const derived of ["paneProfiles", "paneRoleGlobs", "paneFlows", "paneRepos"]) {
      expect(derived in snap, `${derived} is persisted, so the role that produced it must be too`).toBe(true);
    }
    expect("paneRoles" in snap, "the role decides whether the pane gets a cage at all").toBe(true);
    expect("panePersonas" in snap, "a persona may narrow the role's permissions; losing it widens the session").toBe(true);
  });

  it("carries a fleet pane's role across a persist round-trip", () => {
    // The end-to-end shape of the failure: assign a director, serialize the way zustand does,
    // and read the role back. Undefined here is exactly what produced an uncaged director.
    useAppStore.setState({
      paneRoles: { "network-monitor:director": "director" },
      panePersonas: { "network-monitor:director": "director" },
    } as never);

    const rehydrated = JSON.parse(JSON.stringify(persistedState(useAppStore.getState())));

    expect(rehydrated.paneRoles?.["network-monitor:director"]).toBe("director");
    expect(rehydrated.panePersonas?.["network-monitor:director"]).toBe("director");
  });
});

// ── a chosen provider must be as durable as the model it launches (#175) ─────────────────────────
//
// `paneProviders` and `paneModels` are both in `PANE_KEYED_MAPS`, but only `paneModels` was in this
// allowlist. Every read falls back `paneProviders[paneId] ?? "claude"`, so after a restart a pane KEPT
// the local model it had been given and silently reverted to Claude Code — which cannot run it.
// `fleetStartProject` re-derives a fleet pane's provider through `effectiveHarness` at launch, which is
// why the fleet path never showed this: a manually-chosen pane has nothing to re-derive it from.

describe("persistedState — a pane's chosen provider survives a restart (#175)", () => {
  it("persists paneProviders alongside paneModels", () => {
    const snap = persistedState(useAppStore.getState());
    expect("paneModels" in snap).toBe(true);
    expect("paneProviders" in snap, "paneModels is persisted, so the provider that runs it must be too").toBe(true);
  });

  it("carries a manually-chosen local provider + model across a persist round-trip", () => {
    // The end-to-end shape of the failure: assign a local provider/model to a pane, serialize the
    // way zustand does, and read them back. A provider missing here is exactly what made the pane
    // fall back to "claude" and get handed a model id it cannot run.
    useAppStore.setState({
      paneProviders: { "studio-code:blueprint": "ollama" },
      paneModels: { "studio-code:blueprint": "qwen3.5:9b" },
    } as never);

    const rehydrated = JSON.parse(JSON.stringify(persistedState(useAppStore.getState())));

    expect(rehydrated.paneProviders?.["studio-code:blueprint"]).toBe("ollama");
    expect(rehydrated.paneModels?.["studio-code:blueprint"]).toBe("qwen3.5:9b");
  });
});


// A reaped session must not come back on the next launch (#a-reaped-session-comes-back-on-restart).
describe("dormancy survives a restart", () => {
  it("persists dormantPanes, so only sessions live at shutdown come back", () => {
    const pane = "village-animal-hospital:director";
    // Driven through the REAL action rather than a hand-built snapshot, so this exercises the same
    // path the backend's `pty-reaped` listener takes.
    useAppStore.getState().reapPane(pane);
    expect(useAppStore.getState().dormantPanes[pane]).toBe(true);

    // The layout persists in full, so EVERY pane in `tabs` auto-launches on boot unless something
    // per-pane says otherwise. `endedPanes`/`disabledPanes` already said so; `dormantPanes` did not,
    // which is why seventeen sessions relaunched when two were wanted.
    expect(persistedState(useAppStore.getState()).dormantPanes).toHaveProperty(pane, true);
  });

  it("clears on resume, so a resumed pane is not dormant forever", () => {
    const pane = "twitter-clone-test:api";
    useAppStore.getState().reapPane(pane);
    expect(persistedState(useAppStore.getState()).dormantPanes).toHaveProperty(pane, true);

    useAppStore.getState().resumePane(pane);
    // DELETED, not stored as `false`. This file exists because a persisted blob is re-stringified on
    // every store write; one key per REAPED pane is bounded, one per pane ever seen is not.
    expect(persistedState(useAppStore.getState()).dormantPanes).not.toHaveProperty(pane);
  });
});

// #4088 — the Glance triaged marker moved from app-state.json into projects.db.
//
// The marker gates the ENTIRE Glance network (`filterTriaged`, #2541): an untriaged project does not
// appear at all. Living only in the persisted zustand blob meant no `bsc` command could read or repair
// it, an app-state reset silently emptied the graph, and a missing node could only be diagnosed by
// reading a raw JSON blob — which is exactly what happened to `network-monitor` and `studio-code`.
import { describe, it, expect, vi, beforeEach } from "vitest";

const setDbTriaged = vi.fn();
vi.mock("@/features/planner/list/projectsDbBridge", async (orig) => ({
  ...(await orig<Record<string, unknown>>()),
  setDbTriaged: (...a: unknown[]) => setDbTriaged(...a),
}));

import { useAppStore } from "@/store";
import { persistedState } from "@/store/persist";

beforeEach(() => {
  setDbTriaged.mockReset();
  useAppStore.setState({ triagedProjects: {} });
});

describe("the triaged marker is durable, not a persisted blob (#4088)", () => {
  it("is NOT in the persist allowlist — projects.db owns it now", () => {
    expect("triagedProjects" in persistedState(useAppStore.getState())).toBe(false);
  });

  it("writes through to projects.db when a project is triaged", () => {
    useAppStore.getState().markProjectTriaged("network-monitor");
    expect(setDbTriaged).toHaveBeenCalledWith("network-monitor");
    expect(useAppStore.getState().triagedProjects["network-monitor"]).toBeTypeOf("number");
  });

  it("keeps the FIRST timestamp — re-triaging never rewrites history", () => {
    useAppStore.setState({ triagedProjects: { alpha: 111 } });
    useAppStore.getState().markProjectTriaged("alpha");
    expect(useAppStore.getState().triagedProjects.alpha).toBe(111);
  });

  it("ignores an empty key rather than writing a junk row", () => {
    useAppStore.getState().markProjectTriaged("");
    expect(setDbTriaged).not.toHaveBeenCalled();
    expect(Object.keys(useAppStore.getState().triagedProjects)).toEqual([]);
  });

  it("hydrate UNIONS the db set in without dropping a marker set this session", () => {
    // The upgrade path: a marker that exists only in the pre-#4088 cache must survive hydration, or a
    // project the user already worked disappears from Glance the first time they launch.
    useAppStore.setState({ triagedProjects: { "set-this-session": 999 } });
    useAppStore.getState().hydrateTriaged({ "from-db": 111, "set-this-session": 222 });
    const out = useAppStore.getState().triagedProjects;
    expect(out["from-db"]).toBe(111);
    expect(out["set-this-session"]).toBe(999); // the in-memory marker wins, nothing is lost
  });
});

