// planBoardProjection (#2498) — the `plan` store_state domain payload from gate-hook fixtures.
import { describe, it, expect } from "vitest";
import type { Stage } from "@/features/planner/stages/focusedPlan";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import { defaultService, type DeployConfig } from "@/features/planner/lib/deployConfig";
import { buildPlanBoardPayload } from "@/features/planner/session/planBoardProjection";

const stage = (key: string, status: Stage["status"], over: Partial<Stage> = {}): Stage => ({
  key, name: key, glyph: "◇", blurb: `${key} blurb`, gate: `${key} gate`,
  index: 0, total: 2, status, fraction: status === "complete" ? 1 : 0.5,
  unmet: [], ...over,
});

const fleet: FleetPlan = {
  recommended: 2,
  reasoning: "",
  streams: [
    { id: "auth", name: "Auth", repo: "acme/api", owns: ["src/auth/**"], issues: ["#1", "#2"], dependsOn: [], persona: "backend-dev" },
    { id: "ui", name: "UI", repo: "acme/web", owns: [], issues: ["#3"], dependsOn: ["auth"] },
  ],
  director: { enabled: true },
};

const base = {
  projectId: "demo",
  title: "Demo",
  currentStage: "features",
  statusLabel: "in_progress",
  gateReady: true,
  planComplete: false,
  stages: [
    stage("discovery", "complete"),
    stage("features", "active", { unmet: [{ label: "features defined", detail: "0 features" }], optional: false }),
  ],
  confirmed: new Set(["scope", "goal"]),
  skipped: ["market"],
};

describe("buildPlanBoardPayload", () => {
  it("carries the stage board with per-stage status + unmet gate reasons", () => {
    const out = buildPlanBoardPayload(base);
    expect(out).toMatchObject({
      projectId: "demo", title: "Demo", currentStage: "features",
      statusLabel: "in_progress", gateReady: true, planComplete: false,
    });
    expect(out.stages).toEqual([
      { key: "discovery", name: "discovery", glyph: "◇", status: "complete", fraction: 1, optional: undefined, unmet: [] },
      { key: "features", name: "features", glyph: "◇", status: "active", fraction: 0.5, optional: false, unmet: [{ label: "features defined", detail: "0 features" }] },
    ]);
    // Prompt/blurb prose stays desktop-side.
    expect(JSON.stringify(out.stages)).not.toContain("blurb");
  });

  it("sorts confirmed/skipped for a stable (dedup-friendly) serialization", () => {
    const out = buildPlanBoardPayload(base);
    expect(out.confirmed).toEqual(["goal", "scope"]);
    expect(out.skipped).toEqual(["market"]);
  });

  it("summarizes fleet streams (issue counts, deps, persona) + the director flag", () => {
    const out = buildPlanBoardPayload({ ...base, fleet });
    expect(out.streams).toEqual([
      { id: "auth", name: "Auth", repo: "acme/api", issues: 2, dependsOn: [], persona: "backend-dev" },
      { id: "ui", name: "UI", repo: "acme/web", issues: 1, dependsOn: ["auth"], persona: undefined },
    ]);
    expect(out.directorEnabled).toBe(true);
    // Owned globs / kickoff prompts are execution detail — not on the board.
    expect(JSON.stringify(out.streams)).not.toContain("src/auth");
  });

  it("defaults to an empty fleet + undefined configs without crashing", () => {
    const out = buildPlanBoardPayload(base);
    expect(out.streams).toEqual([]);
    expect(out.directorEnabled).toBe(false);
    expect(out.deploy).toEqual({ defined: false, services: [] });
    expect(out.market).toEqual({ defined: false, summary: "", recommendation: undefined });
  });

  it("summarizes deploy services and the market verdict", () => {
    // A REAL service (the same defaultService the planner seeds) so the `defined` gate helper
    // runs over a complete shape, with the summary fields overridden for the assertion.
    const deploy: DeployConfig = {
      services: [{ ...defaultService("acme/web"), id: "web", platform: "vercel", workload: "static" }],
    };
    const out = buildPlanBoardPayload({
      ...base,
      deploy,
      market: {
        summary: "Strong niche",
        scores: {},
        verdict: { recommendation: "go", rationale: "clear demand" },
      },
    });
    expect(out.deploy.services).toEqual([{ id: "web", repo: "acme/web", platform: "vercel", workload: "static" }]);
    expect(out.market).toMatchObject({ summary: "Strong niche", recommendation: "go" });
    // `defined` comes from the real gate helpers — a partial config stays false.
    expect(typeof out.deploy.defined).toBe("boolean");
    expect(out.market.defined).toBe(false); // no dimension scores → marketDefined is false
  });
});

implementations.code:
// MCP-server assignment from the planner (#174). The planner assigns an MCP server to a project via
// `bsc plan mcp add <name>` (plan.db); the section poll resolves each assigned catalog name into the
// MCP-servers subsystem (`applyMcpAssign` installs it; a PERSONA carrying it is what puts it in a
// session's `.mcp.json` — mcp-servers-belong-to-the-persona), so the same launch wiring loads it with
// glue. Pure (no React/Tauri) so the catalog mapping is unit-testable and shared with its tests.
// (The old `<mcp_assign>` stream tag + its parser were removed in the tag→bsc migration, #2012.)

import { mcpFromCatalog, type McpServer } from "@/features/mcp";
import { resolveMcpInstallDir, catalogLink } from "@/features/mcp";

/**
 * The {@link McpServer} (minus id) a `<mcp_assign name>` resolves to: the catalog
 * template for `name`, **enabled** and **scoped to `projectId`** so it applies to that
 * project's build/triage sessions. An unknown name yields a blank stdio server the user
 * completes; required env values stay blank (never invent secrets).
 *
 * For a downloadable (first-party) server, `baseDir` resolves the `{dir}` placeholder in
 * the run config to its on-disk install path (`~/.base-studio-code/mcp/<repo>`). Without
 * this the launched config keeps a literal `--directory {dir}` and the server never starts.
 */
export function mcpAssignToServer(name: string, projectId: string, baseDir = ""): Omit<McpServer, "id"> {
  const def = resolveMcpInstallDir(mcpFromCatalog(name), name, baseDir);
  // `projects` is gone as a SCOPING mechanism (mcp-servers-belong-to-the-persona) but remains on the
  // type until the field itself is dropped; a blueprint-declared server is installed globally and
  // reaches a session only once a persona carries it.
  void projectId;
  return { ...def, enabled: true, projects: [] };
}

/** Whether a `<mcp_assign>` name is a downloadable first-party server (has a catalog
 *  download link) — i.e. assigning it should also clone its repo. */
export function isDownloadableMcp(name: string): boolean {
  return !!catalogLink(name);
}

export interface McpStoreLike {
  mcpServers: McpServer[];
  addMcpServer: (def: Omit<McpServer, "id">) => void;
  updateMcpServer: (id: string, patch: Partial<McpServer>) => void;
}

/**
 * Idempotently apply one `<mcp_assign>` to the MCP-servers store: if a server with this
 * name already exists, just ensure it's enabled and scoped to the project (a global
 * server — `projects: []` — is left global); otherwise add a fresh catalog-derived def.
 * Returns whether a NEW server was added (vs. an existing one updated), for callers that
 * want to report it. Keeping this here (not in the React component) makes the dedup/scope
 * rule unit-testable.
 */
export function applyMcpAssign(store: McpStoreLike, name: string, projectId: string, baseDir = ""): boolean {
  const existing = store.mcpServers.find(
    (e) => e.name.toLowerCase() === name.toLowerCase(),
  );
  if (existing) {
    store.updateMcpServer(existing.id, { enabled: true });
    return false;
  }
  store.addMcpServer(mcpAssignToServer(name, projectId, baseDir));
  return true;
}

