import { describe, it, expect } from "vitest";
import {
  isFeatureKey,
  featureSlug,
  parseFeatureSection,
  featureSectionsToIssues,
  featureDiscoveryComplete,
  incompleteFeatureSections,
  FEATURE_LABEL,
} from "@/features/planner/issues/planFeatures";

describe("isFeatureKey / featureSlug", () => {
  it("recognizes a repo-tier feature key and extracts its slug", () => {
    expect(isFeatureKey("repo__web__feat__login-form")).toBe(true);
    expect(featureSlug("repo__web__feat__login-form")).toBe("login-form");
  });

  it("rejects non-feature sections", () => {
    expect(isFeatureKey("repo__web__api")).toBe(false);     // a dimension, not a feature
    expect(isFeatureKey("repo__web__feat__")).toBe(false);  // empty slug
    expect(isFeatureKey("feat__login")).toBe(false);        // project-tier, not repo-tier
    expect(isFeatureKey("goal")).toBe(false);
    expect(featureSlug("repo__web__api")).toBeNull();
  });
});

describe("parseFeatureSection", () => {
  it("pulls the leading heading title and acceptance checkboxes out of the body", () => {
    const content = [
      "# Login form",
      "",
      "Build the email/password form against POST /sessions.",
      "",
      "- [ ] validates email format",
      "- [x] shows an inline error on 401",
    ].join("\n");
    const f = parseFeatureSection(content, "login-form");
    expect(f.title).toBe("Login form");
    expect(f.acceptance).toEqual(["validates email format", "shows an inline error on 401"]);
    expect(f.body).toBe("Build the email/password form against POST /sessions.");
  });

  it("falls back to the humanized slug, and keeps a former phase: marker as plain body content (#1912)", () => {
    const f = parseFeatureSection("just an approach, no heading", "password-reset");
    expect(f.title).toBe("Password reset");
    expect(f.body).toBe("just an approach, no heading");
    // Milestone phases were removed (#1912): a `phase:` line is no longer parsed — it's body content.
    const g = parseFeatureSection("phase: 2\njust prose", "x");
    expect(g.body).toBe("phase: 2\njust prose");
  });

  it("keeps a non-leading heading in the body and only consumes the FIRST heading as title", () => {
    const f = parseFeatureSection("# Title\nintro\n## Approach\nsteps", "t");
    expect(f.title).toBe("Title");
    expect(f.body).toBe("intro\n## Approach\nsteps");
  });
});

describe("featureDiscoveryComplete (#490 rubric)", () => {
  const feat = (body: string, acceptance: string[]) => parseFeatureSection(
    [body.trim() ? `approach: ${body}` : "", ...acceptance.map(a => `- [ ] ${a}`)].join("\n"),
    "slug",
  );

  it("complete when behavior + acceptance present", () => {
    const r = featureDiscoveryComplete(feat("Build the form.", ["shows inline error on 401"]));
    expect(r.complete).toBe(true);
    expect(r.missingBehavior).toBe(false);
    expect(r.missingAcceptance).toBe(false);
  });

  it("incomplete (hard gate) when acceptance is missing", () => {
    const r = featureDiscoveryComplete(feat("Build the form.", []));
    expect(r.complete).toBe(false);
    expect(r.missingAcceptance).toBe(true);
    expect(r.missingBehavior).toBe(false);
  });

  it("incomplete (hard gate) when behavior body is empty", () => {
    const r = featureDiscoveryComplete({ body: "", acceptance: ["returns 200"], title: "T" });
    expect(r.complete).toBe(false);
    expect(r.missingBehavior).toBe(true);
  });

  it("flags missing edge/error cases as a soft warning when body has no keywords", () => {
    const r = featureDiscoveryComplete(feat("Build the happy path only.", ["renders the list"]));
    expect(r.complete).toBe(true);         // not a hard-gate failure
    expect(r.missingEdgeCases).toBe(true); // soft warning surfaced
  });

  it("clears missingEdgeCases when body mentions an error keyword", () => {
    const r = featureDiscoveryComplete(feat("Shows an error state when the fetch fails.", ["shows spinner"]));
    expect(r.missingEdgeCases).toBe(false);
  });
});

describe("featureSectionsToIssues (#490 hard gate)", () => {
  const repos = ["acme/web", "acme/api"];

  it("converts feature sections to synthetic PlanIssues, resolving the repo short name", () => {
    const sections = [
      { k: "repo__web__feat__login", content: "# Login\napproach here\n- [ ] works" },
      // Sessions endpoint now has acceptance so it passes the gate
      { k: "repo__api__feat__sessions-endpoint", content: "# Sessions endpoint\nadd POST /sessions\n- [ ] returns 201" },
      { k: "repo__web__api", content: "not a feature" },  // ignored
      { k: "goal", content: "ignored" },
    ];
    const issues = featureSectionsToIssues(sections, repos);
    expect(issues).toHaveLength(2);
    expect(issues[0]).toMatchObject({
      ref: "feat:web:login",
      title: "Login",
      repo: "acme/web",
      labels: [FEATURE_LABEL],
      acceptance: ["works"],
    });
    expect(issues[1]).toMatchObject({ ref: "feat:api:sessions-endpoint", title: "Sessions endpoint", repo: "acme/api" });
  });

  it("hard gate: skips features missing acceptance criteria", () => {
    const sections = [
      { k: "repo__web__feat__no-ac", content: "# No AC\napproach only, no checkboxes" },
      { k: "repo__web__feat__has-ac", content: "# Has AC\napproach\n- [ ] works" },
    ];
    const issues = featureSectionsToIssues(sections, repos);
    expect(issues).toHaveLength(1);
    expect(issues[0].ref).toBe("feat:web:has-ac");
  });

  it("hard gate: skips features with no behavior body", () => {
    const sections = [{ k: "repo__web__feat__empty", content: "- [ ] criterion only, no body" }];
    expect(featureSectionsToIssues(sections, repos)).toHaveLength(0);
  });

  it("leaves repo undefined when the short name matches no linked repo (publish files it under the default)", () => {
    const issues = featureSectionsToIssues(
      [{ k: "repo__mobile__feat__x", content: "some approach here\n- [ ] works" }],
      repos,
    );
    expect(issues).toHaveLength(1);
    expect(issues[0].repo).toBeUndefined();
    expect(issues[0].ref).toBe("feat:mobile:x");
  });
});

describe("incompleteFeatureSections (#490 UI gate surface)", () => {
  it("returns blocked features with their reasons", () => {
    const sections = [
      { k: "repo__web__feat__missing-both", content: "# Empty feature" },
      { k: "repo__web__feat__missing-ac", content: "# No AC\nsome approach\n" },
      { k: "repo__web__feat__complete", content: "# Done\napproach\n- [ ] ok" },
    ];
    const blocked = incompleteFeatureSections(sections);
    expect(blocked).toHaveLength(2);
    expect(blocked.map(f => f.key)).toContain("repo__web__feat__missing-both");
    expect(blocked.map(f => f.key)).toContain("repo__web__feat__missing-ac");
    const noAc = blocked.find(f => f.key === "repo__web__feat__missing-ac")!;
    expect(noAc.reasons).toContain("no acceptance criteria");
  });

  it("returns empty when all features are complete", () => {
    const sections = [{ k: "repo__web__feat__ok", content: "# Good\napproach\n- [ ] criterion" }];
    expect(incompleteFeatureSections(sections)).toHaveLength(0);
  });
});

import { describe, it, expect } from "vitest";
import { parseFleetFile, withDerivedStreamIssues } from "@/features/planner/fleet/planFleet";
import { DEFAULT_FLOW } from "@/features/planner/fleet/agentFlow";

describe("withDerivedStreamIssues (#2615 — a worker launches with its real issues, not a placeholder)", () => {
  const streams = [{ id: "api", issues: [] }, { id: "ui", issues: ["#9"] }, { id: "docs", issues: [] }];
  const issues = [
    { ref: "#1", stream: "api" }, { ref: "#2", stream: "api" },
    { ref: "#3", stream: "ui" },  // ui already lists its own — must NOT be overridden
    { ref: "#4" },                // no owning stream — ignored
    { stream: "api" },            // no ref — ignored
  ];
  it("derives an empty stream's issues from the issues that name it; keeps a populated stream's own", () => {
    const out = withDerivedStreamIssues(streams, issues);
    expect(out.find(s => s.id === "api")!.issues).toEqual(["#1", "#2"]); // derived from issue.stream
    expect(out.find(s => s.id === "ui")!.issues).toEqual(["#9"]);        // authored list wins, untouched
    expect(out.find(s => s.id === "docs")!.issues).toEqual([]);          // no matching issues → stays empty
  });
});

describe("parseFleetFile", () => {
  it("parses a full fleet, defaulting list fields", () => {
    const raw = JSON.stringify({
      recommended: 3,
      reasoning: "three independent areas",
      director: { enabled: true, role: "integrator" },
      streams: [
        { id: "auth-ui", name: "Auth UI", repo: "own/web", owns: ["src/auth/**"], issues: ["#1", "#2"], dependsOn: [], prompt: "prompts/auth-ui-kickoff.md" },
        { id: "api", repo: "own/api" },
      ],
    });
    expect(parseFleetFile(raw)).toEqual({
      recommended: 3,
      reasoning: "three independent areas",
      director: { enabled: true, role: "integrator", drive: "event" },
      streams: [
        { id: "auth-ui", name: "Auth UI", repo: "own/web", owns: ["src/auth/**"], issues: ["#1", "#2"], dependsOn: [], prompt: "prompts/auth-ui-kickoff.md" },
        { id: "api", name: "api", repo: "own/api", owns: [], issues: [], dependsOn: [], prompt: undefined },
      ],
      // Agent-relationship fields default to empty when the fleet declares none (#…).
      artifacts: [],
      edges: [],
    });
  });

  it("carries `systemSessions` through — the parser drops any field it does not name", () => {
    // The regression: the field was added to FleetPlan and read by the graph, but this parser builds its
    // result field-by-field, so every fleet loaded from plan.db had it undefined regardless of what the
    // store held — and the declaration could never render.
    const raw = JSON.stringify({ streams: [{ id: "a", repo: "r" }], systemSessions: ["designer", "librarian"] });
    expect(parseFleetFile(raw)!.systemSessions).toEqual(["designer", "librarian"]);
  });

  it("cleans the system-sessions list at the boundary and leaves it undefined when absent", () => {
    const raw = JSON.stringify({
      streams: [{ id: "a", repo: "r" }],
      systemSessions: ["designer", "designer", "  librarian  ", "", 7, null],
    });
    expect(parseFleetFile(raw)!.systemSessions).toEqual(["designer", "librarian"]); // de-duped, trimmed, non-strings dropped
    // absent ⇒ undefined, NOT [] — "not declared" and "declared as none" stay distinguishable
    expect(parseFleetFile(JSON.stringify({ streams: [{ id: "a", repo: "r" }] }))!.systemSessions).toBeUndefined();
  });

  it("drops a stream with no id, but KEEPS a repo-less stream visible (#2611 — no silent hiding)", () => {
    const raw = JSON.stringify({ streams: [{ name: "no id", repo: "own/web" }, { id: "no-repo" }, { id: "ok", repo: "own/api" }] });
    // the id-less stream is dropped (unkeyable); the repo-less one STAYS (repo "") so it shows in the plan
    const streams = parseFleetFile(raw)!.streams;
    expect(streams.map(s => s.id)).toEqual(["no-repo", "ok"]);
    expect(streams.find(s => s.id === "no-repo")!.repo).toBe("");
  });

  it("defaults a repo-less stream to the project's SOLE repo (#2611)", () => {
    const raw = JSON.stringify({ streams: [{ id: "a" }, { id: "b", repo: "own/api" }] });
    const streams = parseFleetFile(raw, ["own/web"])!.streams;
    expect(streams.find(s => s.id === "a")!.repo).toBe("own/web"); // defaulted to the one linked repo
    expect(streams.find(s => s.id === "b")!.repo).toBe("own/api"); // an explicit repo is untouched
  });

  it("keeps a repo-less stream empty (visible) when the repo can't be defaulted (0 or >1 repos)", () => {
    const raw = JSON.stringify({ streams: [{ id: "a" }] });
    expect(parseFleetFile(raw, [])!.streams[0].repo).toBe("");                     // no repos → can't default
    expect(parseFleetFile(raw, ["own/web", "own/api"])!.streams[0].repo).toBe(""); // ambiguous → don't guess
  });

  it("carries a stream's assigned MCP servers, undefined when none (#1054)", () => {
    const raw = JSON.stringify({
      streams: [
        { id: "sci", repo: "o/r", mcp: ["Research", "Compliance"] },
        { id: "ui", repo: "o/r" },
      ],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.streams[0].mcp).toEqual(["Research", "Compliance"]);
    expect(fleet.streams[1].mcp).toBeUndefined();
  });

  it("carries a stream's granted commands, undefined when none (#1572)", () => {
    const raw = JSON.stringify({
      streams: [
        { id: "rust", repo: "o/r", commands: ["cargo", "wasm-pack"] },
        { id: "ui", repo: "o/r" },
      ],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.streams[0].commands).toEqual(["cargo", "wasm-pack"]);
    expect(fleet.streams[1].commands).toBeUndefined();
  });

  it("carries a stream's persona reference, undefined when none (#2094)", () => {
    const raw = JSON.stringify({
      streams: [
        { id: "docs", repo: "o/r", persona: "persona-documentor" },
        { id: "ui", repo: "o/r" },
        { id: "blank", repo: "o/r", persona: "  " }, // whitespace ⇒ undefined
      ],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.streams[0].persona).toBe("persona-documentor");
    expect(fleet.streams[1].persona).toBeUndefined();
    expect(fleet.streams[2].persona).toBeUndefined();
  });

  it("round-trips a per-stream model VERBATIM, tier or local (#173)", () => {
    // This used to validate against the closed Claude-tier set and silently drop anything else — which
    // dropped every local model a director assigned, since `qwen3.5:9b` was never going to be a tier.
    // `AgentStream.model` is a SessionModel precisely because what a session RUNS is wider than what the
    // picker offers; the parser must not narrow it back down on the way through.
    const raw = JSON.stringify({
      streams: [
        { id: "deep",  repo: "o/r", model: "opus-4.5" },     // a Claude tier — kept
        { id: "cheap", repo: "o/r", model: "qwen3.5:9b" },   // a local model — ALSO kept, not dropped
        { id: "empty", repo: "o/r", model: "   " },          // whitespace-only — still clears
        { id: "plain", repo: "o/r" },                        // unset — undefined
      ],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.streams[0].model).toBe("opus-4.5");
    expect(fleet.streams[1].model).toBe("qwen3.5:9b");
    expect(fleet.streams[2].model).toBeUndefined();
    expect(fleet.streams[3].model).toBeUndefined();
  });

  it("accepts depends_on as an alias and coerces a string recommended", () => {
    const raw = JSON.stringify({
      recommended: "2",
      director: { enabled: "true" },
      streams: [{ id: "b", repo: "o/r", depends_on: ["a"] }],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.recommended).toBe(2);
    expect(fleet.director.enabled).toBe(true);
    expect(fleet.streams[0].dependsOn).toEqual(["a"]);
  });

  it("round-trips fleet + stream integration strategy (#378)", () => {
    const raw = JSON.stringify({
      recommended: 2,
      strategy: "pr-ci",
      streams: [
        { id: "a", repo: "o/r", strategy: "manual" },
        { id: "b", repo: "o/r" },
      ],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.strategy).toBe("pr-ci");
    expect(fleet.streams[0].strategy).toBe("manual");
    expect(fleet.streams[1].strategy).toBeUndefined();
  });

  it("drops an invalid fleet/stream strategy to undefined (#378)", () => {
    const raw = JSON.stringify({ strategy: "bogus", streams: [{ id: "a", repo: "o/r", strategy: "nope" }] });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.strategy).toBeUndefined();
    expect(fleet.streams[0].strategy).toBeUndefined();
  });

  it("reads a stream's NESTED flow object (#297, canonical shape)", () => {
    const raw = JSON.stringify({
      streams: [
        { id: "a", repo: "o/r", flow: { autonomy: "checkpoint", push: "push-confirm", trigger: "per-stage", gate: "soft" } },
      ],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.streams[0].flow).toEqual({
      autonomy: "checkpoint", push: "push-confirm", trigger: "per-stage", gate: "soft",
    });
  });

  it("normalizes FLAT autonomy/push/trigger/gate to the same nested flow (#1804)", () => {
    const raw = JSON.stringify({
      streams: [
        { id: "a", repo: "o/r", autonomy: "checkpoint", push: "push-confirm", trigger: "per-stage", gate: "soft" },
      ],
    });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.streams[0].flow).toEqual({
      autonomy: "checkpoint", push: "push-confirm", trigger: "per-stage", gate: "soft",
    });
  });

  it("prefers a named nested flow over flat fields (#1804)", () => {
    const raw = JSON.stringify({
      streams: [
        { id: "a", repo: "o/r", autonomy: "continuous", flow: { autonomy: "confirm", push: "none" } },
      ],
    });
    const fleet = parseFleetFile(raw)!;
    // nested wins entirely; its unset fields fall back to DEFAULT_FLOW, NOT to the flat top-level values.
    expect(fleet.streams[0].flow).toEqual({
      autonomy: "confirm", push: "none", trigger: DEFAULT_FLOW.trigger, gate: DEFAULT_FLOW.gate,
    });
  });

  it("leaves flow undefined when a stream specifies neither nested nor flat flow (#1804 → DEFAULT_FLOW at launch)", () => {
    const raw = JSON.stringify({ streams: [{ id: "a", repo: "o/r" }] });
    const fleet = parseFleetFile(raw)!;
    expect(fleet.streams[0].flow).toBeUndefined();
  });

  it("returns null for blank or malformed input", () => {
    expect(parseFleetFile("")).toBeNull();
    expect(parseFleetFile("   ")).toBeNull();
    expect(parseFleetFile("{not json")).toBeNull();
    expect(parseFleetFile("[1,2,3]")).toBeNull();
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "@/store";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";

// The TRIAGED marker (#2541) — the durable drafted→triaged transition that gates the Glance network.
// markProjectTriaged is idempotent; both triageStartProject and fleetStartProject stamp it on launch.
describe("triagedProjects marker (#2541)", () => {
  beforeEach(() => useAppStore.setState({ triagedProjects: {}, tabs: [], localDraftProjects: {} }));

  it("markProjectTriaged stamps a key and is idempotent (keeps the first timestamp)", () => {
    useAppStore.getState().markProjectTriaged("proj-a");
    const first = useAppStore.getState().triagedProjects["proj-a"];
    expect(first).toBeGreaterThan(0);
    useAppStore.getState().markProjectTriaged("proj-a");
    expect(useAppStore.getState().triagedProjects["proj-a"]).toBe(first); // unchanged on re-mark
  });

  it("ignores an empty key", () => {
    useAppStore.getState().markProjectTriaged("");
    expect(useAppStore.getState().triagedProjects).toEqual({});
  });

  it("triageStartProject marks the project triaged", () => {
    useAppStore.getState().triageStartProject("Proj", ["own/web"], "proj-key");
    expect(useAppStore.getState().triagedProjects["proj-key"]).toBeGreaterThan(0);
  });

  it("fleetStartProject marks the project triaged", () => {
    const fleet: FleetPlan = {
      recommended: 1, reasoning: "",
      streams: [{ id: "s", name: "S", repo: "o/r", owns: [], issues: [], dependsOn: [] }],
      director: { enabled: false },
    } as never;
    useAppStore.getState().fleetStartProject("Proj", fleet, "fleet-key");
    expect(useAppStore.getState().triagedProjects["fleet-key"]).toBeGreaterThan(0);
  });
});

// EVERY FIELD `AgentStream` DECLARES MUST SURVIVE THE PARSER.
//
// THREE TIMES the same shape: a field declared on the type, written by `bsc plan fleet`, sitting in
// plan.db, and silently dropped by `parseFleetFile`.
//
//   model     (#173) — validated against MODEL_IDS and anything else discarded, throwing away every
//                      LOCAL model a director assigned. Its fix comment is still in the parser.
//   requires         — typed `string[]` on the feature side and coerced with `strArray`, dropping every
//                      attributed entry so the board showed an empty list.
//   feature          — `a-feature-owns-many-streams` added it to the interface, to Rust and to the CLI,
//                      and never revisited the decoder. All 89 studio-code streams arrived
//                      `feature: undefined`, which IS the plan as it looked before any feature was
//                      assigned. The maintainer reported "I'm still seeing the old plan" four times
//                      across two days, and every other gate was green throughout.
//
// A dropped field is invisible to typecheck (the property is optional), to lint, and to every unit test
// that builds its fixture in memory instead of round-tripping through the decoder. The only thing that
// sees it is a check reading the TYPE and the PARSER together.
//
// DERIVED, NOT HAND-LISTED — hand-checking is exactly what failed all three times.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { parseFleetFile } from "@/features/planner/fleet/planFleet";

/** The parser's source, from the seed — it is a record, not a file (docs/records.md). */
function planFleetSource(): string {
  const seed = JSON.parse(readFileSync("src-tauri/data/knowledge/algorithms.json", "utf8")) as {
    implementations: { id: string; code?: string }[];
  };
  const rec = seed.implementations.find((i) => i.id === "plan-fleet.ts");
  if (!rec?.code) throw new Error("plan-fleet.ts is not in the seed — this guard is looking at nothing");
  return rec.code;
}

/** The field names declared on an interface body. One level of indentation, so a nested literal's
 *  keys (which are deeper) are not mistaken for fields. */
function declaredFields(src: string, iface: string): string[] {
  const start = src.indexOf(`export interface ${iface} {`);
  if (start < 0) throw new Error(`${iface} not found`);
  const body = src.slice(start, src.indexOf("\n}", start));
  return [...body.matchAll(/\n {2}(\w+)\??:/g)].map((m) => m[1]);
}

describe("parseFleetFile carries every field AgentStream declares", () => {
  const src = planFleetSource();
  const fields = declaredFields(src, "AgentStream");
  /** The parser's stream construction — the object literal pushed into `streams`. */
  const at = src.indexOf("streams.push({");
  const construction = src.slice(at, src.indexOf("\n    });", at));

  it("found a real interface and a real construction", () => {
    // A scan that matched nothing would pass every assertion below for the wrong reason.
    expect(at, "streams.push({ not found — the guard is reading the wrong shape").toBeGreaterThan(-1);
    expect(fields.length).toBeGreaterThan(10);
    expect(fields).toContain("id");
    expect(construction.length).toBeGreaterThan(200);
  });

  it.each(fields)("`%s` appears in the stream the parser builds", (field) => {
    expect(
      new RegExp(`(^|[\\s{,])${field}\\s*[:,]`, "m").test(construction),
      `AgentStream declares \`${field}\` and parseFleetFile never sets it. A field the store holds and ` +
        `the decoder drops is invisible to typecheck, to lint and to every in-memory fixture — it ` +
        `surfaces as "the data I saved isn't there", days later.`,
    ).toBe(true);
  });

  it("round-trips `feature` through the decoder — the regression", () => {
    // The behaviour, not just the source: a blob with `feature` set must come back with it intact.
    const plan = parseFleetFile(
      JSON.stringify({
        streams: [
          { id: "glance", repo: "o/r", feature: "glance-cockpit" },
          { id: "bare", repo: "o/r" },
          { id: "blank", repo: "o/r", feature: "   " },
        ],
      }),
    );
    expect(plan?.streams.find((s) => s.id === "glance")?.feature).toBe("glance-cockpit");
    // Absent stays absent, and whitespace-only is NOT a feature — it would look decided and resolve to
    // nothing, which is the shape the CLI already refuses on the way in.
    expect(plan?.streams.find((s) => s.id === "bare")?.feature).toBeUndefined();
    expect(plan?.streams.find((s) => s.id === "blank")?.feature).toBeUndefined();
  });
});

