import { describe, it, expect } from "vitest";
import { resolveProfileSettings } from "@/shared/lib/security/profileEnforcement";
import { findProfile } from "@/shared/lib/security/agentProfiles";

const profile = (id: string) => {
  const p = findProfile(id);
  if (!p) throw new Error(`missing profile ${id}`);
  return p;
};

describe("resolveProfileSettings", () => {
  it("maps allow/deny tool tiers to tool rules (ask is left to prompt)", () => {
    const s = resolveProfileSettings(profile("pf_sandbox"));
    // read/grep/glob allow → allowed tools
    expect(s.allowToolRules).toEqual(expect.arrayContaining(["Read", "Grep", "Glob"]));
    // web/task deny → denied tools
    expect(s.denyToolRules).toEqual(expect.arrayContaining(["WebFetch", "WebSearch", "Task"]));
    // edit/write are "ask" → neither allowed nor denied (Claude prompts)
    expect(s.allowToolRules).not.toContain("Edit");
    expect(s.denyToolRules).not.toContain("Edit");
  });

  it("never blanket-denies Bash (would kill guaranteed gh/git)", () => {
    // pf_sandbox sets bash: "deny" — but Bash must not be denied wholesale.
    const s = resolveProfileSettings(profile("pf_sandbox"));
    expect(s.denyToolRules).not.toContain("Bash");
  });

  it("exposes the bash posture from the profile's bash tier (#1572)", () => {
    // The backend uses this to scale the auto-approve baseline (a bare `Bash` allow isn't
    // honored by Claude Code), rather than a deny rule.
    expect(resolveProfileSettings(profile("pf_auto")).bashPosture).toBe("allow");
    expect(resolveProfileSettings(profile("pf_review")).bashPosture).toBe("ask");
    expect(resolveProfileSettings(profile("pf_sandbox")).bashPosture).toBe("deny");
  });

  it("scopes file-write tools by path globs (deny wins)", () => {
    const s = resolveProfileSettings(profile("pf_sandbox")); // paths.deny: ["**/*"]
    // Path-scoped file rule is Edit(glob) ONLY (#3534) — Edit covers every file-editing tool.
    expect(s.denyToolRules).toContain("Edit(**/*)");
    expect(s.denyToolRules).not.toContain("Write(**/*)");
    expect(s.denyToolRules).not.toContain("MultiEdit(**/*)");
  });

  it("carries the command allowlist + per-glob allows for a trusted profile", () => {
    const s = resolveProfileSettings(profile("pf_auto"));
    expect(s.allowedCommands).toEqual(["cargo", "npm", "pnpm", "pytest", "make", "node", "docker", "gh", "aws"]);
    // whole-tool edit/write tiers (Edit/NotebookEdit/Write — no MultiEdit) + the path rule Edit(**/*).
    expect(s.allowToolRules).toEqual(
      expect.arrayContaining(["Edit", "NotebookEdit", "Write", "Edit(**/*)"]),
    );
    expect(s.allowToolRules).not.toContain("MultiEdit");
    expect(s.allowToolRules).not.toContain("Write(**/*)");
    // paths.deny → denied write globs, Edit(glob) only.
    expect(s.denyToolRules).toEqual(expect.arrayContaining(["Edit(**/.env)", "Edit(**/secrets/**)"]));
  });

  it("denies the edit tools when a profile sets edit/write to deny", () => {
    const s = resolveProfileSettings(profile("pf_review")); // edit:deny, write:deny, task:allow
    expect(s.denyToolRules).toEqual(expect.arrayContaining(["Edit", "NotebookEdit", "Write"]));
    expect(s.denyToolRules).not.toContain("MultiEdit");
    expect(s.allowToolRules).toContain("Task");
  });

  it("dedupes repeated rules", () => {
    const s = resolveProfileSettings(profile("pf_auto")); // paths.allow: ["**/*"]
    const editAll = s.allowToolRules.filter((r) => r === "Edit(**/*)");
    expect(editAll).toHaveLength(1);
  });
});

// The profile → session-settings bridge, captured from the LIVE TypeScript so the Rust port can be
// proved equal.
//
// This is the role-gate inversion one record over. `ensure_session_settings` already RECEIVES
// `bash_posture` and scales the entire auto-approve baseline by it (settings.rs:211 — an `allow` doer
// gets the read-only AND build command tiers, an `ask` coordinator gets read-only only, `deny` gets
// neither). Rust acts on that value at every launch and has no way to compute it: the breadth of a
// session's shell surface is decided in a renderer and the backend obeys.
//
// The subjects are EVERY PACKAGED ROLE under `src-tauri/data/roles/`, not invented inputs — these are
// the profiles that actually ship, so parity over them is parity over what users get. Synthetic cases
// follow for the three deliberate edges, which no packaged role happens to exercise and each of which
// is a real defect if the port smooths it.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/security/profileEnforcement.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { resolveProfileSettings } from "@/shared/lib/security/profileEnforcement";
// ALL_ROLES itself is not exported, and these two partition it exactly (APP_ROLES is the
// category === "application" half, PROFILES the rest) — so this is the whole packaged set without
// widening the module's public surface just to test it.
import { APP_ROLES, PROFILES } from "@/shared/lib/security/agentProfiles";
import type { AgentProfile, Tier, ToolKey } from "@/shared/lib/security/agentProfiles";

const ALL_PROFILE_ROLES: AgentProfile[] = [...APP_ROLES, ...PROFILES].sort((a, b) => a.id.localeCompare(b.id));

const FIXTURE = join(process.cwd(), "src/shared/lib/security/profileEnforcement.fixtures.json");

const TOOLS: ToolKey[] = ["read", "grep", "glob", "edit", "write", "bash", "web", "task"];

/** A minimal profile with every tool at `tier`, for the synthetic edge cases. */
const synth = (id: string, tier: Tier, over: Partial<AgentProfile> = {}): AgentProfile => ({
  id,
  name: id,
  color: "#000",
  category: "user",
  desc: "",
  mode: tier,
  commands: [],
  tools: Object.fromEntries(TOOLS.map((t) => [t, tier])) as Record<ToolKey, Tier>,
  paths: { allow: [], deny: [] },
  net: { allow: [] },
  ...over,
});

/** The three edges, each deliberate and each a defect if the port drops it. */
const SYNTHETIC: Array<[string, AgentProfile]> = [
  // A bare `Bash` deny would also kill the guaranteed gh/git, so shell control flows through the
  // command allowlist and the role gate instead — `bash: deny` must emit NO tool rule.
  ["every tool denied — bash must still not be blanket-denied", synth("edge-all-deny", "deny")],
  ["every tool allowed", synth("edge-all-allow", "allow")],
  // `ask` is left unlisted so Claude Code prompts, which is its default.
  ["every tool asked — ask emits no rule at all", synth("edge-all-ask", "ask")],
  [
    // Path rules are Edit(<glob>) ONLY (#3534). `Write(<glob>)` was never enforced — a silent no-op for
    // an allow and an UNENFORCED DENY for a deny, which is the dangerous half.
    "path globs become Edit(glob) rules, allow and deny",
    synth("edge-paths", "ask", { paths: { allow: ["src/**", "docs/**"], deny: ["src/secrets/**"] } }),
  ],
  [
    "commands are deduped and deniedCommands stays empty — the role gate supplies those",
    synth("edge-commands", "ask", { commands: ["git status", "npm test", "git status"] }),
  ],
  [
    // mode and net are advisory: every capability the gate can express is in tools + paths, and
    // host-level network limits are not expressible through settings.json at all.
    "mode and net are advisory and produce no rule",
    synth("edge-advisory", "allow", { mode: "deny", net: { allow: ["api.example.com"] } }),
  ],
  [
    // The TypeScript iterates `Object.entries(profile.tools)`, so its OUTPUT ORDER follows whatever
    // order the keys were written in. Every packaged role uses the same canonical order, so this never
    // shows — which is exactly why the case is here. A hand-edited or store-round-tripped profile can
    // have any order, and a fixture built only from the packaged set would have hidden it.
    "tool keys in a SHUFFLED order — output order follows the input",
    synth("edge-shuffled", "ask", {
      tools: { task: "allow", bash: "allow", read: "allow", web: "deny", glob: "deny", write: "allow", edit: "deny", grep: "allow" },
    }),
  ],
  [
    "a mixed profile — the shape a real custom profile has",
    synth("edge-mixed", "ask", {
      commands: ["cargo test"],
      tools: { read: "allow", grep: "allow", glob: "ask", edit: "allow", write: "deny", bash: "deny", web: "deny", task: "ask" },
      paths: { allow: ["crates/**"], deny: ["**/*.env"] },
    }),
  ],
];

describe("profileEnforcement fixtures", () => {
  it("captures resolveProfileSettings over every packaged role and every edge", () => {
    const packaged = ALL_PROFILE_ROLES.map((p) => [`packaged: ${p.id}`, p] as [string, AgentProfile]);
    const subjects = [...packaged, ...SYNTHETIC];
    const cases = subjects.map(([label, profile]) => ({
      label,
      profile,
      settings: resolveProfileSettings(profile),
    }));
    const next = {
      note: "GENERATED from src/shared/lib/security/profileEnforcement.ts — do not hand-edit; see the .gen.test.ts",
      cases,
    };

    if (process.env.UPDATE_FIXTURES) {
      writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    }
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("is non-vacuous: the packaged roles are actually present and actually produce rules", () => {
    expect(ALL_PROFILE_ROLES.length, "no packaged roles found — the glob resolved to nothing").toBeGreaterThanOrEqual(5);
    const withRules = ALL_PROFILE_ROLES.filter((p) => {
      const s = resolveProfileSettings(p);
      return s.allowToolRules.length + s.denyToolRules.length + s.allowedCommands.length > 0;
    });
    expect(withRules.length, "every packaged role resolved to nothing — the bridge is not being exercised").toBeGreaterThanOrEqual(3);
  });

  it("covers all three bash postures, so the value settings.rs scales its baseline by is pinned", () => {
    const postures = new Set([...ALL_PROFILE_ROLES, ...SYNTHETIC.map(([, p]) => p)].map((p) => resolveProfileSettings(p).bashPosture));
    expect([...postures].sort()).toEqual(["allow", "ask", "deny"]);
  });
});

implementations.code:
// Agents — profile → session-settings bridge (#255).
//
// Translates an editable `AgentProfile` (base mode + command allowlist + per-tool
// tri-states + path globs) into the exact inputs `ensure_session_settings` consumes —
// the SAME channel the role gate (#219) uses (allowedCommands / deniedCommands /
// allowToolRules / denyToolRules). Assigning a profile to a console pane therefore
// enforces it for real at session launch, not just in the UI. Pure + unit-testable.

import type { AgentProfile, ToolKey, Tier } from "@/shared/lib/security/agentProfiles";
import type { RoleCapability } from "@/shared/lib/session/sessionRoles";
import { editPathRule } from "@/shared/lib/session/sessionRoles";

/** The Claude Code tool name(s) each profile capability maps to (bare, whole-tool rules). `edit`
 *  covers the in-place edit tools; `write` is creation; `web` is both fetch + search. No `MultiEdit`
 *  — it was removed from Claude Code (#3534). */
const TOOL_NAMES: Record<ToolKey, string[]> = {
  read: ["Read"],
  grep: ["Grep"],
  glob: ["Glob"],
  edit: ["Edit", "NotebookEdit"],
  write: ["Write"],
  bash: ["Bash"],
  web: ["WebFetch", "WebSearch"],
  task: ["Task"],
};

/** Settings-rule inputs for `ensure_session_settings`, identical to the role gate's. */
export interface ProfileSessionSettings {
  /** Shell prefixes auto-approved (wrapped as `Bash(<cmd> *)` by the backend). */
  allowedCommands: string[];
  /** Command prefixes to deny (the role gate supplies git/gh denies; profiles add none). */
  deniedCommands: string[];
  /** Verbatim tool-permission allows (`Read`, `Edit(src/**)`, …). */
  allowToolRules: string[];
  /** Verbatim tool-permission denies (deny wins over allow). */
  denyToolRules: string[];
  /** The catch-all shell disposition (the profile's bash tier) the backend uses to scale how
   *  generous the auto-approve baseline is (#1572): `allow` doers get the read-only + build
   *  baselines, `ask` coordinators get read-only only, `deny` gets neither. */
  bashPosture: Tier;
}

const dedupe = (xs: string[]): string[] => [...new Set(xs)];

/**
 * Map a profile to session settings.
 *
 * - **commands** → `allowedCommands` (auto-approve those shell prefixes).
 * - **tools** tri-states → `allow` (tier `allow`) / `deny` (tier `deny`) tool rules;
 *   `ask` is left unlisted so Claude Code prompts (the default).
 * - **paths** → file-write tool rules scoped per glob (`Edit(<glob>)` etc.); deny wins.
 *
 * Two deliberate edges:
 * - **`bash` is never blanket-denied.** A bare `Bash` deny would also kill the
 *   guaranteed `gh`/`git`; shell control flows through the command allowlist + the
 *   role gate instead. (Bash `allow` is harmless — the backend already allows it.)
 * - **`mode`** (the base policy) and **`net`** are advisory here: every capability the
 *   gate can express is enumerated by the per-tool tiers + paths, and host-level
 *   network limits aren't expressible via `settings.json`.
 */
export function resolveProfileSettings(profile: AgentProfile): ProfileSessionSettings {
  const allowToolRules: string[] = [];
  const denyToolRules: string[] = [];

  for (const [key, tier] of Object.entries(profile.tools) as [ToolKey, Tier][]) {
    if (tier === "deny") {
      if (key === "bash") continue; // see docstring — never blanket-deny Bash
      denyToolRules.push(...TOOL_NAMES[key]);
    } else if (tier === "allow") {
      allowToolRules.push(...TOOL_NAMES[key]);
    }
  }

  // Path-scoped file rules are `Edit(<glob>)` ONLY (#3534): Claude Code matches file-permission rules
  // on the Edit tool alone, and that one rule covers every file-editing tool. `Write(<glob>)` etc. were
  // never enforced — a silent no-op for an allow, an unenforced deny for a deny.
  for (const g of profile.paths.allow) allowToolRules.push(editPathRule(g));
  for (const g of profile.paths.deny) denyToolRules.push(editPathRule(g));

  return {
    allowedCommands: dedupe(profile.commands),
    deniedCommands: [],
    allowToolRules: dedupe(allowToolRules),
    denyToolRules: dedupe(denyToolRules),
    bashPosture: profile.tools.bash,
  };
}


/**
 * The SAME resolution, read from a capability's own `permissions` instead of from a separate
 * `AgentProfile` (`rename-the-profile-to-permissions-on-the-persona`).
 *
 * ── WHY THIS EXISTS RATHER THAN A CHANGED SIGNATURE ─────────────────────────────────────────────
 * The two inputs describe the same six things under different names, because they were the same six
 * things stored twice:
 *
 *   AgentProfile.mode          ⇄  permissions.mode
 *   AgentProfile.tools         ⇄  permissions.tools
 *   AgentProfile.commands      ⇄  permissions.commands
 *   AgentProfile.paths.allow   ⇄  permissions.allowGlobs
 *   AgentProfile.paths.deny    ⇄  permissions.denyGlobs
 *   AgentProfile.net.allow     ⇄  permissions.netAllow
 *
 * VERIFIED, not assumed: for all 20 packaged personas each field equals what
 * `resolveProfileSettings(roleProfileId(role))` was already reading, so a pane resolving through this
 * function gets byte-identical settings to one resolving through the profile. That equality is the
 * whole licence for the swap, and `permissionSettingsMatchTheProfile` in the launch tests pins it —
 * if a persona and its role's profile ever diverge, the settings a session launches under change, and
 * a rename must never do that.
 *
 * It adapts rather than replaces because a pane may still be PINNED to a profile id it does not get
 * from a persona (a stream's own `profile`), and that assignment is a real capability, not a leftover.
 */
export function permissionSettings(cap: RoleCapability): ProfileSessionSettings | null {
  // No posture and no tools means this capability predates the fold — there is nothing to resolve, and
  // returning empty settings would read as "deny everything" rather than "nothing was declared".
  if (!cap.mode && !cap.tools) return null;
  return resolveProfileSettings({
    // The identity fields are not read by the resolution; they exist only on the older shape.
    id: `permissions:${cap.role}`, name: cap.role, color: "", category: "generated", desc: "",
    mode: cap.mode ?? "deny",
    commands: cap.commands ?? [],
    tools: {
      read: "deny", grep: "deny", glob: "deny", edit: "deny",
      write: "deny", bash: "deny", web: "deny", task: "deny",
      ...(cap.tools ?? {}),
    } as Record<ToolKey, Tier>,
    paths: { allow: cap.allowGlobs ?? [], deny: cap.denyGlobs ?? [] },
    net: { allow: cap.netAllow ?? [] },
  });
}

// Shared project-hub file capability — the persistence primitive a pipeline calls from
// inside its own save/confirm behavior (#…). Pipelines decide what/where/when to write;
// this is just the path-safe transport to `~/.base-studio-code/projects/<key>/`. Thin
// wrappers over the Rust `write_project_file` / `read_project_files` commands.

import { invoke } from "@tauri-apps/api/core";

/** Write one file under the project hub. `relpath` is resolved under the project dir;
 *  the Rust side rejects any path that would escape it. */
export function writeProjectFile(projectKey: string, relpath: string, contents: string): Promise<void> {
  return invoke("write_project_file", { projectKey, relpath, contents });
}

// The frontend ↔ project-links bridge (#2253 → #3786 Phase 2) — the Glance L0 contracts are a GLOBAL
// store reached through `bsc project link …` (the same CLI an agent uses to learn what its project
// consumes / contracts with). The Zustand `projectLinks` slice is a write-through cache: `loadProjectLinks`
// hydrates it on boot, and each add/remove pushes through here. Contracts are global (no project key), so
// every call passes null. #3786 threads the optional `target` endpoint (a service / mcp server) through
// load + add.
import { bsc, bscRun } from "@/shared/lib/core/bsc";
import type { ProjectLink, ContractTarget, ContractTargetType } from "@/features/glance/lib/projectLinks";
import type { AppType } from "@/features/planner";

const KINDS = ["api", "data", "events"];
const TARGET_TYPES: ContractTargetType[] = ["project", "service", "mcp"];

/** Coerce a raw `target` blob from the CLI into a {@link ContractTarget}, or `undefined` for a trivial
 *  project endpoint (no descriptors) — so a legacy project link stays byte-identical (no `target`) in the
 *  cache. Returns `undefined` on any malformed/unknown target so the link degrades to a project contract. */
function coerceTarget(raw: unknown): ContractTarget | undefined {
  if (typeof raw !== "object" || raw === null) return undefined;
  const r = raw as Record<string, unknown>;
  const type = TARGET_TYPES.includes(r.type as ContractTargetType) ? (r.type as ContractTargetType) : "project";
  const name = typeof r.name === "string" && r.name ? r.name : undefined;
  const url = typeof r.url === "string" && r.url ? r.url : undefined;
  const appType = typeof r.appType === "string" && r.appType ? (r.appType as AppType) : undefined;
  // A bare project endpoint carries no contract detail → leave `target` absent (byte-compat).
  if (type === "project" && !name && !url && !appType) return undefined;
  return { type, ...(name ? { name } : {}), ...(url ? { url } : {}), ...(appType ? { appType } : {}) };
}

/**
 * Load every contract via `bsc project link list --json`. Returns `null` when the bridge is unreachable
 * (no Tauri host / old binary) so the caller keeps its persisted cache rather than blanking it. NOT
 * `bscJson` — its degrade-to-`[]` would clobber the cache on a transient failure.
 */
export async function loadProjectLinks(): Promise<ProjectLink[] | null> {
  try {
    const out = await bsc(null, ["project", "link", "list", "--json"]);
    const rows = JSON.parse(out.trim() || "[]") as Record<string, unknown>[];
    return (rows ?? [])
      .filter(
        (l) =>
          typeof l.id === "string" && !!l.id && !!l.from && !!l.to && typeof l.kind === "string" && KINDS.includes(l.kind as string),
      )
      .map((l): ProjectLink => {
        const target = coerceTarget(l.target);
        return {
          id: l.id as string,
          from: l.from as string,
          to: l.to as string,
          kind: l.kind as ProjectLink["kind"],
          ...(target ? { target } : {}),
        };
      });
  } catch {
    return null;
  }
}

/** Write-through an add (`bsc project link add`), threading the optional `target` endpoint (#3786) as the
 *  `--target-type`/`--name`/`--url`/`--app-type` flags. Fire-and-forget; never throws (degrades to
 *  cache-only when the bridge/binary is absent). The store computes the id itself, so the printed id is
 *  unused. */
export async function pushProjectLink(from: string, to: string, kind: string, target?: ContractTarget): Promise<void> {
  const flags: string[] = [];
  if (target && target.type !== "project") flags.push("--target-type", target.type);
  if (target?.name) flags.push("--name", target.name);
  if (target?.url) flags.push("--url", target.url);
  if (target?.appType) flags.push("--app-type", target.appType);
  try { await bscRun(null, ["project", "link", "add", from, to, kind, ...flags]); } catch { /* bridge absent — cache-only */ }
}

/** Write-through a removal (`bsc project link remove <id>`). Never throws (see {@link pushProjectLink}). */
export async function dropProjectLink(id: string): Promise<void> {
  try { await bscRun(null, ["project", "link", "remove", id]); } catch { /* bridge absent — cache-only */ }
}

// Project relationships / inter-app contracts (#2253 → #3786 Phase 2) — a Glance L0 network edge:
// `from` (a project) depends on / consumes `to` over a contract of `kind` (Glance's api/data/events).
// #3786 Phase 2 generalizes the TARGET: `to` can be another project (the default), an external `service`,
// or an `mcp` server, described by an optional `target` descriptor. The editable source of truth for the
// project network's edges — a write-through cache over the global `bsc project link` store (the same CLI
// an agent uses to learn what its project consumes). Pure model.
import type { GEdgeKind } from "@/features/glance/lib/glanceGraph";
// Cross-feature TYPE only, via the barrel (#1309 boundary) — the endpoint's application architecture,
// the same `AppType` vocabulary a project is classified by. `import type` is erased at build (no cycle).
import type { AppType } from "@/features/planner";

/** What a contract's `to` endpoint IS (#3786 Phase 2): another `project` (the default), an external
 *  `service`, or an `mcp` server. */
export type ContractTargetType = "project" | "service" | "mcp";

/** The endpoint a contract points at (#3786 Phase 2). Present only for a NON-project contract (an external
 *  service / mcp server) — a plain project↔project link leaves `target` absent (byte-compatible with the
 *  pre-#3786 shape). `name`/`url`/`appType` are optional descriptors of the external endpoint. */
export interface ContractTarget {
  type: ContractTargetType;
  name?: string;
  url?: string;
  appType?: AppType;
}

export interface ProjectLink {
  id: string;
  from: string;
  to: string;
  kind: GEdgeKind;
  /** The target endpoint (#3786). ABSENT ⇒ a project↔project link (`{ type: "project" }`) — kept absent
   *  so a legacy project link's persisted/wire shape is byte-identical. Present for a `service` / `mcp`
   *  contract, carrying the endpoint descriptor Glance draws as an external contract node. */
  target?: ContractTarget;
}

/** Deterministic id for a link, so adding the same edge twice is idempotent. Target-agnostic (the id is
 *  the same shape whatever the target endpoint is), matching the Rust `link_id`. */
export const projectLinkId = (from: string, to: string, kind: GEdgeKind): string => `${from}>${to}:${kind}`;

/** True when a contract points at another PROJECT (the default) — i.e. it draws as a normal L0
 *  project→project edge, not an external band contract node. A missing/`project` target is a project
 *  contract. */
export const isProjectContract = (l: ProjectLink): boolean => !l.target || l.target.type === "project";

