import { describe, it, expect } from "vitest";
import type { AppStore } from "@/store/types";
import {
  PROJECT_SCOPED_MAPS,
  REPO_SCOPED_MAPS,
  deleteProjectScoped,
  rekeyProjectScoped,
  dropProjectScoped,
} from "@/store/slices/projectScopedMaps";

// Build a fake store where every registered map has an entry for two projects (A, B), and every
// repo-scoped map has one entry per project (`<key>::<repo>`). Non-registered fields are irrelevant.
function makeState(): AppStore {
  const s: Record<string, Record<string, unknown>> = {};
  for (const name of PROJECT_SCOPED_MAPS) {
    s[name as string] = { A: `A:${String(name)}`, B: `B:${String(name)}` };
  }
  for (const name of REPO_SCOPED_MAPS) {
    s[name as string] = { "A::repo": `A:${String(name)}`, "B::repo": `B:${String(name)}` };
  }
  return s as unknown as AppStore;
}

const asMap = (o: Partial<AppStore>, name: keyof AppStore) =>
  (o as unknown as Record<string, Record<string, unknown>>)[name as string];

describe("projectScopedMaps registry", () => {
  it("delete removes exactly project A's entries from the delete-op maps, keeping B", () => {
    const s = makeState();
    const out = deleteProjectScoped(s, new Set(["A"]));
    // Every map the helper returns must have dropped A and kept B.
    for (const name of Object.keys(out) as (keyof AppStore)[]) {
      const m = asMap(out, name);
      expect(m).toBeDefined();
      expect("A" in m || "A::repo" in m).toBe(false);
      expect("B" in m || "B::repo" in m).toBe(true);
    }
  });

  it("delete does not touch maps outside the delete op set (e.g. reposPublic / stagePreview)", () => {
    const s = makeState();
    const out = deleteProjectScoped(s, new Set(["A"]));
    // These are `clearPlan`-only maps — delete must never return them.
    for (const outside of ["reposPublic", "planInjectionAck", "stagePreview", "stageRuns"] as (keyof AppStore)[]) {
      expect(asMap(out, outside)).toBeUndefined();
    }
    // …and repoPublic is not a delete-op repo map either.
    expect(asMap(out, "repoPublic" as keyof AppStore)).toBeUndefined();
  });

  it("rekey moves A -> C (target-absent) for every rekey-op map, leaving B", () => {
    const s = makeState();
    const out = rekeyProjectScoped(s, "A", "C");
    for (const name of Object.keys(out) as (keyof AppStore)[]) {
      const m = asMap(out, name);
      if (REPO_SCOPED_MAPS.includes(name)) {
        expect("A::repo" in m).toBe(false);
        expect("C::repo" in m).toBe(true);
        expect("B::repo" in m).toBe(true);
      } else {
        expect("A" in m).toBe(false);
        expect("C" in m).toBe(true);
        expect("B" in m).toBe(true);
      }
    }
  });

  it("rekey is target-wins: an existing newKey entry is kept and the old dropped", () => {
    const s = makeState();
    // planStages is a rekey-op map; give it both A and B, move A -> B.
    const out = rekeyProjectScoped(s, "A", "B");
    const m = asMap(out, "planStages");
    expect("A" in m).toBe(false);
    // B is preserved as its own value (not overwritten by A's).
    expect(m.B).toBe("B:planStages");
  });

  it("dropProjectScoped(clearPlan) drops the key from clearPlan maps but not delete-only maps", () => {
    const s = makeState();
    const out = dropProjectScoped(s, "clearPlan", "A");
    // A plan map cleared…
    expect(asMap(out, "planStages")).toBeDefined();
    expect("A" in asMap(out, "planStages")).toBe(false);
    // reposPublic is a clearPlan map…
    expect("A" in asMap(out, "reposPublic")).toBe(false);
    // …but autoTriage (delete/rekey only) must NOT be returned by clearPlan.
    expect(asMap(out, "autoTriage" as keyof AppStore)).toBeUndefined();
    // …nor a rekey-only map.
    expect(asMap(out, "planFleetTopology" as keyof AppStore)).toBeUndefined();
  });

  it("dropProjectScoped(clearPlan) drops repoPublic entries for the key only", () => {
    const s = makeState();
    const out = dropProjectScoped(s, "clearPlan", "A");
    const m = asMap(out, "repoPublic");
    expect("A::repo" in m).toBe(false);
    expect("B::repo" in m).toBe(true);
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  findProjectByTitle,
  ensureGithubProject,
  canLaunchTriage,
  triageLockReason,
  publishBlockReason,
  type GithubProjectRef,
  type Gql,
} from "@/shared/lib/github/projectSync";

const board = (id: string, number: number, title: string): GithubProjectRef =>
  ({ id, number, title, url: `https://github.com/users/o/projects/${number}` });

describe("findProjectByTitle (#444 dedupe guard)", () => {
  const boards = [board("P1", 1, "Studio Code"), board("P2", 2, "  Other  ")];
  it("matches case/whitespace-insensitively", () => {
    expect(findProjectByTitle(boards, "studio code")?.id).toBe("P1");
    expect(findProjectByTitle(boards, " other ")?.id).toBe("P2");
  });
  it("returns null when no board matches", () => {
    expect(findProjectByTitle(boards, "nope")).toBeNull();
  });
});

describe("ensureGithubProject (#444 adopt-or-create)", () => {
  it("returns linked without any GraphQL when activeProjectId is set", async () => {
    const gql = vi.fn();
    const res = await ensureGithubProject(gql as unknown as Gql, {
      activeProjectId: "PVT_existing", ownerLogin: "o", title: "T",
    });
    expect(res).toEqual({ action: "linked", id: "PVT_existing" });
    expect(gql).not.toHaveBeenCalled(); // already linked — no round-trip
  });

  it("adopts an existing same-title board instead of creating a duplicate", async () => {
    const gql = vi.fn().mockResolvedValueOnce({
      repositoryOwner: { id: "OWNER", projectsV2: { nodes: [board("PVT_dup", 7, "My Project")] } },
    });
    const res = await ensureGithubProject(gql as unknown as Gql, {
      activeProjectId: "", ownerLogin: "o", title: "my project", // case-insensitive match
    });
    expect(res).toEqual({ action: "adopted", id: "PVT_dup", number: 7, url: board("PVT_dup", 7, "x").url });
    expect(gql).toHaveBeenCalledTimes(1); // owner lookup only, NO create mutation
  });

  it("creates a new board when no same-title board exists", async () => {
    const gql = vi.fn()
      .mockResolvedValueOnce({ repositoryOwner: { id: "OWNER", projectsV2: { nodes: [board("PVT_other", 1, "Unrelated")] } } })
      .mockResolvedValueOnce({ createProjectV2: { projectV2: { id: "PVT_new", number: 9, url: "u" } } });
    const res = await ensureGithubProject(gql as unknown as Gql, {
      activeProjectId: "", ownerLogin: "o", title: "Fresh",
    });
    expect(res).toEqual({ action: "created", id: "PVT_new", number: 9, url: "u" });
    expect(gql).toHaveBeenCalledTimes(2); // lookup + create
  });

  it("throws when the owner cannot be resolved", async () => {
    const gql = vi.fn().mockResolvedValueOnce({ repositoryOwner: null });
    await expect(ensureGithubProject(gql as unknown as Gql, {
      activeProjectId: "", ownerLogin: "ghost", title: "T",
    })).rejects.toThrow(/could not resolve owner/);
  });

  it("throws when creation returns nothing", async () => {
    const gql = vi.fn()
      .mockResolvedValueOnce({ repositoryOwner: { id: "OWNER", projectsV2: { nodes: [] } } })
      .mockResolvedValueOnce({ createProjectV2: { projectV2: null } });
    await expect(ensureGithubProject(gql as unknown as Gql, {
      activeProjectId: "", ownerLogin: "o", title: "T",
    })).rejects.toThrow(/project not created/);
  });
});

describe("canLaunchTriage / triageLockReason (#444/#551 triage gate)", () => {
  const ok = { published: true, hasRepos: true, hasFleet: true, busy: false, planReady: true };
  it("allows launch only when plan ready + published + repos + fleet + not busy", () => {
    expect(canLaunchTriage(ok)).toBe(true);
    expect(triageLockReason(ok)).toBeNull();
  });
  it("locks until the plan is complete (#551)", () => {
    expect(canLaunchTriage({ ...ok, planReady: false })).toBe(false);
    expect(triageLockReason({ ...ok, planReady: false })).toMatch(/plan/i);
  });
  it("locks until the project is published", () => {
    expect(canLaunchTriage({ ...ok, published: false })).toBe(false);
    expect(triageLockReason({ ...ok, published: false })).toMatch(/Publish/);
  });
  it("has NO GitHub dependency — a locally-committed project launches offline (#3281 local-first)", () => {
    // `published` is `!!activeProjectId`, which #3280's commitLocal flips with the LOCAL project key —
    // no GitHub token, board, or connection anywhere in this gate. So the same `ok` inputs a local
    // commit produces launch the fleet. This is the evidence the offline fleet path is unblocked.
    expect(canLaunchTriage(ok)).toBe(true);
    expect(triageLockReason(ok)).toBeNull();
  });
  it("locks without repos / without a fleet / while busy, with a reason each", () => {
    expect(triageLockReason({ ...ok, hasRepos: false })).toMatch(/repository/i);
    expect(triageLockReason({ ...ok, hasFleet: false })).toMatch(/fleet/i);
    expect(triageLockReason({ ...ok, busy: true })).toBe("starting…");
    expect(canLaunchTriage({ ...ok, busy: true })).toBe(false);
  });
  it("busy takes precedence in the reason", () => {
    expect(triageLockReason({ published: false, hasRepos: false, hasFleet: false, busy: true, planReady: false })).toBe("starting…");
  });
  it("planReady lock precedes publish lock in the reason", () => {
    expect(triageLockReason({ ...ok, planReady: false, published: false })).toMatch(/plan/i);
  });
});

describe("publishBlockReason (#969 — no silent publish no-op)", () => {
  it("is null when a token + at least one repo are present (publish can proceed)", () => {
    expect(publishBlockReason({ hasToken: true, repoCount: 1 })).toBeNull();
  });
  it("blocks (with a reason) when no GitHub token is connected", () => {
    expect(publishBlockReason({ hasToken: false, repoCount: 1 })).toMatch(/token/i);
  });
  it("blocks (with a reason) when no repository is linked — the Repos-less blueprint case", () => {
    expect(publishBlockReason({ hasToken: true, repoCount: 0 })).toMatch(/repository/i);
  });
});

// The board ADOPT-OR-CREATE decision, captured from the live TypeScript so Rust can be proved to
// match it.
//
// ## Why this one matters more than a tidy-up
//
// `crates/bsc-publish::ensure_project_board` resolves the board TWO ways — a recorded id, else create
// — and never looks for an existing same-title board. That is the bug #444 fixed on the frontend path:
// "creation used to fire blindly and mint a *second* board on every re-sync of a same-titled project."
// So the two publish paths disagree today, and this fixture is what lets the correct rule move to the
// side that publishes.
//
// The corpus is deliberately heavy on the TITLE MATCHER, because that is where a port drifts: the
// shared matcher (#380) trims and lowercases, treats a BLANK title as matching nothing, and takes the
// FIRST match. Each of those is a separate case here; a corpus of ordinary distinct titles passes a
// port that gets any of them wrong.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/github/projectSync.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { findProjectByTitle, ensureGithubProject } from "@/shared/lib/github/projectSync";

const FIXTURE = join(process.cwd(), "src/shared/lib/github/projectSync.fixtures.json");

type Board = { id: string; number: number; url: string; title: string };
const B = (id: string, title: string, number = 1): Board => ({ id, number, url: `https://x/${id}`, title });

const BOARDS: { label: string; boards: Board[]; title: string }[] = [
  { label: "no boards", boards: [], title: "Studio Code" },
  { label: "exact match", boards: [B("p1", "Studio Code")], title: "Studio Code" },
  { label: "case-insensitive", boards: [B("p1", "STUDIO code")], title: "studio CODE" },
  { label: "surrounding whitespace on both sides", boards: [B("p1", "  Studio Code  ")], title: "\tStudio Code\n" },
  // INNER whitespace is NOT normalised — only the ends are trimmed.
  { label: "inner whitespace is not collapsed", boards: [B("p1", "Studio  Code")], title: "Studio Code" },
  { label: "no match", boards: [B("p1", "Other")], title: "Studio Code" },
  // FIRST match wins, and the corpus must contain two matches to prove it.
  { label: "two matches — the first wins", boards: [B("p1", "Studio Code"), B("p2", "studio code")], title: "Studio Code" },
  // A BLANK target matches NOTHING, even against a blank-titled board — a sentinel, not a normal value.
  { label: "blank title matches nothing", boards: [B("p1", ""), B("p2", "Studio Code")], title: "" },
  { label: "whitespace-only title matches nothing", boards: [B("p1", "   ")], title: "   " },
];

/** A scripted GraphQL executor: the decision is unit-testable precisely because it is injected. */
function gqlFor(owner: { id?: string; boards?: Board[] } | null, created?: Board | null) {
  return async (query: string) => {
    if (query.includes("createProjectV2")) {
      return created ? { createProjectV2: { projectV2: { id: created.id, number: created.number, url: created.url } } } : {};
    }
    return owner ? { repositoryOwner: { id: owner.id, projectsV2: { nodes: owner.boards ?? [] } } } : {};
  };
}

const ENSURE: { label: string; activeProjectId: string | null; owner: { id?: string; boards?: Board[] } | null; created?: Board | null; title: string }[] = [
  { label: "already linked short-circuits before any query", activeProjectId: "existing-id", owner: null, title: "Studio Code" },
  { label: "adopts a same-title board", activeProjectId: null, owner: { id: "o1", boards: [B("p9", "Studio Code", 7)] }, title: "Studio Code" },
  { label: "adopts case-insensitively", activeProjectId: null, owner: { id: "o1", boards: [B("p9", "studio CODE", 7)] }, title: "Studio Code" },
  { label: "creates when the owner has no boards", activeProjectId: null, owner: { id: "o1", boards: [] }, created: B("new1", "Studio Code", 3), title: "Studio Code" },
  { label: "creates when no title matches", activeProjectId: null, owner: { id: "o1", boards: [B("p9", "Other", 7)] }, created: B("new2", "Studio Code", 4), title: "Studio Code" },
  // An EMPTY activeProjectId is falsy, so it is NOT a linked board — the sentinel a port reads wrongly.
  { label: "an empty linked id is not linked", activeProjectId: "", owner: { id: "o1", boards: [B("p9", "Studio Code", 7)] }, title: "Studio Code" },
];

const THROWS: { label: string; owner: { id?: string; boards?: Board[] } | null; created?: Board | null }[] = [
  { label: "unresolvable owner", owner: { boards: [] } },
  { label: "creation returns nothing", owner: { id: "o1", boards: [] }, created: null },
];

async function build() {
  return {
    note: "GENERATED from the live TypeScript — see projectSync.fixtures.gen.test.ts",
    findByTitle: BOARDS.map(({ label, boards, title }) => ({
      label,
      boards,
      title,
      // WHOLE BOARD, not just its id — a matcher that finds the right one and returns the wrong
      // fields passes an id-only comparison.
      found: findProjectByTitle(boards, title) ?? null,
    })),
    ensure: await Promise.all(
      ENSURE.map(async ({ label, activeProjectId, owner, created, title }) => ({
        label,
        activeProjectId,
        // THE INPUTS, recorded rather than left to be inferred from the result. Reconstructing the
        // owner's boards from the expected outcome is circular — it makes the case-insensitive case
        // assert nothing about case, because the reconstruction uses the target title.
        title,
        ownerBoards: owner?.boards ?? null,
        result: await ensureGithubProject(gqlFor(owner ?? null, created ?? null), {
          activeProjectId,
          ownerLogin: "acme",
          title,
        }),
      })),
    ),
    throws: await Promise.all(
      THROWS.map(async ({ label, owner, created }) => {
        let message: string | null = null;
        try {
          await ensureGithubProject(gqlFor(owner, created ?? null), { activeProjectId: null, ownerLogin: "acme", title: "Studio Code" });
        } catch (e) {
          message = (e as Error).message;
        }
        return { label, message };
      }),
    ),
  };
}

describe("the board adopt-or-create decision is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", async () => {
    const text = JSON.stringify(await build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  /** All three actions must occur, or a port can hardcode one. */
  it("exercises linked, adopted and created", async () => {
    const actions = new Set((await build()).ensure.map((e) => e.result.action));
    expect([...actions].sort()).toEqual(["adopted", "created", "linked"]);
  });

  /** The three matcher rules a port drifts on, each shown to change the answer. */
  it("pins trimming, case-folding, first-match and the blank sentinel", async () => {
    const f = (await build()).findByTitle;
    const by = (l: string) => f.find((x) => x.label === l)!;
    expect(by("case-insensitive").found?.id).toBe("p1");
    expect(by("surrounding whitespace on both sides").found?.id).toBe("p1");
    expect(by("inner whitespace is not collapsed").found).toBeNull();
    expect(by("two matches — the first wins").found?.id).toBe("p1");
    expect(by("blank title matches nothing").found).toBeNull();
    expect(by("whitespace-only title matches nothing").found).toBeNull();
  });

  /** An empty linked id is falsy — it must NOT short-circuit as "linked". */
  it("treats an empty linked id as not linked", async () => {
    const e = (await build()).ensure.find((x) => x.label === "an empty linked id is not linked")!;
    expect(e.result.action).toBe("adopted");
  });

  /** Both failure paths throw, and the messages are part of the contract. */
  it("records the two throws", async () => {
    const t = (await build()).throws;
    expect(t.every((x) => x.message)).toBe(true);
  });
});

