import { bscJson } from "@/shared/lib/core/bsc";

/**
 * Everything a WORKER stream's pane is wired with that is derived from the stream row itself.
 *
 * ONE COPY, ON PURPOSE. `fleetStartProject` computes this at launch, and the wake path
 * (`the-director-cannot-start-a-stream-that-never-launched`) computes it again when it adopts a stream
 * plan.db names but no session ever ran. A second copy is the drifting-launch-path this codebase has
 * paid for before — the whole reason `fleetStartBridge` builds a FleetPlan and calls the real
 * `fleetStartProject` rather than placing panes itself. So a WOKEN pane is wired exactly like a
 * LAUNCHED one, by construction rather than by two blocks that agree today.
 *
 * The director is deliberately NOT expressible here: its role, profile and cwd come from the project,
 * not from a stream row, and `sess === null` is how the launch says so.
 */
export interface StreamPaneWiring {
  /** #2094: a persona stream launches AS its persona's role; no persona ⇒ the historical worker. */
  role: SessionRole;
  /** The stream's own pin wins, then the blueprint's fleetPolicy default, then the role's profile. */
  profile: string;
  /** Undefined ⇒ the launch path applies DEFAULT_FLOW downstream. */
  flow?: AgentFlow;
  /** Undefined ⇒ the pane falls back to the global `defaultModel` at mount.
   *
   *  This is where the model precedence chain is RESOLVED — the stream's own model first, then the
   *  persona's default. A {@link SessionModel} rather than a tier, because the nearest level (the
   *  stream, set by the director with `bsc plan fleet model`) may name a local model that no tier
   *  catalog contains. The PERSONA fallback below stays tier-validated: a persona's model is picked
   *  from the catalog, so a value outside it there means bad data, not a deliberate local choice. */
  model?: SessionModel;
  /** The harness THIS stream must launch on, derived from {@link model} — set only when the resolved
   *  model is not a Claude tier. `bsc plan fleet model <id> qwen3.5:9b` stores that string verbatim on
   *  the stream (`bsc plan fleet model`'s own note: "a local harness uses it verbatim"), but nothing
   *  downstream of the stream row ever chose `bsc-agent` for it — the pane's harness came ONLY from the
   *  fleet-wide `effectiveHarness(s.llmProvider, s.fleetHarness)` toggle, so a per-stream local model
   *  launched `claude` with no `--model` flag and silently ran Claude's own default (request #173).
   *  Undefined ⇒ the caller falls back to the fleet-wide harness, unchanged. */
  provider?: "bsc-agent";
  /** The write boundary, and ONLY for a code-writing role — a read-only persona stream must not get a
   *  write carve-out from its `owns`, or the read-only floor leaks. */
  roleGlobs?: string[];
  /** Absent for a repo-less stream (a team-derived hub role-actor, #3103). */
  repo?: string;
  /** What the coordinator resolves a pane's repo/branch through. */
  paneStream: { repo: string; branch: string };
}

/**
 * The harness a pane actually launches on, resolved nearest-first:
 *
 *   1. its STORED provider — an explicit choice (the model picker, or a seat that derived one) wins
 *   2. its STREAM's own model — a non-Claude-tier model can only be a local one, so `bsc-agent`
 *   3. the fleet-wide harness
 *   4. `claude`
 *
 * Step 2 is the one that was missing, and its absence is why `bsc plan fleet model <s> qwen3.5:9b`
 * did nothing. `paneProviders` is written ONCE, when a pane is seated, and persisted (#175) — so a
 * pane seated before its model was configured has NO entry, and a bare `?? "claude"` fallback beat a
 * roster row that named a local model. Measured on the live store for `studio-code:blueprint`:
 * `fleetPaneStreams` held `model: "qwen3.5:9b"` and `paneModels` agreed, while `paneProviders` was
 * empty — so the pane launched Claude every time, and re-running the launch never changed it.
 *
 * Deriving here rather than backfilling the map means every pane seated before this self-heals on
 * its next launch, with no migration and nothing to remember.
 */
export function paneHarness(s: AppStore, paneId: string): "claude" | "bsc-agent" {
  const stored = s.paneProviders[paneId];
  if (stored === "claude" || stored === "bsc-agent") return stored;
  const model = s.fleetPaneStreams[paneId]?.model;
  if (model && !(MODEL_IDS as readonly string[]).includes(model)) return "bsc-agent";
  return effectiveHarness(s.llmProvider, s.fleetHarness ?? "claude");
}


export function streamPaneWiring(
  sess: AgentStream,
  persona?: { role?: SessionRole; model?: string },
  fleetPolicy?: { profile?: string; flow?: AgentFlow; model?: string },
): StreamPaneWiring {
  const role: SessionRole = persona?.role ?? "worker";
  const flow = resolveStreamFlow(sess.flow, fleetPolicy?.flow);
  // THE PERSONA'S MODEL PASSES THROUGH WHOLE, exactly as the stream's own does.
  //
  // This used to adopt `persona.model` ONLY if it was a Claude tier, which was a harmless no-op while
  // `bsc persona model` could not store anything else — and became a silent bug the moment it could
  // (`a-persona-cannot-carry-a-local-model`). A persona naming `qwen3.5:35b-a3b` had its model dropped
  // here, so no provider was derived below and the session launched on Claude Code: the identity said
  // local, the launch said otherwise, and nothing reported the disagreement.
  //
  // THE PROJECT'S OWN CHOICE SITS BETWEEN THEM (`discovery-chooses-the-model`). `fleetPolicy.model`
  // is what the architect settled at Discovery and recorded on the classification, and it ranks above
  // the persona's default because a persona is a global library identity placed in every project,
  // while this decision was taken about THIS one. It ranks below `sess.model`, which is already the
  // nearer pair — a stream's own model, or the team placement `teamRoleStreams` carried onto it.
  //
  // Absent at every level means no `--model` at all, which is the harness deciding — never this
  // function inventing a tier.
  const model = sess.model ?? fleetPolicy?.model ?? persona?.model;
  const provider = providerForModel(model);
  return {
    role,
    profile: resolveStreamProfile(sess.profile, fleetPolicy?.profile, roleProfileId(role)),
    ...(flow ? { flow } : {}),
    ...(model ? { model } : {}),
    ...(provider ? { provider } : {}),
    ...(sess.owns.length && roleCapability(role).code === "write"
      ? { roleGlobs: sess.owns.map((g) => (g.endsWith("/") ? g + "**" : g)) }
      : {}),
    ...(sess.repo ? { repo: sess.repo } : {}),
    paneStream: { repo: sess.repo, branch: worktreeSlug(sess.id) },
  };
}

