// The console PROVIDER surface — public API only. The built-in set is seeded by `./registry`, the
// module that owns the map, so this barrel has NO import-time side effect and can be a record
// (providers-register-in-the-registry-that-owns-them).
export type { ConsoleProvider, ProviderLaunchConfig } from "@/app/console/lib/providers/types";
export { registerProvider, getProvider, listProviders } from "@/app/console/lib/providers/registry";

import type { ConsoleProvider } from "@/app/console/lib/providers/types";
import { claudeProvider } from "@/app/console/lib/providers/providers/claude";
import { geminiProvider } from "@/app/console/lib/providers/providers/gemini";
import { codexProvider } from "@/app/console/lib/providers/providers/codex";
import { aiderProvider } from "@/app/console/lib/providers/providers/aider";
import { ollamaProvider } from "@/app/console/lib/providers/providers/ollama";
import { amazonQProvider } from "@/app/console/lib/providers/providers/amazonq";
import { bscAgentProvider } from "@/app/console/lib/providers/providers/bscAgent";

const REGISTRY = new Map<string, ConsoleProvider>();

export function registerProvider(p: ConsoleProvider): void {
  REGISTRY.set(p.id, p);
}

export function getProvider(id: string): ConsoleProvider | undefined {
  return REGISTRY.get(id);
}

export function listProviders(): ConsoleProvider[] {
  return [...REGISTRY.values()];
}

// The built-in provider set, seeded HERE — in the module that owns the map — rather than in the
// barrel (providers-register-in-the-registry-that-owns-them).
//
// Two things this buys. Anyone reaching `getProvider` necessarily loads THIS module, so the built-ins
// are guaranteed present; when the barrel seeded them, a consumer importing `./registry` directly got
// an empty map, and the guarantee rested on which path you happened to take. And the barrel becomes
// re-exports only, which is what lets it be a record rather than a file that must RUN to be correct.
//
// This module cannot be a record either way: it holds REGISTRY, a live map. Seeding it here therefore
// costs nothing that was not already spent.
registerProvider(claudeProvider);
registerProvider(geminiProvider);
registerProvider(codexProvider);
registerProvider(aiderProvider);
registerProvider(ollamaProvider);
registerProvider(amazonQProvider);
registerProvider(bscAgentProvider);

// A published project's lifecycle, derived from GitHub state: open ⇒ active, closed ⇒ shipped.
// (Local, not-yet-on-GitHub work lives in the separate Drafts section.)
export type ProjStatus = "active" | "shipped";
export const STATUS_META: Record<ProjStatus, { label: string; cls: string; dot: string }> = {
  active:   { label: "active",   cls: "green", dot: "var(--success)" },
  shipped:  { label: "shipped",  cls: "",      dot: "var(--fg-dim)" },
};
export function projStatus(p: { closed: boolean }): ProjStatus {
  return p.closed ? "shipped" : "active";
}

interface GhProjectItem { content: { __typename?: string; state?: string } | null }
export interface GhProject {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  items: { totalCount: number; nodes: GhProjectItem[] };
  repositories: { nodes: Array<{ nameWithOwner: string }> };
}

// Open count + closed fraction from the fetched item states (capped at 100 items;
// totalCount is the true item count, used for the headline number).
export function projectProgress(p: GhProject): { open: number; pct: number } {
  let open = 0, closed = 0;
  for (const n of p.items?.nodes ?? []) {
    const s = n.content?.state;
    if (s === "OPEN") open++;
    else if (s === "CLOSED" || s === "MERGED") closed++;
  }
  const total = open + closed;
  return { open, pct: total ? closed / total : 0 };
}

export const PROJECTS_QUERY = `{
  viewer {
    projectsV2(first: 20) {
      nodes {
        id number title shortDescription url closed updatedAt
        items(first: 100) {
          totalCount
          nodes { content { __typename ... on Issue { state } ... on PullRequest { state } } }
        }
        repositories(first: 20) { nodes { nameWithOwner } }
      }
    }
  }
}`;

export const DELETE_MUTATION = `
  mutation DeleteProject($projectId: ID!) {
    deleteProjectV2(input: { projectId: $projectId }) {
      projectV2 { id }
    }
  }
`;

/// Quick sort — partition around the first element, recurse each side.
pub fn quick_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    if xs.len() <= 1 {
        return xs.to_vec();
    }
    let pivot = xs[0].clone();
    let left: Vec<T> = xs[1..].iter().filter(|x| **x < pivot).cloned().collect();
    let right: Vec<T> = xs[1..].iter().filter(|x| **x >= pivot).cloned().collect();
    let mut out = quick_sort(&left);
    out.push(pivot);
    out.extend(quick_sort(&right));
    out
}

