import { describe, it, expect } from "vitest";
import { REACT_UI_COMPONENTS, REACT_UI_KIT } from "@/features/designs/lib/reactUiKit";
import { SEED_COMPONENTS, SEED_KITS, BASE_STUDIO_CODE_KIT_ID } from "@/features/designs/lib/seed";
import { componentRules } from "@/features/designs/lib/rules";
import { UI_KIT } from "@/shared/ui/manifest";

const byName = (name: string) => REACT_UI_COMPONENTS.find((c) => c.name === name);

describe("react-ui kit generated from the manifest (#2305)", () => {
  it("covers exactly the registered primitives — no drift, no missing, no extra", () => {
    const kit = new Set(REACT_UI_COMPONENTS.map((c) => c.name));
    const manifest = new Set(UI_KIT.map((p) => p.name));
    expect(kit).toEqual(manifest);
    expect(REACT_UI_COMPONENTS.length).toBe(UI_KIT.length);
    // Every generated record belongs to the react-ui kit, is a built-in, and has a lowercase id.
    for (const c of REACT_UI_COMPONENTS) {
      expect(c.kitId).toBe(REACT_UI_KIT.id);
      expect(c.builtin).toBe(true);
      expect(c.id).toBe(c.name.toLowerCase());
    }
  });

  it("layers the authored guidance overlay onto the generated records", () => {
    const button = byName("Button")!;
    expect(button.wraps).toBe("button");            // → derives the anti-duplication lint rule
    expect(button.whenUse.length).toBeGreaterThan(0);
    expect(button.variants).toContain("primary");
    expect(button.srcText).toContain("function Button");
    expect(byName("Chip")!.composes).toContain("StatusDot");
    expect(byName("SegmentedControl")!.composes).toContain("Button");
  });

  it("maps the manifest group to a role (overlay wins)", () => {
    expect(byName("Box")!.role).toBe("layout");         // layout group — a true positioner
    expect(byName("Button")!.role).toBe("primitive");   // controls group
    expect(byName("Card")!.role).toBe("composite");     // overlay override (#2970: a chrome container, not a positioner)
    expect(byName("SegmentedControl")!.role).toBe("composite"); // overlay override
  });

  it("records `loading` as a variant wherever the manifest registers a loading prop (#2302)", () => {
    // Card/Chip/Text/TextField/FillBar/Code declare a `loading` prop in the manifest.
    for (const n of ["Card", "Chip", "Text", "TextField", "FillBar", "Code"]) {
      expect(byName(n)!.variants, `${n} should record a loading variant`).toContain("loading");
    }
    // A control without a loading prop does not fabricate one.
    expect(byName("Checkbox")!.variants).not.toContain("loading");
  });

  it("carries the prop schema + a derived source path from the manifest", () => {
    const button = byName("Button")!;
    expect(button.src).toBe("shared/ui/controls/Button.tsx");
    expect(button.props.find((p) => p.name === "variant")?.type).toContain('"primary"');
    // A component without an authored srcText gets a generated usage stub.
    expect(byName("Box")!.srcText).toContain('import { Box } from "@/shared/ui/layout/Box"');
  });

  it("authors when-to-use / when-not guidance for EVERY primitive incl. charts (#2305)", () => {
    for (const c of REACT_UI_COMPONENTS) {
      expect(c.whenUse.length, `${c.name} missing whenUse guidance`).toBeGreaterThan(0);
      expect(c.whenNot.length, `${c.name} missing whenNot guidance`).toBeGreaterThan(0);
    }
  });

  it("derives an anti-duplication lint rule from each primitive that wraps a raw element", () => {
    // The kit dogfoods its own no-raw-element rule: Box→div, Text→span, Button→button, etc.
    const wrapsRule = (name: string, target: string) => {
      const rules = componentRules(byName(name)!);
      const r = rules.find((x) => x.kind === "forbid-element" && x.target === target);
      expect(r, `${name} should derive a forbid-<${target}> rule`).toBeTruthy();
      expect(r!.use).toBe(name);
    };
    wrapsRule("Box", "div");
    wrapsRule("Text", "span");
    wrapsRule("Button", "button");
    wrapsRule("TextField", "input");
    wrapsRule("SelectField", "select");
  });

  it("records real composition edges from the overlay", () => {
    expect(byName("Dialog")!.composes).toEqual(expect.arrayContaining(["ModalScrim", "Card"]));
    expect(byName("ConfirmButton")!.composes).toContain("Button");
    expect(byName("StatCard")!.composes).toEqual(expect.arrayContaining(["Card", "StatTile"]));
  });

  it("stamps the data-shape axis honestly — exact sets, audited components only (#2475)", () => {
    // The ideal-rendering index the planner queries via `bsc ui shapes` / `bsc ui list --shape`.
    expect(byName("MasterDetail")!.shapes).toEqual(["list"]);     // rail = select-a-row list → detail
    expect(byName("GraphCanvas")!.shapes).toEqual(["graph"]);     // node/edge pan-zoom world
    expect(byName("DataTableRow")!.shapes).toEqual(["table"]);    // aligned fixed-column records
    expect(byName("CardListRow")!.shapes).toEqual(["list"]);      // the card-list row archetype
    expect(byName("ActivityFeed")!.shapes).toEqual(["list"]);     // striped feed of homogeneous rows
    expect(byName("KeyValueList")!.shapes).toEqual(["key-value"]); // the record/property-list rendering
    // Audited and deliberately NOT shape-indexed: SplitView's panes are heterogeneous, PaneGrid hosts
    // opaque workspace panes (not data items), StatTile renders a single KPI pair, not a record.
    for (const n of ["SplitView", "PaneGrid", "StatTile"]) {
      expect(byName(n)!.shapes, `${n} must not fake a shape ideal`).toBeUndefined();
    }
    // The Layouts-tier shape ideals: `tree` → Tree (#2476), `linked-list` → Sequence (#2477).
    expect(byName("Tree")!.shapes).toEqual(["tree"]);
    expect(byName("Sequence")!.shapes).toEqual(["linked-list"]);
    // #2505 — the Pages tier stamps the shape its WHOLE composition renders: the same shape as its
    // central layout template, one tier up. DashboardPage is honestly NOT shape-indexed — it renders
    // a heterogeneous board (KPIs + series + slices + feed); no single shape is "the page's shape".
    expect(byName("TablePage")!.shapes).toEqual(["table"]);
    expect(byName("TreeExplorerPage")!.shapes).toEqual(["tree"]);
    expect(byName("PipelinePage")!.shapes).toEqual(["linked-list"]);
    expect(byName("NetworkPage")!.shapes).toEqual(["graph"]);
    expect(byName("CollectionPage")!.shapes).toEqual(["list"]);
    expect(byName("RecordPage")!.shapes).toEqual(["key-value"]); // #2508 — the key-value shape's page
    expect(byName("DashboardPage")!.shapes, "DashboardPage must not fake a shape ideal").toBeUndefined();
  });

  it("keeps shape claimants unambiguous per role tier (#2475, refined by #2505)", () => {
    // THE CLAIMANT CONTRACT. #2475's original guard was one claimant per shape ACROSS THE KIT for
    // tree/linked-list — sized for a kit whose only claimant tier was the layouts. The Pages tier
    // (#2505) legitimately re-claims those shapes one tier up, so the contract is now per ROLE TIER:
    // within each tier that names an "ideal" — the LAYOUTS (structural templates) and the PAGES
    // (complete compositions) — a shape has AT MOST ONE claimant. The layouts stay the shape IDEALS
    // (`bsc ui shapes` answers carry `role`, so a reader tells the structural ideal from the finished
    // page); a page claiming the same shape is the complete rendering of it, never a competing
    // template — and no near-fit outside those two tiers may fake tree/linked-list coverage.
    const claimants = (shape: string, role: string) =>
      REACT_UI_COMPONENTS.filter((c) => c.role === role && ((c.shapes ?? []) as string[]).includes(shape))
        .map((c) => c.name);
    for (const s of ["list", "linked-list", "tree", "graph", "table", "key-value", "series"]) {
      expect(claimants(s, "layout").length, `layout tier claims ${s} at most once`).toBeLessThanOrEqual(1);
      expect(claimants(s, "page").length, `page tier claims ${s} at most once`).toBeLessThanOrEqual(1);
    }
    // tree/linked-list/key-value keep exhaustive claimant sets: the ideal component/template + its
    // page, nothing else (key-value's pair is composite-tier KeyValueList + page-tier RecordPage, #2508).
    const all = (shape: string) =>
      REACT_UI_COMPONENTS.filter((c) => ((c.shapes ?? []) as string[]).includes(shape)).map((c) => c.name).sort();
    expect(all("tree")).toEqual(["Tree", "TreeExplorerPage"]);
    expect(all("linked-list")).toEqual(["PipelinePage", "Sequence"]);
    expect(all("key-value")).toEqual(["KeyValueList", "RecordPage"]);
    // series (#3517): the four charting composites claim it — an axis + aligned numeric value series
    // (windowedTally's { labels, series }). No layout/page tier claims it (per-tier ≤1 holds trivially).
    expect(all("series")).toEqual(["Bars", "LineArea", "Spark", "StackedDayBars"]);
  });

  it("the packaged seed is a single kit — base-studio-code — carrying only the app's own pages (#3543/#3604)", () => {
    // #3543 wiped the packaged component library to a clean slate: ONE kit, `base-studio-code`, which
    // the designer session fills and the studio command exports. The react-ui LIBRARY still exists as
    // the manifest-generated assembler (REACT_UI_KIT / REACT_UI_COMPONENTS — asserted throughout this
    // file); it is just no longer SEEDED into the store.
    //
    // The kit is no longer EMPTY: #3604 packages the app's OWN migrated pages as graph source under
    // `@data/components/app/**`, glob-loaded into SEED_COMPONENTS. So the invariant is no longer
    // "nothing is seeded" but "only that kit is, and only from that glob".
    //
    // This assertion is HAND-MAINTAINED on purpose. Adding a packaged KIT back to the seed should be a
    // decision someone signs off on, not a glob — a failure here is that sign-off being asked for.
    expect(SEED_KITS.map((k) => k.id)).toEqual([BASE_STUDIO_CODE_KIT_ID]);
    expect(SEED_KITS[0].animations ?? []).toEqual([]);
    // Every seeded component belongs to that one kit — no second kit sneaks in via the glob.
    expect([...new Set(SEED_COMPONENTS.map((c) => c.kitId))]).toEqual([BASE_STUDIO_CODE_KIT_ID]);
  });
});

describe("the pages tier (#2505) — complete data-driven page compositions", () => {
  const PAGES = ["CollectionPage", "DashboardPage", "NetworkPage", "PipelinePage", "RecordPage", "TablePage", "TreeExplorerPage"];

  it("registers exactly the seven pages, each with role `page` (the top of the pyramid)", () => {
    const pages = REACT_UI_COMPONENTS.filter((c) => c.role === "page").map((c) => c.name).sort();
    expect(pages).toEqual(PAGES);
  });

  it("every page's composes list is non-empty and every name resolves in-kit (no dangling edges)", () => {
    const names = new Set(REACT_UI_COMPONENTS.map((c) => c.name));
    for (const p of PAGES) {
      const c = byName(p)!;
      expect(c.composes.length, `${p} must record its composition`).toBeGreaterThan(0);
      for (const dep of c.composes) expect(names.has(dep), `${p} composes unknown ${dep}`).toBe(true);
    }
  });

  it("graph completeness: every page transitively reaches a primitive via composes — no orphan pages", () => {
    const byN = new Map(REACT_UI_COMPONENTS.map((c) => [c.name, c]));
    const reachesPrimitive = (name: string, seen: Set<string>): boolean => {
      const c = byN.get(name);
      if (!c || seen.has(name)) return false;
      seen.add(name);
      if (c.role === "primitive") return true;
      return c.composes.some((d) => reachesPrimitive(d, seen));
    };
    for (const p of PAGES) {
      expect(reachesPrimitive(p, new Set()), `${p} must reach a primitive through its composes chain`).toBe(true);
    }
  });

  it("each page's central layout template is a composes edge (page → layout → … in the graph)", () => {
    expect(byName("TablePage")!.composes).toContain("SplitView");
    expect(byName("TreeExplorerPage")!.composes).toContain("Tree");
    expect(byName("PipelinePage")!.composes).toContain("Sequence");
    expect(byName("NetworkPage")!.composes).toContain("GraphCanvas");
    expect(byName("CollectionPage")!.composes).toContain("MasterDetail");
    // RecordPage (#2508) has no single template either — its centre is the KeyValueList composite
    // (the key-value archetype one tier down), grouped by SectionLabel.
    expect(byName("RecordPage")!.composes).toEqual(expect.arrayContaining(["KeyValueList", "SectionLabel"]));
    // DashboardPage has no single template — its chart/feed composites are the edges down.
    expect(byName("DashboardPage")!.composes).toEqual(
      expect.arrayContaining(["StatCard", "LineArea", "Donut", "Legend", "Spark", "ActivityFeed"]),
    );
  });

  it("authors full guidance + a realistic source snippet for every page", () => {
    for (const p of PAGES) {
      const c = byName(p)!;
      expect(c.whenUse.length, `${p} whenUse`).toBeGreaterThan(0);
      expect(c.whenNot.length, `${p} whenNot`).toBeGreaterThan(0);
      expect(c.tags).toContain("page");
      expect(c.srcText).toContain(`<${p}`);
      expect(c.src).toBe(`shared/ui/pages/${p}.tsx`);
    }
  });
});

import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { createHash } from "node:crypto";
import { join } from "node:path";
import { REACT_UI_KIT, REACT_UI_COMPONENTS, REACT_UI_KIT_STORE_ID, REACT_UI_KIT_VERSION } from "@/features/designs/lib/reactUiKit";

// The `react-ui` kit is GENERATED from the shared-UI manifest (slice 1) — a self-contained,
// gist-distributable artifact the frontend seed and the `bsc ui` store read. This test is the
// generator + the drift guard: `UPDATE_KITS=1 npx vitest run reactUiKit.gen` (re)writes it; CI asserts
// it stays in sync with the manifest, so it can't silently drift from the registry.
//
// IT IS NO LONGER COMMITTED (`the-kit-artifact-is-derived-not-committed`). Its home is
// `graph/components.db`, and the file under `src-tauri/data/components/` is a git-ignored CACHE that
// `scripts/emit-records.mjs` materializes from the store — the same shape `.bsc-records/` has, for the
// same reason. Two facts forced it: 619 of the artifact's 660 entries were verbatim copies of
// `.bsc-records/`, carrying inside a committed file the banner that says "do not commit"; and its bytes
// were therefore a function of when that git-ignored cache was last materialized rather than of the
// commit — measured on ONE commit, this guard said "in sync" in one worktree and "3 runtime modules
// drifted" in another, minutes apart.
//
// SO A REGENERATION HAS TWO STEPS, and the second is the one that persists:
//     UPDATE_KITS=1 npx vitest run reactUiKit.gen    # rewrite the cache from the manifest
//     bsc ui store sync --apply                      # push it into the store, which is its home
// Without the second, the next `emit:records` materializes the OLD artifact back over the new one and
// the regeneration undoes itself.
//
// #2465 stamps the packaged kit's GLOBAL-store identity (`bsc/react-ui@1.0.0`) into the artifact and
// additionally generates a hash SIDECAR (`src-tauri/data/ui/react-ui-kit.meta.json` — under data/ui/,
// NOT data/components/, so the builtinKits `@data/components/*.json` glob never mistakes it for a
// kit): `{ id, version, kind, sha256 }` where sha256 is the hash of the artifact's exact bytes. The
// sidecar can't live inside the artifact (a file can't contain its own hash), and both files are
// pinned `eol=lf` in .gitattributes so the bytes — and therefore the hash — are identical on every
// platform (the Rust `bsc ui kit` store embeds both as the packaged fallback entry; the frontend
// default-pin reads the sidecar via `@data/ui/react-ui-kit.meta.json`).
const FILE = join(process.cwd(), "src-tauri/data/components/react-ui.json");
const META_FILE = join(process.cwd(), "src-tauri/data/ui/react-ui-kit.meta.json");

/** Bundle each component's VERBATIM implementation into the artifact (#2794, epic #2793): read the
 *  `.tsx` at its `src` path, LF-normalized so the escaped-newline bytes — and therefore the hash
 *  sidecar — are identical on every platform (the artifact is pinned `eol=lf`). A component whose `src`
 *  has no standalone file (a pure stub) simply carries no `source`. This is what gives `bsc ui … emit`
 *  real code to write; the mutable component store deliberately drops it (`builtinKits.withoutSource`). */
const withSource = (components: typeof REACT_UI_COMPONENTS) =>
  components.map((c) => {
    const source = readSrc(c.src);
    return source === null ? c : { ...c, source };
  });

const SRC = join(process.cwd(), "src");
/** The generated tree `scripts/emit-records.mjs` materializes retired modules into (mirroring `src/`). */
const RECORDS = join(process.cwd(), ".bsc-records");

/** The two-step resolve — `src/` first, then the emitted record tree — for a path relative to `src/`.
 *
 *  The kit generator is the FIFTH consumer that has to know about retired modules, after tsc
 *  (`tsconfig.paths`), vite + vitest (`vite/bscRecords.ts`) and the e2e config. It reads `src/<c.src>`
 *  directly to bundle each component's verbatim implementation, so retiring `Button.tsx` made it throw
 *  ENOENT on a path the app resolves perfectly well. Every such reader needs the fallback, and the shape
 *  is always the same: the file wins while it exists, and the record answers only what `src/` no longer
 *  has. Returns LF-normalized source, or `null` when neither has it (a pure stub legitimately has none). */
function readSrc(rel: string): string | null {
  for (const root of [SRC, RECORDS]) {
    const p = join(root, rel);
    if (existsSync(p)) return readFileSync(p, "utf8").replace(/\r\n/g, "\n");
  }
  return null;
}

/** Does `rel` (relative to `src/`) exist in either tree? The `existsSync` half of {@link readSrc}. */
const hasSrc = (rel: string) => existsSync(join(SRC, rel)) || existsSync(join(RECORDS, rel));

/** Resolve a FIRST-PARTY import specifier — a `@/…` OR a RELATIVE (`./`,`../`) path — to a path relative
 *  to `src/` (with extension), trying TS module-resolution order. `fromRel` is the src/-relative path of
 *  the IMPORTING module (needed to resolve a relative specifier). `null` when it isn't a resolvable
 *  first-party file (an external npm dep — react/node/d3 — or a type-only path with no `.ts(x)` on disk). */
function resolveImport(spec: string, fromRel: string): string | null {
  let base: string;
  if (spec.startsWith("@/")) {
    base = spec.slice(2); // drop "@/"
  } else if (spec.startsWith("./") || spec.startsWith("../")) {
    // Resolve relative to the IMPORTING module's dir, normalising `.`/`..` segments (#2954).
    const fromDir = fromRel.includes("/") ? fromRel.slice(0, fromRel.lastIndexOf("/")) : "";
    const out: string[] = [];
    for (const seg of (fromDir ? fromDir.split("/") : []).concat(spec.split("/"))) {
      if (seg === "" || seg === ".") continue;
      if (seg === "..") out.pop();
      else out.push(seg);
    }
    base = out.join("/");
  } else {
    return null; // external npm dep (react, node, d3, …)
  }
  for (const cand of [`${base}.ts`, `${base}.tsx`, `${base}/index.ts`, `${base}/index.tsx`]) {
    if (hasSrc(cand)) return cand;
  }
  return null;
}

/** Every FIRST-PARTY specifier a source imports/re-exports/dynamically imports — the `@/…` AND the
 *  RELATIVE (`./`, `../`) ones (#2954: relative imports were silently dropped before, so a relatively-
 *  imported support module never vendored). External npm specifiers are left for `resolveImport` to drop. */
function importSpecifiers(source: string): string[] {
  const specs: string[] = [];
  const re = /(?:from|import)\s*\(?\s*["']((?:@\/|\.\.?\/)[^"']+)["']/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(source))) specs.push(m[1]);
  return specs;
}

/** The transitive NON-COMPONENT support closure the components import (#2798) — the `_kit/` runtime the
 *  vendored-source emit (②·2) needs so an emitted file compiles standalone: `{ <path rel. to src/> :
 *  <verbatim LF source> }`. Seeded from every component's real source and walked through first-party
 *  `@/…` imports; a resolved path that is a KIT COMPONENT (a `src` in the kit) is skipped — that's a
 *  `composes` edge, emitted as a sibling file, not runtime — as are external (non-`@/`) deps (react,
 *  d3), which stay npm dependencies. Deterministic (sorted) so the artifact bytes are stable. */
function collectRuntime(components: typeof REACT_UI_COMPONENTS): Record<string, string> {
  const componentSrc = new Set(components.map((c) => c.src)); // e.g. "shared/ui/data/Card.tsx"
  const collected = new Map<string, string>();
  const visited = new Set<string>();
  const walk = (relPath: string) => {
    if (visited.has(relPath)) return;
    visited.add(relPath);
    const source = readSrc(relPath);
    if (source === null) return;
    for (const spec of importSpecifiers(source)) {
      const resolved = resolveImport(spec, relPath);
      if (!resolved || componentSrc.has(resolved)) continue; // external, unresolved, or a kit component
      if (!collected.has(resolved)) collected.set(resolved, readSrc(resolved) ?? "");
      walk(resolved);
    }
  };
  for (const c of components) walk(c.src); // seed the walk from each component's real source
  return Object.fromEntries([...collected.entries()].sort(([a], [b]) => a.localeCompare(b)));
}

const kitFile = {
  order: 0,
  id: REACT_UI_KIT_STORE_ID,
  version: REACT_UI_KIT_VERSION,
  kit: REACT_UI_KIT,
  components: withSource(REACT_UI_COMPONENTS),
  runtime: collectRuntime(REACT_UI_COMPONENTS),
};
const serialised = JSON.stringify(kitFile, null, 2) + "\n";
const meta = {
  id: REACT_UI_KIT_STORE_ID,
  version: REACT_UI_KIT_VERSION,
  kind: "component-kit",
  sha256: createHash("sha256").update(serialised, "utf8").digest("hex"),
};
const metaSerialised = JSON.stringify(meta, null, 2) + "\n";

/** Deterministic stringify — keys sorted recursively — so two objects built with the same content in a
 *  different key order compare equal (JSON.parse/`toEqual` already ignore order; a raw `JSON.stringify`
 *  comparison would not). Used only to detect WHETHER an entry differs; `toEqual` below still owns the
 *  real assertion. */
function stableStringify(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(",")}]`;
  if (v && typeof v === "object") {
    const keys = Object.keys(v as Record<string, unknown>).sort();
    return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify((v as Record<string, unknown>)[k])}`).join(",")}}`;
  }
  return JSON.stringify(v);
}

/** Name the FILE that caused kit drift, instead of leaving a reader to spot one changed string inside a
 *  toEqual diff of two ~86,000-line objects (request #171 — hit three times in one day with no clue which
 *  of ~100+ components or dozens of runtime modules moved). Compares the on-disk artifact against the
 *  freshly generated `kitFile` component-by-component and runtime-entry-by-entry, returning one line per
 *  drifted/added/removed component (by id + its `src`) or runtime module (by path). Empty when nothing
 *  drifted structurally (a `kit`/`id`/`version` change is still reported, just without a file to name). */
function describeDrift(onDisk: typeof kitFile, fresh: typeof kitFile): string[] {
  const reasons: string[] = [];
  for (const key of ["id", "version", "kit"] as const) {
    if (stableStringify(onDisk[key]) !== stableStringify(fresh[key])) reasons.push(`"${key}" changed`);
  }
  const onDiskById = new Map(onDisk.components.map((c) => [c.id, c]));
  const freshById = new Map(fresh.components.map((c) => [c.id, c]));
  for (const [id, freshC] of freshById) {
    const onDiskC = onDiskById.get(id);
    if (!onDiskC) reasons.push(`component "${id}" (${freshC.src}) added to the manifest`);
    else if (stableStringify(onDiskC) !== stableStringify(freshC)) {
      reasons.push(
        onDiskC.source !== freshC.source
          ? `component "${id}" — ${freshC.src} changed on disk since react-ui.json was last generated`
          : `component "${id}" (${freshC.src}) metadata changed (not its source)`,
      );
    }
  }
  for (const id of onDiskById.keys()) {
    if (!freshById.has(id)) reasons.push(`component "${id}" removed from the manifest`);
  }
  const onDiskOrder = onDisk.components.map((c) => c.id);
  const freshOrder = fresh.components.map((c) => c.id);
  if (onDiskOrder.length === freshOrder.length && stableStringify(onDiskOrder) !== stableStringify(freshOrder)) {
    reasons.push(`component order changed (same set, different sequence)`);
  }
  const runtimePaths = new Set([...Object.keys(onDisk.runtime), ...Object.keys(fresh.runtime)]);
  for (const path of runtimePaths) {
    const before = onDisk.runtime[path];
    const after = fresh.runtime[path];
    if (before === undefined) reasons.push(`runtime module ${path} added to the manifest closure`);
    else if (after === undefined) reasons.push(`runtime module ${path} dropped from the manifest closure`);
    else if (before !== after) reasons.push(`runtime module ${path} changed on disk since react-ui.json was last generated`);
  }
  return reasons;
}

describe("data/components/react-ui.json ↔ manifest (#2305 slice 1b)", () => {
  it("stays in sync with the manifest-generated kit (UPDATE_KITS=1 to regenerate)", () => {
    if (process.env.UPDATE_KITS) writeFileSync(FILE, serialised);
    expect(existsSync(FILE), "react-ui.json missing — it is materialized from graph/components.db by `npm run emit:records`").toBe(true);
    // Round-trip the expected value so the comparison ignores `undefined` fields JSON drops.
    const onDisk = JSON.parse(readFileSync(FILE, "utf8"));
    const fresh = JSON.parse(JSON.stringify(kitFile));
    const drift = describeDrift(onDisk, fresh);
    expect(
      drift,
      `kit drifted from the manifest — regenerate with \`UPDATE_KITS=1 npx vitest run reactUiKit.gen\`, then \`bsc ui store sync --apply\`:\n${drift.join("\n")}`,
    ).toEqual([]);
    expect(onDisk).toEqual(fresh);
  });

  it("keeps the packaged-kit hash sidecar in sync (#2465; UPDATE_KITS=1 to regenerate)", () => {
    if (process.env.UPDATE_KITS) writeFileSync(META_FILE, metaSerialised);
    expect(existsSync(META_FILE), "react-ui-kit.meta.json missing — it is materialized from graph/components.db by `npm run emit:records`").toBe(true);
    expect(JSON.parse(readFileSync(META_FILE, "utf8"))).toEqual(meta);
    // The sidecar's hash must be the hash of the artifact's exact bytes (CRLF-normalized: a
    // pre-.gitattributes checkout may still hold the artifact CRLF; LF is the canonical byte form).
    const artifact = readFileSync(FILE, "utf8").replace(/\r\n/g, "\n");
    expect(createHash("sha256").update(artifact, "utf8").digest("hex")).toBe(meta.sha256);
  });

  it("bundles each component's verbatim implementation source (#2794)", () => {
    const artifact = JSON.parse(readFileSync(FILE, "utf8")) as {
      components: { id: string; src: string; source?: string }[];
    };
    const byId = new Map(artifact.components.map((c) => [c.id, c]));
    // Real primitives carry their exact on-disk `.tsx` (not the usage-snippet `srcText`).
    for (const id of ["card", "button"]) {
      const c = byId.get(id);
      expect(c, `${id} present in the artifact`).toBeTruthy();
      const onDisk = readSrc(c!.src);
      expect(c!.source, `${id} bundles its verbatim source`).toBe(onDisk);
    }
    // Most components resolve to a real file — the artifact is now source-bearing, not just a catalog
    // of path pointers. (A few templates/stubs legitimately have no standalone file → no `source`.)
    const withRealSource = artifact.components.filter((c) => (c.source ?? "").length > 0).length;
    expect(withRealSource).toBeGreaterThan(artifact.components.length / 2);
  });

  it("bundles the transitive non-component support closure as `runtime` (#2798)", () => {
    const artifact = JSON.parse(readFileSync(FILE, "utf8")) as {
      components: { src: string }[];
      runtime: Record<string, string>;
    };
    const rt = artifact.runtime;
    expect(rt && Object.keys(rt).length, "runtime is non-empty").toBeTruthy();
    // A known support module the components import (`core/format`) is vendored, verbatim.
    const fmtKey = Object.keys(rt).find((k) => k.startsWith("shared/lib/core/format"));
    expect(fmtKey, "core/format is in the runtime closure").toBeTruthy();
    expect(rt[fmtKey!]).toBe(readSrc(fmtKey!));
    // No COMPONENT module leaked into `runtime` — those are `source` (emitted via `composes`), never
    // the support runtime. And every runtime entry resolves to a real on-disk file.
    const componentSrc = new Set(artifact.components.map((c) => c.src));
    for (const path of Object.keys(rt)) {
      expect(componentSrc.has(path), `${path} is a support module, not a component`).toBe(false);
      // EITHER tree: a retired module still exists as a file, just in the generated record mirror rather
      // than `src/`. Asserting `src/` alone would fail the moment the closure reaches a retired module —
      // which is what happened when `FocusedFeaturesBody.tsx` went — and the assertion's real point is
      // that the closure names something real, not which of the two trees holds it.
      expect(hasSrc(path), `${path} exists on disk (src/ or .bsc-records/)`).toBe(true);
    }
  });

  it("the emit closure is COMPLETE — every first-party import resolves to a component or runtime (#2798)", () => {
    // The guarantee that makes ②·2 emit COMPILABLE source: across everything emit would write (each
    // component's `source` + each runtime module), every `@/…` import must resolve to either a kit
    // component (a `composes` edge → sibling file) or a bundled runtime module. Any unresolved
    // first-party import is a hole the emitted app couldn't build around.
    const artifact = JSON.parse(readFileSync(FILE, "utf8")) as {
      components: { src: string; source?: string }[];
      runtime: Record<string, string>;
    };
    const componentSrc = new Set(artifact.components.map((c) => c.src));
    const runtimeKeys = new Set(Object.keys(artifact.runtime));
    const sources: [string, string][] = [
      ...artifact.components.filter((c) => c.source).map((c) => [c.src, c.source!] as [string, string]),
      ...Object.entries(artifact.runtime),
    ];
    const gaps: string[] = [];
    for (const [file, src] of sources) {
      for (const spec of importSpecifiers(src)) {
        const resolved = resolveImport(spec, file);
        if (!resolved) continue; // external / type-only → an npm dep, not vendored
        if (componentSrc.has(resolved) || runtimeKeys.has(resolved)) continue; // composes edge or runtime
        gaps.push(`${file} → ${spec}`);
      }
    }
    expect(gaps, `unresolved first-party imports would break an emitted file:\n${gaps.join("\n")}`).toEqual([]);
  });
});

describe("describeDrift diagnostic (request #171 — kit drift should name the file that caused it)", () => {
  // A small, self-contained fixture shaped like `kitFile` — NOT read from the real 86,000-line
  // artifact, so each case isolates exactly one kind of drift instead of depending on which real
  // component happens to exist today.
  const baseline = {
    order: 0,
    id: "bsc/react-ui@1.0.0",
    version: "1.0.0",
    kit: { name: "react-ui" },
    components: [
      { id: "button", src: "shared/ui/controls/Button.tsx", name: "Button", source: "export const Button = () => null;\n" },
      { id: "card", src: "shared/ui/data/Card.tsx", name: "Card", source: "export const Card = () => null;\n" },
    ],
    runtime: { "shared/lib/core/format.ts": "export const fmt = (n: number) => String(n);\n" },
  } as unknown as typeof kitFile;
  const clone = () => JSON.parse(JSON.stringify(baseline)) as typeof kitFile;

  it("passes clean when the artifact matches the manifest", () => {
    expect(describeDrift(clone(), clone())).toEqual([]);
  });

  it("names the component id + its src path when a bundled source is stale", () => {
    const fresh = clone();
    const onDisk = clone();
    (onDisk.components[0] as { source?: string }).source = "// stale — edited on disk since react-ui.json was generated\n";
    const drift = describeDrift(onDisk, fresh);
    expect(drift).toEqual([`component "button" — shared/ui/controls/Button.tsx changed on disk since react-ui.json was last generated`]);
  });

