/** A manifest prop's type rendered as a short human/TS-ish string for the props table. */
function mapType(p: ManifestProp): string {
  if (p.type === "enum" && p.values) return p.values.map((v) => `"${v}"`).join(" | ");
  switch (p.type) {
    case "node": return "ReactNode";
    case "function": return "(…) => void";
    case "space": return "Space";
    case "fontSize": return "FontSize";
    case "tracks": return "Tracks";
    case "color": return "Color";
    case "style": return "CSSProperties";
    case "array": return "T[]";
    default: return p.type; // string | number | boolean
  }
}

const mapProps = (specs: readonly ManifestProp[]): PropSpec[] =>
  specs.map((p) => ({ name: p.name, type: mapType(p), req: !!p.required, desc: p.description }));

/** Variants: the overlay's set, else the `variant` enum's values (else "default"), plus "loading"
 *  when the component registers a `loading` prop (#2302). */
function deriveVariants(spec: PrimitiveSpec, g: Guidance): string[] {
  let base = g.variants;
  if (!base) {
    const variantProp = spec.props.find((p) => p.name === "variant" && p.type === "enum" && p.values);
    base = variantProp?.values ? [...variantProp.values] : ["default"];
  }
  const hasLoading = spec.props.some((p) => p.name === "loading");
  return hasLoading && !base.includes("loading") ? [...base, "loading"] : base;
}

/** A minimal, generated usage snippet for a component without an authored `srcText`. */
function stubSrc(spec: PrimitiveSpec): string {
  const req = spec.props.filter((p) => p.required && p.name !== "children");
  const attrs = req.map((p) => ` ${p.name}={…}`).join("");
  const hasChildren = spec.props.some((p) => p.name === "children");
  const body = hasChildren ? `<${spec.name}${attrs}>…</${spec.name}>` : `<${spec.name}${attrs} />`;
  return `import { ${spec.name} } from "${spec.importPath}";\n\n${body}`;
}

function toRecord(spec: PrimitiveSpec): ComponentRecord {
  const g = GUIDANCE[spec.name] ?? {};
  return {
    id: spec.name.toLowerCase(),
    name: spec.name,
    kitId: REACT_UI_KIT_ID,
    role: g.role ?? GROUP_ROLE[spec.group],
    version: g.version ?? "1.0.0",
    used: g.used ?? 0,
    tags: g.tags ?? [spec.group],
    variants: deriveVariants(spec, g),
    composes: g.composes ?? [],
    props: mapProps(spec.props),
    whenUse: g.whenUse ?? [],
    whenNot: g.whenNot ?? [],
    src: `${spec.importPath.replace(/^@\//, "")}.tsx`,
    srcText: g.srcText ?? stubSrc(spec),
    builtin: true,
    ...(g.wraps ? { wraps: g.wraps } : {}),
    ...(g.shapes ? { shapes: g.shapes } : {}),
    // Motion BINDING (#2942/#3451) — the manifest spec already carries NAME references; the defs
    // themselves are owned by the `base` kit (`shared/ui/kit/baseAnimations.ts`) and resolved from
    // there. Only emitted when present so animation-free records stay byte-identical.
    ...(spec.animations?.length ? { animations: [...spec.animations] } : {}),
  };
}

/** The `react-ui` kit — the app's own shared-UI primitives. `tech`/`style` are the #2487 rail
 *  hierarchy axes: react technology, and "studio" — the app's neutral house visual language (the
 *  structural component set; palettes/themes are a separate axis and never name a style).
 *
 *  Its motion library is deliberately EMPTY (#3451): the base motions its primitives play
 *  (`lift`/`fade-in`/`pulse`) are owned by the `base` kit (`shared/ui/kit/baseAnimations.ts`) and
 *  resolved from there by name, so ONE definition serves every consuming kit and a base-motion edit
 *  propagates to all of them. react-ui REFERENCES that shared motion; it no longer owns it. (A kit
 *  may still author its OWN motion here — the resolver prefers a kit's own def over the base one.) */
export const REACT_UI_KIT: Kit = {
  id: REACT_UI_KIT_ID, name: "react-ui", tech: "react", style: "studio", stack: "React · TypeScript",
  dot: "var(--info)", builtin: true, animations: [],
};

/** Every registered primitive as a component record — generated from the manifest, so this is exactly
 *  `UI_KIT` (guarded by `reactUiKit.test.ts`), never a drifting hand-list. */
export const REACT_UI_COMPONENTS: ComponentRecord[] = UI_KIT.map(toRecord);

// Shared readiness-check shape (#1625) — one home for the byte-identical
// `{ id, label, ok, detail }` row used by the deploy / integration / source stage
// banners. Each `*Checks` builder returns these; every row `ok` ⇒ the stage gate passes.

/** A single readiness row driving an in-pane stage banner. */
export interface ReadinessCheck {
  /** stable row id (also the React key). */
  id: string;
  /** human label for the requirement. */
  label: string;
  /** whether this requirement is satisfied. */
  ok: boolean;
  /** a short value/explanation shown beside the label. */
  detail: string;
}

// Blueprint design reconciliation (#2646, epic #2606) — the PURE diff behind the sharing layer. When a
// blueprint is downloaded, its design contribution (the categories it introduces + a theme ref) is
// reconciled against the LOCAL design contract: categories the contract doesn't define are gaps a
// dedicated confirm-list (5b) offers to fill via the generator (#2636), so a shared blueprint brings its
// look with NO holes. This module is the DIFF only — no download/confirm/generation wiring. Kept in
// shared/ (feature-agnostic, structural inputs) so the planner + a future reconciliation UI both use it.
import DESCRIPTOR from "@data/ui/style-descriptor.json";
import { slugify } from "@/shared/lib/core/format";

interface DomainDescriptor {
  domain?: { group: string; tokens?: { key: string }[] }[];
}

/** The graph CATEGORY keys the local contract defines (the `graph-category` domain group): greenfield,
 *  transform, harden, maintain, data, script. A blueprint category outside this set is a gap the
 *  generator fills. Computed once from the descriptor. */
export const KNOWN_GRAPH_CATEGORIES: ReadonlySet<string> = (() => {
  const d = DESCRIPTOR as DomainDescriptor;
  const group = (d.domain ?? []).find((g) => g.group === "graph-category");
  return new Set((group?.tokens ?? []).map((t) => t.key));
})();

/** A blueprint's design contribution — the reconcilable shape (structural; the planner's `BlueprintDesign`
 *  is assignable to it, keeping shared/ free of a feature import). */
export interface DesignContribution {
  categories?: string[];
  theme?: string;
}

export interface DesignReconcile {
  /** Categories the blueprint introduces that the local contract does NOT define — the gaps to fill. */
  missingCategories: string[];
  /** The theme ref carried through (a `bsc ui theme` id), for the confirm-list to resolve/import (5b). */
  themeRef?: string;
  /** True when nothing needs reconciling (no missing categories). */
  complete: boolean;
}

/** Diff a blueprint's design contribution against the local contract (#2646). Pure. `known` defaults to
 *  the contract's graph-category keys; missing categories are slugified, deduped + sorted.
 *
 *  Each category is normalized to a slug FIRST (#2663) so the token derived downstream —
 *  `--graph-category-<key>` — is always a valid custom property. A non-slug key like `"Simulation"` or
 *  `"ui_ux"` would otherwise be dropped SILENTLY when `compileContributionsCss` rejects it against
 *  `SAFE_TOKEN` — a hole the fall-loudly principle forbids. Slugging here also means a capitalized KNOWN
 *  category (e.g. `"Greenfield"`) matches the contract instead of being wrongly flagged missing. Empty
 *  slugs (e.g. from `"!!!"`) are dropped. */
export function reconcileDesign(
  design: DesignContribution | undefined,
  known: ReadonlySet<string> = KNOWN_GRAPH_CATEGORIES,
): DesignReconcile {
  const categories = (design?.categories ?? []).map((c) => slugify(c)).filter(Boolean);
  const missingCategories = [...new Set(categories.filter((c) => !known.has(c)))].sort();
  return { missingCategories, themeRef: design?.theme, complete: missingCategories.length === 0 };
}

tests.src:
import { describe, it, expect } from "vitest";
import { reconcileDesign, KNOWN_GRAPH_CATEGORIES } from "@/shared/ui/kit/reconcile";

describe("reconcileDesign (#2646)", () => {
  it("KNOWN_GRAPH_CATEGORIES = the contract's graph-category keys", () => {
    expect(KNOWN_GRAPH_CATEGORIES.has("greenfield")).toBe(true);
    expect(KNOWN_GRAPH_CATEGORIES.has("script")).toBe(true); // #2596
    expect(KNOWN_GRAPH_CATEGORIES.has("simulation")).toBe(false);
  });

  it("no contribution → complete, nothing missing", () => {
    expect(reconcileDesign(undefined)).toEqual({ missingCategories: [], themeRef: undefined, complete: true });
    expect(reconcileDesign({})).toEqual({ missingCategories: [], themeRef: undefined, complete: true });
  });

  it("known categories are NOT missing; unknown ones ARE (deduped + sorted)", () => {
    expect(reconcileDesign({ categories: ["greenfield", "transform"] }).missingCategories).toEqual([]);
    const r = reconcileDesign({ categories: ["simulation", "greenfield", "analysis", "simulation"] });
    expect(r.missingCategories).toEqual(["analysis", "simulation"]); // unknown only, deduped, sorted
    expect(r.complete).toBe(false);
  });

  it("carries the theme ref through", () => {
    expect(reconcileDesign({ theme: "soft" }).themeRef).toBe("soft");
    expect(reconcileDesign({ categories: ["greenfield"], theme: "warm" })).toEqual({
      missingCategories: [],
      themeRef: "warm",
      complete: true,
    });
  });

  it("accepts a custom known set (feature-agnostic)", () => {
    expect(reconcileDesign({ categories: ["x"] }, new Set(["x"])).missingCategories).toEqual([]);
    expect(reconcileDesign({ categories: ["x"] }, new Set(["y"])).missingCategories).toEqual(["x"]);
  });

  it("slugifies categories so the derived token is always SAFE_TOKEN-valid (#2663)", () => {
    // A non-slug key ("Simulation", "ui_ux", "3D View") would otherwise become an invalid custom
    // property and be dropped SILENTLY at CSS-compile — a hole. Reconcile normalizes to slugs first.
    const r = reconcileDesign({ categories: ["Simulation", "ui_ux", "3D View"] });
    expect(r.missingCategories).toEqual(["3d-view", "simulation", "ui-ux"]);
    expect(r.complete).toBe(false);
  });

  it("a capitalized KNOWN category is matched, not flagged missing (#2663)", () => {
    expect(reconcileDesign({ categories: ["Greenfield", "TRANSFORM"] })).toEqual({
      missingCategories: [],
      themeRef: undefined,
      complete: true,
    });
  });

  it("drops categories that slugify to empty", () => {
    expect(reconcileDesign({ categories: ["!!!", "   ", "greenfield"] }).missingCategories).toEqual([]);
  });
});

