// The repo-scoped CREDENTIAL choice, captured from the live TypeScript so Rust can be proved to match.
//
// This is a security boundary of the same shape as the role gate: `tokenForRepo` picks the credential a
// worker/triage pane is LAUNCHED with as its `GH_TOKEN` (#158), so a session for repo A cannot act on
// repo B; `resolveGithubToken` picks the one a proxied REST request carries. Rust owns both ends —
// `pty_create` builds the session env and `github/api.rs` is the API layer — and the choice was made in
// the renderer.
//
// ## Three rules a port drifts on, each with its own case
//
//   * The token VALUE is tested for truthiness, so a repo with an ASSIGNED BUT EMPTY token falls back
//     to the global one. A corpus of realistic non-empty tokens passes either version.
//   * Matching is case-insensitive on `owner/name`, because GitHub repo names are.
//   * The FIRST matching entry wins — only observable with two keys differing solely by case, and only
//     reproducible if the input preserves ORDER. A Rust `HashMap` would not; a `BTreeMap` would sort
//     rather than keep insertion order. Hence the fixture records ordered PAIRS.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/github/repoCredentials.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { repoFromGitHubPath, resolveGithubToken, tokenForRepo } from "@/shared/lib/github/repoCredentials";

const FIXTURE = join(process.cwd(), "src/shared/lib/github/repoCredentials.fixtures.json");

/** Paths, including the shapes that are NOT repo-scoped and the truncated ones. */
const PATHS = [
  "/repos/acme/web", "repos/acme/web", "/repos/acme/web/issues", "/repos/acme/web/pulls/3",
  "/repos/acme/web?state=open", "/repos/acme/web#frag", "/repos/Acme/Web",
  // Not repo-scoped at all.
  "user/repos", "/user/repos", "/users/x/events", "/orgs/acme/repos", "/search/issues?q=x",
  // Truncated / degenerate — a repo needs BOTH segments.
  "", "/", "/repos", "/repos/", "/repos/acme", "/repos/acme/", "//repos/acme/web",
  // A dot and a dash are ordinary name characters; a second slash ends the name.
  "/repos/acme/my-repo.js", "/repos/a/b/c/d",
];

/** Ordered pairs, so first-match-wins is observable and reproducible. */
type Pairs = [string, string][];
const CASES: { label: string; repo: string | null; pairs: Pairs; global: string }[] = [
  { label: "no assignment falls back to global", repo: "acme/web", pairs: [], global: "GLOBAL" },
  { label: "exact assignment wins", repo: "acme/web", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  { label: "case-insensitive on the key", repo: "acme/web", pairs: [["Acme/Web", "T1"]], global: "GLOBAL" },
  { label: "case-insensitive on the query", repo: "ACME/WEB", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  { label: "a different repo does not match", repo: "acme/api", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  // THE SENTINEL: assigned but EMPTY is skipped by the truthiness test, so the global wins.
  { label: "an assigned but EMPTY token falls back to global", repo: "acme/web", pairs: [["acme/web", ""]], global: "GLOBAL" },
  // …and the skip continues scanning, so a later case-variant entry can still match.
  { label: "an empty entry is skipped, a later variant still matches", repo: "acme/web", pairs: [["acme/web", ""], ["ACME/WEB", "T2"]], global: "GLOBAL" },
  // FIRST match wins — only visible with two keys differing solely by case.
  { label: "first match wins among case variants", repo: "acme/web", pairs: [["acme/web", "FIRST"], ["ACME/WEB", "SECOND"]], global: "GLOBAL" },
  // A null / empty repo is the director or an unbound console.
  { label: "a null repo is the global token", repo: null, pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  { label: "an empty repo is the global token", repo: "", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  // An empty GLOBAL is a real state (no PAT connected) and must come back as-is, not as a match.
  { label: "an empty global is returned when nothing matches", repo: "acme/api", pairs: [["acme/web", "T1"]], global: "" },
];

const RESOLVE: { label: string; path: string; pairs: Pairs; global: string }[] = [
  { label: "a repo path picks its scoped token", path: "/repos/acme/web/issues", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  { label: "a non-repo path always takes the global", path: "/user/repos", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  { label: "a repo path with no assignment takes the global", path: "/repos/other/x", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  { label: "case differs between path and key", path: "/repos/ACME/WEB", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
  { label: "query string does not defeat the match", path: "/repos/acme/web?state=open", pairs: [["acme/web", "T1"]], global: "GLOBAL" },
];

const obj = (pairs: Pairs) => Object.fromEntries(pairs);

function build() {
  return {
    note: "GENERATED from the live TypeScript — see repoCredentials.fixtures.gen.test.ts",
    paths: PATHS.map((path) => ({ path, repo: repoFromGitHubPath(path) })),
    tokenForRepo: CASES.map(({ label, repo, pairs, global }) => ({
      label, repo, pairs, global, token: tokenForRepo(repo, obj(pairs), global),
    })),
    resolve: RESOLVE.map(({ label, path, pairs, global }) => ({
      label, path, pairs, global, token: resolveGithubToken(path, obj(pairs), global),
    })),
  };
}

describe("the repo-scoped credential choice is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const text = JSON.stringify(build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  /** The corpus must contain both a repo-scoped and a non-repo path, or the parse is untested. */
  it("covers repo-scoped and non-repo paths", () => {
    const p = build().paths;
    expect(p.some((x) => x.repo !== null)).toBe(true);
    expect(p.filter((x) => x.repo === null).length).toBeGreaterThanOrEqual(8);
  });

  /** THE SENTINEL. An assigned-but-empty token must not be returned. */
  it("pins that an empty assigned token falls back to the global", () => {
    const c = build().tokenForRepo.find((x) => x.label.includes("EMPTY token"))!;
    expect(c.token).toBe("GLOBAL");
  });

  /** First-match-wins is only observable with two case-variant keys. */
  it("pins first-match-wins with two keys differing only by case", () => {
    const c = build().tokenForRepo.find((x) => x.label.startsWith("first match wins"))!;
    expect(c.token).toBe("FIRST");
  });

  /** Skipping an empty entry must CONTINUE scanning rather than stop. */
  it("keeps scanning past an empty entry", () => {
    const c = build().tokenForRepo.find((x) => x.label.startsWith("an empty entry is skipped"))!;
    expect(c.token).toBe("T2");
  });

  /** Both outcomes must occur in the resolve corpus, or one branch is untested. */
  it("resolves some paths to a scoped token and some to the global", () => {
    const r = build().resolve;
    expect(r.some((x) => x.token === "T1")).toBe(true);
    expect(r.some((x) => x.token === "GLOBAL")).toBe(true);
  });
});

implementations.code:
// Repo-scoped GitHub credentials (#158) — the GitHub-proxy axis of per-session
// isolation. A session for repo A, given a repo-A-scoped token, makes its GitHub API
// calls with that token (not the global PAT), so it can't act on other repos via the
// proxy. The resolution is purely a function of the request path + the assigned tokens,
// so it's transport-free and unit-testable. (Filesystem/git confinement is separate.)

/**
 * The `owner/name` a GitHub REST path targets, or `null` when it isn't repo-scoped
 * (e.g. `user/repos`, `users/x/events`). Tolerates a leading slash and a query string.
 */
export function repoFromGitHubPath(path: string): string | null {
  const m = /^\/?repos\/([^/]+)\/([^/?#]+)/.exec(path);
  return m ? `${m[1]}/${m[2]}` : null;
}

/**
 * Resolve the token for a request: the repo-scoped credential when the path targets a
 * repo that has one assigned, otherwise the global token. Matching is case-insensitive
 * on the `owner/name` (GitHub repo names are case-insensitive).
 */
export function resolveGithubToken(
  path: string,
  repoTokens: Record<string, string>,
  globalToken: string,
): string {
  const repo = repoFromGitHubPath(path);
  return tokenForRepo(repo, repoTokens, globalToken);
}

/**
 * Resolve the token for a session bound to a specific `owner/name` repo: the
 * repo-scoped credential when one is assigned, otherwise the global token. This is
 * the session axis of #158 — a worker/triage pane is launched with this token as its
 * `GH_TOKEN`, so its `gh`/`git` operations carry a fine-grained, repo-scoped credential
 * (when assigned) and can't act on sibling repos. Matching is case-insensitive on the
 * `owner/name` (GitHub repo names are case-insensitive). A null/empty `repo` (a console
 * with no bound repo, the director) falls back to the global token.
 */
export function tokenForRepo(
  repo: string | null | undefined,
  repoTokens: Record<string, string>,
  globalToken: string,
): string {
  if (!repo) return globalToken;
  const lower = repo.toLowerCase();
  for (const [k, v] of Object.entries(repoTokens)) {
    if (v && k.toLowerCase() === lower) return v;
  }
  return globalToken;
}

// Live GitHub → Repo Pulse data (#413). PURE mappers from GitHub REST payloads to
// the typed Pulse shapes (data/repoPulse.ts) — no fleet inference, just what the
// API returns. The fetch orchestration lives in hooks/useRepoPulse.ts; these
// functions are framework-free and unit-tested with payload fixtures.
//
// Bot vs human is GitHub's own signal (account `type === "Bot"` / `[bot]` login),
// NOT fleet-agent attribution (that's the Fleet page, #412).

import type {
  VelocitySlice, ChurnArea, ChurnFile, Contributor, Workflow, Branch, BranchStatusKey,
} from "@/shared/data/repoPulse";
import { dayWindow, windowedTally, type DayWindow } from "@/shared/lib/algorithms/windowedTally";
import { loginColor } from "@/shared/lib/core/format";

// ── GitHub payload shapes (subset of the fields we use) ──────────────────────
export interface GhAccount { login: string; type?: string }
export interface GhCommitItem {
  sha: string;
  commit: { message: string; author: { name: string; date: string } | null };
  author: GhAccount | null;
}
export interface GhCommitFile { filename: string; additions: number; deletions: number; changes: number; status?: string }
export interface GhCommitDetail extends GhCommitItem {
  stats?: { additions: number; deletions: number; total: number };
  files?: GhCommitFile[];
}
export interface GhPull {
  number: number;
  title: string;
  user: GhAccount | null;
  created_at: string;
  merged_at: string | null;
  draft: boolean;
  state: string;
  head: { ref: string };
}
export interface GhBranchItem { name: string; commit: { sha: string } }
export interface GhWorkflowItem { id: number; name: string; path: string; state: string }
export interface GhRun {
  id: number; name: string; conclusion: string | null; status: string;
  created_at: string; updated_at: string; workflow_id: number;
}
export interface GhCompare { ahead_by: number; behind_by: number }

// ── bot detection (GitHub's own signal) ──────────────────────────────────────
export function isBot(acct: GhAccount | null, fallbackName = ""): boolean {
  const login = acct?.login ?? fallbackName;
  return acct?.type === "Bot" || /\[bot\]$/i.test(login);
}

// ── day bucketing ─────────────────────────────────────────────────────────────
// Both live in `shared/lib/algorithms/windowedTally` since #3465 — the generic, dependency-free
// version the algorithms graph also ships as a node. Re-exported here so this module's long-standing
// public surface (and `repoPulseLive.test.ts`) is unchanged; there is one implementation, not two.
export { dayWindow, tallyByDay, type DayWindow } from "@/shared/lib/algorithms/windowedTally";
/** Sum values bucketed by their day — the SUM counterpart to `tallyByDay`'s count. Kept here because it
 *  aggregates a per-event value, not timestamps, so it is not the same algorithm as the shared tally. */
export function sumByDay(win: DayWindow, entries: Array<{ date: string; value: number }>): number[] {
  const idx = new Map(win.keys.map((k, i) => [k, i]));
  const out = new Array(win.keys.length).fill(0);
  for (const e of entries) {
    const i = idx.get(e.date.slice(0, 10));
    if (i !== undefined) out[i] += e.value;
  }
  return out;
}

// ── velocity (commits + PRs per day) ──────────────────────────────────────────
export function mapVelocity(
  commits: GhCommitItem[], pulls: GhPull[], details: GhCommitDetail[], days: number, now: Date,
): VelocitySlice {
  // The three COUNT series share one window (#3465) — that is what makes them aligned by construction
  // rather than by three separate calls happening to agree.
  const { labels, series } = windowedTally(
    {
      commits: commits.map(c => c.commit.author?.date),
      opened: pulls.map(p => p.created_at),
      merged: pulls.map(p => p.merged_at),
    },
    days,
    now,
  );
  // adds/dels are SUMS of a per-event value, not counts, so they keep `sumByDay` over the same window.
  const win = dayWindow(days, now);
  const adds = sumByDay(win, details.flatMap(d => d.commit.author?.date && d.stats ? [{ date: d.commit.author.date, value: d.stats.additions }] : []));
  const dels = sumByDay(win, details.flatMap(d => d.commit.author?.date && d.stats ? [{ date: d.commit.author.date, value: d.stats.deletions }] : []));
  return { labels, commits: series.commits, opened: series.opened, merged: series.merged, adds, dels };
}

// ── churn by top-level area + hottest files (from bounded commit details) ─────
/** Group a file path into a display "area": `crates/<x>` two deep, else `<top>/`. */
export function areaOf(path: string): string {
  const seg = path.split("/");
  if (seg[0] === "crates" && seg.length > 1) return `crates/${seg[1]}`;
  if (seg.length > 1) return `${seg[0]}/`;
  return "(root)";
}
const AREA_COLORS = ["var(--accent)", "var(--info)", "var(--success)", "oklch(0.7 0.12 290)", "oklch(0.7 0.06 90)", "var(--fg-dim)"];

export function mapChurnAreas(details: GhCommitDetail[]): ChurnArea[] {
  const acc = new Map<string, { add: number; del: number; files: Set<string> }>();
  for (const d of details) for (const f of d.files ?? []) {
    const a = areaOf(f.filename);
    const e = acc.get(a) ?? { add: 0, del: 0, files: new Set<string>() };
    e.add += f.additions; e.del += f.deletions; e.files.add(f.filename);
    acc.set(a, e);
  }
  return [...acc.entries()]
    .map(([area, e]) => ({ area, add: e.add, del: e.del, files: e.files.size, color: "" }))
    .sort((a, b) => (b.add + b.del) - (a.add + a.del))
    .slice(0, 6)
    .map((a, i) => ({ ...a, color: AREA_COLORS[i % AREA_COLORS.length] }));
}

export function mapHottestFiles(details: GhCommitDetail[], topN = 16): ChurnFile[] {
  const acc = new Map<string, number>();
  for (const d of details) for (const f of d.files ?? []) {
    acc.set(f.filename, (acc.get(f.filename) ?? 0) + f.additions + f.deletions);
  }
  return [...acc.entries()]
    .map(([p, w]) => ({ p, w }))
    .sort((a, b) => b.w - a.w)
    .slice(0, topN);
}

// ── contributors (bot vs human, GitHub-attributed) ───────────────────────────
export function mapContributors(commits: GhCommitItem[], details: GhCommitDetail[]): Contributor[] {
  const acc = new Map<string, { bot: boolean; commits: number; add: number; del: number }>();
  const keyOf = (c: GhCommitItem) => c.author?.login ?? c.commit.author?.name ?? "unknown";
  for (const c of commits) {
    const k = keyOf(c);
    const e = acc.get(k) ?? { bot: isBot(c.author, c.commit.author?.name), commits: 0, add: 0, del: 0 };
    e.commits += 1;
    acc.set(k, e);
  }
  for (const d of details) {
    const k = keyOf(d);
    const e = acc.get(k);
    if (e && d.stats) { e.add += d.stats.additions; e.del += d.stats.deletions; }
  }
  return [...acc.entries()]
    .map(([name, e]) => ({ name, bot: e.bot, commits: e.commits, add: e.add, del: e.del, color: e.bot ? "var(--accent)" : loginColor(name) }))
    .sort((a, b) => b.commits - a.commits);
}

// ── CI health + per-workflow pass rate ────────────────────────────────────────
export interface CiHealth { passRate: number; runs: number; passed: number; failed: number; cancelled: number; avgMin: number }
const FAIL = new Set(["failure", "timed_out", "startup_failure"]);
export function mapCI(runs: GhRun[], workflows: GhWorkflowItem[]): { ci: CiHealth; workflows: Workflow[] } {
  const done = runs.filter(r => r.status === "completed");
  const passed = done.filter(r => r.conclusion === "success").length;
  const failed = done.filter(r => r.conclusion && FAIL.has(r.conclusion)).length;
  const cancelled = done.filter(r => r.conclusion === "cancelled").length;
  const decisive = passed + failed;
  const durMin = (r: GhRun) => (new Date(r.updated_at).getTime() - new Date(r.created_at).getTime()) / 60000;
  const avgMin = done.length ? round1(done.reduce((s, r) => s + durMin(r), 0) / done.length) : 0;
  const ci: CiHealth = {
    passRate: decisive ? Math.round((passed / decisive) * 100) : 0,
    runs: done.length, passed, failed, cancelled, avgMin,
  };
  const byWf = new Map<number, { name: string; runs: number; pass: number; mins: number[] }>();
  const wfName = new Map(workflows.map(w => [w.id, w.name]));
  for (const r of done) {
    const w = byWf.get(r.workflow_id) ?? { name: wfName.get(r.workflow_id) ?? r.name, runs: 0, pass: 0, mins: [] };
    w.runs += 1;
    if (r.conclusion === "success") w.pass += 1;
    w.mins.push(durMin(r));
    byWf.set(r.workflow_id, w);
  }
  const wf: Workflow[] = [...byWf.values()]
    .map(w => ({ name: w.name, runs: w.runs, pass: w.runs ? Math.round((w.pass / w.runs) * 100) : 0, min: w.mins.length ? round1(w.mins.reduce((a, b) => a + b, 0) / w.mins.length) : 0 }))
    .sort((a, b) => b.runs - a.runs);
  return { ci, workflows: wf };
}
function round1(n: number): number { return Math.round(n * 10) / 10; }

// ── review latency (merged PR open→merge) ─────────────────────────────────────
export function mapReviewLatency(pulls: GhPull[]): Array<{ label: string; v: number }> {
  const buckets = [
    { label: "<30m", v: 0 }, { label: "30m–1h", v: 0 }, { label: "1–3h", v: 0 },
    { label: "3–8h", v: 0 }, { label: "8h+", v: 0 },
  ];
  for (const p of pulls) {
    if (!p.merged_at) continue;
    const h = (new Date(p.merged_at).getTime() - new Date(p.created_at).getTime()) / 3_600_000;
    const i = h < 0.5 ? 0 : h < 1 ? 1 : h < 3 ? 2 : h < 8 ? 3 : 4;
    buckets[i].v += 1;
  }
  return buckets;
}
/** Median merge latency (hours) over merged PRs, or 0. */
export function medianLatencyH(pulls: GhPull[]): number {
  const hs = pulls.filter(p => p.merged_at)
    .map(p => (new Date(p.merged_at as string).getTime() - new Date(p.created_at).getTime()) / 3_600_000)
    .sort((a, b) => a - b);
  if (!hs.length) return 0;
  const mid = Math.floor(hs.length / 2);
  return round1(hs.length % 2 ? hs[mid] : (hs[mid - 1] + hs[mid]) / 2);
}

// ── active branches ───────────────────────────────────────────────────────────
const BRANCH_COLORS = ["var(--accent)", "var(--info)", "var(--success)", "oklch(0.7 0.12 290)", "oklch(0.7 0.06 90)", "var(--fg-dim)"];
export function mapBranches(
  branches: GhBranchItem[], pulls: GhPull[], compares: Record<string, GhCompare>, defaultBranch: string,
): Branch[] {
  const prByRef = new Map<string, GhPull>();
  for (const p of pulls) if (p.state === "open" && !prByRef.has(p.head.ref)) prByRef.set(p.head.ref, p);
  return branches.map((b, i) => {
    const pr = prByRef.get(b.name);
    const cmp = compares[b.name];
    const owner = pr?.user?.login ?? "";
    const status: BranchStatusKey =
      b.name === defaultBranch ? "integration"
      : pr ? (pr.draft ? "draft" : "open-pr")
      : "commit-only";
    return {
      n: b.name, owner, bot: isBot(pr?.user ?? null),
      ahead: cmp?.ahead_by ?? 0, behind: cmp?.behind_by ?? 0,
      status, age: "", color: BRANCH_COLORS[i % BRANCH_COLORS.length],
    };
  });
}

// ── KPIs ──────────────────────────────────────────────────────────────────────
export interface PulseKpis {
  commitsWeek: number; prsMerged: number; netLines: number; passRate: number;
  reviewLatencyH: number; contributors: number; botShare: number;
}
export function deriveKpis(
  velocity: VelocitySlice, ci: CiHealth, pulls: GhPull[], contributors: Contributor[], now: Date,
): PulseKpis {
  // Last-7-day slices of the (up to 14-day) velocity series.
  const last7 = <T,>(a: T[]) => a.slice(-7);
  const sum = (a: number[]) => a.reduce((s, v) => s + v, 0);
  const within7 = (iso: string | null) => !!iso && (now.getTime() - new Date(iso).getTime()) <= 7 * 86_400_000;
  const botCommits = contributors.filter(c => c.bot).reduce((s, c) => s + c.commits, 0);
  const allCommits = contributors.reduce((s, c) => s + c.commits, 0);
  return {
    commitsWeek: sum(last7(velocity.commits)),
    prsMerged: pulls.filter(p => within7(p.merged_at)).length,
    netLines: sum(last7(velocity.adds)) - sum(last7(velocity.dels)),
    passRate: ci.passRate,
    reviewLatencyH: medianLatencyH(pulls.filter(p => within7(p.merged_at))),
    contributors: contributors.length,
    botShare: allCommits ? Math.round((botCommits / allCommits) * 100) : 0,
  };
}

