// RequestSessionsMount (#one-request-one-debug-session) — one debug session per request, bound to it.
//
// Each cycle: CLAIM every open request (atomically, one `bsc request claim` per request), then hold one
// session per claimed request, named for it (`debug-studio:req-<id>`), and close each when ITS request
// resolves. There is no pool, no cap, no pacing and no reaper — see `poolPlan.ts` for what each of those
// was for and why 1:1 removes the need.
//
// WHY THE MOUNT CLAIMS, rather than the session. `bsc request claim` takes the OLDEST open request; it
// cannot be pointed at a specific id. So the only way to bind a session to a KNOWN request is to claim
// first and spawn for whatever came back. That the claim is atomic is what makes this safe beside the
// standing debug session, which self-serves the same queue: whoever claims first holds it, and the other
// simply never sees it as open. No charter change was needed there, and none was made.
//
// It obeys a plan and decides nothing: `planRequestSessions` owns the gate and the reconcile. This mount
// is mechanics — claim, apply the plan (seed each session's charter, close finished ones, publish the
// live ids for the Glance graph).
//
// ── WHAT MAKES THIS SAFE TO SHIP ────────────────────────────────────────────────────────────────────
//  * UNCONDITIONAL (#debug-nodes-hang-off-the-session-that-filed-them) — the `autoSpawnDebugSessions`
//    toggle is gone. It defaulted OFF, which shipped this whole 1:1 machinery switched off: a request
//    was filed and then waited for someone to notice. The one remaining gate is not a preference —
//    `debug_repo_root` must resolve, because a shipped binary with no source tree cannot run these.
//  * EVERY session is a VISIBLE NODE in the Glance graph, labelled with its request and edged to the
//    session that filed it. That is what makes an app-started session supervisable: the user can see
//    it, open it, and stop it. It is the reason the ids are published below.
//  * The only role it can start is the plan's — `debugger` — and every pane is under the
//    `debug-studio:` prefix, so it is full-capability + role-less (#3520).
//  * Sessions launch FRESH (`claude`, never `--continue`) with `paneContinue: false` (#3497): each is
//    bound to one request and must never inherit another conversation.
//  * NOT bounded by a cap any more — a deliberate trade, recorded in `poolPlan.ts`. Concurrency is the
//    number of unresolved claimed requests.
import { useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { fireInvoke, safeInvoke } from "@/shared/lib/core/safeInvoke";
import { usePoll } from "@/shared/hooks/usePoll";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { planRequestSessions, type RequestSession, type RequestRow } from "@/shared/lib/session/poolPlan";
import { requestPaneId, requestIdFromPaneId } from "@/shared/lib/session/requestSpawn";
import { requestCharter, DEBUG_INIT_CMD } from "@/features/debug/requestSession";

/** How often to reconcile against the queue. Slow on purpose: a request is not urgent, and a session
 *  that is already working one is not waiting on this loop. */
const POLL_MS = 20_000;

/** One pane's runtime state, as `pty_pane_runtime` answers (Rust `PaneRuntime`, camelCase on the wire).
 *  Only `live` is read here — "is there a PTY session for this pane" — which is exactly the question
 *  `pty_create` would answer with RECONNECT rather than launch. */
interface PaneRuntime {
  paneId: string;
  live: boolean;
}

/** A raw row from `bsc request list --json` (snake_case from the Rust store). */
interface RawRequest {
  id: number;
  status: string;
  claimed_by?: string | null;
  /** WHO filed it (#debug-request-carries-its-origin) — the MERGED field, holding either a pane id or
   *  a free-text actor. Carried through to the charter so the spawned session knows whose workflow it
   *  is unblocking. Prefer `origin_pane` for anything that needs a SESSION. */
  origin?: string | null;
  /** The filing session's pane id specifically (`a-request-records-where-it-actually-came-from`) — the
   *  only value known to name a node, so it is what the Glance edge is drawn from. */
  origin_pane?: string | null;
  /** WHAT KIND the store classified the origin as — `pane` · `actor` · `both` · `unknown` · `absent`.
   *  Passed to the graph so the reader never re-derives it from the string's shape, which is how a
   *  shell filing by `lane-c4` used to be mistaken for a session belonging to another drill. */
  origin_kind?: string | null;
  /** Always populated by the store (explicit `--title`, else derived from the text). */
  display_title?: string | null;
  /** The branch a `land` named, for the app to merge. Present only while `landed`. */
  landed_branch?: string | null;
}

/** What `land_request_branch` answers (Rust `LandOutcome`, camelCase on the wire). */
interface LandOutcome {
  merged: boolean;
  detail: string;
  cleanedUp: boolean;
}

/**
 * Holds one session per open request. Renders nothing visible; each session's terminal is shown by
 * opening its node in the Glance graph.
 */
export function RequestSessionsMount() {
  // undefined = still resolving; null = no source tree (shipped binary — never launch into a missing
  // cwd); string = the repo root these sessions work in.
  const [repoRoot, setRepoRoot] = useState<string | null | undefined>(undefined);
  // The request sessions this mount tracks. Kept in a ref too so the poll reconciles against the latest
  // set without re-subscribing the interval (the ref is synced in an effect, never during render).
  const [sessions, setSessions] = useState<RequestSession[]>([]);
  const sessionsRef = useRef<RequestSession[]>([]);
  useEffect(() => { sessionsRef.current = sessions; }, [sessions]);
  // The last queue read, kept so the published node specs carry each request's origin + title.
  const [rows, setRows] = useState<RawRequest[]>([]);

  useEffect(() => {
    let alive = true;
    void safeInvoke<string | null>("debug_repo_root", undefined, null, () => {}).then((root) => {
      if (alive) setRepoRoot(root);
    });
    return () => { alive = false; };
  }, []);

  // #3522: review the queue ONCE per app start and drop completed (resolved) requests, so a long-dead
  // row cannot linger as a node. Keyed to mount rather than to a toggle transition (there is no toggle
  // any more) and never to the poll; `bscRun` is fire-and-forget (a missing binary is a no-op).
  useEffect(() => { void bscRun(null, ["request", "prune"]); }, []);

  // The reconcile loop, once per poll. `bscJson`/`bscRun` swallow a missing binary or verb and return the
  // fallback, so a machine without a working `bsc` simply never spawns rather than erroring in a loop.
  usePoll(
    // `isCancelled` is read by the LANDING pass below: it merges, rebuilds and injects across several
    // awaits, and a workspace change mid-flight must not go on driving a torn-down mount.
    async (isCancelled) => {
      if (!repoRoot) return;

      // 1 — CLAIM every open request, one atomic claim each, so that by the time the plan runs each has
      // a definite id to be bound to. Bounded by the open count read first, so a request the claim loop
      // itself creates could never spin it.
      //
      // NO `--by`. It stamps the holder at claim time, and the holder here is a pane named FOR the
      // request the claim is about to return — the id is not known until after. Nothing needs the stamp:
      // the binding is the pane name (`requestIdFromPaneId`), which is derived rather than recorded and
      // so cannot go stale. A `null` claim means the queue drained under us (the standing debug session
      // took the last one), which is exactly the race the atomic claim exists to make safe.
      // THE OFF SWITCH (`auto-spawn-has-no-off-switch`), read BEFORE the claim loop and not after it.
      //
      // Order is the whole correctness of this. Claiming is the side effect that turns `open` into
      // `claimed`, and `claimed` is what gets a session — so reading the flag after claiming would
      // leave the queue permanently altered by a cycle that then started nothing. That is a "pause"
      // which still takes work off the open queue, which is worse than not pausing. A paused cycle
      // therefore claims NOTHING and plans with `enabled: false`, which also closes the sessions
      // already running.
      //
      // Degrades to NOT paused, matching the store: a pause has to have been asked for to be true, and
      // a failed read must never silently stop the debug fleet.
      // ONE READ ANSWERS BOTH SWITCHES. `bsc request sessions --json` resolves the precedence — a
      // global policy outranks a transient pause — and hands back `allowed`, so this side combines
      // nothing and cannot drift from the rule. Two booleans combined by every caller is how the two
      // levels of the model precedence chain drifted apart earlier today.
      //
      // Degrades to ALLOWED, matching both stores: a failed read must never silently stop the debug
      // fleet, and neither switch is true unless someone set it.
      const gate = await bscJson<{ allowed: boolean }>(
        null,
        ["request", "sessions", "--json"],
        { allowed: true },
      );
      const paused = !gate.allowed;

      const open = paused
        ? []
        : (await bscJson<RawRequest[]>(null, ["request", "list", "--json"], [])).filter(
            (r) => r.status === "open",
          );
      for (let i = 0; i < open.length; i += 1) {
        const claimed = await bscJson<RawRequest | null>(null, ["request", "claim", "--json"], null);
        if (!claimed) break;
      }

      // 2 — PLAN + APPLY against the post-claim queue.
      const raw = await bscJson<RawRequest[]>(null, ["request", "list", "--json"], []);
      const requests: RequestRow[] = raw.map((r) => ({ id: r.id, status: r.status, claimedBy: r.claimed_by ?? null }));

      // THE LIVE SET IS DERIVED, NEVER REMEMBERED (#a-resolved-requests-debug-session-is-never-closed).
      //
      // `sessionsRef` is React state seeded `[]`, so it is empty after every remount — and `close` is
      // computed only from what it is handed. That made closing IMPOSSIBLE across a workspace change or
      // an app restart: the plan saw no sessions, closed nothing, and each orphan kept a `claude`
      // process running for good. It also silently disabled the `reload_sidecars` below, which fires on
      // close and is what makes a debugger's `bsc` fix live without a manual restart.
      //
      // The binding was never in doubt — the pane NAME encodes the request id — so the live set can be
      // rebuilt from the queue every poll and cannot go stale. `sessionsRef` is still unioned in as a
      // CANDIDATE, because a request removed from the list outright (`bsc request remove`, or the prune
      // above) yields no pane name to ask about, and the remembered set is the only thing that can still
      // name that one. It is a candidate, not an answer: everything here is filtered by real liveness.
      const candidates = [
        ...new Set([...raw.map((r) => requestPaneId(r.id)), ...sessionsRef.current.map((s) => s.paneId)]),
      ];
      const runtime = await safeInvoke<PaneRuntime[]>("pty_pane_runtime", { paneIds: candidates }, []);
      const live: RequestSession[] = runtime.filter((p) => p.live).map((p) => ({ paneId: p.paneId }));

      // 2a — LAND anything the debug session says is ready (#a-debug-session-strands-its-work).
      //
      // The session cannot merge its own branch: git refuses to check out `develop` in a second
      // worktree, and a debug session lives in one. So it names the branch and this does the merge,
      // the teardown, and the hand-off to the session that FILED the request — the only one that can
      // say whether its own workflow is unblocked.
      //
      // Sequential, not `Promise.all`: every landing merges into the same branch in the same tree, so
      // two at once would race on the index and the second would refuse on a dirty tree it caused.
      for (const r of raw.filter((x) => x.status === "landed")) {
        const outcome = await safeInvoke<LandOutcome | null>(
          "land_request_branch",
          { branch: r.landed_branch ?? "" },
          null,
        );
        if (isCancelled() || !outcome) continue;
        // The outcome goes on the THREAD either way — a refusal the debug session cannot read is a
        // request that silently stops moving, which is the failure this whole loop exists to remove.
        await bscRun(null, ["request", "note", String(r.id), outcome.detail, "--from", "app"]);
        if (!outcome.merged) {
          // Back to its own session, branch cleared. Not `resolved` (the fix is incomplete) and not
          // left `landed` (it would retry the same refusal every poll).
          await bscRun(null, ["request", "unland", String(r.id)]);
          continue;
        }
        // The merge is in develop; make it LIVE before asking anyone to test it, or the filer verifies
        // the old binary and reports a failure the fix already addressed.
        await safeInvoke<[string, string | null][]>("reload_sidecars", undefined, [], () => {});
        // The ask goes on the THREAD, not into the filer's stdin.
        //
        // Injecting it would be an app-initiated `injectPrompt`, and `injectCallers.test.ts` keeps that
        // set deliberately EMPTY (#app-stops-pushing-prompts): "injectPrompt now has NO callers at all,
        // which is a stronger boundary than a one-entry allow-list — there is nothing to argue onto."
        // `injectRedirect` survives only as a USER click. An app poll pushing a prompt into a session
        // is exactly what that boundary removed, so this records the ask durably instead and leaves
        // WAKING the filer to be decided rather than assumed.
        const filer = r.origin?.trim();
        await bscRun(null, [
          "request",
          "note",
          String(r.id),
          `@${filer ?? "filer"} — the fix you filed has landed: ${outcome.detail}. ` +
            `Re-run the command that failed, then report: ` +
            `\`bsc request verify ${r.id} --ok --note "<what you saw>"\` if the gap is gone, or ` +
            `\`bsc request verify ${r.id} --fail --note "<what still fails>"\` to hand it back. ` +
            `You are the only session that can tell — it was your workflow that hit this.`,
          "--from",
          "app",
        ]);
        // Only now is it awaiting a verdict. Flipping before the ask would leave a request waiting on
        // a verification nobody was asked for.
        await bscRun(null, ["request", "verifying", String(r.id)]);
      }
      if (isCancelled()) return;

      const plan = planRequestSessions({ requests, sessions: live, enabled: !paused });

      // STOP IT, don't just stop RENDERING it. Dropping a pane from `sessions` unmounts its
      // `TerminalSlot`, and `TerminalView`'s cleanup deliberately leaves the backend PTY alive so a
      // console tab-switch reconnects rather than respawns (`useStudioReaper` documents the same trap and
      // issues the same explicit kill). So the unmount only ever reclaimed the xterm: the `claude`
      // process under a finished request went on running with nothing on screen to show for it.
      for (const paneId of plan.close) fireInvoke("pty_kill", { paneId }, console.error);

      // Free the store fields of every closed pane, so a stopped session leaves nothing behind.
      if (plan.close.length) {
        useAppStore.setState((st) => {
          const prompts = { ...st.paneStartupPromptText };
          const cont = { ...st.paneContinue };
          for (const paneId of plan.close) { delete prompts[paneId]; delete cont[paneId]; }
          return { paneStartupPromptText: prompts, paneContinue: cont };
        });
      }

      // A CLOSE means a request just resolved, and a resolved `bsc` request means the session very
      // likely rebuilt the binary. Re-stage it and retire the warm child so the fix is LIVE for the next
      // `bsc` call — the last mile of "a designer's request gets processed live", which without this
      // ends in a manual app restart no matter how fast the fix was.
      //
      // Fire-and-forget: a failed reload must not stop the mount reconciling. It is also safe to call
      // when nothing was rebuilt (staging is an idempotent copy) and in a release bundle (a no-op), so
      // it does not need to know WHY the session closed.
      if (plan.close.length) {
        void safeInvoke<[string, string | null][]>("reload_sidecars", undefined, [], () => {});
      }

      if (plan.start.length) {
        // The rows by id, so the charter can name the request and the session that filed it
        // (#debug-request-carries-its-origin). Read from `raw` — the post-claim list — because that is
        // the read that already happened; a session started without its origin would be told nothing
        // about whose workflow it is unblocking, and the relationship would exist only in the graph.
        const byId = new Map(raw.map((r) => [r.id, r]));
        // Seed the launch fields TerminalView reads: the charter naming THIS request (baked as
        // --initial-message) and paneContinue=false (#3497 — never resume; each session is bound to one
        // request and must not inherit another conversation).
        useAppStore.setState((st) => {
          const prompts = { ...st.paneStartupPromptText };
          const cont = { ...st.paneContinue };
          for (const id of plan.start) {
            const row = byId.get(id);
            prompts[requestPaneId(id)] = requestCharter({
              id,
              origin: row?.origin ?? null,
              display_title: row?.display_title ?? null,
            });
            cont[requestPaneId(id)] = false;
          }
          return { paneStartupPromptText: prompts, paneContinue: cont };
        });
      }
      setSessions([...plan.sessions, ...plan.start.map((id) => ({ paneId: requestPaneId(id) }))]);
      // Publish the ROWS, not just the ids (#debug-nodes-hang-off-the-session-that-filed-them): the
      // graph needs each request's origin and title to label its node and edge it to the session that
      // filed it, and this poll is the only place that already holds them.
      setRows(raw);
    },
    POLL_MS,
    [repoRoot],
  );

  // Publish the live REQUESTS so the Glance graph can render a node per request. Without this the
  // sessions run with no node — unopenable, unsupervisable, unstoppable.
  //
  // The published value carries the ORIGIN and TITLE alongside the id
  // (#debug-nodes-hang-off-the-session-that-filed-them), because the node is labelled `debug - <title>`
  // and edged to the session that filed it. A bare id could do neither, which is why every request node
  // used to be called `debugger-req-<n>` and drawn to the designer regardless of who actually filed it.
  const setActiveDebugRequests = useAppStore((s) => s.setActiveDebugRequests);
  useEffect(() => {
    const live = new Map(rows.map((r) => [r.id, r]));
    setActiveDebugRequests(
      sessions
        .map((s) => requestIdFromPaneId(s.paneId))
        .filter((n): n is number => n != null)
        .map((id) => ({
          id,
          origin: live.get(id)?.origin ?? null,
          // The store's own classification travels with the row
          // (`a-request-records-where-it-actually-came-from`), so the graph edges to a real session and
          // draws an actor-filed request unparented instead of omitting it from every graph.
          originPane: live.get(id)?.origin_pane ?? null,
          originKind: live.get(id)?.origin_kind ?? null,
          title: live.get(id)?.display_title ?? null,
        })),
    );
  }, [sessions, rows, setActiveDebugRequests]);

  // The charter for a pane, built from the rows this poll already read, so it travels as a PROP beside
  // `initCmd` (`a-debug-session-launches-with-no-charter`). The store write above stays — it is what a
  // pane seeded by any other route reads — but the prop is what makes the launch correct regardless of
  // when that write lands, because a prop cannot be missed by a one-shot read.
  const charterFor = (paneId: string): string | undefined => {
    const id = requestIdFromPaneId(paneId);
    if (id == null) return undefined;
    const row = rows.find((r) => r.id === id);
    return requestCharter({ id, origin: row?.origin ?? null, display_title: row?.display_title ?? null });
  };

  if (!repoRoot || !sessions.length) return null;
  return (
    <Box
      aria-hidden
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {sessions.map((s) => (
        <TerminalSlot
          key={s.paneId}
          paneId={s.paneId}
          primary
          parked
          visible={false}
          initialCwd={repoRoot}
          initCmd={DEBUG_INIT_CMD}
          startupPrompt={charterFor(s.paneId)}
        />
      ))}
    </Box>
  );
}

tests.src:
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { cleanup, render, waitFor } from "@testing-library/react";
import { RequestSessionsMount } from "@/features/debug/RequestSessionsMount";
import { requestCharter, requestPaneId, originLabel } from "@/features/debug/requestSession";
import { bscRun } from "@/shared/lib/core/bsc";
import { fireInvoke, safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { designerSessionId, librarianSessionId, SOUND_STUDIO_SESSION_ID } from "@/shared/lib/session/systemSessions";

// `vi.hoisted` because vi.mock is hoisted ABOVE plain consts: referencing a normal `const` from a mock
// factory throws "Cannot access before initialization" the moment anything calls the mock early (the
// store does, at init). The tests still passed green while that rejection fired — exactly the kind of
// green-but-throwing suite worth not shipping.
const { queue, resetQueue, ptys, invokeImpl } = vi.hoisted(() => {
  const queue: {
    rows: {
      id: number;
      status: string;
      claimed_by: string | null;
      origin: string | null;
      origin_pane?: string | null;
      origin_kind?: string | null;
      display_title: string;
    }[];
  } = { rows: [] };
  // The app's PTY session map, as `pty_pane_runtime` reports it. The mount must reconcile against THIS
  // rather than against anything it remembers — a session outlives the component that started it, which
  // is the whole of `a-resolved-requests-debug-session-is-never-closed`.
  const ptys: { live: Set<string> } = { live: new Set() };
  const resetQueue = () => {
    queue.rows = [
      { id: 1, status: "open", claimed_by: null, origin: "design-studio:designer-react", origin_pane: "design-studio:designer-react", origin_kind: "pane", display_title: "ui list needs --kit" },
      { id: 2, status: "open", claimed_by: null, origin: "algorithms-studio:librarian-typescript", origin_pane: "algorithms-studio:librarian-typescript", origin_kind: "pane", display_title: "impl list needs --domain" },
    ];
    ptys.live = new Set();
  };
  resetQueue();
  // Hoisted WITH the state it reads. Declared as a plain const it would be referenced by the hoisted
  // `vi.mock` factory before initialization — the same trap this file's header already documents.
  const invokeImpl = async (cmd: string, payload?: unknown) => {
    if (cmd === "reload_sidecars") return [];
    if (cmd === "pty_pane_runtime") {
      const ids = (payload as { paneIds?: string[] } | undefined)?.paneIds ?? [];
      return ids.map((paneId) => ({ paneId, live: ptys.live.has(paneId) }));
    }
    return "C:/repo";
  };
  return { queue, resetQueue, ptys, invokeImpl };
});

// The queue read, the repo-root probe and the terminal itself are all external systems; stub them so the
// PLAN (which requests get a session) is what the test observes. Mock EVERY export, not just the one
// under test: the store also calls into this module, and a partial mock leaves the rest `undefined`,
// which throws asynchronously while the tests still pass green.
//
// `bscJson` is ARGS-AWARE, and that is load-bearing rather than fussy. The mount now CLAIMS before it
// plans, so a mock that returns the same list for every call would leave every request `open` forever
// and the plan would correctly start nothing — a green suite proving the opposite of the feature. This
// models the real contract: `claim` flips the oldest open row and returns it, atomically.
vi.mock("@/shared/lib/core/bsc", () => ({
  bscJson: vi.fn(async (_cwd: unknown, args: string[]) => {
    // THE GATE, args-aware like the rest: `bsc request sessions --json` resolves the global policy
    // AND the pause in Rust and hands back `allowed`. A blanket return would have answered this with
    // the row list, leaving `allowed` undefined — which reads as CLOSED and silently starts nothing,
    // exactly the failure this mock's own header warns about.
    if (args[1] === "sessions") {
      return { enabled: true, paused: false, allowed: true };
    }
    if (args[1] === "claim") {
      const next = queue.rows.find((r) => r.status === "open");
      if (!next) return null;
      next.status = "claimed";
      return next;
    }
    return queue.rows;
  }),
  bsc: vi.fn(async () => ""),
  bscRun: vi.fn(async () => {}),
  bscWrite: vi.fn(async () => {}),
}));
// `safeInvoke` serves THREE calls here — the repo-root probe, the liveness read and the sidecar reload —
// so the mock dispatches on the command name. A single blanket return would answer the reload with a path
// and the repo-root probe with whatever the reload wanted, which is how a mock starts lying quietly.
// (`pty_pane_runtime` is the one that would break loudest: a bare string has no `.filter`.)
vi.mock("@/shared/lib/core/safeInvoke", () => ({
  safeInvoke: vi.fn(invokeImpl),
  // The kill is fire-and-forget, so it is a DIFFERENT export — mocking only `safeInvoke` would leave
  // `fireInvoke` undefined and the mount would throw asynchronously while the suite stayed green.
  fireInvoke: vi.fn((cmd: string, payload?: { paneId?: string }) => {
    if (cmd === "pty_kill" && payload?.paneId) ptys.live.delete(payload.paneId);
  }),
}));
// The slot stands in for the real one, and the real one CREATES THE PTY. Registering the pane here is
// what makes `pty_pane_runtime` above answer truthfully on the next poll — without it every session
// would read as dead one tick after it started, and the mount would re-charter it forever.
vi.mock("@/app/console/terminal/TerminalSlot", () => ({
  TerminalSlot: ({ paneId }: { paneId: string }) => {
    ptys.live.add(paneId);
    return null;
  },
}));
// Run the poll body once, deterministically, instead of on a timer.
// The REAL usePoll hands its callback an isCancelled: () => boolean. Calling fn() with nothing worked
// only while no caller read it; the landing pass does, so an under-specified mock made every test here
// fail with no session launched at all. A mock must honour the contract it stands in for.
vi.mock("@/shared/hooks/usePoll", () => ({
  usePoll: (fn: (isCancelled: () => boolean) => void | Promise<void>) => { void fn(() => false); },
}));

// Unmount every rendered component between tests. Without it, a prior test's RequestSessionsMount stays
// mounted and subscribed to the store, so a later test also drives the stale instances — which was
// masking a mutation of the prune guard in the full run (#3522). The gate runs the full file.
afterEach(cleanup);

// #3836: every describe below must start from the SAME state — otherwise a shuffled order lets one
// block inherit another's sessions + seeded prompts and measure something different.
const resetAll = () => {
  resetQueue();
  // RE-INSTALL the default safeInvoke behaviour. One test overrides it to simulate a machine with no
  // source tree, and `mockImplementation` persists for the whole FILE — so without this reset every
  // later test silently ran against a null repo root and asserted nothing spawning, which is a green
  // suite proving the opposite of the feature.
  vi.mocked(safeInvoke).mockImplementation(invokeImpl as never);
  vi.mocked(fireInvoke).mockClear();
  useAppStore.setState({ paneContinue: {}, paneStartupPromptText: {}, activeDebugRequests: [] });
};

describe("RequestSessionsMount — one session per request", () => {
  beforeEach(resetAll);

  // #debug-nodes-hang-off-the-session-that-filed-them: there is NO toggle any more. The test that used
  // to live here asserted the off-by-default behaviour, which WAS the bug — the whole 1:1 machinery
  // shipped switched off, so a filed request waited for someone to notice. What replaces it is the one
  // gate that is not a preference: a machine with no source tree cannot run these at all.
  it("spawns nothing when there is no source tree — a shipped binary, not a preference", async () => {
    vi.mocked(safeInvoke).mockImplementation(async (cmd: string) => (cmd === "reload_sidecars" ? [] : null));
    const { container } = render(<RequestSessionsMount />);
    await new Promise((r) => setTimeout(r, 0));
    expect(useAppStore.getState().paneStartupPromptText).toEqual({});
    expect(container).toBeEmptyDOMElement();
  });

  it("spawns one session per request — BOTH, in the same cycle", async () => {
    // The pool deliberately started one per cycle to pace growth toward a cap. 1:1 has no cap and so
    // nothing to pace against; staggering would only make the queue drain slower. This is the assertion
    // that would have failed under the old model, so it is the one that pins the change.
    render(<RequestSessionsMount />);
    // BOTH assertions inside ONE waitFor, because they are published by DIFFERENT effects and settle at
    // different times (#requestsessionsmount-is-order-dependent). The poll body writes
    // `paneStartupPromptText`; a separate `useEffect` keyed on `[sessions, setActiveDebugRequests]`
    // publishes `activeDebugRequests`. Awaiting only the prompts and then asserting the requests BARE
    // leaves a real window — prompts landed, effect not yet flushed — and under load that window widens
    // until the assertion sees `[]`.
    //
    // It read as an order dependency for a long time: green alone (11/11), green in the dom project
    // (438 files), green in the full suite (733), and red once in a 103-file `--changed` subset. What
    // settles it is that the EXACT failing command passes twice on the same tree — same input, two
    // outputs, which is non-determinism rather than a polluting neighbour. There was never a state leak
    // to isolate; a `waitFor` that covers everything it should have covered is the whole fix.
    await waitFor(() => {
      expect(Object.keys(useAppStore.getState().paneStartupPromptText).sort())
        .toEqual([requestPaneId(1), requestPaneId(2)].sort());
      // Published with PROVENANCE, not as bare ids: the Glance node is labelled `debug - <title>` and
      // edged to the session that filed the request, and neither is derivable from an id.
      // `originPane` and `originKind` ride along (`a-request-records-where-it-actually-came-from`): the
      // graph must not re-derive "is this a session?" from the string's shape, so the store's verdict
      // has to reach it. Asserted with toEqual, so a field silently dropped in transit is a red.
      expect([...useAppStore.getState().activeDebugRequests].sort((a, b) => a.id - b.id)).toEqual([
        {
          id: 1,
          origin: "design-studio:designer-react",
          originPane: "design-studio:designer-react",
          originKind: "pane",
          title: "ui list needs --kit",
        },
        {
          id: 2,
          origin: "algorithms-studio:librarian-typescript",
          originPane: "algorithms-studio:librarian-typescript",
          originKind: "pane",
          title: "impl list needs --domain",
        },
      ]);
    });
  });

  it("CLAIMS each request before binding a session to it", async () => {
    // The claim is what turns `open` into a definite id to bind to. It stays atomic even though the
    // standing session it used to race is gone: two app instances on one machine share this queue.
    render(<RequestSessionsMount />);
    await waitFor(() => expect(queue.rows.every((r) => r.status === "claimed")).toBe(true));
  });

  it("launches each session FRESH — never resumes (#3497)", async () => {
    render(<RequestSessionsMount />);
    await waitFor(() => {
      expect(useAppStore.getState().paneContinue[requestPaneId(1)]).toBe(false);
      expect(useAppStore.getState().paneContinue[requestPaneId(2)]).toBe(false);
    });
  });

  it("charters each session with ITS OWN request, not a generic claim", async () => {
    render(<RequestSessionsMount />);
    await waitFor(() => {
      const p = useAppStore.getState().paneStartupPromptText[requestPaneId(2)];
      expect(p).toContain("#2");
      expect(p).toContain("bsc request resolve 2");
      // The pool's generic charter told the session to go and find work. An assigned one is told the
      // opposite — explicitly, because the instruction it must not follow is one it would otherwise
      // infer. Asserted as the PROHIBITION rather than the absence of the string: the charter names
      // `bsc request claim` precisely in order to forbid it.
      expect(p).toContain("do not run `bsc request claim`");
      expect(p).not.toContain("$BSC_AUDIT_PANE"); // the standing session's claim stamp has no place here
    });
  });
});

describe("a resolved request goes live without a restart", () => {
  beforeEach(() => {
    vi.mocked(safeInvoke).mockClear();
    resetAll();
  });

  const reloadCalls = () => vi.mocked(safeInvoke).mock.calls.filter(([cmd]) => cmd === "reload_sidecars");

  it("re-stages the sidecar when a session closes because its request resolved", async () => {
    // The point of the whole loop: the debug session rebuilt `bsc`, so the new binary has to be staged
    // and the warm child retired before the NEXT call, or the fix sits on disk unused until a restart.
    const { rerender } = render(<RequestSessionsMount />);
    await waitFor(() => expect(Object.keys(useAppStore.getState().paneStartupPromptText)).toHaveLength(2));

    // The session works its request and resolves it. Next reconcile ⇒ its session closes ⇒ reload.
    queue.rows = queue.rows.map((r) => (r.id === 1 ? { ...r, status: "resolved" } : r));
    vi.mocked(safeInvoke).mockClear();
    rerender(<RequestSessionsMount />);
    await waitFor(() => expect(reloadCalls().length).toBeGreaterThan(0));
  });

  it("does NOT reload while nothing has closed — a steady queue must not restage on every poll", async () => {
    // Staging is a file copy that parks a locked binary as `.old-<stamp>`. Doing it on every 20s tick
    // would churn the sidecar dir for no reason and, worse, retire a perfectly good warm child each time.
    render(<RequestSessionsMount />);
    await waitFor(() => expect(Object.keys(useAppStore.getState().paneStartupPromptText)).toHaveLength(2));
    expect(reloadCalls()).toHaveLength(0);
  });
});

// REGRESSION, `a-resolved-requests-debug-session-is-never-closed`. A session OUTLIVES the component that
// started it — the PTY is owned by the backend, and `TerminalView`'s cleanup deliberately keeps it alive
// so a console tab-switch reconnects rather than respawns. The mount was reconciling against a
// `useState([])` it accumulated as it started sessions, and that state dies on every remount: after a
// workspace change or an app restart it was `[]`, so `close` was `[]`, and every running session was
// orphaned with its `claude` process live for good.
//
// The old suite could not see it because its close test uses `rerender`, which keeps the SAME instance and
// its ref. A rerender is not a remount. These mount FRESH against PTYs that are already up, which is the
// only shape that reproduces it.
describe("a session outlives the component that started it", () => {
  beforeEach(resetAll);

  const killed = () =>
    vi.mocked(fireInvoke).mock.calls
      .filter(([cmd]) => cmd === "pty_kill")
      .map(([, payload]) => (payload as { paneId?: string } | undefined)?.paneId);

  it("closes a resolved request's session though THIS mount never started it", async () => {
    queue.rows = [
      { id: 1, status: "resolved", claimed_by: null, origin: null, display_title: "done" },
      { id: 2, status: "claimed", claimed_by: null, origin: null, display_title: "in flight" },
    ];
    ptys.live = new Set([requestPaneId(1), requestPaneId(2)]);

    render(<RequestSessionsMount />);
    await waitFor(() => expect(killed()).toContain(requestPaneId(1)));
    // …and the one still working its request is left strictly alone. A reconcile that closed both would
    // be just as wrong, and far louder.
    expect(killed()).not.toContain(requestPaneId(2));
  });

  it("does not re-charter a claimed request whose session is already running", async () => {
    // The same empty-set bug in the other direction: `start` is "claimed with no TRACKED session", so a
    // fresh mount also re-chartered every live one. Harmless only because `pty_create` reconnects.
    queue.rows = [{ id: 2, status: "claimed", claimed_by: null, origin: null, display_title: "in flight" }];
    ptys.live = new Set([requestPaneId(2)]);

    render(<RequestSessionsMount />);
    await new Promise((r) => setTimeout(r, 0));
    expect(useAppStore.getState().paneStartupPromptText).toEqual({});
  });

  it("still starts a claimed request whose session is genuinely gone", async () => {
    // The reconcile has to work both ways, or "derive it" would just be a different way to be wrong:
    // a session the user stopped by hand must come back.
    queue.rows = [{ id: 2, status: "claimed", claimed_by: null, origin: null, display_title: "in flight" }];
    ptys.live = new Set();

    render(<RequestSessionsMount />);
    await waitFor(() =>
      expect(Object.keys(useAppStore.getState().paneStartupPromptText)).toEqual([requestPaneId(2)]));
  });
});

describe("pruning completed requests (#3522)", () => {
  const pruneCalls = () =>
    vi.mocked(bscRun).mock.calls.filter(([, args]) => args[0] === "request" && args[1] === "prune");

  beforeEach(() => {
    vi.mocked(bscRun).mockClear();
    resetAll();
  });

  // The trigger MOVED with the toggle (#debug-nodes-hang-off-the-session-that-filed-them). It used to
  // fire on the off→on transition — the only moment a user could express "start working the queue".
  // With no toggle, mount is that moment, and it is still exactly ONCE: a resolved row left in the
  // store would otherwise linger as a node for a request nobody is working.
  it("prunes ONCE on mount", async () => {
    render(<RequestSessionsMount />);
    await waitFor(() => expect(pruneCalls()).toHaveLength(1));
    expect(pruneCalls()[0]).toEqual([null, ["request", "prune"]]);
  });

  it("does not re-prune on a re-render — staging churn is the thing this avoids", async () => {
    const { rerender } = render(<RequestSessionsMount />);
    await waitFor(() => expect(pruneCalls()).toHaveLength(1));
    rerender(<RequestSessionsMount />);
    await new Promise((r) => setTimeout(r, 0));
    expect(pruneCalls()).toHaveLength(1);
  });
});

describe("the per-request charter", () => {
  it("names its request, resolves that id, and never leaves one open", () => {
    const c = requestCharter({ id: 78 });
    expect(c).toContain("#78");
    expect(c).toContain("bsc request get 78");
    expect(c).toContain("bsc request resolve 78");
    expect(c).toMatch(/never be left open/i);
    // It must NOT claim: the app already did, and a second claim would take someone else's request.
    expect(c).toContain("do not run `bsc request claim`");
    expect(c).not.toContain("$BSC_AUDIT_PANE");
    // And the shared role prose must not smuggle the queue-serving half back in — the whole reason
    // DEBUG_ROLE_PROMPT was split out of DEBUG_START_PROMPT.
    expect(c).not.toMatch(/Start by claiming a request/i);
  });

  // ── #debug-request-carries-its-origin ─────────────────────────────────────────────────────────
  //
  // The session that files a request and the session that fixes it are different sessions, and the fix
  // is only right if it unblocks the FILER's real workflow. Putting the origin only on the graph edge
  // would leave the one actor who has to act on it — the debug session — unable to see it.

  it("names the session that filed the request, and how to reply to it", () => {
    const c = requestCharter({ id: 85, origin: "design-studio:designer-react", display_title: "ui list needs --kit" });
    expect(c).toContain('"ui list needs --kit"');
    expect(c).toContain("the react designer");
    expect(c).toContain("`design-studio:designer-react`");
    // The reply channel matters as much as the attribution: a debug session that finds the request
    // ambiguous must have somewhere to say so that the filer actually reads back.
    expect(c).toContain('bsc request note 85');
  });

  it("says nothing about an origin when the request has none", () => {
    const c = requestCharter({ id: 90, origin: null, display_title: null });
    expect(c).toContain("#90");
    expect(c).not.toMatch(/filed by/i);
    // No dangling attribution phrasing, and no empty quotes where the title would be.
    expect(c).not.toContain('""');
  });

  it("labels a per-technology studio by its technology, and falls back to the raw id", () => {
    // Two designers exist (react / react-native); the charter has to say WHICH, since the same gap
    // reported from either is a different reproduction.
    expect(originLabel(designerSessionId("react"))).toBe("the react designer");
    expect(originLabel(designerSessionId("react-native"))).toBe("the react-native designer");
    expect(originLabel(librarianSessionId("typescript"))).toBe("the typescript librarian");
    expect(originLabel(SOUND_STUDIO_SESSION_ID)).toBe("the sound designer");
    // A director-filed request (the one non-studio filer) has no studio phrasing — better the raw
    // pane id than an invented role.
    expect(originLabel("myproject:director")).toBe("myproject:director");
  });
});

