// Role → default permission profile — the unified model. Every session's ROLE decides which
// profile it launches under, so a director / worker / triage gets the right profile WITHOUT a
// per-stream generated profile or a manual assignment. The planner only LAYERS extra commands on
// top (it adds abilities, never replaces the role's profile). Profile ids match the packaged role
// JSON (`src-tauri/data/roles/`); kept as bare strings so this stays free of the agents feature
// (shared/ may not import features/).

import type { SessionRole } from "@/shared/lib/session/sessionRoles";

/** The Sandboxed profile — the default for an ungated / manual pane (no role). */
export const DEFAULT_PROFILE_ID = "pf_sandbox";

/** Each session role's default profile id. Worker → Autonomous (trusted); director + the
 *  read-only coordination / observer roles → Read-only review; planner → its application role.
 *  Documentor (#1555) → Autonomous too: like the worker it must actually WRITE (its DOC_GLOBS prose
 *  docs), so it needs a write-permitting profile — the read-only profile's whole-tool write deny would
 *  mask the role gate's DOC_GLOBS carve-out (deny > allow). The role gate + the bsc-scope hook confine
 *  those writes to DOC_GLOBS, exactly as the worker's writes are confined to its owned lane. */
const ROLE_PROFILE: Record<SessionRole, string> = {
  worker: "pf_auto",
  director: "pf_review",
  triage: "pf_review",
  tester: "pf_review",
  // Surface OPERATOR (`surface-operator-runs-confined-to-its-own-noun`): `code: none`, so read-only
  // review is the closest packaged floor. Like the studio rows below, this mapping only backs the
  // generic role->profile UI surfaces — the operator's real confinement is its own `allow` list,
  // which suppresses the baseline tiers outright.
  operator: "pf_review",
  // STEWARD (`a-network-gets-a-root-session-that-can-use-what-it-owns`): a network's root session.
  // `code: none` on every axis, so read-only review is the right packaged floor — and unlike most rows
  // here it is not merely the closest fit: read-only IS the steward's authority model. Its mutating
  // verbs are absent from its `allow` list rather than denied, so each one falls through to a prompt
  // and the human decides per action.
  steward: "pf_review",
  reviewer: "pf_review",
  issuer: "pf_review",
  juror: "pf_review",
  documentor: "pf_auto",
  // Marketer (#2431): like the documentor it must actually WRITE (its marketing-content carve-out), so
  // it launches under the write-permitting Autonomous profile; the role gate + bsc-scope hook confine
  // its writes to the marketing globs.
  marketer: "pf_auto",
  planner: "sys_planner",
  // Designer (#2471) / Architect (#2755) / Librarian (#2787): the three app-owned studio sessions.
  // Read-only review is the closest packaged floor, but this mapping ONLY backs the generic role→profile
  // UI surfaces — it is NOT applied at launch. Their real launch (`StudioSessionMount` on TerminalHost,
  // #3357) sets `paneRoles` and deliberately NO `paneProfiles` entry, because `buildSessionSettings` ADDS
  // a profile's allowedCommands to the role's `restrictedAllow` surface — i.e. assigning a profile here
  // would WIDEN a session confined to one store CLI. Don't wire this into a launch path.
  designer: "pf_review",
  architect: "pf_review",
  librarian: "pf_review",
  "sound-designer": "pf_review",
  // Integrator (#4023): the same studio treatment — read-only review is the closest packaged floor, and
  // this mapping likewise only backs the generic role→profile UI surfaces. Its `net: "read"` widening
  // comes from the ROLE capability, not from a profile, so nothing here needs to grant it.
  integrator: "pf_review",
  // Debugger (#3322): the app's full-cap maintenance session WRITES code, so like the worker it launches
  // under the write-permitting Autonomous profile; its real launch (`DebugSessionMount` on TerminalHost,
  // #3326) renders bypass directly via the `isFullCapabilitySession` carve-out, so this only backs the
  // generic role→profile surfaces.
  debugger: "pf_auto",
  // Curator (#3092, epic #3087): the reusable-library post-landing actor. Read-only review is the
  // closest packaged floor; its real launch (P2b) renders the role gate + `restrictedAllow` (`bsc ui` +
  // `bsc graph`) directly. Its store writes go through `bsc ui`/`bsc graph` (Bash + the `ui` write-scope),
  // not the file-write tools, so the review profile's whole-tool write deny doesn't mask them.
  curator: "pf_review",
};

/** The default profile id for a role (or the Sandboxed default when there's no role). */
export function roleProfileId(role: SessionRole | undefined | null): string {
  return role ? ROLE_PROFILE[role] : DEFAULT_PROFILE_ID;
}

export function rotate90(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let l = 0; l < Math.floor(n / 2); l++) {
    const f = l, e = n - 1 - l;
    for (let i = f; i < e; i++) {
      const o = i - f, t = a[f][i];
      a[f][i] = a[e - o][f];
      a[e - o][f] = a[e][e - o];
      a[e][e - o] = a[i][e];
      a[i][e] = t;
    }
  }
  return a;
}

// Kit lint rules → eslint preset (#2279) — the auto-firing enforcement a kit ships so an agent building
// an app on it can't quietly re-invent a component. This is the pure spine: the rule model lives in
// model.ts; here are the derivation (from each component's `wraps` hint), the author-declared merge, and
// the emitter that turns a kit's rules into plain eslint config (NO custom plugin — the dogfooded 80%).
//
// Config-level ONLY for now: `forbid-element` → `no-restricted-syntax` (the exact pattern this repo uses
// to force `<Box>`/`<Button>` over raw elements), `forbid-import` → `no-restricted-imports`. The
// generated app extends the emitted preset; every rule message carries the escape hatch so it teaches
// but allows a justified exception. Custom AST plugins, token rules, and non-eslint linters are follow-ups.
import type { ComponentRecord, KitRule } from "@/features/designs/lib/model";

/** The escape-hatch clause every rule message ends with — enforce, but allow a justified exception. */
export const ESCAPE_HATCH = "If truly required, add `// eslint-disable-next-line <rule> -- <reason>`.";

/** The human message for a rule (its own `message`, else a default that names `use` + the escape hatch). */
export function ruleMessage(r: KitRule): string {
  if (r.message) return r.message;
  const base =
    r.kind === "forbid-element"
      ? `Use the kit's <${r.use}> instead of a raw <${r.target}>.`
      : `Import ${r.use} from the kit instead of "${r.target}".`;
  return `${base} ${ESCAPE_HATCH}`;
}

/** Derive the flagship anti-duplication rules from the kit: one `forbid-element` per component that
 *  declares what raw intrinsic it `wraps` ("use <Button> not a raw <button>"). */
export function deriveRules(components: ComponentRecord[]): KitRule[] {
  return components
    .filter((c) => c.wraps)
    .map((c) => ({
      id: `derived:forbid-element:${c.wraps}`,
      kind: "forbid-element" as const,
      target: c.wraps!,
      use: c.name,
      componentId: c.id,
      derived: true,
    }));
}

/** The dedup key for a rule — a kit shouldn't forbid the same target twice. */
const ruleKey = (r: KitRule) => `${r.kind}:${r.target}`;

/** Merge derived + author-declared rules: an authored rule OVERRIDES a derived one for the same
 *  (kind, target), and adds any new ones. Authored wins so a kit can refine a derived message/target. */
export function mergeRules(derived: KitRule[], authored: KitRule[]): KitRule[] {
  const byKey = new Map(derived.map((r) => [ruleKey(r), r]));
  for (const a of authored) byKey.set(ruleKey(a), { ...a, derived: false });
  return [...byKey.values()];
}

/** The full ruleset for a kit's components: the derived anti-duplication rules merged with every
 *  component's author-declared `rules`. */
export function kitRules(components: ComponentRecord[]): KitRule[] {
  const authored = components.flatMap((c) => c.rules ?? []);
  return mergeRules(deriveRules(components), authored);
}

/** The rules a SINGLE component contributes/enforces — its derived `wraps` rule (if any) merged with
 *  its author-declared `rules`. Drives the pane's per-component Rules tab. */
export function componentRules(component: ComponentRecord): KitRule[] {
  return mergeRules(deriveRules([component]), component.rules ?? []);
}

/** The eslint `rules` fragment a kit's ruleset compiles to (only the rules that have entries appear). */
export interface EslintRulesConfig {
  "no-restricted-syntax"?: unknown[];
  "no-restricted-imports"?: unknown[];
}

/** Compile a ruleset into a plain eslint `rules` object — `forbid-element` rules fold into one
 *  `no-restricted-syntax` array (each a JSX-element selector + message); `forbid-import` rules into one
 *  `no-restricted-imports` `paths` list. */
export function toEslintRules(rules: KitRule[]): EslintRulesConfig {
  const syntax = rules
    .filter((r) => r.kind === "forbid-element")
    .map((r) => ({ selector: `JSXOpeningElement[name.name='${r.target}']`, message: ruleMessage(r) }));
  const imports = rules
    .filter((r) => r.kind === "forbid-import")
    .map((r) => ({ name: r.target, message: ruleMessage(r) }));

  const out: EslintRulesConfig = {};
  if (syntax.length) out["no-restricted-syntax"] = ["error", ...syntax];
  if (imports.length) out["no-restricted-imports"] = ["error", { paths: imports }];
  return out;
}

/** The eslint preset a kit ships — a flat-config fragment the generated app extends
 *  (`{ rules: { … } }`). Empty `rules` when the kit declares/derives nothing. */
export function toEslintPreset(components: ComponentRecord[]): { rules: EslintRulesConfig } {
  return { rules: toEslintRules(kitRules(components)) };
}

