// The logs feature's graph-platform surface (#3646, epic #3604) — the modules a graph-loaded Logs page
// imports but does NOT redraw: the pure audit-row derivation plus the two capability/console modules the
// derivation reads. Registered HERE, inside the feature, because the shell must not reach a feature's
// internals (#1545) and eager-importing them from `app/` would de-lazy the feature at boot. The logs host
// calls this synchronously before the graph page loads, so the modules are present when the compiled
// page's `require()` runs. Mirrors registerFleetPlatform / registerAutomationsPlatform.
//
// `agentProfiles` and `consoleModel` now live in `shared/lib/security` rather than in a feature: they are
// read by the console shell, the planner, the tunnel projector AND the store, so a feature was never the
// right owner. The registrar still names them because the graph page's audit derivation imports them —
// registering a shared module is fine; IMPORTING another feature's internals is what the boundary forbids.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as AgentProfiles from "@/shared/lib/security/agentProfiles";
import * as ConsoleModel from "@/shared/lib/security/consoleModel";
import * as AuditRows from "@/features/logs/lib/auditRows";
// The Logs page derives the skill-invocation history with the SKILLS feature's own parser + aggregate,
// through its barrel (never `lib/*` — #1545). Registered here so the loader resolves it without
// having to vendor the whole barrel closure, which declines for feature barrels that reach a
// workspace component.
import * as Skills from "@/features/skills";
import * as GraphPlatform from "@/features/logs/graphPlatform";

/** Register the Logs page's injected graph-platform modules by the specifiers it imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerLogsPlatform(): void {
  registerAppModule("@/shared/lib/security/agentProfiles", AgentProfiles);
  registerAppModule("@/shared/lib/security/consoleModel", ConsoleModel);
  registerAppModule("@/features/logs/lib/auditRows", AuditRows);
  registerAppModule("@/features/skills", Skills);
  registerAppModule("@/features/logs/graphPlatform", GraphPlatform);
}

// The logs feature's PUBLIC API — re-exports only.
//
// The screen itself is the `logspage` RECORD, mounted by `LogsGraphHost` — which is what
// `lazyWorkspaces` resolves the `LogsWorkspace` symbol to, in both App.tsx and DetachedWindow.
//
// This feature WAS `features/security`. The Security workspace held four tabs; three were deleted
// (retire-agentprofile-and-strip-security-to-activity) and Activity — the only one with a real feed
// behind it — became the first tab of the unified Logs screen (epic-a-unified-logs-workspace). The
// remaining tabs (Sessions, Waiting, Skills, Hooks, Cost, Streams) read the `bsc logs` engine (#1607).
//
// WHAT DID NOT COME HERE, and why. `agentProfiles`, `profileEnforcement` and `consoleModel` moved to
// `shared/lib/security` instead: they are read by the console shell, the planner, the tunnel projector
// AND the store, so a feature was never their owner — the shell was reaching into a feature's internals
// to get them, which is exactly what #1545 forbids. Logs imports them from `shared/`, like anyone else.
//
// The `AgentProfile` model is still ENFORCED at launch via `resolveProfileSettings` →
// `ensure_session_settings`, and allowlists still resolve additively (guaranteed ∪ profile ∪ project ∪
// repo). Retiring the model needs a coordinated mobile-studio-code change — the tunnel ships it against
// a byte-exact fixture — and is tracked as `retire-the-agentprofile-model-behind-the-tunnel-contract`.

// The graph-hosted workspace (#3646) — App.tsx/DetachedWindow render this via the lazy LogsWorkspace.
export { LogsGraphHost } from "@/features/logs/LogsGraphHost";

// #1545: public API for cross-feature consumers. The audit feed's derivation is shared with the tunnel
// projector (#3754), which derives its consoles + display rows the SAME way this screen does — one
// source of truth for the pane→console join and the allow/ask/block verdict.
export { parseAuditLog, type AuditRecord } from "@/features/logs/lib/auditLog";
export { buildAuditRows, type AuditDisplayRow } from "@/features/logs/lib/auditRows";

// Hash-based built-in seed refresh (#2483) — the pure decision spine that replaced the frozen
// seed-and-keep reconcile. The store wins ONLY for records the user actually edited; a pristine
// built-in copy tracks the packaged seed release-to-release (the react-ui kit is GENERATED from the
// app's own source, so every release drifts the seed).
//
// The mechanism: every packaged built-in carries a `seedHash` — a small content hash of its
// seed-relevant fields, stamped at seed-assembly time (`makeBuiltinKits`). A store copy whose
// current content still hashes to its recorded `seedHash` is UNMODIFIED (safe to refresh/delete);
// one that no longer does was edited by the user (kept, with an "updated upstream" notice when the
// seed moved too).
//
// Hash exclusions (the "volatile" set, `SEED_HASH_EXCLUDED`):
//   - `seedHash`  — the stamp itself can never feed its own hash.
//   - `builtin`   — provenance, not content (stamped on assembly AND carried by the bridge).
//   - `used`      — the runtime reuse counter; it drifts without a user edit.
//   - `rev` / `updatedAt` / `updatedBy` / `history` (#3606) — SERVER-MANAGED provenance the Rust stamp
//     boundary writes on every `bsc ui set` (a component write-through stamps them). `componentBridge`
//     projects them for the inspector's History tab, so they ride into the loaded record — but they are
//     NOT seed content, so hashing them would make a pristine SEEDED component (pushed → stamped → loaded
//     with a fresh `rev`) mis-hash as user-modified forever. Kits/themes never projected them, so this is
//     the component-seed case the empty `SEED_COMPONENTS` had never exercised.
// Everything else on the record IS seed content — a change to any other field is a user edit (store
// copy) or a new release (seed copy).
//
// THE ROUND-TRIP CONTRACT (#2514). A stamp is only meaningful if the record's seed-relevant content
// survives the push→store→load round-trip byte-for-byte: `bsc ui … set` persists the JSON verbatim
// (key order aside), `… list --full` returns it verbatim, and the bridge projections
// (componentBridge/themeBridge `loadX`) must carry every seed-relevant field WITHOUT normalizing it —
// an absent optional field must stay absent (never defaulted to `""`/`[]`), or the reloaded copy
// hashes differently from its stamp and the reconcile mis-judges a pristine record as user-modified
// forever. This invariant is EXECUTED, not assumed: `seedRoundTrip.test.ts` pushes every packaged
// seed record through the real bridge mapping over a faithful store emulation and asserts the
// reloaded content still hashes to its stamp.
//
// Defense in depth for a stamp that rots anyway (an older hasher, a byte-mangling round-trip in some
// past build): a mismatched `builtin` copy gets a second chance against the CURRENT seed — content
// identical to the seed ⇒ the stamp itself was wrong, re-judged pristine and re-stamped (see the
// verdict table on `reconcileSeed`). Silent keep-forever is impossible: every KEEP of a diverged
// copy surfaces a notice.
//
// Deliberately GENERIC over `{ id, name, builtin?, seedHash? }` (components AND kits today) so the
// same helper can be extracted for the other seed-and-keep stores (personas, orgs, blueprints) later
// — it has no component-specific knowledge beyond the volatile-field list above.

/** The minimum shape the reconcile needs; components, kits, and themes (#2488) all satisfy it. */
export interface SeedRecord {
  id: string;
  /** Display name for the notices — components/kits carry `name`; themes carry `label` instead. */
  name?: string;
  /** Theme display name (#2488) — the notices fall back name → label → id. */
  label?: string;
  /** A packaged built-in. Absent/false ⇒ user-authored (never touched by the reconcile). */
  builtin?: boolean;
  /** A SUPPRESSION tombstone (#3725) — `true` marks this id as a PERMANENTLY removed packaged builtin.
   *  The reconcile skips it (not a record to render) and its presence blocks the seed from re-adding it. */
  suppressed?: boolean;
  /** The content hash stamped when this copy was seeded (#2483). Absent ⇒ a legacy pre-#2483 copy. */
  seedHash?: string;
}

/** The display name a notice carries: `name` (components/kits) → `label` (themes) → the id. */
function displayName(rec: SeedRecord): string {
  return rec.name ?? rec.label ?? rec.id;
}

/** Fields excluded from the seed hash — see the module doc for why each. */
export const SEED_HASH_EXCLUDED = ["seedHash", "builtin", "used", "rev", "updatedAt", "updatedBy", "history"] as const;

/** Deterministic JSON: keys sorted recursively, `undefined` properties dropped (so an absent
 *  optional field and an explicitly-undefined one hash identically). */
export function stableStringify(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v) ?? "null";
  if (Array.isArray(v)) return `[${v.map((x) => (x === undefined ? "null" : stableStringify(x))).join(",")}]`;
  const o = v as Record<string, unknown>;
  const keys = Object.keys(o).filter((k) => o[k] !== undefined).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`).join(",")}}`;
}

/** FNV-1a 32-bit over the text, as 8 hex digits. Not cryptographic — a drift detector, not a
 *  security boundary (the store is the user's own local files). */
export function fnv1a(text: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** The seed hash of a record's CURRENT content (volatile fields excluded). */
export function seedHashOf(record: SeedRecord): string {
  const rest: Record<string, unknown> = { ...record };
  for (const k of SEED_HASH_EXCLUDED) delete rest[k];
  return fnv1a(stableStringify(rest));
}

/** Stamp a record with its own content hash — what `makeBuiltinKits` applies to every packaged
 *  built-in at seed-assembly time (the packaged JSON files do NOT bake the field in). */
export function stampSeedHash<T extends SeedRecord>(record: T): T {
  return { ...record, seedHash: seedHashOf(record) };
}

/** What a notice is about. */
export type SeedNoticeType = "component" | "kit" | "theme";

/** A reconcile outcome the user should see (the propagation-surface record, #2483). */
export interface SeedNotice {
  /** `updated-upstream`: the packaged built-in changed but the user's customized copy was kept.
   *  `orphaned`: the built-in left the seed but the user's customized copy was kept.
   *  `reset-to-seed`: a SEED-AUTHORITATIVE record (an import-based page spec, #3723) had a diverged
   *  store copy FORCED back to the packaged seed. The store never wins for these, so a divergence is a
   *  bug (a designer self-contained it for the preview sandbox), not a user edit — surfaced, not silent.
   *  `unstamped`: the store copy carries NO `builtin` flag but a packaged seed of that id EXISTS, so the
   *  reconcile treats it as user-authored and never refreshes it — while the app renders it (#4216). The
   *  record is left exactly as it is (changing 44 pages at once is not a reconcile's call); this makes
   *  the state visible so it can be judged per record. */
  kind: "updated-upstream" | "orphaned" | "reset-to-seed" | "unstamped" | "refreshed";
  type: SeedNoticeType;
  id: string;
  name: string;
}

/** The reconcile verdicts: the final collection + the write-through work to converge the store. */
export interface SeedReconcile<T extends SeedRecord> {
  /** The reconciled collection (loaded order, refreshed in place; missing seeds appended). */
  records: T[];
  /** Records to write through (`bsc ui set` / `kit set`): refreshed + newly-added built-ins. */
  pushes: T[];
  /** Ids to remove from the store (`bsc ui remove` / `kit remove`): deleted built-ins. */
  drops: string[];
  /** The "kept but diverged" outcomes to surface. */
  notices: SeedNotice[];
}

/**
 * Reconcile the store's loaded records with the packaged seed (#2483). Verdict table — for a loaded
 * record with `builtin: true` ("modified" = its content no longer hashes to its recorded `seedHash`;
 * a record with NO `seedHash` is a legacy pre-#2483 copy, grandfathered as UNMODIFIED — all three
 * real rot incidents were pristine copies, so this heals every existing install once):
 *
 * | in seed? | modified? | seed moved (`seed.seedHash !== record.seedHash`)? | verdict |
 * |---|---|---|---|
 * | yes | no  | yes (incl. legacy no-hash) | REFRESH — take the new seed copy, push it |
 * | yes | no  | no                         | keep the store copy (already current) |
 * | yes | yes | yes (incl. legacy… n/a)    | KEEP + `updated-upstream` notice |
 * | yes | yes | no                         | keep (customized, seed unchanged) |
 * | no  | no  |                            | DELETE (drop from store) |
 * | no  | yes |                            | KEEP + `orphaned` notice |
 *
 * Tolerant re-stamp (#2514): before the "modified" KEEP fires for an in-seed record, its content is
 * compared against the CURRENT seed copy's content hash. Identical content ⇒ only the recorded stamp
 * is wrong (an older hasher / a byte-mangling round-trip in a past build stamped it) — the record is
 * re-judged PRISTINE and refreshed to the seed copy (same content, corrected stamp), no notice. A
 * retired record with a wrong stamp has no seed copy to compare against, so it stays on the
 * conservative KEEP + `orphaned` branch — kept, but never silently (the notice is the surface).
 *
 * Non-builtin (user-authored) loaded records pass through untouched, always. Seed records the store
 * lacks are appended + pushed (the original seed-and-keep add).
 *
 * @param loaded the store's records (from the bridge).
 * @param seed   the packaged built-ins, seedHash-stamped (`makeBuiltinKits`).
 * @param type   what the records are (for the notices).
 * @param opts   `seedAuthoritative` (#3723) — records for which the SEED wins unconditionally (an
 *               import-based page spec): a diverged store copy is a bug, not a user edit, so it is
 *               FORCED back to the seed with a `reset-to-seed` notice instead of the customized-KEEP the
 *               verdict table above would apply. Records it doesn't match keep the normal verdicts.
 */
/** A record's component source, when it has one. Kits and themes do not, and yield "". */
function sourceOf(rec: unknown): string {
  const v = (rec as { srcText?: unknown }).srcText;
  return typeof v === "string" ? v : "";
}

export function reconcileSeed<T extends SeedRecord>(
  loaded: T[],
  seed: T[],
  type: SeedNoticeType,
  opts?: { seedAuthoritative?: (rec: T) => boolean },
): SeedReconcile<T> {
  const seedById = new Map(seed.map((s) => [s.id, s]));
  const records: T[] = [];
  const pushes: T[] = [];
  const drops: string[] = [];
  const notices: SeedNotice[] = [];

  for (const rec of loaded) {
    // #3725: a SUPPRESSION tombstone — a marker that a packaged builtin of this id is permanently removed.
    // It is not a record to render (skip it from `records`), and its presence in `loaded` (hence `have`
    // below) makes the re-seed step SKIP that id, so the builtin never comes back. It stays in the store
    // (never dropped) so the block persists; `unsuppress` (remove it) lets the next hydrate re-seed.
    if (rec.suppressed) continue;
    if (!rec.builtin) {
      // #4216: an unstamped record with a packaged seed of the same id is NOT user-authored — it is a
      // built-in whose stamp was lost (a pre-#4197 partial `bsc ui set` dropped `builtin`/`seedHash`).
      // The reconcile has been skipping it ever since, so it never refreshes — while the app renders it,
      // because this branch pushes the store copy straight into `records`. Say so.
      //
      // Behaviour is deliberately UNCHANGED: the store copy still wins. Deciding which side is right is
      // a per-record judgement (the drift runs both ways — some store copies are far smaller than their
      // seed, some far larger), and a reconcile that silently replaced 44 pages would be the worse bug.
      const lost = seedById.get(rec.id);
      // ...with ONE exception, and it needs no judgement at all: an EMPTY store copy.
      //
      // Eight packaged components were sitting in the store with a zero-length `srcText` while their
      // seed carried real source — `dropdown` (7,846 bytes), `activityfeed` (3,940), `windowcontrols`,
      // `backbutton`, `cardlistrow`, `inlineerror`, `skillsdigesttoggle`, `settingssubheader`. The
      // "which side is right" caution above is about a store copy that holds DIFFERENT work; a copy
      // that holds NOTHING is not a competing edit, it is a record that lost its content. Keeping it
      // means the app renders an empty component and the seed's version can never arrive.
      //
      // Narrow on purpose: empty AND the seed has content. A genuinely empty seed record stays empty.
      // `reconcileSeed` is generic over kits and themes as well as components, and only a COMPONENT
      // has `srcText` — so this reads it defensively rather than widening the constraint. For a kit or
      // a theme the accessor yields undefined and the rule simply never fires, which is correct: the
      // emptiness this repairs is a component-source failure.
      if (lost && !sourceOf(rec).trim() && sourceOf(lost).trim()) {
        notices.push({ kind: "refreshed", type, id: lost.id, name: displayName(lost) });
        records.push(lost);
        pushes.push(lost);
        continue;
      }
      if (lost) {
        notices.push({ kind: "unstamped", type, id: rec.id, name: displayName(rec) });
      }
      records.push(rec); // user-authored (or unstamped) — never touched
      continue;
    }
    const seeded = seedById.get(rec.id);
    // Legacy pre-#2483 copies (no seedHash) are grandfathered as unmodified.
    const contentHash = rec.seedHash === undefined ? undefined : seedHashOf(rec);
    let modified = contentHash !== undefined && contentHash !== rec.seedHash;
    if (seeded) {
      const seedContentHash = seeded.seedHash ?? seedHashOf(seeded);
      // Seed-authoritative records (#3723): the store NEVER wins. A store copy whose CONTENT differs
      // from the seed is a divergence bug — e.g. a designer self-contained an import-based page spec so
      // it would render in the preview sandbox, which then silently shadowed the real page (#3658 →
      // #3723) — not a user edit. Force the seed copy back (push it), surfaced via a `reset-to-seed`
      // notice so the override is never silent. A copy already matching the seed is left untouched.
      if (opts?.seedAuthoritative?.(rec)) {
        if (seedHashOf(rec) !== seedContentHash) {
          records.push(seeded);
          pushes.push(seeded);
          notices.push({ kind: "reset-to-seed", type, id: rec.id, name: displayName(rec) });
        } else {
          records.push(rec); // already matches the seed
        }
        continue;
      }
      // Tolerant re-stamp (#2514): content identical to the CURRENT seed ⇒ the recorded stamp is the
      // broken part, not the content — re-judge pristine (the refresh below adopts the seed copy,
      // which is the same content with the corrected stamp).
      if (modified && contentHash === seedContentHash) modified = false;
      const seedMoved = seedContentHash !== rec.seedHash;
      if (!modified && seedMoved) {
        records.push(seeded); // pristine + stale → refresh to the new seed copy
        pushes.push(seeded);
        // SAY SO WHEN IT ACTUALLY REPLACED SOMETHING (#a-reseed-must-not-silently-overwrite-a-designer-edit).
        //
        // This branch was the one verdict that changed a record and reported nothing. A designer's only
        // signal was noticing their fix had stopped working — which is how request #63 was found, twice,
        // mid-task. The banner's own rule already covers this case: `reset-to-seed` is carried as
        // actionable because "it means a store copy was OVERWRITTEN, which is the most actionable verdict
        // there is". A content-replacing refresh is the same event.
        //
        // Only when the CONTENT differs. A refresh whose seed copy is byte-identical is a stamp
        // correction — the tolerant re-stamp path (#2514) routes through here — and reporting those would
        // bury the real ones, which is exactly why plain divergence is not surfaced either.
        if (seedHashOf(seeded) !== seedHashOf(rec)) {
          notices.push({ kind: "refreshed", type, id: rec.id, name: displayName(rec) });
        }
      } else {
        records.push(rec); // current, or customized (store wins)
        if (modified && seedMoved) notices.push({ kind: "updated-upstream", type, id: rec.id, name: displayName(rec) });
      }
    } else if (modified) {
      records.push(rec); // customized copy of a retired built-in — keep, but say so
      notices.push({ kind: "orphaned", type, id: rec.id, name: displayName(rec) });
    } else {
      drops.push(rec.id); // pristine copy of a retired built-in → delete
    }
  }

  // Built-ins the store lacks entirely (first run / newly packaged) — append + push.
  const have = new Set(loaded.map((r) => r.id));
  for (const s of seed) {
    if (have.has(s.id)) continue;
    records.push(s);
    pushes.push(s);
  }

  return { records, pushes, drops, notices };
}

/** One record the re-stamp declines to touch, and why (#4207). */
export interface RestampDeferral {
  id: string;
  name: string;
  /** `seed-authoritative`: stamping would let the seed OVERWRITE the store copy on the next hydrate
   *  (the `seedAuthoritative` branch of {@link reconcileSeed} fires before any content comparison), so
   *  the repair would silently change what the app renders. That is a per-record judgement, not a
   *  repair's call. */
  reason: "seed-authoritative";
}

/** What {@link planRestamp} would do (#4207). */
export interface RestampPlan<T extends SeedRecord> {
  /** Records to write through, each carrying `builtin: true` + the SEED's content hash. Content is
   *  otherwise untouched. */
  stamps: T[];
  /** Records left alone, with the reason. */
  deferred: RestampDeferral[];
}

/**
 * Plan the repair for the `unstamped` verdict (#4207): store records carrying NO `builtin` flag that a
 * packaged seed of the same id exists for. A pre-#4197 partial `bsc ui set` dropped the flag, and
 * `reconcileSeed` has treated them as user-authored ever since — so they never refresh, never surface a
 * drift notice, and never received the #4107 `group`→`folder` migration, while the app renders them.
 *
 * **The stamp carries the SEED's hash, not the record's own** — that choice is the whole design, because
 * it decides which side wins on the very next hydrate:
 *
 * - Stamped with its OWN content hash, the record reads as PRISTINE (`contentHash === seedHash`) and
 *   STALE (`seedContentHash !== seedHash`), which is the REFRESH verdict: the seed copy replaces the
 *   store copy. On this repo that would discard real content — the store's `automations-history` carries
 *   the post-rename `HistoryTab`, its seed still says `AutomationsHistory`.
 * - Stamped with the SEED's content hash, it reads as EDITED (content differs from the stamp) against an
 *   UNMOVED seed — the "customized, seed unchanged" verdict, which keeps the store copy. Then the moment
 *   the packaged seed genuinely moves, `updated-upstream` fires and the drift is visible from then on.
 *
 * So the repair is non-destructive by construction: it restores the record's MEMBERSHIP in the reconcile
 * without adjudicating its content. Which side is right stays a per-record question — this only makes it
 * a question the machinery can still ask.
 *
 * A record with no packaged seed is never stamped: that is the signature of a genuinely user-authored (or
 * harvested) record, and mislabelling one as a built-in would hand its content to a future seed.
 *
 * @param loaded the store's records (from the bridge).
 * @param seed   the packaged built-ins, seedHash-stamped.
 * @param opts   `seedAuthoritative` — the same predicate {@link reconcileSeed} takes. Matching records
 *               are DEFERRED rather than stamped; see {@link RestampDeferral}.
 */
/**
 * Apply a {@link planRestamp} result to the in-memory list — replace each stamped record by id.
 *
 * Exists so the repair can run BEFORE the reconcile in a single hydrate pass. The alternative, stamping
 * the store and re-reading, costs a second full-fidelity load and a second reconcile; worse, done from
 * inside `hydrateComponents` a re-hydrate would re-enter itself.
 *
 * Returns `loaded` unchanged (same reference) when there is nothing to stamp, so the common case adds no
 * allocation and a caller can cheaply tell whether anything happened.
 */
export function applyStamps<T extends SeedRecord>(loaded: T[], stamps: T[]): T[] {
  if (stamps.length === 0) return loaded;
  const byId = new Map(stamps.map((s) => [s.id, s]));
  return loaded.map((rec) => byId.get(rec.id) ?? rec);
}

export function planRestamp<T extends SeedRecord>(
  loaded: T[],
  seed: T[],
  opts?: { seedAuthoritative?: (rec: T) => boolean },
): RestampPlan<T> {
  const seedById = new Map(seed.map((s) => [s.id, s]));
  const stamps: T[] = [];
  const deferred: RestampDeferral[] = [];

  for (const rec of loaded) {
    // A tombstone, or a record the reconcile ALREADY handles correctly.
    //
    // The `builtin` half used to be unqualified, commented "already in the reconcile path"
    // (#a-builtin-that-lost-its-stamp-falls-between-both-guards). That is only true of a record whose
    // stamp is INTACT. A builtin that has lost its `seedHash` falls between the two guards: restamp
    // skipped it because `builtin` was set, and the reconcile refreshed it because `contentHash` is
    // undefined when `seedHash` is — so `modified` reads false, the seed has moved, and the packaged
    // copy is adopted. Each guard assumed the other covered the case.
    //
    // That cost 38 records on 2026-08-14 (designer request #63): a `--graph` LITE `--replace` push
    // strips the stamp (that projection carries no `seedHash`) and the next hydrate overwrote a
    // designer's fixes with the seed. Claiming it here restores the stamp with the SEED's hash, which
    // reads as edited-against-an-unmoved-seed — the verdict that KEEPS the store copy.
    if (rec.suppressed || (rec.builtin && rec.seedHash)) continue;
    const seeded = seedById.get(rec.id);
    if (!seeded) continue; // no packaged seed ⇒ genuinely user-authored — never claim it
    if (opts?.seedAuthoritative?.(rec)) {
      deferred.push({ id: rec.id, name: displayName(rec), reason: "seed-authoritative" });
      continue;
    }
    stamps.push({ ...rec, builtin: true, seedHash: seeded.seedHash ?? seedHashOf(seeded) });
  }

  return { stamps, deferred };
}

tests.src:
// Hash-based built-in seed refresh (#2483) — the pure decision spine. Covers the full verdict table
// (refresh / keep+notice / delete / orphan / legacy grandfather / user-authored pass-through), hash
// stability + exclusions, and the kit-shaped variants of the same verdicts.
import { describe, it, expect } from "vitest";
import type { ComponentRecord, Kit } from "@/features/designs/lib/model";
import { fnv1a, stableStringify, seedHashOf, stampSeedHash, reconcileSeed, planRestamp, applyStamps } from "@/features/designs/lib/seedRefresh";

/** A minimal component-shaped record. */
const comp = (over: Partial<ComponentRecord> = {}): ComponentRecord => ({
  id: "button", name: "Button", kitId: "react-ui", role: "primitive", version: "1.0.0", used: 0,
  tags: [], variants: ["default"], composes: [], props: [], whenUse: [], whenNot: [],
  src: "", srcText: "", builtin: true,
  ...over,
});

const kit = (over: Partial<Kit> = {}): Kit => ({
  id: "react-ui", name: "React UI", stack: "React · TypeScript", dot: "var(--accent)", builtin: true,
  ...over,
});

describe("seed hash (#2483)", () => {
  it("is stable: the same record always hashes the same", () => {
    expect(seedHashOf(comp())).toBe(seedHashOf(comp()));
  });

  it("changes when any seed-relevant field changes", () => {
    expect(seedHashOf(comp({ version: "2.0.0" }))).not.toBe(seedHashOf(comp()));
    expect(seedHashOf(comp({ srcText: "x" }))).not.toBe(seedHashOf(comp()));
    expect(seedHashOf(comp({ variants: ["default", "ghost"] }))).not.toBe(seedHashOf(comp()));
  });

  it("excludes seedHash itself, builtin, and the volatile `used` counter", () => {
    const base = seedHashOf(comp());
    expect(seedHashOf(comp({ seedHash: "deadbeef" }))).toBe(base);
    expect(seedHashOf(comp({ builtin: undefined }))).toBe(base);
    expect(seedHashOf(comp({ used: 42 }))).toBe(base);
  });

  it("is key-order independent and treats explicit undefined as absent", () => {
    expect(stableStringify({ b: 1, a: [2, { d: 3, c: 4 }] })).toBe(stableStringify({ a: [2, { c: 4, d: 3 }], b: 1 }));
    expect(stableStringify({ a: 1, wraps: undefined })).toBe(stableStringify({ a: 1 }));
  });

  it("fnv1a is deterministic 8-hex-digit output", () => {
    expect(fnv1a("")).toBe("811c9dc5"); // the FNV-1a 32-bit offset basis
    expect(fnv1a("abc")).toMatch(/^[0-9a-f]{8}$/);
    expect(fnv1a("abc")).not.toBe(fnv1a("abd"));
  });

  it("stampSeedHash stamps a hash the stamped record's own content still matches", () => {
    const stamped = stampSeedHash(comp());
    expect(stamped.seedHash).toBeDefined();
    expect(seedHashOf(stamped)).toBe(stamped.seedHash); // seedHash is excluded from its own hash
  });
});

describe("reconcileSeed verdicts (#2483)", () => {
  // The current packaged seed: one built-in, stamped.
  const seedNew = stampSeedHash(comp({ version: "2.0.0" }));
  // Yesterday's packaged copy of the same built-in — pristine (self-consistent hash), but stale.
  const storePristineOld = stampSeedHash(comp({ version: "1.0.0" }));

  it("refreshes an unmodified stale built-in to the new seed copy (and pushes it)", () => {
    const r = reconcileSeed([storePristineOld], [seedNew], "component");
    expect(r.records).toEqual([seedNew]);
    expect(r.pushes).toEqual([seedNew]);
    expect(r.drops).toEqual([]);
    // Was `toEqual([])` — this branch used to report NOTHING
    // (#a-reseed-must-not-silently-overwrite-a-designer-edit). The refresh itself is unchanged; what
    // changed is that replacing a store copy is now stated. It was the one verdict that altered a record
    // and said nothing, which is how 38 records were replaced unnoticed on 2026-08-14 (request #63).
    expect(r.notices.map((n) => n.kind)).toEqual(["refreshed"]);
  });

  it("keeps an unmodified current built-in with no ops (idempotent hydrate)", () => {
    const current = { ...seedNew, used: 7 }; // volatile drift only — still pristine
    const r = reconcileSeed([current], [seedNew], "component");
    expect(r.records).toEqual([current]); // store copy kept (its `used` survives)
    expect(r.pushes).toEqual([]);
    expect(r.drops).toEqual([]);
    expect(r.notices).toEqual([]);
  });

  it("keeps a user-modified built-in and notices the upstream update (never clobbers)", () => {
    // The user edited yesterday's copy: content moved off its recorded baseline.
    const edited = { ...storePristineOld, srcText: "my tweak" };
    const r = reconcileSeed([edited], [seedNew], "component");
    expect(r.records).toEqual([edited]);
    expect(r.pushes).toEqual([]);
    expect(r.drops).toEqual([]);
    expect(r.notices).toEqual([{ kind: "updated-upstream", type: "component", id: "button", name: "Button" }]);
  });

  it("keeps a user-modified built-in silently when the seed did NOT move", () => {
    const edited = { ...seedNew, srcText: "my tweak" }; // baseline = the CURRENT seed
    const r = reconcileSeed([edited], [seedNew], "component");
    expect(r.records).toEqual([edited]);
    expect(r.notices).toEqual([]);
  });

  it("deletes an unmodified built-in that left the seed", () => {
    const retired = stampSeedHash(comp({ id: "spring-row", name: "SpringRow", kitId: "spring-kotlin" }));
    const r = reconcileSeed([retired], [seedNew], "component");
    expect(r.records).toEqual([seedNew]); // retired gone, missing seed appended
    expect(r.drops).toEqual(["spring-row"]);
    expect(r.pushes).toEqual([seedNew]);
    expect(r.notices).toEqual([]);
  });

  it("keeps a modified built-in that left the seed, marked orphaned", () => {
    const retired = stampSeedHash(comp({ id: "spring-row", name: "SpringRow" }));
    const editedRetired = { ...retired, srcText: "mine now" };
    const r = reconcileSeed([editedRetired, seedNew], [seedNew], "component");
    expect(r.records).toEqual([editedRetired, seedNew]);
    expect(r.drops).toEqual([]);
    expect(r.notices).toEqual([{ kind: "orphaned", type: "component", id: "spring-row", name: "SpringRow" }]);
  });

  it("grandfathers a legacy no-seedHash built-in as unmodified: refreshed when in the seed", () => {
    const legacy = comp({ version: "1.0.0" }); // pre-#2483: builtin, no seedHash
    expect(legacy.seedHash).toBeUndefined();
    const r = reconcileSeed([legacy], [seedNew], "component");
    expect(r.records).toEqual([seedNew]);
    expect(r.pushes).toEqual([seedNew]); // the one-time heal stamps the store copy
  });

  it("grandfathers a legacy no-seedHash built-in absent from the seed: deleted", () => {
    const legacy = comp({ id: "tauri-rust-row", name: "TauriRow" }); // the spring-kotlin/tauri-rust incident
    const r = reconcileSeed([legacy, seedNew], [seedNew], "component");
    expect(r.records).toEqual([seedNew]);
    expect(r.drops).toEqual(["tauri-rust-row"]);
  });

  it("re-stamps a wrong-stamped copy whose content EQUALS the current seed (#2514 tolerant heal)", () => {
    // The #2514 failure class: content is byte-identical to the seed but the recorded stamp is rot
    // (an older hasher / a byte-mangling round-trip stamped it). Without the tolerant path this is
    // judged user-modified and kept — with the WRONG stamp — forever.
    const wrongStamp = { ...seedNew, seedHash: "deadbeef" };
    const r = reconcileSeed([wrongStamp], [seedNew], "component");
    expect(r.records).toEqual([seedNew]); // same content, corrected stamp
    expect(r.pushes).toEqual([seedNew]); // pushed so the store converges on the good stamp
    expect(r.drops).toEqual([]);
    expect(r.notices).toEqual([]); // nothing diverged — no notice
  });

  it("keeps a wrong-stamped copy whose content matches NEITHER its stamp NOR the seed — with a notice, never silently (#2514)", () => {
    // Indistinguishable from a genuine user edit (could equally be an old seed's content under a
    // broken stamp) — conservative KEEP, surfaced via the updated-upstream notice.
    const divergent = { ...seedNew, srcText: "my tweak", seedHash: "deadbeef" };
    const r = reconcileSeed([divergent], [seedNew], "component");
    expect(r.records).toEqual([divergent]);
    expect(r.pushes).toEqual([]);
    expect(r.notices).toEqual([{ kind: "updated-upstream", type: "component", id: "button", name: "Button" }]);
  });

  it("keeps a wrong-stamped RETIRED copy on the orphan branch (no seed to verify against, #2514)", () => {
    const retired = { ...stampSeedHash(comp({ id: "spring-row", name: "SpringRow" })), seedHash: "deadbeef" };
    const r = reconcileSeed([retired, seedNew], [seedNew], "component");
    expect(r.records).toEqual([retired, seedNew]);
    expect(r.drops).toEqual([]);
    expect(r.notices).toEqual([{ kind: "orphaned", type: "component", id: "spring-row", name: "SpringRow" }]);
  });

  it("never touches user-authored records, even when stale-looking or absent from the seed", () => {
    const mine = comp({ id: "my-widget", name: "MyWidget", builtin: undefined });
    const mineWithStrayHash = comp({ id: "my-other", name: "MyOther", builtin: false, seedHash: "deadbeef" });
    const r = reconcileSeed([mine, mineWithStrayHash, seedNew], [seedNew], "component");
    expect(r.records).toEqual([mine, mineWithStrayHash, seedNew]);
    expect(r.pushes).toEqual([]);
    expect(r.drops).toEqual([]);
    expect(r.notices).toEqual([]);
  });

  it("appends + pushes built-ins the store lacks (the original seed-and-keep add)", () => {
    const r = reconcileSeed([], [seedNew], "component");
    expect(r.records).toEqual([seedNew]);
    expect(r.pushes).toEqual([seedNew]);
  });
});

describe("reconcileSeed — seedAuthoritative records (#3723): the seed always wins", () => {
  // A page-spec record. The seed is AUTHORITATIVE for it (an import-based page the app renders through
  // the registry at runtime, NOT designer-editable), which `reconcileComponents` keys on `role: "page"`.
  const seedPage = stampSeedHash(comp({ id: "settingspage", name: "SettingsPage", role: "page" }));
  const authoritative = (r: ComponentRecord) => r.role === "page";

  it("FORCES a diverged page copy back to the seed, with a reset-to-seed notice (the #3658/#3723 bug)", () => {
    // A designer self-contained the page (content no longer matches the seed) — a bug, not a user edit.
    const selfContained = { ...seedPage, srcText: "// vendored self-contained for preview" };
    const r = reconcileSeed([selfContained], [seedPage], "component", { seedAuthoritative: authoritative });
    expect(r.records).toEqual([seedPage]); // the clean seed copy wins
    expect(r.pushes).toEqual([seedPage]);  // and is written back to the store
    expect(r.drops).toEqual([]);
    expect(r.notices).toEqual([{ kind: "reset-to-seed", type: "component", id: "settingspage", name: "SettingsPage" }]);
  });

  it("leaves a page copy that already matches the seed untouched (no push, no notice)", () => {
    const current = { ...seedPage, used: 3 }; // volatile drift only — content still matches the seed
    const r = reconcileSeed([current], [seedPage], "component", { seedAuthoritative: authoritative });
    expect(r.records).toEqual([current]);
    expect(r.pushes).toEqual([]);
    expect(r.notices).toEqual([]);
  });

  it("does NOT force records the predicate excludes — a normal edited component is still KEPT (store wins)", () => {
    const seedNew = stampSeedHash(comp({ version: "2.0.0" }));
    const edited = { ...stampSeedHash(comp({ version: "1.0.0" })), srcText: "my tweak" }; // role: primitive
    const r = reconcileSeed([edited], [seedNew], "component", { seedAuthoritative: authoritative });
    expect(r.records).toEqual([edited]); // predicate returns false for a non-page → normal verdict table
    expect(r.pushes).toEqual([]);
    expect(r.notices).toEqual([{ kind: "updated-upstream", type: "component", id: "button", name: "Button" }]);
  });
});

describe("reconcileSeed on kit records (#2483) — the kit store rots the same way", () => {
  const seedKit = stampSeedHash(kit({ stack: "React 19 · TypeScript" }));
  const oldKit = stampSeedHash(kit({ stack: "React · TypeScript" }));

  it("refreshes an unmodified stale kit", () => {
    const r = reconcileSeed([oldKit], [seedKit], "kit");
    expect(r.records).toEqual([seedKit]);
    expect(r.pushes).toEqual([seedKit]);
  });

  it("keeps a user-renamed kit with an updated-upstream notice", () => {
    const renamed = { ...oldKit, name: "My UI" };
    const r = reconcileSeed([renamed], [seedKit], "kit");
    expect(r.records).toEqual([renamed]);
    expect(r.notices).toEqual([{ kind: "updated-upstream", type: "kit", id: "react-ui", name: "My UI" }]);
  });

  it("deletes a pristine kit that left the seed (spring-kotlin regression)", () => {
    const springKotlin = stampSeedHash(kit({ id: "spring-kotlin", name: "Spring Kotlin" }));
    const r = reconcileSeed([springKotlin, seedKit], [seedKit], "kit");
    expect(r.records).toEqual([seedKit]);
    expect(r.drops).toEqual(["spring-kotlin"]);
  });

  it("keeps a customized kit that left the seed, marked orphaned", () => {
    const springKotlin = { ...stampSeedHash(kit({ id: "spring-kotlin", name: "Spring Kotlin" })), dot: "red" };
    const r = reconcileSeed([springKotlin], [seedKit], "kit");
    expect(r.records).toEqual([springKotlin, seedKit]);
    expect(r.notices).toEqual([{ kind: "orphaned", type: "kit", id: "spring-kotlin", name: "Spring Kotlin" }]);
  });
});

describe("reconcileSeed — suppression tombstones (#3725)", () => {
  it("a tombstone blocks the builtin re-seed and is excluded from the library, but stays in the store", () => {
    const seedComp = stampSeedHash(comp({ id: "cost", name: "CostEnergyView" }));
    // The builtin was suppressed: the store holds ONLY the `{ id, suppressed }` tombstone.
    const r = reconcileSeed([{ ...comp({ id: "cost" }), suppressed: true }], [seedComp], "component");
    expect(r.records.some((x) => x.id === "cost")).toBe(false); // not rendered — it's a tombstone
    expect(r.pushes.some((x) => x.id === "cost")).toBe(false); // NOT re-seeded (the whole point of #13)
    expect(r.drops).not.toContain("cost"); // the tombstone stays, to keep blocking the re-seed
  });

  it("removing the tombstone (unsuppress) lets the seed re-add the builtin", () => {
    const seedComp = stampSeedHash(comp({ id: "cost", name: "CostEnergyView" }));
    // With the tombstone gone, the store lacks the builtin → the seed re-adds it (append + push).
    const r = reconcileSeed([], [seedComp], "component");
    expect(r.records).toEqual([seedComp]);
    expect(r.pushes).toEqual([seedComp]);
  });

  it("suppresses a kit the same way", () => {
    const seedK = stampSeedHash(kit({ id: "fleet", name: "Fleet" }));
    const r = reconcileSeed([{ ...kit({ id: "fleet" }), suppressed: true }], [seedK], "kit");
    expect(r.records.some((x) => x.id === "fleet")).toBe(false);
    expect(r.pushes.some((x) => x.id === "fleet")).toBe(false);
  });
});

// #4216 — the verdict for a record the reconcile has been skipping in silence.
describe("reconcileSeed — unstamped built-ins (#4216)", () => {
  const seedNew = stampSeedHash(comp({ version: "2.0.0" }));

  // #4216 — the state nothing was watching for. A store copy with NO `builtin` flag but a packaged seed
  // of that id is a built-in whose stamp was lost (a pre-#4197 partial `bsc ui set` dropped it). The
  // reconcile skipped it silently ever since, so it never refreshed — while the app rendered it, because
  // the unstamped branch pushes the store copy straight into `records`.
  it("reports an UNSTAMPED record that still has a packaged seed, without changing what renders", () => {
    // Same id as the seed, but no `builtin` — and deliberately different content, the real-world shape.
    const unstamped = { ...comp({ version: "1.0.0" }), builtin: undefined };
    const r = reconcileSeed([unstamped], [seedNew], "component");

    // The verdict is surfaced…
    expect(r.notices).toEqual([
      { kind: "unstamped", type: "component", id: unstamped.id, name: expect.any(String) },
    ]);
    // …and NOTHING is changed by it. The store copy still wins, nothing is pushed, nothing is dropped.
    // Deciding which side is right is a per-record judgement; a reconcile that silently replaced 44
    // pages at once would be the worse bug.
    expect(r.records).toEqual([unstamped]);
    expect(r.pushes).toEqual([]);
    expect(r.drops).toEqual([]);
  });

  it("stays silent for a genuinely user-authored record — one with no packaged seed", () => {
    // The discrimination that keeps the notice useful: ~168 store records legitimately have no seed
    // (designer-authored library components). Reporting those would bury the 44 that matter in noise.
    const mine = { ...comp({ id: "my-own-thing", version: "1.0.0" }), builtin: undefined };
    const r = reconcileSeed([mine], [seedNew], "component");
    expect(r.notices).toEqual([]);
    // It survives untouched. (`records` also gains `seedNew` — a packaged built-in the store lacks is
    // re-seeded, which is the pre-existing behaviour and not what this case is about.)
    expect(r.records).toContainEqual(mine);
  });
});

describe("a refresh that REPLACES content says so (#a-reseed-must-not-silently-overwrite-a-designer-edit)", () => {
  it("emits a `refreshed` notice when the packaged copy replaced the store copy", () => {
    // THE silent verdict. This branch adopts the seed copy and pushes it, and reported nothing — so a
    // designer's only signal was noticing their fix had stopped working, which is how request #63 was
    // found mid-task, twice. 38 records were replaced this way on 2026-08-14 with no notice at all.
    const stale = stampSeedHash(comp({ version: "1.0.0", name: "Button" }));
    const moved = stampSeedHash(comp({ version: "2.0.0", name: "ButtonRenamed" }));
    const r = reconcileSeed([stale], [moved], "component");

    expect(r.records[0].name).toBe("ButtonRenamed"); // the refresh still happens
    expect(r.notices.map((n) => n.kind)).toContain("refreshed");
    expect(r.notices.find((n) => n.kind === "refreshed")?.id).toBe(stale.id);
  });

  it("stays QUIET for a stamp-only correction, where nothing was replaced", () => {
    // The tolerant re-stamp (#2514) routes through the same branch with byte-identical content. Reporting
    // those would bury the real ones — the same reason plain divergence is not surfaced.
    const rec = comp({ version: "1.0.0", name: "Button", seedHash: "a-stale-but-wrong-stamp" });
    const seed = stampSeedHash(comp({ version: "1.0.0", name: "Button" }));
    const r = reconcileSeed([rec], [seed], "component");
    expect(r.notices.map((n) => n.kind)).not.toContain("refreshed");
  });
});

describe("planRestamp — repairing the unstamped (#4207)", () => {
  // The packaged seed, and a store copy of the SAME id that lost its `builtin` flag to a pre-#4197
  // partial write AND has since been independently edited (the real shape: harvests kept updating the
  // store copy while the reconcile skipped it, so the two drifted apart in both directions).
  const seeded = stampSeedHash(comp({ version: "2.0.0", name: "Button" }));
  const unstamped = comp({ version: "1.0.0", name: "ButtonTab", builtin: undefined, seedHash: undefined });

  it("stamps a record that a packaged seed exists for", () => {
    const { stamps, deferred } = planRestamp([unstamped], [seeded]);
    expect(stamps).toHaveLength(1);
    expect(stamps[0].builtin).toBe(true);
    expect(deferred).toEqual([]);
  });

  it("leaves the content completely untouched", () => {
    const { stamps } = planRestamp([unstamped], [seeded]);
    const { builtin: _b, seedHash: _h, ...after } = stamps[0];
    const { builtin: _b2, seedHash: _h2, ...before } = unstamped;
    expect(after).toEqual(before);
  });

  // THE design decision. Stamped with the SEED's hash the record reads as EDITED against an UNMOVED
  // seed, which is the verdict that KEEPS the store copy. Stamped with its OWN hash it would read as
  // pristine-and-stale — the REFRESH verdict — and the next hydrate would replace the store content
  // with the seed's. This test is the difference between a repair and a silent data loss.
  it("claims a builtin that LOST its stamp — the #63 shape", () => {
    // #a-builtin-that-lost-its-stamp-falls-between-both-guards. `planRestamp` used to skip ANY record
    // carrying `builtin`, commented "already in the reconcile path". A builtin that has lost its
    // `seedHash` is NOT: the reconcile computes `contentHash` as undefined when `seedHash` is, so
    // `modified` is false, the seed has moved, and the `!modified && seedMoved` branch adopts the
    // packaged copy. Each guard assumed the other covered it, so nothing did.
    //
    // That is what happened to 38 records on 2026-08-14 (designer request #63): a `--graph` LITE
    // `--replace` push strips the stamp — that projection carries no `seedHash` — and the next hydrate
    // overwrote a designer's edits with the seed.
    const strippedBuiltin = comp({ version: "1.0.0", name: "ButtonEdited", builtin: true, seedHash: undefined });
    const { stamps } = planRestamp([strippedBuiltin], [seeded]);
    expect(stamps, "a stamp-less builtin must be re-claimed, not skipped").toHaveLength(1);
    expect(stamps[0].seedHash).toBe(seeded.seedHash);

    // And with the stamp restored, the reconcile KEEPS the edited store copy instead of refreshing it.
    const r = reconcileSeed(applyStamps([strippedBuiltin], stamps), [seeded], "component");
    expect(r.pushes, "the packaged copy must NOT be pushed over the designer's edit").toEqual([]);
    expect(r.records[0].name).toBe("ButtonEdited");
  });

  it("still skips a FULLY stamped builtin — the reconcile path is unchanged for those", () => {
    // The guard narrows, it does not disappear: a record that is correctly stamped is still the
    // reconcile's business alone, so the ordinary refresh/keep behaviour is untouched.
    const healthy = stampSeedHash(comp({ version: "1.0.0", name: "Button", builtin: true }));
    expect(planRestamp([healthy], [seeded]).stamps).toEqual([]);
  });

  it("still refuses to claim a record with NO packaged seed", () => {
    // Restamp must never invent provenance for genuinely user-authored work, stamp or no stamp.
    const mine = comp({ id: "mine", name: "Mine", builtin: true, seedHash: undefined });
    expect(planRestamp([mine], [seeded]).stamps).toEqual([]);
  });

  it("stamps with the SEED's hash, so the next reconcile KEEPS the store copy", () => {
    const { stamps } = planRestamp([unstamped], [seeded]);
    expect(stamps[0].seedHash).toBe(seeded.seedHash);
    expect(stamps[0].seedHash).not.toBe(seedHashOf(unstamped));

    const r = reconcileSeed(stamps, [seeded], "component");
    expect(r.records).toEqual(stamps); // the store copy survived
    expect(r.pushes).toEqual([]);
    expect(r.notices).toEqual([]); // seed has not moved since — nothing to report yet
  });

  it("surfaces updated-upstream once the seed DOES move, which is the point of rejoining", () => {
    const { stamps } = planRestamp([unstamped], [seeded]);
    const seedMoved = stampSeedHash(comp({ version: "3.0.0", name: "Button" }));
    const r = reconcileSeed(stamps, [seedMoved], "component");
    expect(r.records).toEqual(stamps); // still kept — it is an edited built-in
    expect(r.notices).toEqual([{ kind: "updated-upstream", type: "component", id: "button", name: "ButtonTab" }]);
  });

  it("never claims a record with no packaged seed — that is a genuinely user-authored one", () => {
    const authored = comp({ id: "my-thing", builtin: undefined, seedHash: undefined });
    expect(planRestamp([authored], [seeded]).stamps).toEqual([]);
  });

  it("skips records already in the reconcile path, and suppression tombstones", () => {
    const tombstone = comp({ builtin: undefined, seedHash: undefined, suppressed: true });
    expect(planRestamp([seeded, tombstone], [seeded]).stamps).toEqual([]);
  });

  // Stamping a seed-authoritative record arms the branch that forces the seed over the store BEFORE any
  // content comparison — so the "repair" would change what the app renders. Defer, and say so.
  it("defers a seed-authoritative record instead of stamping it", () => {
    const page = comp({ id: "fleetpage", name: "FleetPage", role: "page", builtin: undefined, seedHash: undefined });
    const seedPage = stampSeedHash(comp({ id: "fleetpage", name: "FleetPage", role: "page", version: "2.0.0" }));
    const { stamps, deferred } = planRestamp([page], [seedPage], { seedAuthoritative: (r) => r.role === "page" });
    expect(stamps).toEqual([]);
    expect(deferred).toEqual([{ id: "fleetpage", name: "FleetPage", reason: "seed-authoritative" }]);
  });
});

describe("applyStamps + the repair running INSIDE hydrate (auto-restamp)", () => {
  it("replaces stamped records by id and leaves the rest alone", () => {
    const a = comp({ id: "a", builtin: false });
    const b = comp({ id: "b", builtin: false });
    const stamped = { ...a, builtin: true, seedHash: "H" };
    const out = applyStamps([a, b], [stamped]);
    expect(out[0]).toBe(stamped);
    expect(out[1], "an untouched record keeps its identity").toBe(b);
  });

  it("returns the SAME array reference when there is nothing to stamp", () => {
    // The common case after the first repair — so hydrate pays nothing on every subsequent boot.
    const loaded = [comp({ id: "a" })];
    expect(applyStamps(loaded, [])).toBe(loaded);
  });

  it("a DIVERGED store copy survives the repair with its content intact", () => {
    // The property the whole design rests on. The store copy differs from the seed; stamping with the
    // SEED's hash makes it read as edited-against-an-unmoved-seed, which KEEPS the store copy. Stamping
    // with its OWN hash would read as pristine-and-stale and hand the seed's content over the top.
    const seeded = stampSeedHash(comp({ id: "history", srcText: "OLD seed body" }));
    const store = comp({ id: "history", srcText: "NEW store body", builtin: false });

    const plan = planRestamp([store], [seeded]);
    expect(plan.stamps).toHaveLength(1);
    expect(plan.stamps[0].seedHash).toBe(seeded.seedHash);

    const reconciled = reconcileSeed(applyStamps([store], plan.stamps), [seeded], "component");
    const kept = reconciled.records.find((r) => r.id === "history");
    expect(kept?.srcText, "the store copy is kept — the repair restores membership, not content").toBe("NEW store body");
  });

  it("an IDENTICAL store copy is stamped and simply agrees with its seed — the 214-record case", () => {
    // What promoting store-only records into the seed produced: a seed created for an id whose store
    // copy carries no `builtin` flag, so it read as unstamped despite being byte-identical.
    const seeded = stampSeedHash(comp({ id: "same", srcText: "body" }));
    const store = comp({ id: "same", srcText: "body", builtin: false });
    const plan = planRestamp([store], [seeded]);
    const reconciled = reconcileSeed(applyStamps([store], plan.stamps), [seeded], "component");
    expect(reconciled.records.find((r) => r.id === "same")?.srcText).toBe("body");
    expect(reconciled.notices.filter((n) => n.kind === "unstamped"), "repaired ⇒ no notice").toEqual([]);
  });

  it("a record with NO packaged seed is never stamped — that is the user-authored signature", () => {
    const mine = comp({ id: "mine", builtin: false });
    expect(planRestamp([mine], []).stamps).toEqual([]);
    // …and it still reaches the reconciled output, untouched.
    const reconciled = reconcileSeed([mine], [], "component");
    expect(reconciled.records.find((r) => r.id === "mine")).toBeTruthy();
  });
});

import { describe, it, expect } from "vitest";
import { reconcileSeed } from "@/features/designs/lib/seedRefresh";

type Rec = { id: string; name?: string; srcText?: string; builtin?: boolean; seedHash?: string };

const seed = (id: string, srcText: string): Rec => ({ id, name: id, srcText, builtin: true });

describe("an EMPTY store copy is not a competing edit", () => {
  /**
   * THE BUG. Eight packaged components sat in the store with a zero-length `srcText` while their seed
   * carried real source — `dropdown` (7,846 bytes), `activityfeed` (3,940), `windowcontrols`,
   * `backbutton`, `cardlistrow`, `inlineerror`, `skillsdigesttoggle`, `settingssubheader`. They had
   * also lost their `builtin`/`seedHash` stamp to a pre-#4197 partial write, so the reconcile
   * classified them as user-authored and never touched them: the app rendered an empty component and
   * the seed's version could never arrive.
   *
   * #4216 deliberately left unstamped records alone because "which side is right" is a per-record
   * judgement. That caution is about a store copy holding DIFFERENT work. A copy holding NOTHING is
   * not a competing edit — it is a record that lost its content, and there is nothing to weigh.
   */
  it("restores an unstamped, EMPTY record from the seed", () => {
    const loaded: Rec[] = [{ id: "dropdown", name: "Dropdown", srcText: "" }];
    const out = reconcileSeed(loaded, [seed("dropdown", "export function Dropdown() {}")], "component");
    expect(out.records[0].srcText, "the seed's source is what renders now").toContain("Dropdown");
    expect(out.pushes.map((p) => p.id), "and it is written back, so it stops being empty").toEqual(["dropdown"]);
    expect(out.notices.some((n) => n.kind === "refreshed" && n.id === "dropdown")).toBe(true);
  });

  it("still leaves an unstamped record that has REAL content alone", () => {
    // The #4216 caution stands wherever there is something to lose: the drift runs both ways, and a
    // reconcile that silently replaced a page someone had authored would be the worse bug.
    const loaded: Rec[] = [{ id: "guidecard", name: "GuideCard", srcText: "the user's own work" }];
    const out = reconcileSeed(loaded, [seed("guidecard", "the shipped version")], "component");
    expect(out.records[0].srcText).toBe("the user's own work");
    expect(out.pushes).toEqual([]);
    expect(out.notices.some((n) => n.kind === "unstamped")).toBe(true);
  });

  it("does not invent content when the SEED is the empty one", () => {
    // Narrow on purpose. An empty seed record is a real (if odd) state; replacing a store copy with
    // nothing would be this bug pointed the other way.
    const loaded: Rec[] = [{ id: "x", name: "X", srcText: "" }];
    const out = reconcileSeed(loaded, [seed("x", "   ")], "component");
    expect(out.pushes).toEqual([]);
  });

  it("leaves a genuinely user-authored record untouched — it has no seed at all", () => {
    const loaded: Rec[] = [{ id: "mine", name: "Mine", srcText: "" }];
    const out = reconcileSeed(loaded, [], "component");
    expect(out.records.map((r) => r.id)).toEqual(["mine"]);
    expect(out.pushes).toEqual([]);
  });
});

