// The per-page verdict (#4169) — the two signals must stay independent: structural drift does not block a
// flip (the page still renders, just an older skeleton), an unbound behaviour does (the page throws on
// load and shows its fallback).
import { describe, it, expect } from "vitest";
import { buildPageShadow, formatShadowLine, formatShadowSummary, type ModuleShadow } from "@/shared/lib/runtime/shadow/shadowReport";
import type { OutlineDiff } from "@/shared/lib/runtime/shadow/outlineDiff";

const clean: OutlineDiff = { identical: true, differing: 0, fileNodes: 10, graphNodes: 10, onlyInFile: [], onlyInGraph: [] };
const drifted: OutlineDiff = { identical: false, differing: 3, fileNodes: 10, graphNodes: 8, onlyInFile: ["Screen>New"], onlyInGraph: [] };

const mod = (recordId: string, status: ModuleShadow["status"], diff: OutlineDiff | null): ModuleShadow =>
  ({ recordId, file: `/src/${recordId}.tsx`, status, diff });

const page = (over: Partial<Parameters<typeof buildPageShadow>[0]> = {}) =>
  buildPageShadow({
    pageId: "mcppage", label: "MCP", rendersFrom: "graph",
    modules: [mod("mcppage", "identical", clean)], unbound: [], hasGraphNode: true, ...over,
  });

describe("buildPageShadow", () => {
  it("is graph-identical when every module matches", () => {
    const p = page();
    expect(p.status).toBe("graph-identical");
    expect(p.differingNodes).toBe(0);
    expect(p.readyForGraph).toBe(true);
  });

  it("sums the differing nodes across a page's modules", () => {
    const p = page({ modules: [mod("mcppage", "differs", drifted), mod("mcp-analytics", "differs", drifted)] });
    expect(p.status).toBe("differs");
    expect(p.differingNodes).toBe(6);
    expect(p.fileNodes).toBe(20);
  });

  it("keeps drift OUT of readiness — a drifted page still renders", () => {
    expect(page({ modules: [mod("mcppage", "differs", drifted)] }).readyForGraph).toBe(true);
  });

  it("is NOT ready with an unbound behaviour — it would throw on load, not degrade", () => {
    const p = page({ unbound: [{ specifier: "@/features/mcp/lib/x", symbols: ["probe"], importedBy: ["mcppage"] }] });
    expect(p.readyForGraph).toBe(false);
    expect(p.status).toBe("graph-identical"); // …and the structural verdict is unaffected
  });

  it("is NOT ready when the source will not compile", () => {
    expect(page({ compileError: "Unexpected }" }).readyForGraph).toBe(false);
  });

  it("reports a page the graph does not carry at all", () => {
    const p = page({ hasGraphNode: false, modules: [mod("settingspage", "no-graph-node", null)] });
    expect(p.status).toBe("no-graph-node");
    expect(p.readyForGraph).toBe(false);
  });

  it("counts a module with no graph record as drift, not as a match", () => {
    // A tab body added to the file page after the migration: nothing differs node-for-node because there
    // is nothing to compare — and reading that as "identical" is exactly the false green to avoid.
    const p = page({ modules: [mod("mcppage", "identical", clean), mod("mcp-new-tab", "no-graph-node", null)] });
    expect(p.status).toBe("differs");
  });

  it("reports a graph-only page (its files are deleted) as such, and as ready", () => {
    const p = page({ pageId: "fleetpage", modules: [{ recordId: "fleetpage", file: null, status: "no-file-baseline", diff: null }] });
    expect(p.status).toBe("no-file-baseline");
    expect(p.readyForGraph).toBe(true);
  });
});

describe("formatShadowLine", () => {
  it("states the verdict, the render source and the bindings", () => {
    expect(formatShadowLine(page())).toBe("mcppage [renders from graph] — graph-identical · all behaviors bound");
    expect(formatShadowLine(page({ modules: [mod("mcppage", "differs", drifted)] })))
      .toBe("mcppage [renders from graph] — differs in 3 of 10 nodes · all behaviors bound");
    expect(formatShadowLine(page({ unbound: [{ specifier: "@/x", symbols: [], importedBy: ["mcppage"] }] })))
      .toContain("unbound: @/x");
  });
});

describe("formatShadowSummary", () => {
  it("rolls up how much of the app the graph could render today", () => {
    const summary = formatShadowSummary([
      page(),
      page({ pageId: "skillspage", unbound: [{ specifier: "@/a", symbols: [], importedBy: ["skillspage"] }] }),
      page({ pageId: "githubpage", modules: [mod("githubpage", "differs", drifted)] }),
    ]);
    expect(summary).toBe("3 pages · 2 structurally identical · 2 fully bound · 1 distinct unbound specifiers");
  });
});

implementations.code:
// shapePreview (#3439 / #3790) — the SHAPE tier of component preview data. A component that declares a
// `DataShape` (e.g. `shapes: ["list"]`) is fed REAL algorithm-generated data with NO per-component
// `PREVIEW_BINDINGS` row. It sits BETWEEN the curated binding and `samplePropValue`:
//
//     curated binding  →  shape-mock (here)  →  samplePropValue
//
// Supported are the shapes whose data can be both PRODUCED (a `datasetForStructure`) and LANDED on a real
// data prop: `list` (an array prop, filled with generic objects that render across the feed / collection
// components), `graph` (NetworkPage's `nodes`[+`edges`] arrays), and `tree` (#3790 — the Tree /
// TreeExplorerPage `nodes` nested forest, from a BST). Layout composites with no data-array prop
// (GraphCanvas `world:object`, MasterDetail render-props) find no target and fall through to
// `samplePropValue`, as #3439's acceptance requires; `linked-list`/`key-value` have no tracer and also fall
// through. Pure + synchronous (the programs run on the main thread) and strictly FAIL-SOFT: any gap returns
// `{}` so the component's own sample shows and a preview is never broken.
import type { VizDataset, PreviewStructure } from "@/features/algorithms";
import { isCollectionProp } from "@/features/designs/lib/componentPreview";
import type { ComponentRecord, DataShape, PropSpec } from "@/features/designs/lib/model";

/** Fetches a real dataset for a structure. INJECTED (not imported) so this module holds no runtime
 *  dependency on the `@/features/algorithms` barrel — importing the barrel value here pulls its
 *  crossGraphAdapter ↔ designs libraryComposition module-init cycle into every unit test. `usePreviewData`
 *  passes the real `datasetForStructure`; tests pass the real one via the deep (barrel-free) path or a stub. */
export type DatasetForStructure = (structure: PreviewStructure) => VizDataset | undefined;

/** Shape → how to source its dataset + how to land it on the component's props. */
interface ShapeTierEntry {
  structure: PreviewStructure;
  /** Map the dataset onto the component's props → `{ propName: value }`, or `null` when the component
   *  has no prop this shape can land on (then the shape falls through). */
  fill: (ds: VizDataset, props: PropSpec[]) => Record<string, unknown> | null;
}

/** Prop names that conventionally hold the primary data collection — preferred over any other array prop
 *  so a component with an incidental array prop (e.g. `columns`) still gets its DATA prop filled. */
const DATA_PROP_NAMES = ["items", "rows", "data", "entries", "records", "list"];

/** The first array-typed prop, preferring the conventional data-prop names. */
function firstArrayProp(props: PropSpec[]): PropSpec | undefined {
  const arrays = props.filter(isCollectionProp);
  return arrays.find((p) => DATA_PROP_NAMES.includes(p.name.toLowerCase())) ?? arrays[0];
}

function arrayProp(props: PropSpec[], name: string): PropSpec | undefined {
  return props.find((p) => p.name.toLowerCase() === name && isCollectionProp(p));
}

export const SHAPE_TIER: Partial<Record<DataShape, ShapeTierEntry>> = {
  list: {
    structure: "array",
    fill: (ds, props) => {
      if (ds.kind !== "array") return null;
      const prop = firstArrayProp(props);
      if (!prop) return null; // render-prop layout (MasterDetail, CardListRow) → fall through
      // Generic, render-SAFE objects: the UNION of the fields the real list components read, so each
      // renders fully and none crashes — CollectionItem { id, title } AND ActivityItem { login, action,
      // target, repo, createdAt } (its Avatar needs a `login`). The algorithm's value rides along as
      // `value`. Fixed strings keep it deterministic (no `new Date()` → no per-render flicker).
      const items = ds.data.map((value, i) => ({
        id: `n${i}`,
        title: `Item ${i + 1}`,
        label: `Item ${i + 1}`,
        login: `user${(i % 8) + 1}`,
        action: "updated",
        target: `item ${i + 1}`,
        repo: "demo/app",
        createdAt: "2026-01-01T00:00:00.000Z",
        value,
      }));
      return { [prop.name]: items };
    },
  },
  graph: {
    structure: "graph",
    fill: (ds, props) => {
      if (ds.kind !== "graph") return null;
      const nodesProp = arrayProp(props, "nodes");
      if (!nodesProp) return null; // GraphCanvas (world:object, children) has no nodes array → fall through
      const out: Record<string, unknown> = {
        // NetworkNodeData { id, label } — label defaults to the id so it always renders.
        [nodesProp.name]: ds.nodes.map((n) => ({ id: n.id, label: n.label ?? n.id })),
      };
      const edgesProp = arrayProp(props, "edges");
      // NetworkEdgeData { from, to }.
      if (edgesProp) out[edgesProp.name] = ds.edges.map((e) => ({ from: e.from, to: e.to }));
      return out;
    },
  },
  tree: {
    structure: "tree",
    fill: (ds, props) => {
      if (ds.kind !== "tree") return null;
      const nodesProp = arrayProp(props, "nodes");
      if (!nodesProp) return null; // a tree layout with no nodes array → fall through
      // ds.roots are already the nested `{ id, label, children }` forest the Tree/TreeExplorerPage nodes prop wants.
      return { [nodesProp.name]: ds.roots };
    },
  },
};

/** The shape-tier preview-data override for `comp` (`{ prop: JS-source literal }`), or `{}` when it
 *  declares no supported shape, its shape can't land on a real prop, or the dataset is unavailable.
 *  `getDataset` sources the real per-structure dataset (see {@link DatasetForStructure}). */
export function shapePreviewData(comp: ComponentRecord, getDataset: DatasetForStructure): Record<string, string> {
  for (const shape of comp.shapes ?? []) {
    const entry = SHAPE_TIER[shape];
    if (!entry) continue;
    const ds = getDataset(entry.structure);
    if (!ds) continue;
    const filled = entry.fill(ds, comp.props);
    if (filled && Object.keys(filled).length > 0) {
      return Object.fromEntries(Object.entries(filled).map(([k, v]) => [k, JSON.stringify(v)]));
    }
  }
  return {};
}

