  });

  it("fills a graph component's nodes + edges arrays (the NetworkPage shape)", () => {
    const out = shapePreviewData(comp({ shapes: ["graph"], props: [prop("nodes", "T[]"), prop("edges", "T[]")] }), STUB);
    expect(Object.keys(out).sort()).toEqual(["edges", "nodes"]);
