// The skills feature's graph-platform surface (#3654, epic #3604) — the feature-internal modules a
// graph-loaded Skills page imports but does NOT redraw: the pure skills domain logic (defs/filter/telemetry/
// lessons) + the shared style helper. Registered HERE, inside the feature, because the shell must not reach
// a feature's internals (#1545). The skills host calls this synchronously before the graph page loads.
// Mirrors the fleet/automations/security/github graph-platforms.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Skills from "@/features/skills/lib/skills";
import * as SkillsFilter from "@/features/skills/lib/skillsFilter";
import * as SkillTelemetry from "@/features/skills/lib/skillTelemetry";
import * as Lessons from "@/features/skills/lib/lessons";
import * as SkillStyles from "@/features/skills/skillStyles";
import * as GraphPlatform from "@/features/skills/graphPlatform";

/** Register the skills page's injected graph-platform modules by the specifiers it imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerSkillsPlatform(): void {
  registerAppModule("@/features/skills/lib/skills", Skills);
  registerAppModule("@/features/skills/lib/skillsFilter", SkillsFilter);
  registerAppModule("@/features/skills/lib/skillTelemetry", SkillTelemetry);
  registerAppModule("@/features/skills/lib/lessons", Lessons);
  registerAppModule("@/features/skills/skillStyles", SkillStyles);
  registerAppModule("@/features/skills/graphPlatform", GraphPlatform);
}

// The Skills feature's public API barrel (#1309).
//
// The `SkillsWorkspace` COMPONENT that used to live here is gone (retire-the-dead-skills-workspace-
// copy). It had been dead since #3654 — `lazyWorkspaces` resolves the symbol to `SkillsGraphHost`, so
// the record was what mounted and this was a second copy nobody rendered. #4179 is what that costs:
// two changes landed on the two copies four hours apart, neither was carried across, and the suite
// stayed green for months because the tests rendered THIS one.
//
// The barrel survives where `security`'s did not, because three records import it — `fleet-lessons`,
// `planningpage` and `teams-inspector` all reach `@/features/skills` for types and helpers.
// Re-exported feature surface — this index is the skills feature's public API barrel (#1309).
export { SkillsGraphHost } from "@/features/skills/SkillsGraphHost"; // the graph-hosted workspace (#3654)
export { SkillsStatus } from "@/features/skills/SkillsStatus";
export { SessionSkillsModal, type SessionSkillsModalProps } from "@/features/skills/SessionSkillsModal";

// #1545: public API for cross-feature consumers (planner, app/console).
export {
  type SkillDef, skillFromPayload, resolveSkills, effectiveSessionSkills,
  expandGroups, toSkillCfgs,
} from "@/features/skills/lib/skills";
export { loadPendingLessons, lessonTitle, type Lesson } from "@/features/skills/lib/lessons";
// The skill-usage LOG parser + aggregate. Exported because Logs → Skills renders the invocation
// history and must derive it the SAME way the library page does — two derivations of "how many
// times did this skill run" would eventually disagree, and neither screen would say which was
// right. Cross-feature consumers take the barrel, never `lib/*` (#1545).
export { parseSkillLog, aggregateSkillTelemetry, type SkillUsageRecord, type SkillStats } from "@/features/skills/lib/skillTelemetry";

// Derived KPIs computed from the live skills list (the Skills screen's header tiles).

import type { SkillDef } from "@/features/skills/lib/skillsModel";

// ── derived KPIs (from the live list) ──────────────────────────────────────────

export interface DerivedSkillKpis {
  total: number;
  pinned: number;
  /** sum of per-skill invocations (display telemetry). */
  invWeek: number;
  /** invocation-weighted success rate (0 when there are no invocations). */
  avgSuccess: number;
}

export function deriveSkillKpis(skills: SkillDef[]): DerivedSkillKpis {
  const totalInv = skills.reduce((a, s) => a + s.invocations, 0);
  const avgSuccess = totalInv > 0
    ? Math.round(skills.reduce((a, s) => a + s.success * s.invocations, 0) / totalInv)
    : 0;
  return {
    total: skills.length,
    pinned: skills.filter(s => s.pinned).length,
    invWeek: totalInv,
    avgSuccess,
  };
}

// The SkillDef model + the leaf helpers every other skills-lib module builds on:
// the directory-safe slug and the blank-form factory, plus the coercion key sets
// derived from the shared skills data.
//
// Free of React / Tauri imports so it can be unit-tested and shared between the
// store, the Skills screen, the planner ingestion, and TerminalView.

import {
  KIND, PROFILE_COLOR,
  type SkillKind, type SkillSource, type SkillProfile,
} from "@/shared/data/skills";

export const KIND_KEYS = Object.keys(KIND) as SkillKind[];
export const PROFILE_KEYS = Object.keys(PROFILE_COLOR) as SkillProfile[];
export const SOURCE_KEYS: SkillSource[] = ["first-party", "team", "imported", "community"];

/**
 * A user- or planner-configured skill: a reusable capability bundle (a prompt +
 * bundled tools + profile guardrails) any worker may invoke. Injected into a
 * launched session as a Claude Code Skill file. Scoped via {@link SkillDef.projects}.
 */
export interface SkillDef {
  id: string;
  name: string;
  kind: SkillKind;
  source: SkillSource;
  /** One-line description (the SKILL.md frontmatter `description` + the card). */
  desc: string;
  /** The reusable procedure, written as the SKILL.md body. */
  prompt: string;
  /** Tool names bundled with the skill → the SKILL.md `allowed-tools`. */
  tools: string[];
  /** Permission profiles allowed to invoke it. */
  profiles: SkillProfile[];
  /** `[]` = every project (global); otherwise the project ids it applies to. */
  projects: string[];
  enabled: boolean;
  /** Pinned skills are auto-available to the fleet. */
  pinned: boolean;
  /** Code-owned packaged skill (seeded from {@link seedSkills}). Lets a load-time
   *  refresh replace it from code and prune any packaged skill dropped from the
   *  library, while never touching user-created / imported / catalog skills. */
  packaged?: boolean;
  // ── display-only telemetry (not yet live; see #404 follow-up) ──
  invocations: number;
  success: number;
  avgTokensK: number;
  trend: number[];
}

/** Directory-safe slug for a skill name (matches the Rust slugger). */
export function skillSlug(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");
}

/** A stable content key over a skill's AUTHORED fields — the analogue of teams' `orgStructureKey`
 *  (#3330). `hydrateSkills` compares it (#3672) to re-push ONLY skills whose packaged content drifted
 *  (a code update) instead of re-writing every skill each boot. User/display state (enabled / pinned /
 *  projects / telemetry) is deliberately excluded — those write through via their own mutations, so a
 *  toggle never triggers a hydrate re-push. */
export function skillContentKey(s: SkillDef): string {
  return JSON.stringify([s.name, s.kind, s.source, s.desc, s.prompt, s.tools, s.profiles]);
}

/** A blank custom skill, ready for the new-skill form. */
export function blankSkill(): Omit<SkillDef, "id"> {
  return {
    name: "", kind: "workflow", source: "first-party",
    desc: "", prompt: "", tools: [], profiles: ["build"], projects: [],
    enabled: false, pinned: false,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  };
}

// Planner channel (skills.json): the PlannerSkill entry shape and the tolerant
// parser that turns the planner's authored JSON array into clean, defaulted skills
// the caller upserts into the global library.

import { type SkillKind, type SkillSource, type SkillProfile } from "@/shared/data/skills";
import { KIND_KEYS, PROFILE_KEYS, SOURCE_KEYS, type SkillDef } from "@/features/skills/lib/skillsModel";

// ── Planner channel (skills.json) ──────────────────────────────────────────────

/** One entry the planner may write to `skills.json` (everything but id optional). */
export interface PlannerSkill extends Omit<SkillDef, "id"> { id?: string }

/**
 * Parse the planner's `skills.json` (a JSON array of skill objects) into clean,
 * defaulted {@link PlannerSkill}s. Tolerant of partial objects and malformed
 * input — anything unparseable yields `[]`, and a row without a usable name is
 * dropped. New planner skills are enabled + pinned by default (auto-available to
 * the fleet); the caller upserts them into the global library.
 */
export function parseSkillsFile(raw: string): PlannerSkill[] {
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const out: PlannerSkill[] = [];
  for (const row of data) {
    if (!row || typeof row !== "object") continue;
    const r = row as Record<string, unknown>;
    const name = typeof r.name === "string" ? r.name.trim() : "";
    if (!name) continue;
    out.push({
      id: typeof r.id === "string" && r.id ? r.id : undefined,
      name,
      kind: coerceKind(r.kind),
      source: coerceSource(r.source) ?? "team",
      desc: typeof r.desc === "string" ? r.desc : typeof r.description === "string" ? r.description : "",
      prompt: typeof r.prompt === "string" ? r.prompt : "",
      tools: coerceStrings(r.tools),
      profiles: coerceProfiles(r.profiles),
      projects: coerceStrings(r.projects),
      enabled: r.enabled === undefined ? true : !!r.enabled,
      pinned: r.pinned === undefined ? true : !!r.pinned,
      invocations: 0, success: 0, avgTokensK: 0, trend: [],
    });
  }
  return out;
}

function coerceStrings(v: unknown): string[] {
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === "string" && x.trim() !== "") : [];
}
function coerceKind(v: unknown): SkillKind {
  return typeof v === "string" && (KIND_KEYS as string[]).includes(v) ? v as SkillKind : "workflow";
}
function coerceSource(v: unknown): SkillSource | null {
  return typeof v === "string" && (SOURCE_KEYS as string[]).includes(v) ? v as SkillSource : null;
}
function coerceProfiles(v: unknown): SkillProfile[] {
  const arr = coerceStrings(v).filter(x => (PROFILE_KEYS as string[]).includes(x)) as SkillProfile[];
  return arr.length ? arr : ["build"];
}

// Backend payload: resolved SkillDefs → the SkillCfg shape handed to
// `ensure_session_settings` and written into a session's `.claude/skills/<slug>/SKILL.md`.

import { skillSlug, type SkillDef } from "@/features/skills/lib/skillsModel";

// ── Backend payload ─────────────────────────────────────────────────────────
// Shape handed to `ensure_session_settings` (field names match the Rust SkillCfg).

export interface SkillCfg {
  /** Stable skilldb id — carried so the backend can count an attach as a use (#A). */
  id: string;
  name: string;
  description: string;
  prompt: string;
  tools: string[];
}

/** Resolved skills → their `.claude/skills/<slug>/SKILL.md` payloads. Skips any
 *  skill whose name slugs to empty (nothing to key the directory on). Carries the
 *  stable id so the launch path can count an attach as a use (#A). */
export function toSkillCfgs(defs: SkillDef[]): SkillCfg[] {
  const out: SkillCfg[] = [];
  for (const s of defs) {
    if (!skillSlug(s.name)) continue;
    out.push({ id: s.id, name: s.name, description: s.desc, prompt: s.prompt, tools: s.tools });
  }
  return out;
}

// Catalog → SkillDef templates and the packaged-skill lifecycle: seeding the
// initial library from the sample set, reconstructing a def from a shared
// blueprint's embedded payload, and reconciling a persisted library with the
// code-owned packaged set on load.

import { SKILLS, type Skill, type SkillKind } from "@/shared/data/skills";
import { KIND_KEYS, type SkillDef } from "@/features/skills/lib/skillsModel";

/** Reconstruct a SkillDef from a shared blueprint's embedded skill payload (#897 Phase 5b).
 *  Keeps the original id (so the blueprint's refs resolve) + content; marks it `source:
 *  "imported"` and defaults everything else (kind falls back to the first known kind when the
 *  payload didn't carry one). Structural param so there's no import cycle with blueprintSkills. */
export function skillFromPayload(p: { id: string; name: string; content: string; desc?: string; skillKind?: SkillKind; tools?: string[] }): SkillDef {
  return {
    id: p.id,
    name: p.name,
    kind: p.skillKind && KIND_KEYS.includes(p.skillKind) ? p.skillKind : KIND_KEYS[0],
    source: "imported",
    desc: p.desc ?? "",
    prompt: p.content,
    tools: p.tools ?? [],
    profiles: [],
    projects: [],
    enabled: true,
    pinned: false,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  };
}

/** A sample {@link Skill} → a full editable {@link SkillDef} (enabled + global).
 *  Telemetry (invocations/success/trend/avgTokensK) starts at zero — real usage
 *  is supplied later from the skill-usage log (#406), never seeded with samples. */
function fromSample(s: Skill): SkillDef {
  return {
    id: s.id,
    name: s.name,
    kind: s.kind,
    source: s.source,
    desc: s.desc,
    // Packaged skills carry a full authored procedure in `body`; fall back to the
    // description for any skill that doesn't (the user/planner can refine it).
    prompt: s.body ?? s.desc,
    tools: [...s.tools],
    profiles: [...s.profiles],
    projects: [],
    enabled: true,
    pinned: !!s.pinned,
    packaged: true,
    invocations: 0,
    success: 0,
    avgTokensK: 0,
    trend: [],
  };
}

/** The initial skills library — the sample set, made editable. */
export function seedSkills(): SkillDef[] {
  return SKILLS.map(fromSample);
}

/** Packaged skill ids retired before the {@link SkillDef.packaged} marker existed.
 *  An already-seeded store persisted these as plain skills with no way to tell they
 *  were code-owned — list them here so {@link refreshPackagedSkills} prunes them.
 *  (Going forward, removing a packaged skill needs no entry: the `packaged` flag
 *  prunes it automatically.) */
const RETIRED_PACKAGED_SKILL_IDS = new Set([
  "scaffold-tauri-cmd", "add-screen-slice", "open-pr", "triage-failing-test",
  "bump-dep-safely", "wire-mcp-tool", "security-review", "api-docs", "rename-symbol",
]);

/**
 * Reconcile a persisted skills library with the code-owned packaged set on load
 * (mirrors blueprints' `refreshBuiltIns`, #677). The packaged skills are code-owned
 * but `skills` is persisted, so a store seeded before the library changed would keep
 * the old set forever. This:
 *   • refreshes each current packaged skill from code (preserving the user's
 *     enabled / pinned / project-scoping toggles),
 *   • prunes packaged skills dropped from the library (by the `packaged` flag or the
 *     retired-id list), and
 *   • leaves user-created / imported / catalog-added skills untouched.
 */
export function refreshPackagedSkills(persisted: SkillDef[]): SkillDef[] {
  const fresh = seedSkills();
  const seedIds = new Set(fresh.map((s) => s.id));
  const packaged = fresh.map((f) => {
    const prev = persisted.find((s) => s.id === f.id);
    return prev ? { ...f, enabled: prev.enabled, pinned: prev.pinned, projects: prev.projects } : f;
  });
  const user = persisted.filter(
    (s) => !seedIds.has(s.id) && !s.packaged && !RETIRED_PACKAGED_SKILL_IDS.has(s.id),
  );
  return [...packaged, ...user];
}

// Per-session skill resolution: which library skills apply to a project, and the
// per-session override layer (#1056 follow-up) — force a skill ON/OFF for one
// session over its inherited project resolution, with the reason label the UI shows.

import type { SkillDef } from "@/features/skills/lib/skillsModel";

/**
 * The enabled skills that apply to a session in `projectId`: a def applies when it
 * is enabled AND either global (`projects` empty) or scoped to this project. An
 * empty `projectId` (no project) yields only global defs.
 */
export function resolveSkills(all: SkillDef[], projectId: string): SkillDef[] {
  return all.filter(
    s => s.enabled && (s.projects.length === 0 || (!!projectId && s.projects.includes(projectId))),
  );
}

// ── Per-session assignment (#1056 follow-up) ────────────────────────────────────
// A session (a console pane, a fleet worker, a triage pane) INHERITS the skills that
// resolve for its project (enabled + global/project-scoped — see resolveSkills). On top
// of that the user can choose, per session, to force a skill ON (even one out of the
// session's project scope) or OFF (one it would otherwise inherit). The choice is keyed by
// the session's STABLE identity id so it survives a relaunch. The Skills UI (per-session
// surface) renders sessionSkillState per row; the launch path writes effectiveSessionSkills
// into the session's `.claude/skills/<slug>/SKILL.md`.

/** A user's per-session skill choices, layered over the inherited resolution. Both are
 *  skill ids; a skill in neither list inherits its project-resolved state. */
export interface SessionSkillOverride {
  /** Force ON for this session (incl. an enabled skill outside the session's project scope). */
  add: string[];
  /** Force OFF for this session (a skill it would otherwise inherit). */
  remove: string[];
}

/** Why a skill is on/off for a session — drives the per-session row label. */
export type SessionSkillReason =
  | "global"        // on: enabled + global (applies to every project)
  | "project"       // on: enabled + scoped to this session's project
  | "pinned"        // on (inherited) + pinned (auto-available to the fleet)
  | "group"         // on: enabled via a task group toggled onto this session/stream
  | "added"         // on: a user override turned it on for this session
  | "removed"       // off: a user override turned it off for this session
  | "out-of-scope"  // off: enabled but scoped to other projects (and not added)
  | "disabled";     // off: disabled in the library (never written to any session)

export interface SessionSkillState {
  skill: SkillDef;
  /** Whether this skill is written into the session (its `.claude/skills/<slug>`). */
  on: boolean;
  reason: SessionSkillReason;
  /** True when the effective state DIFFERS from what the session would inherit — i.e. a
   *  live user override (added / removed). */
  overridden: boolean;
}

/**
 * The effective on/off state + reason for one skill in one session, given the override and the
 * skills enabled via the session's task groups (`groupSkillIds`). `disabled` wins over everything
 * (a disabled skill is never invocable). The baseline is "inherited by project scope OR enabled by
 * a toggled-on group"; a remove/add per-skill override beats that baseline. An override that matches
 * the baseline is a no-op (`overridden: false`) so the UI never flags a redundant choice.
 */
export function sessionSkillState(
  skill: SkillDef, projectId: string, override?: SessionSkillOverride, groupSkillIds?: ReadonlySet<string>,
): SessionSkillState {
  if (!skill.enabled) return { skill, on: false, reason: "disabled", overridden: false };
  const inScope = skill.projects.length === 0 || (!!projectId && skill.projects.includes(projectId));
  const viaGroup = groupSkillIds?.has(skill.id) ?? false;
  const baseOn = inScope || viaGroup;            // `enabled` already guaranteed above
  const removed = override?.remove?.includes(skill.id) ?? false;
  const added = override?.add?.includes(skill.id) ?? false;
  const on = removed ? false : added ? true : baseOn;
  const overridden = on !== baseOn;
  let reason: SessionSkillReason;
  if (overridden) reason = on ? "added" : "removed";
  else if (on) reason = inScope ? (skill.pinned ? "pinned" : skill.projects.length === 0 ? "global" : "project") : "group";
  else reason = "out-of-scope";
  return { skill, on, reason, overridden };
}

/** The skills written into a session: every library skill whose {@link sessionSkillState} is `on`
 *  for this project + override + toggled-on groups. With no override/groups this equals
 *  {@link resolveSkills}. */
export function effectiveSessionSkills(
  all: SkillDef[], projectId: string, override?: SessionSkillOverride, groupSkillIds?: ReadonlySet<string>,
): SkillDef[] {
  return all.filter(s => sessionSkillState(s, projectId, override, groupSkillIds).on);
}

/** Layer a user choice onto a session's override (pure). "on" forces the skill on, "off"
 *  forces it off, "inherit" clears any override for it. Returns a fresh override; the caller
 *  drops it from the map when both lists are empty (back to pure inheritance). */
export function applySessionSkillChoice(
  override: SessionSkillOverride | undefined, skillId: string, choice: "on" | "off" | "inherit",
): SessionSkillOverride {
  const add = new Set(override?.add ?? []);
  const remove = new Set(override?.remove ?? []);
  add.delete(skillId);
  remove.delete(skillId);
  if (choice === "on") add.add(skillId);
  else if (choice === "off") remove.add(skillId);
  return { add: [...add], remove: [...remove] };
}

import { useEffect, useState } from "react";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { Box } from "@/shared/ui/layout/Box";
import { useAppStore } from "@/store";
import { parseSkillLog, aggregateSkillTelemetry, skillStatusKpis, type SkillStats } from "@/features/skills/lib/skillTelemetry";

/**
 * Live Skills KPIs for the app status bar (Skills page) — replaces the old hardcoded
 * `SKILL_KPIS` mock. Reads the real skill-usage telemetry (`bsc logs tail skill`, the same source
 * the Skills screen uses) plus the live library size.
 */
export function SkillsStatus() {
  const skillCount = useAppStore((s) => s.skills.length);
  const [stats, setStats] = useState<Record<string, SkillStats>>({});

  useEffect(() => {
    let cancelled = false;
    logsTail("skill", 4000)
      .then((lines) => {
        if (!cancelled) setStats(aggregateSkillTelemetry(parseSkillLog((lines ?? []).join("\n")), new Date()));
      });
    return () => { cancelled = true; };
  }, []);

  const { loaded, invToday, worst } = skillStatusKpis(skillCount, stats);
  return (
    <>
      <Box as="span" className="s"><i /> {loaded} {loaded === 1 ? "skill" : "skills"} loaded</Box>
      <Box as="span" className="s"><i /> {invToday} {invToday === 1 ? "invocation" : "invocations"} today</Box>
      {worst && <Box as="span" className="s"><i className="warn" /> {worst.skill} {worst.rate}%</Box>}
    </>
  );
}

// Skills feature store slice (#1309) — extracted from the former `session` grab-bag slice. Owns the
// skill library, the resolved per-pane set, per-session overrides, and task groups. Composed into
// the single app store by store/index.ts.
//
// Source of truth is the GLOBAL skills.db (#1338 ph2): this slice is a write-through cache. On boot
// `hydrateSkills` loads the library through the `bsc skill` bridge (#2142) and reconciles the
// code-owned packaged set; every library mutation below pushes through to the bridge so the desktop
// UI, the planner, and every live `bsc skill` session see ONE shared library. Per-session toggles
// (`sessionSkillOverrides` / `sessionSkillGroups`) are pane-local and stay store-only — they are not
// part of the global library. The persisted copy is just a fast first-paint cache; hydrate reconciles.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { SkillPayload } from "@/features/planner/blueprints/blueprintSkills";
import {
  seedSkills, refreshPackagedSkills, skillFromPayload, applySessionSkillChoice, skillSlug, skillContentKey,
  type SkillDef, type SessionSkillOverride, type SkillGroup,
} from "@/features/skills/lib/skills";
import { loadLibrary, pushSkill, dropSkill, pushGroup, dropGroup } from "@/features/skills/lib/skillBridge";
import { deleteMapEntry } from "@/store/updateHelpers";

export interface SkillsSlice {
  // Skills — reusable capability bundles (prompt + bundled tools + profile guardrails) the fleet can
  // invoke, each scoped via its `projects` ([] = global). Written into a launched session's
  // .claude/skills/<slug>/SKILL.md. Seeded from the sample library; persisted as a cache. (#404)
  skills: SkillDef[];
  /** Hydrate the library from the global skills.db on boot (#1338): load + reconcile the packaged
   *  set, then seed/refresh the db with the reconciled set. No-op (keeps the seeded set) when the
   *  bridge is unreachable — tests, the web shell, or an old binary. */
  hydrateSkills: () => Promise<void>;
  /** Lightweight re-read of the global skills.db into the cache (#1419): like {@link hydrateSkills}
   *  but WITHOUT the boot-time push-back of the whole set — cheap enough to poll while the planner
   *  runs, so skills the planner authors via `bsc-skill add` (and their session-group membership)
   *  appear live. No-op when the bridge is unreachable. */
  refreshSkills: () => Promise<void>;
  /** Reconstitute a shared blueprint's embedded skills into the library (#897 Phase 5b). */
  installBundledSkills: (payloads: SkillPayload[]) => void;
  addSkill: (def: Omit<SkillDef, "id">) => string;
  updateSkill: (id: string, patch: Partial<SkillDef>) => void;
  removeSkill: (id: string) => void;
  toggleSkill: (id: string) => void;
  toggleSkillPin: (id: string) => void;
  setSkillProjects: (id: string, projects: string[]) => void;
  /** Upsert planner-authored skills (skills.json), by id then name-slug, refining in place. */
  upsertSkills: (defs: Array<Omit<SkillDef, "id"> & { id?: string }>) => void;
  // Resolved per-pane skills (transient): set at session creation, read by TerminalView before
  // launch. Computed via effectiveSessionSkills so it already reflects overrides + groups.
  paneSkills: Record<string, SkillDef[]>;
  // Per-session skill choices, keyed by the session's STABLE identity id; persisted (#1056).
  sessionSkillOverrides: Record<string, SessionSkillOverride>;
  setSessionSkill: (sessionKey: string, skillId: string, choice: "on" | "off" | "inherit") => void;
  /** Drop ALL per-session overrides AND group toggles for a session — back to pure inheritance. */
  resetSessionSkills: (sessionKey: string) => void;
  // Task groups (#skills-groups) — named, reusable skill bundles toggled as one. Persisted as a cache.
  skillGroups: SkillGroup[];
  addSkillGroup: (name: string, hue?: string) => string;
  updateSkillGroup: (id: string, patch: Partial<Omit<SkillGroup, "id">>) => void;
  removeSkillGroup: (id: string) => void;
  toggleSkillGroupMember: (groupId: string, skillId: string) => void;
  upsertSkillGroups: (groups: Array<Omit<SkillGroup, "id"> & { id?: string }>) => void;
  /** Ensure the per-project planning session group exists with a fixed `id` and the given `name`
   *  (#1419): creates it (empty) if absent, else just renames it when the project title changed —
   *  never clobbering the members the planner has paired into it. */
  ensureSessionGroup: (id: string, name: string, hue?: string) => void;
  // Per-session enabled groups, keyed by the session's stable identity id; persisted.
  sessionSkillGroups: Record<string, string[]>;
  setSessionSkillGroup: (sessionKey: string, groupId: string, on: boolean) => void;
}

export const createSkillsSlice: StateCreator<AppStore, [], [], SkillsSlice> = (set, get) => ({
  skills: seedSkills(),
  hydrateSkills: async () => {
    const lib = await loadLibrary();
    if (!lib) return; // bridge unreachable — keep the seeded in-memory set
    // Reconcile the code-owned packaged skills over whatever the db held (first run: db empty →
    // just the packaged set; later: packaged refreshed from code + the user's skills preserved).
    const skills = refreshPackagedSkills(lib.skills);
    set({ skills, skillGroups: lib.groups });
    // Push ONLY skills the db is missing or whose authored content drifted (a packaged code update),
    // mirroring hydrateOrgs (#3672). A normal boot re-writes NOTHING — this used to unconditionally
    // re-push all ~40 packaged skills, a `bsc skill add` subprocess-spawn burst that jammed the backend
    // every boot. User-state edits (enabled/pinned/projects) still write through via their own actions.
    const dbKeys = new Map(lib.skills.map((s) => [s.id, skillContentKey(s)]));
    for (const s of skills) {
      const prior = dbKeys.get(s.id);
      if (prior === undefined || prior !== skillContentKey(s)) void pushSkill(s);
    }
  },
  refreshSkills: async () => {
    const lib = await loadLibrary();
    if (!lib) return; // bridge unreachable — keep the current cache
    // Re-read only; no push-back (that's hydrate's job). The db is the source of truth, and every
    // local edit already wrote through, so overwriting the cache from it can't lose anything.
    set({ skills: refreshPackagedSkills(lib.skills), skillGroups: lib.groups });
  },
  addSkill: (def) => {
    const id = `skill_${Math.random().toString(36).slice(2, 8)}`;
    const full = { ...def, id } as SkillDef;
    set((s) => ({ skills: [...s.skills, full] }));
    void pushSkill(full);
    return id;
  },
  installBundledSkills: (payloads) =>
    set((s) => {
      const haveSkill = new Set(s.skills.map((x) => x.id));
      const newSkills: SkillDef[] = [];
      for (const p of payloads) {
        if (haveSkill.has(p.id) || !p.id) continue;
        haveSkill.add(p.id);
        const def = skillFromPayload(p);
        newSkills.push(def);
        void pushSkill(def);
      }
      if (newSkills.length === 0) return {};
      return { skills: [...s.skills, ...newSkills] };
    }),
  updateSkill: (id, patch) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, ...patch } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  removeSkill: (id) => {
    set((s) => ({ skills: s.skills.filter((sk) => sk.id !== id) }));
    void dropSkill(id);
  },
  toggleSkill: (id) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, enabled: !sk.enabled } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  toggleSkillPin: (id) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, pinned: !sk.pinned } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  setSkillProjects: (id, projects) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, projects } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  upsertSkills: (defs) => {
    set((s) => {
      const skills = [...s.skills];
      for (const def of defs) {
        const slug = skillSlug(def.name);
        const idx = skills.findIndex(
          (sk) => (def.id && sk.id === def.id) || skillSlug(sk.name) === slug,
        );
        if (idx >= 0) {
          const rest = { ...def };
          delete rest.id;
          skills[idx] = { ...skills[idx], ...rest };
        } else {
          skills.push({ ...def, id: def.id ?? `skill_${Math.random().toString(36).slice(2, 8)}` });
        }
      }
      return { skills };
    });
    // Push the resolved (post-merge) rows for the affected names so the db mirrors the store.
    const bySlug = new Map(get().skills.map((sk) => [skillSlug(sk.name), sk] as const));
    for (const def of defs) {
      const merged = bySlug.get(skillSlug(def.name));
      if (merged) void pushSkill(merged);
    }
  },
  paneSkills: {},

  sessionSkillOverrides: {},
  setSessionSkill: (sessionKey, skillId, choice) =>
    set((s) => {
      const next = applySessionSkillChoice(s.sessionSkillOverrides[sessionKey], skillId, choice);
      const map = { ...s.sessionSkillOverrides };
      if (next.add.length === 0 && next.remove.length === 0) delete map[sessionKey];
      else map[sessionKey] = next;
      return { sessionSkillOverrides: map };
    }),
  resetSessionSkills: (sessionKey) =>
    set((s) => {
      const hadOverride = !!s.sessionSkillOverrides[sessionKey];
      const hadGroups = !!s.sessionSkillGroups[sessionKey];
      if (!hadOverride && !hadGroups) return {};
      return {
        sessionSkillOverrides: deleteMapEntry(s.sessionSkillOverrides, sessionKey),
        sessionSkillGroups: deleteMapEntry(s.sessionSkillGroups, sessionKey),
      };
    }),

  // ── Task groups (#skills-groups) ──────────────────────────────────────
  skillGroups: [],
  addSkillGroup: (name, hue) => {
    const id = `grp_${Math.random().toString(36).slice(2, 8)}`;
    const group: SkillGroup = { id, name, hue: hue ?? "var(--accent)", skillIds: [] };
    set((s) => ({ skillGroups: [...s.skillGroups, group] }));
    void pushGroup(group);
    return id;
  },
  updateSkillGroup: (id, patch) => {
    set((s) => ({ skillGroups: s.skillGroups.map((g) => (g.id === id ? { ...g, ...patch } : g)) }));
    const updated = get().skillGroups.find((g) => g.id === id);
    if (updated) void pushGroup(updated);
  },
  removeSkillGroup: (id) => {
    set((s) => {
      const sessionSkillGroups: Record<string, string[]> = {};
      for (const [k, ids] of Object.entries(s.sessionSkillGroups)) {
        const kept = ids.filter((g) => g !== id);
        if (kept.length) sessionSkillGroups[k] = kept;
      }
      return { skillGroups: s.skillGroups.filter((g) => g.id !== id), sessionSkillGroups };
    });
    void dropGroup(id);
  },
  ensureSessionGroup: (id, name, hue) => {
    // Lazy session group (#1616): never PRE-CREATE. `bsc-skill add --group <id>` creates the group on
    // the planner's FIRST authored skill (placeholder name = its id, empty hue); here we only ADOPT it
    // once it exists — rename the placeholder to the project name (and on later title changes) and fill
    // the empty placeholder hue, never clobbering members or a user-set color. A project that authors
    // no skills never gets an empty group written to skills.db.
    const existing = get().skillGroups.find((g) => g.id === id);
    if (!existing) return;
    const patch: Partial<Omit<SkillGroup, "id">> = {};
    if (name && existing.name !== name) patch.name = name;
    if (!existing.hue) patch.hue = hue ?? "var(--violet)";
    if (Object.keys(patch).length > 0) get().updateSkillGroup(id, patch);
  },
  toggleSkillGroupMember: (groupId, skillId) => {
    set((s) => ({
      skillGroups: s.skillGroups.map((g) => {
        if (g.id !== groupId) return g;
        const has = g.skillIds.includes(skillId);
        return { ...g, skillIds: has ? g.skillIds.filter((x) => x !== skillId) : [...g.skillIds, skillId] };
      }),
    }));
    const updated = get().skillGroups.find((g) => g.id === groupId);
    if (updated) void pushGroup(updated);
  },
  upsertSkillGroups: (groups) => {
    set((s) => {
      const next = [...s.skillGroups];
      for (const g of groups) {
        const slug = skillSlug(g.name);
        const idx = next.findIndex((x) => (g.id && x.id === g.id) || skillSlug(x.name) === slug);
        if (idx >= 0) {
          const rest = { ...g }; delete rest.id;
          next[idx] = { ...next[idx], ...rest };
        } else {
          next.push({ ...g, id: g.id ?? `grp_${Math.random().toString(36).slice(2, 8)}` });
        }
      }
      return { skillGroups: next };
    });
    const bySlug = new Map(get().skillGroups.map((g) => [skillSlug(g.name), g] as const));
    for (const g of groups) {
      const merged = bySlug.get(skillSlug(g.name));
      if (merged) void pushGroup(merged);
    }
  },
  sessionSkillGroups: {},
  setSessionSkillGroup: (sessionKey, groupId, on) =>
    set((s) => {
      const cur = s.sessionSkillGroups[sessionKey] ?? [];
      const next = on ? (cur.includes(groupId) ? cur : [...cur, groupId]) : cur.filter((g) => g !== groupId);
      const map = { ...s.sessionSkillGroups };
      if (next.length) map[sessionKey] = next;
      else delete map[sessionKey];
      return { sessionSkillGroups: map };
    }),
});

