import { describe, it, expect } from "vitest";
import {
  migrationSources, proposedSourceIds, connectFieldsFor, SOURCE_DIRECTION,
  type DeclaredIntegration,
} from "@/features/planner/lib/sourceDiscovery";

const row = (id: string, direction: string, extra: Partial<DeclaredIntegration> = {}): DeclaredIntegration =>
  ({ id, direction, ...extra });

describe("migrationSources (#4054)", () => {
  // THE point of the direction split. A payment API is not something you migrate off, and offering it
  // as one sends the user down a pointless connect-and-scan path.
  it("keeps only `source` rows — a runtime integration NEVER reaches the Source pane", () => {
    const rows = [row("salesforce", "source"), row("stripe", "runtime"), row("netsuite", "source")];
    expect(migrationSources(rows).map((r) => r.id)).toEqual(["salesforce", "netsuite"]);
  });

  it("preserves declaration order", () => {
    const rows = [row("zeta", "source"), row("alpha", "source")];
    expect(migrationSources(rows).map((r) => r.id)).toEqual(["zeta", "alpha"]);
  });

  // Defensive: the pane must not depend on the caller having passed --direction, and a row with a
  // missing/blank/unknown direction is not evidence of a migration source.
  it("drops rows with a missing, blank or unknown direction", () => {
    const rows = [row("a", ""), { id: "b" } as DeclaredIntegration, row("c", "inbound"), row("d", SOURCE_DIRECTION)];
    expect(migrationSources(rows).map((r) => r.id)).toEqual(["d"]);
  });

  it("drops unusable ids and collapses duplicates to the first", () => {
    const rows = [row("", "source"), row("   ", "source"), row("dup", "source", { name: "First" }), row("dup", "source", { name: "Second" })];
    const out = migrationSources(rows);
    expect(out.map((r) => r.id)).toEqual(["dup"]);
    expect(out[0].name).toBe("First");
  });

  it("trims the id and survives an empty/degenerate input", () => {
    expect(migrationSources([row("  padded  ", "source")])[0].id).toBe("padded");
    expect(migrationSources([])).toEqual([]);
    expect(migrationSources(undefined as unknown as DeclaredIntegration[])).toEqual([]);
  });
});

describe("proposedSourceIds — Discovery wins, the pitch scan is the fallback", () => {
  it("prefers the confirmed Discovery rows over a pitch guess", () => {
    const out = proposedSourceIds([row("salesforce", "source")], ["hubspot", "zendesk"]);
    expect(out).toEqual({ ids: ["salesforce"], origin: "discovery" });
  });

  // The behaviour a project whose Discovery predates #4024 must keep — no regression for anyone who
  // never worked the `integrations` topic.
  it("falls back to the pitch scan when nothing was declared", () => {
    expect(proposedSourceIds([], ["hubspot"])).toEqual({ ids: ["hubspot"], origin: "pitch" });
  });

  // A project that declared ONLY runtime integrations has said nothing about migration sources, so
  // the pitch scan is still the best available signal — `source`-less is not the same as undeclared.
  it("falls back when every declared integration is runtime-only", () => {
    expect(proposedSourceIds([row("stripe", "runtime")], ["hubspot"]).origin).toBe("pitch");
  });

  it("reports `none` when neither has anything, and never proposes a blank id", () => {
    expect(proposedSourceIds([], [])).toEqual({ ids: [], origin: "none" });
    expect(proposedSourceIds([], ["", "ok"])).toEqual({ ids: ["ok"], origin: "pitch" });
  });

  it("returns a fresh array rather than aliasing the caller's pitch list", () => {
    const pitch = ["hubspot"];
    const out = proposedSourceIds([], pitch);
    out.ids.push("mutated");
    expect(pitch).toEqual(["hubspot"]);
  });
});

describe("connectFieldsFor — what Discovery captured reaches the connect form", () => {
  it("carries the base URL and docs so the agent starts from the vendor reference", () => {
    const rows = [row("salesforce", "source", {
      baseUrl: "https://acme.my.salesforce.com", docs: "https://developer.salesforce.com",
    })];
    expect(connectFieldsFor("salesforce", rows)).toEqual({
      baseUrl: "https://acme.my.salesforce.com", docs: "https://developer.salesforce.com",
    });
  });

  // `auth` is a prose SCHEME, not a field value — and keeping it off this path means there is nothing
  // credential-shaped travelling into the connect form's value bag at all.
  it("never carries auth, purpose or name into the connect fields", () => {
    const rows = [row("x", "source", { auth: "OAuth2 client credentials", purpose: "migrate accounts", name: "X" })];
    expect(connectFieldsFor("x", rows)).toEqual({});
  });

  it("omits blank values instead of seeding an empty URL", () => {
    expect(connectFieldsFor("x", [row("x", "source", { baseUrl: "   ", docs: "" })])).toEqual({});
  });

  it("returns nothing for an unknown id, or for one that is a runtime integration", () => {
    const rows = [row("stripe", "runtime", { baseUrl: "https://api.stripe.com" })];
    expect(connectFieldsFor("nope", rows)).toEqual({});
    expect(connectFieldsFor("stripe", rows)).toEqual({});
  });
});

implementations.code:
// Migration SOURCE gate (#source-pane) — the pure readiness/gate helpers that drive the Source
// stage: connection counts + readiness checks, the `sourcesConnected` gate signal, and the
// Data Model gate signals derived from the live scan state (so the gate reflects scan progress
// without a round-trip to the store). Split out of sourceValidate.ts (#1712); the Data Model derivation
// lives in dataModelDerivation.ts and the type model in sourceSpecs.ts.

import type { ReadinessCheck } from "@/features/planner/lib/readiness";
import { deriveDataModel } from "@/features/planner/lib/dataModelDerivation";
import type { DeclaredSource, SourceConfig } from "@/features/planner/lib/sourceSpecs";

/** A source counts as "connected" once it is scanning or fully scanned (authorized, secret on device). */
export function isConnected(s: DeclaredSource): boolean {
  return s.status === "scanning" || s.status === "scanned";
}

/** How many declared sources are connected. */
export function connectedCount(cfg: SourceConfig): number {
  return cfg.sources.filter(isConnected).length;
}

/** The `sourcesConnected` gate signal: ≥1 source declared and EVERY one fully scanned (no pending or
 *  errored source). An empty set can't pass (nothing to migrate from ⇒ the stage shouldn't apply). */
export function allSourcesConnected(cfg: SourceConfig | undefined): boolean {
  return !!cfg && cfg.sources.length > 0 && cfg.sources.every((s) => s.status === "scanned");
}

/** Readiness checks driving the in-pane banner: every declared source scanned, none errored. */
export function sourceChecks(cfg: SourceConfig): ReadinessCheck[] {
  const total = cfg.sources.length;
  const scanned = cfg.sources.filter((s) => s.status === "scanned").length;
  const errored = cfg.sources.filter((s) => s.status === "error").length;
  return [
    { id: "declared", label: "Declare the systems you're migrating from", ok: total > 0, detail: `${total} source${total !== 1 ? "s" : ""}` },
    { id: "connected", label: "Connect & scan every source", ok: total > 0 && scanned === total, detail: `${scanned}/${total} connected` },
    { id: "healthy", label: "No connection errors", ok: errored === 0, detail: errored ? `${errored} failed` : "all healthy" },
  ];
}

/** Whether a migration source is active for the project (≥1 declared source) — drives the `source`
 *  stage's `migrationSourceEnabled` so the stage applies. */
export function migrationActive(cfg: SourceConfig | undefined): boolean {
  return !!cfg && cfg.sources.length > 0;
}

/** The Data Model gate signals derived from the live scan state (feeds derivePlanStageState), so the
 *  source stage's gate reflects scan progress without reading back the canonical model. The canonical
 *  Data Model itself lives in the project's DuckDB store (`bsc data model get`, #1446) — these are
 *  progress booleans about the scan, not a read of that store. */
export function dataModelSignals(cfg: SourceConfig | undefined): { sourceReachable: boolean; modelInferred: boolean; schemaRefined: boolean } {
  if (!cfg) return { sourceReachable: false, modelInferred: false, schemaRefined: false };
  return {
    sourceReachable: cfg.sources.some((s) => s.status === "scanning" || s.status === "scanned"),
    modelInferred: cfg.sources.some((s) => s.status === "scanned"),
    schemaRefined: allSourcesConnected(cfg),
  };
}

/** The downstream-impact recap: what the scanned sources seed into features + structure. */
export function downstreamImpact(cfg: SourceConfig): { entities: number; fields: number; behaviors: number } {
  const m = deriveDataModel(cfg);
  const behaviors = cfg.sources.reduce((n, s) => {
    const p = s.platform;
    return n + (p ? p.automations.length + p.businessProcesses.length + p.derivedLogic.length : s.behaviors?.length ?? 0);
  }, 0);
  return { entities: m.entities.length, fields: m.entities.reduce((n, e) => n + e.fields.length, 0), behaviors };
}

// Migration SOURCE scan visualizations (#1209) — the view-models behind the Source pane's Graph /
// List / Process views: the entities (with record counts, source provenance, fields + inferred refs)
// the Graph + List views render, the ref edges for the Graph, the aggregated structured behaviors the
// Process view renders, and the multi-source provenance flag. Built from the derived Data Model and
// the scanned objects. Split out of sourceValidate.ts (#1712); the derivation lives in
// dataModelDerivation.ts and the per-source colors in sourceCatalog.ts.

import type { FieldType } from "@/features/planner/data/dataModel";
import { deriveDataModel, safeKey } from "@/features/planner/lib/dataModelDerivation";
import { connectorColor } from "@/features/planner/lib/sourceCatalog";
import type { PlatformScanView, SourceConfig } from "@/features/planner/lib/sourceSpecs";

export interface ScanViewField { key: string; type: FieldType; required: boolean; identity: boolean; ref?: string; refLabel?: string; enumValues?: string[] }
export interface ScanViewEntity { key: string; label: string; count: number; source: string; srcColor: string; fields: ScanViewField[] }

/** The entities (with record counts, source provenance, fields + inferred refs) the Graph + List
 *  views render — built from the derived model and the scanned objects. */
export function scanEntities(cfg: SourceConfig): ScanViewEntity[] {
  const model = deriveDataModel(cfg);
  const labelByKey = new Map(model.entities.map((e) => [e.key, e.label ?? e.key]));
  const meta = new Map<string, { count: number; source: string }>();
  for (const s of cfg.sources) {
    if (s.status !== "scanned") continue;
    for (const o of s.objects ?? []) {
      const k = safeKey(o.name) || "entity";
      if (!meta.has(k)) meta.set(k, { count: o.count, source: s.connectorId }); // first wins (matches dedup)
    }
  }
  return model.entities.map((e) => {
    const m = meta.get(e.key) ?? { count: 0, source: "" };
    return {
      key: e.key,
      label: e.label ?? e.key,
      count: m.count,
      source: m.source,
      srcColor: connectorColor(m.source),
      fields: e.fields.map((f) => ({
        key: f.key, type: f.type, required: !!f.required, identity: e.identity.includes(f.key),
        ref: f.ref, refLabel: f.ref ? labelByKey.get(f.ref) ?? f.ref : undefined,
        enumValues: f.enum_values,
      })),
    };
  });
}

/** All ref relationships as edges for the Graph view. */
export function scanEdges(entities: ScanViewEntity[]): { from: string; to: string; label: string }[] {
  const keys = new Set(entities.map((e) => e.key));
  const edges: { from: string; to: string; label: string }[] = [];
  for (const e of entities) {
    for (const f of e.fields) {
      if (f.ref && keys.has(f.ref)) edges.push({ from: e.key, to: f.ref, label: `${f.key} → ${f.refLabel ?? f.ref}` });
    }
  }
  return edges;
}

/** The aggregated structured behaviors (across scanned sources) the Process view renders. */
export function aggregatePlatform(cfg: SourceConfig): PlatformScanView {
  const out: PlatformScanView = { automations: [], businessProcesses: [], derivedLogic: [] };
  for (const s of cfg.sources) {
    if (s.status !== "scanned" || !s.platform) continue;
    out.automations.push(...s.platform.automations);
    out.businessProcesses.push(...s.platform.businessProcesses);
    out.derivedLogic.push(...s.platform.derivedLogic);
  }
  return out;
}

/** Whether ≥2 distinct connector sources fed the scan (drives per-source provenance badges). */
export function isMultiSource(cfg: SourceConfig): boolean {
  return new Set(cfg.sources.filter((s) => s.status === "scanned").map((s) => s.connectorId)).size > 1;
}

// Migration SOURCE specs (#source-pane) — the pure type model behind the planner's Source stage:
// the per-connector connection contract (auth + form fields), the discovered inventory shape a scan
// returns, the structured behavior scan, and the per-project SourceConfig the Source pane edits.
// Split out of sourceConfig.ts (#1638); the connector catalog lives in sourceCatalog.ts and the
// gate/derivation/scan-view helpers in sourceGate.ts / dataModelDerivation.ts / sourceScanViews.ts.
// sourceConfig.ts re-exports them all.
//
// SECURITY BOUNDARY: a connector's SECRET field values NEVER live in this config (they go to the OS
// keychain on the device and are never persisted here or shared with the planning agent). The config
// keeps only non-secret fields, a redacted `handle`, and the discovered (not extracted) inventory.

import type { FieldType } from "@/features/planner/data/dataModel";

/** How a connector authenticates — drives which card the per-source ConnectionSpec renders. */
export type AuthMethod = "oauth" | "token" | "password" | "basic" | "apiKey" | "open" | "upload";

/** One input a connector's form collects. A `secret` field is masked, kept on-device, and never
 *  written into {@link DeclaredSource.fields}. */
export interface SpecField {
  key: string;
  label: string;
  /** Masked + keychain-bound; never persisted to the config or shared with the planner. */
  secret?: boolean;
  /** Optional field — absence doesn't block connecting (e.g. an app id that just scopes the scan). */
  optional?: boolean;
  hint?: string;
  placeholder?: string;
}

/** The per-connector connection contract — the same surface renders a different page from this. */
export interface ConnectionSpec {
  auth: AuthMethod;
  /** Form fields for token/password/basic/apiKey connectors (empty for oauth/upload). */
  fields: SpecField[];
  /** OAuth button label, e.g. "Connect to Salesforce" (oauth connectors only). */
  oauthLabel?: string;
  /** Show a Production / Sandbox environment toggle (oauth connectors). */
  envs?: boolean;
  /** One-line "will contribute →" summary of what a scan pulls in (objects + behaviors). */
  contributes: string;
}

/** A catalog connector the user can declare as a source. */
export interface Connector {
  id: string;
  name: string;
  /** Two/three-char mono badge, e.g. "QB". */
  badge: string;
  /** Catalog auth blurb, e.g. "OAuth" / "token" / "API key". */
  authLabel: string;
  spec: ConnectionSpec;
  /** Coarse grouping for the catalog UI (#1288) — `crm`, `erp`, `work`, … ; absent for the
   *  dedicated core connectors. */
  category?: string;
  /** A packaged generic-REST vendor preset (#1288), vs a dedicated connector. */
  preset?: boolean;
}

/** A discovered field: name + an inferred type + (for enums) the observed values (#1219). */
export interface DiscoveredField { name: string; type?: FieldType; enumValues?: string[]; ref?: string }
/** An object/table the scan discovered in a connected source (a count, not extracted rows).
 *  `fields` accepts bare column names (older fixtures) or typed {@link DiscoveredField}s (the live
 *  scan) — used to seed the derived Data Model's entity fields + types. */
export interface DiscoveredObject { name: string; count: number; fields?: (string | DiscoveredField)[] }
/** A behavior (business rule / automation) the scan found — these shape the target app, not just data. */
export interface SourceBehavior { label: string }

// ── Structured behavior scan (the Process visualization, #1209) ──────────────────────────────
// Mirrors the Rust `bsc_data::PlatformScan` (serde camelCase). The scan returns this alongside the
// flat `behaviors` labels; the Process view renders the detail (trigger → condition → actions, etc.).
export type ScanAutomationKind = "validation" | "workflow" | "flow" | "processBuilder" | "recurring" | "other";
export interface ScanAutomation {
  source: string; kind: ScanAutomationKind; name: string; object: string;
  active: boolean; trigger: string; condition: string; actions: string[];
}
export interface ScanBusinessProcess { source: string; name: string; object: string; active: boolean; steps: string[] }
export type ScanDerivedKind = "formula" | "code";
export interface ScanDerivedLogic { source: string; kind: ScanDerivedKind; name: string; object?: string; expression: string }
export interface PlatformScanView {
  automations: ScanAutomation[];
  businessProcesses: ScanBusinessProcess[];
  derivedLogic: ScanDerivedLogic[];
}

/** The lifecycle of one declared source. `declared` = chosen, not yet authorized; `connecting` =
 *  validating credentials; `scanning` = authorized, discovering objects; `scanned` = inventory in
 *  hand; `error` = auth/connection failed (holds the gate). */
export type SourceStatus = "declared" | "connecting" | "scanning" | "scanned" | "error";

/** A source the user declared they're migrating from. */
export interface DeclaredSource {
  uid: string;
  connectorId: string;
  /** Friendly instance label once connected, e.g. "Acme Co". */
  instance?: string;
  env?: "production" | "sandbox";
  status: SourceStatus;
  /** Non-secret field values (keyed by ConnectionSpec field key). SECRETS ARE NEVER STORED HERE. */
  fields: Record<string, string>;
  /** Redacted handle the planner is allowed to see ("Acme Co · Production · held by app"). */
  handle?: string;
  /** A secret was saved to the device keychain (we keep the flag, never the value). */
  secretSaved?: boolean;
  objects?: DiscoveredObject[];
  behaviors?: SourceBehavior[];
  /** The structured behavior scan (automations / processes / derived logic) for the Process view (#1209). */
  platform?: PlatformScanView;
  /** Failure reason for the error state, e.g. "token rejected (401)". */
  error?: string;
}

export interface SourceConfig {
  /** The canonical Data Model every connected source feeds, e.g. "Acme Core". */
  dataModelName: string;
  /** Connector ids the planner proposed from the pitch (the pre-declare ★ banner); cleared once acted on. */
  proposed: string[];
  sources: DeclaredSource[];
}

/** A fresh, empty source config. */
export function defaultSourceConfig(): SourceConfig {
  return { dataModelName: "", proposed: [], sources: [] };
}

/** A new declared source for `connectorId` (status `declared`, no fields yet). */
export function newDeclaredSource(connectorId: string, uid: string): DeclaredSource {
  return { uid, connectorId, status: "declared", fields: {} };
}

// space.ts — the shared vocabulary the layout kit (Stack/Row/Spacer) is built on (#2056).
//
// One spacing scale, one alignment mapping. The named `Space` sizes mirror the `--sp-*` CSS
// tokens in tokens.css (xs=4 … xl=24) so the kit and the stylesheet speak the same scale — but
// a raw pixel number is always legal too (the very common `gap:10` stays `gap={10}`), which
// keeps mechanical `<div style>` → primitive conversions lossless.

import type { CSSProperties } from "react";

/** A spacing value: a named scale rung, or a raw pixel number for the off-scale cases. */
export type Space = number | "xs" | "sm" | "md" | "lg" | "xl";

/** Cross-axis / main-axis alignment, friendly names (map to their flexbox values). */
export type Align = "start" | "center" | "end" | "baseline" | "stretch";
export type Justify = "start" | "center" | "end" | "between" | "around" | "evenly";

const SCALE: Record<Exclude<Space, number>, number> = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24 };

const ALIGN: Record<Align, CSSProperties["alignItems"]> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  baseline: "baseline",
  stretch: "stretch",
};

const JUSTIFY: Record<Justify, CSSProperties["justifyContent"]> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  between: "space-between",
  around: "space-around",
  evenly: "space-evenly",
};

/** Resolve a `Space` to a pixel number (named rung → scale, number → itself). */
export function space(v: Space | undefined): number | undefined {
  if (v == null) return undefined;
  return typeof v === "number" ? v : SCALE[v];
}

/** Resolve a friendly `Align` to its CSS box-alignment value. Shared by the flex + grid kit. */
export function alignValue(a: Align): CSSProperties["alignItems"] {
  return ALIGN[a];
}

/** Resolve a friendly `Justify` to its CSS distribution value. Shared by the flex + grid kit. */
export function justifyValue(j: Justify): CSSProperties["justifyContent"] {
  return JUSTIFY[j];
}

/** Resolve a padding shorthand: a single `Space` (all sides) or `[block, inline]`. */
export function pad(v: Space | [Space, Space] | undefined): CSSProperties["padding"] {
  if (v == null) return undefined;
  if (Array.isArray(v)) return `${space(v[0])}px ${space(v[1])}px`;
  const n = space(v);
  return n == null ? undefined : `${n}px`;
}

export interface FlexOptions {
  gap?: Space;
  align?: Align;
  justify?: Justify;
  wrap?: boolean;
}

/** Build the flex-layout portion of a style object shared by Stack and Row. */
export function flexStyle({ gap, align, justify, wrap }: FlexOptions): CSSProperties {
  const s: CSSProperties = {};
  const g = space(gap);
  if (g != null) s.gap = g;
  if (align) s.alignItems = ALIGN[align];
  if (justify) s.justifyContent = JUSTIFY[justify];
  if (wrap) s.flexWrap = "wrap";
  return s;
}

