describe("buildBlueprintsPayload", () => {
  const team = {
    positions: [{ nodeId: "n1", kind: "agent" as const, personaId: "p1" }],
    relationships: [],
  };
  const bp = (id: string, over: Partial<Blueprint> = {}): Blueprint => ({
