describe("buildComponentsPayload", () => {
  it("summarizes components (identity/classification/reuse) and drops source bodies", () => {
    const component: ComponentRecord = {
      id: "c1", name: "Button", kitId: "react-ui", role: "primitive", version: "1.0.0",
      used: 12, tags: ["control"], variants: ["ghost"], composes: [],
      props: [{ name: "kind", type: "string", req: false, desc: "visual kind" }],
      whenUse: ["actions"], whenNot: ["nav"], src: "src/Button.tsx", srcText: "SOURCE BODY",
    };
    const kit: Kit = { id: "react-ui", name: "React UI", stack: "React · TS", dot: "#7aa2ff" };
    const out = buildComponentsPayload({
      kits: [kit],
      components: [component],
      usage: [{ projectKey: "demo", kitId: "react-ui" }],
    });
    expect(out.kits).toEqual([kit]);
    expect(out.components[0]).toEqual({
      id: "c1", name: "Button", kitId: "react-ui", role: "primitive", version: "1.0.0",
      used: 12, tags: ["control"], variants: ["ghost"], composes: [], builtin: undefined,
    });
    expect(JSON.stringify(out)).not.toContain("SOURCE BODY");
    expect(out.usage[0].projectKey).toBe("demo");
  });

  it("carries the declarative `spec` so a mobile shell can render a screen authored HERE", () => {
    // The distinction this asserts is the whole reason `spec` crosses while `srcText` does not:
    // source is CODE the phone cannot run, a spec is DATA naming primitives it implements
    // natively. Without this field a mobile SpecHost can only draw specs bundled inside the
    // phone's own repo — which inverts where screens are authored.
    const spec = {
      type: "Card",
      children: [{ type: "Text", props: { tone: "accent" }, children: "Status" }],
    } as ComponentRecord["spec"];
    const withSpec: ComponentRecord = {
      id: "c2", name: "StatusCard", kitId: "react-ui", role: "composite", version: "2.1.0",
      used: 3, tags: [], variants: [], composes: [], src: "src/StatusCard.tsx",
      srcText: "SOURCE BODY", spec,
    };
    const out = buildComponentsPayload({ kits: [], components: [withSpec], usage: [] });
    expect(out.components[0].spec).toEqual(spec);
    // Passed through verbatim, not pared: the renderer validates the tree against the manifest on
    // arrival, and a partially-projected node would fail as "malformed" rather than "unsupported".
    expect(out.components[0].spec).toBe(spec);
    // …and the source body still does NOT cross, which is the line being drawn.
    expect(JSON.stringify(out)).not.toContain("SOURCE BODY");
  });

  it("leaves an absent spec ABSENT rather than defaulting it to an empty node", () => {
    // A phone reads "no spec authored" and "a spec that renders nothing" differently: the first
    // falls back to a bundled baseline, the second draws an empty screen. Defaulting would make
    // every spec-less component silently render blank.
    const bare: ComponentRecord = {
      id: "c3", name: "Divider", kitId: "react-ui", role: "primitive", version: "1.0.0",
      used: 1, tags: [], variants: [], composes: [], src: "src/Divider.tsx",
    };
    const out = buildComponentsPayload({ kits: [], components: [bare], usage: [] });
    expect(out.components[0].spec).toBeUndefined();
    expect(JSON.stringify(out.components[0])).not.toContain("spec");
  });
});

