// The teams feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/teams")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Team from "@/features/teams/lib/team";
import * as OrgLayout from "@/features/teams/lib/orgLayout";
import * as OrgView from "@/features/teams/lib/orgView";
import * as OrgPools from "@/features/teams/lib/orgPools";
import * as TeamsLayout from "@/features/teams/lib/teamsLayout";
// `d3-force`, registered HERE and not in `appModules`: only the teams auto-layout uses the
// simulation, and registration is EAGER — the shell's set would pay for it at boot.
import * as D3Force from "d3-force";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerTeamsPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/teams/lib/team", Team);
  registerAppModule("@/features/teams/lib/orgLayout", OrgLayout);
  registerAppModule("@/features/teams/lib/orgView", OrgView);
  registerAppModule("@/features/teams/lib/orgPools", OrgPools);
  registerAppModule("@/features/teams/lib/teamsLayout", TeamsLayout);
  registerAppModule("d3-force", D3Force);
}

// The shadow catalogue registers this feature's graph-platform modules by importing
// `./graphPlatform` DIRECTLY and calling its register function (see `shadowPages.ts`). This barrel
// therefore has NO import-time side effect — it is re-exports only, which is what lets it be a
// record rather than a file that must run to be correct.

// Team feature (#2193) — the persona-relationship graph: positions wired by relationship archetypes
// that expand into communication forms. Public API barrel.
// The screen itself is the `teamspage` RECORD, mounted by `TeamsGraphHost` — which is what
// `lazyWorkspaces` renders for the Teams rail destination. `TeamsPanel` stays exported because the
// host loads it BY NAME from the graph, and because a caller that wants the bundled component (a
// test, a detached window) must still be able to reach it.
export { TeamsGraphHost } from "@/features/teams/TeamsGraphHost";
export { TeamsPanel } from "@/features/teams/TeamsPanel";
export { TeamsCanvas, OrgLegend, type Selection } from "@/features/teams/TeamsCanvas";
export { TeamsInspector } from "@/features/teams/TeamsInspector";
export { FormChip, FormLane } from "@/features/teams/components";
export { createOrgSlice, type OrgSlice } from "@/features/teams/store";
export {
  positionDisplay, positionComms, tierChips, formColor, formArrow, hueColor, ROLE_META,
  type PositionDisplay, type CommSummary,
} from "@/features/teams/lib/orgView";
export { nodeBox, edgeGeometry, autoLayout, NODE_SIZE, CANVAS_W, CANVAS_H } from "@/features/teams/lib/orgLayout";
// `anchor` lives in the shared graph core since #2418 (org's copy was byte-identical); `clampZoom`
// was dead vs useGraphViewport's clamping and was dropped.
export { anchor } from "@/shared/lib/graph/edgePath";
export { detectPools, collapseOrg, poolSubgraph, type Pool, type CollapsedOrg } from "@/features/teams/lib/orgPools";
export {
  BUILTIN_ORGS, RELATIONSHIP_ARCHETYPES, COMMUNICATION_FORMS,
  makeBuiltinOrgs, reconcileOrgs, blankOrg, orgSlug, orgIssues, deriveCommunication,
  augmentStudioNetworkForRequests, requestNodeLabel, STUDIO_NETWORK_ID,
  expandStudioPerTechnology, studioNetworkForArchitect, ARCHITECT_NODE,
  // THE ONE per-technology studio-node roster (`the-studio-session-set-is-derived-not-declared`).
  // Exported because Glance's fleet graph kept a SECOND copy of it and the two drifted — a
  // technology present in one and not the other is a node that draws and opens nothing.
  // `studioNodeRoster.test.ts` pins this one against the store the technologies come from.
  PER_TECH_STUDIO_NODES,
  archetypeById, formById,
  type Team, type Position, type Relationship, type RelationshipArchetype,
  type CommunicationForm, type CommEdge, type PositionKind, type RequestNodeSpec, type OriginHostResolver,
} from "@/features/teams/lib/team";

// Teams-overview layout (#2742) — the NEW top graph level: every team is a card laid out in a grid, so
// the user navigates teams IN the graph (click a card to enter) instead of a header dropdown. Pure +
// deterministic (no Date/Math.random), so `teamsBounds` can drive the viewport fit exactly like the
// per-team `contentBounds`. Card boxes are in the same design space as position `nodeBox`es.
import type { Box } from "@/features/teams/lib/orgLayout";
import { positionDisplay } from "@/features/teams/lib/orgView";
import type { Team } from "@/features/teams/lib/team";
import type { Persona } from "@/features/personas";

export const TEAM_CARD_W = 288;
export const TEAM_CARD_H = 160;
const GAP_X = 40;
const GAP_Y = 44;
const ORIGIN_X = 60;
const ORIGIN_Y = 56;

/** Column count for `count` cards — a squarish grid, capped at 3 wide so cards stay readable. */
function columns(count: number): number {
  return Math.max(1, Math.min(3, Math.ceil(Math.sqrt(Math.max(1, count)))));
}

/** Grid boxes for `count` cells (team cards + the trailing "new team" card), row-major. */
export function teamsGrid(count: number): Box[] {
  const cols = columns(count);
  return Array.from({ length: count }, (_, i) => {
    const r = Math.floor(i / cols), c = i % cols;
    return {
      x: ORIGIN_X + c * (TEAM_CARD_W + GAP_X),
      y: ORIGIN_Y + r * (TEAM_CARD_H + GAP_Y),
      w: TEAM_CARD_W, h: TEAM_CARD_H,
    };
  });
}

/** The tight bounding box around all `count` cells — what the viewport fits/centers on (#2673-style). */
export function teamsBounds(count: number): Box | null {
  if (count <= 0) return null;
  const boxes = teamsGrid(count);
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of boxes) {
    minX = Math.min(minX, b.x); minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.w); maxY = Math.max(maxY, b.y + b.h);
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

export interface TeamStats {
  positions: number;
  agents: number;
  resources: number;
  externals: number;
  /** Distinct departments present (from each position's `positionDisplay(...).dept`). */
  depts: string[];
}

/** Headline counts for a team card (positions by kind + the department spread). Pure. */
export function teamStats(team: Team, personas: Persona[]): TeamStats {
  const positions = team.positions.length;
  const agents = team.positions.filter((p) => p.kind === "agent").length;
  const resources = team.positions.filter((p) => p.kind === "resource").length;
  const externals = team.positions.filter((p) => p.kind === "external").length;
  const depts = [...new Set(team.positions.map((p) => positionDisplay(p, personas).dept))];
  return { positions, agents, resources, externals, depts };
}

