import { describe, it, expect } from "vitest";
import {
  transformationsConfirmed, tierGroups, nextPendingTier, tierLabel,
  coerceTransformationRows, specNodeCount, TRANSFORMATION_TAXONOMY, verbMeta,
  type TransformationRow,
} from "@/features/planner/lib/transformations";
import { validateGeneralNode, demoSpec } from "@/shared/ui/spec";
import TRANSFORMATIONS_STAGE from "@data/stages/transformations.json";

/** A minimal valid row; override per test. */
const row = (over: Partial<TransformationRow> = {}): TransformationRow => ({
  id: over.id ?? `t-${Math.random().toString(36).slice(2, 8)}`,
  verb: "extract",
  title: "Extract the shared button",
  target: { description: "4 bespoke buttons across the app" },
  delta: "bespoke buttons → one shared <Button>",
  invariants: ["existing tests pass"],
  owns: ["src/shared/ui/**"],
  tier: 0,
  ...over,
});

describe("transformationsConfirmed — the gate signal (#2509)", () => {
  it("is false for empty/null/undefined (an empty queue never clears the gate)", () => {
    expect(transformationsConfirmed([])).toBe(false);
    expect(transformationsConfirmed(null)).toBe(false);
    expect(transformationsConfirmed(undefined)).toBe(false);
  });

  it("is false while ANY row is pending, true only when every row is confirmed", () => {
    const rows = [row({ id: "a", confirmed: true }), row({ id: "b" })];
    expect(transformationsConfirmed(rows)).toBe(false);
    expect(transformationsConfirmed(rows.map((r) => ({ ...r, confirmed: true })))).toBe(true);
  });

  it("treats a missing/false confirmed as pending (never truthy-coerced)", () => {
    expect(transformationsConfirmed([row({ confirmed: false })])).toBe(false);
    expect(transformationsConfirmed([row({})])).toBe(false);
  });
});

describe("tierGroups", () => {
  it("groups by tier ascending, position-stable within a tier", () => {
    const rows = [
      row({ id: "p2", tier: 2 }),
      row({ id: "a0", tier: 0 }),
      row({ id: "b1", tier: 1 }),
      row({ id: "b0", tier: 0 }),
      row({ id: "a1", tier: 1 }),
    ];
    const groups = tierGroups(rows);
    expect(groups.map((g) => g.tier)).toEqual([0, 1, 2]);
    // Within a tier, original list order is preserved (the planner's order, never re-sorted).
    expect(groups[0].rows.map((r) => r.id)).toEqual(["a0", "b0"]);
    expect(groups[1].rows.map((r) => r.id)).toEqual(["b1", "a1"]);
    expect(groups[2].rows.map((r) => r.id)).toEqual(["p2"]);
  });

  it("handles sparse tiers (no empty groups synthesized) and an empty list", () => {
    expect(tierGroups([]).length).toBe(0);
    const groups = tierGroups([row({ tier: 0 }), row({ tier: 3 })]);
    expect(groups.map((g) => g.tier)).toEqual([0, 3]);
  });
});

describe("nextPendingTier", () => {
  it("is the LOWEST tier containing an unconfirmed row", () => {
    const rows = [
      row({ tier: 0, confirmed: true }),
      row({ tier: 1 }),
      row({ tier: 2 }),
    ];
    expect(nextPendingTier(rows)).toBe(1);
  });

  it("stays on a tier until EVERY row in it is confirmed", () => {
    const rows = [row({ tier: 0, confirmed: true }), row({ tier: 0 }), row({ tier: 1 })];
    expect(nextPendingTier(rows)).toBe(0);
  });

  it("is null when empty or fully confirmed (the completion card shows)", () => {
    expect(nextPendingTier([])).toBe(null);
    expect(nextPendingTier([row({ tier: 0, confirmed: true }), row({ tier: 2, confirmed: true })])).toBe(null);
  });
});

describe("tierLabel — driven by the @data taxonomy tiers (#2509 slice b)", () => {
  it("names the floor primitives, the top pages, and the middle composites", () => {
    expect(tierLabel(0, 2)).toBe("Tier 0 · primitives");
    expect(tierLabel(1, 2)).toBe("Tier 1 · composites");
    expect(tierLabel(2, 2)).toBe("Tier 2 · pages");
  });

  it("a single-tier queue reads as primitives (tier 0 always wins the floor name)", () => {
    expect(tierLabel(0, 0)).toBe("Tier 0 · primitives");
  });

  it("a four-tier queue surfaces the taxonomy's full ladder (layouts between composites and pages)", () => {
    expect(tierLabel(1, 3)).toBe("Tier 1 · composites");
    expect(tierLabel(2, 3)).toBe("Tier 2 · layouts");
    expect(tierLabel(3, 3)).toBe("Tier 3 · pages");
  });

  it("clamps a deep middle tier to the last middle label (never pages before the top)", () => {
    expect(tierLabel(3, 5)).toBe("Tier 3 · layouts");
    expect(tierLabel(5, 5)).toBe("Tier 5 · pages");
  });
});

describe("TRANSFORMATION_TAXONOMY — the @data drift guard (#2509 slice b)", () => {
  it("carries exactly the 11 verbs of the plandb enum, in enum order", () => {
    // MUST match crates/plandb/src/validate.rs's embedded vocabulary (the same file) — the CLI
    // rejects any verb outside this set at set-time.
    expect(TRANSFORMATION_TAXONOMY.verbs.map((v) => v.id)).toEqual([
      "rename", "extract", "split", "merge", "move", "replace",
      "upgrade", "restyle", "remove", "optimize", "harden",
    ]);
  });

  it("every verb carries label + blurb (the chip tooltip) + verification hint", () => {
    for (const v of TRANSFORMATION_TAXONOMY.verbs) {
      expect(v.label.trim().length, `${v.id} label`).toBeGreaterThan(0);
      expect(v.blurb.trim().length, `${v.id} blurb`).toBeGreaterThan(0);
      expect(v.verification.trim().length, `${v.id} verification`).toBeGreaterThan(0);
    }
  });

  it("carries the two recipes, each with its canonical steps", () => {
    expect(TRANSFORMATION_TAXONOMY.recipes.map((r) => r.id)).toEqual([
      "migrate-to-kit", "extract-and-abstract",
    ]);
    for (const r of TRANSFORMATION_TAXONOMY.recipes) {
      expect(r.steps.length, `${r.id} steps`).toBeGreaterThan(0);
    }
  });

  it("carries the four composition tiers 0..3: primitives · composites · layouts · pages", () => {
    expect(TRANSFORMATION_TAXONOMY.tiers.map((t) => [t.tier, t.label])).toEqual([
      [0, "primitives"], [1, "composites"], [2, "layouts"], [3, "pages"],
    ]);
  });
});

describe("verbMeta", () => {
  it("resolves a taxonomy verb's display metadata from the data file", () => {
    const m = verbMeta("replace");
    expect(m.label).toBe("Replace");
    expect(m.blurb.length).toBeGreaterThan(0);
    expect(m.verification.length).toBeGreaterThan(0);
  });

  it("echoes an unknown id back bare (a stale taxonomy never crashes the pane)", () => {
    expect(verbMeta("polish")).toEqual({ id: "polish", label: "polish", blurb: "", verification: "" });
  });
});

describe("coerceTransformationRows", () => {
  it("rejects non-arrays and filters rows without a string id", () => {
    expect(coerceTransformationRows(null)).toEqual([]);
    expect(coerceTransformationRows({ id: "x" })).toEqual([]);
    expect(coerceTransformationRows([{ id: "ok", tier: 1 }, { tier: 0 }, "junk", 7]).map((r) => r.id)).toEqual(["ok"]);
  });

  it("defaults a missing/invalid tier to 0 so grouping never breaks", () => {
    const [a, b] = coerceTransformationRows([{ id: "a" }, { id: "b", tier: "high" }]);
    expect(a.tier).toBe(0);
    expect(b.tier).toBe(0);
  });
});

describe("specNodeCount", () => {
  it("counts nodes carrying a `type`, recursing children + nested prop nodes", () => {
    expect(specNodeCount(undefined)).toBe(0);
    expect(specNodeCount({ type: "Chip", children: "x" })).toBe(1);
    expect(specNodeCount({
      type: "Card",
      props: { header: { type: "Text", children: "h" } },
      children: [
        { type: "Text", children: "t" },
        { type: "Row", children: [{ type: "Chip", children: "y" }] },
      ],
    })).toBe(5);
  });

  it("ignores non-node objects (a target/provenance blob is not a node)", () => {
    expect(specNodeCount({ description: "not a node" })).toBe(0);
  });

  // #3500 retired the `kind` vocabulary. A stale spec counts 0, which is exactly the signal the
  // caller wants — 0 nodes and a failed validation both route to the same "spec present" fallback.
  it("counts a retired `kind` tree as 0 — it is no longer a spec", () => {
    expect(specNodeCount({ kind: "card", children: [{ kind: "text", text: "t" }] })).toBe(0);
  });
});

// The gap-fill preview contract (#2509 slice d): the Transformations stage prompt (Rust-owned,
// src-tauri/data/stages/transformations.json) teaches the planner to author a render `spec` on every
// gap-fill row so the pane can render a LIVE preview of the proposed component.
//
// #3500 — this used to hand-COPY the worked example and validate the copy, which is precisely the
// drift it claimed to prevent: the prompt could change and this would keep passing against a stale
// duplicate. It now extracts the spec from the REAL prompt text the planner reads. (The Rust side runs
// the same assertion against its own validator, so the taught example is checked in both languages.)
describe("gap-fill preview spec — the contract the planner authors to (#2509 slice d)", () => {
  it("the canonical demoSpec (the reference an agent copies) validates", () => {
    expect(validateGeneralNode(demoSpec)).toEqual([]);
  });

  it("the spec taught by the REAL stage prompt validates", () => {
    const prompt = (TRANSFORMATIONS_STAGE as { prompt: string }).prompt;
    const start = prompt.indexOf('"spec": {');
    expect(start).toBeGreaterThan(-1); // the prompt still teaches a preview spec

    // Delimit the JSON object by brace balance — the example is embedded in prose.
    const open = start + '"spec": '.length;
    let depth = 0;
    let end = open;
    for (let i = open; i < prompt.length; i++) {
      if (prompt[i] === "{") depth++;
      else if (prompt[i] === "}") {
        depth--;
        if (depth === 0) { end = i + 1; break; }
      }
    }
    expect(end).toBeGreaterThan(open);

    const spec = JSON.parse(prompt.slice(open, end));
    expect(validateGeneralNode(spec)).toEqual([]);
    // It is a real tree the pane's "n nodes" fallback can also count.
    expect(specNodeCount(spec)).toBeGreaterThan(1);
  });
});

implementations.code:
export function transpose(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) [a[i][j], a[j][i]] = [a[j][i], a[i][j]];
  return a;
}

// TREE trace-programs (#3220, epic #3215) — the binary-search-tree pair, written over a TracedTree so the
// animation is DERIVED from the real walk: every `compare` frame IS the comparison that chose a branch.
//
// WHY THESE EXIST: same story as the stack programs. `TracedTree`, `<TreeView>`, `treeLayout.ts` and their
// tests all shipped, but no program was ever registered for the `tree` structure — so a tree could only be
// met inside a scene, never selected. These two open it, and they are a matched pair on purpose: BUILD the
// structure (insert, which is where the compares live) then READ it (in-order, which is what makes a BST
// worth building — the sorted walk).
import type { TracedTree, TreeNode } from "@/features/algorithms/lib/tracer";

/** A visualizable tree algorithm — its logic over a {@link TracedTree}, plus the nodes the tree STARTS with.
 *  `seed` is what separates the pair: insert starts from nothing and builds; in-order starts from a finished
 *  tree and walks it, so the build noise is not replayed as part of the traversal. */
export interface TreeProgram {
  run: (t: TracedTree, values: number[]) => void;
  /** The tree at rest before `run` — `[]` when the algorithm builds it itself. */
  seed: (values: number[]) => TreeNode[];
  defaultInput: number[];
}

/** A BST laid out as ids + child links. Ids are `n<i>` by INSERTION order, so a node's id is stable across
 *  both programs and the two animations are talking about the same tree. */
export interface BstShape {
  nodes: TreeNode[];
  left: Record<string, string | undefined>;
  right: Record<string, string | undefined>;
  rootId: string | undefined;
}

/**
 * Build the BST that `values` produces, as pure data — no tracer, no frames.
 *
 * Both programs need to know the tree's shape: insert walks it to find each landing spot, and in-order
 * needs the child links the tracer does not model (a {@link TreeNode} carries only a `parent`, which is
 * enough to LAY OUT a tree but not enough to walk one in order). Deriving the shape here once keeps the two
 * programs consistent by construction. Duplicates are dropped — a BST holds a set.
 */
export function bstShape(values: readonly number[]): BstShape {
  const nodes: TreeNode[] = [];
  const left: Record<string, string | undefined> = {};
  const right: Record<string, string | undefined> = {};
  const valueOf: Record<string, number> = {};
  let rootId: string | undefined;

  for (const v of values) {
    const id = `n${nodes.length}`;
    if (rootId === undefined) {
      rootId = id;
      nodes.push({ id, value: v });
      valueOf[id] = v;
      continue;
    }
    let cur = rootId;
    for (;;) {
      if (v === valueOf[cur]) break; // already present — a BST holds a set
      const goLeft = v < valueOf[cur];
      const next = goLeft ? left[cur] : right[cur];
      if (next === undefined) {
        if (goLeft) left[cur] = id;
        else right[cur] = id;
        nodes.push({ id, value: v, parent: cur });
        valueOf[id] = v;
        break;
      }
      cur = next;
    }
  }
  return { nodes, left, right, rootId };
}

/**
 * Insert each value into a BST, starting from an empty tree — the build half of the pair.
 *
 * The descent is the animation: each node the walk passes through takes a `path` mark, and the value lands
 * with an `insert` frame under the parent that trail chose.
 *
 * `compare` is deliberately NOT used. The tracer compares two EXISTING nodes by id, and the value being
 * placed has no node until it lands — so the only compare available during a descent is a node against
 * itself, which would render a decision frame that describes nothing. The path marks are the real trail;
 * an honest empty frame beats a decorative one.
 */
export function bstInsert(t: TracedTree, values: number[]): void {
  const shape = bstShape(values);
  const valueOf = new Map(shape.nodes.map((n) => [n.id, n.value as number]));
  for (const node of shape.nodes) {
    const v = node.value as number;
    if (node.parent === undefined) {
      t.insert(node.id, v); // the root names itself
      continue;
    }
    let cur = shape.rootId!;
    for (;;) {
      t.mark(cur, "path");
      if (cur === node.parent) break;
      const next = v < valueOf.get(cur)! ? shape.left[cur] : shape.right[cur];
      if (next === undefined) break;
      cur = next;
    }
    t.insert(node.id, v, node.parent);
    t.mark(node.id, "current");
  }
}

/**
 * Walk a finished BST in order (left · node · right) — the read half of the pair, and the reason a BST is
 * worth building: the visit sequence comes out SORTED.
 *
 * Iterative with an explicit stack rather than recursion, so the traversal's own pending set is a real data
 * structure the frames can reflect, and a deep tree cannot blow the JS stack.
 */
export function bstInorder(t: TracedTree, values: number[]): void {
  const shape = bstShape(values);
  const stack: string[] = [];
  let cur = shape.rootId;
  while (cur !== undefined || stack.length > 0) {
    while (cur !== undefined) {
      t.mark(cur, "path"); // descending the left spine
      stack.push(cur);
      cur = shape.left[cur];
    }
    const id = stack.pop()!;
    t.visit(id); // the in-order position — these fire in sorted order
    cur = shape.right[id];
  }
}

/** The default seed — an unbalanced-but-readable BST: root 50, both subtrees populated, 9 nodes. */
const TREE_MOCK = [50, 30, 70, 20, 40, 60, 80, 35, 65];

/** The visualizable tree algorithms, keyed by base name (#3220). */
export const TREE_PROGRAMS: Record<string, TreeProgram> = {
  "bst-insert": { run: bstInsert, seed: () => [], defaultInput: TREE_MOCK },
  "bst-inorder": { run: bstInorder, seed: (values) => bstShape(values).nodes, defaultInput: TREE_MOCK },
};

/** Serialize a tree seed to the "your input" text form — the insertion order, comma-separated. */
export function treeToText(input: readonly number[]): string {
  return input.join(", ");
}

/**
 * Parse the "your input" text into an insertion order — comma- or space-separated whole numbers. Throws a
 * helpful `Error` (shown under the field) on empty, non-numeric, or unwatchably-large input.
 */
export function parseTreeInput(text: string): number[] {
  const t = text.trim();
  if (t.length === 0) throw new Error("Enter numbers to insert, e.g. 50, 30, 70");
  const parts = t.split(/[\s,]+/).filter(Boolean);
  const out: number[] = [];
  for (const p of parts) {
    const n = Number(p);
    if (!Number.isFinite(n)) throw new Error(`"${p}" is not a number`);
    if (!Number.isInteger(n)) throw new Error("Use whole numbers so the nodes stay readable");
    out.push(n);
  }
  if (out.length > 15) throw new Error("Keep it to 15 values so the tree stays on screen");
  return out;
}

