// The app-wide store_state publisher (#2498) — the singleton the projector hook and the
// planner's plan-domain push share, bound to the real `tunnel_set_store_state` command.
// Kept apart from domainPublisher.ts so the engine stays Tauri-free and unit-testable.

import { createDomainPublisher } from "@/features/tunnel/lib/domainPublisher";
import { tunnelSetStoreState, type StoreDomain } from "@/features/tunnel/lib/tunnelClient";
import { log } from "@/shared/lib/core/log";

const publisher = createDomainPublisher({
  send: tunnelSetStoreState,
  onError: (domain, e) => log.error(`tunnel: store_state[${domain}] push failed: ${e}`),
});

/** Publish one domain's projection over the tunnel — debounced, deduped, rev-stamped.
 *  Safe to call on every derivation: an unchanged payload never reaches the wire. */
export function publishTunnelDomain(domain: StoreDomain, payload: unknown): void {
  publisher.publish(domain, payload);
}

/** Forget the last-sent cache (the next publish per domain re-sends). Called when the relay
 *  (re)starts so a fresh Rust-side store is repopulated even if the store didn't change. */
export function resetTunnelDomains(): void {
  publisher.reset();
}

// The tunnel feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/tunnel")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Tunnel from "@/features/tunnel/lib/tunnel";
import * as TunnelClient from "@/features/tunnel/lib/tunnelClient";
import * as RelayProbe from "@/features/tunnel/lib/relayProbe";
// `qrcode.react`, registered HERE and not in `appModules`: the pairing QR is the tunnel's own
// dependency and registration is EAGER, so putting it in the shell's set would pull the QR
// renderer into the boot bundle for every user who never pairs a phone.
import * as QrcodeReact from "qrcode.react";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerTunnelPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/tunnel/lib/tunnel", Tunnel);
  registerAppModule("@/features/tunnel/lib/tunnelClient", TunnelClient);
  registerAppModule("@/features/tunnel/lib/relayProbe", RelayProbe);
  registerAppModule("qrcode.react", QrcodeReact);
}

// The shadow catalogue registers this feature's graph-platform modules by importing
// `./graphPlatform` DIRECTLY and calling its register function (see `shadowPages.ts`). This barrel
// therefore has NO import-time side effect — it is re-exports only, which is what lets it be a
// record rather than a file that must run to be correct.

// Tunnel feature — public API (#1309): the optional mobile relay bridge (Noise-IK E2E over a
// zero-knowledge Cloudflare relay). The Tunnel settings page, the always-on sync/automation/coord
// hooks the app mounts, and the protocol/client live here.
export { TunnelSettings } from "@/features/tunnel/Tunnel";
export { useTunnelSync } from "@/features/tunnel/useTunnelSync";
export { useStoreProjector } from "@/features/tunnel/useStoreProjector";
export { useTunnelAutomations } from "@/features/tunnel/lib/useTunnelAutomations";
export { useTunnelHookTelemetry } from "@/features/tunnel/lib/useTunnelHookTelemetry";
export { useTunnelCoordControl } from "@/features/tunnel/lib/useTunnelCoordControl";

// #1545: public API for cross-feature consumers (app/console, planner, components).
export type { PlanMessage, SessionMeta, PaneDescriptor, PaneKind } from "@/features/tunnel/lib/tunnel";
export { TUNNEL_PROTOCOL_VERSION } from "@/features/tunnel/lib/tunnel";
export {
  tunnelStatus, tunnelSetSessions, tunnelSetPlanState,
  tunnelEmitPlanState, tunnelEmitPlanStatus, tunnelEmitPlanEvent,
  tunnelSetStoreState, STORE_DOMAINS,
} from "@/features/tunnel/lib/tunnelClient";
export type { StoreDomain } from "@/features/tunnel/lib/tunnelClient";

// #2498: the store projector + alert pipeline. The planner publishes its stage/gate board as
// the `plan` domain and contributes gate-ready / planner-waiting alerts through these.
export { publishTunnelDomain } from "@/features/tunnel/lib/tunnelDomains";
export { recordTunnelAlerts } from "@/features/tunnel/lib/alertHub";
export { gateReadyAlert, plannerWaitingAlert, coordAlerts } from "@/features/tunnel/lib/alerts";
export type { AlertEvent, AlertKind } from "@/features/tunnel/lib/alerts";

// Tunnel feature store slice (#1309) — the mobile-relay connection state. Extracted from the
// residual `shell` slice (formerly the `github` grab-bag). Composed by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { PaneDescriptor } from "@/features/tunnel/lib/tunnel";

export interface TunnelSlice {
  // The relay Worker URL is persisted (the user's BYO relay); `tunnelRunning` mirrors the Rust
  // client's connected state (transient) so ConsoleWorkspace knows whether to push live pane metadata.
  tunnelRelayUrl: string;
  setTunnelRelayUrl: (url: string) => void;
  tunnelRunning: boolean;
  setTunnelRunning: (v: boolean) => void;
  /** Ad-hoc session panes outside the Console tab grid, mirrored over the relay alongside the
   *  Console panes (#801/#2497), keyed by the REGISTERING SOURCE (`"planner"`, `"designer"`, …)
   *  so independent owners never clobber each other. Transient — not persisted. */
  tunnelExtraPanes: Record<string, PaneDescriptor[]>;
  /** Register (or replace) one source's mirrored panes; pass `[]` to unregister the source. */
  registerTunnelPanes: (source: string, panes: PaneDescriptor[]) => void;
}

export const createTunnelSlice: StateCreator<AppStore, [], [], TunnelSlice> = (set) => ({
  tunnelRelayUrl: "",
  setTunnelRelayUrl: (url) => set({ tunnelRelayUrl: url }),
  tunnelRunning: false,
  setTunnelRunning: (v) => set({ tunnelRunning: v }),
  tunnelExtraPanes: {},
  registerTunnelPanes: (source, panes) =>
    set((s) => {
      const next = { ...s.tunnelExtraPanes };
      if (panes.length === 0) delete next[source];
      else next[source] = panes;
      return { tunnelExtraPanes: next };
    }),
});

