describe("mergeDbIntoDrafts — the durable projects DB is a source, the store map is a cache (#3966)", () => {
  const db = (key: string, state: string, over: Partial<DbProject> = {}): DbProject => ({
    key, title: key, pitch: "", blueprint: null, category: null, state,
    createdAt: 10, updatedAt: 20, ...over,
  });

  // THE regression. `studio-code` was in projects.db, open in the planner and triaged, yet had no
  // Glance node — because `localDraftProjects` (a persisted cache written only by `addDraftProject`,
  // and reset wholesale by `resetProjectData`) never got the entry, and Glance read only that map.
  it("adds a project the store cache never got", () => {
    const out = mergeDbIntoDrafts({}, [db("studio-code", "drafted", { title: "studio code" })]);
    expect(Object.keys(out)).toEqual(["studio-code"]);
    expect(out["studio-code"].title).toBe("studio code");
  });

  // The FOLLOW-UP defect. The first cut admitted only drafted/planning — copied from `mergeDbDrafts`,
  // which feeds a DRAFTS-ONLY list where created/published render in other sections. Glance has no
  // other section, so a `created` project belonged to no source at all and vanished from the graph.
  // A triaged project whose state had advanced drafted → created hit exactly this.
  it("admits a `created` project — it belongs to no other Glance source", () => {
    const out = mergeDbIntoDrafts({}, [db("studio-code", "created", { title: "studio code" })]);
    expect(out["studio-code"]).toMatchObject({ title: "studio code" });
  });

  // `published` stays out: mergeGlanceProjects already overrides a draft with the published entry on a
  // key collision, and the drafts map doubles as the `isDraft` signal for resolveProjectCategory — a
  // published project in here would default to `greenfield` rather than `maintain`.
  it("admits every non-published state and excludes published", () => {
    const out = mergeDbIntoDrafts({}, [
      db("a", "drafted"), db("b", "planning"), db("c", "created"), db("d", "published"),
    ]);
    expect(Object.keys(out).sort()).toEqual(["a", "b", "c"]);
  });

  it("keeps a published project OUT of the drafts map — the merge already covers it", () => {
    // `mergeGlanceProjects` overrides a draft with the published entry on a key collision, so admitting
    // it here would buy nothing. (It also used to feed the `isDraft` signal for the lifecycle category,
    // which #4052 removed.)
    const out = mergeDbIntoDrafts({}, [db("shipped", "published")]);
    expect(out.shipped).toBeUndefined();
  });

  // A DB row has no column for the curated axes, so merging it must not flatten a demo project's
  // authored colouring — a naive `{...cached, ...dbRow}` would strip role/health/activity.
  it("keeps the cache's curated axes and preferred fields when both sides have the key", () => {
    const cached = {
      demo: { title: "Demo", pitch: "cached pitch", createdAt: 5, role: "service" as const, health: "warning" as const, activity: "review" as const },
    };
    const out = mergeDbIntoDrafts(cached, [db("demo", "drafted", { title: "DB Title", pitch: "db pitch" })]);
    expect(out.demo).toMatchObject({
      title: "Demo", pitch: "cached pitch", createdAt: 5,
      role: "service", health: "warning", activity: "review",
    });
  });

  // The DB fills only what the cache is actually missing.
  it("fills blank cache fields from the DB row", () => {
    const out = mergeDbIntoDrafts({ demo: { title: "", pitch: "", createdAt: 0 } }, [
      db("demo", "drafted", { title: "From DB", pitch: "db pitch", createdAt: 77 }),
    ]);
    expect(out.demo).toMatchObject({ title: "From DB", pitch: "db pitch", createdAt: 77 });
  });

  // The bridge returns null when it's unreachable (web shell, tests, an old bundled `bsc` with no
  // `project db` verb). The hook keeps its previous rows; the pure fn must not choke on an empty set.
  it("is a no-op on an empty or non-array db set, preserving the cache", () => {
    const cached = { demo: { title: "Demo", pitch: "p", createdAt: 1 } };
    expect(mergeDbIntoDrafts(cached, [])).toEqual(cached);
    expect(mergeDbIntoDrafts(cached, null as unknown as DbProject[])).toEqual(cached);
  });

  it("does not mutate the store map it was handed", () => {
    const cached = { demo: { title: "Demo", pitch: "p", createdAt: 1 } };
    mergeDbIntoDrafts(cached, [db("other", "drafted")]);
    expect(Object.keys(cached)).toEqual(["demo"]);
  });

  // The pure-fn tests above CANNOT see whether the hook actually calls the merge — bypassing the
  // `effectiveDrafts` memo leaves all of them green. (That is precisely how the #1102 regression test
  // stayed green while its bug shipped: it asserted its own helper call, not the production path.)
  // These drive the real hook through the real `bsc project db list` bridge.
  describe("hook wiring — the graph itself, not just the helper", () => {
    /** Answer the two invokes the hook makes: the local hub inventory and the `bsc` bridge. */
    const mockBridge = (rows: unknown) =>
      vi.mocked(invoke).mockImplementation(async (cmd: string, args?: unknown) => {
        if (cmd === "list_local_projects") return [];
        const argv = (args as { args?: string[] } | undefined)?.args;
        if (cmd === "bsc" && argv?.join(" ") === "project db list --json") {
          return JSON.stringify(rows);
        }
        return null;
      });

    it("renders a node for a triaged project that exists ONLY in projects.db (#3966)", async () => {
      useAppStore.setState({
        localDraftProjects: {}, planFleet: {}, githubToken: "", githubState: null,
        triagedProjects: { "studio-code": 1 },
      });
      mockBridge([{ key: "studio-code", title: "studio code", pitch: "", state: "drafted", createdAt: 1, updatedAt: 2 }]);
      const { result } = renderHook(() => useGlanceProjects());
      await waitFor(() => expect(result.current.some((p) => p.id === "studio-code")).toBe(true));
    });

    // The end-to-end shape of the follow-up defect, at the level the user actually sees: triaging
    // advances the row to `created`, and the graph must still show it. The pure-fn test above covers
    // the filter; this covers the filter AS WIRED, which is where the first fix looked fine and wasn't.
    //
    // NOTE the distinct key. `dbProjectsCache` is module-level (deliberately — it survives the Rail's
    // unmount/remount), so it also survives BETWEEN TESTS: reusing `studio-code` here let the previous
    // test's cached `drafted` row satisfy this one, and the assertion passed even with the narrow
    // filter restored. A unique key per hook test is what makes the assertion mean anything.
    it("renders a node once triage has advanced the row to `created` (#3966)", async () => {
      useAppStore.setState({
        localDraftProjects: {}, planFleet: {}, githubToken: "", githubState: null,
        triagedProjects: { "triaged-created": 1785349752066 },
      });
      mockBridge([{ key: "triaged-created", title: "Triaged Created", pitch: "", state: "created", createdAt: 1784918799301, updatedAt: 1785349712038 }]);
      const { result } = renderHook(() => useGlanceProjects());
      await waitFor(() => expect(result.current.some((p) => p.id === "triaged-created")).toBe(true));
    });

    it("keeps rendering the store cache when the bridge is unreachable", async () => {
      useAppStore.setState({
        localDraftProjects: { cached: { title: "Cached", pitch: "", createdAt: 1 } },
        planFleet: {}, githubToken: "", githubState: null, triagedProjects: { cached: 1 },
      });
      // `bsc` throwing is the old-binary / web-shell case — listDbProjects returns null.
      vi.mocked(invoke).mockImplementation(async (cmd: string) => {
        if (cmd === "list_local_projects") return [];
        if (cmd === "bsc") throw new Error("no bsc bridge");
        return null;
      });
      const { result } = renderHook(() => useGlanceProjects());
      await waitFor(() => expect(result.current.some((p) => p.id === "cached")).toBe(true));
    });

    // #163 — a durable row changed by a DIFFERENT surface (a live session running `bsc project
    // network set`, or any other `bsc project db` write) must surface on Glance while the user is
    // just sitting on the page, not only on the next unmount/remount. The old code fetched
    // `listDbProjects()` exactly once per mount (`useEffect` with deps `[enabled]`); this asserts the
    // hook actually re-reads the bridge on a later tick with NO remount in between.
    it("re-reads the durable projects DB on the next poll tick, with no unmount/remount (#163)", async () => {
      useAppStore.setState({
        localDraftProjects: {}, planFleet: {}, githubToken: "", githubState: null,
        triagedProjects: { "poll-project": 1 },
      });
      let network: string | null = null;
      vi.mocked(invoke).mockImplementation(async (cmd: string, args?: unknown) => {
        if (cmd === "list_local_projects") return [];
        const argv = (args as { args?: string[] } | undefined)?.args;
        if (cmd === "bsc" && argv?.join(" ") === "project db list --json") {
          return JSON.stringify([
            { key: "poll-project", title: "Poll Project", pitch: "", state: "drafted", createdAt: 1, updatedAt: 2, network },
          ]);
        }
        return null;
      });

      vi.useFakeTimers();
      try {
        const { result } = renderHook(() => useGlanceProjects());
        await act(() => vi.advanceTimersByTimeAsync(0)); // flush the immediate poll tick's microtasks
        expect(result.current.find((p) => p.id === "poll-project")?.network).toBeUndefined();

        // The row changes OUT FROM UNDER the already-mounted hook — exactly the failing repro on
        // request #163 (`bsc project network set wan-relay network-finance`, then look at Glance).
        network = "network-finance";
        await act(() => vi.advanceTimersByTimeAsync(10_000)); // the poll cadence — no unmount/remount here
        expect(result.current.find((p) => p.id === "poll-project")?.network).toBe("network-finance");
      } finally {
        vi.useRealTimers();
      }
    });
  });
});

implementations.code:
// useGlanceProjects (#2206) — the REAL project set for the Glance network: the user's PUBLISHED GitHub
// projects (projectsV2, the same query the Planner list runs) MERGED with local DRAFTS. Everything is
// keyed by the PLAN key (the name-derived slug, #2409 — NOT the GitHub node id) so each project appears
// once and drilling into it resolves its fleet from `planFleet` (which is plan-key-keyed). Published
// projects win on a key collision (they carry the real open/shipped status). Falls back to just drafts
// when there's no token / before the fetch lands, so the page is never blocked on the network.
//
// #2339 — the network showed a DIFFERENT set on every visit. Two causes, both fixed here:
//   1. RACE. `useGithubQuery` re-inits to `{ data: null }` on every mount and the Rail unmounts/remounts
//      Glance on leave/return, so each visit rendered drafts-only → then flipped to drafts+published once
//      the async fetch (variable latency) landed. The PERSISTED last-known board state (#2446 — the
//      `githubState` store field, which also survives an app restart) seeds the merge on a revisit, so
//      it renders the last-known network immediately, then refreshes.
//   2. DEDUP GAP. Drafts were keyed by their stable id but published by a different derivation; when
//      the two keys differed the SAME project became TWO nodes. The merge resolves a published project
//      onto its matching draft via a slug(title)→draftKey map, so legacy-keyed drafts collapse too.
// #2409: the plan key IS the name-derived slug (`projectSlug(title)`) — the node-id alias is retired.
import { useEffect, useMemo, useState } from "react";
import { useAppStore } from "@/store";
import { githubGraphql } from "@/shared/lib/github/github";
import { useGithubQuery } from "@/shared/lib/github/useGithubQuery";
import { toMinimalGhProjects, minimalToGhProject, filterRecordsToLocal } from "@/shared/lib/github/githubState";
import { useProjectProgressRows } from "@/features/glance/lib/useProjectProgress";
import { fetchProjectsWithProbe } from "@/shared/lib/github/githubProbe";
import { PROJECTS_QUERY, type GhProject } from "@/features/planner/list/published/publishedModel";
import { projectSlug } from "@/shared/lib/core/projectPaths";
import { usePoll } from "@/shared/hooks/usePoll";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import type { GRole, GHealth, GActivity } from "@/features/glance/lib/glanceGraph";
import type { ProjectLite } from "@/features/glance/lib/glanceData";
import type { GlanceFault } from "@/features/glance/lib/useGlanceFaults";
import { projectKeyOfSession } from "@/features/glance/lib/agentStall";
// #3966: the SAME durable-projects bridge the Projects page reads, so the two surfaces cannot
// disagree about which local projects exist. Type-only + the reader; the bridge already degrades to
// `null` when it is unreachable, which we treat as "keep the cache".
import { listDbProjects, type DbProject } from "@/features/planner";

// #2541 — GitHub board status NO LONGER drives a Glance node's status. The old `ghStatus` (open ⇒
// planning, shipped ⇒ done) is gone; health + activity are derived from runtime signals only.

/** Store shapes the merge reads — mirrored structurally so the pure fn stays decoupled from the slices.
 *  A draft MAY declare curated axes (#2284/#2541) — a demo/tagged project keeps its authored colouring. */
type DraftMap = Record<string, { title: string; pitch: string; createdAt: number; role?: GRole; health?: GHealth; activity?: GActivity; reason?: string }>;

/** Stable empty published set — a fresh `[]` each render would needlessly re-run the merge memo. */
const NO_PUBLISHED: GhProject[] = [];

/** Stable empty DB set — same memo-stability reason as {@link NO_PUBLISHED}. */
const NO_DB_PROJECTS: DbProject[] = [];

/**
 * Union the durable projects DB into the store's draft map (#3966).
 *
 * `localDraftProjects` is a persisted CACHE, written by `addDraftProject` at creation time — and it is
 * reset wholesale by `resetProjectData` and delete/rekey-scoped by `projectScopedMaps`. So a project
 * that predates the map, survives a reset, or is created by a path that never calls `addDraftProject`
 * is absent from it FOREVER, while `projects.db` still has the row and every other surface still shows
 * it. That is how a triaged, openable project had no Glance node at all.
 *
 * The CACHE wins on fields it has — it carries the curated axes the DB row has no column for — and the
 * DB fills what the cache is missing, including whole rows.
 *
 * STATE FILTER — deliberately WIDER than `mergeDbDrafts` (the Projects page's equivalent), and the
 * first cut of this function got that wrong. That helper feeds a DRAFTS-ONLY list, where `created` and
 * `published` projects are excluded because they render in other sections of the same page. Glance has
 * no other section: its node set is drafts ∪ local-published ∪ GitHub-published, so a `created` project
 * — one that has been scaffolded but never published — belongs to NO source and silently vanishes from
 * the graph. That is what happened to a triaged project whose state had advanced `drafted` → `created`.
 *
 * `published` stays out on purpose: `mergeGlanceProjects` already overrides a draft with the published
 * entry on a key collision, so admitting it buys nothing.
 *
 * Pure + exported for direct unit testing, like {@link mergeGlanceProjects}.
 */
export function mergeDbIntoDrafts(drafts: DraftMap, dbRows: DbProject[]): DraftMap {
  const out: DraftMap = { ...drafts };
  for (const r of Array.isArray(dbRows) ? dbRows : []) {
    if (r.state === "published") continue;
    const ex = out[r.key];
    out[r.key] = ex
      // Keep every curated axis (role/health/activity/reason) — the DB row has none of them,
      // so a spread-with-DB-second would silently strip a demo project's authored colouring.
      ? { ...ex, title: ex.title || r.title, pitch: ex.pitch || r.pitch, createdAt: ex.createdAt || r.createdAt }
      : { title: r.title, pitch: r.pitch, createdAt: r.createdAt || r.updatedAt || 0 };
  }
  return out;
}

/** A published hub from the LOCAL inventory (#2445): `key` is the hub FOLDER key — the same key the
 *  drill / `planFleet` / `fleetPaneStreams` resolve against — with the `.title` display name. */
export interface LocalPublishedLite { key: string; title: string }

/** The `list_local_projects` fields the seed reads (camelCase wire format, #789). */
interface LocalProjectWire { key: string; title: string; published: boolean }

// The last-fetched local published inventory (#2445) — module-level so it survives the Glance
// workspace unmount/remount the Rail does on every leave/return: a revisit renders the published
// nodes immediately, then refreshes. (The GitHub-side equivalent is the PERSISTED `githubState`
// store field, #2446.)
let localPublishedCache: LocalPublishedLite[] | null = null;

// The last-fetched durable projects DB rows (#3966) — module-level for the same reason as
// `localPublishedCache`: the Rail unmounts/remounts the Glance workspace on every leave/return, and a
// revisit should render the full node set immediately rather than flashing a cache-only graph first.
let dbProjectsCache: DbProject[] | null = null;

/**
 * Merge local drafts with published GitHub projects into the Glance node set, keyed by the PLAN key so each
 * project is exactly ONE node. Pure + exported for direct unit testing (#2339).
 *
 * Dedup (#2409): a published project's plan key IS `projectSlug(title)` — with one bridge for
 * grandfathered drafts: a draft whose legacy key differs from its title-slug is found via a
 * slug(title)→draftKey map, so the published board collapses onto it rather than spawning a second node.
 */
export function mergeGlanceProjects(
  drafts: DraftMap,
  published: GhProject[],
  localPublished: LocalPublishedLite[] = [],
): ProjectLite[] {
  const byKey = new Map<string, ProjectLite>();
  // slug(title) → draft key, so a published project collapses onto a legacy-keyed draft.
  const draftKeyByTitle = new Map<string, string>();
  // Drafts first; a published project on the same plan key overrides it below.
  for (const [id, d] of Object.entries(drafts)) {
    // A draft may DECLARE its Glance axes (#2284/#2541 — health + activity + reason); else both axes
    // REST at idle (#2551) and the runtime overlays light them up: liveness → live (#2263), running
    // agents → building (#2551), bsc-wait → waiting, faults → warning/error (#2541). A declared value
    // wins so a demo/tagged project keeps its curated colouring.
    byKey.set(id, {
      id, name: d.title, role: d.role,
      health: d.health ?? "off",
      activity: d.activity ?? "idle",
      reason: d.reason,
    });
    draftKeyByTitle.set(projectSlug(d.title), id);
  }
  // Local published hubs (#2445) — the OFFLINE seed: a published project always has a node, keyed by
  // its hub folder key (what the drill resolves), even when the GitHub set is absent (logged out /
  // fetch not landed). A GitHub record below OVERLAYS it. GitHub board status NO LONGER sets the node
  // status (#2541) and a published hub RESTS at idle (#2551) until a runtime overlay lights it up; a
  // draft-declared axis still wins for curated colouring.
  // Collapse the LEGACY + name-slug hub FOLDERS of the SAME project into ONE node (#2409 grandfathering
  // leaves both on disk with the same title — e.g. `Beautiful_Emails` + `beautiful-emails`): group by the
  // canonical `projectSlug(title)`, preferring the folder whose key already IS that slug (what planFleet +
  // the drill resolve against), so a project isn't DUPLICATED on the network.
  const localByTitleKey = new Map<string, LocalPublishedLite>();
  for (const lp of localPublished) {
    const tk = projectSlug(lp.title);
    const cur = localByTitleKey.get(tk);
    if (!cur || (lp.key === tk && cur.key !== tk)) localByTitleKey.set(tk, lp);
  }
  for (const [tk, lp] of localByTitleKey) {
    // Collapse onto a matching draft (a legacy-keyed draft) if one exists; else key by the chosen folder.
    const key = draftKeyByTitle.get(tk) ?? lp.key;
    const prior = byKey.get(key);
    const d = drafts[key];
    byKey.set(key, { id: key, name: lp.title, role: prior?.role, health: d?.health ?? "off", activity: d?.activity ?? "idle", reason: d?.reason });
    draftKeyByTitle.set(tk, key);
  }
  for (const p of published) {
    // The plan key derives from the name (#2409): a matching draft's key (covers grandfathered
    // legacy-keyed drafts) else `projectSlug(title)` — the key `planFleet` + the drill resolve
    // against (NEVER the node id). Preserve any axis already set by a collapsed draft/local hub; the
    // GitHub record contributes only name (+ dedup), never status (#2541).
    const titleKey = projectSlug(p.title);
    const key = draftKeyByTitle.get(titleKey) ?? titleKey;
    const prior = byKey.get(key);
    byKey.set(key, { id: key, name: p.title, role: prior?.role, health: prior?.health ?? "off", activity: prior?.activity ?? "idle", reason: prior?.reason });
  }
  return [...byKey.values()];
}

/** One project's liveness as the `project_liveness` Tauri command reports it (#2263, camelCase). */
interface ProjectLiveness { projectKey: string; live: boolean }

/** How often to poll backend liveness (ms). Comfortably below the backend's 45s window so a project
 *  going silent surfaces (and its "app down" alert records) within ~one interval. */
const LIVENESS_POLL_MS = 10_000;

/** How often to re-read the durable projects DB (ms, #163). A row written from outside the app —
 *  `bsc project network set`, `bsc project architect set`, any `bsc project db` write from a live
 *  session or another surface — must surface on Glance without an app restart. Same cadence as
 *  {@link LIVENESS_POLL_MS}: neither signal is more time-sensitive than the other. */
const DB_PROJECTS_POLL_MS = 10_000;

/**
 * Overlay backend liveness onto the merged node set (#2263/#2541): a project whose key is in `liveKeys`
 * is detected RUNNING → activity `"live"` and health `"healthy"` (a running app is active & fine — the
 * fault overlay below can still escalate it to warning/error). Every other project keeps its merged
 * axes, so liveness lapsing naturally RESETS on the next poll. Additive + pure.
 */
export function applyLiveness(projects: ProjectLite[], liveKeys: ReadonlySet<string>): ProjectLite[] {
  if (liveKeys.size === 0) return projects;
  return projects.map((p) => (liveKeys.has(p.id) ? { ...p, activity: "live", health: p.health === "off" ? "healthy" : p.health } : p));
}

/**
 * Overlay RUNNING-AGENT activity onto the node set (#2551) — the `building` state. A project with a live
 * agent PTY reads activity `building` + health `healthy` (active & fine). This is what makes `building`
 * mean agents are ACTUALLY running — NOT a resting default — so a triaged project with nothing running
 * stays `idle`. Applied after liveness so active agent work (the more current signal) wins over a bare
 * `live` app. The fault overlay still escalates health to warning/error on top. Pure.
 */
export function applyRunningActivity(projects: ProjectLite[], buildingKeys: ReadonlySet<string>): ProjectLite[] {
  if (buildingKeys.size === 0) return projects;
  return projects.map((p) => (buildingKeys.has(p.id) ? { ...p, activity: "building", health: p.health === "off" ? "healthy" : p.health } : p));
}

/**
 * Overlay the `modifying` HEALTH state (#4052) — the project has work IN FLIGHT.
 *
 * Two signals, either sufficient:
 *   · a LIVE FLEET — an agent session is running against the project right now (`activeKeys`);
 *   · OPEN ISSUES — its plan store has issues that are not yet done (`openIssueKeys`).
 *
 * Either alone is real. A fleet running on a fully-closed board is still modifying the project; a
 * project with eight open issues and nothing running is mid-build, just paused. Requiring both would
 * have made `modifying` mean "building", which the ACTIVITY axis already says — and says better,
 * because it clears the moment the panes close. `modifying` is the durable fact and survives a restart.
 *
 * DOES NOT outrank a problem. `warning`/`error` are left exactly as they are: a project can be busy and
 * broken at the same time, and the broken half is the one the user has to see. (Both are applied later
 * anyway — `applyStallHealth`/`applyFaultHealth` in the workspace — so they also win by ordering.)
 *
 * DOES lift the DERIVED `off`. Dormancy (`applyDormantHealth`) greys every project with no live session,
 * which would otherwise swallow the open-issues signal whole — a paused project with unfinished planned
 * work is not "nothing here". Only the derived resting state is lifted: the user's MANUAL off toggle
 * (#3239) is `applyOffHealth`, applied outermost in `GlanceWorkspace`, so a deactivated node still goes
 * grey no matter what this returns. That layering is what makes lifting `off` here safe.
 *
 * `complete` → `modifying` is deliberate: work having RESUMED on a finished project is precisely the
 * transition worth showing, and leaving it blue-and-still would say the opposite.
 *
 * Pure + exported for direct unit testing, like the other overlays here.
 */
/**
 * Attach each project's issue completion to its node (#4118).
 *
 * The counts were already read — `useProjectProgress` has fetched them since #4052 — but only their
 * BOOLEAN shadow was used (does this project have open issues, for the `modifying` colour) and the
 * numbers were discarded. So an L0 project node had no progress at all, which is why the bars looked
 * missing on the board even after the L1 drill worked: they had never existed at this level.
 *
 * A project absent from `byKey` is left untouched rather than given `0/0` — the node draws no bar for
 * either, but only one of them is a claim.
 */
export function withProjectProgress<T extends { id: string; progress?: { done: number; total: number } }>(
  projects: readonly T[],
  byKey: ReadonlyMap<string, { done: number; total: number }>,
): T[] {
  if (byKey.size === 0) return [...projects];
  return projects.map((p) => {
    const hit = byKey.get(p.id);
    return hit ? { ...p, progress: hit } : p;
  });
}

export function applyModifyingHealth(
  projects: ProjectLite[],
  activeKeys: ReadonlySet<string>,
  openIssueKeys: ReadonlySet<string>,
): ProjectLite[] {
  if (activeKeys.size === 0 && openIssueKeys.size === 0) return projects;
  return projects.map((p) => {
    if (p.health === "warning" || p.health === "error") return p;
    return activeKeys.has(p.id) || openIssueKeys.has(p.id) ? { ...p, health: "modifying" } : p;
  });
}

/** The set of project keys with a LIVE agent session (#2551): any launched pane that is still a live CELL
 *  of an open tab, or any pane with an authoritative `run`/`on` status (covers the director, a session not
 *  a stream). The project key is the pane id's prefix (before the first ':'). Pure.
 *
 *  `livePaneIds` — NOT `fleetPaneStreams` (#3429). The roster map is only cleared by `closeTab`; `killPane`
 *  leaves it populated, so a fleet ended via "End sessions" kept reading `building`/`healthy` here until the
 *  tab itself was closed. `livePaneIds` is the same pruned set the L1 overlay reads (tab membership minus
 *  `endedPanes`/`disabledPanes`), so both layers answer "does a session exist?" from one signal. */
export function deriveBuildingKeys(
  livePaneIds: ReadonlySet<string>,
  paneStatus: Record<string, string | undefined>,
): Set<string> {
  const keys = new Set<string>();
  for (const paneId of livePaneIds) keys.add(projectKeyOfSession(paneId));
  for (const [paneId, st] of Object.entries(paneStatus)) if (st === "run" || st === "on") keys.add(projectKeyOfSession(paneId));
  return keys;
}

/**
 * Overlay DORMANCY onto the node set (#3429) — the L0 half of the #3415 existence rule, and the first
 * question the stack asks rather than the last. A project with no live agent session AND no detected app
 * liveness has nothing running at all: it reads `off · idle`.
 *
 * Until this existed, L0 could only ESCALATE. Every overlay lifted a project off the merge default
 * (`health: "off"`, `idle` until #4042), and nothing ever established that there was nothing to lift — so "dormant" and
 * "has a session, currently quiet" both rendered `idle`, exactly the ambiguity #3415 removed at L1:
 *
 *   no session exists → `off` · a session exists but is quiet → `idle` · working → `healthy`
 *
 * (`off` at L0 previously meant ONLY the user's manual toggle, #3239. That still wins outright — it is
 * applied outermost — this just makes the derived resting state honest about the same word.)
 *
 * Applied BEFORE `applyFaultHealth`: a dormant project with an unresolved fault still reads warning/error,
 * because an unfixed error does not stop being real just because nobody is currently working on it.
 *
 * `curated` nodes survive dormancy for exactly the same reason (#2284/#2541 — "curated colouring wins";
 * fixed in #3513): a draft that DECLARES its own health/activity is making a statement, and greying it
 * out the moment nothing happens to be running discards that in favour of a resting state nobody asked
 * about. Curated-ness is passed IN rather than inferred from the value, because by this point in the
 * pipeline a non-default `health` is equally likely to be a declaration or something an earlier overlay
 * derived — the two are indistinguishable here, and only the merge knows which. Pure.
 */
export function applyDormantHealth(
  projects: ProjectLite[],
  activeKeys: ReadonlySet<string>,
  curatedKeys: ReadonlySet<string> = new Set(),
): ProjectLite[] {
  return projects.map((p) =>
    activeKeys.has(p.id) || curatedKeys.has(p.id) ? p : { ...p, health: "off", activity: "idle" },
  );
}

/**
 * Overlay the fault summary onto the node set (#2541) — the HEALTH axis. A project with an open fault
 * escalates to `warning` (warn) or `error` (error/fatal), carrying the worst fault's title as the
 * `reason` (shown bottom-right in place of the activity word) and its count. Applied LAST so a fault
 * beats a healthy/live resting state — a live app that's throwing errors still reads red. Pure.
 */
export function applyFaultHealth(projects: ProjectLite[], faults: Record<string, GlanceFault>): ProjectLite[] {
  return projects.map((p) => {
    const f = faults[p.id];
    if (!f) return p;
    const health: GHealth = f.level === "warn" ? "warning" : "error";
    return { ...p, health, reason: f.title, faults: f.count };
  });
}

/**
 * Overlay the user's manual OFF toggle onto the node set (#3239) — the one caller-driven HEALTH value.
 * A project the user has deactivated (its id is truthy in `off`) reads health `off` and drops its fault
 * `reason`, so the node greys and reads "off" regardless of what it was doing. Applied OUTERMOST (after
 * liveness/running/stall/fault) so the deliberate mute WINS over every derived status — "if it's not idle
 * then it should be off". Sparse map (absent ⇒ on); pure. Keyed by the project id (== the node id).
 */
export function applyOffHealth(projects: ProjectLite[], off: Record<string, boolean>): ProjectLite[] {
  return projects.map((p) => (off[p.id] ? { ...p, health: "off", reason: undefined } : p));
}

/** Poll the backend for the set of currently-live project keys (#2263). Polling also DRIVES backend
 *  down-detection: the sweep records an "app down" fault for any project that has just gone silent. */
export function useProjectLiveness(enabled = true): ReadonlySet<string> {
  const [liveKeys, setLiveKeys] = useState<ReadonlySet<string>>(() => new Set());
  usePoll(
    async (isCancelled) => {
      if (!enabled) return;
      const rows = await safeInvoke<ProjectLiveness[]>("project_liveness", undefined, []);
      if (isCancelled()) return;
      // Tolerate a null/non-array return (no collector, a stubbed invoke) — no live keys, no throw.
      const list = Array.isArray(rows) ? rows : [];
      const next = new Set(list.filter((r) => r.live).map((r) => r.projectKey));
      // Only replace the set when membership actually changed, so a steady state doesn't churn renders.
      setLiveKeys((prev) => (sameKeys(prev, next) ? prev : next));
    },
    LIVENESS_POLL_MS,
    [enabled],
  );
  return liveKeys;
}

/** Two key sets are equal iff same size and every member shared. */
function sameKeys(a: ReadonlySet<string>, b: ReadonlySet<string>): boolean {
  if (a.size !== b.size) return false;
  for (const k of a) if (!b.has(k)) return false;
  return true;
}

/**
 * THE TRIAGED GATE IS GONE (#2541 retired). It used to keep only projects whose triage or fleet had
 * been launched — "once the nodes are here, it's because they're working" — and the cost of that
 * sentence was that a project you had just created, filed into a network and wired up was invisible
 * in the one place you would look for it, with no error and nothing to read.
 *
 * It could not be repaired either, only worked around: the marker it read is not persisted, so it is
 * empty on every boot, and a grandfather backfill re-seeded it from whatever hubs happened to be
 * published. The comment on {@link filterArchived} records 13 `bsc project triaged clear` calls that
 * all "succeeded" and all came back with one identical timestamp.
 *
 * ARCHIVED is the hide now, and it is a better one because it is DURABLE and DELIBERATE: a project
 * leaves the network when somebody says it should, not when a marker nobody set happens to be absent.
 */

/** The durable lifecycle state that hides a project from the network — see {@link filterArchived}. */
export const ARCHIVED_STATE = "archived";

/**
 * Drop ARCHIVED projects — the durable "I am done looking at this" marker.
 *
 * WHY NOT `triaged`. Clearing the triaged marker is the obvious way to hide a project and it cannot
 * work: `triagedProjects` is deliberately not persisted (pinned by `store/triagedStore.test.ts`), so
 * it is empty on every boot, which trips the "REPAIR once" grandfather in `onRehydrateStorage` — it
 * re-seeds from every locally-PUBLISHED hub, and `useAppBoot` then writes those keys back into the DB.
 * Measured: 13 `bsc project triaged clear` calls all succeeded and every project returned with one
 * identical timestamp. A hide built on `triaged` fights that loop on every launch and loses.
 *
 * `state` has none of that machinery pointed at it — nothing grandfathers it, and it already ships
 * writable (`bsc project db state <key> archived`, the column, and the store's own tests). Only the
 * READ was missing, which is all this adds. `triaged` therefore keeps meaning "has been worked",
 * which is what it says.
 *
 * Archiving is orthogonal to every other state: a `published` project can be archived and a `drafted`
 * one can too, so this filters on the archived marker ALONE and never infers it from anything else.
 */
export function filterArchived(projects: ProjectLite[], archived: ReadonlySet<string>): ProjectLite[] {
  return archived.size === 0 ? projects : projects.filter((p) => !archived.has(p.id));
}

export function useGlanceProjects(enabled = true): ProjectLite[] {
  const drafts = useAppStore((s) => s.localDraftProjects);
  // Running-agent signals (#2551): the launched roster + authoritative pane statuses → the `building`
  // activity. A project with a live agent pane reads `building`; nothing running → it rests at `idle`.
  // Launched-tab membership (#3429) — the same pruned "this session exists" signal the L1 overlay reads
  // (`GlanceWorkspace.livePaneIds`): a pane is live only while it is a CELL of an open tab and has not
  // been ended or disabled. Replaces `fleetPaneStreams`, which `killPane` never clears.
  const consoleTabs = useAppStore((s) => s.tabs);
  const endedPanes = useAppStore((s) => s.endedPanes);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const livePaneIds = useMemo(() => {
    const live = new Set<string>();
    for (const t of consoleTabs) for (const pid of t.paneIds ?? []) {
      if (pid && !endedPanes[pid] && !disabledPanes[pid]) live.add(pid);
    }
    return live;
  }, [consoleTabs, endedPanes, disabledPanes]);
  const paneStatus = useAppStore((s) => s.paneStatus);
  const githubState = useAppStore((s) => s.githubState);
  const setGithubState = useAppStore((s) => s.setGithubState);
  // The per-project classification (#3786/#3802): the planner-set `appType` (application architecture) —
  // surfaced on each Glance project node as the contract endpoint-type discriminator. Absent for an
  // unclassified project ⇒ the node renders plain (no type badge).
  const planClassification = useAppStore((s) => s.planClassification);
  const liveKeys = useProjectLiveness(enabled);
  // #4052 — the OPEN-ISSUES half of `modifying`, in ONE spawn for every project (never one per node).
  const { openKeys: openIssueKeys, byKey: projectProgress } = useProjectProgressRows(enabled);

  // The local published inventory (#2445): the on-disk hubs carrying `.published`, so a published
  // project has a Glance node even with no GitHub connection. Seeded from the module cache on a
  // revisit (no flash), refreshed once per mount.
  const [localPublished, setLocalPublished] = useState<LocalPublishedLite[]>(() => localPublishedCache ?? []);
  useEffect(() => {
    if (!enabled) return;
    let cancelled = false;
    void safeInvoke<LocalProjectWire[]>("list_local_projects", undefined, []).then((list) => {
      if (cancelled) return;
      const pub = (Array.isArray(list) ? list : [])
        .filter((lp) => lp?.published)
        .map((lp) => ({ key: lp.key, title: lp.title }));
      localPublishedCache = pub;
      setLocalPublished(pub);
    });
    return () => { cancelled = true; };
  }, [enabled]);

  // #3966: the durable project list, from the same bridge the Projects page uses. `listDbProjects`
  // returns null on ANY failure (bridge absent, old bundled `bsc` without the verb, bad payload) — we
  // keep the previous rows in that case, so a degraded environment falls back to the store cache
  // exactly as before rather than dropping nodes.
  //
  // POLLED, not fetched once (#163): a one-shot mount-only fetch meant a row written from outside the
  // app — `bsc project network set` and friends — was invisible until the Glance workspace unmounted
  // and remounted (a rail navigation), or the app restarted. `usePoll` re-reads on the same cadence as
  // liveness below, so the CLI and the graph can no longer disagree about what a project looks like
  // while the user is just sitting on the page watching it.
  const [dbProjects, setDbProjects] = useState<DbProject[]>(() => dbProjectsCache ?? NO_DB_PROJECTS);
  usePoll(
    async (isCancelled) => {
      if (!enabled) return;
      const rows = await listDbProjects();
      if (isCancelled() || !rows) return;
      dbProjectsCache = rows;
      setDbProjects(rows);
    },
    DB_PROJECTS_POLL_MS,
    [enabled],
  );

  // githubGraphql (not a raw invoke) so the read goes through the backend TTL cache (#2447):
  // a Glance revisit within the window is served with no network call. Past the window, the
  // light updatedAt probe (#2448) diffs against the persisted records first — when no board
  // moved, the heavy `items(first:100)` re-POST is skipped and the records are re-served (the
  // persist effect below re-stamps fetchedAt).
  const published = useGithubQuery<GhProject[]>(
    () => fetchProjectsWithProbe({
      fetchHeavy: () =>
        githubGraphql<{ viewer?: { projectsV2?: { nodes: GhProject[] } } }>(PROJECTS_QUERY, null)
          .then((d) => d.viewer?.projectsV2?.nodes ?? []),
      records: useAppStore.getState().githubState?.records,
    }),
    [], enabled,
  );

  // Persist the freshest published set (#2446, superseding the module-level #2339 cache): a fresh fetch
  // overwrites the store's `githubState` records+fetchedAt (and mirrors into the bsc-project store), so
  // the last-known board state survives the Glance remount AND an app restart. Written in an effect (not
  // during render) so it stays a clean side effect; the merge below reads it synchronously as a fallback.
  useEffect(() => { if (published.data) setGithubState(toMinimalGhProjects(published.data)); }, [published.data, setGithubState]);

  // Precedence (#2446): live fetch > persisted records > local-inventory-only. The persisted fallback
  // renders the last-known set immediately (no drafts-only flash), then refreshes when the fetch lands —
  // FILTERED to projects that still exist locally (a draft or a published hub): a record whose hub was
  // deleted must not resurrect a node. That matches how the merge treats GitHub-only projects — they
  // render only while the LIVE fetch vouches for them.
  const effectivePublished = useMemo<GhProject[]>(() => {
    if (published.data) return published.data;
    if (!githubState?.records.length) return NO_PUBLISHED;
    const locals = [
      ...Object.entries(drafts).map(([key, d]) => ({ key, title: d.title })),
      ...localPublished,
    ];
    return filterRecordsToLocal(githubState.records, locals).map(minimalToGhProject);
  }, [published.data, githubState, drafts, localPublished]);

  const buildingKeys = useMemo(() => deriveBuildingKeys(livePaneIds, paneStatus), [livePaneIds, paneStatus]);
  // Everything that counts as "this project has something running" (#3429): a live agent session OR a
  // detected running app. Anything outside this set is dormant and reads `off` rather than resting at
  // `idle` — see `applyDormantHealth`.
  const activeKeys = useMemo(() => new Set([...buildingKeys, ...liveKeys]), [buildingKeys, liveKeys]);
  // The CURATED nodes (#2284/#2541) — drafts that declare their own Glance axes. Dormancy leaves these
  // alone (#3513): a declared health/activity is a statement, not a resting state to be overwritten.
  const curatedKeys = useMemo(
    () => new Set(Object.entries(drafts).filter(([, d]) => d.health || d.activity).map(([k]) => k)),
    [drafts],
  );
  // #3966: the draft set the graph is actually built from — the store cache UNIONED with the durable
  // projects DB. Computed once and used for BOTH the merge and the `isDraft` signal below, so a
  // DB-only project is a draft for colouring purposes exactly as a cached one is.
  const effectiveDrafts = useMemo(() => mergeDbIntoDrafts(drafts, dbProjects), [drafts, dbProjects]);
  // #architects-own-projects — which architect OWNS each project, straight off the durable row. The
  // ONLY writer is `bsc project architect set`; nothing in the UI edits it, so this is a pure read.
  // Which NETWORK each project belongs to, straight off the durable row like the architect below.
  // Written only by `bsc project network set`; nothing else edits it, so this is a pure read.
  const networkByKey = useMemo(
    () => Object.fromEntries(dbProjects.filter((r) => r.network).map((r) => [r.key, r.network as string])),
    [dbProjects],
  );
  const architectByKey = useMemo(
    () => Object.fromEntries(dbProjects.filter((r) => r.architect).map((r) => [r.key, r.architect as string])),
    [dbProjects],
  );
  // The ARCHIVED set, straight off the durable row like the architect above. Written only by
  // `bsc project db state <key> archived`; see {@link filterArchived} for why this is the marker
  // rather than `triaged`.
  const archivedKeys = useMemo(
    () => new Set(dbProjects.filter((r) => r.state === ARCHIVED_STATE).map((r) => r.key)),
    [dbProjects],
  );
  return useMemo(
    // Merge (drafts + local published + GitHub published), FILTER to triaged/working projects (#2541 —
    // a draft/plan never shows), then overlay activity from real signals: liveness → `live` (#2263),
    // running agents → `building` (#2551); a project with nothing running at all reads `off` (#3429).
    // (Stall → `waiting`/warn and faults → error are overlaid later in the workspace.)
    // …then the `modifying` health state (#4052) LAST, so it can lift the resting `off` that dormancy
    // just derived. It is the only overlay here that reads issue counts.
    () => withProjectProgress(applyModifyingHealth(
      applyDormantHealth(
        applyRunningActivity(
          applyLiveness(
            filterArchived(
              mergeGlanceProjects(effectiveDrafts, effectivePublished, localPublished).map((p) => ({
                ...p,
                appType: planClassification[p.id]?.appType, // #3786/#3802 — the contract endpoint-type discriminator (absent ⇒ plain)
                // #4062 — the discovered lifecycle intent. NOT `lifecycleOf`: that applies the
                // stage-gating default, and an unclassified project must show no chip at all.
                lifecycle: planClassification[p.id]?.lifecycle,
                // #architects-own-projects — absent ⇒ unassigned, which the graph resolves against
                // the architect set (sole architect adopts it; several ⇒ no edge until assigned).
                architect: architectByKey[p.id],
                // The NETWORK this project is filed into — what SCOPES L0 to a tab. Absent reads as
                // unfiled: the project appears in `All projects` and in no network tab, which is the
                // honest answer rather than filing it somewhere it was never put.
                network: networkByKey[p.id],
              })), archivedKeys),
            liveKeys,
          ),
          buildingKeys,
        ),
        activeKeys,
        curatedKeys,
      ),
      activeKeys,
      openIssueKeys,
    ), projectProgress),
    [effectiveDrafts, effectivePublished, localPublished, archivedKeys, liveKeys, buildingKeys, activeKeys, curatedKeys, planClassification, architectByKey, networkByKey, openIssueKeys, projectProgress],
  );
}

// useGraphPage (#2719) — the small composition every graph PAGE hand-rolled: create a
// `useGraphViewport` and then re-fit it (deferred to the next animation frame) whenever the framed
// graph changes. It bundles the viewport plus the fit-on-key effect so a page only supplies the
// world, the fit key, and (optionally) the viewport options.
//
// ⚠️ THE FIT KEY MUST NOT BE THE POLLED GRAPH MODEL. Pass a STABLE value that changes ONLY when the
// graph should genuinely re-fit — a kit id, a drill target, a page name. Do NOT key on the graph
// `model`/`data` object itself: it gets a fresh reference on every data poll (liveness/fault/stall
// overlays recompute it), so keying on it re-fits every few seconds and wipes out the user's pan/zoom
// (#2554). `fit` reads the current world via a ref inside the viewport, so a deferred fit still
// frames the freshly-swapped graph even though the key, not the world, is the dependency.
//
// Bespoke fit logic stays in the page (Teams' saved-zoom restore, Glance's page-visibility guard,
// any centerOn focus move) — this hook owns only the plain rAF fit-on-key path.
import { useEffect } from "react";
import { useGraphViewport, type GraphViewport, type GraphViewportOpts } from "@/shared/ui/layouts/useGraphViewport";

/**
 * Create a graph viewport for `world` and rAF-fit it on mount and whenever any value in `fitKey`
 * changes. Returns the full {@link GraphViewport} (pan/zoom controls, `fit`, `centerOn`, …).
 *
 * @param world  Nominal world box for the viewport.
 * @param fitKey Dependency list whose changes trigger a deferred re-fit — see the model-keying trap above.
 * @param opts   Viewport options (min/max zoom, fit padding, content bounds provider).
 */
export function useGraphPage(
  world: { w: number; h: number },
  fitKey: React.DependencyList,
  opts?: GraphViewportOpts,
): GraphViewport {
  const vp = useGraphViewport(world, opts);
  const { fit } = vp;
  useEffect(() => {
    const id = requestAnimationFrame(() => fit());
    return () => cancelAnimationFrame(id);
    // fit is stable per-viewport; the caller-supplied fitKey drives re-fits.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...fitKey, fit]);
  return vp;
}

tests.src:
// useGraphPage (#2719) — the shared "create a viewport + rAF-fit on a stable key" composition. We
// mock the underlying viewport so `fit` is a spy, then assert the hook fits on mount and on each
// key change but NOT when only the world object churns (the polled-model trap the doc warns about).
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, act } from "@testing-library/react";

const { fitSpy } = vi.hoisted(() => ({ fitSpy: vi.fn() }));
vi.mock("@/shared/ui/layouts/useGraphViewport", async (orig) => {
  const actual = await orig<typeof import("@/shared/ui/layouts/useGraphViewport")>();
  return {
    ...actual,
    useGraphViewport: () => ({
      view: { tx: 0, ty: 0, scale: 1 },
      setVp: () => {}, onCanvasDown: () => {}, fit: fitSpy, centerOn: () => {},
      zoomBy: () => {}, zoomTo: () => {}, zoomToCentered: () => {}, panBy: () => {}, zoomAtClient: () => {},
      dragMoved: { current: false }, worldTransform: {},
    }),
  };
});

import { useGraphPage } from "@/shared/ui/layouts/useGraphPage";

const flushRaf = () => act(async () => { await new Promise((r) => requestAnimationFrame(() => r(null))); });

describe("useGraphPage (#2719)", () => {
  beforeEach(() => fitSpy.mockClear());

  it("fits once on mount (deferred to a frame)", async () => {
    renderHook(({ k }) => useGraphPage({ w: 100, h: 100 }, [k]), { initialProps: { k: "a" } });
    expect(fitSpy).not.toHaveBeenCalled(); // deferred, not synchronous
    await flushRaf();
    expect(fitSpy).toHaveBeenCalledTimes(1);
  });

  it("re-fits when the key changes but NOT when only the world churns", async () => {
    const { rerender } = renderHook(
      ({ k, world }: { k: string; world: { w: number; h: number } }) => useGraphPage(world, [k]),
      { initialProps: { k: "a", world: { w: 100, h: 100 } } },
    );
    await flushRaf();
    expect(fitSpy).toHaveBeenCalledTimes(1); // mount

    // A fresh world reference with the SAME key must not re-fit (the polled-model trap).
    rerender({ k: "a", world: { w: 100, h: 100 } });
    await flushRaf();
    expect(fitSpy).toHaveBeenCalledTimes(1);

    // Changing the key re-fits.
    rerender({ k: "b", world: { w: 100, h: 100 } });
    await flushRaf();
    expect(fitSpy).toHaveBeenCalledTimes(2);
  });
});

