import { describe, it, expect, vi, beforeEach } from "vitest";
import { act, renderHook, waitFor } from "@testing-library/react";

const loadGraph = vi.fn();
const loadGraphSig = vi.fn();
vi.mock("@/features/algorithms/lib/graphBridge", () => ({
  loadGraph: () => loadGraph(),
  loadGraphSig: () => loadGraphSig(),
}));

// CAPTURE THE POLL CALLBACK so a test can drive TICKS instead of waiting for them. The interval is
// 5s; a test that renders the hook and then awaits a macrotask observes exactly ONE tick, so any
// assertion about what the SECOND tick does is vacuous — which is how the first version of the
// short-circuit test below passed against a hook with the short-circuit deleted.
let tick: ((isCancelled: () => boolean) => Promise<void>) | null = null;
vi.mock("@/shared/hooks/usePoll", () => ({
  usePoll: (fn: (isCancelled: () => boolean) => Promise<void>) => {
    tick = fn;
  },
}));

import { useKnowledgeGraph } from "@/features/algorithms/useKnowledgeGraph";
import { KNOWLEDGE } from "@/features/algorithms/lib/knowledge";

describe("useKnowledgeGraph (#2856)", () => {
  // Block body, not the concise arrow — see graphBridge.test.ts (#3390): `mockReset()` returns the mock,
  // which vitest then runs as an after-each teardown. Harmless while every test here resolves, but it is
  // the same landmine that silently failed the sibling suite the moment one test rejected.
  beforeEach(() => {
    loadGraph.mockReset();
    // DEFAULT TO "CANNOT TELL". Every pre-existing test below was written before the signature
    // short-circuit and asserts what `loadGraph` returns, so the default has to be the value that
    // still reaches it — which is the same null-means-fall-through rule the hook itself follows.
    loadGraphSig.mockReset();
    loadGraphSig.mockResolvedValue(null);
  });

  it("starts on the packaged seed (instant first paint), and keeps it when the bridge is unreachable", () => {
    loadGraph.mockResolvedValue(null);
    const { result } = renderHook(() => useKnowledgeGraph());
    expect(result.current.graph).toBe(KNOWLEDGE);
  });

  it("swaps to the store's graph when it differs from the seed (a librarian edit shows)", async () => {
    loadGraph.mockResolvedValue({
      implementations: [
        ...KNOWLEDGE.implementations,
        { id: "rust.skiplist", tech: "rust", role: "primitive", name: "SkipList", composes: [], code: "// skip list" },
      ],
    });
    const { result } = renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    await waitFor(() => expect(result.current.graph.implementations.some((im) => im.id === "rust.skiplist")).toBe(true));
  });

  it("keeps the seed identity when the store still matches it (no needless swap/re-render)", async () => {
    loadGraph.mockResolvedValue(KNOWLEDGE);
    const { result } = renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    expect(result.current.graph).toBe(KNOWLEDGE); // sig matched the seed → never re-set
  });

  // ── the signature short-circuit (#the-algorithms-page-hydrates-fifty-megabytes-every-five-seconds) ──

  it("does not transfer a document when the store's signature has not changed", async () => {
    // THE WHOLE POINT. This poll used to pull the entire store every 5 seconds and compare afterwards —
    // MEASURED at 50.72 MB per tick against a page that renders 0.93 MB of it — and when that transfer
    // failed the hook silently kept the packaged seed. Asking for the signature first makes the common
    // case (nothing changed) cost nothing.
    loadGraphSig.mockResolvedValue("sig-1");
    loadGraph.mockResolvedValue(KNOWLEDGE);
    renderHook(() => useKnowledgeGraph());

    // Tick one: no signature is held yet, so it cannot know the store is current — it must read.
    await act(async () => { await tick!(() => false); });
    expect(loadGraph).toHaveBeenCalledTimes(1);

    // Ticks two and three: same signature, so NO document may cross.
    await act(async () => { await tick!(() => false); });
    await act(async () => { await tick!(() => false); });
    expect(loadGraph, "an unchanged signature must not fetch the document again").toHaveBeenCalledTimes(1);
    expect(loadGraphSig).toHaveBeenCalledTimes(3);
  });

  it("fetches again as soon as the signature moves", async () => {
    // The other half: the short-circuit must not become a freeze. A librarian edit changes the
    // signature, and the very next tick must read the document.
    loadGraphSig.mockResolvedValue("sig-1");
    loadGraph.mockResolvedValue(KNOWLEDGE);
    renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    await act(async () => { await tick!(() => false); });
    expect(loadGraph).toHaveBeenCalledTimes(1);

    loadGraphSig.mockResolvedValue("sig-2");
    await act(async () => { await tick!(() => false); });
    expect(loadGraph).toHaveBeenCalledTimes(2);
  });

  it("treats an unreadable signature as CANNOT TELL and still reads the store", async () => {
    // `null` must never be taken for "unchanged". If it were, one failed signature read would freeze
    // the page on whatever it last rendered and no later edit would ever appear.
    loadGraphSig.mockResolvedValue(null);
    loadGraph.mockResolvedValue(KNOWLEDGE);
    renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    await act(async () => { await tick!(() => false); });
    expect(loadGraph, "cannot-tell must fall through to a full read, every time").toHaveBeenCalledTimes(2);
  });

  // ── the source is REPORTED, not inferred (#the-algorithms-page-says-which-store-it-is-showing) ──

  it("says `seed` until a read of the writable store lands", async () => {
    // The fallback is silent by construction: a failed hydrate keeps the packaged seed and renders a
    // graph that looks entirely correct and is a third the size (758 records against 1,403; 36 under
    // crates/ against 542). Nothing on screen distinguished them, and two separate faults hid behind
    // that for hours. The page can only say so if the hook tells it.
    loadGraphSig.mockResolvedValue(null);
    loadGraph.mockResolvedValue(null);
    const { result } = renderHook(() => useKnowledgeGraph());
    expect(result.current.source).toBe("seed");
    await act(async () => { await tick!(() => false); });
    expect(result.current.source, "a failed read must NOT read as hydrated").toBe("seed");
  });

  it("says `store` once a read lands, even when the content equals the seed", async () => {
    // A store that happens to match the seed IS hydrated — only a store we could not READ is not.
    // Reporting that case as `seed` would leave the notice up permanently on a healthy install.
    loadGraph.mockResolvedValue(KNOWLEDGE);
    const { result } = renderHook(() => useKnowledgeGraph());
    await act(async () => { await tick!(() => false); });
    expect(result.current.source).toBe("store");
    expect(result.current.graph).toBe(KNOWLEDGE);
  });
});

implementations.code:
// useLogStream (#3638) — the event-driven replacement for `usePoll` over a `bsc logs` stream. The
// frontend used to poll each unified log stream every ~1s; instead, the backend watcher
// (`observability::log_watch`) emits `logs://<stream>` when a stream file changes, and this hook
// re-reads (via the in-process `logs_*` commands, #3630) ONLY on that event. So reads happen on
// CHANGE, not on a clock — an idle app makes zero log reads.
//
// It keeps `usePoll`'s callback contract (an `isCancelled()` guard) so the pump bodies move over
// unchanged. A slow safety-net interval (default 60s) is the sole remaining "poll", a backstop against
// a missed change event — 60× rarer than the ~1s polls it replaces, and effectively silent.

import { useEffect, useRef, type DependencyList } from "react";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import { usePoll } from "@/shared/hooks/usePoll";
import { logEventName } from "@/shared/lib/core/logsBridge";

interface LogStreamOptions {
  /** Safety-net re-read interval (ms) — a backstop against a missed change event. Default 60000. */
  safetyMs?: number;
  /** When false, don't subscribe or read at all — the caller-side gate (e.g. page visibility, #3627).
   *  Default true. */
  active?: boolean;
}

/**
 * Re-run `fn` when any of `streams` changes (the `logs://<stream>` event), plus once on mount and on a
 * slow safety-net interval. `fn` gets the same `isCancelled` guard as {@link usePoll}. Pass the read
 * alias(es) the body reads (`"coord"`, `"activity"`, `"audit"`, …) — canonicalized to match the emit.
 *
 * @param streams one stream alias, or several (a body that reads more than one stream re-runs on any).
 * @param fn the read/process body — identical shape to a `usePoll` callback.
 * @param deps re-subscribe deps (like `usePoll`'s).
 * @param opts `safetyMs` (backstop interval) and `active` (caller-side gate).
 */
export function useLogStream(
  streams: string | string[],
  fn: (isCancelled: () => boolean) => void | Promise<void>,
  deps: DependencyList = [],
  opts: LogStreamOptions = {},
): void {
  const { safetyMs = 60_000, active = true } = opts;
  const list = Array.isArray(streams) ? streams : [streams];
  const key = list.join(",");
  const fnRef = useRef(fn);
  useEffect(() => { fnRef.current = fn; });

  // Initial read on mount + a slow backstop poll. `immediate` gives the current state right away;
  // `active:false` short-circuits both this and the subscription below.
  usePoll((isCancelled) => (active ? fnRef.current(isCancelled) : undefined), safetyMs, [key, active, ...deps]);

  // Re-read on any watched stream's change event.
  useEffect(() => {
    if (!active) return;
    let cancelled = false;
    const isCancelled = () => cancelled;
    const uns: UnlistenFn[] = [];
    // EVERY promise here is swallowed on purpose, and none of them was before.
    //
    // `UnlistenFn` RETURNS A PROMISE, and Tauri's `unregisterListener` rejects whenever the listener
    // is already gone — the ordinary case during teardown, when the backend has dropped the channel
    // or the webview is unmounting. Nothing awaited it, so it surfaced as an unhandled rejection
    // whose whole stack was inside Tauri:
    //
    //     @user-script:8:11:75
    //     unregisterListener@user-script:8:13:9
    //     _unlisten@…/@tauri-apps_api_event.js:40:60
    //     @…/.bsc-records/shared/hooks/useLogStream.tsx:54:22
    //
    // — which the crash overlay then reported as a FATAL BOOT ERROR (see `fatalOverlay`), because a
    // rejection with no message and a foreign stack is indistinguishable from a real one. A hook
    // that unsubscribes cleanly should never be able to do that.
    //
    // `listen` itself is caught too: it rejects when the window is torn down mid-subscribe, and that
    // is a normal race on a fast unmount, not a fault.
    const quietly = (p: unknown) => { void Promise.resolve(p).catch(() => {}); };
    for (const s of list) {
      void listen(logEventName(s), () => { if (!cancelled) void fnRef.current(isCancelled); })
        .then((un) => { if (cancelled) quietly(un()); else uns.push(un); })
        .catch(() => { /* the window went away before the subscription landed */ });
    }
    return () => { cancelled = true; uns.forEach((un) => quietly(un())); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, active, ...deps]);
}

tests.src:
// useLogStream (#3638) — event-driven log reads.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { listen } from "@tauri-apps/api/event";
import { useLogStream } from "@/shared/hooks/useLogStream";

// Capture each `listen(name, cb)` so a test can FIRE the stream-change event, and count unlistens.
const handlers: Record<string, () => void> = {};
let unlistened = 0;

beforeEach(() => {
  for (const k of Object.keys(handlers)) delete handlers[k];
  unlistened = 0;
  vi.mocked(listen).mockImplementation((name, cb) => {
    handlers[name] = () => (cb as (e: { payload: unknown }) => void)({ payload: null });
    return Promise.resolve(() => { unlistened++; });
  });
});


describe("useLogStream: the unlisten rejection is handled", () => {
  /** An unlisten that rejects the way Tauri's does, and REPORTS whether anyone attached a handler. */
  function rejectingUnlisten() {
    const state = { caught: false };
    const fn = () => {
      const p = Promise.reject(new Error("listener not found"));
      const realCatch = p.catch.bind(p);
      (p as unknown as { catch: unknown }).catch = (...a: Parameters<typeof realCatch>) => {
        state.caught = true;
        return realCatch(...a);
      };
      return p as unknown as void;
    };
    return { fn, state };
  }

  it("attaches a catch when unsubscribing on unmount", async () => {
    const { fn, state } = rejectingUnlisten();
    vi.mocked(listen).mockImplementation(() => Promise.resolve(fn as unknown as () => void));
    const { unmount } = renderHook(() => useLogStream("coord", () => {}));
    await act(async () => { await Promise.resolve(); await Promise.resolve(); });
    await act(async () => { unmount(); });
    await new Promise((r) => setTimeout(r, 0));
    expect(state.caught).toBe(true);
  });

  it("attaches a catch on the CANCELLED path too", async () => {
    const { fn, state } = rejectingUnlisten();
    let resolveListen: ((un: () => void) => void) | undefined;
    vi.mocked(listen).mockImplementation(() => new Promise((res) => { resolveListen = res as (un: () => void) => void; }));
    const { unmount } = renderHook(() => useLogStream("coord", () => {}));
    unmount();
    resolveListen?.(fn as unknown as () => void);
    await new Promise((r) => setTimeout(r, 0));
    await new Promise((r) => setTimeout(r, 0));
    expect(state.caught).toBe(true);
  });
});

