// usePreviewData (#2940 / #3439) — resolves a component's preview data into the override map
// `ComponentPreviewFrame` feeds `componentPreviewFiles`, in the resolution order
//
//     curated binding (#2940)  →  shape tier (#3439)  →  samplePropValue (the component's own sample)
//
// 1. A curated `PREVIEW_BINDINGS` row runs the bound librarian algorithm's `vizCode` in the sandbox,
//    normalizes it (`vizRunToDataset`), shapes it for the prop (`adaptDataset`) — ASYNC.
// 2. Otherwise, if the component declares a supported `DataShape`, the SHAPE TIER feeds it real
//    algorithm-generated data with no per-component row (`shapePreviewData`) — SYNC (the trace programs
//    run on the main thread).
// 3. Otherwise `{}` → the component's own sample shows.
//
// Fail-SOFT throughout: a missing impl/`vizCode`, a sandbox error, an unusable dataset, or a shape with
// no landable prop all resolve to `{}`, so a preview is never broken.
import { useEffect, useMemo, useState } from "react";
import { KNOWLEDGE, implById, runInSandbox, vizRunToDataset, datasetForStructure } from "@/features/algorithms";
import type { ComponentRecord } from "@/features/designs/lib/model";
import { bindingFor, adaptDataset } from "@/features/designs/lib/previewBindings";
import { shapePreviewData } from "@/features/designs/lib/shapePreview";

const EMPTY: Record<string, string> = {};

/** The preview-data override map for `comp` (`{ prop: JS-source literal }`), or `{}` until/unless a bound
 *  algorithm or a supported shape resolves. Safe to pass straight to `componentPreviewFiles(..., previewData)`. */
export function usePreviewData(comp: ComponentRecord): Record<string, string> {
  const binding = bindingFor(comp.kitId, comp.name);
  const [data, setData] = useState<Record<string, string>>(EMPTY);

  // Shape tier (#3439): SYNC — only when there is NO curated binding (that path wins). The trace programs
  // run on the main thread, so this needs no effect; memoized on the component identity that determines it.
  const shapeData = useMemo(
    () => (binding ? EMPTY : shapePreviewData(comp, datasetForStructure)),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- comp identity (kitId/name/shapes/props) determines it
    [binding, comp.kitId, comp.name],
  );

  // Key the resolve on the identity that determines the result — the bound algorithm + prop. A different
  // component (no binding) resets to EMPTY synchronously below via the early clear.
  const key = binding ? `${binding.algorithm}:${binding.prop}` : "";

  useEffect(() => {
    /* eslint-disable react-hooks/set-state-in-effect -- intentional reset: clear stale data when the
       bound component changes or its algorithm has no runnable vizCode (mirrors ComponentPreviewFrame). */
    if (!binding) { setData(EMPTY); return; }
    const impl = implById(KNOWLEDGE, binding.algorithm);
    const vizCode = impl?.vizCode?.trim();
    if (!vizCode) { setData(EMPTY); return; }
    /* eslint-enable react-hooks/set-state-in-effect */

    let cancelled = false;
    void runInSandbox(vizCode)
      .then((run) => {
        if (cancelled) return;
        const value = adaptDataset(vizRunToDataset(run), binding.adapter);
        setData(value == null ? EMPTY : { [binding.prop]: JSON.stringify(value) });
      })
      .catch(() => { if (!cancelled) setData(EMPTY); });

    return () => { cancelled = true; };
    // `key` captures the binding's algorithm+prop; `comp.kitId`/`comp.name` feed `binding` above.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return binding ? data : shapeData;
}

// usePreviewReview (#2623 slice 5b) — the reviewer loop's actuator for the open preview node. Owns the
// display-capture stream, turns a "Capture & review" click into a shot → Claude review (5c) → findings
// merged into the confirm-gated inbox (5a store), and exposes confirm/dismiss. Findings live in the store
// keyed by project so the strip re-renders; the stream is a ref (one OS "share" pick, reused per shot).

import { useCallback, useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { resolveLlmConfig } from "@/shared/lib/core/llmConfig";
import { startPreviewCapture, grabFrame, stopCapture, screenCaptureAvailable } from "@/shared/lib/preview/captureFrame";
import { reviewShot } from "@/shared/lib/preview/reviewShot";
import {
  mergeFindings,
  setFindingStatus,
  pendingFindings,
  confirmedFindings,
  routedFindings,
  type PreviewShot,
  type ReviewFinding,
} from "@/shared/lib/preview/previewReview";

const EMPTY: ReviewFinding[] = [];
const errText = (e: unknown): string => (e instanceof Error ? e.message : String(e));


export interface PreviewReview {
  findings: ReviewFinding[];
  pending: ReviewFinding[];
  confirmed: ReviewFinding[];
  /** Findings already routed to the fleet (a tally; they don't re-dispatch). */
  routed: ReviewFinding[];
  /** Screen capture is available in this webview (gate the capture button). */
  canCapture: boolean;
  /** A capture + review is in flight. */
  busy: boolean;
  /** The last capture/review/dispatch failure, or null. */
  error: string | null;
  /** Capture the current preview frame and review it — folds new findings into the inbox. */
  captureAndReview: () => Promise<void>;
  confirm: (id: string) => void;
  dismiss: (id: string) => void;
  /** Route all confirmed findings to the project's director (bsc-issue → bsc-assign) and mark them routed. */
  dispatch: () => Promise<void>;
}

export function usePreviewReview(projectKey: string | null): PreviewReview {
  const findings = useAppStore((s) => (projectKey ? s.reviewFindings[projectKey] : undefined) ?? EMPTY);
  const streamRef = useRef<MediaStream | null>(null);
  const seqRef = useRef(0);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // End the OS "sharing" stream when the preview closes / the hook unmounts.
  useEffect(() => () => { stopCapture(streamRef.current); streamRef.current = null; }, []);

  const captureAndReview = useCallback(async () => {
    if (!projectKey || busy) return;
    setError(null);
    setBusy(true);
    try {
      if (!streamRef.current) streamRef.current = await startPreviewCapture();
      const image = await grabFrame(streamRef.current);
      const seq = seqRef.current++;
      const shot: PreviewShot = { id: `${projectKey}:${seq}`, label: `Screen ${seq + 1}`, image };
      const found = await reviewShot(resolveLlmConfig(useAppStore.getState()), shot, seq);
      const store = useAppStore.getState();
      store.setReviewFindings(projectKey, mergeFindings(store.reviewFindings[projectKey] ?? [], found));
    } catch (e) {
      setError(errText(e));
      // A failure often means the user stopped sharing — drop the stream so the next try re-prompts.
      stopCapture(streamRef.current);
      streamRef.current = null;
    } finally {
      setBusy(false);
    }
  }, [projectKey, busy]);

  const setStatus = useCallback((id: string, status: ReviewFinding["status"]) => {
    if (!projectKey) return;
    const store = useAppStore.getState();
    store.setReviewFindings(projectKey, setFindingStatus(store.reviewFindings[projectKey] ?? [], id, status));
  }, [projectKey]);

  const dispatch = useCallback(async () => {
    if (!projectKey) return;
    const store = useAppStore.getState();
    const confirmed = confirmedFindings(store.reviewFindings[projectKey] ?? []);
    if (confirmed.length === 0) return;
    // #app-stops-pushing-prompts — this used to type the confirmed findings into the project's
    // director. The app pushes nothing now, so dispatch only MARKS them routed; a director picks them
    // up when it reads the review state. The maintainer accepted that these findings have no store the
    // director can poll today, so until they get one this is a local status change, not a delivery.
    setError(null);
    let next = store.reviewFindings[projectKey] ?? [];
    for (const f of confirmed) next = setFindingStatus(next, f.id, "routed");
    store.setReviewFindings(projectKey, next);
  }, [projectKey]);

  return {
    findings,
    pending: pendingFindings(findings),
    confirmed: confirmedFindings(findings),
    routed: routedFindings(findings),
    canCapture: screenCaptureAvailable(),
    busy,
    error,
    captureAndReview,
    confirm: useCallback((id: string) => setStatus(id, "confirmed"), [setStatus]),
    dismiss: useCallback((id: string) => setStatus(id, "dismissed"), [setStatus]),
    dispatch,
  };
}

