// usePageSelection — the Pages-tier internal selection hook (#2505): the controlled/uncontrolled
// selection idiom the Layouts tier established (Tree/Sequence — controlled when the `selectedId`
// prop is PRESENT, may be null = none; else internal state seeded by `defaultSelectedId`), extracted
// once so the five selecting pages don't re-implement it.
import { useState } from "react";

export interface PageSelection {
  /** The live selected id — the prop when controlled, internal state otherwise. */
  selected: string | null;
  /** Select an id: updates internal state when uncontrolled; always notifies `onSelect`. */
  select: (id: string) => void;
}

export function usePageSelection(
  selectedId: string | null | undefined,
  defaultSelectedId: string | undefined,
  onSelect?: (id: string) => void,
): PageSelection {
  const [inner, setInner] = useState<string | null>(defaultSelectedId ?? null);
  const controlled = selectedId !== undefined;
  const selected = controlled ? selectedId : inner;
  const select = (id: string) => {
    if (!controlled) setInner(id);
    onSelect?.(id);
  };
  return { selected, select };
}

// useSoundKits (#3080) — the Sounds tab's kit source, seed-first: renders the packaged built-ins
// immediately, then hydrates from the durable `bsc-sound` store and seeds any built-in the store is
// missing (first run). Mirrors the Algorithms knowledge-graph hydration (`useKnowledgeGraph`, #2856):
// a hook, not a store slice, since the library is read-mostly here (authoring lands in Phase 4).
import { useEffect, useState } from "react";
import type { SoundKit } from "@/features/sounds/lib/soundDescriptor";
import { BUILTIN_KITS, mergeKits } from "@/features/sounds/lib/soundKits";
import { loadKits, pushKit } from "@/features/sounds/lib/soundBridge";

export function useSoundKits(): SoundKit[] {
  const [kits, setKits] = useState<SoundKit[]>(BUILTIN_KITS);
  useEffect(() => {
    let cancelled = false;
    void loadKits().then((rows) => {
      const { kits: merged, toSeed } = mergeKits(rows);
      // Push any built-in the store doesn't have yet, so `bsc sound get <id>` works from a session too.
      toSeed.forEach((k) => { void pushKit(k).catch(() => {}); });
      if (!cancelled && merged.length) setKits(merged);
    });
    return () => { cancelled = true; };
  }, []);
  return kits;
}

