// useStudioViewer (#3357) — the ONE way a surface says "I am showing this studio session".
//
// Both surfaces that can show a studio terminal call it: the studio page's `SessionDock` and the Glance
// node morph. On the first call the studio becomes WANTED (the lazy start — nothing launches at app boot),
// and for as long as the caller is showing it the studio's viewer count is held above zero, which keeps the
// idle reaper disarmed. When the last viewer goes away the reaper arms; the session stays warm on
// TerminalHost throughout, so re-opening inside the window reattaches to the SAME conversation.
import { useEffect } from "react";
import { useAppStore } from "@/store";
import type { StudioId } from "@/features/studio-sessions/lib/studioSessions";

/**
 * Register this component as a viewer of `id`'s studio session while `showing` is true.
 *
 * @param id      the studio, or null when this surface currently shows no studio (the hook then no-ops,
 *                so a caller with a conditional target — the Glance morph — can still call it
 *                unconditionally, as the rules of hooks require).
 * @param showing whether the surface is ACTUALLY on screen. A page dock stays MOUNTED but CSS-hidden when
 *                the user switches pages (`KeptMountedPage`), and a mounted-but-hidden dock must not pin
 *                the session alive forever — otherwise the reaper could never fire after a first visit.
 */
export function useStudioViewer(id: StudioId | null | undefined, showing = true): void {
  useEffect(() => {
    if (!id || !showing) return;
    const st = useAppStore.getState();
    // Showing it is what STARTS it: opening a studio page (or its Glance node) is the lazy launch.
    st.openStudio(id);
    st.addStudioViewer(id);
    return () => { useAppStore.getState().removeStudioViewer(id); };
  }, [id, showing]);
}

/**
 * The MANY form of {@link useStudioViewer} — register this surface as a viewer of every studio in `ids`.
 *
 * Needed since #3361, where several node morphs can be open at once: the single-id hook cannot be called
 * in a loop (a variable hook count breaks the rules of hooks), and calling it once with only the
 * most-recently-opened id would leave every other open studio unpinned — so the reaper could kill a
 * session the user is looking at in another morph.
 *
 * Keyed on the joined id list, so opening a second studio re-runs the effect: the cleanup decrements the
 * already-open studios and the body immediately re-increments them. That transient dip to 0 is harmless —
 * the reaper only ARMS a timer at 0 and re-checks the live count when it fires (tens of minutes later),
 * by which point the count is back up.
 */
export function useStudioViewers(ids: readonly StudioId[], showing = true): void {
  const key = ids.join(",");
  useEffect(() => {
    if (!showing || !key) return;
    const list = key.split(",") as StudioId[];
    const st = useAppStore.getState();
    for (const id of list) { st.openStudio(id); st.addStudioViewer(id); }
    return () => {
      const s = useAppStore.getState();
      for (const id of list) s.removeStudioViewer(id);
    };
  }, [key, showing]);
}

// useSystemSessionBridge (#architect-starts-and-stops-system-sessions) — apply a `bsc session
// start|stop` request to the store and ACK it.
//
// THE ROUND TRIP
//   bsc session start → request file → Rust watcher → `bsc://session-lifecycle` → HERE → store
//                     → `system_session_ack`
//
// A thin adapter: the DECISION lives in `systemSessionBridge.ts`, unit-testable without Tauri. Same
// shape as `useFleetWakeBridge`, deliberately — one more emit-and-ack verb on the one channel, not a
// second mechanism.
//
// THIS IS NOT AN INJECTION PATH. Nothing here writes text into a session: `openStudio` mounts a
// studio the user could have opened by clicking, and the started session keeps its own role gate.
// `injectCallers.test.ts` asserts `injectPrompt` has no callers, and this must never become one.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { applyLifecycle, type LifecycleRequest, type LifecycleAck } from "@/app/systemSessionBridge";

/**
 * Listen for `bsc://session-lifecycle` and apply it. Mounted once by the shell.
 */
export function useSystemSessionBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<LifecycleRequest>("bsc://session-lifecycle", async (e) => {
      const req = e.payload;
      let ack: LifecycleAck;
      try {
        // Read off a LIVE getState, not a captured snapshot: zustand hands out a new object per
        // update, so a stale closure could decide against an older `wantedStudios`.
        const st = useAppStore.getState();
        ack = await applyLifecycle(req, {
          wantedStudios: st.wantedStudios,
          openStudio: (id) => useAppStore.getState().openStudio(id),
          closeStudio: (id) => useAppStore.getState().closeStudio(id),
          setPendingDirective: (id, d) => useAppStore.getState().setStudioPendingDirective(id, d),
          // Killing is explicit, exactly as the idle reaper does it: dropping the host claim only
          // unmounts the <TerminalView> — its cleanup deliberately leaves the backend session alive
          // so a console tab-switch reconnects rather than respawns.
          killPane: async (p) => { await safeInvoke("pty_kill", { paneId: p }, undefined); },
        });
      } catch (err) {
        // A throw here would strand the Rust waiter until its timeout. State it instead.
        ack = {
          id: req.id,
          error: `session lifecycle threw: ${err instanceof Error ? err.message : String(err)}`,
        };
        log.error(`session lifecycle ${req.id} threw: ${String(err)}`);
      }
      void invoke("system_session_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`system_session_ack failed for ${req.id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// Session-readiness state for a terminal pane (#1645). Owns the preflight verdict (#564) that
// TerminalView renders as the SessionFailure banner, and the manual retry.
//
// CRITICAL ONLY. The verdict also carries `warning` checks — exactly `gh` and `gh auth` — and those
// used to raise a per-pane banner. It is gone (`drop-the-github-readiness-banner`): whether a project
// uses GitHub is a discovery decision, and the panes that saw it most are denied `gh` by their own
// role gate. Settings → Diagnostics still reports both. The mount-effect launch path sets the verdict via `setReadinessVerdict`
// after its own preflight probe (which runs with the resolved GH token); this hook owns the same probe
// for the user-triggered retry. Kept here (not in lib/) because it carries React state.

import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { log } from "@/shared/lib/core/log";
import { interpretDiagnostics, sessionVerdictFromReport, type PrereqStatus, type SessionVerdict } from "@/shared/lib/core/diagnostics";
import { tokenForRepo } from "@/shared/lib/github/repoCredentials";
import { useAppStore } from "@/store";

export function useTerminalSession(paneId: string, initialCwd?: string) {
  // Session readiness verdict (#564). Set after the preflight probe runs in the mount effect (after
  // the GH token is resolved so gh-auth uses the right env), or by `retryReadiness` below.
  const [readinessVerdict, setReadinessVerdict] = useState<SessionVerdict | null>(null);

  // Only the CRITICAL checks are rendered. The two `warning` ones — `gh` and `gh auth` — used to
  // raise a per-pane banner, and it was wrong twice over: whether a project uses GitHub at all is a
  // DISCOVERY decision (`usesGithub`), not something a probe may infer from the host; and the panes
  // that saw it most are the ones their own role gate denies `gh` outright, so it warned them about a
  // capability they were deliberately never given. `Settings → Diagnostics` still reports both, which
  // is where someone goes to ASK rather than be told.
  const criticalChecks = readinessVerdict?.failed.filter((c) => c.severity === "critical") ?? [];

  function retryReadiness() {
    const cwd = initialCwd ?? "";
    // #3984: say so rather than returning silently. A no-op retry is indistinguishable from one that
    // ran and got the same verdict — which is exactly how the button read while the probe was failing
    // to spawn (#3984): it fired 15 times a boot and looked dead every time.
    if (!cwd) {
      log.warn(`console[${paneId}] readiness retry skipped — this pane has no cwd, so there is nothing to probe`);
      return;
    }
    const ghToken = tokenForRepo(
      useAppStore.getState().paneRepos[paneId],
      useAppStore.getState().repoGithubTokens,
      useAppStore.getState().githubToken,
    );
    const env = ghToken ? { GH_TOKEN: ghToken } : null;
    invoke<PrereqStatus[]>("preflight", { cwd, env })
      .then((prereqs) => setReadinessVerdict(sessionVerdictFromReport(interpretDiagnostics(prereqs))))
      .catch((e) => log.error(`console[${paneId}] preflight retry failed: ${e}`));
  }

  return { setReadinessVerdict, criticalChecks, retryReadiness };
}

// The automations tunnel surface (#937): project the automations store to a paired phone
// and accept its arm / disarm / run-now control. Mounted once at the app root.
//
// Outbound — push the list (id/name/schedule/armed/next-run/last-status) whenever it
//   changes; the relay replays the last push on connect.
// Inbound — route the phone's control through the SAME store + scheduler the desktop uses:
//   arm/disarm validates the cron (an invalid one is rejected back to the phone, never
//   silently armed); run-now fires the automation through the shared dispatch. The phone
//   never runs schedules itself — it only asks the desktop to.

import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { dispatchSchedule } from "@/features/automations";
import { automationToFrame, planArm } from "@/features/tunnel/lib/automationControl";
import { tunnelSetAutomations, tunnelAutomationFailed } from "@/features/tunnel/lib/tunnelClient";
import { log } from "@/shared/lib/core/log";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";

export function useTunnelAutomations(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);
  const automations = useAppStore((s) => s.automations);

  // Outbound projection — re-push whenever the list changes (no-op until a phone is paired).
  useEffect(() => {
    if (!tunnelRunning) return;
    tunnelSetAutomations(automations.map(automationToFrame))
      .catch((e) => log.error(`tunnel: set_automations failed: ${e}`));
  }, [tunnelRunning, automations]);

  // Inbound control — arm/disarm + run-now from the phone.
  useEffect(() => {
    let cancelled = false;

    const onArm = async (id: string, armed: boolean): Promise<void> => {
      const s = useAppStore.getState();
      const decision = planArm(s.automations.find((a) => a.id === id), id, armed);
      if (!decision.ok) {
        log.warn(`tunnel: rejecting mobile arm of "${id}" — ${decision.error}`);
        // Workspace the rejection back to the phone (also FCM-pushed, A4).
        await tunnelAutomationFailed(decision.id, Date.now(), decision.error, decision.name).catch(() => {});
        return;
      }
      log.info(`tunnel: mobile ${decision.armed ? "armed" : "disarmed"} automation "${decision.id}"`);
      s.setAutomationArmed(decision.id, decision.armed);
    };

    const onRunNow = async (id: string): Promise<void> => {
      const s = useAppStore.getState();
      // The mobile id is `<persona>:<schedule>` — the same key the automation log uses, so a
      // run-now and a scheduled fire are indistinguishable in the history, which is the point.
      const [personaId, ...rest] = id.split(":");
      const name = rest.join(":");
      const persona = s.personas?.find((p) => p.id === personaId);
      const sched = persona?.schedules?.find((x) => x.name === name);
      if (!sched) {
        log.warn(`tunnel: run-now for unknown schedule "${id}"`);
        return;
      }
      log.info(`tunnel: mobile run-now of schedule "${id}"`);
      await dispatchSchedule(
        { personaId, name, when: sched.when as never, command: sched.command },
        {
          panePersonas: s.panePersonas ?? {},
          disabledPanes: s.disabledPanes,
          write: (paneId: string, data: string) => invoke<void>("pty_write", { paneId, data }),
          recordRun: (pane: string, schedule: string, status: string, note: string) =>
            fireInvoke("append_automation_run", { pane, schedule, status, note }),
        },
      );
    };

    const subs = [
      listen<{ id: string; armed: boolean }>("tunnel://automation-arm", (e) => {
        if (!cancelled) void onArm(e.payload.id, e.payload.armed);
      }),
      listen<{ id: string }>("tunnel://automation-run-now", (e) => {
        if (!cancelled) void onRunNow(e.payload.id);
      }),
    ];
    return () => {
      cancelled = true;
      for (const s of subs) void s.then((off) => off());
    };
  }, []);
}

