/**
 * @vitest-environment jsdom
 *
 * This file lives under `lib/`, which vitest's `node` project covers, but it genuinely needs a DOM.
 * A per-file docblock beats the project's environment, so the requirement is stated where a reader
 * meets it. See the `projects` split in vitest.config.ts for why the default is `node` here.
 */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, waitFor } from "@testing-library/react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { useWorkerAutoEnd } from "@/shared/lib/fleet/useWorkerAutoEnd";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import type { AgentStream } from "@/features/planner/fleet/planFleet";

// Fleet workers carry STABLE pane ids (#1176): `<projectKey>:<streamId>`, not positional `t{n}p{n}`.
// The project key is resolved from the owning tab's `paneIds` (#1379 regression fix) — these ids +
// the tab's `paneIds` mirror what fleetStartProject actually mints.
const WORKER = "demo:api";
const DIRECTOR = "demo:director";

const handlers: Record<string, () => void> = {};

const stream = (id: string): AgentStream => ({ id, name: id, repo: "me/app", owns: [], issues: [], dependsOn: [] });

/** What Rust returns for a worker whose owned issues are all complete. */
const DONE_VERDICT = { state: "done", summary: "2/2 complete · 0/2 landed" };
/** …and for one that stopped early. */
const OPEN_VERDICT = { state: "needs-attention", summary: "stopped early — 1/2 still open · 1/2 complete" };

/** Every `worker_end_verdicts` invocation the hook made, with its payload. */
const verdictCalls = () =>
  vi.mocked(invoke).mock.calls.filter(([c]) => c === "worker_end_verdicts")
    .map(([, p]) => p as { projectKey: string; streamIds: string[] });

beforeEach(() => {
  vi.clearAllMocks();
  for (const k of Object.keys(handlers)) delete handlers[k];
  vi.mocked(listen).mockImplementation((name, cb) => {
    handlers[name] = () => (cb as (e: { payload: unknown }) => void)({ payload: null });
    return Promise.resolve(() => {});
  });
  // Default invoke: the log reads are the in-process `logs_*` commands (#3630, arrays); the plan issue
  // read stays on the `bsc` bridge (a JSON string). Route by command: `logs_*` → empty log; `bsc` →
  // `plan list … --full` (all issues complete). The done read is event-driven now (#3638) but
  // `useLogStream` still does an initial read on mount, so these fire the same way under `renderHook`.
  vi.mocked(invoke).mockImplementation((cmd: string, _payload?: unknown) => {
    if (cmd === "logs_done_panes") return Promise.resolve([]);     // no self-reported-done panes
    if (cmd === "logs_pane_activity") return Promise.resolve([]);  // no activity rows
    if (cmd === "logs_tail") return Promise.resolve([]);           // coord log empty
    // THE VERDICT COMES FROM RUST (`the-worker-end-is-classified-where-the-pty-exits`). This used to
    // mock `bsc plan list` and let `classifyWorkerEnd` run in the renderer; both plan.db and the
    // coord fold now live behind ONE command, so the mock supplies the ANSWER rather than its inputs.
    // Index-aligned to the `streamIds` asked about — the tests below assert that alignment.
    if (cmd === "worker_end_verdicts") return Promise.resolve(
      ((_payload as { streamIds?: string[] })?.streamIds ?? []).map(() => DONE_VERDICT),
    );
    return Promise.resolve(undefined);
  });
  useAppStore.setState({
    endedPanes: {}, paneStatus: {}, paneRoles: { [WORKER]: "worker", [DIRECTOR]: "director" },
    fleetPaneStreams: { [WORKER]: stream("api"), [DIRECTOR]: stream("director") },
    tabs: [{ id: "t", name: "build", layout: "2×1", state: "idle", runId: 0, projectKey: "demo", paneIds: [DIRECTOR, WORKER] }] as never,
    panePrProbes: {}, paneStream: {}, githubToken: "",
  });
});

describe("useWorkerAutoEnd (#920 / #1379)", () => {
  it("#3944: the idle sweep reads each project ONCE, not once per pane", async () => {
    // The sweep used to spawn `bsc plan list --stream <id>` inside the pane loop, serially, on every
    // change to any of THREE log streams — the bulk of 37 `bsc plan list`/min. Two worker panes on one
    // project must now produce ONE project-wide read, not two per-stream reads.
    useAppStore.setState({
      paneRoles: { [WORKER]: "worker", "demo:web": "worker", [DIRECTOR]: "director" },
      fleetPaneStreams: { [WORKER]: stream("api"), "demo:web": stream("web"), [DIRECTOR]: stream("director") },
      tabs: [{ id: "t", name: "build", layout: "2×1", state: "idle", runId: 0, projectKey: "demo", paneIds: [DIRECTOR, WORKER, "demo:web"] }] as never,
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(verdictCalls().length).toBeGreaterThan(0));

    // The invariant is unchanged and now holds one level down: ONE command per project per sweep,
    // carrying every stream at once, rather than one call per pane.
    const sweep = verdictCalls().filter((p) => p.projectKey === "demo" && p.streamIds.length > 1);
    expect(sweep.length).toBeGreaterThan(0);
    expect(sweep[0].streamIds).toEqual(expect.arrayContaining(["api", "web"]));
    // And no call may ask about a single stream during the sweep — that is the per-pane shape.
    expect(verdictCalls().filter((p) => p.streamIds.length === 1).length).toBeLessThanOrEqual(0);
  });

  // THE WIRING TESTS. The parity corpus in `crates/bsc-fleet` proves `classify_worker_end`; it says
  // nothing about whether this module CALLS it. Reverting the call site here must fail something, or
  // the migration is pinned only at the function.

  it("asks RUST for the verdict — it does not classify in the renderer", async () => {
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(handlers[`pty_exit_${WORKER}`]).toBeTypeOf("function"));
    handlers[`pty_exit_${WORKER}`]();
    await waitFor(() => expect(useAppStore.getState().endedPanes[WORKER]).toBeTruthy());

    // The command was called, with THIS pane's project and stream. A test that only asserted the pane
    // ended would pass with `classifyWorkerEnd` still running here.
    expect(invoke).toHaveBeenCalledWith("worker_end_verdicts", { projectKey: "demo", streamIds: ["api"] });
    // And nothing fetched the classifier's raw INPUTS — issues are no longer read in the renderer.
    expect(invoke).not.toHaveBeenCalledWith(
      "bsc",
      expect.objectContaining({ args: expect.arrayContaining(["plan", "list"]) }),
    );
  });

  it("renders the verdict Rust decided, verbatim — it does not re-derive one", async () => {
    // A state and summary no local classifier would produce for these inputs. If any classification
    // survived here, the card would disagree with what Rust said.
    const ODD = { state: "blocked", summary: "rust said so — 7/9 blocked or failed" };
    vi.mocked(invoke).mockImplementation((cmd: string) => {
      if (cmd === "logs_done_panes" || cmd === "logs_pane_activity" || cmd === "logs_tail") return Promise.resolve([]);
      if (cmd === "worker_end_verdicts") return Promise.resolve([ODD]);
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(handlers[`pty_exit_${WORKER}`]).toBeTypeOf("function"));
    handlers[`pty_exit_${WORKER}`]();

    await waitFor(() => expect(useAppStore.getState().endedPanes[WORKER]).toBeTruthy());
    expect(useAppStore.getState().endedPanes[WORKER]).toMatchObject({
      state: ODD.state, summary: ODD.summary, streamId: "api",
    });
  });

  it("BAILS when Rust reports no plan store — an absent store never ends a pane", async () => {
    // `null` at a position means there is no plan.db to read. That is not a verdict, and ending a pane
    // on it would close a worker's card on the strength of a missing file. Distinct from an EMPTY
    // owned set, which Rust answers with a real `needs-attention` verdict.
    vi.mocked(invoke).mockImplementation((cmd: string) => {
      if (cmd === "logs_done_panes" || cmd === "logs_pane_activity" || cmd === "logs_tail") return Promise.resolve([]);
      if (cmd === "worker_end_verdicts") return Promise.resolve([null]);
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(handlers[`pty_exit_${WORKER}`]).toBeTypeOf("function"));
    handlers[`pty_exit_${WORKER}`]();
    await new Promise((r) => setTimeout(r, 0));

    expect(useAppStore.getState().endedPanes[WORKER]).toBeUndefined();
  });

  it("subscribes to pty_exit for worker panes only (not the director)", async () => {
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(handlers[`pty_exit_${WORKER}`]).toBeTypeOf("function"));
    expect(handlers[`pty_exit_${DIRECTOR}`]).toBeUndefined(); // director is not auto-ended
  });

  it("marks a worker done when all owned issues are complete on PTY exit", async () => {
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(handlers[`pty_exit_${WORKER}`]).toBeTypeOf("function"));

    handlers[`pty_exit_${WORKER}`]();

    await waitFor(() => expect(useAppStore.getState().endedPanes[WORKER]).toBeTruthy());
    expect(useAppStore.getState().endedPanes[WORKER]).toMatchObject({ state: "done", streamId: "api" });
    // THE WIRING, not the helper. The verdict must come from Rust, asked about THIS pane's project and
    // stream — asserting only that the pane ended would pass with the classifier still in the renderer.
    // The project key resolves from the tab's paneIds (the #1176/#1379 regression guard).
    expect(invoke).toHaveBeenCalledWith("worker_end_verdicts", { projectKey: "demo", streamIds: ["api"] });
    // And the summary is Rust's own words, not a sentence rebuilt here.
    expect(useAppStore.getState().endedPanes[WORKER].summary).toBe(DONE_VERDICT.summary);
  });

  it("flags needs-attention when an owned issue is still open", async () => {
    vi.mocked(invoke).mockImplementation((cmd: string, _payload?: unknown) => {
      if (cmd === "logs_done_panes" || cmd === "logs_pane_activity" || cmd === "logs_tail") return Promise.resolve([]);
      if (cmd === "worker_end_verdicts") return Promise.resolve([OPEN_VERDICT]);
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(handlers[`pty_exit_${WORKER}`]).toBeTypeOf("function"));

    handlers[`pty_exit_${WORKER}`]();

    await waitFor(() => expect(useAppStore.getState().endedPanes[WORKER]?.state).toBe("needs-attention"));
  });

  it("self-closes a worker that reported done via bsc-done — ends it AND kills the PTY (#1379)", async () => {
    vi.mocked(invoke).mockImplementation((cmd: string, _payload?: unknown) => {
      if (cmd === "logs_done_panes") return Promise.resolve([WORKER]);
      if (cmd === "logs_pane_activity" || cmd === "logs_tail") return Promise.resolve([]); // coord/activity empty
      if (cmd === "worker_end_verdicts") return Promise.resolve(
        ((_payload as { streamIds?: string[] })?.streamIds ?? []).map(() => DONE_VERDICT),
      );
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));

    // The done reader (event-driven, but read once on mount) reaps the self-reported worker.
    await waitFor(() => expect(useAppStore.getState().endedPanes[WORKER]).toBeTruthy());
    expect(useAppStore.getState().endedPanes[WORKER]).toMatchObject({ state: "done", streamId: "api" });
    expect(invoke).toHaveBeenCalledWith("pty_kill", { paneId: WORKER }); // the live shell is actually killed
  });

  it("does nothing when the project key can't be resolved (no paneIds → no DB query)", async () => {
    // A tab with no paneIds can't map the pane to a project — evaluateExit must bail (no #1176 fallback).
    useAppStore.setState({ tabs: [{ id: "t", name: "build", layout: "2×1", state: "idle", runId: 0 }] as never });
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(handlers[`pty_exit_${WORKER}`]).toBeTypeOf("function"));

    handlers[`pty_exit_${WORKER}`]();
    await new Promise((r) => setTimeout(r, 0));

    expect(useAppStore.getState().endedPanes[WORKER]).toBeUndefined();
    // No verdict is even ASKED FOR — the project-agnostic log reads (`logs_*`) still fire, so narrow
    // the assertion to the one command that would have needed a project key.
    expect(verdictCalls()).toEqual([]);
  });

  it("REAPS an idle, complete, question-free worker without typing at it (#session-stop-is-honoured)", async () => {
    vi.mocked(invoke).mockImplementation((cmd: string, _payload?: unknown) => {
      // Idle since epoch 1ms ⇒ idleMs is huge, well past the close-nudge window.
      if (cmd === "logs_pane_activity") return Promise.resolve([{ pane: WORKER, state: "idle", at: 1 }]);
      if (cmd === "logs_done_panes" || cmd === "logs_tail") return Promise.resolve([]); // done + coord (no ask/wait) empty
      if (cmd === "worker_end_verdicts") return Promise.resolve(
        ((_payload as { streamIds?: string[] })?.streamIds ?? []).map(() => DONE_VERDICT),
      );
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));

    // The pane reaches its resting state from plan.db — the same verdict source as every other path.
    await waitFor(() => expect(useAppStore.getState().endedPanes[WORKER]).toBeTruthy());
    expect(useAppStore.getState().endedPanes[WORKER]).toMatchObject({ state: "done", streamId: "api" });

    // THE INVARIANT: nothing was typed into the worker. This path used to `pty_write` a "run bsc-done"
    // nudge, which never fired while `bsc-defer` refused a worker's Stop — removing that hook would
    // have switched it on and re-prompted every session the moment it finished.
    const wroteToWorker = vi.mocked(invoke).mock.calls.some(
      ([c, a]) => c === "pty_write" && (a as { paneId: string }).paneId === WORKER,
    );
    expect(wroteToWorker, "a finished worker must not be typed at").toBe(false);
    // And its shell is left alive, so resuming it stays a click the USER makes.
    expect(invoke).not.toHaveBeenCalledWith("pty_kill", { paneId: WORKER });
  });

  it("does NOT type at the director when a worker finishes done (#the-fleet-went-pull-but-nobody-told-the-director-to-pull)", async () => {
    vi.mocked(invoke).mockImplementation((cmd: string, _payload?: unknown) => {
      if (cmd === "logs_done_panes") return Promise.resolve([WORKER]); // worker self-reported done
      if (cmd === "logs_pane_activity" || cmd === "logs_tail") return Promise.resolve([]);
      if (cmd === "worker_end_verdicts") return Promise.resolve(
        ((_payload as { streamIds?: string[] })?.streamIds ?? []).map(() => DONE_VERDICT),
      );
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));

    await waitFor(() => expect(useAppStore.getState().endedPanes[WORKER]?.state).toBe("done"));
    // THIS ASSERTION IS INVERTED FROM WHAT IT WAS. It used to require a close-the-open-issues prompt
    // typed into the director's pane. That write ended with a CR, which submits — opening a Claude
    // turn in a session nobody clicked, through the one path the injector ratchet could not see.
    //
    // It also instructed `gh issue close`, and the GitHub-ownership clause was removed from
    // director-protocol.md under local-first (its own tests assert the absence). So the nudge asked
    // for work the director no longer claims. Nothing replaces it.
    const dirMsg = vi.mocked(invoke).mock.calls.find(([c, a]) => c === "pty_write" && (a as { paneId: string }).paneId === DIRECTOR);
    expect(dirMsg, "the app must not type into the director's session").toBeUndefined();
    // The verdict itself is unchanged — the pane still ends `done`, which the waitFor above pins.
  });

  it("does NOT resurface a lost question INTO the director — the queue carries it instead", async () => {
    vi.mocked(invoke).mockImplementation((cmd: string, _payload?: unknown) => {
      if (cmd === "logs_pane_activity") return Promise.resolve([{ pane: WORKER, state: "idle", at: 1 }]); // idle ages ago
      // An outstanding bsc-ask for the worker, never answered (the coord read is `logs_tail` stream=coord).
      if (cmd === "logs_tail") return Promise.resolve([`2020-01-01T00:00:00Z\t${WORKER}\task\tWhich pagination?\t`]);
      if (cmd === "logs_done_panes") return Promise.resolve([]);
      if (cmd === "worker_end_verdicts") return Promise.resolve([OPEN_VERDICT]);
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));

    // Let the sweep run — `logs_done_panes` resolving is the signal a tick completed.
    await waitFor(() => expect(verdictCalls().length).toBeGreaterThan(0));

    // INVERTED, same reason as above: the resurface used to type the worker's question into the
    // director. It does not any more. The information is NOT lost — `bsc logs waiting` lists every
    // unanswered ask oldest-first, and the director's protocol now tells it to sweep that queue on
    // every turn. The pull is strictly better: it shows EVERY stale ask on every sweep, where this
    // fired once per pane per idle period and then went quiet.
    expect(
      vi.mocked(invoke).mock.calls.some(([c, a]) => c === "pty_write" && (a as { paneId: string }).paneId === DIRECTOR),
      "the app must not type into the director's session",
    ).toBe(false);
    expect(useAppStore.getState().endedPanes[WORKER]).toBeUndefined();           // never closes a waiting worker
  });
});

// #180: the PR-probe backoff (an-unmerged-ended-pane-is-polled-against-github-forever) must survive
// a restart. It used to live only in a `useRef` inside this hook, private to whichever component
// instance created it — a fresh mount (exactly what a restart does) started that ref back at an empty
// Map, so a pane already `nextAt: null` (settled — merged, or given up on) was re-asked about from
// attempt zero. `panePrProbes` moves the schedule onto the store, persisted alongside `endedPanes`,
// so a fresh hook instance reads the SAME schedule a prior instance left behind.
describe("PR-probe schedule (#180)", () => {
  it("records the poll's own plan on the STORE, and tears down once GitHub reports the branch merged", async () => {
    useAppStore.setState({
      githubToken: "tok",
      endedPanes: { [WORKER]: { state: "done", streamId: "api", summary: "1/1 complete", at: 1 } },
      paneStream: { [WORKER]: { repo: "me/app", branch: "api" } },
    });
    vi.mocked(invoke).mockImplementation((cmd: string) => {
      if (cmd === "logs_done_panes" || cmd === "logs_pane_activity" || cmd === "logs_tail") return Promise.resolve([]);
      if (cmd === "github_request") return Promise.resolve([{ merged_at: "2026-01-01T00:00:00Z" }]);
      return Promise.resolve(undefined);
    });
    renderHook(() => useWorkerAutoEnd(paneIdFor));

    await waitFor(() => expect(invoke).toHaveBeenCalledWith(
      "teardown_worktree", { projectKey: "demo", repo: "me/app", agentId: "api" },
    ));
    // `nextAt: null` is `planNextProbe`'s terminal "never ask again" plan for a merged verdict — this
    // is what the OLD `useRef` held privately; it must now be readable from the store.
    expect(useAppStore.getState().panePrProbes[WORKER]).toMatchObject({ nextAt: null });
  });

  it("a settled pane's schedule survives a fresh hook mount — the restart regression", async () => {
    // Seed the store exactly as a restart would rehydrate it: `endedPanes` AND `panePrProbes` both
    // already say this pane is settled (its PR merged, in an EARLIER session).
    useAppStore.setState({
      githubToken: "tok",
      endedPanes: { [WORKER]: { state: "done", streamId: "api", summary: "1/1 complete", at: 1 } },
      paneStream: { [WORKER]: { repo: "me/app", branch: "api" } },
      panePrProbes: { [WORKER]: { attempts: 1, nextAt: null } },
    });
    const calls: string[] = [];
    vi.mocked(invoke).mockImplementation((cmd: string) => {
      calls.push(cmd);
      if (cmd === "logs_done_panes" || cmd === "logs_pane_activity" || cmd === "logs_tail") return Promise.resolve([]);
      return Promise.resolve(undefined);
    });

    const { unmount } = renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(calls.length).toBeGreaterThan(0));
    unmount();

    // A FRESH hook instance — the same thing a restart does. Before #180 this held its own empty
    // `useRef` and re-asked GitHub about the (already-settled) pane; it must not.
    calls.length = 0;
    renderHook(() => useWorkerAutoEnd(paneIdFor));
    await waitFor(() => expect(calls.length).toBeGreaterThan(0)); // the log/coord reads still fire on mount
    expect(calls).not.toContain("github_request"); // but the settled pane is never re-asked about
  });
});

implementations.code:
// Data-defined component variants (#2569 rung 3) — the RENDER path for variants an LLM authors with
// `bsc ui component <c> define-variant`. Each stored definition is a token bundle for a
// `<component>:<variant>`; this compiles them into ONE managed `<style>` of `.<component>.<variant>`
// rules that set the component's semantic tokens, so an authored variant restyles the real component
// with zero component changes (the primitive already adds the variant string as a class — a new variant
// is pure DATA). Applied globally on boot + re-applied on a `ui-touch` "variant" write (live, #2525).
//
// DEFENSE IN DEPTH: the CLI already sanitises the name + grammar-checks each value (crates/bsc-ui), but
// this compiles LLM-authored data into live CSS, so we re-validate here — a variant/component name must
// be a safe CSS identifier and a value must not contain a declaration-ending / injection sequence.
// Anything failing is skipped, never emitted.

/** One stored variant definition — the shape `bsc ui variants` returns. */
export interface VariantDef {
  /** `<component>:<variant>` (the store id). */
  id: string;
  component: string;
  variant: string;
  /** Short token key (e.g. `bg`) → value (a `var(--x)` / colour / dimension). */
  tokens: Record<string, string>;
}

const STYLE_ID = "bsc-ui-variants";
/** A safe CSS identifier for a class selector segment (mirrors the CLI's sanitize_variant_name). */
const SAFE_IDENT = /^[a-z][a-z0-9-]*$/;
/** A value that could END the declaration or INJECT CSS — refused even though the CLI already guards. */
const UNSAFE_VALUE = /[;{}<>\\]|url\(|expression\(|@import|\/\*/i;

/**
 * Compile variant definitions into CSS: one `.<component>.<variant> { --<component>-<key>: <value>; … }`
 * rule per definition. Pure + guarded — skips any definition whose component/variant name isn't a safe
 * identifier and any token whose value looks like an injection. Empty string when nothing is renderable.
 */
export function compileVariantsCss(defs: VariantDef[]): string {
  const rules: string[] = [];
  for (const d of defs) {
    if (!d || !SAFE_IDENT.test(d.component ?? "") || !SAFE_IDENT.test(d.variant ?? "")) continue;
    const decls = Object.entries(d.tokens ?? {})
      .filter(([key, value]) => SAFE_IDENT.test(key) && typeof value === "string" && !UNSAFE_VALUE.test(value))
      .map(([key, value]) => `  --${d.component}-${key}: ${value};`);
    if (decls.length) rules.push(`.${d.component}.${d.variant} {\n${decls.join("\n")}\n}`);
  }
  return rules.join("\n\n");
}

/**
 * Inject / update / clear the managed `<style id="bsc-ui-variants">` holding the compiled variant CSS.
 * Removing the last variant removes the element. `doc` is param'd for tests. Mirrors the accent/theme
 * root-apply — one global stylesheet the whole app follows.
 */
export function applyVariantsToRoot(defs: VariantDef[], doc: Document = document): void {
  const css = compileVariantsCss(defs);
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!css) {
    el?.remove();
    return;
  }
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  el.textContent = css;
}

