import { describe, it, expect, vi, beforeEach } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { loadDoneAudit } from "@/shared/lib/fleet/workerAudit";

beforeEach(() => vi.clearAllMocks());

describe("loadDoneAudit (#920)", () => {
  it("returns an empty snapshot (no invokes) when there's no cwd", async () => {
    const a = await loadDoneAudit("", "me/app");
    expect(a).toEqual({ branch: "", commits: [], changedFiles: [], pr: null, transcriptPath: null });
    expect(invoke).not.toHaveBeenCalled();
  });

  it("assembles branch + commits + changed files + PR + transcript", async () => {
    vi.mocked(invoke).mockImplementation((cmd: string) => {
      switch (cmd) {
        case "read_worktree_branch": return Promise.resolve("123-feature");
        case "read_worktree_commits": return Promise.resolve([{ hash: "abc1234", subject: "do it", author: "me", date: "2026-06-23" }]);
        case "read_worktree_changes": return Promise.resolve(["src/a.ts"]);
        case "claude_transcript_path": return Promise.resolve("/home/me/.claude/projects/x/s.jsonl");
        case "find_branch_pr": return Promise.resolve({ number: 42, url: "https://gh/pr/42", state: "MERGED", merged: true });
        default: return Promise.resolve(undefined);
      }
    });
    const a = await loadDoneAudit("/wt/123-feature", "me/app");
    expect(a.branch).toBe("123-feature");
    expect(a.commits[0].hash).toBe("abc1234");
    expect(a.changedFiles).toEqual(["src/a.ts"]);
    expect(a.transcriptPath).toMatch(/\.jsonl$/);
    expect(a.pr).toMatchObject({ number: 42, merged: true });
    expect(invoke).toHaveBeenCalledWith("find_branch_pr", { repo: "me/app", branch: "123-feature" });
  });

  it("skips the PR lookup when the branch can't be read", async () => {
    vi.mocked(invoke).mockImplementation((cmd: string) =>
      Promise.resolve(cmd === "read_worktree_branch" ? "" : cmd === "claude_transcript_path" ? null : []));
    const a = await loadDoneAudit("/wt/x", "me/app");
    expect(a.pr).toBeNull();
    expect(invoke).not.toHaveBeenCalledWith("find_branch_pr", expect.anything());
  });

  it("degrades each failing command to an empty value (never rejects)", async () => {
    vi.mocked(invoke).mockRejectedValue(new Error("git gone"));
    const a = await loadDoneAudit("/wt/x", "me/app");
    expect(a).toEqual({ branch: "", commits: [], changedFiles: [], pr: null, transcriptPath: null });
  });
});

import { describe, it, expect } from "vitest";
import { decideWorkerAutoEnd, DEFAULT_AUTO_END_THRESHOLDS, type AutoEndSignals } from "@/shared/lib/fleet/workerAutoEnd";
import type { WorkerEndVerdict } from "@/shared/lib/fleet/workerEnd";

const T = DEFAULT_AUTO_END_THRESHOLDS;
const done: WorkerEndVerdict = { state: "done", summary: "2/2 complete" };
const needsAttn: WorkerEndVerdict = { state: "needs-attention", summary: "1/2 still open" };
const blocked: WorkerEndVerdict = { state: "blocked", summary: "1/2 blocked" };

const sig = (o: Partial<AutoEndSignals>): AutoEndSignals => ({
  turnOpen: false, idleMs: 0, hasOutstandingQuestion: false, verdict: done, ...o,
});

describe("decideWorkerAutoEnd", () => {
  it("never acts while the turn is open (working, even if silent)", () => {
    expect(decideWorkerAutoEnd(sig({ turnOpen: true, idleMs: 10 * T.lostQuestionMs }), T)).toBe("none");
  });

  describe("no outstanding question → close-nudge when complete", () => {
    it("nudges a complete worker to close once idle past the (shorter) close window", () => {
      expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs, verdict: done }), T)).toBe("close-nudge");
    });
    it("waits until the close window elapses", () => {
      expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs - 1, verdict: done }), T)).toBe("none");
    });
    it("does NOT nudge a worker that stopped early (needs-attention) or is blocked", () => {
      expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs, verdict: needsAttn }), T)).toBe("none");
      expect(decideWorkerAutoEnd(sig({ idleMs: 10 * T.closeNudgeMs, verdict: blocked }), T)).toBe("none");
    });
  });

  describe("outstanding question → resurface only after the (longer) lost-question wait", () => {
    it("resurfaces once idle past the lost-question window", () => {
      expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.lostQuestionMs }), T))
        .toBe("resurface-question");
    });
    it("does nothing while the director still has time to answer", () => {
      expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.lostQuestionMs - 1 }), T))
        .toBe("none");
    });
    it("never closes a worker that's waiting, even if its issues read complete", () => {
      // Past the SHORTER close window but with a question outstanding → resurface path only, never close.
      expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.closeNudgeMs, verdict: done }), T))
        .toBe("none");
    });
  });

  it("uses a longer wait for lost questions than for the close-nudge", () => {
    expect(T.lostQuestionMs).toBeGreaterThan(T.closeNudgeMs);
  });
});
describe("the pane the user is IN is never ended under them", () => {
  // "Idle" measures the AGENT being between turns. Reading a worker's last message and composing a
  // reply is exactly that state, so a focused pane could be ended mid-sentence. The idle reaper has
  // always refused to touch the focused pane; this path never learned the rule.
  it("does not close a focused worker, however long it has rested", () => {
    expect(decideWorkerAutoEnd(sig({ focused: true, idleMs: 60 * 60_000, verdict: done }), T)).toBe("none");
  });

  it("does not resurface a focused worker's question either — that moves it somewhere else", () => {
    expect(
      decideWorkerAutoEnd(sig({ focused: true, hasOutstandingQuestion: true, idleMs: 60 * 60_000 }), T),
    ).toBe("none");
  });

  it("still closes the SAME worker once focus moves away", () => {
    expect(decideWorkerAutoEnd(sig({ focused: false, idleMs: T.closeNudgeMs, verdict: done }), T))
      .toBe("close-nudge");
  });

  it("treats an absent flag as not focused, so existing callers are unchanged", () => {
    expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs, verdict: done }), T)).toBe("close-nudge");
  });
});

describe("the close window bounds an UNWATCHED worker, and focus does the rest", () => {
  // A worker was reported ending while the user was still typing a reply. The window was briefly
  // raised, which treated the timer as the protection — it never was. No window is long enough if the
  // pane you are using can be ended at all, and every window is long enough if it cannot. The focus
  // guard makes a short window safe, so the timer is free to answer its real question: how long an
  // unwatched, finished worker should sit in the grid.
  it("a SHORT window is safe precisely because a focused pane is exempt", () => {
    const anHour = 60 * 60_000;
    expect(decideWorkerAutoEnd(sig({ focused: true, idleMs: anHour, verdict: done }), T)).toBe("none");
    expect(decideWorkerAutoEnd(sig({ focused: false, idleMs: T.closeNudgeMs, verdict: done }), T))
      .toBe("close-nudge");
  });

  it("keeps the close window strictly shorter than the lost-question window", () => {
    // Load-bearing: a waiting worker meets the close window FIRST and must answer `none` there.
    expect(T.lostQuestionMs).toBeGreaterThan(T.closeNudgeMs);
    expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.closeNudgeMs, verdict: done }), T))
      .toBe("none");
  });
});

// The worker auto-end decision, captured from the LIVE TypeScript so the Rust port can be proved equal.
//
// Same class as the idle reaper, which was moved out of a React hook into `console::pty::reap`
// because a dead webview meant nothing bounded the session count. This is an idle-time decision
// still in the renderer: it stops happening when the renderer dies, silently, exactly when a fleet
// is left running unattended.
//
// Regenerate deliberately:
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/fleet/workerAutoEnd.fixtures.gen.test.ts
//
// A regeneration that changes the file is a CHANGE OF BEHAVIOUR. Read the diff before committing it.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  decideWorkerAutoEnd,
  DEFAULT_AUTO_END_THRESHOLDS,
  type AutoEndSignals,
  type AutoEndThresholds,
} from "@/shared/lib/fleet/workerAutoEnd";

const FIXTURE = join(process.cwd(), "src/shared/lib/fleet/workerAutoEnd.fixtures.json");
const T: AutoEndThresholds = DEFAULT_AUTO_END_THRESHOLDS;

/** The verdict enters as a VALUE — `worker-end.ts`'s classifier is out of scope (coordination). */
const verdict = (state: "done" | "needs-attention" | "blocked") => ({ state, summary: `${state} summary` });

const sig = (o: Partial<AutoEndSignals>): AutoEndSignals => ({
  turnOpen: false,
  idleMs: 0,
  hasOutstandingQuestion: false,
  verdict: verdict("done"),
  ...o,
});

interface Case { name: string; signals: AutoEndSignals; thresholds: AutoEndThresholds }

/** Each case names the branch it pins. Both sides of every threshold, and every verdict state. */
const CASES: Case[] = [
  { name: "turn still open — never act, however idle", signals: sig({ turnOpen: true, idleMs: 10_000_000 }), thresholds: T },
  { name: "focused — never act, however idle", signals: sig({ focused: true, idleMs: 10_000_000 }), thresholds: T },
  { name: "focused outranks an outstanding question", signals: sig({ focused: true, hasOutstandingQuestion: true, idleMs: 10_000_000 }), thresholds: T },
  { name: "turnOpen outranks focused being false", signals: sig({ turnOpen: true, focused: false, hasOutstandingQuestion: true, idleMs: 10_000_000 }), thresholds: T },
  { name: "question, just under lostQuestionMs", signals: sig({ hasOutstandingQuestion: true, idleMs: T.lostQuestionMs - 1 }), thresholds: T },
  { name: "question, exactly at lostQuestionMs — resurface", signals: sig({ hasOutstandingQuestion: true, idleMs: T.lostQuestionMs }), thresholds: T },
  { name: "question, well past — resurface", signals: sig({ hasOutstandingQuestion: true, idleMs: T.lostQuestionMs * 3 }), thresholds: T },
  { name: "a question outranks a done verdict past closeNudgeMs", signals: sig({ hasOutstandingQuestion: true, idleMs: T.closeNudgeMs, verdict: verdict("done") }), thresholds: T },
  { name: "done, just under closeNudgeMs", signals: sig({ idleMs: T.closeNudgeMs - 1 }), thresholds: T },
  { name: "done, exactly at closeNudgeMs — nudge", signals: sig({ idleMs: T.closeNudgeMs }), thresholds: T },
  { name: "needs-attention past closeNudgeMs — no nudge", signals: sig({ idleMs: T.closeNudgeMs * 2, verdict: verdict("needs-attention") }), thresholds: T },
  { name: "blocked past closeNudgeMs — no nudge", signals: sig({ idleMs: T.closeNudgeMs * 2, verdict: verdict("blocked") }), thresholds: T },
  { name: "idle zero, done — nothing yet", signals: sig({ idleMs: 0 }), thresholds: T },
  { name: "custom thresholds are honoured, not the packaged ones", signals: sig({ idleMs: 5 }), thresholds: { closeNudgeMs: 5, lostQuestionMs: 10 } },
];

function build() {
  return {
    note: "GENERATED from the live TypeScript — see workerAutoEnd.fixtures.gen.test.ts",
    defaults: DEFAULT_AUTO_END_THRESHOLDS,
    cases: CASES.map((c) => ({ ...c, action: decideWorkerAutoEnd(c.signals, c.thresholds) })),
  };
}

describe("the worker auto-end decision is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const text = JSON.stringify(build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("reaches every action, so a port cannot pass by always returning none", () => {
    const seen = new Set(build().cases.map((c) => c.action));
    expect(seen).toEqual(new Set(["none", "close-nudge", "resurface-question"]));
  });
});

implementations.code:
// Heuristic worker auto-end decision (#1379). The authoritative `pty_exit` trigger (#920) is dead
// for stable-identity workers (#1176) and likely never fires anyway (claude returns to the bash
// prompt without the SHELL exiting). So drive auto-end heuristically off IDLE TIME, branched on
// whether the worker has an outstanding question — Claude-driven, not foolproof, by design.
//
// This is the pure brain: (idle state + outstanding-ask? + owned-issue completeness + thresholds)
// → one action. The side effects (inject the close-nudge, resurface the question, end the pane)
// live in the hook/store; keeping the decision pure makes every branch unit-testable.

import type { WorkerEndVerdict } from "@/shared/lib/fleet/workerEnd";

/** What to do for an at-rest worker this tick. */
export type AutoEndAction =
  | "none"               // still working, or not idle long enough — do nothing
  | "close-nudge"        // idle + no question + work complete → nudge it to close itself
  | "resurface-question"; // idle past the lost-question wait with an unanswered ask → resurface it

export interface AutoEndSignals {
  /** Turn still open per the #1184 activity signal — the worker is actively working (never act). */
  turnOpen: boolean;
  /** How long the worker has been at rest, ms (now − last activity). */
  idleMs: number;
  /** An unanswered `bsc-ask` is outstanding for this worker (from the coordination log). */
  hasOutstandingQuestion: boolean;
  /** The owned-issue completeness verdict (classifyWorkerEnd) — only `done` warrants a close-nudge. */
  verdict: WorkerEndVerdict;
  /** The pane the user is looking at right now. Never auto-ended, however idle it reads.
   *
   *  "Idle" here means the AGENT is not mid-turn — it says nothing about the human. Reading a
   *  worker's output and composing a reply is exactly the state this measures as idle, so the pane
   *  could be ended out from under someone mid-sentence. The idle reaper has always refused to touch
   *  the focused pane ("the user is watching it"); this path never learned the same rule. */
  focused?: boolean;
}

export interface AutoEndThresholds {
  /** Idle before nudging a question-free, complete worker to close — SHORTER. */
  closeNudgeMs: number;
  /** Idle before treating an unanswered question as lost and resurfacing it — LONGER. */
  lostQuestionMs: number;
}

/** Defaults: a question-free worker is nudged to close after 1 min idle; an unanswered question is
 *  given 5 min before it's treated as lost. Tunable; the longer window gives the director time. */
export const DEFAULT_AUTO_END_THRESHOLDS: AutoEndThresholds = {
  // WAS 60 SECONDS. That number was chosen when this decision only NUDGED a worker to close itself —
  // a prompt it could decline. It now ENDS the pane outright (#session-stop-is-honoured removed the
  // nudge), so the same value stopped meaning "ask" and started meaning "act" — against a clock that
  // measures the AGENT being between turns, not the human being done. A minute is not long enough to
  // read a worker's last message and type a reply, which is exactly what was reported.
  //
  // ONE MINUTE, and that is fine BECAUSE OF THE FOCUS GUARD, not despite it.
  //
  // This was briefly raised to three minutes when a worker was reported ending while the user was
  // still typing a reply. That treated the timer as the protection, which it never was: no window is
  // long enough if the pane you are using can be ended at all, and every window is long enough if it
  // cannot. `decideWorkerAutoEnd` now refuses outright while the pane is focused, so the timer is
  // back to answering the question it is actually for — how long an UNWATCHED, finished worker should
  // sit in the grid — and a minute is a good answer to that.
  //
  // It must stay STRICTLY SHORTER than `lostQuestionMs`, which is load-bearing rather than
  // decorative: a worker with an outstanding question meets the close window first and must answer
  // `none` there. Setting them equal sends it down the resurface path the moment it is idle enough to
  // close — the opposite of "never close a worker that's waiting" — and two tests caught exactly that.
  closeNudgeMs: 60_000,
  lostQuestionMs: 300_000,
};

/**
 * Decide what to do for an at-rest worker.
 *
 * - Turn still open → `none` (it's working, even if silent — never act).
 * - Outstanding question → only `resurface-question` once idle ≥ the LONGER `lostQuestionMs`
 *   (give the director time to answer); otherwise `none`. Never close a worker that's waiting.
 * - No question → `close-nudge` once idle ≥ the SHORTER `closeNudgeMs` AND the owned work is
 *   genuinely complete (`verdict.state === "done"`). A `needs-attention`/`blocked` worker is NOT
 *   nudged to close — that's the director's call.
 */
export function decideWorkerAutoEnd(s: AutoEndSignals, t: AutoEndThresholds): AutoEndAction {
  if (s.turnOpen) return "none";
  // The user is IN this pane. Ending it — or resurfacing its question elsewhere — is a change made to
  // the thing they are currently using.
  if (s.focused) return "none";
  if (s.hasOutstandingQuestion) {
    return s.idleMs >= t.lostQuestionMs ? "resurface-question" : "none";
  }
  if (s.idleMs >= t.closeNudgeMs && s.verdict.state === "done") return "close-nudge";
  return "none";
}

// The modal shell used by the per-agent WorkerDetail page (#499) — a titled,
// dismissable card floated over a scrim with an optional footer action row.
import { ModalScrim } from "@/shared/ui/overlay/ModalScrim";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { IconButton } from "@/shared/ui/controls/IconButton";

export function Modal({ title, children, onClose, footer }: {
  title: string; children: React.ReactNode; onClose: () => void; footer?: React.ReactNode;
}) {
  return (
    <ModalScrim onDismiss={onClose}>
      {/* The CARD is the dialog, not the scrim behind it — `aria-modal` is what marks the covered page
          inert to a screen reader. Named by its own title, which is already on screen. */}
      <Box role="dialog" aria-modal="true" aria-label={title} bg="var(--bg-panel)" border radius="lg" style={{ width: 440, maxWidth: "90vw", boxShadow: "0 12px 40px rgba(0,0,0,0.5)" }}>
        <Row style={{ padding: "12px 16px", borderBottom: "1px solid var(--border-soft)" }}>
          <Text as="h3" style={{ margin: 0 }}>{title}</Text>
          <Spacer />
          <IconButton aria-label="close" onClick={onClose} />
        </Row>
        <Box pad={16}>{children}</Box>
        {footer && <Row justify="end" align="stretch" gap={8} style={{ padding: "12px 16px", borderTop: "1px solid var(--border-soft)" }}>{footer}</Row>}
      </Box>
    </ModalScrim>
  );
}

