// The render-loop capture exists because vite forwards only the message and WebKitGTK has no
// inspector, so the component stack is otherwise unreachable. These pin the three things that make it
// useful rather than harmful: it MATCHES the loop, it is BOUNDED, and it cannot recurse.
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import {
  isRenderLoop,
  looksLikeComponentStack,
  captureFrom,
  formatCapture,
  installRenderLoopCapture,
  __resetForTest,
  MAX_CAPTURES,
  MAX_CAPTURE_CHARS,
} from "@/app/safety/renderLoopCapture";

const LOOP = "Maximum update depth exceeded. This can happen when a component calls setState…";
const STACK = "\n    at ConsolePane (http://127.0.0.1:1420/x.tsx:12:3)\n    at TerminalView";

describe("render-loop capture", () => {
  const original = console.error;
  beforeEach(() => {
    __resetForTest();
    console.error = original;
  });
  afterEach(() => {
    console.error = original;
  });

  it("matches the loop and nothing else", () => {
    expect(isRenderLoop([LOOP])).toBe(true);
    expect(isRenderLoop(["warning: something else"])).toBe(false);
    // React passes the message as one of several args, not always the first.
    expect(isRenderLoop([{}, LOOP, STACK])).toBe(true);
    expect(isRenderLoop([])).toBe(false);
    // A non-string arg must not throw the matcher.
    expect(isRenderLoop([null, undefined, 42])).toBe(false);
  });

  it("recognises a component stack by its frame shape, in either spelling", () => {
    expect(looksLikeComponentStack(STACK)).toBe(true);
    expect(looksLikeComponentStack("\n    in ConsolePane")).toBe(true); // React's older spelling
    expect(looksLikeComponentStack("just a message")).toBe(false);
    expect(looksLikeComponentStack(undefined)).toBe(false);
  });

  it("takes the LAST stack-shaped argument, which is the more specific one", () => {
    const earlier = "\n    at Root";
    const c = captureFrom([LOOP, earlier, STACK], "js");
    expect(c.componentStack).toBe(STACK);
    expect(c.message).toContain("Maximum update depth");
    expect(c.jsStack).toBe("js");
  });

  it("records the absence of a stack rather than inventing one", () => {
    const c = captureFrom([LOOP], "");
    expect(c.componentStack).toBe("");
    expect(formatCapture(c, 1)).toContain("(none in args)");
    expect(formatCapture(c, 1)).toContain("(unavailable)");
  });

  /// THE BOUND. A loop fires this thousands of times per second; writing all of them would flood the
  /// very log the evidence must survive in, on a thread that is already the bottleneck.
  it("captures at most MAX_CAPTURES times however often the loop fires", () => {
    const seen: string[] = [];
    console.error = vi.fn((...a: unknown[]) => {
      if (typeof a[0] === "string" && a[0].startsWith("[render-loop]")) seen.push(a[0]);
    }) as unknown as typeof console.error;
    installRenderLoopCapture();

    for (let i = 0; i < 500; i++) console.error(LOOP, STACK);

    // The capture goes straight to `invoke`, not to console, so assert on the counter's effect: the
    // patched function must stop doing work. Re-installing is also a no-op.
    installRenderLoopCapture();
    expect(seen.length).toBeLessThanOrEqual(MAX_CAPTURES);
  });

  /// It OBSERVES. A capture that swallowed the message would trade one blind spot for another.
  it("always calls the original console.error, first and unchanged", () => {
    const spy = vi.fn();
    console.error = spy as unknown as typeof console.error;
    installRenderLoopCapture();

    console.error(LOOP, STACK);
    expect(spy).toHaveBeenCalledWith(LOOP, STACK);

    console.error("an unrelated error", 1);
    expect(spy).toHaveBeenCalledWith("an unrelated error", 1);
    expect(spy).toHaveBeenCalledTimes(2);
  });

  it("truncates as a unit, and says that it did", () => {
    const huge = "\n    at C".repeat(5000);
    const out = formatCapture({ message: LOOP, componentStack: huge, jsStack: "x" }, 1);
    expect(out.length).toBeLessThanOrEqual(MAX_CAPTURE_CHARS + 16);
    expect(out).toContain("truncated");
  });

  it("installs once, so a second call cannot double-wrap the console", () => {
    const spy = vi.fn();
    console.error = spy as unknown as typeof console.error;
    installRenderLoopCapture();
    const afterFirst = console.error;
    installRenderLoopCapture();
    expect(console.error).toBe(afterFirst);

    // Double-wrapping would call the original twice per error.
    console.error("x");
    expect(spy).toHaveBeenCalledTimes(1);
  });

  /// THE FLAW THIS REPLACED. `log.error` queues behind `setTimeout(drain, 250)`, and a render loop
  /// pins the main thread so that timer never runs — the capture died with the renderer, which is the
  /// only case it exists for. It must reach `invoke` with NO timer in between.
  it("reaches the backend without waiting for a timer", () => {
    vi.useFakeTimers();                       // no timer is EVER advanced in this test
    try {
      console.error = vi.fn() as unknown as typeof console.error;
      installRenderLoopCapture();
      console.error(LOOP, STACK);

      // Sent already, with time frozen — a queued implementation would have sent nothing yet.
      expect(invoke).toHaveBeenCalledWith(
        "frontend_log",
        expect.objectContaining({ level: "error", scope: "render-loop" }),
      );
      const msg = (vi.mocked(invoke).mock.calls.at(-1)?.[1] as { message: string }).message;
      expect(msg).toContain("[render-loop] capture 1/3");
      expect(msg).toContain("ConsolePane");   // the component stack made it through
    } finally {
      vi.useRealTimers();
    }
  });

  /// A failed send must not break the page it is diagnosing.
  it("survives the backend being unreachable", () => {
    vi.mocked(invoke).mockRejectedValueOnce(new Error("no backend"));
    console.error = vi.fn() as unknown as typeof console.error;
    installRenderLoopCapture();
    expect(() => console.error(LOOP, STACK)).not.toThrow();
  });
});

implementations.code:
// The COMMAND-SURFACE node projection (`epic-command-surfaces-are-nodes`, slice 1) — turn the crate
// roster into Glance nodes and edges.
//
// The roster comes from `bsc surface crates --json`: every workspace member, whether it exposes verbs,
// the verbs it serves (joined from the one catalog), and its internal cargo dependencies. This module
// is the PURE projection of that into the graph vocabulary; fetching it is the caller's job.
//
// ONE NODE PER CRATE, INCLUDING THE ONES WITH NO VERBS. That is the 2026-09-01 decision and it is the
// whole reason the roster exists rather than just the catalog: the node's job is MAINTENANCE, and
// `bsc-util` exposes no verb while being the crate whose change reaches most of the workspace — so it
// is exactly the one that needs an owner. Whether a crate has verbs is a FACET on the node, never the
// criterion for having one.
import {
  surfaceNodeId,
  dependsOnEdgeId,
  verbNodeId,
  nounNodeId,
  verbOfEdgeId,
  type GRawNode,
  type GRawEdge,
  type GRole,
} from "@/features/glance/lib/glanceGraph";
import type { GlanceData } from "@/features/glance/lib/glanceData";

/** One row of the plan's SURFACES section (`bsc plan surface list --json`), projected into what this
 *  module draws.
 *
 *  IT USED TO BE `bsc surface crates --json`, read live on a poll. The roster comes from the PLAN now
 *  (`epic-the-lexicographer-defines-the-applications-language`): the live catalog is what the
 *  lexicographer SURVEYS, and the plan holds the roster it decided against. Drift between the two is
 *  information rather than a bug — a crate in the catalog with no plan row is one that arrived since
 *  the last survey, and it is legitimately not drawn until someone has looked at it.
 *
 *  `path` and `verbs` are GONE from this type rather than carried as nulls. They came from the
 *  catalog shape and nothing in this module ever read them: `surfaceGraph` needs the key, the edges
 *  and the one facet, and the verb list is read LIVE by the crate drill — deliberately, because a
 *  stale copy would have someone folding a noun on the strength of verbs that had already moved. */
export interface SurfaceRosterRow {
  /** The cargo PACKAGE name — the node key. Not the directory (`crates/data` is `bsc-data`) and not
   *  the lib target (`bsc-llm`'s is `llm`). */
  crate: string;
  /** Whether this crate serves any `bsc` verb. A FACET — a false here still gets a node. */
  surface: boolean;
  /** Its internal cargo dependencies, by package name, as surveyed. */
  dependsOn: string[];
}

/** The projected band: one node per crate, one edge per internal dependency. */
export interface SurfaceGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/** The three kinds of crate, by HOW YOU USE IT — the question a reader of this graph is asking. */
export type CrateKind = "surface" | "library" | "program";

/** Which accent each kind borrows. See {@link crateKind} for why these three and not others. */
export const CRATE_KIND_ROLE: Record<CrateKind, GRole> = {
  surface: "service", // something you CALL — `bsc <verb>`
  library: "infra",   // something others BUILD ON
  program: "client",  // something that RUNS on its own
};

/**
 * Classify one crate. Disjoint and exhaustive over the real roster: MEASURED 43 / 14 / 3 of 60.
 *
 * The axis is HOW THE CRATE IS USED, which is what a "kind" means here and what the graph is read for:
 *
 *  - `surface` — it answers `bsc <verb>`. The catalog says so, so this is a fact, not a heuristic.
 *  - `library` — no verb, but other crates depend on it. `bsc-util` is the extreme: no verb at all and
 *    44 dependents, which is exactly why the 2026-09-01 decision gave every crate a node.
 *  - `program` — no verb AND nothing depends on it: it is its own binary. `base-studio-code` (the app),
 *    `bsc-agent`, `bsc-hook`.
 *
 * FAN-IN IS THE DISCRIMINATOR between the last two, not a name pattern. `bsc-agent` and `bsc-hook` look
 * like libraries by name and are not; `channel` and `research` look like programs and are not. A name
 * heuristic would have got four of seventeen wrong, silently.
 */
export function crateKind(row: SurfaceRosterRow, fanIn: number): CrateKind {
  if (row.surface) return "surface";
  return fanIn > 0 ? "library" : "program";
}

/**
 * Project the crate roster into surface nodes + crate-dependency edges.
 *
 * `health` is `off` and `activity` is `idle` DELIBERATELY: a crate has no health signal yet. Marking
 * every crate `healthy` would assert something nobody measured, and this graph's whole point is that
 * the dot means something. Deriving real health (from `bsc errors`, or the gate) is a later
 * increment; until then the node says "no signal" rather than "fine".
 *
 * An edge to a crate that is NOT in the roster is DROPPED rather than drawn. A dangling edge is worse
 * than a missing one: the layout would carry a node id nothing renders, and the dependency count
 * shown on a node would include a target the user cannot click.
 */
export function surfaceGraph(roster: SurfaceRosterRow[]): SurfaceGraph {
  const known = new Set(roster.map((r) => r.crate));

  // How many OTHER crates build on each one — the signal that separates a library from a program.
  const fanIn = new Map<string, number>();
  for (const r of roster) {
    for (const dep of r.dependsOn) {
      if (dep !== r.crate && known.has(dep)) fanIn.set(dep, (fanIn.get(dep) ?? 0) + 1);
    }
  }

  const nodes: GRawNode[] = roster.map((r) => {
    const kind = crateKind(r, fanIn.get(r.crate) ?? 0);
    return {
      id: surfaceNodeId(r.crate),
      slug: r.crate,
      kind: "surface" as const,
      // The COLOUR channel. Not arbitrary: a library IS infrastructure others stand on, a surface IS a
      // service you call, and a program IS a client — the role vocabulary already means these things,
      // so a reader who knows the L1 legend is not learning a second code.
      role: CRATE_KIND_ROLE[kind],
      // The WORD channel, so the distinction survives colour-blindness, a greyscale screenshot and a
      // reader who has not memorised the legend. A colour alone is a cipher; a caption is a fact.
      roleLabel: kind,
      health: "off" as const,
      activity: "idle" as const,
    };
  });

  // TRANSITIVELY REDUCED — draw only the edges that are not already implied by a longer path.
  //
  // The full cargo graph is 230 edges over 60 crates and it made the drill LAG. Reachability is
  // identical either way: an edge A→C is dropped only when some A→B→…→C already exists, so nothing a
  // reader could follow is lost. MEASURED on the real roster: 230 → 123 edges (46% fewer), and the
  // hub collapse is the point — `bsc-util` went from 44 converging lines to 5, `bsc-cli-util` from
  // 46 to 19. Nearly every crate reaches `bsc-util` THROUGH `bsc-cli-util`, so 39 of those 44 lines
  // were restating a fact the graph already showed.
  //
  // A CAP was the alternative and is worse: dropping the Nth edge of a busy node hides a real
  // dependency and which one you lose depends on iteration order. A reduction is information-
  // preserving and deterministic. Safe because the graph is a DAG (cargo cannot express a cycle in
  // normal dependencies) — on a cyclic graph a transitive reduction is not unique.
  const adj = new Map<string, Set<string>>();
  for (const r of roster) {
    adj.set(r.crate, new Set(r.dependsOn.filter((d) => d !== r.crate && known.has(d))));
  }
  // Reachability per node, computed over a post-order so a node's successors are always done first.
  const reach = new Map<string, Set<string>>();
  const visiting = new Set<string>();
  const settle = (u: string): Set<string> => {
    const done = reach.get(u);
    if (done) return done;
    // `visiting` is belt-and-braces: the DAG is asserted by its own test, but a malformed roster must
    // not hang the cockpit. A back-edge simply contributes nothing rather than recursing forever.
    if (visiting.has(u)) return new Set();
    visiting.add(u);
    const acc = new Set<string>();
    for (const v of adj.get(u) ?? []) {
      acc.add(v);
      for (const w of settle(v)) acc.add(w);
    }
    visiting.delete(u);
    reach.set(u, acc);
    return acc;
  };
  for (const r of roster) settle(r.crate);

  const edges: GRawEdge[] = [];
  const seen = new Set<string>();
  for (const r of roster) {
    const deps = adj.get(r.crate) ?? new Set();
    for (const dep of deps) {
      // Implied by a sibling? Then the path already says it, and the line is noise.
      let implied = false;
      for (const other of deps) {
        if (other !== dep && reach.get(other)?.has(dep)) {
          implied = true;
          break;
        }
      }
      if (implied) continue;
      const id = dependsOnEdgeId(r.crate, dep);
      if (seen.has(id)) continue;
      seen.add(id);
      edges.push({ id, from: surfaceNodeId(r.crate), to: surfaceNodeId(dep), kind: "depends-on" });
    }
  }
  return { nodes, edges };
}

// `dependentCount` USED TO LIVE HERE. Rust owns it: `bsc surface drill` computes
// `"dependentCount": dependents.len()` (crates/bsc/src/main.rs) and ships it as a field on
// `CrateDrillDoc`, so the TypeScript copy answered the same question a second time and was called by
// nothing but its own test. `glanceFoldsAreCalled.test.ts` found it the moment that guard stopped
// counting a generated copy of a declaration as a call site.
/**
 * Fold the crate roster into a DRILL's graph — the app's own project drill, beside its studio sessions.
 *
 * NOT AN L0 BAND, AND THAT IS THE WHOLE POINT. `glanceData` carries the epitaph of the first attempt:
 * one node per active `bsc` subcommand and no edge at all, because the `invokes` edge runs
 * session→surface and L0 has no session node to draw one from. It left 33 permanently unconnected
 * nodes beside the project network — an inventory of the CLI rendered as if it were part of the
 * project graph. The `surfaces` parameter was deleted rather than kept and ignored, precisely so a
 * later reader would not put it back.
 *
 * Two things make this different rather than a repeat, and both are the 2026-09-01 decisions:
 * the node is keyed on the CRATE (so `bsc-util`, which has no verb and reaches 40 crates, gets one),
 * and the band HAS EDGES — `depends-on`, derived from cargo metadata. Structure is exactly what the
 * removed band lacked.
 *
 * Returns `data` UNCHANGED on an empty roster. A failed read must leave what is already drawn alone:
 * blanking the band on a transient error would make every crate vanish from the cockpit, which is the
 * rule the integration band states for the same reason.
 */
export function withSurfaceNodes(data: GlanceData, roster: SurfaceRosterRow[]): GlanceData {
  if (!roster.length) return data;
  const { nodes, edges } = surfaceGraph(roster);
  const present = new Set(data.rawNodes.map((n) => n.id));

  // EVERY CRATE CARRIES ITS REPO, or the drill stops separating by repository.
  //
  // `bandNodesByRepo` groups a drill's nodes on `n.repo` and leaves anything without one UNGROUPED —
  // so crates with no repo scattered through the whole graph instead of sitting with the repository
  // they live in. That was a regression the moment these stopped being fenced band nodes, because the
  // fence had been doing the separating by accident.
  //
  // The repo is taken from the nodes ALREADY in this drill rather than passed in: those are the
  // streams, and `withStreamRepos` has already stamped each with the repo from the plan — so a crate
  // joins the same band as the streams that own it, spelled exactly the same way. A roster is ONE
  // cargo workspace, hence one repository, which is why a single modal value is correct here and not
  // a simplification.
  //
  // With no repo to be had (a drill whose streams carry none) the crates are left UNSTAMPED rather
  // than given an invented one — ungrouped is honest, a wrong band is not.
  const repoTally = new Map<string, number>();
  for (const n of data.rawNodes) {
    if (n.repo) repoTally.set(n.repo, (repoTally.get(n.repo) ?? 0) + 1);
  }
  let repo: string | undefined;
  let best = 0;
  for (const [r, count] of repoTally) {
    if (count > best) {
      best = count;
      repo = r;
    }
  }

  const add = nodes.filter((n) => !present.has(n.id)).map((n) => (repo ? { ...n, repo } : n));
  if (!add.length) return data;
  // Every id this drill will hold once `add` lands — an edge is kept only if BOTH ends resolve, so a
  // node already drawn under another kind cannot acquire a dangling dependency line.
  const known = new Set([...present, ...add.map((n) => n.id)]);
  const seen = new Set(data.rawEdges.map((e) => e.id));
  const addEdges = edges.filter(
    (e) => !seen.has(e.id) && known.has(e.from) && known.has(e.to),
  );
  return { ...data, rawNodes: [...data.rawNodes, ...add], rawEdges: [...data.rawEdges, ...addEdges] };
}
/** One noun's row in `bsc surface drill <crate> --json`. */
export interface CrateDrillNoun {
  noun: string;
  status: string;
  catalog: "projected" | "unreachable";
  /** NULL when the crate serves this noun but publishes no `CmdDoc` catalog — distinct from empty. */
  verbs: { verb: string; summary: string; usage: string }[] | null;
}

/** The whole of `bsc surface drill <crate> --json`. */
export interface CrateDrillDoc {
  crate: string;
  path: string;
  surface: boolean;
  nouns: CrateDrillNoun[];
  dependsOn: string[];
  dependents: string[];
  dependentCount: number;
}

/**
 * THE SECOND LAYER — the NOUNS a crate serves, each rooting its own verbs.
 *
 * MAINTAINER 2026-09-02: "we should have the noun as the root of these graphs." The first cut rooted
 * the CRATE and hung every verb off it, which flattened `logs`/`metrics`/`perf` into one fan and lost
 * the thing a reader is actually navigating — you run `bsc logs sessions`, not `bsc logs-crate
 * sessions`. The noun IS the command; the crate is where it happens to be implemented.
 *
 * So a multi-noun crate yields a FOREST, one root per noun. That is the honest shape: those really are
 * three separate commands that happen to share a compilation unit.
 *
 * A NOUN WITH NO REACHABLE CATALOG IS STILL DRAWN, and this reverses the first cut deliberately.
 * Rooted on the crate, an empty cluster asserted the crate offered something it did not. Rooted on the
 * noun, the node says `bsc metrics` EXISTS and has no verb catalog — which is true and is exactly what
 * a reader wanting to know what they can run needs to see. It is captioned so the emptiness reads as a
 * fact rather than as a load that failed.
 *
 * A crate with NO nouns at all — a library or a program — yields just its own node, so the layer never
 * renders blank, which would read as a failed load rather than as "nothing to call here".
 */
export function crateDrillGraph(doc: CrateDrillDoc): GlanceData {
  const kind = crateKind(
    { crate: doc.crate, surface: doc.surface, dependsOn: doc.dependsOn },
    doc.dependentCount,
  );
  const rawNodes: GRawNode[] = [];
  const rawEdges: GRawEdge[] = [];

  for (const noun of doc.nouns) {
    const rootId = nounNodeId(noun.noun);
    rawNodes.push({
      id: rootId,
      slug: noun.noun,
      kind: "surface" as const,
      role: CRATE_KIND_ROLE.surface,
      // The caption names the CRATE, so a reader knows where this command lives without leaving the
      // layer — the fact the crate root used to carry, kept where it is still useful.
      roleLabel: doc.crate,
      health: "off" as const,
      activity: "idle" as const,
    });

    for (const v of noun.verbs ?? []) {
      const id = verbNodeId(noun.noun, v.verb);
      if (rawNodes.some((x) => x.id === id)) continue;
      rawNodes.push({
        id,
        slug: v.verb,
        kind: "surface" as const,
        role: CRATE_KIND_ROLE.surface,
        // Its NOUN, which is what tells `bsc logs summary` from `bsc perf summary`.
        roleLabel: noun.noun,
        health: "off" as const,
        activity: "idle" as const,
      });
      // VERB → NOUN, and the direction is the LAYOUT. The engine lays layers left→right and puts
      // whatever an edge points AT on the left, so `noun → verb` placed each verb to the LEFT of its
      // own noun — backwards for a left-to-right reader. Pointing the verb AT its noun puts the noun
      // on the left with its verbs fanning right, which is the reading order.
      rawEdges.push({
        id: verbOfEdgeId(doc.crate, noun.noun, v.verb),
        from: id,
        to: rootId,
        kind: "verb-of",
      });
    }
  }

  // Nothing to call: show the crate itself rather than an empty canvas.
  if (!rawNodes.length) {
    rawNodes.push({
      id: surfaceNodeId(doc.crate),
      slug: doc.crate,
      kind: "surface" as const,
      role: CRATE_KIND_ROLE[kind],
      roleLabel: kind,
      health: "off" as const,
      activity: "idle" as const,
    });
  }
  return { rawNodes, rawEdges, sample: false };
}

// SURFACE SESSIONS (`a-noun-and-its-verbs-launch-their-personas`) — the pane grammar and charter for
// the two personas that live on the crate drill.
//
// A NOUN gets an OPERATOR: it drives `bsc <noun>` for real work and reports what using it COSTS.
// A VERB gets a MAINTAINER: it owns that verb and answers the operator.
//
// They are app-owned sessions, exactly like the studio sessions and the per-request debug sessions —
// not fleet panes. A fleet pane is `<project>:<stream>` and belongs to a plan stream; these belong to a
// NODE in the graph, so the pane id is derived from the node and nothing else has to record the link.
import type { CrateDrillDoc } from "@/features/glance/lib/surfaceNodes";
import type { AgentProfile } from "@/shared/lib/security/agentProfiles";

/** Every surface session's pane lives under one prefix, so `livePanesFor…` can recognise them. */
export const SURFACE_PANE_PREFIX = "surface-studio:";

/** The pane a NOUN's operator runs in. */
export const nounPaneId = (noun: string): string => `${SURFACE_PANE_PREFIX}noun-${noun}`;

/** The pane a VERB's maintainer runs in — keyed on BOTH, since `logs summary` and `perf summary` are
 *  different commands and must not share a session. */
export const verbPaneId = (noun: string, verb: string): string =>
  `${SURFACE_PANE_PREFIX}verb-${noun}-${verb}`;

/**
 * The app-owned pane for a crate-drill node, or null if the node is not one.
 *
 * DERIVED FROM THE NODE ID, never recorded anywhere. That is what makes a session answerable from the
 * graph alone: the node knows its pane, so liveness, opening and killing all resolve without a second
 * table to keep in sync — the same property `requestIdFromPaneId` relies on.
 */
export function surfacePaneIdForNode(nodeId: string): string | null {
  if (nodeId.startsWith("noun:")) return nounPaneId(nodeId.slice("noun:".length));
  if (nodeId.startsWith("verb:")) {
    const rest = nodeId.slice("verb:".length);
    const at = rest.indexOf(":");
    // A verb node id is `verb:<noun>:<verb>`; anything else is not one, and guessing would mint a pane
    // that nothing can ever match back to a node.
    if (at <= 0 || at === rest.length - 1) return null;
    return verbPaneId(rest.slice(0, at), rest.slice(at + 1));
  }
  return null;
}

/** What a surface session is: which persona, and what it is pointed at. */
export interface SurfaceAssignment {
  kind: "operator" | "maintainer";
  crate: string;
  /** The crate's REPO-RELATIVE directory (`crates/logs`), carried as data rather than derived from
   *  `crate`. A session runs HERE, not at the repo root — see the cwd note on `surfaceCharter` — and
   *  `crates/${crate}` would be a guess about a layout the drill already states. */
  path: string;
  noun: string;
  verb?: string;
}

/** The assignment behind a node, or null. `doc` names the crate the drill is showing. */
export function surfaceAssignment(nodeId: string, doc: CrateDrillDoc | null): SurfaceAssignment | null {
  if (!doc) return null;
  if (nodeId.startsWith("noun:")) {
    return { kind: "operator", crate: doc.crate, path: doc.path, noun: nodeId.slice("noun:".length) };
  }
  if (nodeId.startsWith("verb:")) {
    const rest = nodeId.slice("verb:".length);
    const at = rest.indexOf(":");
    if (at <= 0 || at === rest.length - 1) return null;
    return { kind: "maintainer", crate: doc.crate, path: doc.path, noun: rest.slice(0, at), verb: rest.slice(at + 1) };
  }
  return null;
}

/** The exact command line for one verb, as the session must type it. */
const verbLine = (noun: string, verb: string, summary: string): string =>
  `  bsc ${noun} ${verb}${" ".repeat(Math.max(1, 22 - noun.length - verb.length))}${summary}`;

/**
 * The session's opening instruction: the PERSONA'S OWN PROMPT, then this session's assignment.
 *
 * `startPrompt` is passed in rather than inlined, because it is read from the persona store at launch
 * (`bsc persona get`). That keeps ONE copy of what an operator or a maintainer is — edit the persona and
 * every session started afterwards changes, with no second text to remember.
 *
 * # It TEACHES the surface rather than sending the session to discover it
 *
 * This used to open with "Read it first with `bsc <noun> help` and `bsc surface drill <crate> --json`",
 * which cost a local model two turns of a twenty-turn budget before it had run anything — and left it
 * inferring the command SHAPE from whatever it had seen. MEASURED 2026-09-03: a session reached for
 * `bsc-studio-help`, generalising from the hyphenated `bsc-ask`/`bsc-answer` helpers it had been
 * granted, which is not a command at all. The drill document is already in hand at launch, so the
 * verbs are listed here as literal command lines and the hyphen rule is stated rather than left to be
 * inferred.
 *
 * `verbs: null` means the crate serves this noun but publishes no `CmdDoc` catalog — DISTINCT from an
 * empty list, and said so rather than rendered as "no verbs", which would read as a broken surface.
 */
export function surfaceCharter(a: SurfaceAssignment, startPrompt: string, doc?: CrateDrillDoc | null): string {
  const row = doc?.nouns.find((n) => n.noun === a.noun);
  const verbs = row?.verbs ?? null;

  // THE SHAPE, stated once and shared by both personas. `bsc <noun> <verb>` is spaced; the ONLY
  // hyphenated names are the small shell-helper family, and conflating them produces a command that
  // does not exist.
  const shape =
    `THE BINARY IS \`bsc\`, already on your PATH, and EVERYTHING you can run is a subcommand of it:\n` +
    `  bsc help              every surface this app has\n` +
    `  bsc <noun> help       one surface in detail\n` +
    `  bsc persona whatami   who this session is, and what it may run\n\n` +
    `THE SHAPE IS SPACED, NEVER HYPHENATED. It is \`bsc ${a.noun} <verb>\` — three words. ` +
    `\`bsc-${a.noun}-<verb>\` is not a command and never was, and neither is \`bsc-session\` or ` +
    `\`bsc-${a.noun}-help\`. The only hyphenated names are the shell helpers (\`bsc-ask\`, ` +
    `\`bsc-answer\`), which are a different, tiny family — everything else is \`bsc\` then a space.\n\n` +
    `YOUR GRANT IS NARROWER THAN THAT CATALOG. \`bsc help\` lists what the APP has; you auto-run only ` +
    `your own surface plus the reporting verbs below. A command outside it will stop and ask rather ` +
    `than run, so reach for what you were given here instead of probing for what you were not.`;

  const catalog =
    verbs === null
      ? `This crate serves \`bsc ${a.noun}\` but publishes no verb catalog, so run \`bsc ${a.noun} help\` ` +
        `once to see what it takes. That is the exception, not the rule.`
      : `ITS VERBS, IN FULL — this is the whole surface, so you never need to discover it:\n` +
        verbs.map((v) => verbLine(a.noun, v.verb, v.summary)).join("\n") +
        `\n\nEach takes \`help\` for its own detail (\`bsc ${a.noun} <verb> help\`).`;

  const head =
    a.kind === "operator"
      ? `YOUR SURFACE IS \`bsc ${a.noun}\`, implemented by the \`${a.crate}\` crate at \`${a.path}\`.\n\n` +
        `${shape}\n\n${catalog}\n\n` +
        `TAKE ONE VERB, use it against something real, and ask ITS MAINTAINER for the change. Each verb ` +
        `has its own session, and the id is derived from the verb — no lookup:\n` +
        (verbs === null
          ? `  bsc session ask surface-studio:verb-${a.noun}-<verb> "<what it cost, and the exact command>"`
          : verbs
              .map((v) => `  bsc session ask surface-studio:verb-${a.noun}-${v.verb} "<…>"`)
              .join("\n"))
      : `YOU MAINTAIN \`bsc ${a.noun}${a.verb ? " " + a.verb : ""}\`, in the \`${a.crate}\` crate at ` +
        `\`${a.path}\` — the directory you are running in.\n\n${shape}\n\n` +
        (verbs?.find((v) => v.verb === a.verb)?.usage
          ? `WHAT YOUR VERB TAKES TODAY:\n${verbs.find((v) => v.verb === a.verb)!.usage}\n\n`
          : "") +
        `The operator of this noun asks you directly — that ask is your job, and you answer on the same ` +
        `loop with \`bsc session reply <loop-id> "<…>"\`.\n\n` +
        `If you change what this verb returns by default, update its \`CmdDoc\` in the same change: ` +
        `\`bsc surface verbs ${a.noun}\`, the Glance drill AND the charter above all PROJECT that catalog, ` +
        `so a stale entry advertises what dispatch will refuse — and teaches the operator a command that ` +
        `does not run.`;
  return `${startPrompt}\n\n---\n\n${head}\n`;
}

/** The profile id for an operator pointed at `noun`. Derived, so re-opening the same noun reuses the
 *  one profile instead of minting a new row per launch. */
export const surfaceOperatorProfileId = (noun: string): string => `gen_surface_${noun}`;

/**
 * The per-pane permission profile that hands an operator ITS OWN NOUN, and nothing else
 * (`surface-operator-runs-confined-to-its-own-noun`).
 *
 * # Why the noun cannot live in the role
 *
 * `build_allow_rules` returns EARLY under `restricted_allow` with only the wrapped `allowedCommands`
 * — no baseline tiers, no mandatory tier, no `Bash(bsc-*)`. A confined session therefore auto-runs
 * exactly what its allow list names and nothing else. A designer never notices, because it is
 * one-noun-per-ROLE and `bsc ui` sits in its floor; an operator's noun is chosen per SESSION, so a
 * static role structurally cannot name it. `buildSessionSettings` composes
 * `[...prof.allowedCommands, ...restrictedCommands]`, and this profile is the first half.
 *
 * # `bash` MUST NOT be `allow`, and that is the whole safety argument
 *
 * `resolveProfileSettings` maps a tool tier of `allow` to a VERBATIM tool rule — so `bash: "allow"`
 * emits a bare `Bash`, which auto-approves every command and silently reopens the confinement this
 * profile exists to create. `deny` is explicitly skipped for `bash` (a blanket Bash deny would also
 * kill the guaranteed `git`/`gh`), so it emits no rule at all and shell control stays entirely with
 * the allow list. `deny` is therefore the only correct value here, and
 * `theOperatorProfileNeverBlanketAllowsBash` pins it.
 *
 * The two `bsc-*` entries are shell FUNCTIONS from `bsc-env.sh`, not the binary — `Bash(bsc *)` cannot
 * match them (no space after `bsc`), and the blanket `Bash(bsc-*)` that every unconfined posture gets
 * is on the far side of that early return. The operator's charter tells it to reach its maintainer
 * with `bsc-ask`, so the grant has to be explicit here or the instruction is one it cannot follow.
 */
export function surfaceOperatorProfile(noun: string): AgentProfile {
  return {
    id: surfaceOperatorProfileId(noun),
    name: `Surface operator · bsc ${noun}`,
    color: "oklch(0.72 0.10 230)",
    category: "generated",
    origin: "generated by the surface studio",
    desc: `Drives \`bsc ${noun}\` and reports what it cost. No build toolchain, no file writes.`,
    mode: "deny",
    commands: [`bsc ${noun}`, "bsc-ask", "bsc-answer"],
    // `read`/`grep`/`glob` so it can look at what a verb wrote; everything that MUTATES is denied,
    // and `bash` is denied so no blanket rule is emitted (see above).
    tools: {
      read: "allow",
      grep: "allow",
      glob: "allow",
      edit: "deny",
      write: "deny",
      bash: "deny",
      web: "deny",
      task: "deny",
    },
    // It reports on a surface; it never edits one. The role already holds `code: none` — this is the
    // same statement at the tool layer, where a path-scoped rule can actually enforce it.
    paths: { allow: [], deny: ["**/*"] },
    net: { allow: [] },
  };
}

// The INTEGRATION node projection (`an-integration-is-a-glance-node-with-a-real-signal`) — turn the two
// landed reads into Glance nodes and edges.
//
// The inputs are the DEMAND and the SUPPLY, and joining them is the whole design:
//
//   demand  `bsc project integrations`      — which projects DECLARED which integrations, at Discovery.
//   supply  `bsc data connector status`     — whether a registered connector last verified, and against
//                                             which manifest.
//
// This module is the PURE projection of that join into the graph vocabulary; fetching is the caller's
// job, exactly as `surfaceNodes` does it.
//
// WHY THIS BAND MAY RENDER WHERE THE SURFACE BAND WAS REVERTED. The surface nodes were hardcoded
// `health: "off"` / `activity: "idle"` — inert by construction, so a cockpit gained 34 marks that could
// never change state. An integration's dot is DERIVED from a real verdict, and every one of its states
// is reachable by ordinary work: declared-but-unbuilt → built-but-unverified → live → stale the moment
// a manifest is edited → failing. It shows work moving, which is the property the revert demanded.
import {
  integrationNodeId,
  usesIntegrationEdgeId,
  type GRawNode,
  type GRawEdge,
  type GHealth,
} from "@/features/glance/lib/glanceGraph";

/** One row of `bsc project integrations` — a project's DECLARED integration. */
export interface DeclaredIntegrationRow {
  /** The project key that declared it. */
  project: string;
  /** The declared slug — the join key to a connector of the same id. */
  id: string;
  /** Display name, when it differs from the id. */
  name?: string;
  /** `source` (data migrates FROM it) | `runtime` (the app talks to it while running). */
  direction?: string;
}

/** The verdict states `bsc data connector status` reports, mirroring `CheckState` in `crates/data`. */
export type IntegrationCheckState = "never-checked" | "live" | "failing" | "stale";

/** One row of `bsc data connector status` — a REGISTERED connector and its last verdict. */
export interface ConnectorStatusRow {
  id: string;
  state: IntegrationCheckState;
  /** The failure reason, when the last check failed. */
  error?: string | null;
}

/** The projected band: one node per integration, one edge per declaration. */
export interface IntegrationGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/**
 * The node health for one integration, derived from whether it is BUILT and what it last verified.
 *
 * `off` is not `healthy`, and that distinction is the whole reason this function exists rather than a
 * ternary at the call site. A connector nobody has checked has earned neither green nor red — the dot
 * is supposed to mean something, and asserting health nobody measured is what made the surface band
 * worth reverting.
 *
 * An integration that is DECLARED but has no connector is also `off`, and that is not a defect: it is
 * the Integrator's queue, rendered. Wanted, not yet built.
 */
export function integrationHealth(state: IntegrationCheckState | undefined): GHealth {
  switch (state) {
    case "live":
      return "healthy";
    case "failing":
      return "error";
    // A verdict about a manifest that has since changed says nothing about the current shape. It is a
    // warning rather than an error because nothing is known to be BROKEN — it is known to be unverified,
    // which is a different and softer claim.
    case "stale":
      return "warning";
    default:
      return "off";
  }
}

/**
 * Project declared integrations + connector verdicts into integration nodes and project edges.
 *
 * EVERY INTEGRATION THAT EXISTS GETS A NODE — declared, registered, or both. A connector registered
 * app-wide that no project declared is still real and still needs an owner, so it appears with no
 * edges rather than being hidden. That is the maintainer's decision and it is the opposite of the MCP
 * band's rule, where a globally-scoped server is skipped.
 *
 * An edge to a project NOT in `projectKeys` is DROPPED. A dangling edge is worse than a missing one:
 * the layout would carry a node id nothing renders. When `projectKeys` is undefined the caller is
 * saying it does not know the project set, and every declared edge is kept.
 */
export function integrationGraph(
  declared: DeclaredIntegrationRow[],
  connectors: ConnectorStatusRow[] = [],
  projectKeys?: Iterable<string>,
): IntegrationGraph {
  const known = projectKeys ? new Set(projectKeys) : null;
  const statusById = new Map(connectors.map((c) => [c.id, c]));

  // The node set is the UNION of both sides, in a stable order: declaration order first (that is the
  // order a reader met them in), then any registered connector nobody declared.
  const ids: string[] = [];
  const seen = new Set<string>();
  for (const d of declared) {
    if (d.id && !seen.has(d.id)) {
      seen.add(d.id);
      ids.push(d.id);
    }
  }
  for (const c of connectors) {
    if (c.id && !seen.has(c.id)) {
      seen.add(c.id);
      ids.push(c.id);
    }
  }

  const nameById = new Map<string, string>();
  for (const d of declared) {
    if (d.name && !nameById.has(d.id)) nameById.set(d.id, d.name);
  }

  const nodes: GRawNode[] = ids.map((id) => {
    const status = statusById.get(id);
    const health = integrationHealth(status?.state);
    return {
      id: integrationNodeId(id),
      slug: nameById.get(id) || id,
      kind: "integration" as const,
      role: "infra" as const,
      health,
      // `idle` always: an integration is a system we READ on demand, never something that is "building".
      activity: "idle" as const,
      // The reason is carried ONLY when the dot changed, matching every other band node — a reason
      // beside a healthy dot reads as a problem that is not there.
      ...(health === "error" && status?.error ? { reason: status.error } : {}),
    };
  });

  const edges: GRawEdge[] = [];
  const drawn = new Set<string>();
  for (const d of declared) {
    if (!d.id || !d.project) continue;
    if (known && !known.has(d.project)) continue;
    const id = usesIntegrationEdgeId(d.project, d.id);
    if (drawn.has(id)) continue;
    drawn.add(id);
    edges.push({ id, from: d.project, to: integrationNodeId(d.id), kind: "uses-integration" });
  }
  return { nodes, edges };
}

/** How many projects declared `id` — the number that says how much a broken integration reaches. */
export function declaringProjectCount(declared: DeclaredIntegrationRow[], id: string): number {
  return new Set(declared.filter((d) => d.id === id).map((d) => d.project)).size;
}

