// The FEATURE node projection (`a-feature-is-a-node`) — the band and one feature's drill.
import { describe, it, expect } from "vitest";
import { featureBand, featureDrill, withFeatureNodes, streamFeature, requiredId, requiredBy } from "@/features/glance/lib/featureNodes";
import { featureNodeId, featureRequiresNodeId } from "@/features/glance/lib/glanceGraph";

const FEATURES = [
  { slug: "glance", name: "Glance", requires: ["safe-invoke.ts", { id: "use-poll.ts", by: "director" }] },
  { slug: "cad", name: "CAD" },
  // No stream anywhere — the case the band must still show.
  { slug: "orphan", name: "Orphan" },
];
const STREAMS = [
  { id: "glance", repo: "o/r" },                              // id IS the slug — the fallback
  { id: "fleet-panes", feature: "glance", repo: "o/r" },       // explicitly under glance
  { id: "cad", feature: "cad", kind: "cleanup", repo: "o/r" },
];

describe("streamFeature — which feature a stream belongs to", () => {
  it("prefers the stream's own `feature` and falls back to its id", () => {
    // The fallback is not a convenience: 37 of studio-code's 89 stream ids ARE feature slugs and the
    // launch has always leaned on that. A projection that disagreed with the launch would draw a graph
    // of a fleet that does not exist.
    expect(streamFeature({ id: "fleet-panes", feature: "glance" })).toBe("glance");
    expect(streamFeature({ id: "glance" })).toBe("glance");
    // Whitespace is the shape a hand-edited record has; it must not read as a real feature.
    expect(streamFeature({ id: "glance", feature: "   " })).toBe("glance");
  });
});

describe("featureBand", () => {
  it("gives EVERY feature a node, including one with no streams", () => {
    // The same reasoning that gives a verb-less crate a node: an unstaffed lane is exactly the one
    // worth seeing, and a projection that dropped it would hide the gap in the view that exists to
    // show gaps.
    const { nodes } = featureBand(FEATURES, STREAMS);
    expect(nodes.map((n) => n.slug)).toEqual(["glance", "cad", "orphan"]);
    expect(nodes.map((n) => n.id)).toEqual([
      featureNodeId("glance"), featureNodeId("cad"), featureNodeId("orphan"),
    ]);
  });

  it("carries the stream COUNT, and states zero rather than omitting it", () => {
    const byId = new Map(featureBand(FEATURES, STREAMS).nodes.map((n) => [n.slug, n.roleLabel]));
    expect(byId.get("glance")).toBe("2 streams");   // the fallback one AND the explicit one
    expect(byId.get("cad")).toBe("1 streams");
    // A blank card is indistinguishable from a rendering bug; `0 streams` is a fact.
    expect(byId.get("orphan")).toBe("0 streams");
  });

  it("draws NO edges between features", () => {
    // `dependsOn` on a feature is the roadmap DAG — a sequencing hint, not a dependency the code has.
    // Drawing it here would read as the same kind of line the crate band uses for a real cargo edge.
    expect(featureBand(FEATURES, STREAMS).edges).toEqual([]);
  });

  it("is deterministic — roster order in, same order out", () => {
    const a = featureBand(FEATURES, STREAMS).nodes.map((n) => n.id);
    const b = featureBand(FEATURES, STREAMS).nodes.map((n) => n.id);
    expect(a).toEqual(b);
  });
});

describe("featureDrill", () => {
  const store = (id: string) => (id === "safe-invoke.ts" ? ("algorithms" as const) : undefined);

  it("puts this feature's streams beneath it, and no other feature's", () => {
    const { nodes, edges } = featureDrill(FEATURES[0], STREAMS, store);
    const streams = nodes.filter((n) => n.kind === "session").map((n) => n.slug);
    expect(streams).toEqual(["glance", "fleet-panes"]);
    expect(streams).not.toContain("cad");
    // Every stream edge points UP to the feature — the drill reads as one lane under one owner.
    const belongs = edges.filter((e) => e.kind === "belongs-to");
    expect(belongs).toHaveLength(2);
    expect(belongs.every((e) => e.to === featureNodeId("glance"))).toBe(true);
    // ONE IDENTITY PER STREAM. The node id is the STREAM's own id — the same id the fleet drill
    // gives the lane — so `fleetPaneId(drill, id)` finds the same pane and the node really is the
    // session it claims to be. A minted `fstream:…` id resolved to nothing.
    expect(belongs[0].from).toBe("glance");
    expect(nodes.filter((n) => n.kind === "session").map((n) => n.id)).toEqual(["glance", "fleet-panes"]);
  });

  it("keeps required RECORDS a different kind from streams", () => {
    // They answer different questions: a stream is this project's own work with a worktree and a
    // worker; a required record is shared and NOT this feature's to edit. Collapsing them would
    // suggest a worker can change both, which is the whole thing `requires` exists to deny.
    const { nodes } = featureDrill(FEATURES[0], STREAMS, store);
    const req = nodes.filter((n) => n.kind === "library");
    expect(req.map((n) => n.slug)).toEqual(["safe-invoke.ts", "use-poll.ts"]);
    expect(req.every((n) => n.role === "infra")).toBe(true);
  });

  it("names WHICH STORE answers a record, and who asked for it", () => {
    // `bsc graph impl get` and `bsc ui get` are different commands — a drill that guessed would send a
    // reader to one that returns nothing for half the list.
    const req = featureDrill(FEATURES[0], STREAMS, store).nodes.filter((n) => n.kind === "library");
    expect(req[0].roleLabel).toBe("algorithms");
    // …and the provenance rides along, which is the whole point of the attributed write.
    expect(req[1].roleLabel).toContain("by director");
  });

  it("flags a record in NEITHER graph rather than dropping it", () => {
    // `requires` is deliberately not validated at plan-write time, so a drill is one of the first
    // places a typo becomes visible. Silently omitting it would make a dangling id look like a
    // feature that requires less than it does.
    const dangling = featureDrill({ slug: "x", requires: ["nope.ts"] }, [], () => undefined);
    // FIND it rather than indexing: node 0 is the feature's own root now, and an index-based test
    // silently changes what it asserts the moment the node order does.
    const n = dangling.nodes.find((x) => x.id === featureRequiresNodeId("x", "nope.ts"))!;
    expect(n, "the dangling record was dropped instead of flagged").toBeDefined();
    expect(n.id).toBe(featureRequiresNodeId("x", "nope.ts"));
    expect(n.health).toBe("warning");
    expect(n.reason).toBe("in neither graph");
  });

  it("puts the FEATURE ITSELF in the graph — the root its streams hang from", () => {
    // It was missing, and every edge named it: the streams rendered with nothing to hang from, which
    // is what a reader sees as "no root". A projection that emits an edge to a node it does not emit
    // is broken however good its other nodes are.
    const { nodes } = featureDrill(FEATURES[0], STREAMS, store);
    const root = nodes.find((n) => n.id === featureNodeId("glance"));
    expect(root, "the drilled feature has no node of its own").toBeDefined();
    expect(root!.kind).toBe("feature");
    expect(root!.roleLabel).toBe("2 streams");
  });

  it("holds a feature with nothing under it to just its root, rather than throwing", () => {
    // Not `{nodes: [], edges: []}` any more: an unstaffed feature still IS one, and a drill that
    // rendered blank would be indistinguishable from a broken one.
    const { nodes, edges } = featureDrill(FEATURES[2], STREAMS, store);
    expect(nodes.map((n) => n.id)).toEqual([featureNodeId("orphan")]);
    expect(edges).toEqual([]);
  });

  // THE INVARIANT THAT WOULD HAVE CAUGHT IT, asserted over BOTH projections rather than trusting
  // either: `featureBand` filtered its edges to the nodes it emitted and `featureDrill` did not, so
  // the property held in one and silently failed in the other.
  it("emits no edge to a node it does not also emit", () => {
    for (const f of FEATURES) {
      const { nodes, edges } = featureDrill(f, STREAMS, store);
      const ids = new Set(nodes.map((n) => n.id));
      const dangling = edges.filter((e) => !ids.has(e.from) || !ids.has(e.to));
      expect(dangling.map((e) => e.id), `dangling edge(s) in the ${f.slug} drill`).toEqual([]);
    }
  });
});

describe("requiredId / requiredBy — the two entry shapes", () => {
  it("reads a bare id and an attributed entry the same way, and invents no author", () => {
    expect(requiredId("a.ts")).toBe("a.ts");
    expect(requiredId({ id: "b.ts" })).toBe("b.ts");
    // A bare id carries NO author — absent, never guessed, which is what makes a seeded entry
    // distinguishable from a discovered one.
    expect(requiredBy("a.ts")).toBeUndefined();
    expect(requiredBy({ id: "b.ts", by: "worker-A" })).toBe("worker-A");
  });
});

// THE FOLD ITSELF WAS UNTESTED, which is how it shipped ADDING to the graph instead of REPLACING in
// it — 89 flat stream nodes and 27 feature cards on one canvas, read (correctly) as "the old plan".
// `featureBand` and `featureDrill` each had their own passing tests throughout; nothing asserted what
// the fold did to the graph it was folding into.
describe("withFeatureNodes — the feature replaces the streams it covers", () => {
  const FLEET = {
    sample: false,
    rawNodes: [
      { id: "director", slug: "director", kind: "session" as const, role: "service" as const, health: "off" as const, activity: "idle" as const },
      { id: "glance", slug: "glance", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      { id: "fleet-panes", slug: "fleet-panes", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      { id: "unassigned", slug: "unassigned", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
    ],
    rawEdges: [
      { id: "d-glance", from: "director", to: "glance", kind: "coordinates" as const },
      { id: "d-panes", from: "director", to: "fleet-panes", kind: "coordinates" as const },
      { id: "d-un", from: "director", to: "unassigned", kind: "coordinates" as const },
    ],
  };
  const FEATS = [{ slug: "glance", name: "Glance" }];
  const STRS = [
    { id: "glance", feature: "glance" },
    { id: "fleet-panes", feature: "glance" },
    { id: "unassigned" },
  ];

  it("drops the stream nodes its features stand for", () => {
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = out.rawNodes.map((n) => n.id);
    expect(ids).not.toContain("glance");
    expect(ids).not.toContain("fleet-panes");
    expect(ids).toContain(featureNodeId("glance"));
  });

  it("KEEPS a stream no feature covers — unassigned work must not vanish", () => {
    // The one thing this view must never do. An unstaffed lane is exactly what a reader is scanning
    // for, and removing it leaves no node to notice its absence by.
    expect(withFeatureNodes(FLEET, FEATS, STRS).rawNodes.map((n) => n.id)).toContain("unassigned");
  });

  it("leaves the director alone", () => {
    expect(withFeatureNodes(FLEET, FEATS, STRS).rawNodes.map((n) => n.id)).toContain("director");
  });

  it("leaves no edge pointing at a removed stream", () => {
    // A dangling edge is what made the feature DRILL render rootless; the fold must not reintroduce
    // the same class one level up.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = new Set(out.rawNodes.map((n) => n.id));
    expect(out.rawEdges.filter((e) => !ids.has(e.from) || !ids.has(e.to))).toEqual([]);
  });

  it("REDIRECTS a removed stream's edges onto its feature — the director still manages it", () => {
    // The relationship is inherited, not minted: `fleetToOrg` draws `director manages <stream>` via
    // `archOf`, which a TEAM may have authored differently. A fresh edge here would discard that.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const toFeature = out.rawEdges.filter((e) => e.to === featureNodeId("glance"));
    expect(toFeature).toHaveLength(1);
    expect(toFeature[0].from).toBe("director");
    expect(toFeature[0].kind).toBe("coordinates");
  });

  it("collapses N streams under one feature into ONE edge", () => {
    // `glance` covers two streams, and the director managed both. Twenty parallel lines between the
    // same pair is one fact drawn twenty times.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const pairs = out.rawEdges.map((e) => `${e.from}|${e.to}|${e.kind}`);
    expect(new Set(pairs).size).toBe(pairs.length);
  });

  it("keeps an UNCOVERED stream's own edge untouched", () => {
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    expect(out.rawEdges.find((e) => e.to === "unassigned")?.id).toBe("d-un");
  });

  it("preserves an AUTHORED archetype through the redirect", () => {
    const authored = {
      ...FLEET,
      rawEdges: [{ id: "d-glance", from: "director", to: "glance", kind: "coordinates" as const, archetype: "mentors" }],
    };
    const out = withFeatureNodes(authored, FEATS, STRS);
    const e = out.rawEdges.find((x) => x.to === featureNodeId("glance"));
    expect(e?.archetype, "a team-authored archetype was replaced by a minted default").toBe("mentors");
  });

  it("does NOT fold a stream-to-stream edge into a feature-to-feature one", () => {
    // THE CYCLE FACTORY. Collapsing a DAG's nodes into groups manufactures cycles: MEASURED on the
    // real plan, 208 acyclic `dependsOn` edges between streams became 20 cycles between features,
    // which flooded the coordination-hazard pane and hid the list. The claims were invented — the
    // plan never said `cad` depends on `cli-platform`.
    const cross = {
      ...FLEET,
      rawNodes: [
        ...FLEET.rawNodes,
        { id: "cad", slug: "cad", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      ],
      rawEdges: [{ id: "s-s", from: "glance", to: "cad", kind: "depends-on" as const }],
    };
    const out = withFeatureNodes(cross, [...FEATS, { slug: "cad", name: "CAD" }], [...STRS, { id: "cad", feature: "cad" }]);
    const featIds = new Set([featureNodeId("glance"), featureNodeId("cad")]);
    expect(
      out.rawEdges.filter((e) => featIds.has(e.from) && featIds.has(e.to)),
      "a stream's dependency was folded into a claim about features",
    ).toEqual([]);
  });

  it("carries the repo when its streams agree — the band survives the fold", () => {
    // `withStreamRepos` stamps this per STREAM and the layout bands by it. A feature carrying none
    // lands unbanded, which is how folding the streams away removed the repository separation.
    const withRepos = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/desktop" },
      { id: "unassigned" },
    ];
    const { nodes } = featureBand(FEATS, withRepos);
    expect(nodes.find((n) => n.slug === "glance")?.repo).toBe("o/desktop");
  });

  it("draws ONE NODE PER REPO when its streams span", () => {
    // A majority pick erases the minority; unbanded says it belongs to no repository at all. The
    // feature really does have work in both, so it appears in both bands. `mobile-tunnel` is the live
    // case. Safe to duplicate because cross-repo coherence is enforced through the components and
    // algorithms graphs, not here.
    const spanning = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/mobile" },
      { id: "extra", feature: "glance", repo: "o/mobile" },
    ];
    const mine = featureBand(FEATS, spanning).nodes.filter((n) => n.slug === "glance");
    expect(mine.map((n) => n.repo).sort()).toEqual(["o/desktop", "o/mobile"]);
    expect(mine.map((n) => n.id).sort()).toEqual([
      featureNodeId("glance", "o/desktop"),
      featureNodeId("glance", "o/mobile"),
    ]);
    // Each band counts ONLY its own streams — the same number in both would be uncheckable.
    expect(mine.find((n) => n.repo === "o/desktop")?.roleLabel).toBe("1 streams");
    expect(mine.find((n) => n.repo === "o/mobile")?.roleLabel).toBe("2 streams");
  });

  it("keeps the plain id for a single-repo feature — no churn", () => {
    const one = [{ id: "glance", feature: "glance", repo: "o/desktop" }];
    expect(featureBand(FEATS, one).nodes[0].id).toBe(featureNodeId("glance"));
  });

  it("bands a feature with NO streams under the plan's dominant repo", () => {
    // Floating beside the director made `help` and `settings` read as project-level actors rather
    // than the unstaffed features they are. "Probably the main repo" is the smaller error.
    const streams = [
      { id: "a", feature: "other", repo: "o/desktop" },
      { id: "b", feature: "other", repo: "o/desktop" },
      { id: "c", feature: "other", repo: "o/mobile" },
    ];
    const n = featureBand([{ slug: "help", name: "help" }], streams).nodes[0];
    expect(n.repo).toBe("o/desktop");
    expect(n.roleLabel).toBe("0 streams");
  });

  it("folds each stream onto the node for ITS OWN repo", () => {
    // Otherwise every `manages` edge lands on whichever band came first and the other sits unmanaged.
    const spanning = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/mobile" },
    ];
    const fleet = {
      sample: false,
      rawNodes: [
        { id: "director", slug: "director", kind: "session" as const, role: "service" as const, health: "off" as const, activity: "idle" as const },
        { id: "glance", slug: "glance", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
        { id: "fleet-panes", slug: "fleet-panes", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      ],
      rawEdges: [
        { id: "d1", from: "director", to: "glance", kind: "coordinates" as const },
        { id: "d2", from: "director", to: "fleet-panes", kind: "coordinates" as const },
      ],
    };
    const out = withFeatureNodes(fleet, FEATS, spanning);
    const managed = out.rawEdges.filter((e) => e.from === "director").map((e) => e.to).sort();
    expect(managed).toEqual([
      featureNodeId("glance", "o/desktop"),
      featureNodeId("glance", "o/mobile"),
    ]);
  });

  it("draws no self-edge when two streams of one feature were connected", () => {
    const linked = {
      ...FLEET,
      rawEdges: [{ id: "s-s", from: "glance", to: "fleet-panes", kind: "coordinates" as const }],
    };
    const out = withFeatureNodes(linked, FEATS, STRS);
    expect(out.rawEdges.filter((e) => e.from === e.to)).toEqual([]);
  });

  it("never leaves a feature AND the streams it covers in one graph", () => {
    // THE INVARIANT, stated directly: two representations of the same work on one canvas is the bug.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = new Set(out.rawNodes.map((n) => n.id));
    for (const f of FEATS) {
      if (!ids.has(featureNodeId(f.slug))) continue;
      const covered = STRS.filter((s) => streamFeature(s) === f.slug).map((s) => s.id);
      expect(covered.filter((id) => ids.has(id)), `${f.slug} is drawn AND so are its streams`).toEqual([]);
    }
  });

  it("is a no-op with no features, rather than emptying the graph", () => {
    expect(withFeatureNodes(FLEET, [], STRS)).toBe(FLEET);
  });
});

implementations.code:
// The FEATURE node projection (`a-feature-is-a-node`) — turn the plan's feature roster + its stream
// roster into Glance nodes and edges.
//
// The rosters come from `bsc plan feature list --json` and `bsc plan fleet get --full`. This module is
// the PURE projection of those into the graph vocabulary; fetching them is the caller's job, exactly
// as `surfaceNodes.ts` splits the crate roster from its projection.
//
// ONE NODE PER FEATURE, INCLUDING THE ONES WITH NO STREAMS. Same reasoning that gives a verb-less
// crate a node: a lane nobody has staffed is precisely the one worth seeing. Six of studio-code's 44
// features had no stream when this was written, and a projection that dropped them would have made
// the gap invisible in the one view that exists to show gaps.
import type { GlanceData } from "@/features/glance/lib/glanceData";
import {
  featureNodeId,
  featureRequiresNodeId,
  belongsToEdgeId,
  // The project→library `requires` edge id, reused rather than re-minted: a feature requiring a record
  // is the same relationship the L0 graph already draws, and a second id scheme for it would make the
  // same edge unequal to itself across the two views.
  requiresEdgeId,
  type GRawNode,
  type GRawEdge,
} from "@/features/glance/lib/glanceGraph";

/** One row of `bsc plan feature list --json`. */
export interface FeatureRow {
  slug: string;
  name?: string;
  /** The records this feature declares it needs. A bare id, or an entry carrying its provenance —
   *  the two shapes `RequiredRef` holds, and the reason the node can say WHO asked for a record. */
  requires?: Array<string | { id: string; by?: string; note?: string }>;
}

/** One row of the fleet's `streams` array, lean or full. */
export interface StreamRow {
  id: string;
  name?: string;
  /** `owner/name`, exactly as the plan records it. The fleet BANDS nodes by this
   *  (`withStreamRepos` → `glance-graph`), and a feature node that carries none lands in the
   *  unbanded group — which is how folding the streams away removed the repository separation. */
  repo?: string;
  /** Which feature it belongs to. ABSENT falls back to the stream's own id, which is how the 37
   *  streams whose id already IS a feature slug resolve — the same rule the launch applies, restated
   *  here rather than assumed, because a projection that disagreed with the launch would draw a graph
   *  of a fleet that does not exist. */
  feature?: string;
  kind?: string;
}

/** The projected band and its drill. */
export interface FeatureGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/** Which feature a stream belongs to — its own `feature`, else its id. See {@link StreamRow.feature}. */
export function streamFeature(s: StreamRow): string {
  const f = (s.feature ?? "").trim();
  return f || s.id;
}

/** The id of a required entry, whichever shape it takes. */
export function requiredId(r: string | { id: string }): string {
  return typeof r === "string" ? r : r.id;
}

/** Who asked for a required entry, when it says. A bare id carries no author — absent, never invented. */
export function requiredBy(r: string | { id: string; by?: string }): string | undefined {
  return typeof r === "string" ? undefined : r.by;
}

/** Every repo `slug` has streams in, in first-appearance order, and how many in each. */
function reposOf(streams: StreamRow[], slug: string): Map<string, number> {
  const out = new Map<string, number>();
  for (const s of streams) {
    if (streamFeature(s) !== slug) continue;
    const r = (s.repo ?? "").trim();
    if (r) out.set(r, (out.get(r) ?? 0) + 1);
  }
  return out;
}

/**
 * The repo a feature with NO streams bands under — the plan's dominant one.
 *
 * There is nothing on the feature itself to derive from, so this is a display default rather than a
 * claim about ownership. It is the right default because the alternative is what the maintainer
 * reported: an unbanded node sits LEFT of the repo fence with the director and the architect, so
 * `help` and `settings` read as project-level actors rather than as the unstaffed features they are.
 * Saying "probably the main repo" is a smaller error than saying "belongs to no repository".
 */
function dominantRepo(streams: StreamRow[]): string | undefined {
  const n = new Map<string, number>();
  for (const s of streams) {
    const r = (s.repo ?? "").trim();
    if (r) n.set(r, (n.get(r) ?? 0) + 1);
  }
  let best: string | undefined;
  for (const [r, c] of n) if (!best || c > (n.get(best) ?? 0)) best = r;
  return best;
}

/**
 * The FEATURE BAND — one node per feature, carrying how many streams it owns.
 *
 * The stream count rides on the node so the band answers "how big is this lane" without a drill. It is
 * the number a reader is actually scanning for: `teams-personas` owning 20 streams and `cad` owning one
 * are different kinds of thing, and a band of identically-sized cards would hide that.
 *
 * DETERMINISTIC — features in roster order, so two renders of the same plan diff meaningfully.
 */
export function featureBand(features: FeatureRow[], streams: StreamRow[]): FeatureGraph {
  const dominant = dominantRepo(streams);
  const nodes: GRawNode[] = features.flatMap((f) => {
    const repos = reposOf(streams, f.slug);
    // ONE NODE PER REPO THE FEATURE HAS WORK IN. A feature spanning repositories really does have work
    // in each, so a majority pick would erase the minority and leaving it unbanded would say it belongs
    // to none. `mobile-tunnel` is the live case: 1 stream in base-studio-code, 2 in mobile.
    //
    // The DUPLICATION IS SAFE because cross-repo coherence is not this graph's job — it is enforced
    // through the components and algorithms graphs and their relationships (maintainer, 2026-09-03).
    //
    // No streams at all ⇒ one node under the plan's dominant repo; see {@link dominantRepo}.
    const bands: { repo?: string; n: number }[] =
      repos.size > 0 ? [...repos].map(([repo, n]) => ({ repo, n })) : [{ repo: dominant, n: 0 }];
    return bands.map(({ repo, n }) => ({
      // The suffix ONLY when the feature actually spans, so the ids that already work do not churn.
      id: featureNodeId(f.slug, repos.size > 1 ? repo : undefined),
      slug: f.slug,
      kind: "feature" as const,
      // `service` — a feature is a CAPABILITY this product offers, which is the closest the role
      // vocabulary has. The size lives in `roleLabel` rather than in the colour.
      role: "service" as const,
      // Only THIS band's streams. A per-repo node claiming the whole feature's count would print the
      // same number in both bands, and neither would be checkable against what is under it.
      //
      // `0 streams` is stated rather than omitted: an unstaffed lane rendering as a blank card is
      // indistinguishable from a rendering bug.
      roleLabel: `${n} streams`,
      // THE REPO BAND, rebuilt on the coarse node. `withStreamRepos` stamps this per STREAM and the
      // layout bands by it, so a feature carrying none lands ungrouped beside the director — which is
      // exactly what removed the repository separation when the streams stopped being drawn.
      ...(repo ? { repo } : {}),
      health: "off" as const,
      activity: "idle" as const,
    }));
  });
  // The band draws no edges between features. `dependsOn` on a feature is the roadmap DAG — a
  // SEQUENCING hint, not a dependency the code has — and drawing it here would read as the same kind
  // of line the crate band uses for a real cargo edge.
  return { nodes, edges: [] };
}

/**
 * ONE FEATURE'S DRILL — its streams beneath it, and the records it requires beside them.
 *
 * Two node kinds because they answer two different questions. A STREAM is a lane of this project's own
 * work, with a worktree and a worker; a REQUIRED RECORD is something from the shared graphs this
 * feature builds against and does not own. Collapsing them would suggest a worker can edit both, and
 * the whole point of `requires` is that the second kind lives somewhere else.
 *
 * A required node names WHICH STORE answers it, because `bsc graph impl get` and `bsc ui get` are
 * different commands: a drill that guessed would send a reader to one that returns nothing for half
 * the list — the same reason the launch block resolves the store rather than assuming.
 */
export function featureDrill(
  feature: FeatureRow,
  streams: StreamRow[],
  /** Which store holds a record id, when known. `undefined` ⇒ the drill says so rather than guessing. */
  storeOf: (recordId: string) => "algorithms" | "components" | undefined = () => undefined,
): FeatureGraph {
  // THE FEATURE ITSELF IS THE ROOT OF ITS OWN DRILL, and it was missing. Every edge below names
  // `featureNodeId(feature.slug)`, so without this node the whole drill dangled: the streams rendered
  // with nothing to hang from, which is exactly what a reader sees as "no root".
  //
  // `featureBand` filters its edges to the nodes it emits (`known.has(e.from) && known.has(e.to)`);
  // this function had no such filter, so the dangling edges went straight into `buildGraph`. The band
  // was careful and the drill was not — hence `emitsNoDanglingEdge` in the tests, which asserts the
  // property for BOTH rather than trusting either.
  const nodes: GRawNode[] = [
    {
      id: featureNodeId(feature.slug),
      slug: feature.slug,
      kind: "feature" as const,
      role: "service" as const,
      roleLabel: `${streams.filter((s) => streamFeature(s) === feature.slug).length} streams`,
      health: "off" as const,
      activity: "idle" as const,
    },
  ];
  const edges: GRawEdge[] = [];

  const mine = streams.filter((s) => streamFeature(s) === feature.slug);
  for (const s of mine) {
    nodes.push({
      // THE STREAM'S OWN ID, which is the id the FLEET drill gives the same lane
      // (`glance-fleet.ts`: `nodeId: s.id`) — and panes bind as `fleetPaneId(drill, nodeId)`. Minting
      // `fstream:<feature>:<stream>` here gave one lane two identities depending on which graph you
      // arrived through, and only the fleet's resolved to a pane: the node said `session` and behaved
      // like a label. A worker's session must be the SAME session however the user navigated to it.
      id: s.id,
      slug: s.id,
      kind: "session" as const,
      // `client` — something that RUNS on its own, which is exactly what a stream is: a lane with a
      // worktree and a worker of its own.
      role: "client" as const,
      roleLabel: s.kind && s.kind !== "feature" ? s.kind : "stream",
      health: "off" as const,
      activity: "idle" as const,
    });
    edges.push({
      id: belongsToEdgeId(feature.slug, s.id),
      from: s.id,
      to: featureNodeId(feature.slug),
      kind: "belongs-to" as const,
    });
  }

  for (const r of feature.requires ?? []) {
    const id = requiredId(r);
    const store = storeOf(id);
    const by = requiredBy(r);
    nodes.push({
      id: featureRequiresNodeId(feature.slug, id),
      slug: id,
      kind: "library" as const,
      // `infra` — something others BUILD ON, the same role the crate band gives a library. A required
      // record is precisely that: shared, and not this feature's to edit.
      role: "infra" as const,
      // The store, then who asked. Both are facts a reader needs before acting: which command reads it,
      // and whether this entry was a director's seed or a worker's discovery.
      roleLabel: `${store ?? "unresolved"}${by ? ` · by ${by}` : ""}`,
      health: store ? ("off" as const) : ("warning" as const),
      // An id in NEITHER store is a dangling reference, and it is surfaced here rather than dropped —
      // `requires` is deliberately not validated at plan-write time, so a drill is one of the first
      // places a typo can become visible.
      ...(store ? {} : { reason: "in neither graph" }),
      activity: "idle" as const,
    });
    edges.push({
      id: requiresEdgeId(feature.slug, featureRequiresNodeId(feature.slug, id)),
      from: featureNodeId(feature.slug),
      to: featureRequiresNodeId(feature.slug, id),
      kind: "requires" as const,
    });
  }
  return { nodes, edges };
}


/**
 * FOLD THE FEATURE BAND INTO A DRILL — the call site `featureBand` existed six hours without.
 *
 * `a-feature-is-a-node` shipped the projection with three passing tests and nothing calling it, so the
 * band did not exist in the running app and no gate could tell. That is the second time this repo has
 * done it — `glanceFoldsAreCalled.test.ts` was written the first time, and its header says the whole
 * thing: A GRAPH FOLD WITH NO CALLER IS A NODE NOBODY SEES.
 *
 * Shaped exactly like [`withSurfaceNodes`], because the constraints are the same ones:
 *
 * - EMPTY IN, UNCHANGED OUT. A project with no features must cost nothing, not an empty band.
 * - AN ID ALREADY PRESENT IS NOT RE-ADDED, so folding twice is folding once.
 * - AN EDGE SURVIVES ONLY IF BOTH ENDS RESOLVE. A feature node drawn under some other kind must not
 *   acquire a dangling line, and the drill is assembled from several folds in sequence.
 */
export function withFeatureNodes(
  data: GlanceData,
  features: FeatureRow[],
  streams: StreamRow[],
): GlanceData {
  if (!features.length) return data;
  const { nodes, edges } = featureBand(features, streams);

  // THE FEATURE REPLACES THE STREAMS IT COVERS — it does not sit on top of them.
  //
  // This fold used to only ADD, so `buildRealFleetData`'s 89 flat stream nodes stayed exactly where
  // they were and 27 feature cards rendered over them. Both plans on one canvas: the maintainer read
  // that as "I'm still seeing the old plan" four times across two days, and every fix in between —
  // the re-mapping, the band, the drill wiring, the missing root, the dropped `feature` field — was
  // real and none of them could have helped, because they made the NEW layer correct while the OLD
  // one kept drawing underneath.
  //
  // A stream a feature owns is reachable by drilling that feature (`featureDrill`), so drawing it
  // flat here says the coarse node is decoration rather than the level you navigate.
  const slugs = new Set(features.map((f) => f.slug));
  // stream id → the feature node standing for it. Also the redirect table below.
  const standsFor = new Map<string, string>();
  for (const s of streams) {
    const f = streamFeature(s);
    if (!slugs.has(f)) continue;
    // TO THE NODE FOR ITS OWN REPO. A spanning feature draws one node per band, so a mobile stream
    // must fold onto the mobile node and a desktop stream onto the desktop one — otherwise the
    // director's `manages` would all land on whichever band happened to be first, and the other band's
    // node would sit there unmanaged.
    const spans = reposOf(streams, f).size > 1;
    const repo = (s.repo ?? "").trim();
    standsFor.set(s.id, featureNodeId(f, spans && repo ? repo : undefined));
  }

  const present = new Set(data.rawNodes.map((n) => n.id));
  const add = nodes.filter((n) => !present.has(n.id));
  // Nothing to add AND nothing to remove ⇒ the graph is already what it should be.
  if (!add.length && !standsFor.size) return data;

  // A stream belonging to NO feature stays drawn. Removing it would hide unassigned work, which is
  // the one thing this view must never do — an unstaffed lane is exactly what a reader is scanning
  // for, and it would vanish with no node to notice it by.
  const keptNodes = data.rawNodes.filter((n) => !standsFor.has(n.id));
  const known = new Set([...keptNodes.map((n) => n.id), ...add.map((n) => n.id)]);

  // THE FEATURE INHERITS THE RELATIONSHIPS OF THE STREAMS IT STANDS FOR — it does not get a fresh
  // edge minted for it.
  //
  // `fleetToOrg` already draws `director manages <stream>` for every stream, through `archOf`, which
  // lets a TEAM author a different archetype for a persona pair. Minting a new `manages` edge here
  // would discard that authored value and quietly disagree with the team graph; redirecting keeps
  // whatever the edge actually said. It also generalises for free — anything that pointed at a
  // stream now points at its feature, without this fold needing to know who or why.
  const redirect = (id: string) => standsFor.get(id) ?? id;
  const rerouted: GRawEdge[] = [];
  const seenPair = new Set<string>();
  for (const e of data.rawEdges) {
    // A STREAM-TO-STREAM EDGE IS NOT A FEATURE-TO-FEATURE FACT, and folding it invents claims the
    // plan never made. MEASURED on studio-code: 208 `dependsOn` edges between streams, ZERO cycles
    // among them — and 20 cycles among features once folded (`cli-platform → cad → cli-platform`,
    // `planner → console → planner`, eighteen more). They flooded the coordination-hazard pane and
    // hid the list behind deadlocks that do not exist.
    //
    // Collapsing a DAG's nodes into groups manufactures cycles: one cli-platform stream depending on
    // a cad stream while some cad stream depends on a cli-platform one is perfectly acyclic at stream
    // level. `featureBand` had already ruled on this — "the band draws no edges between features,
    // `dependsOn` on a feature is a SEQUENCING hint, not a dependency the code has" — and folding
    // every edge reintroduced exactly what that forbids.
    //
    // So only edges from OUTSIDE the covered set fold: the director's `manages` becomes
    // `director manages <feature>`, while a stream's own dependency stays a stream's own business.
    if (standsFor.has(e.from) && standsFor.has(e.to)) continue;
    const from = redirect(e.from);
    const to = redirect(e.to);
    // A stream's own edge to its feature says nothing the containment does not.
    if (from === to) continue;
    if (!known.has(from) || !known.has(to)) continue;
    // N streams under one feature collapse to ONE edge. Twenty parallel `director manages` lines
    // between the same pair is the same fact drawn twenty times.
    const key = `${from}|${to}|${e.kind}`;
    if (seenPair.has(key)) continue;
    seenPair.add(key);
    rerouted.push(
      from === e.from && to === e.to ? e : { ...e, from, to, id: `${e.kind}:${from}>${to}` },
    );
  }

  const seen = new Set(rerouted.map((e) => e.id));
  const addEdges = edges.filter((e) => !seen.has(e.id) && known.has(e.from) && known.has(e.to));
  return { ...data, rawNodes: [...keptNodes, ...add], rawEdges: [...rerouted, ...addEdges] };
}

