// ─────────────────────────────────────────────────────────────────────────────────────────────────
// THE ALGEBRA — ported from `@/features/finance/lib/money`.
//
// The analysis half of this feature was written in TypeScript against a `Money` that CARRIES ITS
// CURRENCY, and the guard that buys is not decorative: `reconcile` refuses a foreign-currency row
// rather than adding it, and `position` excludes a foreign account rather than converting it. A port
// to a bare `i64` would drop both silently, so the currency comes along.
//
// It comes along CHEAPLY. `Currency` is three bytes, `Copy`, and compared by value — no allocation,
// no lifetime, and a mismatch is a compile-time-shaped error rather than a string comparison nobody
// runs.

/// An ISO-4217-shaped code. Three bytes, `Copy`, compared exactly — this module never converts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Currency([u8; 3]);

impl Currency {
    /// Uppercased on the way in, so `usd` and `USD` are the same currency rather than two.
    pub fn new(code: &str) -> Result<Currency, String> {
        let b = code.as_bytes();
        if b.len() != 3 || !b.iter().all(|c| c.is_ascii_alphabetic()) {
            return Err(format!("`{code}` is not a three-letter currency code"));
        }
        Ok(Currency([b[0].to_ascii_uppercase(), b[1].to_ascii_uppercase(), b[2].to_ascii_uppercase()]))
    }

    pub const USD: Currency = Currency(*b"USD");

    pub fn as_str(&self) -> &str {
        std::str::from_utf8(&self.0).unwrap_or("???")
    }
}

impl std::fmt::Display for Currency {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// A signed count of MINOR UNITS, with the currency it is in.
///
/// `0.1 + 0.2 == 0.30000000000000004` is the whole reason this is an integer. In a currency that is
/// not a rounding curiosity: it is a balance that disagrees with itself and a total that fails
/// reconciliation for reasons nobody can see in the numbers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Money {
    pub minor: Minor,
    pub currency: Currency,
}

/// Adding USD to EUR is not a number problem, it is a modelling error — and returning a number would
/// let it travel.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CurrencyMismatch {
    pub left: Currency,
    pub right: Currency,
}

impl std::fmt::Display for CurrencyMismatch {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "cannot combine {} with {} — convert first, explicitly", self.left, self.right)
    }
}

pub fn money(minor: Minor, currency: Currency) -> Money {
    Money { minor, currency }
}

/// USD, for the overwhelmingly common case — named so the assumption is visible at the call site.
pub fn usd(minor: Minor) -> Money {
    Money { minor, currency: Currency::USD }
}

fn same(a: Money, b: Money) -> Result<(), CurrencyMismatch> {
    if a.currency == b.currency {
        Ok(())
    } else {
        Err(CurrencyMismatch { left: a.currency, right: b.currency })
    }
}

pub fn add(a: Money, b: Money) -> Result<Money, CurrencyMismatch> {
    same(a, b)?;
    Ok(Money { minor: a.minor.saturating_add(b.minor), currency: a.currency })
}

pub fn subtract(a: Money, b: Money) -> Result<Money, CurrencyMismatch> {
    same(a, b)?;
    Ok(Money { minor: a.minor.saturating_sub(b.minor), currency: a.currency })
}

pub fn negate(m: Money) -> Money {
    Money { minor: -m.minor, currency: m.currency }
}

pub fn is_zero(m: Money) -> bool {
    m.minor == 0
}

pub fn is_negative(m: Money) -> bool {
    m.minor < 0
}

/// Total a list. The CURRENCY IS PASSED IN rather than taken from the first element, so an EMPTY
/// list has an answer — and a list that turns out to be mixed is an error rather than a total in
/// whichever currency happened to come first.
pub fn sum(items: &[Money], currency: Currency) -> Result<Money, CurrencyMismatch> {
    let mut total: Minor = 0;
    for m in items {
        if m.currency != currency {
            return Err(CurrencyMismatch { left: currency, right: m.currency });
        }
        total = total.saturating_add(m.minor);
    }
    Ok(Money { minor: total, currency })
}

/// How a fraction of a minor unit is resolved. STATED, never inherited from whatever a float did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Rounding {
    HalfUp,
    HalfEven,
    Down,
    Up,
}

/// Apply a rate, rounding EXACTLY ONCE and in a way the caller chose.
///
/// The rate is a float because a rate genuinely is fractional; what matters is that the RESULT is an
/// integer and that the rounding is a decision rather than an accident.
pub fn scale(m: Money, rate: f64, rounding: Rounding) -> Money {
    Money { minor: round(m.minor as f64 * rate, rounding), currency: m.currency }
}

/// The rounding itself, and EVERY MODE HERE IS SYMMETRIC ABOUT ZERO.
///
/// That is the whole subtlety, and it is where a hand-port silently diverges. `half-up` means away
/// from zero, so −2.5 goes to −3 exactly as 2.5 goes to 3; `down` means toward zero (truncate), not
/// toward −∞; `up` means away from zero, not toward +∞. Using `floor`/`ceil` directly gets all three
/// backwards on negatives — and half the amounts in this feature are negative by the sign contract,
/// so it would be wrong on the common case rather than an edge one.
fn round(x: f64, mode: Rounding) -> Minor {
    let r = match mode {
        Rounding::Down => x.trunc(),
        Rounding::Up => {
            if x < 0.0 { x.floor() } else { x.ceil() }
        }
        Rounding::HalfEven => {
            // Banker's rounding — ties go to the EVEN neighbour, so a long series of .5 cases does
            // not drift upward the way half-up does. Written as one condition rather than a ladder
            // because two of the ladder's arms returned the same value.
            let f = x.floor();
            let diff = x - f;
            if diff > 0.5 || (diff == 0.5 && (f as i64) % 2 != 0) { f + 1.0 } else { f }
        }
        Rounding::HalfUp => {
            if x < 0.0 { -(-x).round() } else { x.round() }
        }
    };
    r as Minor
}

/// Split by weights so that the parts SUM EXACTLY BACK to the whole.
///
/// Largest-remainder: floor every share, then hand the leftover minor units out one at a time to
/// whoever was cut hardest. Rounding each share independently loses or invents money — a cent that
/// vanishes here is a reconciliation failure three modules away, with nothing to point at.
pub fn allocate(m: Money, weights: &[i64]) -> Result<Vec<Money>, String> {
    if weights.is_empty() {
        return Err("allocate needs at least one weight".to_string());
    }
    if weights.iter().any(|w| *w < 0) {
        return Err("allocate weights must be non-negative".to_string());
    }
    let total: i64 = weights.iter().sum();
    if total <= 0 {
        return Err("allocate weights must sum to more than zero".to_string());
    }

    // WORK ON THE MAGNITUDE, so a negative amount splits as the mirror of its positive twin rather
    // than having the remainder pushed the other way by flooring toward −∞.
    let sign: Minor = if m.minor < 0 { -1 } else { 1 };
    let magnitude = m.minor.abs();
    let mut shares: Vec<Minor> = weights.iter().map(|w| magnitude * w / total).collect();
    let mut remainder = magnitude - shares.iter().sum::<Minor>();
    let mut i = 0;
    while remainder > 0 {
        shares[i] += 1;
        remainder -= 1;
        i = (i + 1) % shares.len();
    }

    Ok(shares.into_iter().map(|s| Money { minor: sign * s, currency: m.currency }).collect())
}

/// `n` equal parts, losing nothing — the common case of {@link allocate}.
pub fn split(m: Money, n: usize) -> Result<Vec<Money>, String> {
    allocate(m, &vec![1; n])
}

#[cfg(test)]
mod tests {

    // ── the algebra, ported from money.ts ─────────────────────────────────────────────────────────

    fn eur() -> Currency {
        Currency::new("EUR").unwrap()
    }

    #[test]
    fn a_currency_is_three_letters_and_case_does_not_make_a_second_one() {
        assert_eq!(Currency::new("usd").unwrap(), Currency::USD);
        assert_eq!(Currency::USD.as_str(), "USD");
        for bad in ["US", "USDD", "US1", ""] {
            assert!(Currency::new(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn adding_two_currencies_is_refused_rather_than_returning_a_number() {
        // Not a number problem — a modelling error, and returning a number would let it travel.
        let e = add(usd(100), money(100, eur())).unwrap_err();
        assert_eq!(e.left, Currency::USD);
        assert!(e.to_string().contains("convert first, explicitly"));
        assert!(subtract(usd(100), money(100, eur())).is_err());
    }

    #[test]
    fn the_ordinary_arithmetic_holds() {
        assert_eq!(add(usd(100), usd(250)).unwrap().minor, 350);
        assert_eq!(subtract(usd(100), usd(250)).unwrap().minor, -150);
        assert_eq!(negate(usd(100)).minor, -100);
        assert!(is_zero(usd(0)));
        assert!(is_negative(usd(-1)));
        assert!(!is_negative(usd(0)));
    }

    #[test]
    fn sum_takes_its_currency_so_an_empty_list_still_has_an_answer() {
        // Taking it from the first element would leave an empty list with no currency at all, and a
        // mixed list with whichever one happened to come first.
        assert_eq!(sum(&[], Currency::USD).unwrap().minor, 0);
        assert_eq!(sum(&[usd(100), usd(-40)], Currency::USD).unwrap().minor, 60);
        assert!(sum(&[usd(100), money(1, eur())], Currency::USD).is_err());
    }

    #[test]
    fn rounding_is_a_decision_and_each_mode_actually_differs() {
        // 2.5 is the tie every mode disagrees about, which is why it is the one worth pinning.
        assert_eq!(scale(usd(5), 0.5, Rounding::HalfUp).minor, 3);
        assert_eq!(scale(usd(5), 0.5, Rounding::Down).minor, 2);
        assert_eq!(scale(usd(5), 0.5, Rounding::Up).minor, 3);
        // Banker's rounding sends a tie to the EVEN neighbour: 2.5 -> 2, 3.5 -> 4.
        assert_eq!(scale(usd(5), 0.5, Rounding::HalfEven).minor, 2);
        assert_eq!(scale(usd(7), 0.5, Rounding::HalfEven).minor, 4);
    }

    #[test]
    fn every_rounding_mode_is_symmetric_about_zero() {
        // THE CASE A HAND-PORT GETS WRONG, and it is not an edge case here: half the amounts in this
        // feature are negative by the sign contract, so `floor`/`ceil` instead of trunc/away-from-
        // zero would be wrong on the COMMON path. Pinned against the TypeScript these came from.
        for (mode, pos, neg) in [
            (Rounding::HalfUp, 3, -3),
            (Rounding::Down, 2, -2),
            (Rounding::Up, 3, -3),
        ] {
            assert_eq!(scale(usd(5), 0.5, mode).minor, pos, "{mode:?} positive");
            assert_eq!(scale(usd(-5), 0.5, mode).minor, neg, "{mode:?} negative");
        }
    }

    #[test]
    fn scale_keeps_the_currency_and_handles_a_negative() {
        let m = scale(money(-1000, eur()), 0.25, Rounding::HalfUp);
        assert_eq!(m.currency, eur());
        assert_eq!(m.minor, -250);
    }

    #[test]
    fn allocate_loses_nothing_however_awkward_the_split() {
        // The whole point. Rounding each share independently loses or invents money, and a cent that
        // vanishes here is a reconciliation failure three modules away with nothing to point at.
        for total in [100, 101, 1, 999_983, -100, -7] {
            for weights in [vec![1, 1, 1], vec![1, 2, 3], vec![7, 1], vec![1]] {
                let parts = allocate(usd(total), &weights).unwrap();
                let back: i64 = parts.iter().map(|p| p.minor).sum();
                assert_eq!(back, total, "total {total} weights {weights:?} -> {parts:?}");
                assert_eq!(parts.len(), weights.len());
            }
        }
    }

    #[test]
    fn allocate_hands_the_remainder_out_from_the_front_and_mirrors_on_a_negative() {
        // Both halves are behaviour the TypeScript defines, not choices made here: the remainder
        // goes round-robin from index 0, and a negative splits as the mirror of its positive twin.
        let pos: Vec<i64> = allocate(usd(100), &[1, 1, 1]).unwrap().iter().map(|p| p.minor).collect();
        assert_eq!(pos, [34, 33, 33]);
        let neg: Vec<i64> = allocate(usd(-100), &[1, 1, 1]).unwrap().iter().map(|p| p.minor).collect();
        assert_eq!(neg, [-34, -33, -33]);
    }

    /// EVERY VALUE BELOW WAS TAKEN FROM THE TYPESCRIPT, by transpiling
    /// `@/features/finance/lib/money` and running it — not by reading it and reasoning about what it
    /// probably does. Reading it is how the first version of this port ended up with FOUR
    /// divergences, all of them on negatives, all of them silent: `half-up` rounding toward +∞
    /// instead of away from zero, `down` flooring instead of truncating, `up` ceiling instead of
    /// going away from zero, and `allocate` distributing by largest remainder instead of round-robin
    /// over the magnitude.
    ///
    /// Half the amounts in this feature are negative by the sign contract, so those were not edge
    /// cases — they were the common path. This table is what stops the two kits drifting again.
    #[test]
    fn the_port_matches_the_typescript_value_for_value() {
        let cases: &[(Rounding, i64, i64)] = &[
            (Rounding::HalfUp, 5, 3),
            (Rounding::HalfUp, -5, -3),
            (Rounding::HalfUp, 7, 4),
            (Rounding::HalfUp, -7, -4),
            (Rounding::HalfUp, 3, 2),
            (Rounding::HalfUp, -3, -2),
            (Rounding::Down, 5, 2),
            (Rounding::Down, -5, -2),
            (Rounding::Down, 7, 3),
            (Rounding::Down, -7, -3),
            (Rounding::Down, 3, 1),
            (Rounding::Down, -3, -1),
            (Rounding::Up, 5, 3),
            (Rounding::Up, -5, -3),
            (Rounding::Up, 7, 4),
            (Rounding::Up, -7, -4),
            (Rounding::Up, 3, 2),
            (Rounding::Up, -3, -2),
            (Rounding::HalfEven, 5, 2),
            (Rounding::HalfEven, -5, -2),
            (Rounding::HalfEven, 7, 4),
            (Rounding::HalfEven, -7, -4),
            (Rounding::HalfEven, 3, 2),
            (Rounding::HalfEven, -3, -2),
        ];
        for (mode, input, expected) in cases {
            assert_eq!(
                scale(usd(*input), 0.5, *mode).minor,
                *expected,
                "scale({input}, 0.5, {mode:?}) — the TypeScript says {expected}"
            );
        }

        let splits: &[(i64, &[i64], &[i64])] = &[
            (100, &[1, 1, 1], &[34, 33, 33]),
            (-100, &[1, 1, 1], &[-34, -33, -33]),
            (100, &[1, 2, 3], &[17, 33, 50]),
            (-7, &[1, 1], &[-4, -3]),
            (101, &[7, 1], &[89, 12]),
        ];
        for (amount, weights, expected) in splits {
            let got: Vec<i64> = allocate(usd(*amount), weights).unwrap().iter().map(|m| m.minor).collect();
            assert_eq!(got, *expected, "allocate({amount}, {weights:?}) — the TypeScript says {expected:?}");
        }
    }

    #[test]
    fn allocate_refuses_what_is_not_a_split() {
        assert!(allocate(usd(100), &[]).is_err());
        assert!(allocate(usd(100), &[0, 0]).is_err());
        assert!(allocate(usd(100), &[-1, 2]).is_err());
    }

    #[test]
    fn split_is_allocate_with_equal_weights_and_still_loses_nothing() {
        let parts = split(usd(100), 3).unwrap();
        assert_eq!(parts.iter().map(|p| p.minor).sum::<i64>(), 100);
        assert_eq!(split(usd(-100), 7).unwrap().iter().map(|p| p.minor).sum::<i64>(), -100);
    }

    use super::*;

    /// EVERY FIXTURE HERE IS SYNTHETIC. No real statement, balance or account number belongs in this
    /// repo — the maintainer's data stays on the maintainer's machine, which is the whole premise of
    /// this crate.
    #[test]
    fn reads_the_shapes_statements_actually_print() {
        assert_eq!(parse_minor("1234.56").unwrap(), 123456);
        assert_eq!(parse_minor("$1,234.56").unwrap(), 123456);
        assert_eq!(parse_minor("-1234.56").unwrap(), -123456);
        assert_eq!(parse_minor("  1234.56  ").unwrap(), 123456);
        // Whole units with no decimal part at all.
        assert_eq!(parse_minor("1234").unwrap(), 123400);
        // One decimal digit means TENTHS, not hundredths — `1234.5` is $1234.50, not $12.345.
        assert_eq!(parse_minor("1234.5").unwrap(), 123450);
    }

    #[test]
    fn honours_both_negative_conventions() {
        // Accounting parentheses and a TRAILING sign are both real. Reading either as a stray
        // character would flip a refund into a charge, and the balance would be wrong by twice it.
        assert_eq!(parse_minor("(1234.56)").unwrap(), -123456);
        assert_eq!(parse_minor("1234.56-").unwrap(), -123456);
        assert_eq!(parse_minor("($1,234.56)").unwrap(), -123456);
    }

    #[test]
    fn is_exact_where_a_float_would_not_be() {
        // `"0.07".parse::<f64>() * 100.0` is 7.000000000000001. Reading the fraction as an integer
        // makes the value exact by construction rather than by luck at the rounding boundary.
        assert_eq!(parse_minor("0.07").unwrap(), 7);
        assert_eq!(parse_minor("0.29").unwrap(), 29);
        assert_eq!(parse_minor("1.10").unwrap(), 110);
        for cents in 0..100 {
            let s = format!("0.{cents:02}");
            assert_eq!(parse_minor(&s).unwrap(), cents, "{s} must be exact");
        }
    }

    #[test]
    fn truncates_a_third_decimal_rather_than_inventing_a_cent() {
        // A statement printing three decimals has a sub-cent artifact. Rounding it up would put a
        // figure in the store that is not on the statement, and reconciliation would fail against
        // the source rather than against the arithmetic.
        assert_eq!(parse_minor("1.999").unwrap(), 199);
        assert_eq!(parse_minor("-1.999").unwrap(), -199);
    }

    #[test]
    fn refuses_what_it_cannot_read_rather_than_guessing() {
        // A row that silently becomes zero is a missing transaction, which is a wrong balance that
        // nobody can find. Every one of these must be reported to the caller.
        assert!(parse_minor("").is_err());
        assert!(parse_minor("   ").is_err());
        assert!(parse_minor("N/A").is_err());
        assert!(parse_minor("--").is_err());
        assert!(parse_minor("1.2.3").is_err());
        assert!(parse_minor("12 34 abc").is_err());
    }

    #[test]
    fn round_trips_through_display() {
        for v in [0i64, 7, -7, 100, -100, 123456, -123456, 999999999] {
            assert_eq!(parse_minor(&format_minor(v)).unwrap(), v, "{v}");
        }
        assert_eq!(format_minor(-7), "-0.07");
        assert_eq!(format_minor(123456), "1234.56");
    }
}

tests.src:
//! Statement ingest — read what a bank exports, without asking anyone what it is.
//!
//! THE INSTITUTION IS INFERRED FROM THE HEADER ROW, never from a flag. Partly because a flag is one
//! more thing to get wrong, and partly for a reason particular to this crate: the less the tool has
//! to be told about someone's accounts, the less of someone's accounts has to be said out loud.
//!
//! # The one contract every profile normalises to
//!
//! **A stored amount is signed from the ACCOUNT HOLDER's point of view: negative is money leaving.**
//!
//! That is not how the exports are written, and they disagree with each other, which is exactly why
//! this has to be stated once and enforced per profile:
//!
//! - Chase writes a purchase NEGATIVE.
//! - Discover writes a purchase POSITIVE — a charge is a positive number on the card's own terms.
//! - Capital One does not sign at all: it uses separate `Debit` and `Credit` columns.
//! - Bank of America signs like Chase, but its checking and card exports carry different columns.
//!
//! Get one of these backwards and every balance built on it is wrong by twice the amount, in the
//! direction that looks like good news. So the sign rule is per profile, named, and tested.
//!
//! # Nothing is dropped quietly
//!
//! A row that cannot be read is REPORTED, never skipped. A missing transaction is a wrong balance
//! that nobody can find by looking at the balance.
use crate::money::{parse_minor, Minor};

/// Which export this is. `Unknown` is a first-class outcome: a header nobody recognises should say so
/// rather than be forced through the closest-looking profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Institution {
    Chase,
    Discover,
    CapitalOne,
    BankOfAmerica,
    Unknown,
}

impl Institution {
    pub fn name(self) -> &'static str {
        match self {
            Institution::Chase => "chase",
            Institution::Discover => "discover",
            Institution::CapitalOne => "capital-one",
            Institution::BankOfAmerica => "bank-of-america",
            Institution::Unknown => "unknown",
        }
    }
}

/// How one export lays its columns out, and which way its amounts point.
#[derive(Debug, Clone)]
pub struct Profile {
    pub institution: Institution,
    /// Human label for the report — which export shape matched.
    pub label: &'static str,
    /// Header names that must ALL be present for this profile to match, lowercased.
    pub required: &'static [&'static str],
    pub date: &'static str,
    pub description: &'static str,
    /// A single signed amount column…
    pub amount: Option<&'static str>,
    /// …or a separate debit/credit pair, which is Capital One's shape.
    pub debit_credit: Option<(&'static str, &'static str)>,
    /// TRUE when the export writes a purchase as a POSITIVE number, so the sign must be flipped to
    /// reach "negative is money leaving". Discover is the case this exists for.
    pub charge_is_positive: bool,
}

/// The known export shapes.
///
/// DATA, not code, and deliberately: verifying these against a real export is a one-line correction
/// rather than a patch to a parser. They are written from published formats and SHOULD be checked
/// against an actual download before anyone trusts a balance built on them.
pub const PROFILES: &[Profile] = &[
    Profile {
        institution: Institution::CapitalOne,
        label: "capital-one (debit/credit columns)",
        required: &["transaction date", "description", "debit", "credit"],
        date: "transaction date",
        description: "description",
        amount: None,
        debit_credit: Some(("debit", "credit")),
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::Discover,
        label: "discover (charge positive)",
        required: &["trans. date", "description", "amount"],
        date: "trans. date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        // A charge is written POSITIVE. Without this flip every purchase would read as income.
        charge_is_positive: true,
    },
    Profile {
        institution: Institution::Chase,
        label: "chase card",
        required: &["transaction date", "post date", "description", "amount"],
        date: "transaction date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::Chase,
        label: "chase checking",
        required: &["posting date", "description", "amount"],
        date: "posting date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::BankOfAmerica,
        label: "bank-of-america card",
        required: &["posted date", "payee", "amount"],
        date: "posted date",
        description: "payee",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::BankOfAmerica,
        label: "bank-of-america checking",
        required: &["date", "description", "amount", "running bal."],
        date: "date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
];

/// One transaction, normalised.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Txn {
    /// As written in the export. Not reformatted here — normalising a date is a separate decision
    /// from reading one, and guessing between `01/02` conventions silently is how a year goes wrong.
    pub date: String,
    pub description: String,
    /// Minor units, NEGATIVE for money leaving the account holder.
    pub minor: Minor,
}

/// A row that could not be read, and why. Carried out rather than logged, so the caller decides.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rejected {
    /// 1-based line number in the file, counting the header — what a person would see in an editor.
    pub line: usize,
    pub reason: String,
}

#[derive(Debug, Clone)]
pub struct Parsed {
    pub institution: Institution,
    pub profile: &'static str,
    pub txns: Vec<Txn>,
    pub rejected: Vec<Rejected>,
}

/// Split ONE csv line, honouring quoted fields.
///
/// A description containing a comma is not exotic — it is most of them ("SQUARE, INC"). Splitting on
/// every comma would shift every later column by one and put a date where an amount goes.
fn split_csv(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quoted = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' if quoted && chars.peek() == Some(&'"') => {
                cur.push('"');
                chars.next();
            }
            '"' => quoted = !quoted,
            ',' if !quoted => out.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    out.push(cur);
    out.into_iter().map(|s| s.trim().to_string()).collect()
}

/// The profile whose required columns are all present. Most specific first — `PROFILES` is ordered so
/// a shape with more required columns is tried before a looser one it would also satisfy.
pub fn detect(header: &[String]) -> Option<&'static Profile> {
    let have: Vec<String> = header.iter().map(|h| h.trim().to_lowercase()).collect();
    PROFILES.iter().find(|p| p.required.iter().all(|r| have.iter().any(|h| h == r)))
}

/// Parse a whole CSV export.
pub fn parse_csv(text: &str) -> Result<Parsed, String> {
    let mut lines = text.lines().enumerate().filter(|(_, l)| !l.trim().is_empty());
    let (header_line, header_raw) = lines.next().ok_or_else(|| "the file is empty".to_string())?;
    let header = split_csv(header_raw);
    let profile = detect(&header).ok_or_else(|| {
        format!(
            "no known export shape matches this header: [{}]. Add a Profile for it rather than \
             forcing it through the closest one — a mis-mapped column reads as a plausible number.",
            header.join(", ")
        )
    })?;

    let col = |name: &str| header.iter().position(|h| h.trim().eq_ignore_ascii_case(name));
    let (di, ci) = (col(profile.date), col(profile.description));
    let (Some(di), Some(ci)) = (di, ci) else {
        return Err(format!("{}: the header lost a column between detection and read", profile.label));
    };

    let mut txns = Vec::new();
    let mut rejected = Vec::new();
    for (idx, raw) in lines {
        let line = idx + 1; // 1-based, as an editor shows it
        let f = split_csv(raw);
        let get = |i: usize| f.get(i).map(String::as_str).unwrap_or("").trim();
        if f.len() < header.len() {
            rejected.push(Rejected { line, reason: format!("{} columns, expected {}", f.len(), header.len()) });
            continue;
        }
        let minor = match (profile.amount, profile.debit_credit) {
            (Some(a), _) => {
                let Some(ai) = col(a) else {
                    rejected.push(Rejected { line, reason: format!("no `{a}` column") });
                    continue;
                };
                match parse_minor(get(ai)) {
                    Ok(v) => {
                        // Discover's convention: a charge is written positive. Flip so the store's
                        // rule holds — negative is money leaving.
                        if profile.charge_is_positive { -v } else { v }
                    }
                    Err(e) => {
                        rejected.push(Rejected { line, reason: e });
                        continue;
                    }
                }
            }
            (None, Some((d, c))) => {
                // Capital One: exactly one of the two carries a value. Both, or neither, is a row
                // this parser does not understand — and guessing which to believe would be inventing
                // a transaction.
                let (Some(dbi), Some(cri)) = (col(d), col(c)) else {
                    rejected.push(Rejected { line, reason: format!("no `{d}`/`{c}` columns") });
                    continue;
                };
                let (dv, cv) = (get(dbi), get(cri));
                match (dv.is_empty(), cv.is_empty()) {
                    (false, true) => match parse_minor(dv) {
                        Ok(v) => -v.abs(), // a debit is money leaving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, false) => match parse_minor(cv) {
                        Ok(v) => v.abs(), // a credit is money arriving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, true) => { rejected.push(Rejected { line, reason: "neither debit nor credit has a value".into() }); continue; }
                    (false, false) => { rejected.push(Rejected { line, reason: "both debit and credit have values".into() }); continue; }
                }
            }
            (None, None) => return Err(format!("{}: profile declares no amount column", profile.label)),
        };
        let date = get(di).to_string();
        if date.is_empty() {
            rejected.push(Rejected { line, reason: "no date".into() });
            continue;
        }
        txns.push(Txn { date, description: get(ci).to_string(), minor });
    }
    let _ = header_line;
    Ok(Parsed { institution: profile.institution, profile: profile.label, txns, rejected })
}

#[cfg(test)]
mod tests {
    use super::*;

    // EVERY FIXTURE IS SYNTHETIC — invented merchants, round-ish amounts, no account numbers. The
    // maintainer's statements never enter this repo, and a test that needed a real one would be
    // telling us the design is wrong.

    #[test]
    fn a_quoted_comma_does_not_shift_every_later_column() {
        // "SQUARE, INC" is most descriptions, not an exotic case. Splitting on every comma puts a
        // date where an amount goes, and the row still parses — as a plausible wrong number.
        let f = split_csv(r#"01/02/2026,"SQUARE, INC",-12.34"#);
        assert_eq!(f, vec!["01/02/2026", "SQUARE, INC", "-12.34"]);
        assert_eq!(split_csv(r#""a""b",c"#), vec![r#"a"b"#, "c"]);
    }

    #[test]
    fn chase_a_purchase_is_money_leaving() {
        let csv = "Transaction Date,Post Date,Description,Category,Type,Amount,Memo\n\
                   01/02/2026,01/03/2026,COFFEE BAR,Food,Sale,-4.50,\n\
                   01/04/2026,01/05/2026,PAYMENT THANK YOU,,Payment,250.00,\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::Chase);
        assert_eq!(p.txns[0].minor, -450, "a purchase must be negative");
        assert_eq!(p.txns[1].minor, 25000, "a payment to the card is money arriving on it");
        assert!(p.rejected.is_empty());
    }

    #[test]
    fn discover_writes_a_charge_positive_and_it_is_flipped() {
        // THE SIGN BUG THIS FILE EXISTS FOR. Without the flip every Discover purchase reads as
        // income, and the balance is wrong by twice the amount in the direction that looks like good
        // news — which is the direction nobody double-checks.
        let csv = "Trans. Date,Post Date,Description,Amount,Category\n\
                   01/02/2026,01/03/2026,HARDWARE STORE,89.99,Merchandise\n\
                   01/06/2026,01/06/2026,DIRECTPAY FULL BALANCE,-200.00,Payments\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::Discover);
        assert_eq!(p.txns[0].minor, -8999, "a Discover charge is written positive and must flip");
        assert_eq!(p.txns[1].minor, 20000, "and a payment flips the other way");
    }

    #[test]
    fn capital_one_uses_separate_debit_and_credit_columns() {
        let csv = "Transaction Date,Posted Date,Card No.,Description,Category,Debit,Credit\n\
                   2026-01-02,2026-01-03,1234,GROCERY,Merchandise,54.20,\n\
                   2026-01-05,2026-01-06,1234,CREDIT BALANCE REFUND,Other,,15.00\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::CapitalOne);
        assert_eq!(p.txns[0].minor, -5420, "a debit is money leaving");
        assert_eq!(p.txns[1].minor, 1500, "a credit is money arriving");
    }

    #[test]
    fn capital_one_refuses_a_row_that_fills_both_or_neither() {
        // Guessing which column to believe would be inventing a transaction.
        let csv = "Transaction Date,Posted Date,Card No.,Description,Category,Debit,Credit\n\
                   2026-01-02,2026-01-03,1234,BOTH,Other,10.00,10.00\n\
                   2026-01-04,2026-01-05,1234,NEITHER,Other,,\n";
        let p = parse_csv(csv).unwrap();
        assert!(p.txns.is_empty());
        assert_eq!(p.rejected.len(), 2);
        assert!(p.rejected[0].reason.contains("both"));
        assert!(p.rejected[1].reason.contains("neither"));
    }

    #[test]
    fn bank_of_america_checking_and_card_are_different_shapes() {
        let checking = "Date,Description,Amount,Running Bal.\n01/02/2026,RENT,-1450.00,3210.55\n";
        assert_eq!(parse_csv(checking).unwrap().institution, Institution::BankOfAmerica);
        let card = "Posted Date,Reference Number,Payee,Address,Amount\n01/02/2026,000123,PHARMACY,,-23.40\n";
        let p = parse_csv(card).unwrap();
        assert_eq!(p.institution, Institution::BankOfAmerica);
        assert_eq!(p.txns[0].description, "PHARMACY", "the card export calls it Payee, not Description");
    }

    #[test]
    fn an_unreadable_row_is_reported_not_dropped() {
        // A row that silently vanishes is a wrong balance nobody can find by looking at the balance.
        let csv = "Transaction Date,Post Date,Description,Category,Type,Amount,Memo\n\
                   01/02/2026,01/03/2026,GOOD,Food,Sale,-4.50,\n\
                   01/04/2026,01/05/2026,BAD AMOUNT,Food,Sale,N/A,\n\
                   ,01/06/2026,NO DATE,Food,Sale,-1.00,\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.txns.len(), 1);
        assert_eq!(p.rejected.len(), 2);
        // The line number is what a person would see in an editor, header included.
        assert_eq!(p.rejected[0].line, 3);
        assert_eq!(p.rejected[1].line, 4);
    }

    #[test]
    fn an_unknown_header_says_so_rather_than_guessing() {
        // Forcing an unrecognised export through the closest-looking profile produces numbers that
        // are wrong and plausible, which is the worst combination available.
        let err = parse_csv("Foo,Bar,Baz\n1,2,3\n").unwrap_err();
        assert!(err.contains("no known export shape"), "{err}");
        assert!(err.contains("Foo"), "the error must show the header it could not place");
    }

    #[test]
    fn every_profile_is_reachable_and_distinct() {
        // A profile no header can select is dead configuration that reads as coverage. Each one's own
        // required columns must select IT — if a looser profile shadows a stricter one, ordering is
        // wrong and some institution silently parses as another.
        for p in PROFILES {
            let header: Vec<String> = p.required.iter().map(|s| s.to_string()).collect();
            let got = detect(&header).unwrap_or_else(|| panic!("{} matches no profile", p.label));
            assert_eq!(got.label, p.label, "{} is shadowed by {}", p.label, got.label);
        }
    }

    #[test]
    fn the_empty_file_is_an_error_not_an_empty_statement() {
        // An empty result would read as "this account had no activity", which is a different claim.
        assert!(parse_csv("").is_err());
        assert!(parse_csv("   \n\n").is_err());
    }
}

