    #[test]
    fn the_hurdle_report_states_the_expectation_is_yours_and_names_its_source() {
        let (e, debts) = hurdle_fixture();
        let b = hurdle::buffer(crate::money::usd(600_000), crate::money::usd(200_000), 3).expect("valid");
        let l = hurdle::ladder(&debts, &e).expect("valid");
        let out = render_hurdle(&e, &b, &l, &hurdle::next_dollar(&b, &l), "2026-09-05");

        assert!(out.contains("YOUR number and not this tool's"), "{out}");
        assert!(out.contains("long-run index return, my own reading"), "the provenance is printed, not just stored: {out}");
        // A zero risk premium is CALLED OUT rather than passing as a considered choice.
        assert!(out.contains("treats a CERTAIN return and an uncertain one as equal"), "{out}");
        // The gross-up is visible: 24.99% tax-free needs 33.32% pre-tax.
        assert!(out.contains("24.99%") && out.contains("33.32%"), "{out}");
        // And the unknown rate is named as unknown, never as a number.
        assert!(out.contains("RATE UNKNOWN"), "{out}");
        assert!(!out.contains("mystery      1000.00     0.00%"), "an unknown rate must never render as 0%: {out}");
    }

    #[test]
    fn the_recommendation_is_last_and_the_buffer_outranks_a_twentyfive_percent_card() {
        let (e, debts) = hurdle_fixture();
        // 0.6 months held against a 3-month target, with a 24.99% card outstanding.
        let short = hurdle::buffer(crate::money::usd(120_000), crate::money::usd(200_000), 3).expect("valid");
        let l = hurdle::ladder(&debts, &e).expect("valid");
        let out = render_hurdle(&e, &short, &l, &hurdle::next_dollar(&short, &l), "2026-09-05");

        assert!(out.contains("SHORT by 4800.00"), "{out}");
        assert!(out.contains("0.6 months"), "{out}");
        assert!(out.contains("NEXT DOLLAR → build the buffer"), "even against a 24.99% card: {out}");
        assert!(out.contains("pay it down and borrow it again"), "the reason must travel with the instruction: {out}");
        // The recommendation comes AFTER the numbers that justify it.
        let ladder_at = out.find("What each debt demands").expect("ladder");
        let next_at = out.find("NEXT DOLLAR").expect("recommendation");
        assert!(ladder_at < next_at, "the recommendation only means something after the numbers above it");
    }

