    }

    #[test]
    fn claiming_a_file_takes_it_out_of_the_inbox_so_it_cannot_be_read_twice() {
        // Reading the same statement again does not error. It doubles a month of spending and every
        // number stays perfectly plausible, which is why the move is the mechanism.
        let inbox = Tmp::new("claim-in");
        let done = Tmp::new("claim-out");
        let f = inbox.file("chase-2026-07.csv", "a,b\n");
        assert_eq!(scan(&inbox.0).unwrap().len(), 1);

        let dest = claim(&f, &done.0, "2026-07-01T12:00:00Z").unwrap();
        assert!(dest.exists());
        assert!(!f.exists());
        assert_eq!(scan(&inbox.0).unwrap().len(), 0);
    }

    #[test]
    fn a_claim_never_overwrites_an_earlier_one() {
        // Two exports that happen to share a name both survive. Losing the evidence of what was taken
        // in is worse than an ugly filename.
        let inbox = Tmp::new("dup-in");
        let done = Tmp::new("dup-out");
        let at = "2026-07-01T12:00:00Z";

        let first = claim(&inbox.file("chase.csv", "one"), &done.0, at).unwrap();
        let second = claim(&inbox.file("chase.csv", "two"), &done.0, at).unwrap();
        assert_ne!(first, second);
        assert_eq!(std::fs::read_to_string(&first).unwrap(), "one");
        assert_eq!(std::fs::read_to_string(&second).unwrap(), "two");
    }

    #[test]
    fn the_claim_name_carries_when_rather_than_trusting_the_filesystem() {
        // A copy across a filesystem resets mtime, and when a statement was taken in is the one
        // question anybody asks of `processed/`.
        let inbox = Tmp::new("stamp-in");
        let done = Tmp::new("stamp-out");
        let dest = claim(&inbox.file("chase-2026-07.csv", "x"), &done.0, "2026-07-01T12:00:00Z").unwrap();
        let name = dest.file_name().unwrap().to_string_lossy().to_string();
        assert!(name.starts_with("20260701T120000Z-"), "{name}");
        assert!(name.ends_with(".csv"), "{name}");
        assert!(name.contains("chase-2026-07"), "{name}");
    }

    #[test]
    fn claiming_creates_the_processed_directory_rather_than_failing() {
        let inbox = Tmp::new("mkdir-in");
        let parent = Tmp::new("mkdir-out");
        let nested = parent.0.join("a").join("b");
        let dest = claim(&inbox.file("chase.csv", "x"), &nested, "2026-07-01T12:00:00Z").unwrap();
        assert!(dest.exists());
    }

    #[test]
    fn claiming_something_that_is_not_there_is_an_error_naming_it() {
        let done = Tmp::new("gone-out");
        let missing = std::env::temp_dir().join("bsc-fin-not-a-file-xyz.csv");
        let _ = std::fs::remove_file(&missing);
        let e = claim(&missing, &done.0, "2026-07-01T12:00:00Z").unwrap_err();
        assert!(e.contains("bsc-fin-not-a-file-xyz.csv"), "{e}");
    }

    #[test]
    fn every_known_institution_is_one_the_statement_profiles_can_read() {
        // A name this accepts and the parser then rejects would be a promise the next step breaks.
        for id in KNOWN {
            assert!(institution_from_name(&format!("{id}-2026-07.csv")).is_some(), "{id}");
        }
        assert_eq!(KNOWN.len(), 4);
    }
}

//! The account registry — and, more usefully, what it CANNOT tell you.
//!
//! `position` needs to know what each account IS before a balance means anything: whether a positive
//! number is money you have or money you owe, what the credit limit is, what rate it carries. None of
//! that is in a statement export, and until now nothing recorded it — so the analysis existed and had
//! no way to be handed the one thing it needed.
//!
//! # The half that matters to an agent is `gaps`
//!
//! A session driving these systems cannot see a screen. It needs to know not just what is stored but
//! WHAT IS MISSING AND WHAT THAT COSTS — that an absent APR is why there is no interest figure, that
//! an absent credit limit is why utilisation is silent. A registry that only answered "here is what I
//! have" would leave the agent guessing at why a downstream number never appeared, and guessing is
//! how a default gets invented.
//!
//! So every gap names the capability it blocks. That is the difference between a store and an
//! instrument.
//!
//! # An account NUMBER never enters this
//!
//! Refused at any depth, the same way `bsc secret set` refuses a secret-bearing key. The registry
//! needs to know that an account is a credit card at 24.99% with a $5,000 limit; it never needs the
//! digits, and a store that accepts them becomes a file worth stealing.
use std::collections::BTreeMap;

/// What kind of thing an account is — which decides whether a positive balance is held or owed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Kind {
    Checking,
    Savings,
    Credit,
    Loan,
    Investment,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::Checking => "checking",
            Kind::Savings => "savings",
            Kind::Credit => "credit",
            Kind::Loan => "loan",
            Kind::Investment => "investment",
        }
    }

    pub fn parse(s: &str) -> Option<Kind> {
        Some(match s {
            "checking" => Kind::Checking,
            "savings" => Kind::Savings,
            "credit" => Kind::Credit,
            "loan" => Kind::Loan,
            "investment" => Kind::Investment,
            _ => return None,
        })
    }

    /// True where a positive printed balance means money you OWE.
    pub fn is_debt(self) -> bool {
        matches!(self, Kind::Credit | Kind::Loan)
    }

    /// True where it can pay a bill this week. An investment cannot.
    pub fn is_liquid(self) -> bool {
        matches!(self, Kind::Checking | Kind::Savings)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Account {
    /// The key everything else joins on — and the name a statement file starts with.
    pub id: String,
    pub institution: String,
    pub kind: Kind,
    pub currency: String,
    /// Minor units, positive. NONE means unknown, which is not the same as no limit.
    pub credit_limit: Option<i64>,
    /// Annual rate in basis points — 2499 for 24.99%. Integer, because a rate in a float is the
    /// same defect class as money in a float.
    pub apr_bps: Option<u32>,
    /// Minor units the institution will accept this cycle.
    pub minimum_payment: Option<i64>,
    /// Day of month the statement closes, where it is known.
    pub statement_day: Option<u8>,
    pub note: Option<String>,
}

/// Something the registry does not know, and the capability that cannot run without it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Gap {
    pub account: String,
    pub field: &'static str,
    /// What silently does not happen. Named, because the agent's next question is always "why is
    /// there no number here".
    pub blocks: &'static str,
}

/// Keys that must never be stored. The registry needs the SHAPE of an account, never its identity.
const FORBIDDEN: &[&str] = &[
    "number", "account_number", "accountnumber", "acct", "pan", "card_number", "cardnumber",
    "routing", "routing_number", "iban", "ssn", "tax_id", "taxid", "pin", "cvv", "password", "secret", "token",
];

/// Whether any key ANYWHERE in a JSON value is one the registry refuses.
///
/// A GUARD, not a filter. Silently dropping an account number would let a caller keep writing the
/// code that sends one.
pub fn forbidden_key(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::Object(map) => {
            for (k, v) in map {
                let lower = k.to_ascii_lowercase();
                if FORBIDDEN.iter().any(|f| lower == *f) {
                    return Some(k.clone());
                }
                if let Some(hit) = forbidden_key(v) {
                    return Some(hit);
                }
            }
            None
        }
        serde_json::Value::Array(xs) => xs.iter().find_map(forbidden_key),
        _ => None,
    }
}

/// Read one account from JSON, refusing what it must not hold.
pub fn from_json(v: &serde_json::Value) -> Result<Account, String> {
    if let Some(k) = forbidden_key(v) {
        return Err(format!(
            "`{k}` is not something this store will hold. The registry needs to know an account's SHAPE — kind, limit, rate — never its identity, and a store that accepts the digits becomes a file worth stealing."
        ));
    }
    let s = |k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
    let n = |k: &str| v.get(k).and_then(serde_json::Value::as_i64);
    let id = s("id").ok_or_else(|| "an account needs an `id` — the name its statement files start with".to_string())?;
    let kind_raw = s("kind").ok_or_else(|| format!("{id}: `kind` is required — without it a positive balance could be money held or money owed"))?;
    let kind = Kind::parse(&kind_raw)
        .ok_or_else(|| format!("{id}: `{kind_raw}` is not a kind — one of checking, savings, credit, loan, investment"))?;
    Ok(Account {
        institution: s("institution").unwrap_or_else(|| id.clone()),
        currency: s("currency").unwrap_or_else(|| "USD".to_string()),
        credit_limit: n("creditLimit"),
        apr_bps: n("aprBps").and_then(|x| u32::try_from(x).ok()),
        minimum_payment: n("minimumPayment"),
        statement_day: n("statementDay").and_then(|x| u8::try_from(x).ok()).filter(|d| (1..=31).contains(d)),
        note: s("note"),
        id,
        kind,
    })
}

pub fn to_json(a: &Account) -> serde_json::Value {
    serde_json::json!({
        "id": a.id,
        "institution": a.institution,
        "kind": a.kind.as_str(),
        "currency": a.currency,
        "creditLimit": a.credit_limit,
        "aprBps": a.apr_bps,
        "minimumPayment": a.minimum_payment,
        "statementDay": a.statement_day,
        "note": a.note,
        // DERIVED, so a reader does not have to know the kind table to act on the row.
        "isDebt": a.kind.is_debt(),
        "isLiquid": a.kind.is_liquid(),
    })
}

pub fn all_to_json(accounts: &[Account]) -> serde_json::Value {
    serde_json::Value::Array(accounts.iter().map(to_json).collect())
}

/// Read a whole registry back. An entry that cannot be read is DROPPED with its id reported rather
/// than defaulted into something plausible.
pub fn all_from_json(v: &serde_json::Value) -> (Vec<Account>, Vec<String>) {
    let mut out = Vec::new();
    let mut rejected = Vec::new();
    for item in v.as_array().map(Vec::as_slice).unwrap_or_default() {
        match from_json(item) {
            Ok(a) => out.push(a),
            Err(e) => rejected.push(e),
        }
    }
    out.sort_by(|a, b| a.id.cmp(&b.id));
    (out, rejected)
}

/// Replace one account, keeping every other. Sorted, so the file is stable and a diff means something.
pub fn upsert(accounts: &mut Vec<Account>, next: Account) {
    match accounts.iter_mut().find(|a| a.id == next.id) {
        Some(slot) => *slot = next,
        None => accounts.push(next),
    }
    accounts.sort_by(|a, b| a.id.cmp(&b.id));
}

/// WHAT IS MISSING, AND WHAT IT COSTS.
///
/// The instrument half. Each gap names the capability that silently does not run without it, because
/// an agent's next question after a missing number is always "why", and without an answer it invents
/// one.
pub fn gaps(accounts: &[Account]) -> Vec<Gap> {
    let mut out = Vec::new();
    for a in accounts {
        if a.kind == Kind::Credit && a.credit_limit.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "creditLimit",
                blocks: "utilisation — which is UNKNOWN rather than 0%, and 0% is an excellent score while not knowing is not",
            });
        }
        if a.kind.is_debt() && a.apr_bps.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "aprBps",
                blocks: "daily interest, the weighted APR, and the avalanche order — the payoff plan cannot rank a debt whose rate it does not know",
            });
        }
        if a.kind.is_debt() && a.minimum_payment.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "minimumPayment",
                blocks: "the obligation calendar and the minimums-first rule — a missed minimum is a credit event",
            });
        }
        if a.kind.is_debt() && a.statement_day.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "statementDay",
                blocks: "the due date — the calendar falls back to the 1st, the earliest it could plausibly be, so nothing reads as late that is not",
            });
        }
    }
    out.sort_by(|x, y| x.account.cmp(&y.account).then(x.field.cmp(y.field)));
    out
}

/// How much of the picture is actually known, as a count — the one number an agent can act on
/// without reading every row.
pub fn completeness(accounts: &[Account]) -> (usize, usize) {
    let missing = gaps(accounts).len();
    let possible: usize = accounts
        .iter()
        .map(|a| match a.kind {
            Kind::Credit => 4,
            Kind::Loan => 3,
            _ => 0,
        })
        .sum();
    (possible.saturating_sub(missing), possible)
}

/// Every account referenced by a statement that the registry has never heard of.
///
/// The other direction of the same question: not "what do I not know about this account" but "what
/// account do I not know about at all".
pub fn undeclared<'a>(accounts: &[Account], seen: impl IntoIterator<Item = &'a str>) -> Vec<String> {
    let known: BTreeMap<&str, ()> = accounts.iter().map(|a| (a.id.as_str(), ())).collect();
    let mut out: Vec<String> = seen
        .into_iter()
        .filter(|s| !known.contains_key(*s))
        .map(str::to_string)
        .collect();
    out.sort();
    out.dedup();
    out
}

/// What a person reads. Gaps are NOT a footnote — they are most of the value.
pub fn render(accounts: &[Account]) -> String {
    if accounts.is_empty() {
        return "no accounts declared — `position` cannot say whether a balance is held or owed until one is\n".to_string();
    }
    let mut out = String::new();
    for a in accounts {
        let rate = a.apr_bps.map(|b| format!("{}.{:02}%", b / 100, b % 100)).unwrap_or_else(|| "rate unknown".into());
        out.push_str(&format!("  {:<18} {:<12} {:<16} {}\n", a.id, a.kind.as_str(), a.institution, rate));
    }
    let g = gaps(accounts);
    let (known, possible) = completeness(accounts);
    out.push_str(&format!("\n{known} of {possible} facts known about the debts.\n"));
    if !g.is_empty() {
        out.push_str("\nMissing, and what each one costs:\n");
        for x in &g {
            out.push_str(&format!("  {} · {} — blocks {}\n", x.account, x.field, x.blocks));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    // SYNTHETIC FIXTURES ONLY. No real account, limit or rate belongs in this repo.
    fn card() -> Account {
        Account {
            id: "discover".into(),
            institution: "Discover".into(),
            kind: Kind::Credit,
            currency: "USD".into(),
            credit_limit: Some(500_000),
            apr_bps: Some(2499),
            minimum_payment: Some(9_000),
            statement_day: Some(14),
            note: None,
        }
    }

    fn bare_card() -> Account {
        Account { credit_limit: None, apr_bps: None, minimum_payment: None, statement_day: None, ..card() }
    }

    #[test]
    fn an_account_number_is_refused_at_any_depth() {
        // The registry needs an account's SHAPE, never its identity. A store that accepts the digits
        // becomes a file worth stealing.
        for key in ["number", "accountNumber", "routing", "ssn", "pan", "cvv"] {
            let v = serde_json::json!({ "id": "x", "kind": "credit", key: "4111111111111111" });
            let e = from_json(&v).unwrap_err();
            assert!(e.contains("worth stealing"), "{key}: {e}");
        }
        let nested = serde_json::json!({ "id": "x", "kind": "credit", "meta": { "deep": { "ssn": "1" } } });
        assert!(from_json(&nested).is_err());
    }

    #[test]
    fn the_refusal_is_a_guard_not_a_filter() {
        // Silently dropping the field would let a caller keep writing the code that sends one.
        let v = serde_json::json!({ "id": "x", "kind": "credit", "number": "4111" });
        assert!(from_json(&v).is_err());
        assert_eq!(forbidden_key(&v).as_deref(), Some("number"));
    }

    #[test]
    fn kind_is_required_because_a_balance_is_meaningless_without_it() {
        let e = from_json(&serde_json::json!({ "id": "x" })).unwrap_err();
        assert!(e.contains("money held or money owed"), "{e}");
        let e2 = from_json(&serde_json::json!({ "id": "x", "kind": "brokerage" })).unwrap_err();
        assert!(e2.contains("not a kind"), "{e2}");
    }

    #[test]
    fn a_round_trip_loses_nothing() {
        let back = from_json(&to_json(&card())).unwrap();
        assert_eq!(back, card());
        let bare = from_json(&to_json(&bare_card())).unwrap();
        assert_eq!(bare, bare_card());
    }

    #[test]
    fn the_wire_shape_carries_the_derived_facts_so_a_reader_need_not_know_the_kind_table() {
        let v = to_json(&card());
        assert_eq!(v["isDebt"], true);
        assert_eq!(v["isLiquid"], false);
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..card() };
        assert_eq!(to_json(&cash)["isLiquid"], true);
        assert_eq!(to_json(&cash)["isDebt"], false);
    }

    #[test]
    fn every_gap_names_what_it_blocks() {
        // An agent's next question after a missing number is always "why", and without an answer it
        // invents one.
        let g = gaps(&[bare_card()]);
        assert_eq!(g.len(), 4);
        assert!(g.iter().all(|x| !x.blocks.is_empty()));
        let by_field: Vec<&str> = g.iter().map(|x| x.field).collect();
        assert_eq!(by_field, ["aprBps", "creditLimit", "minimumPayment", "statementDay"]);
        assert!(g.iter().find(|x| x.field == "creditLimit").unwrap().blocks.contains("0% is an excellent score"));
        assert!(g.iter().find(|x| x.field == "aprBps").unwrap().blocks.contains("avalanche order"));
    }

    #[test]
    fn a_complete_card_has_no_gaps_and_a_cash_account_never_does() {
        assert_eq!(gaps(&[card()]), vec![]);
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..bare_card() };
        // A chequing account has no rate, no limit and no minimum, and demanding them would fill the
        // report with work nobody can do.
        assert_eq!(gaps(&[cash]), vec![]);
    }

    #[test]
    fn completeness_counts_only_what_could_be_known() {
        assert_eq!(completeness(&[card()]), (4, 4));
        assert_eq!(completeness(&[bare_card()]), (0, 4));
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..bare_card() };
        assert_eq!(completeness(&[cash]), (0, 0));
    }

    #[test]
    fn undeclared_answers_the_other_direction_of_the_question() {
        // Not "what do I not know about this account" but "what account do I not know about at all".
        let out = undeclared(&[card()], ["discover", "chase", "chase", "capital-one"]);
        assert_eq!(out, ["capital-one", "chase"]);
        assert!(undeclared(&[card()], ["discover"]).is_empty());
    }

    #[test]
    fn a_row_that_cannot_be_read_is_dropped_with_its_reason_not_defaulted() {
        let v = serde_json::json!([
            { "id": "good", "kind": "credit" },
            { "id": "bad" },
            { "id": "worse", "kind": "credit", "ssn": "1" },
        ]);
        let (ok, rejected) = all_from_json(&v);
        assert_eq!(ok.len(), 1);
        assert_eq!(ok[0].id, "good");
        assert_eq!(rejected.len(), 2);
    }

    #[test]
    fn upsert_replaces_one_and_keeps_the_rest_sorted() {
        let mut xs = vec![card()];
        upsert(&mut xs, Account { id: "amex".into(), ..bare_card() });
        upsert(&mut xs, Account { apr_bps: Some(1999), ..card() });
        assert_eq!(xs.len(), 2);
        assert_eq!(xs.iter().map(|a| a.id.as_str()).collect::<Vec<_>>(), ["amex", "discover"]);
        assert_eq!(xs[1].apr_bps, Some(1999));
    }

    #[test]
    fn the_render_leads_with_what_is_missing_rather_than_burying_it() {
        let out = render(&[bare_card()]);
        assert!(out.contains("0 of 4 facts known"), "{out}");
        assert!(out.contains("Missing, and what each one costs"), "{out}");
        assert!(out.contains("rate unknown"), "{out}");
    }

    #[test]
    fn an_empty_registry_says_what_that_costs() {
        assert!(render(&[]).contains("cannot say whether a balance is held or owed"));
    }
}

//! The shared transaction shape — ported from `@/features/finance/lib/txn`.
//!
//! One definition, because the alternative is each capability inventing its own and the crate
//! carrying six subtly different ideas of what a transaction is. The fields are the ones a statement
//! actually gives you and nothing more: anything richer — category, merchant identity, account type
//! — is DERIVED by a capability that says so, rather than assumed to be present.
use crate::money::{Currency, Money};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Txn {
    /// ISO `YYYY-MM-DD`. Normalised at ingest, because comparing dates written three ways is not
    /// analysis, it is guessing.
    pub date: String,
    /// The description exactly as the statement wrote it. Normalisation is a capability's job and is
    /// always reversible to this.
    pub description: String,
    /// NEGATIVE is money leaving the account holder — the one contract ingest normalises to.
    pub amount: Money,
    /// Which account it belongs to. Two accounts can hold the same charge on the same day.
    pub account: String,
}

impl Txn {
    /// Lift a parsed statement row into the analysis shape, attaching the account the file belongs
    /// to and the currency it is denominated in — neither of which a row can know on its own.
    pub fn from_row(row: &crate::statement::Txn, account: &str, currency: Currency) -> Txn {
        Txn {
            date: row.date.clone(),
            description: row.description.clone(),
            amount: Money { minor: row.minor, currency },
            account: account.to_string(),
        }
    }
}

/// Days between two ISO dates. UTC, so a DST boundary cannot make a 30-day month 29.96 days.
///
/// Returns 0 for anything that is not a pair of dates rather than guessing a distance — a bad date
/// producing a plausible gap is how a cadence gets misclassified.
pub fn days_between(a: &str, b: &str) -> i64 {
    let (Some(x), Some(y)) = (
        crate::session::epoch_seconds(&format!("{a}T00:00:00Z")),
        crate::session::epoch_seconds(&format!("{b}T00:00:00Z")),
    ) else {
        return 0;
    };
    (y - x) / 86_400
}

/// `YYYY-MM` — the period most statement analysis groups by.
pub fn month_of(date: &str) -> &str {
    if date.len() >= 7 { &date[..7] } else { date }
}

/// Tokens that appear in descriptions without identifying the merchant.
const NOISE: &[&str] = &[
    "purchase", "payment", "pos", "debit", "credit", "card", "recurring", "autopay", "auto",
    "transaction", "ach", "web", "id", "ref", "the", "inc", "llc", "co", "com", "www", "usa", "us",
];

/// A merchant key: the description reduced to what is STABLE across occurrences.
///
/// A recurring charge rarely writes itself identically twice — statements append dates, store
/// numbers, transaction ids and city names. Matching on the raw description would find no recurrence
/// at all, which is the failure mode that makes a subscription detector look like it works while
/// finding nothing.
///
/// SPLIT FIRST, THEN DISCARD ANY TOKEN THAT CARRIED A DIGIT. Stripping digits before splitting
/// leaves the LETTER FRAGMENTS of an alphanumeric id behind: `AMZN Mktp US*2X4TY1` would reduce to
/// `amzn mktp ty` and `AMZN Mktp US*9KK2P0` to `amzn mktp kk`, so one merchant produces a different
/// key on every occurrence and matches itself never.
///
/// Deliberately crude and DETERMINISTIC. A smarter matcher would need a model, and a model here
/// would mean sending somebody's merchant list somewhere.
pub fn merchant_key(description: &str, words: usize) -> String {
    description
        .to_ascii_lowercase()
        .split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
        .filter(|w| !w.bytes().any(|b| b.is_ascii_digit()))
        .filter(|w| w.len() > 1)
        .filter(|w| !NOISE.contains(w))
        .take(words)
        .collect::<Vec<_>>()
        .join(" ")
}

/// The default width — three words, which is what the TypeScript uses everywhere it calls this.
pub fn merchant_key_default(description: &str) -> String {
    merchant_key(description, 3)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    /// EVERY VALUE HERE CAME FROM RUNNING `@/features/finance/lib/txn`, not from reading it — the
    /// same discipline the money parity table records, and for the same reason: the first pass of
    /// that port diverged in four places because it was written from a reading.
    #[test]
    fn merchant_key_matches_the_typescript_value_for_value() {
        let cases: &[(&str, &str)] = &[
            ("AMZN Mktp US*2X4TY1", "amzn mktp"),
            ("AMZN Mktp US*9KK2P0", "amzn mktp"),
            ("SQUARE, INC COFFEE", "square coffee"),
            ("NETFLIX.COM", "netflix"),
            ("SAFEWAY #221", "safeway"),
            ("PAYMENT - THANK YOU", "thank you"),
            ("SHELL OIL 4471", "shell oil"),
            ("RENT PAYMENT LANDLORD", "rent landlord"),
            ("TST* CORNER CAFE 09", "tst corner cafe"),
            ("ACH WEB PMT ID 12345 ACME", "pmt acme"),
            ("a", ""),
            ("  ", ""),
            ("USA INC LLC CO", ""),
        ];
        for (input, expected) in cases {
            assert_eq!(merchant_key_default(input), *expected, "merchantKey({input:?})");
        }
    }

    #[test]
    fn one_merchant_gives_one_key_however_the_statement_dresses_it_up() {
        // THE WHOLE POINT. Two Amazon rows with different order ids must collapse to one key, or a
        // subscription detector looks like it works while finding nothing.
        assert_eq!(merchant_key_default("AMZN Mktp US*2X4TY1"), merchant_key_default("AMZN Mktp US*9KK2P0"));
        assert_ne!(merchant_key_default("SAFEWAY #221"), merchant_key_default("SHELL OIL 4471"));
    }

    #[test]
    fn a_digit_bearing_token_is_dropped_whole_rather_than_stripped() {
        // Stripping digits first would leave `ty` and `kk` behind — letter fragments of an id, which
        // differ on every occurrence.
        assert!(!merchant_key_default("AMZN Mktp US*2X4TY1").contains("ty"));
        assert!(!merchant_key_default("STORE 4A7B").contains("a7b"));
        assert_eq!(merchant_key_default("STORE 4A7B"), "store");
    }

    #[test]
    fn the_width_is_a_parameter_and_three_is_the_default() {
        assert_eq!(merchant_key("TST* CORNER CAFE 09", 1), "tst");
        assert_eq!(merchant_key("TST* CORNER CAFE 09", 2), "tst corner");
        assert_eq!(merchant_key_default("TST* CORNER CAFE 09"), merchant_key("TST* CORNER CAFE 09", 3));
    }

    #[test]
    fn days_between_matches_the_typescript_and_signs_correctly() {
        assert_eq!(days_between("2026-01-01", "2026-03-01"), 59);
        assert_eq!(days_between("2026-03-01", "2026-01-01"), -59);
        // A leap day is a real day.
        assert_eq!(days_between("2024-02-28", "2024-03-01"), 2);
        assert_eq!(days_between("2026-02-28", "2026-03-01"), 1);
        assert_eq!(days_between("2026-06-01", "2026-06-01"), 0);
    }

    #[test]
    fn a_date_it_cannot_read_is_zero_rather_than_a_plausible_gap() {
        // A bad date producing a plausible distance is how a cadence gets misclassified, and the
        // wrong cadence misstates annual income by two whole payments.
        assert_eq!(days_between("not-a-date", "2026-03-01"), 0);
        assert_eq!(days_between("2026-13-01", "2026-03-01"), 0);
    }

    #[test]
    fn month_of_is_the_first_seven_characters_and_survives_a_short_string() {
        assert_eq!(month_of("2026-07-15"), "2026-07");
        assert_eq!(month_of("2026-07"), "2026-07");
        assert_eq!(month_of("bad"), "bad");
    }

    #[test]
    fn a_statement_row_lifts_into_the_analysis_shape_with_its_account_and_currency() {
        // Neither is knowable from the row itself: the account comes from which FILE it was in, and
        // the currency from what the account is denominated in.
        let row = crate::statement::Txn {
            date: "2026-06-03".into(),
            description: "SAFEWAY #221".into(),
            minor: -8410,
        };
        let t = Txn::from_row(&row, "chase-credit", Currency::USD);
        assert_eq!(t.account, "chase-credit");
        assert_eq!(t.amount, usd(-8410));
        assert_eq!(t.date, "2026-06-03");
        assert_eq!(t.description, "SAFEWAY #221");
    }
}

//! RECONCILIATION — the gate every derived figure has to pass through.
//!
//! Ported from `@/features/finance/lib/reconcile`. Every other capability here is arithmetic over a
//! list of transactions, and arithmetic over an INCOMPLETE list is not wrong in a way anybody can
//! see. A missing week of a statement does not produce an error; it produces a spending total that
//! is quietly too low, a runway that is quietly too long, and a payoff schedule that quietly does
//! not work. The numbers stay plausible, which is exactly what makes them dangerous.
//!
//! So reconciliation is not a report — it is a TYPE. [`reconcile`] is the only function that can
//! mint a [`ReconciledLedger`], and a capability that takes one cannot be handed transactions
//! nobody checked.
//!
//! # The brand is STRONGER here than in the TypeScript
//!
//! There it is a phantom symbol — a compile-time fiction that a cast can defeat. Here the fields are
//! private, so a struct literal outside this module is a COMPILE ERROR with no escape hatch at all.
//! The port gains something rather than approximating it.
//!
//! THERE IS NO TOLERANCE, and that is deliberate. Money is an integer count of minor units, so a
//! one-cent discrepancy has no rounding to blame — it is a real transaction that is missing,
//! doubled, or signed the wrong way. A tolerance would be a setting whose only function is to hide
//! the class of defect this module exists to find.
use crate::money::{money, subtract, sum, Currency, Money};
use crate::txn::{days_between, Txn};

/// One statement: what the institution says the account held at each end of a window.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StatementPeriod {
    pub account: String,
    /// `YYYY-MM-DD`, INCLUSIVE.
    pub from: String,
    /// `YYYY-MM-DD`, INCLUSIVE.
    pub to: String,
    pub opening: Money,
    pub closing: Money,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProblemKind {
    /// Opening + the period's transactions does not reach closing.
    Unbalanced,
    /// Consecutive statements leave days uncovered — transactions in them are simply absent.
    Gap,
    /// Two statements for one account claim the same days.
    Overlap,
    /// One statement's opening disagrees with the previous statement's closing.
    Continuity,
    /// A transaction's currency is not the period's.
    CurrencyMismatch,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Problem {
    pub kind: ProblemKind,
    pub account: String,
    /// Written for a person to act on, not for a log.
    pub detail: String,
    pub amount: Option<Money>,
    /// Transactions this problem points at — the shortlist to go and look at.
    pub suspects: Vec<Txn>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PeriodReport {
    pub account: String,
    pub from: String,
    pub to: String,
    pub balanced: bool,
    pub opening: Money,
    pub closing: Money,
    /// opening + everything dated inside the window.
    pub computed: Money,
    /// closing − computed. Zero, or the exact size of what is wrong.
    pub discrepancy: Money,
    pub counted: usize,
}

/// Transactions something has actually checked, and the date they are checked THROUGH.
///
/// EVERY FIELD IS PRIVATE. That is the enforcement: only this module can build one, so a capability
/// that asks for a `ReconciledLedger` cannot be handed a raw list by any means at all.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ReconciledLedger {
    txns: Vec<Txn>,
    through: String,
    accounts: Vec<String>,
    unverified: bool,
    caveat: Option<String>,
}

impl ReconciledLedger {
    pub fn txns(&self) -> &[Txn] {
        &self.txns
    }

    /// The last date EVERY account is covered through — see [`coverage_through`].
    pub fn through(&self) -> &str {
        &self.through
    }

    pub fn accounts(&self) -> &[String] {
        &self.accounts
    }

    /// True when this came from [`unverified_ledger`] rather than a passing reconcile.
    pub fn unverified(&self) -> bool {
        self.unverified
    }

    pub fn caveat(&self) -> Option<&str> {
        self.caveat.as_deref()
    }

    /// The transactions a derived figure may use: everything up to the date coverage actually reaches.
    pub fn covered(&self) -> Vec<Txn> {
        self.txns.iter().filter(|t| t.date <= self.through).cloned().collect()
    }

    /// A one-line statement of what a figure derived from this ledger is standing on.
    pub fn provenance(&self) -> String {
        let base = format!(
            "{} transaction(s) across {} account(s), covered through {}",
            self.txns.len(),
            self.accounts.len(),
            self.through
        );
        match &self.caveat {
            Some(c) if self.unverified => format!("UNVERIFIED — {c} · {base}"),
            _ => format!("reconciled · {base}"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct ReconcileResult {
    pub ok: bool,
    /// Present only when every period balanced and nothing is missing between them.
    pub ledger: Option<ReconciledLedger>,
    pub periods: Vec<PeriodReport>,
    pub problems: Vec<Problem>,
    /// Transactions belonging to no supplied period. Not counted, and not silently dropped either.
    pub uncovered: Vec<Txn>,
}

fn next_day(d: &str) -> String {
    match crate::session::epoch_seconds(&format!("{d}T00:00:00Z")) {
        Some(s) => crate::session::iso_from_epoch(s + 86_400)[..10].to_string(),
        None => d.to_string(),
    }
}

fn in_period(t: &Txn, p: &StatementPeriod) -> bool {
    t.account == p.account && t.date >= p.from && t.date <= p.to
}

/// The last date the WHOLE picture is trustworthy through — the EARLIEST of each account's coverage.
///
/// A ledger is only as complete as its least-covered account. Checking reconciled through August and
/// a credit card only through July does not give you an August position: August's card spending is
/// missing, so every August figure is too flattering. Taking the maximum here would be the specific
/// mistake that produces a confident, wrong number.
pub fn coverage_through(periods: &[StatementPeriod]) -> Option<String> {
    let mut last: std::collections::BTreeMap<&str, &str> = std::collections::BTreeMap::new();
    for p in periods {
        let e = last.entry(p.account.as_str()).or_insert(p.to.as_str());
        if p.to.as_str() > *e {
            *e = p.to.as_str();
        }
    }
    last.values().min().map(|s| s.to_string())
}

/// Explain a discrepancy by pointing at the transactions that would produce exactly it.
fn explain(discrepancy: i64, rows: &[Txn]) -> (String, Vec<Txn>) {
    // A SIGN ERROR IS TWICE THE AMOUNT, and it is checked FIRST. Booking −$50 as +$50 moves the
    // balance by $100, so a $100 discrepancy with a $50 transaction present is far more likely a
    // sign error than a missing $100 charge — and the two want completely different fixes.
    let halved: Vec<Txn> = rows.iter().filter(|t| t.amount.minor.abs() * 2 == discrepancy.abs()).cloned().collect();
    if !halved.is_empty() {
        let what = if halved.len() == 1 { "one transaction".to_string() } else { format!("{} transactions", halved.len()) };
        return (
            format!("the discrepancy is exactly twice {what} — a sign error, not a missing row: money leaving the account must be negative"),
            halved,
        );
    }
    let exact: Vec<Txn> = rows.iter().filter(|t| t.amount.minor.abs() == discrepancy.abs()).cloned().collect();
    if !exact.is_empty() {
        let what = if exact.len() == 1 { "one transaction".to_string() } else { format!("{} transactions", exact.len()) };
        return (
            format!("the discrepancy is exactly {what} in this period — check whether it was counted twice, or a matching one is missing"),
            exact,
        );
    }
    ("no single transaction accounts for it — the statement is probably missing rows".to_string(), Vec::new())
}

pub fn reconcile(txns: &[Txn], periods: &[StatementPeriod]) -> ReconcileResult {
    let mut problems: Vec<Problem> = Vec::new();
    let mut reports: Vec<PeriodReport> = Vec::new();
    let mut claimed: Vec<bool> = vec![false; txns.len()];

    for p in periods {
        let rows: Vec<Txn> = txns
            .iter()
            .enumerate()
            .filter(|(i, t)| {
                let hit = in_period(t, p);
                if hit {
                    claimed[*i] = true;
                }
                hit
            })
            .map(|(_, t)| t.clone())
            .collect();

        let wrong_currency: Vec<Txn> = rows.iter().filter(|t| t.amount.currency != p.opening.currency).cloned().collect();
        for t in &wrong_currency {
            problems.push(Problem {
                kind: ProblemKind::CurrencyMismatch,
                account: p.account.clone(),
                detail: format!(
                    "a {} transaction on {} sits in a {} statement — converting it is a decision, not an assumption this can make",
                    t.amount.currency, t.date, p.opening.currency
                ),
                amount: None,
                suspects: vec![t.clone()],
            });
        }

        let same: Vec<Money> = rows.iter().filter(|t| t.amount.currency == p.opening.currency).map(|t| t.amount).collect();
        let movement = sum(&same, p.opening.currency).unwrap_or(money(0, p.opening.currency));
        let computed = money(p.opening.minor + movement.minor, p.opening.currency);
        let discrepancy = subtract(p.closing, computed).unwrap_or(money(0, p.opening.currency));
        let balanced = discrepancy.minor == 0 && wrong_currency.is_empty();

        if discrepancy.minor != 0 {
            let (detail, suspects) = explain(discrepancy.minor, &rows);
            problems.push(Problem {
                kind: ProblemKind::Unbalanced,
                account: p.account.clone(),
                detail: format!("{}..{} is out by {} minor units — {detail}", p.from, p.to, discrepancy.minor),
                amount: Some(discrepancy),
                suspects,
            });
        }

        reports.push(PeriodReport {
            account: p.account.clone(),
            from: p.from.clone(),
            to: p.to.clone(),
            balanced,
            opening: p.opening,
            closing: p.closing,
            computed,
            discrepancy,
            counted: rows.len(),
        });
    }

    // BETWEEN the statements, per account: a gap, an overlap, or an opening that disagrees with the
    // previous closing. Each period can balance perfectly and the SET still be missing a month.
    let mut by_account: std::collections::BTreeMap<&str, Vec<&StatementPeriod>> = std::collections::BTreeMap::new();
    for p in periods {
        by_account.entry(p.account.as_str()).or_default().push(p);
    }
    for (account, ps) in &by_account {
        let mut sorted = ps.clone();
        sorted.sort_by(|a, b| a.from.cmp(&b.from));
        for w in sorted.windows(2) {
            let (prev, next) = (w[0], w[1]);
            if next.from <= prev.to {
                problems.push(Problem {
                    kind: ProblemKind::Overlap,
                    account: (*account).to_string(),
                    detail: format!(
                        "{}..{} overlaps {}..{} — the shared days would be counted twice",
                        next.from, next.to, prev.from, prev.to
                    ),
                    amount: None,
                    suspects: Vec::new(),
                });
                continue;
            }
            let missing = days_between(&prev.to, &next.from) - 1;
            if missing > 0 {
                problems.push(Problem {
                    kind: ProblemKind::Gap,
                    account: (*account).to_string(),
                    detail: format!(
                        "{missing} day(s) uncovered between {} and {} — anything spent in them is absent, and every total below is too low by however much that was",
                        prev.to, next.from
                    ),
                    amount: None,
                    suspects: Vec::new(),
                });
                continue;
            }
            if next.opening.minor != prev.closing.minor {
                problems.push(Problem {
                    kind: ProblemKind::Continuity,
                    account: (*account).to_string(),
                    detail: format!(
                        "{} opens at {} but {} closed at {} — consecutive statements disagree about the same moment",
                        next_day(&prev.to),
                        next.opening.minor,
                        prev.to,
                        prev.closing.minor
                    ),
                    amount: subtract(next.opening, prev.closing).ok(),
                    suspects: Vec::new(),
                });
            }
        }
    }

    let uncovered: Vec<Txn> = txns.iter().zip(&claimed).filter(|(_, c)| !**c).map(|(t, _)| t.clone()).collect();
    let ok = problems.is_empty() && uncovered.is_empty() && !periods.is_empty();
    let through = coverage_through(periods);

    let ledger = match (ok, through) {
        (true, Some(through)) => {
            let mut sorted = txns.to_vec();
            sorted.sort_by(|a, b| a.date.cmp(&b.date));
            Some(ReconciledLedger {
                txns: sorted,
                through,
                accounts: by_account.keys().map(|k| (*k).to_string()).collect(),
                unverified: false,
                caveat: None,
            })
        }
        _ => None,
    };

    ReconcileResult { ok, ledger, periods: reports, problems, uncovered }
}

/// A ledger accepted WITHOUT a reconcile, because sometimes there is no opening balance to check
/// against and a system that refuses outright is a system nobody uses.
///
/// Deliberately ugly to reach for: it demands a reason, marks the ledger `unverified`, and its name
/// is greppable — so "which of these figures rests on unchecked data?" is a question with an answer.
pub fn unverified_ledger(txns: &[Txn], through: &str, caveat: &str) -> Result<ReconciledLedger, String> {
    if caveat.trim().is_empty() {
        return Err("an unverified ledger must say why it could not be reconciled".to_string());
    }
    let mut sorted = txns.to_vec();
    sorted.sort_by(|a, b| a.date.cmp(&b.date));
    let mut accounts: Vec<String> = sorted.iter().map(|t| t.account.clone()).collect();
    accounts.sort();
    accounts.dedup();
    Ok(ReconciledLedger {
        txns: sorted,
        through: through.to_string(),
        accounts,
        unverified: true,
        caveat: Some(caveat.to_string()),
    })
}

/// A currency for a period, so a caller does not have to reach into `money` for the common case.
pub fn usd_period(account: &str, from: &str, to: &str, opening: i64, closing: i64) -> StatementPeriod {
    StatementPeriod {
        account: account.to_string(),
        from: from.to_string(),
        to: to.to_string(),
        opening: money(opening, Currency::USD),
        closing: money(closing, Currency::USD),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
    fn tx(date: &str, description: &str, minor: i64) -> Txn {
        Txn { date: date.into(), description: description.into(), amount: usd(minor), account: "checking".into() }
    }

    fn period(closing: i64) -> StatementPeriod {
        usd_period("checking", "2026-06-01", "2026-06-30", 100_000, closing)
    }

    fn rows() -> Vec<Txn> {
        vec![tx("2026-06-03", "PAY", 200_000), tx("2026-06-05", "RENT", -150_000)]
    }

    /// One row of the parity table — named rather than a tuple, so each expectation says which
    /// question it is answering.
    struct Case {
        label: &'static str,
        txns: Vec<Txn>,
        period: StatementPeriod,
        ok: bool,
        discrepancy: i64,
        kind: Option<ProblemKind>,
    }

    /// EVERY EXPECTATION HERE CAME FROM RUNNING `@/features/finance/lib/reconcile`, not from reading
    /// it — the method the money batch's four silent divergences established.
    #[test]
    fn the_port_matches_the_typescript_case_for_case() {
        let cases = vec![
            Case { label: "balanced", txns: rows(), period: period(150_000), ok: true, discrepancy: 0, kind: None },
            Case { label: "one cent", txns: rows(), period: period(150_001), ok: false, discrepancy: 1, kind: Some(ProblemKind::Unbalanced) },
            Case {
                label: "sign error",
                txns: vec![tx("2026-06-03", "PAY", 200_000), tx("2026-06-05", "RENT", 150_000)],
                period: period(150_000),
                ok: false,
                discrepancy: -300_000,
                kind: Some(ProblemKind::Unbalanced),
            },
            Case { label: "exact match", txns: rows(), period: period(350_000), ok: false, discrepancy: 200_000, kind: Some(ProblemKind::Unbalanced) },
            Case {
                label: "no explanation",
                txns: vec![tx("2026-06-03", "PAY", 200_000)],
                period: period(277_700),
                ok: false,
                discrepancy: -22_300,
                kind: Some(ProblemKind::Unbalanced),
            },
        ];
        for c in &cases {
            let r = reconcile(&c.txns, std::slice::from_ref(&c.period));
            assert_eq!(r.ok, c.ok, "{}: ok", c.label);
            assert_eq!(r.periods[0].discrepancy.minor, c.discrepancy, "{}: discrepancy", c.label);
            assert_eq!(r.problems.first().map(|x| x.kind), c.kind, "{}: problem kind", c.label);
        }
    }

    #[test]
    fn a_doubled_amount_is_a_sign_error_and_it_is_checked_first() {
        // RENT booked +1500 instead of −1500 moves the balance by 3000, not 1500. A detector that
        // matched the discrepancy against amounts directly would hunt a missing $3,000 charge that
        // does not exist — and the two want completely different fixes.
        let r = reconcile(&[tx("2026-06-03", "PAY", 200_000), tx("2026-06-05", "RENT", 150_000)], &[period(150_000)]);
        let p = r.problems.iter().find(|x| x.kind == ProblemKind::Unbalanced).unwrap();
        assert!(p.detail.contains("sign error"), "{}", p.detail);
        assert_eq!(p.suspects.iter().map(|t| t.description.as_str()).collect::<Vec<_>>(), ["RENT"]);
    }

    #[test]
    fn one_cent_is_refused_because_integers_have_no_rounding_to_blame() {
        let r = reconcile(&rows(), &[period(150_001)]);
        assert!(!r.ok);
        assert!(r.ledger.is_none());
        assert!(r.problems[0].detail.contains("missing rows"), "{}", r.problems[0].detail);
    }

    #[test]
    fn between_the_statements_matches_the_typescript_too() {
        let june = usd_period("checking", "2026-06-01", "2026-06-30", 100_000, 100_000);
        let aug = usd_period("checking", "2026-08-01", "2026-08-31", 100_000, 100_000);
        let g = reconcile(&[], &[june.clone(), aug]);
        assert_eq!(g.problems[0].kind, ProblemKind::Gap);
        assert!(g.problems[0].detail.starts_with("31 day(s) uncovered between 2026-06-30 and 2026-08-01"), "{}", g.problems[0].detail);

        let overlapping = usd_period("checking", "2026-06-15", "2026-07-15", 100_000, 100_000);
        assert_eq!(reconcile(&[], &[june.clone(), overlapping]).problems[0].kind, ProblemKind::Overlap);

        let july_disagrees = usd_period("checking", "2026-07-01", "2026-07-31", 90_000, 90_000);
        let c = reconcile(&[], &[june.clone(), july_disagrees]);
        assert_eq!(c.problems[0].kind, ProblemKind::Continuity);
        assert!(c.problems[0].detail.contains("2026-07-01 opens at 90000"), "{}", c.problems[0].detail);

        let july_abuts = usd_period("checking", "2026-07-01", "2026-07-31", 100_000, 100_000);
        let a = reconcile(&[], &[june, july_abuts]);
        assert!(a.problems.is_empty());
        assert!(a.ok);
    }

    #[test]
    fn coverage_is_the_least_covered_account_never_the_latest() {
        // Checking through August and a card only through July is not an August position: August's
        // card spending is missing, so every August figure would be too flattering.
        let ps = vec![
            usd_period("checking", "2026-08-01", "2026-08-31", 0, 0),
            usd_period("card", "2026-07-01", "2026-07-31", 0, 0),
        ];
        assert_eq!(coverage_through(&ps).as_deref(), Some("2026-07-31"));
        assert_eq!(coverage_through(&[]), None);
    }

    #[test]
    fn a_transaction_belonging_to_no_statement_is_reported_not_dropped() {
        let r = reconcile(
            &[tx("2026-06-03", "IN PERIOD", 0), tx("2026-05-03", "BEFORE ANY STATEMENT", -4_000)],
            &[period(100_000)],
        );
        assert_eq!(r.uncovered.iter().map(|t| t.description.as_str()).collect::<Vec<_>>(), ["BEFORE ANY STATEMENT"]);
        assert!(!r.ok);
        assert_eq!(r.periods[0].counted, 1);
    }

    #[test]
    fn another_accounts_rows_cannot_balance_this_one() {
        let mut card = tx("2026-06-03", "CARD SPEND", -10_000);
        card.account = "card".into();
        let r = reconcile(&[card], &[period(90_000)]);
        assert_eq!(r.periods[0].counted, 0);
        assert_eq!(r.periods[0].discrepancy.minor, -10_000);
        assert_eq!(r.uncovered.len(), 1);
    }

    #[test]
    fn a_foreign_currency_row_is_excluded_from_the_arithmetic_rather_than_added() {
        let eur = Currency::new("EUR").unwrap();
        let mut t = tx("2026-06-03", "PARIS HOTEL", -20_000);
        t.amount = money(-20_000, eur);
        let r = reconcile(&[t], &[period(100_000)]);
        assert!(!r.ok);
        let c = r.problems.iter().find(|p| p.kind == ProblemKind::CurrencyMismatch).unwrap();
        assert!(c.detail.contains("EUR"), "{}", c.detail);
        assert!(c.detail.contains("decision"), "{}", c.detail);
        // Excluded, not converted: the computed balance is untouched by it.
        assert_eq!(r.periods[0].computed.minor, 100_000);
    }

    #[test]
    fn the_ledger_is_minted_only_by_a_clean_reconcile_and_there_is_no_partial_pass() {
        assert!(reconcile(&rows(), &[period(150_000)]).ledger.is_some());
        assert!(reconcile(&rows(), &[period(150_001)]).ledger.is_none());
        // No periods at all is not a pass either.
        let empty = reconcile(&[], &[]);
        assert!(!empty.ok);
        assert!(empty.ledger.is_none());
    }

    #[test]
    fn the_unverified_hatch_demands_a_reason_and_marks_itself() {
        assert!(unverified_ledger(&[], "2026-06-30", "  ").is_err());
        let l = unverified_ledger(&rows(), "2026-06-30", "Chase export has no opening balance").unwrap();
        assert!(l.unverified());
        assert!(l.provenance().starts_with("UNVERIFIED"));
        assert!(l.provenance().contains("Chase export has no opening balance"));

        let clean = reconcile(&rows(), &[period(150_000)]).ledger.unwrap();
        assert!(clean.provenance().starts_with("reconciled"));
        assert!(clean.provenance().contains("covered through 2026-06-30"));
    }

    #[test]
    fn covered_clips_at_the_date_coverage_actually_reaches() {
        let mut card = tx("2026-07-10", "CARD SPEND", -5_000);
        card.account = "card".into();
        let l = unverified_ledger(&[card, tx("2026-06-10", "EARLY", -6_000)], "2026-06-30", "synthetic").unwrap();
        assert_eq!(l.covered().iter().map(|t| t.description.as_str()).collect::<Vec<_>>(), ["EARLY"]);
        assert_eq!(l.txns().len(), 2);
    }
}

//! THE POSITION — what is actually held and actually owed, as of a date coverage really reaches.
//!
//! Ported from `@/features/finance/lib/position`, with one improvement the TypeScript could not
//! make: it reads the ACCOUNT REGISTRY directly rather than a parallel declaration type, so
//! `bsc fin account` feeds this and there is one description of an account rather than two.
//!
//! This is the first capability that takes a [`ReconciledLedger`], and taking one is the point: a
//! position computed from an unchecked transaction list is a confident number built on a list that
//! might be missing a month. The compiler is what stops that.
//!
//! # The sign contract is the whole module
//!
//! A chequing statement printing "1,200.00" means you HAVE $1,200. A card statement printing
//! "2,431.07" means you OWE $2,431.07. Adding the two printed numbers gives $3,631.07, which is not
//! a quantity that exists — the truth is −$1,231.07. So every balance here is SIGNED by what it
//! contributes to net worth, and [`from_statement_balance`] is the one named place a printed figure
//! is converted. Nothing here guesses which convention a number arrived in.
//!
//! The proof the contract holds is that a payment from chequing to a card MOVES NOTHING: −$300 on
//! one account and +$300 on the other, net worth unchanged. Same money, different place — and a
//! model that reports otherwise is wrong in a way that feels like progress.
use crate::account::{Account, Kind};
use crate::money::{money, scale, sum, Currency, Money, Rounding};
use crate::reconcile::ReconciledLedger;

/// Convert the number a statement PRINTS into the signed convention.
///
/// A debt statement prints what you owe as a positive number, because from the institution's side it
/// is an asset. Net worth needs the other side of that. A card in credit (you overpaid) prints a
/// negative and comes back positive, which is also right — negation is the whole rule and it holds
/// in both directions rather than being a special case for the common one.
pub fn from_statement_balance(kind: Kind, printed: Money) -> Money {
    if kind.is_debt() {
        money(-printed.minor, printed.currency)
    } else {
        printed
    }
}

/// A balance as of a date, SIGNED by contribution to net worth.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AccountBalance {
    pub account: String,
    /// `YYYY-MM-DD` the balance was true on.
    pub as_of: String,
    /// Build it with [`from_statement_balance`] rather than by hand.
    pub balance: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct AccountPosition {
    pub account: String,
    pub institution: String,
    pub kind: Kind,
    /// Signed, rolled forward from the stated balance to `as_of`.
    pub balance: Money,
    pub as_of: String,
    /// How many transactions were applied on top of the stated balance to get here.
    pub rolled_forward: usize,
    pub is_debt: bool,
    /// POSITIVE amount owed. Present only when the account is actually in debt.
    pub owed: Option<Money>,
    pub credit_limit: Option<Money>,
    pub available: Option<Money>,
    /// 0-1. NONE when the limit is unknown — 0 would read as "nothing used", which is the opposite
    /// of not knowing.
    pub utilisation: Option<f64>,
    /// Annual rate as a fraction: 0.2499 for 24.99%.
    pub apr: Option<f64>,
    /// What this debt costs per day at its rate. The number that makes a balance feel like a bill.
    pub daily_interest: Option<Money>,
    pub minimum_payment: Option<Money>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Position {
    /// The date this is true as of — the ledger's coverage, never later.
    pub as_of: String,
    pub currency: Currency,
    pub accounts: Vec<AccountPosition>,
    /// Assets minus debts. The one number, and it is signed.
    pub net_worth: Money,
    /// What could pay a bill this week — chequing and savings only.
    pub liquid: Money,
    /// POSITIVE total owed across every debt.
    pub total_debt: Money,
    pub daily_interest: Money,
    pub minimums_due: Money,
    /// Balance-weighted APR across debts whose rate is known. None when none is.
    pub weighted_apr: Option<f64>,
    /// False when anything below is standing on something unchecked or unknown.
    pub complete: bool,
    pub problems: Vec<String>,
    pub provenance: String,
}

/// Basis points as the fraction the arithmetic uses. Exact: 2499 bps is 0.2499.
fn apr_of(a: &Account) -> Option<f64> {
    a.apr_bps.map(|b| b as f64 / 10_000.0)
}

fn round3(x: f64) -> f64 {
    (x * 1000.0).round() / 1000.0
}

pub fn position(
    ledger: &ReconciledLedger,
    accounts: &[Account],
    balances: &[AccountBalance],
    currency: Currency,
) -> Position {
    let mut problems: Vec<String> = Vec::new();
    let rows = ledger.covered();

    // AN UNDECLARED ACCOUNT IS NOT A ROUNDING ERROR. Without its kind there is no way to know
    // whether its transactions are money you have or money you owe, and folding it in either way
    // invents a sign. It is named and left out.
    let known: Vec<&str> = accounts.iter().map(|a| a.id.as_str()).collect();
    let mut seen: Vec<&str> = rows.iter().map(|t| t.account.as_str()).collect();
    seen.sort();
    seen.dedup();
    for s in seen {
        if !known.contains(&s) {
            problems.push(format!(
                "'{s}' has transactions but no declaration — nothing here can tell whether that is money you have or money you owe, so it is left out entirely"
            ));
        }
    }

    let mut out: Vec<AccountPosition> = Vec::new();
    for a in accounts {
        let declared = Currency::new(&a.currency).unwrap_or(Currency::USD);
        if declared != currency {
            problems.push(format!(
                "'{}' is in {} not {} — it is excluded rather than converted, because a rate is a decision and a net worth across currencies is not one number",
                a.id, a.currency, currency
            ));
            continue;
        }
        let Some(stated) = balances.iter().find(|b| b.account == a.id) else {
            problems.push(format!(
                "'{}' is declared but has no balance — its transactions cannot say what it holds, only how it moved",
                a.id
            ));
            continue;
        };
        if stated.as_of.as_str() > ledger.through() {
            problems.push(format!(
                "'{}' has a balance dated {}, past the {} the ledger actually covers — the transactions between them are not here to check it",
                a.id,
                stated.as_of,
                ledger.through()
            ));
        }

        // ONLY WHAT CAME AFTER. A transaction dated on or before the stated balance is already
        // inside that balance; applying it again double-counts, and the error is invisible because
        // the result is still a plausible number.
        let after: Vec<Money> = rows
            .iter()
            .filter(|t| t.account == a.id && t.date > stated.as_of)
            .map(|t| t.amount)
            .collect();
        let movement = sum(&after, currency).unwrap_or(money(0, currency));
        let balance = money(stated.balance.minor + movement.minor, currency);

        let owed_minor = if balance.minor < 0 { -balance.minor } else { 0 };
        let owed = (owed_minor > 0).then(|| money(owed_minor, currency));
        let credit_limit = a.credit_limit.map(|l| money(l, currency));
        let apr = apr_of(a);

        if a.kind == Kind::Credit && credit_limit.is_none() {
            problems.push(format!(
                "'{}' is a credit line with no limit — its utilisation is UNKNOWN, which is not the same as 0%",
                a.id
            ));
        }
        if a.kind.is_debt() && owed.is_some() && apr.is_none() {
            problems.push(format!(
                "'{}' owes {owed_minor} minor units at an unknown APR — the daily interest and weighted APR below both understate what this costs",
                a.id
            ));
        }

        out.push(AccountPosition {
            account: a.id.clone(),
            institution: a.institution.clone(),
            kind: a.kind,
            balance,
            as_of: ledger.through().to_string(),
            rolled_forward: after.len(),
            is_debt: a.kind.is_debt(),
            owed,
            credit_limit,
            available: credit_limit.map(|l| money(l.minor - owed_minor, currency)),
            utilisation: credit_limit
                .filter(|l| l.minor > 0)
                .map(|l| round3(owed_minor as f64 / l.minor as f64)),
            apr,
            daily_interest: match (apr, owed) {
                (Some(r), Some(o)) => Some(scale(o, r / 365.0, Rounding::HalfUp)),
                _ => None,
            },
            minimum_payment: a.minimum_payment.filter(|_| owed.is_some()).map(|m| money(m, currency)),
        });
    }

    let net_worth = sum(&out.iter().map(|a| a.balance).collect::<Vec<_>>(), currency).unwrap_or(money(0, currency));
    let liquid = sum(
        &out.iter().filter(|a| a.kind.is_liquid()).map(|a| a.balance).collect::<Vec<_>>(),
        currency,
    )
    .unwrap_or(money(0, currency));

    let debts: Vec<&AccountPosition> = out.iter().filter(|a| a.owed.is_some()).collect();
    let total_debt: i64 = debts.iter().map(|a| a.owed.unwrap().minor).sum();
    let rated: Vec<&&AccountPosition> = debts.iter().filter(|a| a.apr.is_some()).collect();
    let rated_total: i64 = rated.iter().map(|a| a.owed.unwrap().minor).sum();

    if ledger.unverified() {
        problems.push(format!("the ledger under this was NOT reconciled: {}", ledger.caveat().unwrap_or("no reason given")));
    }

    Position {
        as_of: ledger.through().to_string(),
        currency,
        net_worth,
        liquid,
        total_debt: money(total_debt, currency),
        daily_interest: money(debts.iter().filter_map(|a| a.daily_interest).map(|m| m.minor).sum(), currency),
        minimums_due: money(debts.iter().filter_map(|a| a.minimum_payment).map(|m| m.minor).sum(), currency),
        weighted_apr: (rated_total > 0).then(|| {
            let w: f64 = rated.iter().map(|a| a.owed.unwrap().minor as f64 * a.apr.unwrap()).sum();
            (w / rated_total as f64 * 10_000.0).round() / 10_000.0
        }),
        complete: problems.is_empty(),
        problems,
        provenance: format!("{} · position as of {}", ledger.provenance(), ledger.through()),
        accounts: out,
    }
}

/// What a whole year of carrying today's debt costs, if nothing is paid down. Often the number that
/// changes somebody's mind, so it is given rather than left as an exercise.
pub fn annual_interest_cost(p: &Position) -> Money {
    scale(p.daily_interest, 365.0, Rounding::HalfUp)
}

/// Utilisation across every credit line together — the figure a score actually reads.
pub fn overall_utilisation(p: &Position) -> Option<f64> {
    let lines: Vec<&AccountPosition> = p.accounts.iter().filter(|a| a.kind == Kind::Credit && a.credit_limit.is_some()).collect();
    let limit: i64 = lines.iter().map(|a| a.credit_limit.unwrap().minor).sum();
    if limit <= 0 {
        return None;
    }
    let owed: i64 = lines.iter().map(|a| a.owed.map(|o| o.minor).unwrap_or(0)).sum();
    Some(round3(owed as f64 / limit as f64))
}

/// Debts worst-rate first — the order avalanche pays them in, and the order to read them in.
pub fn by_cost(p: &Position) -> Vec<&AccountPosition> {
    let mut d: Vec<&AccountPosition> = p.accounts.iter().filter(|a| a.owed.is_some()).collect();
    d.sort_by(|a, b| b.apr.unwrap_or(-1.0).partial_cmp(&a.apr.unwrap_or(-1.0)).unwrap_or(std::cmp::Ordering::Equal));
    d
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::reconcile::unverified_ledger;
    use crate::txn::Txn;

    // SYNTHETIC FIXTURES ONLY. No real balance or account number belongs in this repo.
    fn acct(id: &str, kind: Kind) -> Account {
        Account {
            id: id.into(),
            institution: format!("Example {id}"),
            kind,
            currency: "USD".into(),
            credit_limit: None,
            apr_bps: None,
            minimum_payment: None,
            statement_day: None,
            note: None,
        }
    }

    fn card() -> Account {
        Account { credit_limit: Some(600_000), apr_bps: Some(2499), minimum_payment: Some(9_000), ..acct("card", Kind::Credit) }
    }

    fn loan() -> Account {
        Account { apr_bps: Some(699), minimum_payment: Some(22_000), ..acct("loan", Kind::Loan) }
    }

    fn bal(account: &str, minor: i64) -> AccountBalance {
        AccountBalance { account: account.into(), as_of: "2026-06-01".into(), balance: usd(minor) }
    }

    fn tx(date: &str, desc: &str, minor: i64, account: &str) -> Txn {
        Txn { date: date.into(), description: desc.into(), amount: usd(minor), account: account.into() }
    }

    fn led(txns: &[Txn]) -> ReconciledLedger {
        unverified_ledger(txns, "2026-06-30", "synthetic").unwrap()
    }

    /// EVERY NUMBER BELOW CAME FROM RUNNING `@/features/finance/lib/position`, not from reading it.
    #[test]
    fn the_port_matches_the_typescript_number_for_number() {
        assert_eq!(from_statement_balance(Kind::Credit, usd(243_107)).minor, -243_107);
        assert_eq!(from_statement_balance(Kind::Credit, usd(-5_000)).minor, 5_000);
        assert_eq!(from_statement_balance(Kind::Checking, usd(120_000)).minor, 120_000);

        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), card()],
            &[bal("checking", 120_000), bal("card", -243_107)],
            Currency::USD,
        );
        assert_eq!(p.net_worth.minor, -123_107);
        assert_eq!(p.liquid.minor, 120_000);
        assert_eq!(p.total_debt.minor, 243_107);

        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), card(), loan()],
            &[bal("checking", 120_000), bal("card", -200_000), bal("loan", -800_000)],
            Currency::USD,
        );
        let c = p.accounts.iter().find(|a| a.account == "card").unwrap();
        assert_eq!(c.utilisation, Some(0.333));
        assert_eq!(c.available.unwrap().minor, 400_000);
        assert_eq!(c.daily_interest.unwrap().minor, 137);
        assert_eq!(p.weighted_apr, Some(0.1059));
        assert_eq!(p.minimums_due.minor, 31_000);
        assert_eq!(p.daily_interest.minor, 290);
        assert_eq!(annual_interest_cost(&p).minor, 105_850);
        assert_eq!(overall_utilisation(&p), Some(0.333));
        assert_eq!(by_cost(&p).iter().map(|a| a.account.as_str()).collect::<Vec<_>>(), ["card", "loan"]);
    }

    #[test]
    fn a_payment_from_chequing_to_a_card_moves_nothing() {
        // The proof the sign contract holds end to end. A model that reports an improvement in net
        // worth here is wrong in a way that feels like progress.
        let accounts = [acct("checking", Kind::Checking), card()];
        let balances = [bal("checking", 120_000), bal("card", -200_000)];
        let before = position(&led(&[]), &accounts, &balances, Currency::USD);
        let after = position(
            &led(&[tx("2026-06-10", "PAYMENT TO CARD", -30_000, "checking"), tx("2026-06-10", "PAYMENT RECEIVED", 30_000, "card")]),
            &accounts,
            &balances,
            Currency::USD,
        );
        assert_eq!(after.net_worth.minor, before.net_worth.minor);
        // Not a no-op though: liquidity fell and the debt shrank.
        assert_eq!(after.liquid.minor, 90_000);
        assert_eq!(after.total_debt.minor, 170_000);
    }

    #[test]
    fn only_what_came_after_the_stated_balance_is_applied() {
        // A transaction dated ON the balance date is already inside it. Applying it again
        // double-counts, and the result is still a plausible number.
        let p = position(
            &led(&[
                tx("2026-05-20", "BEFORE", -10_000, "checking"),
                tx("2026-06-01", "ON THE DATE", -5_000, "checking"),
                tx("2026-06-10", "AFTER", -2_500, "checking"),
            ]),
            &[acct("checking", Kind::Checking)],
            &[bal("checking", 120_000)],
            Currency::USD,
        );
        assert_eq!(p.accounts[0].rolled_forward, 1);
        assert_eq!(p.accounts[0].balance.minor, 117_500);
    }

    #[test]
    fn what_is_unknown_is_none_rather_than_zero() {
        // 0% utilised is an excellent score. Not knowing is not an excellent score.
        let no_limit = Account { credit_limit: None, ..card() };
        let p = position(&led(&[]), &[no_limit], &[bal("card", -200_000)], Currency::USD);
        assert_eq!(p.accounts[0].utilisation, None);
        assert_eq!(p.accounts[0].available, None);
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("UNKNOWN")));

        let no_apr = Account { apr_bps: None, ..card() };
        let p = position(&led(&[]), &[no_apr], &[bal("card", -200_000)], Currency::USD);
        assert_eq!(p.accounts[0].daily_interest, None);
        assert_eq!(p.weighted_apr, None);
        assert!(p.problems.iter().any(|x| x.contains("understate")));
    }

    #[test]
    fn a_cleared_debt_owes_nothing_costs_nothing_and_is_not_due_a_minimum() {
        let p = position(&led(&[]), &[card()], &[bal("card", 0)], Currency::USD);
        assert_eq!(p.accounts[0].owed, None);
        assert_eq!(p.accounts[0].utilisation, Some(0.0));
        assert_eq!(p.minimums_due.minor, 0);
        assert_eq!(p.daily_interest.minor, 0);
        assert_eq!(p.total_debt.minor, 0);
    }

    #[test]
    fn an_undeclared_account_is_named_and_left_out_rather_than_given_an_invented_sign() {
        let p = position(
            &led(&[tx("2026-06-10", "MYSTERY", -30_000, "unknown-account")]),
            &[acct("checking", Kind::Checking)],
            &[bal("checking", 120_000)],
            Currency::USD,
        );
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("'unknown-account'")));
        assert_eq!(p.net_worth.minor, 120_000);
    }

    #[test]
    fn another_currency_is_excluded_rather_than_converted() {
        let eur = Account { currency: "EUR".into(), ..acct("eu", Kind::Checking) };
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), eur],
            &[bal("checking", 120_000), bal("eu", 90_000)],
            Currency::USD,
        );
        assert_eq!(p.accounts.len(), 1);
        assert_eq!(p.net_worth.minor, 120_000);
        assert!(p.problems.iter().any(|x| x.contains("not one number")));
    }

    #[test]
    fn an_investment_counts_toward_net_worth_but_never_toward_liquidity() {
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), acct("broker", Kind::Investment)],
            &[bal("checking", 120_000), bal("broker", 4_000_000)],
            Currency::USD,
        );
        assert_eq!(p.net_worth.minor, 4_120_000);
        assert_eq!(p.liquid.minor, 120_000);
    }

    #[test]
    fn an_unreconciled_ledger_carries_its_caveat_forward_instead_of_being_laundered() {
        let l = unverified_ledger(&[], "2026-06-30", "Chase export has no opening balance").unwrap();
        let p = position(&l, &[acct("checking", Kind::Checking)], &[bal("checking", 120_000)], Currency::USD);
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("Chase export has no opening balance")));
        assert!(p.provenance.starts_with("UNVERIFIED"));
    }

    #[test]
    fn the_weighted_apr_weights_by_balance_not_by_account_count() {
        // $8,000 at 6.99% and $2,000 at 24.99% is not a 15.99% problem, and averaging the rates
        // would send somebody at the wrong debt first.
        let p = position(
            &led(&[]),
            &[card(), loan()],
            &[bal("card", -200_000), bal("loan", -800_000)],
            Currency::USD,
        );
        let w = p.weighted_apr.unwrap();
        assert!(w < (0.2499 + 0.0699) / 2.0, "weighted {w} should be below the plain mean");
        assert_eq!(w, 0.1059);
    }
}

//! Balances — and the conversion that has to happen at the boundary, not in somebody's head.
//!
//! # A person types what the statement prints
//!
//! That is the whole design constraint. A card statement says `2,431.07` and means you OWE it; a
//! chequing statement says `1,200.00` and means you HAVE it. The analysis needs both SIGNED by their
//! contribution to net worth, so something must convert — and asking a person to pre-negate a card
//! balance is asking them to get it wrong. They will type what they are looking at.
//!
//! So [`set_printed`] takes the printed figure and the account's KIND, and converts. Which means it
//! cannot store a balance for an account the registry has never heard of: without the kind, the sign
//! is not merely unknown, it is unknowable, and storing the number unconverted would put a debt into
//! net worth as an asset. The refusal is principled rather than fussy.
//!
//! # History is kept, and the LATEST is what gets used
//!
//! `position` rolls a balance forward with the transactions after it, so the most recent balance is
//! the one with the least rolling to do and therefore the least room for drift. Older ones are kept
//! rather than overwritten — a balance is an observation, and a store that forgets observations
//! cannot answer why a figure changed.
use crate::account::{Account, Kind};
use crate::money::{money, Currency, Money};
use crate::position::AccountBalance;
use crate::reconcile::StatementPeriod;

/// Record a balance from the figure a statement PRINTS.
///
/// The `kind` decides the sign, so this is the only place a printed number becomes a signed one.
pub fn from_printed(account: &str, as_of: &str, printed: Money, kind: Kind) -> AccountBalance {
    AccountBalance {
        account: account.to_string(),
        as_of: as_of.to_string(),
        balance: crate::position::from_statement_balance(kind, printed),
    }
}

/// The most recent balance for one account, or none.
///
/// LATEST, because `position` rolls forward from it: the nearer the observation, the fewer
/// transactions have to be applied on top and the less there is to get wrong.
pub fn latest_for<'a>(balances: &'a [AccountBalance], account: &str) -> Option<&'a AccountBalance> {
    balances.iter().filter(|b| b.account == account).max_by(|a, b| a.as_of.cmp(&b.as_of))
}

/// One balance per account — the set `position` actually consumes.
pub fn latest_each(balances: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut ids: Vec<&str> = balances.iter().map(|b| b.account.as_str()).collect();
    ids.sort();
    ids.dedup();
    ids.iter().filter_map(|id| latest_for(balances, id).cloned()).collect()
}

/// Add an observation, keeping every earlier one — unless it is the same account on the same DAY, in
/// which case it is a correction rather than a new observation and replaces it.
pub fn record(balances: &mut Vec<AccountBalance>, next: AccountBalance) {
    match balances.iter_mut().find(|b| b.account == next.account && b.as_of == next.as_of) {
        Some(slot) => *slot = next,
        None => {
            balances.push(next);
            balances.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
        }
    }
}

/// Accounts the registry declares that have no balance at all — the reason a position is missing a
/// row rather than showing it as zero.
pub fn without_balance(accounts: &[Account], balances: &[AccountBalance]) -> Vec<String> {
    accounts
        .iter()
        .filter(|a| latest_for(balances, &a.id).is_none())
        .map(|a| a.id.clone())
        .collect()
}

pub fn to_json(balances: &[AccountBalance]) -> serde_json::Value {
    serde_json::Value::Array(
        balances
            .iter()
            .map(|b| {
                serde_json::json!({
                    "account": b.account,
                    "asOf": b.as_of,
                    // SIGNED, and labelled as such — a reader that took this for a printed figure
                    // would negate every card balance back to wrong.
                    "signedMinor": b.balance.minor,
                    "currency": b.balance.currency.as_str(),
                })
            })
            .collect(),
    )
}

pub fn from_json(v: &serde_json::Value) -> Vec<AccountBalance> {
    let mut out: Vec<AccountBalance> = v
        .as_array()
        .map(Vec::as_slice)
        .unwrap_or_default()
        .iter()
        .filter_map(|b| {
            Some(AccountBalance {
                account: b.get("account")?.as_str()?.to_string(),
                as_of: b.get("asOf")?.as_str()?.to_string(),
                balance: money(
                    b.get("signedMinor")?.as_i64()?,
                    Currency::new(b.get("currency").and_then(|c| c.as_str()).unwrap_or("USD")).unwrap_or(Currency::USD),
                ),
            })
        })
        .collect();
    out.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
    out
}

/// The balances the STATEMENTS themselves assert.
///
/// A running-balance column is the institution stating what the account held when the period closed,
/// so a period's closing figure is an observation of exactly the kind a person supplies by typing
/// what the statement prints — arriving by a path that cannot mistype it. Deriving it is why
/// `bsc fin position` can answer at all from an export alone, instead of declaring an account and
/// then reporting that it has no balance.
///
/// The bounds arrive ALREADY SIGNED (`statement::period_from_running` converts at the boundary, for
/// `reconcile`'s sake), so nothing here converts. That is the one thing to know before editing this:
/// routing these through [`from_printed`] would negate every card balance a second time.
pub fn from_periods(periods: &[StatementPeriod]) -> Vec<AccountBalance> {
    periods
        .iter()
        .map(|p| AccountBalance { account: p.account.clone(), as_of: p.to.clone(), balance: p.closing })
        .collect()
}

/// Merge derived balances under observed ones — **the observed wins on the same day**.
///
/// Both are observations, so neither is categorically better; the tie-break is which one a person
/// can correct. A statement's closing figure is fixed by the export, while a balance somebody typed
/// is what they were looking at in the account — often BECAUSE the derived one looked wrong. Letting
/// the derivation overwrite that would make the correction impossible to express, and it would do it
/// silently, which is the part that matters.
///
/// A stored balance on any OTHER day is kept as its own observation rather than replacing anything —
/// [`record`]'s same-account-same-day rule is the whole of the collision policy.
pub fn prefer_observed(stored: &[AccountBalance], derived: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut out = derived.to_vec();
    for b in stored {
        record(&mut out, b.clone());
    }
    out
}

