                rows: vec![t("2026-01-15", "ACME PAYROLL", 250_000, "a"), t("2026-02-13", "ACME PAYROLL", 250_000, "a")],
                as_of: "2026-02-20",
                outflows_only: false,
                expect: vec![row("acme payroll", "a", Cadence::Monthly, 250_000, 3_000_000, 2, 0.97, 1.0, false)],
            },
            Case {
                name: "one occurrence is not a rhythm",
                rows: vec![t("2026-01-15", "ONEOFF", -500, "a")],
                as_of: "2026-02-20",
                outflows_only: true,
                expect: vec![],
            },
            Case {
                name: "an even count of amounts rounds the midpoint, and the spread is against THAT",
                rows: vec![t("2026-01-01", "CLOUD HOST", -1_000, "a"), t("2026-01-31", "CLOUD HOST", -2_000, "a"), t("2026-03-02", "CLOUD HOST", -3_000, "a"), t("2026-04-01", "CLOUD HOST", -5_000, "a")],
                as_of: "2026-04-10",
                outflows_only: true,
                expect: vec![row("cloud host", "a", Cadence::Monthly, 2_500, 30_000, 4, 1.0, 0.5, false)],
            },
        ]
    }

    #[test]
    fn every_case_matches_the_typescript_that_produced_it() {
        for c in cases() {
            let opts = DetectOptions { min_occurrences: 2, outflows_only: c.outflows_only, as_of: c.as_of };
            let got = detect_recurring(&c.rows, &opts);
            assert_eq!(got.len(), c.expect.len(), "{}: wrong number of findings — got {got:?}", c.name);
            for (g, e) in got.iter().zip(c.expect.iter()) {
                assert_eq!(g.key, e.key, "{}: key", c.name);
                assert_eq!(g.account, e.account, "{}: account", c.name);
                assert_eq!(g.cadence, e.cadence, "{}: cadence", c.name);
                assert_eq!(g.typical.minor, e.typical, "{}: typical", c.name);
                assert_eq!(g.annualised.minor, e.annualised, "{}: annualised", c.name);
                assert_eq!(g.occurrences, e.occurrences, "{}: occurrences", c.name);
                assert_eq!(g.regularity, e.regularity, "{}: regularity", c.name);
                assert_eq!(g.amount_stability, e.stability, "{}: amountStability", c.name);
                assert_eq!(g.lapsed, e.lapsed, "{}: lapsed", c.name);
            }
        }
    }

    #[test]
    fn the_parity_table_is_not_quietly_empty() {
        // A table that stopped being built would make the test above pass over nothing.
        assert!(cases().len() >= 13, "the parity table lost cases");
        assert!(cases().iter().any(|c| !c.expect.is_empty()), "every case expects nothing — the table is inert");
    }

    #[test]
    fn a_single_character_merchant_never_forms_a_group() {
        // merchantKey("X") is "", measured against the TypeScript. A group keyed on an empty string
        // would collapse every such row together, which is worse than dropping them.
        let rows = vec![t("2026-01-01", "X", -1_000, "a"), t("2026-01-31", "X", -1_000, "a")];
        assert!(detect_recurring(&rows, &DetectOptions::new("2026-02-05")).is_empty());
    }

    #[test]
    fn the_annual_total_counts_the_live_ones_only() {
        let rows = vec![
            t("2026-01-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-02-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-03-12", "NETFLIX.COM", -1_599, "a"),
            t("2025-01-10", "OLDSUB", -999, "a"),
            t("2025-02-10", "OLDSUB", -999, "a"),
        ];
        let rs = detect_recurring(&rows, &DetectOptions::new("2026-03-20"));
        assert_eq!(rs.len(), 2, "both are found");
        assert!(rs.iter().any(|r| r.lapsed), "the 2025 one has lapsed");
        // 1599 * 12 = 19188. The lapsed one contributes NOTHING.
        assert_eq!(total_annualised(&rs, Currency::USD).unwrap().minor, 19_188);
    }

    #[test]
    fn the_order_is_by_annual_cost_because_that_is_the_order_to_act_in() {
        let rows = vec![
            t("2026-01-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-02-12", "NETFLIX.COM", -1_599, "a"),
            t("2026-01-05", "RENT LANDLORD LLC", -120_000, "a"),
            t("2026-02-05", "RENT LANDLORD LLC", -120_000, "a"),
        ];
        let rs = detect_recurring(&rows, &DetectOptions::new("2026-02-20"));
        assert_eq!(rs.iter().map(|r| r.key.as_str()).collect::<Vec<_>>(), vec!["rent landlord", "netflix"]);
        // And the key keeps BOTH words. The TypeScript joins account and key with a NUL byte for
        // exactly this reason; a space would have truncated it to "rent".
        assert_eq!(rs[0].key, "rent landlord");
    }

    #[test]
    fn a_rhythm_matching_no_cadence_is_dropped_rather_than_forced_into_one() {
        // Measured against the TypeScript. 20/21 medians to 21, which is 7 off biweekly and 9 off
        // monthly — outside both tolerances, so there is no cadence to claim.
        let rows = vec![t("2026-01-01", "CORNER STORE", -1_000, "a"), t("2026-01-21", "CORNER STORE", -1_000, "a"), t("2026-02-11", "CORNER STORE", -1_000, "a")];
        assert!(detect_recurring(&rows, &DetectOptions::new("2026-02-20")).is_empty());
        assert_eq!(classify(&[20, 21]).0, Cadence::Irregular);
        assert_eq!(classify(&[2, 3]).0, Cadence::Irregular, "3 days is 4 off weekly");
        assert_eq!(classify(&[60, 60]).0, Cadence::Irregular, "60 days falls between monthly and quarterly");
        assert_eq!(classify(&[]).0, Cadence::Irregular);
    }

    #[test]
    fn a_near_miss_is_classified_and_then_scored_down_rather_than_hidden() {
        // 2 days then 47 medians to 25, inside monthly's tolerance of 5 — so it IS called monthly.
        // What says it is not a subscription is the REGULARITY of 0.25, which is the design: the
        // cadence is a bucket, the score is the evidence. Both numbers reach the reader.
        let (cadence, regularity) = classify(&[2, 47]);
        assert_eq!(cadence, Cadence::Monthly);
        assert_eq!(round2(regularity), 0.25, "measured by running finance-recurring.ts");
    }

    #[test]
    fn irregular_has_no_annual_multiplier_and_says_so() {
        assert_eq!(Cadence::Irregular.per_year(), None);
        assert_eq!(Cadence::Monthly.per_year(), Some(12));
    }

    #[test]
    fn the_median_rounds_an_even_midpoint_half_up() {
        assert_eq!(median(&[1_000, 2_000, 3_000, 5_000]), 2_500);
        assert_eq!(median(&[1, 2]), 2, "1.5 rounds to 2, matching Math.round");
        assert_eq!(median(&[1, 2, 3]), 2);
        assert_eq!(median(&[]), 0);
        // half-up is toward POSITIVE infinity, so -1.5 is -1. No caller can reach this today —
        // amounts are absolute and gaps are non-negative — and it is pinned so that stays a choice.
        assert_eq!(median(&[-2, -1]), -1);
    }
}

//! Income analysis — what arrives, how regularly, and how much it MOVES.
//!
//! The variance is the part that matters, and it is the part a mean destroys. Two people earning
//! $4,000 a month on average are in completely different situations if one is salaried and the other
//! invoices lumpily — the second has months that do not cover rent, and an average says nothing about
//! them. Every downstream question (runway, what payment is sustainable, whether a balance transfer
//! is safe) turns on the low months, not the typical one.
//!
//! So this reports a MEDIAN and a SPREAD per source, and classifies stability rather than collapsing
//! everything to one number that reads as more certain than it is.
use crate::money::{money, sum, Currency, Minor, Money};
use crate::txn::{days_between, merchant_key_default, month_of, Txn};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IncomeCadence {
    Weekly,
    Biweekly,
    /// Twice a month — the 1st and the 15th. NOT biweekly; see [`classify_cadence`].
    Semimonthly,
    Monthly,
    Irregular,
}

impl IncomeCadence {
    /// How many times this lands in an average month.
    ///
    /// Fractional on purpose: a weekly wage is 52 payments over 12 months, not 4. Rounding it to 4
    /// understates a year by four whole payments.
    pub fn per_month(self) -> Option<f64> {
        match self {
            IncomeCadence::Weekly => Some(52.0 / 12.0),
            IncomeCadence::Biweekly => Some(26.0 / 12.0),
            IncomeCadence::Semimonthly => Some(2.0),
            IncomeCadence::Monthly => Some(1.0),
            IncomeCadence::Irregular => None,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            IncomeCadence::Weekly => "weekly",
            IncomeCadence::Biweekly => "biweekly",
            IncomeCadence::Semimonthly => "semimonthly",
            IncomeCadence::Monthly => "monthly",
            IncomeCadence::Irregular => "irregular",
        }
    }
}

/// How much a source can be relied on, which is a different question from how much it pays.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Stability {
    Steady,
    Variable,
    Lumpy,
}

impl Stability {
    pub fn label(self) -> &'static str {
        match self {
            Stability::Steady => "steady",
            Stability::Variable => "variable",
            Stability::Lumpy => "lumpy",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct IncomeSource {
    pub key: String,
    /// The most recent description, so a person recognises it.
    pub label: String,
    pub account: String,
    pub cadence: IncomeCadence,
    /// MEDIAN receipt — not the mean. One large invoice must not move the figure everything else
    /// depends on.
    pub typical: Money,
    /// The smallest receipt observed. What a bad month actually looked like, which is the number a
    /// runway calculation should be using.
    pub low: Money,
    pub high: Money,
    pub occurrences: usize,
    pub first_seen: String,
    pub last_seen: String,
    /// 0-1, to two decimals. How close the receipts are to each other; 1 is identical every time.
    pub consistency: f64,
    pub stability: Stability,
    /// Typical amount scaled to a month at this cadence — comparable across sources.
    pub monthly_equivalent: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct IncomeAnalysis {
    pub sources: Vec<IncomeSource>,
    /// Median TOTAL across whole months observed. The honest "usual month".
    pub typical_month: Money,
    /// The worst whole month observed. What the plan has to survive.
    pub worst_month: Money,
    pub best_month: Money,
    /// Whole months the analysis is computed over. A figure from two months is not an income
    /// pattern, and stating the coverage is what stops it being read as one.
    pub months_observed: usize,
    /// Inbound money that matched no repeating source — one-offs, transfers, refunds. Reported
    /// rather than folded in: a tax refund is not income you can plan on receiving again.
    pub one_off: Vec<Txn>,
}

const CADENCE_DAYS: [(IncomeCadence, i64, i64); 4] = [
    (IncomeCadence::Weekly, 7, 2),
    (IncomeCadence::Biweekly, 14, 3),
    // Twice a month (the 1st and 15th) averages ~15.2 days and is NOT biweekly — 24 payments a year
    // against 26. Treating one as the other misstates annual income by two whole payments.
    (IncomeCadence::Semimonthly, 15, 2),
    (IncomeCadence::Monthly, 30, 5),
];

/// The median, matching `Math.round` on an even midpoint. See `recurring::median` for the same note.
fn median(xs: &[i64]) -> i64 {
    if xs.is_empty() {
        return 0;
    }
    let mut s = xs.to_vec();
    s.sort_unstable();
    let m = s.len() / 2;
    if s.len() % 2 == 1 {
        s[m]
    } else {
        let total = s[m - 1] + s[m];
        if total >= 0 { (total + 1).div_euclid(2) } else { -((-total).div_euclid(2)) }
    }
}

fn round2(x: f64) -> f64 {
    (x * 100.0).round() / 100.0
}

/// Which rhythm the gaps describe.
///
/// # Semimonthly against biweekly, and why a median cannot decide it
///
/// Getting this wrong costs two whole payments a year — 24 against 26 — which is a month and a half
/// of rent hidden inside the arithmetic. Paid on the 1st and 15th, the gaps ALTERNATE 14 and 16-17,
/// whose median lands exactly where biweekly lives. Paid every fortnight, the gaps are CONSTANT at
/// 14. That constancy is the discriminator, so it is what this checks rather than the average.
pub fn classify_cadence(gaps: &[i64]) -> IncomeCadence {
    if gaps.is_empty() {
        return IncomeCadence::Irregular;
    }
    let typical = median(gaps);
    if (13..=17).contains(&typical) {
        let hi = gaps.iter().max().copied().unwrap_or(0);
        let lo = gaps.iter().min().copied().unwrap_or(0);
        return if hi - lo >= 2 { IncomeCadence::Semimonthly } else { IncomeCadence::Biweekly };
    }
    CADENCE_DAYS
        .iter()
        .find(|(_, days, tol)| (typical - days).abs() <= *tol)
        .map(|(c, _, _)| *c)
        .unwrap_or(IncomeCadence::Irregular)
}

/// How tightly receipts cluster on the median, as a 0-1 score.
fn consistency_of(amounts: &[i64]) -> f64 {
    let mid = median(amounts);
    if mid == 0 {
        return 0.0;
    }
    let spread = amounts.iter().map(|v| (v - mid).abs() as f64).sum::<f64>() / amounts.len() as f64;
    (1.0 - spread / mid as f64).clamp(0.0, 1.0)
}

/// The thresholds are JUDGEMENTS, named so they can be argued with rather than reverse-engineered.
pub fn stability_of(consistency: f64) -> Stability {
    if consistency >= 0.9 {
        Stability::Steady
    } else if consistency >= 0.6 {
        Stability::Variable
    } else {
        Stability::Lumpy
    }
}

pub struct IncomeOptions {
    /// Fewest receipts before a source counts as a source rather than a one-off.
    pub min_occurrences: usize,
}

impl Default for IncomeOptions {
    fn default() -> Self {
        IncomeOptions { min_occurrences: 3 }
    }
}

pub fn analyse_income(txns: &[Txn], currency: Currency, opts: &IncomeOptions) -> IncomeAnalysis {
    let inbound: Vec<&Txn> = txns.iter().filter(|t| t.amount.minor > 0).collect();

    // Insertion-ordered for the same reason as `recurring`: the output sort is stable, so ties fall
    // back to first-seen order and a hash map would make that vary between runs.
    let mut groups: Vec<((String, String), Vec<&Txn>)> = Vec::new();
    for t in &inbound {
        let key = merchant_key_default(&t.description);
        if key.is_empty() {
            continue;
        }
        // A `(account, key)` PAIR. The TypeScript joins these with a NUL byte and says why: a
        // merchant key is several words and an account name commonly holds one too ("Chase
        // Freedom"), so a space separator makes the join ambiguous and splitting it back hands the
        // caller a key with account text inside it. A tuple has nothing to split.
        let id = (t.account.clone(), key);
        match groups.iter_mut().find(|(gid, _)| *gid == id) {
            Some((_, bucket)) => bucket.push(t),
            None => groups.push((id, vec![t])),
        }
    }

    let mut sources: Vec<IncomeSource> = Vec::new();
    // Claimed by IDENTITY, which in Rust is the row's position rather than an object reference.
    let mut claimed: Vec<bool> = vec![false; inbound.len()];
    for (id, rows) in groups {
        if rows.len() < opts.min_occurrences {
            continue;
        }
        let mut sorted = rows;
        sorted.sort_by(|a, b| a.date.cmp(&b.date));
        let gaps: Vec<i64> = sorted.windows(2).map(|w| days_between(&w[0].date, &w[1].date)).collect();
        let cadence = classify_cadence(&gaps);
        if cadence == IncomeCadence::Irregular {
            continue;
        }

        let amounts: Vec<i64> = sorted.iter().map(|t| t.amount.minor).collect();
        let consistency = round2(consistency_of(&amounts));
        let typical = money(median(&amounts), currency);
        for t in &sorted {
            if let Some(i) = inbound.iter().position(|r| std::ptr::eq(*r, *t)) {
                claimed[i] = true;
            }
        }

        let per_month = cadence.per_month().expect("a classified cadence is never irregular");
        let last = sorted[sorted.len() - 1];
        sources.push(IncomeSource {
            key: id.1,
            label: last.description.clone(),
            // The FIRST row's account, while the label is the LAST row's description. Both come
            // from the same group, so they cannot disagree — the asymmetry is the TypeScript's and
            // is preserved rather than tidied, since tidying it would be an unmeasured change.
            account: sorted[0].account.clone(),
            cadence,
            typical,
            low: money(*amounts.iter().min().expect("a group has rows"), currency),
            high: money(*amounts.iter().max().expect("a group has rows"), currency),
            occurrences: sorted.len(),
            first_seen: sorted[0].date.clone(),
            last_seen: last.date.clone(),
            consistency,
            stability: stability_of(consistency),
            // Every receipt is inbound and so positive, which makes `f64::round` (half away from
            // zero) and `Math.round` (half toward +infinity) agree here.
            monthly_equivalent: money((typical.minor as f64 * per_month).round() as Minor, currency),
        });
    }

    // WHOLE months only. A partial month at either end reads as a catastrophic drop and would drag
    // the worst-month figure — the one a plan is built on — to something that never happened.
    let mut by_month: Vec<(String, i64)> = Vec::new();
    for t in &inbound {
        let m = month_of(&t.date).to_string();
        match by_month.iter_mut().find(|(k, _)| *k == m) {
            Some((_, v)) => *v += t.amount.minor,
            None => by_month.push((m, t.amount.minor)),
        }
    }
    by_month.sort_by(|a, b| a.0.cmp(&b.0));
    // With two months or fewer there is nothing to trim TO, so both partials are kept and
    // `months_observed` says how thin the basis is. Trimming here would leave zero months and
    // report every figure as 0, which reads as "no income" rather than "not enough data".
    let whole: &[(String, i64)] = if by_month.len() > 2 { &by_month[1..by_month.len() - 1] } else { &by_month };
    let totals: Vec<i64> = whole.iter().map(|(_, v)| *v).collect();

    sources.sort_by_key(|s| std::cmp::Reverse(s.monthly_equivalent.minor));
    IncomeAnalysis {
        sources,
        typical_month: money(if totals.is_empty() { 0 } else { median(&totals) }, currency),
        worst_month: money(totals.iter().min().copied().unwrap_or(0), currency),
        best_month: money(totals.iter().max().copied().unwrap_or(0), currency),
        months_observed: totals.len(),
        one_off: inbound.iter().enumerate().filter(|(i, _)| !claimed[*i]).map(|(_, t)| (*t).clone()).collect(),
    }
}

/// Every source's monthly equivalent, together.
pub fn expected_monthly(a: &IncomeAnalysis, currency: Currency) -> Result<Money, crate::money::CurrencyMismatch> {
    let each: Vec<Money> = a.sources.iter().map(|s| s.monthly_equivalent).collect();
    sum(&each, currency)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn t(date: &str, description: &str, minor: Minor) -> Txn {
        Txn { account: "a".to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn analyse(rows: &[Txn]) -> IncomeAnalysis {
        analyse_income(rows, Currency::USD, &IncomeOptions::default())
    }

    /// Every expectation below was taken by TRANSPILING AND RUNNING `finance-income.ts`.
    #[test]
    fn a_biweekly_salary_is_twenty_six_payments_a_year_not_twenty_four() {
        let rows: Vec<Txn> = ["2026-01-02", "2026-01-16", "2026-01-30", "2026-02-13", "2026-02-27", "2026-03-13", "2026-03-27", "2026-04-10"]
            .iter()
            .map(|d| t(d, "ACME PAYROLL", 200_000))
            .collect();
        let a = analyse(&rows);
        assert_eq!(a.sources.len(), 1);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Biweekly);
        assert_eq!(s.typical.minor, 200_000);
        assert_eq!(s.consistency, 1.0);
        assert_eq!(s.stability, Stability::Steady);
        // 200000 * 26/12 = 433333.33 → 433333. At 4 payments a month it would read 800000, which is
        // the error this cadence exists to avoid.
        assert_eq!(s.monthly_equivalent.minor, 433_333);
        assert_eq!(a.months_observed, 2, "Jan and Apr are partial and are trimmed");
        assert_eq!(a.typical_month.minor, 400_000);
    }

    #[test]
    fn the_first_and_the_fifteenth_is_semimonthly_and_the_alternating_gap_is_what_says_so() {
        let rows: Vec<Txn> = ["2026-01-01", "2026-01-15", "2026-02-01", "2026-02-15", "2026-03-01", "2026-03-15", "2026-04-01"]
            .iter()
            .map(|d| t(d, "STATE PAYROLL", 150_000))
            .collect();
        let a = analyse(&rows);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Semimonthly, "the gaps alternate, so this is 24 a year");
        assert_eq!(s.monthly_equivalent.minor, 300_000);
        // A constant fortnight is the other answer, from the same median.
        assert_eq!(classify_cadence(&[14, 14, 14]), IncomeCadence::Biweekly);
        assert_eq!(classify_cadence(&[14, 17, 14, 17]), IncomeCadence::Semimonthly);
        // Two payments a month is 24 a year; a fortnight is 26. That gap is the whole point.
        assert_eq!(IncomeCadence::Semimonthly.per_month(), Some(2.0));
        assert!(IncomeCadence::Biweekly.per_month().unwrap() > 2.0);
    }

    #[test]
    fn a_lumpy_freelancer_reports_the_low_month_not_the_average() {
        let rows = vec![
            t("2026-01-05", "CLIENT INVOICE", 300_000),
            t("2026-02-04", "CLIENT INVOICE", 50_000),
            t("2026-03-06", "CLIENT INVOICE", 420_000),
            t("2026-04-05", "CLIENT INVOICE", 120_000),
        ];
        let a = analyse(&rows);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Monthly);
        assert_eq!(s.typical.minor, 210_000, "the median of the four receipts");
        assert_eq!(s.low.minor, 50_000, "the number a runway has to survive");
        assert_eq!(s.high.minor, 420_000);
        assert_eq!(s.consistency, 0.35);
        assert_eq!(s.stability, Stability::Lumpy);
        // The MEAN of the four is 222500, which is 4.45x the worst month. Nothing here reports it.
        assert_eq!(a.worst_month.minor, 50_000);
        assert_eq!(a.typical_month.minor, 235_000);
        assert_eq!(a.best_month.minor, 420_000);
    }

    #[test]
    fn a_weekly_wage_is_fifty_two_payments_a_year() {
        let rows: Vec<Txn> = [("2026-01-02", 40_000), ("2026-01-09", 42_000), ("2026-01-16", 38_000), ("2026-01-23", 41_000), ("2026-01-30", 39_000), ("2026-02-06", 40_000), ("2026-02-13", 40_000), ("2026-02-20", 40_000)]
            .iter()
            .map(|(d, m)| t(d, "GIG PLATFORM", *m))
            .collect();
        let a = analyse(&rows);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Weekly);
        assert_eq!(s.consistency, 0.98);
        assert_eq!(s.stability, Stability::Steady);
        // 40000 * 52/12 = 173333.33 → 173333, not 160000.
        assert_eq!(s.monthly_equivalent.minor, 173_333);
    }

    #[test]
    fn a_tax_refund_is_reported_as_a_one_off_rather_than_folded_into_income() {
        let mut rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30"].iter().map(|d| t(d, "ACME PAYROLL", 400_000)).collect();
        rows.push(t("2026-02-10", "IRS TREAS REFUND", 180_000));
        let a = analyse(&rows);
        assert_eq!(a.sources.len(), 1, "the refund is not a source");
        assert_eq!(a.one_off.len(), 1);
        assert_eq!(a.one_off[0].description, "IRS TREAS REFUND");
        // It DOES move the month totals, because the money genuinely arrived — what it must not do
        // is become something the plan expects again.
        assert_eq!(a.best_month.minor, 580_000);
        assert_eq!(a.worst_month.minor, 400_000);
        assert_eq!(expected_monthly(&a, Currency::USD).unwrap().minor, 400_000, "the expectation excludes it");
    }

    #[test]
    fn two_months_of_data_keeps_both_partials_rather_than_trimming_to_nothing() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31"].iter().map(|d| t(d, "ACME PAYROLL", 400_000)).collect();
        let a = analyse(&rows);
        // Three CALENDAR months, so one is left after trimming.
        assert_eq!(a.months_observed, 1);
        assert_eq!(a.typical_month.minor, 400_000);
    }

    #[test]
    fn too_few_receipts_is_not_a_source_and_the_rows_stay_visible_as_one_offs() {
        let rows = vec![t("2026-01-05", "CLIENT INVOICE", 300_000), t("2026-02-04", "CLIENT INVOICE", 300_000)];
        let a = analyse(&rows);
        assert!(a.sources.is_empty(), "two receipts is below the default of three");
        assert_eq!(a.one_off.len(), 2, "and they are NOT silently dropped");
        assert_eq!(expected_monthly(&a, Currency::USD).unwrap().minor, 0);
    }

    #[test]
    fn nothing_inbound_reports_absence_rather_than_a_confident_zero_pattern() {
        let a = analyse(&[t("2026-01-05", "RENT LANDLORD LLC", -120_000)]);
        assert!(a.sources.is_empty());
        assert_eq!(a.months_observed, 0, "zero months observed is what says there is no basis");
        assert_eq!(a.typical_month.minor, 0);
        assert!(a.one_off.is_empty());
    }

    #[test]
    fn the_stability_thresholds_are_where_they_say_they_are() {
        assert_eq!(stability_of(0.9), Stability::Steady);
        assert_eq!(stability_of(0.89), Stability::Variable);
        assert_eq!(stability_of(0.6), Stability::Variable);
        assert_eq!(stability_of(0.59), Stability::Lumpy);
    }

    #[test]
    fn an_unrecognisable_rhythm_yields_no_source() {
        assert_eq!(classify_cadence(&[]), IncomeCadence::Irregular);
        assert_eq!(classify_cadence(&[60, 60]), IncomeCadence::Irregular);
        assert_eq!(IncomeCadence::Irregular.per_month(), None);
    }
}

//! Income projection — a BAND, its assumptions written down, and a REFUSAL when the history is thin.
//!
//! A projection is the point where analysis stops describing and starts being acted on: it is what a
//! runway figure divides by, what a payoff schedule promises against, and what decides whether a
//! balance transfer is safe. So the failure mode is not inaccuracy — it is a single confident number
//! that hides how little it knows.
//!
//! Three commitments follow, and each is enforced here rather than left to the reader:
//!
//! 1. **A BAND, NEVER A POINT.** Low / expected / high, every month. The low is the one a plan is
//!    built on; the expected is the one a plan is *hoped* on.
//! 2. **THE BAND WIDENS WITH DISTANCE.** Month six is not as knowable as month one. A flat band
//!    asserts that it is, which is the specific lie that makes a twelve-month plan collapse in
//!    month four.
//! 3. **IT REFUSES.** Given two months of history it returns [`IncomeProjection::projectable`] false
//!    and no numbers — not a band of zeroes, which reads as "you will earn nothing" and is worse
//!    than saying nothing.
use crate::income::{IncomeAnalysis, IncomeCadence, IncomeSource};
use crate::money::{money, sum, Currency, Minor, Money};
use crate::txn::{days_between, month_of};

#[derive(Debug, Clone, PartialEq)]
pub struct MonthBand {
    /// `YYYY-MM`.
    pub month: String,
    /// What the month looks like if everything that can reasonably go wrong does. Plan on this.
    pub low: Money,
    /// The median-driven figure. Hope on this.
    pub expected: Money,
    pub high: Money,
}

/// Why a source the analysis found is not in the projection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExclusionReason {
    Lapsed,
}

impl ExclusionReason {
    pub fn label(self) -> &'static str {
        match self {
            ExclusionReason::Lapsed => "lapsed",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct ExcludedSource {
    pub key: String,
    pub label: String,
    pub reason: ExclusionReason,
    pub last_seen: String,
    /// What it WOULD have contributed. Named so the size of the exclusion is visible.
    pub monthly_equivalent: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ProjectionTotal {
    pub low: Money,
    pub expected: Money,
    pub high: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct IncomeProjection {
    pub projectable: bool,
    /// Present ONLY when `projectable` is false, and it says what was missing.
    pub reason: Option<String>,
    /// Empty when not projectable — never a band of zeroes.
    pub months: Vec<MonthBand>,
    /// Absent when not projectable, so a caller cannot accidentally add zero into a runway.
    pub total: Option<ProjectionTotal>,
    /// Every judgement this projection made, in prose, for the reader to disagree with.
    pub assumptions: Vec<String>,
    pub excluded: Vec<ExcludedSource>,
    pub sources_used: usize,
}

pub struct ProjectionOptions<'a> {
    /// `YYYY-MM-DD` — what "now" is. Passed IN, never read from a clock.
    pub as_of: &'a str,
    /// How many months forward.
    pub months: usize,
    /// Fewest WHOLE months of history before a projection is honest. Below it, this refuses.
    pub min_months_observed: usize,
    /// A source unseen for this many of its own periods is treated as ended.
    pub lapse_factor: f64,
    /// How much the band widens per month out, as a fraction of the observed spread.
    pub drift_per_month: f64,
    /// Widening applied per month EVEN TO A PERFECTLY STEADY SOURCE, as a fraction of expected.
    /// Four months of an identical salary is not evidence that a salary cannot stop; a band that
    /// stayed pinned to the observed spread would say it is.
    pub floor_uncertainty: f64,
}

impl<'a> ProjectionOptions<'a> {
    /// The defaults the TypeScript kit applies when the caller supplies only `asOf`.
    pub fn new(as_of: &'a str) -> Self {
        ProjectionOptions { as_of, months: 6, min_months_observed: 3, lapse_factor: 2.5, drift_per_month: 0.15, floor_uncertainty: 0.02 }
    }
}

/// Nominal days between receipts at each cadence — what "overdue" is measured against.
///
/// Fractional for the two that do not divide a month evenly. Rounding semimonthly to 15 and monthly
/// to 30 would make every source drift a little early into "lapsed" over a long history.
fn cadence_days(c: IncomeCadence) -> Option<f64> {
    match c {
        IncomeCadence::Weekly => Some(7.0),
        IncomeCadence::Biweekly => Some(14.0),
        IncomeCadence::Semimonthly => Some(15.2),
        IncomeCadence::Monthly => Some(30.4),
        IncomeCadence::Irregular => None,
    }
}

/// `YYYY-MM` arithmetic. PROPER MODULO, so stepping backwards over a year boundary works — `%` on a
/// negative in both Rust and JavaScript yields a negative, and `2026-01` minus one month would land
/// on month `-1` rather than December.
pub fn add_months(ym: &str, n: i64) -> String {
    let year: i64 = ym[0..4].parse().unwrap_or(0);
    let month: i64 = ym[5..7].parse().unwrap_or(1);
    let total = year * 12 + (month - 1) + n;
    let mm = total.rem_euclid(12);
    let yy = (total - mm) / 12;
    format!("{yy:04}-{:02}", mm + 1)
}

/// A source is ended, not merely late, once it is overdue by several of its own periods.
fn is_lapsed(s: &IncomeSource, as_of: &str, lapse_factor: f64) -> bool {
    match cadence_days(s.cadence) {
        None => false,
        Some(period) => days_between(&s.last_seen, as_of) as f64 > period * lapse_factor,
    }
}

/// A source's smallest and largest receipt, scaled to a month the same way `typical` was.
fn monthly_range(s: &IncomeSource) -> (Minor, Minor) {
    if s.typical.minor == 0 {
        return (0, 0);
    }
    let per_month = s.monthly_equivalent.minor as f64 / s.typical.minor as f64;
    ((s.low.minor as f64 * per_month).round() as Minor, (s.high.minor as f64 * per_month).round() as Minor)
}

pub fn project_income(analysis: &IncomeAnalysis, currency: Currency, opts: &ProjectionOptions) -> IncomeProjection {
    let mut excluded: Vec<ExcludedSource> = Vec::new();
    let mut live: Vec<&IncomeSource> = Vec::new();
    for s in &analysis.sources {
        if is_lapsed(s, opts.as_of, opts.lapse_factor) {
            // A CONTRACT THAT ENDED IS NOT INCOME. Projecting a source last seen four months ago
            // forward for another six is the most expensive mistake this module can make, because
            // it is invisible: the total looks healthy and every downstream figure inherits money
            // that is not coming.
            excluded.push(ExcludedSource {
                key: s.key.clone(),
                label: s.label.clone(),
                reason: ExclusionReason::Lapsed,
                last_seen: s.last_seen.clone(),
                monthly_equivalent: s.monthly_equivalent,
            });
            continue;
        }
        live.push(s);
    }

    let refuse = |reason: String, excluded: Vec<ExcludedSource>| IncomeProjection {
        projectable: false,
        reason: Some(reason),
        months: Vec::new(),
        total: None,
        assumptions: Vec::new(),
        excluded,
        sources_used: 0,
    };

    if analysis.months_observed < opts.min_months_observed {
        let r = format!(
            "{} whole month(s) of history; {} are needed before a projection means anything",
            analysis.months_observed, opts.min_months_observed
        );
        return refuse(r, excluded);
    }
    if live.is_empty() {
        let r = if excluded.is_empty() {
            "no repeating income source was found".to_string()
        } else {
            let latest = excluded.iter().map(|e| e.last_seen.clone()).max().unwrap_or_default();
            format!("every income source has lapsed — the most recent receipt was {latest}")
        };
        return refuse(r, excluded);
    }

    let each: Vec<Money> = live.iter().map(|s| s.monthly_equivalent).collect();
    // Every source came from one analysis over one currency, so this cannot mismatch; falling back
    // to zero would be a silent wrong answer, so it refuses instead.
    let Ok(expected_money) = sum(&each, currency) else {
        return refuse("income sources are denominated in more than one currency, which this cannot add".to_string(), excluded);
    };
    let expected = expected_money.minor;
    let ranges: Vec<(Minor, Minor)> = live.iter().map(|s| monthly_range(s)).collect();
    let source_low: Minor = ranges.iter().map(|r| r.0).sum();
    let source_high: Minor = ranges.iter().map(|r| r.1).sum();

    // THE FLOOR HONOURS THE WORST MONTH THAT ACTUALLY HAPPENED. Summing each source's smallest
    // payment assumes every source paid — but a month where one simply did not pay is worse than
    // that sum, and it is the month a plan has to survive. Whichever is lower wins.
    let worst = analysis.worst_month.minor;
    let clamped = worst < source_low;
    let low_base = if clamped { worst } else { source_low };
    let high_base = source_high.max(expected);

    let start = month_of(opts.as_of).to_string();
    let mut bands: Vec<MonthBand> = Vec::new();
    for i in 0..opts.months {
        let widen = 1.0 + opts.drift_per_month * i as f64;
        let floor = opts.floor_uncertainty * (i + 1) as f64 * expected as f64;
        let low = (expected as f64 - ((expected - low_base) as f64 * widen + floor)).round().max(0.0) as Minor;
        let high = (expected as f64 + ((high_base - expected) as f64 * widen + floor)).round() as Minor;
        bands.push(MonthBand {
            // The month `as_of` falls in is already partly spent, so the projection starts at the NEXT one.
            month: add_months(&start, i as i64 + 1),
            low: money(low, currency),
            expected: money(expected, currency),
            high: money(high, currency),
        });
    }

    let mut assumptions = vec![
        format!("Projected from {} whole month(s) of history across {} repeating source(s).", analysis.months_observed, live.len()),
        "Expected is each source's MEDIAN receipt scaled to a month, so one unusually large payment does not move it.".to_string(),
        format!(
            "The band widens {}% of the observed spread per month, plus {}% of expected — month {} is less certain than month 1, and the numbers say so.",
            (opts.drift_per_month * 100.0).round(),
            (opts.floor_uncertainty * 100.0).round(),
            opts.months
        ),
        format!("Starts at {}: the month containing {} is already partly spent.", bands.first().map(|b| b.month.as_str()).unwrap_or(""), opts.as_of),
    ];
    if clamped {
        assumptions.push(
            "The floor uses the worst whole month observed rather than the sum of each source's smallest payment — a month where a source did not pay at all is worse than a month where it paid little.".to_string(),
        );
    }
    if !analysis.one_off.is_empty() {
        let amounts: Vec<Money> = analysis.one_off.iter().map(|t| t.amount).collect();
        if let Ok(total) = sum(&amounts, currency) {
            assumptions.push(format!(
                "{} one-off receipt(s) totalling {} minor units are NOT projected — a refund is not income you can plan on receiving again.",
                analysis.one_off.len(),
                total.minor
            ));
        }
    }
    if !excluded.is_empty() {
        let names: Vec<String> = excluded.iter().map(|e| format!("{} (last seen {})", e.label, e.last_seen)).collect();
        assumptions.push(format!("{} source(s) excluded as lapsed: {}.", excluded.len(), names.join(", ")));
    }

    let lows: Vec<Money> = bands.iter().map(|b| b.low).collect();
    let exps: Vec<Money> = bands.iter().map(|b| b.expected).collect();
    let highs: Vec<Money> = bands.iter().map(|b| b.high).collect();
    let total = match (sum(&lows, currency), sum(&exps, currency), sum(&highs, currency)) {
        (Ok(low), Ok(expected), Ok(high)) => Some(ProjectionTotal { low, expected, high }),
        _ => None,
    };

    IncomeProjection { projectable: true, reason: None, months: bands, total, assumptions, excluded, sources_used: live.len() }
}

/// The band for one month of a projection, or none if it is outside the horizon.
pub fn band_for<'a>(p: &'a IncomeProjection, month: &str) -> Option<&'a MonthBand> {
    p.months.iter().find(|b| b.month == month)
}

/// What the projection says is safe to commit to per month.
///
/// The LOW of the FURTHEST month, because a commitment made now has to survive the least certain
/// month it reaches. Taking month one's low would price a twelve-month commitment off the one month
/// the projection knows most about.
pub fn committable_monthly(p: &IncomeProjection) -> Option<Money> {
    if !p.projectable {
        return None;
    }
    p.months.last().map(|b| b.low)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::income::{analyse_income, IncomeOptions};
    use crate::money::usd;
    use crate::txn::Txn;

    // SYNTHETIC FIXTURES ONLY.
    fn t(date: &str, description: &str, minor: Minor) -> Txn {
        Txn { account: "a".to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn project(rows: &[Txn], as_of: &str, months: usize) -> IncomeProjection {
        let a = analyse_income(rows, Currency::USD, &IncomeOptions::default());
        project_income(&a, Currency::USD, &ProjectionOptions { months, ..ProjectionOptions::new(as_of) })
    }

    #[test]
    fn month_arithmetic_steps_backwards_over_a_year_boundary() {
        // Measured against the TypeScript. `%` on a negative is negative in both languages, so a
        // naive modulo puts January minus one month on month -1 rather than December.
        assert_eq!(add_months("2026-01", 1), "2026-02");
        assert_eq!(add_months("2026-01", -1), "2025-12");
        assert_eq!(add_months("2026-01", 12), "2027-01");
        assert_eq!(add_months("2026-01", -13), "2024-12");
        assert_eq!(add_months("2026-12", 1), "2027-01");
        assert_eq!(add_months("2026-03", -5), "2025-10");
        assert_eq!(add_months("2026-06", 0), "2026-06");
    }

    #[test]
    fn a_steady_salary_still_widens_because_a_salary_can_stop() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-29", "2026-06-30", "2026-07-31"]
            .iter()
            .map(|d| t(d, "ACME PAYROLL", 400_000))
            .collect();
        let p = project(&rows, "2026-07-15", 3);
        assert!(p.projectable);
        assert_eq!(p.sources_used, 1);
        let got: Vec<(&str, i64, i64, i64)> = p.months.iter().map(|b| (b.month.as_str(), b.low.minor, b.expected.minor, b.high.minor)).collect();
        // Seven identical payments and the band STILL opens 2% of expected per month. That is the
        // floorUncertainty doing its job: a perfect history is not evidence of a perfect future.
        assert_eq!(got, vec![("2026-08", 392_000, 400_000, 408_000), ("2026-09", 384_000, 400_000, 416_000), ("2026-10", 376_000, 400_000, 424_000)]);
        assert_eq!(p.total.as_ref().unwrap().low.minor, 1_152_000);
        assert_eq!(p.total.as_ref().unwrap().expected.minor, 1_200_000);
        assert_eq!(p.total.as_ref().unwrap().high.minor, 1_248_000);
        // The commitment figure is the FURTHEST month's low, not the nearest.
        assert_eq!(committable_monthly(&p).unwrap().minor, 376_000);
        assert_eq!(band_for(&p, "2026-09").unwrap().low.minor, 384_000);
        assert!(band_for(&p, "2026-12").is_none(), "outside the horizon is absent, not zero");
    }

    #[test]
    fn a_lumpy_income_reaches_a_floor_of_zero_and_says_so_rather_than_flattering_itself() {
        let rows: Vec<Txn> = [("2026-01-05", 300_000), ("2026-02-04", 50_000), ("2026-03-06", 420_000), ("2026-04-05", 120_000), ("2026-05-05", 260_000), ("2026-06-04", 310_000)]
            .iter()
            .map(|(d, m)| t(d, "CLIENT INVOICE", *m))
            .collect();
        let p = project(&rows, "2026-06-20", 4);
        let got: Vec<(&str, i64, i64, i64)> = p.months.iter().map(|b| (b.month.as_str(), b.low.minor, b.expected.minor, b.high.minor)).collect();
        assert_eq!(
            got,
            vec![("2026-07", 44_400, 280_000, 425_600), ("2026-08", 4_300, 280_000, 452_200), ("2026-09", 0, 280_000, 478_800), ("2026-10", 0, 280_000, 505_400)]
        );
        // By month three the honest floor is nothing. A point estimate of 280000 would have said
        // this person can commit to a payment they might not be able to make.
        assert_eq!(committable_monthly(&p).unwrap().minor, 0);
    }

    #[test]
    fn thin_history_refuses_rather_than_returning_a_band_of_zeroes() {
        let rows: Vec<Txn> = ["2026-05-31", "2026-06-30", "2026-07-31"].iter().map(|d| t(d, "ACME PAYROLL", 400_000)).collect();
        let p = project(&rows, "2026-07-15", 3);
        assert!(!p.projectable);
        assert_eq!(p.reason.as_deref(), Some("1 whole month(s) of history; 3 are needed before a projection means anything"));
        assert!(p.months.is_empty(), "no numbers at all");
        // A band of zeroes reads as "you will earn nothing"; ABSENT reads as "this does not know".
        assert!(p.total.is_none(), "the total is ABSENT so a runway cannot add zero into itself");
        assert!(committable_monthly(&p).is_none());
        assert!(p.assumptions.is_empty(), "a refusal makes no assumptions to disagree with");
    }

    #[test]
    fn a_contract_that_ended_is_excluded_and_the_size_of_the_exclusion_is_named() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-29"].iter().map(|d| t(d, "OLD CONTRACT", 400_000)).collect();
        let p = project(&rows, "2026-09-01", 3);
        assert!(!p.projectable, "every source lapsed, so there is nothing to project");
        assert_eq!(p.reason.as_deref(), Some("every income source has lapsed — the most recent receipt was 2026-05-29"));
        assert_eq!(p.excluded.len(), 1);
        assert_eq!(p.excluded[0].reason, ExclusionReason::Lapsed);
        assert_eq!(p.excluded[0].last_seen, "2026-05-29");
        // What it WOULD have contributed, so the hole is visible rather than merely missing.
        assert_eq!(p.excluded[0].monthly_equivalent.minor, 400_000);
    }

    #[test]
    fn lapse_is_measured_in_the_sources_own_periods_not_a_fixed_window() {
        let weekly = IncomeSource {
            key: "gig".into(), label: "GIG".into(), account: "a".into(), cadence: IncomeCadence::Weekly,
            typical: usd(40_000), low: usd(40_000), high: usd(40_000), occurrences: 8,
            first_seen: "2026-01-02".into(), last_seen: "2026-02-20".into(), consistency: 1.0,
            stability: crate::income::Stability::Steady, monthly_equivalent: usd(173_333),
        };
        let monthly = IncomeSource { cadence: IncomeCadence::Monthly, ..weekly.clone() };
        // 25 days on: a WEEKLY source is long gone (7 * 2.5 = 17.5), a MONTHLY one is not yet due
        // to worry (30.4 * 2.5 = 76). A single fixed window would call both the same.
        assert!(is_lapsed(&weekly, "2026-03-17", 2.5));
        assert!(!is_lapsed(&monthly, "2026-03-17", 2.5));
        // An unclassifiable cadence has no period to measure against, so it is never called lapsed.
        let irregular = IncomeSource { cadence: IncomeCadence::Irregular, ..weekly.clone() };
        assert!(!is_lapsed(&irregular, "2030-01-01", 2.5));
    }

    #[test]
    fn the_assumptions_are_written_down_for_the_reader_to_disagree_with() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-29", "2026-06-30", "2026-07-31"]
            .iter()
            .map(|d| t(d, "ACME PAYROLL", 400_000))
            .collect();
        let p = project(&rows, "2026-07-15", 3);
        assert_eq!(p.assumptions.len(), 4, "measured against the TypeScript");
        assert!(p.assumptions.iter().any(|a| a.contains("MEDIAN")), "the median choice is stated");
        assert!(p.assumptions.iter().any(|a| a.contains("already partly spent")), "the start month is justified");
        assert!(p.assumptions.iter().any(|a| a.contains("15% of the observed spread")), "the widening rate is stated");
    }

    #[test]
    fn nothing_to_project_is_a_refusal_that_names_which_emptiness_it_is() {
        let a = analyse_income(&[t("2026-01-05", "RENT LANDLORD LLC", -120_000)], Currency::USD, &IncomeOptions::default());
        let p = project_income(&a, Currency::USD, &ProjectionOptions::new("2026-07-15"));
        assert!(!p.projectable);
        // Zero months of history is a DIFFERENT problem from having sources that all lapsed, and
        // the reason says which — one is answered by waiting, the other by finding work.
        assert_eq!(p.reason.as_deref(), Some("0 whole month(s) of history; 3 are needed before a projection means anything"));
    }
}

//! The obligation calendar — what is due, on what day, between now and the horizon.
//!
//! A monthly total is the wrong shape for the question people actually have. Rent on the 1st, a card
//! minimum on the 3rd and an insurance renewal on the 5th is a very different week from the same
//! money spread across thirty days, and a month-level figure cannot see the difference. The failure
//! this prevents is arriving at a heavy week with a balance that was, on a monthly view, fine.
//!
//! # Stepping is the whole problem, and it is not obvious
//!
//! A monthly charge is NOT every 30 days. Step a 15 January bill by 30 days twelve times and it lands
//! on 11 December — five days and, at the boundaries, a whole month wrong. Billing anniversaries are
//! CALENDAR facts, so monthly, quarterly and annual step by calendar months and keep their day, while
//! weekly and biweekly step by days because that is what they actually are.
//!
//! And **the anchor never moves**. A bill on the 31st stepped into February CLAMPS to the 28th for
//! that month, then returns to the 31st in March — it does not walk backwards a few days a year, and
//! it certainly does not roll over into the following month, which is what naive date arithmetic
//! does.
use crate::money::{money, sum, Currency, Money};
use crate::position::Position;
use crate::recurring::{Cadence, Recurring};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ObligationKind {
    Recurring,
    Minimum,
}

impl ObligationKind {
    pub fn label(self) -> &'static str {
        match self {
            ObligationKind::Recurring => "recurring",
            ObligationKind::Minimum => "minimum",
        }
    }
}

/// How much the DATE is to be trusted. The amount is a separate question.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Confidence {
    Observed,
    Assumed,
}

impl Confidence {
    pub fn label(self) -> &'static str {
        match self {
            Confidence::Observed => "observed",
            Confidence::Assumed => "assumed",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Obligation {
    /// `YYYY-MM-DD` it is expected to hit.
    pub date: String,
    pub label: String,
    pub account: String,
    /// POSITIVE amount due — a calendar of outgoings does not need signs to say which way they go.
    pub amount: Money,
    pub kind: ObligationKind,
    pub confidence: Confidence,
    /// For a recurring charge, how metronomic the observed occurrences were.
    pub regularity: Option<f64>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MonthTotal {
    pub month: String,
    pub total: Money,
    pub count: usize,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ObligationCalendar {
    pub from: String,
    pub to: String,
    pub obligations: Vec<Obligation>,
    pub by_month: Vec<MonthTotal>,
    /// The month that costs the most. The one to have money in place for.
    pub heaviest: Option<MonthTotal>,
    /// Everything the calendar DECIDED rather than observed.
    pub notes: Vec<String>,
}

pub struct CalendarOptions<'a> {
    pub from: &'a str,
    pub to: &'a str,
    /// Day of the month a debt's minimum is actually due, where it is known.
    pub minimum_due_day: &'a [(String, u32)],
    /// Include charges that look cancelled. Off by default; they are reported as a note either way.
    pub include_lapsed: bool,
}

impl<'a> CalendarOptions<'a> {
    pub fn new(from: &'a str, to: &'a str) -> Self {
        CalendarOptions { from, to, minimum_due_day: &[], include_lapsed: false }
    }
}

/// Days in the month containing `y`/`m` (1-based month).
pub fn days_in_month(y: i64, m: i64) -> i64 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        // The full Gregorian rule, not the every-four-years approximation: 2100 is NOT a leap year,
        // and a calendar that says a bill falls on 29 February 2100 is simply wrong.
        2 if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 => 29,
        2 => 28,
        _ => 30,
    }
}

/// `YYYY-MM-DD` plus `n` days.
pub fn add_days(iso: &str, n: i64) -> String {
    match crate::session::epoch_seconds(&format!("{iso}T00:00:00Z")) {
        Some(secs) => crate::session::iso_from_epoch(secs + n * 86_400)[..10].to_string(),
        // A date this cannot parse is returned untouched rather than turned into the epoch — a
        // silently-1970 obligation would sort to the front of every calendar.
        None => iso.to_string(),
    }
}

/// Step by CALENDAR months, keeping the day of the month and clamping where it does not exist.
///
/// `2026-01-31` plus one month is `2026-02-28`, not `2026-03-03`. Plus TWO months is `2026-03-31`,
/// not `2026-03-28` — the anchor is the ORIGINAL date, so a bill on the 31st does not walk backwards
/// through the year every time it passes a short month.
pub fn add_calendar_months(iso: &str, n: i64) -> String {
    let (y, m, d) = match (iso.get(0..4).and_then(|s| s.parse::<i64>().ok()), iso.get(5..7).and_then(|s| s.parse::<i64>().ok()), iso.get(8..10).and_then(|s| s.parse::<i64>().ok())) {
        (Some(y), Some(m), Some(d)) => (y, m, d),
        _ => return iso.to_string(),
    };
    let total = y * 12 + (m - 1) + n;
    let mm = total.rem_euclid(12);
    let yy = (total - mm) / 12;
    format!("{yy:04}-{:02}-{:02}", mm + 1, d.min(days_in_month(yy, mm + 1)))
}

/// The nth occurrence after an anchor, by the cadence's own unit.
fn step(anchor: &str, cadence: Cadence, n: i64) -> Option<String> {
    match cadence {
        Cadence::Weekly => Some(add_days(anchor, 7 * n)),
        Cadence::Biweekly => Some(add_days(anchor, 14 * n)),
        Cadence::Monthly => Some(add_calendar_months(anchor, n)),
        Cadence::Quarterly => Some(add_calendar_months(anchor, 3 * n)),
        Cadence::Annual => Some(add_calendar_months(anchor, 12 * n)),
        // An irregular charge has no next date to predict. Inventing one would put a number on the
        // calendar that nothing observed, which is worse than the charge being absent from it.
        Cadence::Irregular => None,
    }
}

/// A hard cap, so a bad cadence can never spin. 5 years of weekly is comfortably inside it.
const MAX_OCCURRENCES: i64 = 400;

fn occurrences(r: &Recurring, from: &str, to: &str) -> Vec<String> {
    let mut out = Vec::new();
    for n in 1..=MAX_OCCURRENCES {
        let Some(at) = step(&r.last_seen, r.cadence, n) else { break };
        if at.as_str() > to {
            break;
        }
        if at.as_str() >= from {
            out.push(at);
        }
    }
    out
}

pub fn build_calendar(recurring: &[Recurring], position: Option<&Position>, opts: &CalendarOptions) -> ObligationCalendar {
    let mut notes: Vec<String> = Vec::new();
    let mut obligations: Vec<Obligation> = Vec::new();

    let lapsed: Vec<&Recurring> = recurring.iter().filter(|r| r.lapsed).collect();
    if !lapsed.is_empty() && !opts.include_lapsed {
        let names: Vec<&str> = lapsed.iter().map(|r| r.label.as_str()).collect();
        notes.push(format!(
            "{} charge(s) look cancelled and are NOT on the calendar — {}. If one of them renews, the months below are light by that much.",
            lapsed.len(),
            names.join(", ")
        ));
    }
    let irregular = recurring.iter().filter(|r| r.cadence == Cadence::Irregular).count();
    if irregular > 0 {
        notes.push(format!("{irregular} charge(s) recur on no predictable schedule and have no date here — they will still cost money."));
    }

    for r in recurring {
        if r.lapsed && !opts.include_lapsed {
            continue;
        }
        for date in occurrences(r, opts.from, opts.to) {
            obligations.push(Obligation {
                date,
                label: r.label.clone(),
                account: r.account.clone(),
                amount: r.typical,
                kind: ObligationKind::Recurring,
                // The DATE is observed — it came from a real rhythm. Whether the AMOUNT repeats is
                // what `regularity` and the charge's own amount stability are for.
                confidence: if r.regularity >= 0.8 { Confidence::Observed } else { Confidence::Assumed },
                regularity: Some(r.regularity),
            });
        }
    }

    for a in position.map(|p| p.accounts.as_slice()).unwrap_or(&[]) {
        let (Some(minimum), Some(_owed)) = (a.minimum_payment, a.owed) else { continue };
        if minimum.minor == 0 {
            continue;
        }
        let day = opts.minimum_due_day.iter().find(|(id, _)| *id == a.account).map(|(_, d)| *d as i64);
        if day.is_none() {
            notes.push(format!(
                "the due day for {}'s minimum is unknown — it is placed on the 1st, the earliest it could plausibly fall, so this calendar cannot be optimistic about it",
                a.institution
            ));
        }
        for month in months_between(opts.from, opts.to) {
            let (Some(y), Some(m)) = (month.get(0..4).and_then(|s| s.parse::<i64>().ok()), month.get(5..7).and_then(|s| s.parse::<i64>().ok())) else { continue };
            let at = format!("{month}-{:02}", day.unwrap_or(1).min(days_in_month(y, m)));
            if at.as_str() < opts.from || at.as_str() > opts.to {
                continue;
            }
            obligations.push(Obligation {
                date: at,
                label: format!("{} minimum", a.institution),
                account: a.account.clone(),
                amount: minimum,
                kind: ObligationKind::Minimum,
                confidence: if day.is_none() { Confidence::Assumed } else { Confidence::Observed },
                regularity: None,
            });
        }
    }

    obligations.sort_by(|x, y| x.date.cmp(&y.date).then(x.label.cmp(&y.label)));

    let currency = obligations.first().map(|o| o.amount.currency).or_else(|| position.map(|p| p.currency)).unwrap_or(Currency::USD);
    let mut buckets: Vec<(String, Vec<&Obligation>)> = Vec::new();
    for o in &obligations {
        let key = o.date[..7.min(o.date.len())].to_string();
        match buckets.iter_mut().find(|(k, _)| *k == key) {
            Some((_, b)) => b.push(o),
            None => buckets.push((key, vec![o])),
        }
    }
    buckets.sort_by(|a, b| a.0.cmp(&b.0));
    let by_month: Vec<MonthTotal> = buckets
        .iter()
        .filter_map(|(month, os)| {
            let amounts: Vec<Money> = os.iter().map(|o| o.amount).collect();
            sum(&amounts, currency).ok().map(|total| MonthTotal { month: month.clone(), total, count: os.len() })
        })
        .collect();

    // The FIRST heaviest month on a tie, because the calendar reads forward and the earlier one is
    // the one arriving first — `max_by_key` would hand back the last.
    let heaviest = by_month.iter().fold(None::<&MonthTotal>, |best, m| match best {
        Some(b) if b.total.minor >= m.total.minor => Some(b),
        _ => Some(m),
    });

    ObligationCalendar {
        from: opts.from.to_string(),
        to: opts.to.to_string(),
        heaviest: heaviest.cloned(),
        by_month,
        obligations,
        notes,
    }
}

/// Every `YYYY-MM` touched by the window, inclusive at both ends.
pub fn months_between(from: &str, to: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = from[..7.min(from.len())].to_string();
    let last = to[..7.min(to.len())].to_string();
    while cur <= last && out.len() < 600 {
        out.push(cur.clone());
        cur = add_calendar_months(&format!("{cur}-01"), 1)[..7].to_string();
    }
    out
}

/// What is due inside a window — the "can I get to Friday?" question.
pub fn due_between<'a>(c: &'a ObligationCalendar, from: &str, to: &str) -> Vec<&'a Obligation> {
    c.obligations.iter().filter(|o| o.date.as_str() >= from && o.date.as_str() <= to).collect()
}

/// The total for one month, ZERO if nothing is due — a month with no obligations is a real answer,
/// unlike a projection's absent total, which means "this does not know".
pub fn month_total(c: &ObligationCalendar, month: &str, currency: Currency) -> Money {
    c.by_month.iter().find(|m| m.month == month).map(|m| m.total).unwrap_or_else(|| money(0, currency))
}

#[derive(Debug, Clone, PartialEq)]
pub struct Window {
    pub from: String,
    pub to: String,
    pub total: Money,
}

/// The heaviest run of `days` consecutive days in the window — where a month-level view goes blind.
///
/// Every window STARTS on a real obligation, because a heavy run always begins at one; sliding day by
/// day over an empty calendar would cost far more and find the same answer.
pub fn heaviest_window(c: &ObligationCalendar, days: i64) -> Option<Window> {
    let first = c.obligations.first()?;
    let currency = first.amount.currency;
    let mut best: Option<Window> = None;
    for o in &c.obligations {
        let end = add_days(&o.date, days - 1);
        let amounts: Vec<Money> = due_between(c, &o.date, &end).iter().map(|x| x.amount).collect();
        let Ok(total) = sum(&amounts, currency) else { continue };
        if best.as_ref().is_none_or(|b| total.minor > b.total.minor) {
            best = Some(Window { from: o.date.clone(), to: end, total });
        }
    }
    best
}

/// Debts whose minimum is on the calendar — what keeps every account current.
pub fn minimums_on(c: &ObligationCalendar) -> Vec<&Obligation> {
    c.obligations.iter().filter(|o| o.kind == ObligationKind::Minimum).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::account::Kind;
    use crate::money::usd;
    use crate::position::{AccountPosition, Position};

    // SYNTHETIC FIXTURES ONLY.
    fn rec(label: &str, cadence: Cadence, minor: i64, last_seen: &str, regularity: f64, lapsed: bool) -> Recurring {
        Recurring {
            key: label.to_lowercase(),
            label: label.to_string(),
            account: "chk".to_string(),
            cadence,
            typical: usd(minor),
            annualised: usd(0),
            occurrences: 3,
            first_seen: "2026-01-01".to_string(),
            last_seen: last_seen.to_string(),
            regularity,
            amount_stability: 1.0,
            lapsed,
        }
    }

    fn card_position() -> Position {
        Position {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            accounts: vec![AccountPosition {
                account: "visa".to_string(),
                institution: "chase".to_string(),
                kind: Kind::Credit,
                balance: usd(-200_000),
                as_of: "2026-06-30".to_string(),
                rolled_forward: 0,
                is_debt: true,
                owed: Some(usd(200_000)),
                credit_limit: None,
                available: None,
                utilisation: None,
                apr: None,
                daily_interest: None,
                minimum_payment: Some(usd(5_000)),
            }],
            net_worth: usd(0),
            liquid: usd(0),
            total_debt: usd(200_000),
            daily_interest: usd(0),
            minimums_due: usd(5_000),
            weighted_apr: None,
            complete: true,
            provenance: String::new(),
            problems: Vec::new(),
        }
    }

    #[test]
    fn a_bill_on_the_thirty_first_clamps_into_february_and_then_comes_back() {
        // THE ANCHOR NEVER MOVES. Measured against the TypeScript, a full year from 2026-01-31.
        let walk: Vec<String> = (0..13).map(|i| add_calendar_months("2026-01-31", i)).collect();
        assert_eq!(
            walk,
            vec![
                "2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-31", "2026-06-30",
                "2026-07-31", "2026-08-31", "2026-09-30", "2026-10-31", "2026-11-30", "2026-12-31", "2027-01-31"
            ]
        );
        // The failure this prevents: stepping the CLAMPED date would give 2026-03-28, and the bill
        // would walk backwards three days a year. Repeatedly re-anchoring is the whole design.
        assert_eq!(add_calendar_months("2026-01-31", 2), "2026-03-31");
        assert_ne!(add_calendar_months("2026-01-31", 2), "2026-03-28");
    }

    #[test]
    fn february_is_correct_in_a_leap_year_and_the_century_rule_holds() {
        assert_eq!(add_calendar_months("2024-01-31", 1), "2024-02-29");
        assert_eq!(add_calendar_months("2023-01-31", 1), "2023-02-28");
        assert_eq!(add_calendar_months("2026-01-29", 1), "2026-02-28");
        // 2100 is divisible by 4 and is NOT a leap year. The every-four-years approximation would
        // put a bill on 29 February 2100.
        assert_eq!(days_in_month(2100, 2), 28);
        assert_eq!(days_in_month(2000, 2), 29);
        assert_eq!(days_in_month(2024, 2), 29);
    }

    #[test]
    fn stepping_backwards_crosses_the_year_boundary() {
        assert_eq!(add_calendar_months("2026-03-31", -1), "2026-02-28");
        assert_eq!(add_calendar_months("2026-01-15", -1), "2025-12-15");
        assert_eq!(add_calendar_months("2026-01-31", -13), "2024-12-31");
    }

    #[test]
    fn day_arithmetic_crosses_months_and_years() {
        assert_eq!(add_days("2026-02-27", 2), "2026-03-01");
        assert_eq!(add_days("2026-12-31", 1), "2027-01-01");
        assert_eq!(add_days("2026-03-01", -1), "2026-02-28");
        // An unparseable date comes back untouched. Returning the epoch would sort it to the front
        // of every calendar as a phantom obligation in 1970.
        assert_eq!(add_days("not-a-date", 5), "not-a-date");
    }

    #[test]
    fn months_between_is_inclusive_at_both_ends() {
        assert_eq!(months_between("2026-01-15", "2026-04-02"), vec!["2026-01", "2026-02", "2026-03", "2026-04"]);
        assert_eq!(months_between("2026-01-15", "2026-01-20"), vec!["2026-01"]);
    }

    #[test]
    fn the_calendar_places_every_charge_on_its_own_day() {
        let c = build_calendar(
            &[rec("RENT", Cadence::Monthly, 120_000, "2026-06-05", 1.0, false), rec("NETFLIX", Cadence::Monthly, 1_599, "2026-06-12", 0.7, false), rec("BUS", Cadence::Weekly, 250, "2026-06-25", 1.0, false)],
            Some(&card_position()),
            &CalendarOptions::new("2026-07-01", "2026-08-31"),
        );
        let got: Vec<(&str, &str, i64, &str)> = c.obligations.iter().map(|o| (o.date.as_str(), o.label.as_str(), o.amount.minor, o.confidence.label())).collect();
        assert_eq!(
            got,
            vec![
                ("2026-07-01", "chase minimum", 5_000, "assumed"),
                ("2026-07-02", "BUS", 250, "observed"),
                ("2026-07-05", "RENT", 120_000, "observed"),
                ("2026-07-09", "BUS", 250, "observed"),
                // Regularity 0.7 is below the 0.8 bar, so the DATE is assumed rather than observed.
                ("2026-07-12", "NETFLIX", 1_599, "assumed"),
                ("2026-07-16", "BUS", 250, "observed"),
                ("2026-07-23", "BUS", 250, "observed"),
                ("2026-07-30", "BUS", 250, "observed"),
                ("2026-08-01", "chase minimum", 5_000, "assumed"),
                ("2026-08-05", "RENT", 120_000, "observed"),
                ("2026-08-06", "BUS", 250, "observed"),
                ("2026-08-12", "NETFLIX", 1_599, "assumed"),
                ("2026-08-13", "BUS", 250, "observed"),
                ("2026-08-20", "BUS", 250, "observed"),
                ("2026-08-27", "BUS", 250, "observed"),
            ]
        );
        let months: Vec<(&str, i64, usize)> = c.by_month.iter().map(|m| (m.month.as_str(), m.total.minor, m.count)).collect();
        assert_eq!(months, vec![("2026-07", 127_849, 8), ("2026-08", 127_599, 7)]);
        assert_eq!(c.heaviest.as_ref().unwrap().month, "2026-07");
        assert_eq!(minimums_on(&c).len(), 2);
        assert_eq!(due_between(&c, "2026-07-01", "2026-07-06").len(), 3);
        // A month with nothing due is ZERO, which is a real answer — unlike a projection's absent
        // total, which means the projection does not know.
        assert_eq!(month_total(&c, "2026-09", Currency::USD).minor, 0);
    }

    #[test]
    fn the_heaviest_seven_days_is_what_a_monthly_view_cannot_see() {
        let c = build_calendar(
            &[rec("RENT", Cadence::Monthly, 120_000, "2026-06-05", 1.0, false), rec("NETFLIX", Cadence::Monthly, 1_599, "2026-06-12", 0.7, false), rec("BUS", Cadence::Weekly, 250, "2026-06-25", 1.0, false)],
            Some(&card_position()),
            &CalendarOptions::new("2026-07-01", "2026-08-31"),
        );
        let w = heaviest_window(&c, 7).expect("there are obligations");
        assert_eq!((w.from.as_str(), w.to.as_str(), w.total.minor), ("2026-07-01", "2026-07-07", 125_250));
        // July totals 127849 across the month, and all but 2599 of it lands in ONE WEEK. A
        // month-level view sees an affordable month; this sees the week that breaks it.
        assert_eq!(month_total(&c, "2026-07", Currency::USD).minor - w.total.minor, 2_599);
    }

    #[test]
    fn a_cancelled_charge_is_off_the_calendar_and_the_omission_is_stated() {
        let c = build_calendar(
            &[rec("OLDGYM", Cadence::Monthly, 5_000, "2026-03-01", 1.0, true), rec("ODD", Cadence::Irregular, 900, "2026-06-01", 1.0, false)],
            None,
            &CalendarOptions::new("2026-07-01", "2026-07-31"),
        );
        assert!(c.obligations.is_empty());
        assert!(c.heaviest.is_none(), "no obligations is ABSENT, not a zero month");
        assert_eq!(c.notes.len(), 2);
        assert!(c.notes[0].contains("look cancelled") && c.notes[0].contains("OLDGYM"));
        // The irregular one has no date, and the note says it will still cost money — silence would
        // read as "nothing else is coming".
        assert!(c.notes[1].contains("no predictable schedule"));
    }

    #[test]
    fn including_the_lapsed_ones_puts_them_back_and_drops_the_note() {
        let opts = CalendarOptions { include_lapsed: true, ..CalendarOptions::new("2026-07-01", "2026-07-31") };
        let c = build_calendar(&[rec("OLDGYM", Cadence::Monthly, 5_000, "2026-03-01", 1.0, true)], None, &opts);
        assert_eq!(c.obligations.len(), 1);
        assert_eq!(c.obligations[0].date, "2026-07-01");
        assert!(c.notes.is_empty(), "nothing was omitted, so there is nothing to warn about");
    }

    #[test]
    fn an_unknown_due_day_goes_on_the_first_because_a_calendar_must_not_be_optimistic() {
        let c = build_calendar(&[], Some(&card_position()), &CalendarOptions::new("2026-07-01", "2026-07-31"));
        assert_eq!(c.obligations.len(), 1);
        assert_eq!(c.obligations[0].date, "2026-07-01");
        assert_eq!(c.obligations[0].confidence, Confidence::Assumed);
        assert!(c.notes[0].contains("earliest it could plausibly fall"));

        // Told the real day, it is placed there and the guess disappears.
        let known = [("visa".to_string(), 17u32)];
        let c2 = build_calendar(&[], Some(&card_position()), &CalendarOptions { minimum_due_day: &known, ..CalendarOptions::new("2026-07-01", "2026-07-31") });
        assert_eq!(c2.obligations[0].date, "2026-07-17");
        assert_eq!(c2.obligations[0].confidence, Confidence::Observed);
        assert!(c2.notes.is_empty());
    }

    #[test]
    fn a_due_day_past_the_end_of_a_short_month_clamps_rather_than_spilling_over() {
        let known = [("visa".to_string(), 31u32)];
        let c = build_calendar(&[], Some(&card_position()), &CalendarOptions { minimum_due_day: &known, ..CalendarOptions::new("2026-02-01", "2026-02-28") });
        assert_eq!(c.obligations[0].date, "2026-02-28", "the 31st of February is the 28th, not 3 March");
    }
}

//! Runway — how long the money lasts, and it is reported on the LOW band.
//!
//! This is the number people act on, so it is the one most worth getting pessimistic. A runway
//! computed on expected income says "eleven months" and is right on average and useless in the case
//! that matters: the case where income comes in low is exactly the case where you needed to know.
//! All three scenarios are computed; [`Runway::headline`] is `low`, and that choice is the module's
//! position rather than a default somebody can drift away from.
//!
//! # Two things that are unknown, not zero — and both would silently lengthen the runway
//!
//! 1. **Discretionary spending.** The obligation calendar knows rent and subscriptions. It does not
//!    know groceries, fuel, or a haircut. A runway from obligations alone is not conservative — it is
//!    wrong in the flattering direction. So `discretionary` is a REQUIRED argument: passing zero is
//!    allowed and is a decision that gets said out loud in the problems list.
//! 2. **Months past the calendar.** Beyond the calendar's window there are no known obligations, so
//!    costs would read as zero and the runway would extend forever on nothing. The horizon is
//!    TRUNCATED to what the calendar actually covers, and truncating is stated.
use crate::money::{money, scale, Currency, Money, Rounding};
use crate::obligations::{month_total, months_between, ObligationCalendar};
use crate::position::Position;
use crate::projection::{IncomeProjection, MonthBand};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Scenario {
    Low,
    Expected,
    High,
}

impl Scenario {
    pub fn label(self) -> &'static str {
        match self {
            Scenario::Low => "low",
            Scenario::Expected => "expected",
            Scenario::High => "high",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct RunwayMonth {
    pub month: String,
    /// Liquid at the start of the month.
    pub opening: Money,
    pub income: Money,
    pub obligations: Money,
    pub discretionary: Money,
    /// income − obligations − discretionary.
    pub net: Money,
    pub closing: Money,
    /// POSITIVE amount the month ends short by, when it ends short.
    pub shortfall: Option<Money>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct RunwayResult {
    pub scenario: Scenario,
    pub months: Vec<RunwayMonth>,
    /// The FIRST month that ends below zero. Not the worst one — the first.
    pub exhausts_in: Option<String>,
    /// WHOLE months survived before that. None when the horizon is survived outright.
    pub months_of_cover: Option<usize>,
    /// The lowest closing balance anywhere in the horizon, which can be LATER than exhaustion.
    pub tightest: Option<RunwayMonth>,
    /// The smallest constant monthly amount that would keep every month above zero.
    pub monthly_gap: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Runway {
    pub as_of: String,
    pub currency: Currency,
    /// LIQUID only. An investment is not runway, and net worth is not money you can spend.
    pub starting_liquid: Money,
    pub low: RunwayResult,
    pub expected: RunwayResult,
    pub high: RunwayResult,
    /// The one to plan on. It is `low`, deliberately.
    pub headline: RunwayResult,
    /// How far the horizon actually reaches, after truncation.
    pub through: Option<String>,
    pub problems: Vec<String>,
    pub provenance: String,
}

pub struct RunwayOptions {
    /// Everything the calendar cannot see: groceries, fuel, transport, the ordinary week. REQUIRED,
    /// so it cannot be forgotten — a runway that quietly assumes zero is the flattering kind of wrong.
    pub discretionary: Money,
}

fn band_value(b: &MonthBand, s: Scenario) -> Money {
    match s {
        Scenario::Low => b.low,
        Scenario::High => b.high,
        Scenario::Expected => b.expected,
    }
}

fn walk(months: &[&MonthBand], calendar: &ObligationCalendar, start: Money, discretionary: Money, scenario: Scenario, currency: Currency) -> RunwayResult {
    let mut out: Vec<RunwayMonth> = Vec::new();
    let mut balance = start;
    for band in months {
        let income = band_value(band, scenario);
        let obligations = month_total(calendar, &band.month, currency);
        // Every figure reaching here is already this position's currency — the caller refuses a
        // mismatched discretionary before walking, and the projection is built from one analysis.
        let net = money(income.minor - obligations.minor - discretionary.minor, currency);
        let opening = balance;
        let closing = money(opening.minor + net.minor, currency);
        balance = closing;
        out.push(RunwayMonth {
            month: band.month.clone(),
            opening,
            income,
            obligations,
            discretionary,
            net,
            closing,
            shortfall: if closing.minor < 0 { Some(money(-closing.minor, currency)) } else { None },
        });
    }

    // THE FIRST month that ends short, not the worst one. Income can be lumpy enough that a later
    // month is deeper underwater, but the month you run out of money is the month you run out.
    let first_short = out.iter().position(|m| m.closing.minor < 0);
    let tightest = out.iter().fold(None::<&RunwayMonth>, |worst, m| match worst {
        Some(w) if w.closing.minor <= m.closing.minor => Some(w),
        _ => Some(m),
    });

    // Adding x per month raises month i's closing by x·(i+1), so the smallest x that clears every
    // month is the largest per-month share of any deficit. EXACT, not searched for.
    let need = out.iter().enumerate().fold(0.0_f64, |mx: f64, (i, m)| {
        let want = if m.closing.minor < 0 { -m.closing.minor as f64 / (i + 1) as f64 } else { 0.0 };
        mx.max(want)
    });

    RunwayResult {
        scenario,
        exhausts_in: first_short.map(|i| out[i].month.clone()),
        months_of_cover: first_short,
        tightest: tightest.cloned(),
        // CEIL, because a gap rounded down does not close it.
        monthly_gap: money(need.ceil() as i64, currency),
        months: out,
    }
}

pub fn runway(position: &Position, projection: &IncomeProjection, calendar: &ObligationCalendar, opts: &RunwayOptions) -> Runway {
    let discretionary = opts.discretionary;
    let currency = position.currency;
    let mut problems: Vec<String> = position.problems.clone();

    let empty = |scenario: Scenario| RunwayResult {
        scenario,
        months: Vec::new(),
        exhausts_in: None,
        months_of_cover: None,
        tightest: None,
        monthly_gap: money(0, currency),
    };
    let refuse = |reason: String, mut problems: Vec<String>| {
        problems.push(reason);
        Runway {
            as_of: position.as_of.clone(),
            currency,
            starting_liquid: position.liquid,
            low: empty(Scenario::Low),
            expected: empty(Scenario::Expected),
            high: empty(Scenario::High),
            headline: empty(Scenario::Low),
            through: None,
            problems,
            provenance: position.provenance.clone(),
        }
    };

    if !projection.projectable {
        let r = format!("no runway without an income projection: {}", projection.reason.clone().unwrap_or_default());
        return refuse(r, problems);
    }
    if discretionary.currency != currency {
        let r = format!("discretionary spending is in {} but the position is in {}", discretionary.currency.as_str(), currency.as_str());
        return refuse(r, problems);
    }

    // TRUNCATE to what the calendar covers. Past its window there are no known obligations, so every
    // month beyond would read as costing nothing and the runway would extend on the strength of a
    // GAP IN THE DATA rather than on money.
    let covered = months_between(&calendar.from, &calendar.to);
    let months: Vec<&MonthBand> = projection.months.iter().filter(|b| covered.contains(&b.month)).collect();
    if months.len() < projection.months.len() {
        problems.push(format!(
            "the obligation calendar stops at {}, so the runway is cut to {} of {} projected month(s) — beyond it nothing is known to be due, which is not the same as nothing being due",
            calendar.to,
            months.len(),
            projection.months.len()
        ));
    }
    if months.is_empty() {
        let r = format!("the obligation calendar ({}..{}) covers none of the projected months", calendar.from, calendar.to);
        return refuse(r, problems);
    }
    if discretionary.minor == 0 {
        problems.push(
            "discretionary spending was given as zero — this runway assumes groceries, fuel and everything else outside the standing obligations cost nothing, which nobody's does".to_string(),
        );
    }
    if !position.complete {
        problems.push("the position under this runway is incomplete, so every figure here inherits whatever it could not account for".to_string());
    }

    let low = walk(&months, calendar, position.liquid, discretionary, Scenario::Low, currency);

    Runway {
        as_of: position.as_of.clone(),
        currency,
        starting_liquid: position.liquid,
        expected: walk(&months, calendar, position.liquid, discretionary, Scenario::Expected, currency),
        high: walk(&months, calendar, position.liquid, discretionary, Scenario::High, currency),
        // THE HEADLINE IS THE LOW BAND. A runway on expected income is right on average and useless
        // in the case that matters, because the case where income comes in low is the case you
        // needed it for.
        headline: low.clone(),
        low,
        through: months.last().map(|b| b.month.clone()),
        problems,
        provenance: position.provenance.clone(),
    }
}

/// Whether the horizon is survived outright under a scenario.
pub fn survives_horizon(r: &RunwayResult) -> bool {
    r.exhausts_in.is_none() && !r.months.is_empty()
}

/// What a year of the headline gap costs to close. Often the more legible framing of `monthly_gap`.
pub fn annual_gap(r: &Runway) -> Money {
    scale(r.headline.monthly_gap, 12.0, Rounding::HalfUp)
}

/// One sentence a person can act on, in the terms they asked the question in.
pub fn summarise(r: &Runway) -> String {
    let h = &r.headline;
    if h.months.is_empty() {
        let why = r.problems.last().cloned().unwrap_or_else(|| "not enough is known".to_string());
        return format!("no runway could be computed — {why}");
    }
    if survives_horizon(h) {
        let t = h.tightest.as_ref().expect("a non-empty walk always has a tightest month");
        return format!(
            "on the LOW income band the money holds through {}, tightest at {} with {} minor units left",
            r.through.clone().unwrap_or_default(),
            t.month,
            t.closing.minor
        );
    }
    format!(
        "on the LOW income band the money runs out in {} — {} whole month(s) of cover; {} minor units more per month would close it",
        h.exhausts_in.clone().unwrap_or_default(),
        h.months_of_cover.unwrap_or(0),
        h.monthly_gap.minor
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::obligations::MonthTotal;
    use crate::projection::ProjectionTotal;

    // SYNTHETIC FIXTURES ONLY.
    fn band(month: &str, low: i64, expected: i64, high: i64) -> MonthBand {
        MonthBand { month: month.to_string(), low: usd(low), expected: usd(expected), high: usd(high) }
    }

    fn projection() -> IncomeProjection {
        IncomeProjection {
            projectable: true,
            reason: None,
            months: vec![band("2026-07", 300_000, 400_000, 500_000), band("2026-08", 280_000, 400_000, 520_000), band("2026-09", 260_000, 400_000, 540_000), band("2026-10", 240_000, 400_000, 560_000)],
            total: Some(ProjectionTotal { low: usd(0), expected: usd(0), high: usd(0) }),
            assumptions: Vec::new(),
            excluded: Vec::new(),
            sources_used: 1,
        }
    }

    fn calendar(to: &str, per: i64) -> ObligationCalendar {
        let by_month: Vec<MonthTotal> = ["2026-07", "2026-08", "2026-09", "2026-10"]
            .iter()
            .filter(|m| **m <= &to[..7])
            .map(|m| MonthTotal { month: m.to_string(), total: usd(per), count: 1 })
            .collect();
        ObligationCalendar { from: "2026-07-01".to_string(), to: to.to_string(), obligations: Vec::new(), by_month, heaviest: None, notes: Vec::new() }
    }

    fn position(liquid: i64, complete: bool, problems: Vec<String>) -> Position {
        Position {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            accounts: Vec::new(),
            net_worth: usd(liquid),
            liquid: usd(liquid),
            total_debt: usd(0),
            daily_interest: usd(0),
            minimums_due: usd(0),
            weighted_apr: None,
            complete,
            provenance: "reconciled".to_string(),
            problems,
        }
    }

    fn opts(d: i64) -> RunwayOptions {
        RunwayOptions { discretionary: usd(d) }
    }

    #[test]
    fn a_surviving_horizon_reports_the_tightest_month_rather_than_a_date_it_runs_out() {
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(0));
        let got: Vec<(&str, i64, i64, i64, i64)> = r.low.months.iter().map(|m| (m.month.as_str(), m.opening.minor, m.income.minor, m.net.minor, m.closing.minor)).collect();
        assert_eq!(
            got,
            vec![
                ("2026-07", 500_000, 300_000, -50_000, 450_000),
                ("2026-08", 450_000, 280_000, -70_000, 380_000),
                ("2026-09", 380_000, 260_000, -90_000, 290_000),
                ("2026-10", 290_000, 240_000, -110_000, 180_000)
            ]
        );
        assert!(survives_horizon(&r.low));
        assert_eq!(r.low.exhausts_in, None);
        assert_eq!(r.low.monthly_gap.minor, 0);
        assert_eq!(r.through.as_deref(), Some("2026-10"));
        // ZERO discretionary is allowed and is SAID OUT LOUD, because a runway that quietly assumes
        // groceries are free is the flattering kind of wrong.
        assert_eq!(r.problems.len(), 1);
        assert!(r.problems[0].contains("groceries"));
        assert!(summarise(&r).starts_with("on the LOW income band the money holds through 2026-10, tightest at 2026-10 with 180000"));
    }

    #[test]
    fn the_headline_is_the_low_band_and_that_is_the_modules_position() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        // The same data on EXPECTED income needs 5000 a month; on LOW it needs 135000. A headline on
        // expected would be right on average and useless in the case that matters.
        assert_eq!(r.low.monthly_gap.minor, 135_000);
        assert_eq!(r.expected.monthly_gap.minor, 5_000);
        assert_eq!(r.headline.monthly_gap.minor, r.low.monthly_gap.minor);
        assert_eq!(r.headline.scenario, Scenario::Low);
        assert!(r.high.monthly_gap.minor < r.low.monthly_gap.minor);
    }

    #[test]
    fn the_monthly_gap_is_solved_exactly_rather_than_searched_for() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        let closings: Vec<i64> = r.low.months.iter().map(|m| m.closing.minor).collect();
        assert_eq!(closings, vec![-30_000, -180_000, -350_000, -540_000]);
        // Adding x per month raises month i by x*(i+1), so the binding constraint is the LARGEST
        // per-month share: max(30000/1, 180000/2, 350000/3, 540000/4) = 135000, from the LAST month
        // rather than the deepest ratio.
        assert_eq!(r.low.monthly_gap.minor, 135_000);
        // And it holds: 135000 a month clears every month.
        for (i, c) in closings.iter().enumerate() {
            assert!(c + 135_000 * (i as i64 + 1) >= 0, "month {i} still short");
        }
        assert_eq!(annual_gap(&r).minor, 1_620_000);
    }

    #[test]
    fn the_first_short_month_is_the_answer_not_the_worst_one() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        assert_eq!(r.low.exhausts_in.as_deref(), Some("2026-07"), "the FIRST month that ends short");
        assert_eq!(r.low.months_of_cover, Some(0));
        // The TIGHTEST month is later and deeper. Both are reported because they answer different
        // questions: when do I run out, and how bad does it get.
        assert_eq!(r.low.tightest.as_ref().unwrap().month, "2026-10");
        assert_eq!(r.low.months[0].shortfall.unwrap().minor, 30_000, "the shortfall is POSITIVE");
        assert!(!survives_horizon(&r.low));
    }

    #[test]
    fn the_horizon_is_cut_to_the_calendar_and_the_cut_is_stated() {
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-08-31", 350_000), &opts(50_000));
        assert_eq!(r.low.months.len(), 2, "four months projected, two covered");
        assert_eq!(r.through.as_deref(), Some("2026-08"));
        // Without truncation the last two months would cost NOTHING and the runway would extend on
        // a gap in the data rather than on money.
        assert!(r.problems.iter().any(|p| p.contains("not the same as nothing being due")));
    }

    #[test]
    fn no_projection_is_a_refusal_that_carries_the_projections_own_reason() {
        let bad = IncomeProjection {
            projectable: false,
            reason: Some("2 whole month(s) of history; 3 are needed".to_string()),
            months: Vec::new(),
            total: None,
            assumptions: Vec::new(),
            excluded: Vec::new(),
            sources_used: 0,
        };
        let r = runway(&position(500_000, true, vec![]), &bad, &calendar("2026-10-31", 350_000), &opts(50_000));
        assert!(r.low.months.is_empty());
        assert!(!survives_horizon(&r.low), "an empty walk has not survived anything");
        assert_eq!(r.through, None);
        assert!(r.problems.last().unwrap().contains("2 whole month(s) of history"));
        assert_eq!(summarise(&r), "no runway could be computed — no runway without an income projection: 2 whole month(s) of history; 3 are needed");
    }

    #[test]
    fn a_calendar_that_does_not_overlap_the_projection_refuses_rather_than_assuming_free_months() {
        let far = ObligationCalendar { from: "2027-01-01".to_string(), to: "2027-03-31".to_string(), obligations: Vec::new(), by_month: Vec::new(), heaviest: None, notes: Vec::new() };
        let r = runway(&position(500_000, true, vec![]), &projection(), &far, &opts(50_000));
        assert!(r.low.months.is_empty());
        assert_eq!(r.problems.len(), 2, "the truncation AND the refusal are both stated");
        assert!(r.problems[1].contains("covers none of the projected months"));
    }

    #[test]
    fn an_incomplete_position_is_inherited_along_with_its_own_problems() {
        let r = runway(&position(500_000, false, vec!["a balance is stale".to_string()]), &projection(), &calendar("2026-10-31", 350_000), &opts(50_000));
        // The position's own problems come FIRST and are not replaced — a runway cannot be sounder
        // than the position under it.
        assert_eq!(r.problems[0], "a balance is stale");
        assert!(r.problems[1].contains("incomplete"));
        assert_eq!(r.low.exhausts_in.as_deref(), Some("2026-10"));
        assert_eq!(r.low.months_of_cover, Some(3));
        assert_eq!(r.low.monthly_gap.minor, 5_000);
        assert_eq!(r.provenance, "reconciled", "the provenance travels with the figure");
    }

    #[test]
    fn a_mismatched_discretionary_currency_refuses_rather_than_subtracting_it_anyway() {
        let eur = Currency::new("EUR").expect("a three-letter code");
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &RunwayOptions { discretionary: money(50_000, eur) });
        assert!(r.low.months.is_empty());
        assert!(r.problems.last().unwrap().contains("EUR"));
    }
}

//! Debt payoff — which debt to attack first, and what the choice actually costs.
//!
//! Two orderings are in common use and they optimise different things:
//!
//! - **Avalanche** — highest interest RATE first. Mathematically optimal: it always pays the least
//!   total interest and is never slower.
//! - **Snowball** — smallest BALANCE first. Pays more, sometimes much more — but clears whole
//!   accounts sooner, and finishing one is what makes people keep going.
//!
//! This module does not pick for you. It runs both and reports the difference in money and months, so
//! the trade is a NUMBER rather than a slogan. That is the honest framing: snowball's cost is real
//! and so is its benefit, and only the person paying can weigh them.
//!
//! Everything is integer MINOR UNITS. A payoff schedule is exactly where float drift shows up as a
//! final instalment that is a cent off and a total that will not reconcile.
use crate::money::{money, sum, Money, Rounding};

/// One debt, as the payer knows it.
#[derive(Debug, Clone, PartialEq)]
pub struct Debt {
    /// How the payer refers to it — shown back in the schedule.
    pub name: String,
    /// What is owed now.
    pub balance: Money,
    /// NOMINAL annual rate as a fraction: 0.2299 for 22.99% APR.
    pub apr: f64,
    /// The contractual minimum for a period. Paying less is default, so it is never skipped.
    pub minimum: Money,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Strategy {
    Avalanche,
    Snowball,
}

impl Strategy {
    pub fn label(self) -> &'static str {
        match self {
            Strategy::Avalanche => "avalanche",
            Strategy::Snowball => "snowball",
        }
    }
}

/// What happened to one debt in one period.
#[derive(Debug, Clone, PartialEq)]
pub struct Payment {
    pub name: String,
    pub interest: Money,
    pub principal: Money,
    pub balance: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Period {
    /// 1-based; period 1 is the first payment made.
    pub period: usize,
    pub payments: Vec<Payment>,
    /// Debts that reached zero in THIS period — the moment a snowball payer is waiting for.
    pub cleared_this_period: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Plan {
    pub strategy: Strategy,
    pub periods: Vec<Period>,
    /// How many periods until every balance is zero.
    pub months: usize,
    pub total_interest: Money,
    pub total_paid: Money,
    /// Payoff order, in the order each debt actually cleared.
    pub order: Vec<String>,
}

/// Why no schedule exists. A REFUSAL, never a truncated plan that stops at an arbitrary horizon and
/// reads as one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Unpayable(pub String);

impl std::fmt::Display for Unpayable {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for Unpayable {}

/// Periodic rate from a nominal annual rate. 12 periods a year unless stated.
pub fn periodic_rate(apr: f64, periods_per_year: f64) -> f64 {
    apr / periods_per_year
}

pub struct PayoffOptions {
    pub periods_per_year: f64,
    pub max_periods: usize,
}

impl Default for PayoffOptions {
    fn default() -> Self {
        PayoffOptions { periods_per_year: 12.0, max_periods: 1200 }
    }
}

/// The ORDER the strategy attacks in.
///
/// Ties are broken by the other key, then by NAME, so a run is deterministic — two runs of the same
/// input must produce the same schedule or the comparison below is not reproducible.
pub fn payoff_order(debts: &[Debt], strategy: Strategy) -> Vec<Debt> {
    let mut out = debts.to_vec();
    out.sort_by(|a, b| {
        let by_rate = b.apr.partial_cmp(&a.apr).unwrap_or(std::cmp::Ordering::Equal);
        let by_balance = a.balance.minor.cmp(&b.balance.minor);
        let first = match strategy {
            Strategy::Avalanche => by_rate.then(by_balance),
            Strategy::Snowball => by_balance.then(by_rate),
        };
        first.then_with(|| a.name.cmp(&b.name))
    });
    out
}

/// Run one strategy to completion.
///
/// The mechanics, which are the same either way and are what actually retires debt:
///
/// - every debt accrues interest on its balance, then takes at least its minimum;
/// - whatever is left of `monthly_payment` goes ENTIRELY to the target — the first unpaid debt in
///   strategy order;
/// - when a debt clears, its minimum is NOT saved. It rolls into the next target. That rolling is
///   the "snowball", and it is why both strategies accelerate rather than run at a constant rate.
///
/// REFUSES an unpayable plan rather than looping. If the budget cannot cover the minimums, or a
/// balance grows despite paying them, no schedule exists.
pub fn payoff(debts: &[Debt], monthly_payment: Money, strategy: Strategy, opts: &PayoffOptions) -> Result<Plan, Unpayable> {
    if debts.is_empty() {
        return Err(Unpayable("payoff needs at least one debt".to_string()));
    }
    let currency = monthly_payment.currency;

    let mins: Vec<Money> = debts.iter().map(|d| d.minimum).collect();
    let minimums = sum(&mins, currency).map_err(|e| Unpayable(e.to_string()))?;
    if monthly_payment.minor < minimums.minor {
        return Err(Unpayable(format!(
            "the budget cannot cover the minimum payments ({} minor units of {}); a plan that ignores that is not a plan — the shortfall has to be closed first",
            minimums.minor, currency
        )));
    }

    let mut live = payoff_order(debts, strategy);
    let mut periods: Vec<Period> = Vec::new();
    let mut order: Vec<String> = Vec::new();
    let mut total_interest = money(0, currency);
    let mut total_paid = money(0, currency);

    let mut p = 0usize;
    while live.iter().any(|d| d.balance.minor != 0) {
        p += 1;
        if p > opts.max_periods {
            return Err(Unpayable(format!(
                "no payoff within {} periods — at this budget the interest is outrunning the payments, which is a fact worth stating rather than a schedule worth returning",
                opts.max_periods
            )));
        }
        let mut budget = monthly_payment.minor;
        let mut payments: Vec<Payment> = Vec::new();
        let mut cleared: Vec<String> = Vec::new();

        // 1 — interest, then the contractual minimum on every live debt.
        for d in live.iter_mut() {
            if d.balance.minor == 0 {
                continue;
            }
            let interest = crate::money::scale(d.balance, periodic_rate(d.apr, opts.periods_per_year), Rounding::HalfUp);
            let owed = d.balance.minor + interest.minor;
            // Never pay more than clears it, and never less than the minimum — unless the debt is
            // SMALLER than its own minimum, in which case the payoff amount IS the payment.
            let wanted = if d.minimum.minor < owed { d.minimum.minor } else { owed };
            let pay = wanted.min(budget);
            budget -= pay;
            let principal = pay - interest.minor;
            d.balance = money(owed - pay, currency);
            total_interest = money(total_interest.minor + interest.minor, currency);
            total_paid = money(total_paid.minor + pay, currency);
            payments.push(Payment { name: d.name.clone(), interest, principal: money(principal, currency), balance: d.balance });
        }

        // 2 — everything left attacks the TARGET, in strategy order.
        for d in live.iter_mut() {
            if budget == 0 {
                break;
            }
            if d.balance.minor == 0 {
                continue;
            }
            let extra = d.balance.minor.min(budget);
            budget -= extra;
            d.balance = money(d.balance.minor - extra, currency);
            total_paid = money(total_paid.minor + extra, currency);
            if let Some(row) = payments.iter_mut().find(|x| x.name == d.name) {
                row.principal = money(row.principal.minor + extra, currency);
                row.balance = d.balance;
            }
        }

        for d in live.iter() {
            if d.balance.minor == 0 && !order.contains(&d.name) {
                order.push(d.name.clone());
                cleared.push(d.name.clone());
            }
        }
        periods.push(Period { period: p, payments, cleared_this_period: cleared });
    }

    Ok(Plan { strategy, months: periods.len(), periods, total_interest, total_paid, order })
}

/// What choosing snowball over avalanche costs — the number the decision actually turns on.
#[derive(Debug, Clone, PartialEq)]
pub struct Comparison {
    pub avalanche: Plan,
    pub snowball: Plan,
    /// Extra interest snowball pays. Never negative: avalanche is optimal on interest by construction.
    pub extra_interest: Money,
    /// Extra periods snowball takes. Never negative.
    pub extra_months: i64,
    /// How much SOONER snowball clears its first debt — what it buys for that cost.
    pub first_cleared_sooner: i64,
}

pub fn compare_strategies(debts: &[Debt], monthly_payment: Money, opts: &PayoffOptions) -> Result<Comparison, Unpayable> {
    let avalanche = payoff(debts, monthly_payment, Strategy::Avalanche, opts)?;
    let snowball = payoff(debts, monthly_payment, Strategy::Snowball, opts)?;
    let first_cleared = |p: &Plan| -> i64 {
        p.periods.iter().find(|x| !x.cleared_this_period.is_empty()).map(|x| x.period as i64).unwrap_or(p.months as i64)
    };
    Ok(Comparison {
        extra_interest: money(snowball.total_interest.minor - avalanche.total_interest.minor, monthly_payment.currency),
        extra_months: snowball.months as i64 - avalanche.months as i64,
        first_cleared_sooner: first_cleared(&avalanche) - first_cleared(&snowball),
        avalanche,
        snowball,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn d(name: &str, balance: i64, apr: f64, minimum: i64) -> Debt {
        Debt { name: name.to_string(), balance: usd(balance), apr, minimum: usd(minimum) }
    }

    /// The store card has the SMALLEST balance and the LOWEST rate; medical has the HIGHEST rate at a
    /// middling balance. That is what makes the two strategies actually disagree — a fixture where
    /// the smallest debt is also the dearest one proves nothing, and my first one was exactly that.
    fn debts() -> Vec<Debt> {
        vec![d("visa", 300_000, 0.2299, 6_000), d("store", 80_000, 0.0999, 2_500), d("medical", 150_000, 0.2999, 4_000)]
    }

    #[test]
    fn avalanche_attacks_the_dearest_and_snowball_the_smallest() {
        let names = |s: Strategy| payoff_order(&debts(), s).iter().map(|d| d.name.clone()).collect::<Vec<_>>();
        assert_eq!(names(Strategy::Avalanche), vec!["medical", "visa", "store"], "by RATE");
        assert_eq!(names(Strategy::Snowball), vec!["store", "medical", "visa"], "by BALANCE");
    }

    #[test]
    fn the_cost_of_snowball_is_a_number_rather_than_a_slogan() {
        // Measured by running finance-payoff.ts on this exact fixture.
        let c = compare_strategies(&debts(), usd(40_000), &PayoffOptions::default()).expect("payable");
        assert_eq!(c.avalanche.months, 16);
        assert_eq!(c.avalanche.total_interest.minor, 78_043);
        assert_eq!(c.avalanche.total_paid.minor, 608_043);
        assert_eq!(c.snowball.months, 16);
        assert_eq!(c.snowball.total_interest.minor, 91_364);
        // Snowball costs $133.21 more and takes the same time — and clears its first debt three
        // months sooner. Both halves of the trade are reported; neither is chosen here.
        assert_eq!(c.extra_interest.minor, 13_321);
        assert_eq!(c.extra_months, 0);
        assert_eq!(c.first_cleared_sooner, 3);
        assert!(c.extra_interest.minor >= 0, "avalanche is optimal on interest BY CONSTRUCTION");
    }

    #[test]
    fn each_strategy_clears_its_debts_in_its_own_order() {
        let opts = PayoffOptions::default();
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &opts).expect("payable");
        let s = payoff(&debts(), usd(40_000), Strategy::Snowball, &opts).expect("payable");
        assert_eq!(a.order, vec!["medical", "visa", "store"]);
        assert_eq!(s.order, vec!["store", "medical", "visa"]);
        let cleared = |p: &Plan| p.periods.iter().filter(|x| !x.cleared_this_period.is_empty()).map(|x| (x.period, x.cleared_this_period.clone())).collect::<Vec<_>>();
        assert_eq!(cleared(&a), vec![(6, vec!["medical".to_string()]), (14, vec!["visa".to_string()]), (16, vec!["store".to_string()])]);
        assert_eq!(cleared(&s), vec![(3, vec!["store".to_string()]), (8, vec!["medical".to_string()]), (16, vec!["visa".to_string()])]);
    }

    #[test]
    fn the_first_period_pays_every_minimum_then_throws_the_rest_at_the_target() {
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        let p1: Vec<(&str, i64, i64, i64)> = a.periods[0].payments.iter().map(|x| (x.name.as_str(), x.interest.minor, x.principal.minor, x.balance.minor)).collect();
        // medical is the target, so it takes its own minimum PLUS everything left over.
        assert_eq!(p1, vec![("medical", 3_749, 27_751, 122_249), ("visa", 5_748, 252, 299_748), ("store", 666, 1_834, 78_166)]);
        // Every minimum was still paid: 4000 + 6000 + 2500 = 12500, and the other 27500 went to the
        // target. Skipping a minimum to attack faster is default, not strategy.
        let paid: i64 = a.periods[0].payments.iter().map(|x| x.interest.minor + x.principal.minor).sum();
        assert_eq!(paid, 40_000, "the whole budget is spent, nothing is idle");
    }

    #[test]
    fn a_budget_below_the_minimums_is_refused_rather_than_scheduled() {
        let e = payoff(&debts(), usd(1_000), Strategy::Avalanche, &PayoffOptions::default()).expect_err("unpayable");
        assert!(e.0.contains("cannot cover the minimum payments (12500 minor units of USD)"));
        assert!(e.0.contains("the shortfall has to be closed first"), "it says what to DO");
    }

    #[test]
    fn interest_outrunning_the_payment_is_stated_rather_than_truncated() {
        let opts = PayoffOptions { max_periods: 24, ..PayoffOptions::default() };
        let e = payoff(&[d("runaway", 1_000_000, 0.99, 100)], usd(100), Strategy::Avalanche, &opts).expect_err("unpayable");
        assert!(e.0.contains("no payoff within 24 periods"));
        // A truncated 24-period schedule would LOOK like a plan while being none. That is the whole
        // reason this returns an error rather than the periods it managed to compute.
        assert!(e.0.contains("worth stating rather than a schedule worth returning"));
    }

    #[test]
    fn no_debts_is_refused_because_there_is_nothing_to_schedule() {
        let e = payoff(&[], usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect_err("unpayable");
        assert_eq!(e.0, "payoff needs at least one debt");
    }

    #[test]
    fn a_debt_smaller_than_its_own_minimum_pays_only_what_clears_it() {
        // Balance 500, minimum 2500. Paying the minimum would overpay by 2000.
        let p = payoff(&[d("tiny", 500, 0.2, 2_500)], usd(2_500), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        assert_eq!(p.months, 1);
        assert_eq!(p.total_interest.minor, 8);
        assert_eq!(p.total_paid.minor, 508, "500 principal + 8 interest, NOT the 2500 minimum");
        let row = &p.periods[0].payments[0];
        assert_eq!((row.interest.minor, row.principal.minor, row.balance.minor), (8, 500, 0));
    }

    #[test]
    fn ties_break_deterministically_so_two_runs_agree() {
        let same = vec![d("b", 50_000, 0.2, 1_000), d("a", 50_000, 0.2, 1_000)];
        assert_eq!(payoff_order(&same, Strategy::Avalanche).iter().map(|d| d.name.clone()).collect::<Vec<_>>(), vec!["a", "b"], "by NAME once rate and balance tie");
        // Equal balances under avalanche fall back to the rate.
        let by_rate = vec![d("hi", 50_000, 0.3, 1_000), d("lo", 50_000, 0.1, 1_000)];
        assert_eq!(payoff_order(&by_rate, Strategy::Avalanche)[0].name, "hi");
        // Equal-ish rates under snowball fall back to the balance.
        let by_balance = vec![d("big", 90_000, 0.3, 1_000), d("small", 10_000, 0.1, 1_000)];
        assert_eq!(payoff_order(&by_balance, Strategy::Snowball)[0].name, "small");
    }

    #[test]
    fn the_periodic_rate_divides_the_nominal_annual_one() {
        assert!((periodic_rate(0.2299, 12.0) - 0.019158333333333333).abs() < 1e-15);
        assert!((periodic_rate(0.2299, 26.0) - 0.008842307692307693).abs() < 1e-15);
    }

    #[test]
    fn the_schedule_reconciles_to_the_cent() {
        // The reason this is integer minor units: principal + interest across every period must
        // equal what was paid, and the balances must reach exactly zero rather than nearly zero.
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        let principal: i64 = a.periods.iter().flat_map(|p| p.payments.iter()).map(|x| x.principal.minor).sum();
        let interest: i64 = a.periods.iter().flat_map(|p| p.payments.iter()).map(|x| x.interest.minor).sum();
        assert_eq!(interest, a.total_interest.minor);
        assert_eq!(principal + interest, a.total_paid.minor);
        // And the principal repaid equals exactly what was owed at the start.
        assert_eq!(principal, 300_000 + 80_000 + 150_000);
        for p in a.periods.last().expect("periods").payments.iter() {
            assert_eq!(p.balance.minor, 0, "{} did not reach exactly zero", p.name);
        }
    }
}

//! Spending analysis — and the one thing it exists to get right: **a transfer is not spending**.
//!
//! Paying $300 from chequing to a credit card looks exactly like a $300 outflow. It is not
//! consumption — it is the same money in a different place, and the card minimum is ALREADY on the
//! obligation calendar. Counting it here as well subtracts it twice from the runway, which shortens
//! the answer in a way that looks like prudence and is simply wrong. Moving money between your own
//! accounts is the same mistake with no upside at all.
//!
//! So outflows are classified before anything is totalled: PAIRED (an outflow matched by an inflow of
//! the same size on another account within a few days), DEBT (a payment to an account declared as a
//! debt), FIXED (matched to a detected recurring charge), or VARIABLE. Only variable spending is
//! discretionary, and [`discretionary_monthly`] is the figure `runway` asks for.
//!
//! # Categorisation is data, deterministic, and local
//!
//! A table of keywords, not a model — a model here would mean sending somebody's merchant list
//! somewhere. What it cannot place is reported as UNCATEGORISED rather than dropped into an "other"
//! bucket, because a large "other" is a finding and a large "uncategorised" is an admission.
use crate::money::{money, sum, Currency, Money};
use crate::position::Position;
use crate::reconcile::ReconciledLedger;
use crate::recurring::Recurring;
use crate::txn::{days_between, merchant_key_default, month_of, Txn};

/// Why an outflow is or is not discretionary spending.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OutflowClass {
    Paired,
    Debt,
    Fixed,
    Variable,
}

impl OutflowClass {
    pub fn label(self) -> &'static str {
        match self {
            OutflowClass::Paired => "paired",
            OutflowClass::Debt => "debt",
            OutflowClass::Fixed => "fixed",
            OutflowClass::Variable => "variable",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct ClassifiedOutflow {
    pub txn: Txn,
    pub kind: OutflowClass,
    /// Present for `Variable` and `Fixed`; NONE means nothing in the table matched — which is not
    /// the same as "other".
    pub category: Option<&'static str>,
    /// For `Paired`, the transaction on the other side.
    pub counterpart: Option<Txn>,
    /// For `Fixed`, the recurring charge it belongs to.
    pub recurring: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct CategoryTotal {
    pub category: &'static str,
    pub total: Money,
    pub count: usize,
    /// Median across the whole months observed — the usual month for this category.
    pub typical_month: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct SpendingAnalysis {
    pub from: String,
    pub to: String,
    /// WHOLE months the medians are computed over.
    pub months_observed: usize,
    pub outflows: Vec<ClassifiedOutflow>,
    /// Standing charges — rent, subscriptions, insurance. Not a choice this month.
    pub fixed_monthly: Money,
    /// Everything else that was actually consumed. What `runway` wants.
    pub variable_monthly: Money,
    pub categories: Vec<CategoryTotal>,
    /// The same totals over VARIABLE outflows only.
    ///
    /// `categories` covers everything that was spent, fixed charges included, because "where does my
    /// money go" wants rent in the answer. Anything downstream that ALSO counts the obligation
    /// calendar must use this one instead — rent appears in both, and adding them counts it twice.
    /// That is not hypothetical: `viable` did exactly that and overstated every tier by the whole of
    /// the rent, which tells somebody they need to earn far more than they do.
    pub variable_categories: Vec<CategoryTotal>,
    /// Money that MOVED rather than left. Named so the exclusion is visible, never silent.
    pub transferred: Money,
    pub transfer_count: usize,
    /// Payments to declared debts, excluded because the calendar already has them.
    pub debt_payments: Money,
    /// Outflows nothing in the table could place. Reported, never bucketed as "other".
    pub uncategorised: Vec<Txn>,
    pub notes: Vec<String>,
}

/// The category table. DATA, so it can be read, argued with and extended without touching logic.
///
/// FIRST MATCH WINS, so the order is meaningful: fuel before transport, groceries before shopping.
pub const CATEGORY_RULES: &[(&str, &[&str])] = &[
    ("housing", &["rent", "mortgage", "landlord", "property mgmt", "hoa"]),
    ("utilities", &["electric", "power", "gas company", "water", "sewer", "internet", "broadband", "mobile", "wireless", "phone"]),
    ("insurance", &["insurance", "assurance", "geico", "allstate"]),
    ("healthcare", &["pharmacy", "dental", "clinic", "medical", "hospital", "optical", "vision"]),
    ("childcare", &["daycare", "childcare", "nursery", "preschool"]),
    ("education", &["tuition", "university", "college", "student loan", "bookstore"]),
    ("fuel", &["shell", "chevron", "exxon", "bp", "texaco", "fuel", "petrol", "gas station"]),
    ("transport", &["uber", "lyft", "transit", "metro", "parking", "toll", "rail", "airline", "airlines"]),
    ("groceries", &["grocery", "market", "supermarket", "safeway", "kroger", "aldi", "trader", "whole foods", "food store"]),
    ("dining", &["restaurant", "cafe", "coffee", "pizza", "grill", "diner", "bar", "brewing", "doordash", "grubhub", "seamless"]),
    ("subscriptions", &["netflix", "spotify", "hulu", "prime", "membership", "subscription", "patreon"]),
    ("entertainment", &["cinema", "theatre", "theater", "concert", "steam", "playstation", "xbox", "nintendo"]),
    ("shopping", &["amzn", "amazon", "target", "walmart", "costco", "store", "shop", "retail"]),
    ("fees", &["fee", "interest", "overdraft", "service charge", "atm"]),
    ("cash", &["withdrawal", "cash", "atm withdrawal"]),
];

/// The category a description falls in, or NONE — which is not the same as "other".
pub fn categorise(description: &str) -> Option<&'static str> {
    let text = description.to_lowercase();
    CATEGORY_RULES.iter().find(|(_, matches)| matches.iter().any(|m| text.contains(m))).map(|(c, _)| *c)
}

pub struct SpendingOptions {
    /// How far apart the two halves of an internal transfer may be dated.
    pub transfer_window_days: i64,
}

impl Default for SpendingOptions {
    fn default() -> Self {
        SpendingOptions { transfer_window_days: 3 }
    }
}

fn median(xs: &[i64]) -> i64 {
    if xs.is_empty() {
        return 0;
    }
    let mut s = xs.to_vec();
    s.sort_unstable();
    let m = s.len() / 2;
    if s.len() % 2 == 1 {
        s[m]
    } else {
        let total = s[m - 1] + s[m];
        if total >= 0 { (total + 1).div_euclid(2) } else { -((-total).div_euclid(2)) }
    }
}

/// The months a median may be taken over: WHOLE ones only, dropping a partial at either end.
fn whole_months(dates: &[String]) -> Vec<String> {
    let mut months: Vec<String> = dates.iter().map(|d| month_of(d).to_string()).collect();
    months.sort();
    months.dedup();
    if months.len() > 2 { months[1..months.len() - 1].to_vec() } else { months }
}

pub fn analyse_spending(ledger: &ReconciledLedger, position: Option<&Position>, recurring: &[Recurring], currency: Currency, opts: &SpendingOptions) -> SpendingAnalysis {
    let rows = ledger.covered();
    let outflow_rows: Vec<&Txn> = rows.iter().filter(|t| t.amount.minor < 0).collect();
    let inflow_rows: Vec<&Txn> = rows.iter().filter(|t| t.amount.minor > 0).collect();
    let mut notes: Vec<String> = Vec::new();

    // PAIRING FIRST. An outflow matched by an inflow of the same size on ANOTHER account within a few
    // days is money that moved, not money that left. Each inflow can be claimed ONCE — otherwise two
    // identical outflows both match one deposit and one of them is wrongly excluded.
    let mut taken_inflow = vec![false; inflow_rows.len()];
    let mut pair_of: Vec<Option<Txn>> = vec![None; outflow_rows.len()];
    for (oi, out) in outflow_rows.iter().enumerate() {
        let hit = inflow_rows.iter().enumerate().find(|(ii, i)| {
            !taken_inflow[*ii] && i.account != out.account && i.amount.minor == -out.amount.minor && days_between(&out.date, &i.date).abs() <= opts.transfer_window_days
        });
        if let Some((ii, i)) = hit {
            taken_inflow[ii] = true;
            pair_of[oi] = Some((*i).clone());
        }
    }

    let empty: &[crate::position::AccountPosition] = &[];
    let accounts = position.map(|p| p.accounts.as_slice()).unwrap_or(empty);
    let debt_accounts: Vec<&str> = accounts.iter().filter(|a| a.is_debt).map(|a| a.account.as_str()).collect();
    let debt_names: Vec<String> = accounts.iter().filter(|a| a.is_debt).map(|a| a.institution.to_lowercase()).filter(|s| !s.is_empty()).collect();

    // Keyed on the PAIR, as `recurring` groups them — a joined string would need a separator that
    // neither an account name nor a merchant key can contain.
    let recurring_keys: Vec<((String, String), String)> = recurring.iter().map(|r| ((r.account.clone(), r.key.clone()), r.label.clone())).collect();

    let outflows: Vec<ClassifiedOutflow> = outflow_rows
        .iter()
        .enumerate()
        .map(|(oi, txn)| {
            if let Some(counterpart) = pair_of[oi].clone() {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Paired, category: None, counterpart: Some(counterpart), recurring: None };
            }

            // A payment to a card the ledger does not contain has no inflow to pair with, so the only
            // remaining signal is the institution's own name in the description.
            let text = txn.description.to_lowercase();
            if !debt_accounts.contains(&txn.account.as_str()) && debt_names.iter().any(|n| text.contains(n)) {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Debt, category: None, counterpart: None, recurring: None };
            }

            let key = (txn.account.clone(), merchant_key_default(&txn.description));
            if let Some((_, label)) = recurring_keys.iter().find(|(k, _)| *k == key) {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Fixed, category: categorise(&txn.description), counterpart: None, recurring: Some(label.clone()) };
            }

            ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Variable, category: categorise(&txn.description), counterpart: None, recurring: None }
        })
        .collect();

    let spent: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Fixed || o.kind == OutflowClass::Variable).collect();
    let months = whole_months(&spent.iter().map(|o| o.txn.date.clone()).collect::<Vec<_>>());

    let per_month = |rows_in: &[&ClassifiedOutflow]| -> i64 {
        let totals: Vec<i64> = months
            .iter()
            .map(|m| rows_in.iter().filter(|o| month_of(&o.txn.date) == m).map(|o| -o.txn.amount.minor).sum())
            .collect();
        median(&totals)
    };

    let in_whole_months: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| months.iter().any(|m| m == month_of(&o.txn.date))).copied().collect();
    let mut by_category: Vec<(&'static str, Vec<&ClassifiedOutflow>)> = Vec::new();
    for o in &in_whole_months {
        let Some(c) = o.category else { continue };
        match by_category.iter_mut().find(|(k, _)| *k == c) {
            Some((_, b)) => b.push(o),
            None => by_category.push((c, vec![o])),
        }
    }

    let mut by_variable_category: Vec<(&'static str, Vec<&ClassifiedOutflow>)> = Vec::new();
    for o in &in_whole_months {
        let Some(c) = o.category else { continue };
        if o.kind != OutflowClass::Variable {
            continue;
        }
        match by_variable_category.iter_mut().find(|(k, _)| *k == c) {
            Some((_, b)) => b.push(o),
            None => by_variable_category.push((c, vec![o])),
        }
    }

    let uncategorised: Vec<Txn> = in_whole_months.iter().filter(|o| o.category.is_none()).map(|o| o.txn.clone()).collect();
    if !uncategorised.is_empty() {
        let share = ((uncategorised.len() as f64 / in_whole_months.len().max(1) as f64) * 100.0).round();
        notes.push(format!(
            "{} outflow(s) — {}% of them — matched no category rule and are listed rather than bucketed as \"other\"; the category totals below do not add up to the monthly figures because of it",
            uncategorised.len(),
            share
        ));
    }
    if months.len() < 3 {
        notes.push(format!("only {} whole month(s) here — a median over that is a description of those months, not a pattern", months.len()));
    }

    let transfers: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Paired).collect();
    let debts: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Debt).collect();
    if !transfers.is_empty() {
        notes.push(format!(
            "{} outflow(s) were matched to an inflow elsewhere and are EXCLUDED — moving money between your own accounts is not spending",
            transfers.len()
        ));
    }
    if !debts.is_empty() {
        notes.push(format!(
            "{} payment(s) to a declared debt are EXCLUDED — the obligation calendar already carries them, and counting them here would subtract the same money twice",
            debts.len()
        ));
    }

    let total_of = |os: &[&ClassifiedOutflow]| -> Money {
        let amounts: Vec<Money> = os.iter().map(|o| money(-o.txn.amount.minor, currency)).collect();
        sum(&amounts, currency).unwrap_or_else(|_| money(0, currency))
    };

    let mut categories: Vec<CategoryTotal> = by_category
        .iter()
        .map(|(category, os)| CategoryTotal { category, total: total_of(os), count: os.len(), typical_month: money(per_month(os), currency) })
        .collect();
    categories.sort_by_key(|c| std::cmp::Reverse(c.total.minor));
    let mut variable_categories: Vec<CategoryTotal> = by_variable_category
        .iter()
        .map(|(category, os)| CategoryTotal { category, total: total_of(os), count: os.len(), typical_month: money(per_month(os), currency) })
        .collect();
    variable_categories.sort_by_key(|c| std::cmp::Reverse(c.total.minor));

    let fixed: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| o.kind == OutflowClass::Fixed).copied().collect();
    let variable: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| o.kind == OutflowClass::Variable).copied().collect();

    SpendingAnalysis {
        from: rows.first().map(|t| t.date.clone()).unwrap_or_else(|| ledger.through().to_string()),
        to: ledger.through().to_string(),
        months_observed: months.len(),
        fixed_monthly: money(per_month(&fixed), currency),
        variable_monthly: money(per_month(&variable), currency),
        categories,
        variable_categories,
        transferred: total_of(&transfers),
        transfer_count: transfers.len(),
        debt_payments: total_of(&debts),
        uncategorised,
        notes,
        outflows,
    }
}

/// The figure `runway` asks for: what an ordinary month costs BEYOND the standing obligations.
///
/// Fixed spending is deliberately NOT included — the obligation calendar already carries it, and a
/// runway that subtracted both would double-count every subscription it knows about.
pub fn discretionary_monthly(s: &SpendingAnalysis) -> Money {
    s.variable_monthly
}

/// Where the variable money actually goes, biggest first — the list to act on.
pub fn top_categories(s: &SpendingAnalysis, n: usize) -> &[CategoryTotal] {
    &s.categories[..n.min(s.categories.len())]
}

