//! Fee and interest audit — what the accounts are charging, gathered into one place.
//!
//! Fees are invisible for a structural reason: each one is small and they are scattered across
//! months and accounts. Nobody adds them up, so nobody sees the total, so nobody acts. Listing them
//! together turns a statement into a CALL SHEET — many are reversible on request, and a repeating fee
//! is usually a standing condition (a plan, a threshold, a due date) that can be changed once.
//!
//! # Patterns are data
//!
//! Institutions word these differently and change the wording; a matcher hard-coded into the logic
//! would silently stop matching and report a clean bill of health, which is the worst possible
//! failure for an audit. So the patterns are a TABLE, correctable in one line, and anything that
//! looks fee-shaped but matches nothing is REPORTED as unclassified rather than dropped.
use crate::money::{money, sum, Currency, Money};
use crate::txn::{month_of, Txn};

/// What kind of charge this is. The kinds differ in WHAT YOU CAN DO ABOUT THEM, which is the point.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FeeKind {
    Interest,
    Late,
    Overdraft,
    Nsf,
    Annual,
    ForeignTransaction,
    CashAdvance,
    Service,
}

impl FeeKind {
    pub fn label(self) -> &'static str {
        match self {
            FeeKind::Interest => "interest",
            FeeKind::Late => "late",
            FeeKind::Overdraft => "overdraft",
            FeeKind::Nsf => "nsf",
            FeeKind::Annual => "annual",
            FeeKind::ForeignTransaction => "foreign-transaction",
            FeeKind::CashAdvance => "cash-advance",
            FeeKind::Service => "service",
        }
    }
}

/// One alternative in a pattern.
///
/// The TypeScript uses regular expressions; every one of them reduces to a case-insensitive
/// alternation of literals plus a SINGLE wildcard construct (`non.?sufficient`). Two variants cover
/// the whole table, which is cheaper than a regex dependency and — more importantly — cannot quietly
/// acquire behaviour nobody wrote down.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Alt {
    /// A plain case-insensitive substring. Deliberately NOT word-bounded, matching the TypeScript:
    /// `od fee` finds "GOOD FEE" in both kits, and a change here would be a silent divergence.
    Literal(&'static str),
    /// `prefix` then AT MOST ONE character then `suffix` — the regex `non.?sufficient`, which is how
    /// "nonsufficient", "non-sufficient" and "non sufficient" are all one rule.
    Gap(&'static str, &'static str),
}

#[derive(Debug, Clone, Copy)]
pub struct FeePattern {
    pub kind: FeeKind,
    pub alts: &'static [Alt],
    /// What can actually be DONE about it. The reason the kinds are separate at all.
    pub lever: &'static str,
}

pub const FEE_PATTERNS: &[FeePattern] = &[
    FeePattern {
        kind: FeeKind::Interest,
        alts: &[Alt::Literal("interest charge"), Alt::Literal("finance charge"), Alt::Literal("purchase interest"), Alt::Literal("int chg")],
        lever: "a rate reduction, or clearing the balance faster — this is the recurring cost of the balance itself",
    },
    FeePattern {
        kind: FeeKind::Late,
        alts: &[Alt::Literal("late fee"), Alt::Literal("late charge"), Alt::Literal("past due fee")],
        lever: "usually reversible on request, especially once; a due-date change prevents the next one",
    },
    FeePattern {
        kind: FeeKind::Overdraft,
        alts: &[Alt::Literal("overdraft"), Alt::Literal("od fee"), Alt::Literal("odp fee")],
        lever: "often reversible; overdraft coverage can be switched off, or a buffer account linked",
    },
    FeePattern {
        kind: FeeKind::Nsf,
        alts: &[Alt::Literal("nsf"), Alt::Gap("non", "sufficient"), Alt::Literal("returned item"), Alt::Literal("insufficient funds")],
        lever: "often reversible once; the underlying cause is timing rather than total",
    },
    FeePattern {
        kind: FeeKind::Annual,
        alts: &[Alt::Literal("annual fee"), Alt::Literal("membership fee"), Alt::Literal("card fee")],
        lever: "ask for it to be waived, or move to a no-fee product on the same account",
    },
    FeePattern {
        kind: FeeKind::ForeignTransaction,
        // `intl? fee` is exactly these two literals.
        alts: &[Alt::Literal("foreign transaction"), Alt::Literal("foreign purchase"), Alt::Literal("int fee"), Alt::Literal("intl fee")],
        lever: "structural — a no-foreign-fee card avoids it entirely",
    },
    FeePattern {
        kind: FeeKind::CashAdvance,
        alts: &[Alt::Literal("cash advance"), Alt::Literal("cash adv fee")],
        lever: "no grace period and a higher rate; the fix is not using the facility",
    },
    FeePattern {
        kind: FeeKind::Service,
        alts: &[Alt::Literal("service charge"), Alt::Literal("maintenance fee"), Alt::Literal("monthly fee"), Alt::Literal("paper statement")],
        lever: "usually waived by a balance minimum, a direct deposit, or switching statement delivery",
    },
];

/// Words that mark a line as fee-shaped even when no specific pattern matches it.
///
/// WORD-BOUNDED, unlike the pattern literals: `\bfee\b` must not find "coffee", or every café would
/// enter the audit as an unclassified charge and the gap-in-the-table signal would be noise.
const FEE_SHAPED: &[&str] = &["fee", "charge", "interest", "penalty"];

fn is_word_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// `\bword\b` over an already-lowercased haystack.
fn contains_word(text: &str, word: &str) -> bool {
    let b = text.as_bytes();
    let mut from = 0;
    while let Some(i) = text[from..].find(word).map(|i| i + from) {
        let before_ok = i == 0 || !is_word_char(b[i - 1] as char);
        let end = i + word.len();
        let after_ok = end >= b.len() || !is_word_char(b[end] as char);
        if before_ok && after_ok {
            return true;
        }
        from = i + 1;
    }
    false
}

fn alt_matches(text: &str, alt: &Alt) -> bool {
    match alt {
        Alt::Literal(s) => text.contains(s),
        Alt::Gap(prefix, suffix) => {
            let mut from = 0;
            while let Some(i) = text[from..].find(prefix).map(|i| i + from) {
                let after = i + prefix.len();
                // AT MOST ONE character between, matching `.?` — and `.` never matches a newline in
                // a JavaScript regex, so a line break does not bridge the gap here either.
                for skip in [0usize, 1] {
                    let start = after + skip;
                    if skip == 1 {
                        match text[after..].chars().next() {
                            None | Some('\n') => continue,
                            Some(_) => {}
                        }
                    }
                    if text.is_char_boundary(start) && text[start..].starts_with(suffix) {
                        return true;
                    }
                }
                from = i + 1;
            }
            false
        }
    }
}

/// Which pattern a description falls under. FIRST MATCH WINS, so the table order is meaningful.
pub fn classify(description: &str) -> Option<&'static FeePattern> {
    let text = description.to_lowercase();
    FEE_PATTERNS.iter().find(|p| p.alts.iter().any(|a| alt_matches(&text, a)))
}

/// Fee-shaped but unmatched — a gap in the table, visible as a gap.
pub fn looks_fee_shaped(description: &str) -> bool {
    let text = description.to_lowercase();
    FEE_SHAPED.iter().any(|w| contains_word(&text, w))
}

#[derive(Debug, Clone, PartialEq)]
pub struct Fee {
    pub date: String,
    pub account: String,
    pub description: String,
    pub amount: Money,
    pub kind: FeeKind,
    pub lever: &'static str,
}

#[derive(Debug, Clone, PartialEq)]
pub struct RecurringCondition {
    pub account: String,
    pub kind: FeeKind,
    pub months: usize,
    pub total: Money,
    pub lever: &'static str,
}

#[derive(Debug, Clone, PartialEq)]
pub struct FeeAudit {
    pub fees: Vec<Fee>,
    /// Total charged over the whole set. The number nobody has ever seen before running this.
    pub total: Money,
    pub by_kind: Vec<(FeeKind, Money)>,
    pub by_account: Vec<(String, Money)>,
    /// A kind that appears in THREE OR MORE distinct months on one account: not an accident, a
    /// standing condition. These are where a single change stops a stream of charges.
    pub recurring_conditions: Vec<RecurringCondition>,
    /// Looked fee-shaped, matched no pattern. REPORTED so a gap in the table is visible as a gap —
    /// an audit that silently matches nothing reports zero fees, which reads like good news.
    pub unclassified: Vec<Txn>,
}

pub fn audit_fees(txns: &[Txn], currency: Currency) -> FeeAudit {
    let mut fees: Vec<Fee> = Vec::new();
    let mut unclassified: Vec<Txn> = Vec::new();

    for t in txns {
        // A fee is money LEAVING. A line matching "interest" that pays IN is interest earned, which
        // is a different thing entirely and must not be totalled as a cost.
        if t.amount.minor >= 0 {
            continue;
        }
        match classify(&t.description) {
            Some(p) => fees.push(Fee {
                date: t.date.clone(),
                account: t.account.clone(),
                description: t.description.clone(),
                amount: t.amount,
                kind: p.kind,
                lever: p.lever,
            }),
            None if looks_fee_shaped(&t.description) => unclassified.push(t.clone()),
            None => {}
        }
    }

    let mut by_kind: Vec<(FeeKind, Money)> = Vec::new();
    let mut by_account: Vec<(String, Money)> = Vec::new();
    for f in &fees {
        match by_kind.iter_mut().find(|(k, _)| *k == f.kind) {
            Some((_, v)) => *v = money(v.minor + f.amount.minor, currency),
            None => by_kind.push((f.kind, money(f.amount.minor, currency))),
        }
        match by_account.iter_mut().find(|(a, _)| *a == f.account) {
            Some((_, v)) => *v = money(v.minor + f.amount.minor, currency),
            None => by_account.push((f.account.clone(), money(f.amount.minor, currency))),
        }
    }

    // A REPEATING fee is the finding worth acting on: one change stops the whole stream. Keyed on
    // the `(account, kind)` PAIR, as every other grouping here is.
    struct Group {
        account: String,
        kind: FeeKind,
        months: Vec<String>,
        total: i64,
        lever: &'static str,
    }
    let mut groups: Vec<Group> = Vec::new();
    for f in &fees {
        let m = month_of(&f.date).to_string();
        match groups.iter_mut().find(|g| g.account == f.account && g.kind == f.kind) {
            Some(g) => {
                if !g.months.contains(&m) {
                    g.months.push(m);
                }
                g.total += f.amount.minor;
                g.lever = f.lever;
            }
            None => groups.push(Group { account: f.account.clone(), kind: f.kind, months: vec![m], total: f.amount.minor, lever: f.lever }),
        }
    }
    let mut recurring_conditions: Vec<RecurringCondition> = groups
        .into_iter()
        .filter(|g| g.months.len() >= 3)
        .map(|g| RecurringCondition { account: g.account, kind: g.kind, months: g.months.len(), total: money(g.total, currency), lever: g.lever })
        .collect();
    // COSTLIEST STANDING CONDITION FIRST — and since a fee is a negative amount, ascending order is
    // what puts the biggest one at the top. Sorting descending here would silently invert the list.
    recurring_conditions.sort_by_key(|r| r.total.minor);

    let amounts: Vec<Money> = fees.iter().map(|f| f.amount).collect();
    let total = sum(&amounts, currency).unwrap_or_else(|_| money(0, currency));

    FeeAudit { fees, total, by_kind, by_account, recurring_conditions, unclassified }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn t(date: &str, description: &str, minor: i64, account: &str) -> Txn {
        Txn { account: account.to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn kind_of(description: &str) -> Option<&'static str> {
        classify(description).map(|p| p.kind.label())
    }

    #[test]
    fn every_wording_in_the_table_lands_on_its_kind() {
        // Measured by running finance-fees.ts on each of these descriptions.
        for (d, want) in [
            ("INTEREST CHARGE ON PURCHASES", "interest"),
            ("FINANCE CHARGE", "interest"),
            ("INT CHG", "interest"),
            ("LATE FEE", "late"),
            ("PAST DUE FEE", "late"),
            ("OVERDRAFT FEE", "overdraft"),
            ("OD FEE", "overdraft"),
            ("NSF FEE", "nsf"),
            ("RETURNED ITEM", "nsf"),
            ("ANNUAL FEE", "annual"),
            ("MEMBERSHIP FEE", "annual"),
            ("FOREIGN TRANSACTION FEE", "foreign-transaction"),
            ("INT FEE", "foreign-transaction"),
            ("INTL FEE", "foreign-transaction"),
            ("CASH ADVANCE FEE", "cash-advance"),
            ("SERVICE CHARGE", "service"),
            ("MONTHLY FEE", "service"),
            ("PAPER STATEMENT", "service"),
        ] {
            assert_eq!(kind_of(d), Some(want), "{d}");
        }
        assert_eq!(FEE_PATTERNS.len(), 8);
    }

    #[test]
    fn the_one_wildcard_in_the_table_covers_three_spellings_of_the_same_fee() {
        // `non.?sufficient` — at most one character between, which is how all three are one rule.
        assert_eq!(kind_of("NONSUFFICIENT FUNDS"), Some("nsf"));
        assert_eq!(kind_of("NON-SUFFICIENT FUNDS"), Some("nsf"));
        assert_eq!(kind_of("NON SUFFICIENT FUNDS"), Some("nsf"));
        // TWO characters between is not a match — `.?` is at most one.
        assert!(alt_matches("nonsufficient", &Alt::Gap("non", "sufficient")));
        assert!(alt_matches("non-sufficient", &Alt::Gap("non", "sufficient")));
        assert!(!alt_matches("non--sufficient", &Alt::Gap("non", "sufficient")));
        // And a false start is retried rather than abandoned at the first "non".
        assert!(alt_matches("nonesuch and non sufficient", &Alt::Gap("non", "sufficient")));
    }

    #[test]
    fn fee_shaped_is_word_bounded_so_a_cafe_is_not_an_unclassified_charge() {
        // `\bfee\b` must not find "coffee", or every café enters the audit as a gap in the table
        // and the signal becomes noise.
        assert!(!looks_fee_shaped("COFFEE SHOP"));
        assert!(!looks_fee_shaped("FEEDER SUPPLY CO"));
        assert!(looks_fee_shaped("MYSTERY PENALTY"));
        assert!(looks_fee_shaped("SOME CHARGE HERE"));
        assert!(!looks_fee_shaped("TOLL BOOTH"));
        assert!(looks_fee_shaped("a fee"), "at the end of the string is still a boundary");
        assert!(looks_fee_shaped("fee-based"), "a hyphen is a boundary");
        assert!(!looks_fee_shaped("fee_based"), "an underscore is a word character, as in JavaScript");
    }

    #[test]
    fn the_pattern_literals_are_not_word_bounded_and_that_matches_the_other_kit() {
        // `od fee` has no \b in the TypeScript, so it finds "GOOD FEE" there too. Preserved rather
        // than tidied: a divergence here would be invisible and would only show as two kits
        // disagreeing about somebody's statement.
        assert_eq!(kind_of("A GOOD FEE"), Some("overdraft"));
    }

    #[test]
    fn interest_paid_in_is_not_a_fee() {
        // A line matching "interest" that pays in is interest EARNED. Totalling it as a cost would
        // make a savings account look like it was charging you.
        let a = audit_fees(&[t("2026-01-01", "INTEREST PAID", 500, "sav")], Currency::USD);
        assert!(a.fees.is_empty());
        assert!(a.unclassified.is_empty(), "and it is not a gap in the table either");
        assert_eq!(a.total.minor, 0);
    }

    #[test]
    fn the_audit_totals_what_nobody_has_added_up_before() {
        let rows = vec![
            t("2026-01-05", "INTEREST CHARGE ON PURCHASES", -4_500, "visa"),
            t("2026-02-05", "INTEREST CHARGE ON PURCHASES", -4_300, "visa"),
            t("2026-03-05", "INTEREST CHARGE ON PURCHASES", -4_100, "visa"),
            t("2026-01-09", "LATE FEE", -3_500, "visa"),
            t("2026-02-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-03-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-04-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-02-11", "WEIRD PENALTY THING", -900, "chk"),
        ];
        let a = audit_fees(&rows, Currency::USD);
        assert_eq!(a.fees.len(), 7);
        assert_eq!(a.total.minor, -20_000, "$200 nobody had seen as one number");
        assert_eq!(a.by_kind.iter().map(|(k, v)| (k.label(), v.minor)).collect::<Vec<_>>(), vec![("interest", -12_900), ("late", -3_500), ("service", -3_600)]);
        assert_eq!(a.by_account.iter().map(|(k, v)| (k.as_str(), v.minor)).collect::<Vec<_>>(), vec![("visa", -16_400), ("chk", -3_600)]);
        // Fee-shaped and unmatched: REPORTED, so a gap in the table is visible as a gap.
        assert_eq!(a.unclassified.len(), 1);
        assert_eq!(a.unclassified[0].description, "WEIRD PENALTY THING");
    }

    #[test]
    fn three_months_of_the_same_charge_is_a_standing_condition_not_an_accident() {
        let rows = vec![
            t("2026-01-05", "INTEREST CHARGE ON PURCHASES", -4_500, "visa"),
            t("2026-02-05", "INTEREST CHARGE ON PURCHASES", -4_300, "visa"),
            t("2026-03-05", "INTEREST CHARGE ON PURCHASES", -4_100, "visa"),
            t("2026-01-09", "LATE FEE", -3_500, "visa"),
            t("2026-02-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-03-20", "MONTHLY FEE", -1_200, "chk"),
            t("2026-04-20", "MONTHLY FEE", -1_200, "chk"),
        ];
        let a = audit_fees(&rows, Currency::USD);
        let got: Vec<(&str, &str, usize, i64)> = a.recurring_conditions.iter().map(|r| (r.account.as_str(), r.kind.label(), r.months, r.total.minor)).collect();
        // COSTLIEST FIRST — and a fee is negative, so that is ASCENDING. The single late fee is one
        // month and is correctly not a standing condition.
        assert_eq!(got, vec![("visa", "interest", 3, -12_900), ("chk", "service", 3, -3_600)]);
        assert!(a.recurring_conditions.iter().all(|r| !r.lever.is_empty()), "each carries what to DO about it");
        assert!(a.recurring_conditions[0].lever.contains("rate reduction"));
    }

    #[test]
    fn two_charges_in_one_month_are_not_three_months() {
        let rows = vec![
            t("2026-01-05", "LATE FEE", -3_500, "visa"),
            t("2026-01-15", "LATE FEE", -3_500, "visa"),
            t("2026-01-25", "LATE FEE", -3_500, "visa"),
        ];
        let a = audit_fees(&rows, Currency::USD);
        assert_eq!(a.fees.len(), 3);
        // DISTINCT months is the test, not occurrences — three in one month is one bad month, and a
        // standing condition is what a single change can stop.
        assert!(a.recurring_conditions.is_empty());
    }

    #[test]
    fn an_empty_set_audits_to_zero_rather_than_failing() {
        let a = audit_fees(&[], Currency::USD);
        assert_eq!(a.total.minor, 0);
        assert!(a.fees.is_empty() && a.by_kind.is_empty() && a.recurring_conditions.is_empty());
    }
}

//! Negotiation prep — the case for the phone call, assembled from your own data.
//!
//! Issuers reduce rates, waive fees and open hardship plans routinely, and almost nobody asks. The
//! call costs nothing: a retention conversation is not a credit application, so there is no hard
//! pull and no score consequence to trying. What there IS, is a right ask and a wrong one — and
//! getting that wrong is how a call that could have helped ends with a "no" on the record.
//!
//! # The ask depends on whether you can pay
//!
//! This is the judgement the module exists to make:
//!
//! - **You can pay** → a RATE REDUCTION, on the strength of tenure, a clean payment history, and a
//!   competing offer you can actually name. This is a customer worth keeping asking to be treated
//!   like one.
//! - **You cannot pay** → a HARDSHIP PLAN, and the timing is the whole thing: entered BEFORE a
//!   missed payment it is an arrangement, and the account stays current on the report. Entered
//!   after, the delinquency is already reported and cannot be taken back. Asking for a rate cut in
//!   this situation wastes the one call you get.
//!
//! A fee that has already landed is a SEPARATE, EASIER call. First-offence waivers are close to
//! routine, so a recent fee is its own ask and goes first — the cheapest win available, and it does
//! not spend any of the goodwill the rate call needs.
//!
//! The evidence here is only ever what the data actually supports. ABSENT EVIDENCE IS ABSENT: a case
//! that invents leverage produces a person confidently saying something an issuer can disprove from
//! their own screen, which is worse than saying nothing.
use crate::account::Kind;
use crate::fees::{FeeAudit, FeeKind};
use crate::money::{money, scale, Currency, Money, Rounding};
use crate::position::{AccountPosition, Position};
use crate::transfer::TransferOffer;
use crate::txn::days_between;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ask {
    FeeWaiver,
    RateReduction,
    HardshipPlan,
}

impl Ask {
    pub fn label(self) -> &'static str {
        match self {
            Ask::FeeWaiver => "fee-waiver",
            Ask::RateReduction => "rate-reduction",
            Ask::HardshipPlan => "hardship-plan",
        }
    }

    /// Cheapest win first. A waiver call does not spend the goodwill the rate call needs.
    fn rank(self) -> u8 {
        match self {
            Ask::FeeWaiver => 0,
            Ask::HardshipPlan => 1,
            Ask::RateReduction => 2,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Strength {
    Strong,
    Moderate,
    Weak,
}

impl Strength {
    pub fn label(self) -> &'static str {
        match self {
            Strength::Strong => "strong",
            Strength::Moderate => "moderate",
            Strength::Weak => "weak",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Evidence {
    /// What can actually be SAID on the call.
    pub claim: String,
    pub strength: Strength,
    /// Where it came from, so it can be checked before it is repeated to a stranger.
    pub source: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct NegotiationCase {
    pub account: String,
    pub institution: String,
    pub ask: Ask,
    /// Why THIS ask and not another.
    pub why: String,
    pub evidence: Vec<Evidence>,
    /// Things not to say, each with the reason it costs you.
    pub do_not_say: Vec<String>,
    /// What a reasonable outcome looks like, so a partial win is not read as a failure.
    pub realistic: String,
    /// A year of the ask, IF it is granted. Contingent, and labelled as such.
    pub annual_value_if_won: Money,
    pub urgency: Option<String>,
}

pub struct NegotiationInput<'a> {
    pub position: &'a Position,
    /// `YYYY-MM-DD`. Passed in, never read from a clock.
    pub as_of: &'a str,
    /// Whether the runway holds — the single fact that decides the ask.
    pub can_pay: bool,
    pub fees: Option<&'a FeeAudit>,
    /// Real offers you could name on the call. The strongest lever there is.
    pub offers: &'a [TransferOffer],
    /// Months the account has been open, where it is known.
    pub tenure_months: &'a [(String, i64)],
    /// How much of a rate cut to model. Not a promise, a unit for the arithmetic.
    pub target_reduction: f64,
    /// A fee this recent is a live waiver candidate.
    pub fee_window_days: i64,
    /// Utilisation above which closing this line would hurt the rest.
    pub utilisation_concern: f64,
}

impl<'a> NegotiationInput<'a> {
    pub fn new(position: &'a Position, as_of: &'a str, can_pay: bool) -> Self {
        NegotiationInput {
            position,
            as_of,
            can_pay,
            fees: None,
            offers: &[],
            tenure_months: &[],
            target_reduction: 0.05,
            fee_window_days: 120,
            utilisation_concern: 0.3,
        }
    }
}

fn pct(n: f64) -> String {
    format!("{}%", (n * 10_000.0).round() / 100.0)
}

/// What overall utilisation would become if this line were CLOSED.
///
/// The reason it matters is the reason "I'll close it" is dangerous advice: THEY MIGHT SAY YES. The
/// balance moves nowhere and the limit disappears, so utilisation across everything left jumps.
pub fn utilisation_if_closed(position: &Position, account: &str) -> Option<f64> {
    let lines: Vec<&AccountPosition> = position.accounts.iter().filter(|a| a.kind == Kind::Credit && a.credit_limit.is_some()).collect();
    let limit: i64 = lines.iter().filter(|a| a.account != account).map(|a| a.credit_limit.map(|l| l.minor).unwrap_or(0)).sum();
    if limit <= 0 {
        return None;
    }
    // The owed total keeps the CLOSED line's balance — that is the entire point. It does not go
    // anywhere; only the limit does.
    let owed: i64 = lines.iter().map(|a| a.owed.map(|o| o.minor).unwrap_or(0)).sum();
    Some((owed as f64 / limit as f64 * 1000.0).round() / 1000.0)
}

fn gather_evidence(a: &AccountPosition, input: &NegotiationInput) -> Vec<Evidence> {
    let mut out: Vec<Evidence> = Vec::new();

    if let Some((_, tenure)) = input.tenure_months.iter().find(|(k, _)| *k == a.account) {
        out.push(Evidence {
            claim: format!("the account has been open {tenure} month(s)"),
            // Under a year is not tenure, it is a trial period, and saying it out loud helps nobody.
            strength: if *tenure >= 36 { Strength::Strong } else if *tenure >= 12 { Strength::Moderate } else { Strength::Weak },
            source: "months between the first and last transaction observed on this account".to_string(),
        });
    }

    if let Some(fees) = input.fees {
        let mine: Vec<&crate::fees::Fee> = fees.fees.iter().filter(|f| f.account == a.account).collect();
        let late: Vec<&&crate::fees::Fee> = mine.iter().filter(|f| f.kind == FeeKind::Late || f.kind == FeeKind::Nsf).collect();
        if late.is_empty() {
            // THE STRONGEST SINGLE CARD, and it is the one people forget they hold.
            out.push(Evidence {
                claim: "no late or returned-payment fee appears anywhere in the statements held".to_string(),
                strength: Strength::Strong,
                source: "the fee audit over every ingested statement".to_string(),
            });
        } else {
            let mut dates: Vec<&str> = late.iter().map(|f| f.date.as_str()).collect();
            dates.sort();
            out.push(Evidence {
                claim: format!("{} late or returned-payment fee(s) appear, the most recent on {}", late.len(), dates.last().copied().unwrap_or("")),
                strength: Strength::Weak,
                source: "the fee audit".to_string(),
            });
        }
        let interest: i64 = mine.iter().filter(|f| f.kind == FeeKind::Interest).map(|f| f.amount.minor.abs()).sum();
        if interest > 0 {
            // Concrete, and THEIR OWN NUMBER. "I have paid you X" is a harder sentence to wave away
            // than "your rate is high".
            out.push(Evidence {
                claim: format!("{interest} minor units of interest have been paid to this account in the statements held"),
                strength: Strength::Strong,
                source: "the fee audit, interest rows only".to_string(),
            });
        }
    }

    let mut better: Vec<&TransferOffer> = input
        .offers
        .iter()
        .filter(|o| o.institution != a.institution && o.promo_apr < a.apr.unwrap_or(f64::INFINITY))
        .collect();
    better.sort_by(|x, y| x.promo_apr.partial_cmp(&y.promo_apr).unwrap_or(std::cmp::Ordering::Equal));
    if let Some(b) = better.first() {
        let expires = b.offer_expires.as_ref().map(|e| format!(", expiring {e}")).unwrap_or_default();
        out.push(Evidence {
            claim: format!("{} is offering {} for {} months{expires}", b.institution, pct(b.promo_apr), b.promo_months),
            strength: Strength::Strong,
            source: "an offer supplied to this analysis — name it only if it is real and you would take it".to_string(),
        });
    }

    if let Some(u) = a.utilisation {
        out.push(Evidence {
            claim: if u <= 0.3 {
                format!("this line is only {}% used, which is what a low-risk customer looks like", (u * 100.0).round())
            } else {
                format!("this line is {}% used, which is what a customer worth retaining looks like", (u * 100.0).round())
            },
            strength: if u <= 0.3 { Strength::Moderate } else { Strength::Weak },
            source: "the position's utilisation for this account".to_string(),
        });
    }

    out
}

pub fn prepare_negotiation(input: &NegotiationInput) -> Vec<NegotiationCase> {
    let currency = input.position.currency;
    let mut cases: Vec<NegotiationCase> = Vec::new();

    for a in &input.position.accounts {
        let (true, Some(owed)) = (a.is_debt, a.owed) else { continue };

        let evidence = gather_evidence(a, input);
        let recent_fees: Vec<&crate::fees::Fee> = input
            .fees
            .map(|f| f.fees.as_slice())
            .unwrap_or(&[])
            .iter()
            .filter(|f| {
                f.account == a.account
                    && f.kind != FeeKind::Interest
                    && days_between(&f.date, input.as_of) <= input.fee_window_days
                    && days_between(&f.date, input.as_of) >= 0
            })
            .collect();

        let mut do_not_say: Vec<String> = Vec::new();
        if let Some(closed) = utilisation_if_closed(input.position, &a.account) {
            if closed > input.utilisation_concern {
                // THEY MIGHT SAY YES. The balance moves nowhere and the limit disappears.
                do_not_say.push(format!(
                    "do not threaten to close this account — if they accept, utilisation across everything left goes to {}%, and the balance has not moved an inch",
                    (closed * 100.0).round()
                ));
            }
        }
        do_not_say.push("do not say you are considering bankruptcy unless you are — it can freeze the account and end the conversation you wanted".to_string());
        do_not_say.push("do not accept a deferral that CAPITALISES the interest without asking what it does to the balance".to_string());

        // THE CHEAPEST WIN FIRST.
        if !recent_fees.is_empty() {
            let total: i64 = recent_fees.iter().map(|f| f.amount.minor.abs()).sum();
            cases.push(NegotiationCase {
                account: a.account.clone(),
                institution: a.institution.clone(),
                ask: Ask::FeeWaiver,
                why: format!(
                    "{} fee(s) totalling {total} minor units landed in the last {} days, and a first-offence waiver is close to routine for anyone who asks",
                    recent_fees.len(),
                    input.fee_window_days
                ),
                evidence: evidence.clone(),
                do_not_say: do_not_say.clone(),
                realistic: "one fee waived is the usual outcome; several at once is not. Ask for the most recent one by name and date.".to_string(),
                annual_value_if_won: money(total, currency),
                urgency: Some("fees are easiest to reverse in the cycle they appear — this gets harder every statement that passes".to_string()),
            });
        }

        if !input.can_pay {
            // THE TIMING IS THE WHOLE THING.
            let mut dns = do_not_say.clone();
            dns.push("do not ask for a rate reduction in the same call — it signals you expect to keep revolving, and it is answered by a different team".to_string());
            cases.push(NegotiationCase {
                account: a.account.clone(),
                institution: a.institution.clone(),
                ask: Ask::HardshipPlan,
                why: "the runway does not hold, so a rate cut is not the ask — a hardship or forbearance arrangement is, and it is a different department and a different conversation".to_string(),
                evidence,
                do_not_say: dns,
                realistic: "a fixed reduced rate for 6-12 months with the account reported CURRENT is a normal outcome; a written-off balance is not".to_string(),
                annual_value_if_won: scale(owed, a.apr.unwrap_or(0.0).min(0.15), Rounding::HalfUp),
                urgency: Some(
                    "CALL BEFORE A PAYMENT IS MISSED. Entered before a delinquency this is an arrangement and the account stays current on the report; entered after, the delinquency is already reported and no arrangement takes it back.".to_string(),
                ),
            });
            continue;
        }

        let strong = evidence.iter().filter(|e| e.strength == Strength::Strong).count();
        cases.push(NegotiationCase {
            account: a.account.clone(),
            institution: a.institution.clone(),
            ask: Ask::RateReduction,
            // The call costing nothing is true either way, so it is said either way. It is the
            // reason to make the WEAK call as well as the strong one, and burying it in the strong
            // branch would leave a case with no evidence reading as a case not worth making.
            why: if strong > 0 {
                format!("{strong} piece(s) of strong evidence support it. The call costs nothing — a retention conversation is not a credit application, so there is no hard pull.")
            } else {
                "there is little here to argue from, so this is a plain ask rather than a case. The call still costs nothing — a retention conversation is not a credit application, so there is no hard pull — and the answer is sometimes yes anyway.".to_string()
            },
            evidence,
            do_not_say,
            realistic: format!(
                "a reduction of 3-7 points is a normal outcome; {} going to zero is not. A \"no\" today does not stop you asking again in six months.",
                pct(a.apr.unwrap_or(0.0))
            ),
            annual_value_if_won: scale(owed, input.target_reduction.min(a.apr.unwrap_or(0.0)), Rounding::HalfUp),
            urgency: None,
        });
    }

    // Cheapest win first, then by what the ask is worth.
    cases.sort_by(|x, y| x.ask.rank().cmp(&y.ask.rank()).then_with(|| y.annual_value_if_won.minor.cmp(&x.annual_value_if_won.minor)));
    cases
}

/// Everything the calls are worth together, IF every one lands. Contingent, and it says so.
pub fn total_if_every_ask_lands(cases: &[NegotiationCase], currency: Currency) -> Money {
    money(cases.iter().map(|c| c.annual_value_if_won.minor).sum(), currency)
}

/// The order to make the calls in, with the one sentence that opens each.
pub fn call_order(cases: &[NegotiationCase]) -> Vec<String> {
    cases
        .iter()
        .map(|c| match c.ask {
            Ask::FeeWaiver => format!("{}: \"I saw a fee on my last statement and I'd like to ask for it to be waived.\"", c.institution),
            Ask::HardshipPlan => format!("{}: \"I want to stay current and I'm not going to be able to at this rate. What hardship options do you have?\"", c.institution),
            Ask::RateReduction => format!("{}: \"I've been a customer a while and I'm looking at my rate. What can you do?\"", c.institution),
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fees::audit_fees;
    use crate::money::usd;
    use crate::txn::Txn;

    // SYNTHETIC FIXTURES ONLY.
    #[allow(clippy::too_many_arguments)]
    fn acct(account: &str, inst: &str, owed: i64, apr: Option<f64>, limit: Option<i64>, util: Option<f64>) -> AccountPosition {
        AccountPosition {
            account: account.to_string(),
            institution: inst.to_string(),
            kind: Kind::Credit,
            balance: usd(-owed),
            as_of: "2026-06-30".to_string(),
            rolled_forward: 0,
            is_debt: true,
            owed: Some(usd(owed)),
            credit_limit: limit.map(usd),
            available: None,
            utilisation: util,
            apr,
            daily_interest: None,
            minimum_payment: None,
        }
    }

    fn pos(accounts: Vec<AccountPosition>) -> Position {
        Position {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            accounts,
            net_worth: usd(0),
            liquid: usd(0),
            total_debt: usd(0),
            daily_interest: usd(0),
            minimums_due: usd(0),
            weighted_apr: None,
            complete: true,
            provenance: "x".to_string(),
            problems: Vec::new(),
        }
    }

    fn t(date: &str, d: &str, m: i64, a: &str) -> Txn {
        Txn { account: a.to_string(), date: date.to_string(), description: d.to_string(), amount: usd(m) }
    }

    fn two_cards() -> Position {
        pos(vec![acct("visa", "chase", 300_000, Some(0.2299), Some(500_000), Some(0.6)), acct("store", "storeco", 80_000, Some(0.0999), Some(100_000), Some(0.8))])
    }

    fn fee_audit() -> FeeAudit {
        audit_fees(
            &[t("2026-05-20", "LATE FEE", -3_500, "visa"), t("2026-01-05", "INTEREST CHARGE", -4_500, "visa"), t("2026-02-05", "INTEREST CHARGE", -4_300, "visa")],
            Currency::USD,
        )
    }

    fn offers() -> Vec<TransferOffer> {
        vec![TransferOffer {
            id: "o1".into(),
            institution: "newbank".into(),
            promo_apr: 0.0,
            promo_months: 12,
            transfer_fee_rate: 0.03,
            transfer_fee_min: None,
            go_to_apr: 0.2999,
            credit_limit: None,
            offer_expires: Some("2026-09-01".into()),
        }]
    }

    #[test]
    fn closing_the_line_is_the_advice_that_backfires_if_they_say_yes() {
        let p = two_cards();
        // Closing the visa removes a 500000 limit and moves NO balance: 380000 owed against the
        // 100000 that is left is 380%. That is why "I'll close it" is a threat you must not make.
        assert_eq!(utilisation_if_closed(&p, "visa"), Some(3.8));
        assert_eq!(utilisation_if_closed(&p, "store"), Some(0.76));
        // With only one line there is no remaining limit to divide by — ABSENT, not zero.
        assert_eq!(utilisation_if_closed(&pos(vec![acct("a", "a", 100, Some(0.1), Some(1_000), None)]), "a"), None);
    }

    #[test]
    fn being_able_to_pay_asks_for_a_rate_and_not_being_able_to_asks_for_hardship() {
        let p = two_cards();
        let f = fee_audit();
        let o = offers();
        let tenure = [("visa".to_string(), 48i64), ("store".to_string(), 6i64)];
        let can = prepare_negotiation(&NegotiationInput { fees: Some(&f), offers: &o, tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
        let cannot = prepare_negotiation(&NegotiationInput { fees: Some(&f), offers: &o, tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", false) });
        assert_eq!(can.iter().map(|c| c.ask.label()).collect::<Vec<_>>(), vec!["fee-waiver", "rate-reduction", "rate-reduction"]);
        assert_eq!(cannot.iter().map(|c| c.ask.label()).collect::<Vec<_>>(), vec!["fee-waiver", "hardship-plan", "hardship-plan"]);
        // Asking for a rate cut when you cannot pay wastes the one call you get, so it is not
        // offered AND the reason is said in the same breath.
        assert!(cannot[1].do_not_say.iter().any(|d| d.contains("do not ask for a rate reduction in the same call")));
        assert!(cannot[1].urgency.as_ref().unwrap().contains("CALL BEFORE A PAYMENT IS MISSED"));
    }

    #[test]
    fn the_cheapest_win_goes_first_because_it_does_not_spend_the_goodwill() {
        let p = two_cards();
        let f = fee_audit();
        let cases = prepare_negotiation(&NegotiationInput { fees: Some(&f), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert_eq!(cases[0].ask, Ask::FeeWaiver);
        assert_eq!(cases[0].annual_value_if_won.minor, 3_500);
        assert!(cases[0].urgency.as_ref().unwrap().contains("harder every statement that passes"));
        // Then by what the ask is worth: visa 15000 before store 4000.
        assert_eq!(cases.iter().skip(1).map(|c| c.annual_value_if_won.minor).collect::<Vec<_>>(), vec![15_000, 4_000]);
    }

    #[test]
    fn an_interest_row_is_not_a_waiver_candidate_and_an_old_fee_is_not_recent() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), Some(500_000), None)]);
        // Interest is excluded by KIND — it is the cost of the balance, not a fee to reverse.
        let interest_only = audit_fees(&[t("2026-05-20", "INTEREST CHARGE", -4_500, "visa")], Currency::USD);
        let a = prepare_negotiation(&NegotiationInput { fees: Some(&interest_only), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(a.iter().all(|c| c.ask != Ask::FeeWaiver));
        // And a fee outside the window is not a live candidate either.
        let old = audit_fees(&[t("2025-05-20", "LATE FEE", -3_500, "visa")], Currency::USD);
        let b = prepare_negotiation(&NegotiationInput { fees: Some(&old), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(b.iter().all(|c| c.ask != Ask::FeeWaiver));
        // A fee dated in the FUTURE is not one either — days_between would be negative.
        let future = audit_fees(&[t("2026-12-20", "LATE FEE", -3_500, "visa")], Currency::USD);
        let c = prepare_negotiation(&NegotiationInput { fees: Some(&future), ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(c.iter().all(|x| x.ask != Ask::FeeWaiver));
    }

    #[test]
    fn absent_evidence_is_absent_and_the_call_is_still_worth_making() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        let cases = prepare_negotiation(&NegotiationInput::new(&p, "2026-06-30", true));
        assert_eq!(cases.len(), 1);
        // NO invented leverage. A case that fabricates evidence produces somebody confidently
        // saying something an issuer can disprove from their own screen.
        assert!(cases[0].evidence.is_empty());
        assert!(cases[0].why.contains("this is a plain ask rather than a case"));
        // And the reason to call anyway is still stated — a case with no evidence must not read as
        // a case not worth making.
        assert!(cases[0].why.contains("The call still costs nothing"));
        assert_eq!(cases[0].annual_value_if_won.minor, 15_000, "5% of 300000, the target reduction");
    }

    #[test]
    fn a_clean_payment_history_is_the_strongest_card_and_people_forget_they_hold_it() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), Some(500_000), Some(0.2))]);
        let f = audit_fees(&[t("2026-01-05", "INTEREST CHARGE", -4_500, "visa")], Currency::USD);
        let tenure = [("visa".to_string(), 48i64)];
        let cases = prepare_negotiation(&NegotiationInput { fees: Some(&f), tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
        let claims: Vec<(&str, &str)> = cases[0].evidence.iter().map(|e| (e.strength.label(), e.claim.as_str())).collect();
        assert_eq!(claims.len(), 4);
        assert_eq!(claims[1], ("strong", "no late or returned-payment fee appears anywhere in the statements held"));
        assert!(claims[2].1.contains("4500 minor units of interest have been paid"), "their own number");
        assert_eq!(claims[3].0, "moderate", "20% used is a low-risk customer");
        assert!(cases[0].why.starts_with("3 piece(s) of strong evidence"));
    }

    #[test]
    fn under_a_year_is_a_trial_period_rather_than_tenure() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        for (months, want) in [(48i64, "strong"), (12, "moderate"), (11, "weak"), (6, "weak")] {
            let tenure = [("visa".to_string(), months)];
            let cases = prepare_negotiation(&NegotiationInput { tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
            assert_eq!(cases[0].evidence[0].strength.label(), want, "{months} months");
        }
    }

    #[test]
    fn only_an_offer_you_could_actually_take_counts_as_leverage() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        // An offer from the SAME institution is not leverage against that institution.
        let same = vec![TransferOffer { institution: "chase".into(), ..offers()[0].clone() }];
        let a = prepare_negotiation(&NegotiationInput { offers: &same, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(a[0].evidence.is_empty());
        // Nor is an offer at a WORSE rate than the one you already have.
        let worse = vec![TransferOffer { promo_apr: 0.30, ..offers()[0].clone() }];
        let b = prepare_negotiation(&NegotiationInput { offers: &worse, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert!(b[0].evidence.is_empty());
        // A real, better one is — and it is named with its expiry so it can be checked first.
        let o = offers();
        let c = prepare_negotiation(&NegotiationInput { offers: &o, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert_eq!(c[0].evidence[0].claim, "newbank is offering 0% for 12 months, expiring 2026-09-01");
        assert!(c[0].evidence[0].source.contains("name it only if it is real and you would take it"));
    }

    #[test]
    fn the_hardship_value_is_capped_because_nobody_is_offered_a_zero_rate() {
        let p = pos(vec![acct("visa", "chase", 300_000, Some(0.2299), None, None)]);
        let cases = prepare_negotiation(&NegotiationInput::new(&p, "2026-06-30", false));
        // min(apr, 0.15) of the balance — the arithmetic models a plausible outcome rather than the
        // whole rate going away.
        assert_eq!(cases[0].annual_value_if_won.minor, 45_000);
        // And a rate BELOW the cap is not inflated up to it.
        let low = pos(vec![acct("store", "storeco", 80_000, Some(0.0999), None, None)]);
        let c2 = prepare_negotiation(&NegotiationInput::new(&low, "2026-06-30", false));
        assert_eq!(c2[0].annual_value_if_won.minor, 7_992);
    }

    #[test]
    fn the_totals_and_the_call_script_come_out_in_the_order_to_use_them() {
        let p = two_cards();
        let f = fee_audit();
        let o = offers();
        let tenure = [("visa".to_string(), 48i64), ("store".to_string(), 6i64)];
        let cases = prepare_negotiation(&NegotiationInput { fees: Some(&f), offers: &o, tenure_months: &tenure, ..NegotiationInput::new(&p, "2026-06-30", true) });
        assert_eq!(total_if_every_ask_lands(&cases, Currency::USD).minor, 22_500, "CONTINGENT — if every one lands");
        let script = call_order(&cases);
        assert_eq!(script.len(), 3);
        assert!(script[0].starts_with("chase: \"I saw a fee on my last statement"));
        assert!(script[1].contains("I've been a customer a while"));
        assert!(script[2].starts_with("storeco:"));
    }

    #[test]
    fn an_account_with_nothing_owed_has_nothing_to_negotiate() {
        let mut a = acct("visa", "chase", 0, Some(0.2299), Some(500_000), None);
        a.owed = None;
        assert!(prepare_negotiation(&NegotiationInput::new(&pos(vec![a]), "2026-06-30", true)).is_empty());
    }
}

//! The brief — every capability in this feature, folded into ONE ranked list of what to do.
//!
//! Twenty-five modules each produce their own answer and nothing composed them, so anything asked to
//! "use the finance system" had to re-derive the same synthesis every time. This is that synthesis,
//! once, as data.
//!
//! **It composes, it does not recompute.** Every input is another capability's OUTPUT. Nothing here
//! recalculates a runway or re-prices a transfer, because a second implementation of a number is a
//! second answer to the same question, and the two will disagree eventually.
//!
//! # Two tiers, because one ordering cannot hold both
//!
//! - **Do not miss** — things with a date. A minimum payment due Friday is not comparable to a
//!   $5,000 opportunity by any rate; it is comparable to a late fee and a credit event. Sorted by
//!   WHEN.
//! - **Best return** — everything else, sorted by what it is worth PER HOUR OF YOUR EFFORT. A $40
//!   fee waiver that takes a ten-minute phone call beats a $5,000 grant that takes eighty hours, and
//!   ranking by size alone gets that exactly backwards.
//!
//! **Absent is not zero**, and this is the discipline that makes the brief trustworthy. A capability
//! that was never run contributes NOTHING and is NAMED as missing. A brief reporting "$0 available
//! in fee waivers" when the fee audit never ran is a lie, and it is the specific lie that would make
//! somebody stop looking.
use crate::money::{money, Currency, Money};
use crate::negotiate::{Ask, NegotiationCase};
use crate::obligations::{add_days, due_between, Confidence, ObligationCalendar, ObligationKind};
use crate::opportunity::{Assessment, Verdict};
use crate::position::Position;
use crate::priority::Priority;
use crate::runway::{survives_horizon, Runway};
use crate::transfer::TransferAssessment;
use crate::viable::ViableIncome;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    DoNotMiss,
    BestReturn,
    Blocked,
}

impl Tier {
    pub fn label(self) -> &'static str {
        match self {
            Tier::DoNotMiss => "do-not-miss",
            Tier::BestReturn => "best-return",
            Tier::Blocked => "blocked",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Action {
    pub id: String,
    pub title: String,
    /// Which capability produced it, so a figure can be traced back and checked.
    pub source: &'static str,
    pub tier: Tier,
    /// `YYYY-MM-DD`, for anything with a date.
    pub by: Option<String>,
    pub worth: Option<Money>,
    /// What the worth MEANS — a year of interest, a one-off, an expectation. Without this the number
    /// is not comparable to the one under it.
    pub worth_basis: Option<&'static str>,
    pub effort_hours: Option<f64>,
    /// `worth ÷ effort`. ABSENT when either is, and it sorts LAST rather than as zero.
    pub per_hour: Option<Money>,
    pub why: String,
    /// True when this rests on something incomplete or unchecked.
    pub provisional: bool,
    pub blocked_by: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Brief {
    pub as_of: String,
    pub currency: Currency,
    /// Where you stand, in one sentence.
    pub headline: String,
    pub do_not_miss: Vec<Action>,
    pub best_return: Vec<Action>,
    pub blocked: Vec<Action>,
    /// Capabilities that produced nothing, BY NAME — the difference between "nothing to do" and
    /// "nothing looked".
    pub absent: Vec<String>,
    /// What every figure above is standing on.
    pub caveats: Vec<String>,
}

#[derive(Default)]
pub struct BriefInput<'a> {
    /// `YYYY-MM-DD`. Passed in, never a clock.
    pub as_of: &'a str,
    pub currency: Option<Currency>,
    pub position: Option<&'a Position>,
    pub runway: Option<&'a Runway>,
    pub viable: Option<&'a ViableIncome>,
    pub priority: Option<&'a Priority>,
    pub negotiation: Option<&'a [NegotiationCase]>,
    pub transfers: Option<&'a [TransferAssessment]>,
    pub opportunities: Option<&'a [Assessment]>,
    pub calendar: Option<&'a ObligationCalendar>,
    /// How far ahead a dated obligation counts as urgent.
    pub horizon_days: i64,
    /// Effort defaults, NAMED rather than buried, because they drive the whole ranking.
    pub call_hours: f64,
    pub transfer_hours: f64,
}

impl<'a> BriefInput<'a> {
    pub fn new(as_of: &'a str, currency: Currency) -> Self {
        BriefInput { as_of, currency: Some(currency), horizon_days: 30, call_hours: 0.5, transfer_hours: 1.0, ..Default::default() }
    }

    fn cur(&self) -> Currency {
        self.currency.unwrap_or(Currency::USD)
    }
}

/// `worth ÷ effort`, or NONE — never zero, which would sort a priceless thing among the worthless.
fn per_hour_of(worth: Option<Money>, hours: f64, currency: Currency) -> Option<Money> {
    let w = worth?;
    if hours <= 0.0 {
        return None;
    }
    Some(money((w.minor as f64 / hours).round() as i64, currency))
}

pub fn build_brief(input: &BriefInput) -> Brief {
    let currency = input.cur();
    let mut actions: Vec<Action> = Vec::new();
    let mut absent: Vec<String> = Vec::new();
    let mut caveats: Vec<String> = Vec::new();

    // PROVISIONAL propagates from the bottom. Everything derived from an incomplete position or an
    // unverified ledger is itself provisional, and saying so once at the top is not enough — the
    // reader acts on individual LINES.
    let unverified = input.position.map(|p| p.provenance.starts_with("UNVERIFIED")).unwrap_or(false);
    let provisional = input.position.is_none_or(|p| !p.complete) || unverified;
    if unverified {
        caveats.push(format!("the ledger under this was never reconciled: {}", input.position.map(|p| p.provenance.as_str()).unwrap_or("")));
    }
    if let Some(p) = input.position {
        if !p.complete {
            caveats.push(format!("the position is incomplete — {} unresolved issue(s), so every figure below inherits them", p.problems.len()));
        }
    }

    // ── DO NOT MISS ──────────────────────────────────────────────────────────────────────────────
    match input.calendar {
        Some(cal) => {
            for o in due_between(cal, input.as_of, &add_days(input.as_of, input.horizon_days)) {
                let assumed = o.confidence == Confidence::Assumed;
                actions.push(Action {
                    id: format!("due:{}:{}:{}", o.account, o.date, o.label),
                    title: format!("{} — {} due", o.label, o.amount.minor),
                    source: "obligations",
                    tier: Tier::DoNotMiss,
                    by: Some(o.date.clone()),
                    worth: Some(o.amount),
                    worth_basis: Some("the amount due"),
                    // The assumed-date note applies to a MINIMUM too, and especially to one:
                    // `obligations` places an unknown due day on the 1st — the earliest it could
                    // plausibly fall — so the date is the conservative guess rather than a fact, and
                    // the one obligation that must not be late is where that matters most.
                    why: format!(
                        "{}{}",
                        if o.kind == ObligationKind::Minimum {
                            "a missed minimum is a late fee, a penalty rate on the whole balance, and a credit event that outlasts the month"
                        } else {
                            "a standing obligation"
                        },
                        if assumed { " — the DATE is assumed, not observed" } else { "" }
                    ),
                    provisional: provisional || assumed,
                    effort_hours: None,
                    per_hour: None,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("obligations — no calendar was built, so nothing here knows what is due".to_string()),
    }

    // ── BEST RETURN ──────────────────────────────────────────────────────────────────────────────
    match input.negotiation {
        Some(cases) => {
            // A hardship case is NOT a best-return item and is handled below as dated work — it has
            // to happen before a missed payment, and ranking it by expectation per hour would bury it.
            for c in cases.iter().filter(|x| x.ask != Ask::HardshipPlan) {
                let worth = c.annual_value_if_won;
                actions.push(Action {
                    id: format!("call:{}:{}", c.account, c.ask.label()),
                    title: format!("{} — ask for a {}", c.institution, c.ask.label().replace('-', " ")),
                    source: "negotiate",
                    tier: Tier::BestReturn,
                    by: None,
                    worth: Some(worth),
                    worth_basis: Some(if c.ask == Ask::FeeWaiver { "the fee, one-off" } else { "a year, if granted" }),
                    effort_hours: Some(input.call_hours),
                    per_hour: per_hour_of(Some(worth), input.call_hours, currency),
                    why: c.why.clone(),
                    provisional,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("negotiate — no call list was prepared".to_string()),
    }

    match input.transfers {
        Some(ts) => {
            for t in ts.iter().filter(|x| x.worth_it) {
                actions.push(Action {
                    id: format!("transfer:{}:{}", t.source_account, t.offer_id),
                    title: format!("move {} from {} to {}", t.moved.minor, t.source_account, t.institution),
                    source: "transfer",
                    tier: Tier::BestReturn,
                    by: None,
                    worth: Some(t.net_benefit),
                    worth_basis: Some("interest avoided over the promotion, less the fee"),
                    effort_hours: Some(input.transfer_hours),
                    per_hour: per_hour_of(Some(t.net_benefit), input.transfer_hours, currency),
                    why: format!(
                        "{} of interest avoided against a {} fee — and the balance must be gone before the promotion ends",
                        t.interest_avoided.minor, t.fee.minor
                    ),
                    provisional,
                    blocked_by: None,
                });
            }
            if !ts.is_empty() && !ts.iter().any(|x| x.worth_it) {
                // A RESULT, not a gap — and the distinction is the whole point of the absent list.
                caveats.push(format!("{} transfer offer(s) were priced and NONE beat its fee — that is a result, not a gap", ts.len()));
            }
        }
        None => absent.push("transfer — no offers were priced".to_string()),
    }

    match input.opportunities {
        Some(os) => {
            for a in os.iter().filter(|x| x.verdict == Verdict::Biddable && x.beats_contracting) {
                actions.push(Action {
                    id: format!("bid:{}", a.opportunity.id),
                    title: format!("bid: {}", a.opportunity.title),
                    source: "opportunity",
                    tier: Tier::BestReturn,
                    by: Some(a.opportunity.closes.clone()),
                    worth: a.expected,
                    worth_basis: Some("expectation — award × hit rate, not revenue"),
                    effort_hours: Some(a.opportunity.bid_hours),
                    per_hour: a.per_hour,
                    why: format!("beats billing the same {}h", a.opportunity.bid_hours),
                    provisional,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("opportunity — no funding sources were scanned".to_string()),
    }

    match input.priority {
        Some(p) => {
            if let Some(target) = &p.target {
                if p.to_debt.minor > 0 {
                    actions.push(Action {
                        id: format!("pay:{}", target.account),
                        title: format!("put {} above the minimum into {}", p.to_debt.minor, target.institution),
                        source: "priority",
                        tier: Tier::BestReturn,
                        by: None,
                        worth: Some(p.to_debt),
                        worth_basis: Some("the payment itself — the return is the rate it stops accruing"),
                        effort_hours: None,
                        per_hour: None,
                        why: target.why.clone(),
                        provisional,
                        blocked_by: None,
                    });
                }
            }
            if p.to_buffer.minor != 0 {
                actions.push(Action {
                    id: "buffer".to_string(),
                    title: format!("put {} into the emergency buffer", p.to_buffer.minor),
                    source: "priority",
                    tier: Tier::BestReturn,
                    by: None,
                    worth: Some(p.to_buffer),
                    worth_basis: Some("the amount set aside"),
                    effort_hours: None,
                    per_hour: None,
                    why: "a buffer beats the rate until it exists — without one the next unplanned bill goes back onto the highest-rate card".to_string(),
                    provisional,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("priority — nothing decided where this month's spare money goes".to_string()),
    }

    // ── BLOCKED ──────────────────────────────────────────────────────────────────────────────────
    if let Some(cases) = input.negotiation {
        for c in cases.iter().filter(|x| x.ask == Ask::HardshipPlan) {
            // Not blocked in the sense of impossible — DATED, in the sense that it must happen
            // before something else, and the something else is a missed payment.
            actions.push(Action {
                id: format!("hardship:{}", c.account),
                title: format!("{} — hardship arrangement, BEFORE a payment is missed", c.institution),
                source: "negotiate",
                tier: Tier::DoNotMiss,
                by: None,
                worth: Some(c.annual_value_if_won),
                worth_basis: Some("a year, if granted"),
                effort_hours: Some(input.call_hours),
                per_hour: per_hour_of(Some(c.annual_value_if_won), input.call_hours, currency),
                why: c.urgency.clone().unwrap_or_else(|| c.why.clone()),
                provisional,
                blocked_by: None,
            });
        }
    }
    if let Some(os) = input.opportunities {
        for a in os.iter().filter(|x| x.verdict == Verdict::Ineligible && !x.unmet.is_empty()) {
            actions.push(Action {
                id: format!("unblock:{}", a.opportunity.id),
                title: format!("cannot bid {}", a.opportunity.title),
                source: "opportunity",
                tier: Tier::Blocked,
                by: None,
                worth: None,
                worth_basis: None,
                effort_hours: None,
                per_hour: None,
                why: a.why.clone().unwrap_or_else(|| "ineligible".to_string()),
                provisional,
                blocked_by: Some(a.unmet.join(", ")),
            });
        }
    }

    let mut do_not_miss: Vec<Action> = actions.iter().filter(|a| a.tier == Tier::DoNotMiss).cloned().collect();
    // Undated work sorts LAST within the dated tier — "9999" is past every real date.
    do_not_miss.sort_by(|a, b| a.by.clone().unwrap_or_else(|| "9999".into()).cmp(&b.by.clone().unwrap_or_else(|| "9999".into())));

    let mut best_return: Vec<Action> = actions.iter().filter(|a| a.tier == Tier::BestReturn).cloned().collect();
    best_return.sort_by(|a, b| {
        let ph = |x: &Action| x.per_hour.map(|m| m.minor).unwrap_or(-1);
        let w = |x: &Action| x.worth.map(|m| m.minor).unwrap_or(-1);
        ph(b).cmp(&ph(a)).then_with(|| w(b).cmp(&w(a))).then_with(|| a.title.cmp(&b.title))
    });

    Brief {
        as_of: input.as_of.to_string(),
        currency,
        headline: headline_for(input, provisional),
        do_not_miss,
        best_return,
        blocked: actions.into_iter().filter(|a| a.tier == Tier::Blocked).collect(),
        absent,
        caveats,
    }
}

/// Where you stand, in one sentence.
///
/// The runway on the LOW band is the sentence when there is one, because it is the fact every other
/// decision bends around. With no runway it says so rather than reaching for a cheerier number.
pub fn headline_for(input: &BriefInput, provisional: bool) -> String {
    let mark = if provisional { " (PROVISIONAL — see the caveats)" } else { "" };

    if let Some(r) = input.runway {
        if !r.headline.months.is_empty() {
            if !survives_horizon(&r.headline) {
                return format!(
                    "the money runs out in {} on the LOW income band — {} whole month(s) of cover, and {} more per month would close it{mark}",
                    r.headline.exhausts_in.clone().unwrap_or_default(),
                    r.headline.months_of_cover.unwrap_or(0),
                    r.headline.monthly_gap.minor
                );
            }
            let tightest = r.headline.tightest.as_ref().map(|t| t.month.clone()).unwrap_or_default();
            return format!("on the LOW income band the money holds through {}, tightest at {tightest}{mark}", r.through.clone().unwrap_or_default());
        }
    }
    if let Some(v) = input.viable {
        return format!(
            "{} a month keeps everything current, measured on {} — the worst month, not the average{mark}",
            v.headline.worst_month.minor, v.headline.worst_month_name
        );
    }
    if let Some(p) = input.position {
        return format!("net worth {}, {} liquid, {} owed as of {}{mark}", p.net_worth.minor, p.liquid.minor, p.total_debt.minor, p.as_of);
    }
    "nothing has been computed yet — ingest a statement and the rest follows".to_string()
}

/// Everything the best-return list is worth if all of it lands. CONTINGENT by construction.
pub fn total_if_everything_lands(b: &Brief) -> Money {
    money(b.best_return.iter().map(|a| a.worth.map(|m| m.minor).unwrap_or(0)).sum(), b.currency)
}

/// Hours the best-return list actually asks for — the constraint people find out about late.
pub fn total_effort_hours(b: &Brief) -> f64 {
    b.best_return.iter().map(|a| a.effort_hours.unwrap_or(0.0)).sum()
}

/// The one thing to do next, or nothing. Dated work first, exactly as the tiers say.
pub fn next_action(b: &Brief) -> Option<&Action> {
    b.do_not_miss.first().or_else(|| b.best_return.first())
}

