//! Signal evaluation — and the machinery that makes a flattering answer hard to produce.
//!
//! `series` guards the DATA. This guards the CONCLUSION, and it exists because the dominant failure
//! in signal research is not a bad idea, it is an honest-looking measurement of a bad idea. Four
//! things produce a backtest that cannot be traded, and only the first is widely known:
//!
//! 1. **Look-ahead** — handled structurally: a signal is only ever handed
//!    [`series::bars_available_at`], so it cannot see the bar it is deciding on.
//! 2. **Costs** — a 2% edge traded fifty times a year against a 0.5% round trip is a LOSING
//!    strategy that backtests beautifully. So [`Costs`] is a required argument, exactly as
//!    `discretionary` is in `runway`, and the report shows gross and net side by side so the drag
//!    is visible rather than absorbed.
//! 3. **The benchmark** — a signal returning 8% on an instrument that returned 30% is a bad signal
//!    that looks good alone. Buy-and-hold on the SAME bars is computed every time and the verdict
//!    is relative to it.
//! 4. **Multiple testing** — this is the one that quietly ruins everything. Test two hundred signals
//!    against the same ten years and the best will look excellent BY ARITHMETIC, not by skill. The
//!    number of trials is an input, and the bar a result must clear rises with it.
//!
//! **The harness must be able to say no.** A verdict that is always a number is the same failure as
//! a backtest that always looks good, so short histories, thin trade counts and results inside the
//! noise are REFUSALS rather than small numbers.
use crate::series::{bars_available_at, Bar, VerifiedSeries};

/// What trading costs, as a fraction of the notional actually traded.
///
/// Applied to the CHANGE in position, so holding is free and flipping long-to-short pays twice. That
/// is what makes turnover expensive in the report rather than merely mentioned in a comment.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Costs {
    /// One-way cost: commission plus half the spread plus expected slippage. 0.001 is 10bps.
    pub per_turn: f64,
}

impl Costs {
    /// A deliberately UNFLATTERING default for a retail account on liquid daily bars.
    ///
    /// Not a promise about your broker — a starting point that errs toward pessimism, because a
    /// backtest that assumes free trading is the most common way to be wrong on paper and poor in
    /// practice.
    pub fn retail_daily() -> Costs {
        Costs { per_turn: 0.001 }
    }

    pub fn free() -> Costs {
        Costs { per_turn: 0.0 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct EvalOptions {
    /// REQUIRED. There is no default, for the same reason `runway` has none for discretionary
    /// spending: a zero assumed silently is the flattering kind of wrong.
    pub costs: Costs,
    /// The fraction of the history used to FIND the result. The remainder judges it.
    pub in_sample_fraction: f64,
    /// Below this the history is too short to say anything, and the verdict is a refusal.
    pub min_bars: usize,
    /// Below this there are too few decisions for the result to be about the signal rather than
    /// about two lucky months.
    pub min_trades: usize,
    /// HOW MANY SIGNALS WERE TESTED against this data, including this one.
    ///
    /// The bar a result must clear rises with it, because the best of N random signals looks good
    /// by arithmetic. Passing 1 while having tried forty is how a backtest lies to its author.
    pub trials: usize,
    /// Bars in a year. 252 for daily equities.
    pub periods_per_year: f64,
}

impl Default for EvalOptions {
    fn default() -> Self {
        EvalOptions { costs: Costs::retail_daily(), in_sample_fraction: 0.7, min_bars: 250, min_trades: 20, trials: 1, periods_per_year: 252.0 }
    }
}

/// What a signal wants to hold, given only what it could have known.
///
/// `-1.0` fully short, `0.0` flat, `1.0` fully long. Fractions are allowed and are how a
/// conviction-weighted or risk-scaled signal expresses itself.
pub trait Signal {
    fn name(&self) -> &str;

    /// The position to hold over the NEXT bar.
    ///
    /// `history` is every bar STRICTLY BEFORE the one being decided, so reading the future is not
    /// something an implementer has to remember to avoid — it is not on offer.
    fn position(&self, history: &[Bar]) -> f64;
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Stats {
    pub periods: usize,
    /// Compounded return over the window, as a fraction.
    pub total_return: f64,
    /// Annualised, geometric.
    pub cagr: f64,
    /// Annualised mean over annualised standard deviation. NONE when nothing varied.
    pub sharpe: Option<f64>,
    /// Worst peak-to-trough fall in the equity curve, as a POSITIVE fraction.
    pub max_drawdown: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    /// Beats buy-and-hold NET of costs, and holds up out of sample.
    Promising,
    /// Indistinguishable from luck once the number of signals tried is accounted for.
    InsideTheNoise,
    /// Real, and smaller than simply holding the thing.
    LosesToBuyAndHold,
    /// Gross of costs it works; net of them it does not.
    EatenByCosts,
    /// Not enough to say anything. The honest answer, and a common one.
    Refused,
}

impl Verdict {
    pub fn label(self) -> &'static str {
        match self {
            Verdict::Promising => "promising",
            Verdict::InsideTheNoise => "inside-the-noise",
            Verdict::LosesToBuyAndHold => "loses-to-buy-and-hold",
            Verdict::EatenByCosts => "eaten-by-costs",
            Verdict::Refused => "refused",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Evaluation {
    pub signal: String,
    pub symbol: String,
    pub verdict: Verdict,
    /// Why, in one sentence a person can act on.
    pub why: String,
    /// NET of costs, over the whole history.
    pub net: Option<Stats>,
    /// GROSS, so the cost drag is visible rather than absorbed into one number.
    pub gross: Option<Stats>,
    /// Buy-and-hold over exactly the same bars.
    pub benchmark: Option<Stats>,
    /// The half the result was found on, and the half that judges it.
    pub in_sample: Option<Stats>,
    pub out_of_sample: Option<Stats>,
    /// How much of the gross return the costs took, as a fraction of notional.
    pub cost_drag: f64,
    /// Position changes. A signal with four of them has not been measured, it has been anecdoted.
    pub trades: usize,
    /// Sum of |position change| — what the strategy actually asks you to trade.
    pub turnover: f64,
    /// The t-statistic of the mean net period return.
    pub t_stat: Option<f64>,
    /// The t a result must beat GIVEN how many signals were tried.
    pub t_required: f64,
    /// Everything this rests on.
    pub caveats: Vec<String>,
}

/// The bar a t-statistic must clear, given how many signals were tested.
///
/// The expected maximum of `n` draws from a standard normal grows like `sqrt(2 ln n)`. That is the
/// whole argument: with forty signals tried, a t of 2 is what the BEST one looks like when none of
/// them work. This is a screen and not a proof — it assumes independent trials and normal returns,
/// and market returns are neither — but it is enormously better than comparing against zero, which
/// is what a backtest with no trial count is doing.
pub fn t_required_for(trials: usize) -> f64 {
    let n = trials.max(1) as f64;
    // At one trial the conventional two-sided 5% bar; above it, whichever is larger.
    (2.0 * n.ln()).sqrt().max(1.96)
}

fn stats_of(returns: &[f64], periods_per_year: f64) -> Stats {
    let n = returns.len();
    if n == 0 {
        return Stats { periods: 0, total_return: 0.0, cagr: 0.0, sharpe: None, max_drawdown: 0.0 };
    }
    let mut equity = 1.0_f64;
    let mut peak = 1.0_f64;
    let mut max_dd = 0.0_f64;
    for r in returns {
        equity *= 1.0 + r;
        peak = peak.max(equity);
        if peak > 0.0 {
            max_dd = max_dd.max((peak - equity) / peak);
        }
    }
    let total_return = equity - 1.0;
    let years = n as f64 / periods_per_year;
    let cagr = if years > 0.0 && equity > 0.0 { equity.powf(1.0 / years) - 1.0 } else { 0.0 };

    let mean = returns.iter().sum::<f64>() / n as f64;
    let var = if n > 1 { returns.iter().map(|r| (r - mean).powi(2)).sum::<f64>() / (n as f64 - 1.0) } else { 0.0 };
    let sd = var.sqrt();
    // ZERO VARIANCE IS NOT AN INFINITE SHARPE. It means nothing moved, which is a fact about the
    // data rather than a perfect strategy.
    let sharpe = if sd > 0.0 { Some(mean / sd * periods_per_year.sqrt()) } else { None };

    Stats { periods: n, total_return, cagr, sharpe, max_drawdown: max_dd }
}

fn refuse(signal: &str, symbol: &str, why: String, caveats: Vec<String>, t_required: f64) -> Evaluation {
    Evaluation {
        signal: signal.to_string(),
        symbol: symbol.to_string(),
        verdict: Verdict::Refused,
        why,
        net: None,
        gross: None,
        benchmark: None,
        in_sample: None,
        out_of_sample: None,
        cost_drag: 0.0,
        trades: 0,
        turnover: 0.0,
        t_stat: None,
        t_required,
        caveats,
    }
}

/// Run one signal over one series and say what it is worth.
///
/// # Execution, stated because it decides the answer
///
/// The position for a bar is chosen from every bar STRICTLY BEFORE it, then executed at that bar's
/// OPEN and held to the next open. That is a decision made on last night's close and acted on this
/// morning, which is a thing a person can actually do. Deciding on a close and earning that same
/// close is the standard flattering mistake and it is not reachable from here.
pub fn evaluate(series: &VerifiedSeries, signal: &dyn Signal, opts: &EvalOptions) -> Evaluation {
    let t_required = t_required_for(opts.trials);
    let symbol = series.meta().symbol.clone();
    let mut caveats: Vec<String> = Vec::new();
    if series.unverified() {
        caveats.push(format!("the series was never checked: {}", series.caveat().unwrap_or("no reason given")));
    }
    if opts.costs.per_turn <= 0.0 {
        caveats.push("costs were given as ZERO — this measures a market nobody trades in, and the net figures below are gross ones wearing a different name".to_string());
    }
    if opts.trials <= 1 {
        caveats.push("one trial was declared, so the bar below is the conventional single-test one — if this is the best of several signals you tried, that bar is too low and the verdict is too generous".to_string());
    }

    let bars = series.bars();
    if bars.len() < opts.min_bars {
        return refuse(
            signal.name(),
            &symbol,
            format!("{} bar(s) of history against a {} minimum — too short to distinguish a signal from a run of luck", bars.len(), opts.min_bars),
            caveats,
            t_required,
        );
    }

    // One decision per bar that has both an entry and an exit price: positions are taken at open[i]
    // and closed at open[i+1], so the last bar has no return to earn.
    let mut gross: Vec<f64> = Vec::new();
    let mut net: Vec<f64> = Vec::new();
    let mut bench: Vec<f64> = Vec::new();
    let mut turnover = 0.0_f64;
    let mut trades = 0usize;
    let mut held = 0.0_f64;

    for i in 0..bars.len().saturating_sub(1) {
        let date = bars[i].date();
        // THE STRUCTURAL GUARD. The signal cannot see bars[i] — only what closed before it.
        let history = bars_available_at(series, date);
        let want = signal.position(history).clamp(-1.0, 1.0);

        let entry = bars[i].open.minor;
        let exit = bars[i + 1].open.minor;
        if entry <= 0 {
            continue;
        }
        let r = (exit - entry) as f64 / entry as f64;

        let change = (want - held).abs();
        if change > f64::EPSILON {
            trades += 1;
            turnover += change;
        }
        let cost = change * opts.costs.per_turn;
        gross.push(want * r);
        net.push(want * r - cost);
        bench.push(r);
        held = want;
    }

    if trades < opts.min_trades {
        return refuse(
            signal.name(),
            &symbol,
            format!("{trades} position change(s) against a {} minimum — too few decisions for this to be a measurement of the signal rather than of two lucky months", opts.min_trades),
            caveats,
            t_required,
        );
    }

    let net_stats = stats_of(&net, opts.periods_per_year);
    let gross_stats = stats_of(&gross, opts.periods_per_year);
    let bench_stats = stats_of(&bench, opts.periods_per_year);

    let split = ((net.len() as f64) * opts.in_sample_fraction).round() as usize;
    let in_sample = stats_of(&net[..split.min(net.len())], opts.periods_per_year);
    let out_of_sample = stats_of(&net[split.min(net.len())..], opts.periods_per_year);

    let n = net.len() as f64;
    let mean = net.iter().sum::<f64>() / n;
    let sd = (net.iter().map(|r| (r - mean).powi(2)).sum::<f64>() / (n - 1.0).max(1.0)).sqrt();
    let t_stat = if sd > 0.0 { Some(mean / (sd / n.sqrt())) } else { None };

    let cost_drag = gross_stats.total_return - net_stats.total_return;

    // THE LADDER, in the order that matters. Each rung answers a different question, and answering
    // them in the wrong order is how a result gets talked up: something inside the noise is not
    // "slightly worse than buy-and-hold", it is nothing at all.
    let (verdict, why) = if t_stat.is_none_or(|t| t.abs() <= t_required) {
        // Two true things, and saying only the first leaves the more actionable one unsaid: the
        // t-test says the returns cannot be told from zero, and the comparison says whether it also
        // did worse than doing nothing. A reader deserves both.
        let also = if net_stats.total_return <= bench_stats.total_return {
            format!(" — and it returned {:.1}% against {:.1}% for simply holding, so it is not a near miss", net_stats.total_return * 100.0, bench_stats.total_return * 100.0)
        } else {
            String::new()
        };
        (
            Verdict::InsideTheNoise,
            format!(
                "t = {:.2} against a bar of {t_required:.2} for {} trial(s) — this is what the best of that many random signals looks like, so there is nothing here to act on{also}",
                t_stat.unwrap_or(0.0),
                opts.trials
            ),
        )
    } else if gross_stats.total_return > bench_stats.total_return && net_stats.total_return <= bench_stats.total_return {
        (
            Verdict::EatenByCosts,
            format!(
                "gross it beats holding by {:.1}%, net it does not — {:.1}% of return went to costs across {:.1} turns of the book",
                (gross_stats.total_return - bench_stats.total_return) * 100.0,
                cost_drag * 100.0,
                turnover
            ),
        )
    } else if net_stats.total_return <= bench_stats.total_return {
        (
            Verdict::LosesToBuyAndHold,
            format!(
                "net {:.1}% against {:.1}% for simply holding it — the signal is real and it is not worth the work",
                net_stats.total_return * 100.0,
                bench_stats.total_return * 100.0
            ),
        )
    } else if out_of_sample.total_return <= 0.0 {
        (
            Verdict::InsideTheNoise,
            format!(
                "it beats holding in sample and returns {:.1}% out of sample — a result that does not survive the half it was not fitted on is a description of the past",
                out_of_sample.total_return * 100.0
            ),
        )
    } else {
        (
            Verdict::Promising,
            format!(
                "net {:.1}% against {:.1}% for holding, and {:.1}% out of sample — worth more data, NOT worth money yet",
                net_stats.total_return * 100.0,
                bench_stats.total_return * 100.0,
                out_of_sample.total_return * 100.0
            ),
        )
    };

    Evaluation {
        signal: signal.name().to_string(),
        symbol,
        verdict,
        why,
        net: Some(net_stats),
        gross: Some(gross_stats),
        benchmark: Some(bench_stats),
        in_sample: Some(in_sample),
        out_of_sample: Some(out_of_sample),
        cost_drag,
        trades,
        turnover,
        t_stat,
        t_required,
        caveats,
    }
}

/// Run several signals over one series, with the trial count set to how many were actually run.
///
/// This is the ONLY honest way to test a batch: the bar rises with the number of attempts, so a
/// sweep cannot quietly grade itself against a single-test threshold. Best first, refusals last.
pub fn evaluate_all(series: &VerifiedSeries, signals: &[&dyn Signal], opts: &EvalOptions) -> Vec<Evaluation> {
    let with_trials = EvalOptions { trials: signals.len().max(opts.trials), ..*opts };
    let mut out: Vec<Evaluation> = signals.iter().map(|s| evaluate(series, *s, &with_trials)).collect();
    out.sort_by(|a, b| {
        let rank = |v: Verdict| match v {
            Verdict::Promising => 0,
            Verdict::EatenByCosts => 1,
            Verdict::LosesToBuyAndHold => 2,
            Verdict::InsideTheNoise => 3,
            Verdict::Refused => 4,
        };
        rank(a.verdict).cmp(&rank(b.verdict)).then_with(|| {
            b.net.map(|s| s.total_return).unwrap_or(f64::MIN).partial_cmp(&a.net.map(|s| s.total_return).unwrap_or(f64::MIN)).unwrap_or(std::cmp::Ordering::Equal)
        })
    });
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::series::{check_series, unverified_series, BarDate, CheckOptions, SeriesMeta};

    // SYNTHETIC FIXTURES ONLY — every price here is generated, none is market data.
    /// A real weekday calendar, walked with the same date arithmetic the rest of the crate uses.
    ///
    /// My first attempt computed the month arithmetically and overflowed past ~150 bars into dates
    /// like `2026-06-554`, which `BarDate` then truncated — so the series stopped being sorted and
    /// `bars_available_at`'s binary search returned nonsense. Three tests failed and NONE of them
    /// was the harness's fault. Generating dates properly is cheaper than debugging that twice.
    fn weekdays(n: usize) -> Vec<String> {
        let mut out = Vec::with_capacity(n);
        let mut d = "2026-01-05".to_string(); // a Monday
        while out.len() < n {
            if !crate::series::is_weekend(&d) {
                out.push(d.clone());
            }
            d = crate::obligations::add_days(&d, 1);
        }
        out
    }

    fn bar_on(date: &str, open: i64, close: i64) -> Bar {
        Bar {
            date_i: BarDate::new(date),
            open: usd(open),
            high: usd(open.max(close) + 1),
            low: usd(open.min(close) - 1),
            close: usd(close),
            volume: None,
        }
    }

    /// A deterministic pseudo-random walk. No `rand` dependency, and the same series every run.
    fn walk(n: usize, drift: f64) -> Vec<Bar> {
        let dates = weekdays(n);
        let mut px = 10_000.0_f64;
        let mut seed = 12_345u64;
        let mut out = Vec::new();
        for date in dates.iter().take(n) {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
            // `seed >> 33` is 31 bits, so dividing by 2^31 gives 0..1 — and subtracting one gave
            // -1..0, a "random walk" that only ever fell. Every signal that needs an up bar then
            // did nothing, and the tests were green over a fixture that tested nothing.
            let u = ((seed >> 33) as f64 / (1u64 << 31) as f64) * 2.0 - 1.0; // -1..1
            let open = px;
            px *= 1.0 + drift + u * 0.02;
            out.push(bar_on(date, open.round() as i64, px.round() as i64));
        }
        out
    }

    fn series_of(bars: &[Bar]) -> VerifiedSeries {
        unverified_series(bars, SeriesMeta::new("SYNTH", "generated"), "a synthetic fixture, not market data").expect("a caveat")
    }

    struct AlwaysLong;
    impl Signal for AlwaysLong {
        fn name(&self) -> &str {
            "always-long"
        }
        fn position(&self, _h: &[Bar]) -> f64 {
            1.0
        }
    }

    /// Flips every bar — the pure turnover machine, for measuring what costs do.
    struct Alternating;
    impl Signal for Alternating {
        fn name(&self) -> &str {
            "alternating"
        }
        fn position(&self, h: &[Bar]) -> f64 {
            if h.len().is_multiple_of(2) { 1.0 } else { -1.0 }
        }
    }

    /// The one that cheats — it is handed only history, so it CANNOT.
    struct LastBarUp;
    impl Signal for LastBarUp {
        fn name(&self) -> &str {
            "last-bar-up"
        }
        fn position(&self, h: &[Bar]) -> f64 {
            match h.last() {
                Some(b) if b.close.minor > b.open.minor => 1.0,
                _ => 0.0,
            }
        }
    }

    #[test]
    fn the_fixture_walk_actually_walks_in_both_directions() {
        // It did not, once: the PRNG produced only negative draws and the series fell every single
        // bar. Every test needing an up bar then exercised nothing while staying green, which is
        // this repo's signature failure reproduced inside its own fixtures.
        let bars = walk(300, 0.0);
        let up = bars.iter().filter(|b| b.close.minor > b.open.minor).count();
        let down = bars.iter().filter(|b| b.close.minor < b.open.minor).count();
        assert!(up > 100, "only {up} up bars in 300");
        assert!(down > 100, "only {down} down bars in 300");
        // And the dates are sorted and real, because an unsorted series breaks the binary search
        // inside `bars_available_at` without saying so.
        assert!(bars.windows(2).all(|w| w[0].date() < w[1].date()));
        assert!(bars.iter().all(|b| !crate::series::is_weekend(b.date())));
    }

    #[test]
    fn a_signal_is_handed_only_what_closed_before_the_bar_it_decides() {
        // THE STRUCTURAL GUARD, asserted rather than trusted. The signal records the last date it
        // was shown; it must always be strictly before the bar being traded.
        use std::cell::RefCell;
        struct Spy(RefCell<Vec<String>>);
        impl Signal for Spy {
            fn name(&self) -> &str {
                "spy"
            }
            fn position(&self, h: &[Bar]) -> f64 {
                self.0.borrow_mut().push(h.last().map(|b| b.date().to_string()).unwrap_or_default());
                1.0
            }
        }
        let bars = walk(300, 0.0);
        let s = series_of(&bars);
        let spy = Spy(RefCell::new(Vec::new()));
        let _ = evaluate(&s, &spy, &EvalOptions { min_trades: 0, ..EvalOptions::default() });
        let seen = spy.0.borrow();
        for (i, last_seen) in seen.iter().enumerate() {
            assert!(last_seen.as_str() < bars[i].date(), "bar {i}: signal saw {last_seen}, deciding on {}", bars[i].date());
        }
        assert_eq!(seen[0], "", "the first decision has NO history at all, not one bar of it");
    }

    #[test]
    fn costs_are_charged_on_the_change_in_position_so_holding_is_free() {
        let bars = walk(300, 0.0005);
        let s = series_of(&bars);
        // Always-long changes position ONCE, at the start.
        let hold = evaluate(&s, &AlwaysLong, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(hold.trades, 1);
        assert!((hold.turnover - 1.0).abs() < 1e-9);
        assert!(hold.cost_drag < 0.002, "one turn at 10bps is a rounding error over 300 bars");

        // Alternating flips every bar: ~2.0 of turnover per bar, and the costs eat it alive.
        let flip = evaluate(&s, &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert!(flip.turnover > 500.0, "turnover was {}", flip.turnover);
        assert!(flip.cost_drag > hold.cost_drag * 100.0, "the same 10bps costs a hundred times more when you trade a hundred times more");
    }

    #[test]
    fn zero_costs_are_allowed_and_said_out_loud() {
        let bars = walk(300, 0.0);
        let s = series_of(&bars);
        let e = evaluate(&s, &Alternating, &EvalOptions { costs: Costs::free(), min_trades: 1, ..EvalOptions::default() });
        assert_eq!(e.cost_drag, 0.0);
        assert!(e.caveats.iter().any(|c| c.contains("measures a market nobody trades in")));
    }

    #[test]
    fn the_harness_can_say_yes_or_it_is_not_measuring_anything() {
        // A machine that always refuses is not conservative, it is broken — and it would be
        // indistinguishable from a correct one on every test above, all of which expect a no.
        // So: a series with REAL exploitable structure, and a signal that exploits it.
        //
        // The structure is genuine autocorrelation — the next bar continues the last one — which
        // does not exist in markets and is entirely the point. If a signal reading it cannot be
        // rated promising, nothing ever will be.
        let dates = weekdays(900);
        let mut bars = Vec::new();
        let mut px = 10_000.0_f64;
        let mut up = true;
        let mut seed = 4_242u64;
        for (i, d) in dates.iter().enumerate() {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
            // Flip direction only occasionally, so runs persist and the last bar predicts the next.
            if (seed >> 40).is_multiple_of(8) {
                up = !up;
            }
            let open = px;
            px *= if up { 1.004 } else { 0.996 };
            let _ = i;
            bars.push(bar_on(d, open.round() as i64, px.round() as i64));
        }
        let s = series_of(&bars);
        let e = evaluate(&s, &LastBarUp, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(e.verdict, Verdict::Promising, "why: {}", e.why);
        assert!(e.net.unwrap().total_return > e.benchmark.unwrap().total_return);
        assert!(e.out_of_sample.unwrap().total_return > 0.0, "and it survives the half it was not fitted on");
        assert!(e.t_stat.unwrap().abs() > e.t_required);
        // Even then it says what it is: worth more data, NOT worth money.
        assert!(e.why.contains("worth more data, NOT worth money yet"));
    }

    #[test]
    fn a_short_history_is_refused_rather_than_answered_quietly() {
        let bars = walk(40, 0.001);
        let e = evaluate(&series_of(&bars), &AlwaysLong, &EvalOptions::default());
        assert_eq!(e.verdict, Verdict::Refused);
        assert!(e.why.contains("too short to distinguish a signal from a run of luck"));
        // A refusal carries NO numbers. Reporting a Sharpe over forty bars is the thing this exists
        // to prevent.
        assert!(e.net.is_none() && e.gross.is_none() && e.benchmark.is_none() && e.t_stat.is_none());
    }

    #[test]
    fn too_few_decisions_is_refused_because_it_measures_two_lucky_months() {
        let bars = walk(300, 0.001);
        // Always-long makes exactly one position change over the whole history.
        let e = evaluate(&series_of(&bars), &AlwaysLong, &EvalOptions::default());
        assert_eq!(e.verdict, Verdict::Refused);
        assert!(e.why.contains("1 position change(s) against a 20 minimum"));
    }

    #[test]
    fn the_bar_rises_with_the_number_of_signals_tried() {
        // The expected maximum of n standard normals grows like sqrt(2 ln n). With forty signals
        // tried, a t of 2 is what the BEST one looks like when none of them work.
        assert!((t_required_for(1) - 1.96).abs() < 1e-9, "one trial is the conventional bar");
        assert!((t_required_for(2) - 1.96).abs() < 1e-9, "and it does not fall below it");
        assert!(t_required_for(40) > 2.6, "got {}", t_required_for(40));
        assert!(t_required_for(200) > 3.2, "got {}", t_required_for(200));
        assert!(t_required_for(1_000) > t_required_for(200));
        assert!((t_required_for(0) - 1.96).abs() < 1e-9, "zero trials cannot lower the bar");
    }

    #[test]
    fn a_sweep_grades_itself_against_the_number_of_signals_it_actually_ran() {
        let bars = walk(400, 0.0);
        let s = series_of(&bars);
        let sigs: Vec<&dyn Signal> = vec![&AlwaysLong, &Alternating, &LastBarUp];
        let out = evaluate_all(&s, &sigs, &EvalOptions { min_trades: 1, trials: 1, ..EvalOptions::default() });
        assert_eq!(out.len(), 3);
        // THE POINT: the caller said one trial, three were run, and the bar used is the one for
        // three. A sweep cannot quietly grade itself against a single-test threshold.
        assert!(out.iter().all(|e| (e.t_required - t_required_for(3)).abs() < 1e-9));
        // Refusals sort last, so the top of the list is never a thing that was not measured.
        let ranks: Vec<&str> = out.iter().map(|e| e.verdict.label()).collect();
        assert!(ranks.iter().position(|v| *v == "refused").unwrap_or(99) >= ranks.len() - 1 || !ranks.contains(&"refused"));
    }

    #[test]
    fn noise_is_called_noise_rather_than_a_small_edge() {
        // A driftless random walk contains nothing. Whatever a signal scores on it is luck, and the
        // verdict has to say so rather than reporting a modest-looking return.
        let bars = walk(500, 0.0);
        let e = evaluate(&series_of(&bars), &LastBarUp, &EvalOptions { min_trades: 1, trials: 20, ..EvalOptions::default() });
        assert_eq!(e.verdict, Verdict::InsideTheNoise, "why: {}", e.why);
        assert!(e.why.contains("what the best of that many random signals looks like"));
        // The numbers are still reported — refusing to show them would stop anyone checking.
        assert!(e.net.is_some() && e.benchmark.is_some());
    }

    #[test]
    fn a_signal_that_only_works_in_sample_does_not_survive_the_other_half() {
        let bars = walk(600, 0.0);
        let s = series_of(&bars);
        let e = evaluate(&s, &LastBarUp, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        // In or out of sample, both halves are computed and reported separately — a single
        // whole-history number cannot show the difference, which is the difference that matters.
        assert!(e.in_sample.is_some() && e.out_of_sample.is_some());
        let (i, o) = (e.in_sample.unwrap(), e.out_of_sample.unwrap());
        assert_eq!(i.periods + o.periods, e.net.unwrap().periods, "every period is in exactly one half");
        assert!(i.periods > o.periods, "70/30 by default");
    }

    #[test]
    fn zero_variance_is_not_an_infinite_sharpe() {
        let flat: Vec<Bar> = weekdays(300).iter().map(|d| bar_on(d, 10_000, 10_000)).collect();
        let e = evaluate(&series_of(&flat), &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        // Nothing moved. That is a fact about the DATA, not a perfect strategy, and a Sharpe of
        // infinity is exactly the kind of number that would get acted on.
        assert!(e.benchmark.unwrap().sharpe.is_none());
        assert_eq!(e.benchmark.unwrap().total_return, 0.0);
    }

    #[test]
    fn an_unchecked_series_carries_its_caveat_into_the_result() {
        let bars = walk(300, 0.001);
        let e = evaluate(&series_of(&bars), &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert!(e.caveats.iter().any(|c| c.contains("the series was never checked")));
        // And a CHECKED one does not.
        let checked = check_series(&bars, SeriesMeta::new("SYNTH", "generated"), &CheckOptions { holidays: &[], stale_run: 500, split_move: 10.0 }).series;
        if let Some(cs) = checked {
            let e2 = evaluate(&cs, &Alternating, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
            assert!(!e2.caveats.iter().any(|c| c.contains("never checked")));
        }
    }

    #[test]
    fn the_drawdown_is_the_worst_fall_from_a_peak_and_not_the_worst_period() {
        // Down 10%, up 5%, down 10% — the worst single period is 10%, the worst peak-to-trough is
        // the compounding of both, and a strategy is lived through the second one.
        let s = stats_of(&[-0.10, 0.05, -0.10], 252.0);
        // 0.9 → 0.945 → 0.8505 against a peak of 1.0. Computed rather than eyeballed: my first
        // guess at this number was 0.1855 and it was simply wrong.
        assert!((s.max_drawdown - 0.1495).abs() < 1e-9, "got {}", s.max_drawdown);
        assert!(s.total_return < 0.0);
        // An empty window has nothing to fall from.
        assert_eq!(stats_of(&[], 252.0).max_drawdown, 0.0);
    }
}

//! A price series, and the gate everything derived has to pass through.
//!
//! This is `reconcile` for market data, and it exists for the same reason: arithmetic over a series
//! that is subtly wrong does not produce an error, it produces A BACKTEST THAT LOOKS GOOD. Every way
//! a price series lies is a way a strategy appears profitable, and none of them announce themselves.
//!
//! # The four that matter, in the order they cost you money
//!
//! 1. **Look-ahead.** Deciding a trade on a bar you could not have seen yet. Using today's CLOSE to
//!    choose today's entry is the single most common backtest bug and it is invisible, because the
//!    equity curve it produces is beautiful. [`bars_available_at`] is the whole answer: it hands back
//!    only bars STRICTLY BEFORE the decision date, so the wrong thing is awkward to write rather
//!    than merely discouraged.
//! 2. **Survivorship.** A universe of "the stocks that exist today" backtested over ten years has
//!    silently excluded everything that went to zero. The bias is enormous and invisible in the data
//!    — nothing in a series says what is missing from it. So it is DECLARED, never inferred, and a
//!    universe-level claim on a series that has not declared it is refused.
//! 3. **Corporate actions.** An unadjusted series shows a 2-for-1 split as a −50% day. A strategy
//!    that buys drops finds a great many of them.
//! 4. **Stale and missing bars.** A feed repeating its last value looks exactly like zero
//!    volatility, which is a wonderful thing to be short. A missing day is a hole a strategy steps
//!    over without noticing.
use crate::money::{money, Currency, Money};

/// One bar. Prices are integer MINOR UNITS at the series' declared scale — never floats.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bar {
    /// `YYYY-MM-DD`.
    pub date_i: BarDate,
    pub open: Money,
    pub high: Money,
    pub low: Money,
    pub close: Money,
    /// Share/contract count. ABSENT means the source did not carry it — not zero.
    pub volume: Option<i64>,
}

/// A `YYYY-MM-DD` held inline so a `Bar` stays `Copy`.
///
/// Ten ASCII bytes, which every ISO date is. A shorter string is padded and compares equal to what
/// it was, so nothing silently becomes a different date.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct BarDate([u8; 10]);

impl BarDate {
    pub fn new(s: &str) -> BarDate {
        let mut b = [b' '; 10];
        for (i, c) in s.bytes().take(10).enumerate() {
            b[i] = c;
        }
        BarDate(b)
    }

    pub fn as_str(&self) -> &str {
        std::str::from_utf8(&self.0).unwrap_or("??????????").trim_end()
    }
}

impl std::fmt::Display for BarDate {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl Bar {
    pub fn date(&self) -> &str {
        self.date_i.as_str()
    }
}

/// What the CALLER asserts about where the series came from. None of this is inferable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SeriesMeta {
    pub symbol: String,
    /// Split- and dividend-adjusted. NONE means nobody said, which is not the same as false.
    pub adjusted: Option<bool>,
    /// The universe this came from includes delisted names. NONE means nobody said.
    pub survivorship_free: Option<bool>,
    pub source: String,
    /// Minor units per whole unit of price — 100 for cents. DECLARED, because an option quoted in
    /// hundredths of a cent and an equity quoted in cents are both "integers".
    pub minor_per_unit: i64,
}

impl SeriesMeta {
    pub fn new(symbol: &str, source: &str) -> SeriesMeta {
        SeriesMeta { symbol: symbol.to_string(), adjusted: None, survivorship_free: None, source: source.to_string(), minor_per_unit: 100 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SeriesProblemKind {
    OutOfOrder,
    Duplicate,
    NonPositive,
    ImpossibleBar,
    Gap,
    Stale,
    ProbableCorporateAction,
}

impl SeriesProblemKind {
    pub fn label(self) -> &'static str {
        match self {
            SeriesProblemKind::OutOfOrder => "out-of-order",
            SeriesProblemKind::Duplicate => "duplicate",
            SeriesProblemKind::NonPositive => "non-positive",
            SeriesProblemKind::ImpossibleBar => "impossible-bar",
            SeriesProblemKind::Gap => "gap",
            SeriesProblemKind::Stale => "stale",
            SeriesProblemKind::ProbableCorporateAction => "probable-corporate-action",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SeriesProblem {
    pub kind: SeriesProblemKind,
    pub at: String,
    pub detail: String,
}

/// A series something has actually checked.
///
/// EVERY FIELD IS PRIVATE, so only [`check_series`] and the deliberately-named [`unverified_series`]
/// can produce one and a backtest asking for a `VerifiedSeries` cannot be handed a raw vector. The
/// same mechanism as `ReconciledLedger`, for the same reason — and in Rust a private field is a
/// strictly stronger brand than the TypeScript's phantom symbol, which a cast can forge.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VerifiedSeries {
    bars: Vec<Bar>,
    meta: SeriesMeta,
    unverified: bool,
    caveat: Option<String>,
}

impl VerifiedSeries {
    pub fn bars(&self) -> &[Bar] {
        &self.bars
    }

    pub fn meta(&self) -> &SeriesMeta {
        &self.meta
    }

    /// True when this came from [`unverified_series`] rather than a passing check.
    pub fn unverified(&self) -> bool {
        self.unverified
    }

    pub fn caveat(&self) -> Option<&str> {
        self.caveat.as_deref()
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SeriesCheck {
    pub ok: bool,
    pub series: Option<VerifiedSeries>,
    pub problems: Vec<SeriesProblem>,
}

pub struct CheckOptions<'a> {
    /// Trading days the market was closed. Without one, a holiday reads as a gap — the check SAYS SO
    /// rather than pretending it can tell them apart.
    pub holidays: &'a [String],
    /// Identical closes in a row before it is called stale.
    pub stale_run: usize,
    /// A single-day move at or beyond this, in an UNADJUSTED series, reads as a corporate action.
    pub split_move: f64,
}

impl Default for CheckOptions<'_> {
    fn default() -> Self {
        CheckOptions { holidays: &[], stale_run: 5, split_move: 0.4 }
    }
}

/// Saturday or Sunday.
///
/// PUBLIC because a synthetic calendar and the gap check must not be able to disagree about which
/// days a market is open — two definitions of a trading day is two answers to the same question.
pub fn is_weekend(iso: &str) -> bool {
    match crate::session::epoch_seconds(&format!("{iso}T00:00:00Z")) {
        // 1970-01-01 was a THURSDAY, so day 0 is index 4 in a Sunday-first week.
        Some(secs) => matches!((secs.div_euclid(86_400) + 4).rem_euclid(7), 0 | 6),
        None => false,
    }
}

fn next_day(iso: &str) -> String {
    crate::obligations::add_days(iso, 1)
}

/// Check a series, and mint a [`VerifiedSeries`] only if nothing is wrong with it.
pub fn check_series(bars: &[Bar], meta: SeriesMeta, opts: &CheckOptions) -> SeriesCheck {
    let mut problems: Vec<SeriesProblem> = Vec::new();

    for (i, b) in bars.iter().enumerate() {
        let prev = if i > 0 { Some(&bars[i - 1]) } else { None };

        if let Some(p) = prev {
            if b.date_i == p.date_i {
                problems.push(SeriesProblem { kind: SeriesProblemKind::Duplicate, at: b.date().to_string(), detail: "two bars share one date".to_string() });
            } else if b.date_i < p.date_i {
                problems.push(SeriesProblem { kind: SeriesProblemKind::OutOfOrder, at: b.date().to_string(), detail: format!("follows {}", p.date()) });
            }
        }

        if [b.open, b.high, b.low, b.close].iter().any(|p| p.minor <= 0) {
            // A zero or negative price is not a price. It is a parse failure or a padded row, and a
            // return computed across one is arbitrarily large.
            problems.push(SeriesProblem { kind: SeriesProblemKind::NonPositive, at: b.date().to_string(), detail: "a price is zero or negative".to_string() });
        } else if b.high.minor < b.low.minor || b.close.minor > b.high.minor || b.close.minor < b.low.minor || b.open.minor > b.high.minor || b.open.minor < b.low.minor {
            problems.push(SeriesProblem { kind: SeriesProblemKind::ImpossibleBar, at: b.date().to_string(), detail: "open/close outside high/low, or high below low".to_string() });
        }

        if let Some(p) = prev {
            if p.close.minor > 0 {
                let move_ = (b.close.minor - p.close.minor) as f64 / p.close.minor as f64;
                // A 2-for-1 split is −50%. In a series that says it is adjusted this is a real move;
                // in one that says it is not, it is almost certainly a corporate action, and a
                // strategy that buys drops will find a great many of them.
                if meta.adjusted == Some(false) && move_.abs() >= opts.split_move {
                    problems.push(SeriesProblem {
                        kind: SeriesProblemKind::ProbableCorporateAction,
                        at: b.date().to_string(),
                        detail: format!("{}% in one day in a series declared UNADJUSTED — a split or a distribution, not a return", (move_ * 100.0).round()),
                    });
                }
            }
            // A missing WEEKDAY. Without an exchange calendar this cannot tell a holiday from a
            // hole, and saying so is better than a silent false positive on every public holiday.
            let mut d = next_day(p.date());
            while d.as_str() < b.date() {
                if !is_weekend(&d) && !opts.holidays.contains(&d) {
                    problems.push(SeriesProblem {
                        kind: SeriesProblemKind::Gap,
                        at: d.clone(),
                        detail: "no bar on a weekday — a market holiday if a calendar says so, a hole in the data if not".to_string(),
                    });
                }
                let next = next_day(&d);
                if next == d {
                    break; // an unparseable date would otherwise spin here
                }
                d = next;
            }
        }
    }

    let mut run = 1usize;
    for i in 1..bars.len() {
        if bars[i].close.minor == bars[i - 1].close.minor {
            run += 1;
            // EXACTLY at the threshold, once — not on every identical close after it, which would
            // bury the finding under its own repetition.
            if run == opts.stale_run {
                problems.push(SeriesProblem {
                    kind: SeriesProblemKind::Stale,
                    at: bars[i].date().to_string(),
                    detail: format!("{} identical closes in a row — a dead feed and a genuinely flat market are indistinguishable here", opts.stale_run),
                });
            }
        } else {
            run = 1;
        }
    }

    let ok = problems.is_empty() && !bars.is_empty();
    SeriesCheck {
        series: if ok { Some(VerifiedSeries { bars: bars.to_vec(), meta, unverified: false, caveat: None }) } else { None },
        ok,
        problems,
    }
}

/// A series accepted WITHOUT the check, because refusing outright makes a system nobody uses.
///
/// Deliberately ugly: it demands a reason, marks the series, and its name is greppable — so "which
/// of these results rest on unchecked data?" has an answer.
pub fn unverified_series(bars: &[Bar], meta: SeriesMeta, caveat: &str) -> Result<VerifiedSeries, String> {
    if caveat.trim().is_empty() {
        return Err("an unverified series must say why it could not be checked".to_string());
    }
    Ok(VerifiedSeries { bars: bars.to_vec(), meta, unverified: true, caveat: Some(caveat.to_string()) })
}

/// THE LOOK-AHEAD GUARD, and the most important function here.
///
/// Everything you could have known when deciding on `date` — which is every bar STRICTLY BEFORE it.
/// Not up to and including: on the morning of a decision, that day's high, low and close do not
/// exist yet, and a backtest that reads them produces an equity curve that cannot be traded.
///
/// Written as the only supported way to slice a series for a decision, so the wrong thing takes
/// deliberate effort rather than merely being discouraged in a comment.
pub fn bars_available_at<'a>(s: &'a VerifiedSeries, date: &str) -> &'a [Bar] {
    let n = s.bars.partition_point(|b| b.date() < date);
    &s.bars[..n]
}

/// The most recent bar that existed BEFORE a decision date, if any.
pub fn last_bar_before<'a>(s: &'a VerifiedSeries, date: &str) -> Option<&'a Bar> {
    bars_available_at(s, date).last()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UniverseClaim {
    pub allowed: bool,
    pub why: String,
}

/// Whether a UNIVERSE-level claim may be made from this series.
///
/// "This strategy beats the index" is a claim about a universe, and it is meaningless on a series
/// that has not declared itself survivorship-free — the losers are missing and nothing in the data
/// says so. Single-instrument claims are unaffected.
pub fn may_make_universe_claim(s: &VerifiedSeries) -> UniverseClaim {
    match s.meta.survivorship_free {
        Some(true) => UniverseClaim { allowed: true, why: "the universe declares it includes delisted names".to_string() },
        Some(false) => UniverseClaim {
            allowed: false,
            why: "the universe EXCLUDES delisted names — every company that went to zero is missing, and no result computed across it is comparable to an index".to_string(),
        },
        None => UniverseClaim {
            allowed: false,
            why: "nobody declared whether this universe includes delisted names, and it cannot be inferred from the data — absent is not the same as false, and neither is safe to build a universe claim on".to_string(),
        },
    }
}

/// One line stating what a result rests on.
pub fn provenance(s: &VerifiedSeries) -> String {
    let adj = match s.meta.adjusted {
        Some(true) => "adjusted",
        Some(false) => "UNADJUSTED",
        None => "adjustment UNDECLARED",
    };
    let base = format!("{} · {} bar(s) · {adj} · {}", s.meta.symbol, s.bars.len(), s.meta.source);
    match &s.caveat {
        Some(c) if s.unverified => format!("UNVERIFIED — {c} · {base}"),
        _ => format!("checked · {base}"),
    }
}

/// Simple return between two bars, as a fraction. NONE where the base is not a price.
pub fn period_return(from: &Bar, to: &Bar) -> Option<f64> {
    if from.close.minor <= 0 {
        return None;
    }
    Some((to.close.minor - from.close.minor) as f64 / from.close.minor as f64)
}

/// Build a price at the series' declared scale, so a caller cannot silently mix scales.
pub fn price(units: f64, meta: &SeriesMeta, currency: Currency) -> Money {
    money((units * meta.minor_per_unit as f64).round() as i64, currency)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY — no real market data reaches this repo.
    fn bar(date: &str, o: i64, h: i64, l: i64, c: i64) -> Bar {
        Bar { date_i: BarDate::new(date), open: usd(o), high: usd(h), low: usd(l), close: usd(c), volume: None }
    }

    fn meta() -> SeriesMeta {
        SeriesMeta::new("ACME", "test")
    }

    fn clean() -> Vec<Bar> {
        vec![bar("2026-06-01", 1_000, 1_010, 990, 1_005), bar("2026-06-02", 1_005, 1_020, 1_000, 1_015), bar("2026-06-03", 1_015, 1_025, 1_010, 1_020)]
    }

    fn kinds(c: &SeriesCheck) -> Vec<(&'static str, &str)> {
        c.problems.iter().map(|p| (p.kind.label(), p.at.as_str())).collect()
    }

    #[test]
    fn the_look_ahead_guard_hands_back_only_what_existed_before_the_decision() {
        let s = check_series(&clean(), meta(), &CheckOptions::default()).series.expect("clean");
        // STRICTLY before. On the morning of the 2nd, the 2nd's close does not exist yet — and a
        // backtest that reads it produces an equity curve nobody could have traded.
        assert_eq!(bars_available_at(&s, "2026-06-02").iter().map(|b| b.date()).collect::<Vec<_>>(), vec!["2026-06-01"]);
        assert_eq!(bars_available_at(&s, "2026-06-03").iter().map(|b| b.date()).collect::<Vec<_>>(), vec!["2026-06-01", "2026-06-02"]);
        assert_eq!(last_bar_before(&s, "2026-06-03").map(|b| b.date()), Some("2026-06-02"));
        // Before the series starts there is nothing, which is ABSENT rather than the first bar.
        assert!(last_bar_before(&s, "2026-06-01").is_none());
        assert!(bars_available_at(&s, "2026-06-01").is_empty());
        // And a date past the end sees everything.
        assert_eq!(bars_available_at(&s, "2030-01-01").len(), 3);
    }

    #[test]
    fn a_raw_vector_cannot_become_a_verified_series() {
        // The fields are PRIVATE, so this module is the only place one is built. That is the whole
        // enforcement, and it is stronger than the TypeScript's phantom symbol, which a cast forges.
        let bad = vec![bar("2026-06-01", 1_000, 1_010, 990, 0)];
        let c = check_series(&bad, meta(), &CheckOptions::default());
        assert!(!c.ok);
        assert!(c.series.is_none(), "a failing check mints NOTHING");
    }

    #[test]
    fn each_way_a_series_lies_is_caught_and_named() {
        // Every row measured by running finance-series.ts.
        let d = CheckOptions::default();
        assert_eq!(kinds(&check_series(&[bar("2026-06-01", 1_000, 1_010, 990, 1_005), bar("2026-06-01", 1_005, 1_020, 1_000, 1_015)], meta(), &d)), vec![("duplicate", "2026-06-01")]);
        assert_eq!(kinds(&check_series(&[bar("2026-06-02", 1_000, 1_010, 990, 1_005), bar("2026-06-01", 1_005, 1_020, 1_000, 1_015)], meta(), &d)), vec![("out-of-order", "2026-06-01")]);
        assert_eq!(kinds(&check_series(&[bar("2026-06-01", 1_000, 1_010, 0, 1_005)], meta(), &d)), vec![("non-positive", "2026-06-01")]);
        assert_eq!(kinds(&check_series(&[bar("2026-06-01", 1_000, 900, 990, 1_005)], meta(), &d)), vec![("impossible-bar", "2026-06-01")]);
    }

    #[test]
    fn a_missing_weekday_is_a_gap_and_a_weekend_is_not() {
        let d = CheckOptions::default();
        let across = [bar("2026-06-01", 1_000, 1_010, 990, 1_000), bar("2026-06-04", 1_000, 1_010, 990, 1_000)];
        assert_eq!(kinds(&check_series(&across, meta(), &d)), vec![("gap", "2026-06-02"), ("gap", "2026-06-03")]);
        // Told which days the market was shut, it says nothing — it cannot tell a holiday from a
        // hole on its own, and it does not pretend to.
        let holidays = ["2026-06-02".to_string(), "2026-06-03".to_string()];
        assert!(check_series(&across, meta(), &CheckOptions { holidays: &holidays, ..CheckOptions::default() }).ok);
        // Friday to Monday is not a gap. 2026-06-05 IS a Friday and 2026-06-08 a Monday.
        let weekend = [bar("2026-06-05", 1_000, 1_010, 990, 1_000), bar("2026-06-08", 1_000, 1_010, 990, 1_000)];
        assert!(check_series(&weekend, meta(), &d).ok);
        assert!(is_weekend("2026-06-06") && is_weekend("2026-06-07"));
        assert!(!is_weekend("2026-06-05") && !is_weekend("2026-06-08"));
    }

    #[test]
    fn a_repeating_feed_is_reported_once_rather_than_on_every_identical_close() {
        let stale: Vec<Bar> = ["2026-06-01", "2026-06-02", "2026-06-03", "2026-06-04", "2026-06-05", "2026-06-08", "2026-06-09"]
            .iter()
            .map(|d| bar(d, 1_000, 1_010, 990, 1_000))
            .collect();
        // Fires EXACTLY at the fifth identical close and not again — a finding repeated seven times
        // is buried under itself.
        assert_eq!(kinds(&check_series(&stale, meta(), &CheckOptions::default())), vec![("stale", "2026-06-05")]);
        // A dead feed and a genuinely flat market are indistinguishable, and the detail says so
        // rather than asserting which one it is.
        let p = &check_series(&stale, meta(), &CheckOptions::default()).problems[0];
        assert!(p.detail.contains("indistinguishable"));
    }

    #[test]
    fn a_split_shaped_move_is_a_corporate_action_only_where_the_series_says_it_is_unadjusted() {
        let split = [bar("2026-06-01", 2_000, 2_010, 1_990, 2_000), bar("2026-06-02", 1_000, 1_010, 990, 1_000)];
        let d = CheckOptions::default();
        let unadj = SeriesMeta { adjusted: Some(false), ..meta() };
        assert_eq!(kinds(&check_series(&split, unadj, &d)), vec![("probable-corporate-action", "2026-06-02")]);
        // In a series that says it IS adjusted, −50% is a real move and reporting it would be noise.
        assert!(check_series(&split, SeriesMeta { adjusted: Some(true), ..meta() }, &d).ok);
        // UNDECLARED is not the same as false — nothing is claimed either way.
        assert!(check_series(&split, meta(), &d).ok);
    }

    #[test]
    fn a_universe_claim_is_refused_unless_survivorship_was_declared() {
        let c = clean();
        let claim = |v: Option<bool>| may_make_universe_claim(&unverified_series(&c, SeriesMeta { survivorship_free: v, ..meta() }, "x").expect("caveat given"));
        assert!(claim(Some(true)).allowed);
        assert!(!claim(Some(false)).allowed);
        assert!(claim(Some(false)).why.contains("every company that went to zero is missing"));
        // ABSENT IS NOT FALSE, and neither is safe to build a universe claim on.
        let undeclared = claim(None);
        assert!(!undeclared.allowed);
        assert!(undeclared.why.contains("absent is not the same as false"));
    }

    #[test]
    fn an_unverified_series_must_say_why_and_carries_it_into_every_provenance() {
        let c = clean();
        assert_eq!(unverified_series(&c, meta(), "  ").unwrap_err(), "an unverified series must say why it could not be checked");
        let u = unverified_series(&c, meta(), "the source could not be checked").expect("a caveat");
        assert!(u.unverified());
        assert_eq!(provenance(&u), "UNVERIFIED — the source could not be checked · ACME · 3 bar(s) · adjustment UNDECLARED · test");
    }

    #[test]
    fn the_provenance_states_the_adjustment_because_a_result_depends_on_it() {
        let c = clean();
        let d = CheckOptions::default();
        let p = |m: SeriesMeta| provenance(&check_series(&c, m, &d).series.expect("clean"));
        assert_eq!(p(meta()), "checked · ACME · 3 bar(s) · adjustment UNDECLARED · test");
        assert_eq!(p(SeriesMeta { adjusted: Some(true), ..meta() }), "checked · ACME · 3 bar(s) · adjusted · test");
        assert_eq!(p(SeriesMeta { adjusted: Some(false), ..meta() }), "checked · ACME · 3 bar(s) · UNADJUSTED · test");
    }

    #[test]
    fn an_empty_series_is_not_ok_and_has_nothing_to_complain_about() {
        let c = check_series(&[], meta(), &CheckOptions::default());
        assert!(!c.ok, "there is nothing here to build on");
        assert!(c.problems.is_empty(), "and nothing is WRONG with it either — it is simply empty");
        assert!(c.series.is_none());
    }

    #[test]
    fn returns_and_prices_stay_at_the_declared_scale() {
        let c = clean();
        assert_eq!(period_return(&c[0], &c[2]), Some(0.014925373134328358));
        // A zero base is not a price, so the return is ABSENT rather than infinite.
        assert_eq!(period_return(&bar("x", 0, 0, 0, 0), &c[0]), None);
        assert_eq!(price(12.345, &meta(), Currency::USD).minor, 1_235);
        assert_eq!(price(10.0, &meta(), Currency::USD).minor, 1_000);
        // A different scale is a different number of minor units for the same quoted price.
        let tenths = SeriesMeta { minor_per_unit: 1_000, ..meta() };
        assert_eq!(price(10.0, &tenths, Currency::USD).minor, 10_000);
    }

    #[test]
    fn a_bar_date_survives_being_held_inline() {
        assert_eq!(BarDate::new("2026-06-01").as_str(), "2026-06-01");
        assert!(BarDate::new("2026-06-01") < BarDate::new("2026-06-02"));
        assert!(BarDate::new("2025-12-31") < BarDate::new("2026-01-01"));
        // Padding never turns one date into another.
        assert_ne!(BarDate::new("2026-06-01"), BarDate::new("2026-06-10"));
        assert_eq!(BarDate::new("2026-06-01").to_string(), "2026-06-01");
    }
}

//! Reading daily bars out of a public CSV, at a DECLARED scale.
//!
//! The shapes are DATA, like the statement profiles: a column layout that changes is a one-line fix
//! rather than a code change, and a file matching nothing is reported rather than half-read.
//!
//! # Why this does not use `money::parse_minor`
//!
//! That function is deliberately fixed at two decimal places and TRUNCATES the rest, because a bank
//! statement is authoritative and inventing a cent from a sub-cent artifact would put a figure in
//! the store that is not on the statement.
//!
//! An adjusted close is the opposite case. `123.456789` is real precision, not an artifact, and
//! truncating every price to `123.45` biases every single one DOWNWARD — which is a systematic
//! distortion of every return computed from them, in the same direction, forever. So bars parse at
//! the scale the series declares, and they ROUND rather than truncate.
use crate::money::{money, Currency, Minor, Money};
use crate::series::{Bar, BarDate, SeriesMeta};

/// One CSV layout. First match wins, so order matters where headers overlap.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BarProfile {
    pub label: &'static str,
    /// Every one of these must be present for the shape to match.
    pub required: &'static [&'static str],
    pub date: &'static str,
    pub open: &'static str,
    pub high: &'static str,
    pub low: &'static str,
    /// The close to USE. For a source carrying both, this is the adjusted one — see `adjusted`.
    pub close: &'static str,
    pub volume: Option<&'static str>,
    /// What the layout lets us assert about adjustment. NONE where the source does not say, which
    /// is not the same as false.
    pub adjusted: Option<bool>,
}

/// The shapes, as data.
///
/// Yahoo's adjusted layout comes FIRST: its file also carries a plain `close`, so a table checking
/// the plain shape first would match it and silently use unadjusted prices from a file that has
/// adjusted ones sitting in the next column.
pub const BAR_PROFILES: &[BarProfile] = &[
    BarProfile {
        label: "yahoo-adjusted",
        required: &["date", "open", "high", "low", "close", "adj close"],
        date: "date",
        open: "open",
        high: "high",
        low: "low",
        close: "adj close",
        volume: Some("volume"),
        adjusted: Some(true),
    },
    BarProfile {
        label: "stooq",
        required: &["date", "open", "high", "low", "close"],
        date: "date",
        open: "open",
        high: "high",
        low: "low",
        close: "close",
        volume: Some("volume"),
        // Stooq's plain download is NOT split-adjusted. Declaring it false is what lets
        // `check_series` flag a split-shaped day as a corporate action rather than a −50% return.
        adjusted: Some(false),
    },
];

#[derive(Debug, Clone, PartialEq)]
pub struct RejectedRow {
    pub line: usize,
    pub reason: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ParsedBars {
    pub bars: Vec<Bar>,
    pub meta: SeriesMeta,
    pub profile: &'static str,
    /// Rows that could not be read. NAMED with their line, because a silently short series is a
    /// gap a strategy steps over.
    pub rejected: Vec<RejectedRow>,
}

/// Minor units per whole unit for market data — FOUR decimal places.
///
/// Two is not enough: adjusted closes routinely carry more, and rounding them to cents turns a
/// long-run adjusted series into a staircase. Declared on the series so nothing can mix a price at
/// this scale with an account balance at cents.
pub const MARKET_SCALE: i64 = 10_000;

/// Parse a decimal string at a declared scale, ROUNDING the last digit.
///
/// Rounding rather than truncating is the whole difference from `money::parse_minor`, and it is not
/// a nicety: truncation moves every price the same direction, so it does not cancel out over a
/// series the way a rounding error does.
pub fn parse_at_scale(raw: &str, minor_per_unit: i64) -> Result<Minor, String> {
    let t = raw.trim();
    if t.is_empty() {
        return Err("empty price".to_string());
    }
    let (t, neg) = match t.strip_prefix('-') {
        Some(rest) => (rest, true),
        None => (t, false),
    };
    let mut whole = String::new();
    let mut frac = String::new();
    let mut seen_dot = false;
    for c in t.chars() {
        match c {
            '.' if !seen_dot => seen_dot = true,
            '.' => return Err(format!("more than one decimal point in {raw:?}")),
            ',' | ' ' | '$' => {}
            c if c.is_ascii_digit() => {
                if seen_dot {
                    frac.push(c)
                } else {
                    whole.push(c)
                }
            }
            c => return Err(format!("unexpected {c:?} in price {raw:?}")),
        }
    }
    if whole.is_empty() && frac.is_empty() {
        return Err(format!("no digits in price {raw:?}"));
    }
    let w: i64 = if whole.is_empty() { 0 } else { whole.parse().map_err(|_| format!("price out of range: {raw:?}"))? };
    // Build the fraction as a rational at the target scale, then round the remainder.
    let digits = frac.len() as u32;
    let f: i64 = if frac.is_empty() { 0 } else { frac.parse().map_err(|_| format!("bad fraction in {raw:?}"))? };
    let pow = 10i64.checked_pow(digits).ok_or_else(|| format!("too many decimal places in {raw:?}"))?;
    let scaled_frac = if pow == 0 { 0 } else { (f * minor_per_unit * 2 / pow).div_euclid(2) + i64::from((f * minor_per_unit * 2 / pow).rem_euclid(2) != 0) };
    let minor = w.checked_mul(minor_per_unit).and_then(|x| x.checked_add(scaled_frac)).ok_or_else(|| format!("price out of range: {raw:?}"))?;
    Ok(if neg { -minor } else { minor })
}

fn split_line(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quoted = false;
    for c in line.chars() {
        match c {
            '"' => quoted = !quoted,
            ',' if !quoted => out.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    out.push(cur);
    out.into_iter().map(|s| s.trim().to_string()).collect()
}

/// Read a CSV of daily bars.
///
/// The symbol and the source are CALLER-supplied, because a file does not know either — and
/// `SeriesMeta` is the place where what nobody declared stays undeclared.
pub fn parse_csv(text: &str, symbol: &str, source: &str) -> Result<ParsedBars, String> {
    let lines: Vec<&str> = text.lines().filter(|l| !l.trim().is_empty()).collect();
    let header_line = lines.first().ok_or("the file is empty")?;
    let header: Vec<String> = split_line(header_line).iter().map(|h| h.to_lowercase()).collect();
    let at = |name: &str| header.iter().position(|h| h == name);

    let profile = BAR_PROFILES
        .iter()
        .find(|p| p.required.iter().all(|r| header.contains(&r.to_string())))
        .ok_or_else(|| {
            format!(
                "no bar layout matches these columns: {}. Known layouts: {}",
                header.join(", "),
                BAR_PROFILES.iter().map(|p| p.label).collect::<Vec<_>>().join(", ")
            )
        })?;

    let (di, oi, hi, li, ci) = (
        at(profile.date).ok_or("no date column")?,
        at(profile.open).ok_or("no open column")?,
        at(profile.high).ok_or("no high column")?,
        at(profile.low).ok_or("no low column")?,
        at(profile.close).ok_or("no close column")?,
    );
    let vi = profile.volume.and_then(at);

    let mut bars: Vec<Bar> = Vec::new();
    let mut rejected: Vec<RejectedRow> = Vec::new();
    for (n, line) in lines.iter().enumerate().skip(1) {
        let cells = split_line(line);
        let get = |i: usize| cells.get(i).map(String::as_str).unwrap_or("");
        let date = get(di).to_string();
        if date.len() < 10 {
            rejected.push(RejectedRow { line: n + 1, reason: format!("{date:?} is not a YYYY-MM-DD date") });
            continue;
        }
        let prices: Result<Vec<Minor>, String> = [oi, hi, li, ci].iter().map(|i| parse_at_scale(get(*i), MARKET_SCALE)).collect();
        match prices {
            Err(e) => rejected.push(RejectedRow { line: n + 1, reason: e }),
            Ok(p) => bars.push(Bar {
                date_i: BarDate::new(&date[..10]),
                open: money(p[0], Currency::USD),
                high: money(p[1], Currency::USD),
                low: money(p[2], Currency::USD),
                close: money(p[3], Currency::USD),
                // ABSENT where the source did not carry it, never zero — a volume filter reading
                // zero as "no trading" would silently drop every bar of an otherwise fine series.
                volume: vi.and_then(|i| get(i).replace(',', "").parse::<i64>().ok()),
            }),
        }
    }

    Ok(ParsedBars {
        meta: SeriesMeta {
            symbol: symbol.to_string(),
            adjusted: profile.adjusted,
            // NOBODY DECLARED IT, and it cannot be inferred from one instrument's file. Left None
            // so `may_make_universe_claim` refuses rather than a universe claim being made by
            // accident from a single-name backtest.
            survivorship_free: None,
            source: source.to_string(),
            minor_per_unit: MARKET_SCALE,
        },
        profile: profile.label,
        bars,
        rejected,
    })
}

/// Render a price held at a series' scale. Never feed this into arithmetic.
pub fn format_price(m: Money, meta: &SeriesMeta) -> String {
    let scale = meta.minor_per_unit.max(1);
    let whole = m.minor / scale;
    let frac = (m.minor % scale).abs();
    let width = (scale as f64).log10().round() as usize;
    format!("{whole}.{frac:0width$}")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_price_is_rounded_at_the_declared_scale_and_never_truncated() {
        // The whole reason this is not `money::parse_minor`: truncation moves every price the same
        // direction, so it does not cancel over a series the way rounding does.
        assert_eq!(parse_at_scale("123.45", MARKET_SCALE).unwrap(), 1_234_500);
        assert_eq!(parse_at_scale("123.456789", MARKET_SCALE).unwrap(), 1_234_568, "rounded UP, not truncated to ...67");
        assert_eq!(parse_at_scale("123.456712", MARKET_SCALE).unwrap(), 1_234_567);
        assert_eq!(parse_at_scale("0.00005", MARKET_SCALE).unwrap(), 1, "a half at the boundary rounds away from zero");
        assert_eq!(parse_at_scale("123", MARKET_SCALE).unwrap(), 1_230_000);
        assert_eq!(parse_at_scale("-1.5", MARKET_SCALE).unwrap(), -15_000);
        assert_eq!(parse_at_scale("1,234.50", MARKET_SCALE).unwrap(), 12_345_000, "thousands separators carry no value");
        // At cents, the same string is a different number of minor units — which is exactly why the
        // scale is DECLARED on the series rather than assumed.
        assert_eq!(parse_at_scale("123.45", 100).unwrap(), 12_345);
    }

    #[test]
    fn an_unreadable_price_is_refused_rather_than_guessed() {
        assert!(parse_at_scale("", MARKET_SCALE).is_err());
        assert!(parse_at_scale("  ", MARKET_SCALE).is_err());
        assert!(parse_at_scale("N/A", MARKET_SCALE).is_err());
        assert!(parse_at_scale("1.2.3", MARKET_SCALE).is_err());
        assert!(parse_at_scale("null", MARKET_SCALE).is_err());
    }

    #[test]
    fn the_adjusted_layout_wins_because_the_file_carries_both_closes() {
        // Yahoo's file has `close` AND `adj close`. A table checking the plain shape first would
        // match it and silently backtest unadjusted prices sitting next to adjusted ones.
        let csv = "Date,Open,High,Low,Close,Adj Close,Volume\n2026-06-01,10.00,10.50,9.90,10.40,5.20,1000\n";
        let p = parse_csv(csv, "ACME", "yahoo").expect("parses");
        assert_eq!(p.profile, "yahoo-adjusted");
        assert_eq!(p.meta.adjusted, Some(true));
        assert_eq!(p.bars[0].close.minor, 52_000, "the ADJUSTED close, not the 10.40");
        assert_eq!(p.bars[0].volume, Some(1_000));
    }

    #[test]
    fn stooq_declares_itself_unadjusted_so_a_split_is_flagged_rather_than_traded() {
        let csv = "Date,Open,High,Low,Close,Volume\n2026-06-01,10.00,10.50,9.90,10.40,1000\n";
        let p = parse_csv(csv, "ACME", "stooq").expect("parses");
        assert_eq!(p.profile, "stooq");
        // Declaring FALSE is what lets `check_series` call a −50% day a corporate action. Leaving
        // it undeclared would let a strategy that buys drops find a great many of them.
        assert_eq!(p.meta.adjusted, Some(false));
        assert_eq!(p.bars[0].close.minor, 104_000);
    }

    #[test]
    fn survivorship_is_left_undeclared_because_one_files_worth_of_data_cannot_know() {
        let csv = "Date,Open,High,Low,Close,Volume\n2026-06-01,10,10,10,10,1\n";
        let p = parse_csv(csv, "ACME", "stooq").expect("parses");
        assert_eq!(p.meta.survivorship_free, None);
        // So a universe claim from it is refused, which is the point — a single-name file says
        // nothing about what is missing from a universe.
        let s = crate::series::unverified_series(&p.bars, p.meta, "test").expect("caveat");
        assert!(!crate::series::may_make_universe_claim(&s).allowed);
    }

    #[test]
    fn an_unreadable_row_is_named_with_its_line_rather_than_dropped() {
        let csv = "Date,Open,High,Low,Close\n2026-06-01,10,10,10,10\n2026-06-02,N/A,10,10,10\nbad-date,1,1,1,1\n2026-06-03,11,11,11,11\n";
        let p = parse_csv(csv, "ACME", "stooq").expect("parses");
        assert_eq!(p.bars.len(), 2);
        assert_eq!(p.rejected.len(), 2);
        assert_eq!(p.rejected[0].line, 3);
        assert_eq!(p.rejected[1].line, 4);
        assert!(p.rejected[1].reason.contains("not a YYYY-MM-DD date"));
        // A silently short series is a gap a strategy steps over without noticing, so the count is
        // reported rather than the rows just being absent.
    }

    #[test]
    fn a_file_matching_no_layout_is_refused_and_says_what_it_knows() {
        let e = parse_csv("Ticker,Price\nACME,10\n", "ACME", "x").unwrap_err();
        assert!(e.contains("no bar layout matches"));
        assert!(e.contains("yahoo-adjusted") && e.contains("stooq"), "it names the layouts it does know");
        assert!(parse_csv("", "ACME", "x").is_err());
    }

    #[test]
    fn a_price_renders_back_at_its_own_scale() {
        let p = parse_csv("Date,Open,High,Low,Close\n2026-06-01,123.4567,1,1,1\n", "ACME", "stooq").expect("parses");
        assert_eq!(format_price(p.bars[0].open, &p.meta), "123.4567");
        let cents = SeriesMeta { minor_per_unit: 100, ..p.meta.clone() };
        assert_eq!(format_price(money(12_345, Currency::USD), &cents), "123.45");
    }
}

//! The signal library — and the control that keeps the harness honest.
//!
//! Each of these is a hypothesis about price, deliberately simple, and every one is judged by the
//! same [`crate::evaluate`] machinery with no special pleading. Simple is not a limitation here: a
//! complicated signal has more places to overfit and the harness cannot tell the difference.
//!
//! # The null control is the most important thing in this file
//!
//! [`NullControl`] flips a deterministic coin. It knows nothing and it cannot work. If the harness
//! ever rates it as promising, THE HARNESS IS BROKEN — and that is a claim about the measuring
//! instrument that can be tested, which is worth more than any of the signals below.
//!
//! It also calibrates expectations. Run it beside a real candidate on the same data and the
//! difference between them is the only part that is evidence.
use crate::evaluate::Signal;
use crate::series::Bar;

/// Hold, always. The benchmark expressed as a signal, so it goes through the identical path.
pub struct BuyAndHold;

impl Signal for BuyAndHold {
    fn name(&self) -> &str {
        "buy-and-hold"
    }
    fn position(&self, _history: &[Bar]) -> f64 {
        1.0
    }
}

/// Long while price is above its own moving average, flat below it.
///
/// The oldest trend filter there is, and one of the few with evidence outside the sample it was
/// found in. What it actually does is avoid long drawdowns rather than improve returns, so read the
/// max drawdown before the total.
pub struct TrendFilter {
    pub window: usize,
}

impl Signal for TrendFilter {
    fn name(&self) -> &str {
        "trend-filter"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() < self.window {
            // NOT ENOUGH HISTORY IS FLAT, never long. A signal that defaults to holding while it
            // warms up is measuring buy-and-hold for its first year and calling it strategy.
            return 0.0;
        }
        let window = &history[history.len() - self.window..];
        let mean = window.iter().map(|b| b.close.minor as f64).sum::<f64>() / self.window as f64;
        let last = history[history.len() - 1].close.minor as f64;
        if last > mean { 1.0 } else { 0.0 }
    }
}

/// Twelve-month return, skipping the most recent month.
///
/// The skip is not decoration: the last month reverses on average, and momentum measured including
/// it is a materially weaker signal. Long when the trailing return is positive, flat otherwise.
pub struct Momentum {
    pub lookback: usize,
    pub skip: usize,
}

impl Momentum {
    /// The conventional 12-1 in trading days.
    pub fn twelve_one() -> Momentum {
        Momentum { lookback: 252, skip: 21 }
    }
}

impl Signal for Momentum {
    fn name(&self) -> &str {
        "momentum-12-1"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() < self.lookback + self.skip {
            return 0.0;
        }
        let end = history.len() - self.skip;
        let start = end - self.lookback;
        let (a, b) = (history[start].close.minor as f64, history[end - 1].close.minor as f64);
        if a <= 0.0 {
            return 0.0;
        }
        if b > a { 1.0 } else { 0.0 }
    }
}

/// Long after a run of consecutive down closes.
///
/// Included BECAUSE it is the most overfit shape in retail research, not because it is expected to
/// work — a candidate whose result cannot be distinguished from this one has not been demonstrated.
pub struct MeanReversion {
    pub down_days: usize,
}

impl Signal for MeanReversion {
    fn name(&self) -> &str {
        "mean-reversion"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() <= self.down_days {
            return 0.0;
        }
        let tail = &history[history.len() - self.down_days - 1..];
        let all_down = tail.windows(2).all(|w| w[1].close.minor < w[0].close.minor);
        if all_down { 1.0 } else { 0.0 }
    }
}

/// Long while the last `lookback` closes are rising — the fast counterpart to `Momentum`.
///
/// A short-horizon persistence signal. Added because the simulation caught its absence: a battery
/// whose fastest signal averages two hundred days cannot see structure that turns over in three,
/// and reported "nothing here" on a series built to contain something. That was a gap in the
/// battery rather than a fault in the harness, and the distinction is only visible because the
/// simulation knew the answer in advance.
///
/// It trades a great deal, so read it net of costs and expect the costs to matter.
pub struct Persistence {
    pub lookback: usize,
}

impl Signal for Persistence {
    fn name(&self) -> &str {
        "persistence"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        if history.len() <= self.lookback {
            return 0.0;
        }
        let tail = &history[history.len() - self.lookback - 1..];
        if tail.windows(2).all(|w| w[1].close.minor > w[0].close.minor) { 1.0 } else { 0.0 }
    }
}

/// A deterministic coin flip. THE CONTROL.
///
/// It knows nothing, it cannot work, and the harness rating it as promising would mean the harness
/// is broken. Seeded off the history length so it is reproducible run to run — a control that
/// changed every run could not be compared against anything.
pub struct NullControl {
    pub seed: u64,
}

impl Signal for NullControl {
    fn name(&self) -> &str {
        "null-control"
    }
    fn position(&self, history: &[Bar]) -> f64 {
        let mut x = self.seed ^ (history.len() as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15);
        x ^= x >> 30;
        x = x.wrapping_mul(0xBF58_476D_1CE4_E5B9);
        x ^= x >> 27;
        if x.is_multiple_of(2) { 1.0 } else { 0.0 }
    }
}

/// The default battery, in the order a person should read it.
///
/// The control is FIRST on purpose. Reading it before the candidates is what stops a mediocre result
/// looking impressive in isolation — and running them together is also what sets the trial count,
/// so the bar every one of them must clear already accounts for the others.
pub fn default_battery() -> Vec<Box<dyn Signal>> {
    vec![
        Box::new(NullControl { seed: 1 }),
        Box::new(BuyAndHold),
        Box::new(TrendFilter { window: 200 }),
        Box::new(Momentum::twelve_one()),
        Box::new(MeanReversion { down_days: 3 }),
        Box::new(Persistence { lookback: 1 }),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::evaluate::{evaluate, evaluate_all, EvalOptions, Verdict};
    use crate::money::usd;
    use crate::series::{unverified_series, BarDate, SeriesMeta, VerifiedSeries};

    // SYNTHETIC FIXTURES ONLY.
    fn weekdays(n: usize) -> Vec<String> {
        let mut out = Vec::with_capacity(n);
        let mut d = "2026-01-05".to_string();
        while out.len() < n {
            if !crate::series::is_weekend(&d) {
                out.push(d.clone());
            }
            d = crate::obligations::add_days(&d, 1);
        }
        out
    }

    fn bar_on(date: &str, open: i64, close: i64) -> Bar {
        Bar { date_i: BarDate::new(date), open: usd(open), high: usd(open.max(close) + 1), low: usd(open.min(close) - 1), close: usd(close), volume: None }
    }

    /// A deterministic walk with a drift, so a trend actually exists to be found.
    fn walk(n: usize, drift: f64) -> Vec<Bar> {
        let dates = weekdays(n);
        let mut px = 10_000.0_f64;
        let mut seed = 999u64;
        let mut out = Vec::new();
        for date in dates.iter().take(n) {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
            let u = ((seed >> 33) as f64 / (1u64 << 31) as f64) * 2.0 - 1.0;
            let open = px;
            px *= 1.0 + drift + u * 0.015;
            out.push(bar_on(date, open.round() as i64, px.round() as i64));
        }
        out
    }

    fn series(bars: &[Bar]) -> VerifiedSeries {
        unverified_series(bars, SeriesMeta::new("SYNTH", "generated"), "a synthetic fixture, not market data").expect("caveat")
    }

    #[test]
    fn the_null_control_is_never_rated_promising_on_noise() {
        // THE GUARD ON THE HARNESS ITSELF. A coin flip cannot work, so a harness that ever calls one
        // promising is broken — and that is a claim about the instrument, testable across seeds.
        let bars = walk(800, 0.0);
        let s = series(&bars);
        for seed in [1u64, 7, 42, 1_000, 65_537] {
            let e = evaluate(&s, &NullControl { seed }, &EvalOptions { trials: 6, ..EvalOptions::default() });
            assert_ne!(e.verdict, Verdict::Promising, "seed {seed} was rated promising: {}", e.why);
        }
    }

    #[test]
    fn a_signal_with_too_little_history_stays_flat_rather_than_defaulting_long() {
        // Defaulting to long while warming up measures buy-and-hold for the first year and calls it
        // strategy — the returns are real and none of them belong to the signal.
        assert_eq!(TrendFilter { window: 200 }.position(&[]), 0.0);
        assert_eq!(Momentum::twelve_one().position(&walk(100, 0.0)), 0.0);
        assert_eq!(MeanReversion { down_days: 3 }.position(&[]), 0.0);
        // And with enough history it does take a view.
        let up: Vec<Bar> = weekdays(300).iter().enumerate().map(|(i, d)| bar_on(d, 10_000 + i as i64 * 10, 10_000 + i as i64 * 10)).collect();
        assert_eq!(TrendFilter { window: 200 }.position(&up), 1.0, "a rising series is above its own average");
    }

    #[test]
    fn the_trend_filter_is_flat_below_its_average_and_long_above_it() {
        let down: Vec<Bar> = weekdays(300).iter().enumerate().map(|(i, d)| bar_on(d, 20_000 - i as i64 * 10, 20_000 - i as i64 * 10)).collect();
        assert_eq!(TrendFilter { window: 200 }.position(&down), 0.0, "a falling series is below its own average");
        // Exactly at the average is FLAT, not long — a strict comparison, so a dead-flat series
        // does not read as a buy signal on every bar.
        let flat: Vec<Bar> = weekdays(300).iter().map(|d| bar_on(d, 10_000, 10_000)).collect();
        assert_eq!(TrendFilter { window: 200 }.position(&flat), 0.0);
    }

    #[test]
    fn momentum_skips_the_most_recent_month_because_it_reverses() {
        let dates = weekdays(300);
        // Rising for a year, then falling hard for the last month. Including the last month would
        // read this as negative momentum; skipping it reads the year, which is the documented shape.
        let mut bars: Vec<Bar> = Vec::new();
        for (i, d) in dates.iter().enumerate() {
            let px = if i < 275 { 10_000 + i as i64 * 20 } else { 15_500 - (i as i64 - 275) * 100 };
            bars.push(bar_on(d, px, px));
        }
        assert_eq!(Momentum { lookback: 252, skip: 21 }.position(&bars), 1.0, "the year was up");
        assert_eq!(Momentum { lookback: 252, skip: 0 }.position(&bars), 1.0);
        // The skip is what makes the two able to disagree at all — pinned so a refactor that drops
        // it cannot pass silently.
        assert_eq!(Momentum::twelve_one().skip, 21);
        assert_eq!(Momentum::twelve_one().lookback, 252);
    }

    #[test]
    fn mean_reversion_needs_a_full_run_of_down_closes() {
        let dates = weekdays(10);
        let down: Vec<Bar> = dates.iter().enumerate().map(|(i, d)| bar_on(d, 10_000 - i as i64 * 10, 10_000 - i as i64 * 10)).collect();
        assert_eq!(MeanReversion { down_days: 3 }.position(&down), 1.0);
        // One up close inside the run and it is not a run.
        let mut broken = down.clone();
        let n = broken.len();
        broken[n - 2] = bar_on(dates[n - 2].as_str(), 99_999, 99_999);
        assert_eq!(MeanReversion { down_days: 3 }.position(&broken), 0.0);
    }

    #[test]
    fn the_battery_runs_them_all_against_the_bar_for_running_them_all() {
        let bars = walk(900, 0.0003);
        let s = series(&bars);
        let battery = default_battery();
        let refs: Vec<&dyn Signal> = battery.iter().map(|b| b.as_ref()).collect();
        let out = evaluate_all(&s, &refs, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(out.len(), 6);
        // The trial count is the number ACTUALLY run, so every one of them is graded against the
        // bar for five attempts rather than one.
        let want = crate::evaluate::t_required_for(6);
        assert!(out.iter().all(|e| (e.t_required - want).abs() < 1e-9));
        // The control is in the battery, so a mediocre candidate is never read in isolation.
        assert!(out.iter().any(|e| e.signal == "null-control"));
        assert!(out.iter().any(|e| e.signal == "buy-and-hold"));
    }

    #[test]
    fn buy_and_hold_as_a_signal_matches_the_benchmark_it_is_measured_against() {
        // A useful internal consistency check: routing the benchmark through the signal path must
        // reproduce the benchmark, or the two are computed differently and every comparison the
        // harness makes is between things that are not comparable.
        let bars = walk(600, 0.0004);
        let e = evaluate(&series(&bars), &BuyAndHold, &EvalOptions { costs: crate::evaluate::Costs::free(), min_trades: 1, ..EvalOptions::default() });
        let (net, bench) = (e.net.unwrap(), e.benchmark.unwrap());
        assert!((net.total_return - bench.total_return).abs() < 1e-9, "net {} vs benchmark {}", net.total_return, bench.total_return);
        assert_eq!(net.periods, bench.periods);
    }
}

//! Simulation — pointing the harness at data whose truth is already known.
//!
//! Every other module here measures a strategy. This one measures the MEASURING INSTRUMENT, which is
//! the thing you cannot check with real data: on a real series nobody knows what the right answer
//! was, so a harness that is subtly broken looks exactly like a harness that found something.
//!
//! Two questions, and the second is the one that matters:
//!
//! 1. **Does it reach the right verdict on a process whose truth we set?** Random walks contain
//!    nothing, and anything reported as a finding on one is the harness lying.
//! 2. **What does testing many signals actually do to a result?** [`multiple_testing`] generates a
//!    pile of signals that are KNOWN to be worthless, runs them on data that is KNOWN to be noise,
//!    and reports how many clear the conventional bar. The answer is not zero, and that number is
//!    the single most useful thing in this file.
use crate::evaluate::{evaluate, evaluate_all, t_required_for, EvalOptions, Evaluation, Signal, Verdict};
use crate::money::{money, Currency};
use crate::series::{is_weekend, unverified_series, Bar, BarDate, SeriesMeta, VerifiedSeries};
use crate::signals::{default_battery, NullControl};

/// A deterministic generator, so a simulation is reproducible and two runs can be compared.
struct Rng(u64);

impl Rng {
    fn next_unit(&mut self) -> f64 {
        self.0 = self.0.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
        ((self.0 >> 33) as f64 / (1u64 << 31) as f64) * 2.0 - 1.0
    }
}

/// `n` consecutive trading days from a Monday.
pub fn trading_days(n: usize, from: &str) -> Vec<String> {
    let mut out = Vec::with_capacity(n);
    let mut d = from.to_string();
    while out.len() < n {
        if !is_weekend(&d) {
            out.push(d.clone());
        }
        let next = crate::obligations::add_days(&d, 1);
        if next == d {
            break;
        }
        d = next;
    }
    out
}

/// What kind of world the prices came from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Shape {
    /// No drift. Contains NOTHING, by construction.
    Noise,
    /// A steady upward drift with noise on top.
    Trend,
    /// A trend that gives most of it back in one stretch.
    Crash,
    /// Yesterday's direction predicts today's — structure that real markets do not have.
    Autocorrelated,
}

impl Shape {
    pub fn label(self) -> &'static str {
        match self {
            Shape::Noise => "noise",
            Shape::Trend => "trend",
            Shape::Crash => "crash",
            Shape::Autocorrelated => "autocorrelated",
        }
    }

    /// What a correct harness should conclude, and WHY that is knowable here.
    pub fn expectation(self) -> &'static str {
        match self {
            Shape::Noise => "nothing found — a driftless walk contains no signal, so anything reported as one is the instrument lying",
            Shape::Trend => "nothing beats holding — timing signals give up upside in a trend, and a battery that claims otherwise is fitting",
            Shape::Crash => "nothing found, but the trend filter should hold a SMALLER drawdown than buying and holding",
            Shape::Autocorrelated => "the battery contains a signal fast enough to see this — real structure that no signal in the battery can read is a gap in the BATTERY, not in the harness, which is proved able to find it elsewhere",
        }
    }
}

/// Build a synthetic series of a known shape.
pub fn synth(shape: Shape, n: usize, seed: u64) -> Vec<Bar> {
    let dates = trading_days(n, "2020-01-06");
    let mut rng = Rng(seed);
    let mut px = 100.0_f64;
    let mut up = true;
    let mut out = Vec::with_capacity(n);
    for (i, date) in dates.iter().enumerate() {
        let u = rng.next_unit();
        let open = px;
        let step = match shape {
            Shape::Noise => u * 0.012,
            Shape::Trend => 0.0006 + u * 0.012,
            // Two thirds up, then a sustained fall that takes most of it back.
            Shape::Crash => {
                if i < n * 2 / 3 {
                    0.0008 + u * 0.010
                } else {
                    -0.0016 + u * 0.016
                }
            }
            Shape::Autocorrelated => {
                if u > 0.75 {
                    up = !up;
                }
                if up { 0.004 } else { -0.004 }
            }
        };
        px *= 1.0 + step;
        if px < 1.0 {
            px = 1.0; // a price floor, so a bad draw cannot make the series non-positive
        }
        let (o, c) = (open, px);
        out.push(Bar {
            date_i: BarDate::new(date),
            open: money((o * 10_000.0).round() as i64, Currency::USD),
            high: money((o.max(c) * 1.002 * 10_000.0).round() as i64, Currency::USD),
            low: money((o.min(c) * 0.998 * 10_000.0).round() as i64, Currency::USD),
            close: money((c * 10_000.0).round() as i64, Currency::USD),
            volume: Some(1_000_000),
        });
    }
    out
}

pub fn series_of(shape: Shape, n: usize, seed: u64) -> VerifiedSeries {
    let bars = synth(shape, n, seed);
    let meta = SeriesMeta {
        symbol: shape.label().to_uppercase(),
        adjusted: Some(true),
        // UNDECLARED even here: a single simulated instrument says nothing about what would be
        // missing from a universe, and pretending otherwise in a simulation would teach the wrong
        // habit to whatever reads it next.
        survivorship_free: None,
        source: "simulated".to_string(),
        minor_per_unit: 10_000,
    };
    unverified_series(&bars, meta, "SIMULATED DATA — generated here, not a market").expect("a caveat is given")
}

#[derive(Debug, Clone, PartialEq)]
pub struct RegimeResult {
    pub shape: Shape,
    pub expectation: &'static str,
    pub results: Vec<Evaluation>,
    /// Did the harness reach the verdict this shape demands?
    pub matched: bool,
    /// What was observed, in the terms the expectation is phrased in.
    pub observed: String,
}

/// Run the battery over every known shape and check the verdicts against what the shape guarantees.
///
/// A mismatch is NOT automatically the harness being wrong — an expectation can be too strong, and
/// saying which is a judgement. What it is, always, is something to go and look at, which is more
/// than a green test suite over real data can ever offer.
pub fn run_regimes(bars: usize, opts: &EvalOptions) -> Vec<RegimeResult> {
    let mut out = Vec::new();
    for shape in [Shape::Noise, Shape::Trend, Shape::Crash, Shape::Autocorrelated] {
        let s = series_of(shape, bars, 20_260_101 + shape as u64);
        let battery = default_battery();
        let refs: Vec<&dyn Signal> = battery.iter().map(|b| b.as_ref()).collect();
        let results = evaluate_all(&s, &refs, opts);

        let found = results.iter().any(|e| e.verdict == Verdict::Promising);
        let beat_hold = results.iter().any(|e| match (e.net, e.benchmark) {
            (Some(n), Some(b)) => n.total_return > b.total_return && e.verdict != Verdict::Refused,
            _ => false,
        });
        let (matched, observed) = match shape {
            Shape::Noise => (!found, format!("{} signal(s) rated promising", results.iter().filter(|e| e.verdict == Verdict::Promising).count())),
            Shape::Trend => (!beat_hold, format!("{} signal(s) beat buy-and-hold", results.iter().filter(|e| matches!((e.net, e.benchmark), (Some(n), Some(b)) if n.total_return > b.total_return)).count())),
            Shape::Crash => {
                let hold_dd = results.iter().find_map(|e| e.benchmark.map(|b| b.max_drawdown)).unwrap_or(0.0);
                let filter_dd = results.iter().find(|e| e.signal == "trend-filter").and_then(|e| e.net.map(|n| n.max_drawdown));
                match filter_dd {
                    Some(f) => (f < hold_dd, format!("trend filter drew down {:.1}% against {:.1}% for holding", f * 100.0, hold_dd * 100.0)),
                    None => (false, "the trend filter produced no result".to_string()),
                }
            }
            Shape::Autocorrelated => (found, format!("{} signal(s) rated promising", results.iter().filter(|e| e.verdict == Verdict::Promising).count())),
        };
        out.push(RegimeResult { shape, expectation: shape.expectation(), results, matched, observed });
    }
    out
}

#[derive(Debug, Clone, PartialEq)]
pub struct MultipleTesting {
    pub trials: usize,
    pub bars: usize,
    /// The largest |t| among signals that are all KNOWN to be worthless.
    pub best_t: f64,
    /// The conventional single-test bar.
    pub naive_bar: f64,
    /// The bar this many trials actually demands.
    pub honest_bar: f64,
    /// How many worthless signals clear the conventional bar. THE NUMBER THAT MATTERS.
    pub pass_naive: usize,
    /// How many clear the honest one.
    pub pass_honest: usize,
    /// What the best of them appeared to return, net.
    pub best_return: f64,
}

/// Run `trials` signals that are KNOWN to be worthless on data that is KNOWN to contain nothing.
///
/// This is the demonstration, and it is not an argument — it is a count. Every signal here is a
/// seeded coin flip and the series is a driftless random walk, so the true answer is zero every
/// time. Whatever clears the conventional bar cleared it by luck, and that is what happens to
/// somebody sweeping parameters without counting how many they tried.
///
/// **Costs are switched off inside this function**, because they are a confound rather than a
/// detail: a signal that trades every bar loses money reliably, and a reliable loss is a real
/// effect with a large t-statistic. The first version of this left them on and reported 40 of 40
/// "significant" — a striking number that was measuring the wrong thing entirely.
pub fn multiple_testing(trials: usize, bars: usize, opts: &EvalOptions) -> MultipleTesting {
    let naive_bar = t_required_for(1);
    let honest_bar = t_required_for(trials);
    let mut best_t = 0.0_f64;
    let mut best_return = 0.0_f64;
    let mut pass_naive = 0usize;
    let mut pass_honest = 0usize;

    for i in 0..trials {
        // A FRESH SERIES PER TRIAL, so the trials are independent. Forty coin flips on ONE series
        // are highly correlated — they are all long about half the time in the same market — so
        // their t-statistics cluster and almost none clear the bar. That is a true fact about
        // correlated trials and it demonstrates nothing about multiple comparisons, which is what
        // this function is for. Real parameter sweeps sit between the two: many signals on one
        // series, correlated, so the effective number of trials is lower than the count and the
        // sqrt(2 ln n) bar is conservative for them.
        let s = series_of(Shape::Noise, bars, 987_654_321 + i as u64 * 7_919);
        let sig = NullControl { seed: 1_000 + i as u64 };
        // Each is judged ALONE, on purpose — this is measuring what a person sees when they look at
        // one result at a time, which is how the mistake is actually made.
        // COSTS ARE OFF HERE, and that is the experiment rather than an oversight. A coin flip
        // trades every bar, so at any real cost it loses money RELIABLY — which is a large negative
        // t-statistic produced by a genuine effect, not by luck. Leaving costs on measured "trading
        // constantly is expensive" and reported it as multiple testing: 40 of 40 "significant",
        // when 5% of 40 should be about two. Luck is the only thing that may vary here.
        let e = evaluate(&s, &sig, &EvalOptions { trials: 1, min_trades: 1, costs: crate::evaluate::Costs::free(), ..*opts });
        let t = e.t_stat.unwrap_or(0.0).abs();
        if t > naive_bar {
            pass_naive += 1;
        }
        if t > honest_bar {
            pass_honest += 1;
        }
        if t > best_t {
            best_t = t;
            best_return = e.net.map(|n| n.total_return).unwrap_or(0.0);
        }
    }

    MultipleTesting { trials, bars, best_t, naive_bar, honest_bar, pass_naive, pass_honest, best_return }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_generated_series_is_a_real_series() {
        for shape in [Shape::Noise, Shape::Trend, Shape::Crash, Shape::Autocorrelated] {
            let bars = synth(shape, 400, 7);
            assert_eq!(bars.len(), 400, "{}", shape.label());
            // Sorted, on weekdays, and every price positive — the properties `check_series` needs
            // and `bars_available_at`'s binary search assumes.
            assert!(bars.windows(2).all(|w| w[0].date() < w[1].date()), "{} is not sorted", shape.label());
            assert!(bars.iter().all(|b| !is_weekend(b.date())), "{} lands on a weekend", shape.label());
            assert!(bars.iter().all(|b| b.close.minor > 0 && b.open.minor > 0), "{} has a non-positive price", shape.label());
            assert!(bars.iter().all(|b| b.high.minor >= b.low.minor), "{} has an impossible bar", shape.label());
        }
    }

    #[test]
    fn the_same_seed_gives_the_same_series() {
        // A simulation nobody can reproduce is an anecdote.
        assert_eq!(synth(Shape::Trend, 200, 42), synth(Shape::Trend, 200, 42));
        assert_ne!(synth(Shape::Trend, 200, 42), synth(Shape::Trend, 200, 43));
    }

    #[test]
    fn the_shapes_actually_differ_in_the_way_they_claim_to() {
        let ret = |shape: Shape| {
            let b = synth(shape, 900, 5);
            (b.last().unwrap().close.minor as f64 - b[0].close.minor as f64) / b[0].close.minor as f64
        };
        // A trend goes up, a crash ends down. If these ever stopped being true the regime checks
        // below would be asserting things about series that are not what they say they are.
        assert!(ret(Shape::Trend) > 0.3, "trend returned {}", ret(Shape::Trend));
        assert!(ret(Shape::Crash) < ret(Shape::Trend), "the crash should give back what the trend keeps");
        // And the autocorrelated one has runs: consecutive same-direction closes, unlike a walk.
        let runs = |shape: Shape| {
            let b = synth(shape, 900, 5);
            b.windows(3).filter(|w| (w[1].close.minor > w[0].close.minor) == (w[2].close.minor > w[1].close.minor)).count()
        };
        assert!(runs(Shape::Autocorrelated) > runs(Shape::Noise), "the autocorrelated shape has no more runs than noise");
    }

    #[test]
    fn the_harness_finds_nothing_in_a_driftless_walk() {
        // THE INSTRUMENT CHECK. A random walk contains nothing, so anything rated promising here is
        // the harness lying — and on real data that failure is invisible.
        let opts = EvalOptions { min_trades: 1, ..EvalOptions::default() };
        for seed in [1u64, 2, 3, 99] {
            let s = series_of(Shape::Noise, 1_200, seed);
            let battery = default_battery();
            let refs: Vec<&dyn Signal> = battery.iter().map(|b| b.as_ref()).collect();
            let out = evaluate_all(&s, &refs, &opts);
            assert!(out.iter().all(|e| e.verdict != Verdict::Promising), "seed {seed}: {:?}", out.iter().map(|e| (e.signal.clone(), e.verdict.label())).collect::<Vec<_>>());
        }
    }

    #[test]
    fn worthless_signals_clear_the_conventional_bar_and_that_is_the_whole_lesson() {
        // Forty coin flips on a driftless walk. The true answer is zero for every one of them, and
        // the count that clears a single-test threshold is not zero — that is what happens to
        // somebody sweeping parameters without counting how many they tried.
        let m = multiple_testing(40, 1_200, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(m.trials, 40);
        assert!(m.honest_bar > m.naive_bar, "the bar must rise with the trial count");
        assert!(m.pass_honest <= m.pass_naive, "the honest bar cannot admit MORE than the naive one");
        // The demonstration is the count itself, whatever it comes out at — pinning an exact number
        // would be pinning the PRNG rather than the phenomenon.
        assert!(m.best_t > 0.0);
        // BUT NOT ALL OF THEM. Under the null about 5% should clear a two-sided 5% bar; if nearly
        // every worthless signal is "significant", this is measuring a systematic effect rather
        // than luck — which is exactly what happened when costs were left on.
        assert!(m.pass_naive < m.trials / 2, "{} of {} cleared the conventional bar — this is measuring an effect, not luck", m.pass_naive, m.trials);
    }

    #[test]
    fn every_regime_reports_whether_it_matched_and_says_what_it_saw() {
        let out = run_regimes(1_000, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert_eq!(out.len(), 4);
        for r in &out {
            assert!(!r.expectation.is_empty(), "{} has no stated expectation", r.shape.label());
            assert!(!r.observed.is_empty(), "{} observed nothing", r.shape.label());
            assert!(!r.results.is_empty(), "{} produced no results", r.shape.label());
        }
        // The noise regime is the one that must hold, because it is the one where the truth is not
        // a matter of degree: there is nothing there.
        let noise = out.iter().find(|r| r.shape == Shape::Noise).expect("noise ran");
        assert!(noise.matched, "the harness found something in a random walk: {}", noise.observed);
    }

    #[test]
    fn simulated_data_is_marked_as_simulated_everywhere_it_goes() {
        // A simulated result that could be mistaken for a real one is worse than no result.
        let s = series_of(Shape::Trend, 300, 1);
        assert!(s.unverified());
        assert!(s.caveat().unwrap().contains("SIMULATED DATA"));
        assert_eq!(s.meta().source, "simulated");
        let e = evaluate(&s, &NullControl { seed: 1 }, &EvalOptions { min_trades: 1, ..EvalOptions::default() });
        assert!(e.caveats.iter().any(|c| c.contains("SIMULATED DATA")), "the caveat must travel into the result");
    }
}

//! The rate floor — the price below which working makes your situation worse.
//!
//! `viable` says what a month has to cover. This says what an HOUR has to earn to cover it, and it
//! exists because the two expensive mistakes in selling your time are both failures of arithmetic
//! rather than of nerve: taking underpriced work out of urgency, and not knowing which work is worth
//! the hours it costs.
//!
//! # Four things that make a naive rate roughly half of a real one
//!
//! 1. **Billable hours are not working hours.** Somebody working forty hours a week sells perhaps
//!    twenty to twenty-five; the rest is finding the work, quoting it, invoicing it, chasing the
//!    invoice, and revisions nobody is paying for. Dividing by hours WORKED is the single largest
//!    error here and it produces a floor about half of the true one.
//! 2. **Fifty-two weeks is a lie.** Holidays, illness, and the gaps between contracts are unpaid.
//! 3. **Contract income is not salary.** Self-employment tax, cover an employer used to provide,
//!    equipment, software, accounting — all of it comes out of the same number.
//! 4. **The month that has to be covered is the WORST one**, not the average, for exactly the reason
//!    `viable` measures on the worst month: a rate that clears the median misses the month with the
//!    annual renewal in it, and that month is a missed payment.
//!
//! Every one of these pushes the same direction, so getting them wrong is never conservative.
use crate::money::{money, Currency, Money};
use crate::viable::{Tier, ViableIncome};

pub struct RateInputs {
    /// Hours a week you can REALISTICALLY SELL. Not hours you can work.
    ///
    /// There is no default, for the same reason `runway` has none for discretionary spending: a
    /// number guessed here silently halves the answer.
    pub billable_hours_per_week: f64,
    /// Weeks a year you actually bill. The default is 46, not 52 — holidays, illness and the gaps
    /// between contracts are real and unpaid, and pricing as though they are not is how a year
    /// comes up six weeks short.
    pub working_weeks_per_year: f64,
    /// The fraction of gross that never reaches you: self-employment tax, income tax, whatever
    /// applies where you are.
    ///
    /// THIS IS A PLACEHOLDER AND NOT ADVICE. It is jurisdiction-specific and it is not something
    /// this can know — set it from what you actually pay. The default is deliberately a round
    /// number so it reads as an assumption rather than a calculation.
    pub tax_fraction: f64,
    /// Monthly costs of being self-employed that a job would have absorbed — health cover,
    /// equipment, software, accounting, insurance.
    pub overheads_monthly: Money,
}

impl RateInputs {
    pub fn new(billable_hours_per_week: f64, currency: Currency) -> Self {
        RateInputs { billable_hours_per_week, working_weeks_per_year: 46.0, tax_fraction: 0.25, overheads_monthly: money(0, currency) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct TierRate {
    pub tier: Tier,
    /// What this tier costs in its WORST month.
    pub monthly_need: Money,
    /// That need plus overheads, grossed up for what never reaches you.
    pub must_bill_monthly: Money,
    /// The rate below which working leaves you short.
    pub hourly: Money,
    /// Eight billable hours. A day rate is what most work is actually quoted at.
    pub day_rate: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct RateFloor {
    pub currency: Currency,
    pub billable_hours_per_month: f64,
    pub tiers: Vec<TierRate>,
    /// The one to quote: the rate that keeps everything CURRENT, which is the line below which new
    /// damage starts.
    pub headline: TierRate,
    /// The absolute floor — what cannot lapse. Below this, working is not solving the problem.
    pub floor: TierRate,
    pub assumptions: Vec<String>,
    pub warnings: Vec<String>,
}

/// Round UP. A rate floor rounded down is a rate below your floor.
fn ceil_div(numerator: f64, denominator: f64) -> i64 {
    if denominator <= 0.0 {
        return 0;
    }
    (numerator / denominator).ceil() as i64
}

/// What an hour has to earn, tier by tier.
///
/// Returns an error rather than a number when the inputs cannot support one — a rate floor computed
/// from a refused projection is a confident number resting on nothing.
pub fn rate_floor(v: &ViableIncome, inputs: &RateInputs) -> Result<RateFloor, String> {
    let currency = v.currency;
    if inputs.billable_hours_per_week <= 0.0 {
        return Err("billable hours must be greater than zero — how many hours a week can you actually SELL? Not hours you can work: somebody working forty sells perhaps twenty to twenty-five, and the rest is finding the work, quoting it, invoicing it and chasing payment".to_string());
    }
    if inputs.working_weeks_per_year <= 0.0 || inputs.working_weeks_per_year > 52.0 {
        return Err(format!("{} working weeks is not a year", inputs.working_weeks_per_year));
    }
    if inputs.tax_fraction < 0.0 || inputs.tax_fraction >= 1.0 {
        return Err(format!("a tax fraction of {} leaves nothing to live on — it is a fraction, so 0.25 is 25%", inputs.tax_fraction));
    }
    if inputs.overheads_monthly.currency != currency {
        return Err(format!("overheads are in {} but the ladder is in {}", inputs.overheads_monthly.currency, currency));
    }

    let billable_hours_per_month = inputs.billable_hours_per_week * inputs.working_weeks_per_year / 12.0;
    let keep = 1.0 - inputs.tax_fraction;

    let mut warnings: Vec<String> = Vec::new();
    if inputs.tax_fraction == 0.0 {
        warnings.push("tax was given as zero — contract income is not salary, and a floor that ignores what never reaches you is too low by exactly that fraction".to_string());
    }
    if inputs.overheads_monthly.minor == 0 {
        warnings.push("overheads were given as zero — health cover, equipment, software and accounting all come out of this same number when nobody else is paying them".to_string());
    }
    if inputs.billable_hours_per_week > 30.0 {
        warnings.push(format!(
            "{} billable hours a week is a high number to sustain — it is not the same as working {} hours, and if the real figure is lower every rate below is too low",
            inputs.billable_hours_per_week, inputs.billable_hours_per_week
        ));
    }
    if v.gaps.is_none() {
        warnings.push("no income projection was compared against this, so nothing here knows how much of the floor you already clear".to_string());
    }

    let build = |t: &crate::viable::TierRequirement| -> TierRate {
        let need = t.worst_month.minor + inputs.overheads_monthly.minor;
        let gross = need as f64 / keep;
        let hourly = ceil_div(gross, billable_hours_per_month);
        TierRate {
            tier: t.tier,
            monthly_need: t.worst_month,
            must_bill_monthly: money(gross.ceil() as i64, currency),
            hourly: money(hourly, currency),
            day_rate: money(hourly * 8, currency),
        }
    };

    let tiers: Vec<TierRate> = v.tiers.iter().map(build).collect();
    let headline = tiers.iter().find(|t| t.tier == Tier::Current).cloned().ok_or("the ladder has no `current` tier")?;
    let floor = tiers.iter().find(|t| t.tier == Tier::Survival).cloned().ok_or("the ladder has no `survival` tier")?;

    let assumptions = vec![
        format!(
            "{} billable hours a week over {} working weeks — {:.0} billable hours a month. Billable, not worked.",
            inputs.billable_hours_per_week, inputs.working_weeks_per_year, billable_hours_per_month
        ),
        format!("{:.0}% of gross never reaches you, so every rate is grossed up by that.", inputs.tax_fraction * 100.0),
        "Measured on each tier's WORST month, not its average — the same month `viable` measures, for the same reason.".to_string(),
        "Rounded UP at every step: a rate floor rounded down is a rate below your floor.".to_string(),
    ];

    Ok(RateFloor { currency, billable_hours_per_month, tiers, headline, floor, assumptions, warnings })
}

#[derive(Debug, Clone, PartialEq)]
pub struct OfferVerdict {
    /// The rate being offered.
    pub offered: Money,
    pub tier: Tier,
    /// Billable hours a month this offer needs to reach that tier.
    pub hours_needed: f64,
    /// Hours actually available in a month.
    pub hours_available: f64,
    /// Whether the offer can reach the tier AT ALL, at any achievable number of hours.
    pub reachable: bool,
    pub why: String,
}

/// What an offered rate would actually have to be worked to reach a tier.
///
/// THE FUNCTION THAT STOPS UNDERPRICED WORK. An offer below the floor is not merely a smaller
/// number — for a low enough rate there is no number of hours in a month that reaches the tier, and
/// working harder cannot fix it. Saying that plainly is the difference between negotiating and
/// grinding.
pub fn assess_offer(f: &RateFloor, offered: Money, tier: Tier) -> Result<OfferVerdict, String> {
    if offered.currency != f.currency {
        return Err(format!("the offer is in {} but the floor is in {}", offered.currency, f.currency));
    }
    let t = f.tiers.iter().find(|x| x.tier == tier).ok_or_else(|| format!("no `{}` tier", tier.label()))?;
    if offered.minor <= 0 {
        return Err("an offered rate of zero or less is not an offer".to_string());
    }
    let hours_needed = t.must_bill_monthly.minor as f64 / offered.minor as f64;
    let reachable = hours_needed <= f.billable_hours_per_month;
    let why = if reachable {
        format!(
            "{:.0} of your {:.0} billable hours a month reaches {} — it leaves {:.0} hours for everything else",
            hours_needed,
            f.billable_hours_per_month,
            tier.label(),
            f.billable_hours_per_month - hours_needed
        )
    } else {
        format!(
            "reaching {} at this rate needs {:.0} billable hours a month and you have {:.0} — working harder cannot close that, only a higher rate or a lower tier can",
            tier.label(),
            hours_needed,
            f.billable_hours_per_month
        )
    };
    Ok(OfferVerdict { offered, tier, hours_needed, hours_available: f.billable_hours_per_month, reachable, why })
}

/// One sentence, in the terms the question gets asked in.
pub fn summarise(f: &RateFloor) -> String {
    format!(
        "{} an hour keeps everything current, {} an hour is the floor below which working is not solving the problem — at {:.0} billable hours a month",
        crate::money::format_minor(f.headline.hourly.minor),
        crate::money::format_minor(f.floor.hourly.minor),
        f.billable_hours_per_month
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::viable::{TierRequirement, ViableIncome};

    // SYNTHETIC FIXTURES ONLY.
    fn tier(t: Tier, worst: i64, typical: i64) -> TierRequirement {
        TierRequirement {
            tier: t,
            typical_month: usd(typical),
            worst_month: usd(worst),
            worst_month_name: "2026-07".to_string(),
            includes: Vec::new(),
            excludes: Vec::new(),
        }
    }

    fn ladder() -> ViableIncome {
        let tiers = vec![
            tier(Tier::Survival, 149_503, 149_503),
            tier(Tier::Current, 151_102, 151_102),
            tier(Tier::Stable, 160_000, 160_000),
            tier(Tier::Progress, 180_000, 180_000),
        ];
        ViableIncome {
            currency: Currency::USD,
            from: "2026-07-01".to_string(),
            to: "2026-10-31".to_string(),
            floor: tiers[0].clone(),
            headline: tiers[1].clone(),
            tiers,
            gaps: None,
            notes: Vec::new(),
        }
    }

    fn inputs(hours: f64) -> RateInputs {
        RateInputs { tax_fraction: 0.25, overheads_monthly: usd(20_000), ..RateInputs::new(hours, Currency::USD) }
    }

    #[test]
    fn the_rate_is_computed_from_billable_hours_and_not_from_hours_worked() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        // 20 billable hours over 46 weeks is 76.67 a month, NOT the 173 a full-time month suggests.
        assert!((f.billable_hours_per_month - 76.666_666).abs() < 0.001, "got {}", f.billable_hours_per_month);
        // current: (151102 + 20000) / 0.75 = 228136 a month to bill, over 76.67 hours = 2975/hr.
        assert_eq!(f.headline.must_bill_monthly.minor, 228_136);
        assert_eq!(f.headline.hourly.minor, 2_976, "rounded UP — a floor rounded down is below the floor");
        assert_eq!(f.headline.day_rate.minor, 2_976 * 8);

        // THE ERROR THIS EXISTS TO PREVENT: dividing by hours WORKED instead of billed. At 40 hours
        // the same need produces a rate roughly half as large, and the difference is the whole
        // margin between solvent and not.
        let naive = rate_floor(&ladder(), &inputs(40.0)).expect("computes");
        assert!(naive.headline.hourly.minor < f.headline.hourly.minor / 2 + 100);
        assert!(naive.headline.hourly.minor * 2 >= f.headline.hourly.minor - 100);
    }

    #[test]
    fn the_year_is_forty_six_weeks_because_the_gaps_are_unpaid() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert_eq!(inputs(20.0).working_weeks_per_year, 46.0);
        // Pricing on 52 weeks produces a lower rate, and the six weeks it assumes you will bill are
        // holidays, illness and the gaps between contracts.
        let optimistic = RateInputs { working_weeks_per_year: 52.0, ..inputs(20.0) };
        let o = rate_floor(&ladder(), &optimistic).expect("computes");
        assert!(o.headline.hourly.minor < f.headline.hourly.minor, "a longer year should lower the rate, making it easier to come up short");
    }

    #[test]
    fn contract_income_is_grossed_up_because_it_is_not_salary() {
        let none = RateInputs { tax_fraction: 0.0, overheads_monthly: usd(0), ..inputs(20.0) };
        let f0 = rate_floor(&ladder(), &none).expect("computes");
        let f1 = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert!(f1.headline.hourly.minor > f0.headline.hourly.minor, "tax and overheads must RAISE the floor");
        // And both omissions are said out loud rather than silently applied.
        assert!(f0.warnings.iter().any(|w| w.contains("too low by exactly that fraction")));
        assert!(f0.warnings.iter().any(|w| w.contains("health cover, equipment, software and accounting")));
    }

    #[test]
    fn the_ladder_of_rates_matches_the_ladder_of_needs() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert_eq!(f.tiers.len(), 4);
        // Each rate is at least the one below it, because each need is.
        assert!(f.tiers.windows(2).all(|w| w[1].hourly.minor >= w[0].hourly.minor));
        // CURRENT is the headline — the line below which new damage starts — and SURVIVAL is the
        // floor, below which working is not solving the problem.
        assert_eq!(f.headline.tier, Tier::Current);
        assert_eq!(f.floor.tier, Tier::Survival);
        assert!(f.floor.hourly.minor < f.headline.hourly.minor);
        assert!(summarise(&f).contains("keeps everything current"));
    }

    #[test]
    fn an_offer_below_the_floor_cannot_be_worked_harder_into_working() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        // A good offer: comfortably reachable inside the hours available.
        let good = assess_offer(&f, usd(6_000), Tier::Current).expect("assesses");
        assert!(good.reachable);
        assert!((good.hours_needed - 38.02).abs() < 0.1, "got {}", good.hours_needed);
        assert!(good.why.contains("it leaves"));

        // A bad one: no achievable number of hours reaches the tier. That is the sentence that
        // stops somebody grinding at a rate that cannot work.
        let bad = assess_offer(&f, usd(1_800), Tier::Current).expect("assesses");
        assert!(!bad.reachable);
        assert!(bad.hours_needed > f.billable_hours_per_month);
        assert!(bad.why.contains("working harder cannot close that, only a higher rate or a lower tier can"));

        // The same offer against a LOWER tier may still be reachable — which is the negotiation.
        let survival = assess_offer(&f, usd(2_400), Tier::Survival).expect("assesses");
        assert!(survival.hours_needed < assess_offer(&f, usd(2_400), Tier::Progress).unwrap().hours_needed);
    }

    #[test]
    fn inputs_that_cannot_support_a_rate_are_refused_rather_than_answered() {
        let l = ladder();
        // Guessing this is the whole error, so there is no default and zero is not one.
        let e = rate_floor(&l, &RateInputs::new(0.0, Currency::USD)).unwrap_err();
        assert!(e.contains("how many hours a week can you actually SELL"));
        assert!(rate_floor(&l, &RateInputs { working_weeks_per_year: 60.0, ..inputs(20.0) }).is_err());
        assert!(rate_floor(&l, &RateInputs { working_weeks_per_year: 0.0, ..inputs(20.0) }).is_err());
        // A "tax fraction" of 25 rather than 0.25 would silently produce a negative rate.
        let e2 = rate_floor(&l, &RateInputs { tax_fraction: 25.0, ..inputs(20.0) }).unwrap_err();
        assert!(e2.contains("it is a fraction, so 0.25 is 25%"));
        // And a currency mismatch is refused rather than added anyway.
        let eur = Currency::new("EUR").expect("code");
        assert!(rate_floor(&l, &RateInputs { overheads_monthly: money(1_000, eur), ..inputs(20.0) }).is_err());
        assert!(assess_offer(&rate_floor(&l, &inputs(20.0)).unwrap(), money(5_000, eur), Tier::Current).is_err());
        assert!(assess_offer(&rate_floor(&l, &inputs(20.0)).unwrap(), usd(0), Tier::Current).is_err());
    }

    #[test]
    fn every_assumption_that_drives_the_answer_is_written_down() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert_eq!(f.assumptions.len(), 4);
        assert!(f.assumptions[0].contains("Billable, not worked"));
        assert!(f.assumptions.iter().any(|a| a.contains("WORST month")));
        assert!(f.assumptions.iter().any(|a| a.contains("Rounded UP")));
        // A high billable figure is flagged, because it is the input most likely to be optimistic.
        let hopeful = rate_floor(&ladder(), &inputs(35.0)).expect("computes");
        assert!(hopeful.warnings.iter().any(|w| w.contains("is a high number to sustain")));
    }

    #[test]
    fn a_ladder_with_no_income_comparison_says_so() {
        let f = rate_floor(&ladder(), &inputs(20.0)).expect("computes");
        assert!(f.warnings.iter().any(|w| w.contains("nothing here knows how much of the floor you already clear")));
    }
}

//! Short positions — what you can take, what it costs to carry, and the price that ends it.
//!
//! Three numbers decide whether a short works, and the one people compute is the least important.
//!
//! 1. **The margin call price.** A short is not a bet that ends when you are proved right or wrong;
//!    it ends when the broker says so. At the Regulation T maximum, a **15.4% rise closes the
//!    position** — you are out whether or not the thesis was correct. This module leads with that
//!    number because it is the one that actually determines the outcome.
//! 2. **The carry.** Borrow fees accrue daily and you owe every dividend the stock pays while you
//!    are short. A thesis that is right in eighteen months can lose to eighteen months of carry.
//! 3. **The profit**, which is the number everyone starts with and which is bounded above by 100%
//!    — the stock can only go to zero — while the loss has no bound at all.
//!
//! # Maximum loss on a naked short is ABSENT, not large
//!
//! There is no number, because the price has no ceiling. [`Exposure::max_loss`] is `None` for a
//! naked short and `Some` for a put, and that difference is the entire argument for the put. A
//! module that returned a big number here would be inviting somebody to plan around it.
use crate::money::{money, Currency, Money};

/// How the short is expressed. The vehicles differ in what can go wrong, which is the point.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Vehicle {
    /// Borrow the shares and sell them. Unlimited loss, margin required, borrow fees, and you owe
    /// the dividends.
    Naked,
    /// Buy a put. Loss is capped at the premium and there is no margin, no borrow and no dividend
    /// liability — you pay for all of that up front in the premium.
    Put,
    /// Buy an inverse fund. No margin, loss capped at what you put in — and it REBALANCES DAILY, so
    /// over more than a day or two it drifts away from the index return in a way that is not a fee
    /// and not a mistake, but is a real cost. See [`inverse_drift`].
    InverseEtf,
}

impl Vehicle {
    pub fn label(self) -> &'static str {
        match self {
            Vehicle::Naked => "naked short",
            Vehicle::Put => "put",
            Vehicle::InverseEtf => "inverse ETF",
        }
    }
}

pub struct MarginRules {
    /// Your own share of the position at entry. Regulation T is 0.50 — $5,000 of equity shorts
    /// $10,000 of stock.
    pub initial: f64,
    /// Equity that must be maintained against the position's CURRENT value. FINRA's floor is 0.25
    /// and brokers commonly require 0.30 or more, which is why the default here is the stricter one:
    /// a call price computed at the regulatory minimum is later than the one you will actually get.
    pub maintenance: f64,
}

impl Default for MarginRules {
    fn default() -> Self {
        MarginRules { initial: 0.50, maintenance: 0.30 }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Capacity {
    pub equity: Money,
    pub price: Money,
    /// The largest position Regulation T allows against this equity.
    pub max_position: Money,
    pub max_shares: i64,
    /// The price at which a maintenance call arrives on a position of `shares`.
    pub margin_call_price: Money,
    /// How far the stock may rise first, as a fraction. THE number to look at.
    pub headroom: f64,
    pub notes: Vec<String>,
}

/// What you may short, and the price at which it ends.
///
/// The call price solves `equity + shares·entry = shares·price·(1 + maintenance)` — the point where
/// account equity falls to the maintenance requirement. Below the maximum position the headroom is
/// larger; at the maximum it is about 15%, which is less than a bad week.
pub fn capacity(equity: Money, price: Money, shares: Option<i64>, rules: &MarginRules) -> Result<Capacity, String> {
    if equity.minor <= 0 {
        return Err("no equity, so no position — a short is collateral before it is a trade".to_string());
    }
    if price.minor <= 0 {
        return Err("a price of zero or less is not a price".to_string());
    }
    if equity.currency != price.currency {
        return Err(format!("equity is in {} and the price is in {}", equity.currency, price.currency));
    }
    if rules.initial <= 0.0 || rules.initial > 1.0 {
        return Err(format!("an initial margin of {} is not a fraction between 0 and 1", rules.initial));
    }
    if rules.maintenance <= 0.0 || rules.maintenance >= 1.0 {
        return Err(format!("a maintenance margin of {} is not a fraction between 0 and 1", rules.maintenance));
    }

    let cur = equity.currency;
    let max_position_minor = (equity.minor as f64 / rules.initial).floor() as i64;
    let max_shares = max_position_minor / price.minor.max(1);
    let n = shares.unwrap_or(max_shares);
    let mut notes: Vec<String> = Vec::new();

    if n <= 0 {
        return Err(format!(
            "{} of equity does not reach one share at {} — Regulation T needs {} of your own money per {} shorted",
            crate::money::format_minor(equity.minor),
            crate::money::format_minor(price.minor),
            crate::money::format_minor((price.minor as f64 * rules.initial).ceil() as i64),
            crate::money::format_minor(price.minor)
        ));
    }
    if n > max_shares {
        notes.push(format!(
            "{n} shares exceeds the {max_shares} Regulation T allows on this equity — the figures below are for a position you could not open"
        ));
    }
    // A US margin account needs $2,000 of equity before it may short at all, whatever the
    // arithmetic above says. Stated rather than silently assumed away.
    if equity.minor < 200_000 {
        notes.push("a US margin account requires $2,000 of equity before it may short at all, regardless of position size".to_string());
    }

    let call = (equity.minor as f64 + (n * price.minor) as f64) / (n as f64 * (1.0 + rules.maintenance));
    let call_minor = call.floor() as i64;
    let headroom = (call_minor as f64 - price.minor as f64) / price.minor as f64;

    Ok(Capacity {
        equity,
        price,
        max_position: money(max_position_minor, cur),
        max_shares,
        margin_call_price: money(call_minor, cur),
        headroom,
        notes,
    })
}

pub struct Carry {
    /// Annualised stock borrow rate. Hard-to-borrow names run well above 0.10 and can exceed 1.0.
    pub borrow_apr: f64,
    /// Dividends per share you expect to owe over the holding period. You pay these while short.
    pub dividends_per_share: Money,
    pub days_held: i64,
    /// Commission and fees, round trip, in total.
    pub commission: Money,
}

impl Carry {
    pub fn new(currency: Currency) -> Self {
        Carry { borrow_apr: 0.0, dividends_per_share: money(0, currency), days_held: 0, commission: money(0, currency) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Outcome {
    pub at_price: Money,
    /// Move in the underlying, as a fraction.
    pub move_pct: f64,
    /// Before any cost.
    pub gross: Money,
    pub borrow_cost: Money,
    pub dividends_owed: Money,
    pub commission: Money,
    pub net: Money,
    /// Net over the equity actually put up.
    pub return_on_equity: f64,
    /// FALSE when this price is at or beyond the margin call — the position ended before here, so
    /// the profit column is describing something that did not happen to you.
    pub reachable: bool,
}

/// What the position is worth at a given price, after carry.
pub fn outcome_at(cap: &Capacity, shares: i64, at: Money, carry: &Carry) -> Outcome {
    let cur = cap.equity.currency;
    let gross = shares * (cap.price.minor - at.minor);
    // Borrow accrues on the position's value, day by day. Approximated on the ENTRY value, which is
    // conservative while the trade is winning and optimistic while it is losing — stated rather
    // than modelled precisely, because the exact convention varies by broker.
    let borrow = ((shares * cap.price.minor) as f64 * carry.borrow_apr * carry.days_held as f64 / 365.0).round() as i64;
    let divs = shares * carry.dividends_per_share.minor;
    let net = gross - borrow - divs - carry.commission.minor;
    Outcome {
        at_price: at,
        move_pct: (at.minor - cap.price.minor) as f64 / cap.price.minor as f64,
        gross: money(gross, cur),
        borrow_cost: money(borrow, cur),
        dividends_owed: money(divs, cur),
        commission: carry.commission,
        net: money(net, cur),
        return_on_equity: net as f64 / cap.equity.minor as f64,
        reachable: at.minor < cap.margin_call_price.minor,
    }
}

/// The scenario table: what happens across a ladder of moves, and which ones you never reach.
///
/// The unreachable rows are KEPT rather than filtered, because seeing that +30% is past your call
/// price is the entire point — a table that stopped at the call would hide how ordinary a move it is.
pub fn ladder(cap: &Capacity, shares: i64, moves: &[f64], carry: &Carry) -> Vec<Outcome> {
    moves
        .iter()
        .map(|m| outcome_at(cap, shares, money(((cap.price.minor as f64) * (1.0 + m)).round() as i64, cap.equity.currency), carry))
        .collect()
}

#[derive(Debug, Clone, PartialEq)]
pub struct Exposure {
    pub vehicle: Vehicle,
    /// What it costs to put on.
    pub capital_at_risk: Money,
    /// ABSENT for a naked short, because the price has no ceiling. This is the whole argument for
    /// the put, and it is represented as absence rather than as a large number.
    pub max_loss: Option<Money>,
    /// Bounded for every short: the stock can only reach zero.
    pub max_gain: Money,
    pub needs_margin: bool,
    pub note: &'static str,
}

/// The same bearish view expressed three ways, so the trade-off is a table rather than an argument.
pub fn compare(price: Money, shares: i64, put_premium: Money, put_strike: Money, contracts: i64, etf_stake: Money) -> Vec<Exposure> {
    let cur = price.currency;
    vec![
        Exposure {
            vehicle: Vehicle::Naked,
            capital_at_risk: money((shares * price.minor) / 2, cur),
            // NO NUMBER. The price has no ceiling and inventing a bound here would invite somebody
            // to size against it.
            max_loss: None,
            max_gain: money(shares * price.minor, cur),
            needs_margin: true,
            note: "loss has no ceiling, and the broker closes it at the call price rather than when you are proved wrong",
        },
        Exposure {
            vehicle: Vehicle::Put,
            capital_at_risk: money(put_premium.minor * 100 * contracts, cur),
            max_loss: Some(money(put_premium.minor * 100 * contracts, cur)),
            max_gain: money(put_strike.minor * 100 * contracts - put_premium.minor * 100 * contracts, cur),
            needs_margin: false,
            note: "the most you can lose is what you paid — that is what the premium buys, and it expires whether or not you were right",
        },
        Exposure {
            vehicle: Vehicle::InverseEtf,
            capital_at_risk: etf_stake,
            max_loss: Some(etf_stake),
            max_gain: etf_stake,
            needs_margin: false,
            note: "no margin and a bounded loss, but it rebalances DAILY and drifts from the index over any longer horizon",
        },
    ]
}

/// What a put is worth at expiry, and where it breaks even.
///
/// `None` for `max_loss` never appears here: the loss is the premium, always, which is the reason
/// this vehicle exists.
pub fn put_payoff(strike: Money, premium: Money, contracts: i64, at: Money) -> Money {
    let intrinsic = (strike.minor - at.minor).max(0);
    money((intrinsic - premium.minor) * 100 * contracts, strike.currency)
}

pub fn put_breakeven(strike: Money, premium: Money) -> Money {
    money(strike.minor - premium.minor, strike.currency)
}

/// Where a daily-rebalanced inverse fund ends up over a PATH, against where a naive reading expects.
///
/// A `-3x` fund does not deliver `-3 ×` the period return over more than one day, and the gap is not
/// a fee — it is compounding. Up 10% then down 9.09% leaves the index flat and a 3x inverse fund
/// down about 11%. Over a choppy year this is the dominant term, and it is why these are built for
/// single-day holds.
pub fn inverse_drift(daily_returns: &[f64], multiple: f64) -> (f64, f64) {
    let index = daily_returns.iter().fold(1.0, |v, r| v * (1.0 + r)) - 1.0;
    let fund = daily_returns.iter().fold(1.0, |v, r| v * (1.0 + multiple * -r)) - 1.0;
    // What somebody reading the label expects, and what compounding actually produced.
    (-multiple * index, fund)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    fn rules() -> MarginRules {
        MarginRules::default()
    }

    #[test]
    fn regulation_t_lets_you_short_twice_your_equity_and_no_more() {
        let c = capacity(usd(500_000), usd(10_000), None, &rules()).expect("computes");
        // $5,000 of equity shorts $10,000 of stock — the 50% is YOUR half; the other half is the
        // sale proceeds, which are not yours.
        assert_eq!(c.max_position.minor, 1_000_000);
        assert_eq!(c.max_shares, 100);
    }

    #[test]
    fn a_maxed_out_short_is_closed_by_a_fifteen_percent_rise() {
        // THE NUMBER NOBODY COMPUTES, and the one that decides the trade. Hand-checked:
        // (5000 + 100·100) / (100 · 1.30) = 115.3846
        let c = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        assert_eq!(c.margin_call_price.minor, 11_538, "115.3846 dollars, floored to the cent");
        assert!((c.headroom - 0.153846).abs() < 0.0001, "got {}", c.headroom);
        // A short is not a bet that ends when you are proved wrong. It ends when the broker says so,
        // and 15% is less than a bad week.
        assert!(c.headroom < 0.16);
    }

    #[test]
    fn a_smaller_position_buys_headroom_and_that_is_the_only_thing_that_does() {
        let full = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        let half = capacity(usd(500_000), usd(10_000), Some(50), &rules()).expect("computes");
        let quarter = capacity(usd(500_000), usd(10_000), Some(25), &rules()).expect("computes");
        assert!(half.headroom > full.headroom);
        assert!(quarter.headroom > half.headroom);
        // Halving the position more than doubles the survivable move — which is the argument for
        // sizing well under the maximum rather than at it.
        assert!(half.headroom > full.headroom * 2.0);
    }

    #[test]
    fn a_stricter_maintenance_requirement_brings_the_call_closer() {
        let finra_floor = capacity(usd(500_000), usd(10_000), Some(100), &MarginRules { initial: 0.50, maintenance: 0.25 }).expect("computes");
        let broker = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        // The default is the stricter 30% on purpose: a call price computed at FINRA's 25% floor is
        // LATER than the one your broker will actually give you.
        assert!(broker.margin_call_price.minor < finra_floor.margin_call_price.minor);
    }

    #[test]
    fn the_two_thousand_dollar_floor_is_stated_rather_than_assumed_away() {
        let small = capacity(usd(50_000), usd(1_000), None, &rules()).expect("computes");
        assert!(small.notes.iter().any(|n| n.contains("$2,000 of equity before it may short at all")));
        let fine = capacity(usd(500_000), usd(10_000), None, &rules()).expect("computes");
        assert!(!fine.notes.iter().any(|n| n.contains("$2,000")));
    }

    #[test]
    fn carry_is_charged_and_a_slow_thesis_pays_for_being_slow() {
        let c = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        // Right by 20%, but held a year at a 12% borrow with a dividend to cover.
        let carry = Carry { borrow_apr: 0.12, dividends_per_share: usd(200), days_held: 365, commission: usd(1_000) };
        let o = outcome_at(&c, 100, usd(8_000), &carry);
        assert_eq!(o.gross.minor, 200_000, "20 points on 100 shares");
        assert_eq!(o.borrow_cost.minor, 120_000, "12% of a 10000 position for a year");
        assert_eq!(o.dividends_owed.minor, 20_000, "$2 a share, and you owe it");
        assert_eq!(o.net.minor, 200_000 - 120_000 - 20_000 - 1_000);
        // Being right by twenty percent nets under a third of the gross once the carry is paid.
        assert!(o.net.minor * 3 < o.gross.minor * 2);
    }

    #[test]
    fn the_scenario_ladder_marks_the_rows_you_never_reach() {
        let c = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        let rows = ladder(&c, 100, &[-0.50, -0.25, -0.10, 0.0, 0.10, 0.25, 0.50], &Carry::new(Currency::USD));
        assert_eq!(rows.len(), 7);
        // Everything at or below +15% is live; +25% and +50% are past the call and the position
        // ended before them. The rows are KEPT so that is visible rather than filtered away.
        assert!(rows[0].reachable && rows[4].reachable);
        assert!(!rows[5].reachable, "+25% is past the call price");
        assert!(!rows[6].reachable, "+50% certainly is");
        // The profit column on an unreachable row is describing something that did not happen.
        assert!(rows[6].net.minor < 0);
    }

    #[test]
    fn the_maximum_loss_on_a_naked_short_is_absent_and_on_a_put_it_is_a_number() {
        let ex = compare(usd(10_000), 100, usd(500), usd(9_500), 1, usd(100_000));
        let naked = &ex[0];
        let put = &ex[1];
        // THE WHOLE ARGUMENT FOR THE PUT, expressed as the presence or absence of a number rather
        // than as a large one — a big figure here would invite somebody to size against it.
        assert!(naked.max_loss.is_none());
        assert_eq!(put.max_loss, Some(usd(50_000)), "the premium, and nothing more");
        assert!(naked.needs_margin && !put.needs_margin);
        // And the gain is bounded either way: the stock can only reach zero.
        assert_eq!(naked.max_gain.minor, 1_000_000);
    }

    #[test]
    fn a_put_breaks_even_below_the_strike_by_the_premium() {
        let (strike, premium) = (usd(9_500), usd(500));
        assert_eq!(put_breakeven(strike, premium).minor, 9_000);
        // At the breakeven it returns nothing; below it, it pays; above the strike the loss is the
        // premium and stops there however far the stock runs.
        assert_eq!(put_payoff(strike, premium, 1, usd(9_000)).minor, 0);
        assert_eq!(put_payoff(strike, premium, 1, usd(8_000)).minor, 100_000, "15 of intrinsic less the 5 premium, over 100 shares");
        assert_eq!(put_payoff(strike, premium, 1, usd(9_500)).minor, -50_000);
        assert_eq!(put_payoff(strike, premium, 1, usd(50_000)).minor, -50_000, "it stops at the premium");
    }

    #[test]
    fn a_daily_rebalanced_inverse_fund_loses_money_on_a_flat_index() {
        // Up 10%, then down 9.0909% — the index ends exactly where it began.
        let path = [0.10, -0.090909];
        let (expected, actual) = inverse_drift(&path, 3.0);
        assert!(expected.abs() < 0.0001, "the index is flat, so the label promises nothing: {expected}");
        // And the fund is down about 11%. That is not a fee and it is not an error — it is
        // compounding, and over a choppy year it is the dominant term.
        assert!((actual - -0.109091).abs() < 0.0001, "got {actual}");
        assert!(actual < -0.10);
    }

    #[test]
    fn over_a_single_day_the_inverse_fund_does_what_the_label_says() {
        let (expected, actual) = inverse_drift(&[0.02], 3.0);
        assert!((expected - actual).abs() < 1e-12, "one day is exactly -3x, which is the only horizon it promises");
        // Two days of a trend still track closely; it is CHOP that costs, not direction.
        let (e2, a2) = inverse_drift(&[-0.01, -0.01], 3.0);
        assert!(a2 > e2, "a sustained move compounds in your favour: {a2} vs {e2}");
    }

    #[test]
    fn inputs_that_cannot_support_a_position_are_refused() {
        assert!(capacity(usd(0), usd(10_000), None, &rules()).is_err());
        assert!(capacity(usd(500_000), usd(0), None, &rules()).is_err());
        assert!(capacity(usd(500_000), usd(10_000), None, &MarginRules { initial: 0.0, maintenance: 0.30 }).is_err());
        assert!(capacity(usd(500_000), usd(10_000), None, &MarginRules { initial: 0.5, maintenance: 1.5 }).is_err());
        // Equity too small for a single share is refused with the arithmetic that shows why.
        let e = capacity(usd(100), usd(10_000), None, &rules()).unwrap_err();
        assert!(e.contains("does not reach one share"));
        // A position larger than Regulation T allows still computes, and says it could not be opened.
        let over = capacity(usd(500_000), usd(10_000), Some(500), &rules()).expect("computes");
        assert!(over.notes.iter().any(|n| n.contains("could not open")));
    }
}

//! Invoices, and the bank credit that matches them.
//!
//! This is the half of getting paid that no processor is needed for. A customer pushes money to your
//! account; the invoice says what was owed and why; and something has to decide that THIS credit is
//! THAT invoice. Issuing is bookkeeping. The matching is where the judgement lives.
//!
//! # An ambiguous match is reported, never resolved
//!
//! Two invoices to the same client for the same amount are genuinely indistinguishable when a single
//! payment arrives with no reference. Picking the earlier one would be a coin flip wearing a
//! decision's clothes, and the cost lands months later when one is chased that was already paid. So
//! [`match_payments`] returns them as AMBIGUOUS with the competing candidates named, and the only
//! thing that resolves it is a human or a reference number.
//!
//! # Cash basis and accrual basis are different numbers and both are reported
//!
//! What you INVOICED in a period and what you RECEIVED in it are not the same, and which one your
//! tax return wants depends on the basis you file on. Reporting one silently would be picking a tax
//! treatment on somebody's behalf, so [`revenue`] returns both and labels them.
use crate::jurisdiction::{self, Supply, Taxability};
use crate::money::{money, Currency, Money};
use crate::txn::{days_between, Txn};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    /// Written but not sent. Owes nothing and counts toward nothing.
    Draft,
    Issued,
    /// Something arrived, and it was not the whole amount.
    PartlyPaid,
    Paid,
    /// Abandoned deliberately, with a reason. NOT the same as unpaid.
    WrittenOff,
}

impl State {
    pub fn label(self) -> &'static str {
        match self {
            State::Draft => "draft",
            State::Issued => "issued",
            State::PartlyPaid => "partly-paid",
            State::Paid => "paid",
            State::WrittenOff => "written-off",
        }
    }

    /// Whether money is still expected. A draft is not owed and a write-off is not owed.
    pub fn is_outstanding(self) -> bool {
        matches!(self, State::Issued | State::PartlyPaid)
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Invoice {
    /// The reference a payer should quote. THE strongest matching signal there is, which is why it
    /// belongs on the invoice in a form a bank will not mangle.
    pub number: String,
    pub client: String,
    /// `YYYY-MM-DD`.
    pub issued: String,
    pub due: String,
    pub amount: Money,
    pub description: String,
    pub state: State,
    /// Why it was abandoned. Present only for a write-off, and required for one.
    pub write_off_reason: Option<String>,
    /// WHAT was sold. `None` means the invoice does not say — which is not the same as a service,
    /// and is why [`price`] returns undetermined rather than assuming the common case.
    pub supply: Option<Supply>,
    /// WHERE the customer is. Sales tax follows them, not you.
    pub buyer_place: Option<String>,
}

impl Invoice {
    pub fn new(number: &str, client: &str, issued: &str, due: &str, amount: Money, description: &str) -> Invoice {
        Invoice {
            number: number.to_string(),
            client: client.to_string(),
            issued: issued.to_string(),
            due: due.to_string(),
            amount,
            description: description.to_string(),
            state: State::Issued,
            write_off_reason: None,
            supply: None,
            buyer_place: None,
        }
    }

    /// Record what was sold and where it went. Separate from [`Invoice::new`] because an invoice is
    /// legitimately raised before either is settled, and a constructor demanding them would push
    /// callers into passing a placeholder — which is the guess this module exists to avoid.
    pub fn sold(mut self, supply: Supply, buyer_place: Option<&str>) -> Invoice {
        self.supply = Some(supply);
        self.buyer_place = buyer_place.map(str::to_string);
        self
    }
}

/// What tax this invoice carries, or why that cannot be said.
#[derive(Debug, Clone, PartialEq)]
pub enum TaxOutcome {
    Charged { bps: i64, amount: Money, sources: Vec<String> },
    /// Legitimately nothing, WITH the reason — which is what somebody asking wants to see, and what
    /// a bare zero cannot supply.
    None { reason: String, source: String },
    /// Not zero. The difference between "this is exempt" and "nobody recorded enough to say" is the
    /// difference between an invoice you can defend and one you cannot.
    Undetermined { what: String, where_to: String },
}

#[derive(Debug, Clone, PartialEq)]
pub struct Priced {
    pub invoice: String,
    pub net: Money,
    pub tax: TaxOutcome,
    /// `None` when the tax is undetermined. A total you cannot compute must not be printed as if the
    /// tax were zero — that is a number somebody would send to a customer.
    pub total: Option<Money>,
}

/// Price an invoice: net, tax, and a total only when the tax is actually known.
pub fn price(
    inv: &Invoice,
    seller_place: &str,
    rates: &[jurisdiction::Rate],
    places: &[jurisdiction::Place],
    on: &str,
) -> Result<Priced, String> {
    let undetermined = |what: String, where_to: &str| Priced {
        invoice: inv.number.clone(),
        net: inv.amount,
        tax: TaxOutcome::Undetermined { what, where_to: where_to.to_string() },
        total: None,
    };
    let Some(supply) = inv.supply else {
        return Ok(undetermined(
            format!("{} does not record WHAT was sold", inv.number),
            "set it with `bsc fin invoice new … --supply <service|good|digital|saas>` — taxability turns on the kind of supply, so it cannot be inferred from the amount",
        ));
    };
    let t = jurisdiction::taxability_for_sale(rates, places, seller_place, inv.buyer_place.as_deref(), supply, on)?;
    Ok(match t {
        Taxability::Exempt { reason, source } => Priced {
            invoice: inv.number.clone(),
            net: inv.amount,
            tax: TaxOutcome::None { reason: reason.to_string(), source: source.to_string() },
            // Exempt is a KNOWN zero, so the total is the net and is safe to print.
            total: Some(inv.amount),
        },
        Taxability::Taxable { bps, sources } => {
            let amount = jurisdiction::apply_bps(inv.amount, bps);
            Priced {
                invoice: inv.number.clone(),
                net: inv.amount,
                tax: TaxOutcome::Charged { bps, amount, sources: sources.iter().map(|s| (*s).to_string()).collect() },
                total: Some(money(inv.amount.minor + amount.minor, inv.amount.currency)),
            }
        }
        Taxability::Unknown { what_to_check, where_to_check } => undetermined(what_to_check, where_to_check),
    })
}

/// How confident the match is, and therefore whether a human needs to look.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Confidence {
    /// The invoice number appears in the payment description. Nothing beats this.
    Reference,
    /// The amount is exact and only one invoice could be it.
    ExactAmount,
    /// The amount is exact but SEVERAL invoices fit. Reported, not resolved.
    Ambiguous,
}

impl Confidence {
    pub fn label(self) -> &'static str {
        match self {
            Confidence::Reference => "reference",
            Confidence::ExactAmount => "exact-amount",
            Confidence::Ambiguous => "ambiguous",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Matched {
    pub invoice: String,
    pub date: String,
    pub amount: Money,
    pub confidence: Confidence,
    /// What the description actually said, so the match can be checked rather than trusted.
    pub evidence: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Ambiguity {
    pub date: String,
    pub amount: Money,
    pub description: String,
    /// Every invoice this credit could equally be. Naming them IS the output.
    pub candidates: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MatchResult {
    pub matched: Vec<Matched>,
    /// Credits that fit several invoices equally well. A human or a reference resolves these.
    pub ambiguous: Vec<Ambiguity>,
    /// Money that arrived and belongs to no invoice — a refund, a transfer, or an invoice you never
    /// raised. Reported rather than dropped.
    pub unexplained: Vec<Txn>,
    pub notes: Vec<String>,
}

/// Strip everything a bank might mangle, so `INV-2026-014` still matches `INV2026014`.
fn squash(s: &str) -> String {
    s.chars().filter(|c| c.is_alphanumeric()).collect::<String>().to_uppercase()
}

pub struct MatchOptions {
    /// A credit dated more than this many days before an invoice's issue date cannot be its payment.
    /// Small and non-zero because bank value dates drift by a day or two.
    pub grace_days: i64,
}

impl Default for MatchOptions {
    fn default() -> Self {
        MatchOptions { grace_days: 2 }
    }
}

/// Match incoming credits against outstanding invoices.
///
/// Reference first, then exact amount, and each credit claims AT MOST ONE invoice while each invoice
/// is claimed AT MOST ONCE — the same discipline `spending` uses for transfer pairing, and for the
/// same reason: without it two invoices of equal value both match one payment and one gets chased
/// after it was already settled.
pub fn match_payments(invoices: &[Invoice], credits: &[Txn], opts: &MatchOptions) -> MatchResult {
    let mut matched: Vec<Matched> = Vec::new();
    let mut ambiguous: Vec<Ambiguity> = Vec::new();
    let mut unexplained: Vec<Txn> = Vec::new();
    let mut notes: Vec<String> = Vec::new();
    let mut claimed: Vec<String> = Vec::new();

    let open: Vec<&Invoice> = invoices.iter().filter(|i| i.state.is_outstanding()).collect();
    if open.is_empty() && !credits.is_empty() {
        notes.push("no invoice is outstanding, so every credit below is unexplained by construction rather than by failure to match".to_string());
    }

    // TWO PASSES, AND THE ORDER IS THE POINT. Resolving each credit in turn let an amount-only
    // match claim an invoice that a LATER credit named explicitly — measured end to end: an
    // unreferenced 2400.00 took INV-015, and the payment whose description actually said
    // "REF INV-015" was then reported as belonging to no invoice. A reference is strictly stronger
    // evidence than a coinciding amount, so every reference is resolved before any amount is.
    let incoming: Vec<&Txn> = credits.iter().filter(|t| t.amount.minor > 0).collect();
    let mut by_reference: Vec<usize> = Vec::new();

    for (n, t) in incoming.iter().enumerate() {
        let desc = squash(&t.description);
        let plausible = |i: &Invoice| days_between(&i.issued, &t.date) >= -opts.grace_days;
        let hit = open
            .iter()
            .find(|i| !claimed.contains(&i.number) && plausible(i) && !squash(&i.number).is_empty() && desc.contains(&squash(&i.number)));
        if let Some(i) = hit {
            claimed.push(i.number.clone());
            by_reference.push(n);
            matched.push(Matched {
                invoice: i.number.clone(),
                date: t.date.clone(),
                amount: t.amount,
                confidence: Confidence::Reference,
                evidence: t.description.clone(),
            });
        }
    }

    for (n, t) in incoming.iter().enumerate() {
        if by_reference.contains(&n) {
            continue;
        }
        // A credit cannot pay an invoice that did not exist yet. The grace window absorbs bank value
        // dates without opening the door to matching a payment to a later invoice entirely.
        let plausible = |i: &Invoice| days_between(&i.issued, &t.date) >= -opts.grace_days;

        // The exact amount, but only when exactly one invoice could be it.
        let fits: Vec<&&Invoice> = open.iter().filter(|i| !claimed.contains(&i.number) && plausible(i) && i.amount.minor == t.amount.minor).collect();
        match fits.len() {
            1 => {
                let i = fits[0];
                claimed.push(i.number.clone());
                matched.push(Matched {
                    invoice: i.number.clone(),
                    date: t.date.clone(),
                    amount: t.amount,
                    confidence: Confidence::ExactAmount,
                    evidence: t.description.clone(),
                });
            }
            0 => unexplained.push((*t).clone()),
            _ => {
                // GENUINELY INDISTINGUISHABLE. Picking one is a coin flip that costs somebody a
                // chased invoice months later, so the candidates are named and nothing is decided.
                ambiguous.push(Ambiguity {
                    date: t.date.clone(),
                    amount: t.amount,
                    description: t.description.clone(),
                    candidates: fits.iter().map(|i| i.number.clone()).collect(),
                });
            }
        }
    }

    // The two passes produce references first; a reader expects date order, and the pass a match
    // came from is already recorded as its confidence.
    matched.sort_by(|a, b| a.date.cmp(&b.date).then_with(|| a.invoice.cmp(&b.invoice)));

    if !ambiguous.is_empty() {
        notes.push(format!(
            "{} credit(s) fit more than one invoice equally — put the invoice NUMBER on the invoice and ask payers to quote it, and this stops happening",
            ambiguous.len()
        ));
    }
    if !unexplained.is_empty() {
        notes.push(format!("{} credit(s) match no outstanding invoice — a refund, a transfer, or work you never invoiced", unexplained.len()));
    }

    MatchResult { matched, ambiguous, unexplained, notes }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Settlement {
    pub invoice: String,
    pub client: String,
    pub billed: Money,
    pub received: Money,
    /// POSITIVE when money is still owed, NEGATIVE when they overpaid.
    pub outstanding: Money,
    pub state: State,
}

/// Apply matched payments to invoices and say what each one is actually owed.
///
/// A partial payment leaves the invoice PARTLY PAID with the shortfall named, rather than being
/// rounded up to paid — the missing amount is the whole point and it is the thing to chase.
pub fn settle(invoices: &[Invoice], m: &MatchResult, currency: Currency) -> Vec<Settlement> {
    invoices
        .iter()
        .map(|i| {
            let received: i64 = m.matched.iter().filter(|p| p.invoice == i.number).map(|p| p.amount.minor).sum();
            let outstanding = i.amount.minor - received;
            let state = match i.state {
                State::Draft | State::WrittenOff => i.state,
                _ if received == 0 => State::Issued,
                _ if outstanding > 0 => State::PartlyPaid,
                _ => State::Paid,
            };
            Settlement {
                invoice: i.number.clone(),
                client: i.client.clone(),
                billed: i.amount,
                received: money(received, currency),
                outstanding: money(outstanding, currency),
                state,
            }
        })
        .collect()
}

#[derive(Debug, Clone, PartialEq)]
pub struct AgeBucket {
    pub label: &'static str,
    pub invoices: Vec<String>,
    pub total: Money,
}

/// Outstanding money by how long it has been outstanding.
///
/// The buckets are the standard ones because they are what a person chasing money actually uses, and
/// the 90+ bucket is the honest one: an invoice that old is not late, it is a decision somebody has
/// made about you, and it needs a different conversation rather than another reminder.
pub fn age(settlements: &[Settlement], invoices: &[Invoice], as_of: &str, currency: Currency) -> Vec<AgeBucket> {
    let mut buckets: Vec<AgeBucket> = ["current", "1-30", "31-60", "61-90", "90+"]
        .iter()
        .map(|l| AgeBucket { label: l, invoices: Vec::new(), total: money(0, currency) })
        .collect();
    for s in settlements.iter().filter(|s| s.state.is_outstanding() && s.outstanding.minor > 0) {
        let Some(inv) = invoices.iter().find(|i| i.number == s.invoice) else { continue };
        let overdue = days_between(&inv.due, as_of);
        let idx = if overdue <= 0 {
            0
        } else if overdue <= 30 {
            1
        } else if overdue <= 60 {
            2
        } else if overdue <= 90 {
            3
        } else {
            4
        };
        buckets[idx].invoices.push(s.invoice.clone());
        buckets[idx].total = money(buckets[idx].total.minor + s.outstanding.minor, currency);
    }
    buckets
}

#[derive(Debug, Clone, PartialEq)]
pub struct Revenue {
    pub from: String,
    pub to: String,
    /// What was RECEIVED in the window. What a cash-basis return reports.
    pub cash_basis: Money,
    /// What was INVOICED in the window. What an accrual-basis return reports.
    pub accrual_basis: Money,
    pub note: &'static str,
}

/// Revenue on both bases, because they are different numbers and the difference is a tax question.
///
/// Most sole proprietors file cash basis, but this module does not know that about you and picking
/// one silently would be choosing a tax treatment on your behalf. Both are returned, labelled.
pub fn revenue(invoices: &[Invoice], m: &MatchResult, from: &str, to: &str, currency: Currency) -> Revenue {
    let inside = |d: &str| d >= from && d <= to;
    let cash: i64 = m.matched.iter().filter(|p| inside(&p.date)).map(|p| p.amount.minor).sum();
    let accrual: i64 = invoices
        .iter()
        .filter(|i| i.state != State::Draft && i.state != State::WrittenOff && inside(&i.issued))
        .map(|i| i.amount.minor)
        .sum();
    Revenue {
        from: from.to_string(),
        to: to.to_string(),
        cash_basis: money(cash, currency),
        accrual_basis: money(accrual, currency),
        note: "cash basis counts what ARRIVED in the window; accrual counts what was INVOICED in it. Which one your return wants is a question for whoever files it — this reports both rather than choosing.",
    }
}

/// Abandon an invoice deliberately. A reason is REQUIRED, because an unpaid invoice and one you
/// decided to stop chasing are different facts and only one of them is a bad debt.
pub fn write_off(inv: &mut Invoice, reason: &str) -> Result<(), String> {
    if reason.trim().is_empty() {
        return Err("a write-off needs a reason — an invoice nobody decided to abandon is still owed".to_string());
    }
    inv.state = State::WrittenOff;
    inv.write_off_reason = Some(reason.to_string());
    Ok(())
}

/// Parse a state written by a previous run. An unknown one is an ERROR rather than a default,
/// because defaulting an unreadable state to `issued` would resurrect a write-off as money owed.
pub fn parse_state(s: &str) -> Option<State> {
    match s {
        "draft" => Some(State::Draft),
        "issued" => Some(State::Issued),
        "partly-paid" => Some(State::PartlyPaid),
        "paid" => Some(State::Paid),
        "written-off" => Some(State::WrittenOff),
        _ => None,
    }
}

pub fn to_json(i: &Invoice) -> serde_json::Value {
    serde_json::json!({
        "number": i.number,
        "client": i.client,
        "issued": i.issued,
        "due": i.due,
        "amountMinor": i.amount.minor,
        "currency": i.amount.currency.as_str(),
        "description": i.description,
        "state": i.state.label(),
        "writeOffReason": i.write_off_reason,
        "supply": i.supply.map(|s| s.key()),
        "buyerPlace": i.buyer_place,
    })
}

/// The account registry's refusal, MINUS the one key that means the opposite thing here.
///
/// `number` is on that list because on an ACCOUNT it is the account number — the thing that makes a
/// store worth stealing. On an INVOICE it is the reference printed on the document and quoted by the
/// payer, which is the single most useful field in this module. Everything else on the list still
/// applies unchanged, including a `number` nested inside some other object, which is an account
/// number wearing an invoice's field name.
fn forbidden_key(v: &serde_json::Value) -> Option<String> {
    match v {
        serde_json::Value::Object(map) => {
            let rest: serde_json::Map<String, serde_json::Value> =
                map.iter().filter(|(k, _)| !k.eq_ignore_ascii_case("number")).map(|(k, x)| (k.clone(), x.clone())).collect();
            crate::account::forbidden_key(&serde_json::Value::Object(rest))
        }
        other => crate::account::forbidden_key(other),
    }
}

pub fn from_json(v: &serde_json::Value) -> Result<Invoice, String> {
    if let Some(k) = forbidden_key(v) {
        return Err(format!(
            "`{k}` is not something this store will hold. An invoice records WHAT WAS OWED and by whom — never how anyone pays."
        ));
    }
    let s = |k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
    let number = s("number").ok_or_else(|| "an invoice needs a `number` — it is the reference a payer quotes, and the only thing that separates two identical invoices".to_string())?;
    let amount_minor = v
        .get("amountMinor")
        .and_then(serde_json::Value::as_i64)
        .ok_or_else(|| format!("{number}: `amountMinor` is required, in MINOR units — a decimal here would be a float, and money is not"))?;
    let issued = s("issued").ok_or_else(|| format!("{number}: `issued` is required — without it nothing can tell a payment from a coincidence that predates the work"))?;
    let state_raw = s("state").unwrap_or_else(|| "issued".to_string());
    let state = parse_state(&state_raw).ok_or_else(|| format!("{number}: `{state_raw}` is not a state — one of draft, issued, partly-paid, paid, written-off"))?;
    if state == State::WrittenOff && s("writeOffReason").is_none() {
        return Err(format!("{number}: written off with no reason — an invoice nobody decided to abandon is still owed"));
    }
    let currency = match s("currency").as_deref() {
        None | Some("USD") => Currency::USD,
        Some(other) => return Err(format!("{number}: currency `{other}` is not supported yet, and silently treating it as USD would add unlike amounts together")),
    };
    // An unreadable supply is an ERROR, not a silent None: a typo would otherwise turn a taxable
    // invoice into one that merely "does not say", and the two read very differently on a report.
    let supply = match s("supply") {
        None => None,
        Some(raw) => Some(Supply::parse(&raw).ok_or_else(|| format!("{number}: `{raw}` is not a supply kind — one of service, good, digital, saas"))?),
    };
    Ok(Invoice {
        supply,
        buyer_place: s("buyerPlace"),
        client: s("client").unwrap_or_else(|| "unknown".to_string()),
        due: s("due").unwrap_or_else(|| issued.clone()),
        amount: money(amount_minor, currency),
        description: s("description").unwrap_or_default(),
        write_off_reason: s("writeOffReason"),
        number,
        issued,
        state,
    })
}

pub fn all_to_json(invoices: &[Invoice]) -> serde_json::Value {
    serde_json::Value::Array(invoices.iter().map(to_json).collect())
}

/// Read the store, keeping what parses and REPORTING what does not — a row this cannot read is a
/// row somebody is owed money on, so dropping it silently is the one outcome that must not happen.
pub fn all_from_json(v: &serde_json::Value) -> (Vec<Invoice>, Vec<String>) {
    let mut out: Vec<Invoice> = Vec::new();
    let mut rejected = Vec::new();
    for item in v.as_array().map(Vec::as_slice).unwrap_or_default() {
        match from_json(item) {
            Ok(i) => {
                if out.iter().any(|e: &Invoice| e.number == i.number) {
                    // Two rows with one number breaks the thing the number exists to do.
                    rejected.push(format!("{}: appears twice — an invoice number must be unique or a reference cannot resolve it", i.number));
                } else {
                    out.push(i);
                }
            }
            Err(e) => rejected.push(e),
        }
    }
    out.sort_by(|a, b| a.issued.cmp(&b.issued).then_with(|| a.number.cmp(&b.number)));
    (out, rejected)
}

#[cfg(test)]
mod store_tests {
    use super::*;
    use crate::money::usd;

    #[test]
    fn an_unreadable_row_is_reported_and_never_dropped() {
        // A row this cannot parse is a row somebody OWES you on. Silently skipping it would
        // subtract real money from the outstanding total and nothing would say so.
        let v = serde_json::json!([
            { "number": "A", "client": "ACME", "issued": "2026-06-01", "due": "2026-07-01", "amountMinor": 240_000 },
            { "client": "NO NUMBER", "issued": "2026-06-01", "amountMinor": 100_000 },
            { "number": "C", "issued": "2026-06-01", "amountMinor": 100_000, "state": "banana" },
        ]);
        let (ok, rejected) = all_from_json(&v);
        assert_eq!(ok.len(), 1);
        assert_eq!(rejected.len(), 2, "both bad rows are NAMED, not skipped");
        assert!(rejected[0].contains("needs a `number`"));
        assert!(rejected[1].contains("is not a state"));
    }

    #[test]
    fn the_store_refuses_to_hold_how_anyone_pays() {
        let ok = |extra: serde_json::Value| {
            let mut v = serde_json::json!({ "number": "A", "issued": "2026-06-01", "amountMinor": 1 });
            let serde_json::Value::Object(e) = extra else { unreachable!() };
            for (k, x) in e {
                v[k] = x;
            }
            from_json(&v)
        };
        // Every identity key the account registry refuses is refused here too.
        for k in ["accountNumber", "routing", "iban", "ssn", "cvv", "token"] {
            let err = ok(serde_json::json!({ k: "1234" })).unwrap_err();
            assert!(err.contains("never how anyone pays"), "{k} was accepted");
        }
        // EXCEPT the bare `number`, which on an invoice is the reference, not an account.
        assert!(ok(serde_json::json!({})).is_ok());
        // But a `number` nested inside another object is an account number wearing this field's name.
        assert!(ok(serde_json::json!({ "payer": { "number": "4111111111111111" } })).unwrap_err().contains("never how anyone pays"));
    }

    #[test]
    fn a_write_off_with_no_reason_does_not_survive_a_round_trip() {
        // The in-memory guard is `write_off`; this is the same rule at the STORE boundary, where a
        // hand-edited file could otherwise retire a debt with no record of who decided to.
        let v = serde_json::json!({ "number": "A", "issued": "2026-06-01", "amountMinor": 1, "state": "written-off" });
        assert!(from_json(&v).unwrap_err().contains("still owed"));
    }

    #[test]
    fn two_rows_with_one_number_is_refused_because_the_number_is_the_key() {
        let v = serde_json::json!([
            { "number": "A", "issued": "2026-06-01", "amountMinor": 100 },
            { "number": "A", "issued": "2026-06-02", "amountMinor": 200 },
        ]);
        let (ok, rejected) = all_from_json(&v);
        assert_eq!(ok.len(), 1);
        assert!(rejected[0].contains("must be unique"));
    }

    #[test]
    fn an_invoice_survives_a_round_trip_through_the_store() {
        let mut i = Invoice::new("INV-1", "ACME", "2026-06-01", "2026-07-01", usd(240_000), "consulting");
        i.state = State::PartlyPaid;
        let back = from_json(&to_json(&i)).expect("round trip");
        assert_eq!(back, i);
    }

    #[test]
    fn an_unsupported_currency_is_refused_rather_than_read_as_dollars() {
        let v = serde_json::json!({ "number": "A", "issued": "2026-06-01", "amountMinor": 1, "currency": "EUR" });
        assert!(from_json(&v).unwrap_err().contains("adding unlike amounts") || from_json(&v).unwrap_err().contains("unlike amounts"));
    }
}

