    #[test]
    fn the_sales_tax_stack_sums_state_and_county() {
        // Duluth's printed rate is the state's 4% plus Gwinnett's 2%. Neither alone is what a
        // customer pays, which is why a single flat number per state is the wrong shape.
        let (bps, found) = combined(RATES, PLACES, "us/ga/gwinnett/duluth", RateKind::SalesTax, "2026-09-04").expect("seeded");
        assert_eq!(bps, 600);
        assert_eq!(found.len(), 2);
        // Nearest first, so a reader sees the local component before the state one.
        assert_eq!(found[0].place, "us/ga/gwinnett");
        assert_eq!(found[1].place, "us/ga");
    }

    #[test]
    fn an_expired_rate_is_refused_and_never_carried_forward() {
        // THE GUARD THIS MODULE EXISTS FOR. Georgia's flat rate steps down on a legislated schedule,
        // so the 2025 rate has a real end date. Asked about 2026, this must refuse — applying last
        // year's percentage would put a wrong number on a return with nothing to flag it.
        let ok = rates_at(RATES, PLACES, "us/ga", RateKind::IncomeTax, "2025-06-01").expect("in window");
        assert_eq!(ok.len(), 1);
        assert_eq!(ok[0].bps, 519);

        let lapsed = rates_at(RATES, PLACES, "us/ga", RateKind::IncomeTax, "2026-06-01").expect("no error, just empty");
        assert!(lapsed.is_empty(), "the 2025 rate must not answer for 2026");

        // And the refusal names where to go rather than saying "unknown".
        let err = combined(RATES, PLACES, "us/ga", RateKind::SalesTax, "1999-01-01").unwrap_err();
        assert!(err.contains("windows have closed") || err.contains("Nothing is recorded"), "{err}");
    }

    #[test]
    fn income_tax_refuses_to_stack_because_the_sum_would_be_a_fiction() {
        let err = combined(RATES, PLACES, "us/ga", RateKind::IncomeTax, "2025-06-01").unwrap_err();
        assert!(err.contains("does not stack"), "{err}");
        assert!(err.contains("invent a rate that exists nowhere"));
        assert!(RateKind::SalesTax.stacks());
        assert!(!RateKind::IncomeTax.stacks());
        assert!(!RateKind::SelfEmployment.stacks());
    }

