        let service = taxability(RATES, PLACES, "us/ga/gwinnett/duluth", Supply::ProfessionalService, "2026-09-04").expect("seeded");
        assert!(matches!(service, Taxability::Exempt { .. }), "{service:?}");
        let saas = taxability(RATES, PLACES, "us/ga/gwinnett/duluth", Supply::SoftwareAsService, "2026-09-04").expect("seeded");
        assert!(matches!(saas, Taxability::Exempt { .. }), "nothing is delivered, so there is nothing to tax: {saas:?}");

        // A downloaded product is a different supply and gets the full stacked rate.
        let digital = taxability(RATES, PLACES, "us/ga/gwinnett/duluth", Supply::DigitalProduct, "2026-09-04").expect("seeded");
        match digital {
            Taxability::Taxable { bps, ref sources } => {
