            Rate { place: "zz/aa/north", kind: RateKind::SalesTax, bps: 100, from: "2000-01-01", to: None, source: "fixture", note: "" },
            Rate { place: "zz/aa/south", kind: RateKind::SalesTax, bps: 300, from: "2000-01-01", to: None, source: "fixture", note: "" },
            Rate { place: "zz/bb", kind: RateKind::SalesTax, bps: 700, from: "2000-01-01", to: None, source: "fixture", note: "" },
