    #[test]
    fn the_rate_follows_the_customer_not_the_seller() {
        // THE INTUITIVE MISTAKE. A seller in North (5%) shipping to South must charge SOUTH's 7%,
        // and using their own rate is wrong on every invoice that leaves town.
        let (places, rates, rules) = two_counties();
        let t = taxability_for_sale_with(&rates, &rules, &places, "zz/aa/north", Some("zz/aa/south"), Supply::TangibleGood, "2026-09-04").expect("same state");
        match t {
            Taxability::Taxable { bps, .. } => assert_eq!(bps, 700, "4% state + South's 3%, NOT North's 1%"),
            other => panic!("a good is taxable here: {other:?}"),
        }
        // Selling at home is the same call with the same shape.
        let home = taxability_for_sale_with(&rates, &rules, &places, "zz/aa/north", Some("zz/aa/north"), Supply::TangibleGood, "2026-09-04").expect("same state");
        assert!(matches!(home, Taxability::Taxable { bps: 500, .. }), "{home:?}");
    }

    #[test]
    fn a_sale_across_a_state_line_is_refused_because_nexus_is_not_modelled() {
        let (places, rates, rules) = two_counties();
        let err = taxability_for_sale_with(&rates, &rules, &places, "zz/aa/north", Some("zz/bb"), Supply::TangibleGood, "2026-09-04").unwrap_err();
        assert!(err.contains("NEXUS is not modelled"), "{err}");
        assert!(err.contains("economic nexus threshold"), "the refusal must name the question to go answer: {err}");
        // It names BOTH states, so the reader knows which direction the sale went.
        assert!(err.contains("Ayeshire") && err.contains("Beeshire"), "{err}");
    }

    #[test]
    fn an_exempt_supply_short_circuits_sourcing_and_nexus_entirely() {
        // The case that matters for a consulting practice: a Georgia service is exempt whoever buys
        // it, so there is no destination to source and no nexus question to ask. If exemption were
        // checked AFTER sourcing, this would come back as a cross-border refusal instead of an
        // answer, and the simple case would look complicated.
        let out_of_state = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", Some("us"), Supply::ProfessionalService, "2026-09-04").expect("exempt regardless");
        assert!(matches!(out_of_state, Taxability::Exempt { .. }), "{out_of_state:?}");
        // And with no buyer recorded at all it is STILL exempt — nothing about the customer changes it.
        let no_buyer = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", None, Supply::ProfessionalService, "2026-09-04").expect("exempt regardless");
        assert!(matches!(no_buyer, Taxability::Exempt { .. }), "{no_buyer:?}");
    }

    #[test]
    fn a_taxable_sale_with_no_customer_recorded_is_undetermined_rather_than_zero() {
        let t = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", None, Supply::DigitalProduct, "2026-09-04").expect("resolvable");
        match t {
            Taxability::Unknown { ref what_to_check, where_to_check } => {
                assert!(what_to_check.contains("follows the customer"), "{what_to_check}");
                assert!(where_to_check.contains("a total cannot be computed"), "{where_to_check}");
            }
            other => panic!("without a buyer the rate cannot be sourced, so it must not resolve: {other:?}"),
        }
    }

    #[test]
    fn every_supply_key_round_trips_and_an_unknown_one_is_none() {
        for sup in Supply::ALL {
            assert_eq!(Supply::parse(sup.key()), Some(*sup), "{} did not round trip", sup.key());
        }
        assert_eq!(Supply::ALL.len(), 4, "a new supply kind needs a key here or it cannot be stored");
        assert_eq!(Supply::parse("services"), None, "a near miss must not resolve — a typo would decide taxability");
        assert_eq!(Supply::parse(""), None);
    }

    #[test]
    fn a_region_resolves_through_the_chain_and_a_country_has_none() {
        assert_eq!(region(PLACES, "us/ga/gwinnett/duluth").expect("resolvable").map(|p| p.id), Some("us/ga"));
        assert_eq!(region(PLACES, "us/ga").expect("resolvable").map(|p| p.id), Some("us/ga"));
        assert_eq!(region(PLACES, "us").expect("resolvable").map(|p| p.id), None, "a country sits above every region");
    }

    #[test]
    fn applying_a_rate_stays_in_integers_and_rounds_half_away_from_zero() {
        assert_eq!(apply_bps(usd(10_000), 600).minor, 600, "6% of 100.00 is 6.00");
        // 0.005 exactly — rounds up, not to even, because that is what a tax table does.
        assert_eq!(apply_bps(usd(25), 200).minor, 1, "2% of 0.25 is 0.005");
        assert_eq!(apply_bps(usd(-25), 200).minor, -1, "and the same magnitude the other way");
        assert_eq!(apply_bps(usd(0), 600).minor, 0);
        // A large amount does not wrap: 10 million dollars at 6%.
        assert_eq!(apply_bps(usd(1_000_000_000), 600).minor, 60_000_000);
    }

    #[test]
    fn every_seeded_rate_cites_a_source() {
        // A rate with no source is a rumour, and this table is the input to a tax return.
        assert!(RATES.len() >= 4, "the scan found only {} rates — it has stopped seeing them", RATES.len());
        for r in RATES {
            assert!(!r.source.trim().is_empty(), "{} {} has no source", r.place, r.kind.label());
            assert!(r.from.len() == 10, "{} {} has no usable effective date", r.place, r.kind.label());
        }
        assert!(SUPPLY_RULES.len() >= 4, "the scan found only {} supply rules", SUPPLY_RULES.len());
        for r in SUPPLY_RULES {
            assert!(!r.source.trim().is_empty(), "{} {:?} has no source", r.place, r.supply);
            assert!(!r.reason.trim().is_empty(), "{} {:?} gives no reason — an exemption you cannot explain is one you cannot defend", r.place, r.supply);
            assert!(PLACES.iter().any(|p| p.id == r.place), "`{}` is ruled on but is not a seeded place", r.place);
        }
        assert!(OBLIGATIONS.len() >= 7, "the scan found only {} obligations", OBLIGATIONS.len());
        for o in OBLIGATIONS {
            assert!(!o.source.trim().is_empty(), "{} has no source", o.name);
            assert!(!o.authority.trim().is_empty(), "{} names no authority — a requirement you cannot act on", o.name);
            assert!(!o.required_when.trim().is_empty(), "{} does not say when it applies, so it reads as always", o.name);
        }
        // And every place a rate or obligation points at must actually exist.
        for (place, _) in sources(RATES, OBLIGATIONS) {
            assert!(PLACES.iter().any(|p| p.id == place), "`{place}` is cited but is not a seeded place");
        }
    }

    #[test]
    fn the_other_states_exist_as_names_and_assert_no_rate_or_rule() {
        // The whole point of seeding them: they must add REACH without adding false precision.
        assert!(PLACES.iter().filter(|p| p.level == Level::Region).count() >= 50, "the states are the reach");
        for p in PLACES.iter().filter(|p| p.level == Level::Region && p.id != "us/ga") {
            assert!(!RATES.iter().any(|r| r.place == p.id), "{} asserts a rate nobody checked", p.id);
            assert!(!SUPPLY_RULES.iter().any(|r| r.place == p.id), "{} asserts a taxability rule nobody checked", p.id);
        }
        // So each answers NOT KNOWN rather than a number, and says so.
        let t = taxability(RATES, PLACES, "us/tx", Supply::ProfessionalService, "2026-09-04").expect("resolvable");
        assert!(matches!(t, Taxability::Unknown { .. }), "{t:?}");
        assert!(combined(RATES, PLACES, "us/tx", RateKind::SalesTax, "2026-09-04").is_err());
        // The federal obligations still reach them, which is the value of existing at all.
        let obs = obligations_for(OBLIGATIONS, PLACES, "us/tx").expect("resolvable");
        assert!(obs.iter().any(|o| o.name == "Estimated tax"), "federal duties do not stop at a state line");
        assert!(obs.iter().all(|o| o.place == "us"), "nothing state-specific may be claimed for Texas: {:?}", obs.iter().map(|o| o.place).collect::<Vec<_>>());
    }

    #[test]
    fn coverage_follows_the_chain_so_duluth_is_not_reported_as_unknown() {
        let cov = |id: &str| coverage(RATES, SUPPLY_RULES, OBLIGATIONS, PLACES, id, "2026-09-04");
        // THE MISREADING THIS FIXES. Duluth declares no rate of its own and inherits every one that
        // applies; labelling it by its own id alone called the seed's whole purpose "name only".
        assert_eq!(cov("us/ga/gwinnett/duluth").label(), "rates + rules");
        assert_eq!(cov("us/ga").label(), "rates + rules");
        // A state with nothing recorded says so, and still carries the federal duties.
        let tx = cov("us/tx");
        assert_eq!(tx.label(), "duties only");
        assert!(!tx.sales_tax && !tx.supply_rules && tx.obligations);
        // The country itself has federal obligations and a self-employment rate, but no sales tax.
        assert!(!cov("us").sales_tax, "there is no federal sales tax");
    }

    #[test]
    fn a_cross_state_sale_now_refuses_for_the_right_reason() {
        // BEFORE the states were seeded this failed as "not a place this knows", which is a true
        // statement that answers the wrong question. Now it names nexus.
        let err = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", Some("us/ca"), Supply::DigitalProduct, "2026-09-04").unwrap_err();
        assert!(err.contains("NEXUS is not modelled"), "{err}");
        assert!(err.contains("California"), "{err}");
        // And a service is STILL exempt across that line, because exemption short-circuits sourcing.
        let svc = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", Some("us/ca"), Supply::ProfessionalService, "2026-09-04").expect("exempt regardless");
        assert!(matches!(svc, Taxability::Exempt { .. }), "{svc:?}");
    }

    #[test]
    fn every_place_reaches_a_country_that_declares_a_currency_and_a_system() {
        for p in PLACES {
            let c = country(PLACES, p.id).unwrap_or_else(|e| panic!("{}: {e}", p.id));
            assert!(c.currency.is_some(), "{} reaches {} which declares no currency", p.id, c.id);
            assert!(c.system.is_some(), "{} reaches {} which declares no tax system", p.id, c.id);
        }
        assert_eq!(country(PLACES, "us/ga/gwinnett/duluth").expect("seeded").id, "us");
    }
}

//! The tax year: what came in, what self-employment tax it carries, and what to put aside.
//!
//! # What this computes, and what it refuses to
//!
//! Self-employment tax is COMPUTABLE. It is a published rate on a published base with a published
//! cap, it needs nothing about the rest of your life, and getting it right is arithmetic.
//!
//! Federal income tax is NOT, and this does not pretend otherwise. It needs filing status, every
//! other source of income, itemised or standard deductions, credits, and a household — none of which
//! a bank statement knows. A number produced without them would be confidently wrong in whichever
//! direction the missing facts pointed, and would be believed because it came out of a machine. So
//! this reports the SE tax it can stand behind, and names income tax as the part somebody else does.
//!
//! # An unseeded year is refused
//!
//! The Social Security wage base changes every year. Applying last year's to this one is the same
//! failure the rate tables were built to prevent, so a year with no parameters answers nothing.
use crate::jurisdiction::apply_bps;
use crate::money::{money, Money};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FilingStatus {
    Single,
    MarriedJointly,
    MarriedSeparately,
    HeadOfHousehold,
}

impl FilingStatus {
    pub fn key(self) -> &'static str {
        match self {
            FilingStatus::Single => "single",
            FilingStatus::MarriedJointly => "joint",
            FilingStatus::MarriedSeparately => "separate",
            FilingStatus::HeadOfHousehold => "head",
        }
    }

    /// Unknown is `None`, never a default — filing status moves the Additional Medicare threshold by
    /// $125,000 between the extremes, and defaulting it would decide somebody's return on a typo.
    pub fn parse(s: &str) -> Option<FilingStatus> {
        match s {
            "single" => Some(FilingStatus::Single),
            "joint" => Some(FilingStatus::MarriedJointly),
            "separate" => Some(FilingStatus::MarriedSeparately),
            "head" => Some(FilingStatus::HeadOfHousehold),
            _ => None,
        }
    }

    pub const ALL: &'static [FilingStatus] =
        &[FilingStatus::Single, FilingStatus::MarriedJointly, FilingStatus::MarriedSeparately, FilingStatus::HeadOfHousehold];

    /// Where the extra 0.9% Medicare surcharge starts. NOT indexed for inflation — these have been
    /// the same figures since 2013, which is why they are constants here rather than per-year data.
    pub fn additional_medicare_threshold_minor(self) -> i64 {
        match self {
            FilingStatus::MarriedJointly => 25_000_000,
            FilingStatus::MarriedSeparately => 12_500_000,
            FilingStatus::Single | FilingStatus::HeadOfHousehold => 20_000_000,
        }
    }
}

/// The parameters of one tax year. DATA, for the same reason every rate in `jurisdiction` is.
#[derive(Debug, Clone, PartialEq)]
pub struct YearParams {
    pub year: i32,
    /// The Social Security wage base — the ceiling on the 12.4% half. Changes EVERY year.
    pub ss_wage_base_minor: i64,
    pub source: &'static str,
    pub note: &'static str,
}

/// 12.4% Social Security. Unchanged since 1990.
pub const SS_BPS: i64 = 1240;
/// 2.9% Medicare, with no ceiling.
pub const MEDICARE_BPS: i64 = 290;
/// An extra 0.9% above a threshold that depends on filing status.
pub const ADDITIONAL_MEDICARE_BPS: i64 = 90;
/// Net earnings are 92.35% of net profit — the deduction standing in for the employer's half.
pub const NET_EARNINGS_BPS: i64 = 9235;
/// Below $400 of net earnings there is no self-employment tax at all.
pub const SE_FLOOR_MINOR: i64 = 40_000;

pub const YEARS: &[YearParams] = &[
    YearParams {
        year: 2024,
        ss_wage_base_minor: 16_860_000,
        source: "SSA — contribution and benefit base, 2024",
        note: "",
    },
    YearParams {
        year: 2025,
        ss_wage_base_minor: 17_610_000,
        source: "SSA — contribution and benefit base, 2025",
        note: "",
    },
    YearParams {
        year: 2026,
        ss_wage_base_minor: 18_450_000,
        source: "SSA — contribution and benefit base, 2026",
        note: "CHECK THIS ONE FIRST. It is the figure this report is most likely to be wrong about, and it only matters if your profit reaches it — the report says whether it actually bound.",
    },
];

pub fn params_for(years: &[YearParams], year: i32) -> Result<YearParams, String> {
    years.iter().find(|y| y.year == year).cloned().ok_or_else(|| {
        let known: Vec<String> = years.iter().map(|y| y.year.to_string()).collect();
        format!(
            "no parameters are recorded for {year}. The Social Security wage base changes every year, so applying another year's would be a wrong number nothing would flag. Known: {}. The figure comes from SSA's contribution and benefit base announcement.",
            known.join(", ")
        )
    })
}

#[derive(Debug, Clone, PartialEq)]
pub struct SelfEmploymentTax {
    pub net_profit: Money,
    /// 92.35% of profit. The base everything below is computed on, and NOT the profit itself.
    pub net_earnings: Money,
    pub social_security: Money,
    pub medicare: Money,
    pub additional_medicare: Money,
    pub total: Money,
    /// Half the regular SE tax, deductible against INCOME tax — it does not reduce the SE tax itself,
    /// and reporting it inside the total would understate what is owed.
    pub deductible_half: Money,
    /// Whether the wage base actually bound. When it did not, the year's most uncertain figure had
    /// no effect on this answer, and saying so is worth more than the caveat it replaces.
    pub cap_bound: bool,
    pub notes: Vec<String>,
}

/// Self-employment tax on a year's net profit.
pub fn self_employment_tax(net_profit: Money, p: &YearParams, status: FilingStatus) -> SelfEmploymentTax {
    let cur = net_profit.currency;
    let zero = money(0, cur);
    let mut notes: Vec<String> = Vec::new();

    // A loss carries no self-employment tax. It may carry other consequences; none of them are here.
    if net_profit.minor <= 0 {
        notes.push("no profit, so no self-employment tax. A LOSS may still matter on a return — that is a question for whoever files it.".to_string());
        return SelfEmploymentTax {
            net_profit,
            net_earnings: zero,
            social_security: zero,
            medicare: zero,
            additional_medicare: zero,
            total: zero,
            deductible_half: zero,
            cap_bound: false,
            notes,
        };
    }

    let net_earnings = apply_bps(net_profit, NET_EARNINGS_BPS);
    if net_earnings.minor < SE_FLOOR_MINOR {
        notes.push(format!(
            "net earnings of {} are below the $400 floor, so no self-employment tax is due. Income tax may still be — the two are separate questions.",
            crate::money::format_minor(net_earnings.minor)
        ));
        return SelfEmploymentTax {
            net_profit,
            net_earnings,
            social_security: zero,
            medicare: zero,
            additional_medicare: zero,
            total: zero,
            deductible_half: zero,
            cap_bound: false,
            notes,
        };
    }

    // The 12.4% half STOPS at the wage base. The 2.9% half never does — that asymmetry is the
    // single most misremembered thing about this tax.
    let cap_bound = net_earnings.minor > p.ss_wage_base_minor;
    let ss_base = money(net_earnings.minor.min(p.ss_wage_base_minor), cur);
    let social_security = apply_bps(ss_base, SS_BPS);
    let medicare = apply_bps(net_earnings, MEDICARE_BPS);

    let threshold = status.additional_medicare_threshold_minor();
    let over = (net_earnings.minor - threshold).max(0);
    let additional_medicare = apply_bps(money(over, cur), ADDITIONAL_MEDICARE_BPS);

    if cap_bound {
        notes.push(format!(
            "the Social Security half stopped at the {} wage base of {}; the Medicare half has no ceiling and was charged on everything",
            p.year,
            crate::money::format_minor(p.ss_wage_base_minor)
        ));
    } else {
        notes.push(format!(
            "profit did not reach the {} wage base, so that figure had no effect on this and does not need checking",
            p.year
        ));
    }
    if over > 0 {
        notes.push(format!(
            "the extra 0.9% Medicare surcharge applies above {} for a {} filer, and it is charged on WAGES PLUS self-employment income — if you also had a job this year, this figure is too low",
            crate::money::format_minor(threshold),
            status.key()
        ));
    }

    let regular = social_security.minor + medicare.minor;
    SelfEmploymentTax {
        net_profit,
        net_earnings,
        social_security,
        medicare,
        additional_medicare,
        // The surcharge is INSIDE the total and OUTSIDE the deduction. Both halves of that are easy
        // to get wrong in opposite directions.
        total: money(regular + additional_medicare.minor, cur),
        deductible_half: money(regular / 2, cur),
        cap_bound,
        notes,
    }
}

/// Where an expense figure came from, because the number is worth very different amounts depending.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExpenseBasis {
    /// Somebody stated it. The only basis this module trusts.
    Declared,
    /// NOBODY stated it, so it is zero — which makes every figure below the worst case.
    Absent,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TaxYear {
    pub year: i32,
    pub status: FilingStatus,
    pub revenue: Money,
    pub expenses: Money,
    pub expense_basis: ExpenseBasis,
    pub net_profit: Money,
    pub se: SelfEmploymentTax,
    /// What to hold back, at a rate the CALLER chose. Not a prediction of your bill.
    pub set_aside: Option<Money>,
    pub notes: Vec<String>,
}

/// Assemble the year.
///
/// `income_tax_bps` is REQUIRED to be a deliberate choice and is never defaulted: it is the caller's
/// estimate of an income tax rate this module refuses to compute, and a number invented here would be
/// indistinguishable, to a reader, from one that had been derived.
pub fn assemble(
    year: i32,
    status: FilingStatus,
    revenue: Money,
    expenses: Option<Money>,
    income_tax_bps: Option<i64>,
    p: &YearParams,
) -> TaxYear {
    let cur = revenue.currency;
    let (expenses, expense_basis) = match expenses {
        Some(e) => (e, ExpenseBasis::Declared),
        None => (money(0, cur), ExpenseBasis::Absent),
    };
    let net_profit = money(revenue.minor - expenses.minor, cur);
    let se = self_employment_tax(net_profit, p, status);
    let mut notes: Vec<String> = Vec::new();

    if expense_basis == ExpenseBasis::Absent {
        notes.push(
            "NO EXPENSE WAS DECLARED, so this treats every dollar of revenue as profit. That is the worst case and almost certainly too high — a business with no costs is not a business. Pass the deductible total you or your accountant stand behind."
                .to_string(),
        );
    }
    notes.push(
        "INCOME TAX IS NOT COMPUTED HERE and no arithmetic below stands in for it. It needs filing status, every other source of income, deductions, credits and a household — none of which a bank statement knows, and a number produced without them would be believed because a machine printed it."
            .to_string(),
    );
    notes.push(format!(
        "half the regular self-employment tax — {} — is deductible against INCOME tax. It does not reduce the self-employment tax itself, so the {} above is the figure to plan against.",
        crate::money::format_minor(se.deductible_half.minor),
        crate::money::format_minor(se.total.minor)
    ));

    let set_aside = income_tax_bps.map(|bps| {
        // A LOSS SETS ASIDE NOTHING. Applying a rate to a negative profit returned a NEGATIVE
        // set-aside — found by running a year with no revenue and declared expenses, which printed
        // "SET ASIDE -924.00". Money you have not made is not money to hold back, and a negative
        // there reads as an instruction to spend.
        let income = apply_bps(money(net_profit.minor.max(0), cur), bps.max(0));
        money(se.total.minor + income.minor, cur)
    });
    if set_aside.is_none() {
        notes.push(
            "no set-aside is shown because no income tax rate was given. Guessing one would produce the single most actionable number in this report out of nothing."
                .to_string(),
        );
    }

    TaxYear { year, status, revenue, expenses, expense_basis, net_profit, se, set_aside, notes }
}

/// The safe harbour rule for estimated payments, and what of it can actually be computed here.
///
/// The rule that avoids an underpayment penalty is 90% of THIS year's tax or 100% of LAST year's
/// (110% above an AGI threshold). The second path needs last year's return, which this does not have
/// — so it computes the first and names the second rather than silently offering one of two.
pub fn safe_harbour(se: &SelfEmploymentTax) -> (Money, &'static str) {
    (
        apply_bps(se.total, 9000),
        "90% of THIS year's self-employment tax. The other path — 100% of last year's TOTAL tax, or 110% above an AGI threshold — is often lower and is usually the one people use, but it needs last year's return, which this does not have. Both are safe harbours against a penalty, not the bill.",
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    fn p2025() -> YearParams {
        params_for(YEARS, 2025).expect("seeded")
    }

    #[test]
    fn an_unseeded_year_is_refused_rather_than_borrowing_another_years_base() {
        let err = params_for(YEARS, 2019).unwrap_err();
        assert!(err.contains("no parameters are recorded for 2019"), "{err}");
        assert!(err.contains("changes every year"), "the refusal must say WHY: {err}");
        assert!(err.contains("2024, 2025, 2026"), "and what IS known: {err}");
    }

    #[test]
    fn the_ordinary_case_is_arithmetic_anyone_can_check() {
        // $60,000 profit, well under the wage base.
        let se = self_employment_tax(usd(6_000_000), &p2025(), FilingStatus::Single);
        // 60,000 × 0.9235 = 55,410.00
        assert_eq!(se.net_earnings.minor, 5_541_000);
        // 55,410 × 12.4% = 6,870.84
        assert_eq!(se.social_security.minor, 687_084);
        // 55,410 × 2.9% = 1,606.89
        assert_eq!(se.medicare.minor, 160_689);
        assert_eq!(se.additional_medicare.minor, 0);
        assert_eq!(se.total.minor, 847_773, "6,870.84 + 1,606.89 = 8,477.73");
        // Half the regular tax, and it is NOT subtracted from the total.
        assert_eq!(se.deductible_half.minor, 423_886, "half of 8,477.73, rounded down to the cent");
        assert_eq!(se.total.minor, se.social_security.minor + se.medicare.minor + se.additional_medicare.minor);
        assert!(!se.cap_bound);
        assert!(se.notes.iter().any(|n| n.contains("did not reach the 2025 wage base")));
    }

    #[test]
    fn the_wage_base_caps_social_security_and_never_caps_medicare() {
        // THE MOST MISREMEMBERED THING ABOUT THIS TAX. $250,000 profit is over the base.
        let p = p2025();
        let se = self_employment_tax(usd(25_000_000), &p, FilingStatus::Single);
        assert_eq!(se.net_earnings.minor, 23_087_500, "250,000 × 0.9235");
        assert!(se.cap_bound);
        // Social Security stops at the base: 176,100 × 12.4% = 21,836.40
        assert_eq!(se.social_security.minor, 2_183_640);
        assert_eq!(se.social_security.minor, apply_bps(usd(p.ss_wage_base_minor), SS_BPS).minor);
        // Medicare is charged on ALL of it: 230,875 × 2.9% = 6,695.375 → 6,695.38
        assert_eq!(se.medicare.minor, 669_538);
        assert!(se.medicare.minor > apply_bps(usd(p.ss_wage_base_minor), MEDICARE_BPS).minor, "Medicare must not be capped");
        assert!(se.notes.iter().any(|n| n.contains("has no ceiling")));
    }

    #[test]
    fn below_four_hundred_dollars_of_net_earnings_there_is_no_tax_at_all() {
        // $400 of NET EARNINGS, not of profit — so the floor bites at a profit around $433.
        let just_under = self_employment_tax(usd(43_000), &p2025(), FilingStatus::Single);
        assert_eq!(just_under.net_earnings.minor, 39_711, "430 × 0.9235 = 397.11, under the floor");
        assert_eq!(just_under.total.minor, 0);
        assert!(just_under.notes.iter().any(|n| n.contains("below the $400 floor")));
        assert!(just_under.notes.iter().any(|n| n.contains("Income tax may still be")), "the floor is not a general exemption");

        let just_over = self_employment_tax(usd(44_000), &p2025(), FilingStatus::Single);
        assert_eq!(just_over.net_earnings.minor, 40_634, "440 × 0.9235 = 406.34, over the floor");
        assert!(just_over.total.minor > 0);
    }

    #[test]
    fn a_loss_carries_no_self_employment_tax_and_says_it_may_still_matter() {
        let se = self_employment_tax(usd(-500_000), &p2025(), FilingStatus::Single);
        assert_eq!(se.total.minor, 0);
        assert_eq!(se.net_earnings.minor, 0);
        assert!(se.notes.iter().any(|n| n.contains("A LOSS may still matter")));
        // Exactly zero is not a loss and not taxable either, and must not panic.
        assert_eq!(self_employment_tax(usd(0), &p2025(), FilingStatus::Single).total.minor, 0);
    }

    #[test]
    fn the_surcharge_threshold_moves_with_filing_status() {
        // $230,000 profit → 212,405 net earnings. Over the $200k single threshold, under the $250k
        // joint one. Same profit, different tax, and nothing but the status changed.
        let profit = usd(23_000_000);
        let single = self_employment_tax(profit, &p2025(), FilingStatus::Single);
        let joint = self_employment_tax(profit, &p2025(), FilingStatus::MarriedJointly);
        assert_eq!(single.net_earnings.minor, 21_240_500);
        // (212,405 − 200,000) × 0.9% = 111.645 → 111.65
        assert_eq!(single.additional_medicare.minor, 11_165);
        assert_eq!(joint.additional_medicare.minor, 0, "under the joint threshold");
        assert!(single.total.minor > joint.total.minor);
        // Separate filers have the LOWEST threshold, which surprises people.
        let separate = self_employment_tax(profit, &p2025(), FilingStatus::MarriedSeparately);
        assert!(separate.additional_medicare.minor > single.additional_medicare.minor);
        assert!(single.notes.iter().any(|n| n.contains("if you also had a job this year, this figure is too low")));
    }

    #[test]
    fn the_surcharge_is_inside_the_total_and_outside_the_deduction() {
        // Two errors in opposite directions, both easy: leaving it out of the total understates the
        // bill, and including it in the deduction overstates the relief.
        let se = self_employment_tax(usd(30_000_000), &p2025(), FilingStatus::Single);
        assert!(se.additional_medicare.minor > 0);
        assert_eq!(se.total.minor, se.social_security.minor + se.medicare.minor + se.additional_medicare.minor);
        assert_eq!(se.deductible_half.minor, (se.social_security.minor + se.medicare.minor) / 2);
        assert!(se.deductible_half.minor * 2 < se.total.minor, "the surcharge is not halved into the deduction");
    }

    #[test]
    fn every_filing_status_key_round_trips_and_a_near_miss_does_not() {
        for s in FilingStatus::ALL {
            assert_eq!(FilingStatus::parse(s.key()), Some(*s));
        }
        assert_eq!(FilingStatus::ALL.len(), 4);
        assert_eq!(FilingStatus::parse("married"), None, "a near miss must not resolve — it moves the threshold by $125,000");
        // Head of household shares the single threshold; joint and separate do not.
        assert_eq!(
            FilingStatus::HeadOfHousehold.additional_medicare_threshold_minor(),
            FilingStatus::Single.additional_medicare_threshold_minor()
        );
        assert_eq!(FilingStatus::MarriedSeparately.additional_medicare_threshold_minor(), 12_500_000);
    }

    #[test]
    fn an_absent_expense_figure_is_flagged_as_the_worst_case_rather_than_taken_as_zero() {
        let y = assemble(2025, FilingStatus::Single, usd(6_000_000), None, None, &p2025());
        assert_eq!(y.expense_basis, ExpenseBasis::Absent);
        assert_eq!(y.net_profit.minor, 6_000_000, "every dollar of revenue treated as profit");
        assert!(y.notes.iter().any(|n| n.contains("a business with no costs is not a business")));
        // Declaring expenses changes the basis AND the profit.
        let z = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_500_000)), None, &p2025());
        assert_eq!(z.expense_basis, ExpenseBasis::Declared);
        assert_eq!(z.net_profit.minor, 4_500_000);
        assert!(z.se.total.minor < y.se.total.minor);
        assert!(!z.notes.iter().any(|n| n.contains("worst case")));
    }

    #[test]
    fn income_tax_is_never_computed_and_the_report_says_so_every_time() {
        for expenses in [None, Some(usd(1_000_000))] {
            for rate in [None, Some(2200)] {
                let y = assemble(2025, FilingStatus::Single, usd(6_000_000), expenses, rate, &p2025());
                assert!(
                    y.notes.iter().any(|n| n.contains("INCOME TAX IS NOT COMPUTED HERE")),
                    "the disclaimer is not conditional on how the report was asked for"
                );
            }
        }
    }

    #[test]
    fn no_set_aside_is_offered_without_a_rate_somebody_chose() {
        // The most actionable number in the report, so it is the one that must not be invented.
        let none = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_000_000)), None, &p2025());
        assert_eq!(none.set_aside, None);
        assert!(none.notes.iter().any(|n| n.contains("out of nothing")));

        // 50,000 profit → SE 7,064.78 (rounded through the same path) plus 22% of 50,000 = 11,000.
        let some = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_000_000)), Some(2200), &p2025());
        let expected = some.se.total.minor + apply_bps(usd(5_000_000), 2200).minor;
        assert_eq!(some.set_aside, Some(usd(expected)));
        assert_eq!(apply_bps(usd(5_000_000), 2200).minor, 1_100_000);
    }

    #[test]
    fn a_loss_sets_aside_nothing_rather_than_a_negative_amount() {
        // FOUND BY RUNNING IT: a year with no revenue and 4,200.00 of declared expenses printed
        // "SET ASIDE -924.00" — 22% of a negative profit. Money you have not made is not money to
        // hold back, and a negative figure there reads as an instruction to spend.
        let y = assemble(2025, FilingStatus::MarriedJointly, usd(0), Some(usd(420_000)), Some(2200), &p2025());
        assert_eq!(y.net_profit.minor, -420_000, "the loss itself is still reported");
        assert_eq!(y.se.total.minor, 0);
        assert_eq!(y.set_aside, Some(usd(0)), "nothing to set aside, and NOT a negative amount");

        // Exactly break-even is the same answer and must not go negative either.
        assert_eq!(assemble(2025, FilingStatus::Single, usd(100_000), Some(usd(100_000)), Some(2200), &p2025()).set_aside, Some(usd(0)));
        // And a real profit is unaffected by the clamp.
        let ok = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_000_000)), Some(2200), &p2025());
        assert_eq!(ok.set_aside, Some(usd(ok.se.total.minor + 1_100_000)));
    }

    #[test]
    fn the_safe_harbour_computes_the_path_it_has_and_names_the_one_it_does_not() {
        let se = self_employment_tax(usd(6_000_000), &p2025(), FilingStatus::Single);
        let (amount, note) = safe_harbour(&se);
        assert_eq!(amount.minor, apply_bps(se.total, 9000).minor);
        assert_eq!(amount.minor, 762_996, "90% of 8,477.73");
        assert!(note.contains("needs last year's return"), "{note}");
        assert!(note.contains("not the bill"), "a safe harbour is a penalty shield, not an estimate: {note}");
    }

    #[test]
    fn every_seeded_year_cites_a_source_and_the_bases_only_rise() {
        assert!(YEARS.len() >= 3, "the scan found only {} years", YEARS.len());
        for y in YEARS {
            assert!(!y.source.trim().is_empty(), "{} has no source", y.year);
            assert!(y.ss_wage_base_minor > 0);
        }
        // The wage base is indexed to average wages and has never fallen. A seeded value that dropped
        // would be a typo, and this is the cheapest place to catch one.
        for w in YEARS.windows(2) {
            assert!(w[1].year > w[0].year, "years must be in order");
            assert!(w[1].ss_wage_base_minor > w[0].ss_wage_base_minor, "{} is not above {}", w[1].year, w[0].year);
        }
        // The most uncertain figure says so on itself, not only in prose somewhere else.
        assert!(params_for(YEARS, 2026).expect("seeded").note.contains("CHECK THIS ONE FIRST"));
    }

    #[test]
    fn the_rates_are_the_published_ones() {
        // Stated as constants so a typo is visible here rather than inside a total.
        assert_eq!(SS_BPS + MEDICARE_BPS, 1530, "15.3% combined");
        assert_eq!(NET_EARNINGS_BPS, 9235);
        assert_eq!(SE_FLOOR_MINOR, 40_000, "$400");
        assert_eq!(ADDITIONAL_MEDICARE_BPS, 90);
    }
}

//! The bar an investment has to clear, which is usually your own credit card.
//!
//! Paying down debt at 24% is a **guaranteed, tax-free 24% return**. Nothing in a market is
//! guaranteed and nothing in a taxable account is tax-free, so the two are not comparable at face
//! value — the market has to clear a HIGHER number to be the better use of the same dollar, and this
//! module computes that number.
//!
//! # Why this exists at all
//!
//! `payoff` knows what debt costs. `evaluate` knows what a signal returns after costs. Nothing put
//! them side by side, so the decision that comes before every investing decision was the one the
//! system could not answer. A tool built to sell investing features would not ship this, because its
//! most common honest answer is **do not invest yet**.
//!
//! # What it will not do
//!
//! It does not predict market returns. The expected return is an INPUT you supply and defend, and it
//! is refused rather than defaulted — inventing it would fabricate the entire comparison. In
//! particular, do NOT feed it a backtested figure from `evaluate`: those are selected from many
//! trials, and `simulate::multiple_testing` demonstrates that the best of 200 worthless signals on
//! pure noise showed +45.9% at t=2.36. A number chosen because it looked good is not an expectation.
use crate::jurisdiction::apply_bps;
use crate::money::{money, Money};

/// One debt, as this module needs it.
#[derive(Debug, Clone, PartialEq)]
pub struct Debt {
    pub account: String,
    /// What is owed, as a POSITIVE magnitude.
    pub balance: Money,
    /// `None` means nobody recorded the rate. It does NOT mean zero — see [`Verdict::RateUnknown`].
    pub apr_bps: Option<i64>,
    /// Whether the interest is deductible (a mortgage, a qualifying student loan). Changes the
    /// answer more than people expect; see [`required_return`].
    pub deductible: bool,
}

/// What you think the market will do, and what it will cost you in tax. Every field is supplied by
/// the caller, because every one of them changes the verdict.
#[derive(Debug, Clone, PartialEq)]
pub struct Expectation {
    /// Your estimate of the ANNUAL pre-tax return, in basis points. Never defaulted.
    pub annual_return_bps: i64,
    /// The rate gains would be taxed at.
    pub tax_bps: i64,
    /// How much MORE than the guaranteed rate you demand before accepting uncertainty. Zero is
    /// permitted and is reported, because zero asserts that a certain return and an uncertain one of
    /// the same size are equally good — which is false.
    pub risk_premium_bps: i64,
    /// Where the estimate came from. A number with no provenance is a guess wearing a decimal point.
    pub source: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Verdict {
    /// The debt wins. `margin_bps` is how far short the market falls.
    PayTheDebt { margin_bps: i64 },
    /// The market clears the bar by `margin_bps`, including the risk premium.
    InvestingClears { margin_bps: i64 },
    /// ABSENT IS NOT ZERO. A missing rate must never read as 0%, because 0% makes investing win by
    /// default on a debt that might be costing 29%.
    RateUnknown,
}

impl Verdict {
    pub fn label(&self) -> &'static str {
        match self {
            Verdict::PayTheDebt { .. } => "pay the debt",
            Verdict::InvestingClears { .. } => "investing clears",
            Verdict::RateUnknown => "rate unknown",
        }
    }
}

/// The pre-tax market return needed to match paying down this debt.
///
/// # The gross-up, and why deductible debt cancels
///
/// Paying non-deductible debt saves you the full rate, TAX-FREE. Matching that with a taxable
/// investment needs `apr / (1 - tax)` — at 24% and a 25% rate, **32%**. That gap is the single most
/// missed fact in this comparison.
///
/// Deductible debt is different and the arithmetic is pleasing: you only really save
/// `apr × (1 - tax)`, because paying it off costs you the deduction. Grossing THAT back up gives
/// `apr × (1 - tax) / (1 - tax)` — the terms cancel, and the required return is simply the nominal
/// APR. So a 6% deductible mortgage needs a 6% market return, while a 6% credit card needs 8%.
///
/// Rounds UP, which makes the market's job harder. That is the conservative direction: the thing
/// being protected is the certain outcome.
pub fn required_return(apr_bps: i64, tax_bps: i64, deductible: bool) -> Result<i64, String> {
    if !(0..10_000).contains(&tax_bps) {
        return Err(format!(
            "a tax rate of {}.{:02}% is not usable here — at 100% there is no after-tax return to compare against, and a negative rate is not a thing",
            tax_bps / 100,
            (tax_bps % 100).abs()
        ));
    }
    if apr_bps < 0 {
        return Err("a negative APR is not a debt this can reason about".to_string());
    }
    if deductible {
        // The gross-up and the lost deduction cancel exactly.
        return Ok(apr_bps);
    }
    let num = i128::from(apr_bps) * 10_000;
    let den = i128::from(10_000 - tax_bps);
    // Ceiling division by hand — `div_ceil` on i128 is not stable on this toolchain, and both
    // operands are known positive here (the guards above), so the +den-1 form is exact.
    let up = (num + den - 1) / den;
    i64::try_from(up).map_err(|_| "the required return overflowed — check the inputs".to_string())
}

#[derive(Debug, Clone, PartialEq)]
pub struct Hurdle {
    pub account: String,
    pub balance: Money,
    pub apr_bps: Option<i64>,
    /// What the market must return, pre-tax, to match paying this down.
    pub required_bps: Option<i64>,
    /// The bar including your risk premium. This is what the expectation is actually judged against.
    pub bar_bps: Option<i64>,
    /// What this debt costs you over a year if you do nothing.
    pub annual_cost: Option<Money>,
    pub verdict: Verdict,
}

/// Judge one debt against an expectation.
pub fn compare(debt: &Debt, e: &Expectation) -> Result<Hurdle, String> {
    let Some(apr) = debt.apr_bps else {
        return Ok(Hurdle {
            account: debt.account.clone(),
            balance: debt.balance,
            apr_bps: None,
            required_bps: None,
            bar_bps: None,
            annual_cost: None,
            verdict: Verdict::RateUnknown,
        });
    };
    let required = required_return(apr, e.tax_bps, debt.deductible)?;
    let bar = required.saturating_add(e.risk_premium_bps.max(0));
    // A TIE GOES TO THE DEBT. Equal numbers are not an equal choice: one is certain and one is not,
    // so `>` rather than `>=` is the whole difference between an honest comparison and a flattering
    // one.
    let verdict = if e.annual_return_bps > bar {
        Verdict::InvestingClears { margin_bps: e.annual_return_bps - bar }
    } else {
        Verdict::PayTheDebt { margin_bps: bar - e.annual_return_bps }
    };
    Ok(Hurdle {
        account: debt.account.clone(),
        balance: debt.balance,
        apr_bps: Some(apr),
        required_bps: Some(required),
        bar_bps: Some(bar),
        annual_cost: Some(apply_bps(debt.balance, apr)),
        verdict,
    })
}

/// Every debt, worst first — the one costing you most against the bar leads.
///
/// Debts with an unknown rate sort to the TOP, not the bottom: an unanswered question about a
/// balance you owe is more urgent than an answered one, and putting them last is how they stay
/// unanswered.
pub fn ladder(debts: &[Debt], e: &Expectation) -> Result<Vec<Hurdle>, String> {
    let mut out: Vec<Hurdle> = debts.iter().map(|d| compare(d, e)).collect::<Result<_, _>>()?;
    out.sort_by_key(|h| match h.verdict {
        Verdict::RateUnknown => (0, 0),
        Verdict::PayTheDebt { margin_bps } => (1, -margin_bps),
        Verdict::InvestingClears { margin_bps } => (2, -margin_bps),
    });
    Ok(out)
}

/// The precondition that comes before either choice.
#[derive(Debug, Clone, PartialEq)]
pub struct Buffer {
    pub liquid: Money,
    pub monthly_need: Money,
    /// Tenths of a month, so the figure is exact without a float.
    pub months_held_tenths: i64,
    pub target_months: i64,
    pub shortfall: Money,
    pub met: bool,
}

/// Whether there is enough cash to absorb a surprise.
///
/// THIS OUTRANKS THE RATE COMPARISON, and the reason is mechanical rather than moral: with no
/// buffer, the next unavoidable expense goes back onto the same card at the same APR. You paid it
/// down and borrowed it again, so the round trip returned nothing and cost you the time. The same
/// applies to selling an investment at whatever price the market happens to be offering that week.
pub fn buffer(liquid: Money, monthly_need: Money, target_months: i64) -> Result<Buffer, String> {
    if monthly_need.minor <= 0 {
        return Err(
            "monthly need must be a positive amount — without it there is no way to say how many months of cover you hold, and a buffer measured in months is the only form of it that means anything"
                .to_string(),
        );
    }
    if target_months < 0 {
        return Err("a negative buffer target is not a target".to_string());
    }
    let months_held_tenths = liquid.minor.max(0).saturating_mul(10) / monthly_need.minor;
    let target = monthly_need.minor.saturating_mul(target_months);
    let shortfall = (target - liquid.minor).max(0);
    Ok(Buffer {
        liquid,
        monthly_need,
        months_held_tenths,
        target_months,
        shortfall: money(shortfall, liquid.currency),
        met: shortfall == 0,
    })
}

/// What to do with the next spare dollar.
#[derive(Debug, Clone, PartialEq)]
pub enum NextDollar {
    /// Build the buffer first, whatever the rates say.
    BuildBuffer { shortfall: Money },
    /// Answer the unknown rates before deciding anything.
    FindOutTheRate { accounts: Vec<String> },
    PayDebt { account: String, apr_bps: i64 },
    /// Nothing is beating the market on your own numbers.
    Invest,
    /// No debts, no buffer gap — the comparison has nothing to weigh.
    NothingToWeigh,
}

/// The single recommendation, in the order the reasons actually bind.
pub fn next_dollar(b: &Buffer, ladder: &[Hurdle]) -> NextDollar {
    if !b.met {
        return NextDollar::BuildBuffer { shortfall: b.shortfall };
    }
    let unknown: Vec<String> = ladder.iter().filter(|h| h.verdict == Verdict::RateUnknown).map(|h| h.account.clone()).collect();
    if !unknown.is_empty() {
        return NextDollar::FindOutTheRate { accounts: unknown };
    }
    for h in ladder {
        if let (Verdict::PayTheDebt { .. }, Some(apr)) = (&h.verdict, h.apr_bps) {
            return NextDollar::PayDebt { account: h.account.clone(), apr_bps: apr };
        }
    }
    if ladder.is_empty() {
        NextDollar::NothingToWeigh
    } else {
        NextDollar::Invest
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    fn card(apr: i64) -> Debt {
        Debt { account: "card".into(), balance: usd(500_000), apr_bps: Some(apr), deductible: false }
    }

    fn expect(ret: i64, tax: i64, premium: i64) -> Expectation {
        Expectation { annual_return_bps: ret, tax_bps: tax, risk_premium_bps: premium, source: "test".into() }
    }

    #[test]
    fn the_tax_gross_up_raises_the_bar_and_it_is_the_fact_people_miss() {
        // 24% non-deductible, taxed at 25%: the market must return 32% PRE-TAX to match.
        assert_eq!(required_return(2400, 2500, false).expect("valid"), 3200);
        // Same debt, no tax at all: the bar is the rate itself.
        assert_eq!(required_return(2400, 0, false).expect("valid"), 2400);
        // A higher tax rate makes the debt look BETTER, not worse.
        assert!(required_return(2400, 3700, false).expect("valid") > 3200);
        // It rounds UP, so the market is never given the benefit of a fraction.
        assert_eq!(required_return(1, 3300, false).expect("valid"), 2, "1bp / 0.67 = 1.49 → 2");
    }

    #[test]
    fn deductible_debt_cancels_exactly_and_needs_only_its_nominal_rate() {
        // The gross-up and the lost deduction are the same factor, so they cancel.
        for tax in [0, 1200, 2500, 3700] {
            assert_eq!(required_return(600, tax, true).expect("valid"), 600, "at tax {tax}");
        }
        // Which is why a 6% mortgage and a 6% card are NOT the same decision.
        assert_eq!(required_return(600, 2500, true).expect("valid"), 600);
        assert_eq!(required_return(600, 2500, false).expect("valid"), 800);
    }

    #[test]
    fn a_missing_apr_is_unknown_and_never_reads_as_zero_percent() {
        // THE DANGEROUS DEFAULT. A 0% reading makes investing win against a debt that might be
        // costing 29%, and it would do so silently.
        let d = Debt { account: "store card".into(), balance: usd(300_000), apr_bps: None, deductible: false };
        let h = compare(&d, &expect(700, 2500, 0)).expect("resolvable");
        assert_eq!(h.verdict, Verdict::RateUnknown);
        assert_eq!(h.required_bps, None);
        assert_eq!(h.annual_cost, None, "a cost computed from an unknown rate would be fiction");
        // And it is not quietly treated as clearing the bar.
        assert!(!matches!(h.verdict, Verdict::InvestingClears { .. }));
    }

    #[test]
    fn a_tie_goes_to_the_debt_because_certain_and_uncertain_are_not_equal() {
        // Bar is exactly 32%; an expectation of exactly 32% does NOT clear it.
        let h = compare(&card(2400), &expect(3200, 2500, 0)).expect("valid");
        assert_eq!(h.bar_bps, Some(3200));
        assert_eq!(h.verdict, Verdict::PayTheDebt { margin_bps: 0 }, "equal numbers are not an equal choice");
        // One basis point more and it clears.
        let over = compare(&card(2400), &expect(3201, 2500, 0)).expect("valid");
        assert_eq!(over.verdict, Verdict::InvestingClears { margin_bps: 1 });
    }

    #[test]
    fn the_risk_premium_raises_the_bar_it_does_not_change_the_required_return() {
        let h = compare(&card(2400), &expect(3500, 2500, 500)).expect("valid");
        assert_eq!(h.required_bps, Some(3200), "the arithmetic bar is unchanged");
        assert_eq!(h.bar_bps, Some(3700), "what you actually demand is higher");
        assert_eq!(h.verdict, Verdict::PayTheDebt { margin_bps: 200 }, "35% loses to a 37% demand");
        // Without the premium the same expectation would have cleared — which is the point of it.
        assert!(matches!(compare(&card(2400), &expect(3500, 2500, 0)).expect("valid").verdict, Verdict::InvestingClears { .. }));
    }

    #[test]
    fn the_realistic_case_is_that_the_card_wins_by_a_lot() {
        // A 24.99% card against a defensible 7% long-run expectation.
        let h = compare(&card(2499), &expect(700, 2500, 0)).expect("valid");
        assert_eq!(h.required_bps, Some(3332), "24.99% tax-free needs 33.32% pre-tax");
        assert_eq!(h.verdict, Verdict::PayTheDebt { margin_bps: 2632 }, "the market falls 26.32 points short");
        // And the annual cost of doing nothing is stated in money, not percent.
        assert_eq!(h.annual_cost, Some(usd(124_950)), "24.99% of 5000.00");
    }

    #[test]
    fn a_low_rate_deductible_loan_is_where_investing_actually_wins() {
        let mortgage = Debt { account: "mortgage".into(), balance: usd(20_000_000), apr_bps: Some(300), deductible: true };
        let h = compare(&mortgage, &expect(700, 2500, 100)).expect("valid");
        assert_eq!(h.required_bps, Some(300));
        assert_eq!(h.bar_bps, Some(400));
        assert_eq!(h.verdict, Verdict::InvestingClears { margin_bps: 300 });
    }

    #[test]
    fn an_impossible_tax_rate_is_refused_rather_than_dividing_by_zero() {
        assert!(required_return(2400, 10_000, false).unwrap_err().contains("at 100% there is no after-tax return"));
        assert!(required_return(2400, 12_000, false).is_err());
        assert!(required_return(2400, -100, false).is_err());
        assert!(required_return(-1, 2500, false).unwrap_err().contains("negative APR"));
        // Deductible debt still refuses the same inputs rather than short-circuiting past the check.
        assert!(required_return(600, 10_000, true).is_err());
    }

    #[test]
    fn unknown_rates_sort_to_the_top_because_that_is_what_keeps_them_from_being_ignored() {
        let debts = vec![
            Debt { account: "mortgage".into(), balance: usd(20_000_000), apr_bps: Some(300), deductible: true },
            card(2499),
            Debt { account: "mystery".into(), balance: usd(100_000), apr_bps: None, deductible: false },
            Debt { account: "auto".into(), balance: usd(1_200_000), apr_bps: Some(900), deductible: false },
        ];
        let l = ladder(&debts, &expect(700, 2500, 0)).expect("valid");
        assert_eq!(l[0].account, "mystery", "an unanswered question outranks an answered one");
        assert_eq!(l[1].account, "card", "then the worst gap");
        assert_eq!(l[2].account, "auto");
        assert_eq!(l[3].account, "mortgage", "the only one investing beats comes last");
        assert!(matches!(l[3].verdict, Verdict::InvestingClears { .. }));
    }

    #[test]
    fn the_buffer_outranks_every_rate_because_without_it_the_paydown_round_trips() {
        // 1,200.00 held against a 2,000.00 month is 0.6 months.
        let b = buffer(usd(120_000), usd(200_000), 3).expect("valid");
        assert_eq!(b.months_held_tenths, 6);
        assert_eq!(b.shortfall.minor, 480_000, "3 months is 6000.00; 1200.00 is held");
        assert!(!b.met);

        // Even against a 24.99% card, the buffer comes first.
        let l = ladder(&[card(2499)], &expect(700, 2500, 0)).expect("valid");
        assert_eq!(next_dollar(&b, &l), NextDollar::BuildBuffer { shortfall: usd(480_000) });

        // Once it is met, the card wins.
        let full = buffer(usd(600_000), usd(200_000), 3).expect("valid");
        assert!(full.met);
        assert_eq!(full.months_held_tenths, 30);
        assert_eq!(next_dollar(&full, &l), NextDollar::PayDebt { account: "card".into(), apr_bps: 2499 });
    }

    #[test]
    fn an_unknown_rate_blocks_the_recommendation_rather_than_being_skipped_over() {
        let full = buffer(usd(600_000), usd(200_000), 3).expect("valid");
        let debts = vec![card(300), Debt { account: "mystery".into(), balance: usd(100_000), apr_bps: None, deductible: false }];
        // Even though the 3% card loses to a 7% expectation, the unknown one must be answered first.
        let l = ladder(&debts, &expect(700, 2500, 0)).expect("valid");
        assert_eq!(next_dollar(&full, &l), NextDollar::FindOutTheRate { accounts: vec!["mystery".into()] });
    }

    #[test]
    fn with_a_buffer_and_no_debt_beating_the_market_the_answer_is_invest() {
        let full = buffer(usd(600_000), usd(200_000), 3).expect("valid");
        let mortgage = Debt { account: "mortgage".into(), balance: usd(20_000_000), apr_bps: Some(300), deductible: true };
        let l = ladder(&[mortgage], &expect(700, 2500, 100)).expect("valid");
        assert_eq!(next_dollar(&full, &l), NextDollar::Invest);
        // And with nothing at all to weigh, it says so rather than recommending anything.
        assert_eq!(next_dollar(&full, &[]), NextDollar::NothingToWeigh);
    }

    #[test]
    fn a_buffer_with_no_monthly_need_is_refused_rather_than_reported_as_infinite() {
        let err = buffer(usd(600_000), usd(0), 3).unwrap_err();
        assert!(err.contains("measured in months is the only form of it that means anything"), "{err}");
        assert!(buffer(usd(600_000), usd(-1), 3).is_err());
        assert!(buffer(usd(600_000), usd(200_000), -1).is_err());
        // Holding nothing is zero months, not an error.
        assert_eq!(buffer(usd(0), usd(200_000), 3).expect("valid").months_held_tenths, 0);
    }
}

