// The GPU graph renderer — instanced nodes + edges in two draw calls (`gpu-graph-slice-1-renderer-core`).
//
// WHY. The DOM graph costs ~19 µs per element per style/layout pass, linearly: 402 nodes ⇒ 99 ms,
// 8,002 ⇒ 1,051 ms, and one click on the 402-node Design Studio graph measured 371–506 ms. At ~6
// elements per node that is ~115 µs/node, so ten thousand nodes is a second of frozen UI and a million
// is two minutes — with the browser out of memory long before it gets there. No amount of trimming
// elements per node fixes an O(N) shape.
//
// Measured in this app's own WebKitGTK webview, one `drawArraysInstanced` at 1920×1080:
//
//     1M small quads (nodes)    1.55 ms   645 fps    11 MB VRAM
//     5M wide quads (edges)    13.2  ms    76 fps    57 MB
//    10M wide quads            22.2  ms    45 fps   114 MB
//
// So a million nodes is a TENTH of a frame budget and the interesting cost is edges, which go
// fill-bound between 5M and 10M. That asymmetry drives two decisions below.
//
// WEBGL2, AND IT MUST STAY WEBGL2. `navigator.gpu` is ABSENT in WebKitGTK — measured, not assumed — so
// there is no WebGPU path to migrate to. What is available and used here: instanced arrays, integer
// vertex attributes, and `texelFetch` on a float texture.
//
// NODES ARE NOT CPU-CULLED, deliberately. Culling them would mean an O(N) pass per frame on the main
// thread, which is precisely the cost this module exists to delete — and it would buy nothing, because
// the GPU clips off-screen geometry for free and the whole million-node draw is 1.55 ms. Edges are the
// ones worth culling, and that is the LOD slice, not this one.
//
// POSITIONS LIVE IN A TEXTURE, NOT AN ATTRIBUTE. Both nodes and edges need them, and an edge that stored
// its endpoints as floats would need rebuilding whenever a node moved — O(E) for a one-node change. With
// positions in an RG32F texture the edge buffer is just two indices, and moving a node is ONE
// `texSubImage2D` texel: O(1). It also halves edge memory (8 B/edge rather than 16 B).

import type { GraphView } from "@/shared/ui/layouts/useGraphViewport";
import { buildGrid, pickRect, queryRect, type SpatialGrid } from "@/shared/lib/graph/spatialGrid";
import { layoutLabel, type GlyphAtlas } from "@/shared/lib/graph/glyphAtlas";
import { levelFor, type LodPyramid } from "@/shared/lib/graph/lodPyramid";

/** Per-instance state byte. Drives appearance in the shader; never causes a re-upload of anything else. */
export const NODE_NORMAL = 0;
export const NODE_SELECTED = 1;
export const NODE_DIMMED = 2;

/** Width of the position texture. 2048 keeps it well inside every `MAX_TEXTURE_SIZE` we could meet
 *  (this webview reports 16384) while covering 1M nodes in 489 rows. */
const POS_TEX_W = 2048;

export interface GraphRenderer {
  /**
   * Upload node positions/sizes/colours. O(n); rebuilds the pick index. `rgba` is packed 0xAABBGGRR.
   *
   * `size` is INTERLEAVED `[w0,h0, w1,h1, …]`. It was a single scalar per node and that shipped every
   * card as a square — 172x58 drawn 172x172, swallowing the rows above and below.
   */
  setNodes(xy: Float32Array, size: Float32Array, rgba: Uint32Array, count: number): void;
  /** Upload edges as node-index PAIRS. O(e). Endpoints are read from the position texture at draw time. */
  setEdges(pairs: Uint32Array, count: number): void;
  /** Change one node's state byte. O(1) — one `bufferSubData` of a single byte. */
  setState(index: number, state: number): void;
  /** Move one node. O(1) — one texel. Keeps the pick index correct by marking it stale. */
  setPosition(index: number, x: number, y: number): void;
  /** Pan/zoom. O(1) — uniforms only, no geometry touched. */
  setView(view: GraphView): void;
  /** Match the drawing buffer to the CSS size × dpr. */
  resize(cssW: number, cssH: number, dpr?: number): void;
  /** Two instanced draw calls. O(1) CPU regardless of node count. */
  draw(): void;
  /** Node index under a CSS-pixel point, or -1. O(1) expected — a grid query, never a scan, and never
   *  `readPixels` (a GPU readback is a pipeline stall costing more than the query it would replace). */
  pick(cssX: number, cssY: number): number;
  /**
   * Attach an LOD pyramid. From here the renderer draws the level the zoom can actually resolve, so the
   * frame cost tracks VIEWPORT AREA rather than node count. Pass `null` to go back to drawing the nodes.
   */
  /**
   * The card palette as 0..1 RGBA. Resolve from the live cascade (--bg-elev, --border, --accent) rather
   * than hard-coding: a second copy of the palette is a second thing to keep in sync with the theme.
   */
  setPalette?(
    surface: readonly number[],
    border: readonly number[],
    accent: readonly number[],
    /** The label colour — `--fg`. Omitted by an older caller, which keeps the previous near-white. */
    text?: readonly number[],
  ): void;
  setLod(pyramid: LodPyramid | null, aggregateColor?: number): void;
  /** Which pyramid level the last `draw()` used. 0 means the nodes themselves. */
  readonly lodLevel: number;
  /** Upload the glyph atlas. Once per (font, size) — never per frame. */
  setAtlas(atlas: GlyphAtlas): void;
  /** Label text per node index. `null`/absent entries simply get no label. */
  setLabels(labels: readonly (string | null)[]): void;
  /** How many glyph instances the last `draw()` emitted — the bounded number, for tests and telemetry. */
  readonly lastGlyphCount: number;
  dispose(): void;
  readonly nodeCount: number;
  readonly edgeCount: number;
  /**
   * True from `webglcontextlost` until a successful `webglcontextrestored` rebuild. `draw()` is a no-op
   * while this is true — the GL calls would be no-ops against a dead context anyway, but skipping them
   * also skips the CPU work (label layout, LOD level arithmetic) that would otherwise run for nothing.
   */
  readonly contextLost: boolean;
}

const NODE_VS = `#version 300 es
layout(location=0) in vec2 aCorner;
layout(location=1) in vec2 aSize;
layout(location=2) in vec4 aColor;
layout(location=3) in float aState;
uniform sampler2D uPos;
uniform vec2 uViewport;
uniform vec2 uTranslate;
uniform float uScale;
out vec2 vCorner; out vec4 vColor; out float vState; out float vPx; out vec2 vHalf; out float vShort;
void main() {
  ivec2 t = ivec2(gl_InstanceID % ${POS_TEX_W}, gl_InstanceID / ${POS_TEX_W});
  vec2 p = texelFetch(uPos, t, 0).rg;
  vec2 world = p + aCorner * (aSize * 0.5);
  vec2 s = world * uScale + uTranslate;
  gl_Position = vec4(s.x / uViewport.x * 2.0 - 1.0, 1.0 - s.y / uViewport.y * 2.0, 0.0, 1.0);
  vCorner = aCorner; vColor = aColor; vState = aState;
  // Half-extents in world units, normalised on the SHORT axis. The fragment shader evaluates the SDF in
  // this space so the corner radius stays CIRCULAR: evaluating it in raw (-1..1) corner space stretches
  // the radius with the aspect ratio and gives a 172x58 card lozenge ends.
  vHalf = aSize / min(aSize.x, aSize.y);
  // The short half-extent in WORLD units. The fragment shader measures the border, the dot and the
  // padding in world units (they are card geometry, not screen geometry), and this is the conversion.
  vShort = min(aSize.x, aSize.y) * 0.5;
  // The THIN axis sets the pixel gradient, so antialiasing must be derived from it — using the long axis
  // makes a wide, short card's edges soften as if it were three times taller than it is.
  vPx = min(aSize.x, aSize.y) * uScale;
}`;

// Rounded-rect SDF. Chosen over a plain quad because the cost is PER-PIXEL, not per-node — the shape is
// free at any count — and because it stays crisp at every zoom where a bitmap or a CSS border would not.
const NODE_FS = `#version 300 es
precision mediump float;
in vec2 vCorner; in vec4 vColor; in float vState; in float vPx; in vec2 vHalf; in float vShort;
out vec4 outColor;
uniform vec4 uSurface;
uniform vec4 uBorder;
uniform vec4 uAccent;
float sdRoundBox(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r;
}
void main() {
  // vCorner is -1..1 on both axes; scaling by vHalf restores the real aspect, so the box is measured in
  // units of the SHORT half-extent and the radius is the same in x and y.
  vec2 p = vCorner * vHalf;
  // Card metrics, mirroring .ds-node in designStudio.css. Expressed as world units over the short
  // half-extent so they travel with the card's size instead of being pinned to one graph's numbers:
  //   border-radius 11px · border 1px · padding 11px 13px · an 8px role dot in the first grid column.
  float u = 1.0 / max(vShort, 0.0001);      // one world unit, in SDF space
  float d = sdRoundBox(p, vHalf, 11.0 * u);
  // One pixel in local units, so antialiasing is a constant screen width at any zoom.
  float aa = max(fwidth(d), 1.0 / max(vPx, 1.0));
  float card = 1.0 - smoothstep(-aa, aa, d);
  if (card <= 0.003) discard;

  float st = floor(vState * 255.0 + 0.5);
  // The BORDER carries the state, never the fill — .ds-node keeps its elevated surface when selected
  // (#2491), and painting the body would lose the role dot and the text contrast with it.
  vec4 border = uBorder;
  if (st == 1.0) border = uAccent;
  if (st == 3.0) border = mix(uBorder, uAccent, 0.55);

  // Inset by one world unit — the 1px border.
  float interior = 1.0 - smoothstep(-aa, aa, d + 1.0 * u);
  vec4 col = mix(border, uSurface, interior);

  // The role dot: 8px across, centred in the first grid column (padding-left 13 + radius 4) and on the
  // NAME row (padding-top 11 + half of that row). This is the only place the role colour appears — it
  // used to be the entire card, which is what made the graph read as coloured blobs.
  vec2 dotC = vec2(-vHalf.x + 17.0 * u, -vHalf.y + 19.0 * u);
  float dotD = length(p - dotC) - 4.0 * u;
  float dot = 1.0 - smoothstep(-aa, aa, dotD);
  col.rgb = mix(col.rgb, vColor.rgb, dot * vColor.a);

  // Dimmed: a related/background node loses contrast without losing its identity.
  float alpha = col.a;
  if (st == 2.0) { col.rgb = mix(col.rgb, uSurface.rgb, 0.45); alpha *= 0.55; }
  outColor = vec4(col.rgb * card * alpha, card * alpha);
}`;

const EDGE_VS = `#version 300 es
layout(location=0) in vec2 aCorner;
layout(location=1) in uvec2 aPair;
layout(location=2) in vec4 aColor;
uniform sampler2D uPos;
uniform vec2 uViewport;
uniform vec2 uTranslate;
uniform float uScale;
uniform float uWidthPx;
out vec4 vColor;
vec2 fetchPos(uint i) {
  return texelFetch(uPos, ivec2(int(i) % ${POS_TEX_W}, int(i) / ${POS_TEX_W}), 0).rg;
}
void main() {
  vec2 a = fetchPos(aPair.x) * uScale + uTranslate;
  vec2 b = fetchPos(aPair.y) * uScale + uTranslate;
  vec2 d = b - a;
  float len = length(d);
  // A zero-length edge (a self-loop, or two nodes not yet laid out) has no direction; normalizing it
  // yields NaN and the GPU renders a full-screen triangle of garbage. Fall back to a fixed axis.
  vec2 dir = len > 1e-6 ? d / len : vec2(1.0, 0.0);
  vec2 nrm = vec2(-dir.y, dir.x);
  // Width in SCREEN px, so lines stay legible when zoomed out instead of vanishing sub-pixel.
  vec2 s = mix(a, b, aCorner.x) + nrm * aCorner.y * uWidthPx;
  gl_Position = vec4(s.x / uViewport.x * 2.0 - 1.0, 1.0 - s.y / uViewport.y * 2.0, 0.0, 1.0);
  vColor = aColor;
}`;

const EDGE_FS = `#version 300 es
precision mediump float;
in vec4 vColor; out vec4 outColor;
void main() { outColor = vec4(vColor.rgb * vColor.a, vColor.a); }`;

// Labels are drawn as one instanced quad per GLYPH, positioned in SCREEN space. Screen space rather
// than world space because a label must stay the same size relative to its node while the graph zooms,
// and because the CPU is already visiting each visible node to decide whether it gets a label at all.
const LABEL_VS = `#version 300 es
layout(location=0) in vec2 aCorner;
layout(location=1) in vec4 aRect;
layout(location=2) in vec4 aUv;
uniform vec2 uViewport;
out vec2 vUv;
void main() {
  vec2 s = aRect.xy + aCorner * aRect.zw;
  gl_Position = vec4(s.x / uViewport.x * 2.0 - 1.0, 1.0 - s.y / uViewport.y * 2.0, 0.0, 1.0);
  vUv = mix(aUv.xy, aUv.zw, aCorner);
}`;

// `fwidth` of the sampled distance is the whole reason this is a distance field: it gives the width of
// one screen pixel IN FIELD UNITS, so the same texture antialiases correctly at any zoom instead of
// blurring in and aliasing out the way a bitmap atlas does.
const LABEL_FS = `#version 300 es
precision mediump float;
in vec2 vUv; out vec4 outColor;
uniform sampler2D uAtlas;
uniform vec4 uColor;
void main() {
  float d = texture(uAtlas, vUv).r;
  float aa = max(fwidth(d), 0.001);
  float a = smoothstep(0.5 - aa, 0.5 + aa, d);
  if (a <= 0.004) discard;
  outColor = vec4(uColor.rgb * uColor.a * a, uColor.a * a);
}`;

/**
 * Smallest label the eye can use, in screen px of em size.
 *
 * This is not a taste setting — it is what BOUNDS THE WORK. A glyph is emitted only for a node whose
 * label would clear this, so the number of labels is limited by screen area divided by legible size,
 * never by graph size. Without it a million nodes means ~12M glyph quads, which is both over the frame
 * budget (measured: 10M wide quads = 22.2 ms) and unreadable, which is the more important half.
 */
const MIN_LABEL_PX = 7;

/**
 * Hard cap on glyph instances per frame.
 *
 * The legibility gate already bounds this in every sane view; the cap covers the pathological one — a
 * layout that stacked every node at one point would pass the gate for all of them at once. Truncating
 * loses labels, which is visible and recoverable; not truncating stalls the frame.
 */
const MAX_LABEL_GLYPHS = 20000;

function compile(gl: WebGL2RenderingContext, type: number, src: string): WebGLShader {
  const sh = gl.createShader(type);
  if (!sh) throw new Error("createShader returned null");
  gl.shaderSource(sh, src);
  gl.compileShader(sh);
  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(sh) ?? "(no log)";
    gl.deleteShader(sh);
    throw new Error(`shader compile failed: ${log}`);
  }
  return sh;
}

function link(gl: WebGL2RenderingContext, vsSrc: string, fsSrc: string): WebGLProgram {
  const vs = compile(gl, gl.VERTEX_SHADER, vsSrc);
  const fs = compile(gl, gl.FRAGMENT_SHADER, fsSrc);
  const p = gl.createProgram();
  if (!p) throw new Error("createProgram returned null");
  gl.attachShader(p, vs);
  gl.attachShader(p, fs);
  gl.linkProgram(p);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
    const log = gl.getProgramInfoLog(p) ?? "(no log)";
    gl.deleteProgram(p);
    throw new Error(`program link failed: ${log}`);
  }
  return p;
}

export interface GraphRendererOpts {
  /** Edge width in screen px. Default 1.5. */
  edgeWidthPx?: number;
  /** Edge colour, packed 0xAABBGGRR. Default a dim neutral. */
  edgeColor?: number;
  /**
   * Keep the drawing buffer after compositing so a caller can read the pixels back. OFF by default —
   * it costs a copy every frame and no product path needs it.
   *
   * It exists because verifying this renderer WITHOUT it is not possible: a composited WebGL buffer is
   * cleared before any later read, so `drawImage` reports an empty canvas for a graph that drew fine.
   * That false negative is how "the pixels are lit" became the whole of slice 5's visual verification —
   * and a graph drawn with every card three times too tall passes that check.
   */
  preserveDrawingBuffer?: boolean;
  /**
   * Fired the instant `webglcontextlost` is observed — before any rebuild is attempted. The renderer is
   * blank from here until (if ever) `onContextRestored` fires; a caller uses this to swap in a fallback
   * rather than leave a silently blank canvas on screen.
   */
  onContextLost?: () => void;
  /** Fired after `webglcontextrestored` has rebuilt every GL object and re-uploaded the current state. */
  onContextRestored?: () => void;
}

/**
 * Create a renderer over `canvas`, or `null` when WebGL2 is unavailable.
 *
 * NULL IS A CONTRACT, not a failure to log and forget: the caller is expected to keep its DOM path and
 * fall back to it. That fallback is also what preserves the accessibility tree, which a canvas does not
 * have — see the epic. A renderer that threw here would take the page down on exactly the machines least
 * able to afford it.
 */
export function createGraphRenderer(canvas: HTMLCanvasElement, opts: GraphRendererOpts = {}): GraphRenderer | null {
  const ctx = canvas.getContext("webgl2", {
    antialias: false, alpha: true, premultipliedAlpha: true, depth: false,
    preserveDrawingBuffer: opts.preserveDrawingBuffer ?? false,
  });
  if (!ctx) return null;
  // Bound to its own non-nullable const: the closures below are FUNCTION DECLARATIONS, which hoist, so
  // TypeScript will not carry the `if (!ctx)` narrowing into them.
  const gl: WebGL2RenderingContext = ctx;

  const edgeWidthPx = opts.edgeWidthPx ?? 1.5;
  // The card palette. These defaults are a dark-surface guess; the caller resolves the REAL tokens
  // (--bg-elev, --border, --accent) from the live cascade, so the graph follows the theme instead of
  // carrying a second copy of it.
  let surfaceRgba: [number, number, number, number] = [0.11, 0.12, 0.14, 1];
  let borderRgba: [number, number, number, number] = [0.25, 0.27, 0.30, 1];
  let accentRgba: [number, number, number, number] = [0.36, 0.62, 1.0, 1];
  // The LABEL colour. It was a literal in the draw path — written when the card was drawn in the role
  // colour, where near-white read against anything. The card is the surface token now, so the text's
  // contrast against it was coincidence rather than a guarantee, and on a light theme it was
  // near-white on near-white. This is the last colour in the renderer that has to come from the theme.
  let textRgba: [number, number, number, number] = [0.93, 0.94, 0.96, 1];
  const edgeColor = opts.edgeColor ?? 0x66808080;

  // Every GL object below is invalidated the instant the context is lost, so each is a `let` assigned
  // by `initGLResources()` — never inline — and reassigned wholesale on `webglcontextrestored`. See
  // `restoreContext`.
  // `!` (definite assignment): each is assigned inside `initGLResources()`, a separate function TS
  // cannot trace into for control-flow analysis — the assertion says what the call below guarantees.
  let nodeProg!: WebGLProgram, edgeProg!: WebGLProgram, labelProg!: WebGLProgram;
  let nodeQuadBuf!: WebGLBuffer, edgeQuadBuf!: WebGLBuffer, unitQuadBuf!: WebGLBuffer;
  let sizeBuf!: WebGLBuffer, colorBuf!: WebGLBuffer, stateBuf!: WebGLBuffer, pairBuf!: WebGLBuffer, edgeColorBuf!: WebGLBuffer;
  let posTex!: WebGLTexture, atlasTex!: WebGLTexture;
  let labelRectBuf!: WebGLBuffer, labelUvBuf!: WebGLBuffer;
  let nodeVao!: WebGLVertexArrayObject, edgeVao!: WebGLVertexArrayObject, labelVao!: WebGLVertexArrayObject;
  let uNode!: {
    pos: WebGLUniformLocation | null; surface: WebGLUniformLocation | null; border: WebGLUniformLocation | null;
    accent: WebGLUniformLocation | null; viewport: WebGLUniformLocation | null; translate: WebGLUniformLocation | null;
    scale: WebGLUniformLocation | null;
  };
  let uLabel!: { atlas: WebGLUniformLocation | null; viewport: WebGLUniformLocation | null; color: WebGLUniformLocation | null };
  let uEdge!: {
    pos: WebGLUniformLocation | null; viewport: WebGLUniformLocation | null; translate: WebGLUniformLocation | null;
    scale: WebGLUniformLocation | null; width: WebGLUniformLocation | null;
  };

  // Unit quad, shared by both programs. Corner space is (-1..1) for nodes and (0..1, -0.5..0.5) for
  // edges, so each program reinterprets the same four vertices rather than owning a second buffer.
  // Plain data, not GL objects — survives a context loss untouched, so these stay outside `initGLResources`.
  const nodeQuad = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);
  const edgeQuad = new Float32Array([0, -0.5, 1, -0.5, 0, 0.5, 1, 0.5]);
  // Labels need a 0..1 corner: `aRect.xy` is the quad's top-left and the corner scales `aRect.zw` off
  // it. The node quad is -1..1 (centred) and the edge quad is 0..1 by 0.5 (a ribbon), so neither fits.
  const unitQuad = new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]);

  let nodeCount = 0;
  let edgeCount = 0;
  let posRows = 1;
  let stateBytes = new Uint8Array(0);
  // Annotated: an un-annotated `new Float32Array(0)` infers `Float32Array<ArrayBuffer>`, which refuses the
  // caller's `Float32Array` (ArrayBufferLike) under TS 5.7 typed-array generics.
  let positions: Float32Array = new Float32Array(0);
  let halfW = new Float32Array(0);
  let halfH = new Float32Array(0);
  /** The largest node radius, kept as the pick search reach. Computed ONCE per `setNodes`: deriving it
   *  inside `pick` was an O(n) scan on every mousemove, which would have quietly cost more than the
   *  index saves and made the O(1) claim false. */
  let maxRadius = 0;
  let grid: SpatialGrid | null = null;
  let gridStale = true;
  let view: GraphView = { tx: 0, ty: 0, scale: 1 };
  let vpW = 1, vpH = 1;
  let lod: LodPyramid | null = null;
  let lodLevel = 0;
  let lodColor = 0xffb0b0b0;
  /** The level-0 node arrays, kept so going back down the pyramid does not need the caller. */
  let baseNodes: { xy: Float32Array; size: Float32Array; rgba: Uint32Array; n: number } | null = null;
  let atlas: GlyphAtlas | null = null;
  let labels: readonly (string | null)[] = [];
  let lastGlyphCount = 0;
  // Reused across frames so the label pass allocates NOTHING per frame — the point of bounding the
  // glyph count is lost if the bound is re-allocated 60 times a second.
  const labelRects = new Float32Array(MAX_LABEL_GLYPHS * 4);
  const labelUvs = new Float32Array(MAX_LABEL_GLYPHS * 4);
  let visible = new Uint32Array(4096);

  /**
   * Link the programs, create every buffer/texture/VAO, resolve uniform locations, and set the static
   * GL state (blend, quads, texture params). Runs once at construction and again — verbatim — from
   * `restoreContext` after `webglcontextrestored`, because a restored context starts with NONE of this:
   * every object above is gone, and the spec gives you a blank context to rebuild into.
   */
  function initGLResources(): boolean {
    try {
      nodeProg = link(gl, NODE_VS, NODE_FS);
      edgeProg = link(gl, EDGE_VS, EDGE_FS);
      labelProg = link(gl, LABEL_VS, LABEL_FS);
    } catch {
      // A driver that cannot compile these is a driver we fall back from, not one we crash on. On a
      // RESTORE this just leaves `contextLost` true instead of throwing out of an event handler.
      return false;
    }

    nodeQuadBuf = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, nodeQuadBuf);
    gl.bufferData(gl.ARRAY_BUFFER, nodeQuad, gl.STATIC_DRAW);
    edgeQuadBuf = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, edgeQuadBuf);
    gl.bufferData(gl.ARRAY_BUFFER, edgeQuad, gl.STATIC_DRAW);
    unitQuadBuf = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, unitQuadBuf);
    gl.bufferData(gl.ARRAY_BUFFER, unitQuad, gl.STATIC_DRAW);

    sizeBuf = gl.createBuffer()!;
    colorBuf = gl.createBuffer()!;
    stateBuf = gl.createBuffer()!;
    pairBuf = gl.createBuffer()!;
    edgeColorBuf = gl.createBuffer()!;
    posTex = gl.createTexture()!;
    atlasTex = gl.createTexture()!;
    labelRectBuf = gl.createBuffer()!;
    labelUvBuf = gl.createBuffer()!;
    nodeVao = gl.createVertexArray()!;
    edgeVao = gl.createVertexArray()!;
    labelVao = gl.createVertexArray()!;

    uNode = {
      pos: gl.getUniformLocation(nodeProg, "uPos"),
      surface: gl.getUniformLocation(nodeProg, "uSurface"),
      border: gl.getUniformLocation(nodeProg, "uBorder"),
      accent: gl.getUniformLocation(nodeProg, "uAccent"),
      viewport: gl.getUniformLocation(nodeProg, "uViewport"),
      translate: gl.getUniformLocation(nodeProg, "uTranslate"),
      scale: gl.getUniformLocation(nodeProg, "uScale"),
    };
    uLabel = {
      atlas: gl.getUniformLocation(labelProg, "uAtlas"),
      viewport: gl.getUniformLocation(labelProg, "uViewport"),
      color: gl.getUniformLocation(labelProg, "uColor"),
    };
    uEdge = {
      pos: gl.getUniformLocation(edgeProg, "uPos"),
      viewport: gl.getUniformLocation(edgeProg, "uViewport"),
      translate: gl.getUniformLocation(edgeProg, "uTranslate"),
      scale: gl.getUniformLocation(edgeProg, "uScale"),
      width: gl.getUniformLocation(edgeProg, "uWidthPx"),
    };

    gl.bindTexture(gl.TEXTURE_2D, posTex);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

    gl.bindTexture(gl.TEXTURE_2D, atlasTex);
    // LINEAR: the field is meant to be interpolated — nearest sampling would step the distance and put
    // the antialiasing back where it started.
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

    gl.bindVertexArray(labelVao);
    gl.bindBuffer(gl.ARRAY_BUFFER, unitQuadBuf);
    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    gl.bindBuffer(gl.ARRAY_BUFFER, labelRectBuf);
    gl.bufferData(gl.ARRAY_BUFFER, labelRects.byteLength, gl.DYNAMIC_DRAW);
    gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 0, 0); gl.vertexAttribDivisor(1, 1);
    gl.bindBuffer(gl.ARRAY_BUFFER, labelUvBuf);
    gl.bufferData(gl.ARRAY_BUFFER, labelUvs.byteLength, gl.DYNAMIC_DRAW);
    gl.enableVertexAttribArray(2); gl.vertexAttribPointer(2, 4, gl.FLOAT, false, 0, 0); gl.vertexAttribDivisor(2, 1);
    gl.bindVertexArray(null);

    gl.disable(gl.DEPTH_TEST);
    gl.enable(gl.BLEND);
    // Premultiplied source: the shaders already multiply rgb by alpha, which is what keeps a soft SDF edge
    // from fringing dark against a light background.
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    return true;
  }

  if (!initGLResources()) return null;

  // A context is NOT owned by the page — the browser reclaims one when a canvas is hidden/occluded
  // (WebKit is aggressive here), past the live-context cap, or on a driver reset. `webglcontextlost`
  // MUST be `preventDefault()`-ed for the browser to attempt a restore at all; without that call it
  // abandons the context permanently and `webglcontextrestored` never fires.
  const onContextLost = (e: Event): void => {
    e.preventDefault();
    contextLost = true;
    opts.onContextLost?.();
  };
  const onContextRestored = (): void => {
    // A failed rebuild leaves `contextLost` true and fires no callback — the caller's fallback (raised
    // by `onContextLost`) stays up rather than reading a dead canvas as fine. Nothing else retries: the
    // next `webglcontextlost`/`webglcontextrestored` pair is the browser's to offer, not ours to poll for.
    if (restoreContext()) {
      contextLost = false;
      opts.onContextRestored?.();
    }
  };
  canvas.addEventListener("webglcontextlost", onContextLost, false);
  canvas.addEventListener("webglcontextrestored", onContextRestored, false);

  /**
   * Rebuild every GL object from nothing and re-upload whatever was last on the GPU. A restored context
   * starts EMPTY — re-drawing into it without this shows nothing, silently, until something remounts it.
   */
  function restoreContext(): boolean {
    if (!initGLResources()) return false;
    if (atlas) setAtlas(atlas);
    if (lastNodeXy && lastNodeSize && lastNodeRgba) {
      // `uploadNodes` (below) resets the state buffer to all-NORMAL, so capture the live selection/dim
      // state first and restore it after — a restore must not silently clear the user's selection.
      const savedState = stateBytes;
      uploadNodes(lastNodeXy, lastNodeSize, lastNodeRgba, lastNodeUploadCount);
      if (savedState.length === stateBytes.length) {
        stateBytes.set(savedState);
        gl.bindBuffer(gl.ARRAY_BUFFER, stateBuf);
        gl.bufferData(gl.ARRAY_BUFFER, stateBytes, gl.DYNAMIC_DRAW);
      }
    }
    if (lastEdgePairs) setEdges(lastEdgePairs, lastEdgeCount);
    return true;
  }

  const unpackRgba = (packed: Uint32Array, n: number): Uint8Array =>
    new Uint8Array(packed.buffer, packed.byteOffset, n * 4);

  // What is CURRENTLY on the GPU, in CPU-retrievable form — not just the level-0 `baseNodes`, since the
  // draw may be showing an LOD level instead. A restored context starts EMPTY, so `restoreContext` needs
  // exactly the arguments the last `uploadNodes`/`setEdges` call was given, to re-issue them verbatim.
  let lastNodeXy: Float32Array | null = null;
  let lastNodeSize: Float32Array | null = null;
  let lastNodeRgba: Uint32Array | null = null;
  let lastNodeUploadCount = 0;
  let lastEdgePairs: Uint32Array | null = null;
  let lastEdgeCount = 0;
  let contextLost = false;

  function setNodes(xy: Float32Array, size: Float32Array, rgba: Uint32Array, count: number): void {
    baseNodes = { xy, size, rgba, n: Math.max(0, Math.min(count, xy.length >> 1, size.length, rgba.length)) };
    uploadNodes(xy, size, rgba, count);
  }

  /** The upload itself, without recording it as the base set — used when swapping to an LOD level. */
  function uploadNodes(xy: Float32Array, size: Float32Array, rgba: Uint32Array, count: number): void {
    lastNodeXy = xy; lastNodeSize = size; lastNodeRgba = rgba; lastNodeUploadCount = count;
    nodeCount = Math.max(0, Math.min(count, xy.length >> 1, size.length >> 1, rgba.length));
    positions = xy;
    gridStale = true;

    posRows = Math.max(1, Math.ceil(nodeCount / POS_TEX_W));
    // The texture is a fixed-width rectangle; the tail of the last row is padding the shader never reads.
    const padded = new Float32Array(POS_TEX_W * posRows * 2);
    padded.set(xy.subarray(0, nodeCount * 2));
    gl.bindTexture(gl.TEXTURE_2D, posTex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RG32F, POS_TEX_W, posRows, 0, gl.RG, gl.FLOAT, padded);

    // Half-extents per axis — picking is a RECTANGLE, not a circle. A circle of radius max(w,h)/2 on a
    // 172x58 card reaches 86 px vertically and selects a node a whole row away.
    halfW = new Float32Array(nodeCount);
    halfH = new Float32Array(nodeCount);
    maxRadius = 0;
    for (let i = 0; i < nodeCount; i++) {
      const w = size[i * 2] * 0.5, h = size[i * 2 + 1] * 0.5;
      halfW[i] = w;
      halfH[i] = h;
      // The grid query reach must still cover the largest half-extent on EITHER axis, or a wide card is
      // unpickable near its ends.
      if (w > maxRadius) maxRadius = w;
      if (h > maxRadius) maxRadius = h;
    }

    gl.bindBuffer(gl.ARRAY_BUFFER, sizeBuf);
    gl.bufferData(gl.ARRAY_BUFFER, size.subarray(0, nodeCount * 2), gl.STATIC_DRAW);
    gl.bindBuffer(gl.ARRAY_BUFFER, colorBuf);
    gl.bufferData(gl.ARRAY_BUFFER, unpackRgba(rgba, nodeCount), gl.STATIC_DRAW);
    stateBytes = new Uint8Array(nodeCount);
    gl.bindBuffer(gl.ARRAY_BUFFER, stateBuf);
    gl.bufferData(gl.ARRAY_BUFFER, stateBytes, gl.DYNAMIC_DRAW);

    gl.bindVertexArray(nodeVao);
    gl.bindBuffer(gl.ARRAY_BUFFER, nodeQuadBuf);
    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    gl.bindBuffer(gl.ARRAY_BUFFER, sizeBuf);
    gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 0, 0); gl.vertexAttribDivisor(1, 1);
    gl.bindBuffer(gl.ARRAY_BUFFER, colorBuf);
    gl.enableVertexAttribArray(2); gl.vertexAttribPointer(2, 4, gl.UNSIGNED_BYTE, true, 0, 0); gl.vertexAttribDivisor(2, 1);
    gl.bindBuffer(gl.ARRAY_BUFFER, stateBuf);
    gl.enableVertexAttribArray(3); gl.vertexAttribPointer(3, 1, gl.UNSIGNED_BYTE, true, 0, 0); gl.vertexAttribDivisor(3, 1);
    gl.bindVertexArray(null);
  }

  function setEdges(pairs: Uint32Array, count: number): void {
    lastEdgePairs = pairs; lastEdgeCount = count;
    edgeCount = Math.max(0, Math.min(count, pairs.length >> 1));
    gl.bindBuffer(gl.ARRAY_BUFFER, pairBuf);
    gl.bufferData(gl.ARRAY_BUFFER, pairs.subarray(0, edgeCount * 2), gl.STATIC_DRAW);
    // One flat colour for now: per-edge colouring is a later slice, and a uniform would not survive it,
    // so the attribute exists from the start and is simply filled with the same value.
    const col = new Uint8Array(edgeCount * 4);
    const r = edgeColor & 255, g2 = (edgeColor >>> 8) & 255, b = (edgeColor >>> 16) & 255, a = (edgeColor >>> 24) & 255;
    for (let i = 0; i < edgeCount; i++) { col[i * 4] = r; col[i * 4 + 1] = g2; col[i * 4 + 2] = b; col[i * 4 + 3] = a; }
    gl.bindBuffer(gl.ARRAY_BUFFER, edgeColorBuf);
    gl.bufferData(gl.ARRAY_BUFFER, col, gl.STATIC_DRAW);

    gl.bindVertexArray(edgeVao);
    gl.bindBuffer(gl.ARRAY_BUFFER, edgeQuadBuf);
    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    gl.bindBuffer(gl.ARRAY_BUFFER, pairBuf);
    // INTEGER attribute — `vertexAttribPointer` would silently convert to float and lose precision above
    // 2^24, which is inside the range a million-node graph reaches.
    gl.enableVertexAttribArray(1); gl.vertexAttribIPointer(1, 2, gl.UNSIGNED_INT, 0, 0); gl.vertexAttribDivisor(1, 1);
    gl.bindBuffer(gl.ARRAY_BUFFER, edgeColorBuf);
    gl.enableVertexAttribArray(2); gl.vertexAttribPointer(2, 4, gl.UNSIGNED_BYTE, true, 0, 0); gl.vertexAttribDivisor(2, 1);
    gl.bindVertexArray(null);
  }

  function setState(index: number, state: number): void {
    if (index < 0 || index >= nodeCount) return;
    stateBytes[index] = state & 255;
    gl.bindBuffer(gl.ARRAY_BUFFER, stateBuf);
    // The whole point: ONE byte at one offset. Re-uploading the buffer would make selection O(N) again,
    // which is the 371 ms this module exists to remove.
    gl.bufferSubData(gl.ARRAY_BUFFER, index, stateBytes.subarray(index, index + 1));
  }

  function setPosition(index: number, x: number, y: number): void {
    if (index < 0 || index >= nodeCount) return;
    positions[index * 2] = x;
    positions[index * 2 + 1] = y;
    gridStale = true;
    gl.bindTexture(gl.TEXTURE_2D, posTex);
    gl.texSubImage2D(gl.TEXTURE_2D, 0, index % POS_TEX_W, (index / POS_TEX_W) | 0, 1, 1, gl.RG, gl.FLOAT, new Float32Array([x, y]));
  }

  function setView(v: GraphView): void { view = v; }

  // `dpr` scales only the DRAWING BUFFER. The shaders work in CSS px against `uViewport`, and clip space
  // spans the whole buffer, so device-pixel scaling falls out of `gl.viewport` with no other change.
  function resize(cssW: number, cssH: number, dpr = 1): void {
    vpW = Math.max(1, Math.round(cssW));
    vpH = Math.max(1, Math.round(cssH));
    canvas.width = Math.max(1, Math.round(cssW * dpr));
    canvas.height = Math.max(1, Math.round(cssH * dpr));
  }

  function draw(): void {
    // Every GL call below is a no-op against a dead context anyway, but skipping them also skips the
    // CPU work (LOD level arithmetic, label layout) that would otherwise run for a frame nobody sees.
    if (contextLost) return;
    // O(1): the level is arithmetic on the view scale. The swap below is skipped unless it changed.
    if (lod) applyLevel(levelFor(lod, view.scale));
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, posTex);

    // Edges first so nodes sit on top — the same ordering the DOM graph got from `orderedEdges`, for
    // free, because it is just draw order.
    if (edgeCount > 0) {
      gl.useProgram(edgeProg);
      gl.uniform1i(uEdge.pos, 0);
      gl.uniform2f(uEdge.viewport, vpW, vpH);
      gl.uniform2f(uEdge.translate, view.tx, view.ty);
      gl.uniform1f(uEdge.scale, view.scale);
      gl.uniform1f(uEdge.width, edgeWidthPx);
      gl.bindVertexArray(edgeVao);
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, edgeCount);
    }
    if (nodeCount > 0) {
      gl.useProgram(nodeProg);
      gl.uniform1i(uNode.pos, 0);
      gl.uniform2f(uNode.viewport, vpW, vpH);
      gl.uniform2f(uNode.translate, view.tx, view.ty);
      gl.uniform1f(uNode.scale, view.scale);
      gl.uniform4f(uNode.surface, surfaceRgba[0], surfaceRgba[1], surfaceRgba[2], surfaceRgba[3]);
      gl.uniform4f(uNode.border, borderRgba[0], borderRgba[1], borderRgba[2], borderRgba[3]);
      gl.uniform4f(uNode.accent, accentRgba[0], accentRgba[1], accentRgba[2], accentRgba[3]);
      gl.bindVertexArray(nodeVao);
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, nodeCount);
    }
    // Labels LAST so they sit above both nodes and edges, and because the pass is skipped entirely when
    // nothing is legible — which is the common case at overview zoom.
    lastGlyphCount = buildLabelInstances();
    if (lastGlyphCount > 0) {
      gl.useProgram(labelProg);
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_2D, atlasTex);
      gl.uniform1i(uLabel.atlas, 1);
      gl.uniform2f(uLabel.viewport, vpW, vpH);
      gl.uniform4f(uLabel.color, textRgba[0], textRgba[1], textRgba[2], textRgba[3]);
      gl.bindVertexArray(labelVao);
      // Only the glyphs actually written are uploaded — the buffers are allocated once at full capacity
      // and re-filled, so a frame with 200 labels does not pay for a capacity of 20,000.
      gl.bindBuffer(gl.ARRAY_BUFFER, labelRectBuf);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, labelRects, 0, lastGlyphCount * 4);
      gl.bindBuffer(gl.ARRAY_BUFFER, labelUvBuf);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, labelUvs, 0, lastGlyphCount * 4);
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, lastGlyphCount);
    }
    gl.bindVertexArray(null);
  }

  /**
   * Swap the drawn geometry to pyramid level `k` — `O(m)` in that level's population, and paid ONLY when
   * the level changes, not per frame.
   *
   * Reuses the ordinary node upload rather than keeping a separate VAO and texture per level. Levels
   * change a handful of times across a whole zoom sweep, so re-uploading ~n/4 floats on a transition is
   * cheaper than the state and the code that per-level buffers would cost — and it means the LOD path
   * runs through geometry that is already tested.
   */
  // NOT `useLevel`: a `use` prefix in this codebase means a React hook, and the lint rule that enforces
  // that is right to — this is a plain function inside a factory, and calling it from `draw` would have
  // read as a hook call outside a component to anyone scanning the file.
  function applyLevel(k: number): void {
    if (!lod || k === lodLevel) return;
    lodLevel = k;
    if (k === 0) {
      if (baseNodes) uploadNodes(baseNodes.xy, baseNodes.size, baseNodes.rgba, baseNodes.n);
      return;
    }
    const lv = lod.levels[k];
    const size = new Float32Array(lv.n * 2);
    const rgba = new Uint32Array(lv.n);
    // An aggregate is drawn at its CELL size, so the level tiles the space it stands for instead of
    // leaving gaps that read as missing data. Square, unlike the cards it stands for — a cell IS square.
    size.fill(lv.cellSize);
    rgba.fill(lodColor);
    uploadNodes(lv.xy, size, rgba, lv.n);
  }

  function setLod(p: LodPyramid | null, aggregateColor?: number): void {
    lod = p;
    if (aggregateColor !== undefined) lodColor = aggregateColor;
    // Force the next draw to re-evaluate: the pyramid may have changed under the same level number.
    lodLevel = -1;
    if (!p && baseNodes) {
      lodLevel = 0;
      uploadNodes(baseNodes.xy, baseNodes.size, baseNodes.rgba, baseNodes.n);
    }
  }

  function setPalette(
    s: readonly number[],
    b: readonly number[],
    a: readonly number[],
    text?: readonly number[],
  ): void {
    const four = (v: readonly number[] | undefined, d: [number, number, number, number]): [number, number, number, number] =>
      v && v.length >= 3 ? [v[0], v[1], v[2], v.length > 3 ? v[3] : 1] : d;
    surfaceRgba = four(s, surfaceRgba);
    borderRgba = four(b, borderRgba);
    accentRgba = four(a, accentRgba);
    // Optional: a caller written before the label colour existed keeps the previous default rather than
    // getting a transparent — an invisible label is the bug this is fixing.
    textRgba = four(text, textRgba);
  }

  function setAtlas(a: GlyphAtlas): void {
    atlas = a;
    gl.bindTexture(gl.TEXTURE_2D, atlasTex);
    // R8, one byte per texel: the field is a single channel, and storing it as RGBA would quadruple a
    // texture that is uploaded once and sampled constantly.
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, a.width, a.height, 0, gl.RED, gl.UNSIGNED_BYTE, a.data);
  }

  function setLabels(l: readonly (string | null)[]): void {
    labels = l;
  }

  /**
   * Fill the glyph instance buffers for everything on screen and legible — `O(visible glyphs)`.
   *
   * The gate is what makes this bounded: a node whose label would render under `MIN_LABEL_PX` is
   * skipped entirely, so the cost tracks SCREEN AREA rather than node count. A million-node graph
   * zoomed out emits zero glyphs and costs one `queryRect`.
   */
  function buildLabelInstances(): number {
    if (!atlas || labels.length === 0 || nodeCount === 0) return 0;
    if (gridStale || !grid) { grid = buildGrid(positions, nodeCount); gridStale = false; }
    // The world rect the viewport currently shows. No margin: unlike a DOM graph there is nothing to
    // pre-mount, and a label that appears as it enters the screen is correct.
    const wx = -view.tx / view.scale;
    const wy = -view.ty / view.scale;
    const ww = vpW / view.scale;
    const wh = vpH / view.scale;
    if (visible.length < nodeCount && visible.length < 1 << 20) {
      visible = new Uint32Array(Math.min(nodeCount, 1 << 20));
    }
    const n = queryRect(grid, wx, wy, ww, wh, visible);
    let g = 0;
    for (let k = 0; k < n; k++) {
      const i = visible[k];
      const text = labels[i];
      if (!text) continue;
      // Label em size follows the node, so text zooms with the graph rather than floating free of it.
      // The label follows the card's HEIGHT, not its width: a 172x58 card sized off its long axis would
      // put ~55 px of text on a 58 px card.
      // The NAME's own size, mirroring .ds-node-name (13px on a 58px card) rather than a fraction of
      // the box. The text sits INSIDE the card now, so it has to match the card's type scale or it
      // overlaps the second row.
      const emPx = (halfH[i] * 2) * (13 / 58) * view.scale;
      if (emPx < MIN_LABEL_PX) continue;
      const scale = emPx / atlas.fontSize;
      const laid = layoutLabel(text, atlas);
        // Left-aligned at the grid's name column: padding-left 13 + the 8px dot + an 8px column gap
        // = 29 card units in from the left edge. It used to be centred UNDER the node.
        const leftPx = (positions[i * 2] - halfW[i]) * view.scale + view.tx;
        const originX = leftPx + (halfH[i] * 2) * (29 / 58) * view.scale;
        // The name row's baseline: padding-top 11 plus the row's own height, in card units.
        const topPx = (positions[i * 2 + 1] - halfH[i]) * view.scale + view.ty;
        const originY = topPx + (halfH[i] * 2) * (23 / 58) * view.scale;
      for (const pg of laid.glyphs) {
        if (g >= MAX_LABEL_GLYPHS) return g;
        const q = pg.glyph;
        labelRects[g * 4] = originX + pg.x * scale;
        labelRects[g * 4 + 1] = originY + pg.y * scale;
        labelRects[g * 4 + 2] = q.w * scale;
        labelRects[g * 4 + 3] = q.h * scale;
        labelUvs[g * 4] = q.x / atlas.width;
        labelUvs[g * 4 + 1] = q.y / atlas.height;
        labelUvs[g * 4 + 2] = (q.x + q.w) / atlas.width;
        labelUvs[g * 4 + 3] = (q.y + q.h) / atlas.height;
        g++;
      }
    }
    return g;
  }

  function pick(cssX: number, cssY: number): number {
    if (nodeCount === 0) return -1;
    if (gridStale || !grid) { grid = buildGrid(positions, nodeCount); gridStale = false; }
    // Screen → world is the inverse of the shader's transform, so picking and drawing cannot disagree.
    const wx = (cssX - view.tx) / view.scale;
    const wy = (cssY - view.ty) / view.scale;
    // The reach must cover the LARGEST half-extent on either axis, or a wide card is unclickable near
    // its ends. Read, not computed — see `maxRadius`.
    return pickRect(grid, positions, halfW, halfH, wx, wy, maxRadius);
  }

  function dispose(): void {
    canvas.removeEventListener("webglcontextlost", onContextLost, false);
    canvas.removeEventListener("webglcontextrestored", onContextRestored, false);
    for (const b of [nodeQuadBuf, edgeQuadBuf, unitQuadBuf, sizeBuf, colorBuf, stateBuf, pairBuf, edgeColorBuf, labelRectBuf, labelUvBuf]) gl.deleteBuffer(b);
    gl.deleteTexture(posTex);
    gl.deleteTexture(atlasTex);
    gl.deleteVertexArray(nodeVao);
    gl.deleteVertexArray(edgeVao);
    gl.deleteVertexArray(labelVao);
    gl.deleteProgram(nodeProg);
    gl.deleteProgram(edgeProg);
    gl.deleteProgram(labelProg);
    // Deleting objects returns GPU memory; it does not return the CONTEXT. Browsers cap live WebGL
    // contexts (Chromium ~16) and force-lose the OLDEST past the cap, so a caller that creates and
    // disposes renderers repeatedly (a mount/unmount cycle, hasWebgl2's throwaway probe) can silently
    // evict a context another part of the page is still using.
    gl.getExtension("WEBGL_lose_context")?.loseContext();
  }

  return {
    setNodes, setEdges, setState, setPosition, setView, resize, draw, pick, dispose, setAtlas, setLabels, setLod, setPalette,
    get lodLevel() { return lodLevel < 0 ? 0 : lodLevel; },
    get nodeCount() { return nodeCount; },
    get edgeCount() { return edgeCount; },
    get lastGlyphCount() { return lastGlyphCount; },
    get contextLost() { return contextLost; },
  };
}

/** One loop left `open` by a crash — enough to name it in the banner (#3961). */
export interface InterruptedLoop { id: number; a: string; b: string; seed?: string }

// Console domain — navigation + the tabs/panes/focus core app state, plus the pane-lifecycle
// value types (warden quarantine, auto-ended workers). Split from store/types (#1634).
import type { Workspace } from "@/app/chrome/Rail";
import type { NavLoc } from "@/app/navigate";
import type { Tab } from "@/app/chrome/Tabstrip";
import type { ViewKey } from "@/app/console/panes/viewDefs";
import type { ReaperConfig } from "@/app/console/lib/idleReaper";
import type { QueuedPane, FocusTarget } from "@/app/console/lib/focusQueue";
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import type { AgentFlow } from "@/features/planner/fleet/agentFlow";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import type { AgentProfile } from "@/shared/lib/security/agentProfiles";
import type { DirectorMode } from "@/features/planner/lib/integrationStrategy";
import type { DirectorDrive } from "@/features/planner/fleet/directorDrive";
import type { TtsVerbosity } from "@/shared/lib/a11y/speech";

/** A worker the warden quarantined (#1102): why it tripped + when, for the user-facing surface. */
export interface QuarantineInfo {
  /** The stream the quarantined pane belonged to. */
  streamId: string;
  /** One-line deterministic trip summary (out-of-lane file / denied command). */
  summary: string;
  /** Epoch ms when it was quarantined. */
  at: number;
  /** Dismissed from the banner: the user acknowledged it. The banner hides, but the pane STAYS
   *  quarantined (its PTY is already dead, so it's paused) and the warden keeps skipping it — so a
   *  still-present out-of-lane edit in its diff can't re-trip and re-show the banner. Cleared for
   *  real only on relaunch / completion. */
  acknowledged?: boolean;
}

/** The resting state a finished fleet worker lands in, classified from plan.db owned-issue
 *  status (#920): every owned issue terminal-good ⇒ `done`; some still open ⇒ `needs-attention`
 *  (stopped early); any blocked/failed ⇒ `blocked`. */
export type WorkerEndState = "done" | "needs-attention" | "blocked";

/** A fleet worker auto-ended after its PTY exited (#920). Persisted so a restart never
 *  re-opens/relaunches a finished worker; the view renders a resting card with a reopen action. */
import type { PaneStop, StopReason } from "@/app/console/lib/paneStops";

export interface EndedInfo {
  /** Done / needs-attention / blocked, from the owned-issue status (not the worker's say-so). */
  state: WorkerEndState;
  /** The stream the worker owned. */
  streamId: string;
  /** One-line completeness summary (e.g. "3/3 complete · 2/3 landed"). */
  summary: string;
  /** Epoch ms when it ended. */
  at: number;
  /** HOW THE PROCESS ENDED, as Rust classified it — distinct from `state`, which says whether the
   *  LANE is done.
   *
   *  Both belong on the card and neither implies the other: a worker can crash with its issues
   *  complete, or exit cleanly with none of them done. Reporting only `state` is what let a cage
   *  that never started, an agent that crashed, and a genuine completion all render as
   *  "finished its work".
   *
   *  Absent for the `bsc-done` path, where the worker asked to close and there is no `pty_exit`
   *  payload — which is the one case `auto-ended` still names honestly. */
  exit?: { reason?: StopReason; detail?: string; lastOutput?: string };
}

/** One ended pane's PR-probe backoff schedule (`@/shared/lib/fleet/prProbe`'s `ProbePlan`, applied).
 *  PERSISTED alongside {@link EndedInfo} — see `panePrProbes` — so a restart resumes the backoff
 *  instead of re-asking GitHub about every already-settled pane from scratch
 *  (`an-unmerged-ended-pane-is-polled-against-github-forever` shipped the backoff; it lived only in a
 *  `useRef` and reset on every restart, which is the bug `panePrProbes` fixes). */
export interface PrProbeState {
  /** How many ANSWERS (not requests) this pane has produced — `unknown` verdicts don't count. */
  attempts: number;
  /** Epoch ms to ask again, or `null` once settled (merged, or exhausted `NO_PR_ATTEMPTS`) — a
   *  settled pane is never asked again. */
  nextAt: number | null;
}

/** Console domain slice of {@link AppStore}: navigation + the tabs/panes/focus core app state. */
/**
 * A stream the wake path may START rather than merely resume
 * (`the-director-cannot-start-a-stream-that-never-launched`).
 *
 * The plan.db row Rust resolved, plus the ABSOLUTE cwd it resolved with it — the worktree for a
 * repo'd worker, the project hub for a repo-less hub role-actor (#3103). The path travels with the
 * row for the same reason a fleet launch's does (#905): re-deriving it in the store depends on the
 * async-loaded `bscBaseDir` mirror, and an empty one drops the session at the user's home dir.
 */
export type WakeStream = AgentStream & { cwd: string };

export interface ConsoleState {
  // Navigation
  activeWorkspace: Workspace;
  setWorkspace: (screen: Workspace) => void;
  /** Navigate to a location — switch the workspace AND set its page/entity in one call (#3602), so a
   *  cross-workspace jump can never forget the page. Prefer this over a bare `setWorkspace` whenever the
   *  target page matters (which is nearly always, except the page-less console). */
  navigate: (loc: NavLoc) => void;
  // True once the async persisted state has rehydrated (transient — NOT persisted).
  // The app shell holds its first paint until this flips, to avoid a defaults flash.
  hasHydrated: boolean;
  setHasHydrated: (v: boolean) => void;

  // Console — tabs & panes
  tabs: Tab[];
  activeTabIdx: number;
  paneMenuOpenIdx: number;   // transient — NOT persisted
  focusedPaneIdx: number;    // transient — NOT persisted
  fullscreenPaneIdx: number; // transient — NOT persisted
  consoleBroadcast: boolean; // transient — NOT persisted
  setConsoleBroadcast: (v: boolean) => void;
  // Focus queue (transient — NOT persisted): panes (across all tabs) that finished
  // a turn and await attention, FIFO. Stepped through with Ctrl+Shift+N
  // (advanceFocus), which switches tabs when the next pane lives on another tab.
  // Persists across tab switches; enqueue/remove/reconcile target the active tab.
  focusQueue: QueuedPane[];
  // Enqueue / remove take (tab, pane) so background-tab status changes can
  // participate too — every tab's TerminalView is mounted after #187, so
  // ConsoleWorkspace sees idle transitions for all panes and routes them here (#77).
  enqueueFocus: (tab: number, pane: number) => void;
  removeFocus: (tab: number, pane: number) => void;
  // Role-aware focus targeting (#392, persisted). Which panes the autofocus queue
  // surfaces — by default only the director (workers run dark, escalating via
  // bsc-ask). enqueueFocus is gated by it; changing it re-gates the live queue.
  focusTarget: FocusTarget;
  setFocusTarget: (target: FocusTarget) => void;
  /** Wake a parked pane (#199): seed it with `prompt` as a FRESH claude session and
   *  remount its tab (runId bump). Returns false if the pane/tab is gone or disabled.
   *  The caller `pty_kill`s the pane first so the remount spawns fresh, not reconnect.
   *
   *  `stream` STARTS a session that was never opened
   *  (`the-director-cannot-start-a-stream-that-never-launched`). The store's roster
   *  (`fleetPaneStreams`) only knows what LAUNCHED, so a stream plan.db names and no session
   *  ever ran is invisible here — Rust reads plan.db and passes the row, with the absolute cwd
   *  it resolved, so the pane can be wired exactly as `fleetStartProject` would have wired it.
   *  Omitted (or undefined) ⇒ the historical behaviour: a pane absent from the roster refuses. */
  wakePane: (paneId: string, prompt: string, stream?: WakeStream) => boolean;
  clearFocusQueue: () => void;
  advanceFocus: () => void;
  // Prune queued panes across every tab whose live status the caller has —
  // dropped if their pane index isn't in that tab's waiting set. Tabs absent
  // from the map (no live data) keep their entries, so a transient missing-tab
  // moment can't silently drop queued panes.
  reconcileFocusQueue: (waitingByTab: ReadonlyMap<number, ReadonlySet<number>>) => void;
  // Global terminal font size (px), shared by every console pane (persisted).
  // Adjusted via Ctrl++ / Ctrl+- / Ctrl+0; clamped to the legible range.
  terminalFontSize: number;
  setTerminalFontSize: (size: number) => void;
  // Accent color preset id (persisted; configured in Settings → Appearance).
  // Applied to the --accent / --accent-dim CSS tokens at the document root.
  accent: string;
  setAccent: (id: string) => void;
  // Kit theme id (#1852 Phase 3; persisted; configured in Settings → Appearance). A theme is a map
  // of semantic component-token overrides (--card-*/--btn-*/--field-*/--chip-*) applied to :root at
  // boot (like the accent). "default" = the base look. Registry: src/shared/ui/kit/theme.ts.
  kitTheme: string;
  setKitTheme: (id: string) => void;
  // Opt-in notification sounds (#3082; persisted, default OFF; toggled in Settings → Appearance).
  // When on, useNotificationSounds() plays a Signal-kit cue on fleet coord events (landing/merge →
  // success, failure → error, a worker pausing → notify).
  soundNotifications: boolean;
  setSoundNotifications: (on: boolean) => void;
  // App-owned text-to-speech (#3804, a11y epic #2725 Tier 1; persisted, default OFF; Settings →
  // Accessibility). When on, useCoordSpeaker() speaks NEW fleet coordination events via speechSynthesis
  // (paused / question / landed / …), distinct from #3770's ARIA live region for the user's own reader.
  ttsEnabled: boolean;
  setTtsEnabled: (on: boolean) => void;
  ttsRate: number;                       // speechSynthesis rate multiplier
  setTtsRate: (rate: number) => void;
  ttsVoice: string;                      // selected SpeechSynthesisVoice.voiceURI ("" = platform default)
  setTtsVoice: (voiceURI: string) => void;
  ttsVerbosity: TtsVerbosity;            // "terse" (needs-you only) | "verbose" (adds progress)
  setTtsVerbosity: (v: TtsVerbosity) => void;
  // Custom keyboard shortcut overrides (#771): rebindable-shortcut id → chord
  // string (e.g. "Ctrl+Shift+KeyC"). Only overrides are stored; useHotkeys falls
  // back to DEFAULT_BINDINGS for any id absent here. Persisted; edited in
  // Settings → Keyboard.
  keybindings: Record<string, string>;
  setKeybinding: (id: string, chord: string) => void;
  resetKeybinding: (id: string) => void;
  resetAllKeybindings: () => void;
  paneViews: ViewKey[];
  paneNames: Record<number, Record<number, string>>;
  paneCwds: Record<string, string>;  // keyed by "t{tabIdx}p{paneIdx}"
  setPaneCwd: (paneId: string, cwd: string) => void;
  // Live per-pane run status (transient — NOT persisted), keyed by "t{tab}p{pane}".
  // Mirrors Console's local pane-status map into the store so other screens (the
  // Fleet board, #412) can read whether a worker pane is actively running. "run" =
  // claude is mid-turn, "on" = shell up / claude idle, "idle" = at rest.
  paneStatus: Record<string, "run" | "on" | "idle">;
  // Record a pane's live status AND re-roll its tab's state in one step (#435) — the
  // store is the single source of truth for both the pane dot and the tab rollup.
  setPaneStatus: (paneId: string, status: "run" | "on" | "idle") => void;
  // ── Warden quarantine (#1102) ──
  /** Panes the warden hard-paused (PTY killed) for drifting off their plan — possible prompt
   *  injection / hijack. Keyed by pane id; surfaced to the user, who clears it explicitly. */
  quarantinedPanes: Record<string, QuarantineInfo>;
  markQuarantine: (paneId: string, info: QuarantineInfo) => void;
  clearQuarantine: (paneId: string) => void;
  /** Dismiss the banner WITHOUT un-quarantining the pane (the worker stays paused, the warden keeps
   *  skipping it). Distinct from clearQuarantine, which fully removes it (relaunch / completion). */
  acknowledgeQuarantine: (paneId: string) => void;
  /** Per-pane warden "since" floor (epoch ms): the warden ignores `bsc-audit` commands logged BEFORE
   *  this, so a denied command from a PRIOR run can't re-quarantine a relaunched worker. Triage stamps
   *  it; persisted alongside quarantinedPanes. */
  wardenSince: Record<string, number>;
  /** Pressing triage: clear EVERY quarantine under a project's `<projectKey>:` pane-id prefix and
   *  stamp `since` as the warden floor for each relaunching pane — so the relaunch starts clean and a
   *  stale denied command (still in the persisted bsc-audit log) can't immediately re-pause the worker. */
  clearProjectQuarantine: (projectKey: string, panes: string[], since: number) => void;
  // ── Auto-end finished workers (#920) ──
  /** Fleet workers auto-ended after their PTY exited, classified from plan.db owned-issue
   *  status. PERSISTED + recovery-gated so a restart never re-opens a finished worker; the view
   *  renders a resting card with a reopen action. Keyed by pane id. */
  endedPanes: Record<string, EndedInfo>;
  /** Mark a worker pane ended (done/needs-attention/blocked); drops its live status. */
  markPaneEnded: (paneId: string, info: EndedInfo) => void;
  /** Clear a pane's ended state so the user can relaunch it (reopen). */
  reopenPane: (paneId: string) => void;
  /** Each ended pane's PR-probe backoff — see {@link PrProbeState}. PERSISTED alongside
   *  `endedPanes` so a restart resumes the schedule instead of restarting it from empty. Keyed by
   *  pane id. */
  panePrProbes: Record<string, PrProbeState>;
  /** Record what `useWorkerAutoEnd`'s poll learned about one pane's PR — its own `planNextProbe`
   *  plan, so the NEXT tick (this run or after a restart) knows whether and when to ask again. */
  setPanePrProbe: (paneId: string, probe: PrProbeState) => void;
  /** Drop a pane's probe schedule — called wherever its ended state is cleared, so a pane that ends
   *  again later starts its backoff fresh rather than resuming a stale one. */
  clearPanePrProbe: (paneId: string) => void;
  // ── Idle session reaping (#849) ──
  /** Panes whose PTY has been reaped for idleness; the view renders a dormant placeholder
   *  and resumes on focus. Transient (not persisted) — panes relaunch on next app start. */
  dormantPanes: Record<string, boolean>;
  /** Epoch ms of each pane's last status change — the reaper's idle clock. Transient. */
  paneLastActivity: Record<string, number>;
  /** Idle-reaper config (enabled + thresholds). Persisted. */
  idleReaper: ReaperConfig;
  /** Mark a pane dormant after its PTY was reaped (the hook calls pty_kill alongside). */
  reapPane: (paneId: string) => void;
  // ── Why a pane stopped (#a-stopped-session-says-why) ──
  /** Recent pane stops, newest last — what the transient banner renders and what the log records.
   *  TRANSIENT (absent from `partialize`): a notice that survives a restart is a notice about a
   *  session the user is no longer looking at. Bounded + self-pruning; see `paneStops.ts`. */
  paneStops: PaneStop[];
  /** Record WHY a pane stopped: appends to {@link paneStops} (replacing any earlier entry for the
   *  same pane) and ALWAYS writes a log line, faults at warn.
   *
   *  Called from the stop actions themselves — `reapPane`, `markPaneEnded`, `markQuarantine`,
   *  `setPaneDisabled` — because the action that ran IS the reason, so one edit covers every caller.
   *  The PROCESS-ended reasons come from Rust on the `pty_exit` payload instead. */
  notePaneStopped: (paneId: string, reason: StopReason, detail: string, lastOutput?: string) => void;
  /** Clear a pane's dormant state so the view relaunches it (resume on focus). */
  resumePane: (paneId: string) => void;
  /** Resume a single dormant fleet/agent session in place (#glance-resume): clears the pane's
   *  ended / disabled / dormant flags and stamps `restoreRequested` so its remounted terminal
   *  relaunches with `claude --continue`. Non-disruptive — it touches ONLY this pane, so live
   *  siblings in the same build tab keep running. Returns false (a no-op) when no open tab hosts
   *  the pane id, so the caller can fall back to a full fleet relaunch. */
  /** Drop the ENDED flag for a set of panes about to be relaunched (#3916). */
  clearEndedPanes: (paneIds: string[]) => void;
  resumePaneSession: (paneId: string) => boolean;
  /** Update the idle-reaper config (Settings). */
  setIdleReaperConfig: (cfg: Partial<ReaperConfig>) => void;
  // Recompute one tab's rolled-up state from the current pane statuses + layout +
  // disabled set (#435). Called whenever a rollup input changes that isn't itself a
  // status event — a layout change or a pane enable/disable — so the tab dot never
  // goes stale (e.g. shows "run" after the only running pane was disabled).
  recomputeTabState: (tabIdx: number) => void;
  // Drop a tab's pane statuses on close / remount so a prior session's "run"/"on"
  // can't strand a stale activity dot on the fresh panes (#435).
  clearTabStatuses: (tabIdx: number) => void;
  // Per-pane flag: this pane has had `claude` running at some point this
  // session. Persisted so that on next launch the pane can auto-resume the
  // CLI (with `--continue`) instead of dropping the user back at a bare
  // bash prompt (#36). Set by TerminalView when OSC 100 "run" fires.
  paneWasClaude: Record<string, boolean>;
  /** Crash recovery (#1041): the previous shutdown was unclean (set once at boot from the
   *  `was_unclean_shutdown` command). Transient — NOT persisted. Gates session auto-resume (a clean
   *  quit leaves sessions dormant) + the restore banner. */
  uncleanShutdown: boolean;
  setUncleanShutdown: (v: boolean) => void;
  /** Loops an unclean shutdown stranded (#3961), as CLOSED at boot — what the notice reports.
   *  Empty on a clean quit: an open loop is then legitimately dormant, not interrupted. */
  interruptedLoops: InterruptedLoop[];
  /** CLOSE the stranded loops (`bsc loop reap`) and keep the list to report. Boot-only, crash-gated.
   *
   *  It used to only COUNT them (`--dry-run`) and ask, which was a decision with one answer: an open
   *  loop blocks `watch` on a turn that will never come, so leaving them was never the better option.
   *  The reap is safe exactly where it runs — after an unclean shutdown, before anything is launched —
   *  which is the same gate that decides whether to call it at all. */
  reapStrandedLoops: () => Promise<void>;
  /** Dismiss the notice. The loops are already closed; this only clears what is on screen. */
  dismissInterruptedLoops: () => void;
  /** Crash recovery (#1041): panes the user clicked "restore" for — resume with `claude --continue`
   *  on remount, regardless of the autoResumeClaude setting. Transient. */
  restoreRequested: Record<string, boolean>;
  /** Relaunch every `paneWasClaude` pane with `claude --continue`, staggered. Returns the count. */
  restoreSessionsFromCrash: () => number;
  /** Live agent/terminal pane count (transient, not persisted) — drives the >10 easter egg (#365). */
  liveAgents: number;
  bumpLiveAgents: (delta: number) => void;
  /** Unlocked achievements: id -> unlockedAt epoch ms (persisted). */
  achievements: Record<string, number>;
  /** Unlock an achievement once, ever. Returns true only on the FIRST unlock
   *  (so the caller fires its toast exactly once); false if already unlocked. */
  unlockAchievement: (id: string) => boolean;
  setPaneWasClaude: (paneId: string, on: boolean) => void;
  paneInitCmds: Record<string, string>; // transient — NOT persisted
  setPaneInitCmd: (paneId: string, cmd: string) => void;
  // Resolved startup-prompt document per pane (transient — NOT persisted).
  // paneId → document relpath; "" means the built-in default prompt; absent
  // means no startup prompt (a plain console pane). Read by TerminalView.
  paneStartupPromptDocs: Record<string, string>;
  // Verbatim startup-prompt text per pane (transient — NOT persisted). Takes
  // precedence over paneStartupPromptDocs in TerminalView: when present, the
  // exact text is sent to the session once Claude reaches its prompt. Used by
  // triage panes (see TRIAGE_PROMPT).
  paneStartupPromptText: Record<string, string>;
  // paneId → unified-store relpath of the triage CHECKPOINT doc (transient — NOT
  // persisted). The session overwrites it via the `bsc-checkpoint` shell helper;
  // TerminalView composes its content onto the next triage launch's prompt so the
  // pass resumes where it left off. Set for triage panes (see triageStartProject).
  paneCheckpointDocs: Record<string, string>;
  // Per-pane flag (transient — NOT persisted): launch claude with --continue to
  // resume the repo's prior conversation rather than starting fresh. Set for
  // triage panes (see triageStartProject); read by TerminalView.
  paneContinue: Record<string, boolean>;
  // Disabled panes (keyed by "t{tabIdx}p{paneIdx}") — terminal unmounted + PTY killed.
  disabledPanes: Record<string, boolean>;
  setPaneDisabled: (paneId: string, disabled: boolean) => void;
  // Role-scoped capability per pane (#219) — transient. When set, the session's
  // command allowlist is narrowed at launch (a planner can't run git/gh writes).
  // Absent ⇒ unrestricted (current behavior). Set by the planning/fleet assignment.
  paneRoles: Record<string, SessionRole>;
  /**
   * The PERSONA each pane launches as (epic `the-persona-is-the-whole-agent`).
   *
   * Read BEFORE `paneRoles` when the launch resolves a capability, because a persona carries its own
   * `floor` and that floor may be NARROWER than its role's. Storing only the role discarded exactly
   * that narrowing at the one moment it mattered: a user persona derived from `worker` with a tighter
   * floor still launched with the full worker capability.
   *
   * PERSISTED, along with `paneRoles` — see the note beside them in `@/store/persist`.
   *
   * They were transient, on the premise that both are "rewritten by whatever re-seeds the pane after
   * a restart". Nothing re-seeds a fleet pane on a plain restart, and the pane relaunches anyway, so
   * the role resolved undefined and the session came up with no cage and no role gate — while every
   * value DERIVED from that role (`paneProfiles`, `paneRoleGlobs`, `paneFlows`) was persisted right
   * beside it.
   */
  panePersonas: Record<string, string>;
  /** Drive mode for each launched director pane (#366) — read by useDirectorPump. */
  paneDirectorDrive: Record<string, DirectorDrive>;
  /** Integration mode (watchdog/integrator) for each launched director pane (#378) — read by useCiWatcher. */
  paneDirectorMode: Record<string, DirectorMode>;
  /** Each worker pane's repo + branch (#373) — lets useCiWatcher map a PR back to it. */
  paneStream: Record<string, { repo: string; branch: string }>;
  setPaneRole: (paneId: string, role: SessionRole) => void;
  /** Point a pane at the persona it launches as. */
  setPanePersona: (paneId: string, personaId: string) => void;
  // Agents (#255) — editable permission profiles + their per-pane assignment, both
  // persisted. A pane's assigned profile is applied to its session at launch (the
  // same gate as paneRoles). Absent ⇒ no profile (unrestricted beyond the role gate).
  agentProfiles: AgentProfile[];
  setAgentProfiles: (profiles: AgentProfile[]) => void;
  updateAgentProfile: (id: string, patch: Partial<AgentProfile>) => void;
  paneProfiles: Record<string, string>;
  /** Panes whose assigned profile was edited while running — drives a "relaunch to apply"
   *  nudge (Claude Code reads settings.json at session start). Transient; cleared on relaunch (#799). */
  panePermsStale: Record<string, boolean>;
  clearPanePermsStale: (paneId: string) => void;
  /** Monotonic per-pane counter that drives the resize-nudge redraw (#1221) — a SIGWINCH that
   *  un-jumbles the Claude CLI's TUI the way a window resize does. Bumped by `requestPaneRedraw`
   *  (the pane menu / hotkey); the pane's terminal watches its own count and nudges on each bump. */
  paneRedrawNonce: Record<string, number>;
  requestPaneRedraw: (paneId: string) => void;
  // Worker write boundary: the stream's owned globs, fed to the role gate as
  // writeGlobs so a worker auto-approves edits within its lane (bsc-confine bounds the repo).
  paneRoleGlobs: Record<string, string[]>;
  // Per-pane `owner/name` repo binding (#158), set at fleet/triage launch. TerminalView
  // resolves the pane's GH_TOKEN from this via tokenForRepo: a repo with an assigned
  // fine-grained credential gets that token (scoping its gh/git to that repo), otherwise
  // the global PAT. Absent (director, ad-hoc console) ⇒ global token. Persisted so a
  // restored session keeps its scope.
  paneRepos: Record<string, string>;
  /** Per-agent flow (#297) for each pane, seeded at fleet launch from the stream. */
  paneFlows: Record<string, AgentFlow>;
  /** Console provider id per pane (persisted). Absent ⇒ "claude" (default). */
  paneProviders: Record<string, string>;
  setPaneProvider: (paneId: string, providerId: string) => void;
  /** WSL2 sandbox distro a pane spawns INTO (#1988). Set at fleet/triage launch when the sandbox is
   *  on and the harness is bsc-agent — its cwd is a distro-native path + the session runs in the cage.
   *  Absent ⇒ the normal host shell. Persisted so a restored sandboxed pane reconnects into the cage. */
  paneWslDistro: Record<string, string>;
  /** Whether a Claude session is the running program in each pane (#1158) — transient. Drives the
   *  native console input (which replaces Claude's prompt) and hides the pane's status footer. */
  /** Panes STOPPED waiting on the USER (#4005) — Claude Code fired `Notification`: a permission
   *  prompt, or a long input idle. Fed from the ONE shared pane-activity read in ConsoleWorkspace, so
   *  Glance can raise the `attention` health without importing the console shell (features must not
   *  import `app/`). Transient — not persisted; it is re-derived from activity.log on every read. */
  /** Panes that DECLARED maintenance (#4025) — `bsc-maintain`: everything they own is done and they
   *  are standing by. Projected from `CoordState.maintaining` by the coordinator (the one reader that
   *  already computes it) so the idle reaper and Glance can both see it without a second log poll.
   *  Transient — re-derived from coord.log on every read. */
  paneMaintaining: Record<string, boolean>;
  setPaneMaintaining: (panes: Record<string, boolean>) => void;
  paneAttention: Record<string, boolean>;
  setPaneAttention: (panes: Record<string, boolean>) => void;
  paneClaudeActive: Record<string, boolean>;
  setPaneClaudeActive: (paneId: string, active: boolean) => void;
  setPaneProfile: (paneId: string, profileId: string | null) => void;
  setActiveTab: (idx: number) => void;
  addTab: (tab: Tab) => void;
  closeTab: (idx: number) => void;
  /** Reorder a tab from index `from` to `to`, remapping all index-keyed pane
   *  state (names/cwds/status/disabled/extensions/allowed-commands/focus queue)
   *  so nothing bleeds onto the wrong tab (#461). */
  moveTab: (from: number, to: number) => void;
  renameTab: (idx: number, name: string) => void;
  setTabLayout: (tabIdx: number, layout: string) => void;
  setTabState: (tabIdx: number, state: Tab["state"]) => void;
  setPaneMenu: (idx: number) => void;
  setFocusedPane: (idx: number) => void;
  setFullscreenPane: (idx: number) => void;
  focusedAgentName: string;
  setFocusedAgentName: (name: string) => void;
  setPaneView: (idx: number, view: ViewKey) => void;
  setAllPanesView: (view: ViewKey) => void;
  setPaneName: (tabIdx: number, paneIdx: number, name: string) => void;
}

