// The index's correctness AND its complexity. The second half is the point: a spatial index that is
// merely correct but degrades to a scan has replaced an O(N) loop with a slower O(N) loop.
import { describe, it, expect } from "vitest";
import { buildGrid, queryRect, pickNearest, pickRect, type SpatialGrid } from "@/shared/lib/graph/spatialGrid";

/** Deterministic RNG — a timing-free test that seeds from Math.random is a test that fails on a Friday. */
function rng(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function uniform(n: number, extent: number, seed = 1): Float32Array {
  const r = rng(seed);
  const xy = new Float32Array(n * 2);
  for (let i = 0; i < n * 2; i++) xy[i] = r() * extent;
  return xy;
}

/**
 * How many nodes a `pickNearest` at (x,y) would actually examine — the per-call cost, computed from the
 * grid's own fields rather than from a clock.
 *
 * Deliberately NOT a wall-time measurement. Timing on a machine running a fleet of agents is noise, and
 * this repo has already been bitten by guards that pass for the wrong reason; the number of candidates
 * scanned IS the complexity, and it is deterministic.
 */
function candidatesScanned(g: SpatialGrid, x: number, y: number, reach: number): number {
  const cl = (v: number, len: number) => (v < 0 ? 0 : v >= len ? len - 1 : v | 0);
  const c0 = cl(Math.floor((x - reach - g.minX) / g.cellSize), g.cols);
  const c1 = cl(Math.floor((x + reach - g.minX) / g.cellSize), g.cols);
  const r0 = cl(Math.floor((y - reach - g.minY) / g.cellSize), g.rows);
  const r1 = cl(Math.floor((y + reach - g.minY) / g.cellSize), g.rows);
  let n = 0;
  for (let r = r0; r <= r1; r++) n += g.cellStart[r * g.cols + c1 + 1] - g.cellStart[r * g.cols + c0];
  return n;
}

describe("buildGrid", () => {
  it("indexes every node exactly once", () => {
    const xy = uniform(1000, 500);
    const g = buildGrid(xy, 1000);
    expect(g.count).toBe(1000);
    expect(g.items.length).toBe(1000);
    expect(new Set(g.items).size).toBe(1000);
    expect(g.cellStart[g.cellStart.length - 1]).toBe(1000);
  });

  it("survives an empty input rather than throwing on the render path", () => {
    const g = buildGrid(new Float32Array(0), 0);
    expect(g.count).toBe(0);
    expect(pickNearest(g, new Float32Array(0), 5, 0, 0, 10)).toBe(-1);
    expect(queryRect(g, 0, 0, 100, 100, new Uint32Array(8))).toBe(0);
  });

  it("handles every node sharing one position — a degenerate span is one cell, not a divide-by-zero", () => {
    const xy = new Float32Array(20).fill(7);
    const g = buildGrid(xy, 10);
    expect(g.count).toBe(10);
    expect(Number.isFinite(g.cellSize)).toBe(true);
    expect(g.cellSize).toBeGreaterThan(0);
    expect(pickNearest(g, xy, 1, 7, 7, 1)).toBeGreaterThanOrEqual(0);
  });

  it("CLAMPS a non-finite coordinate instead of dropping the node", () => {
    // A node you can see but cannot click is worse than one drawn at the edge, so NaN must still be
    // indexed. Dropping it from `items` is the failure this guards.
    const xy = new Float32Array([0, 0, 10, 10, NaN, 5, 20, 20]);
    const g = buildGrid(xy, 4);
    expect(g.items.length).toBe(4);
    expect(new Set(g.items).size).toBe(4);
  });

  it("caps the grid so one far outlier cannot ask for a hostile allocation", () => {
    // 500 clustered nodes and one a million units away. An uncapped grid sizes its cell to the CLUSTER
    // and its extent to the OUTLIER, which is how you ask for billions of cells.
    const xy = new Float32Array(501 * 2);
    for (let i = 0; i < 500; i++) { xy[i * 2] = i % 25; xy[i * 2 + 1] = Math.floor(i / 25); }
    xy[1000] = 1e6; xy[1001] = 1e6;
    const g = buildGrid(xy, 501);
    expect(g.cols * g.rows).toBeLessThanOrEqual(1 << 22);
    expect(g.items.length).toBe(501);
  });
});

describe("queryRect", () => {
  it("reports the nodes inside the rect and none from far outside it", () => {
    const xy = new Float32Array([0, 0, 10, 10, 100, 100, 105, 95, 500, 500]);
    const g = buildGrid(xy, 5);
    const out = new Uint32Array(16);
    const n = queryRect(g, 90, 85, 30, 30, out);
    const got = new Set([...out.slice(0, n)]);
    expect(got.has(2)).toBe(true);
    expect(got.has(3)).toBe(true);
    expect(got.has(4)).toBe(false);
  });

  it("TRUNCATES rather than allocating when `out` is too small, and says how many it wrote", () => {
    // The render path cannot budget for a surprise allocation; a short buffer must degrade, not grow.
    const xy = uniform(400, 50);
    const g = buildGrid(xy, 400);
    const out = new Uint32Array(7);
    const n = queryRect(g, -10, -10, 200, 200, out);
    expect(n).toBe(7);
    expect(out.every((v) => v < 400)).toBe(true);
  });

  it("finds everything when the rect covers the world", () => {
    const xy = uniform(300, 200, 9);
    const g = buildGrid(xy, 300);
    const out = new Uint32Array(512);
    expect(queryRect(g, -1000, -1000, 4000, 4000, out)).toBe(300);
  });
});

describe("pickNearest", () => {
  it("returns the nearest node whose own radius contains the point", () => {
    const xy = new Float32Array([0, 0, 30, 0, 60, 0]);
    const g = buildGrid(xy, 3);
    expect(pickNearest(g, xy, 10, 2, 0, 10)).toBe(0);
    expect(pickNearest(g, xy, 10, 29, 0, 10)).toBe(1);
  });

  it("returns -1 when the point is inside no node's radius", () => {
    const xy = new Float32Array([0, 0, 100, 100]);
    const g = buildGrid(xy, 2);
    expect(pickNearest(g, xy, 5, 50, 50, 60)).toBe(-1);
  });

  it("lets a LARGE node win over a nearer small one — the thing that makes clicking feel right", () => {
    // Node 1 is closer to the cursor but the cursor is outside it; node 0 is further but contains it.
    const xy = new Float32Array([0, 0, 24, 0]);
    const radii = new Float32Array([40, 2]);
    const g = buildGrid(xy, 2);
    expect(pickNearest(g, xy, radii, 20, 0, 40)).toBe(0);
  });

  it("agrees with a brute-force scan over a random field", () => {
    const n = 2000;
    const xy = uniform(n, 400, 42);
    const g = buildGrid(xy, n);
    const r = rng(7);
    for (let t = 0; t < 200; t++) {
      const px = r() * 400, py = r() * 400, rad = 6;
      let want = -1, bestD2 = Infinity;
      for (let i = 0; i < n; i++) {
        const dx = xy[i * 2] - px, dy = xy[i * 2 + 1] - py;
        const d2 = dx * dx + dy * dy;
        if (d2 < bestD2 && d2 <= rad * rad) { bestD2 = d2; want = i; }
      }
      expect(pickNearest(g, xy, rad, px, py, rad)).toBe(want);
    }
  });
});

describe("the complexity guarantee", () => {
  it("keeps mean cell occupancy constant as the graph grows — the whole basis of O(1) lookup", () => {
    for (const n of [1_000, 50_000, 400_000]) {
      // Density held constant: extent grows as sqrt(n) so nodes-per-unit-area does not change.
      const g = buildGrid(uniform(n, Math.sqrt(n) * 20, 3), n);
      const mean = g.count / (g.cols * g.rows);
      expect(mean).toBeGreaterThan(0.5);
      expect(mean).toBeLessThan(8);
    }
  });

  it("does NOT degrade toward linear: candidates scanned per pick stays flat from 10k to 500k", () => {
    // The claim under test is that `pickNearest` is O(1) EXPECTED, not O(n). If the index ever regresses
    // to a scan, `scanned` tracks `n` and this fails loudly instead of the app just getting slower.
    const sample = (n: number): number => {
      const extent = Math.sqrt(n) * 20;
      const g = buildGrid(uniform(n, extent, 11), n);
      const r = rng(5);
      let worst = 0;
      for (let t = 0; t < 100; t++) {
        worst = Math.max(worst, candidatesScanned(g, r() * extent, r() * extent, g.cellSize));
      }
      return worst;
    };
    const small = sample(10_000);
    const large = sample(500_000);
    // 50× the nodes. A linear index would scan ~50× more; a constant-time one scans the same handful.
    expect(large).toBeLessThan(small * 3 + 20);
    expect(large).toBeLessThan(200);
  });
});

describe("pickRect — the card-shaped hit test", () => {
  // THE TEST THAT WOULD HAVE CAUGHT THE SQUARE-NODE REGRESSION. Nothing in the suite looked at node
  // SHAPE, so a renderer drawing every 172x58 card as a 172x172 square passed every check: pixels were
  // lit, the GL context was healthy, picking "agreed with drawing" — because picking was a circle of the
  // same wrong radius, so the two agreed with each other and both were wrong.
  const CARD_W = 172;
  const CARD_H = 58;
  /** Two cards, one directly above the other at a realistic row pitch. */
  const twoRows = () => {
    const xy = new Float32Array([0, 0, 0, CARD_H + 22]);
    const hw = new Float32Array([CARD_W / 2, CARD_W / 2]);
    const hh = new Float32Array([CARD_H / 2, CARD_H / 2]);
    return { xy, hw, hh, g: buildGrid(xy, 2) };
  };

  it("selects a card at its far LEFT and RIGHT ends", () => {
    // A circle of radius min(w,h)/2 = 29 would miss both — the naive "use the short axis" fix.
    const { xy, hw, hh, g } = twoRows();
    expect(pickRect(g, xy, hw, hh, -CARD_W / 2 + 2, 0, CARD_W)).toBe(0);
    expect(pickRect(g, xy, hw, hh, CARD_W / 2 - 2, 0, CARD_W)).toBe(0);
  });

  it("does NOT select a card from a whole row away", () => {
    // The actual regression: a circle of radius max(w,h)/2 = 86 reaches 86 px vertically, well past the
    // 29 px the card occupies, and grabs the neighbour above or below.
    const { xy, hw, hh, g } = twoRows();
    const justBelowCard0 = CARD_H / 2 + 6;
    expect(pickRect(g, xy, hw, hh, 0, justBelowCard0, CARD_W)).toBe(-1);
    // …and the point that IS inside card 1 still selects card 1, so the test is not passing by refusing
    // everything.
    expect(pickRect(g, xy, hw, hh, 0, CARD_H + 22, CARD_W)).toBe(1);
  });

  it("respects the card's real aspect on both axes", () => {
    const { xy, hw, hh, g } = twoRows();
    expect(pickRect(g, xy, hw, hh, 0, 0, CARD_W)).toBe(0);            // centre
    expect(pickRect(g, xy, hw, hh, 0, CARD_H / 2 - 1, CARD_W)).toBe(0); // inside, vertically
    expect(pickRect(g, xy, hw, hh, 0, CARD_H / 2 + 1, CARD_W)).toBe(-1); // just outside
    expect(pickRect(g, xy, hw, hh, CARD_W / 2 + 1, 0, CARD_W)).toBe(-1); // just outside, horizontally
  });

  it("breaks a tie between overlapping cards by nearest CENTRE", () => {
    const xy = new Float32Array([0, 0, 20, 0]);
    const hw = new Float32Array([50, 50]);
    const hh = new Float32Array([20, 20]);
    const g = buildGrid(xy, 2);
    expect(pickRect(g, xy, hw, hh, 18, 0, 50)).toBe(1);
    expect(pickRect(g, xy, hw, hh, 2, 0, 50)).toBe(0);
  });

  it("returns -1 on an empty grid rather than throwing on the render path", () => {
    const g = buildGrid(new Float32Array(0), 0);
    expect(pickRect(g, new Float32Array(0), new Float32Array(0), new Float32Array(0), 0, 0, 10)).toBe(-1);
  });
});

implementations.code:
// A uniform spatial grid over node positions — the index that makes hit-testing and viewport queries
// cost something other than "look at every node" (`gpu-graph-slice-1-renderer-core`).
//
// WHY THIS EXISTS. The DOM graph answers "which nodes are visible" with `isNodeVisible` called once per
// node per commit — an O(N) scan on the main thread. Measured on the live Design Studio graph, the whole
// per-interaction cost is linear at ~19 µs per DOM element (402 nodes ⇒ 99 ms, 8,002 ⇒ 1,051 ms), and a
// per-frame O(N) scan is part of what keeps it that way. At a million nodes an O(N) scan per mousemove is
// not a slow feature, it is a hung window.
//
// WHY A GRID AND NOT A QUADTREE. Build is O(n) rather than O(n log n), lookup is arithmetic rather than
// pointer-chasing, and the whole structure is two flat typed arrays — no per-node objects, so it costs
// ~8 bytes per node and nothing for the GC to walk. A quadtree wins on adversarial clustering; a layered
// DAG layout (`layerDag` + `orderLayers`, which is what feeds this) spreads nodes across rows by
// construction, so the clustering a quadtree defends against is not the distribution we have.
//
// THE STRUCTURE IS A COUNTING SORT. `cellStart` holds the prefix sums and `items` holds node indices
// grouped by cell, so cell `c` owns `items[cellStart[c] .. cellStart[c+1])`. That is the cache-friendly
// shape: one pass to count, one prefix sum, one pass to scatter, and every subsequent read is a
// contiguous run. The obvious alternative — an array of arrays — allocates `cells` objects and scatters
// the reads across the heap.
//
// PURE. No DOM, no GL, no React. Every complexity claim below is asserted in `spatialGrid.test.ts`,
// including a scaling test that fails if `pickNearest` starts to look linear.

/** The grid. All fields are read-only views over two typed arrays plus the transform that addresses them. */
export interface SpatialGrid {
  /** Number of nodes indexed. */
  readonly count: number;
  readonly cols: number;
  readonly rows: number;
  /** World units per cell, on both axes. */
  readonly cellSize: number;
  /** World-space origin of cell (0,0). */
  readonly minX: number;
  readonly minY: number;
  /** Prefix sums, length `cols*rows + 1`. Cell `c` owns `items[cellStart[c] .. cellStart[c+1])`. */
  readonly cellStart: Uint32Array;
  /** Node indices, grouped by cell. Length `count`. */
  readonly items: Uint32Array;
}

/**
 * How many nodes we aim to put in each cell.
 *
 * Two is the balance point, and it is a real trade rather than a preference. Lower means more cells:
 * the grid allocates `cols*rows+1` u32s and a rect query touches more of them, so memory and the
 * per-query constant both rise. Higher means longer runs to scan inside each cell, which is what turns
 * `pickNearest` from O(1)-expected back toward linear. Two keeps a point query looking at ~18 nodes
 * across the 3×3 cell neighbourhood it must consider.
 */
const TARGET_PER_CELL = 2;

/**
 * Hard ceiling on `cols*rows`, independent of `count`.
 *
 * Without it a degenerate distribution — a few thousand nodes with one outlier a million units away —
 * yields a tiny `cellSize` against a vast bounding box and asks for an allocation big enough to kill the
 * tab. The cap grows the cell instead, which costs query time on a pathological input and nothing at all
 * on a sane one. Failing slower is always better than failing with an out-of-memory.
 */
const MAX_CELLS = 1 << 22;

/**
 * Build the index. `xy` is interleaved `[x0,y0, x1,y1, …]`; only the first `count` pairs are read.
 *
 * O(n) — three linear passes (bounds, count, scatter) plus an O(cells) prefix sum, and `cells` is
 * proportional to `n` by construction. No allocation per node.
 *
 * A non-finite coordinate is CLAMPED into the grid rather than rejected: this runs on the render path,
 * and a NaN that drops a node out of the index makes it invisible AND unpickable — a node you can see
 * but cannot click is a worse failure than one drawn at the edge.
 */
export function buildGrid(xy: Float32Array, count: number, targetPerCell = TARGET_PER_CELL): SpatialGrid {
  const n = Math.max(0, Math.min(count, xy.length >> 1));
  if (n === 0) {
    return { count: 0, cols: 1, rows: 1, cellSize: 1, minX: 0, minY: 0, cellStart: new Uint32Array(2), items: new Uint32Array(0) };
  }
  // Pass 1 — bounds. Non-finite values are skipped here so one NaN cannot swallow the whole extent;
  // they are still placed (clamped) in the scatter pass below.
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let i = 0; i < n; i++) {
    const x = xy[i * 2], y = xy[i * 2 + 1];
    if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  // Every coordinate was non-finite, or there is exactly one distinct point: a single cell is correct
  // and every query degenerates to "scan the one bucket", which is what a one-point index should do.
  if (!Number.isFinite(minX) || !Number.isFinite(minY)) { minX = 0; minY = 0; maxX = 0; maxY = 0; }

  const spanX = Math.max(maxX - minX, 0);
  const spanY = Math.max(maxY - minY, 0);
  // Aim for `n / targetPerCell` cells spread over the bounding area. A zero-area span (all nodes on one
  // row or one point) has no meaningful density, so fall back to a unit cell and let the cap below
  // decide the resolution.
  const area = spanX * spanY;
  let cellSize = area > 0 ? Math.sqrt((area * targetPerCell) / n) : 1;
  if (!Number.isFinite(cellSize) || cellSize <= 0) cellSize = 1;

  let cols = Math.max(1, Math.ceil(spanX / cellSize) || 1);
  let rows = Math.max(1, Math.ceil(spanY / cellSize) || 1);
  // Grow the cell until the grid fits the cap. Each doubling quarters the cell count, so this converges
  // in a handful of iterations from any starting point.
  while (cols * rows > MAX_CELLS) {
    cellSize *= 2;
    cols = Math.max(1, Math.ceil(spanX / cellSize) || 1);
    rows = Math.max(1, Math.ceil(spanY / cellSize) || 1);
  }

  const cells = cols * rows;
  // Length `cells + 1` and counted at `cell + 1`, so after the prefix sum `cellStart[c]` is already the
  // start of cell `c` and `cellStart[c+1]` its end — no separate end array, no off-by-one at the tail.
  const cellStart = new Uint32Array(cells + 1);
  const cellOf = (x: number, y: number): number => {
    const cx = clampInt(Math.floor((x - minX) / cellSize), cols);
    const cy = clampInt(Math.floor((y - minY) / cellSize), rows);
    return cy * cols + cx;
  };
  // Pass 2 — count.
  for (let i = 0; i < n; i++) cellStart[cellOf(xy[i * 2], xy[i * 2 + 1]) + 1]++;
  // Prefix sum.
  for (let c = 1; c <= cells; c++) cellStart[c] += cellStart[c - 1];
  // Pass 3 — scatter. `cursor` starts as a copy of the offsets and is consumed as it fills.
  const cursor = cellStart.slice(0, cells);
  const items = new Uint32Array(n);
  for (let i = 0; i < n; i++) items[cursor[cellOf(xy[i * 2], xy[i * 2 + 1])]++] = i;

  return { count: n, cols, rows, cellSize, minX, minY, cellStart, items };
}

/** Floor-to-cell with clamping, so a non-finite or out-of-range coordinate lands in a real cell. */
function clampInt(v: number, len: number): number {
  return v < 0 || !Number.isFinite(v) ? 0 : v >= len ? len - 1 : v | 0;
}

/**
 * Write the indices of every node inside the world-space rect into `out`; returns how many were written.
 *
 * O(k + cellsTouched) where k is the number of nodes in the touched cells — independent of total node
 * count. The caller owns `out` so a per-frame query allocates NOTHING; when it is too small the result
 * is TRUNCATED and the return value says so, because growing it here would hand the render path an
 * allocation it cannot budget for.
 *
 * This tests cell membership, not exact containment: a node in a touched cell is reported even if it
 * sits just outside the rect. That is deliberate and matches `CULL_MARGIN_VIEWPORTS` — over-reporting
 * costs a few instances in a draw call that is already measured at 1.55 ms per million, while
 * under-reporting is a node missing from the screen.
 */
export function queryRect(g: SpatialGrid, x: number, y: number, w: number, h: number, out: Uint32Array): number {
  if (g.count === 0 || out.length === 0) return 0;
  const c0 = clampInt(Math.floor((x - g.minX) / g.cellSize), g.cols);
  const c1 = clampInt(Math.floor((x + w - g.minX) / g.cellSize), g.cols);
  const r0 = clampInt(Math.floor((y - g.minY) / g.cellSize), g.rows);
  const r1 = clampInt(Math.floor((y + h - g.minY) / g.cellSize), g.rows);
  let m = 0;
  for (let r = r0; r <= r1; r++) {
    const rowBase = r * g.cols;
    // One contiguous run per ROW rather than per cell: cells within a row are adjacent in `items`, so a
    // whole row of the query rect is a single span and `subarray`-free copy loop.
    const start = g.cellStart[rowBase + c0];
    const end = g.cellStart[rowBase + c1 + 1];
    for (let k = start; k < end; k++) {
      if (m >= out.length) return m;
      out[m++] = g.items[k];
    }
  }
  return m;
}

/**
 * The node nearest to (`x`,`y`) within `maxRadius` world units, or -1.
 *
 * O(1) expected: the search visits the cells within `maxRadius` of the point, and cell occupancy is
 * bounded by `targetPerCell` in expectation, so the work does not grow with node count. That is the
 * property `pickNearest_does_not_degrade_toward_linear` asserts.
 *
 * `radii` gives each node's own hit radius — pass a number for a uniform one. A node is a candidate only
 * when the point is inside ITS radius, so a big node still wins over a small one that happens to be a
 * little closer to the cursor, which is what makes clicking feel right.
 */
export function pickNearest(
  g: SpatialGrid,
  xy: Float32Array,
  radii: Float32Array | number,
  x: number,
  y: number,
  maxRadius: number,
): number {
  if (g.count === 0) return -1;
  const reach = Math.max(0, maxRadius);
  const c0 = clampInt(Math.floor((x - reach - g.minX) / g.cellSize), g.cols);
  const c1 = clampInt(Math.floor((x + reach - g.minX) / g.cellSize), g.cols);
  const r0 = clampInt(Math.floor((y - reach - g.minY) / g.cellSize), g.rows);
  const r1 = clampInt(Math.floor((y + reach - g.minY) / g.cellSize), g.rows);
  let best = -1;
  // Squared throughout — a hit test does not need the square root, and skipping it removes one sqrt per
  // candidate from a path that runs on every mousemove.
  let bestD2 = Infinity;
  for (let r = r0; r <= r1; r++) {
    const rowBase = r * g.cols;
    const start = g.cellStart[rowBase + c0];
    const end = g.cellStart[rowBase + c1 + 1];
    for (let k = start; k < end; k++) {
      const i = g.items[k];
      const dx = xy[i * 2] - x, dy = xy[i * 2 + 1] - y;
      const d2 = dx * dx + dy * dy;
      if (d2 >= bestD2) continue;
      const rad = typeof radii === "number" ? radii : radii[i];
      if (d2 > rad * rad) continue;
      bestD2 = d2;
      best = i;
    }
  }
  return best;
}

/**
 * The node whose RECTANGLE contains (`x`,`y`), or -1 — the hit test for card-shaped nodes.
 *
 * `pickNearest` measures a circle, which is right for a dot and wrong for a card. On the Design Studio's
 * 172x58 cards a circle of radius `max(w,h)/2` reaches 86 px vertically and selects a node a whole row
 * away, while a circle of `min/2` misses the card's own ends. Neither radius is correct because the shape
 * is not a circle.
 *
 * O(1) expected, exactly like `pickNearest`: the same cell neighbourhood, the same bounded occupancy.
 * `reach` must cover the largest half-extent on EITHER axis or a wide card is unpickable near its ends.
 *
 * When rectangles overlap, the nearest CENTRE wins — the same tie-break a user expects when cards are
 * densely packed and two hit areas meet.
 */
export function pickRect(
  g: SpatialGrid,
  xy: Float32Array,
  halfW: Float32Array,
  halfH: Float32Array,
  x: number,
  y: number,
  reach: number,
): number {
  if (g.count === 0) return -1;
  const r = Math.max(0, reach);
  const c0 = clampInt(Math.floor((x - r - g.minX) / g.cellSize), g.cols);
  const c1 = clampInt(Math.floor((x + r - g.minX) / g.cellSize), g.cols);
  const r0 = clampInt(Math.floor((y - r - g.minY) / g.cellSize), g.rows);
  const r1 = clampInt(Math.floor((y + r - g.minY) / g.cellSize), g.rows);
  let best = -1;
  let bestD2 = Infinity;
  for (let row = r0; row <= r1; row++) {
    const rowBase = row * g.cols;
    const start = g.cellStart[rowBase + c0];
    const end = g.cellStart[rowBase + c1 + 1];
    for (let k = start; k < end; k++) {
      const i = g.items[k];
      const dx = x - xy[i * 2];
      const dy = y - xy[i * 2 + 1];
      // Containment first — cheaper than the distance, and it is the actual question.
      if (dx < -halfW[i] || dx > halfW[i] || dy < -halfH[i] || dy > halfH[i]) continue;
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) {
        bestD2 = d2;
        best = i;
      }
    }
  }
  return best;
}

import { useEffect, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { addDbProject, listDbProjects, setDbTriaged } from "@/features/planner";
import { markBoot, logStartupTrace } from "@/shared/lib/core/startupTrace";
import { startPerfMonitor, recordStoreWrite } from "@/shared/lib/core/perf";
import { log } from "@/shared/lib/core/log";
import { safeInvoke, fireInvoke } from "@/shared/lib/core/safeInvoke";
// `worktreeChecks` / `reconcileMissingWorktrees` are NOT imported here any more — the decision moved
// to Rust (`reconcile_worktrees`). The TypeScript copy stays in place, still bound to the Rust by
// `worktreeReconcile.fixtures.json`, and is deleted only once the divergence log has been empty in
// the field. Per the epic method, a flip does not delete its predecessor.
import type { EndedInfo } from "@/store/types/console";
import { useAppStore } from "@/store";
import { accentVars } from "@/features/settings";
import { applyThemeToRoot } from "@/shared/ui/kit/theme";
import { applyContributionsToRoot } from "@/shared/ui/kit";

/** Delay (ms after hydration) before the perf monitor + store-write diagnostics start, so they don't
 *  load the cold-start window (#1033). Metrics during boot have no diagnostic value. */
const METRICS_GRACE_MS = 5000;

/**
 * The app-shell boot + lifecycle effects, pulled out of App so the shell reads as composition:
 * the accent CSS vars, the startup-timing trace, the one-shot base-dir / crash-flag / skills
 * hydration, and the deferred perf monitor + store-write diagnostics.
 */
export function useAppBoot() {
  const accent = useAppStore((s) => s.accent);
  const kitTheme = useAppStore((s) => s.kitTheme);
  const kitThemes = useAppStore((s) => s.kitThemes);
  const designContributions = useAppStore((s) => s.designContributions);
  const hasHydrated = useAppStore((s) => s.hasHydrated);
  const setBscBaseDir = useAppStore((s) => s.setBscBaseDir);
  // Guards the one-time draft→DB migration (#2995) so it fires exactly once per app session.
  const draftsMigratedToDb = useRef(false);
  const triagedSyncedToDb = useRef(false);
  const worktreeReconciled = useRef(false);

  // Apply the chosen accent to the design-token CSS vars at the document root,
  // live on change and after persisted state rehydrates. Inline vars on :root
  // override the stylesheet defaults; the default accent is a no-op restore.
  useEffect(() => {
    const { accent: a, accentDim } = accentVars(accent);
    const root = document.documentElement;
    root.style.setProperty("--accent", a);
    root.style.setProperty("--accent-dim", accentDim);
  }, [accent]);

  // Apply the chosen kit theme (#1852 Phase 3) to the semantic component tokens at the document root,
  // live on change and after rehydrate. A theme sets --card-*/--btn-*/--field-*/--chip-* overrides;
  // switching clears the prior theme's set first, so `default` restores the stylesheet look.
  // `kitThemes` is read as a dep (#2488) so the vars re-apply after the theme STORE hydrates — the
  // chosen theme may be designer-edited (or designer-authored) and differ from the packaged fallback.
  useEffect(() => { void kitThemes; applyThemeToRoot(kitTheme); }, [kitTheme, kitThemes]);

  // Apply the persisted downloaded-blueprint design overlays (#2656/#2663), live on add/remove AND after
  // the store rehydrates. Keyed on `designContributions` (NOT the one-shot mount effect) because persist
  // hydration is async: a mount-time read sees the default [] and would never re-apply the restored
  // overlays. Mirrors applyThemeToRoot above (compose-don't-mutate — a managed :root <style>).
  useEffect(() => { applyContributionsToRoot(designContributions); }, [designContributions]);

  // Startup timing trace (#perf): mark the gate commit, then the first paint of the
  // real UI once the store rehydrates — logStartupTrace emits the breakdown once.
  //
  // `boot_mounted` rides the same effect, and is NOT tracing: it is the ack the Rust launch watchdog
  // is waiting on (the-app-starts-and-never-mounts-and-nothing-says-so). Silence past its deadline is
  // recorded as a `launch` fault, because a window that opens and never mounts looks identical from
  // Rust to a slow boot, a failed module fetch and a frozen page. This is the one signal that tells
  // them apart, and it also CLEARS what the last boot recorded about itself.
  //
  // At `mounted`, not `hydrated`/`painted`: the failure being ruled out is "the UI never mounted", and
  // acking at a later milestone would let a slow rehydrate file a fault about a boot that plainly
  // worked. Fire-and-forget — a missing backend (the browser harness, a test) must not break boot.
  useEffect(() => {
    markBoot("mounted");
    fireInvoke("boot_mounted");
  }, []);
  useEffect(() => {
    if (!hasHydrated) return;
    markBoot("hydrated");
    requestAnimationFrame(() => { markBoot("painted"); logStartupTrace(); });
  }, [hasHydrated]);

  // One-time draft → projects-DB migration (#2995): after the store rehydrates, upsert every entry in
  // the fragile `localDraftProjects` cache into the durable projects DB (`bsc project db add` is an
  // idempotent upsert), so drafts that only ever lived in the cache become restart-durable. Gated on
  // `hasHydrated` because persist is async — a mount-time read would see the pre-hydration empty map —
  // and ref-guarded so it runs exactly once. Each write is fire-and-forget and degrades silently when
  // the bridge/binary is absent.
  useEffect(() => {
    if (!hasHydrated || draftsMigratedToDb.current) return;
    draftsMigratedToDb.current = true;
    const drafts = useAppStore.getState().localDraftProjects;
    for (const [key, d] of Object.entries(drafts)) {
      void addDbProject({ key, title: d.title, pitch: d.pitch, state: "drafted" });
    }
  }, [hasHydrated]);

  // TRIAGED markers ↔ projects.db (#4088). The marker gates the whole Glance network (#2541), and it
  // used to live ONLY in app-state.json — unreachable from `bsc`, lost on an app-state reset, and
  // diagnosable only by reading a raw zustand blob. projects.db is the source now; this reconciles.
  //
  // BOTH directions, once, in this order:
  //   ① push any marker the cache still holds that the DB has not got — the upgrade path, so a user
  //     who triaged projects before #4088 does not watch them vanish from Glance on first launch;
  //   ② union the DB's markers into the cache — the durable set wins for everything else, and a
  //     marker set on another machine or repaired via `bsc project triaged set` shows up here.
  //
  // Gated on `hasHydrated` (persist is async — a mount-time read sees an empty map) and ref-guarded so
  // it runs exactly once. Degrades silently: with no bridge the in-memory cache still gates the session.
  useEffect(() => {
    if (!hasHydrated || triagedSyncedToDb.current) return;
    triagedSyncedToDb.current = true;
    void (async () => {
      const cached = useAppStore.getState().triagedProjects;
      const rows = await listDbProjects();
      if (!rows) return; // bridge unreachable — keep the cache as-is
      const fromDb: Record<string, number> = {};
      for (const r of rows) {
        if (typeof r.triagedAt === "number") fromDb[r.key] = r.triagedAt;
      }
      for (const key of Object.keys(cached)) {
        if (!(key in fromDb)) void setDbTriaged(key); // ① upgrade the pre-#4088 markers forward
      }
      useAppStore.getState().hydrateTriaged(fromDb); // ② durable set into the cache
    })();
  }, [hasHydrated]);

  // Fleet worktree reconciliation (#3614): after hydrate, mark any persisted fleet worker whose worktree
  // was reclaimed by the boot-GC (merged+clean = work landed) as ENDED — so its `<project> · build` tab
  // renders a resting card instead of relaunching the worker into a deleted directory. That relaunch
  // spawned a burst of doomed PTYs into missing cwds, jamming the backend event loop on EVERY boot. Gated
  // on `hasHydrated` (persist is async), ref-guarded to run once. `dir_exists` defaults to `true` on any
  // bridge/command miss, so a probe failure can never wrongly end a live worker.
  useEffect(() => {
    if (!hasHydrated || worktreeReconciled.current) return;
    worktreeReconciled.current = true;
    const s = useAppStore.getState();
    // THE DECISION RUNS IN RUST (`a-reclaimed-worktree-reports-why-it-was-reclaimed`). It owns the
    // worktrees, ran the GC that removed them, and is the only place that knows WHY — the reason is
    // unrecoverable afterwards, because `worktree_is_disposable` compares against a clone the orphan
    // path has already deleted. The renderer used to probe `dir_exists` per pane and infer "work
    // merged" from the absence, which was false on that arm.
    //
    // Rust cannot mark the panes: `markPaneEnded` is zustand state it does not own. So it returns the
    // marks and this applies them — derive there, render here.
    const panes = Object.keys(s.fleetPaneStreams).map((paneId) => ({
      paneId,
      stream: s.fleetPaneStreams[paneId],
      cwd: s.paneCwds[paneId],
      ended: !!s.endedPanes[paneId],
      disabled: !!s.disabledPanes[paneId],
    }));
    if (panes.length === 0) return;
    void safeInvoke<{ paneId: string; info: EndedInfo }[]>("reconcile_worktrees", { panes }, []).then(
      (marks) => {
        for (const m of marks) {
          // Re-checked HERE and not in Rust: the store may have marked this pane ended while the
          // command was in flight, and the backend holds no view of that.
          if (useAppStore.getState().endedPanes[m.paneId]) continue;
          log.info(`worktree-reconcile: ${m.paneId} worktree gone → marking ended (${m.info.summary})`);
          useAppStore.getState().markPaneEnded(m.paneId, m.info);
        }
      },
    );
  }, [hasHydrated]);

  // Fetch the app-managed base directory once so the rest of the UI can
  // compute repo local paths deterministically without round-tripping Rust.
  useEffect(() => {
    invoke<string>("get_base_dir")
      .then(setBscBaseDir)
      .catch((e) => log.error(`get_base_dir failed: ${e}`));
    // Crash recovery (#1041): learn once whether the previous shutdown was unclean — gates the
    // restore banner + session auto-resume (a clean quit leaves sessions dormant).
    invoke<boolean>("was_unclean_shutdown")
      .then((v) => {
        useAppStore.getState().setUncleanShutdown(v);
        // #3961: the same signal, asked of the LOOP store. A loop in flight when the app died is never
        // reconciled — nothing closes it, so it stays `open` forever and a participant's `bsc loop
        // watch` blocks on a turn that will never come. Only an UNCLEAN shutdown implies that; after a
        // clean quit an open loop is legitimately dormant, so this is gated exactly like the session
        // restore.
        //
        // IT CLOSES THEM HERE rather than counting and asking. `loop reap` is unconditional, so the
        // decision it needs is "is anything running" — and this point, gated on an unclean shutdown
        // and before any session is launched, is the one place that can answer it. Leaving the choice
        // to a banner made the user the gate for a question they cannot see the state of, on a
        // decision with one answer. The notice reports what was closed.
        if (v) void useAppStore.getState().reapStrandedLoops();
      })
      .catch(() => { /* command absent (e.g. tests) — leave false */ });
    // Skills library (#1338 ph2): hydrate from the global skills.db so the desktop UI, the planner,
    // and every live `bsc-skill` session share ONE library. Reconciles the code-owned packaged set
    // and seeds the db on first run; a no-op when the bridge is absent (keeps the seeded set).
    void useAppStore.getState().hydrateSkills();
    // Persona library (#2094): hydrate from the global persona store (`bsc persona`) so the desktop
    // Personas tab, live sessions, and the planner share ONE library. Reconciles the packaged
    // built-ins + seeds the store on first run; a no-op when the bridge is absent (keeps the seed).
    void useAppStore.getState().hydratePersonas();
    // Org library (#2193): hydrate the persona-relationship graph from the global org store (`bsc org`)
    // so the desktop Org tab, live sessions, and the planner share ONE library. Reconciles the packaged
    // built-ins + seeds the store on first run; a no-op when the bridge is absent (keeps the seed).
    void useAppStore.getState().hydrateOrgs();
    // The NETWORKS — Glance's tab strip is derived from them, so a boot that skipped this would show
    // only the two fixed tabs and read as "you have no networks" rather than "not loaded yet".
    void useAppStore.getState().hydrateNetworks();
    // Component library (#2269): hydrate the proven-component library from the global `bsc ui`
    // store so the planner's test_ui pane + (later) the Design Studio share ONE library. A no-op that
    // keeps the typed seed when the bridge is unreachable (which is every build until the store lands).
    void useAppStore.getState().hydrateComponents();
    // The ALGORITHM impls (resolver-reads-the-algorithms-store) — the set `resolveGraphSource` matches a
    // module-granularity `provides` against, so a logic module authored as a record resolves like a
    // component does. Same contract as the components hydrate: a no-op when the read is unavailable, so
    // a degraded environment resolves nothing rather than failing boot.
    void useAppStore.getState().hydrateAlgorithms();
    // Kit-usage consumer index (#2277): hydrate which projects use which kit from the global
    // `bsc ui usage` store — the edges a kit change fans out over. No-op keeping the cache when
    // the bridge is absent.
    void useAppStore.getState().hydrateKitUsage();
    // Kit themes (#2488): hydrate the designer-writable theme collection from the global `bsc ui
    // theme` store — the Settings picker, the Design Studio preview switcher, and every ThemeScope
    // resolve against it. No-op keeping the packaged registry when the bridge is absent.
    void useAppStore.getState().hydrateThemes();
    // Data-defined component variants (#2569): compile the designer-authored `bsc ui variants` store
    // into the managed `<style>` so an LLM-authored variant renders on boot (re-applied on ui-touch).
    void useAppStore.getState().hydrateVariants();
    // (Design contributions are applied by the `designContributions`-keyed effect above, #2663 — a
    // one-shot mount read here saw the pre-hydration default [] and never re-applied the restored set.)
    // Project relationships (#2253): hydrate the Glance L1 network edges from the global `bsc project
    // link` store so the desktop, live sessions, and a restart share ONE set. A no-op when the bridge
    // is absent (keeps the persisted cache).
    void useAppStore.getState().hydrateProjectLinks();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Defer the perf monitor + store-write diagnostics past the cold-start window (#1033). Both run
  // every 2s and add IPC + sampling load that's pure overhead while the app is still booting (and
  // useless before it's interactive) — start them a few seconds after hydration instead of at mount.
  useEffect(() => {
    if (!hasHydrated) return;
    let unsub: (() => void) | undefined;
    const id = setTimeout(() => {
      // Watch the main thread for jank (logs `[perf] main thread blocked …`).
      startPerfMonitor();
      // Count how often each store key changes, so a re-render loop reveals which key drives it.
      unsub = useAppStore.subscribe((state, prev) => {
        const s = state as unknown as Record<string, unknown>;
        const p = prev as unknown as Record<string, unknown>;
        for (const k in s) {
          if (s[k] !== p[k]) recordStoreWrite(k);
        }
      });
    }, METRICS_GRACE_MS);
    return () => { clearTimeout(id); unsub?.(); };
  }, [hasHydrated]);
}

// Projects domain — page mode/view, active-project meta, drafts, startup-prompt + reference-context
// assignment, planning-session context, triage + fleet launch. Split from store/types (#1634).
import type { FleetPlan, AgentStream } from "@/features/planner/fleet/planFleet";
import type { ProjectLink, ContractTarget } from "@/features/glance/lib/projectLinks";
import type { GEdgeKind, GRole, GHealth, GActivity } from "@/features/glance/lib/glanceGraph";
import type { PreviewSource } from "@/shared/lib/preview/previewSource";
import type { ReviewFinding } from "@/shared/lib/preview/previewReview";

/** Projects slice of {@link AppStore}. */
export interface ProjectsState {
  // Projects (transient). "designs" is the Designs studio page (#move-to-planner) — formerly its own rail
  // Workspace, folded in as a Planner tab; it owns the structure axis AND, since #2834, the theme try-on,
  // so the standalone "themes" tab was retired (#2850). "algorithms" is the knowledge graph, folded in
  // the same way (formerly its own rail Workspace).
  projectsPageMode: "projects" | "teams" | "designs" | "algorithms" | "sounds";
  setProjectsPageMode: (v: "projects" | "teams" | "designs" | "algorithms" | "sounds") => void;
  // Glance drill target (#…), PER TAB: for each Glance tab, the project whose fleet graph is open on it,
  // or null/absent for that tab's project network. Lifted into the store (transient, not persisted) so
  // the app-wide navigation history (mouse back/forward) can drive it alongside the active workspace.
  // See useNavHistory.
  //
  // KEYED BY TAB, exactly as `activePageTab` is keyed by workspace. It was ONE value shared by every
  // tab, so drilling on one network applied that navigation to all of them — switching tabs landed you
  // inside a drill belonging to a different domain, on a graph that does not contain the node. Nothing
  // re-scoped it on a tab change, because a single value has nothing to re-scope.
  glanceDrill: Record<string, string | null>;
  setGlanceDrill: (tab: string, id: string | null) => void;
  // The graph's PAN/ZOOM per Glance tab (`each-glance-tab-remembers-its-own-viewport`). Recorded when
  // you leave a tab and restored when you come back, so a tab keeps the place you left it in rather
  // than inheriting the previous tab's transform — one viewport instance serves every tab, so without
  // this a switch lands you at whatever position the other graph was at.
  //
  // Transient like `glanceDrill`, and written only on a tab SWITCH — never per pan frame, which would
  // put a store write on every mousemove.
  glanceView: Record<string, { tx: number; ty: number; scale: number }>;
  setGlanceView: (tab: string, view: { tx: number; ty: number; scale: number }) => void;
  // Verify-preview (#2623, transient): the PreviewSource the verify-build produced per project (what the
  // graph's preview node renders), and whether a build is in flight. Not persisted — a served preview
  // URL dies with its process, so it's re-built on demand.
  previewSources: Record<string, PreviewSource>;
  setPreviewSource: (key: string, source: PreviewSource) => void;
  previewBuilding: Record<string, boolean>;
  setPreviewBuilding: (key: string, building: boolean) => void;
  // Preview REVIEW findings (#2623 slice 5b, transient): what the reviewer (Claude) flagged about the
  // running preview, per project key, in the confirm-gated inbox (pending → user confirms/dismisses;
  // confirmed ones route to the fleet, 5d). Not persisted — findings belong to a live preview session.
  reviewFindings: Record<string, ReviewFinding[]>;
  setReviewFindings: (key: string, findings: ReviewFinding[]) => void;
  // Teams drill target (#2492): the pool nodeId whose sub-graph is open in the Teams designer, or null for
  // the parent graph. Transient like glanceDrill and lifted into the store for the same reason — the
  // app-wide navigation history (mouse back/forward) steps drill in/out. See useNavHistory.
  teamsDrill: string | null;
  setTeamsDrill: (id: string | null) => void;
  // Inter-app contracts (#2253 → #3786 Phase 2) — the edges of the Glance L0 network. A write-through
  // cache over the global `bsc project link` store (agent-reachable): `addProjectLink` (idempotent,
  // deterministic id) + `removeProjectLink` push through the bridge; `hydrateProjectLinks` loads
  // authoritative on boot; the persisted copy is a fast-first-paint fallback. `target` (#3786) names a
  // NON-project endpoint (an external service / mcp server); absent ⇒ a project↔project contract.
  projectLinks: ProjectLink[];
  addProjectLink: (from: string, to: string, kind: GEdgeKind, target?: ContractTarget) => void;
  removeProjectLink: (id: string) => void;
  /** Hydrate the links from the global `bsc project link` store on boot (write-through cache). No-op when
   *  the bridge is unreachable (keeps the persisted cache). */
  hydrateProjectLinks: () => Promise<void>;
  // The Projects page is list ↔ planning (#499): the board moved to the GitHub
  // page (#498) and the execution tabs were removed.
  projectsView: "list" | "planning";
  setProjectsView: (v: "list" | "planning") => void;
  activeProjectId: string | null;
  activeProjectName: string;
  activeProjectRepo: string;
  activeProjectRepos: string[];
  activeProjectNumber: number;
  setActiveProject: (id: string | null) => void;
  setActiveProjectMeta: (id: string | null, name: string, repo: string, number: number, repos?: string[]) => void;
  setActiveProjectRepos: (repos: string[]) => void;
  // Purge a project's local footprint from the store: the per-project plan/config
  // maps and repo-scoped (`<key>::<repo>`) maps for every key in `keys` (pass the
  // name-derived slug, plus any legacy forms — the raw title and the GitHub node id —
  // so grandfathered entries drop too, #2409), plus the active-project meta if it
  // matches. Pairs with the backend delete_project_dir for the on-disk hub.
  deleteLocalProject: (keys: string[]) => void;
  /** New, not-yet-published projects (drafts, #379). Keyed by the planning session key —
   *  the name-derived slug (`projectSlug(name)`, #2409) frozen at creation, or a legacy key
   *  (minted `p-…` id / title-sanitized) for grandfathered drafts. The record's `title` is
   *  display-only: renaming edits it in place (`updateDraftProject`) and never moves the
   *  on-disk hub (the folder keeps its birth-slug). */
  /** `role`/`health`/`activity` (#2284/#2541) are OPTIONAL Glance-node hints: when set they give the
   *  project's node its curated colour/state on the Glance network (`infra/service/data/client` ·
   *  health `idle/healthy/warning/error` · activity `building/waiting/review/…`), else
   *  `useGlanceProjects` derives them. Lets a project (or a loaded demo) declare its own colouring. */
  localDraftProjects: Record<string, { title: string; pitch: string; createdAt: number; role?: GRole; health?: GHealth; activity?: GActivity; reason?: string }>;
  addDraftProject: (key: string, draft: { title: string; pitch: string; createdAt: number; role?: GRole; health?: GHealth; activity?: GActivity; reason?: string }) => void;
  /** Patch a draft record in place (#1222) — persists a title edit so it survives a reopen;
   *  keyed by the FROZEN key so the on-disk folder doesn't move. No-ops if the draft is gone. */
  updateDraftProject: (key: string, patch: Partial<{ title: string; pitch: string }>) => void;
  removeDraftProject: (key: string) => void;
  /** TRIAGED projects (#2541): the durable set of projects whose triage/fleet has been launched — the
   *  drafted→triaged transition. Keyed by the plan key → the ms epoch it was first triaged. This is what
   *  gates the Glance network: a project appears there only once it's WORKING (`useGlanceProjects` filters
   *  to these keys), so a mere draft/plan never shows. Stamped by `triageStartProject`/`fleetStartProject`. */
  triagedProjects: Record<string, number>;
  /** Mark a project triaged (idempotent — keeps the first timestamp). */
  markProjectTriaged: (key: string) => void;
  /** Union the durable triaged markers from projects.db into the cache (#4088). */
  hydrateTriaged: (fromDb: Record<string, number>) => void;
  /**
   * Move every per-project store entry from `oldKey` to `newKey` (#2409) — the store half of the
   * one-time hub relink (`relink_project_hub`) that migrates a legacy-keyed project onto its
   * name-derived slug. Covers the per-project data maps (plans, fleet, repos, drafts, toggles),
   * the repo-scoped (`<key>::<repo>`) prompt maps, and extension/skill scope lists. Target-wins:
   * an entry already present under `newKey` is never clobbered (the old one is dropped). Console
   * tab/pane state is NOT rewritten — a relinked project relaunches its fleet under the new key.
   */
  rekeyProjectData: (oldKey: string, newKey: string) => void;
  // Dev reset: clears all project/plan-scoped state (keeps auth, profiles, UI).
  resetProjectData: () => void;
  // GitHub project ids the user removed in-app (persisted). The Projects list is
  // re-fetched from GitHub on every sync, so without this a deleted-but-still-
  // returned project (closed, delete denied, or stale) would reappear. The list
  // is filtered against this set so removal sticks.
  hiddenProjectIds: string[];
  dismissProject: (id: string) => void;
  // Startup-prompt assignment (persisted). Values are unified-store document
  // relpaths, or null = inherit. Resolution: repo → project → global default →
  // built-in. See lib/startupPrompt.ts.
  defaultStartupPromptDoc: string | null;
  setDefaultStartupPromptDoc: (doc: string | null) => void;
  projectStartupPromptDoc: Record<string, string | null>;
  setProjectStartupPromptDoc: (projectId: string, doc: string | null) => void;
  repoStartupPromptDoc: Record<string, string | null>;
  setRepoStartupPromptDoc: (projectId: string, repo: string, doc: string | null) => void;
  // Per-repo TRIAGE starting script (persisted). relpath of a unified-store doc,
  // or null. Used by triageStartProject for that repo's triage pane; falls back
  // to the verbatim TRIAGE_PROMPT when unset. Keyed by repoPromptKey.
  repoTriagePromptDoc: Record<string, string | null>;
  setRepoTriagePromptDoc: (projectId: string, repo: string, doc: string | null) => void;
  // The GitHub page's active top tab (summary | projects | repos), store-controlled
  // so other screens can deep-link to it (e.g. the Projects list signpost → projects).
  githubTab: string;
  setGithubTab: (t: string) => void;
  // The GitHub Projects v2 board now lives on the GitHub page (#498). When a project
  // is opened from the GitHub portfolio, this flips on and its board renders there
  // with `githubBoardTab` selecting the sub-view. Session-only (not persisted).
  githubBoardOpen: boolean;
  githubBoardTab: "board" | "roadmap" | "issues" | "insights";
  /** Open the GitHub-page board for the active project at a given sub-tab. */
  openGithubBoard: (tab?: "board" | "roadmap" | "issues" | "insights") => void;
  setGithubBoardTab: (t: "board" | "roadmap" | "issues" | "insights") => void;
  closeGithubBoard: () => void;
  projectsDrawerIssue: number | null;
  setProjectsDrawerIssue: (n: number | null) => void;
  planningPitch: string;
  planningRepo: string;
  planningTitle: string;
  setPlanningContext: (pitch: string, repo: string) => void;
  setPlanningTitle: (title: string) => void;
  // Stable per-session key for the planning directory, PTY slot, and plan
  // buckets. Frozen the moment a planning session begins so that neither the
  // publish flow assigning a GitHub Project id, nor the user editing the title,
  // can move the working directory out from under an active session. This is the
  // name-derived slug (`projectSlug(name)`, #2409) frozen at creation — renames are
  // display-only (the folder keeps its birth-slug); grandfathered projects pass
  // their legacy key (minted `p-…` id / title-sanitized) here unchanged.
  planningSessionKey: string;
  setPlanningSession: (key: string) => void;
  /** A prompt queued for the live planner session of a project, keyed by project key.
   *  Planning.tsx writes it into the planner PTY (a deliberate, user-triggered inject —
   *  e.g. the file-intake "Route" action) and clears it. (#604) */
  pendingPlannerPrompt: Record<string, string>;
  requestPlannerPrompt: (projectKey: string, text: string) => void;
  clearPlannerPrompt: (projectKey: string) => void;
  // Per-project AUTO-TRIAGE toggle (#2265). When ON, the fault-fix loop (useFaultTriage) routes a fix
  // for a new unresolved runtime fault (errordb, #2260) into the project's director via bsc-issue →
  // bsc-assign; when OFF (the default) faults are surfaced (the Glance node badge) but never
  // auto-dispatched. Keyed by the project's plan key (the same key the errordb/plan.db resolve under).
  autoTriage: Record<string, boolean>;
  /** Flip a project's auto-triage toggle (persisted). Default (absent) is OFF = surface-only. */
  setAutoTriage: (projectKey: string, on: boolean) => void;
  // Per-node Glance OFF toggle (#3239) — the user has DEACTIVATED this node from its details pane, so
  // it renders greyed (health `off`) on the network and reads "off" over any live status. Persisted so it
  // continues from the last session; keyed by the Glance node id (a project's plan key). Sparse map:
  // absent ⇒ the node is ON (its normal derived status). Cleaned on project delete/rename.
  glanceOff: Record<string, boolean>;
  /** Turn a Glance node off (deactivate, greyed) or back on (persisted). Default (absent) is ON. */
  setGlanceNodeOff: (nodeId: string, off: boolean) => void;
  // Per-project KIT AUTO-DISPATCH toggle (#2277). When ON, the kit-change drain (useKitDispatch) delivers
  // a BREAKING kit change queued for this consumer to a rail — a live fleet → its director via bsc-issue →
  // bsc-assign; no live fleet → a plain kit-update GitHub issue in the consumer repo. When OFF (the
  // default) queued changes are surface-only (KitChangesCard). Keyed by the consumer project's plan key.
  autoKitDispatch: Record<string, boolean>;
  /** Flip a project's kit auto-dispatch toggle (persisted). Default (absent) is OFF = notify-only. */
  setAutoKitDispatch: (projectKey: string, on: boolean) => void;
  // project key -> structure node id -> linked GitHub issue (#393).
  issueLinks: Record<string, Record<string, { number: number; url: string }>>;
  // Merge links for a project (idempotent upsert; never drops existing entries).
  setIssueLinks: (projectKey: string, links: Record<string, { number: number; url: string }>) => void;
  // Repository resolution — base dir is `~/.base-studio-code` (the base); repo
  // clone paths are derived as `<base>/projects/<key>/<repo>`.
  bscBaseDir: string;
  setBscBaseDir: (dir: string) => void;
  projectLocalRepos: Record<string, string[]>;
  addProjectRepo: (projectId: string, fullName: string) => void;
  // `deltas` (#1004): optional per-repo (fullName → lead) since-last-run summary, prepended to
  // each pane's default triage prompt so a re-run resumes from what changed instead of re-ingesting.
  // Built by `prepareTriageRun` (which also records the new run marker) and passed in at launch.
  // `clonePaths` (#1819): optional per-repo (fullName → absolute clone dir) cwds resolved from the
  // Rust backend (`repo_dir_path`), mirroring `fleetStartProject`'s `paths`. Used verbatim so a
  // triage launch never depends on the async-loaded `bscBaseDir` mirror (empty at crash-recovery
  // startup → empty cwd → the settings.json writer is skipped → a permission-less session); falls
  // back to the `bscBaseDir`-derived path per repo when an entry is absent.
  triageStartProject: (projectName: string, repos: string[], projectId?: string, deltas?: Record<string, string>, clonePaths?: Record<string, string>) => void;
  // #1004: read each repo's last-triage marker + the since-then changed-issue delta from plan.db,
  // render a one-line resume lead per repo, and STAMP a fresh run marker (read-before-write). Keyed
  // by the project's plan.db key (effectiveProjectId). Returns the fullName → lead map for `deltas`.
  prepareTriageRun: (projectKey: string, repos: string[]) => Promise<Record<string, string>>;
  // Index of this project's triage tab, matched on its STABLE projectKey — the
  // name-derived key (#457/#2409), not the derived "· triage" name — so a rename never
  // forks a duplicate. Pass the same projectName used to launch it. -1 when none.
  findTriageTabIdx: (projectName: string) => number;
  // Launch the agent fleet: a "· build" tab with the director (if enabled) at the
  // project root and one worker pane per launched stream in its repo clone. Path
  // keys off projectKey (the planning session key — where repos/prompts live).
  /** Launches the fleet; returns the fleet roster rows (paneId/stream/repo/branch/role TSV,
   *  one per live session) for the caller to persist via publishFleetRoster (#734). */
  fleetStartProject: (
    projectName: string,
    fleet: FleetPlan,
    projectKey: string,
    /** Authoritative absolute cwds from the Rust backend (#905): the hub dir
     *  (`project_dir_path`) for the director and each stream's worktree path
     *  (`ensure_worktree`) for its worker. Used verbatim so the launch never
     *  depends on the async-loaded `bscBaseDir` mirror; falls back to the
     *  `bscBaseDir`-derived path per pane when an entry is absent. */
    paths?: { hubPath?: string; worktreePaths?: Record<string, string>;
      /** When set (#1988), the fleet spawns INSIDE this WSL2 distro: hubPath/worktreePaths are
       *  distro-native paths and each pane records `paneWslDistro` so pty_create runs in the cage. */
      wslDistro?: string },
  ) => string[];
  // Index of this project's primary "· build" tab, matched on its STABLE projectKey
  // (#457) — pass the same projectKey used to launch the fleet. -1 when none.
  findFleetTabIdx: (projectKey: string) => number;
  // Coordination (#199 AC#7): paneId ("t{tab}p{pane}") → the AgentStream launched into
  // it. The coordination log keys waiters/producers by PANE id (BSC_AUDIT_PANE), but a
  // stream's produced contracts/issues/owned globs live on the stream by its slug. This
  // map bridges the two so the inbox can build a producer resolver (buildProducerOf) and
  // light up file/issue wait-for cycles. Written at fleet launch, persisted, global
  // (pane ids are unique across all tabs). Only worker panes are recorded.
  fleetPaneStreams: Record<string, AgentStream>;
}

