// The drop path, tested as a BYTE STREAM rather than as opaque strings.
//
// `pendingPtyData.test.ts` pushed `"a"`, `"b"`, `"c"` and asserted on the joined result, so it could see
// that a chunk went missing and could not see that the *stream* had been corrupted — which is the only
// thing that actually mattered. Every assertion here is written against a stream of text INTERLEAVED
// WITH ESCAPE SEQUENCES, because that is what a PTY emits and what the old buffer silently broke.
import { describe, it, expect } from "vitest";
import { isAlreadyReplayed,
  dispositionWhileHidden,
  UnrecordedPtyText,
  TRUNCATION_NOTICE, replayReason, truncationNoticeFor } from "@/app/console/lib/terminalHandoff";

/** A state-setting sequence, then text — the shape whose FIRST half is what must never be lost. */
const DECAWM_OFF = "\x1b[?7l";
const SCROLL_REGION = "\x1b[1;24r";

describe("dispositionWhileHidden", () => {
  it("drops a RECORDED batch — the disk already holds it, verbatim and uncapped", () => {
    expect(dispositionWhileHidden({ data: DECAWM_OFF + "hello", upto: 512 })).toBe("drop");
  });

  it("holds an UNRECORDED batch — nothing else has a copy", () => {
    // `upto: null` is a session whose recording failed to open, or a notice the emitter generated
    // itself. A reveal cannot give either one back.
    expect(dispositionWhileHidden({ data: "\r\nsession ended\r\n", upto: null })).toBe("hold");
  });

  it("drops at offset 0 — a falsy offset is still an offset", () => {
    // `upto: 0` is a real recorded position (the very start of a stream). A truthiness check here
    // would hold the first batch of every session and start the buffer this design deletes.
    expect(dispositionWhileHidden({ data: "first", upto: 0 })).toBe("drop");
  });
});

describe("isAlreadyReplayed", () => {
  it("drops a batch the reveal has already covered", () => {
    expect(isAlreadyReplayed(400, 512)).toBe(true);
    expect(isAlreadyReplayed(512, 512)).toBe(true); // the boundary itself is inclusive: `text` ends AT it
  });

  it("keeps a batch past the reveal", () => {
    expect(isAlreadyReplayed(513, 512)).toBe(false);
  });

  it("never treats an UNRECORDED batch as a duplicate", () => {
    // No reveal can have replayed something that was never written down, so this must be written
    // however far the mark has advanced — including the cage-death notice, which arrives last.
    expect(isAlreadyReplayed(null, 999_999)).toBe(false);
  });

  it("writes everything before any reveal has happened", () => {
    // -1 rather than 0 is the initial mark for exactly this reason: offset 0 is replayable content.
    expect(isAlreadyReplayed(0, -1)).toBe(false);
  });
});

describe("UnrecordedPtyText — bounded WITHOUT dropping from the front", () => {
  it("returns what it was given, in order, when it fits", () => {
    const b = new UnrecordedPtyText(1024);
    b.push(DECAWM_OFF);
    b.push("one");
    b.push("two");
    expect(b.flush()).toBe(DECAWM_OFF + "onetwo");
  });

  it("is empty and silent when nothing was held", () => {
    const b = new UnrecordedPtyText(1024);
    expect(b.pending()).toBe(false);
    expect(b.flush()).toBe("");
  });

  // ── THE REGRESSION, stated as a byte stream ──
  //
  // The old buffer did `this.chunks.shift()` — dropping the OLDEST. Fed a state-setting sequence
  // followed by more output than the cap, it silently produced a stream that no longer contained the
  // state sequence, and everything xterm drew afterwards inherited the wrong state. That is the bug,
  // and it is invisible to any assertion that only counts bytes.
  it("never emits a stream whose leading state sequence was silently removed", () => {
    const cap = 64;
    const b = new UnrecordedPtyText(cap);
    b.push(SCROLL_REGION + DECAWM_OFF); // the state the rest of the stream depends on
    b.push("x".repeat(cap)); // …and enough after it to blow the cap

    const out = b.flush();

    // The old behaviour: `out` would begin with "xxxx…", the two sequences gone, and NOTHING would say
    // so. Either the state survives, or the output admits it does not — never a quiet third option.
    const stateSurvived = out.includes(SCROLL_REGION) && out.includes(DECAWM_OFF);
    expect(stateSurvived || out.startsWith(TRUNCATION_NOTICE)).toBe(true);
    // And here it is the second: a reset that redefines the state, not an inherited wrong one.
    expect(out.startsWith("\x1bc")).toBe(true);
  });

  it("says so when it truncated, even if nothing is left to write", () => {
    const b = new UnrecordedPtyText(8);
    b.push("y".repeat(8));
    b.push("z".repeat(8)); // overflows: the first push is discarded whole
    expect(b.pending()).toBe(true);
    expect(b.flush()).toBe(TRUNCATION_NOTICE + "z".repeat(8));
  });

  it("keeps the RECENT tail, not a stale prefix", () => {
    // Which end to keep is a real choice. A prefix would be non-corrupting too, but it leaves the user
    // staring at output from before the gap while the live stream resumes after it — the gap lands in
    // the middle, unannounced. Keeping the tail behind a reset puts the gap where it can be labelled.
    const b = new UnrecordedPtyText(16);
    b.push("old".repeat(5)); // 15 bytes
    b.push("NEWEST");
    expect(b.flush()).toBe(TRUNCATION_NOTICE + "NEWEST");
  });

  it("clears the truncation flag on flush, so one gap is reported once", () => {
    const b = new UnrecordedPtyText(8);
    b.push("a".repeat(8));
    b.push("b");
    b.flush();
    b.push("c");
    expect(b.flush()).toBe("c");
  });

  it("ignores an empty push rather than counting it as content", () => {
    const b = new UnrecordedPtyText(8);
    b.push("");
    expect(b.pending()).toBe(false);
  });
});

describe("replayReason", () => {
  it("asks for everything on a remount, which is what a reopened pane is", () => {
    // Closing a pane unmounts the component, so the reopen builds a FRESH handoff: writtenUpto -1 and
    // dropped false. Under the old `if (dropped)` rule that asked Rust for nothing and rendered an
    // empty terminal over a complete recording — the reported bug.
    expect(replayReason(-1, false)).toBe("remount");
    expect(replayReason(-1, true)).toBe("remount");
  });

  it("still asks when a hidden pane dropped recorded bytes", () => {
    expect(replayReason(4096, true)).toBe("dropped");
  });

  it("asks for nothing when the screen is already current", () => {
    expect(replayReason(0, false)).toBeNull();   // offset 0 is real content, not "nothing yet"
    expect(replayReason(4096, false)).toBeNull();
  });
});

describe("truncationNoticeFor", () => {
  it("stays SILENT on a fresh pane that simply has no history", () => {
    // The notice claims output was dropped. On a remount with nothing recorded that is a lie, and it
    // would fire on every fresh pane — which is most panes most of the time.
    expect(truncationNoticeFor("remount", false)).toBeNull();
    expect(truncationNoticeFor("remount", true)).toBeNull();
  });

  it("still admits the gap when bytes were dropped and cannot come back", () => {
    expect(truncationNoticeFor("dropped", false)).toBe(TRUNCATION_NOTICE);
  });

  it("says nothing when the reveal answered", () => {
    expect(truncationNoticeFor("dropped", true)).toBeNull();
  });
});

implementations.code:
// The hidden-pane handoff — what a pane does with PTY output it cannot render yet, and how it catches
// up when it can. Pure: no React, no xterm, no Tauri. `TerminalView` wires it to all three.
//
// ## What this replaces, and why the old answer was worse than no answer
//
// `PendingPtyData` buffered a hidden pane's output in RAM and, past 256 KB, dropped the OLDEST chunks:
//
//     while (this.bytes > this.maxBytes && this.chunks.length > 1) this.chunks.shift();
//
// PTY output is not lines. It is text INTERLEAVED WITH ANSI ESCAPE SEQUENCES, split wherever a `read()`
// happened to stop — frequently mid-sequence. Dropping from the FRONT of that does two things, and the
// second is the damaging one:
//
//   1. the flushed stream can BEGIN mid-sequence, so xterm misparses the remainder;
//   2. the sequences that establish STATE are silently lost — auto-wrap (DECAWM), scroll regions,
//      alt-screen enter/exit, character attributes, cursor addressing. Everything drawn afterwards
//      renders under the wrong terminal state, permanently.
//
// That is exactly the reported symptom: the newest ~20 lines correct (state re-established by later
// sequences) while older scrollback above sits in the wrong layout. And it was reached ROUTINELY, not in
// a corner — measured PTY throughput is 3-13 KB per 2s across all panes and #187 keeps every tab's panes
// mounted, so one busy hidden pane crossed 256 KB in well under a minute.
//
// ## The answer is that the bytes are already durable
//
// Rust records every byte of every session to disk as it reads them (`console::pty::scrollback`), with
// offsets recorded only where the stream is provably BETWEEN escape sequences. So a hidden pane does not
// need a second, lossy copy in the renderer's heap: it can drop what it cannot draw and ask for the
// history back at a SAFE BOUNDARY when it is shown. The buffer was defending memory against a problem
// the disk had already solved.
//
// What is left here is the small amount of reasoning that is genuinely the frontend's: which live batch
// a reveal has already covered, and what to do with the one kind of output disk cannot give back.

/** One batch of PTY output, as Rust emits it on `pty_data_<pane>`.
 *
 *  `upto` is the RECORDING offset the batch reaches. `null` means the batch is not in the recording at
 *  all — an older backend that still sends a bare string, a session whose recording failed to open, or
 *  a notice the emitter generated itself (the cage-death banner). That distinction is the whole basis of
 *  {@link dispositionWhileHidden}: a recorded batch is safe to throw away, an unrecorded one is not. */
export interface PtyChunk {
  data: string;
  upto: number | null;
}

/** What `pty_scrollback_reveal` hands back: the replay text, and the offset it ends at. */
export interface ScrollbackReveal {
  text: string;
  upto: number;
}

/**
 * Has the terminal already been given this batch?
 *
 * A reveal reads the recording up to its own offset while holding the emitter's cursor, so everything at
 * or below that number is on screen by the time the reply arrives. Tauri does NOT guarantee ordering
 * between an event and a command reply, so a batch emitted just before the lock can still be delivered
 * after the reveal returns — this is the check that closes that seam, not a belt-and-braces one.
 *
 * An unrecorded batch is never a duplicate: no reveal can have replayed something that was never
 * written down, so it is always written and never advances the mark.
 */
export function isAlreadyReplayed(upto: number | null, writtenUpto: number): boolean {
  return upto !== null && upto <= writtenUpto;
}

/** What to do with a batch that arrives while the pane cannot render it. */
export type HiddenDisposition = "drop" | "hold";

/**
 * Drop a batch the recording already owns; hold one it does not.
 *
 * DROPPING IS THE POINT. The bytes are on disk, verbatim and uncapped, and a reveal will replay them
 * from a boundary the recorder verified — which is strictly more than the old buffer could offer even
 * before it started corrupting them. Holding a recorded batch would rebuild the very copy this exists to
 * delete.
 *
 * "hold" is reached only when nothing is recording this pane, so there is no other copy to fall back on.
 */
export function dispositionWhileHidden(chunk: PtyChunk): HiddenDisposition {
  return chunk.upto === null ? "hold" : "drop";
}

/** Why a terminal is asking Rust for its recorded history.
 *
 *  The two reasons are NOT interchangeable, and conflating them is what would put a false warning in
 *  front of every fresh pane (see {@link truncationNoticeFor}).
 *
 *  - `"remount"` — this terminal has been given NOTHING. Closing a pane unmounts the component, so
 *    reopening it builds a fresh handoff and a fresh xterm with an empty buffer while the complete
 *    recording sits on disk. It needs everything, and it has lost nothing.
 *  - `"dropped"` — a HIDDEN pane let recorded bytes go rather than keeping a second copy in the
 *    renderer's heap, and now needs them back. Something really is missing until the reveal lands. */
export type ReplayReason = "remount" | "dropped";

/** Does this terminal need Rust to replay its history, and why? `null` when the screen is current.
 *
 *  DRIVEN BY WHAT THE TERMINAL HAS BEEN GIVEN, never by a flag that a close destroys. `writtenUpto` is
 *  `-1` on a fresh handoff and is only ever set from a batch or a reveal, so "below zero" is exactly
 *  "this terminal has been shown nothing" — which is true on a reopen regardless of what came before.
 *
 *  The rule used to be `if (dropped)` alone. A reopened pane has `dropped === false`, because the ref
 *  holding it died with the component — so it asked Rust for nothing and rendered an empty terminal
 *  over a full recording. That is the bug this exists to remove. */
export function replayReason(writtenUpto: number, dropped: boolean): ReplayReason | null {
  if (writtenUpto < 0) return "remount";
  return dropped ? "dropped" : null;
}

/** What to write when a reveal comes back empty — `null` meaning write nothing at all.
 *
 *  A `null` reveal means Rust has no cursor or no readable recording for this pane. What that MEANS
 *  depends entirely on why it was asked:
 *
 *  - after `"dropped"` it is the real, unrecoverable case: bytes went and cannot come back, and a pane
 *    that quietly resumes mid-stream is worse than one that admits the gap.
 *  - after `"remount"` it means the pane simply has no history yet — a session that just started, or
 *    one that ran before recording existed. Announcing dropped output there would be a plain lie, and
 *    it would fire on EVERY fresh pane, which is most panes most of the time. */
export function truncationNoticeFor(reason: ReplayReason, revealed: boolean): string | null {
  if (revealed || reason === "remount") return null;
  return TRUNCATION_NOTICE;
}

/** A full reset (RIS) plus a line saying output was lost. See {@link UnrecordedPtyText}. */
export const TRUNCATION_NOTICE =
  "\x1bc\r\n\x1b[2m…earlier output was dropped: this session is not being recorded…\x1b[0m\r\n";

/**
 * The bounded hold for output that is NOT in the recording — the only case disk cannot answer.
 *
 * In practice this holds a handful of emitter-generated notices and nothing else. It fills up only when a
 * session's recording failed to open, and then it is the sole copy of that session's output, so it must
 * stay bounded.
 *
 * WHEN IT OVERFLOWS IT DOES NOT DROP FROM THE FRONT, which is the entire lesson of the bug above. It
 * discards what it holds and starts again, and {@link flush} then prefixes {@link TRUNCATION_NOTICE} —
 * a RIS, which puts the terminal into a DEFINED state rather than an inherited-and-wrong one, followed
 * by a line admitting the gap.
 *
 * The honest residue, stated rather than glossed: the retained tail begins at whatever chunk edge the
 * discard fell on, so its first bytes may be the middle of one escape sequence and garble a single
 * fragment. That is bounded to one fragment because the RIS in front of it re-establishes state.
 * Dropping from the front had no such bound — it lost the state sequences themselves, and every line
 * drawn afterwards inherited the mistake.
 */
export class UnrecordedPtyText {
  private chunks: string[] = [];
  private bytes = 0;
  private truncated = false;

  constructor(private readonly maxBytes: number) {}

  push(s: string): void {
    if (s.length === 0) return;
    if (this.bytes + s.length > this.maxBytes) {
      // Start over rather than shift() — see the class doc. Losing the tail we were holding is a
      // visible gap; losing the front of it is an invisible corruption.
      this.chunks = [];
      this.bytes = 0;
      this.truncated = true;
    }
    this.chunks.push(s);
    this.bytes += s.length;
  }

  /** Everything held, as one string, and clear. `""` when nothing is held AND nothing was lost. */
  flush(): string {
    const body = this.chunks.join("");
    const out = this.truncated ? TRUNCATION_NOTICE + body : body;
    this.chunks = [];
    this.bytes = 0;
    this.truncated = false;
    return out;
  }

  /** Whether a flush would write anything. A truncation is worth writing even with nothing held. */
  pending(): boolean {
    return this.bytes > 0 || this.truncated;
  }
}

