// The pyramid's INVARIANTS and its complexity. The whole claim of this slice is "the drawn count stops
// referencing n", and that is a property, not an anecdote — so it is asserted across graph sizes an
// order of magnitude apart rather than measured once.
import { describe, it, expect } from "vitest";
import { buildPyramid, levelFor, MIN_SEPARATION_PX, type LodPyramid } from "@/shared/lib/graph/lodPyramid";

function rng(seed: number): () => number {
  let s = seed >>> 0;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
}

function uniform(n: number, extent: number, seed = 1): Float32Array {
  const r = rng(seed);
  const xy = new Float32Array(n * 2);
  for (let i = 0; i < n * 2; i++) xy[i] = r() * extent;
  return xy;
}

/** Total aggregates a viewport of `vpW`x`vpH` px would draw at this scale. */
function drawnInViewport(p: LodPyramid, scale: number, vpW: number, vpH: number): number {
  const k = levelFor(p, scale);
  const lv = p.levels[k];
  // World rect the viewport covers, centred on the data's own middle so the sample is representative.
  const w = vpW / scale, h = vpH / scale;
  let cx = 0, cy = 0;
  for (let i = 0; i < lv.n; i++) { cx += lv.xy[i * 2]; cy += lv.xy[i * 2 + 1]; }
  cx /= Math.max(1, lv.n); cy /= Math.max(1, lv.n);
  const x0 = cx - w / 2, y0 = cy - h / 2;
  let seen = 0;
  for (let i = 0; i < lv.n; i++) {
    const x = lv.xy[i * 2], y = lv.xy[i * 2 + 1];
    if (x >= x0 && x <= x0 + w && y >= y0 && y <= y0 + h) seen++;
  }
  return seen;
}

describe("buildPyramid", () => {
  it("is TRANSPARENT at level 0 — the original nodes, unchanged", () => {
    // If the pyramid altered what you see when zoomed in, it would be a rendering change disguised as
    // an optimization.
    const xy = uniform(500, 400, 3);
    const p = buildPyramid(xy, 500);
    expect(p.levels[0].n).toBe(500);
    expect([...p.levels[0].xy]).toEqual([...xy]);
    expect([...p.levels[0].count].every((c) => c === 1)).toBe(true);
  });

  it("shrinks geometrically, and the WHOLE pyramid costs a small multiple of n", () => {
    const n = 50_000;
    const p = buildPyramid(uniform(n, 2000, 5), n);
    expect(p.levels.length).toBeGreaterThan(2);
    for (let k = 1; k < p.levels.length; k++) {
      expect(p.levels[k].n, `level ${k} must be smaller than ${k - 1}`).toBeLessThan(p.levels[k - 1].n);
    }
    const total = p.levels.reduce((s, l) => s + l.n, 0);
    // 1 + 1/4 + 1/16 + … converges below 4n/3; allow slack for boundary cells, but a pyramid costing
    // several times n would mean the levels are not really collapsing.
    expect(total).toBeLessThan(n * 2);
  });

  it("represents EVERY original node exactly once at every level", () => {
    // The counts are what an aggregate means. If they did not sum to n, the aggregate would be claiming
    // to stand for a population it does not have — and nothing on screen would reveal it.
    const n = 4000;
    const p = buildPyramid(uniform(n, 900, 7), n);
    for (const lv of p.levels) {
      const sum = [...lv.count].reduce((a, b) => a + b, 0);
      expect(sum, `level with ${lv.n} aggregates`).toBe(n);
    }
  });

  it("places every aggregate inside the bounds of what it represents", () => {
    const n = 3000;
    const xy = uniform(n, 600, 11);
    const p = buildPyramid(xy, n);
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let i = 0; i < n; i++) {
      minX = Math.min(minX, xy[i * 2]); maxX = Math.max(maxX, xy[i * 2]);
      minY = Math.min(minY, xy[i * 2 + 1]); maxY = Math.max(maxY, xy[i * 2 + 1]);
    }
    for (const lv of p.levels) {
      for (let i = 0; i < lv.n; i++) {
        expect(lv.xy[i * 2]).toBeGreaterThanOrEqual(minX - 1e-3);
        expect(lv.xy[i * 2]).toBeLessThanOrEqual(maxX + 1e-3);
        expect(lv.xy[i * 2 + 1]).toBeGreaterThanOrEqual(minY - 1e-3);
        expect(lv.xy[i * 2 + 1]).toBeLessThanOrEqual(maxY + 1e-3);
      }
    }
  });

  it("weights the centroid by population, so it does not drift with the pyramid's own shape", () => {
    // Three nodes in one cell and one in the next: the coarse aggregate of both must sit nearer the
    // heavy side. An unweighted mean of the two sub-aggregates would put it in the middle.
    const xy = new Float32Array([0, 0, 1, 0, 2, 0, 100, 0]);
    const p = buildPyramid(xy, 4, 4);
    const top = p.levels[p.levels.length - 1];
    if (top.n === 1) {
      expect(top.count[0]).toBe(4);
      expect(top.xy[0]).toBeCloseTo((0 + 1 + 2 + 100) / 4, 3);
    }
  });

  it("survives an empty graph and a single node", () => {
    expect(buildPyramid(new Float32Array(0), 0).levels[0].n).toBe(0);
    const one = buildPyramid(new Float32Array([5, 5]), 1);
    expect(one.levels[0].n).toBe(1);
    expect(levelFor(one, 1)).toBe(0);
  });

  it("does not spin on a degenerate extent", () => {
    // Every node at one point: no cell size ever reduces the population, so it must stop rather than
    // double the cell forever.
    const p = buildPyramid(new Float32Array(2000).fill(3), 1000);
    expect(p.levels.length).toBeLessThan(26);
  });
});

describe("levelFor", () => {
  it("is MONOTONIC in zoom — zooming out never selects a finer level", () => {
    // A non-monotonic selector flickers between levels as you zoom, which reads as the graph glitching.
    const p = buildPyramid(uniform(20_000, 1500, 13), 20_000);
    let prev = -1;
    for (const scale of [8, 4, 2, 1, 0.5, 0.25, 0.1, 0.05, 0.02, 0.01, 0.004]) {
      const k = levelFor(p, scale);
      expect(k, `scale ${scale} after ${prev}`).toBeGreaterThanOrEqual(prev === -1 ? 0 : prev);
      prev = k;
    }
  });

  it("returns level 0 when zoomed in — full detail is what a close view is for", () => {
    const p = buildPyramid(uniform(5000, 800, 17), 5000);
    expect(levelFor(p, 1000)).toBe(0);
  });

  it("keeps the selected level's separation at or above the legibility floor while one exists", () => {
    const p = buildPyramid(uniform(20_000, 1500, 19), 20_000);
    for (const scale of [2, 1, 0.4, 0.1, 0.03]) {
      const k = levelFor(p, scale);
      if (k > 0 && k < p.levels.length - 1) {
        expect(p.levels[k].cellSize * scale).toBeGreaterThanOrEqual(MIN_SEPARATION_PX);
      }
    }
  });
});

describe("the whole point", () => {
  it("bounds the DRAWN count by viewport, not by graph size", () => {
    // THE EXTENT IS FIXED AND ONLY THE DENSITY CHANGES, which is the only way this property is even
    // observable. An earlier version of this test grew the extent with n (constant density) and failed
    // reporting 2,508 against 25,150 — correctly, because at that zoom the viewport contained BOTH
    // graphs whole, so there was nothing to cull and drawing everything was the right answer. The claim
    // is not "two graphs always draw the same"; it is "the drawn count is bounded by what the viewport
    // can RESOLVE", and that only bites once the nodes outnumber the resolvable cells.
    const vp = [1600, 900] as const;
    const EXTENT = 20_000;
    const mk = (n: number) => buildPyramid(uniform(n, EXTENT, 23), n);
    const sparse = mk(20_000);
    const dense = mk(200_000);
    for (const scale of [0.05, 0.02, 0.01]) {
      const a = drawnInViewport(sparse, scale, vp[0], vp[1]);
      const b = drawnInViewport(dense, scale, vp[0], vp[1]);
      // 10x the nodes in the SAME space. The selected level's cell size is an absolute world size, so
      // both collapse to roughly the same number of cells over the same area — the drawn count tracks
      // the AREA, not n.
      expect(b, `scale ${scale}: sparse(20k) drew ${a}, dense(200k) drew ${b}`).toBeLessThan(a * 3 + 400);
      // And the absolute bound: viewport area divided by the separation floor.
      const cap = (vp[0] * vp[1]) / (MIN_SEPARATION_PX * MIN_SEPARATION_PX);
      expect(b, `scale ${scale}: drawn must stay under the viewport's resolvable cells (${cap})`).toBeLessThan(cap);
    }
  });

  it("builds a 1,000,000-node pyramid in well under a second", () => {
    const n = 1_000_000;
    const t = performance.now();
    const p = buildPyramid(uniform(n, 30_000, 29), n);
    const ms = performance.now() - t;
    expect(p.levels[0].n).toBe(n);
    expect(p.levels.length).toBeGreaterThan(3);
    // O(n) with a small constant. A per-node string key — the obvious way to bucket — would blow this.
    expect(ms, `built in ${ms.toFixed(0)}ms`).toBeLessThan(4000);
  });
});

implementations.code:
// A mipmap over SPACE — the structure that makes frame cost stop referencing the node count
// (`gpu-graph-slice-4-lod-pyramid`).
//
// WHY THIS IS STILL NEEDED WHEN A MILLION NODES ALREADY DRAW IN 1.55 ms. Measured in this app's own
// webview, node quads scale fine and EDGES do not — they are fill-bound: 5M wide quads 13.2 ms, 10M
// 22.2 ms (over a 16.7 ms budget), 20M 37.6 ms. A million nodes usually means 2-10M edges, so the edge
// pass is already the ceiling and at 10M+ nodes the node pass joins it. Drawing faster cannot fix that;
// not drawing the invisible can.
//
// AND IT IS NOT ONLY ABOUT SPEED. A million nodes at overview zoom is a grey rectangle — every node is
// sub-pixel and every edge overlaps everything. The aggregate is the more HONEST picture at that scale,
// so the level the user should be looking at is the one that is also cheap.
//
// THE SHAPE. Level 0 is the nodes. Level k aggregates them into grid cells of `base * 2^k`, and each
// non-empty cell becomes one node at its members' centroid carrying how many it stands for. Each level
// is built from the one below, over a population that shrinks geometrically, so the whole pyramid is
// O(n) — not O(n log n), because the work per level falls off faster than the level count rises.
//
// EDGES ARE DROPPED ABOVE A LEVEL, NOT AGGREGATED. Aggregating them means mapping every edge onto its
// endpoints' clusters and deduping — O(E) per level with a hash — to produce a hairball nobody can read.
// Dropping is cheaper AND more legible: the aggregates already carry the density the edges conveyed.
//
// PURE. Numbers in, numbers out — which is what lets "the drawn count does not grow with n" be an
// assertion rather than a hope.

/** One level of the pyramid. `xy` is interleaved centroids; `count[i]` is how many level-0 nodes it stands for. */
export interface LodLevel {
  /** Interleaved `[x,y]` per aggregate. */
  xy: Float32Array;
  /** How many original nodes each aggregate represents. 1 at level 0. */
  count: Uint32Array;
  /** Number of aggregates. */
  n: number;
  /** World units per grid cell at this level — `base * 2^k`. */
  cellSize: number;
}

export interface LodPyramid {
  levels: LodLevel[];
  /** Cell size of level 1; level k is `base * 2^(k-1)`. Level 0 is the raw nodes. */
  base: number;
  minX: number;
  minY: number;
}

/**
 * Stop building once a level is this small.
 *
 * Below it the aggregates are fewer than a screen could usefully show and each further level halves
 * almost nothing, so the remaining levels cost storage and buy no reduction.
 */
const MIN_LEVEL_NODES = 64;

/** Hard cap on levels, so a degenerate extent cannot spin. */
const MAX_LEVELS = 24;

/**
 * Build the pyramid — `O(n)` total.
 *
 * Level k+1 is built from level k, and each level has at most a quarter of the previous one's
 * aggregates once the cell size doubles in both axes, so the total work is `n * (1 + 1/4 + 1/16 + …)`,
 * which converges below `4n/3`. Storage converges the same way, which is why the whole pyramid costs a
 * small multiple of the original rather than a multiple of the level count.
 *
 * `base` defaults to the spacing that puts ~2 nodes in a level-1 cell, matching `buildGrid`'s density
 * target so the two structures agree about what "close" means.
 */
export function buildPyramid(xy: Float32Array, count: number, base?: number): LodPyramid {
  const n = Math.max(0, Math.min(count, xy.length >> 1));
  const level0: LodLevel = {
    xy: xy.subarray(0, n * 2),
    count: (() => { const c = new Uint32Array(n); c.fill(1); return c; })(),
    n,
    cellSize: 0,
  };
  if (n === 0) return { levels: [level0], base: 1, minX: 0, minY: 0 };

  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let i = 0; i < n; i++) {
    const x = xy[i * 2], y = xy[i * 2 + 1];
    if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  if (!Number.isFinite(minX)) { minX = 0; minY = 0; maxX = 0; maxY = 0; }
  const area = Math.max(maxX - minX, 0) * Math.max(maxY - minY, 0);
  let cell = base ?? (area > 0 ? Math.sqrt((area * 2) / n) : 1);
  if (!Number.isFinite(cell) || cell <= 0) cell = 1;

  const levels: LodLevel[] = [level0];
  let src = level0;
  for (let k = 0; k < MAX_LEVELS && src.n > MIN_LEVEL_NODES; k++) {
    const next = aggregate(src, cell, minX, minY);
    // No reduction means the extent is degenerate for this cell size — doubling again would loop
    // without shrinking, so stop rather than spin.
    if (next.n >= src.n) break;
    levels.push(next);
    src = next;
    cell *= 2;
  }
  return { levels, base: base ?? levels[1]?.cellSize ?? 1, minX, minY };
}

/**
 * Collapse a level into grid cells of `cell`, one aggregate per non-empty cell — `O(m)` for `m` inputs.
 *
 * Centroid is WEIGHTED by each input's own count, so an aggregate always sits at the centre of mass of
 * the original nodes beneath it rather than drifting toward whichever branch happened to have more
 * aggregates. Without the weight the position would depend on the pyramid's own shape, not the data's.
 */
function aggregate(src: LodLevel, cell: number, minX: number, minY: number): LodLevel {
  const buckets = new Map<number, number>(); // cell key -> index into the output
  const sx: number[] = [];
  const sy: number[] = [];
  const cnt: number[] = [];
  for (let i = 0; i < src.n; i++) {
    const x = src.xy[i * 2], y = src.xy[i * 2 + 1];
    const cx = Math.floor((x - minX) / cell);
    const cy = Math.floor((y - minY) / cell);
    // Packed into one number rather than a string key: a string key here allocates once per input node,
    // which at a million nodes is the dominant cost of the whole build.
    const key = cx * 4294967296 + cy;
    let at = buckets.get(key);
    if (at === undefined) {
      at = sx.length;
      buckets.set(key, at);
      sx.push(0); sy.push(0); cnt.push(0);
    }
    const w = src.count[i];
    sx[at] += x * w;
    sy[at] += y * w;
    cnt[at] += w;
  }
  const m = sx.length;
  const out = new Float32Array(m * 2);
  const oc = new Uint32Array(m);
  for (let i = 0; i < m; i++) {
    out[i * 2] = sx[i] / cnt[i];
    out[i * 2 + 1] = sy[i] / cnt[i];
    oc[i] = cnt[i];
  }
  return { xy: out, count: oc, n: m, cellSize: cell };
}

/**
 * Minimum on-screen separation, in px, that a drawn aggregate must have from its neighbours.
 *
 * This is the knob that converts "how zoomed out am I" into "how much may I draw", and it is a
 * LEGIBILITY threshold like the label gate: below a few px, adjacent nodes are the same pixel and
 * drawing both is paying twice for one dot.
 */
export const MIN_SEPARATION_PX = 4;

/**
 * Which level to draw at this zoom — `O(1)`.
 *
 * Picks the coarsest level whose cell still covers at least `MIN_SEPARATION_PX` on screen, so the drawn
 * population is bounded by viewport area divided by that separation — independent of how many nodes
 * exist. Monotonic in `scale` by construction: a smaller scale can only select an equal or coarser
 * level, which is what stops the view from flickering between levels as you zoom.
 */
export function levelFor(p: LodPyramid, scale: number): number {
  if (p.levels.length <= 1 || !(scale > 0)) return 0;
  for (let k = 0; k < p.levels.length; k++) {
    // Level 0 has no cell of its own; its natural spacing is finer than a level-1 cell, and `base` was
    // chosen for ~2 nodes per level-1 cell, so half of it is the honest estimate.
    const sep = k === 0 ? p.base / 2 : p.levels[k].cellSize;
    if (sep * scale >= MIN_SEPARATION_PX) return k;
  }
  // Zoomed out past even the coarsest level — draw that, which is the fewest aggregates there are.
  return p.levels.length - 1;
}

// The Credentials workspace — the window onto the credential store (`bsc secret`).
//
// It answers one question the app previously could not answer at all: WHICH services are we paired
// with, and are any of those pairings broken? The OS keychain has no listing, so before this store
// existed a credential that had quietly expired was indistinguishable from one that worked, right up
// until an agent's call failed in the middle of a task.
//
// What it deliberately does NOT do: show, reveal, copy or edit a secret value. There is no verb on
// `bsc secret` that returns one, so there is nothing here to render even by accident — the page reads
// metadata and a derived status, and that is the whole of what it can reach.
//
// The status is NOT computed here. `crates/bsc-secret` derives it, because only the backend can see
// the keychain — which is what decides `missing`. Re-deriving it in the frontend would be a second
// implementation of the same rule, free to drift from the first.
import { useCallback, useEffect, useMemo, useState } from "react";
import { KeyRound, RefreshCw } from "lucide-react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { bsc } from "@/shared/lib/core/bsc";
import { ServiceGlyph } from "@/features/credentials/serviceGlyphs";
import {
  parseCredentials, sortCredentials, summarize, displayName,
  relativeAge, expiryLabel, STATUS_META, type Credential, type CredentialStatus,
} from "@/features/credentials/lib/credentials";

/** The command that registers a credential — shown in the empty state and the footer, because a
 *  screen that reports an empty store without saying how to fill it is a dead end. */
const REGISTER_CMD = `echo '{"id":"github-acme","service":"github","label":"GitHub"}' | bsc secret set`;

function StatusPill({ status }: { status: CredentialStatus }) {
  const meta = STATUS_META[status];
  // The tone rides a data attribute rather than the class name, so the CSS has one rule per tone
  // instead of one per status. More importantly the status is rendered as TEXT: colour alone would
  // make the entire content of this screen invisible to anyone who cannot tell the tones apart.
  return (
    <Text as="span" className="cred-pill" data-tone={meta.tone} title={meta.hint}>
      {meta.label}
    </Text>
  );
}

function CredentialRow({ credential, now }: { credential: Credential; now: number }) {
  const meta = STATUS_META[credential.status];
  const expiry = expiryLabel(credential.expiresAt, now);
  // Assembled from whatever the record actually has — every field but the id is optional, so a
  // sparse record renders a short line rather than a line full of "unknown".
  const details = [
    credential.service,
    credential.kind,
    credential.account,
    expiry,
    `checked ${relativeAge(credential.lastVerifiedAt, now)}`,
  ].filter((d): d is string => !!d && d.trim().length > 0);

  return (
    <li className="cred-row" data-tone={meta.tone}>
      <Text as="span" className="cred-glyph" aria-hidden="true">
        <ServiceGlyph service={credential.service} />
      </Text>
      <Stack gap={2} className="cred-body">
        <Text as="span" className="cred-name">{displayName(credential)}</Text>
        <Text as="span" mono className="cred-details">{details.join(" · ")}</Text>
        {/* The reason, when there is one. A red pill with no explanation makes the user go and
            reproduce the failure themselves to find out what it was. */}
        {credential.status === "failing" && credential.lastError && (
          <Text as="span" mono className="cred-reason">{credential.lastError}</Text>
        )}
        {credential.status === "missing" && (
          <Text as="span" mono className="cred-reason">{meta.hint}</Text>
        )}
      </Stack>
      <StatusPill status={credential.status} />
    </li>
  );
}

/** The Credentials rail Workspace. */
export function CredentialsWorkspace() {
  const [credentials, setCredentials] = useState<Credential[]>([]);
  const [error, setError] = useState<string | null>(null);
  // `loaded` rather than `loading`: the empty state and the still-fetching state look identical
  // otherwise, and flashing "no credentials" before the first response lands reads as data loss.
  const [loaded, setLoaded] = useState(false);
  const [now, setNow] = useState(() => Math.floor(Date.now() / 1000));

  const load = useCallback(async () => {
    try {
      // The credential store is GLOBAL, not per-project — a GitHub token is not owned by whichever
      // project happens to be open — so the bridge's project key is null, as it is for `bsc skill`.
      const raw = await bsc(null, ["secret", "list"]);
      // Every setState below happens AFTER the await. A synchronous one would run during the
      // effect's own pass, which is what `react-hooks/set-state-in-effect` exists to prevent.
      setCredentials(parseCredentials(raw));
      setNow(Math.floor(Date.now() / 1000));
      setError(null);
    } catch (e) {
      // Surfaced, never swallowed into an empty list: "the store could not be read" and "the store
      // is empty" are opposite facts, and this screen exists to say truthfully which one holds.
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoaded(true);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const rows = useMemo(() => sortCredentials(credentials), [credentials]);
  const summary = useMemo(() => summarize(credentials), [credentials]);

  return (
    <Stack gap="md" className="cred-screen">
      <Row align="start" justify="between" gap="md" wrap className="cred-head">
        <Stack gap={0}>
          <h2 className="cred-title">Credentials</h2>
          <p className="cred-sub">
            The services this app is paired with. Values live in the OS keychain and are never shown
            here, or to an agent session.
          </p>
        </Stack>
        <Row align="center" gap="sm" className="cred-head-right">
          {loaded && !error && (
            <Text as="span" mono className="cred-count" data-attention={summary.attention > 0}>
              {summary.attention > 0
                ? `${summary.attention} of ${summary.total} need attention`
                : `${summary.total} credential${summary.total === 1 ? "" : "s"}`}
            </Text>
          )}
          <Button size="sm" className="cred-refresh" onClick={() => void load()} title="Re-read the credential store">
            <RefreshCw size={14} />
            Refresh
          </Button>
        </Row>
      </Row>

      {error && (
        <Stack gap="xs" className="cred-error" role="alert">
          <strong>The credential store could not be read.</strong>
          <Text as="span" mono>{error}</Text>
        </Stack>
      )}

      {!error && loaded && rows.length === 0 && (
        <EmptyState
          icon={<KeyRound size={20} />}
          title="No credentials registered"
          description="Register one to pair this app with a service. The value goes into the OS keychain separately, so it never enters the store — or an agent's context."
          extra={<code className="mono cred-cmd">{REGISTER_CMD}</code>}
        />
      )}

      {!error && rows.length > 0 && (
        <Box as="ul" className="cred-list">
          {rows.map((c) => (
            <CredentialRow key={c.id} credential={c} now={now} />
          ))}
        </Box>
      )}

      {!error && rows.length > 0 && (
        <p className="cred-foot hint">
          Add one with <code className="mono">bsc secret set</code>, store its value with{" "}
          <code className="mono">bsc secret put &lt;id&gt;</code>.
        </p>
      )}
    </Stack>
  );
}

// Session-behavior domain — denied shell commands + the console-behavior toggles (auto-focus,
// auto-resume, gate overrides, default/per-pane model, fleet harness). Split from store/types (#1634).
import type { ConsoleAutoFocusMode } from "@/app/console/lib/focusQueue";
import type { ModelId } from "@/app/console/panes/PaneMenu";
import type { SessionModel } from "@/app/console/lib/models";
import type { StudioTarget } from "@/shared/lib/fleet/studioNetworkDrive";
import type { RequestNodeSpec } from "@/features/teams";
import type { SurfaceRow } from "@/shared/lib/session/surfaceCatalog";

/** Session-behavior slice of {@link AppStore}. */
export interface SessionState {
  // Blocked shell commands. Sessions allow Bash broadly (start-and-go); the
  // backend always denies a curated dangerous set, and these are the user's
  // additional global denies. Deny wins
  // over allow.
  deniedCommands: string[];
  addDeniedCommand: (cmd: string) => void;
  removeDeniedCommand: (cmd: string) => void;
  setDeniedCommands: (commands: string[]) => void;

  /**
   * The `bsc` command-surface catalog, as `bsc surface list --json` reports it
   * (`a-persona-declares-its-command-surfaces`).
   *
   * Held in the store because TWO consumers need the same catalog and neither may restate it: the
   * session launch complements it against each persona's declared set to build that session's denies
   * (`sessionDeniedCommands`), and the Glance drill draws the band from it. `bsc surface help` says
   * the role join belongs at the consumer, and a second reader would be the fourth hand-kept copy of
   * this set — three plan items already exist for earlier ones drifting.
   *
   * THE ROWS ARE STORED WHOLE — `status` included — because the two consumers filter DIFFERENTLY, and
   * collapsing them to one pre-filtered name list is a bypass rather than a simplification. The band
   * draws ACTIVE only (a deprecated alias and its live surface are one store, so two nodes overstate
   * it); the gate denies active AND deprecated (`bsc org` reaches the store `bsc teams` serves, so an
   * un-denied alias is a side door into a store the declaration removed). See `activeSurfaceNames` /
   * `deniableSurfaceNames`.
   *
   * EMPTY UNTIL THE FIRST READ RESOLVES, and every consumer must treat empty as "unknown" rather than
   * "there are none": the complement fails open on it, deliberately, because a launch that raced the
   * catalog read must not deny a session its whole CLI. Not persisted — it describes the binary on
   * this machine right now, and a stale copy restored from disk would be worse than no copy.
   */
  surfaceCatalog: SurfaceRow[];
  setSurfaceCatalog: (surfaces: SurfaceRow[]) => void;

  // Console behavior
  // Selectable auto-focus mode (#434): controls whether and when focus advances
  // after you reply. Persisted; configured in Settings → Integrations.
  // Replaces the old boolean; autoAdvanceOnReply is kept for Console.tsx back-compat.
  autoFocusMode: ConsoleAutoFocusMode;
  setAutoFocusMode: (mode: ConsoleAutoFocusMode) => void;
  // Back-compat derived field: true when autoFocusMode is not "off".
  autoAdvanceOnReply: boolean;
  setAutoAdvanceOnReply: (v: boolean) => void;
  // When true, panes that had claude running at last shutdown auto-relaunch
  // it with --continue on next mount (persisted; configured in Settings →
  // Integrations). Gated per pane by paneWasClaude — off by default for
  // panes that never used claude (#36).
  autoResumeClaude: boolean;
  /** #1107: hard-gate plan publishing on detected prompt-injection markers. ON ⇒ a flagged plan
   *  cannot publish until the marker is removed; OFF (default) ⇒ acknowledge-to-clear. */
  injectionHardGate: boolean;
  setInjectionHardGate: (v: boolean) => void;
  /** Permission posture (#1916): true ⇒ agents (and manual consoles) auto-run and the PreToolUse hooks
   *  do the gating (the deny-list); false ⇒ Claude's `default` mode enforces the enumerated allow-list
   *  (require approval). Default true. Threaded to `write_session_settings` via `buildSessionSettings`. */
  bypassPermissions: boolean;
  setBypassPermissions: (v: boolean) => void;
  /** #1988: launch console panes INSIDE the sealed WSL2 sandbox distro (`bsc-agent-sandbox`) — a clean
   *  bash at the distro home. Opt-in; off by default. Your Windows repos aren't mounted in (the seal),
   *  so it's a scratch/verification shell until project files are relocated into the distro. */
  sandboxConsoles: boolean;
  setSandboxConsoles: (v: boolean) => void;
  // BOTH DEBUG TOGGLES ARE GONE (#debug-nodes-hang-off-the-session-that-filed-them).
  //
  // `debugSession` gated the standing `debugger` node, and that node is gone with it — a stand-in
  // earns its place by showing an element that exists but is not yet active, and every request now
  // draws its own labelled node instead.
  //
  // `autoSpawnDebugSessions` gated the per-request sessions, off by default, which shipped the whole
  // 1:1 request→session machinery switched off. A filed request is worked now. The remaining gate is
  // NOT a preference: `debug_repo_root` must resolve, because a shipped binary with no source tree
  // cannot run these at all.
  /** #3498: the requests that currently have a spawned debug session. Lives in the STORE, not in the
   *  mount's local state, because the Glance graph must render a node per live session — a session that
   *  appears nowhere is one the user cannot open, supervise or stop. Session-only.
   *
   *  Carries each request's ORIGIN and TITLE, not just its id
   *  (#debug-nodes-hang-off-the-session-that-filed-them): the node is labelled `debug - <title>` and
   *  edged to the session that FILED it, and a bare id can express neither. (The old name said "slots"
   *  — pool slot indices, #3535 — which it had already stopped holding when assignment replaced the
   *  pool; a field whose name contradicts its doc comment is one nobody can reason about.) */
  activeDebugRequests: RequestNodeSpec[];
  setActiveDebugRequests: (requests: RequestNodeSpec[]) => void;
  /** #3509: the base-studio-code source tree this app was built from, or null on a shipped binary.
   *  Resolved ONCE at boot so a launch can turn a role's symbolic `app-repo` harvest root into a real
   *  path synchronously. Session-only — it is a property of the machine, not of the user's state. */
  appRepoRoot: string | null;
  setAppRepoRoot: (p: string | null) => void;
  /** #2940 (studio network): the app-owned studio sessions the pump currently wants reachable —
   *  targets ("designer"/"librarian") with at least one open commission. Written by
   *  `useStudioNetworkPump` each tick; read by ConsoleWorkspace's lazy-mount hosts, which launch the
   *  target session on demand and tear it down when the list empties. SESSION-ONLY (not persisted). */
  activeStudioTargets: StudioTarget[];
  setActiveStudioTargets: (t: StudioTarget[]) => void;
  /** #199: auto-relaunch a parked pane when its deps land (opt-in; off by default). */
  coordAutoWake: boolean;
  setCoordAutoWake: (v: boolean) => void;
  setAutoResumeClaude: (v: boolean) => void;
  /** #682: let Claude auto-drive the planning phase from a pitch (opt-in; off by default).
   *  Enables the "Auto-plan" control on the planner page. */
  autoPlanWithClaude: boolean;
  setAutoPlanWithClaude: (v: boolean) => void;
  /** #1068: auto-advance planner gates — when a stage's sections are ready, confirm them without
   *  the manual "approve & continue" click (opt-in; off by default). One global flag every gate
   *  follows; steps aside while the planning autopilot is running (it owns confirmation then). */
  autoCompleteGates: boolean;
  setAutoCompleteGates: (v: boolean) => void;
  /** Allow the user to override a blocking planner stage gate and advance anyway (#1285). Off by
   *  default; surfaces a cautionary "override gate & continue" action in the planner footer. */
  allowGateOverride: boolean;
  setAllowGateOverride: (v: boolean) => void;
  /** #738 (security): restrict agents that pull live GitHub issues (triage) to issues
   *  base-studio-code authored — the `bsc-generated` label. ON by default so a hand-created
   *  or injected issue isn't acted on; off works every open issue. */
  restrictToBscIssues: boolean;
  setRestrictToBscIssues: (v: boolean) => void;
  /** Default Claude model new console panes open with (persisted; configured in
   *  Settings → General). Per-pane override lives in the pane hamburger menu. */
  defaultModel: ModelId;
  setDefaultModel: (m: ModelId) => void;
  /** Which harness the agent fleet launches on (#1078 P5): "claude" (default) or
   *  "bsc-agent" — our model-agnostic runtime, on the provider configured in
   *  Settings → Integrations. Persisted. */
  fleetHarness: "claude" | "bsc-agent";
  setFleetHarness: (h: "claude" | "bsc-agent") => void;
  /** Per-pane model override, keyed by paneId. A pane with no entry falls back to
   *  {@link defaultModel}.
   *
   *  Where the whole model precedence chain LANDS — a fleet stream's model, else a team placement's,
   *  else the persona's default (`streamPaneWiring`). The harness decides what to do with it: Claude
   *  Code takes `claude --model <tier>`, a local (bsc-agent) session takes `$BSC_AGENT_MODEL`.
   *
   *  {@link SessionModel}, not {@link ModelId}: a director may point a local worker at an installed
   *  model by name, and `qwen3.5:9b` is not a tier. The narrow type never actually constrained this —
   *  the value arrives from plan.db as untyped JSON — it only asserted something false. */
  paneModels: Record<string, SessionModel>;
  setPaneModel: (paneId: string, m: SessionModel) => void;
}

