// Exact Euclidean distance transform, and the signed field built from it (`gpu-graph-slice-2-labels`).
//
// WHY A DISTANCE FIELD AT ALL. The graph is a pan/zoom surface. A bitmap glyph atlas is correct only
// near the size it was rasterized at — it blurs on the way in and aliases on the way out — and text
// that degrades as you zoom is the thing a graph is FOR. A signed distance field is one texture
// sampled with a `smoothstep` whose width comes from the screen derivative, so a glyph is crisp at
// every scale. The cost is per-PIXEL, not per-node, so it does not grow with the graph.
//
// WHY EXACT AND NOT APPROXIMATE. The usual runtime shortcut is a chamfer/8SSEDT approximation, which
// is a few percent wrong on diagonals. On a distance FIELD that error lands exactly where glyph
// outlines are most diagonal — the shoulders of an 'a', the apex of an 'A' — and reads as a wobbling
// edge when you zoom. Felzenszwalb-Huttenlocher is exact and still O(pixels): two separable passes of
// a 1D transform whose inner loop is amortized O(1) per column.
//
// PURE. No canvas, no GL, no DOM — it takes an array of numbers and returns one. That is what lets the
// exactness claim be tested against a brute-force nearest-pixel search rather than eyeballed, which is
// the only way anyone would ever notice it was subtly wrong.

/** Squared distances, so nothing here takes a square root until the caller asks for one. */
const INF = 1e20;

/**
 * The 1D squared-distance transform of a sampled function, in place.
 *
 * `f[q]` is the cost at position q; the result is `min over p of (f[p] + (q-p)^2)`. Feeding it 0 at
 * "inside" pixels and INF elsewhere makes it a distance transform; running it per column and then per
 * row makes that distance Euclidean, which is the separability the algorithm exists for.
 *
 * The scratch arrays are passed in because this is called once per row AND once per column of every
 * glyph — allocating them here would allocate twice per pixel of the atlas.
 *
 * `v` holds the indices of parabolas in the lower envelope and `z` the boundaries between them; the
 * `while` pops parabolas that have been overtaken, which is what makes the whole pass amortized O(n).
 */
export function edt1d(f: Float64Array, n: number, d: Float64Array, v: Int32Array, z: Float64Array): void {
  let k = 0;
  v[0] = 0;
  z[0] = -INF;
  z[1] = INF;
  for (let q = 1; q < n; q++) {
    let s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    while (s <= z[k]) {
      k--;
      s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    }
    k++;
    v[k] = q;
    z[k] = s;
    z[k + 1] = INF;
  }
  k = 0;
  for (let q = 0; q < n; q++) {
    while (z[k + 1] < q) k++;
    const dq = q - v[k];
    d[q] = dq * dq + f[v[k]];
  }
}

/**
 * Squared Euclidean distance from every pixel to the nearest pixel where `inside` is true — `O(W*H)`.
 *
 * Returns squared distances; the caller takes the root once, on the values it actually keeps.
 */
export function edt2d(inside: Uint8Array, w: number, h: number): Float64Array {
  const grid = new Float64Array(w * h);
  for (let i = 0; i < w * h; i++) grid[i] = inside[i] ? 0 : INF;
  const n = Math.max(w, h);
  const f = new Float64Array(n);
  const d = new Float64Array(n);
  const v = new Int32Array(n);
  const z = new Float64Array(n + 1);
  // Columns first, then rows. Order does not matter mathematically — the transform is separable — but
  // doing columns first keeps the row pass reading contiguous memory, which is the hot one.
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) f[y] = grid[y * w + x];
    edt1d(f, h, d, v, z);
    for (let y = 0; y < h; y++) grid[y * w + x] = d[y];
  }
  for (let y = 0; y < h; y++) {
    const row = y * w;
    for (let x = 0; x < w; x++) f[x] = grid[row + x];
    edt1d(f, w, d, v, z);
    for (let x = 0; x < w; x++) grid[row + x] = d[x];
  }
  return grid;
}

/**
 * A signed distance field, encoded to bytes for an R8 texture.
 *
 * `alpha` is a rasterized glyph's coverage (0-255); a pixel counts as inside above `threshold`. The
 * signed distance is `outside - inside`, so it is negative within the glyph and positive without, and
 * it is mapped into 0..255 with 0.5 at the edge — the value the shader compares against.
 *
 * `spread` is how many pixels the field covers either side of the outline. Too small and the shader
 * has no gradient to antialias against when zoomed in; too large and precision is wasted on distances
 * nothing samples. 8 is the usual working value for text at these sizes.
 */
export function signedDistanceField(
  alpha: Uint8Array,
  w: number,
  h: number,
  spread = 8,
  threshold = 128,
): Uint8Array {
  const inside = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) inside[i] = alpha[i] >= threshold ? 1 : 0;
  const outsideD = edt2d(inside, w, h);
  // The complement's transform gives the distance from an inside pixel to the nearest OUTSIDE one.
  // Both are needed: a field built from one side only is flat within the glyph, and the shader's
  // antialiasing has nothing to work with on the inner edge.
  const flipped = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) flipped[i] = inside[i] ? 0 : 1;
  const insideD = edt2d(flipped, w, h);

  const out = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) {
    const dist = inside[i] ? -Math.sqrt(insideD[i]) : Math.sqrt(outsideD[i]);
    // Clamp AFTER mapping so the byte range is used symmetrically around the edge value.
    const v = 0.5 - dist / (2 * spread);
    out[i] = Math.max(0, Math.min(255, Math.round(v * 255)));
  }
  return out;
}

// The networks slice — a WRITE-THROUGH CACHE over the global network store (`bsc network`).
//
// A NETWORK is a domain: the set of projects that share one concern, drawn as one Glance tab, and the
// owner of exactly one architect session. The desktop, a live session's own shell and the architect all
// read the same store; on boot `hydrateNetworks` loads through the bridge, and every mutation below
// pushes through. The in-memory copy exists only for a fast first paint.
//
// DELIBERATELY NOT PERSISTED. `persistedState` is re-serialized on every store `set()`, and its own doc
// forbids putting anything a `bsc` store owns and re-hydrates at boot into it — a persisted copy is a
// duplicated source of truth that goes stale, and a large one freezes the app.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import {
  loadNetworks, pushNetwork, dropNetwork, projectsByNetwork, mintNetworkId, type Network,
} from "@/features/networks/lib/networkBridge";

/** The kitchen-sink domain — where everything not yet organised lives, and what a fresh install opens
 *  on. Must match `bsc_project::store::DEFAULT_NETWORK_ID`, which is what the migration writes onto every
 *  pre-existing project row. */
export const DEFAULT_NETWORK_ID = "network-kitchen";

export interface NetworksSlice {
  /** Every network, tab order first. Hydrated from `bsc network`; never persisted. */
  networks: Network[];
  /** Load from the store. Authoritative — a null read (bridge unreachable) LEAVES what is there rather
   *  than blanking the tab strip, which is why the bridge distinguishes the two. */
  hydrateNetworks: () => Promise<void>;
  /** Create one from a display name; returns its minted id. Idempotent only in the sense that a
   *  colliding name gets a fresh id rather than overwriting — see `mintNetworkId`. */
  addNetwork: (name: string) => string;
  /** Rename — DISPLAY ONLY. The id is frozen because the architect's pane id and workspace dir derive
   *  from it, and renaming those would strand a running session. */
  renameNetwork: (id: string, name: string) => void;
  /**
   * Delete a network. REFUSES while any project is still filed into it, resolving to `false`.
   *
   * A network is not the owner of its projects — membership is a column on each project row — so a
   * delete cannot cascade, and removing it anyway would leave those projects pointing at nothing:
   * present in `bsc project list`, absent from every tab. Refusing is the recoverable answer, and the
   * caller is told which projects are in the way.
   */
  removeNetwork: (id: string) => Promise<{ ok: boolean; blockedBy: string[] }>;
}

export const createNetworksSlice: StateCreator<AppStore, [], [], NetworksSlice> = (set, get) => ({
  networks: [],

  hydrateNetworks: async () => {
    const rows = await loadNetworks();
    if (rows === null) return; // unreachable bridge — keep what we have

    // RECONCILE, not just load. Two stores hold the two halves of a network and neither writes the
    // other: `bsc project network set` (and the kitchen migration) writes the id onto a PROJECT row,
    // while the network's own row lives here. They can therefore disagree — and did, on every machine
    // that upgraded: the migration filed all 27 projects into `network-kitchen` while
    // `bsc network list` returned nothing, so Glance had no tab to draw them in.
    //
    // Creating what is referenced-but-missing heals that in the direction that cannot lose data: a
    // project naming a network is evidence the network should exist. The reverse is never done — an
    // empty network is perfectly legitimate and must not be swept away.
    const referenced = new Set(
      (await projectsByNetwork()).map((p) => p.network).filter((n): n is string => !!n),
    );
    const have = new Set(rows.map((n) => n.id));
    const missing = [...referenced].filter((id) => !have.has(id)).sort();

    // …and with NOTHING at all, `kitchen` — the kitchen-sink domain. Every Glance tab is a domain, so a
    // fresh install must open on one rather than on an empty strip with only a `+`.
    if (rows.length === 0 && missing.length === 0) missing.push(DEFAULT_NETWORK_ID);

    if (missing.length === 0) { set({ networks: rows }); return; }

    const created = missing.map((id, i) => ({
      id,
      // `network-kitchen` → `kitchen`. The id is the only thing that survived the migration, so the
      // name is derived from it rather than invented; the user renames it freely afterwards.
      name: id.startsWith("network-") ? id.slice("network-".length) : id,
      position: rows.length + i,
    }));
    for (const n of created) void pushNetwork(n);
    set({ networks: [...rows, ...created] });
  },

  addNetwork: (name) => {
    const trimmed = name.trim() || "network";
    const id = mintNetworkId(get().networks, trimmed);
    const network: Network = {
      id,
      name: trimmed,
      position: get().networks.reduce((max, n) => Math.max(max, n.position), -1) + 1,
    };
    set((s) => ({ networks: [...s.networks, network] }));
    void pushNetwork(network);
    return id;
  },

  renameNetwork: (id, name) => {
    const trimmed = name.trim();
    if (!trimmed) return; // an empty name is dropped, matching TabBar's own inline-rename contract
    let updated: Network | undefined;
    set((s) => ({
      networks: s.networks.map((n) => {
        if (n.id !== id) return n;
        // The id is re-pinned rather than spread-over: a patch must never be able to move it.
        updated = { ...n, name: trimmed, id: n.id };
        return updated;
      }),
    }));
    if (updated) void pushNetwork(updated);
  },

  removeNetwork: async (id) => {
    const blockedBy = (await projectsByNetwork()).filter((p) => p.network === id).map((p) => p.key);
    if (blockedBy.length > 0) return { ok: false, blockedBy };
    set((s) => ({ networks: s.networks.filter((n) => n.id !== id) }));
    void dropNetwork(id);
    return { ok: true, blockedBy: [] };
  },
});

import { useState, Suspense } from "react";
import { useAppStore } from "@/store";
import { Titlebar } from "@/app/chrome/Titlebar";
import { DetachedTabStrip } from "@/app/DetachedTabStrip";
import { ConsoleGraphHost } from "@/app/console/ConsoleGraphHost";
import { TerminalHost } from "@/app/console/terminal/TerminalHost";
import { detachedTabId, detachedSection } from "@/app/console/lib/detachWindow";
import { StudioSessionHosts } from "@/features/studio-sessions";
import { LiveSpectrumAnalyzer } from "@/features/lan";
import { ImaginationWidget } from "@/features/imagination";
import { Stack } from "@/shared/ui/layout/Stack";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import {
  LogsWorkspace, WorkspaceFallback,
} from "@/app/lazyWorkspaces";

// Render a detached page's section. A switch over literal cases (not a dynamic
// lookup keyed by the URL-supplied `page`) so there's no user-controlled dispatch.
function renderDetachedSection(page: string, section: string): React.ReactNode {
  switch (page) {
    case "logs":          return <LogsWorkspace pageOverride={section} />;
    // Widget windows (`bsc widget open <id>`). The id arrives from a command
    // line, so it is matched against LITERAL cases here rather than looked up:
    // the no-user-controlled-dispatch property of this switch is the reason a
    // CLI-supplied id is safe to act on at all.
    case "widget":
      switch (section) {
        case "spectrum":  return <LiveSpectrumAnalyzer />;
        case "imagination": return <ImaginationWidget />;
        default:
          return (
            <Text as="div" mono tone="dim" style={{ padding: 24 }}>
              Unknown widget: {section}
            </Text>
          );
      }
    default:
      return (
        <Text as="div" mono tone="dim" style={{ padding: 24 }}>
          Unknown detached page: {page}
        </Text>
      );
  }
}

/** True when this window was opened as a detached tab/section (a tear-off, #430/#463). */
export function isDetachedWindow(): boolean {
  return detachedTabId() !== null || detachedSection() !== null;
}

/**
 * The minimal-chrome window rendered for a tear-off (#430/#463): either a detached page-section
 * (?detach=<page>&section=<id>) or a single console tab (?detachTab=<id>) — no rail/tabstrip, just
 * a titlebar + the one surface. Only mounted when isDetachedWindow() (computed once per window load).
 */
export function DetachedWindow() {
  const [detachId] = useState(() => detachedTabId());
  const [detSection] = useState(() => detachedSection());
  const tabs = useAppStore((s) => s.tabs);
  const hasHydrated = useAppStore((s) => s.hasHydrated);

  // Detached page-section window: minimal chrome, just that page's section. Like the detached TAB window
  // below it needs its OWN <TerminalHost> (#2378) — a torn-off Design/Algorithms studio docks a
  // <TerminalSlot> (#3357), which is inert without a host ancestor — plus the studio session hosts, since
  // this window is the SOLE owner of that studio's terminal while it is torn off (the main window skips it,
  // see `studioDetached`).
  if (detSection) {
    return (
      <TerminalHost>
      <Box className="app">
        {/* #3919: the browser model — this window carries its tab, and dragging it off the strip
            docks the page back into the main window. */}
        <DetachedTabStrip page={detSection.page} section={detSection.section} label={detSection.section} />
        <Box className="shell">
          <Box className="main">
            <Box className="page">
              {hasHydrated && <Suspense fallback={<WorkspaceFallback />}>{renderDetachedSection(detSection.page, detSection.section)}</Suspense>}
            </Box>
          </Box>
        </Box>
      </Box>
      <StudioSessionHosts />
      </TerminalHost>
    );
  }

  // Detached tab window: minimal chrome (no rail/tabstrip), just this tab's console. This is a separate
  // window/React root reconnecting to the same backend PTYs, so it needs its OWN TerminalHost (#2378) —
  // its console cells drop TerminalSlots, and without a host ancestor they'd be inert (no terminal).
  const detachIdx = detachId !== null ? tabs.findIndex((t) => t.id === detachId) : -1;
  return (
    <TerminalHost>
    <Box className="app">
      <Titlebar workspace={detachIdx >= 0 ? (tabs[detachIdx]?.name ?? "Console") : "Console"} />
      <Box className="shell">
        <Box className="main">
          <Box className="page">
            {hasHydrated && detachIdx >= 0 && (
              <Stack style={{ flex: 1, minHeight: 0 }}>
                <ConsoleGraphHost tabIdxOverride={detachIdx} />
              </Stack>
            )}
          </Box>
        </Box>
      </Box>
    </Box>
    </TerminalHost>
  );
}

// The frontend ↔ network store bridge. A NETWORK is a domain: the set of projects that share one
// concern, drawn as one Glance tab, and the owner of exactly one architect session. The desktop and
// every live session share ONE global store (`~/.base-studio-code/networks.db`), reached here — and
// from a session's own shell — through the same `bsc network …` CLI over the generic `bsc` bridge
// (#2114). Networks are GLOBAL (no project key), so every call passes `null`. Mirrors orgBridge.ts
// exactly; the store slice is a write-through cache over this.
//
// Which PROJECTS are in a network is deliberately not here: that is the `network` column on each
// project row (`bsc project network set`), so a network never carries a member list to keep in sync.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";

/** One network, exactly as the `bsc network` store holds it. */
export interface Network {
  /** `network-<slug>`, minted at creation and FROZEN — the architect's pane id and workspace dir are
   *  derived from it, so a changed id strands a running session. Rename the `name`. */
  id: string;
  /** What the Glance tab shows. Display-only; safe to change. */
  name: string;
  /** The architect persona id, or absent for the default architect. */
  architect?: string;
  /** Tab order. */
  position: number;
}

/**
 * Load every network via `bsc network list --full`. Returns `null` when the bridge is unreachable (no
 * Tauri host — tests, the web shell, or an older bundled binary) so the caller can tell "no networks"
 * from "could not ask", and leave what it has rather than blanking the tab strip.
 *
 * NOT `bscJson`: its degrade-to-fallback returns an empty array, which is indistinguishable from a
 * store that genuinely holds nothing — and here that difference is a UI with no tabs.
 */
export async function loadNetworks(): Promise<Network[] | null> {
  try {
    const out = await bsc(null, ["network", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<Network>[];
    return (rows ?? [])
      .filter((n): n is Network => typeof n.id === "string" && !!n.id)
      .map((n, i) => ({
        id: n.id,
        name: n.name?.trim() || n.id,
        architect: n.architect || undefined,
        // A missing position sorts to where it was read rather than to 0, so a hand-written row does
        // not silently jump to the front of the strip.
        position: typeof n.position === "number" ? n.position : i,
      }))
      .sort((a, b) => a.position - b.position || a.id.localeCompare(b.id));
  } catch {
    return null;
  }
}

/** Write-through an upsert (`bsc network set` reads the JSON on stdin). Fire-and-forget; never throws,
 *  so an older bundled `bsc` without the `network` subcommand degrades to cache-only silently. */
export async function pushNetwork(network: Network): Promise<void> {
  try { await bscWrite(null, ["network", "set"], network); } catch { /* store unreachable — cache-only */ }
}

/** Write-through a removal (`bsc network remove <id>`). Never throws (see {@link pushNetwork}). */
export async function dropNetwork(id: string): Promise<void> {
  try { await bscRun(null, ["network", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

/**
 * Every project's network, as `bsc project network list --json` reports it — the answer to "is this
 * network empty?", which the network store itself cannot give.
 *
 * Returns `[]` on any failure. Unlike {@link loadNetworks} the ambiguity is harmless here: the one
 * caller uses it to REFUSE a delete, and failing open (allowing it) would be worse than failing closed
 * only when the store is genuinely reachable and genuinely empty.
 */
export async function projectsByNetwork(): Promise<{ key: string; network: string | null }[]> {
  try {
    const out = await bsc(null, ["project", "network", "list", "--json"]);
    const rows = JSON.parse(out.trim() || "[]") as { key?: string; network?: string | null }[];
    return (rows ?? [])
      .filter((r): r is { key: string; network: string | null } => typeof r.key === "string")
      .map((r) => ({ key: r.key, network: r.network ?? null }));
  } catch {
    return [];
  }
}

/** `network-<slug>` from a display name — the id minting rule, mirroring `mintOrgId`.
 *
 *  Auto-disambiguating (`network-foo`, `network-foo-2`, …) rather than refusing a collision: that is
 *  the convention every in-app library uses. The `projectSlug`-plus-collision-modal discipline exists
 *  only where an id names an on-disk hub recovered by DERIVATION, and a network is a row.
 *
 *  The character class is narrower than a display name allows on purpose — the id becomes a pane key
 *  (`network-<slug>:architect`) and a directory name, and `bsc_session::network_architect_slug`
 *  refuses anything outside `[a-z0-9-]`. A name that slugs to nothing falls back to `network`. */
export function mintNetworkId(existing: { id: string }[], name: string): string {
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60);
  const base = `network-${slug || "network"}`;
  if (!existing.some((n) => n.id === base)) return base;
  let n = 2;
  while (existing.some((x) => x.id === `${base}-${n}`)) n++;
  return `${base}-${n}`;
}

