// The list of pane-keyed maps must not drift from the store (#pane-keyed-store-maps-are-never-pruned).
import { describe, it, expect } from "vitest";
import { PANE_KEYED_MAPS, NOT_PANE_KEYED, looksPaneKeyed, releasePaneState } from "./paneState";
import { useAppStore } from "@/store";

describe("PANE_KEYED_MAPS", () => {
  it("covers every pane-keyed map the store actually declares", () => {
    // THE DRIFT GUARD, and the reason this file exists. A new `paneFoo: Record<string, …>` added to a
    // slice and not listed here would silently start accumulating orphans again — the exact bug this
    // fixes, reintroduced by a one-line addition nobody would think to connect.
    const state = useAppStore.getState() as unknown as Record<string, unknown>;
    const declared = Object.keys(state)
      .filter(looksPaneKeyed)
      .filter((k) => {
        const v = state[k];
        return !!v && typeof v === "object" && !Array.isArray(v);
      })
      .sort();
    // Every map with the shape must be either PRUNED or explicitly EXCLUDED with a reason. A new one
    // that is neither fails here, which is the point — silence is how the orphans accumulated.
    expect(declared).toEqual([...PANE_KEYED_MAPS, ...NOT_PANE_KEYED].sort());
  });
});

describe("NOT_PANE_KEYED", () => {
  it("never overlaps the pruned set", () => {
    // A map in both lists would be pruned AND documented as un-prunable — the two would disagree and
    // the reader could not tell which was true.
    const pruned = new Set<string>(PANE_KEYED_MAPS);
    expect([...NOT_PANE_KEYED].filter((k) => pruned.has(k))).toEqual([]);
  });
});

describe("releasePaneState", () => {
  const state = {
    paneRoles: { a: "worker", b: "director" },
    paneCwds: { a: "/x", b: "/y" },
    paneStatus: { b: "run" },
    // NOT pane-keyed — a credential map keyed by `owner/name`. Must never be touched.
    repoGithubTokens: { "owner/repo": "ghp_secret" },
  } as unknown as Record<string, unknown>;

  it("drops the ids from every pane-keyed map that holds them", () => {
    const out = releasePaneState(state, ["a"]);
    expect(out.paneRoles).toEqual({ b: "director" });
    expect(out.paneCwds).toEqual({ b: "/y" });
  });

  it("leaves maps that are not pane-keyed completely alone", () => {
    // The reason the list is explicit rather than "every object in the state": wrongly deleting a
    // credential costs far more than naming the maps.
    const out = releasePaneState(state, ["owner/repo", "a"]);
    expect(out).not.toHaveProperty("repoGithubTokens");
  });

  it("returns ONLY the maps that changed", () => {
    // Rebuilding untouched maps would replace their identity and invalidate every selector watching
    // them — a re-render storm in the name of tidying up.
    const out = releasePaneState(state, ["a"]);
    expect(Object.keys(out).sort()).toEqual(["paneCwds", "paneRoles"]);
    expect(out).not.toHaveProperty("paneStatus"); // never held "a"
  });

  it("is a no-op for no ids", () => {
    expect(releasePaneState(state, [])).toEqual({});
  });

  it("removes every id it is given", () => {
    const out = releasePaneState(state, ["a", "b"]);
    expect(out.paneRoles).toEqual({});
    expect(out.paneCwds).toEqual({});
    expect(out.paneStatus).toEqual({});
  });
});

// #an-unmerged-ended-pane-is-polled-against-github-forever
import { describe, it, expect } from "vitest";
import {
  verdictFromPulls, planNextProbe, isDue,
  PROBE_BASE_MS, PROBE_MAX_MS, NO_PR_ATTEMPTS,
} from "./prProbe";

describe("verdictFromPulls", () => {
  it("reads a merged PR, an open one, and none at all", () => {
    expect(verdictFromPulls([{ merged_at: "2026-08-29T00:00:00Z" }])).toBe("merged");
    expect(verdictFromPulls([{ merged_at: null }])).toBe("open");
    expect(verdictFromPulls([])).toBe("none");
  });

  it("treats a FAILED request as unknown, never as 'no PR'", () => {
    // `safeInvoke` returns its fallback on failure. Reading that as "no PR exists" is what would
    // retire a pane for being briefly offline — and its PR might merge an hour later.
    expect(verdictFromPulls(null)).toBe("unknown");
    expect(verdictFromPulls(undefined)).toBe("unknown");
    expect(verdictFromPulls({ message: "Bad credentials" })).toBe("unknown");
  });
});

describe("planNextProbe", () => {
  it("stops permanently once merged", () => {
    expect(planNextProbe("merged", 0).retryInMs).toBeNull();
  });

  it("backs off an open PR instead of asking every minute", () => {
    // THE BUG, as a test: the old code re-asked at a flat 60s forever.
    expect(planNextProbe("open", 0).retryInMs).toBe(PROBE_BASE_MS);
    expect(planNextProbe("open", 1).retryInMs).toBe(PROBE_BASE_MS * 2);
    expect(planNextProbe("open", 3).retryInMs).toBe(PROBE_BASE_MS * 8);
  });

  it("caps the backoff so a long-lived PR is still checked eventually", () => {
    expect(planNextProbe("open", 40).retryInMs).toBe(PROBE_MAX_MS);
  });

  it("gives up on a branch with no PR after a bounded number of answers", () => {
    for (let a = 0; a < NO_PR_ATTEMPTS - 1; a++) {
      expect(planNextProbe("none", a).retryInMs, `attempt ${a} should still retry`).not.toBeNull();
    }
    expect(planNextProbe("none", NO_PR_ATTEMPTS - 1).retryInMs).toBeNull();
  });

  it("does NOT spend an attempt on a failed request", () => {
    // Otherwise an outage lasting NO_PR_ATTEMPTS polls would permanently retire every pane, and the
    // worktrees they own would never be reclaimed.
    const p = planNextProbe("unknown", 0);
    expect(p.countsAsAttempt).toBe(false);
    expect(p.retryInMs).toBe(PROBE_BASE_MS);
    for (const v of ["merged", "open", "none"] as const) {
      expect(planNextProbe(v, 0).countsAsAttempt, `${v} is an answer`).toBe(true);
    }
  });

  it("every verdict yields a decision", () => {
    // No verdict may fall through to `undefined` — that would read as "retry immediately, forever".
    for (const v of ["merged", "open", "none", "unknown"] as const) {
      expect(planNextProbe(v, 0)).toHaveProperty("retryInMs");
    }
  });
});

describe("isDue", () => {
  it("treats a pane with no record as due", () => {
    expect(isDue(undefined, 1000)).toBe(true);
  });

  it("waits until the scheduled time", () => {
    expect(isDue(2000, 1999)).toBe(false);
    expect(isDue(2000, 2000)).toBe(true);
  });
});

implementations.code:
// When to ask GitHub about a finished worker's PR again — and when to stop asking.
//
// ## The bug this replaces
//
// `useWorkerAutoEnd` reclaims a worker's worktree once its PR is merged. Its retry state was recorded
// ONLY on the success path (`tornDownRef.add(paneId)` after a merge), so a pane whose branch was never
// merged — or that never had a PR at all — was re-queried every 60 seconds for the life of the app.
//
// MEASURED on a real install: 31 ended panes, all `role: worker`, producing a dead-steady 30
// `github_request` invokes per minute in one burst — 935 in a single app log. That is ~1800 API calls
// an hour, roughly a third of the authenticated rate budget, spent re-asking a question whose answer
// had not changed.
//
// ## Why a verdict, not a boolean
//
// "Not merged" hides three different futures, and they deserve different treatment:
//
//   * `merged` — done. Tear the worktree down and never ask again.
//   * `open`   — a PR exists and is unmerged. This one CAN still change, so it is the only verdict
//                worth re-asking — but on a backoff, because a PR that has been open for an hour is
//                not about to become urgent.
//   * `none`   — no PR exists for that branch. Nothing is in flight to change. Someone could open one
//                later, so a few attempts are worth it, but polling forever is how the 30/min happened.
//   * `unknown`— the request failed (offline, 401, rate-limited). That is not an ANSWER, so it must
//                not consume an attempt; otherwise a spell of bad network would permanently retire a
//                pane whose PR later merges.

/** What GitHub said about a worker branch's pull request. */
export type PrVerdict = "merged" | "open" | "none" | "unknown";

/** First retry delay for a verdict that is worth re-asking. Matches the poll cadence it replaces. */
export const PROBE_BASE_MS = 60_000;
/** Ceiling on the backoff. Half an hour is far below "forever" and far above "every minute". */
export const PROBE_MAX_MS = 30 * 60_000;
/** How many times to re-ask when NO pull request exists. Enough to cover "the PR is opened shortly
 *  after the worker finishes", which is the normal flow; not enough to poll for a day. */
export const NO_PR_ATTEMPTS = 5;

export interface ProbePlan {
  /** Wait this long before asking again, or `null` to stop asking permanently. */
  retryInMs: number | null;
  /** Whether this verdict consumed an attempt. A failed REQUEST is not an answer and must not. */
  countsAsAttempt: boolean;
}

/**
 * Classify a `repos/:repo/pulls?head=…` response into a verdict.
 *
 * `null`/non-array is `unknown` — `safeInvoke` returns the fallback on failure, and treating a failed
 * request as "no PR" is what would retire a pane for being briefly offline.
 */
export function verdictFromPulls(prs: unknown): PrVerdict {
  if (!Array.isArray(prs)) return "unknown";
  if (prs.length === 0) return "none";
  const first = prs[0] as { merged_at?: string | null } | undefined;
  return first?.merged_at ? "merged" : "open";
}

/**
 * When to ask again, given the verdict and how many answers this pane has already produced.
 *
 * `attempts` counts ANSWERS, not requests — see `countsAsAttempt`.
 */
export function planNextProbe(verdict: PrVerdict, attempts: number): ProbePlan {
  switch (verdict) {
    case "merged":
      // The terminal state. The caller tears down; there is nothing left to learn.
      return { retryInMs: null, countsAsAttempt: true };
    case "open":
      // Exponential from the old fixed cadence, capped. `attempts` is the count BEFORE this answer, so
      // the first backoff is one interval — the same wait the old code used, then progressively less.
      return {
        retryInMs: Math.min(PROBE_BASE_MS * 2 ** attempts, PROBE_MAX_MS),
        countsAsAttempt: true,
      };
    case "none":
      return {
        retryInMs: attempts + 1 >= NO_PR_ATTEMPTS ? null : Math.min(PROBE_BASE_MS * 2 ** attempts, PROBE_MAX_MS),
        countsAsAttempt: true,
      };
    case "unknown":
      // Retry at the base cadence WITHOUT consuming an attempt: a failed request says nothing about
      // the PR, and letting it count would let an outage permanently retire a pane.
      return { retryInMs: PROBE_BASE_MS, countsAsAttempt: false };
  }
}

/** Is this pane due to be asked about at `now`? A pane with no record yet is always due. */
export function isDue(nextAt: number | undefined, now: number): boolean {
  return nextAt === undefined || now >= nextAt;
}

// App-chrome domain — automations/settings sub-tabs, per-page tab order, detached tabs/sections,
// and perf + log config. Split from store/types (#1634).
import type { PerfConfig } from "@/store/types/perf";
import type { LogConfig } from "@/store/types/log";
import type { AppStateSnapshot } from "@/store/appState";

/** App-chrome slice of {@link AppStore}. */
export interface ShellState {
  // Automations
  automationsTab: "schedules" | "history";
  setAutomationsTab: (tab: ShellState["automationsTab"]) => void;
  /** Persisted, user-arranged tab order per page (keyed by page id). A page opens
   *  whatever tab the user dragged to the front, so the order IS the preference
   *  (#463). Unknown/new tabs append; stale ids are ignored. */
  pageTabOrder: Record<string, string[]>;
  setPageTabOrder: (page: string, order: string[]) => void;
  /** Persisted last-selected page (tab id) per page (keyed by page id). Lets a
   *  workspace reopen on the Page the user last viewed — across an in-session
   *  workspace switch (most workspaces unmount when inactive) and across restart —
   *  instead of always snapping back to the front tab. Falls back to the front tab
   *  (see {@link pageTabOrder}, #463) when there's no memory; a stale id self-heals
   *  to the front tab via `usePageTabs`'s validity effect. */
  activePageTab: Record<string, string>;
  setActivePageTab: (page: string, id: string) => void;
  /** The navigated ENTITY label per graph, keyed by page id (`glance`/`teams`/`designs`/`algorithms`),
   *  reported by each graph via `useCrumbEntity` so the titlebar location crumb can name where you are
   *  INSIDE a graph — the drilled project, entered team, active kit, active language (#3041). Session-only
   *  transient (NOT persisted): each graph re-reports on mount, so it's always live. Empty = no entity. */
  crumbEntity: Record<string, string>;
  setCrumbEntity: (key: string, label: string) => void;
  /** Console tab ids currently shown in their own window (#430). Session-only
   *  (NOT persisted): hidden from this window's tab bar while detached, cleared
   *  on re-dock or app restart — so the tab returns to its persisted place. */
  detachedTabIds: string[];
  setTabDetached: (id: string, detached: boolean) => void;
  /** Per-page section ids currently shown in their own window (#430). Session-only
   *  (NOT persisted), like detachedTabIds — hidden from the page's tab bar while
   *  detached, returned on re-dock/restart to their persisted place. */
  detachedSections: Record<string, string[]>;
  setSectionDetached: (page: string, id: string, detached: boolean) => void;

  // Settings
  settingsSection: string;
  setSettingsSection: (section: string) => void;
  /**
   * First-run OS-sandbox setup nudge (#1916). How many times the user has DISMISSED the banner
   * (pressed the ✕). The banner shows on launch while the deny-list posture is on and the sandbox
   * isn't ready, and stays hidden once this reaches `SANDBOX_NUDGE_MAX_DISMISSALS`. Counting
   * dismissals (not shows) means the nudge persists across launches until the user actually
   * acknowledges it, rather than silently vanishing after a render they may have missed.
   */
  /** Notices dismissed from the CLI this session (#54, `bsc navigate dismiss`). A banner hides when its
   *  own local state says so OR when its id is here, so an agent driving the app can clear what a mouse
   *  could. Deliberately NOT persisted: a dismissal is for the notice ON SCREEN NOW, and persisting it
   *  would permanently suppress a notice on a future boot that the user has never seen. */
  dismissedNotices: string[];
  /** Hide `id` for the rest of this session. Idempotent; a decision-bearing notice is refused upstream. */
  dismissNotice: (id: string) => void;
  sandboxNudgeDismissCount: number;
  /** Record a ✕ dismissal of the sandbox nudge. */
  dismissSandboxNudge: () => void;

  // Performance monitoring (#569)
  perfConfig: PerfConfig;
  setPerfConfig: (config: PerfConfig) => void;

  // Log management (#1060)
  logConfig: LogConfig;
  setLogConfig: (config: LogConfig) => void;

  // Demo app-state (#2272) — a loaded demo overlays the demoable store slices; the pre-demo values
  // are stashed in `demoBackup` so clearing restores exactly what was there (empty → empty). Both
  // persist so a demo survives restart and stays clearable.
  /** Whether a demo app-state is currently loaded over the user's real state. */
  demoActive: boolean;
  /** The demoable slice values captured just before the demo was loaded (null when no demo active). */
  demoBackup: AppStateSnapshot | null;
  /** Overlay a demo snapshot onto the store, backing up the current demoable state first (once). */
  loadDemoState: (snapshot: AppStateSnapshot) => void;
  /** Restore the pre-demo state (no-op when no demo is active). */
  clearDemoState: () => void;
}

