// GitHub value types shared across the store (connection STATE lives in the GitHub feature
// slice, @/features/github/store). Split from the former store/types monolith (#1634).
export interface GithubUser {
  login: string;
  name: string | null;
  avatar_url: string;
}

export interface GithubRepo {
  full_name: string;
  private: boolean;
  language: string | null;
  open_issues_count: number;
  default_branch: string;
  description: string | null;
  pushed_at: string;
  stargazers_count: number;
}

/**
 * The fields above, as VALUES — because the interface does nothing at runtime.
 *
 * GitHub's repo response carries 82 fields; this type names 8. Annotating the response as
 * `GithubRepo` narrows what the compiler will let you *read*, and strips exactly nothing from what you
 * *store* — so the whole payload went into the store, and 61% of its bytes are `*_url` templates
 * (`archive_url`, `assignees_url`, `blobs_url`, …) that nothing reads. Measured on a real install: 84
 * repos at ~6 KB each, 493.8 KB, which was 86% of the entire persisted state.
 *
 * That is a CPU cost before it is a memory one. `persist`'s `partialize` result is `JSON.stringify`'d
 * on EVERY store `set()` — the module doc in `store/persist.ts` says so, and says a large one freezes
 * the app, citing #3610 where `components` (592 KB) did exactly that. This list is what keeps the same
 * blob from sitting in the same allowlist.
 */
export const GITHUB_REPO_FIELDS = [
  "full_name",
  "private",
  "language",
  "open_issues_count",
  "default_branch",
  "description",
  "pushed_at",
  "stargazers_count",
] as const;

// The list and the interface must agree in BOTH directions, checked by tsc rather than by a test:
// a field added to one and not the other is either silently dropped at runtime (interface-only) or a
// type error waiting at the first read (list-only). Neither shows up in a test that only feeds a
// fixture through, which is why this is a compile-time check.
type ListedField = (typeof GITHUB_REPO_FIELDS)[number];
type _EveryListedFieldIsDeclared = ListedField extends keyof GithubRepo ? true : never;
type _EveryDeclaredFieldIsListed = keyof GithubRepo extends ListedField ? true : never;
const _fieldsAgree: [_EveryListedFieldIsDeclared, _EveryDeclaredFieldIsListed] = [true, true];
void _fieldsAgree;

/**
 * Keep only the declared fields of a raw GitHub repo response.
 *
 * Takes `unknown`-ish input deliberately: the whole point is that the caller has an API object which
 * is NOT a `GithubRepo` no matter what its annotation claims, and pretending otherwise is how the
 * extra 74 fields got in.
 */
export function leanRepo(raw: Record<string, unknown>): GithubRepo {
  const out = {} as Record<string, unknown>;
  for (const f of GITHUB_REPO_FIELDS) out[f] = raw[f];
  return out as unknown as GithubRepo;
}

/** {@link leanRepo} over a list — what every caller actually has. */
export function leanRepos(raw: readonly Record<string, unknown>[]): GithubRepo[] {
  return raw.map(leanRepo);
}

// useFleetStartBridge (`headless-fleet-launch-a-director-cannot-start-its-own-fleet`) — apply a
// `bsc fleet start` request and ACK it.
//
// THE ROUND TRIP
//   bsc fleet start <key> → request file → Rust watcher (resolves the project, reads plan.db's fleet,
//   refuses a live fleet, materializes the hub, creates EVERY worktree fail-closed) →
//   `bsc://fleet-start` → HERE → fleetStartProject → `fleet_start_ack`
//
// A thin adapter: the DECISION lives in `fleetStartBridge.ts`, unit-testable without Tauri.
//
// THIS IS NOT AN INJECTION PATH, for the same reason the director bridge is not: each session's
// context arrives as its kickoff/scope doc on disk, written before the launch reads it. Nothing is
// typed into a running session.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { applyFleetStart, type StartRequest, type StartAck } from "@/app/fleetStartBridge";

/** Listen for `bsc://fleet-start` and launch it. Mounted once by the shell. */
export function useFleetStartBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<StartRequest>("bsc://fleet-start", (e) => {
      const req = e.payload;
      let ack: StartAck;
      try {
        ack = applyFleetStart(req, {
          // Read off a LIVE getState, not a captured snapshot — zustand hands out a new object per
          // update, so a stale closure could launch against an older tab list.
          fleetStartProject: (name, fleet, key, paths) =>
            useAppStore.getState().fleetStartProject(name, fleet, key, paths),
        });
      } catch (err) {
        ack = {
          id: req.id,
          error: `fleet start threw: ${err instanceof Error ? err.message : String(err)}`,
          launched: false,
        };
        log.error(`fleet start ${req.id} threw: ${String(err)}`);
      }
      void invoke("fleet_start_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`fleet_start_ack failed for ${req.id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// Keep the store's `bsc` command-surface catalog current
// (`a-persona-declares-its-command-surfaces`, epic `epic-command-surfaces-are-nodes`).
//
// ONE READER FOR TWO CONSUMERS. The session launch complements this catalog against each persona's
// declared surfaces to build that session's denies (`sessionDeniedCommands` → `permissions.deny` and
// `$BSC_DENY_BASH`), and the Glance drill draws its command-surface band from it. `bsc surface help`
// states outright that the role join belongs at the consumer, and three plan items already exist for
// hand-kept copies of this set drifting from what really dispatches — a second reader would be the
// next one.
//
// IT LIVES IN THE SHELL, not in a workspace. The first read of this catalog was inside
// `GlanceWorkspace`, which only mounts when Glance is open — so a session launched from the Console,
// from the fleet, or headlessly via `bsc fleet start` saw an EMPTY catalog, and an empty catalog
// denies nothing. The permission consequence of a UI-scoped poll is invisible until you look for it.
//
// The rows are stored WHOLE; the two filters over them live in `@/shared/lib/session/surfaceCatalog`
// so a feature can reach them without importing the shell.
import { usePoll } from "@/shared/hooks/usePoll";
import { bscJson } from "@/shared/lib/core/bsc";
import { useAppStore } from "@/store";
import type { SurfaceRow } from "@/shared/lib/session/surfaceCatalog";

/** How often to re-read. The catalog is a `const` compiled into the `bsc` binary, so it moves only
 *  when the binary is REPLACED — which does happen mid-session, since a rebuild re-stages the sidecar
 *  (`replaced_since` in `bsc serve` exists for exactly that). Far above how often it changes, far
 *  below how long a stale set would matter. */
const POLL_MS = 60_000;

/** Poll the catalog into the store. Mount ONCE, in the shell. */
export function useSurfaceCatalogPoll(): void {
  const setSurfaceCatalog = useAppStore((s) => s.setSurfaceCatalog);
  usePoll(async (isCancelled) => {
    const rows = await bscJson<SurfaceRow[]>(null, ["surface", "list", "--json"], []);
    if (isCancelled()) return;
    // A failed read yields `[]`, which every consumer treats as UNKNOWN and fails open on. Writing it
    // is still correct: the alternative — keeping the last good value — would let a catalog that has
    // genuinely shrunk keep denying a surface that no longer exists.
    //
    // Narrowed to {name, status} rather than stored as-is: the catalog also carries `store` and
    // `summary`, which nothing here reads, and holding them would put prose into a store that a
    // selector compares on every mutation.
    setSurfaceCatalog(
      Array.isArray(rows)
        ? rows.filter((r) => r && typeof r.name === "string").map((r) => ({ name: r.name, status: r.status }))
        : [],
    );
  }, POLL_MS);
}

// Service icon name → the glyph that draws it.
//
// Split from the workspace for two reasons. A file that exports both a component and a plain map
// loses fast refresh (`react-refresh/only-export-components`); and this cannot live in `lib/`, which
// is React-free by convention — a `LucideIcon` is a component, and importing lucide-react there
// would put React into the pure domain module.
//
// So the split is: `lib/credentials.ts` decides WHICH glyph name a service gets (pure, unit-tested),
// and this decides what that name draws as.
import { createElement } from "react";
import { KeyRound, Mail, MessageSquare, Cloud, Database, CreditCard, Server, Bot, AtSign } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { Github } from "@/shared/ui/icons";
import { serviceIcon } from "@/features/credentials/lib/credentials";

/** Icon key (from `serviceIcon`) → glyph. Every value `SERVICE_ICONS` can produce needs an entry
 *  here, or the row silently draws the fallback key — `credentialsGlyphCoverage` in the test pins
 *  the two halves together so a new service cannot map to a glyph nothing renders. */
const GLYPHS: Record<string, LucideIcon> = {
  github: Github,
  mail: Mail,
  chat: MessageSquare,
  cloud: Cloud,
  database: Database,
  payments: CreditCard,
  server: Server,
  model: Bot,
  social: AtSign,
  key: KeyRound,
};

/** The glyph for a service, always resolvable. `serviceIcon` already falls an unmapped service back
 *  to `key`; this falls back again so a bad map entry costs an icon rather than the whole row. */
export function glyphFor(service: string | undefined): LucideIcon {
  return GLYPHS[serviceIcon(service)] ?? KeyRound;
}

/**
 * A service's icon.
 *
 * `createElement` rather than `const Glyph = glyphFor(…)` + `<Glyph />`: assigning a component to a
 * capitalized local inside a render body reads to `react-hooks/static-components` as creating a
 * component during render (which resets its state every pass). The glyph here is looked up from a
 * module-level map, never created — and calling `createElement` on it says so.
 */
export function ServiceGlyph({ service, size = 18 }: { service?: string; size?: number }) {
  return createElement(glyphFor(service), { size });
}

