import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor, fireEvent, within } from "@testing-library/react";
import { MemoryWorkspace } from "@/features/memory/MemoryWorkspace";

const bsc = vi.hoisted(() => vi.fn());
// A PARTIAL mock, not a replacement. This workspace renders through `Screen`/`usePageTabs`, which
// pull in the app store — and the store imports `bscJson` from this same module. A whole-module mock
// therefore breaks the store's own import rather than this component's, and reports as an unhandled
// rejection from a file that never mentions the store.
vi.mock("@/shared/lib/core/bsc", async (importOriginal) => ({
  ...(await importOriginal<typeof import("@/shared/lib/core/bsc")>()),
  bsc,
}));

const row = (over: Record<string, unknown> = {}) => ({
  id: "1788838726372414613",
  text: "the gate records its own evidence",
  tags: ["gate"],
  created_at_ms: Date.now(),
  status: "open",
  horizon: "now",
  kind: "lesson",
  links: [],
  ...over,
});

/** Open a kind page. The workspace opens on GRAPH, so a list assertion has to navigate there first —
 *  by clicking the tab, which is also how a person gets there.
 *
 *  Scoped to the TABSTRIP on purpose: once a page is open its label is also the heading, so a bare
 *  `findByText` matches two elements and fails on the ambiguity rather than on the behaviour. */
async function openPage(label: string) {
  const strip = document.querySelector(".tabstrip") as HTMLElement;
  const tab = await within(strip).findByText(label);
  fireEvent.click(tab);
}

beforeEach(() => {
  bsc.mockReset();
});

describe("MemoryWorkspace", () => {
  it("reads the GLOBAL store — a null project key, like `bsc skill`", async () => {
    bsc.mockResolvedValue(JSON.stringify([]));
    render(<MemoryWorkspace />);
    await waitFor(() => expect(bsc).toHaveBeenCalled());
    // The payload, not just the call: a memory about the gate is not owned by whichever project
    // happens to be open, so passing a project key here would scope the store wrongly.
    expect(bsc).toHaveBeenCalledWith(null, ["memory", "list", "--json"]);
  });

  it("opens on the GRAPH page — the edges are the point, and a list cannot show them", async () => {
    bsc.mockResolvedValue(JSON.stringify([row({ links: [{ ref: "bsc-mem--cli.rs", rel: "about" }] })]));
    render(<MemoryWorkspace />);
    // The toolbar stat is assembled from several JSX expressions, so it is read as the element's
    // textContent rather than matched as one text node — a matcher that cannot span elements would
    // fail here on the markup rather than on the count.
    await waitFor(() => expect(document.querySelector(".mem-graph-stat")).toBeTruthy());
    // TWO nodes for one memory: the memory itself and the record STUB it points at. That is the
    // claim "everything is a node" made countable.
    expect(document.querySelector(".mem-graph-stat")!.textContent).toContain("2 nodes");
    expect(document.querySelector(".mem-graph-stat")!.textContent).toContain("1 edge");
    // The edge's relationship is drawn as a LABEL on the line, not left as a bare connection.
    expect(screen.getByText("about")).toBeTruthy();
    // Two nodes: the memory, and the record STUB it points at — everything is a node.
    expect(document.querySelectorAll(".mem-node")).toHaveLength(2);
  });

  it("renders a memory's text, tags and every typed edge as a chip on its kind page", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([row({ links: [{ ref: "bsc-mem--cli.rs", rel: "about" }, { ref: "feature:auth", rel: "because" }] })]),
    );
    render(<MemoryWorkspace />);
    await openPage("Lessons");
    expect(await screen.findByText("the gate records its own evidence")).toBeTruthy();
    expect(screen.getByText("#gate")).toBeTruthy();
    // BOTH halves of each edge are text. This is the accessibility guard: `about` and `contradicts`
    // are opposite claims about one target, so neither may be carried by colour alone.
    expect(screen.getByText("about")).toBeTruthy();
    expect(screen.getByText("bsc-mem--cli.rs")).toBeTruthy();
    expect(screen.getByText("because")).toBeTruthy();
    // A prefixed target renders its TYPE and its readable half, not the raw `feature:auth`.
    expect(screen.getByText("feature")).toBeTruthy();
    expect(screen.getByText("auth")).toBeTruthy();
  });

  it("puts each memory only on its own kind page", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([
        row({ id: "1788838726372414613", text: "a rule we learned", kind: "lesson" }),
        row({ id: "1788838726372414614", text: "a decision we took", kind: "highlight" }),
      ]),
    );
    render(<MemoryWorkspace />);
    await openPage("Lessons");
    expect(await screen.findByText("a rule we learned")).toBeTruthy();
    expect(screen.queryByText("a decision we took")).toBeNull();
    await openPage("Highlights");
    expect(await screen.findByText("a decision we took")).toBeTruthy();
    expect(screen.queryByText("a rule we learned")).toBeNull();
  });

  it("names the unclassified count in the footer — a memory with no kind is where nobody looks", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([row({ kind: "note" }), row({ id: "1788838726372414615", kind: "lesson" })]),
    );
    render(<MemoryWorkspace />);
    expect(await screen.findByText("1 unclassified")).toBeTruthy();
  });

  it("surfaces a read failure as the real error — never as an empty store", async () => {
    bsc.mockRejectedValue(new Error("Cannot read properties of undefined (reading 'invoke')"));
    render(<MemoryWorkspace />);
    expect(await screen.findByRole("alert")).toBeTruthy();
    expect(screen.getByText(/Cannot read properties of undefined/)).toBeTruthy();
    // The opposite fact must NOT also be on screen: "could not be read" and "nothing remembered"
    // are contradictory claims, and showing both is how a broken store reads as an empty one.
    expect(screen.queryByText("Nothing remembered yet")).toBeNull();
  });

  it("names the capture command when the store is empty, so the screen is not a dead end", async () => {
    bsc.mockResolvedValue("[]");
    render(<MemoryWorkspace />);
    expect(await screen.findByText("Nothing remembered yet")).toBeTruthy();
    expect(screen.getByText(/bsc memory add/)).toBeTruthy();
  });

  it("reports how many memories AND how many edges — a pile is not a graph", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([row({ links: [{ ref: "a.rs", rel: "about" }] }), row({ id: "1788838726372414614" })]),
    );
    render(<MemoryWorkspace />);
    expect(await screen.findByText("2 memories · 1 edge")).toBeTruthy();
  });
});

implementations.code:
// The Memory workspace — the window onto the session-memory store (`bsc memory`).
//
// It answers the question this repo kept losing: WHAT DO WE KNOW, and what is it about? A session
// generates findings, decisions, lessons and parked threads that have no plan item and no code task,
// and until `bsc memory` they evaporated when the terminal closed. The store catches them; this is
// where a person reads them without opening a shell.
//
// EVERYTHING IS A NODE. A memory carries typed edges (`about`, `because`, `supersedes`, `lesson-of`,
// …) to whatever it relates to — a code record, a FEATURE, a SESSION, a plan ref, another memory — so
// the first page is the GRAPH, and the kind pages are the readable index into it.
//
// THE PAGE AXIS IS KIND, NOT HORIZON, and that is the decision worth keeping. The kinds have
// different provenance and different lifecycles: a lesson comes from a session getting something
// wrong, a highlight from a conversation that must persist indefinitely, a record note from a comment
// inside code, an ambient capture from the always-on ear. Horizon (`now`/`future`) was the first cut
// and it was the model's facet rather than the reader's — two readings of one pile. It survives as a
// filter within a page, which is where it belongs: a highlight can be a hope, a lesson never is.
//
// `note` is a QUEUE, not a category — the kind an unclassified memory reads as, so that omitting
// `--kind` never mislabels one. Same for an edgeless memory: it used to have its own tab, and the
// graph shows it better, as a node visibly floating with nothing reaching it.
//
// EVERY WRITE GOES THROUGH `bsc memory`, not through a UI-only path. `add`/`link`/`horizon`/`done`
// already exist as verbs a session runs, and a capability only the UI has is the bug this project
// keeps correcting — so the footer TEACHES the command rather than replacing it.
import { useCallback, useEffect, useMemo, useState } from "react";
import { Brain, RefreshCw } from "lucide-react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Screen } from "@/shared/ui/layouts/Screen";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import type { TabItem } from "@/shared/ui/layouts/TabBar";
import { bsc } from "@/shared/lib/core/bsc";
import { MemoryGraphView } from "@/features/memory/MemoryGraphView";
import {
  parseMemories, sortMemories, selectTab, searchMemories, summarize, linkKind, targetLabel,
  relativeAge, MEMORY_TABS, TAB_LABEL, TAB_BLURB, KIND_META,
  type MemoryEntry, type MemoryLink, type MemoryTab,
} from "@/features/memory/lib/memory";

/** The command that captures one — shown in the empty state and the footer, because a screen that
 *  reports an empty store without saying how to fill it is a dead end. */
const CAPTURE_CMD = `bsc memory add "<what you learned>" --kind lesson --link about:<record-id>`;

function LinkChip({ link }: { link: MemoryLink }) {
  const kind = linkKind(link.ref);
  // The relationship is rendered as TEXT, never as colour alone: `about` and `contradicts` are
  // opposite claims about the same target, and a reader who cannot tell two tones apart would see
  // one chip. The kind rides a data attribute so the CSS has one rule per kind, not per rel.
  return (
    <Text as="span" className="mem-chip" data-kind={kind} title={`${link.rel} → ${link.ref} (${kind})`}>
      <span className="mem-chip-rel">{link.rel}</span>
      <span className="mem-chip-kind">{kind}</span>
      <span className="mem-chip-ref mono">{targetLabel(link.ref)}</span>
    </Text>
  );
}

function MemoryRow({ memory, now }: { memory: MemoryEntry; now: number }) {
  return (
    <li className="mem-row" data-horizon={memory.horizon} data-status={memory.status} data-kind={memory.kind}>
      <Stack gap={4} className="mem-body">
        <Text as="p" className="mem-text">{memory.text}</Text>
        <Row gap="xs" wrap align="center" className="mem-meta">
          {/* The kind is on the row as TEXT even inside its own page, because the Graph page mixes
              every kind and a row there must still say what it is. */}
          <Text as="span" className="mem-kind">{KIND_META[memory.kind].label.replace(/s$/, "")}</Text>
          <Text as="span" mono className="mem-age">{relativeAge(memory.createdAtMs, now)}</Text>
          {memory.horizon === "future" && <Text as="span" className="mem-horizon">future</Text>}
          {memory.status === "done" && <Text as="span" className="mem-done">done</Text>}
          {memory.tags.map((t) => (
            <Text as="span" key={t} mono className="mem-tag">#{t}</Text>
          ))}
        </Row>
        {memory.links.length > 0 && (
          <Row gap="xs" wrap align="center" className="mem-links">
            {memory.links.map((l) => (
              <LinkChip key={`${l.rel}:${l.ref}`} link={l} />
            ))}
          </Row>
        )}
      </Stack>
    </li>
  );
}

/** The Memory rail Workspace. */
export function MemoryWorkspace() {
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [error, setError] = useState<string | null>(null);
  // `loaded` rather than `loading`: the empty state and the still-fetching state look identical
  // otherwise, and flashing "nothing remembered" before the first response lands reads as data loss.
  const [loaded, setLoaded] = useState(false);
  const [query, setQuery] = useState("");
  const [now, setNow] = useState(() => Date.now());

  const load = useCallback(async () => {
    try {
      // The memory store is GLOBAL, not per-project — a lesson about the gate is not owned by
      // whichever project happens to be open — so the bridge's project key is null, as for `bsc skill`.
      const raw = await bsc(null, ["memory", "list", "--json"]);
      // Every setState below happens AFTER the await; a synchronous one would run during the
      // effect's own pass, which is what `react-hooks/set-state-in-effect` exists to prevent.
      setMemories(parseMemories(raw));
      setNow(Date.now());
      setError(null);
    } catch (e) {
      // Surfaced, never swallowed into an empty list: "the store could not be read" and "the store
      // is empty" are opposite facts, and this screen exists to say truthfully which one holds.
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoaded(true);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const all = useMemo(() => sortMemories(memories), [memories]);
  const summary = useMemo(() => summarize(all), [all]);

  const defs: TabItem[] = useMemo(
    () =>
      MEMORY_TABS.map((id) => ({
        id,
        label: TAB_LABEL[id],
        // The count decides whether the page is worth opening at all — an Unclassified tab reading 0
        // is the goal state, and worth seeing from outside.
        count: selectTab(all, id).length,
      })),
    [all],
  );
  const pages = usePageTabs("memory", defs);
  const tab = (MEMORY_TABS.find((t) => t === pages.activeId) ?? "graph") as MemoryTab;
  const rows = useMemo(() => searchMemories(selectTab(all, tab), query), [all, tab, query]);

  return (
    <Screen
      tabs={pages.tabs}
      active={pages.activeId}
      onSelect={pages.select}
      onReorder={pages.reorder}
      className="mem-workspace"
      bodyClassName="mem-body-wrap"
    >
      <Stack gap="md" className="mem-screen">
        <Row align="start" justify="between" gap="md" wrap className="mem-head">
          <Stack gap={0}>
            <h2 className="mem-title">{TAB_LABEL[tab]}</h2>
            <p className="mem-sub">{TAB_BLURB[tab]}</p>
          </Stack>
          <Row align="center" gap="sm" className="mem-head-right">
            {loaded && !error && (
              // Both numbers, because they are different claims: how much we remember, and how much
              // of it is connected. A store with many memories and no edges is a pile, not a graph.
              <Text as="span" mono className="mem-count">
                {summary.total} memor{summary.total === 1 ? "y" : "ies"} · {summary.edges} edge
                {summary.edges === 1 ? "" : "s"}
              </Text>
            )}
            <input
              className="mem-search mono"
              type="search"
              value={query}
              placeholder="search text, tags, edges"
              aria-label="Search memories"
              onChange={(e) => setQuery(e.target.value)}
            />
            <Button size="sm" className="mem-refresh" onClick={() => void load()} title="Re-read the memory store">
              <RefreshCw size={14} />
              Refresh
            </Button>
          </Row>
        </Row>

        {error && (
          <Stack gap="xs" className="mem-error" role="alert">
            <strong>The memory store could not be read.</strong>
            <Text as="span" mono>{error}</Text>
          </Stack>
        )}

        {!error && loaded && all.length === 0 && (
          <EmptyState
            icon={<Brain size={20} />}
            title="Nothing remembered yet"
            description="Capture what a session learns but has no plan item for — a finding, a decision, a lesson, a parked thread. Link it to the record or plan ref it is about, and it becomes traversable rather than a note nobody finds again."
            extra={<code className="mono mem-cmd">{CAPTURE_CMD}</code>}
          />
        )}

        {!error && loaded && all.length > 0 && rows.length === 0 && (
          <EmptyState
            icon={<Brain size={20} />}
            title={query.trim() ? "Nothing matches that search" : `Nothing under ${TAB_LABEL[tab]}`}
            description={
              query.trim()
                ? "The store is not empty — this query narrowed it to nothing. Clear the search to see the page again."
                : TAB_BLURB[tab]
            }
          />
        )}

        {/* The GRAPH page renders the canvas; every other page is the readable list for its kind.
            The search box narrows BOTH — a filtered graph is the useful one. */}
        {!error && tab === "graph" && rows.length > 0 && <MemoryGraphView memories={rows} />}

        {!error && tab !== "graph" && rows.length > 0 && (
          <Box as="ul" className="mem-list">
            {rows.map((m) => (
              <MemoryRow key={m.id} memory={m} now={now} />
            ))}
          </Box>
        )}

        {!error && loaded && all.length > 0 && (
          <p className="mem-foot hint">
            Capture with <code className="mono">bsc memory add --kind &lt;kind&gt;</code>, classify one with{" "}
            <code className="mono">bsc memory kind &lt;id&gt; &lt;kind&gt;</code>, connect it with{" "}
            <code className="mono">bsc memory link &lt;id&gt; &lt;rel&gt; &lt;ref&gt;</code>, and ask what we
            remember about anything with <code className="mono">bsc memory list --link &lt;ref&gt;</code>.
            {summary.byKind.note > 0 && (
              <>
                {" "}
                <strong>{summary.byKind.note} unclassified</strong> — a memory with no kind appears where
                nobody looks for it.
              </>
            )}
          </p>
        )}
      </Stack>
    </Screen>
  );
}

// The Memory feature's public API. Cross-feature, import ONLY this barrel (#1545).
//
// `bsc memory` (`~/.base-studio-code/memory.db`) is the store that catches what a session LEARNS but
// has no plan item for — a finding, a decision, a lesson, a parked thread — as a TYPED GRAPH rather
// than a log: each memory carries edges to the record, plan ref or other memory it is about.
//
// The store is deliberately SEPARATE from the code-record graph (`graph/algorithms.json`): memory is
// high-churn user data and must never enter the committed store the build compiles.
export { MemoryWorkspace } from "@/features/memory/MemoryWorkspace";
export { MemoryGraphView } from "@/features/memory/MemoryGraphView";
export {
  HORIZONS, KINDS, KIND_META, MEMORY_STATUSES, MEMORY_TABS, NODE_TYPES,
  TAB_LABEL, TAB_BLURB, DEFAULT_REL, NODE_W, NODE_H, LAYOUT_COLUMNS,
  asHorizon, asKind, asStatus, buildGraph, layoutGraph, linkKind, targetLabel,
  parseMemories, relativeAge, searchMemories, selectTab, sortMemories, summarize, tagCounts,
  type GraphEdge, type GraphLayout, type GraphNode, type Horizon, type Kind, type LayoutColumn,
  type LinkKind, type MemoryEntry, type MemoryGraph, type MemoryLink, type MemoryStatus,
  type MemorySummary, type MemoryTab, type Placed,
} from "@/features/memory/lib/memory";

// The Memory GRAPH page — every memory as a node, every typed edge drawn.
//
// WHY A GRAPH AND NOT ANOTHER LIST. The edges are the whole difference between a memory graph and a
// memory log, and a list can only ever show them as chips on a row — you can read what one memory is
// about, but never which record everything has an opinion about, or which memory nothing can reach.
// Those two questions are the point, and they are only answerable in a picture.
//
// It rides the SHARED `GraphCanvas` (the same Layouts-tier template Glance and the Org designer use),
// so the pan/zoom/world-transform machinery is not reimplemented here — this page brings only its
// world content and its toolbar.
//
// The LAYOUT is deterministic and lives in `lib/memory` where it is unit-tested: columns by kind, most
// -connected first, no physics. A force layout re-arranges on every render and every data change, so a
// node you were reading moves out from under you and the same graph never looks the same twice.
import { useMemo } from "react";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import {
  buildGraph, layoutGraph, NODE_W, NODE_H, KIND_META, type MemoryEntry, type Kind,
} from "@/features/memory/lib/memory";

/** Is this node one of the memory kinds (so it takes a kind colour), or a target stub? */
function isKind(k: string): k is Kind {
  return k in KIND_META;
}

export function MemoryGraphView({ memories, onSelect }: { memories: MemoryEntry[]; onSelect?: (id: string) => void }) {
  const layout = useMemo(() => layoutGraph(buildGraph(memories)), [memories]);
  const vp = useGraphViewport(layout.world);

  return (
    <GraphCanvas
      vp={vp}
      world={layout.world}
      toolbar={
        <Row align="center" gap="sm" className="mem-graph-toolbar">
          <Text as="span" mono className="mem-graph-stat">
            {layout.nodes.length} node{layout.nodes.length === 1 ? "" : "s"} · {layout.edges.length} edge
            {layout.edges.length === 1 ? "" : "s"}
          </Text>
          <ZoomControls vp={vp} />
        </Row>
      }
    >
      {/* Edges first so nodes paint over them. `pointer-events: none` on the layer keeps the canvas
          pan gesture working through the gaps between nodes. */}
      <svg
        className="mem-graph-edges"
        width={layout.world.w}
        height={layout.world.h}
        style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
        aria-hidden="true"
      >
        {layout.edges.map((e, i) => (
          <g key={`${e.from}|${e.rel}|${e.to}|${i}`}>
            <line x1={e.x1} y1={e.y1} x2={e.x2} y2={e.y2} className="mem-edge" />
            {/* The relationship is LABELLED on the edge. `about` and `contradicts` to the same record
                are opposite claims, and an unlabelled line asserts only that they are related. */}
            <text x={(e.x1 + e.x2) / 2} y={(e.y1 + e.y2) / 2 - 4} className="mem-edge-rel" textAnchor="middle">
              {e.rel}
            </text>
          </g>
        ))}
      </svg>

      {layout.nodes.map((n) => (
        <button
          key={n.id}
          type="button"
          data-node
          className="mem-node"
          data-kind={n.kind}
          data-stub={!n.isMemory}
          data-orphan={n.isMemory && n.degree === 0}
          style={{ position: "absolute", left: n.x, top: n.y, width: NODE_W, height: NODE_H }}
          onClick={() => onSelect?.(n.id)}
          title={n.isMemory ? n.label : `${n.kind}: ${n.id}`}
        >
          {/* The type is TEXT on every node, memory or stub. Colour carries no information alone —
              a reader who cannot tell the tones apart must still see which column is which. */}
          <Text as="span" mono className="mem-node-kind">
            {isKind(n.kind) ? KIND_META[n.kind].label.replace(/s$/, "").toLowerCase() : n.kind}
          </Text>
          <Text as="span" className="mem-node-label">{n.label}</Text>
          {n.isMemory && n.degree === 0 && (
            // Named, not merely styled: an edgeless memory is one nothing can traverse to, and that is
            // a state to act on rather than a shade of grey to notice.
            <Text as="span" mono className="mem-node-orphan">no edges</Text>
          )}
        </button>
      ))}
    </GraphCanvas>
  );
}

