// @vitest-environment jsdom
//
// THE DOCBLOCK IS LOAD-BEARING. `vitest.config.ts` splits environments on the `lib/` boundary — a
// `lib/` test is pure logic and gets `node`, because building a jsdom per file cost 890s against 103s
// of actual tests. This one lives in `lib/` and DOES need a DOM: it renders a hook. The config names
// this docblock as the way out, and without it the whole suite fails on `document is not defined`.
// Carried test for `@/features/algorithms/lib/useImplSource`.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, waitFor } from "@testing-library/react";

const loadImplSource = vi.fn();
vi.mock("@/features/algorithms/lib/graphBridge", () => ({ loadImplSource: (id: string) => loadImplSource(id) }));

import { useImplSource } from "@/features/algorithms/lib/useImplSource";

describe("useImplSource", () => {
  beforeEach(() => {
    loadImplSource.mockReset();
    loadImplSource.mockResolvedValue({ code: "fetched body" });
  });

  it("does not fetch when the record already carries its own code", async () => {
    // The packaged seed carries bodies, so the common first paint must cost NOTHING.
    const { result } = renderHook(() => useImplSource("a.ts", "seeded body"));
    expect(result.current).toBe("seeded body");
    await new Promise((r) => setTimeout(r, 0));
    expect(loadImplSource).not.toHaveBeenCalled();
  });

  it("fetches the body for a record the index carries without one", async () => {
    const { result } = renderHook(() => useImplSource("a.ts", undefined));
    await waitFor(() => expect(result.current).toBe("fetched body"));
    expect(loadImplSource).toHaveBeenCalledWith("a.ts");
  });

  it("shows nothing rather than the PREVIOUS record's body while a fetch is in flight", async () => {
    // The bug this ordering exists to prevent: select B, and A's source sits under B's name until the
    // fetch lands. Wrong source attributed to the wrong record is worse than an empty pane.
    const { result, rerender } = renderHook(({ id }) => useImplSource(id, undefined), {
      initialProps: { id: "a.ts" },
    });
    await waitFor(() => expect(result.current).toBe("fetched body"));

    let release: (v: unknown) => void = () => {};
    loadImplSource.mockReturnValue(new Promise((r) => { release = r; }));
    rerender({ id: "b.ts" });
    expect(result.current, "the previous record's body must be gone immediately").toBeUndefined();
    release({ code: "b body" });
    await waitFor(() => expect(result.current).toBe("b body"));
  });

  it("renders nothing when the source cannot be read, rather than throwing", async () => {
    loadImplSource.mockResolvedValue(null);
    const { result } = renderHook(() => useImplSource("a.ts", undefined));
    await new Promise((r) => setTimeout(r, 0));
    expect(result.current).toBeUndefined();
  });

  it("re-fetches when the body's hash moves — a librarian's live edit must land", async () => {
    // The index carries NO bodies, so `codeHash` is the only thing that can tell this hook a body
    // changed. Without it in the deps the pane serves the first body it ever fetched, forever — and a
    // live edit is exactly what the page's 5-second poll exists for.
    const { result, rerender } = renderHook(({ h }) => useImplSource("a.ts", undefined, h), {
      initialProps: { h: "hash-1" },
    });
    await waitFor(() => expect(result.current).toBe("fetched body"));
    expect(loadImplSource).toHaveBeenCalledTimes(1);

    loadImplSource.mockResolvedValue({ code: "edited body" });
    rerender({ h: "hash-2" });
    await waitFor(() => expect(result.current).toBe("edited body"));
  });

  it("does not re-fetch while the hash is unchanged", async () => {
    const { rerender } = renderHook(({ h }) => useImplSource("a.ts", undefined, h), {
      initialProps: { h: "hash-1" },
    });
    await waitFor(() => expect(loadImplSource).toHaveBeenCalledTimes(1));
    rerender({ h: "hash-1" });
    rerender({ h: "hash-1" });
    expect(loadImplSource).toHaveBeenCalledTimes(1);
  });
});

implementations.code:
// useImplSource (#the-algorithms-page-hydrates-fifty-megabytes-every-five-seconds) — the selected
// record's source, fetched on demand.
//
// WHY THIS EXISTS. `graph_dump` used to hand the page every record's `code`: 19.31 MB of a 20.26 MB
// hydrate, MEASURED over 1,401 records, to render the ONE body the inspector shows. When that transfer
// failed, `loadGraph` returned null and the page silently kept the packaged seed — a graph showing 757
// records instead of 1,401, with nothing to say so. The index no longer carries bodies; this asks for
// the one that is on screen.
//
// THE RECORD'S OWN `code` WINS when it has one, and that is not a fallback so much as the common case
// on first paint: the packaged seed DOES carry bodies, so a freshly mounted inspector has source to
// show before any fetch resolves, and the fetch only matters for records the live store has and the
// seed does not.
import { useEffect, useState } from "react";
import { loadImplSource } from "@/features/algorithms/lib/graphBridge";

/** The source to render for `id`.
 *
 *  `seeded` is the record's own `code` when it carries one (the packaged seed does). `codeHash` is the
 *  index's hash of the source — it is in the deps so a LIVE EDIT re-fetches: the index carries no
 *  bodies, so without it a librarian's `bsc graph impl set` would move nothing this hook can see and
 *  the pane would serve the first body it ever fetched, forever. */
export function useImplSource(
  id: string | undefined,
  seeded: string | undefined,
  codeHash?: string,
): string | undefined {
  const [fetched, setFetched] = useState<string | undefined>(undefined);
  useEffect(() => {
    // Clear FIRST, so selecting a record never shows the previous one's body while this resolves.
    setFetched(undefined);
    if (!id || seeded) return;
    let cancelled = false;
    void loadImplSource(id).then((src) => {
      if (!cancelled) setFetched(src?.code ?? undefined);
    });
    return () => {
      cancelled = true;
    };
  }, [id, seeded, codeHash]);
  return seeded ?? fetched;
}

// The graph's DEPTH follows the session mode (`nodes-are-features-and-surfaces`).
//
// # The two node kinds, stated
//
//     a FEATURE node  = a UI the user can interact with
//     a SURFACE node  = logic, and how the AI interacts with it
//
// Both kinds existed before this and neither had a meaning written down, so they had drifted toward
// "the plan's roster" and "the crate's roster" — a description of where the data came from rather
// than of what the node is FOR. Under this reading one graph answers two questions at once: what a
// person can do here, and what an agent can do here. Everything below follows from that split being
// real, because it is what makes a single layer legible at all.
//
// # Why the mode decides how many layers there are
//
// There are three today: the project drill, then a crate sub-layer (its nouns and verbs) and a
// feature sub-layer (its streams). That is the right shape for a LOCAL model and the wrong one for
// Claude, and the reason is the same fact that sets `numCtx`: a local model is markedly more verbose
// and has to split its context far harder. A smaller view per navigation is that split expressed in
// the interface rather than only in a number — so local keeps the sub-layers, and Claude, which can
// hold the project at once, gets one layer and no navigation into a new graph.
//
// # It is a pure function on purpose
//
// A rendering rule you can only check by clicking is one nobody checks. This module is the whole
// decision and takes no store, no graph and no React — the workspace asks it a question and obeys.

/** The session modes a project can be in — the two `bsc session mode` writes. `null` is a project in
 *  neither, which is a real state: a machine with an `openai` provider resolves to no mode at all. */
export type SessionMode = "local" | "claude" | null;

/** The layers below the project drill. Named rather than counted, because "two layers" says nothing
 *  about WHICH two and a caller has to gate them individually. */
export type SubLayer = "crate" | "feature";

/**
 * Whether `layer` opens as its own graph in `mode`.
 *
 * Claude gets ONE layer: selecting a crate or a feature at the project drill does not navigate into a
 * new graph. Local keeps both, unchanged.
 *
 * A NULL MODE KEEPS THE LAYERS, and that direction is deliberate. The two failures are not
 * symmetrical: showing a sub-layer to a session that did not need it costs a click, while hiding
 * navigation from a user who had it removes the only route to a verb node. An unrecognised provider —
 * `openai`, or a machine nobody has configured — is the case that hits it, and degrading to the
 * richer view is the one that cannot strand anybody.
 */
export function opensSubLayer(mode: SessionMode, layer: SubLayer): boolean {
  void layer; // both sub-layers move together today; named so a future mode can split them.
  return mode !== "claude";
}

/**
 * How many graph layers a project has in `mode`, counting the project drill itself.
 *
 * Reported rather than derived at each call site so the answer is one number a test can pin and a
 * caller can show — "1 layer" and "3 layers" is the difference the mode makes, and it should be
 * possible to state it without reading the workspace.
 */
export function layerCount(mode: SessionMode): number {
  return mode === "claude" ? 1 : 3;
}

/** What a node kind IS, for the inspector and for anything that has to explain the graph. */
export const NODE_KIND_MEANING: Record<"feature" | "surface", string> = {
  feature: "a UI the user can interact with",
  surface: "logic, and how the AI interacts with it",
};

