import { describe, it, expect } from "vitest";
import { isLivePane, livePaneIdsIn, liveCountIn } from "@/app/console/lib/livePanes";

const tab = (...paneIds: (string | undefined)[]) => ({ paneIds });

describe("what counts as a live session (one rule, two counters)", () => {
  it("a REAPED pane is not live — the door that was missing", () => {
    // The regression this exists for. A reaped pane is marked dormant and nothing else, so a counter
    // reading only ended/disabled kept offering to kill sessions whose PTY was already gone.
    expect(isLivePane("p:director", { dormantPanes: { "p:director": true } })).toBe(false);
    expect(livePaneIdsIn([tab("p:director", "p:worker")], { dormantPanes: { "p:director": true } }))
      .toEqual(new Set(["p:worker"]));
  });

  it("all three doors take a pane out, and nothing else does", () => {
    const panes = tab("ended", "disabled", "dormant", "live");
    const flags = { endedPanes: { ended: {} }, disabledPanes: { disabled: true }, dormantPanes: { dormant: true } };
    expect(livePaneIdsIn([panes], flags)).toEqual(new Set(["live"]));
    // A pane nothing has stopped is live even with every map present but empty.
    expect(livePaneIdsIn([tab("live")], { endedPanes: {}, disabledPanes: {}, dormantPanes: {} }))
      .toEqual(new Set(["live"]));
  });

  it("counts a pane ONCE however many tabs list it", () => {
    // A total that exceeds the number of sessions that exist is the other way this reads wrong.
    expect(livePaneIdsIn([tab("shared"), tab("shared"), tab("shared", "other")], {}).size).toBe(2);
  });

  it("survives the shapes a real tab actually has", () => {
    // `paneIds` is optional and its entries can be undefined for an empty grid cell — a layout is
    // cols × rows whether or not anything was ever opened in each one.
    expect(livePaneIdsIn([{}], {}).size).toBe(0);
    expect(livePaneIdsIn([tab(undefined, "", "real")], {}).size).toBe(1);
    expect(isLivePane(undefined, {})).toBe(false);
  });

  it("counts ONE tab for the status bar, and no tab is zero rather than a crash", () => {
    const flags = { dormantPanes: { b: true } };
    expect(liveCountIn(tab("a", "b", "c"), flags)).toBe(2);
    expect(liveCountIn(undefined, flags)).toBe(0);
  });
});

implementations.code:
// What counts as a LIVE session — one rule, because two counters that answer it separately will
// disagree and one of them will be wrong.
//
// # The three ways a pane stops, and the one that was missed
//
// A pane leaves the live set by three different doors, and a counter has to know all three:
//
//   · `endedPanes`    — the session EXITED and something classified it (`markPaneEnded`).
//   · `disabledPanes` — the pane was switched off, by the user or the boot GC.
//   · `dormantPanes`  — the backend REAPED it. Its PTY is gone; it resumes when you open it.
//
// The third was missing from Glance's toolbar count, and it is the one that fires most: the idle
// reaper reclaims parked sessions by design. Worse, the first door does not open for every pane —
// `useWorkerAutoEnd` subscribes to `pty_exit_` only for panes whose role is `worker`, so a DIRECTOR's
// exit never sets `endedPanes` at all. MEASURED 2026-09-10: eight parked directors were reaped, every
// one stayed out of `endedPanes`, and "End 8 sessions" offered to kill sessions that were already gone.
//
// # Pure, and taking the flags rather than reading the store
//
// So it can be tested without a store and called from anywhere — Glance is a feature and the status
// bar is app chrome, and neither may import the other's internals.

/** The minimum a tab has to expose for its live panes to be counted. */
export interface LivePaneTab {
  paneIds?: readonly (string | undefined)[];
}

/** The store maps that take a pane OUT of the live set. Each is `paneId -> truthy when stopped`. */
export interface StoppedPaneFlags {
  endedPanes?: Record<string, unknown>;
  disabledPanes?: Record<string, unknown>;
  dormantPanes?: Record<string, unknown>;
}

/** Is this pane id still a live session? */
export function isLivePane(paneId: string | undefined, flags: StoppedPaneFlags): boolean {
  if (!paneId) return false;
  return !flags.endedPanes?.[paneId] && !flags.disabledPanes?.[paneId] && !flags.dormantPanes?.[paneId];
}

/** Every live pane id across these tabs. A SET, because a pane id can appear in more than one tab's
 *  layout and counting it twice is how a total exceeds the number of sessions that exist. */
export function livePaneIdsIn(tabs: readonly LivePaneTab[], flags: StoppedPaneFlags): Set<string> {
  const live = new Set<string>();
  for (const tab of tabs) {
    for (const paneId of tab.paneIds ?? []) {
      if (paneId && isLivePane(paneId, flags)) live.add(paneId);
    }
  }
  return live;
}

/** How many live sessions one tab holds — the number the status bar shows for the tab you are on. */
export function liveCountIn(tab: LivePaneTab | undefined, flags: StoppedPaneFlags): number {
  return tab ? livePaneIdsIn([tab], flags).size : 0;
}

