// ── the restricted spec's "you do not have python" is now ENFORCED ───────────────────────────────
//
// The designer's spec says: "You do **not** have `node`, `python`, `jq` … and reaching for one will
// be refused — not as a mistake, but by design: your shell surface is an allow-list." That was PROSE
// ONLY. Nothing denied an interpreter; it simply was not in the allow-list, so it PROMPTED and was
// approved. Measured on a real session before writing this: 555 Bash calls, 37 of them python, every
// one post-processing `bsc` JSON — and it had run `which python3 node jq` first, so it went looking.
//
// A promise the environment does not keep teaches the opposite of what it says.
describe("roleDeniedCommands — a restricted role has no interpreter", () => {
  const INTERPRETERS = ["python", "python3", "node", "jq"];

  it("denies the interpreters the designer's own spec says it does not have", () => {
    const denies = roleDeniedCommands(roleCapability("designer"));
    for (const prog of INTERPRETERS) {
      expect(denies, `${prog} must be DENIED, not merely un-allowed`).toContain(prog);
    }
  });

  it("leaves a worker's interpreters alone — it legitimately builds and tests", () => {
    const denies = roleDeniedCommands(roleCapability("worker"));
    for (const prog of INTERPRETERS) {
      expect(denies, `${prog} must stay available to a worker`).not.toContain(prog);
    }
  });

  it("applies to every restricted role, not just the designer", () => {
    // The rule is derived from `isRestrictedRole`, so a studio added later inherits it rather than
    // being remembered individually — which is how `designer` ended up the only one of five caged.
    for (const role of Object.values(ROLE_DEFAULTS).map((c) => c.role)) {
      if (restrictedRoleCommands(role).length === 0) continue;
      const denies = roleDeniedCommands(roleCapability(role));
      expect(denies, `${role} is restricted, so it must inherit the interpreter deny`).toContain("python3");
    }
  });

  it("denies them as bare PROGRAM NAMES, so a piped interpreter is caught", () => {
    // `deny_matches` gives a bare name program-token semantics across pipeline segments and recurses
    // into `sh -c`. A `python3 *` prefix rule would have matched NONE of the observed misuse, which
    // was almost entirely `bsc ui get … | python3 -c '…'`.
    const denies = roleDeniedCommands(roleCapability("designer"));
    for (const d of denies.filter((x) => INTERPRETERS.includes(x))) {
      expect(d, "a bare program name, not a prefix pattern").not.toContain(" ");
      expect(d).not.toContain("*");
    }
  });

  it("still leaves the route it is pushing the session TOWARD", () => {
    // The whole point is `bsc request new` instead of a workaround, so that must not be denied —
    // and neither must its own store CLI.
    const denies = roleDeniedCommands(roleCapability("designer"));
    expect(denies).not.toContain("bsc request");
    expect(denies).not.toContain("bsc ui");
  });
});

// The banner must COLLAPSE (`one-stop-banner-per-pane-fills-the-screen`).
//
// `stopBannerCollapse.test.tsx` proves the ordering and summary rules; this proves the thing the
// maintainer actually reported — that N stops no longer render N full-width bars.
import { describe, it, expect, beforeEach, vi } from "vitest";
import { render, screen } from "@testing-library/react";
import { useAppStore } from "@/store";
import type { PaneStop } from "@/app/console/lib/paneStops";
import { AppBanners } from "@/app/AppBanners";

vi.mock("@/shared/hooks/useSandboxReadiness", () => ({ useSandboxReadiness: () => ({ ready: true }) }));

const NOW = Date.now();
const stop = (paneId: string, reason: PaneStop["reason"], lastOutput?: string): PaneStop =>
  ({ paneId, reason, detail: "detail", at: NOW, lastOutput }) as PaneStop;

/** Every rendered status banner, by its role. */
const banners = () => screen.queryAllByRole("status");

beforeEach(() => {
  useAppStore.setState({ paneStops: [], dismissedNotices: [] } as never);
});

describe("many stops render as ONE banner", () => {
  it("collapses six simultaneous stops into a single banner", () => {
    // THE REPORTED BUG: an app relaunch ends every session, and this used to be six full-width bars.
    useAppStore.setState({
      paneStops: ["a", "b", "c", "d", "e", "f"].map((n) => stop(`p:${n}`, "app-closed")),
    } as never);
    render(<AppBanners />);
    expect(banners()).toHaveLength(1);
  });

  it("still names every pane inside that one banner — collapsing is not hiding", () => {
    useAppStore.setState({
      paneStops: ["a", "b", "c"].map((n) => stop(`p:${n}`, "app-closed")),
    } as never);
    render(<AppBanners />);
    for (const n of ["p:a", "p:b", "p:c"]) expect(screen.getByText(new RegExp(n))).toBeTruthy();
  });

  it("keeps a fault's LAST WORDS, which nothing else in the app has", () => {
    // The one thing collapsing must not drop: once the pane is recreated, this output is gone.
    useAppStore.setState({
      paneStops: [stop("p:a", "app-closed"), stop("p:bad", "failed", "panic: boom")],
    } as never);
    render(<AppBanners />);
    expect(banners()).toHaveLength(1);
    expect(screen.getByText(/panic: boom/)).toBeTruthy();
  });

  it("still shows a SINGLE stop the way it always did", () => {
    useAppStore.setState({ paneStops: [stop("p:only", "finished")] } as never);
    render(<AppBanners />);
    expect(banners()).toHaveLength(1);
    expect(screen.getByText(/finished/)).toBeTruthy();
  });

  it("renders nothing when there are no stops", () => {
    render(<AppBanners />);
    expect(banners()).toHaveLength(0);
  });
});

// The Algorithms rail's FOLDER TREE (#4107, brought to components parity by #4128). Before #4107 the
// rail had exactly one level — each LANGUAGE was a folder — so all 50 Rust impls sat flat inside it. It
// now nests the way the Components rail does, from the harvested source layout, through the SAME shared
// `buildFolderTree` + `RailFolderRow` the Designs rail renders — including the folder tooltip
// (`folder: <path>`) and the trailing "ungrouped" bucket.
import { describe, it, expect } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { AlgorithmsRail } from "@/features/algorithms/AlgorithmsRail";
import { UNGROUPED_LABEL } from "@/shared/lib/core/folderTree";
import { buildKnowledge, type AlgoImpl } from "@/features/algorithms/lib/knowledge";

const im = (o: Partial<AlgoImpl> & Pick<AlgoImpl, "id" | "tech" | "name">): AlgoImpl =>
  ({ role: "algorithm", composes: [], ...o });

const noop = () => {};

const foldered = buildKnowledge({
  implementations: [
    im({ id: "job.rs", tech: "rust", name: "attachJob", folder: "src-tauri/src/console/pty" }),
    im({ id: "perf.rs", tech: "rust", name: "sample", folder: "src-tauri/src/observability" }),
  ],
});

const renderRail = (graph: ReturnType<typeof buildKnowledge>) =>
  render(<AlgorithmsRail graph={graph} activeTech="rust" selectedImpl={null} onSelectImpl={noop} />);

describe("AlgorithmsRail folder tree (#4107/#4128)", () => {
  it("nests the harvested folders under the language, tooltipped like the components rail", () => {
    // Sections default to OPEN, so the whole tree is visible without a click. The `folder: ` tooltip
    // prefix is the shared `RailFolderRow`'s — the algorithms rail used a bare path before #4128.
    renderRail(foldered);
    expect(screen.getByTitle("folder: src-tauri")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src/console")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src/console/pty")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src/observability")).toBeInTheDocument();
    // The impls sit inside their folders, not flat under the language.
    expect(screen.getByText("attachJob")).toBeInTheDocument();
    expect(screen.getByText("sample")).toBeInTheDocument();
  });

  it("collapsing a folder hides its whole subtree", () => {
    // What keeps a harvested library (hundreds of impls across dozens of folders) cheap to render.
    renderRail(foldered);
    fireEvent.click(screen.getByTitle("folder: src-tauri/src/observability"));
    expect(screen.queryByText("sample")).toBeNull();
    expect(screen.getByText("attachJob")).toBeInTheDocument();   // its sibling branch is untouched
  });

  it("a collapsed folder still reports how much is inside it", () => {
    renderRail(foldered);
    fireEvent.click(screen.getByTitle("folder: src-tauri"));      // collapse the root
    expect(screen.queryByText("attachJob")).toBeNull();
    // The count is the whole SUBTREE (2), not the root folder's own impls (0) — otherwise a deep tree
    // gives no sense of where the work lives.
    expect(screen.getByTitle("folder: src-tauri").textContent).toContain("2");
  });

  it("buckets unfoldered impls into a trailing `ungrouped` folder, not a flat spill (#4128)", () => {
    // The components rail has always done this; the algorithms rail used to render them loose beside the
    // tree. It matters HERE more than there: the seeded classics carry no `src`, so in the live library
    // the unfoldered set is the majority, and loose rows next to folders read as two competing lists.
    const mixed = buildKnowledge({
      implementations: [
        im({ id: "job.rs", tech: "rust", name: "attachJob", folder: "src-tauri/src/console/pty" }),
        im({ id: "merge.rs", tech: "rust", name: "merge" }),
      ],
    });
    renderRail(mixed);
    const bucket = screen.getByTitle("records with no folder");
    expect(bucket).toBeInTheDocument();
    expect(bucket.textContent).toContain(UNGROUPED_LABEL);
    expect(screen.getByText("merge")).toBeInTheDocument();
    // Collapsing the bucket hides its rows, exactly like any other folder.
    fireEvent.click(bucket);
    expect(screen.queryByText("merge")).toBeNull();
    expect(screen.getByText("attachJob")).toBeInTheDocument();
  });

  it("still lists a WHOLLY unfoldered library flat — no bucket, no blank folder", () => {
    // The zero-regression case: a library that has never been foldered renders as the plain list it
    // always did rather than collapsing under one `ungrouped` node.
    const flat = buildKnowledge({ implementations: [im({ id: "merge.rs", tech: "rust", name: "merge" })] });
    renderRail(flat);
    expect(screen.getByText("merge")).toBeInTheDocument();
    expect(screen.queryByTitle("folder: src-tauri")).toBeNull();
    expect(screen.queryByTitle("records with no folder")).toBeNull();
  });
});

import { describe, it, expect } from "vitest";
import type { ArrayFrame } from "@/features/algorithms/lib/trace";
import { KNOWLEDGE, implById } from "@/features/algorithms/lib/knowledge";
import { runVizProgram } from "@/features/algorithms/viz/examples/vizProgram";
import { resolveVizExample, programVizForImpl } from "./registry";

// Guards the SHIPPED demonstrator (#3213): the seeded `sort.ts` carries a real `vizCode` that OVERRIDES its
// in-app program (both animate a sort). If the seed's vizCode string ever rots (bad JS, wrong shape), this
// fails loudly rather than silently blanking the visualization. Run through the #3233 sandbox path.
describe("seeded sort.ts visualization (#3213 demonstrator)", () => {
  const sort = implById(KNOWLEDGE, "sort.ts");

  it("ships a kind + a non-empty vizCode", () => {
    expect(sort).toBeDefined();
    expect(sort!.kind).toBe("sort");
    expect(sort!.vizCode?.trim()).toBeTruthy();
  });

  it("its stored vizCode compiles + runs the real sort (frames end sorted, swaps recorded)", () => {
    const { datatype, frames } = runVizProgram(sort!.vizCode!);
    expect(datatype).toBe("array");
    expect((frames as ArrayFrame[]).some((f) => f.ops?.some((o) => o.op === "swap"))).toBe(true);
    const last = (frames[frames.length - 1] as ArrayFrame).data as number[];
    expect(last).toEqual([...last].sort((a, b) => a - b)); // ascending — the real algorithm sorted it
  });

  it("resolves through the sandbox to a renderable array example", async () => {
    const viz = (await resolveVizExample(sort!.vizCode!))!;
    expect(viz).toBeDefined();
    expect(viz.renderers.array).toBeDefined();
  });

  it("also has an in-app program under its base name (sort.ts → the `sort` program)", () => {
    // sort.ts is doubly covered: an in-app `sort` program AND its stored vizCode (which useVizForImpl
    // prefers). The program is what shows synchronously before the sandbox resolves the vizCode.
    expect(programVizForImpl({ id: "sort.ts", name: "sort" })?.renderers.array).toBeDefined();
  });
});

// The SHIPPED per-op highlighting (#3250). This is the one path a user actually sees: the seeded
// `sort.ts` vizCode → the sandbox → the stage's code column. It guards both halves — that the seed is
// still multi-line (a one-line program makes the column unreadable) and that its frames carry ranges
// that slice back out as real tracer calls.
describe("seeded sort.ts per-op source highlighting (#3250)", () => {
  const sort = implById(KNOWLEDGE, "sort.ts");

  it("ships a MULTI-LINE program, so the code column is readable", () => {
    expect(sort!.vizCode!.trim().split("\n").length).toBeGreaterThan(5);
  });

  it("every op-frame carries a range that slices out as the tracer call that emitted it", () => {
    const { frames, source } = runVizProgram(sort!.vizCode!);
    const stamped = frames.filter((f) => f.loc);
    expect(stamped.length).toBeGreaterThan(5); // a real trace, not one lucky frame

    for (const frame of stamped) {
      const span = source.slice(frame.loc!.start, frame.loc!.end);
      expect(span).toMatch(/^a\.\w+\(/); // e.g. `a.compare(j - 1, j)` — a call on the traced array
      // The range's reported line must be the line that span actually sits on.
      expect(source.slice(0, frame.loc!.start).split("\n").length).toBe(frame.loc!.line);
    }
  });

  it("highlights the compare and the swap as SEPARATE beats, though both are ops of one inner loop", () => {
    const { frames, source } = runVizProgram(sort!.vizCode!);
    const spans = frames.filter((f) => f.loc).map((f) => source.slice(f.loc!.start, f.loc!.end));
    expect(spans.some((s) => s.startsWith("a.compare("))).toBe(true);
    expect(spans.some((s) => s.startsWith("a.swap("))).toBe(true);
    // Per-op, not per-line: the compare and the swap are on different lines here, and each gets its own
    // beat — consecutive frames never share one range across two distinct ops.
    const compare = frames.find((f) => f.loc && source.slice(f.loc.start, f.loc.end).startsWith("a.compare("));
    const swap = frames.find((f) => f.loc && source.slice(f.loc.start, f.loc.end).startsWith("a.swap("));
    expect(compare!.loc!.start).not.toBe(swap!.loc!.start);
  });

  it("resolves through the sandbox with the source the ranges index into", async () => {
    const viz = (await resolveVizExample(sort!.vizCode!))!;
    expect(viz.source).toBe(sort!.vizCode!.trim());
  });
});

import { describe, it, expect, vi } from "vitest";
import { isPanelsFrame, type ArrayFrame, type PanelsFrame } from "@/features/algorithms/lib/trace";
import { runVizProgram } from "@/features/algorithms/viz/examples/vizProgram";
import { resolveVizExample, programVizForImpl } from "./registry";

// A real bubble sort as a STORED vizCode descriptor (#3232) — the persisted-data form of a trace-program.
const BUBBLE_VIZCODE = `({
  datatype: "array",
  input: [5, 2, 9, 1, 6],
  run(a) {
    for (let i = 0; i < a.length; i++)
      for (let j = 0; j < a.length - i - 1; j++)
        if (a.compare(j, j + 1) > 0) a.swap(j, j + 1);
  },
})`;

// A matrix descriptor, used to prove the datatype → renderer dispatch.
const MATRIX_VIZCODE = `({
  datatype: "matrix",
  input: [[1, 2], [3, 4]],
  run(m) { m.read(0, 0); m.read(1, 1); },
})`;

// A MULTI-STRUCTURE scene descriptor (#3275) — a graph + a "seen" array marched together. Proves a scene
// can be authored + persisted as stored vizCode (not just an in-app program) and run through the sandbox.
const SCENE_VIZCODE = `({
  datatype: "scene",
  input: { nodes: [{ id: "a" }, { id: "b" }, { id: "c" }], edges: [{ from: "a", to: "b" }, { from: "b", to: "c" }] },
  run(scene, input) {
    const g = scene.graph("graph", input);
    const seen = scene.array("seen", [0, 0, 0]);
    g.ids().forEach((id, i) => { g.visit(id); seen.set(i, 1); });
  },
})`;

describe("runVizProgram — the pure compile+run core (#3233)", () => {
  it("runs the real array program (frames end sorted, swaps recorded)", () => {
    const { datatype, frames } = runVizProgram(BUBBLE_VIZCODE);
    expect(datatype).toBe("array");
    expect((frames as ArrayFrame[]).some((f) => f.ops?.some((o) => o.op === "swap"))).toBe(true);
    const last = (frames[frames.length - 1] as ArrayFrame).data as number[];
    expect(last).toEqual([1, 2, 5, 6, 9]);
  });

  it("runs on an overriding input (the 'your input' seam)", () => {
    const { frames } = runVizProgram(BUBBLE_VIZCODE, [4, 3, 2, 1]);
    expect((frames[frames.length - 1] as ArrayFrame).data).toEqual([1, 2, 3, 4]);
  });

  it("dispatches by datatype (matrix descriptor)", () => {
    expect(runVizProgram(MATRIX_VIZCODE).datatype).toBe("matrix");
  });

  it("runs a SCENE descriptor as synchronized panels (#3275)", () => {
    const { datatype, frames } = runVizProgram(SCENE_VIZCODE);
    expect(datatype).toBe("scene");
    expect(frames.every(isPanelsFrame)).toBe(true); // every frame is a multi-panel frame
    const last = (frames[frames.length - 1] as PanelsFrame).panels;
    expect(Object.keys(last).sort()).toEqual(["graph", "seen"]); // both declared panels present
    expect((last.seen as ArrayFrame).data).toEqual([1, 1, 1]); // every node marked seen, in sync with the graph
  });

  it("throws on malformed code", () => {
    expect(() => runVizProgram("({ datatype: 'array', ")).toThrow(/failed to compile/);
  });
});

describe("resolveVizExample — sandbox-run stored vizCode (#3233)", () => {
  it("builds an array example whose factory replays the sandbox-computed sorted frames", async () => {
    const viz = (await resolveVizExample(BUBBLE_VIZCODE))!;
    expect(viz).toBeDefined();
    expect(viz.renderers.array).toBeDefined();
    const frames = [...viz.factory()] as ArrayFrame[];
    expect(frames[frames.length - 1].data).toEqual([1, 2, 5, 6, 9]);
  });

  it("re-runs the program on user input via the async input seam", async () => {
    const viz = (await resolveVizExample(BUBBLE_VIZCODE))!;
    const factory = await viz.input.make(viz.input.parse("4, 3, 2, 1"));
    const last = [...factory()].map((f) => (f as ArrayFrame).data);
    expect(last[last.length - 1]).toEqual([1, 2, 3, 4]);
  });

  it("dispatches datatype → renderer (matrix descriptor → matrix renderer)", async () => {
    const viz = (await resolveVizExample(MATRIX_VIZCODE))!;
    expect(viz.renderers.matrix).toBeDefined();
    expect(viz.renderers.array).toBeUndefined();
  });

  it("builds a SCENE example — every structure renderer registered, panel frames (#3275)", async () => {
    const viz = (await resolveVizExample(SCENE_VIZCODE))!;
    expect(viz).toBeDefined();
    expect(viz.renderers.graph).toBeDefined();
    expect(viz.renderers.array).toBeDefined();
    expect(viz.renderers.tree).toBeDefined(); // a scene may declare ANY structure, so all are registered
    expect([...viz.factory()].every(isPanelsFrame)).toBe(true);
  });

  it("caches by code string (one sandbox run, stable resolved example)", async () => {
    const a = await resolveVizExample(BUBBLE_VIZCODE);
    const b = await resolveVizExample(BUBBLE_VIZCODE);
    expect(a).toBe(b);
  });

  it("resolves to undefined (and warns) for malformed code", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
