// The HANDOFF: RequestSessionsMount → TerminalHost → TerminalView → pty_create.
//
// `RequestSessionsMount`'s own test asserts the charter lands in `paneStartupPromptText`, and stubs
// `TerminalSlot` out entirely — so nothing had ever checked that the charter reaches the LAUNCH. It
// did not. Every debug session in the running app came up as a bare `claude --model sonnet` (three
// argv entries, read from /proc) and sat at an empty prompt with no work, for as long as the feature
// has existed: no session transcript has ever contained the charter's first line.
//
// That is this repo's recurring shape — a green test covering less than its name implies — so the
// guard has to be the seam itself, not either side of it. This file mocks only what jsdom cannot run
// (xterm) and the two external stores (`bsc`, the Tauri bridge); the mount, the host, the slot and the
// view are all real, and the assertion is on the argument `pty_create` actually received.
import { describe, it, expect, beforeAll, beforeEach, afterEach, vi } from "vitest";
import { render, cleanup, waitFor } from "@testing-library/react";
import { TerminalHost } from "@/app/console/terminal/TerminalHost";
import { RequestSessionsMount } from "@/features/debug/RequestSessionsMount";
import { useAppStore } from "@/store";
import { invoke } from "@tauri-apps/api/core";

const REQUEST = { id: 7, status: "open", claimed_by: null, origin: "design-studio:designer-react", display_title: "ui list needs --kit" };
const { queue } = vi.hoisted(() => ({ queue: { rows: [] as (typeof REQUEST)[] } }));

// The queue, modelling the one contract that matters here: `claim` flips the oldest open row and
// returns it, so the mount has a definite id to bind a session to.
vi.mock("@/shared/lib/core/bsc", () => ({
  bscJson: vi.fn(async (_cwd: unknown, args: string[]) => {
    // The GLOBAL gate (`debug-sessions-have-a-global-off-switch`). `bsc request sessions --json`
    // resolves the policy and the pause in Rust and returns `allowed`; a blanket return answers it
    // with the row list, leaving `allowed` undefined — which reads as CLOSED and launches nothing.
    if (args[1] === "sessions") return { enabled: true, paused: false, allowed: true };
    if (args[1] === "claim") {
      const next = queue.rows.find((r) => r.status === "open");
      if (!next) return null;
      next.status = "claimed";
      return next;
    }
    return queue.rows;
  }),
  bsc: vi.fn(async () => ""),
  bscRun: vi.fn(async () => {}),
  bscWrite: vi.fn(async () => {}),
}));
// Run the poll body once, deterministically, rather than on a 20s timer.
// `usePoll` hands its callback an `isCancelled` probe (the mount checks it before writing state after
// an await). A mock that calls `fn()` bare passes `undefined` for it, so the first `isCancelled()`
// throws — the callback never ran, and the test failed for a reason that had nothing to do with it.
vi.mock("@/shared/hooks/usePoll", () => ({
  usePoll: (fn: (isCancelled: () => boolean) => void | Promise<void>) => { void fn(() => false); },
}));
// xterm cannot initialize in jsdom (`open()` needs real measurements).
vi.mock("@xterm/xterm", () => {
  class Terminal {
    cols = 80; rows = 24; options = {}; parser = { registerOscHandler: vi.fn() };
    loadAddon = vi.fn(); open = vi.fn(); write = vi.fn(); scrollToBottom = vi.fn();
    onData = vi.fn(() => ({ dispose: vi.fn() })); focus = vi.fn(); dispose = vi.fn();
    attachCustomKeyEventHandler = vi.fn(); getSelection = vi.fn(() => ""); refresh = vi.fn();
  }
  return { Terminal };
});
vi.mock("@xterm/addon-fit", () => ({ FitAddon: class { fit = vi.fn(); } }));
vi.mock("@xterm/xterm/css/xterm.css", () => ({}));

beforeAll(() => {
  Object.defineProperty(HTMLElement.prototype, "offsetWidth", { configurable: true, value: 800 });
  Object.defineProperty(HTMLElement.prototype, "offsetHeight", { configurable: true, value: 600 });
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => { cb(0); return 0; });
  vi.stubGlobal("ResizeObserver", class { observe() {} unobserve() {} disconnect() {} });
});

beforeEach(() => {
  queue.rows = [{ ...REQUEST }];
  vi.mocked(invoke).mockClear();
  vi.mocked(invoke).mockImplementation(async (cmd: string, payload?: unknown) => {
    if (cmd === "debug_repo_root") return "/repo";
    if (cmd === "pty_pane_runtime") {
      const ids = (payload as { paneIds?: string[] } | undefined)?.paneIds ?? [];
      return ids.map((paneId) => ({ paneId, live: false }));
    }
    if (cmd === "pty_create") return true;
    return "";
  });
  useAppStore.setState({ paneStartupPromptText: {}, paneContinue: {} });
});
afterEach(cleanup);

/** The `pty_create` payload, or undefined if the launch never happened. */
const launch = () => {
  const call = vi.mocked(invoke).mock.calls.find((c) => c[0] === "pty_create");
  return call?.[1] as { startupPrompt?: string; initCmd?: string; cwd?: string; continueSession?: boolean } | undefined;
};

describe("a spawned debug session launches with its charter", () => {
  it("bakes the charter into pty_create, naming the request it was spawned for", async () => {
    render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
    await waitFor(() => {
      const p = launch();
      expect(p, "pty_create was never called — no session launched at all").toBeTruthy();
      // The whole point: a session that reaches claude with no prompt sits at an empty prompt forever,
      // and looks exactly like one that has finished.
      expect(p!.startupPrompt, "launched with NO charter — the session has nothing to do").toBeTruthy();
      expect(p!.startupPrompt).toContain("YOUR REQUEST IS #7");
      // ...and it is THIS request's charter, not a generic "go find work" (#one-request-one-debug-session).
      expect(p!.startupPrompt).toContain("bsc request get 7");
    });
  });

  /// The bug this file was written for, and the assertion that would have caught it first time.
  ///
  /// The charter was reaching `pty_create` all along — and the BACKEND threw it away.
  /// `resolveStartupPromptFreshOnly` returned true for every `debug-studio:` pane, and `plan_launch`
  /// suppresses the prompt when `fresh_only && has_history`. Every debug session runs in the
  /// base-studio-code repo, where claude has always run before, so `has_history` is permanently true:
  /// the charter was dropped on every launch that has ever happened, and the session came up as a
  /// bare `claude` with nothing to do.
  ///
  /// Asserting the payload — not just the prompt — is what makes this a guard rather than a
  /// coincidence: a prompt that is present in the payload and then discarded downstream looks
  /// identical to a working launch from here.
  ///
  /// The FLAG IS GONE (`the-launch-derives-its-own-fresh-only-instead-of-receiving-it`). The frontend
  /// no longer decides; it sends the two facts and the backend derives the rule from them plus its own
  /// studio registry. So the assertion moves with it: send the facts that make the backend DELIVER,
  /// and let `console::pty::tests::the_launch_derives_fresh_only_from_the_facts_it_is_given` prove the
  /// backend does. Asserting the old key here would have gone vacuous rather than red — `undefined`
  /// is not `false`, but a `?? false` would have swallowed exactly that.
  it("does NOT ask the backend to suppress the charter — the launch is fresh, so there is nothing to re-greet", async () => {
    render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
    await waitFor(() => {
      const p = launch() as
        | ({ startupPromptFreshOnly?: boolean; restoreRequested?: boolean; startupPromptIsErrand?: boolean } & Record<string, unknown>)
        | undefined;
      expect(p, "pty_create was never called").toBeTruthy();
      expect(
        p!.startupPromptFreshOnly,
        "the computed flag must not come back — the backend derives it, and a second opinion on the wire is what this whole inversion removes",
      ).toBeUndefined();
      // A per-request session is not a crash restore, and `debug-studio:req-<id>` is not in the studio
      // registry — so these two facts are what make the backend deliver the charter.
      expect(p!.restoreRequested, "a freshly claimed request is not a crash restore").toBe(false);
      expect(typeof p!.startupPromptIsErrand, "the errand fact must be sent, not omitted").toBe("boolean");
    });
  });

  it("launches fresh in the repo, never resuming another conversation (#3497)", async () => {
    render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
    await waitFor(() => {
      const p = launch();
      expect(p?.cwd).toBe("/repo");
      expect(p?.initCmd).toBe("claude");
      expect(p?.continueSession).toBe(false);
    });
  });

  it("carries the charter even when the STORE never got it — the property the prop buys", async () => {
    // The failure this fixes was invisible from either side: the mount wrote the charter, the view read
    // the store, and in production the write never reached the read. Emptying the store mid-flight is
    // the only way to assert that the launch no longer DEPENDS on that route.
    const original = useAppStore.setState;
    const spy = vi.spyOn(useAppStore, "setState").mockImplementation(((...args: Parameters<typeof original>) => {
      const out = original(...args);
      // Whatever the mount wrote, drop it again before anything can read it.
      original({ paneStartupPromptText: {} } as never);
      return out;
    }) as never);
    try {
      render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
      await waitFor(() => {
        expect(useAppStore.getState().paneStartupPromptText).toEqual({});
        const prompt = launch()?.startupPrompt;
        expect(prompt, "the launch still depends on the store — it went out with no charter").toBeTruthy();
        expect(prompt).toContain("YOUR REQUEST IS #7");
      });
    } finally {
      spy.mockRestore();
    }
  });
});

// The frame's REGISTRY contract (#3437 + the navigate-ack fix).
//
// The build effect used to return early on a refused build without touching the iframe or the registry,
// so `registerPreviewFrame` kept naming the LAST component that built. Everything downstream then read a
// mount that was no longer on screen: `bsc debug frames` reported it, and `bsc navigate` acked it — the
// designer saw `navigate plan-body-deployment` succeed while the preview still showed `ui-tab-bar`.
//
// These tests drive the REAL component. They deliberately do not need esbuild: the refused-build path is
// synchronous (`componentPreviewFiles` returns null), which is exactly the path that was silent.
import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { render, waitFor, cleanup } from "@testing-library/react";
// NOTE: the feature barrel is imported FIRST on purpose. `lib/libraryModules` reaches the algorithms
// BARREL, and pulling this component in through a different entry order re-enters that module graph
// mid-initialisation ("algoNodeLookup is not a function") — a known cycle, not a defect in this test.
import "@/features/designs";
import { useAppStore } from "@/store";
import { ComponentPreviewFrame } from "@/features/designs/ComponentPreviewFrame";
import { mountedPreviewFrames, resetPreviewFrames } from "./lib/previewRegistry";
import { recordPreviewError, clearPreviewError } from "./lib/componentBridge";
import type { ComponentRecord } from "@/features/designs/lib/model";

// The bridge shells out to `bsc`; only WHETHER the two error verbs were called matters here. PARTIAL
// mock — the module is the Studio's whole `bsc` surface and the frame's siblings import the rest of it,
// so replacing it wholesale breaks unrelated modules at import time.
vi.mock("./lib/componentBridge", async (importOriginal) => ({
  ...(await importOriginal<typeof import("./lib/componentBridge")>()),
  recordPreviewError: vi.fn(async () => {}),
  clearPreviewError: vi.fn(async () => {}),
}));

/** A record whose `srcText` is a usage SNIPPET, not a runnable module — `componentPreviewFiles` returns
 *  null for it, which is the refused-build path. */
const snippet = (id: string): ComponentRecord => ({
  id, name: id, kitId: "test-kit", role: "primitive", version: "1.0.0", used: 0,
  tags: [], variants: ["default"], composes: [], props: [], whenUse: [], whenNot: [],
  src: `test-kit/${id}.tsx`, srcText: `<${id} label="hi" />`,
});

const frameProps = { theme: "dark" as const, themeId: "default", themeVars: {}, width: 200 };

describe("ComponentPreviewFrame — the registry never names a component that is not on screen", () => {
  beforeEach(() => {
    resetPreviewFrames();
    useAppStore.setState({ kits: [{ id: "test-kit", name: "Test" }], components: [] } as never);
  });
  afterEach(() => cleanup());

  it("registers a REFUSED build under the component it refused, with the reason", async () => {
    render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);

    await waitFor(() => expect(mountedPreviewFrames()).toHaveLength(1));
    const [f] = mountedPreviewFrames();
    expect(f.component).toBe("achievements");
    expect(f.status).toBe("error");
    expect(f.error).toContain("no implementation source yet");
  });

  it("REPRODUCER: switching to a component that cannot build stops reporting the previous one", async () => {
    const { rerender } = render(<ComponentPreviewFrame comp={snippet("ui-tab-bar")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()).toHaveLength(1));

    rerender(<ComponentPreviewFrame comp={snippet("plan-body-deployment")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()[0]?.component).toBe("plan-body-deployment"));
    // The old entry is REPLACED, not accumulated — one frame, one truth.
    expect(mountedPreviewFrames()).toHaveLength(1);
    expect(mountedPreviewFrames().map((f) => f.component)).not.toContain("ui-tab-bar");
  });

  it("leaves nothing of the previous component rendered underneath the error overlay", async () => {
    const { container, rerender } = render(<ComponentPreviewFrame comp={snippet("a")} {...frameProps} />);
    const iframe = container.querySelector("iframe")!;
    iframe.srcdoc = "<html><body>the PREVIOUS component</body></html>";

    rerender(<ComponentPreviewFrame comp={snippet("b")} {...frameProps} />);
    // A capture that photographs the iframe must not find the component that is no longer selected.
    await waitFor(() => expect(iframe.srcdoc).toBe(""));
  });
});

// #45/#60: the error record is written on a failed render and must be RETIRED on a successful one.
// Without the success half, a component fixed by a change elsewhere — a shared dependency, or a resolver
// bug in the preview itself — kept its `render-error` finding forever, and `bsc ui doctor` reported a
// failure that a live `bsc shot preview` disproved. Measured right after the barrel-resolution fix:
// components that mounted fine still carried 54 findings between them.
describe("ComponentPreviewFrame — a render that succeeds retires the recorded error", () => {
  beforeEach(() => {
    resetPreviewFrames();
    vi.mocked(clearPreviewError).mockClear();
    vi.mocked(recordPreviewError).mockClear();
    useAppStore.setState({ kits: [{ id: "test-kit", name: "Test" }], components: [] } as never);
  });
  afterEach(() => cleanup());

  /** Post a preview signal AS the frame's own iframe, which is the only source it accepts (#2908). */
  const post = (container: HTMLElement, data: unknown) => {
    const iframe = container.querySelector("iframe") as HTMLIFrameElement;
    window.dispatchEvent(new MessageEvent("message", { data, source: iframe.contentWindow }));
  };

  it("REPRODUCER: clears the recorded error when the preview reports ready", async () => {
    const { container } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    post(container, { __preview: "ready" });
    await waitFor(() => expect(vi.mocked(clearPreviewError)).toHaveBeenCalledWith("achievements"));
    expect(vi.mocked(recordPreviewError)).not.toHaveBeenCalled();
  });

  it("still RECORDS on a runtime error, and does not clear", async () => {
    const { container } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    post(container, { __preview: "error", message: "boom" });
    await waitFor(() => expect(vi.mocked(recordPreviewError)).toHaveBeenCalledWith("achievements", "boom"));
    expect(vi.mocked(clearPreviewError)).not.toHaveBeenCalled();
  });

  it("ignores a ready from ANOTHER window, so a concurrent scan probe cannot clear this component", () => {
    render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    // #2908: the on-visit scan runs its own hidden probe iframes; their messages must not be honoured.
    window.dispatchEvent(new MessageEvent("message", { data: { __preview: "ready" }, source: window }));
    expect(vi.mocked(clearPreviewError)).not.toHaveBeenCalled();
  });

  // #126: `srcdoc` reassignment does not synchronously replace the iframe's document — the outgoing one
  // (a pending timer, a late async throw) keeps running until the new one loads, and the SAME reused
  // `<iframe>`'s `contentWindow` cannot tell that leftover apart from the current build by source alone.
  // Live symptom: a designer navigating rapidly between graph-hosted pages (fleetpage/mcppage) saw an
  // unrelated earlier build's `SecurityError`/`STARTER_KIT is undefined` attributed to whichever page was
  // current when the stale message finally arrived (designer request #126).
  it("STALE-BUILD GUARD: a message tagged with an earlier generation is dropped even from this frame's own iframe window", async () => {
    const { container, rerender } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()[0]?.component).toBe("achievements")); // build #1 settles

    rerender(<ComponentPreviewFrame comp={snippet("plan-body-deployment")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()[0]?.component).toBe("plan-body-deployment")); // build #2

    // A message from build #1's still-finishing document, arriving after build #2 has already started —
    // it carries build #1's generation, and must not be attributed to the CURRENTLY selected component.
    post(container, { __preview: "error", message: "stale — from the torn-down previous build", __gen: 1 });
    expect(vi.mocked(recordPreviewError)).not.toHaveBeenCalled();

    // The CURRENT build's own message (generation 2) is still honoured.
    post(container, { __preview: "error", message: "the real error", __gen: 2 });
    await waitFor(() =>
      expect(vi.mocked(recordPreviewError)).toHaveBeenCalledWith("plan-body-deployment", "the real error"),
    );
  });

  it("a message carrying no __gen at all (a caller that never set buildGen) is still honoured", async () => {
    const { container } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    post(container, { __preview: "ready" });
    await waitFor(() => expect(vi.mocked(clearPreviewError)).toHaveBeenCalledWith("achievements"));
  });
});

