// #4062 — the L0 project node's LIFECYCLE chip, and the drift guard over the three places the
// vocabulary is written down.
//
// The chip is a second attempt: #4052 deleted the first one because it ALWAYS produced a value
// (`resolveProjectCategory` ended in `isDraft ? greenfield : maintain`), so every unclassified project
// wore a confident label. The no-default rule is therefore the load-bearing assertion here, not a
// nicety — if it regresses, the axis is dead again in exactly the same way.
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
// Through the MERGED loader (`epic-retire-json-ledgers-for-db-and-git-drivers`): records live
// in a DATABASE that `graph/store.toml` names, so a spelled path resolves to nothing and a
// `readFileSync` of it cannot be parsed at all.
import { readFileSync } from "node:fs";
import { loadStore, resolveStorePath } from "@scripts/lib/recordStore.mjs";
import { join } from "node:path";
import { GlanceCanvas, GlanceOverlays } from "@/features/glance/GlanceCanvas";
import { buildGraph, LIFECYCLE_META } from "@/features/glance/lib/glanceGraph";
import { LIFECYCLES } from "@/features/planner/lib/classifyConfig";

/** Mount the canvas over one project node. `fleet` switches to the L1 (drill) shape. */
function renderGraph(node: Parameters<typeof buildGraph>[0][number], fleet = false) {
  const model = buildGraph([node], []);
  return render(
    <GlanceCanvas
      model={model}
      dragMoved={{ current: false }}
      focus={null}
      selNodeId={null}
      selEdgeId={null}
      onHoverNode={() => {}}
      onHoverEdge={() => {}}
      onSelectNode={() => {}}
      onSelectEdge={() => {}}
      fleet={fleet}
    />,
  );
}

const project = { id: "p", slug: "Payments", role: "service" as const, health: "healthy" as const, activity: "idle" as const };

describe("the L0 lifecycle chip (#4062)", () => {
  it("renders the discovered lifecycle on a classified project", () => {
    const { container } = renderGraph({ ...project, lifecycle: "harvest" });
    expect(container.textContent).toContain("harvest");
  });

  it("renders NOTHING for an UNCLASSIFIED project — no default, no `role` fallback", () => {
    // The whole reason #4052 deleted the previous chip. A defaulted label is a lie that looks like
    // data, and `role` would resurrect the hash-per-id microservices tier the chip replaced.
    const { container } = renderGraph(project);
    for (const key of Object.keys(LIFECYCLE_META)) {
      expect(container.textContent, `unclassified node must not read "${key}"`).not.toContain(key);
    }
    expect(container.textContent).not.toContain("SERVICE");
  });

  it("ignores an UNKNOWN lifecycle token rather than rendering it raw", () => {
    // A planner writing a value this build does not know about must degrade to no chip, not paint a
    // colourless label with an undefined accent.
    const { container } = renderGraph({ ...project, lifecycle: "sideways" });
    expect(container.textContent).not.toContain("sideways");
  });

  it("the legend keys EVERY lifecycle the nodes can paint (#4066)", () => {
    // The legend rows are derived from LIFECYCLE_META, so this is really a guard on that derivation
    // surviving a refactor into a hand-maintained list — which is how a legend silently stops
    // explaining a colour that is still on screen.
    render(<GlanceOverlays />);
    for (const m of Object.values(LIFECYCLE_META)) {
      expect(screen.getByText(m.label), `legend must key "${m.label}"`).toBeTruthy();
    }
  });

  it("gives every lifecycle its OWN accent, distinct from the health palette", () => {
    const colors = Object.values(LIFECYCLE_META).map((m) => m.color);
    expect(new Set(colors).size).toBe(colors.length);          // no two lifecycles share a hue
    for (const c of colors) expect(c).toContain("--graph-lifecycle-");  // never a health token
  });
});

describe("the lifecycle vocabulary is written down three times — keep them in lockstep", () => {
  // `plandb` COMPILES FROM THE GRAPH now (`plandb-compiles-from-the-graph`), so
  // `crates/plandb/src/validate.rs` no longer exists — the module is the record `plandb--validate--mod.rs`
  // in the repo store, which is what `crates/graph-materialize/build.rs` materializes for the
  // compiler. Reading the store is the same evidence this assertion always wanted, taken one step
  // closer to the source of truth; reading the file would now be reading nothing at all. Same move,
  // and the same reasoning, as `recordResolvers.test.ts` made for `bsc-ui--emit.rs`.
  const store = loadStore(resolveStorePath()) as { implementations?: { id?: string; code?: string }[] };
  const impls = store.implementations ?? [];
  // NON-VACUITY, twice over: a store that parsed to nothing, or a record that has been renamed, must
  // fail LOUDLY here rather than leaving `rust` an empty string — which would make the LIFECYCLES
  // regex below report "not found in validate.rs" and send the next reader hunting a deleted file.
  expect(impls.length).toBeGreaterThan(100);
  const validate = impls.find((i) => i.id === "plandb--validate--mod.rs")?.code;
  expect(validate, "no `plandb--validate--mod.rs` record in the committed store").toBeTypeOf("string");
  const rust = validate as string;
  const directive = readFileSync(join(process.cwd(), "src-tauri/data/stages/discovery.json"), "utf8");

  it("the Rust validator accepts exactly the TS `LIFECYCLES`", () => {
    // `bsc plan classify set` rejects an unknown token, so a value the app can render but the CLI
    // refuses (or the reverse) is a silently broken write path.
    const declared = rust.match(/pub const LIFECYCLES: \[&str; (\d+)\] = \[([^\]]+)\]/);
    expect(declared, "LIFECYCLES not found in validate.rs").toBeTruthy();
    const tokens = [...declared![2].matchAll(/"([a-z]+)"/g)].map((m) => m[1]);
    expect(tokens.sort()).toEqual([...LIFECYCLES].sort());
    expect(Number(declared![1]), "the array length must match its contents").toBe(tokens.length);
  });

  it("every lifecycle has a chip entry — a value with no meta renders blank", () => {
    expect(Object.keys(LIFECYCLE_META).sort()).toEqual([...LIFECYCLES].sort());
  });

  it("the discovery directive names every lifecycle, or the planner never writes it", () => {
    // The directive is the ONLY thing that tells the planner these values exist. A token missing here
    // is a token no project will ever carry — which is how the first lifecycle axis starved.
    for (const l of LIFECYCLES) {
      expect(directive, `discovery.json must offer \`${l}\``).toContain(`\`${l}\``);
    }
  });

  it("keeps `harden` and `transform` from overlapping (#4064)", () => {
    // `studio-code` was classified `harden` — a restructure, not a security pass. The old wording,
    // "improve an existing codebase in place", covered almost any work on an existing repo, so it
    // competed with `transform` and won on anything short of a full rewrite. The directive must now
    // say what `harden` actually is and which way to break the tie.
    expect(directive).toMatch(/SECURITY \/ ROBUSTNESS \/ RELIABILITY pass/);
    expect(directive, "the tie-break must be explicit").toMatch(/could read as both `transform` and `harden`/);
    expect(directive).not.toContain("improve an existing codebase in place");
  });
});

// #architect-wires-project-relationships — Glance re-reads the contracts when it mounts.
//
// `projectLinks` is a write-through cache whose only authoritative read used to be boot, which was
// correct while the app was the sole writer of `project-links.json`. The architect now edits contracts
// through `bsc project link` from its own session, and that write has no route back into zustand — so
// without a re-read, a relationship the user just asked the architect for stays invisible until the app
// restarts. That failure mode is the reason this test exists: it does not look like a stale view, it
// looks like the command did nothing.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, waitFor } from "@testing-library/react";
import { useAppStore } from "@/store";
import * as bridge from "@/features/glance/lib/projectLinksBridge";
import type { ProjectLink } from "@/features/glance/lib/projectLinks";

// Same viewport stub the other GlanceWorkspace tests use — jsdom does no layout measurement.
vi.mock("@/shared/ui/layouts/useGraphViewport", async (orig) => {
  const actual = await orig<typeof import("@/shared/ui/layouts/useGraphViewport")>();
  return {
    ...actual,
    useGraphViewport: () => ({
      view: { tx: 0, ty: 0, scale: 1 },
      setVp: () => {}, onCanvasDown: () => {}, fit: () => {}, centerOn: () => {},
      zoomBy: () => {}, zoomTo: () => {}, zoomToCentered: () => {},
      dragMoved: { current: false }, worldTransform: {},
    }),
  };
});

import { GlanceWorkspace } from "@/features/glance/GlanceWorkspace";

/** A contract the ARCHITECT wrote from its session — present in the store, absent from the cache. */
const authored: ProjectLink[] = [{ id: "app>billing:api", from: "app", to: "billing", kind: "api" }];

describe("Glance re-reads the project relationships on mount (#architect-wires-project-relationships)", () => {
  beforeEach(() => {
    useAppStore.setState({
      localDraftProjects: {
        app: { title: "App", pitch: "", createdAt: 1 },
        billing: { title: "Billing", pitch: "", createdAt: 1 },
      },
      triagedProjects: { app: 1, billing: 1 },
      // The stale cache: the app has never seen the contract the architect just wrote.
      projectLinks: [], githubToken: "", githubState: null, glanceDrill: {}, tabs: [], bscBaseDir: "/base",
    });
  });

  it("picks up a contract written outside the app, without a restart", async () => {
    const load = vi.spyOn(bridge, "loadProjectLinks").mockResolvedValue(authored);
    render(<GlanceWorkspace />);
    expect(load).toHaveBeenCalled();
    await waitFor(() => expect(useAppStore.getState().projectLinks).toEqual(authored));
  });

