// L0 is scoped to its network, and the architect OPENS rather than DRILLS.
//
// Asserted against the shipped records, because those are what mount — and because the two claims here
// were each false in a way no unit test noticed before: the graph drew every project on every tab, and
// the architect drilled into a team graph that ignored which architect had been clicked.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { architectNodeId } from "@/features/glance/lib/glanceGraph";
import { studioPaneIdForNode } from "@/features/glance/lib/studioProject";
import { decideExpand } from "@/features/glance/lib/expandNode";

const GLANCE: string = JSON.parse(
  readFileSync("src-tauri/data/components/app/features/glance/glancepage.json", "utf8"),
).srcText;
const IMPLS = JSON.parse(
  readFileSync("src-tauri/data/knowledge/algorithms.json", "utf8"),
).implementations as { id: string; code: string }[];
const STUDIO_PROJECT = IMPLS.find((i) => i.id === "studio-project.ts")!.code;

describe("a network architect node resolves to its own session", () => {
  it("maps `architect:network-<slug>` to the pane `network-<slug>:architect`", () => {
    // The id `bsc session stop` also names, and the one Rust derives the workspace directory from. If
    // this drifts, the session still launches and still runs — it is merely unreachable and unwatchable.
    expect(studioPaneIdForNode(architectNodeId("network-kitchen"))).toBe("network-kitchen:architect");
    expect(studioPaneIdForNode(architectNodeId("network-finance"))).toBe("network-finance:architect");
  });

  it("leaves a non-network architect node alone", () => {
    // A persona-shaped architect id is not a network and must not mint a pane that no store backs.
    expect(studioPaneIdForNode(architectNodeId("persona-architect"))).toBeNull();
  });
});

describe("L0 is scoped to the active network tab", () => {
  it("filters the project list by the tab's network", () => {
    expect(GLANCE).toMatch(/allProjects\.filter\(\(p\) => p\.network === networkTab\.id\)/);
  });

  it("keeps `All projects` unfiltered, and gives it no architect node", () => {
    // No single architect owns everything; inventing one there would draw an edge nobody could act on.
    expect(GLANCE).toMatch(/networkTab \? \[\{ id: networkTab\.id/);
    expect(GLANCE).toMatch(/: \[\]\),/);
  });

  it("edges the tab's projects to the NETWORK as their architect", () => {
    // `architect` on a ProjectLite means "which architect node this edges to" — an id that is now a
    // network id. The per-project persona column is the older answer and no longer what the graph draws.
    expect(GLANCE).toMatch(/architect: networkTab\.id/);
  });
});

describe("the architect opens its session instead of drilling", () => {
  it("clicks through to `expandNode`, not `setDrill`", () => {
    expect(GLANCE).toMatch(/else if \(isArchitectNodeId\(id\)\) expandNode\(id\)/);
  });

  it("can never be a drill target, however the value arrived", () => {
    // `glanceDrill` is restored by the app-wide nav history and reachable by `bsc navigate`, so a drill
    // recorded before this change would land on a branch that no longer exists. Guarding at the source
    // is what makes the removed branch genuinely dead rather than merely unlikely.
    expect(GLANCE).toMatch(/isArchitectNodeId\(rawDrill\) \? null : rawDrill/);
  });

  it("removed the drill branch rather than leaving it unreachable", () => {
    // The IMPORT is the signal, not the identifier: the two remaining mentions are comments recording
    // why the branch went, which is exactly the kind of prose that should survive a deletion. An
    // unused import would not compile, so its absence is what proves nothing calls it.
    expect(GLANCE).not.toMatch(/^import[^;]*buildArchitectFleetData/m);
    expect(GLANCE).not.toMatch(/return buildArchitectFleetData/);
  });
});

describe("the two competing stories about the architect are resolved", () => {
  it("no longer claims there is no architect persona to assign a project to", () => {
    // This sentence was live in `studioProject` at the same time as the persona-ownership machinery in
    // `glanceData` — two stories contradicting each other, both true once. The architect is per NETWORK.
    expect(STUDIO_PROJECT).not.toMatch(/There is no architect persona to assign a project to any/);
    expect(STUDIO_PROJECT).toMatch(/THE ARCHITECT IS PER NETWORK/);
  });
});

/** The body of `expandNode` as SHIPPED, from its arrow head to the matching two-space `};`. Sliced
 *  rather than regexed whole so the assertions below can talk about ORDER, which is what was wrong. */
function expandNodeBody(src: string): string {
  const start = src.indexOf("const expandNode = (id: string) => {");
  const end = src.indexOf("\n  };", start);
  return start < 0 || end < 0 ? "" : src.slice(start, end);
}

describe("expandNode admits a STUDIO node that has no drill — the L0 architect", () => {
  // THE BUG THIS PINS. `expandNode` opened with an unconditional `if (!drill) return;`, and
  // `onNodeClick` routes the architect into it from the `else` of `if (drill)` — i.e. only at L0,
  // where `drill` is null by definition. So the call bailed on its first line and the click did
  // nothing, on every network tab, while the session sat warm and reachable in its
  // `NetworkArchitectMount`.
  //
  // "clicks through to `expandNode`, not `setDrill`" above passed the whole time it was broken: it
  // proved the CALL SITE existed, never that the call did anything. Order is the property that was
  // wrong, so order is what these assert.
  const body = expandNodeBody(GLANCE);

  it("finds the function at all", () => {
    expect(body, "expandNode's body must be sliceable, or the rest of this block proves nothing")
      .not.toBe("");
  });

  it("does not bail before it knows whether the node is app-owned", () => {
    const decides = body.indexOf("const isStudio =");
    const guards = body.indexOf("if (!isStudio && !drill) return;");
    expect(decides).toBeGreaterThanOrEqual(0);
    expect(guards, "the drill guard must come AFTER isStudio is known").toBeGreaterThan(decides);
  });

  it("has no unconditional drill guard as its first statement", () => {
    expect(body).not.toMatch(/=> \{\s*\n\s*if \(!drill\) return;/);
  });

  it("still refuses a FLEET node with no drill — the guard narrowed, not removed", () => {
    // The fleet path's pane id is `fleetPaneId(drill, id)`, so without a drill there is nothing to
    // expand. Deleting the guard outright would trade a dead click for a bad pane id.
    expect(body).toMatch(/if \(!isStudio && !drill\) return;/);
  });
});

describe("a studio node's expansion never reads the drill", () => {
  it("resolves to a morph or a select — both return before the fleet path", () => {
    // This is WHY the narrowed guard is safe: an app-owned node's action is decided without a drill,
    // and both outcomes return from the switch before anything reads one.
    // The three fleet fields are required by the type and IGNORED when `isAppOwnedSession` is true —
    // set to the values that would send a FLEET node down the resume path, so the assertion is that
    // app-ownership wins over them rather than that they happened to be benign.
    const fleet = { paneIsLive: true, paneIsComplete: false, canResumeInPlace: true };
    expect(decideExpand({ isAppOwnedSession: true, studioMorphs: true, ...fleet }).kind)
      .toBe("studio-morph");
    expect(decideExpand({ isAppOwnedSession: true, studioMorphs: false, ...fleet }).kind)
      .toBe("select");
  });
});

// The WHOLE chain, end to end (#4118) — real fleet shape → progress → buildGraph → the node.
//
// Every layer was verified in isolation and the bars still did not appear, twice. That is the signature
// of a JOIN that fails silently: each half is correct and the keys do not meet. This asserts the join.
import { describe, it, expect } from "vitest";
import { fleetPlanProgress } from "@/features/glance/lib/fleetPlanProgress";
import { withStreamProgress } from "@/features/glance/lib/streamProgress";
import { buildRealFleetData } from "@/features/glance/lib/glanceFleet";
import { buildGraph } from "@/features/glance/lib/glanceGraph";
import { fleetToOrg } from "@/features/glance/lib/glanceFleet";

// The live shape: streams carrying GitHub refs, exactly as `bsc plan fleet get` returns them.
const fleet = {
  streams: [
    { id: "cli-platform", name: "CLI", repo: "kev/app", owns: [], issues: ["#3898", "#3979"], dependsOn: [] },
    { id: "console", name: "Console", repo: "kev/app", owns: [], issues: ["#3871"], dependsOn: [] },
    { id: "standing", name: "Standing", repo: "kev/app", owns: [], issues: [], dependsOn: [] },
  ],
  director: { enabled: true },
} as unknown as Parameters<typeof fleetToOrg>[0];

describe("progress reaches the rendered node (#4118)", () => {
  it("a fleet node's id IS its stream id — the join the whole feature rests on", () => {
    // If these ever diverge, every lookup misses and the bars vanish with nothing failing.
    const org = fleetToOrg(fleet);
    const ids = org.positions.map((p) => p.nodeId);
    expect(ids).toContain("cli-platform");
    expect(ids).toContain("console");
  });

  it("carries done/total from the stream refs all the way onto the built graph node", () => {
    const byStream = fleetPlanProgress(fleet.streams, new Set(["3898", "3871"]));
    const raw = withStreamProgress(buildRealFleetData(fleet, []).rawNodes, byStream);
    const graph = buildGraph(raw, []);

    const cli = graph.nodes.find((n) => n.id === "cli-platform");
    expect(cli?.progress).toEqual({ done: 1, total: 2 });
    const console_ = graph.nodes.find((n) => n.id === "console");
    expect(console_?.progress).toEqual({ done: 1, total: 1 });
  });

  it("a stream owning nothing reaches the node with total 0, so it draws no bar", () => {
    const byStream = fleetPlanProgress(fleet.streams, new Set());
    const raw = withStreamProgress(buildRealFleetData(fleet, []).rawNodes, byStream);
    const graph = buildGraph(raw, []);
    expect(graph.nodes.find((n) => n.id === "standing")?.progress).toEqual({ done: 0, total: 0 });
  });

  it("buildGraph does not DROP progress while mapping raw nodes to graph nodes", () => {
    // The spread at the node construction is load-bearing; an explicit field list would silently lose it.
    const raw = withStreamProgress(
      buildRealFleetData(fleet, []).rawNodes,
      fleetPlanProgress(fleet.streams, new Set(["3898"])),
    );
    expect(raw.some((n) => n.progress)).toBe(true);
    expect(buildGraph(raw, []).nodes.some((n) => n.progress)).toBe(true);
  });
});

// REPOSITORY GROUPS (#nodes-are-grouped-by-repository) — a fleet drill stacks its nodes into one
// full-width horizontal band per repo, so a project with two codebases reads as two groups rather than
// one interleaved mass.
//
// This groups data that already exists: every fleet stream carries a `repo` and `bsc plan fleet set`
// validates it as required, so nothing new has to be maintained for the grouping to stay true. The gap
// it closes was purely that `repo` never reached the graph — `GRawNode` had no field for it.
//
// A SEPARATE FILE rather than appended to the record's carried test: `bsc graph tests set` was removed
// from the binary (the verb is now `tests harvest <dir>`, which carries a COLOCATED file onto its node),
// and `glanceGraph` has no file to colocate with. An on-disk test is the pattern the other record-backed
// glance modules already use.
import { describe, it, expect } from "vitest";
import { buildGraph, NW, NH, type GRawNode, type GRawEdge } from "@/features/glance/lib/glanceGraph";
import { withStreamRepos } from "@/features/glance/lib/glanceFleet";

const n = (id: string, repo?: string): GRawNode =>
  ({ id, role: "service", health: "off", activity: "idle", ...(repo ? { repo } : {}) });

const BASE = "kevinthelago/base-studio-code";
const MOBILE = "kevinthelago/mobile-studio-code";

describe("buildGraph — repository groups", () => {
  it("draws one band per repo, labelled with the BARE repo name", () => {
    const m = buildGraph([n("a", BASE), n("b", MOBILE)], []);
    // The owner is identical on every band in a project, so repeating it costs width and distinguishes
    // nothing — the band carries the full `owner/name` as its identity and prints only the name.
    expect(m.repoBands?.map((b) => b.label)).toEqual(["base-studio-code", "mobile-studio-code"]);
    expect(m.repoBands?.map((b) => b.repo)).toEqual([BASE, MOBILE]);
  });

  it("orders bands by FIRST APPEARANCE, not alphabetically", () => {
    // The plan's own stream order is roughly build order and is meaningful; sorting by name would
    // reshuffle it for no reason a reader could see.
    const m = buildGraph([n("a", MOBILE), n("b", BASE)], []);
    expect(m.repoBands?.map((b) => b.repo)).toEqual([MOBILE, BASE]);
  });

  it("puts every node inside its own band's zone, and the bands never overlap", () => {
    const m = buildGraph([n("a", "o/one"), n("b", "o/one"), n("c", "o/two")], []);
    const band = (repo: string) => m.repoBands!.find((b) => b.repo === repo)!;
    for (const node of m.nodes) {
      const b = band(node.repo!);
      expect(node.y).toBeGreaterThanOrEqual(b.y0);
      expect(node.y + NH).toBeLessThanOrEqual(b.y1);
    }
    expect(band("o/one").y1).toBeLessThan(band("o/two").y0);
  });

  it("puts the bands to the RIGHT of everything ungrouped, not below it", () => {
    // The architect, the peer directors, the system sessions and the debug sessions are project-scoped,
    // not repo-scoped. Filing one under a repo would be an invented fact, so they keep their own zone.
    //
    // BESIDE, not beneath — the first attempt stacked the bands under the tier, which implied the repos
    // hang off the architect the way a debug session hangs off its spawner. They are not subordinate to
    // it: the tier is who is working, the bands are the codebases they work in.
    const m = buildGraph([n("architect"), n("a", "o/one"), n("b", "o/two")], []);
    const arch = m.nodes.find((x) => x.id === "architect")!;
    for (const b of m.repoBands!) expect(b.x0).toBeGreaterThan(arch.x + NW);
    for (const node of m.nodes.filter((x) => x.repo)) expect(node.x).toBeGreaterThan(arch.x + NW);
  });

  it("starts the first band level with the top of the graph, so it reads beside the tier", () => {
    const m = buildGraph([n("architect"), n("a", "o/one"), n("b", "o/two")], []);
    const top = Math.min(...m.nodes.map((x) => x.y));
    expect(m.repoBands![0].y0).toBeLessThanOrEqual(top);
  });

  it("draws NO bands for a single repo — one band around everything states nothing", () => {
    expect(buildGraph([n("a", "o/one"), n("b", "o/one")], []).repoBands).toBeUndefined();
  });

  it("leaves a graph with no repos at all untouched — the L0 project network", () => {
    // L0's nodes are PROJECTS and carry no repo, so the project map cannot regress through this path.
    const nodes: GRawNode[] = [n("core"), n("api"), n("web")];
    const edges: GRawEdge[] = [{ from: "web", to: "api", kind: "api" }, { from: "api", to: "core", kind: "data" }];
    const m = buildGraph(nodes, edges);
    expect(m.repoBands).toBeUndefined();
    expect(m.nodes.map((x) => [x.id, x.x, x.y])).toEqual(buildGraph(nodes, edges).nodes.map((x) => [x.id, x.x, x.y]));
  });

  it("WRAPS a wide layer instead of stacking it, so the band's height is bounded", () => {
    // THE REASON THIS EXISTS. A fleet's layers are lopsided — base-studio-code's 30 streams fall into 5
    // layers of which ONE holds 16 — and a layer laid out as a single column makes the band as tall as
    // its widest layer, not as tall as its depth. 16 rows is ~1630px for one band alone.
    const many = Array.from({ length: 16 }, (_, i) => n(`w${i}`, "o/one"));
    const m = buildGraph([n("architect"), ...many, n("z", "o/two")], []);
    const band = m.repoBands!.find((b) => b.repo === "o/one")!;
    const rows = new Set(m.nodes.filter((x) => x.repo === "o/one").map((x) => x.y));
    expect(rows.size).toBeLessThanOrEqual(6);          // wrapped, not stacked 16 deep
    expect(band.y1 - band.y0).toBeLessThan(16 * NH);   // and the band is bounded by that
  });

  it("keeps LAYER ORDER left→right — the dependency meaning the packing must not lose", () => {
    // Re-packing is allowed to change WHERE in a column a node sits; it is not allowed to reorder the
    // layers, because that is the only thing the drill says about what depends on what.
    const raw = [n("a", "o/one"), n("b", "o/one"), n("c", "o/two")];
    const edges: GRawEdge[] = [{ from: "b", to: "a", kind: "api" }];
    const m = buildGraph(raw, edges);
    const at = (id: string) => m.nodes.find((v) => v.id === id)!;
    expect(at("a").layer).toBeLessThan(at("b").layer);
    expect(at("a").x).toBeLessThan(at("b").x);
  });

  it("gives each band a real zone the canvas can wash, out to the world's right edge", () => {
    const m = buildGraph([n("architect"), n("a", "o/one"), n("b", "o/two")], []);
    for (const b of m.repoBands!) {
      expect(b.y1).toBeGreaterThan(b.y0);
      expect(m.worldW).toBeGreaterThan(b.x0);   // a non-negative width for the rect
    }
  });

  it("CENTRES the band stack on the director, not the top of the graph", () => {
    // Built from the graph's top edge (the only reference available while packing), then centred — the
    // director's row is what a reader actually relates the workers to. Without this the workers hang
    // off the tier's top corner and the taller the fleet, the more lopsided it reads.
    const m = buildGraph([
      n("director"), n("a", "o/one"), n("b", "o/one"), n("c", "o/two"), n("d", "o/two"),
    ], []);
    const dir = m.nodes.find((x) => x.id === "director")!;
    const bands = m.repoBands!;
    const mid = (bands[0].y0 + bands[bands.length - 1].y1) / 2;
    expect(Math.abs(mid - (dir.y + NH / 2))).toBeLessThan(2);
  });

  it("never centres the stack off the top of the world", () => {
    // `worldH` is measured from the nodes, so a negative y is unreachable rather than merely ugly. A
    // fleet taller than its tier centres as far as it can and then sits at the top.
    const many = Array.from({ length: 14 }, (_, i) => n(`w${i}`, "o/one"));
    const m = buildGraph([n("director"), ...many, n("z", "o/two")], []);
    for (const b of m.repoBands!) expect(b.y0).toBeGreaterThanOrEqual(0);
    for (const node of m.nodes) expect(node.y).toBeGreaterThanOrEqual(0);
  });
});

describe("withStreamRepos — the join from the plan to the graph", () => {
  const data = (ids: string[]) => ({
    rawNodes: ids.map((id) => n(id)),
    rawEdges: [],
    sample: false,
  });
  const fleet = (streams: { id: string; repo: string }[]) => ({ streams }) as never;

  it("stamps a stream's repo onto the node of the same id", () => {
    const out = withStreamRepos(data(["console", "mobile-shell"]), fleet([
      { id: "console", repo: BASE }, { id: "mobile-shell", repo: MOBILE },
    ]));
    expect(out.rawNodes.map((x) => x.repo)).toEqual([BASE, MOBILE]);
  });

  it("leaves a node with no matching stream alone — the director is not a stream", () => {
    const out = withStreamRepos(data(["director", "console"]), fleet([{ id: "console", repo: BASE }]));
    expect(out.rawNodes.find((x) => x.id === "director")!.repo).toBeUndefined();
  });

  it("treats an EMPTY repo as absent rather than grouping under a nameless band", () => {
    // `parseFleetFile` keeps a stream whose repo could not be resolved VISIBLE with an empty `repo`
    // (#2611). Banding on "" would draw a group with no name, which reads as a bug rather than as the
    // missing datum it actually is — ungrouped is the honest position.
    const out = withStreamRepos(data(["orphan"]), fleet([{ id: "orphan", repo: "  " }]));
    expect(out.rawNodes[0].repo).toBeUndefined();
    expect(buildGraph(out.rawNodes, []).repoBands).toBeUndefined();
  });

  it("is a no-op for a fleet with no repos at all, preserving the graph's own fields", () => {
    const before = data(["a"]);
    expect(withStreamRepos(before, fleet([]))).toBe(before);
  });
});

// #architect-node-expands-into-system-sessions — where the app-owned system sessions live.
//
// They used to be an L0 ROW to the architect's left, wired `architect → session`
// (#glance-reads-left-to-right-sessions-to-libraries). The maintainer's directive moved them INSIDE:
// the architect's node expands into them. So this file now pins two things at once — that L0 no longer
// draws them, and that the drill-in does — because a half-done move (removed from one place, not
// arriving in the other) is the failure that would leave the sessions unreachable from the graph
// entirely, with every "the node exists" test still green somewhere else.
//
// The left→right reading survives the move, minus one stop: architect → projects → libraries.
import { describe, it, expect } from "vitest";
import { buildGlanceData } from "@/features/glance/lib/glanceData";
import { buildArchitectFleetData } from "@/features/glance/lib/studioProject";
import { studioNetworkForArchitect, STUDIO_NETWORK_ID, ARCHITECT_NODE, BUILTIN_ORGS } from "@/features/teams";
import { buildGraph, architectNodeId, kitNodeId } from "@/features/glance/lib/glanceGraph";

const projects = [
  { id: "app-a", name: "App A" },
  { id: "app-b", name: "App B" },
];
const architect = [{ id: "persona-architect", name: "Team architect" }];
const build = (p = projects, a = architect) => buildGlanceData(p, [], [], [], [], [], a);

const studioTeam = () => BUILTIN_ORGS.find((t) => t.id === STUDIO_NETWORK_ID)!;

describe("L0 no longer carries the system sessions", () => {
  it("emits NO session node beside the architect", () => {
    const d = build();
    expect(d.rawNodes.filter((n) => n.kind === "session")).toHaveLength(0);
    expect(d.rawEdges.filter((e) => e.kind === "served-by")).toHaveLength(0);
  });

  it("still emits the ARCHITECT — it is the node that expands", () => {
    const d = build();
    const arch = d.rawNodes.find((n) => n.id === architectNodeId("persona-architect"));
    expect(arch).toBeTruthy();
    expect(arch!.kind).toBe("architect");
  });

  it("reads left→right end to end: architect → projects → libraries", () => {
    // The axis the L0 layout is FOR, minus the sessions stop. Still worth asserting as one chain: this
    // is what silently regresses if any remaining dimension's edge direction is flipped later.
    const d = buildGlanceData(
      projects, [], [{ projectKey: "app-a", kitId: "react-ui" }], [{ id: "react-ui", name: "React UI" }], [], [], architect,
    );
    const m = buildGraph(d.rawNodes, d.rawEdges);
    const x = (id: string) => m.nodes.find((n) => n.id === id)!.x;

    expect(x(architectNodeId("persona-architect"))).toBeLessThan(x("app-a"));
    expect(x("app-a")).toBeLessThan(x(kitNodeId("react-ui")));
    expect(x(kitNodeId("react-ui"))).toBeGreaterThanOrEqual(m.bandZone!.x0);
  });

  it("keeps the architect a SINK for provenance, with no cycle", () => {
    // `owned-by` points AT the architect. That is what stops a project↔architect cycle blanking the
    // graph (glance-planner-edge-isolation) — a cycle here takes the whole board down, so it is pinned
    // even though this item removed the edges that used to point the other way.
    const d = build();
    const m = buildGraph(d.rawNodes, d.rawEdges);
    const archId = architectNodeId("persona-architect");
    for (const e of m.edges.filter((x) => x.kind === "owned-by")) expect(e.to).toBe(archId);
    expect(m.cycleNodeIds.size).toBe(0);
  });
});

describe("the architect node expands into the sessions it commands", () => {
  it("narrows the Studio Network to the architect plus the sessions its verbs reach", () => {
    const t = studioNetworkForArchitect(studioTeam());
    const ids = t.positions.map((p) => p.nodeId);
    expect(ids[0]).toBe(ARCHITECT_NODE); // the hub comes first
    // #system-sessions-are-per-technology: the singular designer/librarian POSITIONS expand into one
    // node per technology, so the architect commands seven sessions rather than four.
    expect([...ids].sort()).toEqual([
      "architect",
      "designer-react", "designer-react-native",
      "integrator",
      "librarian-rust", "librarian-typescript",
      "sound-designer",
    ]);
  });

  it("excludes what no architect verb can reach — the planner, the libraries, the debugger", () => {
    // The drill-in's whole claim is that it shows what the architect COMMANDS. A node it cannot start,
    // stop or ask would be a promise the verbs do not keep.
    const ids = new Set(studioNetworkForArchitect(studioTeam()).positions.map((p) => p.nodeId));
    // The un-teched role ids are absent too: they are ROLES, not sessions, since the split.
    for (const absent of ["planner", "debugger", "teams", "components", "algorithms", "designer", "librarian"]) {
      expect(ids.has(absent), `${absent} must not be in the architect's drill-in`).toBe(false);
    }
  });

  it("wires the architect to every session it commands — the L0 relationship, moved inside", () => {
    const t = studioNetworkForArchitect(studioTeam());
    // SIX, not seven: `librarianPython` was the seventh and it named a technology with no record
    // anywhere in the repo (`the-studio-session-set-is-derived-not-declared`). The count is derived
    // from the node set asserted above rather than restated, so a technology arriving or leaving moves
    // both in one edit instead of leaving this number to be noticed.
    expect(t.relationships).toHaveLength(t.positions.length - 1);
    expect(t.relationships).toHaveLength(6);
    for (const r of t.relationships) {
      expect(r.from).toBe(ARCHITECT_NODE);
      expect(r.to).not.toBe(ARCHITECT_NODE);
    }
    // Every edge lands on a position that is actually present — a dangling edge is what narrowing a
    // graph gets wrong.
    const ids = new Set(t.positions.map((p) => p.nodeId));
    for (const r of t.relationships) expect(ids.has(r.to)).toBe(true);
  });

  it("builds a real drilled graph through the SAME team adapter", () => {
    const d = buildArchitectFleetData(BUILTIN_ORGS, []);
    expect(d).toBeTruthy();
    const ids = d!.rawNodes.map((n) => n.id).sort();
    expect(ids).toEqual([
      "architect",
      "designer-react", "designer-react-native",
      "integrator",
      "librarian-rust", "librarian-typescript",
      "sound-designer",
    ]);
    // One edge per commanded session — six since `librarianPython` left the set, and asserted against
    // the node count so the two cannot disagree.
    expect(d!.rawEdges).toHaveLength(ids.length - 1);
    expect(d!.rawEdges).toHaveLength(6);
  });

  it("keeps the node ids that make a session OPENABLE — the morph path is unchanged", async () => {
    // `studioPaneIdForNode` maps a Studio Network POSITION id to its fixed app-owned pane id. If the
    // drill-in renamed its nodes, every session in it would stop opening — the graph would draw and do
    // nothing, which is the worst version of this change landing.
    const { studioPaneIdForNode, studioNodeHome } = await import("@/features/glance/lib/studioProject");
    const d = buildArchitectFleetData(BUILTIN_ORGS, [])!;
    for (const n of d.rawNodes) {
      expect(studioPaneIdForNode(n.id), `${n.id} resolves to a pane`).toBeTruthy();
      expect(studioNodeHome(n.id)?.kind, `${n.id} opens as a morph`).toBe("morph");
    }
  });

  it("is a NO-OP on a team that is not the Studio Network", () => {
    // The transform is exported, so a caller could hand it a user's own team. Narrowing that to five
    // positions would silently destroy their graph.
    const other = BUILTIN_ORGS.find((t) => t.id !== STUDIO_NETWORK_ID);
    if (!other) return;
    expect(studioNetworkForArchitect(other)).toBe(other);
  });
});

// The surface-node PROJECTION (`epic-command-surfaces-are-nodes`, slice 1) — the crate roster from
// `bsc surface crates --json` becomes Glance nodes and crate-dependency edges.
//
// The corpus is shaped like the real roster: 54 workspace members of which 37 expose verbs and 17 do
// not, `bsc-util` among the verbless ones. Every assertion here is about a decision that could
// plausibly have gone the other way, and would have been wrong in a way the UI would not reveal.
import { describe, it, expect } from "vitest";
import { surfaceGraph, withSurfaceNodes, crateKind, crateDrillGraph, CRATE_KIND_ROLE, type SurfaceRosterRow, type CrateDrillDoc } from "@/features/glance/lib/surfaceNodes";
import { buildGlanceData, type GlanceData } from "@/features/glance/lib/glanceData";
import { buildGraph } from "@/features/glance/lib/glanceGraph";
import { surfaceNodeId, isBandNode, isBandEdge } from "@/features/glance/lib/glanceGraph";

// `verbs` stays a PARAMETER and is no longer a FIELD. The roster comes from the plan's surfaces
// section now and carries the key, the edges and the one facet — but these cases are written in terms
// of which crates serve verbs, which is the thing being classified, so the argument stays.
const row = (crate: string, dependsOn: string[] = [], verbs: string[] = []): SurfaceRosterRow => ({
  crate, surface: verbs.length > 0, dependsOn,
});

/** A miniature of the real workspace: a verbless util everything leans on, plus verb-bearing crates. */
const ROSTER: SurfaceRosterRow[] = [
  row("bsc-util"),
  row("bsc-cli-util", ["bsc-util"]),
  row("plandb", ["bsc-util", "bsc-cli-util"], ["plan"]),
  row("logs", ["bsc-util"], ["logs", "metrics", "perf"]),
  row("bsc", ["plandb", "logs", "bsc-cli-util"], ["surface", "version"]),
];

describe("the surface-node projection", () => {
  it("gives EVERY crate a node, including the ones with no verbs", () => {
    const { nodes } = surfaceGraph(ROSTER);
    expect(nodes).toHaveLength(ROSTER.length);
    // The whole point of the crate-keyed decision: bsc-util has no verb and is the crate whose
    // change reaches most of the workspace, so it is exactly the one that must have an owner.
    expect(nodes.map((n) => n.id)).toContain(surfaceNodeId("bsc-util"));
  });

  it("leaves them UNBANDED so they flow with the graph", () => {
    const { nodes } = surfaceGraph(ROSTER);
    // REVERSED 2026-09-02 — see "crates are ordinary nodes" below; a crate flows with the graph.
    for (const n of nodes) expect(isBandNode(n), n.id).toBe(false);
  });

  it("says NO SIGNAL rather than claiming healthy", () => {
    // A crate has no health measurement yet. `healthy` would assert something nobody measured, and
    // the dot is supposed to mean something.
    const { nodes } = surfaceGraph(ROSTER);
    for (const n of nodes) {
      expect(n.health, `${n.id} must not claim a health nobody measured`).toBe("off");
      expect(n.activity).toBe("idle");
    }
  });

  // REPLACED 2026-09-02: the guarantee is no longer "one edge per dep" but "reachability preserved".
  //
  // Edges are transitively reduced now (the drill lagged at 230 of them), so `plandb -> bsc-util` is
  // deliberately ABSENT — plandb reaches bsc-util through bsc-cli-util, and the direct line restated
  // what the path already showed. Asserting the edge count would pin the wrong property; asserting
  // reachability pins the one that actually matters to a reader following the graph.
  it("preserves REACHABILITY while drawing fewer lines than there are deps", () => {
    const { edges } = surfaceGraph(ROSTER);
    expect(edges.every((e) => e.kind === "depends-on")).toBe(true);
    for (const e of edges) expect(isBandEdge(e.kind), e.kind).toBe(false);

    const declared = ROSTER.reduce((n, r) => n + r.dependsOn.length, 0);
    expect(edges.length).toBeLessThan(declared);

    // plandb still REACHES bsc-util, just not directly — which is the whole claim of a reduction.
    const out = new Map<string, string[]>();
    for (const e of edges) out.set(e.from, [...(out.get(e.from) ?? []), e.to]);
    const reaches = (from: string, to: string): boolean => {
      const seen = new Set<string>([from]);
      const stack = [from];
      while (stack.length) {
        const u = stack.pop() as string;
        for (const v of out.get(u) ?? []) {
          if (v === to) return true;
          if (!seen.has(v)) { seen.add(v); stack.push(v); }
        }
      }
      return false;
    };
    expect(reaches(surfaceNodeId("plandb"), surfaceNodeId("bsc-util"))).toBe(true);
    expect(edges.some((e) => e.from === surfaceNodeId("plandb") && e.to === surfaceNodeId("bsc-util"))).toBe(false);
  });

  /** A dangling edge is worse than a missing one — the layout would carry an id nothing renders. */
  it("drops an edge to a crate that is not in the roster", () => {
    const { nodes, edges } = surfaceGraph([row("a", ["not-a-member", "b"]), row("b")]);
    const ids = new Set(nodes.map((n) => n.id));
    expect(edges).toHaveLength(1);
    for (const e of edges) {
      expect(ids.has(e.from), `${e.from} must be a real node`).toBe(true);
      expect(ids.has(e.to), `${e.to} must be a real node`).toBe(true);
    }
  });

  it("never draws a self-loop, even from a malformed roster", () => {
    const { edges } = surfaceGraph([row("a", ["a"])]);
    expect(edges).toEqual([]);
  });

  it("deduplicates a repeated dependency", () => {
    const { edges } = surfaceGraph([row("a", ["b", "b"]), row("b")]);
    expect(edges).toHaveLength(1);
  });

  it("is empty for an empty roster, without throwing", () => {
    expect(surfaceGraph([])).toEqual({ nodes: [], edges: [] });
  });

  // "counts dependents" MOVED TO RUST. `bsc surface drill` computes `dependentCount` and ships it on
  // `CrateDrillDoc`; its cases (3 for a load-bearing util, 0 for a leaf, and a self-edge not inflating
  // the count) are asserted in `crates/bsc/src/main.rs`. The TypeScript copy answered the same question
  // twice and had no caller but this test.
});

// ---------------------------------------------------------------------------------------------
// THE DRILL FOLD (`the-surface-band-is-projected-but-never-drawn`).
//
// The projection above was landed by slice 1 and NOTHING CALLED IT — `surfaceGraph(` occurred exactly
// once in the tree, its own definition — so every crate node was provably absent from the running app
// while the item read `verified` and this file was green. These assertions are about the FOLD, which is
// the part that makes a node appear.
// ---------------------------------------------------------------------------------------------
describe("folding the surface band into a drill", () => {
  const data = (ids: string[] = []): GlanceData => ({
    rawNodes: ids.map((id) => ({ id, slug: id, kind: "project" as const, role: "service" as const, health: "off" as const, activity: "idle" as const })),
    rawEdges: [],
    sample: false,
  });

  it("adds a node per crate, and the depends-on edges that give the band structure", () => {
    const out = withSurfaceNodes(data(["studio-code"]), ROSTER);
    const added = out.rawNodes.filter((n) => n.kind === "surface");
    expect(added.map((n) => n.slug).sort()).toEqual(ROSTER.map((r) => r.crate).sort());
    // The EDGES are the whole difference from the removed L0 band, which drew none and left an
    // unconnected inventory. A fold that added nodes and dropped edges would repeat it exactly.
    expect(out.rawEdges.length).toBeGreaterThan(0);
    expect(out.rawEdges.every((e) => e.kind === "depends-on")).toBe(true);
    // and the host node it was folded into survives
    expect(out.rawNodes.some((n) => n.id === "studio-code")).toBe(true);
  });

  it("returns the graph UNCHANGED on an empty roster, rather than blanking the band", () => {
    const before = data(["studio-code"]);
    const after = withSurfaceNodes(before, []);
    // Identity, not just equality: a failed read must be a no-op, and re-deriving would drop the
    // reference the memo above it is keyed on.
    expect(after).toBe(before);
  });

  it("never draws a second node for a crate already in the graph", () => {
    const existing = surfaceNodeId(ROSTER[0].crate);
    const out = withSurfaceNodes(data([existing]), ROSTER);
    expect(out.rawNodes.filter((n) => n.id === existing)).toHaveLength(1);
  });

  it("drops an edge whose other end is not drawn, rather than dangling it", () => {
    // A roster of one crate that depends on a crate absent from the roster: the node lands, the edge
    // must not, or the layout carries an id nothing renders.
    const lone: SurfaceRosterRow[] = [
      { crate: "logs", path: "crates/logs", surface: true, verbs: ["logs"], dependsOn: ["not-in-roster"] },
    ];
    const out = withSurfaceNodes(data(), lone);
    expect(out.rawNodes.filter((n) => n.kind === "surface")).toHaveLength(1);
    expect(out.rawEdges).toHaveLength(0);
  });
});

// L0 MUST STAY FREE OF SURFACE NODES. An L0 band was built, shipped and REMOVED — one node per `bsc`
// subcommand with no edge, 33 unconnected marks beside the project network — and `glanceData`'s comment
// says the `surfaces` parameter was deleted rather than kept and ignored so that a later reader would
// not put it back. This is that guard, since a comment cannot fail a build.
describe("L0 draws no command surfaces", () => {
  it("buildGlanceData emits no node of kind `surface`", () => {
    const out = buildGlanceData([{ id: "studio-code", name: "studio-code" }]);
    // NOT VACUOUS: an empty graph would satisfy "contains no surface node" trivially, which is the
    // shape of every green-but-blind test this repo keeps getting caught by.
    expect(out.rawNodes.length).toBeGreaterThan(0);
    expect(out.rawNodes.some((n) => n.kind === "surface")).toBe(false);
    expect(out.rawEdges.some((e) => e.kind === "depends-on")).toBe(false);
  });
});

// ---------------------------------------------------------------------------------------------
// CRATES FLOW IN THE GRAPH — they are not fenced into the band.
//
// MAINTAINER, 2026-09-02: "lets treat these like normal nodes, instead of placing them in a box.
// they should flow within the graph."
//
// The same correction `architect-sits-with-the-projects` made, for the same reason. The band is for a
// shared DEPENDENCY the projects consume — a kit, an algorithm, an MCP server — where lifting keeps its
// health out of a project's roll-up. A crate is not consumed by the project; it IS the project,
// decomposed. Fencing 60 of them renders an inventory beside the work rather than the work.
// ---------------------------------------------------------------------------------------------
describe("crates are ordinary nodes, not band nodes", () => {
  it("a surface node is not banded, and its depends-on edge is not a band edge", () => {
    const { nodes, edges } = surfaceGraph(ROSTER);
    expect(nodes.length).toBeGreaterThan(0);
    for (const n of nodes) expect(isBandNode(n)).toBe(false);
    expect(edges.length).toBeGreaterThan(0);
    for (const e of edges) expect(isBandEdge(e.kind)).toBe(false);
  });

  it("the band still holds the kinds that DO belong in it", () => {
    // Un-fencing crates must not un-fence the dimensions the band exists for — the failure mode the
    // architect change had to guard too.
    for (const kind of ["mcp", "service", "integration"] as const) {
      expect(isBandNode({ kind })).toBe(true);
    }
    for (const kind of ["uses-mcp", "uses-service", "uses-integration"] as const) {
      expect(isBandEdge(kind)).toBe(true);
    }
  });

  it("the crate graph is ACYCLIC, which is what makes admitting it to the network safe", () => {
    // A cycle in this graph has blanked it before (glance-planner-edge-isolation), and the architect
    // was only safe to un-fence because it is a sink. A crate is not a sink, so the safety argument has
    // to be the DAG — asserted here rather than assumed, over the real projection.
    const { nodes, edges } = surfaceGraph(ROSTER);
    const out = new Map(nodes.map((n) => [n.id, [] as string[]]));
    for (const e of edges) out.get(e.from)?.push(e.to);
    const state = new Map<string, number>();
    const walk = (u: string): boolean => {
      state.set(u, 1);
      for (const v of out.get(u) ?? []) {
        if (state.get(v) === 1) return true;
        if (!state.has(v) && walk(v)) return true;
      }
      state.set(u, 2);
      return false;
    };
    for (const n of nodes) if (!state.has(n.id) && walk(n.id)) throw new Error("cycle in the crate graph");
    expect(state.size).toBe(nodes.length);
  });
});

// ---------------------------------------------------------------------------------------------
// REPO SEPARATION + EDGE VOLUME (`crates-keep-their-repo-and-stop-drawing-implied-edges`).
//
// MAINTAINER, 2026-09-02, on the un-banded first cut: "we're now no longer separating between repos …
// this really jumbled our graph. we're also drawing a ton more lines here so we're experiencing lag."
//
// Both were caused by un-fencing. The fence had been doing the repo separation by accident, and it had
// also been hiding how many `depends-on` lines there are.
// ---------------------------------------------------------------------------------------------
describe("crates stay separated by repository", () => {
  const withRepo = (ids: string[], repo?: string): GlanceData => ({
    rawNodes: ids.map((id) => ({
      id, slug: id, kind: "project" as const, role: "service" as const,
      health: "off" as const, activity: "idle" as const, ...(repo ? { repo } : {}),
    })),
    rawEdges: [],
    sample: false,
  });

  it("stamps every crate with the repo the drill's own streams carry", () => {
    const out = withSurfaceNodes(withRepo(["design-studio", "fleet"], "acme/base-studio-code"), ROSTER);
    const crates = out.rawNodes.filter((n) => n.kind === "surface");
    expect(crates.length).toBeGreaterThan(0);
    // Every one, not most — `bandNodesByRepo` leaves an unstamped node UNGROUPED, which is exactly the
    // scattering this fixes.
    for (const c of crates) expect(c.repo).toBe("acme/base-studio-code");
  });

  it("takes the MODAL repo, so one odd node cannot capture the whole roster", () => {
    const data: GlanceData = {
      rawNodes: [
        ...withRepo(["a", "b", "c"], "acme/main").rawNodes,
        ...withRepo(["d"], "acme/other").rawNodes,
      ],
      rawEdges: [], sample: false,
    };
    const out = withSurfaceNodes(data, ROSTER);
    for (const c of out.rawNodes.filter((n) => n.kind === "surface")) expect(c.repo).toBe("acme/main");
  });

  it("leaves crates UNSTAMPED when no repo is knowable, rather than inventing one", () => {
    // Ungrouped is honest; a wrong band is not.
    const out = withSurfaceNodes(withRepo(["a", "b"]), ROSTER);
    for (const c of out.rawNodes.filter((n) => n.kind === "surface")) expect(c.repo).toBeUndefined();
  });
});

describe("only the edges that are not already implied get drawn", () => {
  it("drops an edge a longer path already expresses", () => {
    // a → b → c, plus a redundant a → c. The direct a→c must go; reachability is unchanged.
    const r: SurfaceRosterRow[] = [
      { crate: "a", path: "crates/a", surface: false, verbs: [], dependsOn: ["b", "c"] },
      { crate: "b", path: "crates/b", surface: false, verbs: [], dependsOn: ["c"] },
      { crate: "c", path: "crates/c", surface: false, verbs: [], dependsOn: [] },
    ];
    const { edges } = surfaceGraph(r);
    const pairs = edges.map((e) => `${e.from}->${e.to}`).sort();
    expect(pairs).toEqual([
      `${surfaceNodeId("a")}->${surfaceNodeId("b")}`,
      `${surfaceNodeId("b")}->${surfaceNodeId("c")}`,
    ]);
  });

  it("keeps an edge that is the ONLY path — a reduction must not lose reachability", () => {
    const r: SurfaceRosterRow[] = [
      { crate: "a", path: "crates/a", surface: false, verbs: [], dependsOn: ["b"] },
      { crate: "b", path: "crates/b", surface: false, verbs: [], dependsOn: [] },
    ];
    expect(surfaceGraph(r).edges).toHaveLength(1);
  });

  it("collapses a hub — the specific shape that caused the lag", () => {
    // Every crate depends on `util` directly AND through `cli`. The direct lines are all implied, so a
    // hub with N dependents draws far fewer than N. This is `bsc-util`'s 44 → 5 in miniature.
    const r: SurfaceRosterRow[] = [
      { crate: "util", path: "p", surface: false, verbs: [], dependsOn: [] },
      { crate: "cli", path: "p", surface: false, verbs: [], dependsOn: ["util"] },
      ...["x", "y", "z", "w"].map((c) => ({
        crate: c, path: "p", surface: false, verbs: [], dependsOn: ["cli", "util"],
      })),
    ];
    const { edges } = surfaceGraph(r);
    const intoUtil = edges.filter((e) => e.to === surfaceNodeId("util"));
    expect(intoUtil).toHaveLength(1); // only cli → util survives; the four direct lines are implied
    expect(edges).toHaveLength(5);
  });

  it("terminates on a malformed CYCLIC roster instead of hanging the cockpit", () => {
    const r: SurfaceRosterRow[] = [
      { crate: "a", path: "p", surface: false, verbs: [], dependsOn: ["b"] },
      { crate: "b", path: "p", surface: false, verbs: [], dependsOn: ["a"] },
    ];
    expect(() => surfaceGraph(r)).not.toThrow();
    expect(surfaceGraph(r).nodes).toHaveLength(2);
  });
});

// ---------------------------------------------------------------------------------------------
// THE THREE KINDS OF CRATE (`a-crate-node-shows-which-of-the-three-kinds-it-is`).
//
// MAINTAINER 2026-09-02: "take a look at the crate nodes and lets create a visual distinction between
// the 3 different kinds we have."
//
// The axis is HOW YOU USE IT, which is what a reader of this graph is asking: call it (`bsc <verb>`),
// build on it, or run it. Measured on the real roster: 43 surface / 14 library / 3 program of 60.
// ---------------------------------------------------------------------------------------------
describe("a crate node says which of the three kinds it is", () => {
  const row2 = (crate: string, surface: boolean, deps: string[] = []): SurfaceRosterRow => ({
    crate, surface, dependsOn: deps,
  });

  it("classifies on VERBS then FAN-IN — never on the name", () => {
    // The trap, stated as a test: `bsc-agent` and `bsc-hook` read as libraries and are programs;
    // `channel` and `research` read as programs and are libraries. A name heuristic gets four of
    // seventeen wrong, silently, which is why fan-in is the discriminator.
    expect(crateKind(row2("plandb", true), 0)).toBe("surface");
    expect(crateKind(row2("bsc-util", false), 44)).toBe("library");
    expect(crateKind(row2("bsc-agent", false), 0)).toBe("program");
    // a verb WINS over fan-in — a crate you can call is a surface however many depend on it
    expect(crateKind(row2("logs", true), 12)).toBe("surface");
  });

  it("gives each kind its own colour AND its own word", () => {
    // Colour alone is a cipher: it dies in greyscale, in a screenshot, and for a colour-blind reader.
    // The caption is what makes the distinction legible without the legend.
    const r = [row2("cli", true), row2("util", false, []), row2("app", false, [])];
    r[0].dependsOn = ["util"]; // so `util` has a dependent and `app` does not
    const { nodes } = surfaceGraph(r);
    const by = (c: string) => nodes.find((n) => n.slug === c);
    expect(by("cli")?.roleLabel).toBe("surface");
    expect(by("util")?.roleLabel).toBe("library");
    expect(by("app")?.roleLabel).toBe("program");
    const roles = [by("cli")?.role, by("util")?.role, by("app")?.role];
    expect(new Set(roles).size).toBe(3); // three kinds, three accents — none collides
  });

  it("is exhaustive and disjoint — every crate gets exactly one kind", () => {
    const { nodes } = surfaceGraph(ROSTER);
    const kinds = nodes.map((n) => n.roleLabel);
    expect(kinds.every((k) => k === "surface" || k === "library" || k === "program")).toBe(true);
    expect(kinds).toHaveLength(ROSTER.length);
  });

  it("maps every kind to a role, so the legend can never be handed an unknown one", () => {
    for (const k of ["surface", "library", "program"] as const) {
      expect(CRATE_KIND_ROLE[k], `${k} has no accent`).toBeTruthy();
    }
    expect(Object.keys(CRATE_KIND_ROLE).sort()).toEqual(["library", "program", "surface"]);
  });
});

// ---------------------------------------------------------------------------------------------
// THE SECOND LAYER (`a-crate-node-drills-into-its-verbs`).
//
// MAINTAINER: a crate node should "navigate into a second layer which will present the user the
// surface node and their related verbs". So this is a GRAPH, not an inspector panel.
// ---------------------------------------------------------------------------------------------
describe("a crate drills into its NOUNS, each rooting its verbs", () => {
  const doc = (over: Partial<CrateDrillDoc> = {}): CrateDrillDoc => ({
    crate: "logs", path: "crates/logs", surface: true,
    nouns: [
      { noun: "logs", status: "active", catalog: "projected", verbs: [
        { verb: "sessions", summary: "s", usage: "u" },
        { verb: "summary", summary: "s", usage: "u" },
      ] },
      { noun: "metrics", status: "active", catalog: "unreachable", verbs: null },
      { noun: "perf", status: "active", catalog: "projected", verbs: [{ verb: "summary", summary: "s", usage: "u" }] },
    ],
    dependsOn: ["bsc-util"], dependents: ["bsc-fleet"], dependentCount: 1,
    ...over,
  });

  it("roots on the NOUN, not the crate — a multi-noun crate is a forest", () => {
    // You run `bsc logs sessions`, not `bsc logs-crate sessions`. Rooting on the crate flattened three
    // separate commands into one fan and lost the thing the reader is navigating.
    const g = crateDrillGraph(doc());
    const roots = g.rawNodes.filter((n) => n.id.startsWith("noun:"));
    expect(roots.map((n) => n.slug).sort()).toEqual(["logs", "metrics", "perf"]);
    // no crate node while there are nouns — the drill is already scoped to it
    expect(g.rawNodes.some((n) => n.id === surfaceNodeId("logs"))).toBe(false);
    // EVERY EDGE POINTS AT THE NOUN, and that is what puts the noun on the LEFT.
    //
    // `layoutProjectNetwork` hands `layerDag` the edges reversed and lays layers out left→right, so an
    // edge's TARGET lands at a lower layer — further left. Drawn `noun → verb` the verbs sat left of
    // their own noun, which is backwards to read. This assertion is the layout, not a formality.
    for (const e of g.rawEdges) {
      expect(e.to.startsWith("noun:"), `${e.id} must point AT its noun`).toBe(true);
      expect(e.from.startsWith("verb:"), `${e.id} must start at a verb`).toBe(true);
      expect(e.kind).toBe("verb-of");
    }
    expect(g.rawEdges).toHaveLength(3);
  });

  it("LAYS THE NOUN LEFT OF ITS VERBS — the property, not a proxy for it", () => {
    // MAINTAINER: "information is, in the west, read from left to right! lets please place the noun on
    // the left hand side and their verbs to the right."
    //
    // Asserting edge DIRECTION only pins the current layering convention ("the target sits at a lower
    // layer"). Asserting POSITION pins what was actually asked for, and survives that convention
    // changing underneath — which is the whole reason the direction had to be flipped in the first
    // place. This runs the real layout engine, not a stand-in.
    const g = crateDrillGraph(doc());
    const m = buildGraph(g.rawNodes, g.rawEdges);
    const at = (id: string) => m.nodes.find((n) => n.id === id)!;
    const logsRoot = at("noun:logs");
    for (const v of ["sessions", "summary"]) {
      const verb = m.nodes.find((n) => n.slug === v && n.roleLabel === "logs")!;
      expect(verb.x, `bsc logs ${v} must sit RIGHT of its noun`).toBeGreaterThan(logsRoot.x);
    }
  });

  it("DRAWS a noun whose catalog is unreachable, rather than hiding the command", () => {
    // Reversed from the crate-rooted cut on purpose: `bsc metrics` EXISTS and has no verb catalog, and
    // a reader asking "what can I run" needs to see it. Rooted on the crate it would have asserted the
    // crate offered something it did not; rooted on the noun it states a fact.
    const g = crateDrillGraph(doc());
    const metrics = g.rawNodes.find((n) => n.slug === "metrics");
    expect(metrics).toBeTruthy();
    expect(g.rawEdges.filter((e) => e.to === metrics!.id)).toHaveLength(0);
  });

  it("keys a verb on its NOUN, so two nouns' same-named verbs stay distinct", () => {
    const g = crateDrillGraph(doc());
    expect(g.rawNodes.filter((n) => n.slug === "summary")).toHaveLength(2);
    const ids = g.rawNodes.map((n) => n.id);
    expect(new Set(ids).size).toBe(ids.length);
    expect(g.rawNodes.filter((n) => n.slug === "summary").map((n) => n.roleLabel).sort()).toEqual(["logs", "perf"]);
  });

  it("captions each noun root with its CRATE, so the reader keeps that fact", () => {
    const g = crateDrillGraph(doc());
    expect(g.rawNodes.find((n) => n.slug === "logs" && n.id.startsWith("noun:"))?.roleLabel).toBe("logs");
    expect(g.rawNodes.find((n) => n.slug === "perf")?.roleLabel).toBe("logs");
  });

  it("falls back to the crate node when there is nothing to call", () => {
    // A library or a program must not render as a blank canvas, which reads as a failed load.
    const g = crateDrillGraph(doc({ crate: "bsc-util", surface: false, nouns: [], dependentCount: 44 }));
    expect(g.rawNodes).toHaveLength(1);
    expect(g.rawNodes[0].id).toBe(surfaceNodeId("bsc-util"));
    expect(g.rawNodes[0].roleLabel).toBe("library");
    expect(g.rawEdges).toHaveLength(0);
  });
});

// A Glance drill belongs to ITS TAB (#each-glance-tab-owns-its-own-drill).
//
// THE BUG: `glanceDrill` was a single global value while `activePageTab` — the thing that picks a tab —
// is a map. Nothing re-scoped the drill on a tab change (the only writers are the node click and
// `exitDrill`), so drilling into a layer on one network applied that navigation to every other tab:
// switching landed the user inside a drill belonging to a different domain, on a graph that does not
// contain that node.
//
// Asserted on the STORE rather than through a render, because the leak is a state-shape property: one
// value cannot hold two tabs' depths, and no amount of component behaviour can fix that.
import { describe, it, expect, beforeEach, vi } from "vitest";
import { render, waitFor } from "@testing-library/react";
import { useAppStore } from "@/store";
import { architectNodeId } from "@/features/glance/lib/glanceGraph";

// Same viewport stub the other GlanceWorkspace tests use — jsdom does no layout measurement.
vi.mock("@/shared/ui/layouts/useGraphViewport", async (orig) => {
  const actual = await orig<typeof import("@/shared/ui/layouts/useGraphViewport")>();
  return {
    ...actual,
    useGraphViewport: () => ({
      view: { tx: 0, ty: 0, scale: 1 },
      setVp: () => {}, onCanvasDown: () => {}, fit: () => {}, centerOn: () => {},
      zoomBy: () => {}, zoomTo: () => {}, zoomToCentered: () => {},
      dragMoved: { current: false }, worldTransform: {},
    }),
  };
});

import { GlanceWorkspace } from "@/features/glance/GlanceWorkspace";

const FINANCE = "network-finance";
const KITCHEN = "network-kitchen";

beforeEach(() => {
  useAppStore.setState({ glanceDrill: {}, activePageTab: {} });
});

describe("each Glance tab keeps its own drill", () => {
  it("does not apply one tab's drill to another", () => {
    useAppStore.getState().setGlanceDrill(FINANCE, "ledger");
    const drills = useAppStore.getState().glanceDrill;
    expect(drills[FINANCE]).toBe("ledger");
    // The whole bug in one assertion: kitchen must still be at its own depth.
    expect(drills[KITCHEN] ?? null).toBeNull();
  });

  it("keeps a tab's drill while another tab drills and exits", () => {
    // Switching away and back must RESTORE the depth, not clear it — the fix is per-tab memory, not a
    // reset on tab change (which would trade a leak for losing the user's place).
    useAppStore.getState().setGlanceDrill(FINANCE, "ledger");
    useAppStore.getState().setGlanceDrill(KITCHEN, "wan-relay");
    useAppStore.getState().setGlanceDrill(KITCHEN, null); // kitchen exits its drill
    const drills = useAppStore.getState().glanceDrill;
    expect(drills[KITCHEN]).toBeNull();
    expect(drills[FINANCE], "finance keeps its own depth").toBe("ledger");
  });

  it("tracks each tab independently across many tabs", () => {
    for (const [tab, target] of [[FINANCE, "a"], [KITCHEN, "b"], ["network-science", "c"]] as const) {
      useAppStore.getState().setGlanceDrill(tab, target);
    }
    expect(useAppStore.getState().glanceDrill).toEqual({
      [FINANCE]: "a", [KITCHEN]: "b", "network-science": "c",
    });
  });
});

describe("the tab a drill belongs to is the tab that shows it", () => {
  it("renders KITCHEN at L0 while FINANCE is drilled", async () => {
    // THE LEAK, as the user meets it: with one global value, a drill set on finance made kitchen render
    // finance's fleet graph — a drill into a project kitchen's tab does not even contain. The proof
    // that kitchen is at L0 is its ARCHITECT node: that node exists only in the project model, and a
    // drill swaps the whole model to the fleet, so drawing it is exactly "not drilled".
    useAppStore.setState({
      networks: [
        { id: KITCHEN, name: "kitchen", position: 0 },
        { id: FINANCE, name: "finance", position: 1 },
      ],
      glanceDrill: { [FINANCE]: "ledger" },   // finance is deep…
      activePageTab: { glance: KITCHEN },     // …and kitchen is what we are showing
      localDraftProjects: {}, triagedProjects: {},
      projectLinks: [], githubToken: "", githubState: null, tabs: [], bscBaseDir: "/base",
    });

    const { container } = render(<GlanceWorkspace />);
    await waitFor(() =>
      expect(
        container.querySelector(`[data-glance-node="${architectNodeId(KITCHEN)}"]`),
        "kitchen must render its own L0, not finance's drill",
      ).toBeTruthy());
  });
});

describe("each tab remembers its own graph position", () => {
  // THE BUG: one `useGraphViewport` instance serves every Glance tab, so a switch applied the outgoing
  // tab's transform to the incoming graph and you landed somewhere arbitrary. Nothing recorded it.
  //
  // Asserted on the STORE, because the leak is a state-shape property — one view cannot hold two tabs'
  // positions. The render path is covered by the sibling case above; what matters here is that leaving
  // a tab records where you were and that another tab cannot overwrite it.
  it("keeps a position per tab", () => {
    useAppStore.setState({ glanceView: {} });
    useAppStore.getState().setGlanceView(FINANCE, { tx: -100, ty: -50, scale: 1.4 });
    useAppStore.getState().setGlanceView(KITCHEN, { tx: 20, ty: 30, scale: 0.6 });
    const v = useAppStore.getState().glanceView;
    expect(v[FINANCE]).toEqual({ tx: -100, ty: -50, scale: 1.4 });
    expect(v[KITCHEN], "kitchen must not inherit finance's transform").toEqual({ tx: 20, ty: 30, scale: 0.6 });
  });

  it("has NO recorded position for a tab never visited — the signal to fit it", () => {
    // `undefined` is load-bearing: it is what tells the workspace to FIT a graph the user has not
    // looked at yet, rather than dropping them at another tab's coordinates.
    useAppStore.setState({ glanceView: {} });
    useAppStore.getState().setGlanceView(FINANCE, { tx: 1, ty: 2, scale: 1 });
    expect(useAppStore.getState().glanceView[KITCHEN]).toBeUndefined();
  });
});

// After a TAB SWITCH the graph is still usable — nodes draw, and a click still opens.
//
// TWO failures met as one symptom ("I can't interact with nodes after switching tabs", and "sometimes
// the node doesn't load in"), both fallout from making every Glance tab its own graph:
//
//  1. A STALE GRID ANCHOR SWALLOWED THE CLICK. `gridAnchorId` is released only when the last morph
//     closes, or by `exitDrill` — never on a tab change. So it named a node of the tab being LEFT, and
//     `openChat` did `if (!anchor) return prev;`, dropping the placement with no error and no
//     selection. `openChats`, the READ side, already tolerated a stale anchor via `resolveGridAnchor`;
//     the WRITER did not.
//
//  2. A RECORDED VIEW PINNED THE GRAPH OFF-SCREEN. `restoreView` sets `userMoved`, which disables
//     `useGraphViewport`'s world-change re-fit — and that re-fit is the only thing that re-frames a
//     graph whose data arrives async (#3433: "the real data then arrives, the world grows, and nothing
//     re-frames it — the graph renders from screen center off the bottom-right"). A view captured
//     before a tab's data landed was therefore pinned forever.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, waitFor, fireEvent, act } from "@testing-library/react";
import { useAppStore } from "@/store";
import { architectNodeId } from "@/features/glance/lib/glanceGraph";

const KITCHEN = "network-kitchen";
const FINANCE = "network-finance";

// The viewport stub the other GlanceWorkspace tests use, plus the two seams under test. `moved` is
// what the real hook's `userMoved` ref is: false until the USER pans/zooms.
let moved = false;
const restored: unknown[] = [];
vi.mock("@/shared/ui/layouts/useGraphViewport", async (orig) => {
  const actual = await orig<typeof import("@/shared/ui/layouts/useGraphViewport")>();
  return {
    ...actual,
    useGraphViewport: () => ({
      view: { tx: 0, ty: 0, scale: 1 },
      setVp: () => {}, onCanvasDown: () => {}, fit: () => {}, centerOn: () => {},
      restoreView: (v: unknown) => { restored.push(v); },
      hasUserMoved: () => moved,
      zoomBy: () => {}, zoomTo: () => {}, zoomToCentered: () => {},
      dragMoved: { current: false }, worldTransform: {},
    }),
  };
});

import { GlanceWorkspace } from "@/features/glance/GlanceWorkspace";

const seed = (activeTab: string) => ({
  networks: [
    { id: KITCHEN, name: "kitchen", position: 0 },
    { id: FINANCE, name: "finance", position: 1 },
  ],
  glanceDrill: {}, glanceView: {},
  activePageTab: { glance: activeTab },
  localDraftProjects: {}, triagedProjects: {},
  projectLinks: [], githubToken: "", githubState: null, tabs: [], bscBaseDir: "/base",
});

const nodeIn = async (container: HTMLElement, id: string) =>
  await waitFor(() => {
    const el = container.querySelector(`[data-glance-node="${id}"]`);
    expect(el, `${id} must be on the graph`).toBeTruthy();
    return el as Element;
  });

const switchTo = (tab: string) =>
  act(() => { useAppStore.getState().setActivePageTab("glance", tab); });

describe("the graph stays usable across a tab switch", () => {
  beforeEach(() => {
    moved = false;
    restored.length = 0;
    useAppStore.setState(seed(KITCHEN));
  });

  it("still opens a node on the tab you switched TO, after opening one on the tab you left", async () => {
    const { container, rerender } = render(<GlanceWorkspace />);

    // Opening this is what sets `gridAnchorId` — the state that used to go stale.
    fireEvent.click(await nodeIn(container, architectNodeId(KITCHEN)));
    await waitFor(() => expect(container.querySelector(".glance-card")).toBeTruthy());

    switchTo(FINANCE);
    rerender(<GlanceWorkspace />);

    fireEvent.click(await nodeIn(container, architectNodeId(FINANCE)));
    await waitFor(
      () => expect(container.querySelector(".glance-card"), "the click must open a morph").toBeTruthy(),
      { timeout: 2000 },
    );
  });

  it("records NO position for a tab the user never positioned", async () => {
    // The one that pinned a graph off-screen. A fitted view is reproducible on return, so recording it
    // buys nothing — and restoring it would suppress the async-data re-fit for good.
    const { rerender } = render(<GlanceWorkspace />);
    switchTo(FINANCE);
    rerender(<GlanceWorkspace />);
    await waitFor(() => expect(useAppStore.getState().activePageTab.glance).toBe(FINANCE));
    expect(useAppStore.getState().glanceView[KITCHEN], "a merely fitted view is not a position").toBeUndefined();
  });

  it("records the position of a tab the user DID move, and restores it on return", async () => {
    const { rerender } = render(<GlanceWorkspace />);
    moved = true;                       // the user panned/zoomed kitchen
    switchTo(FINANCE);
    rerender(<GlanceWorkspace />);
    await waitFor(() => expect(useAppStore.getState().glanceView[KITCHEN]).toBeTruthy());

    switchTo(KITCHEN);
    rerender(<GlanceWorkspace />);
    await waitFor(() => expect(restored.length, "returning restores the recorded position").toBeGreaterThan(0));
  });
});

// glance-progress-ref-namespace-split — a fleet stream's `issues` and plan.db's `ref` column are two
// SEPARATE ownership records, and they need not share a namespace.
//
// WHY NO EXISTING TEST CAUGHT THIS. Every fixture in the suite uses ONE ref shape throughout — refs go
// in, the same refs come out, `done` matches, green. The bug only exists where the two shapes MEET, so
// it is structurally invisible to a single-shape fixture. That is what this file supplies: both shapes
// in one fixture, which is the shape of the real data.
//
// Measured on the two live projects when this was filed:
//   base-studio-code   22 stream refs, ALL plan.db slugs   -> 22/22 resolve, the ref path is right
//   studio-code        56 stream refs, ALL GitHub numbers  -> 0/56 resolve, and every owning node read
//                                                             0/N while plan.db knew the real answer
import { describe, it, expect } from "vitest";
import { fleetPlanProgress, knownRefAliases, mergeStreamProgress, unionDone } from "@/features/glance/lib/fleetPlanProgress";
import { streamProgress, projectProgress } from "@/features/glance/lib/streamProgress";
import type { OwnedIssue } from "@/shared/lib/fleet/workerEnd";

/** plan.db as `studio-code` actually holds it: slug refs, no GitHub identity anywhere. */
const SLUG_ISSUES: OwnedIssue[] = [
  { ref: "glance-planner-node-per-project", status: "verified", stream: "glance" },
  { ref: "glance-project-studio-sessions", status: "verified", stream: "glance" },
  { ref: "glance-open-issue", status: "open", stream: "glance" },
  { ref: "design-studio-a", status: "complete", stream: "design-studio" },
  { ref: "design-studio-b", status: "verified", stream: "design-studio" },
  // Owned by NO stream — counted by the project, never by a worker.
  { ref: "unowned-chore", status: "verified" },
];

/** The same project's fleet, whose streams were authored with GitHub NUMBERS. */
const NUMERIC_STREAMS = [
  { id: "glance", issues: ["#233", "#234"] },
  { id: "design-studio", issues: ["#243", "#245", "#246"] },
];

describe("stream refs in a namespace plan.db has never seen", () => {
  const known = knownRefAliases(SLUG_ISSUES);
  const done = unionDone(SLUG_ISSUES.filter((i) => i.status === "verified" || i.status === "complete").map((i) => i.ref));

  it("resolves none of them — the premise of the bug, stated as a fact", () => {
    const refs = NUMERIC_STREAMS.flatMap((s) => s.issues).map((r) => r.replace(/^#/, ""));
    expect(refs.some((r) => known.has(r))).toBe(false);
  });

  it("emits NO ref-path entry for a stream whose refs all resolve to nothing", () => {
    const out = fleetPlanProgress(NUMERIC_STREAMS, done, undefined, known);
    expect(out.has("glance")).toBe(false);
    expect(out.has("design-studio")).toBe(false);
  });

  it("so plan.db answers, and a stream that IS done stops reading 0/N", () => {
    const merged = mergeStreamProgress(
      fleetPlanProgress(NUMERIC_STREAMS, done, undefined, known),
      streamProgress(SLUG_ISSUES),
    );
    // The reported case: plan.db knows design-studio is 2/2, the ref path claimed 0/3, and the ref path won.
    expect(merged.get("design-studio")).toEqual({ done: 2, total: 2 });
    expect(merged.get("glance")).toEqual({ done: 2, total: 3 });
  });

  it("gives the DIRECTOR no aggregate it cannot substantiate", () => {
    const out = fleetPlanProgress(NUMERIC_STREAMS, done, "director", known);
    // Not `{done: 0, total: 5}` — an unmovable denominator is worse than none, and 0/5 reads as
    // "nothing done" for a board that is mostly finished.
    expect(out.has("director")).toBe(false);
  });

  it("the project number the director falls back to counts UNOWNED issues too", () => {
    // 5 of 6 are complete|verified — including `unowned-chore`, which NO stream counts. Summing the
    // per-stream rows says 4/5, and that gap is exactly why the director cannot just add up its workers.
    expect(projectProgress(SLUG_ISSUES)).toEqual({ done: 5, total: 6 });
    const perStream = [...streamProgress(SLUG_ISSUES).values()].reduce(
      (a, p) => ({ done: a.done + p.done, total: a.total + p.total }), { done: 0, total: 0 },
    );
    expect(perStream).not.toEqual(projectProgress(SLUG_ISSUES));
  });
});

describe("stream refs in plan.db's OWN namespace still work — this must not regress", () => {
  // `base-studio-code`: the streams carry the same slugs plan.db does.
  const SLUG_STREAMS = [
    { id: "glance", issues: ["glance-planner-node-per-project", "glance-open-issue"] },
    { id: "design-studio", issues: ["design-studio-a", "design-studio-b"] },
  ];
  const known = knownRefAliases(SLUG_ISSUES);
  const done = unionDone(["glance-planner-node-per-project", "design-studio-a", "design-studio-b"]);

  it("the ref path answers, with the stream's OWN denominator", () => {
    const out = fleetPlanProgress(SLUG_STREAMS, done, "director", known);
    expect(out.get("glance")).toEqual({ done: 1, total: 2 });
    expect(out.get("design-studio")).toEqual({ done: 2, total: 2 });
    // …and the director aggregates the union, de-duplicated.
    expect(out.get("director")).toEqual({ done: 3, total: 4 });
  });

  it("a slug carrying its origin number also answers to that number", () => {
    const aliases = knownRefAliases([{ ref: "4260-sandbox-by-default" }]);
    expect(aliases.has("4260-sandbox-by-default")).toBe(true);
    expect(aliases.has("4260")).toBe(true);
    // …so a stream written with `#4260` resolves against a plan.db that stores the slug.
    const out = fleetPlanProgress([{ id: "s", issues: ["#4260"] }], unionDone(["4260-sandbox-by-default"]), undefined, aliases);
    expect(out.get("s")).toEqual({ done: 0, total: 1 });
    expect(out.has("s")).toBe(true); // it RESOLVED — done-ness is a separate question from resolvability
  });

  it("omitting `knownRefs` keeps the old behaviour exactly — no caller is forced to change", () => {
    const out = fleetPlanProgress(NUMERIC_STREAMS, done, "director");
    expect(out.get("glance")).toEqual({ done: 0, total: 2 });
    expect(out.get("director")).toEqual({ done: 0, total: 5 });
  });
});

// A PERSONA'S LOCAL MODEL MUST REACH THE LAUNCH (`a-personas-local-model-reaches-the-launch`).
//
// MAINTAINER 2026-09-02: "these nodes are still being opened into a claude cli sessions."
//
// The persona carried `qwen3.5:35b-a3b` and the terminal ran Claude. Two independent places dropped it,
// and BOTH failed silently — `ClaudeCodeAdapter.model_flag` maps the known tiers and ignores anything
// else, so a local name handed to Claude Code produces no error at all, just the wrong harness.
import { describe, it, expect } from "vitest";
import { providerForModel } from "@/app/console/lib/models";
import { streamPaneWiring } from "@/store/slices/projects";
// A cross-feature `import type` (allowed by #1545); `AgentStream` is not on the planner barrel — the
// same import `GlanceWorkspace` itself uses for `FleetPlan`.
import type { AgentStream } from "@/features/planner/fleet/planFleet";

const stream = (over: Partial<AgentStream> = {}): AgentStream =>
  ({ id: "s", name: "s", repo: "acme/r", owns: [], ...over }) as AgentStream;

describe("the harness a model implies", () => {
  it("sends a non-tier model to bsc-agent, and a tier to the default", () => {
    expect(providerForModel("qwen3.5:35b-a3b")).toBe("bsc-agent");
    expect(providerForModel("sonnet-4.5")).toBeUndefined();
    // unset is a real state — NOT "claude"
    expect(providerForModel(undefined)).toBeUndefined();
    expect(providerForModel("")).toBeUndefined();
  });
});

describe("a persona's model survives streamPaneWiring", () => {
  it("adopts a LOCAL model from the persona and derives bsc-agent", () => {
    // The regression: this used to adopt `persona.model` only when it was a Claude tier, so a local
    // name was dropped here and the session launched on Claude Code with nothing reporting it.
    const w = streamPaneWiring(stream(), { role: "worker", model: "qwen3.5:35b-a3b" });
    expect(w.model).toBe("qwen3.5:35b-a3b");
    expect(w.provider).toBe("bsc-agent");
  });

  it("still adopts a tier from the persona, with no provider override", () => {
    const w = streamPaneWiring(stream(), { role: "worker", model: "sonnet-4.5" });
    expect(w.model).toBe("sonnet-4.5");
    expect(w.provider).toBeUndefined();
  });

  it("lets the STREAM's own model win over the persona's", () => {
    // Nearest-first precedence: a fleet stream's model beats the persona's default.
    const w = streamPaneWiring(stream({ model: "haiku-4.5" }), { role: "worker", model: "qwen3.5:9b" });
    expect(w.model).toBe("haiku-4.5");
    expect(w.provider).toBeUndefined();
  });

  it("carries a local model from the STREAM too", () => {
    const w = streamPaneWiring(stream({ model: "qwen3.5:9b" }), { role: "worker" });
    expect(w.model).toBe("qwen3.5:9b");
    expect(w.provider).toBe("bsc-agent");
  });
});

// The pane grammar + charter for the two personas on the crate drill
// (`a-noun-and-its-verbs-launch-their-personas`).
import { describe, it, expect } from "vitest";
import {
  nounPaneId, verbPaneId, surfacePaneIdForNode, surfaceAssignment, surfaceCharter,
  SURFACE_PANE_PREFIX, surfaceOperatorProfile, surfaceOperatorProfileId,
} from "@/features/glance/lib/surfaceSpawn";
import { resolveProfileSettings } from "@/shared/lib/security/profileEnforcement";
import type { CrateDrillDoc } from "@/features/glance/lib/surfaceNodes";

const doc: CrateDrillDoc = {
  crate: "logs", path: "crates/logs", surface: true,
  nouns: [{
    noun: "logs", status: "active", catalog: "projected",
    verbs: [
      { verb: "sessions", summary: "every session, one line each", usage: "USAGE:\n  bsc logs sessions" },
      { verb: "tail", summary: "newest raw lines of one stream", usage: "USAGE:\n  bsc logs tail <stream>" },
    ],
  }],
  dependsOn: [], dependents: [], dependentCount: 0,
};

/** The same crate with NO published catalog — distinct from an empty one. */
const uncatalogued: CrateDrillDoc = { ...doc, nouns: [{ noun: "logs", status: "active", catalog: "unreachable", verbs: null }] };

describe("a surface node's pane is DERIVED from the node", () => {
  it("resolves a noun and a verb, and nothing else", () => {
    expect(surfacePaneIdForNode("noun:logs")).toBe(nounPaneId("logs"));
    expect(surfacePaneIdForNode("verb:logs:sessions")).toBe(verbPaneId("logs", "sessions"));
    // not a surface node — must not mint a pane nothing can match back
    expect(surfacePaneIdForNode("studio-code:director")).toBeNull();
    expect(surfacePaneIdForNode("surface:logs")).toBeNull();
  });

  it("keys a verb pane on BOTH noun and verb", () => {
    // `bsc logs summary` and `bsc perf summary` are different commands; sharing one session would put
    // two maintainers in one terminal and lose whichever arrived second.
    expect(verbPaneId("logs", "summary")).not.toBe(verbPaneId("perf", "summary"));
  });

  it("refuses a malformed verb id rather than guessing", () => {
    // A pane minted from a half-parsed id can never be matched back to a node, so the session becomes
    // unopenable and unkillable — the failure the derived-id rule exists to prevent.
    expect(surfacePaneIdForNode("verb:")).toBeNull();
    expect(surfacePaneIdForNode("verb:logs")).toBeNull();
    expect(surfacePaneIdForNode("verb:logs:")).toBeNull();
    expect(surfacePaneIdForNode("verb::sessions")).toBeNull();
  });

  it("puts every surface pane under one prefix", () => {
    for (const id of [nounPaneId("logs"), verbPaneId("logs", "tail")]) {
      expect(id.startsWith(SURFACE_PANE_PREFIX)).toBe(true);
    }
  });
});

describe("the assignment says which persona and what it is pointed at", () => {
  it("a noun is an OPERATOR, a verb is a MAINTAINER", () => {
    expect(surfaceAssignment("noun:logs", doc)).toEqual({ kind: "operator", crate: "logs", path: "crates/logs", noun: "logs" });
    // THE PATH IS THE FIX. A surface session runs HERE, not at the repo root: `ensure_session_settings`
    // writes `<cwd>/.claude/settings.json`, so a confined session parked at the root wrote its
    // confinement into the tree every other session inherits. It comes from the drill as data — a
    // derived `crates/${crate}` would be a guess about a layout the doc already states.
    expect(surfaceAssignment("noun:logs", doc)?.path).toBe(doc.path);
    expect(surfaceAssignment("verb:logs:tail", doc)).toEqual({
      kind: "maintainer", crate: "logs", path: "crates/logs", noun: "logs", verb: "tail",
    });
  });

  it("is null with no document — the crate is not knowable from the node alone", () => {
    expect(surfaceAssignment("noun:logs", null)).toBeNull();
  });
});

describe("the charter carries the persona's own words, then the assignment", () => {
  it("leads with the persona prompt rather than restating it", () => {
    // ONE copy of what an operator is. A charter that re-described the persona would drift from it, and
    // drift between two descriptions of the same actor is the failure this whole catalog exists to end.
    const c = surfaceCharter({ kind: "operator", crate: "logs", path: "crates/logs", noun: "logs" }, "PERSONA-PROMPT-BODY");
    expect(c.startsWith("PERSONA-PROMPT-BODY")).toBe(true);
  });

  // WAS: "gives the operator the EXACT --surface string its requests must carry". That string was how
  // the request QUEUE routed a finding — and the queue is worked by the debug session, not by the
  // maintainer of the verb (`the-noun-asks-the-verbs-own-session`). The address that matters now is the
  // maintainer's pane, and the charter hands it over already built rather than asking the operator to
  // assemble one.
  it("gives the operator the maintainer's address, already built", () => {
    const c = surfaceCharter({ kind: "operator", crate: "logs", path: "crates/logs", noun: "logs" }, "P", doc);
    expect(c).toContain("bsc session ask surface-studio:verb-logs-sessions");
    expect(c).not.toContain("bsc request new");
  });

  // WAS: "points the maintainer at that same queue". It no longer reads a queue — the operator asks it
  // directly and it answers on that loop. What survives unchanged is the catalog obligation, and it
  // matters MORE now: the operator's charter is generated FROM that catalog, so a stale `CmdDoc`
  // teaches a command that does not run.
  it("points the maintainer at the loop it answers on, and at the catalog it must keep true", () => {
    const c = surfaceCharter({ kind: "maintainer", crate: "logs", path: "crates/logs", noun: "logs", verb: "tail" }, "P", doc);
    expect(c).toContain("bsc session reply");
    expect(c).toContain("bsc surface verbs logs");
    expect(c).toContain("bsc logs tail");
  });
});

// ── the per-pane noun grant (`surface-operator-runs-confined-to-its-own-noun`) ─────────────────────
//
// The operator's ROLE is confined, and `build_allow_rules` returns EARLY under `restricted_allow`
// with only the wrapped allowedCommands — no baseline tiers, no mandatory tier, no `Bash(bsc-*)`. So
// a confined session auto-runs exactly what its allow list names. The role carries the cross-cutting
// half; the noun is chosen per SESSION and can only come from here.
describe("the operator's per-pane profile", () => {
  it("grants ITS noun — the one command the session exists to run", () => {
    const p = surfaceOperatorProfile("studio");
    expect(p.id).toBe(surfaceOperatorProfileId("studio"));
    expect(resolveProfileSettings(p).allowedCommands).toContain("bsc studio");
    // Derived from the noun, so re-opening the same one reuses its row rather than minting a
    // duplicate per launch.
    expect(surfaceOperatorProfileId("persona")).not.toBe(surfaceOperatorProfileId("studio"));
  });

  // THE SAFETY ARGUMENT, and the reason this profile can carry a grant at all. A tool tier of `allow`
  // becomes a VERBATIM rule, so `bash: "allow"` emits a bare `Bash` that auto-approves everything and
  // silently reopens the confinement. `deny` is skipped for bash specifically (a blanket Bash deny
  // would kill the guaranteed git/gh), so it emits NO rule and shell control stays with the allow
  // list. This is the single line that must never be "tidied" to `allow`.
  it("never blanket-allows Bash — that would reopen everything the role closed", () => {
    const p = surfaceOperatorProfile("studio");
    expect(p.tools.bash).toBe("deny");
    const s = resolveProfileSettings(p);
    expect(s.allowToolRules).not.toContain("Bash");
    // and `deny` emits nothing for bash either, so `git`/`gh` are not collaterally killed
    expect(s.denyToolRules).not.toContain("Bash");
  });

  it("carries the bsc-* helpers its charter tells it to use", () => {
    // Shell FUNCTIONS from bsc-env.sh, not the binary: `Bash(bsc *)` cannot match them (no space
    // after `bsc`), and the blanket `Bash(bsc-*)` every unconfined posture gets is on the far side of
    // that early return. Without an explicit grant the charter names a command it cannot run.
    const cmds = resolveProfileSettings(surfaceOperatorProfile("studio")).allowedCommands;
    expect(cmds).toContain("bsc-ask");
    expect(cmds).toContain("bsc-answer");
  });

  it("denies every mutating tool — it reports on a surface, it does not fix one", () => {
    const s = resolveProfileSettings(surfaceOperatorProfile("studio"));
    for (const t of ["Edit", "Write", "WebFetch", "WebSearch", "Task"]) expect(s.denyToolRules).toContain(t);
    expect(s.allowToolRules).toContain("Read");
  });

  // No build toolchain reaches the allow list — the regression that started this: the session ran
  // `cargo run --bin bsc` in the tree the running app owns, to invoke a binary already on its PATH.
  it("grants no build toolchain at all", () => {
    const cmds = resolveProfileSettings(surfaceOperatorProfile("studio")).allowedCommands;
    for (const c of cmds) expect(c.startsWith("bsc")).toBe(true);
    for (const bad of ["cargo", "npm", "python", "python3", "node"]) expect(cmds).not.toContain(bad);
  });
});

// ── the charter TEACHES the surface (`a-session-is-taught-its-surface`) ────────────────────────────
//
// It used to open "Read it first with `bsc <noun> help` and `bsc surface drill <crate> --json`", which
// spent two turns of a twenty-turn budget before anything was run — and left the model inferring the
// command SHAPE. MEASURED: a session reached for `bsc-studio-help`, generalising from the hyphenated
// `bsc-ask`/`bsc-answer` helpers it had been granted. That is not a command at all.
describe("the charter teaches the surface rather than sending the session to find it", () => {
  const op = { kind: "operator", crate: "logs", path: "crates/logs", noun: "logs" } as const;

  it("lists every verb as a literal command line", () => {
    const c = surfaceCharter(op, "P", doc);
    expect(c).toContain("bsc logs sessions");
    expect(c).toContain("every session, one line each");
    expect(c).toContain("bsc logs tail");
    // ...and does NOT send it off to discover what it was just told.
    expect(c).not.toContain("bsc surface drill");
  });

  // THE REGRESSION, named. The hyphen is not a typo the model invented from nothing — it generalised
  // from the helper family, so the charter has to draw the line rather than assume it.
  it("states the command shape, because a hyphenated guess is not a command", () => {
    const c = surfaceCharter(op, "P", doc);
    expect(c).toContain("SPACED, NEVER HYPHENATED");
    expect(c).toContain("`bsc-logs-<verb>` is not a command");
    // `bsc-session` was a real attempt, so it is named rather than left to the general rule. A model
    // that reaches for one hyphenated form reaches for the next.
    expect(c).toContain("`bsc-session`");
  });

  // NAME THE BINARY (`a-session-knows-the-binary-is-bsc`). A session reached for `bsc-session`,
  // apparently to file a request — it knew what it wanted and not what to type. The entry point is
  // stated, and so is the gap between what the APP has and what THIS session may auto-run: a confined
  // role runs exactly its allow list and stops to ask for anything else, which for an unattended
  // session is a stall rather than a refusal it can read.
  it("names the binary and the one command that lists everything", () => {
    const c = surfaceCharter(op, "P", doc);
    expect(c).toContain("THE BINARY IS `bsc`");
    expect(c).toContain("bsc help");
    expect(c).toContain("bsc persona whatami");
    expect(c).toContain("YOUR GRANT IS NARROWER THAN THAT CATALOG");
  });

  it("gives the operator the maintainer's pane id per verb, already built", () => {
    const c = surfaceCharter(op, "P", doc);
    expect(c).toContain("bsc session ask surface-studio:verb-logs-sessions");
    expect(c).toContain("bsc session ask surface-studio:verb-logs-tail");
  });

  // The two instructions the personas replaced. Leaving them here made the charter contradict the
  // persona — and the charter is APPENDED, so its version was the last thing the session read.
  it("no longer routes findings to the request queue or tells a maintainer to claim", () => {
    const c = surfaceCharter(op, "P", doc);
    expect(c).not.toContain("bsc request new");
    const m = surfaceCharter({ ...op, kind: "maintainer", verb: "tail" }, "P", doc);
    expect(m).not.toContain("bsc request claim");
    expect(m).toContain("bsc session reply");
  });

  it("gives the maintainer its own verb's usage and the directory it runs in", () => {
    const m = surfaceCharter({ ...op, kind: "maintainer", verb: "tail" }, "P", doc);
    expect(m).toContain("bsc logs tail <stream>");
    expect(m).toContain("crates/logs");
  });

  // ABSENT IS NOT EMPTY. A crate that serves the noun but publishes no catalog must say so, or the
  // charter reads as "this surface has no verbs" — which describes a broken surface, not a missing doc.
  it("says a catalog is unpublished rather than rendering an empty surface", () => {
    const c = surfaceCharter(op, "P", uncatalogued);
    expect(c).toContain("publishes no verb catalog");
    expect(c).toContain("bsc logs help");
    expect(c).toContain("surface-studio:verb-logs-<verb>");
  });

  it("still degrades to the persona prompt alone when no doc reached it", () => {
    const c = surfaceCharter(op, "PERSONA-PROMPT-BODY", null);
    expect(c.startsWith("PERSONA-PROMPT-BODY")).toBe(true);
    expect(c).toContain("SPACED, NEVER HYPHENATED");
  });
});

