// The RENDERED settings a session actually launches with — the one artifact no other guard reads.
//
// Three defects shipped together in `surface-operator-runs-confined-to-its-own-noun`, and every gate
// leg was green for all of them, because each existed only in the composed result: a granted noun
// that `permissions.deny` also matched, a confined session writing into a shared tree, and a role the
// cage could not classify. The fixtures next door capture SHAPE per role; this asserts a PROPERTY of
// the composition — that the file does not contradict itself.
import { describe, it, expect } from "vitest";
import { buildSessionSettings } from "@/app/console/lib/sessionLaunch";
import { ROLE_DEFAULTS, type SessionRole } from "@/shared/lib/session/sessionRoles";
import type { AppStore } from "@/store/types";

const PANE = "p:0";

/** A REAL catalog, not `[]`. An empty one denies nothing extra by design, so a test that passed one
 *  would assert the invariant against a settings file with no surface denies in it at all — vacuous,
 *  and it passed the bite unchanged until this was fixed. These are the surfaces the operator's noun
 *  is drawn from plus a few it must never reach. */
const CATALOG = [
  { name: "studio" }, { name: "persona" }, { name: "teams" }, { name: "graph" }, { name: "ui" },
  { name: "plan" }, { name: "surface" }, { name: "request" }, { name: "errors" }, { name: "mem" },
  { name: "perf" }, { name: "logs" }, { name: "session" }, { name: "worktree" }, { name: "disk" },
  { name: "component", status: "deprecated" },
];

const BASE = {
  paneRoles: {}, paneProfiles: {}, agentProfiles: [], paneRoleGlobs: {}, deniedCommands: [],
  paneFlows: {}, surfaceCatalog: CATALOG, fleetPaneStreams: {}, appRepoRoot: "/repo", bscBaseDir: "/base",
  mcpServers: [], skills: [], sessionSkillOverrides: {}, sessionSkillGroups: {}, skillGroups: [],
  paneSkills: {}, personas: [], panePersonas: {}, bypassPermissions: false,
} as unknown as AppStore;

/** The command a `Bash(...)` rule names, or null for a whole-tool rule like `Read`. */
function bashPrefix(rule: string): string | null {
  const m = /^Bash\((.*)\)$/.exec(rule);
  if (!m) return null;
  return m[1].replace(/\s*\*$/, "").trim();
}

/**
 * Does `deny` swallow `allow`? Claude Code precedence is deny > ask > allow, so an allow the deny
 * list also matches is not a grant — it is a grant that silently does nothing.
 *
 * A trailing `*` makes a rule a PREFIX; without one it matches the bare command. Both directions
 * matter: `Bash(bsc studio *)` in deny swallows `Bash(bsc studio)` in allow, which is exactly the
 * pair the operator shipped with.
 */
function denySwallows(deny: string, allow: string): boolean {
  const d = bashPrefix(deny), a = bashPrefix(allow);
  if (d === null || a === null) return false;
  return deny.includes("*") ? a === d || a.startsWith(`${d} `) : a === d;
}

function contradictions(settings: { allowedCommands?: string[]; deniedCommands?: string[] }) {
  const allow = (settings.allowedCommands ?? []).map((c) => `Bash(${c})`);
  const deny = (settings.deniedCommands ?? []).map((c) => `Bash(${c})`);
  const out: string[] = [];
  for (const a of allow) for (const d of deny) if (denySwallows(d, a)) out.push(`${a} is granted, and ${d} denies it`);
  return out;
}

const settingsFor = (role: string | undefined, profile?: Record<string, unknown>) =>
  buildSessionSettings(
    {
      ...BASE,
      paneRoles: role ? { [PANE]: role } : {},
      paneProfiles: profile ? { [PANE]: profile.id as string } : {},
      agentProfiles: profile ? [profile] : [],
    } as unknown as AppStore,
    PANE,
  ) as unknown as { allowedCommands?: string[]; deniedCommands?: string[] };

describe("a rendered session never denies what it grants", () => {
  // THE REGRESSION. The operator's noun arrives on a per-pane PROFILE, because a noun chosen per
  // session is not something a static role can name. The undeclared-surface complement was built from
  // the ROLE alone, so `Bash(bsc studio *)` landed in allow AND deny — and deny wins, leaving the one
  // command that session exists to run denied by the same change that granted it.
  it("a granted per-pane noun is not denied by the role's undeclared-surface complement", () => {
    const profile = {
      id: "gen_surface_studio", name: "op", color: "#000", category: "generated", desc: "", mode: "deny",
      commands: ["bsc studio", "bsc-ask", "bsc-answer"],
      tools: { read: "allow", grep: "allow", glob: "allow", edit: "deny", write: "deny", bash: "deny", web: "deny", task: "deny" },
      paths: { allow: [], deny: ["**/*"] }, net: { allow: [] },
    };
    const s = settingsFor("operator", profile);
    expect(s.allowedCommands ?? []).toContain("bsc studio");
    expect(contradictions(s)).toEqual([]);
  });

  // The property, over the whole table — so the next role added cannot reintroduce it quietly.
  it("holds for every role in the capability table", () => {
    for (const role of Object.keys(ROLE_DEFAULTS) as SessionRole[]) {
      expect(contradictions(settingsFor(role)), role).toEqual([]);
    }
  });

  it("holds for a pane with no role at all", () => {
    expect(contradictions(settingsFor(undefined))).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import { UNCAGED_ROLES, isUncagedRole, sandboxPlanFor } from "@/app/console/lib/sessionLaunch";
import type { AppStore } from "@/store/types";

// THE SAME LIST as `UNCAGED_ROLES` in `bsc-sandbox--profile.rs`. The two decide the same question on
// opposite sides of the bridge: Rust decides whether to CAGE, the frontend decides whether to write
// the `/bsc-hook` guest paths that only exist inside a cage. When they disagreed, every launch of
// these panes wrote hooks Rust then had to repair — 13 repairs in one app run, the notice printed in
// the pane each time, because the writer kept regenerating what the repair had just fixed.
const RUST_UNCAGED = ["designer", "architect", "librarian", "director", "integrator", "operator", "steward"];

const state = (role: string | undefined) =>
  ({ paneRoles: role ? { p: role } : {}, sandboxConsoles: false, paneWslDistro: {} } as unknown as AppStore);

describe("uncaged roles — the backend's list, mirrored", () => {
  it("matches the Rust list exactly", () => {
    expect([...UNCAGED_ROLES].sort()).toEqual([...RUST_UNCAGED].sort());
  });

  it("recognises each one, and nothing else", () => {
    for (const r of RUST_UNCAGED) expect(isUncagedRole(r as never), r).toBe(true);
    for (const r of ["worker", "tester", "reviewer", "triage", "juror"]) {
      expect(isUncagedRole(r as never), r).toBe(false);
    }
    expect(isUncagedRole(undefined)).toBe(false);
  });

  it("does NOT plan a namespace for a role the backend will refuse to cage", () => {
    // The bug: a director got backend "namespace", so `namespaceHooks` was true and the settings
    // writer emitted `/bsc-hook` — a path that exists only inside a cage the backend then declined.
    const plan = sandboxPlanFor(state("director"), "p", true);
    expect(plan.backend).not.toBe("namespace");
    expect(plan.namespaceHooks).toBe(false);
    expect(plan.role).toBeUndefined();
  });

  it("still plans a namespace for a role the backend WILL cage", () => {
    // The fix must not disable caging generally — a worker is exactly what the cage is for.
    const plan = sandboxPlanFor(state("worker"), "p", true);
    expect(plan.backend).toBe("namespace");
    expect(plan.namespaceHooks).toBe(true);
    expect(plan.role).toBe("worker");
  });

  it("plans nothing for a pane with no role at all", () => {
    expect(sandboxPlanFor(state(undefined), "p", true).backend).not.toBe("namespace");
  });
});

// Tests for GENERIC rendering of general nodes (#3494, slice 3b of the keystone #3484).
//
// The legacy `kind` path is covered by the existing KitRenderer tests, which are deliberately
// UNMODIFIED by this slice — that they still pass is the parity evidence for the two production
// surfaces (SessionsBehaviorCard, TransformationsBody). These tests cover only the new path.
import { describe, it, expect, vi } from "vitest";
import { render, screen } from "@testing-library/react";
import { KitRenderer } from "@/shared/ui/spec/KitRenderer";
import { validateGeneralNode, type GeneralNode } from "@/shared/ui/spec/generalNode";
import { UI_KIT } from "@/shared/ui/manifest";

describe("generic rendering through the registry (#3494)", () => {
  it("renders a primitive resolved by `type`, not by a per-primitive branch", () => {
    render(<KitRenderer node={{ type: "Text", children: "hello world" } as GeneralNode} />);
    expect(screen.getByText("hello world")).toBeTruthy();
  });

  it("renders nested children recursively", () => {
    const tree: GeneralNode = {
      type: "Stack",
      children: [
        { type: "Text", children: "first" },
        { type: "Text", children: "second" },
      ],
    };
    render(<KitRenderer node={tree} />);
    expect(screen.getByText("first")).toBeTruthy();
    expect(screen.getByText("second")).toBeTruthy();
  });

  it("renders MANY different primitives with no renderer edit — the point of the slice", () => {
    // If the renderer were still branching per primitive, most of these would come back blank. Picking
    // them from the manifest (rather than a hardcoded list) is what makes this a genericity test.
    const simple = UI_KIT.filter((p) =>
      ["Text", "Chip", "Button", "Code", "SectionLabel"].includes(p.name),
    );
    expect(simple.length).toBeGreaterThan(3);
    for (const p of simple) {
      const { unmount } = render(
        <KitRenderer node={{ type: p.name, children: `body-${p.name}` } as GeneralNode} />,
      );
      expect(screen.getByText(`body-${p.name}`), `${p.name} rendered nothing`).toBeTruthy();
      unmount();
    }
  });
});

describe("bindings on the generic path (#3494)", () => {
  it("resolves a DECLARED function prop as an ACTION NAME against the host callbacks", () => {
    // The 3a contract: a data tree binds handlers by NAME; it can never carry a function. The renderer
    // knows WHICH props are handlers from the manifest's declared `type: "function"` — never by
    // guessing from the prop's name.
    const onClick = vi.fn();
    const { container } = render(
      <KitRenderer
        node={{ type: "Toggle", props: { on: true, onClick: "doTheThing" } } as GeneralNode}
        on={{ doTheThing: onClick }}
      />,
    );
    (container.firstElementChild as HTMLElement).click();
    expect(onClick).toHaveBeenCalledOnce();
  });

  it("an unknown action name is a no-op, not a crash", () => {
    // Same tolerance the legacy `button` branch has always had — a missing host callback must not
    // take down a surface that is otherwise fine.
    const { container } = render(
      <KitRenderer
        node={{ type: "Toggle", props: { on: true, onClick: "missing" } } as GeneralNode}
        on={{}}
      />,
    );
    expect(() => (container.firstElementChild as HTMLElement).click()).not.toThrow();
  });

  it("binds a handler on a PASSTHROUGH primitive via the actions map (#3496)", () => {
    // This closes the gap #3494 recorded. `Button` is passthrough and does NOT declare `onClick`, so
    // the manifest cannot tell the renderer that prop is a handler — the actions map states it
    // outright instead of the renderer guessing from the prop's name.
    const onClick = vi.fn();
    render(
      <KitRenderer
        node={{ type: "Button", children: "Go", actions: { onClick: "doTheThing" } } as GeneralNode}
        on={{ doTheThing: onClick }}
      />,
    );
    screen.getByText("Go").click();
    expect(onClick).toHaveBeenCalledOnce();
  });

  it("the actions map WINS over a declared function prop of the same name (#3496)", () => {
    // Documented precedence: the explicit map beats the implicit declared-type path. Asserted rather
    // than left to chance, because "which one wins" is exactly what an author needs to be able to rely
    // on when they reach for the map to disambiguate.
    const viaProp = vi.fn();
    const viaMap = vi.fn();
    const { container } = render(
      <KitRenderer
        node={{ type: "Toggle", props: { on: true, onClick: "fromProp" }, actions: { onClick: "fromMap" } } as GeneralNode}
        on={{ fromProp: viaProp, fromMap: viaMap }}
      />,
    );
    (container.firstElementChild as HTMLElement).click();
    expect(viaMap).toHaveBeenCalledOnce();
    expect(viaProp).not.toHaveBeenCalled();
  });

  it("an unknown action name in the map is a no-op, not a crash", () => {
    const { container } = render(
      <KitRenderer
        node={{ type: "Button", children: "Go", actions: { onClick: "missing" } } as GeneralNode}
        on={{}}
      />,
    );
    expect(() => (container.querySelector("button") as HTMLElement).click()).not.toThrow();
  });
});

describe("failure is visible, never blank (#3494)", () => {
  it("an unresolvable type renders a stated error rather than nothing", () => {
    // A silent blank in a data-driven UI is indistinguishable from "the data said render nothing" —
    // precisely the failure mode this migration must not introduce.
    render(<KitRenderer node={{ type: "NotAPrimitive" } as unknown as GeneralNode} />);
    expect(screen.getByText(/unknown primitive "NotAPrimitive"/)).toBeTruthy();
  });

  it("does not throw on a bad node — one bad node must not white-screen a surface", () => {
    expect(() =>
      render(<KitRenderer node={{ type: "AlsoNotReal" } as unknown as GeneralNode} />),
    ).not.toThrow();
  });
});

// #3500 — the legacy `kind` vocabulary is GONE. A tree carrying one is no longer a second dialect the
// renderer understands; it is simply an invalid node, and must fail the way any invalid node does:
// visibly, without throwing. (The interop suite that used to live here tested a coexistence that no
// longer exists, so keeping it would have asserted the opposite of the contract.)
describe("the retired vocabulary is not silently accepted (#3500)", () => {
  it("a node carrying the legacy `kind` discriminant does not validate", () => {
    const legacy = { kind: "text", text: "legacy" } as unknown as GeneralNode;
    expect(validateGeneralNode(legacy)).toEqual(['$: missing string "type"']);
  });

  it("a legacy node nested in a general tree does not validate either", () => {
    const tree = {
      type: "Stack",
      children: [{ kind: "text", text: "legacy child" }],
    } as unknown as GeneralNode;
    // The `children` slot rejects it as a non-node, and the walk does not descend into it — one clear
    // error at the container, not a confusing cascade from inside a node that was never valid.
    expect(validateGeneralNode(tree)).toEqual(["$.props.children: expected nodes or text"]);
  });

  it("rendering one shows a visible error instead of silently dropping it", () => {
    const legacy = { kind: "text", text: "legacy" } as unknown as GeneralNode;
    render(<KitRenderer node={legacy} />);
    expect(screen.getByText(/unknown primitive/)).toBeTruthy();
  });
});

// `discovery-chooses-the-model` — the PROJECT's level of the model precedence chain.
//
// The chain, nearest first:
//     a fleet stream's own model  (bsc plan fleet model)
//       > a team placement's      (bsc teams model)          the NODE
//       > the project's own       (bsc plan classify.model)  DISCOVERY
//       > the persona's default   (bsc persona model)
//       > the harness's own default (no --model at all)
//
// Every one of these is tested as a SEPARATION rather than in isolation: a level only means anything
// relative to the ones on either side of it, and a test that sets one level with the others empty
// passes for a chain assembled in any order.
import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import type { AgentStream, FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

const NAME = "discovery-model-test";
const KEY = sanitizeProjectKey(NAME);
const HUB = "/home/user/.base-studio-code/projects/discovery-model-test";
const PANE = `${KEY}:curator`;

const fleet = (streams: AgentStream[]): FleetPlan => ({ recommended: 1, reasoning: "t", streams, director: { enabled: false } });
const persona: Persona = { id: "persona-curator", name: "Curator", blurb: "", role: "curator", startPrompt: "curate", skills: [] };
const stream: AgentStream = { id: "curator", name: "Curator", repo: "", owns: [], issues: [], dependsOn: [], persona: "persona-curator" };

/** Seat the store with one persona and one project classification, then launch. */
function launch(opts: { personaModel?: string; projectModel?: string; streamModel?: string }) {
  useAppStore.setState({
    tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
    paneProviders: {},
    personas: [{ ...persona, ...(opts.personaModel ? { model: opts.personaModel } : {}) }],
    planClassification: opts.projectModel ? { [KEY]: { model: opts.projectModel } } : {},
  });
  useAppStore.getState().fleetStartProject(
    NAME,
    fleet([{ ...stream, ...(opts.streamModel ? { model: opts.streamModel } : {}) }]),
    KEY,
    { hubPath: HUB },
  );
  return useAppStore.getState();
}

describe("the project's discovery model", () => {
  beforeEach(() => {
    useAppStore.setState({ tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, personas: [persona], planClassification: {} });
  });

  it("beats the persona's default — a global identity is further away than this project", () => {
    // THE BITE. Before this, `classify.model` reached no launch at all: the architect could record the
    // decision and every session went on resolving `sess.model ?? persona.model`, so the project ran
    // on the persona's tier while the classification said otherwise. A recorded decision that changes
    // nothing is worse than an absent one — it reads as settled.
    expect(launch({ personaModel: "opus-4.5", projectModel: "haiku-4.5" }).paneModels[PANE]).toBe("haiku-4.5");
  });

  it("LOSES to the stream's own model, which already carries the node's placement", () => {
    // The nearer pair. `teamRoleStreams` puts a team placement's model on the stream, so beating
    // `sess.model` here would make a per-NODE choice unreachable — the thing
    // `a-node-cannot-carry-a-local-model` had just finished making possible.
    expect(launch({ personaModel: "opus-4.5", projectModel: "haiku-4.5", streamModel: "sonnet-4.5" }).paneModels[PANE])
      .toBe("sonnet-4.5");
  });

  it("applies when the persona has no default of its own", () => {
    expect(launch({ projectModel: "haiku-4.5" }).paneModels[PANE]).toBe("haiku-4.5");
  });

  it("falls through to the persona when the project made no choice", () => {
    // Non-regression for every project classified before this axis existed: an absent project model
    // must be indistinguishable from the axis not existing.
    expect(launch({ personaModel: "opus-4.5" }).paneModels[PANE]).toBe("opus-4.5");
  });

  it("leaves the pane with NO model when no level names one", () => {
    // An entry here would be the app choosing a tier on the user's behalf; the harness's own default
    // is what "nobody decided" has to mean.
    expect(launch({}).paneModels[PANE]).toBeUndefined();
  });

  it("routes the whole project to bsc-agent when discovery chose a LOCAL model", () => {
    // The point of the axis for today's work: ONE write moves a project onto the local runtime,
    // rather than one write per node. Asserting only `paneModels` would pass with the session still
    // launching Claude Code.
    const s = launch({ personaModel: "opus-4.5", projectModel: "qwen3.5:35b-a3b" });
    expect(s.paneModels[PANE]).toBe("qwen3.5:35b-a3b");
    expect(s.paneProviders[PANE]).toBe("bsc-agent");
  });

  it("lets ONE node stay on Claude inside a locally-classified project", () => {
    // The direction that proves the levels are ordered rather than merged: the project says local,
    // the stream (a node's placement, carried by `teamRoleStreams`) says a tier, and the tier wins.
    const s = launch({ projectModel: "qwen3.5:35b-a3b", streamModel: "opus-4.5" });
    expect(s.paneModels[PANE]).toBe("opus-4.5");
    expect(s.paneProviders[PANE]).not.toBe("bsc-agent");
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
