// ls-stream: unit tests for the load migration stream wiring in fleetStartProject (#ls-stream).
//
// Verifies that when a fleet plan contains the "load-stream" AgentStream with the correct
// owns/dependsOn, fleetStartProject wires paneRoleGlobs, fleetPaneStreams, and the startup
// prompt doc correctly — without requiring a real git worktree or Tauri process.

import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import { resetFleetPanes } from "@/test/storeReset";
import type { AgentStream, FleetPlan } from "@/features/planner/fleet/planFleet";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

const LOAD_STREAM_OWNS = [
  "src/store/index.ts",
  "src-tauri/src/lib.rs",
  "@/features/planner/LoadReconcile.tsx",
  "crates/data/src/reconcile.rs",
  "crates/data/src/ddl.rs",
  "prompts/load-stream-kickoff.md",
  "src/__tests__/loadStream.test.ts",
  "src/__tests__/loadReconcile.test.tsx",
];

function loadStream(p: Partial<AgentStream> = {}): AgentStream {
  return {
    id: "load-stream",
    name: "Build-time load",
    repo: "org/studio-code",
    owns: LOAD_STREAM_OWNS,
    issues: ["ls-stream", "ls-reconcile-ui", "ls-lineage-verify"],
    dependsOn: ["source-experience"],
    prompt: "prompts/load-stream-kickoff.md",
    ...p,
  };
}

function fleet(streams: AgentStream[]): FleetPlan {
  return {
    recommended: 2,
    reasoning: "test",
    streams,
    director: { enabled: false },
  };
}

const PROJECT_NAME = "migration-test";
const PROJECT_KEY  = sanitizeProjectKey(PROJECT_NAME);

describe("load-stream fleet wiring (#ls-stream)", () => {
  beforeEach(() => {
    // #3836: `paneRoleGlobs` is what this suite ASSERTS on and a sibling launch populates it, so it
    // has to be cleared here or a later test reads the earlier project's globs.
    resetFleetPanes();
    useAppStore.setState({ tabs: [], bscBaseDir: "/home/user/.base-studio-code" });
  });

  it("paneRoleGlobs contains all load-stream owns, expanding trailing-slash globs", () => {
    const rows = useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([loadStream()]), PROJECT_KEY);
    const { paneRoleGlobs } = useAppStore.getState();

    // Find the pane the LOAD STREAM landed in — by its stream id, not by "the first pane with any
    // globs". The commons lane carries globs now (#funnel-commons-and-integration-streams) and it
    // launches FIRST, so a positional lookup silently reads the commons set instead.
    const { fleetPaneStreams } = useAppStore.getState();
    const paneId = Object.keys(fleetPaneStreams).find((k) => fleetPaneStreams[k].id === "load-stream");
    expect(paneId).toBeDefined();
    const globs = paneRoleGlobs[paneId!];

    // Every owned path from LOAD_STREAM_OWNS should appear in the role globs
    for (const owned of LOAD_STREAM_OWNS) {
      const expected = owned.endsWith("/") ? owned + "**" : owned;
      expect(globs).toContain(expected);
    }

    // One roster row per session: the load stream plus the two lanes every project now gets.
    expect(rows.length).toBe(3);
  });

  it("fleetPaneStreams records the load-stream AgentStream", () => {
    useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([loadStream()]), PROJECT_KEY);
    const { fleetPaneStreams } = useAppStore.getState();
    const streams = Object.values(fleetPaneStreams);
    // The load stream plus the commons + integration lanes.
    expect(streams.length).toBe(3);
    const s = streams.find((x) => x.id === "load-stream")!;
    expect(s).toBeDefined();
    expect(s.dependsOn).toContain("source-experience");
    expect(s.issues).toEqual(expect.arrayContaining(["ls-stream", "ls-reconcile-ui", "ls-lineage-verify"]));
  });

  it("paneStartupPromptDocs points to the kickoff relpath when stream.prompt is set", () => {
    useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([loadStream()]), PROJECT_KEY);
    const { paneStartupPromptDocs } = useAppStore.getState();
    const docs = Object.values(paneStartupPromptDocs);
    // The doc relpath is built as scriptDocRelpath(safeKey, sess.prompt)
    expect(docs.some((d) => d.includes("load-stream-kickoff.md"))).toBe(true);
  });

  it("a stream without a prompt falls back to paneStartupPromptText", () => {
    const streamNoPrompt = loadStream({ prompt: undefined });
    useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([streamNoPrompt]), PROJECT_KEY);
    const { paneStartupPromptText } = useAppStore.getState();
    const texts = Object.values(paneStartupPromptText);
    // fallback text should mention the stream name / id
    expect(texts.some((t) => t.includes("load-stream") || t.includes("Build-time load"))).toBe(true);
  });

  it("a fleet with two streams produces a pane wiring entry per stream, plus the two lanes", () => {
    const second: AgentStream = {
      id: "source-experience", name: "Source XP", repo: "org/studio-code",
      owns: ["src-tauri/src/data.rs"], issues: ["se-1"], dependsOn: [],
    };
    useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([loadStream(), second]), PROJECT_KEY);
    const streams = Object.values(useAppStore.getState().fleetPaneStreams);
    // Two feature streams + the commons and integration lanes. Both streams share a repo here, so it
    // is ONE pair of lanes, not one pair per stream.
    expect(streams).toHaveLength(4);
    expect(streams.map((s) => s.id)).toEqual(
      expect.arrayContaining(["load-stream", "source-experience", "commons", "integration"]),
    );
  });

  it("gives a DIRECTOR-LESS fleet the commons lane — the owner is a worker, not the director", () => {
    // This whole suite runs `director: { enabled: false }`. Before the funnel that meant NO commons
    // set was derived at all (the DIRECTOR was the steward, so a director-less fleet had none) and
    // every feature stream was left free to write `.gitignore`. That gap is what these lanes close.
    useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([loadStream()]), PROJECT_KEY);
    const { fleetPaneStreams, paneRoleGlobs } = useAppStore.getState();
    const commonsPane = Object.keys(fleetPaneStreams).find((k) => fleetPaneStreams[k].id === "commons");
    expect(commonsPane).toBeDefined();
    expect(paneRoleGlobs[commonsPane!]).toContain(".gitignore");
    // …and the feature stream gates on it rather than racing it.
    const load = Object.values(fleetPaneStreams).find((s) => s.id === "load-stream")!;
    expect(load.dependsOn).toContain("commons");
  });
});

import { describe, it, expect, beforeEach, vi } from "vitest";
import { useAppStore } from "./";
import { STOP_NOTICE_MS } from "@/app/console/lib/paneStops";

vi.mock("@/shared/lib/core/log", () => ({
  log: { debug: vi.fn(), info: vi.fn(), warn: vi.fn(), error: vi.fn() },
}));
const { log } = await import("@/shared/lib/core/log");

/**
 * #a-stopped-session-says-why — the STORE half.
 *
 * The reason for an app-side stop is the ACTION that ran, so each stop action reports itself. That
 * placement is the point: it is why a new caller of `reapPane` cannot forget to say why, and it is
 * what this file pins.
 */
describe("a stopped pane reports itself (#a-stopped-session-says-why)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useAppStore.setState({
      paneStops: [], dormantPanes: {}, endedPanes: {}, quarantinedPanes: {}, disabledPanes: {},
      paneStatus: {}, tabs: [],
    });
  });

  const stops = () => useAppStore.getState().paneStops;

  it("the IDLE REAPER marks the pane dormant and reports NOTHING — Rust already did", () => {
    // The reap happens in the backend, which kills the session and sends `reaped` on `pty_exit`.
    // This used to ALSO report it, so one reap produced two notices for one pane in different words
    // and the ledger's replace-per-pane rule kept whichever landed last. MEASURED 2026-09-10: eight
    // reaped directors all read "closed by the app", because that race resolved the other way.
    useAppStore.getState().reapPane("proj:worker");
    expect(stops()).toHaveLength(0);
    // What it DOES do is the state the backend cannot set: dormant is persisted, so the pane renders
    // a resume placeholder and does not relaunch on the next boot.
    expect(useAppStore.getState().dormantPanes["proj:worker"]).toBe(true);
  });

  it("reports the reap when RUST says so, in Rust's words", () => {
    // The same event, arriving the one way it now arrives: on the exit payload, already classified.
    useAppStore.getState().markPaneEnded("proj:worker", {
      state: "done", streamId: "worker", summary: "", at: 1,
      exit: { reason: "reaped", detail: "Reclaimed while idle — the reaper took it back. It resumes when you open it." },
    });
    expect(stops()).toHaveLength(1);
    expect(stops()[0].reason).toBe("reaped");
    expect(stops()[0].detail).toMatch(/idle/i);
  });

  it("WORKER AUTO-END carries the completeness summary the user would otherwise have to go find", () => {
    useAppStore.getState().markPaneEnded("proj:worker", {
      state: "needs-attention", streamId: "worker", summary: "stopped early — 1/1 still open", at: 1,
    });
    expect(stops()[0].reason).toBe("auto-ended");
    expect(stops()[0].detail).toBe("stopped early — 1/1 still open");
  });

  it("a WARDEN QUARANTINE reports the warden's own summary", () => {
    useAppStore.getState().markQuarantine("proj:worker", { summary: "wrote outside its lane" } as never);
    expect(stops()[0].reason).toBe("quarantined");
    expect(stops()[0].detail).toBe("wrote outside its lane");
  });

  it("DISABLING a pane is a stop; RE-ENABLING it is not an event", () => {
    useAppStore.getState().setPaneDisabled("proj:worker", true);
    expect(stops()).toHaveLength(1);
    expect(stops()[0].reason).toBe("disabled");
    useAppStore.getState().setPaneDisabled("proj:worker", false);
    // Turning it back on is not a stop — reporting it would make the banner fire on a recovery.
    expect(stops()).toHaveLength(1);
  });

  it("never re-reports a stop the action itself refuses to repeat", () => {
    // Each action guards against re-marking; the report sits INSIDE that guard, so a second call is
    // silent rather than a duplicate banner.
    useAppStore.getState().markPaneEnded("proj:a", { state: "done", streamId: "a", summary: "done", at: 1 });
    useAppStore.getState().markPaneEnded("proj:a", { state: "done", streamId: "a", summary: "again", at: 2 });
    expect(stops().filter((s) => s.paneId === "proj:a")).toHaveLength(1);
  });

  /// The banner lasts five seconds; THIS is what answers the question afterwards, so it is written
  /// unconditionally — and the level is what makes `grep WARN` a list of sessions that DIED.
  it("LOGS every stop, faults at warn and routine ones at info", () => {
    useAppStore.getState().notePaneStopped("proj:w", "failed", "exited 1");
    expect(log.warn).toHaveBeenCalledTimes(1);
    expect(vi.mocked(log.warn).mock.calls[0][0]).toContain("proj:w");
    expect(vi.mocked(log.warn).mock.calls[0][0]).toContain("exited 1");
    // (message, scope) — the swap is invisible to tsc because both are strings.
    expect(vi.mocked(log.warn).mock.calls[0][1]).toBe("session");

    useAppStore.getState().notePaneStopped("proj:x", "finished", "exited 0");
    expect(log.info).toHaveBeenCalledTimes(1);
    expect(log.warn).toHaveBeenCalledTimes(1);
  });

  it("keeps only the NEWEST stop per pane — the reported worker stopped nine times in one run", () => {
    useAppStore.getState().notePaneStopped("proj:w", "failed", "first");
    useAppStore.getState().notePaneStopped("proj:w", "signalled", "second");
    expect(stops()).toHaveLength(1);
    expect(stops()[0].detail).toBe("second");
  });

  it("is TRANSIENT — the ledger is not in the persisted snapshot", async () => {
    // A notice that survives a restart is a notice about a session the user is no longer looking at.
    const { persistedState } = await import("@/store/persist");
    useAppStore.getState().notePaneStopped("proj:w", "failed", "boom");
    expect(persistedState(useAppStore.getState() as never)).not.toHaveProperty("paneStops");
  });

  it("stamps `at` so the notice can expire on its own", () => {
    const before = Date.now();
    useAppStore.getState().notePaneStopped("proj:w", "failed", "boom");
    const { at } = stops()[0];
    expect(at).toBeGreaterThanOrEqual(before);
    expect(at).toBeLessThanOrEqual(Date.now());
    expect(STOP_NOTICE_MS).toBe(5_000);
  });
});

// Team role-actor hub launch (#3103): a repo-less stream — the shape `teamRoleStreams` emits for a
// team's curator/documentor/… — must launch at the project HUB (like the director), NOT in a per-repo
// worktree, while its persona still drives the pane role. Workers are unaffected. Verified through
// fleetStartProject without a real git worktree or Tauri process (mirrors loadStream.test.ts).

import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import type { AgentStream, FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

const NAME = "team-launch-test";
const KEY = sanitizeProjectKey(NAME);
const HUB = "/home/user/.base-studio-code/projects/team-launch-test";

const fleet = (streams: AgentStream[]): FleetPlan => ({ recommended: 1, reasoning: "t", streams, director: { enabled: false } });

const curatorPersona: Persona = { id: "persona-curator", name: "Curator", blurb: "", role: "curator", startPrompt: "harvest the library", skills: [] };

// A repo-less role-actor stream (exactly what teamRoleStreams produces).
const curatorStream: AgentStream = { id: "curator", name: "Curator", repo: "", owns: [], issues: [], dependsOn: [], persona: "persona-curator" };
const workerStream: AgentStream = { id: "engine", name: "Engine", repo: "org/app", owns: ["src/**"], issues: ["#1"], dependsOn: [] };

describe("team role-actor hub launch (#3103)", () => {
  beforeEach(() => {
    useAppStore.setState({ tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, personas: [curatorPersona] });
  });

  it("routes a repo-less role-actor to the HUB cwd and its persona role; the worker keeps its worktree", () => {
    useAppStore.getState().fleetStartProject(NAME, fleet([workerStream, curatorStream]), KEY, {
      hubPath: HUB, worktreePaths: { engine: "/wt/engine" },
    });
    const s = useAppStore.getState();
    const curatorPane = `${KEY}:curator`;
    expect(s.paneRoles[curatorPane]).toBe("curator");   // persona resolves the role
    expect(s.paneCwds[curatorPane]).toBe(HUB);           // hub-scoped, NOT a worktree path
    // The worker is unaffected — worktree cwd + worker role.
    const workerPane = `${KEY}:engine`;
    expect(s.paneRoles[workerPane]).toBe("worker");
    expect(s.paneCwds[workerPane]).toBe("/wt/engine");
  });

  // ── the model a role-actor launches on (a-model-cannot-be-chosen-from-the-command-surface) ────
  //
  // End to end, because the value crosses three hands — the team record, `teamRoleStreams`, and this
  // launch — and the middle one is the only place a unit test would otherwise see it.

  it("launches a role-actor on its placement's model, then the persona's, then the harness default", () => {
    // A persona carrying its own default, placed once. The stream shape is what `teamRoleStreams`
    // emits: the placement's override (when there is one) lands on `model`.
    useAppStore.setState({
      tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
      personas: [{ ...curatorPersona, model: "opus-4.5" }],
    });
    useAppStore.getState().fleetStartProject(NAME, fleet([{ ...curatorStream, model: "haiku-4.5" }]), KEY, { hubPath: HUB });
    // The placement wins over the persona's default — the point of the override.
    expect(useAppStore.getState().paneModels[`${KEY}:curator`]).toBe("haiku-4.5");

    // No override → the persona's own default.
    useAppStore.setState({ tabs: [], fleetPaneStreams: {}, paneModels: {} });
    useAppStore.getState().fleetStartProject(NAME, fleet([curatorStream]), KEY, { hubPath: HUB });
    expect(useAppStore.getState().paneModels[`${KEY}:curator`]).toBe("opus-4.5");

    // Neither → NO pane model at all, which is what makes the session launch with no `--model` and run
    // on Claude Code's own default. An entry here would be the app choosing a tier on the user's behalf.
    useAppStore.setState({ tabs: [], fleetPaneStreams: {}, paneModels: {}, personas: [curatorPersona] });
    useAppStore.getState().fleetStartProject(NAME, fleet([curatorStream]), KEY, { hubPath: HUB });
    expect(useAppStore.getState().paneModels[`${KEY}:curator`]).toBeUndefined();
  });

  it("launches a role-actor on a LOCAL model, and routes it to bsc-agent rather than Claude", () => {
    // `a-node-cannot-carry-a-local-model`, at the far end. The unit half is
    // `src/features/planner/fleet/teamFleet.test.ts` (the position → stream hop, where the value used
    // to be dropped); this is the half that proves a carried local model actually changes which
    // HARNESS the session runs on. Asserting only `paneModels` would pass with the session still
    // launching Claude Code — the exact silent-no-op shape the item was filed about.
    useAppStore.setState({
      tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
      paneProviders: {}, personas: [curatorPersona],
    });
    useAppStore.getState().fleetStartProject(NAME, fleet([{ ...curatorStream, model: "qwen3.5:35b-a3b" }]), KEY, { hubPath: HUB });
    const pane = `${KEY}:curator`;
    expect(useAppStore.getState().paneModels[pane]).toBe("qwen3.5:35b-a3b");
    expect(useAppStore.getState().paneProviders[pane]).toBe("bsc-agent");
  });

  it("keeps a Claude TIER on the claude harness — the local routing is derived, not global", () => {
    // The counterpart that stops the fix from over-reaching: `providerForModel` derives `bsc-agent`
    // from a model being OUTSIDE the tier registry, so a tier must go on producing no such provider.
    useAppStore.setState({
      tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
      paneProviders: {}, personas: [curatorPersona],
    });
    useAppStore.getState().fleetStartProject(NAME, fleet([{ ...curatorStream, model: "haiku-4.5" }]), KEY, { hubPath: HUB });
    expect(useAppStore.getState().paneProviders[`${KEY}:curator`]).not.toBe("bsc-agent");
  });

  it("falls back to the derived hub dir when no absolute hubPath is passed (never a worktree path)", () => {
    useAppStore.getState().fleetStartProject(NAME, fleet([curatorStream]), KEY);
    const cwd = useAppStore.getState().paneCwds[`${KEY}:curator`];
    // Derived hub path (projectHubCwd) — contains the project key under the base dir, and is NOT the
    // worktrees tree (a repo-less stream must never resolve to an agentWorktreeCwd).
    expect(cwd).toContain(KEY);
    expect(cwd).not.toContain("worktrees");
  });
});

import { describe, it, expect, beforeEach, vi } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "./";
import { triagePaneId } from "@/app/console/lib/paneIdentity";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

// #1004: prepareTriageRun reads plan.db (last-run marker + changed-since delta), renders the resume
// lead, and stamps a fresh marker; triageStartProject leads each pane's prompt with that delta.
const mockInvoke = vi.mocked(invoke);
const issue = (ref: string, status: string) => ({
  ref, title: ref, status, acceptance: [], owns: [], dependsOn: [], labels: [],
});

describe("prepareTriageRun (#1004)", () => {
  beforeEach(() => mockInvoke.mockReset());

  // The triage markers now route through the `bsc` bridge (#2114): the reads are `bsc plan triage
  // last|changed|record`, dispatched via `invoke("bsc", { projectKey, args })` and JSON-parsed from
  // stdout by bscJson (so the mock returns a JSON STRING, "" for a void verb).
  // Null-safe: the store's async rehydrate migration fires background `invoke`s that can settle during
  // teardown with undefined args — don't throw on those.
  const triageArgs = (args: unknown): string[] => (args as { args?: string[] } | undefined)?.args ?? [];

  it("first run (no marker) → empty lead, never queries changed-since, stamps a marker", async () => {
    mockInvoke.mockImplementation(async (_cmd, args) =>
      triageArgs(args)[2] === "last" ? JSON.stringify(null) : "");
    const deltas = await useAppStore.getState().prepareTriageRun("proj", ["o/web"]);
    expect(deltas["o/web"]).toBe("");
    expect(mockInvoke).not.toHaveBeenCalledWith("bsc", expect.objectContaining({ args: expect.arrayContaining(["changed"]) }));
    expect(mockInvoke).toHaveBeenCalledWith("bsc", { projectKey: "proj", args: ["plan", "triage", "record", "o/web"] });
  });

  it("subsequent run → leads with the changed-issue delta and re-stamps", async () => {
    mockInvoke.mockImplementation(async (_cmd, args) => {
      const a = triageArgs(args);
      if (a[2] === "last") return JSON.stringify(1000);
      if (a[2] === "changed") return JSON.stringify([issue("F1", "complete"), issue("F2", "blocked")]);
      return "";
    });
    const deltas = await useAppStore.getState().prepareTriageRun("proj", ["o/web"]);
    expect(deltas["o/web"]).toContain("2 issue(s) changed");
    expect(deltas["o/web"]).toContain("landed F1");
    expect(deltas["o/web"]).toContain("blocked/failed F2");
    expect(mockInvoke).toHaveBeenCalledWith("bsc", { projectKey: "proj", args: ["plan", "triage", "changed", "o/web", "--since", "1000"] });
    expect(mockInvoke).toHaveBeenCalledWith("bsc", { projectKey: "proj", args: ["plan", "triage", "record", "o/web"] });
  });

  it("a per-repo bsc failure degrades to the fallback (non-fatal) — the other repos still resolve", async () => {
    mockInvoke.mockImplementation(async (_cmd, args) => {
      const a = triageArgs(args);
      if (a[2] === "last") {
        // bscJson swallows a rejected read and returns its fallback (null), so a broken repo no
        // longer aborts — it renders the empty (full-prompt) lead like a first run.
        if (a[3] === "o/bad") throw new Error("db locked");
        return JSON.stringify(null);
      }
      return "";
    });
    const deltas = await useAppStore.getState().prepareTriageRun("proj", ["o/bad", "o/good"]);
    expect(deltas["o/good"]).toBe("");
    expect(deltas["o/bad"]).toBe("");
  });
});

describe("triageStartProject deltas (#1004)", () => {
  it("leads the default triage prompt with the supplied per-repo delta", () => {
    // Token AND a remote-integrating strategy — see store.test.ts.
    useAppStore.setState({
