// #fleet-wake-reaches-a-session-with-no-pane — the director's one lever over a stopped stream.
//
// Reported from a running fleet: "the director is unable to wake sessions that aren't running."
// `wakePane` resolved the owning tab and bailed when there was none, so it could only ever wake a pane
// that ALREADY EXISTED in an open tab — which is the opposite of the case the director protocol names
// it for ("a stream still has open issues but its session is not live").
//
// It matters more now than when it was filed: under the no-app-injection directive the app never starts
// or prompts a session, so a stream that has stopped has exactly ONE way back that is not a user click,
// and this is it.
//
// NOTE the adjacent fix this is NOT: #4025 made wake resolve the owning tab by IDENTITY rather than by
// the retired positional id, which fixed wake for panes that exist. This is the pane that does not.
import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import { resetFleetPanes } from "@/test/storeReset";
import { fleetPaneId } from "@/app/console/lib/paneIdentity";

const KEY = "demo";
const STREAM = "api";
const PANE = fleetPaneId(KEY, STREAM);

/** A build tab for `demo` that does NOT contain the api pane — a closed-and-reopened fleet, or a
 *  stream that was planned but never launched. */
function buildTab(paneIds: string[]) {
  return {
    id: "tab-1", name: "Demo · build", layout: "2×2", state: "idle",
    runId: 1, projectKey: KEY, kind: "build" as const, seq: 0, paneIds,
  };
}

/** Arm the store as a real fleet leaves it: the roster knows the stream, the tab does not hold it. */
function arm(paneIds: string[], over: Record<string, unknown> = {}) {
  useAppStore.setState({
    tabs: [buildTab(paneIds)],
    fleetPaneStreams: { [PANE]: { id: STREAM, name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [] } },
    disabledPanes: {},
    dormantPanes: {},
    endedPanes: {},
    ...over,
  } as never);
}

describe("wakePane reaches a stream whose pane does not exist", () => {
  beforeEach(() => { resetFleetPanes(); useAppStore.setState({ tabs: [] }); });

  it("creates the pane in the project's build tab and reports success", () => {
    // The regression: an empty `paneIds` used to make `findPaneOwnerTab` return null and wake return
    // false, which the Rust side surfaces as "it resolved to no open tab, or is disabled".
    arm([]);
    const ok = useAppStore.getState().wakePane(PANE, "pick up your open issues");
    expect(ok, "wake must succeed for a planned stream with no pane").toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
  });

  it("bumps the owning tab's runId, so the new pane actually mounts", () => {
    // Seating the pane without the remount would leave the grid rendering yesterday's cells.
    arm([]);
    useAppStore.getState().wakePane(PANE, "go");
    expect(useAppStore.getState().tabs[0].runId).toBe(2);
  });

  it("bakes the prompt and asks to RESUME, exactly as an existing-pane wake does", () => {
    // This asserted `false` — describing the behaviour rather than justifying it, and the two wake
    // paths agreed on the wrong thing. `plan_launch` computes `resume: continue_session &&
    // has_history`, so a cleared flag meant a woken worker could never continue however much history
    // it had: it re-read its kickoff and started over. Waking a parked worker is by definition
    // "pick this back up", and with no history the launch still starts fresh and still delivers the
    // prompt, because `resume` needs both halves.
    arm([]);
    useAppStore.getState().wakePane(PANE, "pick up #12");
    const st = useAppStore.getState();
    expect(st.paneStartupPromptText[PANE]).toBe("pick up #12");
    expect(st.paneContinue[PANE]).toBe(true);
  });

  it("fills a FREE cell before extending the grid", () => {
    // A reaped fleet leaves holes. Appending past them would grow the layout for no reason and leave
    // an empty cell in the middle of the grid.
    arm(["demo:director", "", "demo:web"]);
    useAppStore.getState().wakePane(PANE, "go");
    expect(useAppStore.getState().tabs[0].paneIds).toEqual(["demo:director", PANE, "demo:web"]);
  });

  it("REFUSES a stream that is not in the project's fleet — an unknown stream is a real error", () => {
    // The acceptance draws this line deliberately: an UNLAUNCHED stream is not an error, an UNKNOWN one
    // is. `fleetPaneStreams` is the roster, so its absence is what distinguishes them.
    arm([]);
    expect(useAppStore.getState().wakePane(fleetPaneId(KEY, "not-a-stream"), "go")).toBe(false);
    expect(useAppStore.getState().tabs[0].paneIds).toEqual([]);
  });

  it("mints a fresh build tab when the project has NO tab at all (#165)", () => {
    // The regression this fixes: a stream already in the roster (it ran once) but its build tab was
    // closed ENTIRELY — not just missing this one pane. The old refusal ("that is a relaunch, not a
    // wake") sent a director straight past this lever to a whole-fleet `bsc fleet start --force`, just
    // to reseat one pane and repair its `.claude/settings.json` (request #165).
    useAppStore.setState({
      tabs: [],
      fleetPaneStreams: { [PANE]: { id: STREAM, name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [] } },
    } as never);
    expect(useAppStore.getState().wakePane(PANE, "go")).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    expect(tab.kind).toBe("build");
    expect(tab.projectKey).toBe(KEY);
    expect(tab.paneIds).toContain(PANE);
  });

  it("SEATS a disabled pane and clears the flag — a wake revives, it does not refuse", () => {
    // This asserted the opposite. Maintainer's call (2026-08-26), after being blocked three times:
    // ending a session must not prevent the director from restarting it. The old refusal made
    // `disabledPanes` a permanent, director-unreachable state — only a Console pane-menu toggle
    // clears it — so "paused" and "ended twenty minutes ago" were the same thing, forever.
    arm([], { disabledPanes: { [PANE]: true } });
    expect(useAppStore.getState().wakePane(PANE, "go")).toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
    expect(useAppStore.getState().disabledPanes[PANE]).toBeUndefined();
  });

  it("leaves the EXISTING-pane path exactly as it was (#4025 must not regress)", () => {
    arm([PANE], { dormantPanes: { [PANE]: true }, endedPanes: { [PANE]: true } });
    const before = useAppStore.getState().tabs[0].paneIds;
    expect(useAppStore.getState().wakePane(PANE, "resume")).toBe(true);
    const st = useAppStore.getState();
    expect(st.tabs[0].paneIds).toEqual(before);          // not re-seated, not duplicated
    expect(st.dormantPanes[PANE]).toBeUndefined();        // the reaped placeholder is cleared…
    expect(st.endedPanes[PANE]).toBeUndefined();          // …and so is the ended mark
    expect(st.tabs[0].runId).toBe(2);
  });
});

// ── STARTING a stream that never launched (#the-director-cannot-start-a-stream-that-never-launched) ──
//
// Reported from a running fleet: "the director is unable to start sessions that aren't already opened."
//
// The refusal above (`REFUSES a stream that is not in the project's fleet`) used `fleetPaneStreams` as
// the oracle for "is this a real stream". But that map is written by `fleetStartProject` alone, so it is
// the roster of what LAUNCHED — never of what the plan HOLDS. A stream plan.db names and no session ever
// ran has no entry, so it read as UNKNOWN and the wake refused. `bsc fleet list` calls that state
// `never-launched` and sent the director to `bsc fleet start <projectKey>`, a WHOLE-fleet launch that is
// refused outright while any pane is live — so a director with a running fleet had no lever at all.
//
// Rust reads plan.db (`fleet/start.rs` already does) and now carries the row, with the absolute cwd it
// resolved, on `bsc://fleet-wake` for a pane that is NOT LIVE. So the store's answer to "is this real"
// comes from the plan rather than from its own launch history, and the acceptance's line survives
// intact: Rust resolving NOTHING means plan.db does not name it, and that still refuses.
import type { AgentStream } from "@/features/planner/fleet/planFleet";

/** The plan row for a stream that has never launched, as Rust hands it over. */
const NEVER_LAUNCHED: AgentStream & { cwd: string } = {
  id: STREAM, name: "API", repo: "own/api", owns: ["src/api/"], issues: ["#7"], dependsOn: [],
  cwd: "/home/u/.base-studio-code/worktrees/demo/api--api",
};

describe("wakePane STARTS a stream the roster never saw", () => {
  beforeEach(() => { resetFleetPanes(); useAppStore.setState({ tabs: [] }); });

  /** A build tab exists (the director is running in it) and the roster is EMPTY — the never-launched case. */
  function armUnlaunched() {
    useAppStore.setState({
      tabs: [buildTab([`${KEY}:director`])],
      fleetPaneStreams: {}, disabledPanes: {}, dormantPanes: {}, endedPanes: {},
      personas: [], blueprints: [], projectBlueprintId: {},
    } as never);
  }

  it("seats the pane when Rust supplies the plan row", () => {
    armUnlaunched();
    expect(useAppStore.getState().wakePane(PANE, "start on #7", NEVER_LAUNCHED)).toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
  });

  it("adopts the row into the roster, so the NEXT wake needs no plan lookup", () => {
    // The roster is what `bsc fleet wake` reads on the second call, and what the coordinator resolves a
    // pane's stream through — a pane seated without it would be a session nothing could attribute.
    armUnlaunched();
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    expect(useAppStore.getState().fleetPaneStreams[PANE]?.id).toBe(STREAM);
    // `cwd` is a LAUNCH fact, not part of the plan row — it must not be stored as if it were.
    expect(useAppStore.getState().fleetPaneStreams[PANE]).not.toHaveProperty("cwd");
  });

  it("uses the absolute cwd RUST resolved, never a re-derived one", () => {
    // #905: re-deriving it here reads the async-loaded `bscBaseDir` mirror, and an empty one drops the
    // session at the user's home dir. `bscBaseDir` is deliberately left unset to prove nothing falls back.
    armUnlaunched();
    useAppStore.setState({ bscBaseDir: "" } as never);
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    expect(useAppStore.getState().paneCwds[PANE]).toBe(NEVER_LAUNCHED.cwd);
  });

  it("still REFUSES when Rust resolved nothing — an unknown stream stays an error", () => {
    // This is the whole reason the refusal moved rather than being deleted: plan.db not naming the
    // stream is what "unknown" now means, and it arrives as an absent `stream`.
    armUnlaunched();
    expect(useAppStore.getState().wakePane(fleetPaneId(KEY, "not-a-stream"), "go")).toBe(false);
    expect(useAppStore.getState().tabs[0].paneIds).not.toContain(fleetPaneId(KEY, "not-a-stream"));
  });

  it("mints a build tab too, for a stream that never launched AND has no tab at all (#165)", () => {
    // The exact dogfood shape request #165 was filed over: a stream plan.db has always named, whose
    // worktree already exists on disk, that has NEVER seated a pane — and whose project has no open
    // build tab either (closed, or the fleet's director never launched one). `bsc fleet start` refuses
    // outright while any OTHER stream in the fleet is live, and `--force` would relaunch every one of
    // them just to repair this one worktree's missing `.claude/settings.json`.
    useAppStore.setState({
      tabs: [], fleetPaneStreams: {}, disabledPanes: {}, dormantPanes: {}, endedPanes: {},
      personas: [], blueprints: [], projectBlueprintId: {},
    } as never);
    expect(useAppStore.getState().wakePane(PANE, "start on #7", NEVER_LAUNCHED)).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    expect(tab.paneIds).toEqual([PANE]);
    expect(useAppStore.getState().paneCwds[PANE]).toBe(NEVER_LAUNCHED.cwd);
  });

  it("wires the woken pane EXACTLY as a launch would have wired it", () => {
    // The anti-drift guard, and the reason `streamPaneWiring` exists. Two launch paths that agree today
    // and diverge later is the failure this codebase has paid for before (`fleetStartBridge`'s header
    // names it). So: launch the same row, record what it produced, then wake it and compare.
    const streamRow: AgentStream = (({ cwd: _cwd, ...row }) => row)(NEVER_LAUNCHED);
    resetFleetPanes();
    useAppStore.setState({ tabs: [], personas: [], blueprints: [], projectBlueprintId: {}, bscBaseDir: "/base" } as never);
    useAppStore.getState().fleetStartProject("Demo", { recommended: 1, reasoning: "t", streams: [streamRow], director: { enabled: false } }, KEY,
      { hubPath: "/hub", worktreePaths: { [STREAM]: NEVER_LAUNCHED.cwd } });
    const launched = useAppStore.getState();
    const asLaunched = {
      role: launched.paneRoles[PANE], profile: launched.paneProfiles[PANE], repo: launched.paneRepos[PANE],
      globs: launched.paneRoleGlobs[PANE], flow: launched.paneFlows[PANE], model: launched.paneModels[PANE],
      stream: launched.paneStream[PANE], cwd: launched.paneCwds[PANE],
    };

    resetFleetPanes();
    armUnlaunched();
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    const woken = useAppStore.getState();
    expect({
      role: woken.paneRoles[PANE], profile: woken.paneProfiles[PANE], repo: woken.paneRepos[PANE],
      globs: woken.paneRoleGlobs[PANE], flow: woken.paneFlows[PANE], model: woken.paneModels[PANE],
      stream: woken.paneStream[PANE], cwd: woken.paneCwds[PANE],
    }).toEqual(asLaunched);
    // Non-vacuity: the comparison is worthless if the launch wired nothing.
    expect(asLaunched.role).toBe("worker");
    expect(asLaunched.globs, "the owned path became a write boundary").toEqual(["src/api/**"]);
  });

  it("leaves the ALREADY-ROSTERED path alone — a plain wake still needs no stream", () => {
    arm([]);
    expect(useAppStore.getState().wakePane(PANE, "resume")).toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
  });

  // #173 (studio-code:director): `bsc plan fleet model <id> qwen3.5:9b` stored the model, but no
  // harness actually consumed it — every pane launched on the fleet-wide toggle (default "claude"),
  // so a director-assigned local model silently ran on Claude Code's own default, no ollama/bsc-agent
  // process anywhere in the pane's tree. A stream's own local model must now win the HARNESS too, on
  // both launch paths — a fresh `fleetStartProject` and a `wakePane` adoption.
  describe("a stream's own local model overrides the fleet's default harness (#173)", () => {
    const LOCAL: AgentStream & { cwd: string } = { ...NEVER_LAUNCHED, model: "qwen3.5:9b" };

    it("fleetStartProject launches a local-model stream on bsc-agent, and every other pane on the fleet default", () => {
      const streamRow: AgentStream = (({ cwd: _cwd, ...row }) => row)(LOCAL);
      resetFleetPanes();
      useAppStore.setState({
        tabs: [], personas: [], blueprints: [], projectBlueprintId: {}, bscBaseDir: "/base",
        llmProvider: "anthropic", fleetHarness: "claude",
      } as never);
      useAppStore.getState().fleetStartProject("Demo", { recommended: 1, reasoning: "t", streams: [streamRow], director: { enabled: true } }, KEY,
        { hubPath: "/hub", worktreePaths: { [STREAM]: LOCAL.cwd } });
      const st = useAppStore.getState();
      expect(st.paneModels[PANE]).toBe("qwen3.5:9b");
      expect(st.paneProviders[PANE]).toBe("bsc-agent");
      // The director carries no stream model, so it stays on the fleet-wide default — one local
      // worker must not drag the rest of the fleet onto bsc-agent with it.
      expect(st.paneProviders[`${KEY}:director`]).toBe("claude");
    });

    it("wakePane adopts a local-model stream onto bsc-agent the same way", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", LOCAL);
      const st = useAppStore.getState();
      expect(st.paneModels[PANE]).toBe("qwen3.5:9b");
      expect(st.paneProviders[PANE]).toBe("bsc-agent");
    });

    // THE GAP #173 LEFT, and what this file did not catch. Every assertion above checks
    // `paneProviders`, which was always derived correctly — while `paneInitCmds`, the string that
    // ACTUALLY LAUNCHES, was written as the literal "claude" one line above it in both paths. So the
    // provider was decorative: measured on merged main, a `blueprint` stream set to qwen3.5:9b still
    // came up as `pty[studio-code:blueprint] created · provider=claude`.
    it("writes the HARNESS as the init cmd, not the literal claude — the provider alone launches nothing", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", LOCAL);
      const st = useAppStore.getState();
      expect(st.paneInitCmds[PANE]).toBe("bsc-agent");
      // ...and it agrees with the provider. These two disagreeing IS the bug, so pin the pair.
      expect(st.paneInitCmds[PANE]).toBe(st.paneProviders[PANE]);
    });

    it("fleetStartProject writes the harness as the init cmd too", () => {
      const streamRow: AgentStream = (({ cwd: _cwd, ...row }) => row)(LOCAL);
      resetFleetPanes();
      useAppStore.setState({
        tabs: [], personas: [], blueprints: [], projectBlueprintId: {}, bscBaseDir: "/base",
        llmProvider: "anthropic", fleetHarness: "claude",
      } as never);
      useAppStore.getState().fleetStartProject("Demo", { recommended: 1, reasoning: "t", streams: [streamRow], director: { enabled: true } }, KEY,
        { hubPath: "/hub", worktreePaths: { [STREAM]: LOCAL.cwd } });
      const st = useAppStore.getState();
      expect(st.paneInitCmds[PANE]).toBe("bsc-agent");
      // The director has no stream wiring, so it keeps the fleet-wide harness — one local worker
      // must not drag the rest of the fleet with it, on the init cmd any more than on the provider.
      expect(st.paneInitCmds[`${KEY}:director`]).toBe("claude");
    });

    it("a Claude stream still gets the claude init cmd — the fix must not invert the default", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", { ...NEVER_LAUNCHED, model: "opus-4.5" });
      expect(useAppStore.getState().paneInitCmds[PANE]).toBe("claude");
    });

    it("a Claude-tier stream model stays on the fleet default — only a NON-tier model forces bsc-agent", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", { ...NEVER_LAUNCHED, model: "opus-4.5" });
      const st = useAppStore.getState();
      expect(st.paneModels[PANE]).toBe("opus-4.5");
      expect(st.paneProviders[PANE]).toBe("claude");
    });
  });
});

// ── the grid has to have a cell for it (#a-woken-pane-needs-a-cell-in-the-grid) ──────────────────
//
// Every test above uses a `2×2` fixture, so there was always a spare cell and the layout never had to
// grow. A REAL build tab whose fleet never launched holds one pane — the director — and is `1×1`. So
// seating a second id put it outside the grid: the pane was in the roster, fully wired, with the right
// cwd and role, and TerminalView never mounted it, so `pty_create` never ran. Observed on the live
// app: `woke studio-code:accessibility` returned success and `bsc fleet list` still said `stopped`.
//
// The success is the dangerous half — `wakePane` returned true because it had done everything it
// thought it had to.
describe("a woken pane gets a cell, not just a slot in the array", () => {
  beforeEach(() => { resetFleetPanes(); useAppStore.setState({ tabs: [] }); });

  /** The shape a director-only build tab actually has. */
  function armOnePaneTab() {
    useAppStore.setState({
      tabs: [{ ...buildTab([`${KEY}:director`]), layout: "1×1" }],
      fleetPaneStreams: {}, disabledPanes: {}, dormantPanes: {}, endedPanes: {},
      personas: [], blueprints: [], projectBlueprintId: {},
    } as never);
  }

  it("grows the layout so the pane it just seated can render", () => {
    armOnePaneTab();
    expect(useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED)).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    const ids = tab.paneIds ?? [];
    expect(ids).toEqual([`${KEY}:director`, PANE]);
    const [cols, rows] = tab.layout.split("×").map(Number);
    expect(cols * rows, `the grid must hold ${ids.length} panes, got ${tab.layout}`)
      .toBeGreaterThanOrEqual(ids.length);
  });

  it("grows the layout for a pane that is ALREADY seated but does not fit", () => {
    // The correction. Checking capacity only where the pane is SEATED was not enough: once seated, the
    // next wake finds an owning tab, takes the early path, and skipped the check — so a pane that never
    // fit stayed outside the grid forever, and every wake killed its PTY and remounted a grid without
    // it. Observed live: a `live` worker became `stopped` once per wake, while the wake said it worked.
    useAppStore.setState({
      tabs: [{ ...buildTab([`${KEY}:director`, PANE]), layout: "1×1" }],
      fleetPaneStreams: { [PANE]: { id: STREAM, name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [] } },
      disabledPanes: {}, dormantPanes: {}, endedPanes: {},
    } as never);
    expect(useAppStore.getState().wakePane(PANE, "go")).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    const [cols, rows] = tab.layout.split("×").map(Number);
    expect(cols * rows, `a seated pane still needs a cell; layout ${tab.layout}`)
      .toBeGreaterThanOrEqual((tab.paneIds ?? []).length);
  });

  it("leaves a layout that already fits exactly as it was", () => {
    // Reshaping a grid the user arranged, to seat a pane that already had a home, would be a second bug.
    arm(["", `${KEY}:director`]);
    const before = useAppStore.getState().tabs[0].layout;
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    expect(useAppStore.getState().tabs[0].layout).toBe(before);
  });
});

// #2446 — the persisted `githubState` slice: a fresh fetch overwrites records + fetchedAt, the field
// travels in the persist snapshot (so it survives restart), and each write mirrors the durable copy
// into the bsc-project store over the `bsc` bridge (`bsc project github-state set`, JSON on stdin).
import { describe, it, expect, beforeEach, vi } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import type { AppStore } from "@/store/types";
import type { MinimalGhProject } from "@/shared/lib/github/githubState";

const rec = (title: string): MinimalGhProject => ({
  id: `PVT_${title}`, number: 1, title, shortDescription: null, url: "", closed: false,
  updatedAt: "", itemsTotalCount: 0, openCount: 0, closedCount: 0, repos: [],
});

describe("githubState slice (#2446)", () => {
  beforeEach(() => {
    useAppStore.setState({ githubState: null });
    vi.mocked(invoke).mockReset();
    vi.mocked(invoke).mockResolvedValue("");
  });

  it("defaults to null (no fetch has ever landed)", () => {
    expect(useAppStore.getState().githubState).toBeNull();
  });

  it("setGithubState overwrites the records wholesale and stamps fetchedAt", () => {
    const before = Date.now();
    useAppStore.getState().setGithubState([rec("Acme CRM")]);
    const first = useAppStore.getState().githubState!;
    expect(first.records.map((r) => r.title)).toEqual(["Acme CRM"]);
    expect(first.fetchedAt).toBeGreaterThanOrEqual(before);

    // A later fetch REPLACES (never merges) — a board deleted on GitHub drops out.
    useAppStore.getState().setGithubState([rec("Other")]);
    expect(useAppStore.getState().githubState!.records.map((r) => r.title)).toEqual(["Other"]);
  });

  it("mirrors each write into the bsc-project store (bsc project github-state set, JSON on stdin)", () => {
    useAppStore.getState().setGithubState([rec("Acme CRM")]);
    expect(invoke).toHaveBeenCalledWith("bsc", {
      projectKey: null,
      args: ["project", "github-state", "set"],
      stdin: JSON.stringify(useAppStore.getState().githubState),
    });
  });

  it("persists: the partialize snapshot carries githubState, and applying it back rehydrates", () => {
    useAppStore.getState().setGithubState([rec("Acme CRM")]);
    const partialize = useAppStore.persist.getOptions().partialize!;
    const snap = partialize(useAppStore.getState()) as Partial<AppStore>;
    expect(snap.githubState).toEqual(useAppStore.getState().githubState);

    // Simulate the restart: a fresh store + the persisted snapshot applied → the state is back.
    useAppStore.setState({ githubState: null });
    useAppStore.setState(snap);
    expect(useAppStore.getState().githubState!.records[0].title).toBe("Acme CRM");
  });

  it("disconnectGithub does NOT clear it — surviving the logged-out state is its point", () => {
    useAppStore.getState().setGithubState([rec("Acme CRM")]);
    useAppStore.getState().disconnectGithub();
    expect(useAppStore.getState().githubState?.records).toHaveLength(1);
  });
});

// The EMITTERS, tested through the real loader (#runtime-attests-what-actually-ran).
//
// `attest.test.ts` proves the sink coalesces and that the hash matches Rust. Neither says anything about
// whether the loader CALLS it — and an emitter that is never reached is the exact failure this feature
// exists to end: every gate green, the store empty, and "no record ever declined" indistinguishable from
// "attestation was never wired up".
//
// So these drive `loadComponentFromSource` and assert on what came out of the sink. The compile step is
// INJECTED (esbuild-wasm is browser-only), and the fixtures are hand-written CommonJS — the same shape
// esbuild emits and the same approach `componentLoader.test.ts` already takes.
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { loadComponentFromSource } from "@/shared/lib/runtime/componentLoader";
import { registerAppModule, __resetRegistry } from "@/shared/lib/runtime/moduleRegistry";
import {
  enableAttestation, __resetAttestationsForTest, __pendingAttestationsForTest, srcHash,
} from "./attest";

/** The injected compile: the fixtures are already CJS, so this is identity. What matters is that
 *  `scanRequires` runs over it exactly as it does over esbuild's real output. */
const identity = async (src: string) => src;

beforeEach(() => {
  __resetRegistry();
  __resetAttestationsForTest();
  enableAttestation();
});
afterEach(() => {
  __resetAttestationsForTest();
  __resetRegistry();
});

/** Rows for one outcome, so each case reads as the fact it asserts. */
const rows = (outcome: string) => __pendingAttestationsForTest().filter((r) => r.outcome === outcome);

const COMPONENT = 'module.exports = { default: function C() { return null; } };\n';

describe("the loader attests what it decided", () => {
  it("attests every module in the closure that SERVED, with the hash of what linked", async () => {
    const sibling = 'module.exports = { helper: function () { return 1; } };\n';
    const entry = `const sib = require("@/components/sib");\n${COMPONENT}`;
    await loadComponentFromSource(entry, (spec) => (spec === "@/components/sib" ? sibling : null), undefined, identity);

    const linked = rows("linked");
    // The sibling is an ORDINARY closure member — the same shape an algorithm implementation takes, and
    // the reason LINKAGE is the honest claim for one rather than an execution count.
    const sib = linked.find((r) => r.specifier === "@/components/sib");
    expect(sib, `expected @/components/sib among [${linked.map((r) => r.specifier).join(", ")}]`).toBeTruthy();
    // The hash is of the SOURCE THAT LINKED, so a later edit cannot inherit this evidence.
    expect(sib!.src_hash).toBe(srcHash(sibling));
  });

  it("attests a DECLINED-CLOSURE override instead of only logging it", async () => {
    // A record whose closure needs a module that is neither registered nor a record: the runtime serves
    // the platform module instead and the record is INERT. That is the case which was invisible — one
    // warn line, and a graph that looked healthy.
    const broken = 'const nope = require("@/definitely/not/registered");\nmodule.exports = { X: nope };\n';
    const entry = `const b = require("@/broken");\n${COMPONENT}`;
    registerAppModule("@/broken", { X: 1 }); // the platform module it shadows, so the page still loads
    await loadComponentFromSource(entry, (spec) => (spec === "@/broken" ? broken : null), undefined, identity);

    const d = rows("declined-closure").find((r) => r.specifier === "@/broken");
    expect(d, `expected @/broken declined, got [${rows("declined-closure").map((r) => r.specifier).join(", ")}]`).toBeTruthy();
    // The REASON names the missing module. Without it the finding says "something was wrong" and the
    // reader is back to the log dive this replaced.
    expect(d!.reason).toContain("@/definitely/not/registered");
    // A declined record has no version to claim ran.
    expect(d!.src_hash).toBe("");
  });

  it("attests a DECLINED-EVAL override — it compiled and linked, then threw at module init", async () => {
    // The commonest real cause is a build-time-only form (`import.meta.glob` survives esbuild verbatim);
    // a bare throw reaches the identical decision point.
    const exploding = 'throw new Error("module init boom");\n';
    const entry = `const b = require("@/boom");\n${COMPONENT}`;
    registerAppModule("@/boom", { ok: true });
    await loadComponentFromSource(entry, (spec) => (spec === "@/boom" ? exploding : null), undefined, identity);

    const d = rows("declined-eval").find((r) => r.specifier === "@/boom");
    expect(d, `expected @/boom declined-eval, got [${rows("declined-eval").map((r) => r.specifier).join(", ")}]`).toBeTruthy();
    expect(d!.reason).toContain("boom");
  });

  it("never attributes the ENTRY's failure to the modules it pulled in", async () => {
    // An entry that exports no component still LINKED its closure. Attesting those as failed would blame
    // every dependency for the entry's problem — and those rows are what `doctor` reads to decide whether
    // an implementation is live.
    const sibling = 'module.exports = { helper: function () { return 1; } };\n';
    const entry = 'const sib = require("@/components/sib");\nmodule.exports = { notAComponent: 1 };\n';
    await expect(
      loadComponentFromSource(entry, (spec) => (spec === "@/components/sib" ? sibling : null), undefined, identity),
    ).rejects.toThrow();
    expect(rows("linked").some((r) => r.specifier === "@/components/sib")).toBe(true);
    expect(rows("declined-compile")).toHaveLength(0);
    expect(rows("declined-closure")).toHaveLength(0);
    expect(rows("declined-eval")).toHaveLength(0);
  });

  it("emits NOTHING when the sink is off — the loader must never REQUIRE attestation", async () => {
    // Every existing loader test runs with it off, and none of them should have to learn about it.
    __resetAttestationsForTest(); // leaves it disabled
    await loadComponentFromSource(COMPONENT, () => null, undefined, identity);
    expect(__pendingAttestationsForTest()).toHaveLength(0);
  });
});

// #components-graph-culls-offscreen-nodes — the workbench mounts only the nodes inside the visible rect.
//
// WHY THE RECT IS INJECTED. jsdom has no layout, so `clientWidth` is 0, so `visibleWorldRect` correctly
// returns null and culling is OFF in every other test in this suite — which is the safe default, and also
// means a render test cannot observe culling by accident. The geometry itself is proven exhaustively in
// `viewportCull.test.ts`; what THIS file proves is the wiring: that the page actually consults the rect,
// tests each node at the coordinates it renders at, and renders everything when there is no rect.
import { describe, it, expect, beforeEach, vi } from "vitest";
import { render } from "@testing-library/react";
import { useAppStore } from "@/store";
import type { GraphBox } from "@/shared/ui/layouts/useGraphViewport";

// esbuild-wasm can't run under jsdom — mock the bundler (mirrors DesignsWorkbench.test.tsx #2824).
vi.mock("@/shared/lib/preview/componentBundle", () => ({
  bundleComponent: vi.fn().mockResolvedValue("/*bundle*/"),
  buildComponentSrcDoc: (js: string) => `<!doctype html><html><body>${js}</body></html>`,
  COMPONENT_IMPORTMAP: { react: "https://esm.sh/react" },
  COMPONENT_EXTERNALS: ["react"],
}));
vi.mock("@/features/designs/lib/uiActivity", () => ({ useUiActivity: vi.fn() }));
vi.mock("@/features/designs/lib/useComponentScan", () => ({ useComponentScan: vi.fn() }));

// The rect the page sees, swappable per test — this is the seam that stands in for real layout.
const { rectRef } = vi.hoisted(() => ({ rectRef: { current: null as GraphBox | null } }));
vi.mock("@/shared/ui/layouts/useVisibleRect", () => ({ useVisibleRect: () => rectRef.current }));

import { DesignsWorkbench } from "@/features/designs/DesignsWorkbench";
import { REACT_UI_KIT, REACT_UI_COMPONENTS } from "@/features/designs/lib/reactUiKit";
import { SEED_THEMES } from "@/features/designs/lib/themes";

const nodeCount = (c: HTMLElement) => c.querySelectorAll(".ds-node").length;

beforeEach(() => {
  rectRef.current = null;
  useAppStore.setState({
    components: REACT_UI_COMPONENTS,
    kits: [REACT_UI_KIT],
    kitThemes: SEED_THEMES,
    aiFocusedId: null,
    designsKitId: "",
    designsCompId: null,
    // The Studio must be the VISIBLE page or the graph never renders (#3627) — same gate every other
    // workbench test sets.
    activeWorkspace: "components",
    projectsPageMode: "designs",
  });
});

describe("the components graph culls what you cannot see", () => {
  it("renders EVERY node when there is no rect — the unmeasured default is render-everything", () => {
    // The load-bearing default: a viewport that has not been measured must not blank the graph. Every
    // failure mode of the cull is supposed to land here.
    const { container } = render(<DesignsWorkbench />);
    expect(nodeCount(container)).toBe(REACT_UI_COMPONENTS.filter((c) => c.kitId === REACT_UI_KIT.id).length);
  });

  it("drops the nodes outside the rect and keeps the ones inside it", () => {
    const { container } = render(<DesignsWorkbench />);
    const all = nodeCount(container);
    expect(all).toBeGreaterThan(20); // the packaged kit is big enough for this test to mean something

    // A rect around the graph's ORIGIN — the first lane's nodes fall inside, everything below does not.
    rectRef.current = { x: -50, y: -50, w: 400, h: 300 };
    const { container: culled } = render(<DesignsWorkbench />);
    const shown = nodeCount(culled);
    expect(shown).toBeGreaterThan(0);     // …but not so hard that the screen is empty
    expect(shown).toBeLessThan(all);
  });

  it("culls to NOTHING for a rect far off in empty world space", () => {
    // Proves the filter is really running over each node's own coordinates rather than passing
    // everything through — the failure mode a too-clever memo would produce.
    rectRef.current = { x: 900_000, y: 900_000, w: 10, h: 10 };
    const { container } = render(<DesignsWorkbench />);
    expect(nodeCount(container)).toBe(0);
  });

  it("keeps a culled node's identity intact — the ones that survive are unchanged", () => {
    // This slice must be invisible except in the profiler: a surviving node keeps its classes and its
    // data-node hook, so selection, the related ring and the health badges all behave as before.
    rectRef.current = { x: -50, y: -50, w: 400, h: 300 };
    const { container } = render(<DesignsWorkbench />);
    const first = container.querySelector(".ds-node");
    expect(first).toBeTruthy();
    expect(first!.getAttribute("data-node")).not.toBeNull();
  });
});

// #graph-health-stops-blocking-first-paint — the badges still arrive.
//
// Deferring graph health off the render path has one failure mode that no other test in this suite would
// notice: the findings never land, and the graph simply renders forever without badges. Nothing guarded
// the badge path before this file, so the deferral could have silently turned a feature off and every
// existing test would still have passed.
//
// So this asserts the SEQUENCE the change introduces — painted first, decorated after — rather than just
// the end state, because "the badge is there" alone would also pass if the work were still blocking paint.
import { describe, it, expect, beforeEach, vi } from "vitest";
import { render, waitFor } from "@testing-library/react";
import { useAppStore } from "@/store";

vi.mock("@/shared/lib/preview/componentBundle", () => ({
  bundleComponent: vi.fn().mockResolvedValue("/*bundle*/"),
  buildComponentSrcDoc: (js: string) => `<!doctype html><html><body>${js}</body></html>`,
  COMPONENT_IMPORTMAP: { react: "https://esm.sh/react" },
  COMPONENT_EXTERNALS: ["react"],
}));
vi.mock("@/features/designs/lib/uiActivity", () => ({ useUiActivity: vi.fn() }));
vi.mock("@/features/designs/lib/useComponentScan", () => ({ useComponentScan: vi.fn() }));
// SPY, not a stub: the cache test has to prove the REAL analysis is skipped, so the implementation
// stays and only the call count is observable. A stub would make "it wasn't called" trivially true.
vi.mock("@/features/designs/lib/graphHealth", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/features/designs/lib/graphHealth")>();
  return { ...actual, analyzeGraphHealth: vi.fn(actual.analyzeGraphHealth) };
});

import { DesignsWorkbench } from "@/features/designs/DesignsWorkbench";
import { analyzeGraphHealth } from "@/features/designs/lib/graphHealth";
import { REACT_UI_KIT, REACT_UI_COMPONENTS } from "@/features/designs/lib/reactUiKit";
import { SEED_THEMES } from "@/features/designs/lib/themes";

/** An ORPHAN: a component nothing composes and which composes nothing — a finding the analyzer reports,
 *  so the graph must eventually badge it. */
const orphan = {
  ...REACT_UI_COMPONENTS[0],
  id: "lonely-orphan", name: "LonelyOrphan", composes: [], used: 0,
};

beforeEach(() => {
  useAppStore.setState({
    components: [...REACT_UI_COMPONENTS, orphan],
    kits: [REACT_UI_KIT],
    kitThemes: SEED_THEMES,
    aiFocusedId: null,
    designsKitId: "",
    designsCompId: null,
    activeWorkspace: "components",
    projectsPageMode: "designs",
  });
});

describe("graph health arrives after paint, not before it", () => {
  it("paints the graph FIRST with no badges, then badges once idle work runs", async () => {
    const { container } = render(<DesignsWorkbench />);

    // The graph is already on screen…
    expect(container.querySelectorAll(".ds-node").length).toBeGreaterThan(0);
    // …and undecorated, because the analysis has not run yet. This is the half that proves the work is
    // genuinely OFF the render path: if it still blocked paint, badges would already be here.
    expect(container.querySelector(".ds-health")).toBeFalsy();

    // jsdom has no requestIdleCallback, so `runWhenIdle` falls back to a timeout — the fallback that
    // makes the deferral safe where the API is missing. If it were a no-op, this would never resolve.
    await waitFor(() => expect(container.querySelector(".ds-health")).toBeTruthy(), { timeout: 3000 });
  });

  it("shows the toolbar finding count once the analysis lands", async () => {
    const { container } = render(<DesignsWorkbench />);
    await waitFor(() => {
      const chip = [...container.querySelectorAll("*")].find((el) => /^⚠ \d+$/.test(el.textContent ?? ""));
      expect(chip).toBeTruthy();
    }, { timeout: 3000 });
  });
});

describe("the analysis is not repeated for a library it has already analysed", () => {
  // WHY THIS EXISTS. `analyzeGraphHealth` runs `componentBuildable` over every component in the kit, so
  // it costs ~250ms on a real library and grows with it — measured as the heaviest named phase in the
  // app (`bsc perf phases`: designs:health, 9 runs, 248ms mean, 2.2s total). Nothing was recomputing
  // because the data changed: navigating away and back gave `kitComps`/`libResolver` fresh identities
  // for identical contents, and the whole library was re-analysed to reach the answer just discarded.
  it("re-uses the findings on a remount, and does not run the analyser again", async () => {
    const spy = vi.mocked(analyzeGraphHealth);
    spy.mockClear();

    const first = render(<DesignsWorkbench />);
    await waitFor(() => expect(first.container.querySelector(".ds-health")).toBeTruthy(), { timeout: 3000 });
    const runsAfterFirstVisit = spy.mock.calls.length;
    expect(runsAfterFirstVisit).toBeGreaterThan(0);
    first.unmount();

    // Navigate back. The store's `components` array is untouched, so this is the same library.
    const second = render(<DesignsWorkbench />);
    // Decorated on the FIRST commit — no clear, no idle round trip. This is the user-visible half: the
    // badges are simply there, instead of arriving a beat later after a quarter-second of blocked work.
    expect(second.container.querySelector(".ds-health")).toBeTruthy();
    expect(spy.mock.calls.length).toBe(runsAfterFirstVisit);
  });

  // The cache must not outlive its inputs — stale badges point at components that are no longer there,
  // and the existing behaviour (clear first, then recompute) is what keeps a wrong badge off screen.
  it("re-analyses when the library actually changes", async () => {
    const spy = vi.mocked(analyzeGraphHealth);
    spy.mockClear();

    const first = render(<DesignsWorkbench />);
    await waitFor(() => expect(first.container.querySelector(".ds-health")).toBeTruthy(), { timeout: 3000 });
    const before = spy.mock.calls.length;
    first.unmount();

    // A real edit: a NEW array with different contents, exactly as a store write produces.
    useAppStore.setState({
      components: [...useAppStore.getState().components, { ...orphan, id: "second-orphan", name: "SecondOrphan" }],
    });

    const second = render(<DesignsWorkbench />);
    await waitFor(() => expect(second.container.querySelector(".ds-health")).toBeTruthy(), { timeout: 3000 });
    expect(spy.mock.calls.length).toBeGreaterThan(before);
  });
});

// #3627 regression — the Design Studio's background loops (activity poll + preview scan) must pause when
// the Studio is HIDDEN. KeptMountedPage keeps DesignsWorkbench mounted (display:none) after the first
// visit and a hidden child's effects keep firing, so an unconditional `useUiActivity(true)` (the pre-#3627
// bug) kept polling the ui log against the Rust host forever. Both loops are gated on the one
// `designStudioVisible` flag; this asserts they receive it.
import { describe, it, expect, beforeEach, vi } from "vitest";
import { render } from "@testing-library/react";
import { useAppStore } from "@/store";

// esbuild-wasm can't run under jsdom — mock the bundler (mirrors DesignsWorkbench.test.tsx #2824).
vi.mock("@/shared/lib/preview/componentBundle", () => ({
  bundleComponent: vi.fn().mockResolvedValue("/*bundle*/"),
  buildComponentSrcDoc: (js: string) => `<!doctype html><html><body>${js}</body></html>`,
  COMPONENT_IMPORTMAP: { react: "https://esm.sh/react" },
  COMPONENT_EXTERNALS: ["react"],
}));

// Spy the two background loops so we can read the visibility flag each was handed. `vi.hoisted` so the
// spies exist before `vi.mock` is hoisted above the imports.
const { uiSpy, scanSpy } = vi.hoisted(() => ({ uiSpy: vi.fn(), scanSpy: vi.fn() }));
vi.mock("@/features/designs/lib/uiActivity", () => ({ useUiActivity: uiSpy }));
vi.mock("@/features/designs/lib/useComponentScan", () => ({ useComponentScan: scanSpy }));

import { DesignsWorkbench } from "@/features/designs/DesignsWorkbench";
import { REACT_UI_KIT, REACT_UI_COMPONENTS } from "@/features/designs/lib/reactUiKit";
import { SEED_THEMES } from "@/features/designs/lib/themes";

beforeEach(() => {
  uiSpy.mockClear();
  scanSpy.mockClear();
  useAppStore.setState({
    components: REACT_UI_COMPONENTS,
    kits: [REACT_UI_KIT],
    kitThemes: SEED_THEMES,
    aiFocusedId: null,
    designsKitId: "",
    designsCompId: null,
  });
});

describe("DesignsWorkbench visibility gating (#3627)", () => {
  it("polls activity + scans previews when the Studio is the visible page", () => {
    useAppStore.setState({ activeWorkspace: "components" });
    render(<DesignsWorkbench />);
    expect(uiSpy).toHaveBeenCalledWith(true);
    expect(scanSpy).toHaveBeenCalledWith(true, expect.anything(), undefined, expect.anything());
  });

  it("does NOT poll or scan while hidden — the KeptMountedPage leak the bug caused", () => {
    useAppStore.setState({ activeWorkspace: "console", projectsPageMode: "designs" });
    render(<DesignsWorkbench />);
    expect(uiSpy).toHaveBeenCalledWith(false);
    expect(scanSpy).toHaveBeenCalledWith(false, expect.anything(), undefined, expect.anything());
  });

  it("hidden on the projects workspace when it's showing a non-designs page (e.g. Teams)", () => {
    useAppStore.setState({ activeWorkspace: "teams" });
    render(<DesignsWorkbench />);
    expect(uiSpy).toHaveBeenCalledWith(false);
    expect(scanSpy).toHaveBeenCalledWith(false, expect.anything(), undefined, expect.anything());
  });
});

// EVERY PACKAGED APP RECORD MUST SURVIVE ITS OWN LOAD PROJECTION — `seed === load(push(seed))` (#2514).
//
// `SEED_COMPONENTS` stamps each packaged JSON with `stampSeedHash(projectComponent(raw))`. If the raw JSON
// carries a field the projection normalizes — an empty array where the projection wants it absent, a key it
// drops — then the stamped hash describes content the store will never reproduce. The record then reads as
// PRISTINE-BUT-CHANGED on every single boot: `reconcileSeed` reports `refreshed`, `hydrateComponents`
// re-pushes it, and the same write repeats forever.
//
// Nothing else notices. The app works, the record renders, and the churn is invisible unless a test happens
// to assert an empty reconcile — which is exactly how this was found: promoting two records made three
// unrelated `store.test.ts` cases fail, and the failure named `console-pane-menu` rather than the field that
// broke it. This test names the field.
import { describe, it, expect } from "vitest";
import type { ComponentRecord } from "@/features/designs/lib/model";
import { projectComponent } from "@/features/designs/lib/componentBridge";
import { seedHashOf } from "@/features/designs/lib/seedRefresh";

const raw = import.meta.glob<Partial<ComponentRecord>>("@data/components/app/**/*.json", {
  eager: true,
  import: "default",
});

describe("packaged app records round-trip through the load projection (#2514)", () => {
  const paths = Object.keys(raw).sort();

  it("has records to check", () => {
    expect(paths.length).toBeGreaterThan(20);
  });

  it("no id appears twice — the glob is FLAT, so folders do not namespace", () => {
    // `SEED_COMPONENTS` globs `app/**` and keys by `id`, so two files under different folders sharing an
    // id are two records with one identity. `reconcileSeed` then reports that id as pristine-but-changed
    // on every boot and re-pushes it, forever. The app keeps working, which is why it took three unrelated
    // `store.test.ts` failures to surface — and those named the record, not the duplication.
    const seen = new Map<string, string[]>();
    for (const p of paths) {
      const id = raw[p]?.id;
      if (!id) continue;
      seen.set(id, [...(seen.get(id) ?? []), p]);
    }
    const dupes = [...seen].filter(([, ps]) => ps.length > 1).map(([id, ps]) => `${id}: ${ps.join(" · ")}`);
    expect(dupes).toEqual([]);
  });

  it("projecting a packaged record TWICE is the same as projecting it once", () => {
    // The round-trip in the form this test can see without a store: the projection must be idempotent,
    // or the hash stamped over `project(raw)` cannot survive `project(load(...))`.
    const unstable: string[] = [];
    for (const p of paths) {
      const once = projectComponent(raw[p]);
      const twice = projectComponent({ ...once });
      if (seedHashOf(once) !== seedHashOf(twice)) {
        const a = once as unknown as Record<string, unknown>;
        const b = twice as unknown as Record<string, unknown>;
        const fields = [...new Set([...Object.keys(a), ...Object.keys(b)])].filter(
          (k) => JSON.stringify(a[k]) !== JSON.stringify(b[k]),
        );
        unstable.push(`${p.split("/").pop()} — differs on: ${fields.join(", ") || "(field set)"}`);
      }
    }
    expect(unstable).toEqual([]);
  });

  it("a packaged record carries only fields the projection preserves", () => {
    // A field the projection DROPS is the other half of the same bug: it is in the JSON, absent from the
    // stamped record, and every reader after that disagrees with the file about what the record is.
    const dropped: string[] = [];
    for (const p of paths) {
      const projected = projectComponent(raw[p]) as unknown as Record<string, unknown>;
      const missing = Object.keys(raw[p] as Record<string, unknown>).filter((k) => !(k in projected));
      if (missing.length) dropped.push(`${p.split("/").pop()} — ${missing.join(", ")}`);
    }
    expect(dropped).toEqual([]);
  });
});

// The role gate's behaviour, captured from the LIVE TypeScript so Rust can be proved to match it.
//
// ## Why a fixture rather than a hand-written table
//
// `launch-rules.ts` derives the security policy a session launches under — which commands are denied,
// which tools, which paths. Rust ENFORCES it (`deny_matches`, bsc-util/src/deny.rs) and WRITES it
// (`ensure_session_settings` takes the computed lists) but never COMPUTES it, so the policy is decided
// in the renderer. `epic-frontend-logic-over-backend-resources-belongs-in-rust` moves that derivation.
//
// A port of security policy that is subtly different is worse than no port. So this generates the
// answer from the implementation that is live TODAY, and a Rust test asserts its own derivation
// matches case for case. Hand-writing the expectations would only prove Rust agrees with whoever
// typed the table.
//
// Same pattern as `tunnelProtocol.fixtures.json` / `plannerCore.fixtures.json`: one byte-exact
// artifact read by BOTH sides. Regenerate deliberately:
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/roleGate.fixtures.gen.test.ts
//
// A regeneration that changes the file is a CHANGE OF POLICY. Read the diff before committing it.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { ROLE_DEFAULTS, roleCapability, type SessionRole } from "@/shared/lib/session/roleModel";
import {
  roleDeniedCommands,
  roleDeniedTools,
  roleWriteRules,
  sessionScopes,
} from "@/shared/lib/session/launchRules";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/roleGate.fixtures.json");

/** A surface catalog to complement against. Two shapes, because the EMPTY one fails open by design
 *  (see `roleDeniedCommands`) and that asymmetry is exactly the kind of thing a port drops. */
const SURFACES: Record<string, string[]> = {
  none: [],
  catalog: ["ui", "plan", "graph", "persona", "teams", "request", "fleet", "logs"],
};

/** Write globs are filled PER ASSIGNMENT, so a worker with an owned glob is a distinct case from one
 *  without: the carve-out logic branches on it. */
const GLOBS: Record<string, string[]> = {
  none: [],
  owned: ["src/**/*.ts", "contracts/**/*.json"],
};

function build() {
  const roles = Object.keys(ROLE_DEFAULTS).sort() as SessionRole[];
  const cases = [];
  for (const role of roles) {
    for (const [surfaceKey, surfaces] of Object.entries(SURFACES)) {
      for (const [globKey, writeGlobs] of Object.entries(GLOBS)) {
        const cap = roleCapability(role, writeGlobs.length ? { writeGlobs } : {});
        cases.push({
          role,
          surfaces: surfaceKey,
          globs: globKey,
          // EVERY field the derivation reads, so Rust can reproduce it from the fixture alone.
          // `allow` and `surfaces` were missing on the first pass and they are not decoration:
          // `isRestrictedRole`, `capabilitySurfaces` and `mayFileToolingRequest` all branch on them,
          // so a fixture without them cannot express the cases that matter most.
          capability: {
            role: cap.role,
            github: cap.github, git: cap.git, code: cap.code, net: cap.net, ui: cap.ui,
            // `graph` joins the projection the moment `roleDeniedCommands` starts reading it. This is
            // the exact trap the comment above records: a derivation that reads a field the fixture
            // does not carry cannot be reproduced from the fixture, and Rust's parity test fails
            // pointing at the DERIVATION when the fault is in what was captured
            // (`the-algorithms-graph-has-no-write-gate`).
            graph: cap.graph,
            writeGlobs: cap.writeGlobs ?? [],
            allow: [...(cap.allow ?? [])],
            surfaces: cap.surfaces ? [...cap.surfaces] : null,
          },
          deniedCommands: roleDeniedCommands(cap, surfaces),
          deniedTools: roleDeniedTools(cap),
          writeRules: roleWriteRules(cap),
          scopes: sessionScopes(cap),
        });
      }
    }
  }
  return { note: "GENERATED from the live TypeScript — see roleGate.fixtures.gen.test.ts", roles, surfaces: SURFACES, cases };
}

describe("the role gate's behaviour is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const built = build();
    const text = JSON.stringify(built, null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") {
      writeFileSync(FIXTURE, text);
    }
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("covers every role the table defines, so a new role cannot slip past the port", () => {
    const built = build();
    expect(built.roles.length).toBeGreaterThanOrEqual(9);
    expect(new Set(built.cases.map((c) => c.role)).size).toBe(built.roles.length);
  });
});

// The write-scope env, captured from the LIVE TypeScript so the Rust derivation can be proved equal.
//
// Two variables, both pure security:
//
//   BSC_SCOPE_GLOBS — the globs the `bsc-scope` PreToolUse hook hard-blocks outside of. This is the
//                     HARD deny the role gate's allow-only rules lack, and it survives the bypass
//                     posture where `permissions.deny` is ignored entirely.
//   BSC_SCOPES      — the role's per-store access tiers, checked by the store CLIs before a mutating
//                     verb (#2470).
//
// The `bsc-hook--main.rs` record reads the first and BLOCKS on it; `crates/bsc-cli-util` reads the
// second and refuses a store write on it. Rust enforces both on every tool call and computes neither.
//
// The values are read out of `buildAgentEnv` itself rather than recomposed from its parts, so the
// fixture records the decision the LAUNCH actually makes — including its three-way branch, which is
// what the Rust port has to reproduce:
//
//   globs non-empty            → the globs, space-joined
//   empty AND code:none        → the deny-all sentinel (#1916 Step 3.5)
//   empty AND code is not none → UNSET, so an ungated pane stays allow-all
//
// Getting that branch order wrong inverts a hard deny into a permit: `scope_verdict` reads an ABSENT
// scope as "no scope configured" and allows.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/writeScopeEnv.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { buildAgentEnv, SCOPE_DENY_ALL } from "@/app/console/lib/sessionLaunch";
import { roleCapability, type SessionRole } from "@/shared/lib/session/sessionRoles";
import type { AppStore } from "@/store/types";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/writeScopeEnv.fixtures.json");
const PANE = "p1";

const BASE = {
  deniedCommands: [], paneRoles: {}, paneRoleGlobs: {}, paneProfiles: {}, agentProfiles: [],
  paneFlows: {}, surfaceCatalog: [], fleetPaneStreams: {}, appRepoRoot: "/repo", bscBaseDir: "/base",
  mcpServers: [], skills: [], sessionSkillOverrides: {}, sessionSkillGroups: {}, skillGroups: [], paneSkills: {},
};

/** Every role the gate knows, plus the glob-carrying variants. `claude` as the provider keeps the
 *  bsc-agent branch of `buildAgentEnv` out of this — the two scope vars are set before it. */
const ROLES: SessionRole[] = [
  "planner", "worker", "director", "triage", "tester", "reviewer",
  "issuer", "juror", "documentor", "designer", "architect", "librarian", "sound-designer", "marketer",
] as SessionRole[];

const SUBJECTS: Array<[string, { role?: string; globs?: string[] }]> = [
  ["no role at all — an ungated pane is never scoped", {}],
  ...ROLES.map((r) => [`role ${r}, no own globs`, { role: r }] as [string, { role?: string; globs?: string[] }]),
  ["worker with own write globs", { role: "worker", globs: ["src/**", "docs/**"] }],
  ["worker with ONE glob", { role: "worker", globs: ["src/**"] }],
  ["designer with own globs — a carve-out role keeps its scoped write", { role: "designer", globs: ["scratch/**"] }],
  ["triage with own globs — code:none WITHOUT a carve-out grants nothing", { role: "triage", globs: ["src/**"] }],
  ["director with own globs — the commons carve-out", { role: "director", globs: ["docs/**"] }],
  ["a glob containing a space-free path stays space-joined", { role: "worker", globs: ["a/**", "b/**", "c/**"] }],
];

const envFor = (role: string | undefined, globs: string[] | undefined) =>
  buildAgentEnv(
    { ...BASE, paneRoles: role ? { [PANE]: role } : {}, paneRoleGlobs: globs ? { [PANE]: globs } : {} } as unknown as AppStore,
    PANE,
    "claude",
    "",
  );

describe("writeScopeEnv fixtures", () => {
  it("captures BSC_SCOPE_GLOBS and BSC_SCOPES over every role", () => {
    const cases = SUBJECTS.map(([label, { role, globs }]) => {
      const env = envFor(role, globs) ?? {};
      return {
        label,
        role: role ?? null,
        writeGlobs: globs ?? [],
        // The resolved capability, so Rust can deserialize it rather than needing a role→capability
        // function. The self-check below proves it is the one the live launch used.
        capability: role ? roleCapability(role as SessionRole, globs?.length ? { writeGlobs: globs } : {}) ?? null : null,
        scopeGlobs: env.BSC_SCOPE_GLOBS ?? null,
        scopes: env.BSC_SCOPES ?? null,
      };
    });
    const next = {
      note: "GENERATED from @/app/console/lib/sessionLaunch buildAgentEnv — do not hand-edit; see the .gen.test.ts",
      denyAllSentinel: SCOPE_DENY_ALL,
      cases,
    };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("is non-vacuous: all three branches actually occur in the corpus", () => {
    const scoped = SUBJECTS.filter(([, s]) => {
      const g = envFor(s.role, s.globs)?.BSC_SCOPE_GLOBS;
      return g && g !== SCOPE_DENY_ALL;
    });
    const sentinel = SUBJECTS.filter(([, s]) => envFor(s.role, s.globs)?.BSC_SCOPE_GLOBS === SCOPE_DENY_ALL);
    const unset = SUBJECTS.filter(([, s]) => !envFor(s.role, s.globs)?.BSC_SCOPE_GLOBS);

    expect(scoped.length, "no role produced real globs — the fixture would not exercise the first branch").toBeGreaterThan(0);
    expect(sentinel.length, "no role produced the deny-all sentinel — #1916 Step 3.5 would be untested").toBeGreaterThan(0);
    expect(unset.length, "no case left the scope UNSET — the ungated branch would be untested").toBeGreaterThan(0);
  });

  it("an ungated pane is never scoped — the branch that must stay allow-all", () => {
    const env = envFor(undefined, undefined);
    expect(env?.BSC_SCOPE_GLOBS, "a pane with no role must not be scoped at all").toBeUndefined();
    expect(env?.BSC_SCOPES, "and gets no store scopes either").toBeUndefined();
  });
});

// What `matchGlob` actually means, captured from the LIVE TypeScript so the Rust matcher can be
// measured against it.
//
// TWO ENGINES DECIDE ONE WRITE SCOPE. `write-scope.ts`'s `matchGlob` compiles a glob to a RegExp;
// `bsc_util::scope`'s `fnmatch` is a hand-written POSIX-style matcher. The `bsc-scope` hook ENFORCES
// writes with the Rust one, while the role model, the launch write-rules and the warden's
// conformance check all reason with this one. Nothing binds them.
//
// This file is the measurement, not a claim: it records what the TypeScript does for pairs chosen to
// separate the two readings, and the Rust side asserts against it. A disagreement is a finding.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/globSemantics.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { matchGlob } from "@/shared/lib/session/writeScope";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/globSemantics.fixtures.json");

/** Each pair is chosen to separate the two readings, not to be representative traffic. */
const PAIRS: Array<[string, string, string]> = [
  // [why it is here, glob, path]
  ["plain literal", "src/a.ts", "src/a.ts"],
  ["literal miss", "src/a.ts", "src/b.ts"],
  ["* within one segment", "src/*.ts", "src/a.ts"],
  ["* ACROSS a separator — the security case", "src/*.ts", "src/a/b.ts"],
  ["* across two separators", "src/*.ts", "src/a/b/c.ts"],
  ["** across a separator", "src/**/*.ts", "src/a/b.ts"],
  ["** at the tail", "src/**", "src/a/b/c.ts"],
  ["** matching nothing", "src/**", "src/"],
  ["* does not escape the prefix", "src/*.ts", "lib/a.ts"],
  ["anchoring — no prefix match", "src/a.ts", "x/src/a.ts"],
  ["anchoring — no suffix match", "src/a.ts", "src/a.tsx"],
  ["? as a wildcard or a literal", "src/a?.ts", "src/ab.ts"],
  ["? against a literal question mark", "src/a?.ts", "src/a?.ts"],
  // If `?` is LITERAL these are false; if it is a REGEX QUANTIFIER leaking through the compiler
  // (`a?` = optional 'a') the first is true. That distinction is the difference between a missing
  // feature and an unescaped metacharacter in a security predicate.
  ["? as a leaked regex quantifier — 'a' absent", "src/a?.ts", "src/.ts"],
  ["? as a leaked regex quantifier — 'a' present", "src/a?.ts", "src/a.ts"],
  ["unescaped alternation leaks too?", "src/a|b.ts", "src/a"],
  ["bracket class or literal brackets", "src/[ab].ts", "src/a.ts"],
  ["bracket against literal brackets", "src/[ab].ts", "src/[ab].ts"],
  ["dot is not a wildcard", "src/a.ts", "src/axts"],
  ["plus is literal", "src/a+.ts", "src/a+.ts"],
  ["parens are literal", "src/(a).ts", "src/(a).ts"],
  ["dollar is literal", "src/a$.ts", "src/a$.ts"],
  ["contracts glob from a real capability", "contracts/**/*.json", "contracts/x/y.json"],
  ["real capability glob, one level", "src/**/*.tsx", "src/app/Thing.tsx"],
  ["real capability glob, zero levels", "src/**/*.tsx", "src/Thing.tsx"],
];

function build() {
  return {
    note: "GENERATED from the live TypeScript matchGlob — see globSemantics.fixtures.gen.test.ts",
    pairs: PAIRS.map(([why, glob, path]) => ({ why, glob, path, matches: matchGlob(glob, path) })),
  };
}

describe("what matchGlob means is captured for the Rust matcher to be measured against", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const text = JSON.stringify(build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("contains both matches and non-matches, or it separates nothing", () => {
    const m = build().pairs;
    expect(m.some((p) => p.matches)).toBe(true);
    expect(m.some((p) => !p.matches)).toBe(true);
  });
});

// `bsc-agent`'s native permission doc, captured from the LIVE TypeScript so the Rust rendering can be
// proved equal.
//
// This doc IS the gate on the model-agnostic harness. There is no `.claude/settings.json` on that path:
// `crates/bsc-agent/src/main.rs` calls `Permissions::from_env()` and enforces the result on every tool
// call, deserializing exactly `deny_tools` / `deny_bash` / `write_globs`. So a Rust runtime enforces,
// per tool call, a permission document computed in a renderer.
//
// Two details a port is most likely to drop, both covered below:
//   * The USER'S GLOBAL DENYLIST rides in here rather than through a settings file, because bsc-agent
//     has none. It is trimmed and de-duplicated against the role denies.
//   * The catastrophic floor (sudo / rm -rf / force-push) is NOT in this doc — it is always-on inside
//     the runtime via `bsc_util::dangerous`, so an empty doc still cannot run those.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/bscAgentPerms.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { roleCapability, bscAgentPerms, type SessionRole } from "@/shared/lib/session/sessionRoles";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/bscAgentPerms.fixtures.json");

const ROLES: SessionRole[] = [
  "planner", "worker", "director", "triage", "tester", "reviewer",
  "issuer", "juror", "documentor", "designer", "architect", "librarian", "sound-designer", "marketer",
] as SessionRole[];

const PUSH_GRANT = ["git push", "gh pr create"];

type Case = { label: string; role: string | null; globs?: string[]; granted?: string[]; extraDeny?: string[]; surfaces?: string[] };

/** A stand-in `bsc surface list` catalog. Small and FIXED rather than the real one: the complement is
 *  what a role did NOT declare, so a live catalog would silently rewrite every expectation here each
 *  time a surface is added. `plan`/`skill` are surfaces no studio role declares; `ui` is one the
 *  designer does, so the pair proves the complement rather than a blanket deny. */
const CATALOG = ["plan", "skill", "ui"];

const SUBJECTS: Case[] = [
  // A role-less ad-hoc console: only the user's denylist applies.
  { label: "NO capability — an ad-hoc bsc-agent console", role: null },
  { label: "NO capability, but the user has a denylist", role: null, extraDeny: ["curl", "wget"] },

  ...ROLES.map((r) => ({ label: `role ${r}`, role: r })),

  // The flow reconciliation (#304), mirroring the Claude path.
  { label: "worker + the flow's push grant", role: "worker", granted: PUSH_GRANT },
  { label: "director + the flow's push grant", role: "director", granted: PUSH_GRANT },
  { label: "designer + a push grant it cannot use", role: "designer", granted: PUSH_GRANT },

  // The user's global denylist — the half that has no settings file to ride in on.
  { label: "worker + user denylist", role: "worker", extraDeny: ["curl", "npm publish"] },
  { label: "user denylist entries are TRIMMED", role: "worker", extraDeny: ["  curl  ", "npm publish"] },
  { label: "empty and whitespace-only denylist entries are dropped", role: "worker", extraDeny: ["", "   ", "curl"] },
  { label: "a user deny DUPLICATING a role deny is de-duplicated", role: "worker", extraDeny: ["gh pr merge"] },
  { label: "user denylist plus a push grant together", role: "worker", granted: PUSH_GRANT, extraDeny: ["curl"] },

  // write_globs: code:write takes its own, a carve-out keeps its scoped set, everything else gets none.
  { label: "worker with own write globs", role: "worker", globs: ["src/**", "docs/**"] },
  { label: "designer — code:none WITH a carve-out keeps its globs", role: "designer" },
  { label: "documentor — the doc-globs carve-out", role: "documentor" },
  { label: "triage — code:none with NO carve-out gets no globs and loses the write tools", role: "triage" },
  { label: "triage handed globs it has no carve-out for", role: "triage", globs: ["src/**"] },

  // The persona SURFACE COMPLEMENT (`a-bsc-agent-session-is-denied-less-than-the-same-role-on-claude`).
  // It used to be absent here entirely, so a bsc-agent session was denied strictly less than the same
  // role on Claude. An EMPTY catalog still denies nothing extra, which is the fail-open the launch
