// The resume command, captured from the LIVE TypeScript so the Rust resolution can be proved equal.
//
// `plan_launch` (src-tauri/src/console/pty/launch.rs) consumes the `init_cmd` this produces and cannot
// compute it. Every failure mode the function guards against was a session that came up wrong and said
// nothing:
//
//   · a resuming pane whose `explicit` is the bare harness placeholder used to return it verbatim, so a
//     resumed worker opened a NEW conversation beside the old one — and a `bsc-agent` pane resumed into
//     CLAUDE, silently ignoring its local model (#173);
//   · an EMPTY startup prompt returned "" and the pane came up a bare shell, because an empty string is
//     discarded downstream too;
//   · `continueSession` used to require `paneWasClaude`, which deadlocked — that flag is only set once
//     claude has started, so 77 of 78 fleet panes could never be resumed at all.
//
// A clean quit must resume NOTHING. That is asserted rather than assumed, because this function is one
// edit away from starting sessions by itself.
//
//     UPDATE_FIXTURES=1 npx vitest run src/app/console/lib/resumeCommand.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { resolveInitCmd } from "@/app/console/lib/resumeClaude";
import { CONTINUE_OR_FRESH, continueOrFresh } from "@/shared/lib/session/ensureClaudeRunning";

const FIXTURE = join(process.cwd(), "src/app/console/lib/resumeCommand.fixtures.json");

type Args = Parameters<typeof resolveInitCmd>[0];
const args = (over: Partial<Args> = {}): Args => ({
  explicit: undefined, startupPrompt: undefined, continueSession: false,
  paneWasClaude: false, autoResumeClaude: false, wasUncleanShutdown: false, restoreRequested: false,
  ...over,
});

type Case = { label: string; args: Args };

const SUBJECTS: Case[] = [
  { label: "nothing set — a clean quit resumes NOTHING", args: args() },

  // The three resume signals, each alone.
  { label: "signal 1: an explicit fleet/triage resume", args: args({ continueSession: true }) },
  { label: "signal 2: the crash banner's Restore click", args: args({ paneWasClaude: true, restoreRequested: true }) },
  { label: "signal 3: silent auto-resume after an unclean shutdown", args: args({ paneWasClaude: true, autoResumeClaude: true, wasUncleanShutdown: true }) },

  // #3986: continueSession ALONE, without paneWasClaude — the conjunction that deadlocked.
  { label: "continueSession WITHOUT paneWasClaude — the 77-of-78 case", args: args({ continueSession: true, paneWasClaude: false }) },
  { label: "restoreRequested WITHOUT paneWasClaude — still gated on it", args: args({ restoreRequested: true, paneWasClaude: false }) },
  { label: "auto-resume WITHOUT paneWasClaude", args: args({ autoResumeClaude: true, wasUncleanShutdown: true, paneWasClaude: false }) },
  { label: "auto-resume armed but the shutdown was CLEAN", args: args({ paneWasClaude: true, autoResumeClaude: true, wasUncleanShutdown: false }) },
  { label: "unclean shutdown but auto-resume NOT armed", args: args({ paneWasClaude: true, autoResumeClaude: false, wasUncleanShutdown: true }) },

  // The harness placeholder — the bug that sent a resumed worker to an empty conversation.
  { label: "placeholder `claude`, NOT resuming — returned verbatim", args: args({ explicit: "claude" }) },
  { label: "placeholder `claude`, RESUMING — becomes the resume form", args: args({ explicit: "claude", continueSession: true }) },
  { label: "placeholder `bsc-agent`, RESUMING — #173, must NOT become claude", args: args({ explicit: "bsc-agent", continueSession: true }) },
  { label: "placeholder `bsc-agent`, not resuming", args: args({ explicit: "bsc-agent" }) },
  { label: "placeholder with surrounding whitespace, resuming", args: args({ explicit: "  claude  ", continueSession: true }) },

  // A REAL override must win untouched, even on a resume.
  { label: "a real override with flags, resuming — wins untouched", args: args({ explicit: "aider --message go", continueSession: true }) },
  { label: "a real override, not resuming", args: args({ explicit: "./my-wrapper.sh" }) },
  { label: "an override that merely CONTAINS the harness name", args: args({ explicit: "claude --model opus", continueSession: true }) },

  // startupPrompt: TRUTHY, not defined-ness.
  { label: "a startup prompt wins over a resume", args: args({ startupPrompt: "do the thing", continueSession: true }) },
  { label: "an EMPTY startup prompt falls THROUGH to the resume", args: args({ startupPrompt: "", continueSession: true }) },
  { label: "an empty startup prompt with no resume signal", args: args({ startupPrompt: "" }) },
  { label: "a startup prompt AND an explicit override — explicit is checked first", args: args({ explicit: "aider --message go", startupPrompt: "kickoff" }) },
];

describe("resumeCommand fixtures", () => {
  it("captures resolveInitCmd over every signal combination", () => {
    const cases = SUBJECTS.map((c) => ({ label: c.label, args: c.args, cmd: resolveInitCmd(c.args) }));
    const next = {
      note: "GENERATED from @/app/console/lib/resumeClaude — do not hand-edit; see the .gen.test.ts",
      continueOrFresh: CONTINUE_OR_FRESH,
      continueOrFreshBscAgent: continueOrFresh("bsc-agent"),
      cases,
    };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("A CLEAN QUIT RESUMES NOTHING — the app must not start sessions by itself", () => {
    expect(resolveInitCmd(args()), "no signal, no command").toBe("");
    expect(resolveInitCmd(args({ paneWasClaude: true })), "having BEEN claude is not a resume signal").toBe("");
  });

  it("#173: a resuming bsc-agent pane resumes BSC-AGENT, never claude", () => {
    const cmd = resolveInitCmd(args({ explicit: "bsc-agent", continueSession: true }));
    expect(cmd, "the resume form is derived from the placeholder").toContain("bsc-agent");
    expect(cmd.startsWith("claude"), "resuming into claude silently ignores the configured local model").toBe(false);
  });

  it("an empty startup prompt does NOT short-circuit — it fell through to a bare shell", () => {
    expect(resolveInitCmd(args({ startupPrompt: "", continueSession: true })), "empty is not a prompt").not.toBe("");
    expect(resolveInitCmd(args({ startupPrompt: "real", continueSession: true })), "a real prompt wins").toBe("");
  });
});

// The fresh-only kickoff decision, captured from the LIVE TypeScript so the Rust derivation can be
// proved equal.
//
// `plan_launch` (src-tauri/src/console/pty/launch.rs) computes `suppress = fresh_only && has_history`
// and decides whether a session is re-greeted or resumes quietly. It cannot compute `fresh_only` —
// that arrives as a `pty_create` argument from the renderer, defaulting to false when absent. Rust owns
// the consequence; the frontend owns the decision.
//
// This is the rule the local-model kickoff loop turned on: the predicate used to be gated on
// `isClaudeProvider`, so a local pane never suppressed its kickoff and was re-instructed on every
// launch.
//
// BOTH FAILURE DIRECTIONS ARE DOCUMENTED BUGS, and they are not symmetric. Over-suppressing strands a
// session with no instructions at an empty prompt (the per-request debug sessions, which resume
// nothing); under-suppressing merely re-greets. So a port must fail toward re-greeting.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/freshOnly.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { resolveStartupPromptFreshOnly } from "@/app/console/lib/sessionLaunch";
import { SINGLE_STUDIO_PANE_IDS, designerSessionId, librarianSessionId, DEBUG_STUDIO_SESSION_ID, DEBUG_STUDIO_PANE_PREFIX } from "@/shared/lib/session/systemSessions";
import type { AppStore } from "@/store/types";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/freshOnly.fixtures.json");

const store = (restore: Record<string, boolean>) => ({ restoreRequested: restore }) as unknown as AppStore;

type Case = { label: string; paneId: string; restore?: boolean };

const SUBJECTS: Case[] = [
  // Every fixed app-owned studio session — these genuinely resume across restarts.
  // The per-technology studios are recognised by GRAMMAR now
  // (`the-studio-session-set-is-derived-not-declared`), so there is no list of them to spread.
  // The corpus names two of them explicitly instead — the point of the case is the SHAPE of a
  // studio pane id, and two per-technology examples cover it as well as an enumeration did.
  ...[...SINGLE_STUDIO_PANE_IDS, designerSessionId("react"), librarianSessionId("rust")]
    .map((id) => ({ label: `studio session ${id}`, paneId: id })),

  // THE DOCUMENTED BUG: the per-request debug sessions share the `debug-studio:` PREFIX with the
  // standing debugger but resume nothing, so suppressing their charter strands them.
  { label: "the STANDING debug session IS fresh-only", paneId: DEBUG_STUDIO_SESSION_ID },
  { label: "a PER-REQUEST debug session is NOT — it resumes nothing", paneId: `${DEBUG_STUDIO_PANE_PREFIX}req-4212` },
  { label: "another per-request debug session", paneId: `${DEBUG_STUDIO_PANE_PREFIX}req-99` },

  // Ordinary panes.
  { label: "a fleet worker pane", paneId: "studio-code:kernel" },
  { label: "a fleet worker pane being crash-RESTORED", paneId: "studio-code:kernel", restore: true },
  { label: "a director pane", paneId: "studio-code:director" },
  { label: "a triage pane", paneId: "studio-code:base-studio-code:triage" },
  { label: "a triage pane being restored", paneId: "studio-code:base-studio-code:triage", restore: true },

  // A manual console is NEVER fresh-only (#1176) — not even when restore is requested. The id shape is
  // `man:<tabId>:p<idx>` (`manualPaneId`), NOT the `t<n>p<n>` positional id: those are two different
  // schemes and only the `man:` prefix is what `isManualPaneId` reads.
  { label: "a manual console", paneId: "man:tab1:p0" },
  { label: "a manual console WITH restore requested — still never fresh-only", paneId: "man:tab1:p0", restore: true },
  { label: "another manual console", paneId: "man:tab2:p3" },
  // The POSITIONAL id, kept as a contrast case: it is not manual, so the restore flag does apply. The
  // two schemes look interchangeable and are not.
  { label: "a POSITIONAL pane id is not a manual one", paneId: "t0p0" },
  { label: "a positional pane id being restored — the restore DOES apply", paneId: "t0p0", restore: true },

  { label: "an unknown pane id", paneId: "something-else" },
  { label: "an unknown pane id being restored", paneId: "something-else", restore: true },
  { label: "the empty pane id", paneId: "" },
];

/** The provider argument is deliberately NOT this rule's business — the record says so in place. Both
 *  values are captured so a port cannot quietly reintroduce the `isClaudeProvider` gate that made every
 *  protection here Claude-only. */
const PROVIDERS = [true, false];

describe("freshOnly fixtures", () => {
  it("captures the decision over every studio id and edge case", () => {
    const cases = SUBJECTS.map((c) => {
      const s = store(c.restore ? { [c.paneId]: true } : {});
      const byProvider = PROVIDERS.map((isClaude) => resolveStartupPromptFreshOnly(s, c.paneId, isClaude));
      return {
        label: c.label,
        paneId: c.paneId,
        restoreRequested: !!c.restore,
        freshOnly: byProvider[0],
        // Pinned so the harness gate cannot come back: both providers must agree.
        freshOnlyNonClaude: byProvider[1],
      };
    });
    const next = {
      note: "GENERATED from @/app/console/lib/sessionLaunch resolveStartupPromptFreshOnly — do not hand-edit; see the .gen.test.ts",
      studioPaneIds: [...SINGLE_STUDIO_PANE_IDS],
      cases,
    };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("THE HARNESS GATE IS GONE: the decision never differs by provider", () => {
    // Gating on `isClaudeProvider` is what made a local pane re-instructed on every launch. If a port
    // reintroduces it, this is the test that names why it matters.
    for (const c of SUBJECTS) {
      const s = store(c.restore ? { [c.paneId]: true } : {});
      expect(
        resolveStartupPromptFreshOnly(s, c.paneId, true),
        `${c.label}: the rule is about RESUMING, and bsc-agent resumes too`,
      ).toBe(resolveStartupPromptFreshOnly(s, c.paneId, false));
    }
  });

  it("is non-vacuous: the decision is true for some panes and false for others", () => {
    const vals = SUBJECTS.map((c) => resolveStartupPromptFreshOnly(store(c.restore ? { [c.paneId]: true } : {}), c.paneId, true));
    expect(vals.filter(Boolean).length, "nothing was fresh-only").toBeGreaterThan(2);
    expect(vals.filter((v) => !v).length, "everything was fresh-only").toBeGreaterThan(2);
  });

  it("the per-request debug session is NOT fresh-only while the standing one IS", () => {
    // The distinction the prefix predicate got wrong, asserted directly because it is the whole point.
    expect(resolveStartupPromptFreshOnly(store({}), DEBUG_STUDIO_SESSION_ID, true)).toBe(true);
    expect(
      resolveStartupPromptFreshOnly(store({}), `${DEBUG_STUDIO_PANE_PREFIX}req-1`, true),
      "a per-request session resumes nothing — suppressing its charter strands it at an empty prompt",
    ).toBe(false);
  });
});

// The session's ACCESS env, captured from the LIVE TypeScript so the Rust derivation can be proved
// equal. Three grants, each consumed by Rust and decided nowhere near it:
//
//   GH_TOKEN            whether this session gets a GitHub credential at all
